window.HSK_DATA = window.HSK_DATA || {};
window.HSK_DATA["7-9-p5"] = [{"id":"碰钉子","hanzi":"碰钉子","pinyin":"pèngdīngzi","meaning_vi":"bị từ chối, bị khước từ, gặp trở ngại","explanation":"碰 (bính – va) + 钉子 (đinh tử – cái đinh) → va phải đinh; nghĩa bóng là bị từ chối thẳng, vấp phải trở ngại.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"📌","examples":[{"type":"basic","zh":"他又碰钉子了。","pinyin":"Tā yòu pèngdīngzi le.","vi":"Anh ấy lại bị từ chối rồi."},{"type":"simple","zh":"他去银行贷款，结果又碰钉子了。","pinyin":"Tā qù yínháng dàikuǎn, jiéguǒ yòu pèngdīngzi le.","vi":"Anh ấy đến ngân hàng vay tiền, kết quả lại bị từ chối thẳng thừng."},{"type":"compound","zh":"虽然找工作时经常碰钉子，但是他没有放弃。","pinyin":"Suīrán zhǎogōngzuò shí jīngcháng pèngdīngzi, dànshì tā méiyǒu fàngqì.","vi":"Tuy khi tìm việc đã bị từ chối không ít lần, nhưng anh ấy không bỏ cuộc."}],"related":[{"hanzi":"碰壁","pinyin":"pèngbì","vi":"vấp phải tường"},{"hanzi":"拒绝","pinyin":"jùjué","vi":"từ chối"},{"hanzi":"吃闭门羹","pinyin":"chībìméngēng","vi":"ăn canh bế môn"},{"hanzi":"钉子","pinyin":"dīngzi","vi":"cái đinh"}],"traditional":"碰釘子"},{"id":"碰巧","hanzi":"碰巧","pinyin":"pèngqiǎo","meaning_vi":"tình cờ, vừa may, ngẫu nhiên","explanation":"碰 (bính – gặp) + 巧 (xảo – khéo, đúng lúc) → gặp đúng lúc, tình cờ.","hsk_level":"7-9","tags":["pho-tu"],"image":"🎲","examples":[{"type":"basic","zh":"我碰巧也在那儿。","pinyin":"Wǒ pèngqiǎo yě zài nàr.","vi":"Tôi tình cờ cũng ở đó."},{"type":"simple","zh":"昨天在地铁上碰巧遇到了老同学。","pinyin":"Zuótiān zài dìtiě shang pèngqiǎo yùdàole lǎo tóngxué.","vi":"Hôm qua trên tàu điện ngầm tình cờ gặp lại bạn học cũ."},{"type":"compound","zh":"因为碰巧带了伞，所以下大雨时我没被淋湿。","pinyin":"Yīnwèi pèngqiǎo dàile sǎn, suǒyǐ xià dàyǔ shí wǒ méi bèi línshī.","vi":"Vì tình cờ có mang ô nên khi mưa to tôi không bị ướt."}],"related":[{"hanzi":"恰巧","pinyin":"qiàqiǎo","vi":"vừa khéo"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"ngẫu nhiên"},{"hanzi":"正好","pinyin":"zhènghǎo","vi":"vừa đúng"},{"hanzi":"凑巧","pinyin":"còuqiǎo","vi":"tình cờ"}]},{"id":"碰上","hanzi":"碰上","pinyin":"pèngshàng","meaning_vi":"gặp phải, gặp, đụng phải","explanation":"碰 (bính – va, gặp) + 上 (thượng – bổ ngữ kết quả) → gặp phải, đụng phải (người hoặc chuyện).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙌","examples":[{"type":"basic","zh":"路上碰上了堵车。","pinyin":"Lùshang pèngshàngle dǔchē.","vi":"Trên đường gặp phải tắc xe."},{"type":"simple","zh":"我在超市门口碰上了以前的老师。","pinyin":"Wǒ zài chāoshì ménkǒu pèngshàngle yǐqián de lǎoshī.","vi":"Tôi gặp thầy giáo cũ ở cổng siêu thị."},{"type":"compound","zh":"如果碰上什么麻烦，就给我打电话。","pinyin":"Rúguǒ pèngshàng shénme máfan, jiù gěi wǒ dǎdiànhuà.","vi":"Nếu gặp phải rắc rối gì thì gọi điện cho mình."}],"related":[{"hanzi":"遇到","pinyin":"yùdào","vi":"gặp"},{"hanzi":"碰见","pinyin":"pèngjiàn","vi":"gặp phải"},{"hanzi":"赶上","pinyin":"gǎnshàng","vi":"gặp đúng lúc"},{"hanzi":"撞上","pinyin":"zhuàngshàng","vi":"đâm phải"}]},{"id":"碰撞","hanzi":"碰撞","pinyin":"pèngzhuàng","meaning_vi":"va chạm, đụng nhau","explanation":"碰 (bính – va) + 撞 (chàng – đâm) → va đập vào nhau; nghĩa bóng là sự cọ xát giữa các tư tưởng, nền văn hóa.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"💥","examples":[{"type":"basic","zh":"两辆车碰撞了。","pinyin":"Liǎng liàng chē pèngzhuàng le.","vi":"Hai chiếc xe va chạm nhau."},{"type":"simple","zh":"这次会议是一场思想的碰撞。","pinyin":"Zhè cì huìyì shì yì chǎng sīxiǎng de pèngzhuàng.","vi":"Cuộc họp lần này là một cuộc va chạm tư tưởng."},{"type":"compound","zh":"虽然两车发生了碰撞，但是幸好没有人受伤。","pinyin":"Suīrán liǎng chē fāshēngle pèngzhuàng, dànshì xìnghǎo méiyǒu rén shòushāng.","vi":"Tuy hai xe đã va chạm nhưng may là không ai bị thương."}],"related":[{"hanzi":"撞击","pinyin":"zhuàngjī","vi":"va đập"},{"hanzi":"冲突","pinyin":"chōngtū","vi":"xung đột"},{"hanzi":"相撞","pinyin":"xiāngzhuàng","vi":"đâm nhau"},{"hanzi":"车祸","pinyin":"chēhuò","vi":"tai nạn xe"}]},{"id":"皮带","hanzi":"皮带","pinyin":"pídài","meaning_vi":"thắt lưng da, dây lưng; dây curoa","explanation":"皮 (bì – da) + 带 (đái – dây) → dây làm bằng da, thắt lưng; cũng chỉ dây curoa máy.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"🪢","examples":[{"type":"basic","zh":"这条皮带太长了。","pinyin":"Zhè tiáo pídài tài cháng le.","vi":"Chiếc thắt lưng này dài quá."},{"type":"simple","zh":"他吃得太饱，只好把皮带松了一格。","pinyin":"Tā chī de tài bǎo, zhǐhǎo bǎ pídài sōngle yì gé.","vi":"Anh ấy ăn no quá, đành phải nới thắt lưng ra một nấc."},{"type":"compound","zh":"因为机器的皮带断了，所以生产线停了。","pinyin":"Yīnwèi jīqì de pídài duàn le, suǒyǐ shēngchǎnxiàn tíng le.","vi":"Vì dây curoa máy bị đứt nên dây chuyền sản xuất phải dừng."}],"related":[{"hanzi":"腰带","pinyin":"yāodài","vi":"thắt lưng"},{"hanzi":"皮鞋","pinyin":"píxié","vi":"giày da"},{"hanzi":"皮包","pinyin":"píbāo","vi":"túi da"},{"hanzi":"裤子","pinyin":"kùzi","vi":"quần"}],"traditional":"皮帶"},{"id":"脾","hanzi":"脾","pinyin":"pí","meaning_vi":"lá lách, tỳ","explanation":"脾 (tỳ) → tỳ tạng, lá lách; trong Đông y là cơ quan chủ về tiêu hóa; ghép thành 脾气 (tính khí).","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🫀","examples":[{"type":"basic","zh":"他的脾受伤了。","pinyin":"Tā de pí shòushāng le.","vi":"Lá lách của anh ấy bị thương."},{"type":"simple","zh":"中医认为，吃太多冷饮会伤脾胃。","pinyin":"Zhōngyī rènwéi, chī tài duō lěngyǐn huì shāng píwèi.","vi":"Đông y cho rằng uống quá nhiều đồ lạnh sẽ hại tỳ vị."},{"type":"compound","zh":"如果脾胃不好，就要少吃生冷的东西。","pinyin":"Rúguǒ píwèi bù hǎo, jiùyào shǎo chī shēnglěng de dōngxi.","vi":"Nếu tỳ vị không tốt thì nên ăn ít đồ sống lạnh."}],"related":[{"hanzi":"脾气","pinyin":"píqi","vi":"tính khí"},{"hanzi":"脾胃","pinyin":"píwèi","vi":"tỳ vị"},{"hanzi":"肝","pinyin":"gān","vi":"gan"},{"hanzi":"内脏","pinyin":"nèizàng","vi":"nội tạng"}]},{"id":"匹配","hanzi":"匹配","pinyin":"pǐpèi","meaning_vi":"khớp, phù hợp, tương xứng; ghép đôi","explanation":"匹 (thất – sánh ngang) + 配 (phối – ghép) → ghép đôi cho tương xứng; khớp, phù hợp với nhau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧩","examples":[{"type":"basic","zh":"密码不匹配。","pinyin":"Mìmǎ bù pǐpèi.","vi":"Mật khẩu không khớp."},{"type":"simple","zh":"系统会自动为你匹配合适的对手。","pinyin":"Xìtǒng huì zìdòng wèi nǐ pǐpèi héshì de duìshǒu.","vi":"Hệ thống sẽ tự động ghép đối thủ phù hợp cho bạn."},{"type":"compound","zh":"如果血型不匹配，就不能进行输血。","pinyin":"Rúguǒ xuèxíng bù pǐpèi, jiù bù néng jìnxíng shūxuè.","vi":"Nếu nhóm máu không phù hợp thì không thể truyền máu."}],"related":[{"hanzi":"相配","pinyin":"xiāngpèi","vi":"xứng đôi"},{"hanzi":"吻合","pinyin":"wěnhé","vi":"khớp"},{"hanzi":"搭配","pinyin":"dāpèi","vi":"phối hợp"},{"hanzi":"对应","pinyin":"duìyìng","vi":"tương ứng"}]},{"id":"僻静","hanzi":"僻静","pinyin":"pìjìng","meaning_vi":"hẻo lánh, vắng vẻ, yên tĩnh","explanation":"僻 (tích – hẻo lánh) + 静 (tĩnh – yên lặng) → vắng vẻ, yên tĩnh, ít người qua lại.","hsk_level":"7-9","tags":["tinh-tu","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"这条小路很僻静。","pinyin":"Zhè tiáo xiǎolù hěn pìjìng.","vi":"Con đường nhỏ này rất vắng vẻ."},{"type":"simple","zh":"他在郊外找了一处僻静的地方写小说。","pinyin":"Tā zài jiāowài zhǎole yí chù pìjìng de dìfang xiě xiǎoshuō.","vi":"Anh ấy tìm một nơi yên tĩnh ở ngoại ô để viết tiểu thuyết."},{"type":"compound","zh":"虽然这里很僻静，但是晚上一个人走不太安全。","pinyin":"Suīrán zhèlǐ hěn pìjìng, dànshì wǎnshang yígèrén zǒu bú tài ānquán.","vi":"Tuy chỗ này rất yên tĩnh nhưng buổi tối đi một mình không an toàn lắm."}],"related":[{"hanzi":"偏僻","pinyin":"piānpì","vi":"hẻo lánh"},{"hanzi":"幽静","pinyin":"yōujìng","vi":"tĩnh mịch"},{"hanzi":"安静","pinyin":"ānjìng","vi":"yên tĩnh"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"}],"traditional":"僻靜"},{"id":"譬如说","hanzi":"譬如说","pinyin":"pìrúshuō","meaning_vi":"ví dụ như, chẳng hạn như","explanation":"譬如 (thí như – ví như) + 说 (thuyết – nói) → nói ví dụ, dùng để đưa ra ví dụ minh họa.","hsk_level":"7-9","tags":["lien-tu","giao-tiep"],"image":"💡","examples":[{"type":"basic","zh":"譬如说，你可以早起。","pinyin":"Pìrúshuō, nǐ kěyǐ zǎoqǐ.","vi":"Ví dụ như, bạn có thể dậy sớm."},{"type":"simple","zh":"多吃水果有好处，譬如说苹果和香蕉。","pinyin":"Duō chī shuǐguǒ yǒu hǎochu, pìrúshuō píngguǒ hé xiāngjiāo.","vi":"Ăn nhiều trái cây có lợi, chẳng hạn như táo và chuối."},{"type":"compound","zh":"如果你想练口语，就多跟人聊天，譬如说找中国朋友。","pinyin":"Rúguǒ nǐ xiǎng liàn kǒuyǔ, jiù duō gēn rén liáotiān, pìrúshuō zhǎo Zhōngguó péngyou.","vi":"Nếu bạn muốn luyện nói thì hãy trò chuyện nhiều, chẳng hạn như tìm bạn người Trung Quốc."}],"related":[{"hanzi":"比如","pinyin":"bǐrú","vi":"ví dụ"},{"hanzi":"例如","pinyin":"lìrú","vi":"ví dụ như"},{"hanzi":"譬如","pinyin":"pìrú","vi":"thí như"},{"hanzi":"举例","pinyin":"jǔlì","vi":"lấy ví dụ"}],"traditional":"譬如說"},{"id":"偏方","hanzi":"偏方","pinyin":"piānfāng","meaning_vi":"bài thuốc dân gian, phương thuốc mẹo","explanation":"偏 (thiên – lệch, không chính thống) + 方 (phương – bài thuốc) → bài thuốc dân gian không có trong y thư chính thống.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🌿","examples":[{"type":"basic","zh":"这是治感冒的偏方。","pinyin":"Zhè shì zhì gǎnmào de piānfāng.","vi":"Đây là bài thuốc dân gian chữa cảm."},{"type":"simple","zh":"奶奶总喜欢用生姜红糖水这种偏方。","pinyin":"Nǎinai zǒng xǐhuan yòng shēngjiāng hóng tángshuǐ zhè zhǒng piānfāng.","vi":"Bà nội luôn thích dùng mẹo dân gian như nước gừng đường đỏ."},{"type":"compound","zh":"虽然有些偏方很管用，但是生了重病还是要看医生。","pinyin":"Suīrán yǒuxiē piānfāng hěn guǎnyòng, dànshì shēngle zhòngbìng háishi yào kànyīshēng.","vi":"Tuy có những bài thuốc dân gian khá hiệu nghiệm, nhưng ốm nặng thì vẫn phải đi khám bác sĩ."}],"related":[{"hanzi":"药方","pinyin":"yàofāng","vi":"đơn thuốc"},{"hanzi":"秘方","pinyin":"mìfāng","vi":"bí phương"},{"hanzi":"中药","pinyin":"zhōngyào","vi":"thuốc bắc"},{"hanzi":"民间","pinyin":"mínjiān","vi":"dân gian"}]},{"id":"偏远","hanzi":"偏远","pinyin":"piānyuǎn","meaning_vi":"xa xôi, hẻo lánh","explanation":"偏 (thiên – lệch, hẻo) + 远 (viễn – xa) → xa xôi, hẻo lánh, xa trung tâm.","hsk_level":"7-9","tags":["tinh-tu","dia-diem"],"image":"🏔️","examples":[{"type":"basic","zh":"他来自偏远山区。","pinyin":"Tā láizì piānyuǎn shānqū.","vi":"Anh ấy đến từ vùng núi xa xôi."},{"type":"simple","zh":"她大学毕业后去偏远农村当了老师。","pinyin":"Tā dàxué bìyè hòu qù piānyuǎn nóngcūn dāngle lǎoshī.","vi":"Tốt nghiệp đại học, cô ấy về vùng quê hẻo lánh làm giáo viên."},{"type":"compound","zh":"因为村子太偏远，所以快递要一周才能送到。","pinyin":"Yīnwèi cūnzi tài piānyuǎn, suǒyǐ kuàidì yào yìzhōu cáinéng sòng dào.","vi":"Vì làng quá xa xôi nên hàng chuyển phát phải mất một tuần mới tới."}],"related":[{"hanzi":"偏僻","pinyin":"piānpì","vi":"hẻo lánh"},{"hanzi":"遥远","pinyin":"yáoyuǎn","vi":"xa xôi"},{"hanzi":"边远","pinyin":"biānyuǎn","vi":"biên viễn"},{"hanzi":"山区","pinyin":"shānqū","vi":"vùng núi"}],"traditional":"偏遠"},{"id":"篇幅","hanzi":"篇幅","pinyin":"piānfú","meaning_vi":"độ dài (bài viết), dung lượng trang","explanation":"篇 (thiên – bài văn) + 幅 (phúc – khổ, bề rộng) → độ dài của bài viết, khoảng trang giấy chiếm chỗ.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"📄","examples":[{"type":"basic","zh":"这篇文章篇幅太长。","pinyin":"Zhè piān wénzhāng piānfú tài cháng.","vi":"Bài viết này quá dài."},{"type":"simple","zh":"报纸用了很大篇幅报道这次地震。","pinyin":"Bàozhǐ yòngle hěn dà piānfú bàodào zhè cì dìzhèn.","vi":"Báo dành rất nhiều trang để đưa tin về trận động đất này."},{"type":"compound","zh":"由于篇幅有限，所以有些细节就不展开了。","pinyin":"Yóuyú piānfú yǒuxiàn, suǒyǐ yǒuxiē xìjié jiù bù zhǎnkāi le.","vi":"Do giới hạn dung lượng nên một số chi tiết sẽ không triển khai thêm."}],"related":[{"hanzi":"字数","pinyin":"zìshù","vi":"số chữ"},{"hanzi":"版面","pinyin":"bǎnmiàn","vi":"trang báo"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"bài viết"},{"hanzi":"长度","pinyin":"chángdù","vi":"độ dài"}]},{"id":"片子","hanzi":"片子","pinyin":"piānzi","meaning_vi":"phim, bộ phim; phim chụp (X-quang)","explanation":"片 (phiến – tấm mỏng) + 子 (tử – hậu tố) → cuộn phim; trong khẩu ngữ chỉ bộ phim hoặc phim chụp X-quang.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎞️","examples":[{"type":"basic","zh":"这部片子很好看。","pinyin":"Zhè bù piānzi hěn hǎokàn.","vi":"Bộ phim này rất hay."},{"type":"simple","zh":"医生拿着片子仔细看了半天。","pinyin":"Yīshēng názhe piānzi zǐxì kànle bàn tiān.","vi":"Bác sĩ cầm tấm phim chụp xem kỹ hồi lâu."},{"type":"compound","zh":"虽然这部片子成本很低，但是票房非常好。","pinyin":"Suīrán zhè bù piānzi chéngběn hěn dī, dànshì piàofáng fēicháng hǎo.","vi":"Tuy bộ phim này kinh phí rất thấp nhưng doanh thu phòng vé rất tốt."}],"related":[{"hanzi":"影片","pinyin":"yǐngpiàn","vi":"bộ phim"},{"hanzi":"电影","pinyin":"diànyǐng","vi":"điện ảnh"},{"hanzi":"拍片","pinyin":"pāipiàn","vi":"chụp phim"},{"hanzi":"大片","pinyin":"dàpiàn","vi":"phim bom tấn"}]},{"id":"骗人","hanzi":"骗人","pinyin":"piànrén","meaning_vi":"lừa người, lừa gạt","explanation":"骗 (phiến – lừa) + 人 (nhân – người) → lừa dối người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤥","examples":[{"type":"basic","zh":"你别骗人了！","pinyin":"Nǐ bié piànrén le!","vi":"Cậu đừng lừa người ta nữa!"},{"type":"simple","zh":"这种中奖短信都是骗人的。","pinyin":"Zhè zhǒng zhòngjiǎng duǎnxìn dōu shì piànrén de.","vi":"Mấy tin nhắn trúng thưởng kiểu này đều là lừa đảo."},{"type":"compound","zh":"如果你总是骗人，以后就没人相信你了。","pinyin":"Rúguǒ nǐ zǒngshì piànrén, yǐhòu jiù méi rén xiāngxìn nǐ le.","vi":"Nếu cậu cứ lừa người, sau này sẽ chẳng ai tin cậu nữa."}],"related":[{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa dối"},{"hanzi":"骗子","pinyin":"piànzi","vi":"kẻ lừa đảo"},{"hanzi":"诈骗","pinyin":"zhàpiàn","vi":"lừa đảo"},{"hanzi":"撒谎","pinyin":"sāhuǎng","vi":"nói dối"}],"traditional":"騙人"},{"id":"漂","hanzi":"漂","pinyin":"piāo","meaning_vi":"trôi, nổi, lênh đênh","explanation":"漂 (phiêu – trôi nổi) → nổi và trôi trên mặt nước; nghĩa bóng là sống lang bạt (北漂).","hsk_level":"7-9","tags":["dong-tu"],"image":"🛶","examples":[{"type":"basic","zh":"树叶漂在水面上。","pinyin":"Shùyè piāo zài shuǐmiàn shang.","vi":"Lá cây trôi trên mặt nước."},{"type":"simple","zh":"一只小纸船顺着小河慢慢漂走了。","pinyin":"Yì zhī xiǎo zhǐ chuán shùnzhe xiǎohé mànmàn piāozǒu le.","vi":"Một chiếc thuyền giấy nhỏ chầm chậm trôi theo dòng sông."},{"type":"compound","zh":"虽然他在北京漂了十年，但是还没买上房。","pinyin":"Suīrán tā zài Běijīng piāole shí nián, dànshì hái méi mǎi shàngfáng.","vi":"Tuy đã lăn lộn ở Bắc Kinh mười năm nhưng anh ấy vẫn chưa mua được nhà."}],"related":[{"hanzi":"漂浮","pinyin":"piāofú","vi":"trôi nổi"},{"hanzi":"漂流","pinyin":"piāoliú","vi":"trôi dạt"},{"hanzi":"浮","pinyin":"fú","vi":"nổi"},{"hanzi":"沉","pinyin":"chén","vi":"chìm"}]},{"id":"撇","hanzi":"撇","pinyin":"piē","meaning_vi":"vứt bỏ, gạt sang bên, bỏ lại","explanation":"撇 (phiết – gạt ra) → gạt bỏ, bỏ lại; cũng là nét phẩy trong chữ Hán và động từ hớt (bọt).","hsk_level":"7-9","tags":["dong-tu"],"image":"↪️","examples":[{"type":"basic","zh":"他撇下我走了。","pinyin":"Tā piēxià wǒ zǒu le.","vi":"Anh ta bỏ tôi lại mà đi."},{"type":"simple","zh":"妈妈把汤上面的油沫撇掉了。","pinyin":"Māma bǎ tāng shàngmian de yóu mò piēdiào le.","vi":"Mẹ hớt bỏ lớp bọt dầu trên mặt canh."},{"type":"compound","zh":"即使工作再忙，他也不会撇下家人不管。","pinyin":"Jíshǐ gōngzuò zài máng, tā yě bú huì piēxià jiārén bùguǎn.","vi":"Dù công việc bận đến mấy, anh ấy cũng không bỏ mặc gia đình."}],"related":[{"hanzi":"撇开","pinyin":"piēkāi","vi":"gạt sang bên"},{"hanzi":"抛弃","pinyin":"pāoqì","vi":"vứt bỏ"},{"hanzi":"扔下","pinyin":"rēngxià","vi":"bỏ lại"},{"hanzi":"丢下","pinyin":"diūxià","vi":"bỏ rơi"}]},{"id":"贫富","hanzi":"贫富","pinyin":"pínfù","meaning_vi":"giàu nghèo","explanation":"贫 (bần – nghèo) + 富 (phú – giàu) → nghèo và giàu; thường dùng trong 贫富差距 (chênh lệch giàu nghèo).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"⚖️","examples":[{"type":"basic","zh":"贫富差距很大。","pinyin":"Pínfùchājù hěn dà.","vi":"Chênh lệch giàu nghèo rất lớn."},{"type":"simple","zh":"在法律面前，不分贫富人人平等。","pinyin":"Zài fǎlǜ miànqián, bùfēn pínfù rénrén píngděng.","vi":"Trước pháp luật, không phân biệt giàu nghèo, mọi người đều bình đẳng."},{"type":"compound","zh":"如果贫富差距继续扩大，社会就会不稳定。","pinyin":"Rúguǒ pínfùchājù jìxù kuòdà, shèhuì jiù huì bù wěndìng.","vi":"Nếu chênh lệch giàu nghèo tiếp tục gia tăng thì xã hội sẽ bất ổn."}],"related":[{"hanzi":"贫穷","pinyin":"pínqióng","vi":"nghèo khó"},{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"},{"hanzi":"差距","pinyin":"chājù","vi":"chênh lệch"},{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khổ"}],"traditional":"貧富"},{"id":"聘","hanzi":"聘","pinyin":"pìn","meaning_vi":"mời, thuê (làm việc); dạm hỏi","explanation":"聘 (sính – mời, đón) → mời người đảm nhận công việc; xưa còn chỉ lễ hỏi cưới (聘礼).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📃","examples":[{"type":"basic","zh":"学校聘了一位外教。","pinyin":"Xuéxiào pìnle yí wèi wàijiào.","vi":"Trường đã mời một giáo viên nước ngoài."},{"type":"simple","zh":"公司高薪聘他担任技术总监。","pinyin":"Gōngsī gāoxīn pìn tā dānrèn jìshù zǒngjiān.","vi":"Công ty trả lương cao mời anh ấy làm giám đốc kỹ thuật."},{"type":"compound","zh":"因为他经验丰富，所以被三家公司同时聘请。","pinyin":"Yīnwèi tā jīngyàn fēngfù, suǒyǐ bèi sān jiā gōngsī tóngshí pìnqǐng.","vi":"Vì giàu kinh nghiệm nên anh ấy được ba công ty cùng lúc mời về."}],"related":[{"hanzi":"聘请","pinyin":"pìnqǐng","vi":"mời làm"},{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"应聘","pinyin":"yìngpìn","vi":"ứng tuyển"},{"hanzi":"解聘","pinyin":"jiěpìn","vi":"sa thải"}]},{"id":"聘任","hanzi":"聘任","pinyin":"pìnrèn","meaning_vi":"bổ nhiệm (theo hợp đồng), mời đảm nhiệm","explanation":"聘 (sính – mời) + 任 (nhiệm – giao chức vụ) → mời và giao giữ một chức vụ.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🎓","examples":[{"type":"basic","zh":"他被聘任为教授。","pinyin":"Tā bèi pìnrèn wéi jiàoshòu.","vi":"Ông ấy được bổ nhiệm làm giáo sư."},{"type":"simple","zh":"董事会决定聘任她为新的总经理。","pinyin":"Dǒngshìhuì juédìng pìnrèn tā wéi xīn de zǒngjīnglǐ.","vi":"Hội đồng quản trị quyết định bổ nhiệm bà ấy làm tổng giám đốc mới."},{"type":"compound","zh":"只要通过考核，学校就会继续聘任你。","pinyin":"Zhǐyào tōngguò kǎohé, xuéxiào jiù huì jìxù pìnrèn nǐ.","vi":"Chỉ cần đạt yêu cầu đánh giá, nhà trường sẽ tiếp tục bổ nhiệm bạn."}],"related":[{"hanzi":"任命","pinyin":"rènmìng","vi":"bổ nhiệm"},{"hanzi":"聘用","pinyin":"pìnyòng","vi":"tuyển dụng"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"聘书","pinyin":"pìnshū","vi":"giấy mời làm việc"}]},{"id":"聘用","hanzi":"聘用","pinyin":"pìnyòng","meaning_vi":"tuyển dụng, thuê (làm việc)","explanation":"聘 (sính – mời) + 用 (dụng – dùng) → mời và sử dụng người làm việc, tuyển dụng.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"公司聘用了他。","pinyin":"Gōngsī pìnyòngle tā.","vi":"Công ty đã tuyển dụng anh ấy."},{"type":"simple","zh":"这家医院今年聘用了二十名护士。","pinyin":"Zhè jiā yīyuàn jīnnián pìnyòngle èrshí míng hùshi.","vi":"Năm nay bệnh viện này đã tuyển hai mươi y tá."},{"type":"compound","zh":"虽然他没有学历，但是公司还是聘用了他。","pinyin":"Suīrán tā méiyǒu xuélì, dànshì gōngsī háishi pìnyòngle tā.","vi":"Tuy anh ấy không có bằng cấp nhưng công ty vẫn tuyển dụng anh ấy."}],"related":[{"hanzi":"雇用","pinyin":"gùyòng","vi":"thuê mướn"},{"hanzi":"录用","pinyin":"lùyòng","vi":"tuyển dụng"},{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"辞退","pinyin":"cítuì","vi":"cho thôi việc"}]},{"id":"平常心","hanzi":"平常心","pinyin":"píngchángxīn","meaning_vi":"tâm thế bình thản, thái độ bình thường","explanation":"平常 (bình thường) + 心 (tâm) → tấm lòng bình thản, không quá mừng hay quá lo trước được mất.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🧘","examples":[{"type":"basic","zh":"要保持平常心。","pinyin":"Yào bǎochí píngchángxīn.","vi":"Phải giữ tâm thế bình thản."},{"type":"simple","zh":"教练让队员们以平常心面对决赛。","pinyin":"Jiàoliàn ràng duìyuánmen yǐ píngchángxīn miànduì juésài.","vi":"Huấn luyện viên bảo các cầu thủ đối mặt trận chung kết với tâm thế bình thường."},{"type":"compound","zh":"只要用平常心对待考试，就不会太紧张。","pinyin":"Zhǐyào yòng píngchángxīn duìdài kǎoshì, jiù bú huì tài jǐnzhāng.","vi":"Chỉ cần coi kỳ thi bằng tâm thế bình thản thì sẽ không quá căng thẳng."}],"related":[{"hanzi":"心态","pinyin":"xīntài","vi":"tâm thái"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình tĩnh"},{"hanzi":"淡定","pinyin":"dàndìng","vi":"điềm tĩnh"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"}]},{"id":"平和","hanzi":"平和","pinyin":"pínghé","meaning_vi":"ôn hòa, hiền hòa, bình thản","explanation":"平 (bình – bằng phẳng) + 和 (hòa – hài hòa) → ôn hòa, nhẹ nhàng; cũng chỉ thuốc có tính dịu.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🕊️","examples":[{"type":"basic","zh":"他说话很平和。","pinyin":"Tā shuōhuà hěn pínghé.","vi":"Anh ấy nói chuyện rất ôn hòa."},{"type":"simple","zh":"老人性格平和，从来不跟人吵架。","pinyin":"Lǎorén xìnggé pínghé, cóngláibù gēn rén chǎojià.","vi":"Cụ già tính tình hiền hòa, chưa bao giờ cãi nhau với ai."},{"type":"compound","zh":"虽然对方很生气，但是她的语气始终很平和。","pinyin":"Suīrán duìfāng hěn shēngqì, dànshì tā de yǔqì shǐzhōng hěn pínghé.","vi":"Tuy đối phương rất tức giận nhưng giọng cô ấy trước sau vẫn ôn hòa."}],"related":[{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"},{"hanzi":"和平","pinyin":"hépíng","vi":"hòa bình"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình lặng"},{"hanzi":"暴躁","pinyin":"bàozào","vi":"nóng nảy"}]},{"id":"平价","hanzi":"平价","pinyin":"píngjià","meaning_vi":"giá bình dân, giá phải chăng","explanation":"平 (bình – bình thường) + 价 (giá) → giá cả bình thường, phải chăng; cũng chỉ ngang giá (tỷ giá).","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这是平价超市。","pinyin":"Zhè shì píngjià chāoshì.","vi":"Đây là siêu thị giá rẻ."},{"type":"simple","zh":"学校附近开了几家平价餐厅。","pinyin":"Xuéxiào fùjìn kāile jǐ jiā píngjià cāntīng.","vi":"Gần trường mở mấy nhà hàng giá bình dân."},{"type":"compound","zh":"虽然这款口红是平价的，但是颜色很好看。","pinyin":"Suīrán zhè kuǎn kǒuhóng shì píngjià de, dànshì yánsè hěn hǎokàn.","vi":"Tuy thỏi son này giá bình dân nhưng màu rất đẹp."}],"related":[{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"实惠","pinyin":"shíhuì","vi":"thiết thực"},{"hanzi":"高价","pinyin":"gāojià","vi":"giá cao"},{"hanzi":"物价","pinyin":"wùjià","vi":"vật giá"}],"traditional":"平價"},{"id":"平民","hanzi":"平民","pinyin":"píngmín","meaning_vi":"dân thường, thường dân","explanation":"平 (bình – bình thường) + 民 (dân) → người dân bình thường, không phải quan chức hay quân nhân.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🧑‍🤝‍🧑","examples":[{"type":"basic","zh":"战争伤害了平民。","pinyin":"Zhànzhēng shānghàile píngmín.","vi":"Chiến tranh gây tổn hại cho dân thường."},{"type":"simple","zh":"他出身平民家庭，靠自己考上了名校。","pinyin":"Tā chūshēn píngmín jiātíng, kào zìjǐ kǎoshàngle míngxiào.","vi":"Anh ấy xuất thân gia đình bình dân, tự mình thi đỗ trường danh tiếng."},{"type":"compound","zh":"虽然他是国王，但是他的生活跟平民差不多。","pinyin":"Suīrán tā shì guówáng, dànshì tā de shēnghuó gēn píngmín chàbuduō.","vi":"Tuy là vua nhưng cuộc sống của ông chẳng khác dân thường là mấy."}],"related":[{"hanzi":"百姓","pinyin":"bǎixìng","vi":"bách tính"},{"hanzi":"老百姓","pinyin":"lǎobǎixìng","vi":"dân thường"},{"hanzi":"贵族","pinyin":"guìzú","vi":"quý tộc"},{"hanzi":"平民百姓","pinyin":"píngmínbǎixìng","vi":"thường dân"}]},{"id":"平日","hanzi":"平日","pinyin":"píngrì","meaning_vi":"ngày thường, thường ngày","explanation":"平 (bình – bình thường) + 日 (nhật – ngày) → những ngày thường, không phải ngày lễ.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📆","examples":[{"type":"basic","zh":"他平日很少说话。","pinyin":"Tā píngrì hěn shǎo shuōhuà.","vi":"Ngày thường anh ấy rất ít nói."},{"type":"simple","zh":"这家博物馆平日游客不多，周末很挤。","pinyin":"Zhè jiā bówùguǎn píngrì yóukè bù duō, zhōumò hěn jǐ.","vi":"Bảo tàng này ngày thường ít khách, cuối tuần rất đông."},{"type":"compound","zh":"如果平日多努力，考试时就不用熬夜了。","pinyin":"Rúguǒ píngrì duō nǔlì, kǎoshì shí jiù bú yòng áoyè le.","vi":"Nếu ngày thường chăm chỉ hơn thì lúc thi không phải thức khuya."}],"related":[{"hanzi":"平时","pinyin":"píngshí","vi":"lúc thường"},{"hanzi":"往日","pinyin":"wǎngrì","vi":"ngày trước"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"},{"hanzi":"工作日","pinyin":"gōngzuòrì","vi":"ngày làm việc"}]},{"id":"评定","hanzi":"评定","pinyin":"píngdìng","meaning_vi":"đánh giá, bình xét, xếp loại","explanation":"评 (bình – bình phẩm) + 定 (định – quyết định) → xem xét rồi đưa ra kết luận, xếp loại.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏅","examples":[{"type":"basic","zh":"他被评定为一级。","pinyin":"Tā bèi píng dìngwéi yìjí.","vi":"Anh ấy được xếp loại cấp một."},{"type":"simple","zh":"专家组正在评定这批论文的质量。","pinyin":"Zhuānjiā zǔ zhèngzài píngdìng zhè pī lùnwén de zhìliàng.","vi":"Nhóm chuyên gia đang đánh giá chất lượng loạt luận văn này."},{"type":"compound","zh":"如果成绩评定不公平，学生就可以申请复查。","pinyin":"Rúguǒ chéngjì píngdìng bù gōngpíng, xuésheng jiù kěyǐ shēnqǐng fùchá.","vi":"Nếu việc đánh giá điểm số không công bằng thì học sinh có thể xin phúc tra."}],"related":[{"hanzi":"评估","pinyin":"pínggū","vi":"đánh giá"},{"hanzi":"评审","pinyin":"píngshěn","vi":"thẩm định"},{"hanzi":"鉴定","pinyin":"jiàndìng","vi":"giám định"},{"hanzi":"评价","pinyin":"píngjià","vi":"nhận xét"}],"traditional":"評定"},{"id":"评论员","hanzi":"评论员","pinyin":"pínglùnyuán","meaning_vi":"bình luận viên","explanation":"评论 (bình luận) + 员 (viên – người làm) → người chuyên bình luận thời sự, thể thao.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🎤","examples":[{"type":"basic","zh":"他是体育评论员。","pinyin":"Tā shì tǐyù pínglùnyuán.","vi":"Anh ấy là bình luận viên thể thao."},{"type":"simple","zh":"电视台请了几位评论员分析这场比赛。","pinyin":"Diànshìtái qǐngle jǐ wèi pínglùnyuán fēnxī zhè chǎng bǐsài.","vi":"Đài truyền hình mời mấy bình luận viên phân tích trận đấu này."},{"type":"compound","zh":"虽然评论员说得头头是道，但是比赛结果出人意料。","pinyin":"Suīrán pínglùnyuán shuō de tóutóushìdào, dànshì bǐsài jiéguǒ chūrényìliào.","vi":"Tuy bình luận viên nói rất có lý, nhưng kết quả trận đấu lại ngoài dự đoán."}],"related":[{"hanzi":"解说员","pinyin":"jiěshuōyuán","vi":"người bình luận"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"},{"hanzi":"记者","pinyin":"jìzhě","vi":"phóng viên"},{"hanzi":"主持人","pinyin":"zhǔchírén","vi":"người dẫn chương trình"}],"traditional":"評論員"},{"id":"评审","hanzi":"评审","pinyin":"píngshěn","meaning_vi":"thẩm định, đánh giá, chấm (thi)","explanation":"评 (bình – bình xét) + 审 (thẩm – xem xét kỹ) → xem xét kỹ để đánh giá; cũng chỉ người làm giám khảo.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"他担任大赛评审。","pinyin":"Tā dānrèn dàsài píngshěn.","vi":"Anh ấy làm giám khảo cuộc thi."},{"type":"simple","zh":"这个项目还在等待专家评审。","pinyin":"Zhè ge xiàngmù hái zài děngdài zhuānjiā píngshěn.","vi":"Dự án này vẫn đang chờ chuyên gia thẩm định."},{"type":"compound","zh":"一旦评审通过，我们就可以拿到资金了。","pinyin":"Yídàn píngshěn tōngguò, wǒmen jiù kěyǐ nádào zījīn le.","vi":"Một khi thẩm định thông qua, chúng ta sẽ nhận được vốn."}],"related":[{"hanzi":"评委","pinyin":"píngwěi","vi":"ban giám khảo"},{"hanzi":"审核","pinyin":"shěnhé","vi":"thẩm duyệt"},{"hanzi":"评定","pinyin":"píngdìng","vi":"xếp loại"},{"hanzi":"审查","pinyin":"shěnchá","vi":"thẩm tra"}],"traditional":"評審"},{"id":"凭着","hanzi":"凭着","pinyin":"píngzhe","meaning_vi":"dựa vào, nhờ vào","explanation":"凭 (bằng – dựa vào) + 着 (trợ từ) → dựa vào, nhờ vào (năng lực, kinh nghiệm…).","hsk_level":"7-9","tags":["gioi-tu"],"image":"🪜","examples":[{"type":"basic","zh":"他凭着经验找到了路。","pinyin":"Tā píngzhe jīngyàn zhǎodàole lù.","vi":"Anh ấy dựa vào kinh nghiệm tìm ra đường."},{"type":"simple","zh":"她凭着一手好厨艺开了家小饭馆。","pinyin":"Tā píngzhe yìshǒu hǎo chúyì kāile jiā xiǎofànguǎn.","vi":"Nhờ tay nghề nấu ăn giỏi, cô ấy đã mở một quán ăn nhỏ."},{"type":"compound","zh":"虽然家里很穷，但是他凭着努力考上了大学。","pinyin":"Suīrán jiālǐ hěn qióng, dànshì tā píngzhe nǔlì kǎoshàngle dàxué.","vi":"Tuy nhà rất nghèo nhưng nhờ nỗ lực anh ấy đã đỗ đại học."}],"related":[{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"凭借","pinyin":"píngjiè","vi":"nhờ vào"},{"hanzi":"靠","pinyin":"kào","vi":"dựa"},{"hanzi":"根据","pinyin":"gēnjù","vi":"căn cứ"}],"traditional":"憑著"},{"id":"凭证","hanzi":"凭证","pinyin":"píngzhèng","meaning_vi":"chứng từ, bằng chứng, giấy tờ làm bằng","explanation":"凭 (bằng – căn cứ) + 证 (chứng – chứng nhận) → giấy tờ làm căn cứ, chứng từ.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"请保留购物凭证。","pinyin":"Qǐng bǎoliú gòuwù píngzhèng.","vi":"Vui lòng giữ lại chứng từ mua hàng."},{"type":"simple","zh":"会计要求每笔支出都要有凭证。","pinyin":"Kuàijì yāoqiú měi bǐ zhīchū dōu yàoyǒu píngzhèng.","vi":"Kế toán yêu cầu mỗi khoản chi đều phải có chứng từ."},{"type":"compound","zh":"如果没有付款凭证，就不能办理退货。","pinyin":"Rúguǒ méiyǒu fùkuǎn píngzhèng, jiù bù néng bànlǐ tuìhuò.","vi":"Nếu không có chứng từ thanh toán thì không thể làm thủ tục trả hàng."}],"related":[{"hanzi":"收据","pinyin":"shōujù","vi":"biên lai"},{"hanzi":"发票","pinyin":"fāpiào","vi":"hóa đơn"},{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"giấy chứng nhận"}],"traditional":"憑證"},{"id":"萍水相逢","hanzi":"萍水相逢","pinyin":"píngshuǐ-xiāngféng","meaning_vi":"bèo nước gặp nhau, tình cờ quen biết","explanation":"萍 (bình – bèo) + 水 (thủy – nước) + 相逢 (tương phùng – gặp nhau) → bèo trôi trên nước tình cờ gặp nhau; chỉ người xa lạ ngẫu nhiên quen biết. Gốc từ “Đằng Vương các tự” của Vương Bột.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🍃","examples":[{"type":"basic","zh":"我们只是萍水相逢。","pinyin":"Wǒmen zhǐshì píngshuǐxiāngféng.","vi":"Chúng ta chỉ là bèo nước gặp nhau."},{"type":"simple","zh":"萍水相逢的路人竟然帮我修好了车。","pinyin":"Píngshuǐxiāngféng de lùrén jìngrán bāng wǒ xiūhǎole chē.","vi":"Người qua đường tình cờ gặp vậy mà lại giúp tôi sửa xong xe."},{"type":"compound","zh":"虽然我们萍水相逢，但是他对我像老朋友一样。","pinyin":"Suīrán wǒmen píngshuǐxiāngféng, dànshì tā duì wǒ xiàng lǎopéngyou yíyàng.","vi":"Tuy chúng tôi chỉ tình cờ gặp nhau, nhưng anh ấy đối xử với tôi như bạn cũ."}],"related":[{"hanzi":"相逢","pinyin":"xiāngféng","vi":"gặp gỡ"},{"hanzi":"邂逅","pinyin":"xièhòu","vi":"tình cờ gặp"},{"hanzi":"陌生人","pinyin":"mòshēngrén","vi":"người lạ"},{"hanzi":"一面之交","pinyin":"yímiànzhījiāo","vi":"quen sơ"}]},{"id":"迫使","hanzi":"迫使","pinyin":"pòshǐ","meaning_vi":"buộc, bắt buộc, ép","explanation":"迫 (bách – ép, bức) + 使 (sử – khiến) → dùng sức ép khiến người khác phải làm gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛓️","examples":[{"type":"basic","zh":"大雨迫使比赛暂停。","pinyin":"Dàyǔ pòshǐ bǐsài zàntíng.","vi":"Mưa lớn buộc trận đấu phải tạm dừng."},{"type":"simple","zh":"经济危机迫使很多工厂关了门。","pinyin":"Jīngjì wēijī pòshǐ hěn duō gōngchǎng guānle mén.","vi":"Khủng hoảng kinh tế buộc nhiều nhà máy phải đóng cửa."},{"type":"compound","zh":"因为公司还不上贷款，所以银行迫使它卖掉了工厂。","pinyin":"Yīnwèi gōngsī huán bu shàng dàikuǎn, suǒyǐ yínháng pòshǐ tā màidiàole gōngchǎng.","vi":"Vì công ty không trả nổi khoản vay nên ngân hàng buộc nó phải bán nhà máy."}],"related":[{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"cưỡng ép"},{"hanzi":"逼迫","pinyin":"bīpò","vi":"bức ép"},{"hanzi":"被迫","pinyin":"bèipò","vi":"bị buộc"},{"hanzi":"促使","pinyin":"cùshǐ","vi":"thúc đẩy"}]},{"id":"破案","hanzi":"破案","pinyin":"pò'àn","meaning_vi":"phá án","explanation":"破 (phá – làm vỡ, khám phá) + 案 (án – vụ án) → điều tra làm rõ và giải quyết vụ án.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"警察终于破案了。","pinyin":"Jǐngchá zhōngyú pò'àn le.","vi":"Cảnh sát cuối cùng đã phá được án."},{"type":"simple","zh":"这起盗窃案，警方只用三天就破案了。","pinyin":"Zhè qǐ dàoqiè àn, jǐngfāng zhǐ yòng sān tiān jiù pò'àn le.","vi":"Cảnh sát chỉ mất ba ngày đã phá vụ trộm này."},{"type":"compound","zh":"如果没有监控录像，警察就很难这么快破案。","pinyin":"Rúguǒ méiyǒu jiānkòng lùxiàng, jǐngchá jiù hěn nán zhème kuài pò'àn.","vi":"Nếu không có video camera giám sát thì cảnh sát khó mà phá án nhanh như vậy."}],"related":[{"hanzi":"侦破","pinyin":"zhēnpò","vi":"điều tra phá án"},{"hanzi":"案件","pinyin":"ànjiàn","vi":"vụ án"},{"hanzi":"侦探","pinyin":"zhēntàn","vi":"thám tử"},{"hanzi":"线索","pinyin":"xiànsuǒ","vi":"manh mối"}]},{"id":"破除","hanzi":"破除","pinyin":"pòchú","meaning_vi":"bài trừ, xóa bỏ, phá bỏ","explanation":"破 (phá – phá vỡ) + 除 (trừ – loại bỏ) → phá bỏ, xóa bỏ (mê tín, hủ tục, quan niệm cũ).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚫","examples":[{"type":"basic","zh":"要破除迷信。","pinyin":"Yào pòchú míxìn.","vi":"Cần bài trừ mê tín."},{"type":"simple","zh":"这部电影帮助观众破除了对精神病的偏见。","pinyin":"Zhè bù diànyǐng bāngzhù guānzhòng pòchúle duì jīngshénbìng de piānjiàn.","vi":"Bộ phim này giúp khán giả xóa bỏ định kiến về bệnh tâm thần."},{"type":"compound","zh":"只有破除旧观念，改革才能顺利进行。","pinyin":"Zhǐyǒu pòchú jiù guānniàn, gǎigé cáinéng shùnlì jìnxíng.","vi":"Chỉ có xóa bỏ quan niệm cũ thì cải cách mới tiến hành thuận lợi."}],"related":[{"hanzi":"消除","pinyin":"xiāochú","vi":"loại bỏ"},{"hanzi":"废除","pinyin":"fèichú","vi":"bãi bỏ"},{"hanzi":"打破","pinyin":"dǎpò","vi":"phá vỡ"},{"hanzi":"迷信","pinyin":"míxìn","vi":"mê tín"}]},{"id":"破裂","hanzi":"破裂","pinyin":"pòliè","meaning_vi":"vỡ, nứt vỡ; tan vỡ (quan hệ)","explanation":"破 (phá – vỡ) + 裂 (liệt – nứt) → nứt vỡ; nghĩa bóng là quan hệ, đàm phán đổ vỡ.","hsk_level":"7-9","tags":["dong-tu"],"image":"💔","examples":[{"type":"basic","zh":"水管破裂了。","pinyin":"Shuǐguǎn pòliè le.","vi":"Ống nước bị vỡ rồi."},{"type":"simple","zh":"两国的谈判最终还是破裂了。","pinyin":"Liǎngguó de tánpàn zuìzhōng háishi pòliè le.","vi":"Cuộc đàm phán giữa hai nước cuối cùng vẫn đổ vỡ."},{"type":"compound","zh":"因为长期缺少沟通，所以他们的婚姻破裂了。","pinyin":"Yīnwèi chángqī quēshǎo gōutōng, suǒyǐ tāmen de hūnyīn pòliè le.","vi":"Vì lâu ngày thiếu giao tiếp nên hôn nhân của họ đã tan vỡ."}],"related":[{"hanzi":"破碎","pinyin":"pòsuì","vi":"vỡ vụn"},{"hanzi":"决裂","pinyin":"juéliè","vi":"cắt đứt"},{"hanzi":"分裂","pinyin":"fēnliè","vi":"chia rẽ"},{"hanzi":"裂缝","pinyin":"lièfèng","vi":"vết nứt"}]},{"id":"破灭","hanzi":"破灭","pinyin":"pòmiè","meaning_vi":"tan vỡ, tiêu tan (hy vọng, ảo tưởng)","explanation":"破 (phá – vỡ) + 灭 (diệt – tắt, mất) → vỡ tan và mất hẳn, thường nói về hy vọng, giấc mơ.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🫧","examples":[{"type":"basic","zh":"他的梦想破灭了。","pinyin":"Tā de mèngxiǎng pòmiè le.","vi":"Giấc mơ của anh ấy đã tan vỡ."},{"type":"simple","zh":"比赛输了以后，球队进决赛的希望破灭了。","pinyin":"Bǐsài shūle yǐhòu, qiúduì jìn juésài de xīwàng pòmiè le.","vi":"Sau khi thua trận, hy vọng vào chung kết của đội bóng đã tiêu tan."},{"type":"compound","zh":"即使一次又一次希望破灭，她也没有放弃。","pinyin":"Jíshǐ yí cì yòu yí cì xīwàng pòmiè, tā yě méiyǒu fàngqì.","vi":"Dù hy vọng hết lần này đến lần khác tan vỡ, cô ấy vẫn không bỏ cuộc."}],"related":[{"hanzi":"幻灭","pinyin":"huànmiè","vi":"vỡ mộng"},{"hanzi":"落空","pinyin":"luòkōng","vi":"thất bại"},{"hanzi":"泡沫","pinyin":"pàomò","vi":"bong bóng"},{"hanzi":"实现","pinyin":"shíxiàn","vi":"thực hiện"}],"traditional":"破滅"},{"id":"破碎","hanzi":"破碎","pinyin":"pòsuì","meaning_vi":"vỡ vụn, tan nát","explanation":"破 (phá – vỡ) + 碎 (toái – vụn) → vỡ thành từng mảnh; nghĩa bóng là tan nát (gia đình, trái tim).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🪞","examples":[{"type":"basic","zh":"镜子破碎了。","pinyin":"Jìngzi pòsuì le.","vi":"Cái gương vỡ vụn rồi."},{"type":"simple","zh":"她来自一个破碎的家庭，从小跟着奶奶。","pinyin":"Tā láizì yí gè pòsuì de jiātíng, cóngxiǎo gēnzhe nǎinai.","vi":"Cô ấy đến từ một gia đình tan vỡ, từ nhỏ đã sống với bà."},{"type":"compound","zh":"虽然玻璃杯摔得破碎了，但是幸好没伤到人。","pinyin":"Suīrán bōlibēi shuāi de pòsuì le, dànshì xìnghǎo méi shāng dào rén.","vi":"Tuy chiếc cốc thủy tinh rơi vỡ vụn nhưng may là không ai bị thương."}],"related":[{"hanzi":"粉碎","pinyin":"fěnsuì","vi":"nghiền nát"},{"hanzi":"破裂","pinyin":"pòliè","vi":"nứt vỡ"},{"hanzi":"碎片","pinyin":"suìpiàn","vi":"mảnh vỡ"},{"hanzi":"完整","pinyin":"wánzhěng","vi":"nguyên vẹn"}]},{"id":"扑克","hanzi":"扑克","pinyin":"pūkè","meaning_vi":"bài tây, bài poker","explanation":"Phiên âm từ tiếng Anh “poker” → bộ bài tây 54 lá, trò chơi bài.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🃏","examples":[{"type":"basic","zh":"我们来打扑克吧！","pinyin":"Wǒmen lái dǎpūkè ba!","vi":"Chúng mình chơi bài đi!"},{"type":"simple","zh":"过年时，一家人常常围在一起打扑克。","pinyin":"Guònián shí, yìjiārén chángcháng wéi zài yìqǐ dǎpūkè.","vi":"Dịp Tết, cả nhà thường quây quần chơi bài cùng nhau."},{"type":"compound","zh":"虽然他打扑克总是输，但是每次都玩得很开心。","pinyin":"Suīrán tā dǎpūkè zǒngshì shū, dànshì měi cì dōu wán de hěn kāixīn.","vi":"Tuy chơi bài lúc nào cũng thua nhưng lần nào anh ấy cũng chơi rất vui."}],"related":[{"hanzi":"扑克牌","pinyin":"pūkèpái","vi":"lá bài tây"},{"hanzi":"纸牌","pinyin":"zhǐpái","vi":"bài giấy"},{"hanzi":"打牌","pinyin":"dǎpái","vi":"đánh bài"},{"hanzi":"麻将","pinyin":"májiàng","vi":"mạt chược"}],"traditional":"撲克"},{"id":"菩萨","hanzi":"菩萨","pinyin":"púsà","meaning_vi":"Bồ Tát","explanation":"Phiên âm rút gọn từ tiếng Phạn “Bodhisattva” (菩提萨埵) → bậc giác ngộ cứu độ chúng sinh; nghĩa bóng chỉ người hiền lành, từ bi.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🙏","examples":[{"type":"basic","zh":"庙里供着菩萨。","pinyin":"Miào lǐ gòngzhe púsà.","vi":"Trong chùa thờ Bồ Tát."},{"type":"simple","zh":"奶奶每天早上都对着菩萨烧香祈福。","pinyin":"Nǎinai měitiān zǎo Shangdōu duìzhe púsà shāoxiāng qífú.","vi":"Sáng nào bà cũng thắp hương trước Bồ Tát cầu phúc."},{"type":"compound","zh":"虽然他长得很凶，但是心肠像菩萨一样好。","pinyin":"Suīrán tā zhǎngde hěn xiōng, dànshì xīncháng xiàng púsà yíyàng hǎo.","vi":"Tuy trông dữ dằn nhưng lòng dạ ông ấy hiền như Bồ Tát."}],"related":[{"hanzi":"佛","pinyin":"fó","vi":"Phật"},{"hanzi":"观音","pinyin":"Guānyīn","vi":"Quan Âm"},{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"佛教","pinyin":"Fójiào","vi":"Phật giáo"}],"traditional":"菩薩"},{"id":"普通人","hanzi":"普通人","pinyin":"pǔtōngrén","meaning_vi":"người bình thường, người thường","explanation":"普通 (phổ thông – bình thường) + 人 (nhân) → người bình thường, không có gì đặc biệt.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧍","examples":[{"type":"basic","zh":"我只是个普通人。","pinyin":"Wǒ zhǐshì gè pǔtōngrén.","vi":"Tôi chỉ là người bình thường."},{"type":"simple","zh":"这部电影讲述了一个普通人的英雄故事。","pinyin":"Zhè bù diànyǐng jiǎngshùle yí gè pǔtōngrén de yīngxióng gùshi.","vi":"Bộ phim kể câu chuyện anh hùng của một người bình thường."},{"type":"compound","zh":"虽然他已经出名了，但是仍然过着普通人的生活。","pinyin":"Suīrán tā yǐjīng chūmíng le, dànshì réngránguò zhe pǔtōngrén de shēnghuó.","vi":"Tuy đã nổi tiếng nhưng anh ấy vẫn sống cuộc sống của người bình thường."}],"related":[{"hanzi":"平民","pinyin":"píngmín","vi":"dân thường"},{"hanzi":"老百姓","pinyin":"lǎobǎixìng","vi":"dân thường"},{"hanzi":"凡人","pinyin":"fánrén","vi":"người phàm"},{"hanzi":"名人","pinyin":"míngrén","vi":"người nổi tiếng"}]},{"id":"谱","hanzi":"谱","pinyin":"pǔ","meaning_vi":"bảng, phả, sổ ghi; bản nhạc; (khẩu ngữ) chừng mực","explanation":"谱 (phổ – bảng ghi theo thứ tự) → gia phả, bản nhạc, sách hướng dẫn (菜谱); khẩu ngữ: có chừng mực, đáng tin (靠谱).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎼","examples":[{"type":"basic","zh":"我不会看谱。","pinyin":"Wǒ bú huì kàn pǔ.","vi":"Tôi không biết đọc bản nhạc."},{"type":"simple","zh":"他按照菜谱一步一步地做了红烧肉。","pinyin":"Tā ànzhào càipǔ yí bù yi bù de zuòle hóngshāoròu.","vi":"Anh ấy làm món thịt kho từng bước theo sách nấu ăn."},{"type":"compound","zh":"虽然他说得很有把握，但是我心里没谱。","pinyin":"Suīrán tā shuō de hěn yǒubǎwò, dànshì wǒ xīnlǐ méipǔ.","vi":"Tuy anh ấy nói rất chắc chắn nhưng trong lòng tôi chẳng nắm chắc gì."}],"related":[{"hanzi":"乐谱","pinyin":"yuèpǔ","vi":"bản nhạc"},{"hanzi":"菜谱","pinyin":"càipǔ","vi":"công thức nấu ăn"},{"hanzi":"家谱","pinyin":"jiāpǔ","vi":"gia phả"},{"hanzi":"靠谱","pinyin":"kàopǔ","vi":"đáng tin"}],"traditional":"譜"},{"id":"沏","hanzi":"沏","pinyin":"qī","meaning_vi":"pha (trà)","explanation":"沏 (thế – rót nước sôi) → rót nước sôi vào để pha trà, pha nước.","hsk_level":"7-9","tags":["dong-tu","do-uong"],"image":"🍵","examples":[{"type":"basic","zh":"给客人沏杯茶。","pinyin":"Gěi kèrén qī bēi chá.","vi":"Pha cho khách một tách trà."},{"type":"simple","zh":"爷爷每天早上都要沏一壶绿茶。","pinyin":"Yéye měitiān zǎo Shangdōu yào qī yì hú lǜchá.","vi":"Sáng nào ông cũng pha một ấm trà xanh."},{"type":"compound","zh":"如果水温太高，沏出来的绿茶就会发苦。","pinyin":"Rúguǒ shuǐwēn tài gāo, qī chūlái de lǜchá jiù huì fā kǔ.","vi":"Nếu nước quá nóng thì trà xanh pha ra sẽ bị đắng."}],"related":[{"hanzi":"泡茶","pinyin":"pàochá","vi":"pha trà"},{"hanzi":"茶壶","pinyin":"cháhú","vi":"ấm trà"},{"hanzi":"冲","pinyin":"chōng","vi":"pha, rót"},{"hanzi":"茶叶","pinyin":"cháyè","vi":"lá trà"}]},{"id":"期盼","hanzi":"期盼","pinyin":"qīpàn","meaning_vi":"mong đợi, mong chờ, trông mong","explanation":"期 (kỳ – mong đợi) + 盼 (phán – trông ngóng) → mong mỏi, trông chờ điều tốt đẹp.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🌅","examples":[{"type":"basic","zh":"大家都期盼着和平。","pinyin":"Dàjiā dōu qīpànzhe hépíng.","vi":"Mọi người đều mong chờ hòa bình."},{"type":"simple","zh":"父母期盼孩子能平平安安地长大。","pinyin":"Fùmǔ qīpàn háizi néng píngpíng ān'ān de zhǎngdà.","vi":"Cha mẹ mong con cái lớn lên bình an."},{"type":"compound","zh":"因为期盼了很多年，所以团聚那天他们都哭了。","pinyin":"Yīnwèi qīpànle hěn duōnián, suǒyǐ tuánjù nà tiān tāmen dōu kū le.","vi":"Vì đã mong chờ nhiều năm nên ngày đoàn tụ họ đều bật khóc."}],"related":[{"hanzi":"期待","pinyin":"qīdài","vi":"mong đợi"},{"hanzi":"盼望","pinyin":"pànwàng","vi":"mong ngóng"},{"hanzi":"期望","pinyin":"qīwàng","vi":"kỳ vọng"},{"hanzi":"渴望","pinyin":"kěwàng","vi":"khao khát"}]},{"id":"欺诈","hanzi":"欺诈","pinyin":"qīzhà","meaning_vi":"lừa đảo, gian lận","explanation":"欺 (khi – lừa dối) + 诈 (trá – gian trá) → dùng thủ đoạn gian dối để lừa người, chiếm lợi.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🎭","examples":[{"type":"basic","zh":"这是商业欺诈。","pinyin":"Zhè shì shāngyè qīzhà.","vi":"Đây là lừa đảo thương mại."},{"type":"simple","zh":"这家公司因为欺诈消费者被罚款了。","pinyin":"Zhè jiā gōngsī yīnwèi qīzhà xiāofèizhě bèi fákuǎn le.","vi":"Công ty này bị phạt tiền vì lừa đảo người tiêu dùng."},{"type":"compound","zh":"如果商家有欺诈行为，消费者就可以要求赔偿。","pinyin":"Rúguǒ shāngjiā yǒu qīzhà xíngwéi, xiāofèizhě jiù kěyǐ yāoqiú péicháng.","vi":"Nếu người bán có hành vi gian lận thì người tiêu dùng có thể yêu cầu bồi thường."}],"related":[{"hanzi":"诈骗","pinyin":"zhàpiàn","vi":"lừa đảo"},{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa dối"},{"hanzi":"骗局","pinyin":"piànjú","vi":"trò lừa"},{"hanzi":"诚信","pinyin":"chéngxìn","vi":"thành tín"}],"traditional":"欺詐"},{"id":"漆","hanzi":"漆","pinyin":"qī","meaning_vi":"sơn, sơn mài; sơn (đồ vật)","explanation":"漆 (tất) → nhựa cây sơn, sơn; cũng làm động từ là quét sơn.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🖌️","examples":[{"type":"basic","zh":"小心，油漆未干！","pinyin":"Xiǎoxīn, yóuqī wèi gān!","vi":"Cẩn thận, sơn chưa khô!"},{"type":"simple","zh":"工人把大门漆成了深绿色。","pinyin":"Gōngrén bǎ dàmén qī chéngle shēn lǜsè.","vi":"Thợ đã sơn cánh cổng thành màu xanh lá đậm."},{"type":"compound","zh":"因为墙上的漆有点脱落，所以我们打算重新刷一遍。","pinyin":"Yīnwèi qiáng shang de qī yǒudiǎn tuōluò, suǒyǐ wǒmen dǎsuàn chóngxīn shuā yíbiàn.","vi":"Vì sơn trên tường hơi bong tróc nên chúng tôi định quét lại một lượt."}],"related":[{"hanzi":"油漆","pinyin":"yóuqī","vi":"sơn dầu"},{"hanzi":"漆器","pinyin":"qīqì","vi":"đồ sơn mài"},{"hanzi":"涂","pinyin":"tú","vi":"quét, bôi"},{"hanzi":"漆黑","pinyin":"qīhēi","vi":"tối đen"}]},{"id":"其后","hanzi":"其后","pinyin":"qíhòu","meaning_vi":"sau đó, về sau","explanation":"其 (kỳ – cái đó) + 后 (hậu – sau) → sau việc đó, sau đó (văn viết).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏭️","examples":[{"type":"basic","zh":"其后他去了美国。","pinyin":"Qíhòu tā qùle Měiguó.","vi":"Sau đó anh ấy sang Mỹ."},{"type":"simple","zh":"他先当了几年老师，其后又开始写小说。","pinyin":"Tā xiān dāngle jǐ nián lǎoshī, qíhòu yòu kāishǐ xiě xiǎoshuō.","vi":"Ông ấy làm giáo viên mấy năm trước, sau đó lại bắt đầu viết tiểu thuyết."},{"type":"compound","zh":"虽然第一次实验失败了，但是其后的实验都很顺利。","pinyin":"Suīrán dìyīcì shíyàn shībài le, dànshì qíhòu de shíyàn dōu hěn shùnlì.","vi":"Tuy thí nghiệm đầu tiên thất bại, nhưng các thí nghiệm sau đó đều rất suôn sẻ."}],"related":[{"hanzi":"随后","pinyin":"suíhòu","vi":"ngay sau đó"},{"hanzi":"此后","pinyin":"cǐhòu","vi":"từ đó về sau"},{"hanzi":"之后","pinyin":"zhīhòu","vi":"sau đó"},{"hanzi":"其间","pinyin":"qíjiān","vi":"trong khoảng đó"}],"traditional":"其後"},{"id":"其间","hanzi":"其间","pinyin":"qíjiān","meaning_vi":"trong thời gian đó, trong khoảng đó","explanation":"其 (kỳ – cái đó) + 间 (gian – khoảng giữa) → trong khoảng thời gian hoặc phạm vi đó.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"其间发生了很多事。","pinyin":"Qíjiān fāshēngle hěn duōshì.","vi":"Trong khoảng thời gian đó đã xảy ra nhiều chuyện."},{"type":"simple","zh":"他在国外住了五年，其间回过两次家。","pinyin":"Tā zài guówài zhùle wǔ nián, qíjiān huíguo liǎng cì jiā.","vi":"Anh ấy sống ở nước ngoài năm năm, trong thời gian đó có về nhà hai lần."},{"type":"compound","zh":"虽然项目花了两年，但是其间遇到的困难数不清。","pinyin":"Suīrán xiàngmù huāle liǎng nián, dànshì qíjiān yùdào de kùnnan shǔbuqīng.","vi":"Tuy dự án mất hai năm, nhưng khó khăn gặp phải trong khoảng đó thì kể không xiết."}],"related":[{"hanzi":"期间","pinyin":"qījiān","vi":"trong thời gian"},{"hanzi":"其中","pinyin":"qízhōng","vi":"trong đó"},{"hanzi":"中间","pinyin":"zhōngjiān","vi":"ở giữa"},{"hanzi":"其后","pinyin":"qíhòu","vi":"sau đó"}],"traditional":"其間"},{"id":"奇花异草","hanzi":"奇花异草","pinyin":"qíhuā-yìcǎo","meaning_vi":"kỳ hoa dị thảo, hoa lạ cỏ quý","explanation":"奇 (kỳ – lạ) + 花 (hoa) + 异 (dị – khác thường) + 草 (thảo – cỏ) → hoa lạ cỏ hiếm, những loài cây quý hiếm ít thấy.","hsk_level":"7-9","tags":["thanh-ngu","thien-nhien"],"image":"🌸","examples":[{"type":"basic","zh":"园里种满奇花异草。","pinyin":"Yuán lǐ zhòng mǎn qíhuāyìcǎo.","vi":"Trong vườn trồng đầy hoa lạ cỏ quý."},{"type":"simple","zh":"这座植物园收集了世界各地的奇花异草。","pinyin":"Zhè zuò zhíwùyuán shōujíle shìjiè gèdì de qíhuāyìcǎo.","vi":"Vườn thực vật này sưu tập hoa lạ cỏ quý từ khắp nơi trên thế giới."},{"type":"compound","zh":"因为山谷里气候特殊，所以长满了奇花异草。","pinyin":"Yīnwèi shāngǔ lǐ qìhòu tèshū, suǒyǐ zhǎngmǎnle qíhuāyìcǎo.","vi":"Vì khí hậu trong thung lũng đặc biệt nên mọc đầy kỳ hoa dị thảo."}],"related":[{"hanzi":"花草","pinyin":"huācǎo","vi":"hoa cỏ"},{"hanzi":"珍稀","pinyin":"zhēnxī","vi":"quý hiếm"},{"hanzi":"植物","pinyin":"zhíwù","vi":"thực vật"},{"hanzi":"花园","pinyin":"huāyuán","vi":"vườn hoa"}],"traditional":"奇花異草"},{"id":"祈祷","hanzi":"祈祷","pinyin":"qídǎo","meaning_vi":"cầu nguyện, khấn cầu","explanation":"祈 (kỳ – cầu xin) + 祷 (đảo – khấn) → khấn vái, cầu xin thần linh phù hộ.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🙏","examples":[{"type":"basic","zh":"我为你祈祷。","pinyin":"Wǒ wèi nǐ qídǎo.","vi":"Tôi cầu nguyện cho bạn."},{"type":"simple","zh":"她每天睡觉前都会安静地祈祷一会儿。","pinyin":"Tā měitiān shuìjiào qián dōuhuì ānjìng de qídǎo yíhuìr.","vi":"Mỗi tối trước khi ngủ cô ấy đều lặng lẽ cầu nguyện một lúc."},{"type":"compound","zh":"虽然医生说希望不大，但是家人仍在为他祈祷。","pinyin":"Suīrán yīshēng shuō xīwàng búdà, dànshì jiārén réng zài wèi tā qídǎo.","vi":"Tuy bác sĩ nói hy vọng không nhiều nhưng gia đình vẫn cầu nguyện cho anh ấy."}],"related":[{"hanzi":"祈求","pinyin":"qíqiú","vi":"cầu xin"},{"hanzi":"祷告","pinyin":"dǎogào","vi":"cầu khấn"},{"hanzi":"祝福","pinyin":"zhùfú","vi":"chúc phúc"},{"hanzi":"保佑","pinyin":"bǎoyòu","vi":"phù hộ"}],"traditional":"祈禱"},{"id":"棋","hanzi":"棋","pinyin":"qí","meaning_vi":"cờ (cờ tướng, cờ vây…)","explanation":"棋 (kỳ) gồm 木 (gỗ) + 其 → quân cờ bằng gỗ, môn cờ.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"♟️","examples":[{"type":"basic","zh":"我们下盘棋吧。","pinyin":"Wǒmen xià pán qí ba.","vi":"Chúng ta đánh một ván cờ đi."},{"type":"simple","zh":"公园里有几位老人在树下下棋。","pinyin":"Gōngyuán lǐ yǒu jǐ wèi lǎorén zài shù xià xiàqí.","vi":"Trong công viên có mấy cụ già đang đánh cờ dưới gốc cây."},{"type":"compound","zh":"虽然他刚学下棋，但是已经能赢爸爸了。","pinyin":"Suīrán tā gāng xué xiàqí, dànshì yǐjīng néng yíng bàba le.","vi":"Tuy mới học đánh cờ nhưng cậu bé đã thắng được bố rồi."}],"related":[{"hanzi":"下棋","pinyin":"xiàqí","vi":"đánh cờ"},{"hanzi":"象棋","pinyin":"xiàngqí","vi":"cờ tướng"},{"hanzi":"围棋","pinyin":"wéiqí","vi":"cờ vây"},{"hanzi":"棋盘","pinyin":"qípán","vi":"bàn cờ"}]},{"id":"棋子","hanzi":"棋子","pinyin":"qízǐ","meaning_vi":"quân cờ; con cờ (bị lợi dụng)","explanation":"棋 (kỳ – cờ) + 子 (tử – quân, viên) → quân cờ; nghĩa bóng là người bị kẻ khác lợi dụng như con tốt.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"♟️","examples":[{"type":"basic","zh":"棋子掉在地上了。","pinyin":"Qízǐ diào zài dìshang le.","vi":"Quân cờ rơi xuống đất rồi."},{"type":"simple","zh":"他小心翼翼地把棋子摆回棋盘上。","pinyin":"Tā xiǎoxīnyìyì de bǎ qízǐ bǎi huí qípán shang.","vi":"Anh ấy cẩn thận xếp quân cờ trở lại bàn cờ."},{"type":"compound","zh":"他以为自己是老板，其实只是别人的一颗棋子。","pinyin":"Tā yǐwéi zìjǐ shì lǎobǎn, qíshí zhǐshì biérén de yì kē qízǐ.","vi":"Anh ta tưởng mình là ông chủ, thực ra chỉ là một con cờ của người khác."}],"related":[{"hanzi":"棋盘","pinyin":"qípán","vi":"bàn cờ"},{"hanzi":"下棋","pinyin":"xiàqí","vi":"đánh cờ"},{"hanzi":"卒子","pinyin":"zúzi","vi":"con tốt"},{"hanzi":"木偶","pinyin":"mù'ǒu","vi":"con rối"}]},{"id":"乞求","hanzi":"乞求","pinyin":"qǐqiú","meaning_vi":"van xin, cầu xin","explanation":"乞 (khất – xin) + 求 (cầu – cầu xin) → van nài, xin xỏ một cách hạ mình.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥺","examples":[{"type":"basic","zh":"他乞求原谅。","pinyin":"Tā qǐqiú yuánliàng.","vi":"Anh ta van xin tha thứ."},{"type":"simple","zh":"那个孩子用乞求的眼神看着妈妈。","pinyin":"Nà ge háizi yòng qǐqiú de yǎnshén kànzhe māma.","vi":"Đứa bé nhìn mẹ bằng ánh mắt van nài."},{"type":"compound","zh":"即使生活再难，他也不愿乞求别人的帮助。","pinyin":"Jíshǐ shēnghuó zài nán, tā yě búyuàn qǐqiú biérén de bāngzhù.","vi":"Dù cuộc sống khó khăn đến mấy, anh ấy cũng không muốn van xin người khác giúp đỡ."}],"related":[{"hanzi":"恳求","pinyin":"kěnqiú","vi":"khẩn cầu"},{"hanzi":"哀求","pinyin":"āiqiú","vi":"van nài"},{"hanzi":"乞丐","pinyin":"qǐgài","vi":"ăn mày"},{"hanzi":"请求","pinyin":"qǐngqiú","vi":"yêu cầu"}]},{"id":"起程","hanzi":"起程","pinyin":"qǐchéng","meaning_vi":"khởi hành, lên đường","explanation":"起 (khởi – bắt đầu) + 程 (trình – chặng đường) → bắt đầu chuyến đi, lên đường.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🧳","examples":[{"type":"basic","zh":"我们明天起程。","pinyin":"Wǒmen míngtiān qǐchéng.","vi":"Ngày mai chúng ta lên đường."},{"type":"simple","zh":"代表团一早就起程前往上海了。","pinyin":"Dàibiǎotuán yìzǎo jiù qǐchéng qiánwǎng Shànghǎi le.","vi":"Đoàn đại biểu đã lên đường đi Thượng Hải từ sáng sớm."},{"type":"compound","zh":"如果天气好转，我们就马上起程回国。","pinyin":"Rúguǒ tiānqì hǎozhuǎn, wǒmen jiù mǎshàng qǐchéng huíguó.","vi":"Nếu thời tiết tốt lên, chúng tôi sẽ lập tức lên đường về nước."}],"related":[{"hanzi":"出发","pinyin":"chūfā","vi":"xuất phát"},{"hanzi":"启程","pinyin":"qǐchéng","vi":"khởi hành"},{"hanzi":"动身","pinyin":"dòngshēn","vi":"lên đường"},{"hanzi":"旅程","pinyin":"lǚchéng","vi":"hành trình"}]},{"id":"起劲","hanzi":"起劲","pinyin":"qǐjìn","meaning_vi":"hăng say, hăng hái, nhiệt tình","explanation":"起 (khởi – nổi lên) + 劲 (kình – sức lực) → sức lực dâng lên, làm việc hăng say.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"大家干得很起劲。","pinyin":"Dàjiā gàn de hěn qǐjìn.","vi":"Mọi người làm rất hăng say."},{"type":"simple","zh":"孩子们在雪地里玩得正起劲呢。","pinyin":"Háizimen zài xuědì lǐ wán de zhèng qǐjìn ne.","vi":"Bọn trẻ đang chơi đùa hăng say trên tuyết."},{"type":"compound","zh":"虽然天已经黑了，但是他们还聊得很起劲。","pinyin":"Suīrán tiān yǐjīng hēi le, dànshì tāmen hái liáo de hěn qǐjìn.","vi":"Tuy trời đã tối nhưng họ vẫn trò chuyện rất hăng say."}],"related":[{"hanzi":"带劲","pinyin":"dàijìn","vi":"hăng hái"},{"hanzi":"卖力","pinyin":"màilì","vi":"ra sức"},{"hanzi":"积极","pinyin":"jījí","vi":"tích cực"},{"hanzi":"没劲","pinyin":"méijìn","vi":"chán"}],"traditional":"起勁"},{"id":"起跑线","hanzi":"起跑线","pinyin":"qǐpǎoxiàn","meaning_vi":"vạch xuất phát","explanation":"起跑 (khởi bào – bắt đầu chạy) + 线 (tuyến – vạch) → vạch xuất phát trong đường đua; nghĩa bóng là điểm khởi đầu.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏁","examples":[{"type":"basic","zh":"运动员站在起跑线上。","pinyin":"Yùndòngyuán zhàn zài qǐpǎo xiànshang.","vi":"Các vận động viên đứng ở vạch xuất phát."},{"type":"simple","zh":"很多家长怕孩子输在起跑线上。","pinyin":"Hěn duō jiāzhǎng pà háizi shū zài qǐpǎo xiànshang.","vi":"Nhiều phụ huynh sợ con mình thua ngay từ vạch xuất phát."},{"type":"compound","zh":"虽然大家站在同一条起跑线上，但是结果完全不同。","pinyin":"Suīrán dàjiā zhàn zài tóngyī tiáo qǐpǎo xiànshang, dànshì jiéguǒ wánquán bùtóng.","vi":"Tuy mọi người cùng đứng trên một vạch xuất phát, nhưng kết quả hoàn toàn khác nhau."}],"related":[{"hanzi":"终点线","pinyin":"zhōngdiǎnxiàn","vi":"vạch đích"},{"hanzi":"起点","pinyin":"qǐdiǎn","vi":"điểm xuất phát"},{"hanzi":"赛跑","pinyin":"sàipǎo","vi":"chạy đua"},{"hanzi":"跑道","pinyin":"pǎodào","vi":"đường chạy"}],"traditional":"起跑線"},{"id":"气愤","hanzi":"气愤","pinyin":"qìfèn","meaning_vi":"tức giận, phẫn nộ","explanation":"气 (khí – tức) + 愤 (phẫn – phẫn uất) → tức tối, phẫn nộ vì điều bất công.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😠","examples":[{"type":"basic","zh":"大家都很气愤。","pinyin":"Dàjiā dōu hěn qìfèn.","vi":"Mọi người đều rất phẫn nộ."},{"type":"simple","zh":"看到有人虐待小狗，她非常气愤。","pinyin":"Kàndào yǒurén nüèdài xiǎogǒu, tā fēicháng qìfèn.","vi":"Thấy có người ngược đãi chó con, cô ấy vô cùng tức giận."},{"type":"compound","zh":"因为商家不肯退款，所以顾客气愤地投诉了。","pinyin":"Yīnwèi shāngjiā bùkěn tuìkuǎn, suǒyǐ gùkè qìfèn de tóusù le.","vi":"Vì cửa hàng không chịu hoàn tiền nên khách hàng tức giận khiếu nại."}],"related":[{"hanzi":"愤怒","pinyin":"fènnù","vi":"phẫn nộ"},{"hanzi":"生气","pinyin":"shēngqì","vi":"tức giận"},{"hanzi":"恼火","pinyin":"nǎohuǒ","vi":"bực tức"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình tĩnh"}],"traditional":"氣憤"},{"id":"气管","hanzi":"气管","pinyin":"qìguǎn","meaning_vi":"khí quản, ống thở","explanation":"气 (khí – hơi thở) + 管 (quản – ống) → ống dẫn khí từ họng xuống phổi.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🫁","examples":[{"type":"basic","zh":"他的气管发炎了。","pinyin":"Tā de qìguǎn fāyán le.","vi":"Khí quản của anh ấy bị viêm."},{"type":"simple","zh":"一块鱼骨头差点卡进他的气管。","pinyin":"Yíkuài yú gǔtou chàdiǎn qiǎ jìn tā de qìguǎn.","vi":"Một mẩu xương cá suýt nữa mắc vào khí quản của anh ấy."},{"type":"compound","zh":"因为气管一直不好，所以他冬天很少出门。","pinyin":"Yīnwèi qìguǎn yìzhí bù hǎo, suǒyǐ tā dōngtiān hěn shǎo chūmén.","vi":"Vì khí quản vốn yếu nên mùa đông anh ấy rất ít ra ngoài."}],"related":[{"hanzi":"支气管","pinyin":"zhīqìguǎn","vi":"phế quản"},{"hanzi":"肺","pinyin":"fèi","vi":"phổi"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"},{"hanzi":"喉咙","pinyin":"hóulóng","vi":"cổ họng"}],"traditional":"氣管"},{"id":"气派","hanzi":"气派","pinyin":"qìpài","meaning_vi":"hoành tráng, bề thế, sang trọng; phong thái","explanation":"气 (khí – khí chất) + 派 (phái – phong cách) → phong thái, dáng vẻ bề thế, oai vệ; dùng tả nhà cửa, con người trông sang trọng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"这栋楼真气派！","pinyin":"Zhè dòng lóu zhēn qìpài!","vi":"Tòa nhà này thật bề thế!"},{"type":"simple","zh":"他们公司的大门修得特别气派。","pinyin":"Tāmen gōngsī de dàmén xiū de tèbié qìpài.","vi":"Cổng công ty họ được xây cực kỳ hoành tráng."},{"type":"compound","zh":"虽然婚礼办得很气派，但是新娘看起来并不开心。","pinyin":"Suīrán hūnlǐ bàn de hěn qìpài, dànshì xīnniáng kànqǐlai bìngbù kāixīn.","vi":"Tuy đám cưới tổ chức rất hoành tráng, nhưng cô dâu trông chẳng vui chút nào."}],"related":[{"hanzi":"豪华","pinyin":"háohuá","vi":"xa hoa"},{"hanzi":"壮观","pinyin":"zhuàngguān","vi":"hùng vĩ"},{"hanzi":"派头","pinyin":"pàitóu","vi":"phong thái, dáng vẻ"},{"hanzi":"寒酸","pinyin":"hánsuān","vi":"tồi tàn"}],"traditional":"氣派"},{"id":"气泡","hanzi":"气泡","pinyin":"qìpào","meaning_vi":"bọt khí, bong bóng; có ga","explanation":"气 (khí – hơi) + 泡 (bào – bọt) → bọt khí nổi trong chất lỏng; 气泡水 là nước có ga.","hsk_level":"7-9","tags":["danh-tu"],"image":"🫧","examples":[{"type":"basic","zh":"水里冒出了气泡。","pinyin":"Shuǐ lǐ mào chūle qìpào.","vi":"Trong nước sủi lên bọt khí."},{"type":"simple","zh":"我更喜欢喝不加糖的气泡水。","pinyin":"Wǒ gèng xǐhuan hē bùjiā táng de qìpào shuǐ.","vi":"Tôi thích uống nước có ga không đường hơn."},{"type":"compound","zh":"如果贴膜时留下气泡，就要用卡片慢慢刮出去。","pinyin":"Rúguǒ tiēmó shí liúxià qìpào, jiùyào yòng kǎpiàn mànmàn guā chūqu.","vi":"Nếu khi dán màn hình còn bọt khí thì phải dùng thẻ gạt từ từ ra ngoài."}],"related":[{"hanzi":"泡沫","pinyin":"pàomò","vi":"bọt"},{"hanzi":"肥皂泡","pinyin":"féizàopào","vi":"bong bóng xà phòng"},{"hanzi":"汽水","pinyin":"qìshuǐ","vi":"nước ngọt có ga"},{"hanzi":"冒泡","pinyin":"màopào","vi":"sủi bọt"}],"traditional":"氣泡"},{"id":"恰恰相反","hanzi":"恰恰相反","pinyin":"qiàqiàxiāngfǎn","meaning_vi":"hoàn toàn ngược lại","explanation":"恰恰 (kháp kháp – đúng là, chính là) + 相反 (tương phản – ngược nhau) → sự thật lại đúng là ngược lại; dùng để bác bỏ ý trước.","hsk_level":"7-9","tags":["lien-tu"],"image":"🔁","examples":[{"type":"basic","zh":"事实恰恰相反。","pinyin":"Shìshí qiàqiàxiāngfǎn.","vi":"Sự thật thì hoàn toàn ngược lại."},{"type":"simple","zh":"他不是不爱说话，恰恰相反，他特别健谈。","pinyin":"Tā bú shì bú ài shuōhuà, qiàqiàxiāngfǎn, tā tèbié jiàntán.","vi":"Anh ấy không phải ít nói, ngược lại, anh ấy cực kỳ hoạt ngôn."},{"type":"compound","zh":"很多人以为节食能减肥，但是结果往往恰恰相反。","pinyin":"Hěn duō rén yǐwéi jiéshí néng jiǎnféi, dànshì jiéguǒ wǎngwǎng qiàqiàxiāngfǎn.","vi":"Nhiều người tưởng nhịn ăn có thể giảm cân, nhưng kết quả thường hoàn toàn ngược lại."}],"related":[{"hanzi":"相反","pinyin":"xiāngfǎn","vi":"trái ngược"},{"hanzi":"恰恰","pinyin":"qiàqià","vi":"đúng là, chính là"},{"hanzi":"反而","pinyin":"fǎn'ér","vi":"trái lại"},{"hanzi":"正好相反","pinyin":"zhènghǎoxiāngfǎn","vi":"đúng là ngược lại"}]},{"id":"千钧一发","hanzi":"千钧一发","pinyin":"qiānjūn-yífà","meaning_vi":"nghìn cân treo sợi tóc","explanation":"Nghĩa đen: vật nặng ngàn quân (钧 – quân, đơn vị khoảng 15 kg) treo trên một sợi tóc → nghĩa bóng: tình thế cực kỳ nguy cấp; Hán Việt: thiên quân nhất phát.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚠️","examples":[{"type":"basic","zh":"情况千钧一发。","pinyin":"Qíngkuàng qiānjūnyífà.","vi":"Tình hình nghìn cân treo sợi tóc."},{"type":"simple","zh":"在千钧一发之际，他抓住了孩子的手。","pinyin":"Zài qiānjūnyífà zhījì, tā zhuāzhùle háizi de shǒu.","vi":"Vào giây phút nghìn cân treo sợi tóc, anh ấy đã nắm được tay đứa bé."},{"type":"compound","zh":"就在千钧一发的时候，司机猛踩刹车，所以才没撞上行人。","pinyin":"Jiù zài qiānjūnyífà de shíhou, sījī měng cǎishāchē, suǒyǐ cái méi zhuàngshang xíngrén.","vi":"Đúng lúc nghìn cân treo sợi tóc, tài xế đạp mạnh phanh nên mới không đâm vào người đi bộ."}],"related":[{"hanzi":"危在旦夕","pinyin":"wēizàidànxī","vi":"nguy trong sớm tối"},{"hanzi":"危急","pinyin":"wēijí","vi":"nguy cấp"},{"hanzi":"一发千钧","pinyin":"yífàqiānjūn","vi":"ngàn cân treo sợi tóc"},{"hanzi":"紧急","pinyin":"jǐnjí","vi":"khẩn cấp"}],"traditional":"千鈞一髮"},{"id":"迁","hanzi":"迁","pinyin":"qiān","meaning_vi":"dời, chuyển (chỗ ở), thay đổi","explanation":"迁 (thiên – dời đi) → chuyển từ nơi này sang nơi khác; gặp trong 搬迁, 迁居, 变迁.","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🚚","examples":[{"type":"basic","zh":"他们家迁到南方了。","pinyin":"Tāmen jiā qiān dào nánfāng le.","vi":"Nhà họ đã dời xuống phía Nam rồi."},{"type":"simple","zh":"这家工厂明年要迁出市中心。","pinyin":"Zhè jiā gōngchǎng míngnián yào qiān chū shìzhōngxīn.","vi":"Nhà máy này năm sau sẽ dời ra khỏi trung tâm thành phố."},{"type":"compound","zh":"因为老房子要拆了，所以全村人都得迁走。","pinyin":"Yīnwèi lǎo fángzi yào chāi le, suǒyǐ quán cūn rén dōu děi qiān zǒu.","vi":"Vì nhà cũ sắp bị dỡ nên cả làng đều phải dời đi."}],"related":[{"hanzi":"搬迁","pinyin":"bānqiān","vi":"di dời"},{"hanzi":"迁居","pinyin":"qiānjū","vi":"chuyển nhà"},{"hanzi":"变迁","pinyin":"biànqiān","vi":"biến đổi"},{"hanzi":"移民","pinyin":"yímín","vi":"di cư"}],"traditional":"遷"},{"id":"牵涉","hanzi":"牵涉","pinyin":"qiānshè","meaning_vi":"liên quan, dính líu, liên lụy","explanation":"牵 (khiên – kéo) + 涉 (thiệp – dính vào) → kéo theo, dính dáng đến người hay việc khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"这件事牵涉很多人。","pinyin":"Zhè jiàn shì qiānshè hěn duō rén.","vi":"Việc này dính líu đến rất nhiều người."},{"type":"simple","zh":"这个案子牵涉到两家大公司。","pinyin":"Zhè ge'àn zi qiānshèdào liǎng jiā dàgōngsī.","vi":"Vụ án này liên quan đến hai công ty lớn."},{"type":"compound","zh":"即使问题牵涉到领导，我们也要查清楚。","pinyin":"Jíshǐ wèntí qiānshèdào lǐngdǎo, wǒmen yě yào chá qīngchu.","vi":"Dù vấn đề dính líu đến lãnh đạo, chúng ta cũng phải điều tra rõ ràng."}],"related":[{"hanzi":"涉及","pinyin":"shèjí","vi":"liên quan"},{"hanzi":"牵连","pinyin":"qiānlián","vi":"liên lụy"},{"hanzi":"关联","pinyin":"guānlián","vi":"liên quan"},{"hanzi":"卷入","pinyin":"juǎnrù","vi":"bị cuốn vào"}],"traditional":"牽涉"},{"id":"铅","hanzi":"铅","pinyin":"qiān","meaning_vi":"chì (kim loại)","explanation":"铅 (diên – chì) → kim loại mềm, nặng, màu xám; ruột bút chì gọi là 铅笔 dù thực ra làm bằng than chì.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🔩","examples":[{"type":"basic","zh":"铅对人体有害。","pinyin":"Qiān duì réntǐ yǒuhài.","vi":"Chì có hại cho cơ thể người."},{"type":"simple","zh":"这种玩具的油漆里含有铅。","pinyin":"Zhè zhǒng wánjù de yóuqī lǐ hányǒu qiān.","vi":"Sơn trên loại đồ chơi này có chứa chì."},{"type":"compound","zh":"如果孩子长期接触铅，就可能影响大脑发育。","pinyin":"Rúguǒ háizi chángqī jiēchù qiān, jiù kěnéng yǐngxiǎng dànǎo fāyù.","vi":"Nếu trẻ tiếp xúc với chì lâu dài thì có thể ảnh hưởng đến sự phát triển của não."}],"related":[{"hanzi":"铅笔","pinyin":"qiānbǐ","vi":"bút chì"},{"hanzi":"铅中毒","pinyin":"qiānzhòngdú","vi":"nhiễm độc chì"},{"hanzi":"无铅","pinyin":"wúqiān","vi":"không chì"},{"hanzi":"金属","pinyin":"jīnshǔ","vi":"kim loại"}],"traditional":"鉛"},{"id":"前辈","hanzi":"前辈","pinyin":"qiánbèi","meaning_vi":"tiền bối, bậc đàn anh, người đi trước","explanation":"前 (tiền – trước) + 辈 (bối – thế hệ) → người thuộc lớp trước, có tuổi tác hoặc kinh nghiệm hơn mình.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"他是我的前辈。","pinyin":"Tā shì wǒ de qiánbèi.","vi":"Anh ấy là tiền bối của tôi."},{"type":"simple","zh":"刚进公司时，前辈们教了我很多。","pinyin":"Gāng jìn gōngsī shí, qiánbèimen jiāole wǒ hěn duō.","vi":"Mới vào công ty, các anh chị đi trước đã dạy tôi rất nhiều."},{"type":"compound","zh":"虽然他是行业前辈，但是对新人一点儿架子也没有。","pinyin":"Suīrán tā shì hángyè qiánbèi, dànshì duì xīnrén yìdiǎnr jiàzi yě méiyǒu.","vi":"Tuy là bậc tiền bối trong ngành, nhưng ông ấy chẳng hề ra vẻ với người mới."}],"related":[{"hanzi":"晚辈","pinyin":"wǎnbèi","vi":"hậu bối"},{"hanzi":"长辈","pinyin":"zhǎngbèi","vi":"bề trên"},{"hanzi":"前人","pinyin":"qiánrén","vi":"người đi trước"},{"hanzi":"老前辈","pinyin":"lǎoqiánbèi","vi":"lão tiền bối"}],"traditional":"前輩"},{"id":"前不久","hanzi":"前不久","pinyin":"qiánbùjiǔ","meaning_vi":"cách đây không lâu, mới đây","explanation":"前 (tiền – trước) + 不久 (bất cửu – không lâu) → khoảng thời gian chưa lâu trước hiện tại.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"前不久我见过他。","pinyin":"Qiánbùjiǔ wǒ jiànguo tā.","vi":"Cách đây không lâu tôi đã gặp anh ấy."},{"type":"simple","zh":"前不久这里刚开了一家咖啡馆。","pinyin":"Qiánbùjiǔ zhèlǐ gāng kāile yìjiā kāfēiguǎn.","vi":"Mới đây ở đây vừa mở một quán cà phê."},{"type":"compound","zh":"前不久他还说要出国，可是现在又改主意了。","pinyin":"Qiánbùjiǔ tā hái shuō yào chūguó, kěshì xiànzài yòu gǎi zhǔyi le.","vi":"Mới đây anh ấy còn nói muốn ra nước ngoài, nhưng giờ lại đổi ý rồi."}],"related":[{"hanzi":"不久","pinyin":"bùjiǔ","vi":"không lâu"},{"hanzi":"最近","pinyin":"zuìjìn","vi":"gần đây"},{"hanzi":"近来","pinyin":"jìnlái","vi":"dạo gần đây"},{"hanzi":"前些日子","pinyin":"qiánxiērìzi","vi":"mấy hôm trước"}]},{"id":"前期","hanzi":"前期","pinyin":"qiánqī","meaning_vi":"giai đoạn đầu, thời kỳ trước","explanation":"前 (tiền – trước) + 期 (kỳ – thời kỳ) → giai đoạn đầu của một quá trình hay dự án.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"前期准备很重要。","pinyin":"Qiánqī zhǔnbèi hěn zhòngyào.","vi":"Khâu chuẩn bị giai đoạn đầu rất quan trọng."},{"type":"simple","zh":"这个项目的前期投入非常大。","pinyin":"Zhè ge xiàng mùde qiánqī tóurù fēicháng dà.","vi":"Vốn bỏ ra ở giai đoạn đầu của dự án này rất lớn."},{"type":"compound","zh":"如果前期调查做得不够，后期就会出现很多问题。","pinyin":"Rúguǒ qiánqī diàochá zuò de búgòu, hòuqī jiù huì chūxiàn hěn duō wèntí.","vi":"Nếu khảo sát giai đoạn đầu chưa đủ thì giai đoạn sau sẽ nảy sinh nhiều vấn đề."}],"related":[{"hanzi":"后期","pinyin":"hòuqī","vi":"giai đoạn sau"},{"hanzi":"中期","pinyin":"zhōngqī","vi":"giai đoạn giữa"},{"hanzi":"初期","pinyin":"chūqī","vi":"thời kỳ đầu"},{"hanzi":"早期","pinyin":"zǎoqī","vi":"thời kỳ đầu"}]},{"id":"前任","hanzi":"前任","pinyin":"qiánrèn","meaning_vi":"người tiền nhiệm; cũ (chức vụ); người yêu cũ","explanation":"前 (tiền – trước) + 任 (nhiệm – chức vụ) → người giữ chức trước mình; khẩu ngữ còn chỉ người yêu cũ.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他是前任校长。","pinyin":"Tā shì qiánrèn xiàozhǎng.","vi":"Ông ấy là cựu hiệu trưởng."},{"type":"simple","zh":"新经理改掉了前任定下的规矩。","pinyin":"Xīn jīnglǐ gǎidiàole qiánrèn dìngxià de guīju.","vi":"Giám đốc mới đã bỏ những quy định do người tiền nhiệm đặt ra."},{"type":"compound","zh":"虽然已经分手两年了，但是她偶尔还会想起前任。","pinyin":"Suīrán yǐjīng fēnshǒu liǎng nián le, dànshì tā ǒu'ěr hái huì xiǎngqǐ qiánrèn.","vi":"Tuy đã chia tay hai năm, nhưng thỉnh thoảng cô ấy vẫn nhớ đến người yêu cũ."}],"related":[{"hanzi":"继任","pinyin":"jìrèn","vi":"kế nhiệm"},{"hanzi":"现任","pinyin":"xiànrèn","vi":"đương nhiệm"},{"hanzi":"上任","pinyin":"shàngrèn","vi":"nhậm chức"},{"hanzi":"卸任","pinyin":"xièrèn","vi":"mãn nhiệm"}]},{"id":"前所未有","hanzi":"前所未有","pinyin":"qiánsuǒ-wèiyǒu","meaning_vi":"chưa từng có, chưa từng thấy","explanation":"前 (tiền – trước đây) + 所未有 (sở vị hữu – điều chưa có) → trước nay chưa từng có, vô tiền khoáng hậu.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🆕","examples":[{"type":"basic","zh":"这是前所未有的事。","pinyin":"Zhè shì qiánsuǒwèiyǒu de shì.","vi":"Đây là chuyện chưa từng có."},{"type":"simple","zh":"今年的旅游人数达到了前所未有的高度。","pinyin":"Jīnnián de lǚyóu rénshù dádàole qiánsuǒwèiyǒu de gāodù.","vi":"Lượng khách du lịch năm nay đạt mức cao chưa từng có."},{"type":"compound","zh":"虽然公司面临前所未有的困难，但是员工们都没有放弃。","pinyin":"Suīrán gōngsī miànlín qiánsuǒwèiyǒu de kùnnan, dànshì yuángōngmen dōu méiyǒu fàngqì.","vi":"Tuy công ty đối mặt với khó khăn chưa từng có, nhưng nhân viên đều không bỏ cuộc."}],"related":[{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa từng có trong lịch sử"},{"hanzi":"空前","pinyin":"kōngqián","vi":"chưa từng có"},{"hanzi":"前无古人","pinyin":"qiánwúgǔrén","vi":"xưa nay chưa ai làm"},{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"chuyện thường gặp"}]},{"id":"前台","hanzi":"前台","pinyin":"qiántái","meaning_vi":"quầy lễ tân; sân khấu phía trước","explanation":"前 (tiền – phía trước) + 台 (đài – quầy, bục) → quầy phía trước nơi tiếp khách; nghĩa gốc là phần sân khấu trước mặt khán giả.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🛎️","examples":[{"type":"basic","zh":"请到前台办理入住。","pinyin":"Qǐng dào qiántái bànlǐ rùzhù.","vi":"Mời quý khách đến quầy lễ tân làm thủ tục nhận phòng."},{"type":"simple","zh":"我把房卡忘在前台了。","pinyin":"Wǒ bǎ fángkǎ wàng zài qiántái le.","vi":"Tôi để quên thẻ phòng ở quầy lễ tân rồi."},{"type":"compound","zh":"如果您有任何需要，就可以随时打电话给前台。","pinyin":"Rúguǒ nín yǒu rènhé xūyào, jiù kěyǐ suíshí dǎdiànhuà gěi qiántái.","vi":"Nếu quý khách có bất kỳ nhu cầu gì, có thể gọi điện cho lễ tân bất cứ lúc nào."}],"related":[{"hanzi":"后台","pinyin":"hòutái","vi":"hậu trường"},{"hanzi":"服务台","pinyin":"fúwùtái","vi":"quầy phục vụ"},{"hanzi":"接待","pinyin":"jiēdài","vi":"tiếp đón"},{"hanzi":"大堂","pinyin":"dàtáng","vi":"sảnh"}],"traditional":"前臺"},{"id":"前无古人","hanzi":"前无古人","pinyin":"qiánwú-gǔrén","meaning_vi":"xưa nay chưa ai làm được, chưa có tiền lệ","explanation":"Nghĩa đen: phía trước không có người xưa (tiền vô cổ nhân) → nghĩa bóng: việc chưa ai từng làm, thành tựu chưa có tiền lệ; thường đi với 后无来者.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"这是前无古人的壮举。","pinyin":"Zhè shì qiánwúgǔrén de zhuàngjǔ.","vi":"Đây là kỳ tích xưa nay chưa từng có."},{"type":"simple","zh":"他创造了一个前无古人的纪录。","pinyin":"Tā chuàngzàole yí ge qiánwúgǔrén de jìlù.","vi":"Anh ấy đã lập một kỷ lục chưa ai từng đạt được."},{"type":"compound","zh":"虽然这项工程前无古人，但是工程师们还是成功完成了。","pinyin":"Suīrán zhè xiàng gōngchéng qiánwúgǔrén, dànshì gōngchéngshīmen háishi chénggōng wánchéng le.","vi":"Tuy công trình này chưa có tiền lệ, nhưng các kỹ sư vẫn hoàn thành thành công."}],"related":[{"hanzi":"后无来者","pinyin":"hòuwúláizhě","vi":"sau không ai bằng"},{"hanzi":"前所未有","pinyin":"qiánsuǒwèiyǒu","vi":"chưa từng có"},{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa từng có trong lịch sử"},{"hanzi":"空前绝后","pinyin":"kōngqiánjuéhòu","vi":"vô tiền khoáng hậu"}],"traditional":"前無古人"},{"id":"前夕","hanzi":"前夕","pinyin":"qiánxī","meaning_vi":"đêm trước, thời điểm ngay trước (sự kiện)","explanation":"前 (tiền – trước) + 夕 (tịch – buổi tối) → đêm hôm trước; nghĩa rộng là thời điểm sắp xảy ra sự kiện lớn.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌆","examples":[{"type":"basic","zh":"春节前夕，街上很热闹。","pinyin":"Chūnjié qiánxī, jiēshang hěn rènao.","vi":"Đêm trước Tết, phố xá rất náo nhiệt."},{"type":"simple","zh":"比赛前夕，队员们都早早睡觉了。","pinyin":"Bǐsài qiánxī, duìyuánmen dōu zǎo zǎo shuìjiào le.","vi":"Đêm trước trận đấu, các cầu thủ đều đi ngủ sớm."},{"type":"compound","zh":"就在出发前夕，他突然生病了，所以只好取消旅行。","pinyin":"Jiù zài chūfā qiánxī, tā tūrán shēngbìng le, suǒyǐ zhǐhǎo qǔxiāo lǚxíng.","vi":"Ngay trước hôm khởi hành anh ấy bỗng đổ bệnh, nên đành phải hủy chuyến đi."}],"related":[{"hanzi":"前夜","pinyin":"qiányè","vi":"đêm trước"},{"hanzi":"除夕","pinyin":"Chúxī","vi":"đêm giao thừa"},{"hanzi":"夕阳","pinyin":"xīyáng","vi":"hoàng hôn"},{"hanzi":"临近","pinyin":"línjìn","vi":"sắp đến"}]},{"id":"前线","hanzi":"前线","pinyin":"qiánxiàn","meaning_vi":"tiền tuyến, mặt trận; tuyến đầu","explanation":"前 (tiền – phía trước) + 线 (tuyến – đường, tuyến) → tuyến đầu nơi giao chiến; nghĩa rộng là nơi trực tiếp làm việc khó khăn nhất.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎖️","examples":[{"type":"basic","zh":"他被派到了前线。","pinyin":"Tā bèi pài dàole qiánxiàn.","vi":"Anh ấy được điều ra tiền tuyến."},{"type":"simple","zh":"医生和护士奋战在抗疫前线。","pinyin":"Yīshēng hé hùshi fènzhàn zài kàngyì qiánxiàn.","vi":"Bác sĩ và y tá chiến đấu trên tuyến đầu chống dịch."},{"type":"compound","zh":"虽然前线非常危险，但是记者还是坚持去现场报道。","pinyin":"Suīrán qiánxiàn fēicháng wēixiǎn, dànshì jìzhě háishi jiānchí qù xiànchǎng bàodào.","vi":"Tuy tiền tuyến rất nguy hiểm, nhưng phóng viên vẫn kiên quyết đến hiện trường đưa tin."}],"related":[{"hanzi":"后方","pinyin":"hòufāng","vi":"hậu phương"},{"hanzi":"战线","pinyin":"zhànxiàn","vi":"chiến tuyến"},{"hanzi":"第一线","pinyin":"dìyīxiàn","vi":"tuyến đầu"},{"hanzi":"战场","pinyin":"zhànchǎng","vi":"chiến trường"}],"traditional":"前線"},{"id":"前者","hanzi":"前者","pinyin":"qiánzhě","meaning_vi":"cái trước, người trước (trong hai thứ được nhắc)","explanation":"前 (tiền – trước) + 者 (giả – cái, người) → cái được nhắc đến trước; đối lập với 后者.","hsk_level":"7-9","tags":["dai-tu"],"image":"1️⃣","examples":[{"type":"basic","zh":"我更喜欢前者。","pinyin":"Wǒ gèng xǐhuan qiánzhě.","vi":"Tôi thích cái trước hơn."},{"type":"simple","zh":"在价格和质量之间，他选择了前者。","pinyin":"Zài jiàgé hé zhìliàng zhījiān, tā xuǎnzéle qiánzhě.","vi":"Giữa giá cả và chất lượng, anh ấy chọn cái trước."},{"type":"compound","zh":"前者价格便宜，而后者质量更好，所以很难选择。","pinyin":"Qiánzhě jiàgé piányi, ér hòuzhě zhìliàng gèng hǎo, suǒyǐ hěn nán xuǎnzé.","vi":"Cái trước giá rẻ, còn cái sau chất lượng tốt hơn, nên rất khó chọn."}],"related":[{"hanzi":"后者","pinyin":"hòuzhě","vi":"cái sau"},{"hanzi":"两者","pinyin":"liǎngzhě","vi":"cả hai"},{"hanzi":"前面","pinyin":"qiánmian","vi":"phía trước"},{"hanzi":"或者","pinyin":"huòzhě","vi":"hoặc"}]},{"id":"钱财","hanzi":"钱财","pinyin":"qiáncái","meaning_vi":"tiền của, tiền bạc, của cải","explanation":"钱 (tiền – tiền) + 财 (tài – của cải) → tiền bạc và tài sản nói chung.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"钱财是身外之物。","pinyin":"Qiáncái shì shēn wài zhī wù.","vi":"Tiền tài là vật ngoài thân."},{"type":"simple","zh":"骗子骗走了老人所有的钱财。","pinyin":"Piànzi piànzǒule lǎorén suǒyǒu de qiáncái.","vi":"Kẻ lừa đảo đã lừa lấy hết tiền của của cụ già."},{"type":"compound","zh":"即使拥有再多钱财，也买不到真正的友情。","pinyin":"Jíshǐ yōngyǒu zài duō qiáncái, yě mǎi búdào zhēnzhèng de yǒuqíng.","vi":"Dù có nhiều tiền của đến đâu cũng không mua được tình bạn thật sự."}],"related":[{"hanzi":"财产","pinyin":"cáichǎn","vi":"tài sản"},{"hanzi":"财富","pinyin":"cáifù","vi":"của cải"},{"hanzi":"金钱","pinyin":"jīnqián","vi":"tiền bạc"},{"hanzi":"钱包","pinyin":"qiánbāo","vi":"ví tiền"}],"traditional":"錢財"},{"id":"钳子","hanzi":"钳子","pinyin":"qiánzi","meaning_vi":"cái kìm, kẹp","explanation":"钳 (kiềm – kìm kẹp) + 子 (hậu tố) → dụng cụ hai má kẹp dùng để kẹp, vặn, cắt dây.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔧","examples":[{"type":"basic","zh":"把钳子递给我。","pinyin":"Bǎ qiánzi dìgěi wǒ.","vi":"Đưa cái kìm cho tôi."},{"type":"simple","zh":"他用钳子把墙上的钉子拔了出来。","pinyin":"Tāyòng qiánzi bǎ qiáng shang de dīngzi bále chūlai.","vi":"Anh ấy dùng kìm nhổ cái đinh trên tường ra."},{"type":"compound","zh":"如果没有钳子，就很难剪断这根铁丝。","pinyin":"Rúguǒ méiyǒu qiánzi, jiù hěn nán jiǎnduàn zhè gēn tiěsī.","vi":"Nếu không có kìm thì rất khó cắt đứt sợi dây thép này."}],"related":[{"hanzi":"扳手","pinyin":"bānshou","vi":"cờ lê"},{"hanzi":"螺丝刀","pinyin":"luósīdāo","vi":"tua vít"},{"hanzi":"锤子","pinyin":"chuízi","vi":"búa"},{"hanzi":"工具","pinyin":"gōngjù","vi":"dụng cụ"}],"traditional":"鉗子"},{"id":"潜艇","hanzi":"潜艇","pinyin":"qiántǐng","meaning_vi":"tàu ngầm","explanation":"潜 (tiềm – lặn) + 艇 (đĩnh – thuyền nhỏ) → thuyền có thể lặn sâu dưới nước.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"潜艇潜入了海底。","pinyin":"Qiántǐng qiánrùle hǎidǐ.","vi":"Tàu ngầm đã lặn xuống đáy biển."},{"type":"simple","zh":"这艘核潜艇可以在水下待好几个月。","pinyin":"Zhè sōu héqiántǐng kěyǐ zài shuǐxià dāi hǎojǐ geyuè.","vi":"Chiếc tàu ngầm hạt nhân này có thể ở dưới nước mấy tháng liền."},{"type":"compound","zh":"因为潜艇很难被发现，所以在海战中非常重要。","pinyin":"Yīnwèi qiántǐng hěn nán bèi fāxiàn, suǒyǐ zài hǎizhàn zhōng fēicháng zhòngyào.","vi":"Vì tàu ngầm rất khó bị phát hiện nên nó cực kỳ quan trọng trong hải chiến."}],"related":[{"hanzi":"潜水","pinyin":"qiánshuǐ","vi":"lặn"},{"hanzi":"军舰","pinyin":"jūnjiàn","vi":"tàu chiến"},{"hanzi":"舰艇","pinyin":"jiàntǐng","vi":"tàu thuyền quân sự"},{"hanzi":"潜入","pinyin":"qiánrù","vi":"lặn vào"}],"traditional":"潛艇"},{"id":"潜在","hanzi":"潜在","pinyin":"qiánzài","meaning_vi":"tiềm ẩn, tiềm tàng","explanation":"潜 (tiềm – ẩn sâu) + 在 (tại – tồn tại) → tồn tại ngầm, chưa lộ ra nhưng có thể xuất hiện.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"这有潜在的危险。","pinyin":"Zhè yǒu qiánzài de wēixiǎn.","vi":"Điều này có nguy hiểm tiềm ẩn."},{"type":"simple","zh":"公司正在寻找潜在的客户。","pinyin":"Gōngsī zhèngzài xúnzhǎo qiánzài de kèhù.","vi":"Công ty đang tìm kiếm khách hàng tiềm năng."},{"type":"compound","zh":"虽然现在没出问题，但是这个设计存在潜在的风险。","pinyin":"Suīrán xiànzài méi chūwèntí, dànshì zhè ge shèjì cúnzài qiánzài de fēngxiǎn.","vi":"Tuy hiện chưa có trục trặc, nhưng thiết kế này tồn tại rủi ro tiềm ẩn."}],"related":[{"hanzi":"潜力","pinyin":"qiánlì","vi":"tiềm lực"},{"hanzi":"潜能","pinyin":"qiánnéng","vi":"tiềm năng"},{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"ẩn giấu"},{"hanzi":"明显","pinyin":"míngxiǎn","vi":"rõ ràng"}],"traditional":"潛在"},{"id":"欠条","hanzi":"欠条","pinyin":"qiàntiáo","meaning_vi":"giấy nợ, giấy biên nhận nợ","explanation":"欠 (khiếm – nợ) + 条 (điều – mẩu giấy) → tờ giấy ghi nhận khoản tiền mình còn nợ người khác.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"📝","examples":[{"type":"basic","zh":"他给我写了欠条。","pinyin":"Tā gěi wǒ xiěle qiàntiáo.","vi":"Anh ấy đã viết giấy nợ cho tôi."},{"type":"simple","zh":"借钱给朋友时最好让他打个欠条。","pinyin":"Jièqián gěi péngyou shí zuìhǎo ràng tā dǎ gè qiàntiáo.","vi":"Khi cho bạn vay tiền, tốt nhất nên bảo bạn viết giấy nợ."},{"type":"compound","zh":"如果没有欠条，就很难证明他借过你的钱。","pinyin":"Rúguǒ méiyǒu qiàntiáo, jiù hěn nán zhèngmíng tā jièguo nǐ de qián.","vi":"Nếu không có giấy nợ thì rất khó chứng minh anh ta đã vay tiền của bạn."}],"related":[{"hanzi":"借条","pinyin":"jiètiáo","vi":"giấy vay tiền"},{"hanzi":"收据","pinyin":"shōujù","vi":"biên lai"},{"hanzi":"欠债","pinyin":"qiànzhài","vi":"mắc nợ"},{"hanzi":"还钱","pinyin":"huánqián","vi":"trả tiền"}],"traditional":"欠條"},{"id":"歉意","hanzi":"歉意","pinyin":"qiànyì","meaning_vi":"lời xin lỗi, sự áy náy","explanation":"歉 (khiểm – áy náy) + 意 (ý – ý tứ) → lòng áy náy, ý muốn xin lỗi.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"我向您表示歉意。","pinyin":"Wǒ xiàng nín biǎoshì qiànyì.","vi":"Tôi xin bày tỏ lời xin lỗi với ngài."},{"type":"simple","zh":"航空公司对航班延误深表歉意。","pinyin":"Hángkōng gōngsī duì hángbān yánwù shēn biǎo qiànyì.","vi":"Hãng hàng không vô cùng xin lỗi vì chuyến bay bị chậm."},{"type":"compound","zh":"虽然他嘴上没说，但是眼神里充满了歉意。","pinyin":"Suīrán tā zuǐ shang méi shuō, dànshì yǎnshén lǐ chōngmǎnle qiànyì.","vi":"Tuy ngoài miệng anh ấy không nói, nhưng ánh mắt đầy vẻ áy náy."}],"related":[{"hanzi":"道歉","pinyin":"dàoqiàn","vi":"xin lỗi"},{"hanzi":"抱歉","pinyin":"bàoqiàn","vi":"áy náy"},{"hanzi":"致歉","pinyin":"zhìqiàn","vi":"gửi lời xin lỗi"},{"hanzi":"谢意","pinyin":"xièyì","vi":"lòng cảm ơn"}]},{"id":"呛","hanzi":"呛","pinyin":"qiāng","meaning_vi":"sặc (nước, thức ăn); (qiàng) hăng, cay nồng","explanation":"呛 (sặc) → đồ ăn uống đi nhầm vào khí quản gây ho; đọc qiàng khi chỉ mùi hăng xộc vào mũi.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😵","examples":[{"type":"basic","zh":"慢点喝，别呛着。","pinyin":"Màn diǎn hē, bié qiāng zhe.","vi":"Uống từ từ thôi, kẻo sặc."},{"type":"simple","zh":"他喝水太急，被呛得直咳嗽。","pinyin":"Tā hēshuǐ tài jí, bèi qiāng dezhí késou.","vi":"Anh ấy uống nước vội quá, bị sặc ho sặc sụa."},{"type":"compound","zh":"孩子一边吃饭一边笑，结果被饭粒呛到了。","pinyin":"Háizi yìbiān chīfàn yìbiān xiào, jiéguǒ bèi fànlì qiāngdào le.","vi":"Đứa bé vừa ăn vừa cười, kết quả bị hạt cơm làm sặc."}],"related":[{"hanzi":"咳嗽","pinyin":"késou","vi":"ho"},{"hanzi":"噎","pinyin":"yē","vi":"nghẹn"},{"hanzi":"呛水","pinyin":"qiāngshuǐ","vi":"sặc nước"},{"hanzi":"辣","pinyin":"là","vi":"cay"}],"traditional":"嗆"},{"id":"腔","hanzi":"腔","pinyin":"qiāng","meaning_vi":"khoang (cơ thể); giọng, khẩu âm; điệu hát","explanation":"腔 (xoang – khoang rỗng) → khoang trong cơ thể như 口腔, 胸腔; nghĩa mở rộng là giọng điệu, khẩu âm khi nói.","hsk_level":"7-9","tags":["danh-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"他说话带着山东腔。","pinyin":"Tā shuōhuà dàizhe Shāndōng qiāng.","vi":"Anh ấy nói giọng Sơn Đông."},{"type":"simple","zh":"她在国外住了几年，回来说话有点洋腔。","pinyin":"Tā zài guówài zhùle jǐ nián, huílai shuōhuà yǒudiǎn yáng qiāng.","vi":"Cô ấy sống ở nước ngoài mấy năm, về nước nói chuyện hơi lơ lớ giọng Tây."},{"type":"compound","zh":"虽然他的普通话不太标准，但是这股家乡腔让人觉得很亲切。","pinyin":"Suīrán tā de pǔtōnghuà bú tài biāozhǔn, dànshì zhè gǔ jiāxiāng qiāng ràng rén juéde hěn qīnqiè.","vi":"Tuy tiếng phổ thông của anh ấy không chuẩn lắm, nhưng giọng quê ấy khiến người ta thấy rất thân thiết."}],"related":[{"hanzi":"口腔","pinyin":"kǒuqiāng","vi":"khoang miệng"},{"hanzi":"胸腔","pinyin":"xiōngqiāng","vi":"lồng ngực"},{"hanzi":"口音","pinyin":"kǒuyīn","vi":"khẩu âm"},{"hanzi":"腔调","pinyin":"qiāngdiào","vi":"giọng điệu"}]},{"id":"强加","hanzi":"强加","pinyin":"qiángjiā","meaning_vi":"áp đặt, gán ép","explanation":"强 (cường – ép buộc) + 加 (gia – thêm vào) → dùng sức ép đặt ý kiến hay trách nhiệm lên người khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"☝️","examples":[{"type":"basic","zh":"别把想法强加给别人。","pinyin":"Bié bǎ xiǎngfǎ qiángjiā gěi biérén.","vi":"Đừng áp đặt suy nghĩ lên người khác."},{"type":"simple","zh":"父母不应该把自己的梦想强加给孩子。","pinyin":"Fùmǔ bù yīnggāi bǎ zìjǐ de mèngxiǎng qiángjiā gěi háizi.","vi":"Cha mẹ không nên áp đặt ước mơ của mình lên con cái."},{"type":"compound","zh":"即使你是为他好，也不能把决定强加于他。","pinyin":"Jíshǐ nǐ shì wèi tā hǎo, yě bù néng bǎ juédìng qiángjiā yú tā.","vi":"Dù bạn muốn tốt cho anh ấy, cũng không thể áp đặt quyết định lên anh ấy."}],"related":[{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"ép buộc"},{"hanzi":"强求","pinyin":"qiǎngqiú","vi":"cưỡng cầu"},{"hanzi":"强制","pinyin":"qiángzhì","vi":"cưỡng chế"},{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"tôn trọng"}],"traditional":"強加"},{"id":"强项","hanzi":"强项","pinyin":"qiángxiàng","meaning_vi":"thế mạnh, sở trường","explanation":"强 (cường – mạnh) + 项 (hạng – hạng mục) → hạng mục mình làm giỏi nhất.","hsk_level":"7-9","tags":["danh-tu"],"image":"💪","examples":[{"type":"basic","zh":"数学是他的强项。","pinyin":"Shùxué shì tā de qiángxiàng.","vi":"Toán là thế mạnh của cậu ấy."},{"type":"simple","zh":"跳水一直是中国队的强项。","pinyin":"Tiàoshuǐ yìzhí shì Zhōngguó duì de qiángxiàng.","vi":"Nhảy cầu luôn là thế mạnh của đội Trung Quốc."},{"type":"compound","zh":"虽然唱歌不是我的强项，但是我愿意试一试。","pinyin":"Suīrán chànggē bú shì wǒ de qiángxiàng, dànshì wǒ yuànyì shìyishì.","vi":"Tuy ca hát không phải sở trường của tôi, nhưng tôi sẵn lòng thử."}],"related":[{"hanzi":"弱项","pinyin":"ruòxiàng","vi":"điểm yếu"},{"hanzi":"长处","pinyin":"chángchu","vi":"sở trường"},{"hanzi":"优势","pinyin":"yōushì","vi":"ưu thế"},{"hanzi":"特长","pinyin":"tècháng","vi":"năng khiếu"}],"traditional":"強項"},{"id":"强行","hanzi":"强行","pinyin":"qiángxíng","meaning_vi":"cưỡng ép, làm bằng vũ lực, bất chấp","explanation":"强 (cường – ép) + 行 (hành – làm) → làm bằng sức ép, bất chấp sự phản đối hay điều kiện không cho phép.","hsk_level":"7-9","tags":["pho-tu"],"image":"🚫","examples":[{"type":"basic","zh":"他们强行闯了进来。","pinyin":"Tāmen qiángxíng chuǎngle jìnlai.","vi":"Bọn họ xông bừa vào."},{"type":"simple","zh":"司机强行变道，差点撞上旁边的车。","pinyin":"Sījī qiángxíng biàndào, chàdiǎn zhuàngshang pángbiān de chē.","vi":"Tài xế cố tình chuyển làn ẩu, suýt đâm vào xe bên cạnh."},{"type":"compound","zh":"如果病人不同意，医生就不能强行给他做手术。","pinyin":"Rúguǒ bìngrén bù tóngyì, yī shēngjiù bù néng qiángxíng gěi tā zuò shǒushù.","vi":"Nếu bệnh nhân không đồng ý thì bác sĩ không thể cưỡng ép phẫu thuật cho anh ta."}],"related":[{"hanzi":"强制","pinyin":"qiángzhì","vi":"cưỡng chế"},{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"ép buộc"},{"hanzi":"硬闯","pinyin":"yìngchuǎng","vi":"xông bừa"},{"hanzi":"自愿","pinyin":"zìyuàn","vi":"tự nguyện"}],"traditional":"強行"},{"id":"强硬","hanzi":"强硬","pinyin":"qiángyìng","meaning_vi":"cứng rắn, kiên quyết","explanation":"强 (cường – mạnh) + 硬 (ngạnh – cứng) → thái độ cứng rắn, không nhượng bộ.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🪨","examples":[{"type":"basic","zh":"他的态度很强硬。","pinyin":"Tā de tàidu hěn qiángyìng.","vi":"Thái độ của anh ấy rất cứng rắn."},{"type":"simple","zh":"政府对腐败问题采取了强硬措施。","pinyin":"Zhèngfǔ duì fǔbài wèntí cǎiqǔle qiángyìng cuòshī.","vi":"Chính phủ đã áp dụng biện pháp cứng rắn với vấn đề tham nhũng."},{"type":"compound","zh":"虽然对方语气强硬，但是我们也不能轻易让步。","pinyin":"Suīrán duìfāng yǔqì qiángyìng, dànshì wǒmen yě bù néng qīngyì ràngbù.","vi":"Tuy đối phương giọng điệu cứng rắn, nhưng chúng ta cũng không thể dễ dàng nhượng bộ."}],"related":[{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"mềm yếu"},{"hanzi":"坚决","pinyin":"jiānjué","vi":"kiên quyết"},{"hanzi":"强势","pinyin":"qiángshì","vi":"thế mạnh, áp đảo"},{"hanzi":"让步","pinyin":"ràngbù","vi":"nhượng bộ"}],"traditional":"強硬"},{"id":"强占","hanzi":"强占","pinyin":"qiángzhàn","meaning_vi":"chiếm đoạt bằng vũ lực, cưỡng chiếm","explanation":"强 (cường – ép) + 占 (chiếm – chiếm giữ) → dùng sức mạnh chiếm lấy thứ không thuộc về mình.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🏴","examples":[{"type":"basic","zh":"他强占了别人的土地。","pinyin":"Tā qiángzhànle biérén de tǔdì.","vi":"Hắn đã cưỡng chiếm đất của người khác."},{"type":"simple","zh":"有人强占了我的停车位。","pinyin":"Yǒurén qiángzhànle wǒ de tíngchēwèi.","vi":"Có người đã chiếm chỗ đỗ xe của tôi."},{"type":"compound","zh":"即使他们人多势众，也不能强占村里的公共用地。","pinyin":"Jíshǐ tāmen rén duō shì zhòng, yě bù néng qiángzhàn cūnlǐ de gōng gòngyòng dì.","vi":"Dù họ đông người thế mạnh, cũng không được cưỡng chiếm đất công của làng."}],"related":[{"hanzi":"霸占","pinyin":"bàzhàn","vi":"chiếm đoạt"},{"hanzi":"占领","pinyin":"zhànlǐng","vi":"chiếm lĩnh"},{"hanzi":"侵占","pinyin":"qīnzhàn","vi":"xâm chiếm"},{"hanzi":"占有","pinyin":"zhànyǒu","vi":"chiếm hữu"}],"traditional":"強佔"},{"id":"强制","hanzi":"强制","pinyin":"qiángzhì","meaning_vi":"cưỡng chế, bắt buộc","explanation":"强 (cường – ép) + 制 (chế – khống chế) → dùng quyền lực hoặc pháp luật bắt buộc phải làm.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⛓️","examples":[{"type":"basic","zh":"这是强制规定。","pinyin":"Zhè shì qiángzhì guīdìng.","vi":"Đây là quy định bắt buộc."},{"type":"simple","zh":"法院决定强制执行这项判决。","pinyin":"Fǎyuàn juédìng qiángzhì zhíxíng zhè xiàng pànjué.","vi":"Tòa án quyết định cưỡng chế thi hành bản án này."},{"type":"compound","zh":"如果他再不搬走，政府就会强制拆除这栋房子。","pinyin":"Rúguǒ tā zài bù bānzǒu, zhèngfǔ jiù huì qiángzhì chāichú zhè dòng fángzi.","vi":"Nếu ông ấy vẫn không dọn đi thì chính quyền sẽ cưỡng chế phá dỡ căn nhà này."}],"related":[{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"ép buộc"},{"hanzi":"强行","pinyin":"qiángxíng","vi":"cưỡng ép"},{"hanzi":"义务","pinyin":"yìwù","vi":"nghĩa vụ"},{"hanzi":"自愿","pinyin":"zìyuàn","vi":"tự nguyện"}],"traditional":"強制"},{"id":"抢夺","hanzi":"抢夺","pinyin":"qiǎngduó","meaning_vi":"cướp đoạt, giành giật","explanation":"抢 (thương – cướp) + 夺 (đoạt – giành lấy) → dùng sức giật lấy của người khác; cũng dùng cho tranh giành thị trường, nhân tài.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🦹","examples":[{"type":"basic","zh":"小偷抢夺了她的包。","pinyin":"Xiǎotōu qiǎngduóle tā de bāo.","vi":"Tên trộm đã giật túi của cô ấy."},{"type":"simple","zh":"两家公司正在激烈地抢夺市场。","pinyin":"Liǎng jiā gōngsī zhèngzài jīliè de qiǎngduó shìchǎng.","vi":"Hai công ty đang giành giật thị trường quyết liệt."},{"type":"compound","zh":"因为他当众抢夺别人的手机，所以被警察抓走了。","pinyin":"Yīnwèi tā dāngzhòng qiǎngduó biérén de shǒujī, suǒyǐ bèi jǐngchá zhuāzǒu le.","vi":"Vì giật điện thoại của người khác trước đám đông nên hắn bị cảnh sát bắt đi."}],"related":[{"hanzi":"抢劫","pinyin":"qiǎngjié","vi":"cướp giật"},{"hanzi":"夺取","pinyin":"duóqǔ","vi":"đoạt lấy"},{"hanzi":"争夺","pinyin":"zhēngduó","vi":"tranh giành"},{"hanzi":"掠夺","pinyin":"lüèduó","vi":"cướp bóc"}],"traditional":"搶奪"},{"id":"抢眼","hanzi":"抢眼","pinyin":"qiǎngyǎn","meaning_vi":"bắt mắt, nổi bật, thu hút ánh nhìn","explanation":"抢 (thương – giành) + 眼 (nhãn – mắt) → giành lấy ánh mắt người khác, rất nổi bật.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👀","examples":[{"type":"basic","zh":"这件红裙子很抢眼。","pinyin":"Zhè jiàn hóng qúnzi hěn qiǎngyǎn.","vi":"Chiếc váy đỏ này rất bắt mắt."},{"type":"simple","zh":"这位新人在比赛中表现非常抢眼。","pinyin":"Zhè wèi xīnrén zài bǐsài zhōng biǎoxiàn fēicháng qiǎngyǎn.","vi":"Gương mặt mới này thể hiện rất nổi bật trong trận đấu."},{"type":"compound","zh":"因为广告牌的颜色太抢眼，所以路过的人都会多看几眼。","pinyin":"Yīnwèi guǎnggàopái de yánsè tài qiǎngyǎn, suǒyǐ lùguò de rén dōuhuì duō kàn jǐ yǎn.","vi":"Vì màu bảng quảng cáo quá bắt mắt nên người đi ngang đều nhìn thêm mấy lần."}],"related":[{"hanzi":"醒目","pinyin":"xǐngmù","vi":"nổi bật"},{"hanzi":"显眼","pinyin":"xiǎnyǎn","vi":"dễ thấy"},{"hanzi":"夺目","pinyin":"duómù","vi":"chói lọi"},{"hanzi":"不起眼","pinyin":"bùqǐyǎn","vi":"không gây chú ý"}],"traditional":"搶眼"},{"id":"敲边鼓","hanzi":"敲边鼓","pinyin":"qiāobiāngǔ","meaning_vi":"đánh trống phụ họa, nói vào giúp (ai)","explanation":"Nghĩa đen: gõ vào cạnh trống (xao biên cổ) → nghĩa bóng: đứng bên nói thêm vào để ủng hộ, phụ họa cho người khác.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🥁","examples":[{"type":"basic","zh":"你帮我敲敲边鼓。","pinyin":"Nǐ bāng wǒ qiāo qiaobiāngǔ.","vi":"Cậu nói vào giúp tôi với."},{"type":"simple","zh":"我跟爸爸要钱时，妈妈在一旁敲边鼓。","pinyin":"Wǒ gēn bàba yàoqián shí, māma zài yìpáng qiāobiāngǔ.","vi":"Khi tôi xin tiền bố, mẹ đứng bên nói vào giúp."},{"type":"compound","zh":"如果你在会上替我敲边鼓，老板就更可能同意。","pinyin":"Rúguǒ nǐ zài huì shang tì wǒ qiāobiāngǔ, lǎobǎn jiù gèng kěnéng tóngyì.","vi":"Nếu cậu nói đỡ cho tôi trong cuộc họp thì sếp sẽ dễ đồng ý hơn."}],"related":[{"hanzi":"帮腔","pinyin":"bāngqiāng","vi":"nói đỡ"},{"hanzi":"附和","pinyin":"fùhè","vi":"phụ họa"},{"hanzi":"撑腰","pinyin":"chēngyāo","vi":"chống lưng"},{"hanzi":"打鼓","pinyin":"dǎgǔ","vi":"đánh trống"}],"traditional":"敲邊鼓"},{"id":"敲诈","hanzi":"敲诈","pinyin":"qiāozhà","meaning_vi":"tống tiền, bắt chẹt","explanation":"敲 (xao – gõ, bắt chẹt) + 诈 (trá – lừa dối) → dùng đe dọa hoặc thủ đoạn để moi tiền người khác.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"💸","examples":[{"type":"basic","zh":"他被人敲诈了。","pinyin":"Tā bèi rén qiāozhà le.","vi":"Anh ta bị người ta tống tiền."},{"type":"simple","zh":"那个司机想敲诈外地游客。","pinyin":"Nà ge sījī xiǎng qiāozhà wàidì yóukè.","vi":"Gã tài xế đó muốn bắt chẹt du khách từ nơi khác."},{"type":"compound","zh":"即使对方拿照片威胁你，也不要答应他的敲诈。","pinyin":"Jíshǐ duìfāng ná zhàopiàn wēixié nǐ, yě bú yào dāying tā de qiāozhà.","vi":"Dù đối phương lấy ảnh ra đe dọa, cậu cũng đừng chiều theo trò tống tiền của hắn."}],"related":[{"hanzi":"勒索","pinyin":"lèsuǒ","vi":"tống tiền"},{"hanzi":"欺诈","pinyin":"qīzhà","vi":"lừa đảo"},{"hanzi":"威胁","pinyin":"wēixié","vi":"đe dọa"},{"hanzi":"敲竹杠","pinyin":"qiāozhúgàng","vi":"chặt chém"}],"traditional":"敲詐"},{"id":"乔装","hanzi":"乔装","pinyin":"qiáozhuāng","meaning_vi":"cải trang, giả dạng","explanation":"乔 (kiều – giả) + 装 (trang – hóa trang) → thay đổi trang phục, dáng vẻ để người khác không nhận ra.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥸","examples":[{"type":"basic","zh":"他乔装成了服务员。","pinyin":"Tā qiáozhuāng chéngle fúwùyuán.","vi":"Anh ta cải trang thành nhân viên phục vụ."},{"type":"simple","zh":"警察乔装成乘客混进了火车。","pinyin":"Jǐngchá qiáozhuāng chéng chéngkè hùnjìnle huǒchē.","vi":"Cảnh sát cải trang thành hành khách trà trộn lên tàu hỏa."},{"type":"compound","zh":"虽然他乔装打扮了一番，但是还是被邻居认了出来。","pinyin":"Suīrán tā qiáozhuāng dǎbanle yìfān, dànshì háishi bèi línjū rènle chūlai.","vi":"Tuy anh ta đã cải trang một phen, nhưng vẫn bị hàng xóm nhận ra."}],"related":[{"hanzi":"化装","pinyin":"huàzhuāng","vi":"hóa trang"},{"hanzi":"伪装","pinyin":"wěizhuāng","vi":"ngụy trang"},{"hanzi":"假扮","pinyin":"jiǎbàn","vi":"giả làm"},{"hanzi":"打扮","pinyin":"dǎban","vi":"ăn diện"}],"traditional":"喬裝"},{"id":"瞧不起","hanzi":"瞧不起","pinyin":"qiáobuqǐ","meaning_vi":"coi thường, khinh thường","explanation":"瞧 (tiều – nhìn) + 不起 (không nổi) → nhìn không lọt mắt, coi thường người khác.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙄","examples":[{"type":"basic","zh":"别瞧不起穷人。","pinyin":"Bié qiáobuqǐ qióngrén.","vi":"Đừng coi thường người nghèo."},{"type":"simple","zh":"他总是瞧不起刚来的新同事。","pinyin":"Tā zǒngshì qiáobuqǐ gāng lái de xīn tóngshì.","vi":"Anh ta lúc nào cũng coi thường đồng nghiệp mới đến."},{"type":"compound","zh":"虽然别人瞧不起他，但是他用成绩证明了自己。","pinyin":"Suīrán biérén qiáobuqǐ tā, dànshì tāyòng chéngjì zhèngmíngle zìjǐ.","vi":"Tuy người khác coi thường anh ấy, nhưng anh ấy đã dùng thành tích chứng minh bản thân."}],"related":[{"hanzi":"看不起","pinyin":"kànbuqǐ","vi":"coi thường"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"xem nhẹ"},{"hanzi":"鄙视","pinyin":"bǐshì","vi":"khinh bỉ"},{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"tôn trọng"}]},{"id":"巧合","hanzi":"巧合","pinyin":"qiǎohé","meaning_vi":"trùng hợp, ngẫu nhiên","explanation":"巧 (xảo – khéo, đúng lúc) + 合 (hợp – khớp nhau) → hai sự việc tình cờ khớp nhau.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎲","examples":[{"type":"basic","zh":"这真是太巧合了！","pinyin":"Zhè zhēn shì tài qiǎohé le!","vi":"Thật là quá trùng hợp!"},{"type":"simple","zh":"我们俩同一天生日，纯属巧合。","pinyin":"Wǒmen liǎ tóngyī tiān shēngrì, chúnshǔ qiǎohé.","vi":"Hai chúng tôi sinh cùng ngày, hoàn toàn là trùng hợp."},{"type":"compound","zh":"如果只发生一次是巧合，那么连续三次就不太可能了。","pinyin":"Rúguǒ zhǐ fāshēng yí cì shì qiǎohé, nàme liánxù sāncì jiù bú tài kěnéng le.","vi":"Nếu chỉ xảy ra một lần là trùng hợp, thì ba lần liên tiếp khó mà như vậy."}],"related":[{"hanzi":"碰巧","pinyin":"pèngqiǎo","vi":"tình cờ"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"ngẫu nhiên"},{"hanzi":"凑巧","pinyin":"còuqiǎo","vi":"vừa khéo"},{"hanzi":"恰好","pinyin":"qiàhǎo","vi":"vừa đúng"}]},{"id":"撬","hanzi":"撬","pinyin":"qiào","meaning_vi":"cạy, nạy, bẩy","explanation":"撬 (khiêu – cạy) → dùng vật cứng nhét vào khe rồi bẩy để mở ra hoặc nhấc lên.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔓","examples":[{"type":"basic","zh":"小偷撬开了门锁。","pinyin":"Xiǎotōu qiàokāile ménsuǒ.","vi":"Tên trộm đã cạy khóa cửa."},{"type":"simple","zh":"他用螺丝刀把罐头盖撬开了。","pinyin":"Tāyòng luósīdāo bǎ guàntou gài qiàokāi le.","vi":"Anh ấy dùng tua vít cạy nắp hộp ra."},{"type":"compound","zh":"因为钥匙丢了，所以我们只好请人来撬锁。","pinyin":"Yīnwèi yàoshi diū le, suǒyǐ wǒmen zhǐhǎo qǐng rén lái qiàosuǒ.","vi":"Vì mất chìa khóa nên chúng tôi đành phải gọi người đến phá khóa."}],"related":[{"hanzi":"撬开","pinyin":"qiàokāi","vi":"cạy ra"},{"hanzi":"撬锁","pinyin":"qiàosuǒ","vi":"phá khóa"},{"hanzi":"杠杆","pinyin":"gànggǎn","vi":"đòn bẩy"},{"hanzi":"砸","pinyin":"zá","vi":"đập"}]},{"id":"且","hanzi":"且","pinyin":"qiě","meaning_vi":"và, lại còn; tạm thời; hơn nữa","explanation":"且 (thả – hơn nữa) → nối hai ý tăng tiến (vừa…lại…); còn nghĩa tạm thời như 且慢, 暂且.","hsk_level":"7-9","tags":["lien-tu"],"image":"➕","examples":[{"type":"basic","zh":"他聪明且勤奋。","pinyin":"Tā cōngmíng qiě qínfèn.","vi":"Anh ấy thông minh và lại chăm chỉ."},{"type":"simple","zh":"这家餐厅的菜便宜且好吃。","pinyin":"Zhè jiā cāntīng de cài piányi qiě hǎochī.","vi":"Món ăn ở nhà hàng này vừa rẻ lại ngon."},{"type":"compound","zh":"这条路不但窄，而且坑多，且天黑后没有路灯。","pinyin":"Zhè tiáo lù búdàn zhǎi, érqiě kēng duō, qiě tiānhēi hòu méiyǒu lùdēng.","vi":"Con đường này không những hẹp mà còn nhiều ổ gà, hơn nữa trời tối thì không có đèn đường."}],"related":[{"hanzi":"而且","pinyin":"érqiě","vi":"hơn nữa"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"và"},{"hanzi":"暂且","pinyin":"zànqiě","vi":"tạm thời"},{"hanzi":"况且","pinyin":"kuàngqiě","vi":"huống hồ"}]},{"id":"切除","hanzi":"切除","pinyin":"qiēchú","meaning_vi":"cắt bỏ (bằng phẫu thuật)","explanation":"切 (thiết – cắt) + 除 (trừ – bỏ đi) → cắt bỏ bộ phận bị bệnh khỏi cơ thể.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"医生切除了肿瘤。","pinyin":"Yīshēng qiēchúle zhǒngliú.","vi":"Bác sĩ đã cắt bỏ khối u."},{"type":"simple","zh":"他小时候做过阑尾切除手术。","pinyin":"Tā xiǎoshíhou zuòguo lánwěi qiēchú shǒushù.","vi":"Hồi nhỏ anh ấy từng mổ cắt ruột thừa."},{"type":"compound","zh":"如果肿瘤发现得早，就可以通过手术完全切除。","pinyin":"Rúguǒ zhǒngliú fāxiàn de zǎo, jiù kěyǐ tōngguò shǒushù wánquán qiēchú.","vi":"Nếu khối u được phát hiện sớm thì có thể cắt bỏ hoàn toàn bằng phẫu thuật."}],"related":[{"hanzi":"手术","pinyin":"shǒushù","vi":"phẫu thuật"},{"hanzi":"切掉","pinyin":"qiēdiào","vi":"cắt đi"},{"hanzi":"摘除","pinyin":"zhāichú","vi":"cắt bỏ"},{"hanzi":"肿瘤","pinyin":"zhǒngliú","vi":"khối u"}]},{"id":"切断","hanzi":"切断","pinyin":"qiēduàn","meaning_vi":"cắt đứt, ngắt (nguồn điện, liên lạc...)","explanation":"切 (thiết – cắt) + 断 (đoạn – đứt) → cắt cho đứt hẳn; nghĩa rộng là ngắt nguồn điện, liên lạc, quan hệ.","hsk_level":"7-9","tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"电源被切断了。","pinyin":"Diànyuán bèi qiēduàn le.","vi":"Nguồn điện đã bị cắt."},{"type":"simple","zh":"他切断了和过去朋友的所有联系。","pinyin":"Tā qiēduànle hé guòqù péngyou de suǒyǒu liánxì.","vi":"Anh ấy cắt đứt mọi liên lạc với bạn bè cũ."},{"type":"compound","zh":"维修电路以前，一定要先切断电源，否则会触电。","pinyin":"Wéixiū diànlù yǐqián, yídìngyào xiān qiēduàn diànyuán, fǒuzé huì chùdiàn.","vi":"Trước khi sửa mạch điện nhất định phải ngắt nguồn trước, nếu không sẽ bị điện giật."}],"related":[{"hanzi":"割断","pinyin":"gēduàn","vi":"cắt đứt"},{"hanzi":"中断","pinyin":"zhōngduàn","vi":"gián đoạn"},{"hanzi":"断开","pinyin":"duànkāi","vi":"ngắt ra"},{"hanzi":"连接","pinyin":"liánjiē","vi":"kết nối"}],"traditional":"切斷"},{"id":"切割","hanzi":"切割","pinyin":"qiēgē","meaning_vi":"cắt, cắt gọt (vật liệu)","explanation":"切 (thiết – cắt) + 割 (cát – cắt xẻ) → dùng dao, máy cắt vật liệu thành từng phần.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪚","examples":[{"type":"basic","zh":"工人在切割钢板。","pinyin":"Gōngrén zài qiēgē gāngbǎn.","vi":"Công nhân đang cắt tấm thép."},{"type":"simple","zh":"这台机器能把玻璃切割得非常整齐。","pinyin":"Zhè tái jīqì néng bǎ bōli qiēgē de fēicháng zhěngqí.","vi":"Chiếc máy này có thể cắt kính rất ngay ngắn."},{"type":"compound","zh":"因为钻石非常坚硬，所以切割时需要特殊的工具。","pinyin":"Yīnwèi zuànshí fēicháng jiānyìng, suǒyǐ qiēgē shí xūyào tèshū de gōngjù.","vi":"Vì kim cương cực kỳ cứng nên khi cắt cần dụng cụ đặc biệt."}],"related":[{"hanzi":"切断","pinyin":"qiēduàn","vi":"cắt đứt"},{"hanzi":"分割","pinyin":"fēngē","vi":"phân chia"},{"hanzi":"切开","pinyin":"qiēkāi","vi":"cắt ra"},{"hanzi":"焊接","pinyin":"hànjiē","vi":"hàn"}]},{"id":"窃取","hanzi":"窃取","pinyin":"qièqǔ","meaning_vi":"đánh cắp, ăn cắp (thông tin, bí mật)","explanation":"窃 (thiết – lấy trộm) + 取 (thủ – lấy) → lén lút lấy đi, thường dùng cho thông tin, bí mật, thành quả của người khác.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🕵️","examples":[{"type":"basic","zh":"他窃取了公司机密。","pinyin":"Tā qièqǔle gōngsī jīmì.","vi":"Anh ta đã đánh cắp bí mật của công ty."},{"type":"simple","zh":"黑客试图窃取用户的银行账户信息。","pinyin":"Hēikè shìtú qièqǔ yònghù de yínháng zhànghù xìnxī.","vi":"Tin tặc cố đánh cắp thông tin tài khoản ngân hàng của người dùng."},{"type":"compound","zh":"虽然他窃取了别人的研究成果，但是最终还是被揭穿了。","pinyin":"Suīrán tā qièqǔle biérén de yánjiū chéngguǒ, dànshì zuìzhōng háishì bèi jiēchuān le.","vi":"Tuy anh ta đánh cắp thành quả nghiên cứu của người khác, nhưng cuối cùng vẫn bị vạch trần."}],"related":[{"hanzi":"偷窃","pinyin":"tōuqiè","vi":"ăn trộm"},{"hanzi":"盗取","pinyin":"dàoqǔ","vi":"đánh cắp"},{"hanzi":"窃听","pinyin":"qiètīng","vi":"nghe lén"},{"hanzi":"剽窃","pinyin":"piāoqiè","vi":"đạo văn"}],"traditional":"竊取"},{"id":"亲近","hanzi":"亲近","pinyin":"qīnjìn","meaning_vi":"thân cận, gần gũi, thân thiết","explanation":"亲 (thân – gần gũi) + 近 (cận – gần) → gần gũi, thân thiết; cũng dùng như động từ “gần gũi với ai”.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"孩子很亲近奶奶。","pinyin":"Háizi hěn qīnjìn nǎinai.","vi":"Đứa bé rất gần gũi với bà nội."},{"type":"simple","zh":"这只小狗不太愿意亲近陌生人。","pinyin":"Zhè zhī xiǎogǒu bú tài yuànyì qīnjìn mòshēngrén.","vi":"Con chó nhỏ này không mấy thích gần gũi người lạ."},{"type":"compound","zh":"因为老师总是耐心倾听，所以学生们都愿意亲近她。","pinyin":"Yīnwèi lǎoshī zǒngshì nàixīn qīngtīng, suǒyǐ xuéshēngmen dōu yuànyì qīnjìn tā.","vi":"Vì cô giáo luôn kiên nhẫn lắng nghe nên học sinh đều muốn gần gũi cô."}],"related":[{"hanzi":"亲密","pinyin":"qīnmì","vi":"thân mật"},{"hanzi":"接近","pinyin":"jiējìn","vi":"tiếp cận"},{"hanzi":"疏远","pinyin":"shūyuǎn","vi":"xa lánh"},{"hanzi":"亲切","pinyin":"qīnqiè","vi":"thân thiết, ân cần"}],"traditional":"親近"},{"id":"亲朋好友","hanzi":"亲朋好友","pinyin":"qīnpéng-hǎoyǒu","meaning_vi":"người thân và bạn bè","explanation":"亲 (thân – họ hàng) + 朋 (bằng – bạn) + 好友 (hảo hữu – bạn tốt) → toàn bộ người thân và bạn bè thân thiết.","hsk_level":"7-9","tags":["thanh-ngu","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"他邀请了亲朋好友。","pinyin":"Tā yāoqǐngle qīnpénghǎoyǒu.","vi":"Anh ấy đã mời người thân và bạn bè."},{"type":"simple","zh":"春节时亲朋好友都来家里拜年。","pinyin":"Chūnjié shí qīnpénghǎoyǒu dōu lái jiālǐ bàinián.","vi":"Dịp Tết, người thân bạn bè đều đến nhà chúc Tết."},{"type":"compound","zh":"如果遇到困难，就别忘了向亲朋好友求助。","pinyin":"Rúguǒ yùdào kùnnan, jiù bié wàngle xiàng qīnpénghǎoyǒu qiúzhù.","vi":"Nếu gặp khó khăn thì đừng quên nhờ người thân bạn bè giúp đỡ."}],"related":[{"hanzi":"亲友","pinyin":"qīnyǒu","vi":"người thân bạn bè"},{"hanzi":"亲戚","pinyin":"qīnqi","vi":"họ hàng"},{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"},{"hanzi":"好友","pinyin":"hǎoyǒu","vi":"bạn thân"}],"traditional":"親朋好友"},{"id":"亲情","hanzi":"亲情","pinyin":"qīnqíng","meaning_vi":"tình thân, tình cảm gia đình","explanation":"亲 (thân – người thân) + 情 (tình – tình cảm) → tình cảm giữa những người ruột thịt trong gia đình.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"❤️","examples":[{"type":"basic","zh":"亲情是最珍贵的。","pinyin":"Qīnqíng shì zuì zhēnguì de.","vi":"Tình thân là thứ quý giá nhất."},{"type":"simple","zh":"这部电影讲述了一个关于亲情的故事。","pinyin":"Zhè bù diànyǐng jiǎngshùle yí gè guānyú qīnqíng de gùshi.","vi":"Bộ phim này kể một câu chuyện về tình thân."},{"type":"compound","zh":"即使相隔千里，亲情也不会因此变淡。","pinyin":"Jíshǐ xiānggé qiānlǐ, qīnqíng yě bú huì yīncǐ biàn dàn.","vi":"Dù cách xa nghìn dặm, tình thân cũng không vì thế mà phai nhạt."}],"related":[{"hanzi":"友情","pinyin":"yǒuqíng","vi":"tình bạn"},{"hanzi":"爱情","pinyin":"àiqíng","vi":"tình yêu"},{"hanzi":"亲人","pinyin":"qīnrén","vi":"người thân"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"}],"traditional":"親情"},{"id":"亲生","hanzi":"亲生","pinyin":"qīnshēng","meaning_vi":"ruột, đẻ ra (con ruột, cha mẹ ruột)","explanation":"亲 (thân – ruột thịt) + 生 (sinh – sinh ra) → do chính mình sinh ra, có quan hệ huyết thống; thường đứng trước 父母, 儿子, 女儿.","hsk_level":"7-9","tags":["tinh-tu","gia-dinh"],"image":"👶","examples":[{"type":"basic","zh":"她是我亲生女儿。","pinyin":"Tā shì wǒ qīnshēng nǚ'ér.","vi":"Nó là con gái ruột của tôi."},{"type":"simple","zh":"他长大后终于找到了自己的亲生父母。","pinyin":"Tā zhǎngdà hòu zhōngyú zhǎodàole zìjǐ de qīnshēng fùmǔ.","vi":"Lớn lên anh ấy cuối cùng đã tìm được cha mẹ ruột."},{"type":"compound","zh":"虽然这孩子不是亲生的，但是他们把他当成宝贝。","pinyin":"Suīrán zhè háizi bú shì qīnshēng de, dànshì tāmen bǎ tā dàngchéng bǎobèi.","vi":"Tuy đứa trẻ không phải con ruột nhưng họ coi nó như báu vật."}],"related":[{"hanzi":"亲人","pinyin":"qīnrén","vi":"người thân"},{"hanzi":"领养","pinyin":"lǐngyǎng","vi":"nhận nuôi"},{"hanzi":"养父母","pinyin":"yǎngfùmǔ","vi":"cha mẹ nuôi"},{"hanzi":"骨肉","pinyin":"gǔròu","vi":"ruột thịt"}],"traditional":"親生"},{"id":"亲手","hanzi":"亲手","pinyin":"qīnshǒu","meaning_vi":"tự tay, chính tay","explanation":"亲 (thân – tự mình) + 手 (thủ – tay) → tự tay mình làm, không nhờ người khác.","hsk_level":"7-9","tags":["pho-tu"],"image":"✋","examples":[{"type":"basic","zh":"这是我亲手做的。","pinyin":"Zhè shì wǒ qīnshǒu zuò de.","vi":"Cái này do tôi tự tay làm."},{"type":"simple","zh":"妈妈亲手给我织了一条围巾。","pinyin":"Māma qīnshǒu gěi wǒ zhīle yì tiáo wéijīn.","vi":"Mẹ tự tay đan cho tôi một chiếc khăn quàng."},{"type":"compound","zh":"因为这张卡片是孩子亲手画的，所以她一直珍藏着。","pinyin":"Yīnwèi zhè zhāng kǎpiàn shì háizi qīnshǒu huà de, suǒyǐ tā yìzhí zhēncáng zhe.","vi":"Vì tấm thiệp do con tự tay vẽ nên cô ấy luôn cất giữ cẩn thận."}],"related":[{"hanzi":"亲自","pinyin":"qīnzì","vi":"đích thân"},{"hanzi":"亲眼","pinyin":"qīnyǎn","vi":"tận mắt"},{"hanzi":"动手","pinyin":"dòngshǒu","vi":"bắt tay làm"},{"hanzi":"手工","pinyin":"shǒugōng","vi":"thủ công"}],"traditional":"親手"},{"id":"亲友","hanzi":"亲友","pinyin":"qīnyǒu","meaning_vi":"người thân và bạn bè","explanation":"亲 (thân – họ hàng) + 友 (hữu – bạn) → người thân và bạn bè; cách nói ngắn gọn, hơi trang trọng.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👪","examples":[{"type":"basic","zh":"婚礼来了很多亲友。","pinyin":"Hūnlǐ láile hěn duō qīnyǒu.","vi":"Đám cưới có rất nhiều người thân bạn bè đến dự."},{"type":"simple","zh":"他出国前专门去拜访了几位亲友。","pinyin":"Tā chūguó qián zhuānmén qù bàifǎngle jǐ wèi qīnyǒu.","vi":"Trước khi ra nước ngoài, anh ấy đặc biệt đi thăm vài người thân bạn bè."},{"type":"compound","zh":"一旦家里出了事，亲友们就会主动赶来帮忙。","pinyin":"Yídàn jiālǐ chūleshì, qīnyǒumen jiù huì zhǔdòng gǎnlái bāngmáng.","vi":"Hễ nhà có chuyện, người thân bạn bè sẽ chủ động đến giúp."}],"related":[{"hanzi":"亲朋好友","pinyin":"qīnpénghǎoyǒu","vi":"người thân bạn bè"},{"hanzi":"亲戚","pinyin":"qīnqi","vi":"họ hàng"},{"hanzi":"亲属","pinyin":"qīnshǔ","vi":"thân nhân"},{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"}],"traditional":"親友"},{"id":"侵权","hanzi":"侵权","pinyin":"qīnquán","meaning_vi":"xâm phạm quyền lợi, vi phạm bản quyền","explanation":"侵 (xâm – xâm phạm) + 权 (quyền – quyền lợi) → xâm phạm quyền hợp pháp của người khác, hay gặp trong bản quyền, sở hữu trí tuệ.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"这种做法属于侵权。","pinyin":"Zhè zhǒng zuòfǎ shǔyú qīnquán.","vi":"Cách làm này là hành vi xâm phạm quyền."},{"type":"simple","zh":"那家网站因为侵权被作者告上了法庭。","pinyin":"Nà jiā wǎngzhàn yīnwèi qīnquán bèi zuòzhě gào shàngle fǎtíng.","vi":"Trang web đó bị tác giả kiện ra tòa vì vi phạm bản quyền."},{"type":"compound","zh":"如果未经允许使用别人的照片，就可能构成侵权。","pinyin":"Rúguǒ wèijīng yǔnxǔ shǐyòng biérén de zhàopiàn, jiù kěnéng gòuchéng qīnquán.","vi":"Nếu dùng ảnh của người khác mà không được phép thì có thể cấu thành vi phạm quyền."}],"related":[{"hanzi":"版权","pinyin":"bǎnquán","vi":"bản quyền"},{"hanzi":"侵犯","pinyin":"qīnfàn","vi":"xâm phạm"},{"hanzi":"维权","pinyin":"wéiquán","vi":"bảo vệ quyền lợi"},{"hanzi":"盗版","pinyin":"dàobǎn","vi":"hàng lậu, bản lậu"}],"traditional":"侵權"},{"id":"侵占","hanzi":"侵占","pinyin":"qīnzhàn","meaning_vi":"chiếm đoạt, xâm chiếm","explanation":"侵 (xâm – xâm lấn) + 占 (chiếm – chiếm giữ) → dùng thủ đoạn bất chính chiếm lấy đất đai, tài sản của người khác.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚧","examples":[{"type":"basic","zh":"他侵占了公共财产。","pinyin":"Tā qīnzhànle gōnggòng cáichǎn.","vi":"Hắn đã chiếm đoạt tài sản công."},{"type":"simple","zh":"邻居私自侵占了我家门前的一块空地。","pinyin":"Línjū sīzì qīnzhànle wǒ jiā ménqián de yíkuài kōngdì.","vi":"Hàng xóm tự ý chiếm mảnh đất trống trước cửa nhà tôi."},{"type":"compound","zh":"即使对方势力再大，我们也不能让他们侵占集体的土地。","pinyin":"Jíshǐ duìfāng shìlì zài dà, wǒmen yě bù néng ràng tāmen qīnzhàn jítǐ de tǔdì.","vi":"Dù đối phương thế lực lớn đến mấy, chúng ta cũng không thể để họ chiếm đất của tập thể."}],"related":[{"hanzi":"占领","pinyin":"zhànlǐng","vi":"chiếm lĩnh"},{"hanzi":"侵略","pinyin":"qīnlüè","vi":"xâm lược"},{"hanzi":"霸占","pinyin":"bàzhàn","vi":"chiếm đoạt"},{"hanzi":"侵犯","pinyin":"qīnfàn","vi":"xâm phạm"}],"traditional":"侵佔"},{"id":"勤工俭学","hanzi":"勤工俭学","pinyin":"qíngōng-jiǎnxué","meaning_vi":"vừa học vừa làm","explanation":"勤 (cần – chăm) + 工 (công – làm việc) + 俭 (kiệm – tiết kiệm) + 学 (học) → chăm chỉ làm thêm, sống tiết kiệm để có tiền đi học.","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他靠勤工俭学读完大学。","pinyin":"Tā kào qíngōngjiǎnxué dú wán dàxué.","vi":"Anh ấy vừa học vừa làm để học xong đại học."},{"type":"simple","zh":"学校为贫困学生提供了勤工俭学的岗位。","pinyin":"Xuéxiào wèi pínkùn xuéshēng tígōngle qíngōngjiǎnxué de gǎngwèi.","vi":"Trường cung cấp việc làm thêm cho sinh viên nghèo."},{"type":"compound","zh":"虽然勤工俭学很辛苦，但是她的成绩一直名列前茅。","pinyin":"Suīrán qíngōngjiǎnxué hěn xīnkǔ, dànshì tā de chéngjì yìzhí mínglièqiánmáo.","vi":"Tuy vừa học vừa làm rất vất vả nhưng thành tích của cô ấy luôn đứng đầu."}],"related":[{"hanzi":"打工","pinyin":"dǎgōng","vi":"làm thuê"},{"hanzi":"兼职","pinyin":"jiānzhí","vi":"làm bán thời gian"},{"hanzi":"留学","pinyin":"liúxué","vi":"du học"},{"hanzi":"奖学金","pinyin":"jiǎngxuéjīn","vi":"học bổng"}],"traditional":"勤工儉學"},{"id":"勤快","hanzi":"勤快","pinyin":"qínkuai","meaning_vi":"siêng năng, chăm chỉ, chịu khó","explanation":"勤 (cần – siêng) + 快 (khoái – nhanh nhẹn) → siêng năng, chịu khó làm việc, chân tay nhanh nhẹn; dùng nhiều trong khẩu ngữ.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🧹","examples":[{"type":"basic","zh":"这个小伙子很勤快。","pinyin":"Zhè ge xiǎohuǒzi hěn qínkuai.","vi":"Chàng trai này rất siêng năng."},{"type":"simple","zh":"她每天都勤快地把院子打扫得干干净净。","pinyin":"Tā měitiān dōu qínkuai de bǎ yuànzi dǎsǎo de gān gānjìng jìng.","vi":"Ngày nào cô ấy cũng chăm chỉ quét sân sạch sẽ."},{"type":"compound","zh":"只要你勤快一点，就能把工作提前做完。","pinyin":"Zhǐyào nǐ qínkuai yìdiǎn, jiù néng bǎ gōngzuò tíqián zuòwán.","vi":"Chỉ cần bạn siêng năng một chút là có thể làm xong việc trước thời hạn."}],"related":[{"hanzi":"勤劳","pinyin":"qínláo","vi":"cần cù"},{"hanzi":"勤奋","pinyin":"qínfèn","vi":"chăm chỉ"},{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"},{"hanzi":"能干","pinyin":"nénggàn","vi":"giỏi giang"}]},{"id":"寝室","hanzi":"寝室","pinyin":"qǐnshì","meaning_vi":"phòng ngủ, phòng ký túc xá","explanation":"寝 (tẩm – ngủ) + 室 (thất – phòng) → phòng ngủ; ở trường học Trung Quốc thường chỉ phòng ký túc xá.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🛏️","examples":[{"type":"basic","zh":"我们寝室住四个人。","pinyin":"Wǒmen qǐnshì zhù sì gè rén.","vi":"Phòng ký túc của chúng tôi có bốn người."},{"type":"simple","zh":"晚上十一点以后寝室楼就关门了。","pinyin":"Wǎnshang shí yīdiǎn yǐhòu qǐnshì lóu jiù guānmén le.","vi":"Sau 11 giờ đêm, tòa ký túc xá sẽ đóng cửa."},{"type":"compound","zh":"因为寝室太吵，所以他常常去图书馆学习。","pinyin":"Yīnwèi qǐnshì tài chǎo, suǒyǐ tā chángcháng qù túshūguǎn xuéxí.","vi":"Vì phòng ký túc quá ồn nên anh ấy thường lên thư viện học."}],"related":[{"hanzi":"宿舍","pinyin":"sùshè","vi":"ký túc xá"},{"hanzi":"卧室","pinyin":"wòshì","vi":"phòng ngủ"},{"hanzi":"室友","pinyin":"shìyǒu","vi":"bạn cùng phòng"},{"hanzi":"就寝","pinyin":"jiùqǐn","vi":"đi ngủ"}],"traditional":"寢室"},{"id":"青春期","hanzi":"青春期","pinyin":"qīngchūnqī","meaning_vi":"tuổi dậy thì","explanation":"青春 (thanh xuân – tuổi trẻ) + 期 (kỳ – giai đoạn) → giai đoạn dậy thì, cơ thể và tâm lý thay đổi mạnh.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🧑","examples":[{"type":"basic","zh":"他正处在青春期。","pinyin":"Tā zhèng chǔzài qīngchūnqī.","vi":"Cậu ấy đang ở tuổi dậy thì."},{"type":"simple","zh":"进入青春期的孩子往往比较叛逆。","pinyin":"Jìnrù qīngchūnqī de háizi wǎngwǎng bǐjiào pànnì.","vi":"Trẻ bước vào tuổi dậy thì thường khá nổi loạn."},{"type":"compound","zh":"如果父母多理解孩子，青春期的矛盾就会少很多。","pinyin":"Rúguǒ fùmǔ duō lǐjiě háizi, qīngchūnqī de máodùn jiù huì shǎo hěn duō.","vi":"Nếu cha mẹ hiểu con hơn thì mâu thuẫn tuổi dậy thì sẽ giảm đi nhiều."}],"related":[{"hanzi":"青春","pinyin":"qīngchūn","vi":"thanh xuân"},{"hanzi":"青少年","pinyin":"qīngshàonián","vi":"thanh thiếu niên"},{"hanzi":"发育","pinyin":"fāyù","vi":"phát triển (cơ thể)"},{"hanzi":"叛逆","pinyin":"pànnì","vi":"nổi loạn"}]},{"id":"青蛙","hanzi":"青蛙","pinyin":"qīngwā","meaning_vi":"con ếch","explanation":"青 (thanh – xanh) + 蛙 (oa – ếch) → con ếch xanh, loài lưỡng cư sống gần nước.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐸","examples":[{"type":"basic","zh":"池塘里有青蛙。","pinyin":"Chítáng lǐ yǒu qīngwā.","vi":"Trong ao có ếch."},{"type":"simple","zh":"夏天晚上田里的青蛙叫个不停。","pinyin":"Xiàtiān wǎnshang tián lǐ de qīngwā jiào gè bùtíng.","vi":"Đêm hè ếch ngoài đồng kêu không ngớt."},{"type":"compound","zh":"一旦下起大雨，青蛙就会从草丛里跳出来。","pinyin":"Yídàn xià qǐ dàyǔ, qīngwā jiù huì cóng cǎocóng lǐ tiào chūlái.","vi":"Hễ trời mưa to là ếch lại nhảy ra từ bụi cỏ."}],"related":[{"hanzi":"蝌蚪","pinyin":"kēdǒu","vi":"nòng nọc"},{"hanzi":"蛤蟆","pinyin":"háma","vi":"con cóc"},{"hanzi":"井底之蛙","pinyin":"jǐngdǐzhīwā","vi":"ếch ngồi đáy giếng"},{"hanzi":"池塘","pinyin":"chítáng","vi":"cái ao"}]},{"id":"轻蔑","hanzi":"轻蔑","pinyin":"qīngmiè","meaning_vi":"khinh miệt, coi thường","explanation":"轻 (khinh – xem nhẹ) + 蔑 (miệt – coi rẻ) → coi thường, khinh bỉ người khác; hay đi với 眼光, 态度, 地笑.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"他轻蔑地笑了笑。","pinyin":"Tā qīngmiè de xiàole xiào.","vi":"Anh ta cười khinh miệt."},{"type":"simple","zh":"她用轻蔑的眼光看着那个骗子。","pinyin":"Tā yòng qīngmiè de yǎnguāng kànzhe nà ge piànzi.","vi":"Cô ấy nhìn tên lừa đảo bằng ánh mắt khinh miệt."},{"type":"compound","zh":"虽然别人轻蔑他的出身，但是他从不自卑。","pinyin":"Suīrán biérén qīngmiè tā de chūshēn, dànshì tā cóng bú zìbēi.","vi":"Tuy người khác coi thường xuất thân của anh ấy nhưng anh chưa bao giờ tự ti."}],"related":[{"hanzi":"轻视","pinyin":"qīngshì","vi":"xem nhẹ"},{"hanzi":"蔑视","pinyin":"mièshì","vi":"miệt thị"},{"hanzi":"鄙视","pinyin":"bǐshì","vi":"khinh bỉ"},{"hanzi":"尊重","pinyin":"zūnzhòng","vi":"tôn trọng"}],"traditional":"輕蔑"},{"id":"轻微","hanzi":"轻微","pinyin":"qīngwēi","meaning_vi":"nhẹ, nhỏ, không đáng kể","explanation":"轻 (khinh – nhẹ) + 微 (vi – nhỏ) → mức độ nhẹ, nhỏ; hay dùng cho vết thương, triệu chứng, ảnh hưởng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🤏","examples":[{"type":"basic","zh":"他受了轻微的伤。","pinyin":"Tā shòule qīngwēi de shāng.","vi":"Anh ấy bị thương nhẹ."},{"type":"simple","zh":"昨晚这座城市发生了一次轻微地震。","pinyin":"Zuówǎn zhè zuò chéngshì fāshēngle yí cì qīngwēi dìzhèn.","vi":"Tối qua thành phố này xảy ra một trận động đất nhẹ."},{"type":"compound","zh":"虽然症状很轻微，但是医生还是建议他住院观察。","pinyin":"Suīrán zhèngzhuàng hěn qīngwēi, dànshì yīshēng háishì jiànyì tā zhùyuàn guānchá.","vi":"Tuy triệu chứng rất nhẹ nhưng bác sĩ vẫn khuyên anh ấy nằm viện theo dõi."}],"related":[{"hanzi":"微弱","pinyin":"wēiruò","vi":"yếu ớt"},{"hanzi":"轻度","pinyin":"qīngdù","vi":"mức độ nhẹ"},{"hanzi":"严重","pinyin":"yánzhòng","vi":"nghiêm trọng"},{"hanzi":"细微","pinyin":"xìwēi","vi":"nhỏ nhặt"}],"traditional":"輕微"},{"id":"轻型","hanzi":"轻型","pinyin":"qīngxíng","meaning_vi":"loại nhẹ, hạng nhẹ","explanation":"轻 (khinh – nhẹ) + 型 (hình – kiểu loại) → loại có trọng lượng, quy mô nhỏ; dùng cho máy móc, xe, máy bay.","hsk_level":"7-9","tags":["tinh-tu","giao-thong"],"image":"🛩️","examples":[{"type":"basic","zh":"这是一架轻型飞机。","pinyin":"Zhè shì yí jià qīngxíng fēijī.","vi":"Đây là một chiếc máy bay hạng nhẹ."},{"type":"simple","zh":"这条路只允许轻型货车通过。","pinyin":"Zhè tiáo lù zhǐ yǔnxǔ qīngxíng huòchē tōngguò.","vi":"Con đường này chỉ cho phép xe tải nhẹ đi qua."},{"type":"compound","zh":"因为轻型电动车方便又省钱，所以很多上班族选择它。","pinyin":"Yīnwèi qīngxíng diàndòngchē fāngbiàn yòu shěngqián, suǒyǐ hěn duō shàngbānzú xuǎnzé tā.","vi":"Vì xe điện loại nhẹ tiện lợi lại tiết kiệm nên nhiều người đi làm chọn nó."}],"related":[{"hanzi":"重型","pinyin":"zhòngxíng","vi":"hạng nặng"},{"hanzi":"小型","pinyin":"xiǎoxíng","vi":"cỡ nhỏ"},{"hanzi":"型号","pinyin":"xínghào","vi":"mẫu mã"},{"hanzi":"轻便","pinyin":"qīngbiàn","vi":"gọn nhẹ"}],"traditional":"輕型"},{"id":"倾家荡产","hanzi":"倾家荡产","pinyin":"qīngjiā-dàngchǎn","meaning_vi":"khuynh gia bại sản, mất sạch tài sản","explanation":"倾 (khuynh – đổ hết) + 家 (gia – nhà) + 荡 (đãng – sạch trơn) + 产 (sản – tài sản) → đổ hết cơ nghiệp, mất sạch của cải, thường do cờ bạc hay làm ăn thất bại.","hsk_level":"7-9","tags":["thanh-ngu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"赌博让他倾家荡产。","pinyin":"Dǔbó ràng tā qīngjiādàngchǎn.","vi":"Cờ bạc khiến anh ta khuynh gia bại sản."},{"type":"simple","zh":"那场投资失败几乎使他倾家荡产。","pinyin":"Nà chǎng tóuzī shībài jīhū shǐ tā qīngjiādàngchǎn.","vi":"Thương vụ đầu tư thất bại đó gần như khiến anh ta trắng tay."},{"type":"compound","zh":"即使倾家荡产，他也要治好女儿的病。","pinyin":"Jíshǐ qīngjiādàngchǎn, tā yě yào zhìhǎo nǚ'ér de bìng.","vi":"Dù có phải bán hết gia sản, anh ấy cũng phải chữa khỏi bệnh cho con gái."}],"related":[{"hanzi":"破产","pinyin":"pòchǎn","vi":"phá sản"},{"hanzi":"家产","pinyin":"jiāchǎn","vi":"gia sản"},{"hanzi":"一贫如洗","pinyin":"yìpínrúxǐ","vi":"nghèo rớt mồng tơi"},{"hanzi":"倾尽","pinyin":"qīngjìn","vi":"dốc hết"}],"traditional":"傾家蕩產"},{"id":"清单","hanzi":"清单","pinyin":"qīngdān","meaning_vi":"danh sách, bảng kê","explanation":"清 (thanh – rõ ràng) + 单 (đơn – tờ giấy ghi) → tờ ghi rõ từng hạng mục, danh sách kê khai.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"📋","examples":[{"type":"basic","zh":"我列了一张购物清单。","pinyin":"Wǒ lièle yì zhāng gòuwù qīngdān.","vi":"Tôi đã lập một danh sách mua sắm."},{"type":"simple","zh":"出发前请对照清单检查一下行李。","pinyin":"Chūfā qián qǐng duìzhào qīngdān jiǎnchá yíxià xíngli.","vi":"Trước khi xuất phát, hãy đối chiếu danh sách kiểm tra lại hành lý."},{"type":"compound","zh":"如果没有这份清单，我们就很容易漏掉重要的东西。","pinyin":"Rúguǒ méiyǒu zhè fèn qīngdān, wǒmen jiù hěn róngyì lòudiào zhòngyào de dōngxi.","vi":"Nếu không có danh sách này, chúng ta rất dễ bỏ sót đồ quan trọng."}],"related":[{"hanzi":"名单","pinyin":"míngdān","vi":"danh sách tên"},{"hanzi":"账单","pinyin":"zhàngdān","vi":"hóa đơn"},{"hanzi":"菜单","pinyin":"càidān","vi":"thực đơn"},{"hanzi":"列表","pinyin":"lièbiǎo","vi":"bảng liệt kê"}],"traditional":"清單"},{"id":"清静","hanzi":"清静","pinyin":"qīngjìng","meaning_vi":"yên tĩnh, thanh tịnh","explanation":"清 (thanh – trong, sạch) + 静 (tĩnh – yên) → yên tĩnh, không bị ồn ào quấy rầy.","hsk_level":"7-9","tags":["tinh-tu","dia-diem"],"image":"🍃","examples":[{"type":"basic","zh":"山里的生活很清静。","pinyin":"Shān lǐ de shēnghuó hěn qīngjìng.","vi":"Cuộc sống trên núi rất yên tĩnh."},{"type":"simple","zh":"他想找个清静的地方好好看书。","pinyin":"Tā xiǎng zhǎo gè qīngjìng de dìfang hǎohǎo kànshū.","vi":"Anh ấy muốn tìm một chỗ yên tĩnh để đọc sách cho tử tế."},{"type":"compound","zh":"虽然郊区交通不方便，但是那里比市中心清静得多。","pinyin":"Suīrán jiāoqū jiāotōng bù fāngbiàn, dànshì nàlǐ bǐ shìzhōngxīn qīngjìng de duō.","vi":"Tuy ngoại ô đi lại không tiện nhưng ở đó yên tĩnh hơn trung tâm nhiều."}],"related":[{"hanzi":"安静","pinyin":"ānjìng","vi":"yên tĩnh"},{"hanzi":"宁静","pinyin":"níngjìng","vi":"tĩnh lặng"},{"hanzi":"清闲","pinyin":"qīngxián","vi":"nhàn rỗi"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"}],"traditional":"清靜"},{"id":"清明","hanzi":"清明","pinyin":"qīngmíng","meaning_vi":"tiết Thanh Minh, Tết Thanh Minh; trong sáng, minh bạch","explanation":"清 (thanh – trong) + 明 (minh – sáng) → trong sáng; còn là tiết khí thứ 5 và Tết Thanh Minh đi tảo mộ vào đầu tháng 4.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🌿","examples":[{"type":"basic","zh":"清明节要去扫墓。","pinyin":"Qīngmíngjié yào qù sǎomù.","vi":"Tết Thanh Minh phải đi tảo mộ."},{"type":"simple","zh":"清明前后江南常常下着蒙蒙细雨。","pinyin":"Qīngmíng qiánhòu Jiāngnán chángcháng xiàzhe méngméng xìyǔ.","vi":"Quanh tiết Thanh Minh, Giang Nam thường có mưa phùn lất phất."},{"type":"compound","zh":"每年清明一到，他就会回老家给祖父母扫墓。","pinyin":"Měinián qīngmíng yí dào, tā jiù huì huílǎojiā gěi zǔfùmǔ sǎomù.","vi":"Mỗi năm cứ đến Thanh Minh, anh ấy lại về quê tảo mộ ông bà."}],"related":[{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"},{"hanzi":"节气","pinyin":"jiéqì","vi":"tiết khí"},{"hanzi":"清明节","pinyin":"Qīngmíngjié","vi":"Tết Thanh Minh"},{"hanzi":"端午","pinyin":"Duānwǔ","vi":"Tết Đoan Ngọ"}]},{"id":"清新","hanzi":"清新","pinyin":"qīngxīn","meaning_vi":"trong lành, tươi mát","explanation":"清 (thanh – trong) + 新 (tân – mới) → trong lành, tươi mới; dùng cho không khí, phong cách.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"雨后空气很清新。","pinyin":"Yǔ hòu kōngqì hěn qīngxīn.","vi":"Sau mưa không khí rất trong lành."},{"type":"simple","zh":"这家咖啡馆的装修风格十分清新。","pinyin":"Zhè jiā kāfēiguǎn de zhuāngxiū fēnggé shífēn qīngxīn.","vi":"Phong cách trang trí của quán cà phê này rất tươi mát."},{"type":"compound","zh":"一打开窗户，清新的空气就扑面而来。","pinyin":"Yì dǎkāi chuānghu, qīngxīn de kōngqì jiù pūmiàn'érlái.","vi":"Vừa mở cửa sổ, không khí trong lành đã ùa vào mặt."}],"related":[{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"tươi"},{"hanzi":"清爽","pinyin":"qīngshuǎng","vi":"mát mẻ, dễ chịu"},{"hanzi":"清澈","pinyin":"qīngchè","vi":"trong vắt"},{"hanzi":"污浊","pinyin":"wūzhuó","vi":"ô uế, vẩn đục"}]},{"id":"清真寺","hanzi":"清真寺","pinyin":"qīngzhēnsì","meaning_vi":"nhà thờ Hồi giáo","explanation":"清真 (thanh chân – Hồi giáo, halal) + 寺 (tự – nơi thờ) → nơi thờ phụng của người Hồi giáo.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🕌","examples":[{"type":"basic","zh":"那座清真寺很古老。","pinyin":"Nà zuò qīngzhēnsì hěn gǔlǎo.","vi":"Nhà thờ Hồi giáo đó rất cổ."},{"type":"simple","zh":"每周五很多穆斯林去清真寺做礼拜。","pinyin":"Měi Zhōuwǔ hěn duō Mùsīlín qù qīngzhēnsì zuòlǐbài.","vi":"Mỗi thứ Sáu, nhiều người Hồi giáo đến nhà thờ để cầu nguyện."},{"type":"compound","zh":"如果你参观清真寺，就要注意穿着得体。","pinyin":"Rúguǒ nǐ cānguān qīngzhēnsì, jiùyào zhùyì chuānzhuó détǐ.","vi":"Nếu bạn tham quan nhà thờ Hồi giáo thì phải chú ý ăn mặc lịch sự."}],"related":[{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"教堂","pinyin":"jiàotáng","vi":"nhà thờ"},{"hanzi":"伊斯兰教","pinyin":"Yīsīlánjiào","vi":"đạo Hồi"},{"hanzi":"清真","pinyin":"qīngzhēn","vi":"halal, Hồi giáo"}]},{"id":"情","hanzi":"情","pinyin":"qíng","meaning_vi":"tình, tình cảm; tình hình","explanation":"情 (tình) → tình cảm, cảm xúc giữa người với người; cũng chỉ tình hình, tình trạng (như 病情, 实情).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💞","examples":[{"type":"basic","zh":"这份情我永远记得。","pinyin":"Zhè fèn qíng wǒ yǒngyuǎn jìde.","vi":"Ân tình này tôi mãi ghi nhớ."},{"type":"simple","zh":"战友之间的那份情是用生命换来的。","pinyin":"Zhànyǒu zhījiān de nà fèn qíng shì yòng shēngmìng huàn lái de.","vi":"Tình đồng đội ấy được đổi bằng cả mạng sống."},{"type":"compound","zh":"虽然分开多年，但是两人之间的情始终没有变。","pinyin":"Suīrán fēnkāi duōnián, dànshì liǎng rén zhījiān de qíng shǐzhōng méiyǒu biàn.","vi":"Tuy xa nhau nhiều năm nhưng tình cảm giữa hai người vẫn không đổi."}],"related":[{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"tình hình"},{"hanzi":"爱情","pinyin":"àiqíng","vi":"tình yêu"},{"hanzi":"情感","pinyin":"qínggǎn","vi":"cảm xúc"}]},{"id":"情调","hanzi":"情调","pinyin":"qíngdiào","meaning_vi":"không khí, phong vị, sắc thái (lãng mạn)","explanation":"情 (tình – cảm xúc) + 调 (điệu – giọng điệu) → không khí, sắc thái cảm xúc của một nơi hay tác phẩm; 有情调 nghĩa là lãng mạn, có gu.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🕯️","examples":[{"type":"basic","zh":"这家餐厅很有情调。","pinyin":"Zhè jiā cāntīng hěn yǒu qíngdiào.","vi":"Nhà hàng này rất lãng mạn."},{"type":"simple","zh":"烛光晚餐给约会增添了浪漫的情调。","pinyin":"Zhúguāng wǎncān gěi yuēhuì zēngtiānle làngmàn de qíngdiào.","vi":"Bữa tối dưới nến tạo thêm không khí lãng mạn cho buổi hẹn."},{"type":"compound","zh":"虽然房子不大，但是她布置得很有情调。","pinyin":"Suīrán fángzi búdà, dànshì tā bùzhì de hěn yǒu qíngdiào.","vi":"Tuy nhà không lớn nhưng cô ấy bài trí rất có gu."}],"related":[{"hanzi":"格调","pinyin":"gédiào","vi":"phong cách"},{"hanzi":"浪漫","pinyin":"làngmàn","vi":"lãng mạn"},{"hanzi":"氛围","pinyin":"fēnwéi","vi":"bầu không khí"},{"hanzi":"情趣","pinyin":"qíngqù","vi":"thú vị, tình thú"}],"traditional":"情調"},{"id":"情结","hanzi":"情结","pinyin":"qíngjié","meaning_vi":"nỗi niềm, mặc cảm, phức cảm","explanation":"情 (tình – tình cảm) + 结 (kết – nút thắt) → nút thắt tình cảm sâu kín trong lòng; trong tâm lý học là “phức cảm”, cũng chỉ sự gắn bó khó dứt.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🧠","examples":[{"type":"basic","zh":"他有很深的故乡情结。","pinyin":"Tā yǒu hěn shēn de gùxiāng qíngjié.","vi":"Anh ấy mang nặng nỗi niềm quê hương."},{"type":"simple","zh":"很多老人对黑白电影有一种特殊的情结。","pinyin":"Hěn duō lǎorén duì hēibái diànyǐng yǒu yì zhǒng tèshū de qíngjié.","vi":"Nhiều người già có một tình cảm đặc biệt với phim đen trắng."},{"type":"compound","zh":"因为小时候家里穷，所以他心里一直有自卑情结。","pinyin":"Yīnwèi xiǎoshíhou jiālǐ qióng, suǒyǐ tā xīnlǐ yìzhí yǒu zìbēi qíngjié.","vi":"Vì hồi nhỏ nhà nghèo nên trong lòng anh ấy luôn có mặc cảm tự ti."}],"related":[{"hanzi":"心结","pinyin":"xīnjié","vi":"khúc mắc trong lòng"},{"hanzi":"情感","pinyin":"qínggǎn","vi":"tình cảm"},{"hanzi":"情怀","pinyin":"qínghuái","vi":"tâm tình"},{"hanzi":"自卑","pinyin":"zìbēi","vi":"tự ti"}],"traditional":"情結"},{"id":"情侣","hanzi":"情侣","pinyin":"qínglǚ","meaning_vi":"cặp tình nhân, đôi yêu nhau","explanation":"情 (tình – tình yêu) + 侣 (lữ – bạn đồng hành) → đôi bạn đồng hành trong tình yêu, cặp người yêu.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"💑","examples":[{"type":"basic","zh":"公园里有很多情侣。","pinyin":"Gōngyuán lǐ yǒu hěn duō qínglǚ.","vi":"Trong công viên có rất nhiều cặp đôi."},{"type":"simple","zh":"这对情侣决定明年春天举行婚礼。","pinyin":"Zhè duì qínglǚ juédìng míngnián chūntiān jǔxíng hūnlǐ.","vi":"Cặp đôi này quyết định tổ chức đám cưới vào mùa xuân năm sau."},{"type":"compound","zh":"每到情人节，这家花店就会挤满了买花的情侣。","pinyin":"Měi dào Qíngrénjié, zhè jiā huādiàn jiù huì jǐmǎnle mǎi huā de qínglǚ.","vi":"Cứ đến ngày lễ tình nhân, tiệm hoa này lại chật kín các cặp đôi mua hoa."}],"related":[{"hanzi":"恋人","pinyin":"liànrén","vi":"người yêu"},{"hanzi":"情人","pinyin":"qíngrén","vi":"người tình"},{"hanzi":"伴侣","pinyin":"bànlǚ","vi":"bạn đời"},{"hanzi":"情侣装","pinyin":"qínglǚzhuāng","vi":"đồ đôi"}],"traditional":"情侶"},{"id":"情人","hanzi":"情人","pinyin":"qíngrén","meaning_vi":"người yêu, người tình","explanation":"情 (tình – tình yêu) + 人 (nhân – người) → người mình yêu; lưu ý trong tiếng Trung hiện đại đôi khi mang nghĩa “nhân tình ngoài hôn nhân”.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"💘","examples":[{"type":"basic","zh":"今天是情人节。","pinyin":"Jīntiān shì Qíngrénjié.","vi":"Hôm nay là ngày lễ tình nhân."},{"type":"simple","zh":"他给情人写了一封很长的情书。","pinyin":"Tā gěi qíngrén xiěle yì fēng hěn cháng de qíngshū.","vi":"Anh ấy viết cho người yêu một bức thư tình rất dài."},{"type":"compound","zh":"俗话说“情人眼里出西施”，所以他觉得女朋友什么都好。","pinyin":"Súhuàshuō \"qíngrén yǎn lǐ chū Xīshī\", suǒyǐ tā juéde nǚpéngyou shénme dōu hǎo.","vi":"Tục ngữ nói “trong mắt người tình hóa Tây Thi”, nên anh ấy thấy bạn gái cái gì cũng tốt."}],"related":[{"hanzi":"恋人","pinyin":"liànrén","vi":"người yêu"},{"hanzi":"情侣","pinyin":"qínglǚ","vi":"cặp đôi"},{"hanzi":"情人节","pinyin":"Qíngrénjié","vi":"lễ tình nhân"},{"hanzi":"爱人","pinyin":"àirén","vi":"vợ/chồng"}]},{"id":"情愿","hanzi":"情愿","pinyin":"qíngyuàn","meaning_vi":"cam lòng, tự nguyện; thà rằng","explanation":"情 (tình – lòng) + 愿 (nguyện – mong muốn) → trong lòng cam tâm tình nguyện; còn dùng theo mẫu 情愿…也不… nghĩa “thà… chứ không…”.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙏","examples":[{"type":"basic","zh":"这是我心甘情愿的。","pinyin":"Zhè shì wǒ xīngānqíngyuàn de.","vi":"Đây là điều tôi cam tâm tình nguyện."},{"type":"simple","zh":"他情愿自己吃亏也不愿麻烦别人。","pinyin":"Tā qíngyuàn zìjǐ chīkuī yě búyuàn máfan biérén.","vi":"Anh ấy thà mình chịu thiệt chứ không muốn làm phiền người khác."},{"type":"compound","zh":"即使工资低一点，我也情愿做自己喜欢的工作。","pinyin":"Jíshǐ gōngzī dī yìdiǎn, wǒ yě qíngyuàn zuòzìjǐ xǐhuan de gōngzuò.","vi":"Dù lương thấp hơn một chút, tôi vẫn cam lòng làm công việc mình thích."}],"related":[{"hanzi":"愿意","pinyin":"yuànyì","vi":"bằng lòng"},{"hanzi":"宁愿","pinyin":"nìngyuàn","vi":"thà"},{"hanzi":"甘心","pinyin":"gānxīn","vi":"cam lòng"},{"hanzi":"自愿","pinyin":"zìyuàn","vi":"tự nguyện"}],"traditional":"情願"},{"id":"囚犯","hanzi":"囚犯","pinyin":"qiúfàn","meaning_vi":"tù nhân, phạm nhân","explanation":"囚 (tù – giam giữ) + 犯 (phạm – kẻ phạm tội) → người phạm tội đang bị giam trong tù.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"⛓️","examples":[{"type":"basic","zh":"囚犯逃出了监狱。","pinyin":"Qiúfàn táo chūle jiānyù.","vi":"Tù nhân đã trốn khỏi nhà tù."},{"type":"simple","zh":"监狱每天安排囚犯参加劳动和学习。","pinyin":"Jiānyù měitiān ānpái qiúfàn cānjiā láodòng hé xuéxí.","vi":"Nhà tù mỗi ngày sắp xếp cho phạm nhân lao động và học tập."},{"type":"compound","zh":"如果囚犯表现良好，就有机会获得减刑。","pinyin":"Rúguǒ qiúfàn biǎoxiàn liánghǎo, jiù yǒujī huì huòdé jiǎnxíng.","vi":"Nếu phạm nhân cải tạo tốt thì có cơ hội được giảm án."}],"related":[{"hanzi":"犯人","pinyin":"fànrén","vi":"phạm nhân"},{"hanzi":"监狱","pinyin":"jiānyù","vi":"nhà tù"},{"hanzi":"罪犯","pinyin":"zuìfàn","vi":"tội phạm"},{"hanzi":"囚禁","pinyin":"qiújìn","vi":"giam cầm"}]},{"id":"求婚","hanzi":"求婚","pinyin":"qiúhūn","meaning_vi":"cầu hôn","explanation":"求 (cầu – xin) + 婚 (hôn – hôn nhân) → ngỏ lời xin cưới, cầu hôn.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"💍","examples":[{"type":"basic","zh":"他向女友求婚了。","pinyin":"Tā xiàng nǚyǒu qiúhūn le.","vi":"Anh ấy đã cầu hôn bạn gái."},{"type":"simple","zh":"他在海边准备了一场浪漫的求婚。","pinyin":"Tā zài hǎibiān zhǔnbèile yì chǎng làngmàn de qiúhūn.","vi":"Anh ấy chuẩn bị một màn cầu hôn lãng mạn bên bờ biển."},{"type":"compound","zh":"虽然他求婚时紧张得说不出话，但是她还是笑着答应了。","pinyin":"Suīrán tā qiúhūn shí jǐnzhāng de shuōbùchū huà, dànshì tā háishì xiàozhe dāying le.","vi":"Tuy lúc cầu hôn anh ấy run đến nói không nên lời, nhưng cô ấy vẫn mỉm cười nhận lời."}],"related":[{"hanzi":"结婚","pinyin":"jiéhūn","vi":"kết hôn"},{"hanzi":"订婚","pinyin":"dìnghūn","vi":"đính hôn"},{"hanzi":"婚礼","pinyin":"hūnlǐ","vi":"đám cưới"},{"hanzi":"戒指","pinyin":"jièzhi","vi":"nhẫn"}]},{"id":"求救","hanzi":"求救","pinyin":"qiújiù","meaning_vi":"cầu cứu, kêu cứu","explanation":"求 (cầu – xin) + 救 (cứu – cứu giúp) → xin người khác cứu giúp khi gặp nguy hiểm hoặc khó khăn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🆘","examples":[{"type":"basic","zh":"他大声喊着求救。","pinyin":"Tā dàshēng hǎnzhe qiújiù.","vi":"Anh ấy hét to kêu cứu."},{"type":"simple","zh":"被困的登山者用手机发出了求救信号。","pinyin":"Bèi kùn de dēngshān zhě yòng shǒujī fāchūle qiújiù xìnhào.","vi":"Người leo núi bị mắc kẹt đã dùng điện thoại phát tín hiệu cầu cứu."},{"type":"compound","zh":"一旦在海上遇到危险，就要立刻向附近的船只求救。","pinyin":"Yídàn zài hǎishàng yùdào wēixiǎn, jiùyào lìkè xiàng fùjìn de chuánzhī qiújiù.","vi":"Một khi gặp nguy hiểm trên biển thì phải lập tức cầu cứu các tàu gần đó."}],"related":[{"hanzi":"救命","pinyin":"jiùmìng","vi":"cứu mạng"},{"hanzi":"求助","pinyin":"qiúzhù","vi":"nhờ giúp đỡ"},{"hanzi":"呼救","pinyin":"hūjiù","vi":"kêu cứu"},{"hanzi":"救援","pinyin":"jiùyuán","vi":"cứu hộ"}]},{"id":"求学","hanzi":"求学","pinyin":"qiúxué","meaning_vi":"đi học, theo đuổi việc học","explanation":"求 (cầu – tìm kiếm) + 学 (học) → đi tìm tri thức, đi học (thường là xa nhà).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"他去北京求学了。","pinyin":"Tā qù Běijīng qiúxué le.","vi":"Anh ấy đã lên Bắc Kinh học."},{"type":"simple","zh":"她十八岁就离开家乡到国外求学。","pinyin":"Tā shíbā suì jiù líkāi jiāxiāng dào guówài qiúxué.","vi":"Mười tám tuổi cô ấy đã rời quê ra nước ngoài học."},{"type":"compound","zh":"虽然求学之路很艰难，但是他从来没想过放弃。","pinyin":"Suīrán qiúxué zhī lù hěn jiānnán, dànshì tā cónglái méi xiǎngguo fàngqì.","vi":"Tuy con đường học vấn rất gian nan nhưng anh ấy chưa từng nghĩ đến bỏ cuộc."}],"related":[{"hanzi":"留学","pinyin":"liúxué","vi":"du học"},{"hanzi":"上学","pinyin":"shàngxué","vi":"đi học"},{"hanzi":"求知","pinyin":"qiúzhī","vi":"tìm tòi tri thức"},{"hanzi":"学业","pinyin":"xuéyè","vi":"việc học"}],"traditional":"求學"},{"id":"求医","hanzi":"求医","pinyin":"qiúyī","meaning_vi":"đi chữa bệnh, tìm thầy chữa bệnh","explanation":"求 (cầu – tìm) + 医 (y – thầy thuốc) → đi tìm bác sĩ, tìm nơi chữa bệnh.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他四处求医。","pinyin":"Tā sìchù qiúyī.","vi":"Anh ấy đi khắp nơi tìm thầy chữa bệnh."},{"type":"simple","zh":"他们带着孩子专程到上海求医。","pinyin":"Tāmen dàizhe háizi zhuānchéng dào Shànghǎi qiúyī.","vi":"Họ đưa con đến tận Thượng Hải để chữa bệnh."},{"type":"compound","zh":"如果身体出现异常，就应该及时求医，不要拖延。","pinyin":"Rúguǒ shēntǐ chūxiàn yìcháng, jiù yīnggāi jíshí qiúyī, bú yào tuōyán.","vi":"Nếu cơ thể có dấu hiệu bất thường thì nên đi khám kịp thời, đừng trì hoãn."}],"related":[{"hanzi":"看病","pinyin":"kànbìng","vi":"khám bệnh"},{"hanzi":"就医","pinyin":"jiùyī","vi":"đi khám chữa"},{"hanzi":"求诊","pinyin":"qiúzhěn","vi":"xin khám bệnh"},{"hanzi":"医生","pinyin":"yīshēng","vi":"bác sĩ"}],"traditional":"求醫"},{"id":"求证","hanzi":"求证","pinyin":"qiúzhèng","meaning_vi":"tìm chứng cứ, xác minh","explanation":"求 (cầu – tìm) + 证 (chứng – bằng chứng) → tìm bằng chứng để xác minh một điều là thật hay không.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🔍","examples":[{"type":"basic","zh":"这个消息需要求证。","pinyin":"Zhè ge xiāoxi xūyào qiúzhèng.","vi":"Tin này cần được xác minh."},{"type":"simple","zh":"记者向警方求证了事故的具体情况。","pinyin":"Jìzhě xiàng jǐngfāng qiúzhèngle shìgù de jùtǐ qíngkuàng.","vi":"Phóng viên đã xác minh với cảnh sát tình hình cụ thể của vụ tai nạn."},{"type":"compound","zh":"因为网上谣言很多，所以转发前最好先求证一下。","pinyin":"Yīnwèi wǎngshàng yáoyán hěn duō, suǒyǐ zhuǎnfā qián zuìhǎo xiān qiúzhèng yíxià.","vi":"Vì trên mạng nhiều tin đồn nên trước khi chia sẻ tốt nhất hãy xác minh trước."}],"related":[{"hanzi":"证实","pinyin":"zhèngshí","vi":"chứng thực"},{"hanzi":"核实","pinyin":"héshí","vi":"kiểm tra xác thực"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"chứng minh"},{"hanzi":"求实","pinyin":"qiúshí","vi":"cầu thị"}],"traditional":"求證"},{"id":"曲","hanzi":"曲","pinyin":"qū","meaning_vi":"cong, uốn khúc, quanh co","explanation":"曲 (khúc – cong) → cong, không thẳng; nghĩa bóng là sai trái, không ngay thẳng (是非曲直). Khi đọc qǔ thì nghĩa là bản nhạc, khúc ca.","hsk_level":"7-9","tags":["tinh-tu"],"image":"〰️","examples":[{"type":"basic","zh":"这条小路弯弯曲曲。","pinyin":"Zhè tiáo xiǎolù wānwānqūqū.","vi":"Con đường nhỏ này quanh co khúc khuỷu."},{"type":"simple","zh":"法官必须分清事情的是非曲直。","pinyin":"Fǎguān bìxū fēnqīng shìqing de shìfēi qūzhí.","vi":"Thẩm phán phải phân rõ phải trái đúng sai của sự việc."},{"type":"compound","zh":"虽然这条河曲曲折折，但是最终还是流进了大海。","pinyin":"Suīrán zhè tiáo héqū qūzhé zhé, dànshì zuìzhōng háishì liú jìnle dàhǎi.","vi":"Tuy dòng sông này quanh co uốn khúc nhưng cuối cùng vẫn chảy ra biển lớn."}],"related":[{"hanzi":"弯曲","pinyin":"wānqū","vi":"cong queo"},{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co"},{"hanzi":"曲线","pinyin":"qūxiàn","vi":"đường cong"},{"hanzi":"歌曲","pinyin":"gēqǔ","vi":"bài hát"}]},{"id":"曲线","hanzi":"曲线","pinyin":"qūxiàn","meaning_vi":"đường cong; (cách làm) vòng vèo, gián tiếp","explanation":"曲 (khúc – cong) + 线 (tuyến – đường) → đường cong; nghĩa bóng chỉ cách làm vòng vo, gián tiếp.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"📈","examples":[{"type":"basic","zh":"请画一条曲线。","pinyin":"Qǐng huà yì tiáo qūxiàn.","vi":"Hãy vẽ một đường cong."},{"type":"simple","zh":"这张图表的曲线显示销量在逐月上升。","pinyin":"Zhè zhāng túbiǎo de qūxiàn xiǎnshì xiāoliàng zài zhúyuè shàngshēng.","vi":"Đường cong trên biểu đồ cho thấy doanh số tăng dần theo tháng."},{"type":"compound","zh":"因为她坚持锻炼，所以身材曲线越来越好看。","pinyin":"Yīnwèi tā jiānchí duànliàn, suǒyǐ shēncái qūxiàn yuèláiyuè hǎokàn.","vi":"Vì kiên trì tập luyện nên đường cong cơ thể cô ấy ngày càng đẹp."}],"related":[{"hanzi":"直线","pinyin":"zhíxiàn","vi":"đường thẳng"},{"hanzi":"弯曲","pinyin":"wānqū","vi":"cong"},{"hanzi":"线条","pinyin":"xiàntiáo","vi":"đường nét"},{"hanzi":"曲折","pinyin":"qūzhé","vi":"quanh co"}],"traditional":"曲線"},{"id":"驱动","hanzi":"驱动","pinyin":"qūdòng","meaning_vi":"thúc đẩy, dẫn động; trình điều khiển (driver)","explanation":"驱 (khu – xua, thúc) + 动 (động – chuyển động) → tạo lực làm vật chuyển động; nghĩa rộng là thúc đẩy; trong máy tính là “driver”.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"⚙️","examples":[{"type":"basic","zh":"这辆车是四轮驱动。","pinyin":"Zhè liàng chē shì sì lún qūdòng.","vi":"Chiếc xe này dẫn động bốn bánh."},{"type":"simple","zh":"电脑需要先安装打印机的驱动程序。","pinyin":"Diànnǎo xūyào xiān ānzhuāng dǎyìnjī de qūdòng chéngxù.","vi":"Máy tính cần cài driver máy in trước."},{"type":"compound","zh":"虽然有人只被金钱驱动，但是更多人是为了梦想而努力。","pinyin":"Suīrán yǒurén zhǐ bèi jīnqián qūdòng, dànshì gèng duō rén shì wèile mèngxiǎng ér nǔlì.","vi":"Tuy có người chỉ bị đồng tiền thúc đẩy, nhưng nhiều người hơn nỗ lực vì ước mơ."}],"related":[{"hanzi":"推动","pinyin":"tuīdòng","vi":"thúc đẩy"},{"hanzi":"带动","pinyin":"dàidòng","vi":"kéo theo"},{"hanzi":"驱使","pinyin":"qūshǐ","vi":"sai khiến"},{"hanzi":"动力","pinyin":"dònglì","vi":"động lực"}],"traditional":"驅動"},{"id":"取而代之","hanzi":"取而代之","pinyin":"qǔ'ér-dàizhī","meaning_vi":"thay thế, thế chỗ","explanation":"取 (thủ – lấy) + 而 (nhi – mà) + 代 (đại – thay) + 之 (chi – nó) → giành lấy vị trí của người/vật khác để thay thế (gốc từ câu Hạng Vũ nói về Tần Thủy Hoàng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔄","examples":[{"type":"basic","zh":"新技术取而代之。","pinyin":"Xīnjìshù qǔ'érdàizhī.","vi":"Công nghệ mới đã thay thế nó."},{"type":"simple","zh":"纸质地图渐渐被手机导航取而代之。","pinyin":"Zhǐzhì dìtú jiànjiàn bèi shǒujī dǎoháng qǔ'érdàizhī.","vi":"Bản đồ giấy dần bị định vị trên điện thoại thay thế."},{"type":"compound","zh":"如果他继续犯错，就会有人取而代之。","pinyin":"Rúguǒ tā jìxù fàncuò, jiù huì yǒurén qǔ'érdàizhī.","vi":"Nếu anh ta tiếp tục mắc lỗi thì sẽ có người thay thế vị trí."}],"related":[{"hanzi":"代替","pinyin":"dàitì","vi":"thay thế"},{"hanzi":"取代","pinyin":"qǔdài","vi":"thay thế"},{"hanzi":"替代","pinyin":"tìdài","vi":"thay thế"},{"hanzi":"接替","pinyin":"jiētì","vi":"kế nhiệm"}]},{"id":"取经","hanzi":"取经","pinyin":"qǔjīng","meaning_vi":"thỉnh kinh; học hỏi kinh nghiệm","explanation":"取 (thủ – lấy) + 经 (kinh – kinh sách) → vốn chỉ việc sang Ấn Độ thỉnh kinh Phật (Đường Tăng); nay nghĩa bóng là đến nơi khác học hỏi kinh nghiệm.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"唐僧去西天取经。","pinyin":"Tángsēng qù Xītiān qǔjīng.","vi":"Đường Tăng đi Tây Thiên thỉnh kinh."},{"type":"simple","zh":"我们专门到先进企业去取经学习。","pinyin":"Wǒmen zhuānmén dào xiānjìn qǐyè qù qǔjīng xuéxí.","vi":"Chúng tôi đặc biệt đến các doanh nghiệp tiên tiến để học hỏi kinh nghiệm."},{"type":"compound","zh":"因为那所学校的教学方法很成功，所以很多老师去那里取经。","pinyin":"Yīnwèi nà suǒ xuéxiào de jiàoxué fāngfǎ hěn chénggōng, suǒyǐ hěn duō lǎoshī qù nàlǐ qǔjīng.","vi":"Vì phương pháp dạy của trường đó rất thành công nên nhiều giáo viên đến đó học hỏi."}],"related":[{"hanzi":"学习","pinyin":"xuéxí","vi":"học tập"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"kinh nghiệm"},{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo, học theo"},{"hanzi":"西游记","pinyin":"Xīyóujì","vi":"Tây Du Ký"}],"traditional":"取經"},{"id":"取决于","hanzi":"取决于","pinyin":"qǔjuéyú","meaning_vi":"phụ thuộc vào, quyết định bởi","explanation":"取决 (thủ quyết – lấy làm quyết định) + 于 (ư – vào) → được quyết định bởi, tùy thuộc vào điều gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"这取决于你自己。","pinyin":"Zhè qǔjuéyú nǐ zìjǐ.","vi":"Điều này phụ thuộc vào chính bạn."},{"type":"simple","zh":"成功与否取决于你付出了多少努力。","pinyin":"Chénggōng yǔfǒu qǔjuéyú nǐ fùchūle duōshǎo nǔlì.","vi":"Thành công hay không tùy thuộc vào việc bạn bỏ ra bao nhiêu nỗ lực."},{"type":"compound","zh":"虽然计划已经定了，但是能不能出发还取决于天气。","pinyin":"Suīrán jìhuà yǐjīng dìng le, dànshì néng bu néng chūfā hái qǔjuéyú tiānqì.","vi":"Tuy kế hoạch đã định nhưng có xuất phát được không còn phụ thuộc vào thời tiết."}],"related":[{"hanzi":"决定","pinyin":"juédìng","vi":"quyết định"},{"hanzi":"在于","pinyin":"zàiyú","vi":"nằm ở"},{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"依赖","pinyin":"yīlài","vi":"phụ thuộc"}],"traditional":"取決於"},{"id":"取暖","hanzi":"取暖","pinyin":"qǔnuǎn","meaning_vi":"sưởi ấm","explanation":"取 (thủ – lấy) + 暖 (noãn – ấm) → lấy hơi ấm, sưởi ấm cho cơ thể.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🔥","examples":[{"type":"basic","zh":"我们围着火炉取暖。","pinyin":"Wǒmen wéizhe huǒlú qǔnuǎn.","vi":"Chúng tôi quây quanh lò để sưởi ấm."},{"type":"simple","zh":"北方的冬天家家户户都靠暖气取暖。","pinyin":"Běifāng de dōngtiān jiājiāhùhù dōu kào nuǎnqì qǔnuǎn.","vi":"Mùa đông ở phương Bắc, nhà nhà đều sưởi ấm bằng hệ thống sưởi."},{"type":"compound","zh":"因为山上没有电，所以我们只能烧木柴取暖。","pinyin":"Yīnwèi shān shàng méiyǒu diàn, suǒyǐ wǒmen zhǐnéng shāo mùchái qǔnuǎn.","vi":"Vì trên núi không có điện nên chúng tôi chỉ có thể đốt củi để sưởi."}],"related":[{"hanzi":"暖气","pinyin":"nuǎnqì","vi":"hệ thống sưởi"},{"hanzi":"保暖","pinyin":"bǎonuǎn","vi":"giữ ấm"},{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"},{"hanzi":"火炉","pinyin":"huǒlú","vi":"lò sưởi"}]},{"id":"取笑","hanzi":"取笑","pinyin":"qǔxiào","meaning_vi":"trêu chọc, chế giễu","explanation":"取 (thủ – lấy) + 笑 (tiếu – cười) → lấy người khác làm trò cười, trêu chọc, giễu cợt.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😜","examples":[{"type":"basic","zh":"别取笑他了。","pinyin":"Bié qǔxiào tā le.","vi":"Đừng trêu anh ấy nữa."},{"type":"simple","zh":"同学们取笑他说话带着很重的口音。","pinyin":"Tóngxuémen qǔxiào tā shuōhuà dàizhe hěn zhòng de kǒuyīn.","vi":"Các bạn cùng lớp chế giễu cậu ấy nói giọng địa phương nặng."},{"type":"compound","zh":"即使别人取笑你的梦想，你也要坚持下去。","pinyin":"Jíshǐ biérén qǔxiào nǐ de mèngxiǎng, nǐ yě yào jiānchí xiàqù.","vi":"Dù người khác chế giễu ước mơ của bạn, bạn cũng phải kiên trì đến cùng."}],"related":[{"hanzi":"嘲笑","pinyin":"cháoxiào","vi":"chế nhạo"},{"hanzi":"开玩笑","pinyin":"kāiwánxiào","vi":"đùa"},{"hanzi":"讥笑","pinyin":"jīxiào","vi":"giễu cợt"},{"hanzi":"笑话","pinyin":"xiàohua","vi":"chuyện cười"}]},{"id":"去除","hanzi":"去除","pinyin":"qùchú","meaning_vi":"loại bỏ, tẩy sạch","explanation":"去 (khứ – bỏ đi) + 除 (trừ – loại bỏ) → loại bỏ thứ không cần thiết như vết bẩn, mùi, tạp chất.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧽","examples":[{"type":"basic","zh":"这能去除异味。","pinyin":"Zhè néng qùchú yìwèi.","vi":"Cái này khử được mùi lạ."},{"type":"simple","zh":"用柠檬汁可以去除衣服上的茶渍。","pinyin":"Yòng níngméngzhī kěyǐ qùchú yīfu shàng de chá zì.","vi":"Dùng nước chanh có thể tẩy vết trà trên quần áo."},{"type":"compound","zh":"如果不先去除水里的杂质，就不能直接饮用。","pinyin":"Rúguǒ bù xiān qùchú shuǐ lǐ de zázhì, jiù bù néng zhíjiē yǐnyòng.","vi":"Nếu không loại bỏ tạp chất trong nước trước thì không thể uống trực tiếp."}],"related":[{"hanzi":"清除","pinyin":"qīngchú","vi":"dọn sạch"},{"hanzi":"消除","pinyin":"xiāochú","vi":"xóa bỏ"},{"hanzi":"去掉","pinyin":"qùdiào","vi":"bỏ đi"},{"hanzi":"删除","pinyin":"shānchú","vi":"xóa"}]},{"id":"去处","hanzi":"去处","pinyin":"qùchù","meaning_vi":"nơi để đi, chỗ đến","explanation":"去 (khứ – đi) + 处 (xứ – nơi) → nơi để đi tới; 好去处 là chỗ hay nên đến.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"这里是避暑的好去处。","pinyin":"Zhèlǐ shì bìshǔ de hǎo qùchù.","vi":"Đây là nơi tránh nóng lý tưởng."},{"type":"simple","zh":"周末孩子们最喜欢的去处是动物园。","pinyin":"Zhōumò háizimen zuì xǐhuan de qùchù shì dòngwùyuán.","vi":"Nơi bọn trẻ thích đến nhất vào cuối tuần là sở thú."},{"type":"compound","zh":"虽然城市很大，但是晚上适合散步的去处并不多。","pinyin":"Suīrán chéngshì hěn dà, dànshì wǎnshang shìhé sànbù de qùchù bìngbù duō.","vi":"Tuy thành phố rất lớn nhưng buổi tối không có nhiều chỗ thích hợp để đi dạo."}],"related":[{"hanzi":"地方","pinyin":"dìfang","vi":"nơi chốn"},{"hanzi":"去向","pinyin":"qùxiàng","vi":"hướng đi"},{"hanzi":"场所","pinyin":"chǎngsuǒ","vi":"địa điểm"},{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm tham quan"}],"traditional":"去處"},{"id":"去向","hanzi":"去向","pinyin":"qùxiàng","meaning_vi":"hướng đi, tung tích, nơi đến","explanation":"去 (khứ – đi) + 向 (hướng – phương hướng) → hướng mà người hoặc vật đã đi tới, tung tích.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧭","examples":[{"type":"basic","zh":"他的去向不明。","pinyin":"Tā de qùxiàng bùmíng.","vi":"Tung tích của anh ta không rõ."},{"type":"simple","zh":"警方正在调查这笔钱的去向。","pinyin":"Jǐngfāng zhèngzài diàochá zhè bǐ qián de qùxiàng.","vi":"Cảnh sát đang điều tra số tiền này đã đi đâu."},{"type":"compound","zh":"因为毕业生的去向越来越多样，所以学校开设了职业规划课。","pinyin":"Yīnwèi bìyèshēng de qùxiàng yuèláiyuè duōyàng, suǒyǐ xuéxiào kāishèle zhíyèguīhuà kè.","vi":"Vì hướng đi của sinh viên tốt nghiệp ngày càng đa dạng nên trường mở lớp định hướng nghề nghiệp."}],"related":[{"hanzi":"下落","pinyin":"xiàluò","vi":"tung tích"},{"hanzi":"去处","pinyin":"qùchù","vi":"nơi đến"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"},{"hanzi":"动向","pinyin":"dòngxiàng","vi":"động thái"}]},{"id":"全程","hanzi":"全程","pinyin":"quánchéng","meaning_vi":"toàn bộ hành trình, suốt quá trình","explanation":"全 (toàn – tất cả) + 程 (trình – chặng đường) → toàn bộ quãng đường, từ đầu đến cuối.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🛣️","examples":[{"type":"basic","zh":"全程大约三个小时。","pinyin":"Quánchéng dàyuē sān gè xiǎoshí.","vi":"Toàn bộ hành trình khoảng ba tiếng."},{"type":"simple","zh":"导游全程陪同我们参观了故宫。","pinyin":"Dǎoyóu quánchéng péitóng wǒmen cānguānle gùgōng.","vi":"Hướng dẫn viên đi cùng chúng tôi suốt chuyến tham quan Cố Cung."},{"type":"compound","zh":"虽然马拉松全程很长，但是他坚持跑到了终点。","pinyin":"Suīrán mǎlāsōng quánchéng hěn cháng, dànshì tā jiānchí pǎo dàole zhōngdiǎn.","vi":"Tuy toàn bộ cự ly marathon rất dài nhưng anh ấy đã kiên trì chạy đến đích."}],"related":[{"hanzi":"路程","pinyin":"lùchéng","vi":"quãng đường"},{"hanzi":"行程","pinyin":"xíngchéng","vi":"lịch trình"},{"hanzi":"全过程","pinyin":"quánguòchéng","vi":"toàn bộ quá trình"},{"hanzi":"半程","pinyin":"bànchéng","vi":"nửa chặng"}]},{"id":"全方位","hanzi":"全方位","pinyin":"quánfāngwèi","meaning_vi":"toàn diện, mọi mặt","explanation":"全 (toàn – tất cả) + 方位 (phương vị – phương hướng, vị trí) → mọi phương hướng, mọi mặt; nghĩa là toàn diện.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌐","examples":[{"type":"basic","zh":"我们提供全方位服务。","pinyin":"Wǒmen tígōng quánfāngwèi fúwù.","vi":"Chúng tôi cung cấp dịch vụ toàn diện."},{"type":"simple","zh":"这款摄像头可以全方位监控整个房间。","pinyin":"Zhè kuǎn shèxiàngtóu kěyǐ quánfāngwèi jiānkòng zhěnggè fángjiān.","vi":"Camera này có thể giám sát toàn bộ căn phòng từ mọi góc."},{"type":"compound","zh":"如果想培养出优秀的人才，就要对学生进行全方位的教育。","pinyin":"Rúguǒ xiǎng péiyǎng chū yōuxiù de réncái, jiùyào duì xuéshēng jìnxíng quánfāngwèi de jiàoyù.","vi":"Nếu muốn đào tạo ra nhân tài xuất sắc thì phải giáo dục học sinh một cách toàn diện."}],"related":[{"hanzi":"全面","pinyin":"quánmiàn","vi":"toàn diện"},{"hanzi":"多方面","pinyin":"duōfāngmiàn","vi":"nhiều mặt"},{"hanzi":"方位","pinyin":"fāngwèi","vi":"phương vị"},{"hanzi":"立体","pinyin":"lìtǐ","vi":"lập thể, đa chiều"}]},{"id":"全文","hanzi":"全文","pinyin":"quánwén","meaning_vi":"toàn văn, toàn bộ bài viết","explanation":"全 (toàn – tất cả) + 文 (văn – bài văn) → toàn bộ nội dung một văn bản.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"📄","examples":[{"type":"basic","zh":"请阅读全文。","pinyin":"Qǐng yuèdú quánwén.","vi":"Hãy đọc toàn văn."},{"type":"simple","zh":"这篇报告全文共有一万多字。","pinyin":"Zhè piān bàogào quánwén gòngyǒu yī wàn duō zì.","vi":"Bản báo cáo này toàn văn có hơn một vạn chữ."},{"type":"compound","zh":"因为时间有限，所以我只看了摘要，没读全文。","pinyin":"Yīnwèi shíjiān yǒuxiàn, suǒyǐ wǒ zhǐ kànle zhāiyào, méi dú quánwén.","vi":"Vì thời gian có hạn nên tôi chỉ xem phần tóm tắt, chưa đọc toàn văn."}],"related":[{"hanzi":"原文","pinyin":"yuánwén","vi":"nguyên văn"},{"hanzi":"全篇","pinyin":"quánpiān","vi":"cả bài"},{"hanzi":"摘要","pinyin":"zhāiyào","vi":"tóm tắt"},{"hanzi":"正文","pinyin":"zhèngwén","vi":"phần chính văn"}]},{"id":"全长","hanzi":"全长","pinyin":"quáncháng","meaning_vi":"tổng chiều dài, chiều dài toàn bộ","explanation":"全 (toàn – tất cả) + 长 (trường – dài) → tổng chiều dài từ đầu đến cuối của cầu, sông, đường…","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📏","examples":[{"type":"basic","zh":"这座桥全长两公里。","pinyin":"Zhè zuò qiáo quáncháng liǎng gōnglǐ.","vi":"Cây cầu này dài tổng cộng hai cây số."},{"type":"simple","zh":"长江全长约六千三百公里。","pinyin":"Chángjiāng quáncháng yuē liù qiān sān bǎi gōnglǐ.","vi":"Sông Trường Giang dài khoảng 6.300 km."},{"type":"compound","zh":"虽然这条地铁线全长不到二十公里，但是每天的客流量很大。","pinyin":"Suīrán zhè tiáo dìtiě xiàn quáncháng búdào èrshí gōnglǐ, dànshì měitiān de kèliúliàng hěn dà.","vi":"Tuy tuyến tàu điện ngầm này dài chưa đến 20 km nhưng lượng khách mỗi ngày rất lớn."}],"related":[{"hanzi":"长度","pinyin":"chángdù","vi":"chiều dài"},{"hanzi":"全程","pinyin":"quánchéng","vi":"toàn hành trình"},{"hanzi":"总长","pinyin":"zǒngcháng","vi":"tổng chiều dài"},{"hanzi":"宽度","pinyin":"kuāndù","vi":"chiều rộng"}],"traditional":"全長"},{"id":"拳","hanzi":"拳","pinyin":"quán","meaning_vi":"nắm đấm; quyền (võ); cú đấm","explanation":"拳 (quyền – nắm tay) → bàn tay nắm lại; còn chỉ quyền thuật (太极拳) và làm lượng từ cho cú đấm (打了一拳).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"👊","examples":[{"type":"basic","zh":"他握紧了拳头。","pinyin":"Tā wò jǐnle quántou.","vi":"Anh ấy nắm chặt tay lại."},{"type":"simple","zh":"爷爷每天早上都在公园里打太极拳。","pinyin":"Yéye měitiān zǎo Shangdōu zài gōngyuán lǐ dǎ tàijíquán.","vi":"Ông nội sáng nào cũng tập thái cực quyền trong công viên."},{"type":"compound","zh":"虽然他挨了一拳，但是他并没有还手。","pinyin":"Suīrán tā áile yì quán, dànshì tā bìng méiyǒu huán shǒu.","vi":"Tuy bị ăn một cú đấm nhưng anh ấy không hề đánh trả."}],"related":[{"hanzi":"拳头","pinyin":"quántou","vi":"nắm đấm"},{"hanzi":"拳击","pinyin":"quánjī","vi":"quyền anh"},{"hanzi":"太极拳","pinyin":"tàijíquán","vi":"thái cực quyền"},{"hanzi":"拳打脚踢","pinyin":"quándǎjiǎotī","vi":"đấm đá túi bụi"}]},{"id":"劝说","hanzi":"劝说","pinyin":"quànshuō","meaning_vi":"khuyên nhủ, thuyết phục","explanation":"劝 (khuyến – khuyên) + 说 (thuyết – nói) → dùng lời lẽ khuyên bảo để người khác làm theo.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"我劝说他戒烟。","pinyin":"Wǒ quànshuō tā jièyān.","vi":"Tôi khuyên anh ấy bỏ thuốc lá."},{"type":"simple","zh":"在家人的劝说下，他终于同意去看医生。","pinyin":"Zài jiārén de quànshuō xià, tā zhōngyú tóngyì qù kànyīshēng.","vi":"Nhờ người nhà khuyên nhủ, anh ấy cuối cùng đồng ý đi khám bác sĩ."},{"type":"compound","zh":"虽然大家反复劝说，但是她还是坚持辞职了。","pinyin":"Suīrán dàjiā fǎnfù quànshuō, dànshì tā háishì jiānchí cízhí le.","vi":"Tuy mọi người khuyên đi khuyên lại nhưng cô ấy vẫn nhất quyết nghỉ việc."}],"related":[{"hanzi":"劝告","pinyin":"quàngào","vi":"khuyên bảo"},{"hanzi":"说服","pinyin":"shuōfú","vi":"thuyết phục"},{"hanzi":"劝阻","pinyin":"quànzǔ","vi":"can ngăn"},{"hanzi":"劝导","pinyin":"quàndǎo","vi":"khuyên dẫn"}],"traditional":"勸說"},{"id":"缺失","hanzi":"缺失","pinyin":"quēshī","meaning_vi":"thiếu hụt, thiếu sót; khuyết điểm","explanation":"缺 (khuyết – thiếu) + 失 (thất – mất) → thiếu mất, không đầy đủ; cũng chỉ chỗ thiếu sót.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"文件有几页缺失。","pinyin":"Wénjiàn yǒu jǐ yè quēshī.","vi":"Tài liệu bị thiếu mất vài trang."},{"type":"simple","zh":"孩子的成长中不能缺失父母的陪伴。","pinyin":"Háizi de chéngzhǎng zhōng bù néng quēshī fùmǔ de péibàn.","vi":"Quá trình trưởng thành của trẻ không thể thiếu sự đồng hành của cha mẹ."},{"type":"compound","zh":"因为数据缺失太多，所以这次的分析结果不太可靠。","pinyin":"Yīnwèi shùjù quēshī tài duō, suǒyǐ zhè cì de fēnxī jiéguǒ bú tài kěkào.","vi":"Vì thiếu quá nhiều dữ liệu nên kết quả phân tích lần này không đáng tin lắm."}],"related":[{"hanzi":"缺少","pinyin":"quēshǎo","vi":"thiếu"},{"hanzi":"缺乏","pinyin":"quēfá","vi":"thiếu hụt"},{"hanzi":"缺陷","pinyin":"quēxiàn","vi":"khiếm khuyết"},{"hanzi":"遗漏","pinyin":"yílòu","vi":"bỏ sót"}]},{"id":"确凿","hanzi":"确凿","pinyin":"quèzáo","meaning_vi":"xác thực, rõ ràng, không thể chối cãi","explanation":"确 (xác – chắc chắn) + 凿 (tạc – rõ ràng, đanh thép) → chắc chắn, không thể bác bỏ; thường nói 证据确凿.","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"🧾","examples":[{"type":"basic","zh":"他的罪证十分确凿。","pinyin":"Tā de zuìzhèng shífēn quèzáo.","vi":"Chứng cứ phạm tội của hắn hết sức rõ ràng."},{"type":"simple","zh":"警方已经掌握了他受贿的确凿证据。","pinyin":"Jǐngfāng yǐjīng zhǎngwòle tā shòuhuì de quèzáo zhèngjù.","vi":"Cảnh sát đã nắm được bằng chứng xác thực hắn nhận hối lộ."},{"type":"compound","zh":"如果没有确凿的证据，就不能随便给别人定罪。","pinyin":"Rúguǒ méiyǒu quèzáo de zhèngjù, jiù bù néng suíbiàn gěi biérén dìngzuì.","vi":"Nếu không có bằng chứng xác thực thì không thể tùy tiện buộc tội người khác."}],"related":[{"hanzi":"确实","pinyin":"quèshí","vi":"xác thực"},{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"},{"hanzi":"可靠","pinyin":"kěkào","vi":"đáng tin"},{"hanzi":"千真万确","pinyin":"qiānzhēnwànquè","vi":"hoàn toàn chính xác"}],"traditional":"確鑿"},{"id":"确诊","hanzi":"确诊","pinyin":"quèzhěn","meaning_vi":"chẩn đoán xác định, xác nhận mắc bệnh","explanation":"确 (xác – chắc chắn) + 诊 (chẩn – khám bệnh) → chẩn đoán chắc chắn là mắc một bệnh nào đó.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"他被确诊为肺炎。","pinyin":"Tā bèi quèzhěn wéi fèiyán.","vi":"Anh ấy được chẩn đoán xác định là viêm phổi."},{"type":"simple","zh":"今天全市新增了十例确诊病例。","pinyin":"Jīntiān quánshì xīnzēngle shí lì quèzhěn bìnglì.","vi":"Hôm nay toàn thành phố có thêm mười ca bệnh được xác nhận."},{"type":"compound","zh":"一旦确诊是流感，就要马上隔离休息。","pinyin":"Yídàn quèzhěn shì liúgǎn, jiùyào mǎshàng gélí xiūxi.","vi":"Một khi xác định là cúm thì phải lập tức cách ly nghỉ ngơi."}],"related":[{"hanzi":"诊断","pinyin":"zhěnduàn","vi":"chẩn đoán"},{"hanzi":"病例","pinyin":"bìnglì","vi":"ca bệnh"},{"hanzi":"疑似","pinyin":"yísì","vi":"nghi ngờ (mắc bệnh)"},{"hanzi":"误诊","pinyin":"wùzhěn","vi":"chẩn đoán sai"}],"traditional":"確診"},{"id":"燃放","hanzi":"燃放","pinyin":"ránfàng","meaning_vi":"đốt, bắn (pháo, pháo hoa)","explanation":"燃 (nhiên – đốt) + 放 (phóng – thả) → đốt và phóng pháo hoa, pháo nổ.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🎆","examples":[{"type":"basic","zh":"市区禁止燃放鞭炮。","pinyin":"Shìqū jìnzhǐ ránfàng biānpào.","vi":"Nội thành cấm đốt pháo."},{"type":"simple","zh":"除夕夜很多人家燃放烟花迎接新年。","pinyin":"Chúxīyè hěn duō rénjiā ránfàng yānhuā yíngjiē xīnnián.","vi":"Đêm giao thừa nhiều nhà bắn pháo hoa đón năm mới."},{"type":"compound","zh":"虽然燃放烟花很热闹，但是也会造成空气污染。","pinyin":"Suīrán ránfàng yānhuā hěn rènao, dànshì yě huì zàochéng kōngqì wūrǎn.","vi":"Tuy bắn pháo hoa rất náo nhiệt nhưng cũng gây ô nhiễm không khí."}],"related":[{"hanzi":"鞭炮","pinyin":"biānpào","vi":"pháo"},{"hanzi":"烟花","pinyin":"yānhuā","vi":"pháo hoa"},{"hanzi":"点燃","pinyin":"diǎnrán","vi":"châm lửa"},{"hanzi":"爆竹","pinyin":"bàozhú","vi":"pháo tre"}]},{"id":"燃气","hanzi":"燃气","pinyin":"ránqì","meaning_vi":"khí đốt, gas","explanation":"燃 (nhiên – đốt cháy) + 气 (khí – hơi) → khí dùng làm nhiên liệu như khí than, khí thiên nhiên.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"♨️","examples":[{"type":"basic","zh":"做完饭要关燃气。","pinyin":"Zuòwán fàn yào guān ránqì.","vi":"Nấu cơm xong phải khóa gas."},{"type":"simple","zh":"这个月的燃气费比上个月高了不少。","pinyin":"Zhè geyuè de ránqì fèi bǐ shànggèyuè gāole bùshǎo.","vi":"Tiền gas tháng này cao hơn tháng trước khá nhiều."},{"type":"compound","zh":"如果闻到燃气的味道，就要立刻打开窗户通风。","pinyin":"Rúguǒ wéndào ránqì de wèidao, jiùyào lìkè dǎkāi chuānghu tōngfēng.","vi":"Nếu ngửi thấy mùi gas thì phải lập tức mở cửa sổ cho thông gió."}],"related":[{"hanzi":"天然气","pinyin":"tiānránqì","vi":"khí thiên nhiên"},{"hanzi":"煤气","pinyin":"méiqì","vi":"khí than, gas"},{"hanzi":"燃料","pinyin":"ránliào","vi":"nhiên liệu"},{"hanzi":"燃气灶","pinyin":"ránqìzào","vi":"bếp gas"}],"traditional":"燃氣"},{"id":"燃油","hanzi":"燃油","pinyin":"rányóu","meaning_vi":"dầu đốt, nhiên liệu (xăng dầu)","explanation":"燃 (nhiên – đốt) + 油 (du – dầu) → dầu dùng làm nhiên liệu cho động cơ, lò đốt.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"⛽","examples":[{"type":"basic","zh":"飞机正在加燃油。","pinyin":"Fēijī zhèngzài jiā rányóu.","vi":"Máy bay đang được tiếp nhiên liệu."},{"type":"simple","zh":"机票价格里包含了燃油附加费。","pinyin":"Jīpiào jiàgé lǐ bāohánle rányóu fùjiāfèi.","vi":"Giá vé máy bay đã bao gồm phụ phí nhiên liệu."},{"type":"compound","zh":"因为国际油价上涨，所以燃油费用也跟着提高了。","pinyin":"Yīnwèi Guójì yóujià shàngzhǎng, suǒyǐ rányóu fèiyòng yě gēnzhe tígāo le.","vi":"Vì giá dầu thế giới tăng nên chi phí nhiên liệu cũng tăng theo."}],"related":[{"hanzi":"汽油","pinyin":"qìyóu","vi":"xăng"},{"hanzi":"柴油","pinyin":"cháiyóu","vi":"dầu diesel"},{"hanzi":"燃料","pinyin":"ránliào","vi":"nhiên liệu"},{"hanzi":"加油站","pinyin":"jiāyóuzhàn","vi":"trạm xăng"}]},{"id":"饶","hanzi":"饶","pinyin":"ráo","meaning_vi":"tha, tha thứ; dồi dào","explanation":"饶 (nhiêu – dư dả; tha) → nghĩa gốc là dồi dào (丰饶); thường dùng với nghĩa tha thứ, bỏ qua (饶了他吧).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"这次就饶了你吧。","pinyin":"Zhè cì jiù ráole nǐ ba.","vi":"Lần này tha cho cậu đấy."},{"type":"simple","zh":"他跪在地上求对方饶他一命。","pinyin":"Tā guì zài dìshang qiú duìfāng ráo tā yí mìng.","vi":"Hắn quỳ dưới đất xin đối phương tha cho một mạng."},{"type":"compound","zh":"如果你下次再迟到，我就不饶你了。","pinyin":"Rúguǒ nǐ xiàcì zài chídào, wǒ jiù bù ráo nǐ le.","vi":"Nếu lần sau cậu còn đến muộn thì tôi không tha đâu."}],"related":[{"hanzi":"饶恕","pinyin":"ráoshù","vi":"tha thứ"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"tha lỗi"},{"hanzi":"求饶","pinyin":"qiúráo","vi":"xin tha"},{"hanzi":"丰饶","pinyin":"fēngráo","vi":"phong phú, trù phú"}],"traditional":"饒"},{"id":"绕行","hanzi":"绕行","pinyin":"ràoxíng","meaning_vi":"đi vòng, đi đường vòng","explanation":"绕 (nhiễu – vòng quanh) + 行 (hành – đi) → đi vòng qua để tránh đoạn đường phía trước; cũng chỉ bay quanh quỹ đạo.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"↪️","examples":[{"type":"basic","zh":"前方施工，请绕行。","pinyin":"Qiánfāng shīgōng, qǐng ràoxíng.","vi":"Phía trước đang thi công, vui lòng đi đường vòng."},{"type":"simple","zh":"公交车这几天要绕行另一条街。","pinyin":"Gōngjiāochē zhèjǐtiān yào ràoxíng lìngyì tiáo jiē.","vi":"Mấy hôm nay xe buýt phải đi vòng qua một con phố khác."},{"type":"compound","zh":"因为桥梁正在维修，所以所有车辆都必须绕行。","pinyin":"Yīnwèi qiáoliáng zhèngzài wéixiū, suǒyǐ suǒyǒu chēliàng dōu bìxū ràoxíng.","vi":"Vì cầu đang sửa chữa nên mọi phương tiện đều phải đi đường vòng."}],"related":[{"hanzi":"绕道","pinyin":"ràodào","vi":"đi đường vòng"},{"hanzi":"绕圈","pinyin":"ràoquān","vi":"đi vòng tròn"},{"hanzi":"环绕","pinyin":"huánrào","vi":"bao quanh"},{"hanzi":"改道","pinyin":"gǎidào","vi":"đổi tuyến"}],"traditional":"繞行"},{"id":"惹","hanzi":"惹","pinyin":"rě","meaning_vi":"chọc, gây (chuyện), trêu tức","explanation":"惹 (nhạ – khiêu khích) → gây ra, chuốc lấy (惹麻烦); chọc giận người khác (别惹他).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😠","examples":[{"type":"basic","zh":"别惹他生气。","pinyin":"Bié rě tā shēngqì.","vi":"Đừng chọc anh ấy giận."},{"type":"simple","zh":"这孩子又在学校惹了麻烦。","pinyin":"Zhè háizi yòu zài xuéxiào rěle máfan.","vi":"Đứa trẻ này lại gây rắc rối ở trường."},{"type":"compound","zh":"如果你不想惹事，就离那些人远一点。","pinyin":"Rúguǒ nǐ bù xiǎng rěshì, jiù lí nàxiē rén yuǎn yìdiǎn.","vi":"Nếu không muốn gây chuyện thì tránh xa những người đó ra."}],"related":[{"hanzi":"惹祸","pinyin":"rěhuò","vi":"gây họa"},{"hanzi":"招惹","pinyin":"zhāorě","vi":"trêu chọc"},{"hanzi":"惹人注目","pinyin":"rěrénzhùmù","vi":"gây chú ý"},{"hanzi":"挑衅","pinyin":"tiǎoxìn","vi":"khiêu khích"}]},{"id":"热带","hanzi":"热带","pinyin":"rèdài","meaning_vi":"nhiệt đới","explanation":"热 (nhiệt – nóng) + 带 (đới – vùng) → vùng khí hậu nóng nằm giữa hai chí tuyến.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌴","examples":[{"type":"basic","zh":"这是热带水果。","pinyin":"Zhè shì rèdài shuǐguǒ.","vi":"Đây là trái cây nhiệt đới."},{"type":"simple","zh":"海南岛属于热带季风气候。","pinyin":"Hǎinándǎo shǔyú rèdài jìfēng qìhòu.","vi":"Đảo Hải Nam thuộc khí hậu nhiệt đới gió mùa."},{"type":"compound","zh":"因为越南南部位于热带，所以一年四季都很温暖。","pinyin":"Yīnwèi Yuènán Nánbù wèiyú rèdài, suǒyǐ yì nián sìjì dōu hěn wēnnuǎn.","vi":"Vì miền Nam Việt Nam nằm trong vùng nhiệt đới nên quanh năm đều ấm áp."}],"related":[{"hanzi":"亚热带","pinyin":"yàrèdài","vi":"cận nhiệt đới"},{"hanzi":"寒带","pinyin":"hándài","vi":"hàn đới"},{"hanzi":"温带","pinyin":"wēndài","vi":"ôn đới"},{"hanzi":"热带雨林","pinyin":"rèdàiyǔlín","vi":"rừng mưa nhiệt đới"}],"traditional":"熱帶"},{"id":"热气","hanzi":"热气","pinyin":"rèqì","meaning_vi":"hơi nóng, hơi nước nóng","explanation":"热 (nhiệt – nóng) + 气 (khí – hơi) → hơi nóng bốc lên; nghĩa bóng là không khí sôi nổi.","hsk_level":"7-9","tags":["danh-tu"],"image":"💨","examples":[{"type":"basic","zh":"锅里冒着热气。","pinyin":"Guō lǐ màozhe rèqì.","vi":"Trong nồi đang bốc hơi nóng."},{"type":"simple","zh":"刚出锅的包子还冒着热气。","pinyin":"Gāng chū guō de bāozi hái màozhe rèqì.","vi":"Bánh bao vừa ra nồi vẫn còn bốc hơi nóng."},{"type":"compound","zh":"虽然外面下着雪，但是屋里的热气让人觉得很舒服。","pinyin":"Suīrán wàimiàn xiàzhe xuě, dànshì wū lǐ de rèqì ràng rén juéde hěn shūfu.","vi":"Tuy bên ngoài tuyết rơi nhưng hơi ấm trong nhà khiến người ta thấy dễ chịu."}],"related":[{"hanzi":"蒸汽","pinyin":"zhēngqì","vi":"hơi nước"},{"hanzi":"冷气","pinyin":"lěngqì","vi":"hơi lạnh"},{"hanzi":"热气腾腾","pinyin":"rèqìténgténg","vi":"nóng hổi nghi ngút"},{"hanzi":"热量","pinyin":"rèliàng","vi":"nhiệt lượng"}],"traditional":"熱氣"},{"id":"热气球","hanzi":"热气球","pinyin":"rèqìqiú","meaning_vi":"khinh khí cầu","explanation":"热气 (nhiệt khí – hơi nóng) + 球 (cầu – quả bóng) → quả bóng lớn bay lên nhờ không khí nóng bên trong, tức khinh khí cầu.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎈","examples":[{"type":"basic","zh":"天上飘着热气球。","pinyin":"Tiānshàng piāozhe rèqìqiú.","vi":"Trên trời có khinh khí cầu đang bay."},{"type":"simple","zh":"我们清晨坐热气球俯瞰了整个山谷。","pinyin":"Wǒmen qīngchén zuò rèqìqiú fǔkànle zhěnggè shāngǔ.","vi":"Sáng sớm chúng tôi ngồi khinh khí cầu ngắm toàn cảnh thung lũng."},{"type":"compound","zh":"如果明天风太大，热气球就不能起飞了。","pinyin":"Rúguǒ míngtiān fēng tài dà, rèqìqiú jiù bù néng qǐfēi le.","vi":"Nếu mai gió quá to thì khinh khí cầu sẽ không cất cánh được."}],"related":[{"hanzi":"气球","pinyin":"qìqiú","vi":"bóng bay"},{"hanzi":"飞艇","pinyin":"fēitǐng","vi":"khí cầu có động cơ"},{"hanzi":"热气","pinyin":"rèqì","vi":"hơi nóng"},{"hanzi":"降落伞","pinyin":"jiàngluòsǎn","vi":"dù nhảy"}],"traditional":"熱氣球"},{"id":"热腾腾","hanzi":"热腾腾","pinyin":"rèténgténg","meaning_vi":"nóng hổi, bốc hơi nghi ngút","explanation":"热 (nhiệt – nóng) + 腾腾 (đằng đằng – bốc lên nghi ngút) → nóng hổi, hơi nóng bốc lên; hay dùng cho đồ ăn vừa nấu xong.","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"一碗热腾腾的面。","pinyin":"Yì wǎn rèténgténg de miàn.","vi":"Một bát mì nóng hổi."},{"type":"simple","zh":"妈妈端来了一盘热腾腾的饺子。","pinyin":"Māma duān láile yì pán rèténgténg de jiǎozi.","vi":"Mẹ bưng ra một đĩa sủi cảo nóng hổi."},{"type":"compound","zh":"虽然外面天寒地冻，但是喝一碗热腾腾的汤就暖和了。","pinyin":"Suīrán wàimiàn tiān hán dì dòng, dànshì hē yì wǎn rèténgténg de tāng jiù nuǎnhuo le.","vi":"Tuy bên ngoài trời rét căm căm nhưng uống một bát canh nóng hổi là ấm ngay."}],"related":[{"hanzi":"热乎乎","pinyin":"rèhūhū","vi":"nóng hổi"},{"hanzi":"香喷喷","pinyin":"xiāngpēnpēn","vi":"thơm phức"},{"hanzi":"冷冰冰","pinyin":"lěngbīngbīng","vi":"lạnh ngắt"},{"hanzi":"热气","pinyin":"rèqì","vi":"hơi nóng"}],"traditional":"熱騰騰"},{"id":"人次","hanzi":"人次","pinyin":"réncì","meaning_vi":"lượt người","explanation":"人 (nhân – người) + 次 (thứ – lần, lượt) → đơn vị tính tổng số lượt người tham gia (một người đến hai lần tính là hai lượt).","hsk_level":"7-9","tags":["luong-tu","so-luong"],"image":"👥","examples":[{"type":"basic","zh":"观众达到十万人次。","pinyin":"Guānzhòng dádào shíwàn réncì.","vi":"Khán giả đạt mười vạn lượt người."},{"type":"simple","zh":"春节期间景区共接待游客五十万人次。","pinyin":"Chūnjié qījiān jǐngqū gòng jiēdài yóukè wǔ shíwàn réncì.","vi":"Dịp Tết, khu du lịch đã đón tổng cộng năm mươi vạn lượt khách."},{"type":"compound","zh":"因为展览非常受欢迎，所以一个月就吸引了上百万人次参观。","pinyin":"Yīnwèi zhǎnlǎn fēicháng shòuhuānyíng, suǒyǐ yí gèyuè jiù xīyǐnle shàng bǎiwàn réncì cānguān.","vi":"Vì triển lãm rất được yêu thích nên chỉ một tháng đã thu hút hơn một triệu lượt khách."}],"related":[{"hanzi":"人数","pinyin":"rénshù","vi":"số người"},{"hanzi":"次数","pinyin":"cìshù","vi":"số lần"},{"hanzi":"客流量","pinyin":"kèliúliàng","vi":"lượng khách"},{"hanzi":"人口","pinyin":"rénkǒu","vi":"dân số"}]},{"id":"人均","hanzi":"人均","pinyin":"rénjūn","meaning_vi":"bình quân đầu người","explanation":"人 (nhân – người) + 均 (quân – chia đều) → tính bình quân cho mỗi người.","hsk_level":"7-9","tags":["tinh-tu","so-luong"],"image":"🧮","examples":[{"type":"basic","zh":"这顿饭人均一百元。","pinyin":"Zhè dùn fàn rénjūn yī bǎi yuán.","vi":"Bữa ăn này bình quân mỗi người 100 tệ."},{"type":"simple","zh":"这个国家的人均收入逐年提高。","pinyin":"Zhè ge guójiā de rénjūnshōurù zhúnián tígāo.","vi":"Thu nhập bình quân đầu người của nước này tăng qua từng năm."},{"type":"compound","zh":"虽然这里的经济总量很大，但是人均水平并不高。","pinyin":"Suīrán zhèlǐ de jīngjì zǒngliàng hěn dà, dànshì rénjūn shuǐpíng bìngbù gāo.","vi":"Tuy tổng quy mô kinh tế ở đây rất lớn nhưng mức bình quân đầu người không cao."}],"related":[{"hanzi":"平均","pinyin":"píngjūn","vi":"bình quân"},{"hanzi":"人均收入","pinyin":"rénjūnshōurù","vi":"thu nhập bình quân"},{"hanzi":"均匀","pinyin":"jūnyún","vi":"đồng đều"},{"hanzi":"总量","pinyin":"zǒngliàng","vi":"tổng lượng"}]},{"id":"人品","hanzi":"人品","pinyin":"rénpǐn","meaning_vi":"nhân phẩm, phẩm chất con người","explanation":"人 (nhân – người) + 品 (phẩm – phẩm chất) → phẩm chất đạo đức của một người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"😇","examples":[{"type":"basic","zh":"他的人品很好。","pinyin":"Tā de rénpǐn hěn hǎo.","vi":"Nhân phẩm của anh ấy rất tốt."},{"type":"simple","zh":"选择合作伙伴时人品比能力更重要。","pinyin":"Xuǎnzé hézuò huǒbàn shí rénpǐn bǐ nénglì gèng zhòngyào.","vi":"Khi chọn đối tác, nhân phẩm quan trọng hơn năng lực."},{"type":"compound","zh":"即使他能力再强，人品不好也没人愿意跟他共事。","pinyin":"Jíshǐ tā nénglì zài qiáng, rénpǐn bù hǎo yě méi rén yuànyì gēn tā gòngshì.","vi":"Dù năng lực có giỏi đến đâu, nhân phẩm kém thì cũng không ai muốn làm việc cùng."}],"related":[{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"人格","pinyin":"réngé","vi":"nhân cách"},{"hanzi":"品行","pinyin":"pǐnxíng","vi":"phẩm hạnh"},{"hanzi":"为人","pinyin":"wéirén","vi":"cách làm người"}]},{"id":"人气","hanzi":"人气","pinyin":"rénqì","meaning_vi":"độ nổi tiếng, sức hút; sự đông người","explanation":"人 (nhân – người) + 气 (khí – khí thế) → sức hút với công chúng, mức độ được yêu thích; cũng chỉ sự đông vui đông người.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"⭐","examples":[{"type":"basic","zh":"这位歌手人气很高。","pinyin":"Zhè wèi gēshǒu rénqì hěn gāo.","vi":"Ca sĩ này rất nổi tiếng."},{"type":"simple","zh":"这家新开的奶茶店人气越来越旺。","pinyin":"Zhè jiā xīn kāi de nǎichá diàn rénqì yuèláiyuè wàng.","vi":"Quán trà sữa mới mở này ngày càng đông khách."},{"type":"compound","zh":"因为参加了那档综艺节目，所以他的人气一下子涨了很多。","pinyin":"Yīnwèi cānjiāle nà dàng zōngyì jiémù, suǒyǐ tā de rénqì yíxiàzi zhǎngle hěn duō.","vi":"Vì tham gia chương trình tạp kỹ đó nên độ nổi tiếng của anh ấy tăng vọt."}],"related":[{"hanzi":"名气","pinyin":"míngqì","vi":"danh tiếng"},{"hanzi":"受欢迎","pinyin":"shòuhuānyíng","vi":"được yêu thích"},{"hanzi":"粉丝","pinyin":"fěnsī","vi":"người hâm mộ"},{"hanzi":"知名度","pinyin":"zhīmíngdù","vi":"độ nổi tiếng"}],"traditional":"人氣"},{"id":"人情","hanzi":"人情","pinyin":"rénqíng","meaning_vi":"tình người, ân tình; quan hệ xã giao","explanation":"人 (nhân – người) + 情 (tình – tình cảm) → tình cảm thường tình của con người; còn chỉ ân huệ, món nợ ân tình và quan hệ xã giao (欠人情).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"我欠他一个人情。","pinyin":"Wǒ qiàn tā yígèrén qíng.","vi":"Tôi nợ anh ấy một ân tình."},{"type":"simple","zh":"这个小镇保留着浓浓的人情味。","pinyin":"Zhè ge xiǎozhèn bǎoliúzhe nóng nóng de rénqíngwèi.","vi":"Thị trấn nhỏ này vẫn giữ được tình người đậm đà."},{"type":"compound","zh":"虽然送礼是人情往来，但是礼物太贵就变成负担了。","pinyin":"Suīrán sònglǐ shì rénqíng wǎnglái, dànshì lǐwù tài guì jiù biànchéng fùdān le.","vi":"Tuy tặng quà là chuyện qua lại xã giao, nhưng quà quá đắt thì lại thành gánh nặng."}],"related":[{"hanzi":"人情味","pinyin":"rénqíngwèi","vi":"tình người"},{"hanzi":"情面","pinyin":"qíngmiàn","vi":"thể diện, nể nang"},{"hanzi":"关系","pinyin":"guānxi","vi":"quan hệ"},{"hanzi":"恩情","pinyin":"ēnqíng","vi":"ân tình"}]},{"id":"人身","hanzi":"人身","pinyin":"rénshēn","meaning_vi":"thân thể con người, (thuộc) cá nhân","explanation":"人 (nhân – người) + 身 (thân – thân thể) → thân thể, sinh mạng và quyền cá nhân của con người; hay dùng trong 人身安全, 人身攻击.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🛡️","examples":[{"type":"basic","zh":"请注意人身安全。","pinyin":"Qǐng zhùyì rénshēn'ānquán.","vi":"Hãy chú ý an toàn bản thân."},{"type":"simple","zh":"网上讨论问题不应该进行人身攻击。","pinyin":"Wǎngshàng tǎolùn wèntí bù yīnggāi jìnxíng rénshēn gōngjī.","vi":"Thảo luận trên mạng không nên công kích cá nhân."},{"type":"compound","zh":"如果有人威胁你的人身安全，就要马上报警。","pinyin":"Rúguǒ yǒurén wēixié nǐ de rénshēn'ānquán, jiùyào mǎshàng bàojǐng.","vi":"Nếu có người đe dọa an toàn thân thể bạn thì phải báo cảnh sát ngay."}],"related":[{"hanzi":"人身自由","pinyin":"rénshēnzìyóu","vi":"tự do thân thể"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"cơ thể"},{"hanzi":"人身攻击","pinyin":"rénshēngōngjī","vi":"công kích cá nhân"},{"hanzi":"本人","pinyin":"běnrén","vi":"bản thân"}]},{"id":"人手","hanzi":"人手","pinyin":"rénshǒu","meaning_vi":"nhân lực, người làm","explanation":"人 (nhân – người) + 手 (thủ – tay) → người làm việc, nhân lực; thường nói 人手不够 (thiếu người).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🙋","examples":[{"type":"basic","zh":"店里人手不够。","pinyin":"Diàn lǐ rénshǒu búgòu.","vi":"Cửa hàng không đủ người làm."},{"type":"simple","zh":"节假日期间餐厅需要临时增加人手。","pinyin":"Jiéjiàrì qījiān cāntīng xūyào línshí zēngjiā rénshǒu.","vi":"Dịp lễ, nhà hàng cần tăng thêm nhân lực tạm thời."},{"type":"compound","zh":"因为人手太少，所以这个项目恐怕不能按时完成。","pinyin":"Yīnwèi rénshǒu tài shǎo, suǒyǐ zhè ge xiàngmù kǒngpà bù néng ànshí wánchéng.","vi":"Vì quá ít người nên dự án này e là không thể hoàn thành đúng hạn."}],"related":[{"hanzi":"人力","pinyin":"rénlì","vi":"nhân lực"},{"hanzi":"人员","pinyin":"rényuán","vi":"nhân viên"},{"hanzi":"帮手","pinyin":"bāngshou","vi":"người giúp việc"},{"hanzi":"劳动力","pinyin":"láodònglì","vi":"sức lao động"}]},{"id":"人行道","hanzi":"人行道","pinyin":"rénxíngdào","meaning_vi":"vỉa hè, lối đi bộ","explanation":"人 (nhân – người) + 行 (hành – đi) + 道 (đạo – đường) → phần đường dành cho người đi bộ.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚶","examples":[{"type":"basic","zh":"请走人行道。","pinyin":"Qǐng zǒurén xíngdào.","vi":"Hãy đi trên vỉa hè."},{"type":"simple","zh":"很多电动车停在人行道上挡住了路。","pinyin":"Hěn duō diàndòngchē tíng zài rénxíngdào shàng dǎngzhùle lù.","vi":"Nhiều xe điện đỗ trên vỉa hè chắn hết lối đi."},{"type":"compound","zh":"如果人行道被占用，行人就只能走到马路上。","pinyin":"Rúguǒ rénxíngdào bèi zhànyòng, xíngrén jiù zhǐnéng zǒu dào mǎ lùshàng.","vi":"Nếu vỉa hè bị chiếm dụng thì người đi bộ đành phải đi xuống lòng đường."}],"related":[{"hanzi":"斑马线","pinyin":"bānmǎxiàn","vi":"vạch qua đường"},{"hanzi":"马路","pinyin":"mǎlù","vi":"đường cái"},{"hanzi":"行人","pinyin":"xíngrén","vi":"người đi bộ"},{"hanzi":"人行横道","pinyin":"rénxínghéngdào","vi":"lối sang đường"}]},{"id":"人缘儿","hanzi":"人缘儿","pinyin":"rényuánr","meaning_vi":"quan hệ với mọi người, sự được lòng người","explanation":"人 (nhân – người) + 缘 (duyên – duyên phận) + 儿 (âm cuộn lưỡi) → mối quan hệ với người xung quanh; 人缘儿好 nghĩa là được nhiều người quý mến.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"😊","examples":[{"type":"basic","zh":"她人缘儿特别好。","pinyin":"Tā rényuánr tèbié hǎo.","vi":"Cô ấy rất được lòng mọi người."},{"type":"simple","zh":"老王在我们小区里很有人缘儿。","pinyin":"Lǎo Wáng zài wǒmen xiǎoqū lǐ hěn yǒu rényuánr.","vi":"Ông Vương rất được lòng mọi người trong khu chung cư."},{"type":"compound","zh":"因为他总是乐于帮助别人，所以人缘儿一直很好。","pinyin":"Yīnwèi tā zǒngshì lèyú bāngzhù biérén, suǒyǐ rényuánr yìzhí hěn hǎo.","vi":"Vì anh ấy luôn vui vẻ giúp đỡ người khác nên luôn được mọi người quý mến."}],"related":[{"hanzi":"人缘","pinyin":"rényuán","vi":"quan hệ với mọi người"},{"hanzi":"人脉","pinyin":"rénmài","vi":"mạng lưới quan hệ"},{"hanzi":"受欢迎","pinyin":"shòuhuānyíng","vi":"được yêu thích"},{"hanzi":"缘分","pinyin":"yuánfèn","vi":"duyên phận"}],"traditional":"人緣兒"},{"id":"忍饥挨饿","hanzi":"忍饥挨饿","pinyin":"rěnjī-ái'è","meaning_vi":"chịu đói chịu khát, nhịn đói","explanation":"忍 (nhẫn – chịu đựng) + 饥 (cơ – đói) + 挨 (ai – chịu) + 饿 (ngạ – đói) → chịu đựng cảnh đói khát, sống thiếu thốn.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😣","examples":[{"type":"basic","zh":"他们曾经忍饥挨饿。","pinyin":"Tāmen céngjīng rěnjī'ái'è.","vi":"Họ từng phải chịu đói."},{"type":"simple","zh":"战争年代很多百姓不得不忍饥挨饿。","pinyin":"Zhànzhēng niándài hěn duō bǎixìng bùdébù rěnjī'ái'è.","vi":"Thời chiến tranh nhiều người dân buộc phải chịu cảnh đói khát."},{"type":"compound","zh":"虽然小时候常常忍饥挨饿，但是他从不抱怨生活。","pinyin":"Suīrán xiǎoshíhou chángcháng rěnjī'ái'è, dànshì tā cóng bú bàoyuàn shēnghuó.","vi":"Tuy hồi nhỏ thường xuyên chịu đói nhưng anh ấy chưa bao giờ than phiền về cuộc sống."}],"related":[{"hanzi":"饥饿","pinyin":"jī'è","vi":"đói"},{"hanzi":"挨饿","pinyin":"ái'è","vi":"chịu đói"},{"hanzi":"饥寒交迫","pinyin":"jīhánjiāopò","vi":"đói rét cùng cực"},{"hanzi":"温饱","pinyin":"wēnbǎo","vi":"no ấm"}],"traditional":"忍飢挨餓"},{"id":"忍心","hanzi":"忍心","pinyin":"rěnxīn","meaning_vi":"nỡ lòng, đành lòng","explanation":"忍 (nhẫn – nén lòng) + 心 (tâm – lòng) → nén lòng làm việc khó nỡ; thường dùng phủ định 不忍心 (không nỡ).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"我不忍心拒绝她。","pinyin":"Wǒ bù rěnxīn jùjué tā.","vi":"Tôi không nỡ từ chối cô ấy."},{"type":"simple","zh":"你怎么忍心把小猫扔在路边？","pinyin":"Nǐ zěnme rěnxīn bǎ xiǎomāo rēng zài lùbiān?","vi":"Sao bạn nỡ vứt con mèo con bên đường?"},{"type":"compound","zh":"虽然孩子哭得很伤心，但是妈妈还是忍心把他送去了幼儿园。","pinyin":"Suīrán háizi kū de hěn shāngxīn, dànshì māma háishì rěnxīn bǎ tā sòngqùle yòu'éryuán.","vi":"Tuy con khóc rất đau lòng nhưng mẹ vẫn đành lòng đưa con đến nhà trẻ."}],"related":[{"hanzi":"不忍","pinyin":"bùrěn","vi":"không nỡ"},{"hanzi":"狠心","pinyin":"hěnxīn","vi":"nhẫn tâm"},{"hanzi":"舍得","pinyin":"shěde","vi":"nỡ, chịu bỏ"},{"hanzi":"忍耐","pinyin":"rěnnài","vi":"nhẫn nại"}]},{"id":"认错","hanzi":"认错","pinyin":"rèncuò","meaning_vi":"nhận lỗi; nhận nhầm","explanation":"认 (nhận – thừa nhận) + 错 (thác – lỗi) → thừa nhận sai lầm; cũng có nghĩa nhận nhầm (认错人).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😔","examples":[{"type":"basic","zh":"他终于认错了。","pinyin":"Tā zhōngyú rèncuò le.","vi":"Cuối cùng anh ấy đã nhận lỗi."},{"type":"simple","zh":"孩子低着头向老师认错。","pinyin":"Háizi dīzhe tóu xiàng lǎoshī rèncuò.","vi":"Đứa bé cúi đầu nhận lỗi với cô giáo."},{"type":"compound","zh":"只要你真心认错，大家就会原谅你。","pinyin":"Zhǐyào nǐ zhēnxīn rèncuò, dàjiā jiù huì yuánliàng nǐ.","vi":"Chỉ cần bạn thật lòng nhận lỗi thì mọi người sẽ tha thứ cho bạn."}],"related":[{"hanzi":"道歉","pinyin":"dàoqiàn","vi":"xin lỗi"},{"hanzi":"认罪","pinyin":"rènzuì","vi":"nhận tội"},{"hanzi":"承认","pinyin":"chéngrèn","vi":"thừa nhận"},{"hanzi":"改错","pinyin":"gǎicuò","vi":"sửa lỗi"}],"traditional":"認錯"},{"id":"认证","hanzi":"认证","pinyin":"rènzhèng","meaning_vi":"chứng nhận, xác thực","explanation":"认 (nhận – công nhận) + 证 (chứng – chứng minh) → cơ quan có thẩm quyền xác nhận, chứng nhận; cũng chỉ xác thực danh tính trên mạng.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"✅","examples":[{"type":"basic","zh":"这款产品通过了认证。","pinyin":"Zhè kuǎn chǎnpǐn tōngguòle rènzhèng.","vi":"Sản phẩm này đã đạt chứng nhận."},{"type":"simple","zh":"注册账号以后需要进行实名认证。","pinyin":"Zhùcè zhànghào yǐhòu xūyào jìnxíng shímíng rènzhèng.","vi":"Sau khi đăng ký tài khoản cần xác thực danh tính."},{"type":"compound","zh":"如果没有通过质量认证，产品就不能出口。","pinyin":"Rúguǒ méiyǒu tōngguò zhìliàng rènzhèng, chǎnpǐn jiù bù néng chūkǒu.","vi":"Nếu không đạt chứng nhận chất lượng thì sản phẩm không thể xuất khẩu."}],"related":[{"hanzi":"认可","pinyin":"rènkě","vi":"công nhận"},{"hanzi":"证书","pinyin":"zhèngshū","vi":"chứng chỉ"},{"hanzi":"验证","pinyin":"yànzhèng","vi":"xác minh"},{"hanzi":"实名","pinyin":"shímíng","vi":"tên thật"}],"traditional":"認證"},{"id":"认知","hanzi":"认知","pinyin":"rènzhī","meaning_vi":"nhận thức, sự hiểu biết","explanation":"认 (nhận – nhận biết) + 知 (tri – hiểu biết) → quá trình nhận biết, hiểu biết thế giới; thuật ngữ tâm lý học là “nhận thức”.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"每个人的认知不同。","pinyin":"Měigèrén de rènzhī bùtóng.","vi":"Nhận thức của mỗi người khác nhau."},{"type":"simple","zh":"多读书能提高一个人的认知水平。","pinyin":"Duō dúshū néng tígāo yígèrén de rènzhī shuǐpíng.","vi":"Đọc nhiều sách có thể nâng cao trình độ nhận thức của một người."},{"type":"compound","zh":"因为年龄还小，所以孩子对危险的认知非常有限。","pinyin":"Yīnwèi niánlíng hái xiǎo, suǒyǐ háizi duì wēixiǎn de rènzhī fēicháng yǒuxiàn.","vi":"Vì còn nhỏ tuổi nên nhận thức của trẻ về nguy hiểm rất hạn chế."}],"related":[{"hanzi":"认识","pinyin":"rènshi","vi":"nhận biết"},{"hanzi":"意识","pinyin":"yìshí","vi":"ý thức"},{"hanzi":"认知能力","pinyin":"rènzhīnénglì","vi":"năng lực nhận thức"},{"hanzi":"感知","pinyin":"gǎnzhī","vi":"cảm nhận"}],"traditional":"認知"},{"id":"任期","hanzi":"任期","pinyin":"rènqī","meaning_vi":"nhiệm kỳ","explanation":"任 (nhiệm – chức vụ) + 期 (kỳ – thời hạn) → khoảng thời gian giữ một chức vụ.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🗳️","examples":[{"type":"basic","zh":"他的任期是五年。","pinyin":"Tā de rènqī shì wǔ nián.","vi":"Nhiệm kỳ của ông ấy là năm năm."},{"type":"simple","zh":"新校长在任期内建了一座图书馆。","pinyin":"Xīn xiàozhǎng zài rènqī nèijiànle yí zuò túshūguǎn.","vi":"Hiệu trưởng mới đã xây một thư viện trong nhiệm kỳ của mình."},{"type":"compound","zh":"虽然任期只剩一年，但是他仍然推出了很多新政策。","pinyin":"Suīrán rènqī zhǐ shèng yì nián, dànshì tā réngrán tuīchūle hěn duō xīn zhèngcè.","vi":"Tuy nhiệm kỳ chỉ còn một năm nhưng ông ấy vẫn đưa ra nhiều chính sách mới."}],"related":[{"hanzi":"任职","pinyin":"rènzhí","vi":"giữ chức"},{"hanzi":"连任","pinyin":"liánrèn","vi":"tái nhiệm"},{"hanzi":"卸任","pinyin":"xièrèn","vi":"mãn nhiệm"},{"hanzi":"届","pinyin":"jiè","vi":"khóa, kỳ"}]},{"id":"任人宰割","hanzi":"任人宰割","pinyin":"rènrén-zǎigē","meaning_vi":"mặc người chém giết, để người ta tùy ý chà đạp","explanation":"任 (nhậm – mặc cho) + 人 (nhân – người) + 宰割 (tể cát – mổ xẻ) → như con vật để mặc người mổ xẻ; nghĩa bóng là bị áp bức, lợi dụng mà không thể chống lại.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔪","examples":[{"type":"basic","zh":"我们不能任人宰割。","pinyin":"Wǒmen bù néng rènrénzǎigē.","vi":"Chúng ta không thể để người khác tùy ý chà đạp."},{"type":"simple","zh":"落后的国家往往只能任人宰割。","pinyin":"Luòhòu de guójiā wǎngwǎng zhǐnéng rènrénzǎigē.","vi":"Quốc gia lạc hậu thường chỉ đành để mặc người khác chà đạp."},{"type":"compound","zh":"如果不懂法律，就可能在合同纠纷中任人宰割。","pinyin":"Rúguǒ bù dǒng fǎlǜ, jiù kěnéng zài hétong jiūfēn zhōng rènrénzǎigē.","vi":"Nếu không hiểu luật thì có thể bị người ta chèn ép trong tranh chấp hợp đồng."}],"related":[{"hanzi":"宰割","pinyin":"zǎigē","vi":"chém giết, xâu xé"},{"hanzi":"欺负","pinyin":"qīfu","vi":"bắt nạt"},{"hanzi":"逆来顺受","pinyin":"nìláishùnshòu","vi":"cam chịu"},{"hanzi":"任意","pinyin":"rènyì","vi":"tùy ý"}]},{"id":"韧性","hanzi":"韧性","pinyin":"rènxìng","meaning_vi":"độ dẻo dai, sức bền bỉ","explanation":"韧 (nhận – dai, bền) + 性 (tính – tính chất) → tính dai, khó đứt gãy của vật liệu; nghĩa bóng là sự bền bỉ, kiên cường.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🎋","examples":[{"type":"basic","zh":"竹子很有韧性。","pinyin":"Zhúzi hěn yǒu rènxìng.","vi":"Tre rất dẻo dai."},{"type":"simple","zh":"这种新材料的韧性比钢铁还要好。","pinyin":"Zhè zhǒng xīn cáiliào de rènxìng bǐ gāngtiě hái yàohǎo.","vi":"Độ dẻo dai của loại vật liệu mới này còn tốt hơn thép."},{"type":"compound","zh":"虽然经历了很多挫折，但是她表现出了惊人的韧性。","pinyin":"Suīrán jīnglìle hěn duō cuòzhé, dànshì tā biǎoxiàn chūle jīngrén de rènxìng.","vi":"Tuy trải qua nhiều thất bại nhưng cô ấy thể hiện sự bền bỉ đáng kinh ngạc."}],"related":[{"hanzi":"坚韧","pinyin":"jiānrèn","vi":"bền bỉ"},{"hanzi":"弹性","pinyin":"tánxìng","vi":"tính đàn hồi"},{"hanzi":"毅力","pinyin":"yìlì","vi":"nghị lực"},{"hanzi":"脆弱","pinyin":"cuìruò","vi":"mong manh"}],"traditional":"韌性"},{"id":"日复一日","hanzi":"日复一日","pinyin":"rìfù-yīrì","meaning_vi":"ngày này qua ngày khác","explanation":"日 (nhật – ngày) + 复 (phục – lặp lại) + 一日 (nhất nhật – một ngày) → ngày qua ngày lặp lại như nhau, chỉ sự đều đặn lâu dài hoặc nhàm chán.","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"📆","examples":[{"type":"basic","zh":"他日复一日地练琴。","pinyin":"Tā rìfùyīrì de liàn qín.","vi":"Anh ấy luyện đàn ngày này qua ngày khác."},{"type":"simple","zh":"日复一日的加班让她感到非常疲惫。","pinyin":"Rìfùyīrì de jiābān ràng tā gǎndào fēicháng píbèi.","vi":"Ngày nào cũng tăng ca khiến cô ấy cảm thấy rất mệt mỏi."},{"type":"compound","zh":"虽然工作日复一日地重复，但是他从来不觉得无聊。","pinyin":"Suīrán gōngzuò rìfùyīrì de chóngfù, dànshì tā cóngláibù juéde wúliáo.","vi":"Tuy công việc lặp đi lặp lại ngày qua ngày nhưng anh ấy chưa bao giờ thấy chán."}],"related":[{"hanzi":"年复一年","pinyin":"niánfùyìnián","vi":"năm này qua năm khác"},{"hanzi":"天天","pinyin":"tiāntiān","vi":"ngày ngày"},{"hanzi":"日积月累","pinyin":"rìjīyuèlěi","vi":"tích lũy theo ngày tháng"},{"hanzi":"周而复始","pinyin":"zhōu'érfùshǐ","vi":"lặp đi lặp lại"}],"traditional":"日復一日"},{"id":"日后","hanzi":"日后","pinyin":"rìhòu","meaning_vi":"sau này, mai sau","explanation":"日 (nhật – ngày) + 后 (hậu – sau) → những ngày sau này, tương lai.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🔮","examples":[{"type":"basic","zh":"日后再说吧。","pinyin":"Rìhòu zàishuō ba.","vi":"Để sau này hãy nói."},{"type":"simple","zh":"这些经验对你日后的工作很有帮助。","pinyin":"Zhèxiē jīngyàn duì nǐ rìhòu de gōngzuò hěn yǒubāngzhù.","vi":"Những kinh nghiệm này rất có ích cho công việc của bạn sau này."},{"type":"compound","zh":"如果现在不打好基础，日后就会遇到更多麻烦。","pinyin":"Rúguǒ xiànzài bù dǎ hǎo jīchǔ, rìhòu jiù huì yùdào gèng duō máfan.","vi":"Nếu bây giờ không xây nền tảng vững thì sau này sẽ gặp nhiều rắc rối hơn."}],"related":[{"hanzi":"今后","pinyin":"jīnhòu","vi":"từ nay về sau"},{"hanzi":"将来","pinyin":"jiānglái","vi":"tương lai"},{"hanzi":"以后","pinyin":"yǐhòu","vi":"sau này"},{"hanzi":"日前","pinyin":"rìqián","vi":"mấy hôm trước"}],"traditional":"日後"},{"id":"日前","hanzi":"日前","pinyin":"rìqián","meaning_vi":"mấy hôm trước, gần đây","explanation":"日 (nhật – ngày) + 前 (tiền – trước) → mấy ngày trước; thường dùng trong văn viết, tin tức.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🗓️","examples":[{"type":"basic","zh":"新馆日前正式开放。","pinyin":"Xīn guǎn rìqián zhèngshì kāifàng.","vi":"Bảo tàng mới vừa chính thức mở cửa mấy hôm trước."},{"type":"simple","zh":"有关部门日前公布了新的交通规定。","pinyin":"Yǒuguān bùmén rìqián gōngbùle xīn de jiāotōng guīdìng.","vi":"Mấy hôm trước cơ quan hữu quan đã công bố quy định giao thông mới."},{"type":"compound","zh":"因为日前下了一场暴雨，所以山路暂时封闭了。","pinyin":"Yīnwèi rìqián xiàle yì chǎng bàoyǔ, suǒyǐ shānlù zànshí fēngbì le.","vi":"Vì mấy hôm trước có trận mưa lớn nên đường núi tạm thời bị phong tỏa."}],"related":[{"hanzi":"近日","pinyin":"jìnrì","vi":"gần đây"},{"hanzi":"前几天","pinyin":"qiánjǐtiān","vi":"mấy hôm trước"},{"hanzi":"日后","pinyin":"rìhòu","vi":"sau này"},{"hanzi":"目前","pinyin":"mùqián","vi":"hiện nay"}]},{"id":"日趋","hanzi":"日趋","pinyin":"rìqū","meaning_vi":"ngày càng, mỗi ngày một","explanation":"日 (nhật – ngày) + 趋 (xu – hướng tới) → ngày một hướng về một trạng thái nào đó; đứng trước tính từ hai âm tiết, dùng trong văn viết.","hsk_level":"7-9","tags":["pho-tu"],"image":"⏫","examples":[{"type":"basic","zh":"竞争日趋激烈。","pinyin":"Jìngzhēng rìqū jīliè.","vi":"Cạnh tranh ngày càng gay gắt."},{"type":"simple","zh":"这座城市的交通状况日趋改善。","pinyin":"Zhè zuò chéngshì de jiāotōng zhuàngkuàng rìqū gǎishàn.","vi":"Tình hình giao thông thành phố này ngày càng được cải thiện."},{"type":"compound","zh":"虽然两国关系日趋紧张，但是民间交流并没有中断。","pinyin":"Suīrán liǎngguó guānxì rìqū jǐnzhāng, dànshì mínjiān jiāoliú bìng méiyǒu zhōngduàn.","vi":"Tuy quan hệ hai nước ngày càng căng thẳng nhưng giao lưu dân gian không hề gián đoạn."}],"related":[{"hanzi":"日益","pinyin":"rìyì","vi":"ngày càng"},{"hanzi":"逐渐","pinyin":"zhújiàn","vi":"dần dần"},{"hanzi":"趋势","pinyin":"qūshì","vi":"xu thế"},{"hanzi":"越来越","pinyin":"yuèláiyuè","vi":"càng ngày càng"}],"traditional":"日趨"},{"id":"荣获","hanzi":"荣获","pinyin":"rónghuò","meaning_vi":"vinh dự giành được, đoạt (giải)","explanation":"荣 (vinh – vinh dự) + 获 (hoạch – đạt được) → vinh dự giành được giải thưởng, danh hiệu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏆","examples":[{"type":"basic","zh":"他荣获了一等奖。","pinyin":"Tā rónghuòle yìděngjiǎng.","vi":"Anh ấy vinh dự giành giải nhất."},{"type":"simple","zh":"这部电影荣获了最佳导演奖。","pinyin":"Zhè bù diànyǐng rónghuòle zuì jiā dǎoyǎn jiǎng.","vi":"Bộ phim này đã đoạt giải Đạo diễn xuất sắc nhất."},{"type":"compound","zh":"因为她在抗疫中表现突出，所以荣获了先进个人称号。","pinyin":"Yīnwèi tā zài kàngyì zhōng biǎoxiàn tūchū, suǒyǐ rónghuòle xiānjìn gèrén chēnghào.","vi":"Vì có thành tích nổi bật trong chống dịch nên cô ấy được trao danh hiệu cá nhân tiên tiến."}],"related":[{"hanzi":"获得","pinyin":"huòdé","vi":"đạt được"},{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"获奖","pinyin":"huòjiǎng","vi":"đoạt giải"},{"hanzi":"光荣","pinyin":"guāngróng","vi":"vẻ vang"}],"traditional":"榮獲"},{"id":"容光焕发","hanzi":"容光焕发","pinyin":"róngguāng-huànfā","meaning_vi":"mặt mày rạng rỡ, tươi tắn","explanation":"容光 (dung quang – vẻ sáng trên mặt) + 焕发 (hoán phát – tỏa sáng) → nét mặt sáng bừng, tràn đầy sức sống.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"她今天容光焕发。","pinyin":"Tā jīntiān róngguānghuànfā.","vi":"Hôm nay cô ấy trông rạng rỡ."},{"type":"simple","zh":"度假回来的爸爸显得容光焕发。","pinyin":"Dùjià huílái de bàba xiǎnde róngguānghuànfā.","vi":"Bố đi nghỉ về trông tươi tỉnh hẳn."},{"type":"compound","zh":"因为最近睡眠充足，所以她每天都容光焕发。","pinyin":"Yīnwèi zuìjìn shuìmián chōngzú, suǒyǐ tā měitiān dōu róngguānghuànfā.","vi":"Vì dạo này ngủ đủ giấc nên ngày nào cô ấy cũng rạng rỡ."}],"related":[{"hanzi":"神采奕奕","pinyin":"shéncǎiyìyì","vi":"tinh thần phấn chấn"},{"hanzi":"精神焕发","pinyin":"jīngshénhuànfā","vi":"tinh thần phấn khởi"},{"hanzi":"满面春风","pinyin":"mǎnmiànchūnfēng","vi":"mặt mày hớn hở"},{"hanzi":"憔悴","pinyin":"qiáocuì","vi":"tiều tụy"}],"traditional":"容光煥發"},{"id":"容量","hanzi":"容量","pinyin":"róngliàng","meaning_vi":"dung lượng, sức chứa","explanation":"容 (dung – chứa) + 量 (lượng – lượng) → lượng tối đa có thể chứa được.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💾","examples":[{"type":"basic","zh":"这个硬盘容量很大。","pinyin":"Zhè ge yìngpán róngliàng hěn dà.","vi":"Ổ cứng này dung lượng rất lớn."},{"type":"simple","zh":"这个保温杯的容量是五百毫升。","pinyin":"Zhè ge bǎowēnbēi de róngliàng shì wǔ bǎi háoshēng.","vi":"Dung tích của bình giữ nhiệt này là 500 ml."},{"type":"compound","zh":"如果手机存储容量不够，就删掉一些旧照片吧。","pinyin":"Rúguǒ shǒujī cúnchǔ róngliàng búgòu, jiù shāndiào yìxiē jiù zhàopiàn ba.","vi":"Nếu bộ nhớ điện thoại không đủ thì xóa bớt một số ảnh cũ đi."}],"related":[{"hanzi":"容积","pinyin":"róngjī","vi":"dung tích"},{"hanzi":"内存","pinyin":"nèicún","vi":"bộ nhớ"},{"hanzi":"容纳","pinyin":"róngnà","vi":"chứa"},{"hanzi":"存储","pinyin":"cúnchǔ","vi":"lưu trữ"}]},{"id":"容许","hanzi":"容许","pinyin":"róngxǔ","meaning_vi":"cho phép, dung thứ","explanation":"容 (dung – dung chứa) + 许 (hứa – cho phép) → cho phép, chấp nhận điều gì xảy ra.","hsk_level":"7-9","tags":["dong-tu"],"image":"👌","examples":[{"type":"basic","zh":"时间不容许拖延。","pinyin":"Shíjiān bù róngxǔ tuōyán.","vi":"Thời gian không cho phép trì hoãn."},{"type":"simple","zh":"这种严重的错误绝对不容许再发生。","pinyin":"Zhè zhǒng yánzhòng de cuòwù juéduì bù róngxǔ zài fāshēng.","vi":"Lỗi nghiêm trọng như thế này tuyệt đối không được để xảy ra nữa."},{"type":"compound","zh":"如果条件容许，我们就去国外旅行一次。","pinyin":"Rúguǒ tiáojiàn róngxǔ, wǒmen jiù qù guówài lǚxíng yí cì.","vi":"Nếu điều kiện cho phép, chúng ta sẽ đi du lịch nước ngoài một chuyến."}],"related":[{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"cho phép"},{"hanzi":"容忍","pinyin":"róngrěn","vi":"dung nhẫn"},{"hanzi":"许可","pinyin":"xǔkě","vi":"giấy phép"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"cấm"}],"traditional":"容許"},{"id":"容颜","hanzi":"容颜","pinyin":"róngyán","meaning_vi":"dung nhan, khuôn mặt","explanation":"容 (dung – dáng vẻ) + 颜 (nhan – mặt) → dung mạo, nét mặt; từ mang sắc thái văn chương.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"👩","examples":[{"type":"basic","zh":"她的容颜依旧美丽。","pinyin":"Tā de róngyán yījiù měilì.","vi":"Dung nhan bà vẫn đẹp như xưa."},{"type":"simple","zh":"岁月在母亲的容颜上留下了痕迹。","pinyin":"Suìyuè zài mǔqīn de róngyán shàng liúxiàle hénjì.","vi":"Năm tháng đã để lại dấu vết trên khuôn mặt mẹ."},{"type":"compound","zh":"虽然容颜会慢慢老去，但是善良的心永远美丽。","pinyin":"Suīrán róngyán huì mànmàn lǎoqù, dànshì shànliáng de xīn yǒngyuǎn měilì.","vi":"Tuy dung nhan sẽ dần già đi nhưng tấm lòng lương thiện mãi mãi đẹp."}],"related":[{"hanzi":"容貌","pinyin":"róngmào","vi":"dung mạo"},{"hanzi":"面容","pinyin":"miànróng","vi":"gương mặt"},{"hanzi":"颜值","pinyin":"yánzhí","vi":"độ đẹp (ngoại hình)"},{"hanzi":"美貌","pinyin":"měimào","vi":"sắc đẹp"}],"traditional":"容顏"},{"id":"融","hanzi":"融","pinyin":"róng","meaning_vi":"tan chảy; hòa hợp, dung hòa","explanation":"融 (dung – tan, hòa) → tan chảy (冰雪融化); nghĩa rộng là hòa nhập, hòa trộn làm một (融为一体).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧊","examples":[{"type":"basic","zh":"春天雪融了。","pinyin":"Chūntiān xuě róng le.","vi":"Mùa xuân tuyết tan rồi."},{"type":"simple","zh":"他很快就融入了新的集体。","pinyin":"Tā hěn kuài jiù róngrùle xīn de jítǐ.","vi":"Anh ấy nhanh chóng hòa nhập vào tập thể mới."},{"type":"compound","zh":"只要大家真诚相待，不同的文化也能融为一体。","pinyin":"Zhǐyào dàjiā zhēnchéng xiāngdài, bùtóng de wénhuà yě néng róngwéiyìtǐ.","vi":"Chỉ cần mọi người đối xử chân thành, các nền văn hóa khác nhau cũng có thể hòa làm một."}],"related":[{"hanzi":"融化","pinyin":"rónghuà","vi":"tan chảy"},{"hanzi":"融合","pinyin":"rónghé","vi":"dung hợp"},{"hanzi":"融入","pinyin":"róngrù","vi":"hòa nhập"},{"hanzi":"交融","pinyin":"jiāoróng","vi":"hòa quyện"}]},{"id":"冗长","hanzi":"冗长","pinyin":"rǒngcháng","meaning_vi":"dài dòng, lê thê","explanation":"冗 (nhũng – thừa thãi) + 长 (trường – dài) → dài dòng, thừa thãi, gây nhàm chán; dùng cho bài viết, phát biểu, cuộc họp.","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"🥱","examples":[{"type":"basic","zh":"这篇文章太冗长了。","pinyin":"Zhè piān wénzhāng tài rǒngcháng le.","vi":"Bài viết này quá dài dòng."},{"type":"simple","zh":"冗长的会议让大家都昏昏欲睡。","pinyin":"Rǒngcháng de huìyì ràng dàjiā dōu hūn hūn yù shuì.","vi":"Cuộc họp lê thê khiến ai cũng buồn ngủ."},{"type":"compound","zh":"如果报告写得太冗长，领导就没耐心看完。","pinyin":"Rúguǒ bàogào xiě de tài rǒngcháng, lǐngdǎo jiù méi nàixīn kàn wán.","vi":"Nếu báo cáo viết quá dài dòng thì lãnh đạo sẽ không đủ kiên nhẫn đọc hết."}],"related":[{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"lắm lời"},{"hanzi":"简洁","pinyin":"jiǎnjié","vi":"ngắn gọn"},{"hanzi":"冗余","pinyin":"rǒngyú","vi":"dư thừa"},{"hanzi":"繁琐","pinyin":"fánsuǒ","vi":"rườm rà"}],"traditional":"冗長"},{"id":"如果说","hanzi":"如果说","pinyin":"rúguǒshuō","meaning_vi":"nếu nói rằng, nếu như","explanation":"如果 (như quả – nếu) + 说 (thuyết – nói) → “nếu nói rằng…”; hay dùng để so sánh, đối chiếu: 如果说A是…，那么B就是….","hsk_level":"7-9","tags":["lien-tu"],"image":"🤔","examples":[{"type":"basic","zh":"如果说这是缘分呢？","pinyin":"Rúguǒshuō zhè shì yuánfèn ne?","vi":"Nếu nói đây là duyên phận thì sao?"},{"type":"simple","zh":"如果说有遗憾，那就是没去长城。","pinyin":"Rúguǒshuō yǒu yíhàn, nà jiùshì méi qù Chángchéng.","vi":"Nếu nói có điều gì tiếc nuối, thì đó là chưa được đi Vạn Lý Trường Thành."},{"type":"compound","zh":"如果说青春是一首歌，那么友情就是其中最美的旋律。","pinyin":"Rúguǒshuō qīngchūn shì yìshǒugē, nàme yǒuqíng jiùshì qízhōng zuì měi de xuánlǜ.","vi":"Nếu nói tuổi trẻ là một bài hát, thì tình bạn chính là giai điệu đẹp nhất trong đó."}],"related":[{"hanzi":"如果","pinyin":"rúguǒ","vi":"nếu"},{"hanzi":"假如","pinyin":"jiǎrú","vi":"giả như"},{"hanzi":"要是","pinyin":"yàoshi","vi":"nếu như"},{"hanzi":"那么","pinyin":"nàme","vi":"vậy thì"}],"traditional":"如果說"},{"id":"如醉如痴","hanzi":"如醉如痴","pinyin":"rúzuì-rúchī","meaning_vi":"say mê, ngây ngất","explanation":"如 (như – như là) + 醉 (túy – say) + 如 + 痴 (si – ngây dại) → như say như dại; nghĩa bóng là say mê, đắm chìm hoàn toàn vào điều gì.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🎵","examples":[{"type":"basic","zh":"观众听得如醉如痴。","pinyin":"Guānzhòng tīng de rúzuìrúchī.","vi":"Khán giả nghe say sưa ngây ngất."},{"type":"simple","zh":"他如醉如痴地读着那本武侠小说。","pinyin":"Tā rúzuìrúchī de dúzhe nà běn wǔxiáxiǎoshuō.","vi":"Anh ấy say mê đọc cuốn tiểu thuyết võ hiệp đó."},{"type":"compound","zh":"因为她的歌声太动人了，所以全场观众都如醉如痴。","pinyin":"Yīnwèi tā de gēshēng tài dòngrén le, suǒyǐ quánchǎng guānzhòng dōu rúzuìrúchī.","vi":"Vì giọng hát cô ấy quá cảm động nên toàn bộ khán giả đều ngây ngất."}],"related":[{"hanzi":"如痴如醉","pinyin":"rúchīrúzuì","vi":"say mê"},{"hanzi":"着迷","pinyin":"zháomí","vi":"mê mẩn"},{"hanzi":"陶醉","pinyin":"táozuì","vi":"say sưa"},{"hanzi":"入迷","pinyin":"rùmí","vi":"nhập tâm, say mê"}],"traditional":"如醉如癡"},{"id":"儒学","hanzi":"儒学","pinyin":"Rúxué","meaning_vi":"Nho học, đạo Nho","explanation":"儒 (Nho – nhà Nho) + 学 (học – học thuyết) → học thuyết của Khổng Tử và các nhà Nho.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📖","examples":[{"type":"basic","zh":"他专门研究儒学。","pinyin":"Tā zhuānmén yánjiū Rúxué.","vi":"Ông ấy chuyên nghiên cứu Nho học."},{"type":"simple","zh":"儒学对越南传统文化影响很深。","pinyin":"Rúxué duì Yuènán chuántǒng wénhuà yǐngxiǎng hěn shēn.","vi":"Nho học ảnh hưởng rất sâu đến văn hóa truyền thống Việt Nam."},{"type":"compound","zh":"虽然儒学产生于两千多年前，但是它的很多思想今天仍有价值。","pinyin":"Suīrán Rúxué chǎnshēng yú liǎng qiān duō niánqián, dànshì tā de hěn duō sīxiǎng jīntiān réng yǒujiàzhí.","vi":"Tuy Nho học ra đời từ hơn hai nghìn năm trước nhưng nhiều tư tưởng của nó ngày nay vẫn có giá trị."}],"related":[{"hanzi":"儒家","pinyin":"Rújiā","vi":"Nho gia"},{"hanzi":"孔子","pinyin":"Kǒngzǐ","vi":"Khổng Tử"},{"hanzi":"论语","pinyin":"Lúnyǔ","vi":"Luận Ngữ"},{"hanzi":"道家","pinyin":"Dàojiā","vi":"Đạo gia"}],"traditional":"儒學"},{"id":"入场","hanzi":"入场","pinyin":"rùchǎng","meaning_vi":"vào cửa, vào sân, vào hội trường","explanation":"入 (nhập – vào) + 场 (trường – nơi, sân) → đi vào địa điểm tổ chức như hội trường, sân vận động, phòng thi.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎟️","examples":[{"type":"basic","zh":"观众开始入场了。","pinyin":"Guānzhòng kāishǐ rùchǎng le.","vi":"Khán giả bắt đầu vào cửa rồi."},{"type":"simple","zh":"请大家排好队，凭票依次入场。","pinyin":"Qǐng dàjiā pái hǎo duì, píng piào yīcì rùchǎng.","vi":"Mời mọi người xếp hàng, xuất trình vé và lần lượt vào cửa."},{"type":"compound","zh":"如果你迟到超过十五分钟，就不能入场参加考试了。","pinyin":"Rúguǒ nǐ chídào chāoguò shíwǔ fēnzhōng, jiù bù néng rùchǎng cānjiā kǎoshì le.","vi":"Nếu bạn đến muộn quá mười lăm phút thì không được vào phòng thi nữa."}],"related":[{"hanzi":"入场券","pinyin":"rùchǎngquàn","vi":"vé vào cửa"},{"hanzi":"退场","pinyin":"tuìchǎng","vi":"rời sân, ra về"},{"hanzi":"进场","pinyin":"jìnchǎng","vi":"vào sân"},{"hanzi":"门票","pinyin":"ménpiào","vi":"vé vào cửa"}],"traditional":"入場"},{"id":"入侵","hanzi":"入侵","pinyin":"rùqīn","meaning_vi":"xâm nhập, xâm lược","explanation":"入 (nhập – vào) + 侵 (xâm – lấn chiếm) → tiến vào lãnh thổ hay hệ thống của người khác một cách trái phép.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"⚔️","examples":[{"type":"basic","zh":"敌军入侵了边境。","pinyin":"Díjūn rùqīnle biānjìng.","vi":"Quân địch đã xâm lược biên giới."},{"type":"simple","zh":"黑客昨晚入侵了学校的网络系统。","pinyin":"Hēikè zuówǎn rùqīnle xuéxiào de wǎngluò xìtǒng.","vi":"Tối qua tin tặc đã xâm nhập vào hệ thống mạng của trường."},{"type":"compound","zh":"一旦外来物种入侵，本地的生态平衡就可能被打破。","pinyin":"Yídàn wàilái wùzhǒng rùqīn, běndì de shēngtàipínghéng jiù kěnéng bèi dǎpò.","vi":"Một khi loài ngoại lai xâm nhập, cân bằng sinh thái bản địa có thể bị phá vỡ."}],"related":[{"hanzi":"侵略","pinyin":"qīnlüè","vi":"xâm lược"},{"hanzi":"侵犯","pinyin":"qīnfàn","vi":"xâm phạm"},{"hanzi":"入侵者","pinyin":"rùqīnzhě","vi":"kẻ xâm nhập"},{"hanzi":"防御","pinyin":"fángyù","vi":"phòng ngự"}]},{"id":"润","hanzi":"润","pinyin":"rùn","meaning_vi":"ẩm, làm ẩm, bôi trơn, bóng mượt, trau chuốt","explanation":"润 (nhuận – ẩm ướt, trơn bóng) → làm cho ẩm, mượt; nghĩa bóng là trau chuốt (润色) hoặc lợi nhuận (利润).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"💧","examples":[{"type":"basic","zh":"喝点水润润嗓子。","pinyin":"Hē diǎnshuǐ rùn run sǎngzi.","vi":"Uống chút nước cho đỡ khô họng."},{"type":"simple","zh":"冬天皮肤干，要经常抹点油润一润。","pinyin":"Dōngtiān pífū gān, yào jīngcháng mǒ diǎn yóu rùn yi rùn.","vi":"Mùa đông da khô, phải thường xuyên bôi chút kem cho ẩm."},{"type":"compound","zh":"因为这场春雨润了土地，所以庄稼长得特别好。","pinyin":"Yīnwèi zhè chǎng chūnyǔ rùnle tǔdì, suǒyǐ zhuāngjia zhǎngde tèbié hǎo.","vi":"Vì cơn mưa xuân đã làm ẩm đất nên hoa màu mọc rất tốt."}],"related":[{"hanzi":"湿润","pinyin":"shīrùn","vi":"ẩm ướt"},{"hanzi":"润滑","pinyin":"rùnhuá","vi":"bôi trơn"},{"hanzi":"滋润","pinyin":"zīrùn","vi":"tưới tắm, làm ẩm"},{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"}],"traditional":"潤"},{"id":"弱势","hanzi":"弱势","pinyin":"ruòshì","meaning_vi":"yếu thế, thế yếu","explanation":"弱 (nhược – yếu) + 势 (thế – thế lực) → ở vào vị trí yếu, ít sức mạnh; thường gặp trong cụm 弱势群体 (nhóm yếu thế).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🫂","examples":[{"type":"basic","zh":"他们处于弱势。","pinyin":"Tāmen chǔyú ruòshì.","vi":"Họ đang ở thế yếu."},{"type":"simple","zh":"社会应该多关心弱势群体的生活。","pinyin":"Shèhuì yīnggāi duō guānxīn ruòshì qúntǐ de shēnghuó.","vi":"Xã hội nên quan tâm nhiều hơn đến đời sống của nhóm yếu thế."},{"type":"compound","zh":"虽然这家小公司在市场上处于弱势，但是它的产品很有特色。","pinyin":"Suīrán zhè jiā xiǎo gōngsī zài shìchǎng shàng chǔyú ruòshì, dànshì tā de chǎnpǐn hěn yǒu tèsè.","vi":"Tuy công ty nhỏ này ở thế yếu trên thị trường nhưng sản phẩm của nó rất có nét riêng."}],"related":[{"hanzi":"强势","pinyin":"qiángshì","vi":"thế mạnh, mạnh thế"},{"hanzi":"弱者","pinyin":"ruòzhě","vi":"kẻ yếu"},{"hanzi":"劣势","pinyin":"lièshì","vi":"thế bất lợi"},{"hanzi":"弱小","pinyin":"ruòxiǎo","vi":"yếu ớt"}],"traditional":"弱勢"},{"id":"撒","hanzi":"撒","pinyin":"sā","meaning_vi":"thả, buông ra, tung, giăng (lưới); làm (nũng, nói dối)","explanation":"撒 (tát – tung ra) → buông ra, tung ra như 撒网 (giăng lưới); còn dùng trong 撒谎 (nói dối), 撒娇 (làm nũng). Đọc sǎ khi nghĩa là rắc, rải.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🎣","examples":[{"type":"basic","zh":"渔民在海上撒网。","pinyin":"Yúmín zài hǎishàng sāwǎng.","vi":"Ngư dân giăng lưới trên biển."},{"type":"simple","zh":"小女孩总喜欢跟爸爸撒娇。","pinyin":"Xiǎo nǚhái zǒng xǐhuan gēn bàba sājiāo.","vi":"Cô bé lúc nào cũng thích làm nũng với bố."},{"type":"compound","zh":"即使你撒了谎，事情的真相早晚也会被发现。","pinyin":"Jíshǐ nǐ sāle huǎng, shìqing de zhēnxiàng zǎowǎn yě huì bèi fāxiàn.","vi":"Cho dù bạn có nói dối thì sớm muộn sự thật cũng sẽ bị phát hiện."}],"related":[{"hanzi":"撒谎","pinyin":"sāhuǎng","vi":"nói dối"},{"hanzi":"撒娇","pinyin":"sājiāo","vi":"làm nũng"},{"hanzi":"撒手","pinyin":"sāshǒu","vi":"buông tay"},{"hanzi":"撒网","pinyin":"sāwǎng","vi":"giăng lưới"}]},{"id":"赛车","hanzi":"赛车","pinyin":"sàichē","meaning_vi":"đua xe, xe đua","explanation":"赛 (tái – thi đấu) + 车 (xa – xe) → cuộc đua xe hoặc chiếc xe dùng để đua.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏎️","examples":[{"type":"basic","zh":"他从小就爱赛车。","pinyin":"Tā cóngxiǎo jiù ài sàichē.","vi":"Từ nhỏ anh ấy đã mê đua xe."},{"type":"simple","zh":"这辆红色赛车的速度非常快。","pinyin":"Zhè liàng hóngsè sàichē de sùdù fēicháng kuài.","vi":"Chiếc xe đua màu đỏ này chạy cực kỳ nhanh."},{"type":"compound","zh":"虽然赛车运动很危险，但是仍然吸引了大批年轻人。","pinyin":"Suīrán sàichē yùndòng hěn wēixiǎn, dànshì réngrán xīyǐnle dàpī niánqīngrén.","vi":"Tuy môn đua xe rất nguy hiểm nhưng vẫn thu hút rất nhiều người trẻ."}],"related":[{"hanzi":"赛车手","pinyin":"sàichēshǒu","vi":"tay đua"},{"hanzi":"赛跑","pinyin":"sàipǎo","vi":"chạy đua"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"跑车","pinyin":"pǎochē","vi":"xe thể thao"}],"traditional":"賽車"},{"id":"赛跑","hanzi":"赛跑","pinyin":"sàipǎo","meaning_vi":"chạy đua, thi chạy","explanation":"赛 (tái – thi đấu) + 跑 (bào – chạy) → thi xem ai chạy nhanh hơn.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏃","examples":[{"type":"basic","zh":"我们来赛跑吧！","pinyin":"Wǒmen lái sàipǎo ba!","vi":"Chúng ta thi chạy đi!"},{"type":"simple","zh":"龟兔赛跑的故事大家都听过。","pinyin":"Guī tù sàipǎo de gùshi dàjiā dōu tīng guo.","vi":"Ai cũng từng nghe câu chuyện rùa và thỏ chạy đua."},{"type":"compound","zh":"因为他每天早上都练习，所以这次赛跑得了第一名。","pinyin":"Yīnwèi tā měitiān zǎo Shangdōu liànxí, suǒyǐ zhè cì sàipǎo déle dìyīmíng.","vi":"Vì sáng nào cũng luyện tập nên lần thi chạy này cậu ấy giành giải nhất."}],"related":[{"hanzi":"长跑","pinyin":"chángpǎo","vi":"chạy đường dài"},{"hanzi":"短跑","pinyin":"duǎnpǎo","vi":"chạy cự ly ngắn"},{"hanzi":"接力","pinyin":"jiēlì","vi":"chạy tiếp sức"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"}],"traditional":"賽跑"},{"id":"三角","hanzi":"三角","pinyin":"sānjiǎo","meaning_vi":"hình tam giác, ba góc","explanation":"三 (tam – ba) + 角 (giác – góc) → hình có ba góc; cũng chỉ lượng giác (三角学) hay quan hệ tay ba.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🔺","examples":[{"type":"basic","zh":"请画一个三角。","pinyin":"Qǐng huà yí gè sānjiǎo.","vi":"Hãy vẽ một hình tam giác."},{"type":"simple","zh":"她把三明治切成了两个三角。","pinyin":"Tā bǎ sānmíngzhì qiē chéngle liǎng gè sānjiǎo.","vi":"Cô ấy cắt bánh sandwich thành hai miếng hình tam giác."},{"type":"compound","zh":"如果三角的三条边都相等，那么它就是等边三角形。","pinyin":"Rúguǒ sānjiǎo de sāntiáo biān dōu xiāngděng, nàme tā jiùshì děng biān sānjiǎoxíng.","vi":"Nếu ba cạnh của tam giác đều bằng nhau thì đó là tam giác đều."}],"related":[{"hanzi":"三角形","pinyin":"sānjiǎoxíng","vi":"hình tam giác"},{"hanzi":"直角","pinyin":"zhíjiǎo","vi":"góc vuông"},{"hanzi":"四边形","pinyin":"sìbiānxíng","vi":"hình tứ giác"},{"hanzi":"三角洲","pinyin":"sānjiǎozhōu","vi":"châu thổ"}]},{"id":"三维","hanzi":"三维","pinyin":"sānwéi","meaning_vi":"ba chiều, 3D","explanation":"三 (tam – ba) + 维 (duy – chiều) → có ba chiều dài, rộng, cao; thường nói về hình ảnh, mô hình 3D.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🧊","examples":[{"type":"basic","zh":"这是三维动画。","pinyin":"Zhè shì sānwéi dònghuà.","vi":"Đây là phim hoạt hình 3D."},{"type":"simple","zh":"设计师用电脑做了一个三维模型。","pinyin":"Shèjìshī yòng diànnǎo zuòle yí gè sānwéi móxíng.","vi":"Nhà thiết kế dùng máy tính làm một mô hình ba chiều."},{"type":"compound","zh":"有了三维打印技术，我们就能在家里制作各种小零件。","pinyin":"Yǒule sānwéi dǎyìn jìshù, wǒmen jiù néng zài jiālǐ zhìzuò gèzhǒng xiǎo língjiàn.","vi":"Có công nghệ in 3D, chúng ta có thể tự làm đủ loại linh kiện nhỏ ở nhà."}],"related":[{"hanzi":"二维","pinyin":"èrwéi","vi":"hai chiều"},{"hanzi":"立体","pinyin":"lìtǐ","vi":"lập thể"},{"hanzi":"维度","pinyin":"wéidù","vi":"chiều, số chiều"},{"hanzi":"平面","pinyin":"píngmiàn","vi":"mặt phẳng"}],"traditional":"三維"},{"id":"桑拿","hanzi":"桑拿","pinyin":"sāngná","meaning_vi":"xông hơi, phòng tắm hơi (sauna)","explanation":"Từ phiên âm của “sauna” → tắm hơi khô kiểu Phần Lan; thường nói 洗桑拿 (đi xông hơi).","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"🧖","examples":[{"type":"basic","zh":"他喜欢洗桑拿。","pinyin":"Tā xǐhuan xǐ sāngná.","vi":"Anh ấy thích đi xông hơi."},{"type":"simple","zh":"健身以后去蒸个桑拿特别舒服。","pinyin":"Jiànshēn yǐhòu qù zhēng ge sāngná tèbié shūfu.","vi":"Tập gym xong đi xông hơi một chút thì cực kỳ dễ chịu."},{"type":"compound","zh":"虽然桑拿能让人放松，但是心脏不好的人最好别去。","pinyin":"Suīrán sāngná néng ràng rén fàngsōng, dànshì xīnzàng bù hǎo de rén zuìhǎo bié qù.","vi":"Tuy xông hơi giúp thư giãn nhưng người yếu tim tốt nhất đừng đi."}],"related":[{"hanzi":"蒸汽","pinyin":"zhēngqì","vi":"hơi nước"},{"hanzi":"洗浴","pinyin":"xǐyù","vi":"tắm rửa"},{"hanzi":"温泉","pinyin":"wēnquán","vi":"suối nước nóng"},{"hanzi":"按摩","pinyin":"ànmó","vi":"mát-xa"}]},{"id":"丧生","hanzi":"丧生","pinyin":"sàngshēng","meaning_vi":"chết, thiệt mạng, mất mạng","explanation":"丧 (tang – mất) + 生 (sinh – mạng sống) → mất mạng, thường do tai nạn hay thảm họa.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🕯️","examples":[{"type":"basic","zh":"三人在火灾中丧生。","pinyin":"Sān rén zài huǒzāi zhōng sàngshēng.","vi":"Ba người thiệt mạng trong vụ hỏa hoạn."},{"type":"simple","zh":"这次地震造成上百人丧生。","pinyin":"Zhè cì dìzhèn zàochéng shàng bǎi rén sàngshēng.","vi":"Trận động đất này khiến hơn một trăm người thiệt mạng."},{"type":"compound","zh":"如果司机当时没有及时刹车，可能就会有更多人丧生。","pinyin":"Rúguǒ sījī dāngshí méiyǒu jíshí shāchē, kěnéng jiù huì yǒu gèng duō rén sàngshēng.","vi":"Nếu lúc đó tài xế không phanh kịp thì có lẽ đã có nhiều người thiệt mạng hơn."}],"related":[{"hanzi":"丧命","pinyin":"sàngmìng","vi":"mất mạng"},{"hanzi":"遇难","pinyin":"yùnàn","vi":"gặp nạn"},{"hanzi":"死亡","pinyin":"sǐwáng","vi":"tử vong"},{"hanzi":"身亡","pinyin":"shēnwáng","vi":"chết"}],"traditional":"喪生"},{"id":"骚乱","hanzi":"骚乱","pinyin":"sāoluàn","meaning_vi":"bạo loạn, náo loạn, rối loạn","explanation":"骚 (tao – quấy động) + 乱 (loạn – rối) → tình trạng hỗn loạn, đám đông gây rối.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🔥","examples":[{"type":"basic","zh":"街头发生了骚乱。","pinyin":"Jiētóu fāshēngle sāoluàn.","vi":"Trên đường phố đã xảy ra bạo loạn."},{"type":"simple","zh":"警察很快平息了这场骚乱。","pinyin":"Jǐngchá hěn kuài píngxīle zhè chǎng sāoluàn.","vi":"Cảnh sát nhanh chóng dập tắt cuộc bạo loạn này."},{"type":"compound","zh":"一旦有人在人群里大喊着火了，就很容易引起骚乱。","pinyin":"Yídàn yǒurén zài rénqún lǐ dàhǎn zháohuǒ le, jiù hěn róngyì yǐnqǐ sāoluàn.","vi":"Hễ có người hét lên “cháy rồi” giữa đám đông là rất dễ gây náo loạn."}],"related":[{"hanzi":"暴乱","pinyin":"bàoluàn","vi":"bạo loạn"},{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"},{"hanzi":"动乱","pinyin":"dòngluàn","vi":"loạn lạc"},{"hanzi":"秩序","pinyin":"zhìxù","vi":"trật tự"}],"traditional":"騷亂"},{"id":"扫墓","hanzi":"扫墓","pinyin":"sǎomù","meaning_vi":"tảo mộ, viếng mộ","explanation":"扫 (tảo – quét) + 墓 (mộ – mồ mả) → quét dọn mộ và tưởng nhớ người đã khuất, nhất là vào tiết Thanh Minh.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🪦","examples":[{"type":"basic","zh":"清明节去扫墓。","pinyin":"Qīngmíngjié qù sǎomù.","vi":"Tết Thanh Minh đi tảo mộ."},{"type":"simple","zh":"每年这个时候，我们全家都回老家扫墓。","pinyin":"Měinián zhè ge shíhou, wǒmen quánjiā dōu huílǎojiā sǎomù.","vi":"Hằng năm vào dịp này, cả nhà tôi đều về quê tảo mộ."},{"type":"compound","zh":"虽然工作很忙，但是他每年都会抽时间回去给爷爷扫墓。","pinyin":"Suīrán gōngzuò hěn máng, dànshì tā měinián dōuhuì chōushíjiān huíqù gěi yéye sǎomù.","vi":"Tuy công việc bận rộn nhưng năm nào anh ấy cũng dành thời gian về viếng mộ ông nội."}],"related":[{"hanzi":"清明","pinyin":"qīngmíng","vi":"Thanh Minh"},{"hanzi":"祭祖","pinyin":"jìzǔ","vi":"cúng tổ tiên"},{"hanzi":"墓地","pinyin":"mùdì","vi":"nghĩa trang"},{"hanzi":"上坟","pinyin":"shàngfén","vi":"đi viếng mộ"}],"traditional":"掃墓"},{"id":"僧人","hanzi":"僧人","pinyin":"sēngrén","meaning_vi":"nhà sư, tăng nhân","explanation":"僧 (tăng – thầy tu) + 人 (nhân – người) → người xuất gia tu hành theo đạo Phật.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧘","examples":[{"type":"basic","zh":"寺里住着几位僧人。","pinyin":"Sì lǐ zhùzhe jǐ wèi sēngrén.","vi":"Trong chùa có mấy vị sư sống."},{"type":"simple","zh":"那位年老的僧人每天清晨都要念经。","pinyin":"Nà wèi niánlǎo de sēngrén měitiān qīngchén dōu yào niànjīng.","vi":"Vị sư già ấy sáng sớm nào cũng tụng kinh."},{"type":"compound","zh":"因为僧人不吃肉，所以寺庙的饭菜都是素的。","pinyin":"Yīnwèi sēngrén bù chī ròu, suǒyǐ sìmiào de fàncài dōu shì sù de.","vi":"Vì nhà sư không ăn thịt nên cơm nước trong chùa đều là đồ chay."}],"related":[{"hanzi":"和尚","pinyin":"héshang","vi":"hòa thượng, nhà sư"},{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"尼姑","pinyin":"nígū","vi":"ni cô"},{"hanzi":"出家","pinyin":"chūjiā","vi":"xuất gia"}]},{"id":"杀害","hanzi":"杀害","pinyin":"shāhài","meaning_vi":"sát hại, giết hại","explanation":"杀 (sát – giết) + 害 (hại – làm hại) → giết người, thường mang tính cố ý, tội ác.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔪","examples":[{"type":"basic","zh":"他被敌人杀害了。","pinyin":"Tā bèi dírén shāhài le.","vi":"Ông ấy đã bị kẻ thù sát hại."},{"type":"simple","zh":"这名记者在调查中被犯罪分子杀害了。","pinyin":"Zhè míng jìzhě zài diàochá zhōng bèi fànzuì fènzǐ shāhài le.","vi":"Phóng viên này đã bị bọn tội phạm sát hại trong lúc điều tra."},{"type":"compound","zh":"虽然凶手杀害了两个人，但是他到现在还没被抓到。","pinyin":"Suīrán xiōngshǒu shāhàile liǎng gè rén, dànshì tā dàoxiànzài hái méi bèi zhuā dào.","vi":"Tuy hung thủ đã sát hại hai người nhưng đến giờ hắn vẫn chưa bị bắt."}],"related":[{"hanzi":"谋杀","pinyin":"móushā","vi":"mưu sát"},{"hanzi":"杀手","pinyin":"shāshǒu","vi":"sát thủ"},{"hanzi":"伤害","pinyin":"shānghài","vi":"làm tổn thương"},{"hanzi":"凶手","pinyin":"xiōngshǒu","vi":"hung thủ"}],"traditional":"殺害"},{"id":"杀手","hanzi":"杀手","pinyin":"shāshǒu","meaning_vi":"sát thủ, kẻ giết người; (thể thao) tay chơi đáng gờm","explanation":"杀 (sát – giết) + 手 (thủ – người làm việc gì) → kẻ giết người, sát thủ thuê; nghĩa bóng là thứ gây chết người hoặc đối thủ đáng sợ.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🥷","examples":[{"type":"basic","zh":"他是职业杀手。","pinyin":"Tā shì zhíyè shāshǒu.","vi":"Hắn là sát thủ chuyên nghiệp."},{"type":"simple","zh":"吸烟被称为健康的头号杀手。","pinyin":"Xīyān bèi chēngwéi jiànkāng de tóuhào shāshǒu.","vi":"Hút thuốc được gọi là sát thủ số một của sức khỏe."},{"type":"compound","zh":"虽然电影里的杀手很冷酷，但是他对小女孩特别温柔。","pinyin":"Suīrán diànyǐng lǐ de shāshǒu hěn lěngkù, dànshì tā duì xiǎo nǚhái tèbié wēnróu.","vi":"Tuy gã sát thủ trong phim rất lạnh lùng nhưng lại cực kỳ dịu dàng với cô bé."}],"related":[{"hanzi":"凶手","pinyin":"xiōngshǒu","vi":"hung thủ"},{"hanzi":"杀害","pinyin":"shāhài","vi":"sát hại"},{"hanzi":"刺客","pinyin":"cìkè","vi":"thích khách"},{"hanzi":"枪手","pinyin":"qiāngshǒu","vi":"tay súng"}],"traditional":"殺手"},{"id":"沙龙","hanzi":"沙龙","pinyin":"shālóng","meaning_vi":"salon, buổi tọa đàm, câu lạc bộ giao lưu","explanation":"Từ phiên âm của “salon” → buổi gặp gỡ giao lưu của giới văn nghệ, trí thức; cũng chỉ tiệm làm đẹp.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"周末有个读书沙龙。","pinyin":"Zhōumò yǒu ge dúshū shālóng.","vi":"Cuối tuần có một buổi giao lưu đọc sách."},{"type":"simple","zh":"她每个月都在家里举办艺术沙龙。","pinyin":"Tā měi gèyuè dōu zài jiālǐ jǔbàn yìshù shālóng.","vi":"Tháng nào cô ấy cũng tổ chức salon nghệ thuật tại nhà."},{"type":"compound","zh":"如果你对摄影感兴趣，就来参加我们的摄影沙龙吧。","pinyin":"Rúguǒ nǐ duì shèyǐng gǎnxìngqù, jiù lái cānjiā wǒmen de shèyǐng shālóng ba.","vi":"Nếu bạn yêu thích nhiếp ảnh thì hãy đến tham gia buổi giao lưu nhiếp ảnh của chúng tôi."}],"related":[{"hanzi":"聚会","pinyin":"jùhuì","vi":"buổi gặp mặt"},{"hanzi":"讲座","pinyin":"jiǎngzuò","vi":"buổi tọa đàm"},{"hanzi":"俱乐部","pinyin":"jùlèbù","vi":"câu lạc bộ"},{"hanzi":"论坛","pinyin":"lùntán","vi":"diễn đàn"}],"traditional":"沙龍"},{"id":"纱","hanzi":"纱","pinyin":"shā","meaning_vi":"sợi bông, vải sa, vải mỏng (lưới)","explanation":"纱 (sa – sợi, vải mỏng) → sợi bông kéo thành, hoặc loại vải mỏng thưa như 纱窗 (lưới chống muỗi), 婚纱 (váy cưới).","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"🧵","examples":[{"type":"basic","zh":"窗户上装了纱。","pinyin":"Chuānghu shàngzhuāngle shā.","vi":"Cửa sổ đã lắp lưới."},{"type":"simple","zh":"这条裙子是用薄纱做的。","pinyin":"Zhè tiáo qúnzi shì yòng báoshā zuò de.","vi":"Chiếc váy này được may bằng vải sa mỏng."},{"type":"compound","zh":"因为工厂的纱不够了，所以这批布要晚几天才能织好。","pinyin":"Yīnwèi gōngchǎng de shā búgòu le, suǒyǐ zhè pī bù yào wǎn jǐtiān cáinéng zhī hǎo.","vi":"Vì nhà máy hết sợi nên lô vải này phải chậm vài ngày mới dệt xong."}],"related":[{"hanzi":"婚纱","pinyin":"hūnshā","vi":"váy cưới"},{"hanzi":"纱窗","pinyin":"shāchuāng","vi":"lưới cửa sổ"},{"hanzi":"纱布","pinyin":"shābù","vi":"vải gạc"},{"hanzi":"棉纱","pinyin":"miánshā","vi":"sợi bông"}],"traditional":"紗"},{"id":"砂糖","hanzi":"砂糖","pinyin":"shātáng","meaning_vi":"đường cát","explanation":"砂 (sa – cát) + 糖 (đường) → đường có hạt nhỏ như cát.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍬","examples":[{"type":"basic","zh":"咖啡里加点砂糖。","pinyin":"Kāfēi lǐ jiādiǎn shātáng.","vi":"Cho chút đường cát vào cà phê."},{"type":"simple","zh":"做蛋糕需要准备一百克砂糖。","pinyin":"Zuò dàngāo xūyào zhǔnbèi yī bǎikè shātáng.","vi":"Làm bánh ngọt cần chuẩn bị một trăm gam đường cát."},{"type":"compound","zh":"如果家里没有砂糖了，就用蜂蜜代替吧。","pinyin":"Rúguǒ jiālǐ méiyǒu shātáng le, jiù yòng fēngmì dàitì ba.","vi":"Nếu nhà hết đường cát thì dùng mật ong thay thế nhé."}],"related":[{"hanzi":"白糖","pinyin":"báitáng","vi":"đường trắng"},{"hanzi":"冰糖","pinyin":"bīngtáng","vi":"đường phèn"},{"hanzi":"红糖","pinyin":"hóngtáng","vi":"đường đỏ"},{"hanzi":"方糖","pinyin":"fāngtáng","vi":"đường viên"}]},{"id":"鲨鱼","hanzi":"鲨鱼","pinyin":"shāyú","meaning_vi":"cá mập","explanation":"鲨 (sa – cá mập) + 鱼 (ngư – cá) → loài cá dữ ở biển, răng sắc nhọn.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦈","examples":[{"type":"basic","zh":"海里有很多鲨鱼。","pinyin":"Hǎilǐ yǒu hěn duō shāyú.","vi":"Dưới biển có rất nhiều cá mập."},{"type":"simple","zh":"潜水的时候，我们看到了一条小鲨鱼。","pinyin":"Qiánshuǐ de shíhou, wǒmen kàndàole yì tiáo xiǎo shāyú.","vi":"Lúc lặn biển, chúng tôi đã nhìn thấy một con cá mập nhỏ."},{"type":"compound","zh":"虽然鲨鱼看起来很可怕，但是大多数鲨鱼并不主动攻击人。","pinyin":"Suīrán shāyú kànqǐlái hěn kěpà, dànshì dàduōshù shāyú bìngbù zhǔdòng gōngjī rén.","vi":"Tuy cá mập trông rất đáng sợ nhưng phần lớn chúng không chủ động tấn công người."}],"related":[{"hanzi":"鲸鱼","pinyin":"jīngyú","vi":"cá voi"},{"hanzi":"海豚","pinyin":"hǎitún","vi":"cá heo"},{"hanzi":"鱼翅","pinyin":"yúchì","vi":"vây cá mập"},{"hanzi":"海洋","pinyin":"hǎiyáng","vi":"đại dương"}],"traditional":"鯊魚"},{"id":"筛","hanzi":"筛","pinyin":"shāi","meaning_vi":"sàng, rây, lọc; sàng lọc, loại bớt; cái sàng","explanation":"筛 (si – cái rây) → dụng cụ có lỗ nhỏ để sàng; động từ là sàng, lọc bỏ, nghĩa bóng là chọn lọc qua nhiều vòng.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🧺","examples":[{"type":"basic","zh":"把面粉筛一下。","pinyin":"Bǎ miànfěn shāi yíxià.","vi":"Rây bột mì qua một lượt."},{"type":"simple","zh":"他把沙子里的小石头都筛了出去。","pinyin":"Tā bǎ shāzi lǐ de xiǎo shítou dōu shāile chūqù.","vi":"Anh ấy sàng hết sỏi nhỏ ra khỏi cát."},{"type":"compound","zh":"虽然报名的人很多，但是第一轮就筛掉了一大半。","pinyin":"Suīrán bàomíng de rén hěn duō, dànshì dìyīlún jiù shāi diàole yí dàbàn.","vi":"Tuy người đăng ký rất đông nhưng vòng đầu đã loại hơn một nửa."}],"related":[{"hanzi":"筛选","pinyin":"shāixuǎn","vi":"sàng lọc"},{"hanzi":"筛子","pinyin":"shāizi","vi":"cái sàng"},{"hanzi":"过滤","pinyin":"guòlǜ","vi":"lọc"},{"hanzi":"挑选","pinyin":"tiāoxuǎn","vi":"chọn lựa"}],"traditional":"篩"},{"id":"晒太阳","hanzi":"晒太阳","pinyin":"shàitàiyáng","meaning_vi":"phơi nắng, tắm nắng","explanation":"晒 (sái – phơi) + 太阳 (thái dương – mặt trời) → phơi mình hoặc phơi đồ dưới nắng.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"☀️","examples":[{"type":"basic","zh":"爷爷在院子里晒太阳。","pinyin":"Yéye zài yuànzi lǐ shàitàiyáng.","vi":"Ông nội đang phơi nắng ngoài sân."},{"type":"simple","zh":"冬天多晒太阳对身体有好处。","pinyin":"Dōngtiān duō shàitàiyáng duì shēntǐ yǒu hǎochù.","vi":"Mùa đông phơi nắng nhiều tốt cho sức khỏe."},{"type":"compound","zh":"如果天气好，我们就把被子拿出去晒太阳。","pinyin":"Rúguǒ tiānqì hǎo, wǒmen jiù bǎ bèizi ná chūqù shàitàiyáng.","vi":"Nếu trời đẹp thì chúng ta mang chăn ra phơi nắng."}],"related":[{"hanzi":"阳光","pinyin":"yángguāng","vi":"ánh nắng"},{"hanzi":"晒衣服","pinyin":"shàiyīfu","vi":"phơi quần áo"},{"hanzi":"日光浴","pinyin":"rìguāngyù","vi":"tắm nắng"},{"hanzi":"晒黑","pinyin":"shàihēi","vi":"rám nắng"}],"traditional":"曬太陽"},{"id":"山顶","hanzi":"山顶","pinyin":"shāndǐng","meaning_vi":"đỉnh núi","explanation":"山 (sơn – núi) + 顶 (đỉnh – chóp) → chỗ cao nhất của ngọn núi.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"我们终于到山顶了。","pinyin":"Wǒmen zhōngyú dào shāndǐng le.","vi":"Cuối cùng chúng tôi cũng lên tới đỉnh núi."},{"type":"simple","zh":"站在山顶可以看到整个城市。","pinyin":"Zhàn zài shāndǐng kěyǐ kàndào zhěnggè chéngshì.","vi":"Đứng trên đỉnh núi có thể nhìn thấy toàn bộ thành phố."},{"type":"compound","zh":"虽然爬到山顶很累，但是看到日出的那一刻一切都值得。","pinyin":"Suīrán pá dào shāndǐng hěn lèi, dànshì kàndào rìchū de nà yíkè yíqiè dōu zhíde.","vi":"Tuy leo lên đỉnh núi rất mệt nhưng khoảnh khắc ngắm bình minh khiến mọi thứ đều xứng đáng."}],"related":[{"hanzi":"山脚","pinyin":"shānjiǎo","vi":"chân núi"},{"hanzi":"山峰","pinyin":"shānfēng","vi":"ngọn núi"},{"hanzi":"顶峰","pinyin":"dǐngfēng","vi":"đỉnh cao"},{"hanzi":"爬山","pinyin":"páshān","vi":"leo núi"}],"traditional":"山頂"},{"id":"山冈","hanzi":"山冈","pinyin":"shāngāng","meaning_vi":"đồi, gò, đồi núi thấp","explanation":"山 (sơn – núi) + 冈 (cương – sườn đồi) → quả đồi nhỏ, gò đất cao.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"太阳落到山冈后面了。","pinyin":"Tàiyáng luò dào shāngāng hòumiàn le.","vi":"Mặt trời đã lặn sau quả đồi."},{"type":"simple","zh":"村子后面有一片长满松树的山冈。","pinyin":"Cūnzi hòumiàn yǒu yípiàn zhǎngmǎn sōngshù de shāngāng.","vi":"Phía sau làng có một ngọn đồi mọc đầy thông."},{"type":"compound","zh":"因为山冈不太高，所以孩子们经常爬上去放风筝。","pinyin":"Yīnwèi shāngāng bú tài gāo, suǒyǐ háizimen jīngcháng pá shàngqù fàngfēngzheng.","vi":"Vì quả đồi không cao lắm nên bọn trẻ thường trèo lên thả diều."}],"related":[{"hanzi":"山坡","pinyin":"shānpō","vi":"sườn núi"},{"hanzi":"山丘","pinyin":"shānqiū","vi":"đồi"},{"hanzi":"山岭","pinyin":"shānlǐng","vi":"dãy núi"},{"hanzi":"土坡","pinyin":"tǔpō","vi":"gò đất"}],"traditional":"山岡"},{"id":"山岭","hanzi":"山岭","pinyin":"shānlǐng","meaning_vi":"dãy núi, đỉnh núi liền dải","explanation":"山 (sơn – núi) + 岭 (lĩnh – đỉnh núi, đèo) → những ngọn núi nối liền thành dải.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"山岭被白雪覆盖。","pinyin":"Shānlǐng bèi báixuě fùgài.","vi":"Dãy núi bị tuyết trắng bao phủ."},{"type":"simple","zh":"这条公路穿过了好几座高大的山岭。","pinyin":"Zhè tiáo gōnglù chuānguòle hǎojǐ zuò gāodà de shānlǐng.","vi":"Con đường quốc lộ này băng qua mấy dãy núi cao lớn."},{"type":"compound","zh":"虽然山岭重重，但是勘探队还是找到了一条近路。","pinyin":"Suīrán shānlǐng chóngchóng, dànshì kāntàn duì háishì zhǎodàole yì tiáo jìnlù.","vi":"Tuy núi non trùng điệp nhưng đội khảo sát vẫn tìm ra một lối tắt."}],"related":[{"hanzi":"山脉","pinyin":"shānmài","vi":"dãy núi"},{"hanzi":"山峰","pinyin":"shānfēng","vi":"ngọn núi"},{"hanzi":"山冈","pinyin":"shāngāng","vi":"đồi"},{"hanzi":"峻岭","pinyin":"jùnlǐng","vi":"núi cao hiểm trở"}],"traditional":"山嶺"},{"id":"山路","hanzi":"山路","pinyin":"shānlù","meaning_vi":"đường núi","explanation":"山 (sơn – núi) + 路 (lộ – đường) → con đường đi trên núi, thường quanh co, dốc.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛤️","examples":[{"type":"basic","zh":"山路又窄又陡。","pinyin":"Shānlù yòu zhǎi yòu dǒu.","vi":"Đường núi vừa hẹp vừa dốc."},{"type":"simple","zh":"下雨以后山路特别滑，走路要小心。","pinyin":"Xiàyǔ yǐhòu shānlù tèbié huá, zǒulù yào xiǎoxīn.","vi":"Sau khi mưa đường núi rất trơn, đi phải cẩn thận."},{"type":"compound","zh":"如果晚上开车走山路，就一定要放慢速度。","pinyin":"Rúguǒ wǎnshang kāichē zǒu shānlù, jiù yídìngyào fàngmàn sùdù.","vi":"Nếu ban đêm lái xe đường núi thì nhất định phải giảm tốc độ."}],"related":[{"hanzi":"小路","pinyin":"xiǎolù","vi":"đường nhỏ"},{"hanzi":"公路","pinyin":"gōnglù","vi":"quốc lộ"},{"hanzi":"山顶","pinyin":"shāndǐng","vi":"đỉnh núi"},{"hanzi":"弯路","pinyin":"wānlù","vi":"đường cong"}]},{"id":"山寨","hanzi":"山寨","pinyin":"shānzhài","meaning_vi":"hàng nhái, hàng giả; sơn trại (trại trên núi)","explanation":"山 (sơn – núi) + 寨 (trại – trại có rào) → vốn là sơn trại của thổ phỉ; nay dùng chỉ hàng nhái, bắt chước hàng hiệu.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"📱","examples":[{"type":"basic","zh":"这是山寨手机。","pinyin":"Zhè shì shānzhài shǒujī.","vi":"Đây là điện thoại nhái."},{"type":"simple","zh":"市场上有很多山寨名牌包。","pinyin":"Shìchǎng shàng yǒu hěn duō shānzhài míngpái bāo.","vi":"Ngoài chợ có rất nhiều túi xách nhái hàng hiệu."},{"type":"compound","zh":"虽然山寨产品价格便宜，但是质量往往没有保证。","pinyin":"Suīrán shānzhài chǎnpǐn jiàgé piányi, dànshì zhìliàng wǎngwǎng méiyǒu bǎozhèng.","vi":"Tuy hàng nhái giá rẻ nhưng chất lượng thường không được đảm bảo."}],"related":[{"hanzi":"假冒","pinyin":"jiǎmào","vi":"giả mạo"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"},{"hanzi":"盗版","pinyin":"dàobǎn","vi":"lậu, sao chép trái phép"},{"hanzi":"仿冒","pinyin":"fǎngmào","vi":"làm nhái"}]},{"id":"删","hanzi":"删","pinyin":"shān","meaning_vi":"xóa, cắt bỏ, lược bỏ","explanation":"删 (san – cắt bỏ) → bỏ đi chữ, câu, tệp tin không cần thiết.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🗑️","examples":[{"type":"basic","zh":"我把照片删了。","pinyin":"Wǒ bǎ zhàopiàn shān le.","vi":"Tôi đã xóa ảnh rồi."},{"type":"simple","zh":"这篇文章太长，你删掉一些吧。","pinyin":"Zhè piān wénzhāng tài cháng, nǐ shāndiào yìxiē ba.","vi":"Bài viết này dài quá, bạn cắt bớt một ít đi."},{"type":"compound","zh":"要是不小心删了重要文件，就赶紧去回收站找找。","pinyin":"Yàoshi bù xiǎoxīn shānle zhòngyào wénjiàn, jiù gǎnjǐn qù huíshōuzhàn zhǎo zhao.","vi":"Nếu lỡ tay xóa tệp quan trọng thì mau vào thùng rác tìm lại."}],"related":[{"hanzi":"删除","pinyin":"shānchú","vi":"xóa bỏ"},{"hanzi":"删减","pinyin":"shānjiǎn","vi":"cắt giảm"},{"hanzi":"添加","pinyin":"tiānjiā","vi":"thêm vào"},{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa đổi"}],"traditional":"刪"},{"id":"善","hanzi":"善","pinyin":"shàn","meaning_vi":"thiện, tốt lành; giỏi về, khéo; dễ (làm gì)","explanation":"善 (thiện – tốt lành) → hiền lành, tốt; còn nghĩa “giỏi về” như 善于, hay “dễ” như 善变 (dễ thay đổi).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😇","examples":[{"type":"basic","zh":"他心地很善。","pinyin":"Tā xīndì hěn shàn.","vi":"Anh ấy có tấm lòng rất lương thiện."},{"type":"simple","zh":"人之初，性本善，这是古人的看法。","pinyin":"Rén zhī chū, xìng běn shàn, zhè shì gǔrén de kànfǎ.","vi":"Người mới sinh ra bản tính vốn thiện, đó là quan niệm của người xưa."},{"type":"compound","zh":"虽然她不善言辞，但是做事非常认真可靠。","pinyin":"Suīrán tā búshàn yáncí, dànshì zuòshì fēicháng rènzhēn kěkào.","vi":"Tuy cô ấy không giỏi ăn nói nhưng làm việc rất chăm chỉ và đáng tin cậy."}],"related":[{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"善于","pinyin":"shànyú","vi":"giỏi về"},{"hanzi":"恶","pinyin":"è","vi":"ác"},{"hanzi":"改善","pinyin":"gǎishàn","vi":"cải thiện"}]},{"id":"赡养","hanzi":"赡养","pinyin":"shànyǎng","meaning_vi":"phụng dưỡng, nuôi dưỡng (cha mẹ, người già)","explanation":"赡 (thiệm – chu cấp) + 养 (dưỡng – nuôi) → chu cấp, chăm lo đời sống, nhất là con cái đối với cha mẹ già.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"👵","examples":[{"type":"basic","zh":"子女要赡养父母。","pinyin":"Zǐnǚ yào shànyǎng fùmǔ.","vi":"Con cái phải phụng dưỡng cha mẹ."},{"type":"simple","zh":"他每个月都给老家寄钱赡养老人。","pinyin":"Tā měi gèyuè dōu gěi lǎojiā jì qián shànyǎng lǎorén.","vi":"Tháng nào anh ấy cũng gửi tiền về quê phụng dưỡng người già."},{"type":"compound","zh":"即使工作再忙，他也从来没有忘记赡养年迈的母亲。","pinyin":"Jíshǐ gōngzuò zài máng, tā yě cónglái méiyǒu wàngjì shànyǎng niánmài de mǔqīn.","vi":"Dù công việc bận đến đâu, anh ấy cũng chưa từng quên phụng dưỡng người mẹ già."}],"related":[{"hanzi":"抚养","pinyin":"fǔyǎng","vi":"nuôi nấng (con)"},{"hanzi":"供养","pinyin":"gōngyǎng","vi":"cung dưỡng"},{"hanzi":"孝顺","pinyin":"xiàoshùn","vi":"hiếu thảo"},{"hanzi":"养老","pinyin":"yǎnglǎo","vi":"dưỡng già"}],"traditional":"贍養"},{"id":"伤残","hanzi":"伤残","pinyin":"shāngcán","meaning_vi":"tàn tật, thương tật, bị thương tật","explanation":"伤 (thương – bị thương) + 残 (tàn – tàn tật) → bị thương dẫn đến khuyết tật lâu dài.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🦽","examples":[{"type":"basic","zh":"他在事故中伤残了。","pinyin":"Tā zài shìgù zhōng shāngcán le.","vi":"Anh ấy bị thương tật trong vụ tai nạn."},{"type":"simple","zh":"政府为伤残军人提供生活补助。","pinyin":"Zhèngfǔ wèi shāngcán jūnrén tígōng shēnghuó bǔzhù.","vi":"Chính phủ cấp trợ cấp sinh hoạt cho thương binh."},{"type":"compound","zh":"虽然他在工作中落下了伤残，但是依然乐观地生活。","pinyin":"Suīrán tā zài gōngzuò zhōng luòxiàle shāngcán, dànshì yīrán lèguān de shēnghuó.","vi":"Tuy bị thương tật trong lúc làm việc nhưng anh ấy vẫn sống lạc quan."}],"related":[{"hanzi":"残疾","pinyin":"cánjí","vi":"tàn tật"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"bị thương"},{"hanzi":"残疾人","pinyin":"cánjírén","vi":"người khuyết tật"},{"hanzi":"伤亡","pinyin":"shāngwáng","vi":"thương vong"}],"traditional":"傷殘"},{"id":"伤势","hanzi":"伤势","pinyin":"shāngshì","meaning_vi":"tình trạng vết thương, thương thế","explanation":"伤 (thương – vết thương) + 势 (thế – tình thế) → mức độ nặng nhẹ của vết thương.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"他的伤势不重。","pinyin":"Tā de shāngshì bú zhòng.","vi":"Vết thương của anh ấy không nặng."},{"type":"simple","zh":"医生说病人的伤势已经稳定了。","pinyin":"Yīshēng shuō bìngrén de shāngshì yǐjīng wěndìng le.","vi":"Bác sĩ nói thương thế của bệnh nhân đã ổn định."},{"type":"compound","zh":"因为伤势太严重，所以他不得不退出了这场比赛。","pinyin":"Yīnwèi shāngshì tài yánzhòng, suǒyǐ tā bùdébú tuìchūle zhè chǎng bǐsài.","vi":"Vì vết thương quá nặng nên anh ấy buộc phải rút khỏi trận đấu này."}],"related":[{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"bị thương"},{"hanzi":"病情","pinyin":"bìngqíng","vi":"bệnh tình"},{"hanzi":"伤员","pinyin":"shāngyuán","vi":"người bị thương"}],"traditional":"傷勢"},{"id":"商贩","hanzi":"商贩","pinyin":"shāngfàn","meaning_vi":"người buôn bán nhỏ, tiểu thương, người bán hàng rong","explanation":"商 (thương – buôn bán) + 贩 (phiến – buôn đi bán lại) → người buôn bán nhỏ lẻ.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🛒","examples":[{"type":"basic","zh":"路边有很多商贩。","pinyin":"Lùbiān yǒu hěn duō shāngfàn.","vi":"Ven đường có rất nhiều người bán hàng rong."},{"type":"simple","zh":"早上的菜市场里挤满了商贩和顾客。","pinyin":"Zǎoshang de càishìchǎng lǐ jǐmǎnle shāngfàn hé gùkè.","vi":"Chợ rau buổi sáng chật kín tiểu thương và khách hàng."},{"type":"compound","zh":"如果商贩缺斤少两，顾客就可以向市场管理处投诉。","pinyin":"Rúguǒ shāngfàn quē jīn shǎo liǎng, gùkè jiù kěyǐ xiàng shìchǎng guǎnlǐ chù tóusù.","vi":"Nếu người bán cân thiếu thì khách hàng có thể khiếu nại với ban quản lý chợ."}],"related":[{"hanzi":"小贩","pinyin":"xiǎofàn","vi":"người bán rong"},{"hanzi":"商人","pinyin":"shāngrén","vi":"thương nhân"},{"hanzi":"摊贩","pinyin":"tānfàn","vi":"người bán sạp"},{"hanzi":"顾客","pinyin":"gùkè","vi":"khách hàng"}],"traditional":"商販"},{"id":"商贾","hanzi":"商贾","pinyin":"shānggǔ","meaning_vi":"thương nhân, thương gia, nhà buôn","explanation":"商 (thương – buôn bán lưu động) + 贾 (cổ – buôn bán tại chỗ) → giới buôn bán nói chung; từ mang sắc thái văn viết, cổ.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"💰","examples":[{"type":"basic","zh":"这里商贾云集。","pinyin":"Zhèlǐ shānggǔ yúnjí.","vi":"Nơi đây thương nhân tụ hội đông đúc."},{"type":"simple","zh":"古代的丝绸之路上来往着各国商贾。","pinyin":"Gǔdài de Sīchóuzhīlù shànglái wǎngzhe gèguó shānggǔ.","vi":"Trên Con đường tơ lụa thời xưa qua lại thương nhân các nước."},{"type":"compound","zh":"因为这座小镇交通便利，所以自古就吸引了大批商贾。","pinyin":"Yīnwèi zhè zuò xiǎozhèn jiāotōng biànlì, suǒyǐ zìgǔ jiù xīyǐnle dàpī shānggǔ.","vi":"Vì thị trấn nhỏ này giao thông thuận tiện nên từ xưa đã thu hút rất nhiều thương gia."}],"related":[{"hanzi":"商人","pinyin":"shāngrén","vi":"thương nhân"},{"hanzi":"富商","pinyin":"fùshāng","vi":"nhà buôn giàu"},{"hanzi":"经商","pinyin":"jīngshāng","vi":"kinh doanh"},{"hanzi":"商贩","pinyin":"shāngfàn","vi":"tiểu thương"}],"traditional":"商賈"},{"id":"上报","hanzi":"上报","pinyin":"shàngbào","meaning_vi":"báo cáo lên trên; lên báo","explanation":"上 (thượng – lên trên) + 报 (báo – báo cáo) → báo cáo lên cấp trên; cũng có nghĩa được đăng lên báo.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📤","examples":[{"type":"basic","zh":"这件事要马上上报。","pinyin":"Zhè jiàn shì yào mǎshàng shàngbào.","vi":"Việc này phải báo cáo lên trên ngay."},{"type":"simple","zh":"各部门请在周五前上报本月数据。","pinyin":"Gè bùmén qǐng zài Zhōuwǔ qián shàngbào běnyuè shùjù.","vi":"Đề nghị các phòng ban báo cáo số liệu tháng này trước thứ Sáu."},{"type":"compound","zh":"一旦发现安全隐患，就必须立即上报主管部门。","pinyin":"Yídàn fāxiàn ānquán yǐnhuàn, jiù bìxū lìjí shàngbào zhǔguǎn bùmén.","vi":"Một khi phát hiện nguy cơ mất an toàn thì phải lập tức báo cáo cơ quan chủ quản."}],"related":[{"hanzi":"汇报","pinyin":"huìbào","vi":"báo cáo"},{"hanzi":"报告","pinyin":"bàogào","vi":"báo cáo"},{"hanzi":"下达","pinyin":"xiàdá","vi":"truyền đạt xuống"},{"hanzi":"申报","pinyin":"shēnbào","vi":"khai báo"}],"traditional":"上報"},{"id":"上场","hanzi":"上场","pinyin":"shàngchǎng","meaning_vi":"ra sân, ra sân khấu, vào trận","explanation":"上 (thượng – lên) + 场 (trường – sân, sân khấu) → bước ra sân thi đấu hoặc lên sân khấu biểu diễn.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"⚽","examples":[{"type":"basic","zh":"下半场他上场了。","pinyin":"Xiàbànchǎng tā shàngchǎng le.","vi":"Hiệp hai anh ấy được vào sân."},{"type":"simple","zh":"演员们正在后台准备上场。","pinyin":"Yǎnyuánmen zhèngzài hòutái zhǔnbèi shàngchǎng.","vi":"Các diễn viên đang ở hậu trường chuẩn bị ra sân khấu."},{"type":"compound","zh":"虽然他上场才十分钟，但是已经踢进了两个球。","pinyin":"Suīrán tā shàngchǎng cái shí fēnzhōng, dànshì yǐjīng tī jìnle liǎng gè qiú.","vi":"Tuy mới vào sân được mười phút nhưng anh ấy đã ghi hai bàn."}],"related":[{"hanzi":"下场","pinyin":"xiàchǎng","vi":"rời sân"},{"hanzi":"出场","pinyin":"chūchǎng","vi":"ra sân, xuất hiện"},{"hanzi":"登场","pinyin":"dēngchǎng","vi":"lên sân khấu"},{"hanzi":"替补","pinyin":"tìbǔ","vi":"dự bị"}],"traditional":"上場"},{"id":"上调","hanzi":"上调","pinyin":"shàngtiáo","meaning_vi":"điều chỉnh tăng, nâng (giá, lương)","explanation":"上 (thượng – lên) + 调 (điều – điều chỉnh) → điều chỉnh theo hướng tăng lên, thường nói về giá cả, lãi suất, lương.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"油价又上调了。","pinyin":"Yóujià yòu shàngtiáo le.","vi":"Giá xăng lại tăng rồi."},{"type":"simple","zh":"公司决定明年上调员工工资。","pinyin":"Gōngsī juédìng míngnián shàngtiáo yuángōng gōngzī.","vi":"Công ty quyết định năm sau tăng lương cho nhân viên."},{"type":"compound","zh":"如果银行上调贷款利率，买房的人就会减少。","pinyin":"Rúguǒ yínháng shàngtiáo dàikuǎn lìlǜ, mǎifáng de rén jiù huì jiǎnshǎo.","vi":"Nếu ngân hàng tăng lãi suất cho vay thì người mua nhà sẽ giảm."}],"related":[{"hanzi":"下调","pinyin":"xiàtiáo","vi":"điều chỉnh giảm"},{"hanzi":"上涨","pinyin":"shàngzhǎng","vi":"tăng lên"},{"hanzi":"调整","pinyin":"tiáozhěng","vi":"điều chỉnh"},{"hanzi":"提高","pinyin":"tígāo","vi":"nâng cao"}],"traditional":"上調"},{"id":"上方","hanzi":"上方","pinyin":"shàngfāng","meaning_vi":"phía trên, bên trên","explanation":"上 (thượng – trên) + 方 (phương – phía) → vị trí ở phía trên của một vật.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"⬆️","examples":[{"type":"basic","zh":"门的上方有个钟。","pinyin":"Mén de shàngfāng yǒu ge zhōng.","vi":"Phía trên cửa có một cái đồng hồ."},{"type":"simple","zh":"请在表格上方写上你的名字。","pinyin":"Qǐng zài biǎogé shàngfāng xiě shàng nǐ de míngzi.","vi":"Hãy viết tên bạn ở phía trên bảng biểu."},{"type":"compound","zh":"如果找不到按钮，就看看屏幕右上方的菜单。","pinyin":"Rúguǒ zhǎobúdào ànniǔ, jiù kànkan píngmù yòu shàngfāng de càidān.","vi":"Nếu không tìm thấy nút thì hãy xem menu ở phía trên bên phải màn hình."}],"related":[{"hanzi":"下方","pinyin":"xiàfāng","vi":"phía dưới"},{"hanzi":"上面","pinyin":"shàngmiàn","vi":"bên trên"},{"hanzi":"上空","pinyin":"shàngkōng","vi":"bầu trời phía trên"},{"hanzi":"顶部","pinyin":"dǐngbù","vi":"phần đỉnh"}]},{"id":"上岗","hanzi":"上岗","pinyin":"shànggǎng","meaning_vi":"nhận việc, vào vị trí công tác, vào ca","explanation":"上 (thượng – lên) + 岗 (cương – vị trí, trạm gác) → bắt đầu đảm nhận vị trí công việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👷","examples":[{"type":"basic","zh":"新员工明天上岗。","pinyin":"Xīn yuángōng míngtiān shànggǎng.","vi":"Nhân viên mới ngày mai bắt đầu làm việc."},{"type":"simple","zh":"司机必须经过培训才能上岗。","pinyin":"Sījī bìxū jīngguò péixùn cáinéng shànggǎng.","vi":"Tài xế phải qua đào tạo mới được nhận việc."},{"type":"compound","zh":"如果没有取得资格证书，就不允许上岗工作。","pinyin":"Rúguǒ méiyǒu qǔdé zīgé zhèngshū, jiù bù yǔnxǔ shànggǎng gōngzuò.","vi":"Nếu chưa có chứng chỉ hành nghề thì không được phép nhận việc."}],"related":[{"hanzi":"下岗","pinyin":"xiàgǎng","vi":"mất việc, nghỉ việc"},{"hanzi":"岗位","pinyin":"gǎngwèi","vi":"vị trí công tác"},{"hanzi":"就业","pinyin":"jiùyè","vi":"có việc làm"},{"hanzi":"入职","pinyin":"rùzhí","vi":"vào làm"}],"traditional":"上崗"},{"id":"上火","hanzi":"上火","pinyin":"shànghuǒ","meaning_vi":"nóng trong (Đông y), nhiệt; nổi nóng, sốt ruột","explanation":"上 (thượng – bốc lên) + 火 (hỏa – lửa) → theo Đông y là nội nhiệt bốc lên gây nhiệt miệng, viêm họng; nghĩa bóng là nóng ruột, nổi giận.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🔥","examples":[{"type":"basic","zh":"吃辣的容易上火。","pinyin":"Chī là de róngyì shànghuǒ.","vi":"Ăn cay dễ bị nóng trong."},{"type":"simple","zh":"他最近上火了，嘴里长了好几个泡。","pinyin":"Tā zuìjìn shànghuǒ le, zuǐlǐ zhǎngle hǎojǐ gè pào.","vi":"Dạo này anh ấy bị nhiệt, trong miệng mọc mấy nốt nhiệt."},{"type":"compound","zh":"因为孩子考试没考好，所以妈妈急得直上火。","pinyin":"Yīnwèi háizi kǎoshì méi kǎo hǎo, suǒyǐ māma jí dezhí shànghuǒ.","vi":"Vì con thi không tốt nên mẹ sốt ruột đến phát nóng."}],"related":[{"hanzi":"降火","pinyin":"jiànghuǒ","vi":"giải nhiệt"},{"hanzi":"发火","pinyin":"fāhuǒ","vi":"nổi giận"},{"hanzi":"着急","pinyin":"zháojí","vi":"sốt ruột"},{"hanzi":"凉茶","pinyin":"liángchá","vi":"trà thanh nhiệt"}]},{"id":"上流","hanzi":"上流","pinyin":"shàngliú","meaning_vi":"thượng lưu (tầng lớp); thượng nguồn","explanation":"上 (thượng – trên) + 流 (lưu – dòng) → phần trên của dòng sông; nghĩa bóng là tầng lớp trên trong xã hội.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🎩","examples":[{"type":"basic","zh":"她出身上流家庭。","pinyin":"Tā chūshēn shàngliú jiātíng.","vi":"Cô ấy xuất thân từ gia đình thượng lưu."},{"type":"simple","zh":"这家俱乐部只接待上流社会的客人。","pinyin":"Zhè jiā jùlèbù zhǐ jiēdài shàngliú shèhuì de kèrén.","vi":"Câu lạc bộ này chỉ tiếp đón khách thuộc giới thượng lưu."},{"type":"compound","zh":"虽然他挤进了上流社会，但是始终觉得自己不属于那里。","pinyin":"Suīrán tā jǐjìnle shàngliú shèhuì, dànshì shǐzhōng juéde zìjǐ bù shǔyú nàlǐ.","vi":"Tuy đã chen chân được vào giới thượng lưu nhưng anh ấy luôn cảm thấy mình không thuộc về nơi đó."}],"related":[{"hanzi":"上游","pinyin":"shàngyóu","vi":"thượng du, thượng nguồn"},{"hanzi":"下流","pinyin":"xiàliú","vi":"hạ lưu"},{"hanzi":"上层","pinyin":"shàngcéng","vi":"tầng lớp trên"},{"hanzi":"贵族","pinyin":"guìzú","vi":"quý tộc"}]},{"id":"上期","hanzi":"上期","pinyin":"shàngqī","meaning_vi":"kỳ trước, số trước","explanation":"上 (thượng – trước) + 期 (kỳ – kỳ, số) → kỳ trước (tuần, tháng, quý) hoặc số báo, tập chương trình trước.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🗓️","examples":[{"type":"basic","zh":"上期杂志卖完了。","pinyin":"Shàngqī zázhì mài wánle.","vi":"Tạp chí số trước đã bán hết rồi."},{"type":"simple","zh":"本季度的销量比上期增长了两成。","pinyin":"Běn jìdù de xiāoliàng bǐ shàngqī zēngzhǎngle liǎng chéng.","vi":"Doanh số quý này tăng hai mươi phần trăm so với kỳ trước."},{"type":"compound","zh":"如果你错过了上期节目，就可以在网上看回放。","pinyin":"Rúguǒ nǐ cuòguòle shàngqī jiémù, jiù kěyǐ zài wǎngshàng kàn huífàng.","vi":"Nếu bạn lỡ tập chương trình trước thì có thể xem lại trên mạng."}],"related":[{"hanzi":"下期","pinyin":"xiàqī","vi":"kỳ sau"},{"hanzi":"本期","pinyin":"běnqī","vi":"kỳ này"},{"hanzi":"同期","pinyin":"tóngqī","vi":"cùng kỳ"},{"hanzi":"期刊","pinyin":"qīkān","vi":"tạp chí định kỳ"}]},{"id":"上述","hanzi":"上述","pinyin":"shàngshù","meaning_vi":"nói trên, kể trên, nêu trên","explanation":"上 (thượng – trên) + 述 (thuật – trình bày) → những điều đã trình bày ở trên; dùng nhiều trong văn viết.","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"📄","examples":[{"type":"basic","zh":"上述问题很重要。","pinyin":"Shàngshù wèntí hěn zhòngyào.","vi":"Những vấn đề nêu trên rất quan trọng."},{"type":"simple","zh":"请按照上述要求准备申请材料。","pinyin":"Qǐng ànzhào shàngshù yāoqiú zhǔnbèi shēnqǐng cáiliào.","vi":"Vui lòng chuẩn bị hồ sơ theo các yêu cầu nêu trên."},{"type":"compound","zh":"如果你不符合上述条件，就不能参加这次选拔。","pinyin":"Rúguǒ nǐ bù fúhé shàngshù tiáojiàn, jiù bù néng cānjiā zhè cì xuǎnbá.","vi":"Nếu bạn không đáp ứng các điều kiện kể trên thì không thể tham gia đợt tuyển chọn này."}],"related":[{"hanzi":"以上","pinyin":"yǐshàng","vi":"trên đây"},{"hanzi":"下述","pinyin":"xiàshù","vi":"dưới đây"},{"hanzi":"前述","pinyin":"qiánshù","vi":"đã nói trước"},{"hanzi":"如下","pinyin":"rúxià","vi":"như sau"}]},{"id":"上司","hanzi":"上司","pinyin":"shàngsi","meaning_vi":"cấp trên, sếp","explanation":"上 (thượng – trên) + 司 (ti – người quản lý) → người cấp trên trực tiếp quản lý mình.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"我的上司很严格。","pinyin":"Wǒ de shàngsi hěn yángé.","vi":"Sếp của tôi rất nghiêm khắc."},{"type":"simple","zh":"他把报告交给了上司审阅。","pinyin":"Tā bǎ bàogào jiāogěile shàngsi shěnyuè.","vi":"Anh ấy nộp báo cáo cho cấp trên duyệt."},{"type":"compound","zh":"虽然上司批评了他，但是他并没有因此灰心。","pinyin":"Suīrán shàngsi pīpíngle tā, dànshì tā bìng méiyǒu yīncǐ huīxīn.","vi":"Tuy bị cấp trên phê bình nhưng anh ấy không vì thế mà nản lòng."}],"related":[{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"下属","pinyin":"xiàshǔ","vi":"cấp dưới"},{"hanzi":"老板","pinyin":"lǎobǎn","vi":"ông chủ"},{"hanzi":"同事","pinyin":"tóngshì","vi":"đồng nghiệp"}]},{"id":"上头","hanzi":"上头","pinyin":"shàngtou","meaning_vi":"bên trên, phía trên; cấp trên; (rượu) bốc lên đầu","explanation":"上 (thượng – trên) + 头 (đầu – phía) → phía trên, hay chỉ cấp trên; đọc shàng tóu khi nói rượu bốc lên đầu hoặc (từ mới) bị cuốn, nghiện.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔝","examples":[{"type":"basic","zh":"这是上头的决定。","pinyin":"Zhè shì shàngtou de juédìng.","vi":"Đây là quyết định của cấp trên."},{"type":"simple","zh":"桌子上头放着一本旧字典。","pinyin":"Zhuōzi shàngtou fàngzhe yì běn jiù zìdiǎn.","vi":"Trên mặt bàn để một cuốn từ điển cũ."},{"type":"compound","zh":"既然上头已经同意了，我们就赶快开始干吧。","pinyin":"Jìrán shàngtou yǐjīng tóngyì le, wǒmen jiù gǎnkuài kāishǐ gàn ba.","vi":"Cấp trên đã đồng ý rồi thì chúng ta mau bắt tay vào làm thôi."}],"related":[{"hanzi":"上面","pinyin":"shàngmiàn","vi":"bên trên"},{"hanzi":"上级","pinyin":"shàngjí","vi":"cấp trên"},{"hanzi":"下头","pinyin":"xiàtou","vi":"bên dưới"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"}],"traditional":"上頭"},{"id":"上限","hanzi":"上限","pinyin":"shàngxiàn","meaning_vi":"giới hạn trên, mức trần","explanation":"上 (thượng – trên) + 限 (hạn – giới hạn) → mức cao nhất được phép, không được vượt quá.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"每人借书有上限。","pinyin":"Měirén jièshū yǒu shàngxiàn.","vi":"Mỗi người mượn sách có giới hạn tối đa."},{"type":"simple","zh":"这张信用卡的消费上限是五万元。","pinyin":"Zhè zhāng xìnyòngkǎ de xiāofèi shàngxiàn shì wǔ wàn yuán.","vi":"Hạn mức chi tiêu của thẻ tín dụng này là năm vạn tệ."},{"type":"compound","zh":"一旦报名人数达到上限，系统就会自动关闭报名。","pinyin":"Yídàn bàomíng rénshù dádào shàngxiàn, xìtǒng jiù huì zìdòng guānbì bàomíng.","vi":"Một khi số người đăng ký đạt mức tối đa, hệ thống sẽ tự động đóng đăng ký."}],"related":[{"hanzi":"下限","pinyin":"xiàxiàn","vi":"giới hạn dưới"},{"hanzi":"限度","pinyin":"xiàndù","vi":"giới hạn"},{"hanzi":"极限","pinyin":"jíxiàn","vi":"cực hạn"},{"hanzi":"最高","pinyin":"zuìgāo","vi":"cao nhất"}]},{"id":"上映","hanzi":"上映","pinyin":"shàngyìng","meaning_vi":"công chiếu, trình chiếu (phim)","explanation":"上 (thượng – đưa lên) + 映 (ánh – chiếu) → đưa phim lên màn ảnh để chiếu cho khán giả.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"这部电影下周上映。","pinyin":"Zhè bù diànyǐng xiàzhōu shàngyìng.","vi":"Bộ phim này tuần sau công chiếu."},{"type":"simple","zh":"新片上映第一天票房就破了纪录。","pinyin":"Xīn piàn shàngyìng dìyī tiān piàofáng jiù pòle jìlù.","vi":"Phim mới công chiếu ngày đầu tiên doanh thu phòng vé đã phá kỷ lục."},{"type":"compound","zh":"虽然这部动画片上映很久了，但是电影院里仍然坐满了人。","pinyin":"Suīrán zhè bù dònghuàpiàn shàngyìng hěn jiǔ le, dànshì diànyǐngyuàn lǐ réngrán zuò mǎnle rén.","vi":"Tuy bộ phim hoạt hình này đã chiếu từ lâu nhưng rạp vẫn kín chỗ."}],"related":[{"hanzi":"放映","pinyin":"fàngyìng","vi":"trình chiếu"},{"hanzi":"首映","pinyin":"shǒuyìng","vi":"công chiếu lần đầu"},{"hanzi":"票房","pinyin":"piàofáng","vi":"doanh thu phòng vé"},{"hanzi":"下映","pinyin":"xiàyìng","vi":"ngừng chiếu"}]},{"id":"尚","hanzi":"尚","pinyin":"shàng","meaning_vi":"vẫn còn, còn; coi trọng, chuộng","explanation":"尚 (thượng – còn, vẫn; tôn sùng) → phó từ văn viết nghĩa là “vẫn còn” (= 还); động từ nghĩa là coi trọng, như 崇尚.","hsk_level":"7-9","tags":["pho-tu","ngon-ngu"],"image":"⏳","examples":[{"type":"basic","zh":"此事尚不清楚。","pinyin":"Cǐshì shàng bù qīngchu.","vi":"Việc này vẫn chưa rõ ràng."},{"type":"simple","zh":"病人的情况尚好，请家属放心。","pinyin":"Bìngrén de qíngkuàng shàng hǎo, qǐng jiāshǔ fàngxīn.","vi":"Tình trạng bệnh nhân vẫn ổn, xin người nhà yên tâm."},{"type":"compound","zh":"虽然调查尚在进行，但是警方已经掌握了一些线索。","pinyin":"Suīrán diàochá shàng zài jìnxíng, dànshì jǐngfāng yǐjīng zhǎngwòle yìxiē xiànsuǒ.","vi":"Tuy cuộc điều tra vẫn đang tiến hành nhưng cảnh sát đã nắm được một số manh mối."}],"related":[{"hanzi":"尚未","pinyin":"shàngwèi","vi":"vẫn chưa"},{"hanzi":"仍","pinyin":"réng","vi":"vẫn"},{"hanzi":"崇尚","pinyin":"chóngshàng","vi":"tôn sùng"},{"hanzi":"时尚","pinyin":"shíshàng","vi":"thời thượng"}]},{"id":"尚未","hanzi":"尚未","pinyin":"shàngwèi","meaning_vi":"vẫn chưa, còn chưa","explanation":"尚 (thượng – vẫn còn) + 未 (vị – chưa) → vẫn chưa xảy ra; sắc thái trang trọng, văn viết.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⌛","examples":[{"type":"basic","zh":"结果尚未公布。","pinyin":"Jiéguǒ shàngwèi gōngbù.","vi":"Kết quả vẫn chưa được công bố."},{"type":"simple","zh":"这座大桥尚未完工，暂时不能通车。","pinyin":"Zhè zuò Dàqiáo shàngwèi wángōng, zànshí bù néng tōngchē.","vi":"Cây cầu này vẫn chưa hoàn công, tạm thời chưa thể thông xe."},{"type":"compound","zh":"既然双方尚未达成协议，那么谈判就还得继续下去。","pinyin":"Jìrán shuāngfāng shàngwèi dáchéng xiéyì, nàme tánpàn jiù hái děi jìxù xiàqù.","vi":"Vì hai bên vẫn chưa đạt được thỏa thuận nên đàm phán vẫn phải tiếp tục."}],"related":[{"hanzi":"还没","pinyin":"háiméi","vi":"còn chưa"},{"hanzi":"未曾","pinyin":"wèicéng","vi":"chưa từng"},{"hanzi":"已经","pinyin":"yǐjīng","vi":"đã"},{"hanzi":"仍然","pinyin":"réngrán","vi":"vẫn"}]},{"id":"稍候","hanzi":"稍候","pinyin":"shāohòu","meaning_vi":"đợi một lát, chờ một chút","explanation":"稍 (sảo – hơi, chút ít) + 候 (hậu – chờ đợi) → đợi trong chốc lát; lời nói lịch sự.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"⏱️","examples":[{"type":"basic","zh":"请您稍候片刻。","pinyin":"Qǐng nín shāohòu piànkè.","vi":"Xin quý khách vui lòng đợi một lát."},{"type":"simple","zh":"经理正在开会，请您在这里稍候。","pinyin":"Jīnglǐ zhèngzài kāihuì, qǐng nín zài zhèlǐ shāohòu.","vi":"Giám đốc đang họp, xin anh chờ ở đây một chút."},{"type":"compound","zh":"如果系统显示请稍候，就说明数据正在处理。","pinyin":"Rúguǒ xìtǒng xiǎnshì qǐng shāohòu, jiù shuōmíng shùjù zhèngzài chǔlǐ.","vi":"Nếu hệ thống hiện “vui lòng đợi” thì nghĩa là dữ liệu đang được xử lý."}],"related":[{"hanzi":"稍等","pinyin":"shāoděng","vi":"đợi chút"},{"hanzi":"等候","pinyin":"děnghòu","vi":"chờ đợi"},{"hanzi":"片刻","pinyin":"piànkè","vi":"chốc lát"},{"hanzi":"稍后","pinyin":"shāohòu","vi":"lát nữa"}]},{"id":"稍稍","hanzi":"稍稍","pinyin":"shāoshāo","meaning_vi":"hơi hơi, một chút, chút ít","explanation":"稍 (sảo – hơi) lặp lại → mức độ rất nhẹ, một chút thôi.","hsk_level":"7-9","tags":["pho-tu","so-luong"],"image":"🤏","examples":[{"type":"basic","zh":"请稍稍等一下。","pinyin":"Qǐng shāoshāo děngyíxià.","vi":"Xin đợi một chút."},{"type":"simple","zh":"听了他的解释，我才稍稍放心了。","pinyin":"Tīngle tā de jiěshì, wǒ cái shāoshāo fàngxīn le.","vi":"Nghe anh ấy giải thích, tôi mới hơi yên tâm một chút."},{"type":"compound","zh":"虽然价格稍稍高了一点，但是质量确实好很多。","pinyin":"Suīrán jiàgé shāoshāo gāole yìdiǎn, dànshì zhìliàng quèshí hǎo hěn duō.","vi":"Tuy giá hơi cao một chút nhưng chất lượng quả thật tốt hơn nhiều."}],"related":[{"hanzi":"稍微","pinyin":"shāowēi","vi":"hơi, một chút"},{"hanzi":"略微","pinyin":"lüèwēi","vi":"hơi hơi"},{"hanzi":"有些","pinyin":"yǒuxiē","vi":"có phần"},{"hanzi":"稍许","pinyin":"shāoxǔ","vi":"chút ít"}]},{"id":"少不了","hanzi":"少不了","pinyin":"shǎobuliǎo","meaning_vi":"không thể thiếu, ắt phải có, chắc chắn có","explanation":"少 (thiểu – thiếu) + 不了 (không thể) → không thể thiếu được; cũng diễn tả việc chắc chắn sẽ có nhiều.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"✅","examples":[{"type":"basic","zh":"过年少不了饺子。","pinyin":"Guònián shǎobuliǎo jiǎozi.","vi":"Ăn Tết không thể thiếu sủi cảo."},{"type":"simple","zh":"这次出差少不了你的帮忙。","pinyin":"Zhè cì chūchāi shǎobuliǎo nǐ de bāngmáng.","vi":"Chuyến công tác lần này không thể thiếu sự giúp đỡ của anh."},{"type":"compound","zh":"既然要搬家，那就少不了要请几个朋友来帮忙。","pinyin":"Jìrán yào bānjiā, nà jiù shǎobuliǎo yào qǐng jǐ gè péngyou lái bāngmáng.","vi":"Đã chuyển nhà thì thế nào cũng phải nhờ mấy người bạn đến giúp."}],"related":[{"hanzi":"离不开","pinyin":"líbukāi","vi":"không thể rời xa"},{"hanzi":"必不可少","pinyin":"bìbùkěshǎo","vi":"không thể thiếu"},{"hanzi":"免不了","pinyin":"miǎnbuliǎo","vi":"khó tránh khỏi"},{"hanzi":"缺少","pinyin":"quēshǎo","vi":"thiếu"}]},{"id":"少见","hanzi":"少见","pinyin":"shǎojiàn","meaning_vi":"hiếm thấy, ít gặp","explanation":"少 (thiểu – ít) + 见 (kiến – thấy) → ít khi nhìn thấy, hiếm có.","hsk_level":"7-9","tags":["tinh-tu","so-luong"],"image":"🦄","examples":[{"type":"basic","zh":"这种鸟很少见。","pinyin":"Zhè zhǒng niǎo hěn shǎojiàn.","vi":"Loài chim này rất hiếm gặp."},{"type":"simple","zh":"南方下这么大的雪真是少见。","pinyin":"Nánfāng xià zhème dà de xuě zhēn shì shǎojiàn.","vi":"Miền Nam có tuyết rơi lớn thế này thật là hiếm thấy."},{"type":"compound","zh":"因为这种病非常少见，所以很多医生都没有治疗经验。","pinyin":"Yīnwèi zhè zhǒng bìng fēicháng shǎojiàn, suǒyǐ hěn duō yīshēng dōu méiyǒu zhìliáo jīngyàn.","vi":"Vì bệnh này cực hiếm nên nhiều bác sĩ không có kinh nghiệm điều trị."}],"related":[{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"常见","pinyin":"chángjiàn","vi":"thường thấy"},{"hanzi":"少有","pinyin":"shǎoyǒu","vi":"hiếm có"},{"hanzi":"稀有","pinyin":"xīyǒu","vi":"quý hiếm"}],"traditional":"少見"},{"id":"少量","hanzi":"少量","pinyin":"shǎoliàng","meaning_vi":"một ít, lượng nhỏ","explanation":"少 (thiểu – ít) + 量 (lượng – số lượng) → số lượng ít.","hsk_level":"7-9","tags":["tinh-tu","so-luong"],"image":"🥄","examples":[{"type":"basic","zh":"加入少量的盐。","pinyin":"Jiārù shǎoliàng de yán.","vi":"Cho vào một ít muối."},{"type":"simple","zh":"每天喝少量红酒对身体不一定有好处。","pinyin":"Měitiān hē shǎoliàng hóngjiǔ duì shēntǐ bù yídìng yǒu hǎochù.","vi":"Mỗi ngày uống một ít rượu vang chưa chắc đã tốt cho sức khỏe."},{"type":"compound","zh":"虽然仓库里还有少量存货，但是恐怕撑不过这个月。","pinyin":"Suīrán cāngkù lǐ háiyǒu shǎoliàng cúnhuò, dànshì kǒngpà chēng búguò zhè geyuè.","vi":"Tuy trong kho vẫn còn một ít hàng tồn nhưng e là không trụ được qua tháng này."}],"related":[{"hanzi":"大量","pinyin":"dàliàng","vi":"lượng lớn"},{"hanzi":"适量","pinyin":"shìliàng","vi":"vừa phải"},{"hanzi":"一些","pinyin":"yìxiē","vi":"một vài, một ít"},{"hanzi":"微量","pinyin":"wēiliàng","vi":"vi lượng"}]},{"id":"少林寺","hanzi":"少林寺","pinyin":"Shàolínsì","meaning_vi":"chùa Thiếu Lâm","explanation":"少林 (Thiếu Lâm) + 寺 (tự – chùa) → ngôi chùa ở Hà Nam, Trung Quốc, nổi tiếng với võ công Thiếu Lâm.","hsk_level":"7-9","tags":["danh-tu","dia-danh"],"image":"🥋","examples":[{"type":"basic","zh":"少林寺在河南。","pinyin":"Shàolínsì zài Hénán.","vi":"Chùa Thiếu Lâm ở Hà Nam."},{"type":"simple","zh":"很多外国人专门去少林寺学武术。","pinyin":"Hěn duō wàiguórén zhuānmén qù Shàolínsì xué wǔshù.","vi":"Nhiều người nước ngoài đến tận chùa Thiếu Lâm để học võ."},{"type":"compound","zh":"虽然少林寺已经有一千多年的历史，但是每年仍吸引大量游客。","pinyin":"Suīrán Shàolínsì yǐjīng yǒu yī qiān duōnián de lìshǐ, dànshì měinián réng xīyǐn dàliàng yóukè.","vi":"Tuy chùa Thiếu Lâm đã có hơn nghìn năm lịch sử nhưng hằng năm vẫn thu hút rất nhiều du khách."}],"related":[{"hanzi":"武术","pinyin":"wǔshù","vi":"võ thuật"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"công phu, kung fu"},{"hanzi":"寺庙","pinyin":"sìmiào","vi":"chùa chiền"},{"hanzi":"和尚","pinyin":"héshang","vi":"hòa thượng"}]},{"id":"少女","hanzi":"少女","pinyin":"shàonǚ","meaning_vi":"thiếu nữ, cô gái trẻ","explanation":"少 (thiếu – trẻ) + 女 (nữ – con gái) → cô gái tuổi mới lớn.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👧","examples":[{"type":"basic","zh":"她已经是个少女了。","pinyin":"Tā yǐjīng shì ge shàonǚ le.","vi":"Cô bé đã thành thiếu nữ rồi."},{"type":"simple","zh":"画中的少女穿着一条白色长裙。","pinyin":"Huà zhōng de shàonǚ chuānzhe yì tiáo báisè chángqún.","vi":"Thiếu nữ trong tranh mặc một chiếc váy dài màu trắng."},{"type":"compound","zh":"虽然她已经四十岁了，但是心态还像个少女一样。","pinyin":"Suīrán tā yǐjīng sìshí suì le, dànshì xīntài hái xiàng ge shàonǚ yíyàng.","vi":"Tuy đã bốn mươi tuổi nhưng tâm hồn cô ấy vẫn như một thiếu nữ."}],"related":[{"hanzi":"少年","pinyin":"shàonián","vi":"thiếu niên"},{"hanzi":"姑娘","pinyin":"gūniang","vi":"cô gái"},{"hanzi":"女孩","pinyin":"nǚhái","vi":"bé gái"},{"hanzi":"妇女","pinyin":"fùnǚ","vi":"phụ nữ"}]},{"id":"少有","hanzi":"少有","pinyin":"shǎoyǒu","meaning_vi":"hiếm có, ít có","explanation":"少 (thiểu – ít) + 有 (hữu – có) → ít khi có, hiếm có.","hsk_level":"7-9","tags":["tinh-tu","so-luong"],"image":"💎","examples":[{"type":"basic","zh":"这是少有的好机会。","pinyin":"Zhè shì shǎoyǒu de hǎo jīhuì.","vi":"Đây là cơ hội tốt hiếm có."},{"type":"simple","zh":"今年夏天出现了几十年少有的高温。","pinyin":"Jīnnián xiàtiān chūxiànle jǐ shí niánshǎo yǒude gāowēn.","vi":"Mùa hè năm nay xuất hiện đợt nắng nóng hiếm có trong mấy chục năm."},{"type":"compound","zh":"像他这样既聪明又勤奋的学生，在我们学校是少有的。","pinyin":"Xiàng tā zhèyàng jì cōngmíng yòu qínfèn de xuésheng, zài wǒmen xuéxiào shì shǎoyǒu de.","vi":"Học sinh vừa thông minh vừa chăm chỉ như cậu ấy là hiếm có ở trường chúng tôi."}],"related":[{"hanzi":"少见","pinyin":"shǎojiàn","vi":"ít thấy"},{"hanzi":"罕有","pinyin":"hǎnyǒu","vi":"hiếm có"},{"hanzi":"难得","pinyin":"nándé","vi":"khó có được"},{"hanzi":"常有","pinyin":"chángyǒu","vi":"thường có"}]},{"id":"奢望","hanzi":"奢望","pinyin":"shēwàng","meaning_vi":"hy vọng xa vời, mong ước quá đáng","explanation":"奢 (xa – quá mức) + 望 (vọng – mong) → mong muốn vượt quá khả năng, khó thành hiện thực.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🌠","examples":[{"type":"basic","zh":"我没有别的奢望。","pinyin":"Wǒ méiyǒu biéde shēwàng.","vi":"Tôi không có mong ước xa vời nào khác."},{"type":"simple","zh":"对他来说，出国留学只是一个奢望。","pinyin":"Duì tā lái shuō, chūguó liúxué zhǐshì yí gè shēwàng.","vi":"Với cậu ấy, du học chỉ là một ước mơ xa vời."},{"type":"compound","zh":"既然他已经变了心，你就不要再奢望他会回来了。","pinyin":"Jìrán tā yǐjīng biànle xīn, nǐ jiù bú yào zài shēwàng tā huì huílái le.","vi":"Anh ta đã thay lòng rồi thì cậu đừng mong anh ta quay lại nữa."}],"related":[{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"},{"hanzi":"愿望","pinyin":"yuànwàng","vi":"nguyện vọng"},{"hanzi":"奢侈","pinyin":"shēchǐ","vi":"xa xỉ"},{"hanzi":"妄想","pinyin":"wàngxiǎng","vi":"vọng tưởng"}]},{"id":"设","hanzi":"设","pinyin":"shè","meaning_vi":"đặt, thiết lập, bố trí; giả sử","explanation":"设 (thiết – đặt bày) → thành lập, bố trí (设立, 设置); trong toán học nghĩa là giả sử, cho.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"学校设了奖学金。","pinyin":"Xuéxiào shèle jiǎngxuéjīn.","vi":"Nhà trường đã lập quỹ học bổng."},{"type":"simple","zh":"这家公司在上海设了一个办事处。","pinyin":"Zhè jiā gōngsī zài Shànghǎi shèle yí gè bànshìchù.","vi":"Công ty này đã đặt một văn phòng đại diện ở Thượng Hải."},{"type":"compound","zh":"如果设甲的速度是乙的两倍，那么这道题就很容易解了。","pinyin":"Rúguǒ shè jiǎ de sùdù shì yǐ de liǎngbèi, nàme zhè dào tí jiù hěn róngyì jiě le.","vi":"Nếu giả sử tốc độ của A gấp đôi B thì bài này sẽ rất dễ giải."}],"related":[{"hanzi":"设立","pinyin":"shèlì","vi":"thành lập"},{"hanzi":"设置","pinyin":"shèzhì","vi":"cài đặt, bố trí"},{"hanzi":"假设","pinyin":"jiǎshè","vi":"giả thiết"},{"hanzi":"建设","pinyin":"jiànshè","vi":"xây dựng"}],"traditional":"設"},{"id":"设定","hanzi":"设定","pinyin":"shèdìng","meaning_vi":"cài đặt, thiết lập, quy định","explanation":"设 (thiết – đặt) + 定 (định – cố định) → đặt ra và cố định một giá trị, mục tiêu, chế độ.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"⚙️","examples":[{"type":"basic","zh":"我设定了闹钟。","pinyin":"Wǒ shèdìngle nàozhōng.","vi":"Tôi đã đặt chuông báo thức."},{"type":"simple","zh":"你可以在手机里设定字体的大小。","pinyin":"Nǐ kěyǐ zài shǒujī lǐ shèdìng zìtǐ de dàxiǎo.","vi":"Bạn có thể cài đặt cỡ chữ trong điện thoại."},{"type":"compound","zh":"只要设定一个明确的目标，你就会更有动力去努力。","pinyin":"Zhǐyào shèdìng yí gè míngquè de mùbiāo, nǐ jiù huì gèng yǒu dònglì qù nǔlì.","vi":"Chỉ cần đặt ra một mục tiêu rõ ràng, bạn sẽ có thêm động lực để cố gắng."}],"related":[{"hanzi":"设置","pinyin":"shèzhì","vi":"cài đặt"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"},{"hanzi":"预设","pinyin":"yùshè","vi":"thiết lập sẵn"},{"hanzi":"制定","pinyin":"zhìdìng","vi":"đặt ra"}],"traditional":"設定"},{"id":"社会主义","hanzi":"社会主义","pinyin":"shèhuìzhǔyì","meaning_vi":"chủ nghĩa xã hội","explanation":"社会 (xã hội) + 主义 (chủ nghĩa) → học thuyết và chế độ xã hội lấy công hữu làm nền tảng.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"这是社会主义国家。","pinyin":"Zhè shì shèhuìzhǔyì guójiā.","vi":"Đây là nước xã hội chủ nghĩa."},{"type":"simple","zh":"越南正在走社会主义发展道路。","pinyin":"Yuènán zhèngzài zǒu shèhuìzhǔyì fāzhǎn dàolù.","vi":"Việt Nam đang đi theo con đường phát triển xã hội chủ nghĩa."},{"type":"compound","zh":"虽然很多国家都实行过社会主义，但是具体做法很不一样。","pinyin":"Suīrán hěn duō guójiā dōu shíxíngguo shèhuìzhǔyì, dànshì jùtǐ zuòfǎ hěn bù yíyàng.","vi":"Tuy nhiều nước từng thực hiện chủ nghĩa xã hội nhưng cách làm cụ thể rất khác nhau."}],"related":[{"hanzi":"资本主义","pinyin":"zīběnzhǔyì","vi":"chủ nghĩa tư bản"},{"hanzi":"共产主义","pinyin":"gòngchǎnzhǔyì","vi":"chủ nghĩa cộng sản"},{"hanzi":"社会","pinyin":"shèhuì","vi":"xã hội"},{"hanzi":"制度","pinyin":"zhìdù","vi":"chế độ"}],"traditional":"社會主義"},{"id":"社交","hanzi":"社交","pinyin":"shèjiāo","meaning_vi":"giao tiếp xã hội, giao thiệp","explanation":"社 (xã – xã hội) + 交 (giao – qua lại) → quan hệ qua lại, giao lưu giữa người với người trong xã hội.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🥂","examples":[{"type":"basic","zh":"他不太喜欢社交。","pinyin":"Tā bú tài xǐhuan shèjiāo.","vi":"Anh ấy không thích giao thiệp lắm."},{"type":"simple","zh":"现在年轻人每天都离不开社交软件。","pinyin":"Xiànzài niánqīngrén měitiān dōu líbukāi shèjiāo ruǎnjiàn.","vi":"Giới trẻ bây giờ ngày nào cũng không rời được ứng dụng mạng xã hội."},{"type":"compound","zh":"虽然她在社交场合很活跃，但是私下里其实很内向。","pinyin":"Suīrán tā zài shèjiāo chǎnghé hěn huóyuè, dànshì sīxià lǐ qíshí hěn nèixiàng.","vi":"Tuy cô ấy rất sôi nổi ở những dịp giao tế nhưng thực ra lúc riêng tư lại rất hướng nội."}],"related":[{"hanzi":"交际","pinyin":"jiāojì","vi":"giao tiếp"},{"hanzi":"社交网络","pinyin":"shèjiāowǎngluò","vi":"mạng xã hội"},{"hanzi":"交往","pinyin":"jiāowǎng","vi":"qua lại"},{"hanzi":"应酬","pinyin":"yìngchou","vi":"tiệc tùng xã giao"}]},{"id":"社论","hanzi":"社论","pinyin":"shèlùn","meaning_vi":"xã luận, bài xã luận","explanation":"社 (xã – tòa soạn) + 论 (luận – bàn luận) → bài bình luận thể hiện quan điểm chính thức của tòa báo.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📰","examples":[{"type":"basic","zh":"今天的社论很精彩。","pinyin":"Jīntiān de shèlùn hěn jīngcǎi.","vi":"Bài xã luận hôm nay rất hay."},{"type":"simple","zh":"这家报纸发表社论批评了这项政策。","pinyin":"Zhè jiā bàozhǐ fābiǎo shèlùn pīpíngle zhè xiàng zhèngcè.","vi":"Tờ báo này đăng xã luận phê phán chính sách đó."},{"type":"compound","zh":"因为社论代表报社的立场，所以写的时候要特别谨慎。","pinyin":"Yīnwèi shèlùn dàibiǎo bàoshè de lìchǎng, suǒyǐ xiě de shíhou yào tèbié jǐnshèn.","vi":"Vì xã luận đại diện cho lập trường của tòa báo nên khi viết phải đặc biệt thận trọng."}],"related":[{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"},{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"báo"},{"hanzi":"专栏","pinyin":"zhuānlán","vi":"chuyên mục"},{"hanzi":"报社","pinyin":"bàoshè","vi":"tòa soạn"}],"traditional":"社論"},{"id":"涉嫌","hanzi":"涉嫌","pinyin":"shèxián","meaning_vi":"bị tình nghi, bị nghi ngờ (phạm tội)","explanation":"涉 (thiệp – dính líu) + 嫌 (hiềm – nghi ngờ) → dính líu đến và bị nghi ngờ có liên quan tới tội phạm.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚔","examples":[{"type":"basic","zh":"他涉嫌受贿。","pinyin":"Tā shèxián shòuhuì.","vi":"Ông ta bị tình nghi nhận hối lộ."},{"type":"simple","zh":"两名男子因涉嫌盗窃被警方带走。","pinyin":"Liǎng míng nánzǐ yīn shèxián dàoqiè bèi jǐngfāng dàizǒu.","vi":"Hai người đàn ông bị cảnh sát đưa đi vì tình nghi trộm cắp."},{"type":"compound","zh":"虽然他涉嫌诈骗，但是在法院判决之前还不能算罪犯。","pinyin":"Suīrán tā shèxián zhàpiàn, dànshì zài fǎyuàn pànjué zhīqián hái bù néng suàn zuìfàn.","vi":"Tuy anh ta bị tình nghi lừa đảo nhưng trước khi tòa tuyên án thì chưa thể coi là tội phạm."}],"related":[{"hanzi":"嫌疑","pinyin":"xiányí","vi":"hiềm nghi"},{"hanzi":"嫌疑人","pinyin":"xiányírén","vi":"nghi phạm"},{"hanzi":"涉及","pinyin":"shèjí","vi":"liên quan đến"},{"hanzi":"犯罪","pinyin":"fànzuì","vi":"phạm tội"}]},{"id":"申办","hanzi":"申办","pinyin":"shēnbàn","meaning_vi":"xin đăng cai, nộp đơn xin làm (thủ tục)","explanation":"申 (thân – trình bày, xin) + 办 (biện – làm, tổ chức) → đăng ký xin được tổ chức sự kiện hoặc xin làm thủ tục.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏟️","examples":[{"type":"basic","zh":"这座城市申办奥运会。","pinyin":"Zhè zuò chéngshì shēnbàn Àoyùnhuì.","vi":"Thành phố này xin đăng cai Thế vận hội."},{"type":"simple","zh":"我去银行申办了一张信用卡。","pinyin":"Wǒqù yínháng shēnbànle yì zhāng xìnyòngkǎ.","vi":"Tôi đã đến ngân hàng làm thủ tục mở một thẻ tín dụng."},{"type":"compound","zh":"虽然这次申办没有成功，但是城市的知名度提高了不少。","pinyin":"Suīrán zhè cì shēnbàn méiyǒu chénggōng, dànshì chéngshì de zhīmíngdù tígāole bùshǎo.","vi":"Tuy lần xin đăng cai này không thành công nhưng độ nổi tiếng của thành phố đã tăng lên đáng kể."}],"related":[{"hanzi":"申请","pinyin":"shēnqǐng","vi":"xin, nộp đơn"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"tổ chức"},{"hanzi":"主办","pinyin":"zhǔbàn","vi":"chủ trì tổ chức"},{"hanzi":"办理","pinyin":"bànlǐ","vi":"làm thủ tục"}],"traditional":"申辦"},{"id":"申领","hanzi":"申领","pinyin":"shēnlǐng","meaning_vi":"xin cấp, đăng ký nhận (giấy tờ, trợ cấp)","explanation":"申 (thân – xin) + 领 (lĩnh – nhận) → làm đơn xin và nhận giấy phép, thẻ, trợ cấp…","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🪪","examples":[{"type":"basic","zh":"我去申领护照。","pinyin":"Wǒqù shēnlǐng hùzhào.","vi":"Tôi đi xin cấp hộ chiếu."},{"type":"simple","zh":"失业人员可以申领失业保险金。","pinyin":"Shīyè rényuán kěyǐ shēnlǐng shīyèbǎoxiǎn jīn.","vi":"Người thất nghiệp có thể đăng ký nhận trợ cấp bảo hiểm thất nghiệp."},{"type":"compound","zh":"如果你想申领驾驶证，就必须先通过驾驶考试。","pinyin":"Rúguǒ nǐ xiǎng shēnlǐng jiàshǐzhèng, jiù bìxū xiān tōngguò jiàshǐ kǎoshì.","vi":"Nếu muốn xin cấp bằng lái thì bạn phải thi đỗ sát hạch lái xe trước."}],"related":[{"hanzi":"申请","pinyin":"shēnqǐng","vi":"xin, nộp đơn"},{"hanzi":"领取","pinyin":"lǐngqǔ","vi":"nhận, lĩnh"},{"hanzi":"办理","pinyin":"bànlǐ","vi":"làm thủ tục"},{"hanzi":"证件","pinyin":"zhèngjiàn","vi":"giấy tờ"}],"traditional":"申領"},{"id":"伸手","hanzi":"伸手","pinyin":"shēnshǒu","meaning_vi":"giơ tay, chìa tay, đưa tay ra; (nghĩa bóng) xin xỏ, nhúng tay","explanation":"伸 (thân – duỗi ra) + 手 (thủ – tay) → duỗi tay ra; nghĩa bóng là ngửa tay xin hoặc can thiệp vào việc gì.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"🤚","examples":[{"type":"basic","zh":"他伸手拿了一本书。","pinyin":"Tā shēnshǒu nále yì běn shū.","vi":"Anh ấy đưa tay lấy một cuốn sách."},{"type":"simple","zh":"天太黑了，伸手不见五指。","pinyin":"Tiān tài hēi le, shēnshǒu bújiàn wǔzhǐ.","vi":"Trời tối quá, giơ tay không thấy năm ngón."},{"type":"compound","zh":"虽然他已经工作了，但是还常常向父母伸手要钱。","pinyin":"Suīrán tā yǐjīng gōngzuò le, dànshì hái chángcháng xiàng fùmǔ shēnshǒu yàoqián.","vi":"Tuy đã đi làm nhưng anh ta vẫn thường xuyên ngửa tay xin tiền bố mẹ."}],"related":[{"hanzi":"伸出","pinyin":"shēnchū","vi":"chìa ra"},{"hanzi":"援手","pinyin":"yuánshǒu","vi":"bàn tay giúp đỡ"},{"hanzi":"缩手","pinyin":"suōshǒu","vi":"rụt tay"},{"hanzi":"握手","pinyin":"wòshǒu","vi":"bắt tay"}]},{"id":"伸缩","hanzi":"伸缩","pinyin":"shēnsuō","meaning_vi":"co giãn, kéo ra thu vào; linh hoạt","explanation":"伸 (thân – duỗi ra) + 缩 (súc – co lại) → có thể kéo dài và thu ngắn; nghĩa bóng là có độ linh hoạt.","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"↔️","examples":[{"type":"basic","zh":"这根杆子能伸缩。","pinyin":"Zhè gēn gānzi néng shēnsuō.","vi":"Cây sào này có thể kéo ra thu vào."},{"type":"simple","zh":"我买了一把可以伸缩的自拍杆。","pinyin":"Wǒ mǎile yì bǎ kěyǐ shēnsuō de zìpāigān.","vi":"Tôi mua một cây gậy tự sướng có thể co giãn."},{"type":"compound","zh":"既然计划还有伸缩的余地，我们就再讨论一下细节吧。","pinyin":"Jìrán jìhuà háiyǒu shēnsuō de yúdì, wǒmen jiù zài tǎolùn yíxià xìjié ba.","vi":"Kế hoạch vẫn còn chỗ linh hoạt thì chúng ta bàn thêm chi tiết nhé."}],"related":[{"hanzi":"伸展","pinyin":"shēnzhǎn","vi":"duỗi ra"},{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"},{"hanzi":"弹性","pinyin":"tánxìng","vi":"tính đàn hồi"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"}],"traditional":"伸縮"},{"id":"伸张","hanzi":"伸张","pinyin":"shēnzhāng","meaning_vi":"đề cao, bảo vệ, làm sáng tỏ (chính nghĩa)","explanation":"伸 (thân – duỗi ra, làm sáng) + 张 (trương – mở rộng) → làm cho lẽ phải, chính nghĩa được thực thi; thường gặp 伸张正义.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"我们要伸张正义。","pinyin":"Wǒmen yào shēnzhāng zhèngyì.","vi":"Chúng ta phải bảo vệ lẽ phải."},{"type":"simple","zh":"法律的作用之一就是伸张公平和正义。","pinyin":"Fǎlǜ de zuòyòng zhīyí jiùshì shēnzhāng gōng pínghé zhèngyì.","vi":"Một trong những tác dụng của pháp luật là thực thi công bằng và chính nghĩa."},{"type":"compound","zh":"只要大家敢于站出来，正义就一定能得到伸张。","pinyin":"Zhǐyào dàjiā gǎnyú zhàn chūlái, zhèngyì jiù yídìng néng dédào shēnzhāng.","vi":"Chỉ cần mọi người dám đứng lên thì chính nghĩa nhất định sẽ được thực thi."}],"related":[{"hanzi":"正义","pinyin":"zhèngyì","vi":"chính nghĩa"},{"hanzi":"主张","pinyin":"zhǔzhāng","vi":"chủ trương"},{"hanzi":"维护","pinyin":"wéihù","vi":"bảo vệ"},{"hanzi":"弘扬","pinyin":"hóngyáng","vi":"phát huy"}],"traditional":"伸張"},{"id":"身躯","hanzi":"身躯","pinyin":"shēnqū","meaning_vi":"thân hình, thân thể, tấm thân","explanation":"身 (thân – thân thể) + 躯 (khu – thân mình) → toàn bộ thân thể, thường nhấn mạnh vóc dáng; sắc thái văn viết.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🧍","examples":[{"type":"basic","zh":"他身躯高大。","pinyin":"Tā shēnqū gāodà.","vi":"Anh ấy có thân hình cao lớn."},{"type":"simple","zh":"老人拖着疲惫的身躯走回了家。","pinyin":"Lǎorén tuōzhe píbèi de shēnqū zǒu huíle jiā.","vi":"Ông lão lê tấm thân mệt mỏi trở về nhà."},{"type":"compound","zh":"虽然她身躯瘦小，但是能扛起一大袋米。","pinyin":"Suīrán tā shēnqū shòuxiǎo, dànshì néng káng qǐ yí dà dài mǐ.","vi":"Tuy thân hình nhỏ bé nhưng cô ấy có thể vác nổi cả bao gạo lớn."}],"related":[{"hanzi":"身体","pinyin":"shēntǐ","vi":"cơ thể"},{"hanzi":"身材","pinyin":"shēncái","vi":"vóc dáng"},{"hanzi":"躯体","pinyin":"qūtǐ","vi":"thân thể"},{"hanzi":"身子","pinyin":"shēnzi","vi":"thân mình"}],"traditional":"身軀"},{"id":"身心","hanzi":"身心","pinyin":"shēnxīn","meaning_vi":"thể chất và tinh thần, thân tâm","explanation":"身 (thân – cơ thể) + 心 (tâm – tinh thần) → cả thể xác lẫn tâm hồn.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🧘‍♀️","examples":[{"type":"basic","zh":"运动有益身心健康。","pinyin":"Yùndòng yǒuyì shēnxīn jiànkāng.","vi":"Vận động có lợi cho sức khỏe thể chất và tinh thần."},{"type":"simple","zh":"忙了一年，他觉得身心都很疲惫。","pinyin":"Mángle yì nián, tā juéde shēnxīn dōu hěn píbèi.","vi":"Bận rộn suốt một năm, anh ấy thấy cả thân lẫn tâm đều mệt mỏi."},{"type":"compound","zh":"如果长期压力太大，身心就会出现各种问题。","pinyin":"Rúguǒ chángqī yālì tài dà, shēnxīn jiù huì chūxiàn gèzhǒng wèntí.","vi":"Nếu áp lực quá lớn trong thời gian dài thì cả thể chất lẫn tinh thần sẽ gặp đủ thứ vấn đề."}],"related":[{"hanzi":"身体","pinyin":"shēntǐ","vi":"cơ thể"},{"hanzi":"心理","pinyin":"xīnlǐ","vi":"tâm lý"},{"hanzi":"全身心","pinyin":"quánshēnxīn","vi":"toàn tâm toàn ý"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"sức khỏe"}]},{"id":"身影","hanzi":"身影","pinyin":"shēnyǐng","meaning_vi":"bóng dáng, hình bóng","explanation":"身 (thân – thân hình) + 影 (ảnh – bóng) → dáng người nhìn thấy mờ mờ hoặc từ xa.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👤","examples":[{"type":"basic","zh":"我看到了他的身影。","pinyin":"Wǒ kàndàole tā de shēnyǐng.","vi":"Tôi đã nhìn thấy bóng dáng anh ấy."},{"type":"simple","zh":"她的身影慢慢消失在人群中。","pinyin":"Tā de shēnyǐng mànmàn xiāoshī zài rénqún zhōng.","vi":"Bóng dáng cô ấy dần khuất trong đám đông."},{"type":"compound","zh":"每当我走进厨房，就会想起妈妈忙碌的身影。","pinyin":"Měidāng wǒ zǒujìn chúfáng, jiù huì xiǎngqǐ māma mánglù de shēnyǐng.","vi":"Mỗi khi bước vào bếp, tôi lại nhớ đến bóng dáng tất bật của mẹ."}],"related":[{"hanzi":"背影","pinyin":"bèiyǐng","vi":"bóng lưng"},{"hanzi":"影子","pinyin":"yǐngzi","vi":"cái bóng"},{"hanzi":"身形","pinyin":"shēnxíng","vi":"dáng người"},{"hanzi":"人影","pinyin":"rényǐng","vi":"bóng người"}]},{"id":"身子","hanzi":"身子","pinyin":"shēnzi","meaning_vi":"thân mình, cơ thể; sức khỏe; (khẩu ngữ) có mang","explanation":"身 (thân – thân thể) + 子 (hậu tố) → thân mình, cơ thể trong khẩu ngữ; cũng chỉ sức khỏe hay việc mang thai.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🙆","examples":[{"type":"basic","zh":"他转过身子走了。","pinyin":"Tā zhuǎnguò shēnzi zǒu le.","vi":"Anh ấy quay người bỏ đi."},{"type":"simple","zh":"奶奶最近身子不太好，常常咳嗽。","pinyin":"Nǎinai zuìjìn shēnzi bú tài hǎo, chángcháng késou.","vi":"Dạo này bà nội không khỏe lắm, hay bị ho."},{"type":"compound","zh":"既然你身子还没恢复，就别急着回去上班了。","pinyin":"Jìrán nǐ shēnzi hái méi huīfù, jiù bié jízhe huíqù shàngbān le.","vi":"Sức khỏe cậu còn chưa hồi phục thì đừng vội quay lại làm việc."}],"related":[{"hanzi":"身体","pinyin":"shēntǐ","vi":"cơ thể"},{"hanzi":"身躯","pinyin":"shēnqū","vi":"thân hình"},{"hanzi":"身材","pinyin":"shēncái","vi":"vóc dáng"},{"hanzi":"怀孕","pinyin":"huáiyùn","vi":"mang thai"}]},{"id":"深切","hanzi":"深切","pinyin":"shēnqiè","meaning_vi":"sâu sắc, tha thiết, chân thành","explanation":"深 (thâm – sâu) + 切 (thiết – thiết tha) → tình cảm sâu nặng, chân thành; thường gặp 深切怀念, 深切慰问.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💐","examples":[{"type":"basic","zh":"我们深切怀念他。","pinyin":"Wǒmen shēnqiè huáiniàn tā.","vi":"Chúng tôi tưởng nhớ ông ấy sâu sắc."},{"type":"simple","zh":"向遇难者家属表示深切的慰问。","pinyin":"Xiàng yùnànzhě jiāshǔ biǎoshì shēnqiè de wèiwèn.","vi":"Xin gửi lời thăm hỏi chân thành tới gia đình các nạn nhân."},{"type":"compound","zh":"只有亲身经历过，才能深切体会到父母的不容易。","pinyin":"Zhǐyǒu qīnshēn jīnglì guo, cáinéng shēnqiè tǐhuì dào fùmǔ de bù róngyì.","vi":"Chỉ khi tự mình trải qua mới thấu hiểu sâu sắc sự vất vả của cha mẹ."}],"related":[{"hanzi":"深刻","pinyin":"shēnkè","vi":"sâu sắc"},{"hanzi":"真切","pinyin":"zhēnqiè","vi":"chân thật"},{"hanzi":"亲切","pinyin":"qīnqiè","vi":"thân thiết"},{"hanzi":"深厚","pinyin":"shēnhòu","vi":"sâu đậm"}]},{"id":"深入人心","hanzi":"深入人心","pinyin":"shēnrù-rénxīn","meaning_vi":"đi sâu vào lòng người, ăn sâu vào lòng người","explanation":"Nghĩa đen: đi sâu vào lòng người → (tư tưởng, hình tượng, tác phẩm) được mọi người hiểu và đón nhận rộng rãi, thấm sâu trong tâm trí.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"❤️","examples":[{"type":"basic","zh":"这个观念深入人心。","pinyin":"Zhè ge guānniàn shēnrùrénxīn.","vi":"Quan niệm này đã ăn sâu vào lòng người."},{"type":"simple","zh":"电影里的英雄形象早已深入人心。","pinyin":"Diànyǐng lǐ de yīngxióng xíngxiàng zǎoyǐ shēnrùrénxīn.","vi":"Hình tượng người anh hùng trong phim từ lâu đã in sâu vào lòng người."},{"type":"compound","zh":"因为这首歌唱出了大家的心声，所以很快就深入人心。","pinyin":"Yīnwèi zhè shǒu gēchàng chūle dàjiā de xīnshēng, suǒyǐ hěn kuài jiù shēnrùrénxīn.","vi":"Vì bài hát này nói lên tiếng lòng của mọi người nên nhanh chóng đi vào lòng người."}],"related":[{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"},{"hanzi":"人心","pinyin":"rénxīn","vi":"lòng người"},{"hanzi":"深入","pinyin":"shēnrù","vi":"đi sâu"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"}]},{"id":"深受","hanzi":"深受","pinyin":"shēnshòu","meaning_vi":"rất được, chịu nhiều, chịu ảnh hưởng sâu sắc","explanation":"深 (thâm – sâu) + 受 (thụ – nhận, chịu) → nhận được ở mức độ sâu sắc, như 深受欢迎 (rất được yêu thích), 深受影响.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"👍","examples":[{"type":"basic","zh":"这本书深受欢迎。","pinyin":"Zhè běn shū shēnshòu huānyíng.","vi":"Cuốn sách này rất được yêu thích."},{"type":"simple","zh":"他从小深受父亲的影响，也当了医生。","pinyin":"Tā cóngxiǎo shēnshòu fùqīn de yǐngxiǎng, yě dāngle yīshēng.","vi":"Từ nhỏ anh ấy đã chịu ảnh hưởng sâu sắc của cha, cũng trở thành bác sĩ."},{"type":"compound","zh":"虽然这位老师要求很严，但是深受学生的尊敬。","pinyin":"Suīrán zhè wèi lǎoshī yāoqiú hěn yán, dànshì shēnshòu xuésheng de zūnjìng.","vi":"Tuy thầy giáo này rất nghiêm khắc nhưng được học sinh hết sức kính trọng."}],"related":[{"hanzi":"备受","pinyin":"bèishòu","vi":"được hết mực"},{"hanzi":"受到","pinyin":"shòudào","vi":"nhận được"},{"hanzi":"遭受","pinyin":"zāoshòu","vi":"gặp phải"},{"hanzi":"深得","pinyin":"shēndé","vi":"được rất nhiều"}]},{"id":"深思","hanzi":"深思","pinyin":"shēnsī","meaning_vi":"suy nghĩ sâu sắc, ngẫm kỹ","explanation":"深 (thâm – sâu) + 思 (tư – suy nghĩ) → nghĩ kỹ, nghĩ thấu đáo.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"这个问题值得深思。","pinyin":"Zhè ge wèntí zhíde shēnsī.","vi":"Vấn đề này đáng để suy ngẫm."},{"type":"simple","zh":"他的话让在场的每个人都陷入了深思。","pinyin":"Tā dehuà ràng zài chǎng de měigèrén dōu xiànrùle shēnsī.","vi":"Lời anh ấy khiến mọi người có mặt đều chìm vào suy tư."},{"type":"compound","zh":"如果你不经过深思就做决定，以后很可能会后悔。","pinyin":"Rúguǒ nǐ bù jīngguò shēnsī jiù zuò juédìng, yǐhòu hěn kěnéng huì hòuhuǐ.","vi":"Nếu bạn quyết định mà không suy nghĩ kỹ thì sau này rất có thể sẽ hối hận."}],"related":[{"hanzi":"思考","pinyin":"sīkǎo","vi":"suy nghĩ"},{"hanzi":"沉思","pinyin":"chénsī","vi":"trầm tư"},{"hanzi":"反思","pinyin":"fǎnsī","vi":"suy ngẫm lại"},{"hanzi":"深思熟虑","pinyin":"shēnsīshúlǜ","vi":"suy tính kỹ càng"}]},{"id":"深信","hanzi":"深信","pinyin":"shēnxìn","meaning_vi":"tin chắc, tin tưởng sâu sắc","explanation":"深 (thâm – sâu) + 信 (tín – tin) → tin tưởng một cách chắc chắn, không chút nghi ngờ.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🙏","examples":[{"type":"basic","zh":"我深信他是无辜的。","pinyin":"Wǒ shēnxìn tā shì wúgū de.","vi":"Tôi tin chắc anh ấy vô tội."},{"type":"simple","zh":"她深信只要努力就一定会有回报。","pinyin":"Tā shēnxìn zhǐyào nǔlì jiù yídìng huì yǒu huíbào.","vi":"Cô ấy tin chắc rằng chỉ cần cố gắng thì nhất định sẽ được đền đáp."},{"type":"compound","zh":"虽然大家都反对，但是他深信自己的选择是对的。","pinyin":"Suīrán dàjiā dōu fǎnduì, dànshì tā shēnxìn zìjǐ de xuǎnzé shì duì de.","vi":"Tuy mọi người đều phản đối nhưng anh ấy tin chắc lựa chọn của mình là đúng."}],"related":[{"hanzi":"相信","pinyin":"xiāngxìn","vi":"tin tưởng"},{"hanzi":"坚信","pinyin":"jiānxìn","vi":"tin chắc"},{"hanzi":"确信","pinyin":"quèxìn","vi":"xác tín"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"}]},{"id":"深夜","hanzi":"深夜","pinyin":"shēnyè","meaning_vi":"đêm khuya, nửa đêm","explanation":"深 (thâm – sâu) + 夜 (dạ – đêm) → lúc đêm đã về khuya.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌙","examples":[{"type":"basic","zh":"他常常工作到深夜。","pinyin":"Tā chángcháng gōngzuò dào shēnyè.","vi":"Anh ấy thường làm việc đến tận khuya."},{"type":"simple","zh":"深夜的街道上几乎看不到行人。","pinyin":"Shēnyè de jiēdào shàng jīhū kàn búdào xíngrén.","vi":"Trên đường phố lúc đêm khuya gần như không thấy người đi lại."},{"type":"compound","zh":"如果你深夜还不睡觉，第二天就很难打起精神。","pinyin":"Rúguǒ nǐ shēnyè hái bú shuìjiào, dì'èrtiān jiù hěn nán dǎ qǐ jīngshen.","vi":"Nếu đêm khuya rồi mà bạn vẫn chưa ngủ thì hôm sau sẽ rất khó tỉnh táo."}],"related":[{"hanzi":"半夜","pinyin":"bànyè","vi":"nửa đêm"},{"hanzi":"午夜","pinyin":"wǔyè","vi":"nửa đêm"},{"hanzi":"夜晚","pinyin":"yèwǎn","vi":"buổi tối"},{"hanzi":"凌晨","pinyin":"língchén","vi":"rạng sáng"}]},{"id":"深远","hanzi":"深远","pinyin":"shēnyuǎn","meaning_vi":"sâu xa, sâu rộng, lâu dài","explanation":"深 (thâm – sâu) + 远 (viễn – xa) → (ảnh hưởng, ý nghĩa) vừa sâu sắc vừa lâu dài.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🌊","examples":[{"type":"basic","zh":"这件事影响深远。","pinyin":"Zhè jiàn shì yǐngxiǎng shēnyuǎn.","vi":"Việc này có ảnh hưởng sâu rộng."},{"type":"simple","zh":"这次改革具有深远的历史意义。","pinyin":"Zhè cì gǎigé jùyǒu shēnyuǎn de lìshǐ yìyì.","vi":"Cuộc cải cách này có ý nghĩa lịch sử sâu xa."},{"type":"compound","zh":"虽然那本书出版得很早，但是对后人的影响非常深远。","pinyin":"Suīrán nà běn shū chūbǎn de hěn zǎo, dànshì duì hòurén de yǐngxiǎng fēicháng shēnyuǎn.","vi":"Tuy cuốn sách đó xuất bản từ rất sớm nhưng ảnh hưởng tới hậu thế vô cùng sâu rộng."}],"related":[{"hanzi":"深刻","pinyin":"shēnkè","vi":"sâu sắc"},{"hanzi":"长远","pinyin":"chángyuǎn","vi":"lâu dài"},{"hanzi":"重大","pinyin":"zhòngdà","vi":"to lớn"},{"hanzi":"久远","pinyin":"jiǔyuǎn","vi":"lâu đời"}],"traditional":"深遠"},{"id":"甚至于","hanzi":"甚至于","pinyin":"shènzhìyú","meaning_vi":"thậm chí, đến nỗi, thậm chí đến mức","explanation":"甚至 (thậm chí) + 于 (ư – đến) → nhấn mạnh mức độ cao nhất, nghĩa như 甚至 nhưng trang trọng hơn.","hsk_level":"7-9","tags":["lien-tu","ngon-ngu"],"image":"❗","examples":[{"type":"basic","zh":"他忙得甚至于忘了吃饭。","pinyin":"Tā máng de shènzhìyú wàngle chīfàn.","vi":"Anh ấy bận đến mức quên cả ăn cơm."},{"type":"simple","zh":"这件事大人知道，甚至于连孩子都知道。","pinyin":"Zhè jiàn shì dàrén zhīdào, shènzhìyú lián háizi dōu zhīdào.","vi":"Chuyện này người lớn biết, thậm chí đến trẻ con cũng biết."},{"type":"compound","zh":"他不但不道歉，甚至于还把责任推到了别人身上。","pinyin":"Tā búdàn bú dàoqiàn, shènzhìyú hái bǎ zérèn tuī dàole biérén shēnshàng.","vi":"Anh ta không những không xin lỗi mà thậm chí còn đổ trách nhiệm lên người khác."}],"related":[{"hanzi":"甚至","pinyin":"shènzhì","vi":"thậm chí"},{"hanzi":"以至于","pinyin":"yǐzhìyú","vi":"đến nỗi"},{"hanzi":"乃至","pinyin":"nǎizhì","vi":"thậm chí"},{"hanzi":"甚而","pinyin":"shèn'ér","vi":"thậm chí"}],"traditional":"甚至於"},{"id":"审","hanzi":"审","pinyin":"shěn","meaning_vi":"xét, thẩm tra; xét xử; duyệt","explanation":"审 (thẩm – xem xét kỹ) → xem xét cẩn thận (审稿 duyệt bài), thẩm vấn hoặc xét xử tại tòa.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"这份稿子我审过了。","pinyin":"Zhè fèn gǎozi wǒ shěnguo le.","vi":"Bản thảo này tôi đã duyệt rồi."},{"type":"simple","zh":"这个案子由王法官来审。","pinyin":"Zhè ge ànzi yóu wáng fǎguān lái shěn.","vi":"Vụ án này do thẩm phán Vương xét xử."},{"type":"compound","zh":"既然材料已经交上去了，那就等领导审完再说吧。","pinyin":"Jìrán cáiliào yǐjīng jiāo shàngqù le, nà jiù děng lǐngdǎo shěn wán zàishuō ba.","vi":"Hồ sơ đã nộp lên rồi thì đợi lãnh đạo duyệt xong rồi tính."}],"related":[{"hanzi":"审查","pinyin":"shěnchá","vi":"thẩm tra"},{"hanzi":"审判","pinyin":"shěnpàn","vi":"xét xử"},{"hanzi":"审批","pinyin":"shěnpī","vi":"xét duyệt"},{"hanzi":"审美","pinyin":"shěnměi","vi":"thẩm mỹ"}],"traditional":"審"},{"id":"审定","hanzi":"审定","pinyin":"shěndìng","meaning_vi":"thẩm định, xét duyệt, phê duyệt","explanation":"审 (thẩm – xem xét) + 定 (định – quyết định) → xem xét kỹ rồi quyết định thông qua.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"教材已经审定了。","pinyin":"Jiàocái yǐjīng shěndìng le.","vi":"Giáo trình đã được thẩm định xong."},{"type":"simple","zh":"新词典需要专家审定后才能出版。","pinyin":"Xīn cídiǎn xūyào zhuānjiā shěndìng hòu cáinéng chūbǎn.","vi":"Từ điển mới phải được chuyên gia thẩm định rồi mới xuất bản được."},{"type":"compound","zh":"只要方案通过了委员会审定，我们就可以马上施工。","pinyin":"Zhǐyào fāng'àn tōngguòle wěiyuánhuì shěndìng, wǒmen jiù kěyǐ mǎshàng shīgōng.","vi":"Chỉ cần phương án được hội đồng phê duyệt là chúng ta có thể thi công ngay."}],"related":[{"hanzi":"审核","pinyin":"shěnhé","vi":"thẩm tra"},{"hanzi":"审批","pinyin":"shěnpī","vi":"xét duyệt"},{"hanzi":"鉴定","pinyin":"jiàndìng","vi":"giám định"},{"hanzi":"批准","pinyin":"pīzhǔn","vi":"phê chuẩn"}],"traditional":"審定"},{"id":"审核","hanzi":"审核","pinyin":"shěnhé","meaning_vi":"thẩm tra, xét duyệt, kiểm duyệt","explanation":"审 (thẩm – xem xét) + 核 (hạch – đối chiếu, kiểm tra) → kiểm tra đối chiếu kỹ lưỡng (tài liệu, số liệu, hồ sơ).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🗂️","examples":[{"type":"basic","zh":"你的申请正在审核中。","pinyin":"Nǐ de shēnqǐng zhèngzài shěnhé zhōng.","vi":"Đơn của bạn đang được xét duyệt."},{"type":"simple","zh":"财务部门每个月都要审核账目。","pinyin":"Cáiwù bùmén měi gèyuè dōu yào shěnhé zhàngmù.","vi":"Phòng tài chính tháng nào cũng phải kiểm tra sổ sách."},{"type":"compound","zh":"如果资料审核没有通过，就要在三天内重新提交。","pinyin":"Rúguǒ zīliào shěnhé méiyǒu tōngguò, jiùyào zài sān tiān nèi chóngxīn tíjiāo.","vi":"Nếu hồ sơ không qua xét duyệt thì phải nộp lại trong vòng ba ngày."}],"related":[{"hanzi":"审查","pinyin":"shěnchá","vi":"thẩm tra"},{"hanzi":"审定","pinyin":"shěndìng","vi":"thẩm định"},{"hanzi":"核对","pinyin":"héduì","vi":"đối chiếu"},{"hanzi":"审计","pinyin":"shěnjì","vi":"kiểm toán"}],"traditional":"審核"},{"id":"渗","hanzi":"渗","pinyin":"shèn","meaning_vi":"thấm, rỉ, ngấm","explanation":"渗 (sấm – thấm) → chất lỏng từ từ thấm qua, rỉ ra hoặc ngấm vào.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"💦","examples":[{"type":"basic","zh":"墙上渗水了。","pinyin":"Qiáng shàng shènshuǐ le.","vi":"Tường bị thấm nước rồi."},{"type":"simple","zh":"伤口的血渗过了纱布。","pinyin":"Shāngkǒu de xuè shènguò le shābù.","vi":"Máu từ vết thương thấm qua lớp băng gạc."},{"type":"compound","zh":"因为屋顶有裂缝，所以一下雨水就渗进房间里来。","pinyin":"Yīnwèi wūdǐng yǒu lièfèng, suǒyǐ yíxià yǔshuǐ jiù shèn jìn fángjiān lǐ lái.","vi":"Vì mái nhà có vết nứt nên hễ mưa là nước thấm vào phòng."}],"related":[{"hanzi":"渗透","pinyin":"shèntòu","vi":"thẩm thấu"},{"hanzi":"渗漏","pinyin":"shènlòu","vi":"rò rỉ"},{"hanzi":"浸","pinyin":"jìn","vi":"ngâm"},{"hanzi":"漏水","pinyin":"lòushuǐ","vi":"dột nước"}],"traditional":"滲"},{"id":"升温","hanzi":"升温","pinyin":"shēngwēn","meaning_vi":"tăng nhiệt độ, nóng lên; (nghĩa bóng) nóng lên, sôi động lên","explanation":"升 (thăng – lên) + 温 (ôn – nhiệt độ) → nhiệt độ tăng lên; nghĩa bóng là sự việc, quan hệ trở nên sôi động hơn.","hsk_level":"7-9","tags":["dong-tu","thoi-tiet"],"image":"🌡️","examples":[{"type":"basic","zh":"明天开始升温。","pinyin":"Míngtiān kāishǐ shēngwēn.","vi":"Từ ngày mai nhiệt độ bắt đầu tăng."},{"type":"simple","zh":"最近房地产市场又开始升温了。","pinyin":"Zuìjìn fángdìchǎn shìchǎng yòu kāishǐ shēngwēn le.","vi":"Gần đây thị trường bất động sản lại bắt đầu nóng lên."},{"type":"compound","zh":"随着全球不断升温，冰川融化的速度也越来越快。","pinyin":"Suízhe quánqiú búduàn shēngwēn, bīngchuān rónghuà de sùdù yě yuèláiyuè kuài.","vi":"Cùng với việc trái đất không ngừng nóng lên, băng hà tan chảy ngày càng nhanh."}],"related":[{"hanzi":"降温","pinyin":"jiàngwēn","vi":"giảm nhiệt"},{"hanzi":"气温","pinyin":"qìwēn","vi":"nhiệt độ không khí"},{"hanzi":"变暖","pinyin":"biànnuǎn","vi":"ấm lên"},{"hanzi":"升高","pinyin":"shēnggāo","vi":"tăng cao"}],"traditional":"升溫"},{"id":"生命线","hanzi":"生命线","pinyin":"shēngmìngxiàn","meaning_vi":"huyết mạch, đường sống, đường sinh mệnh","explanation":"生命 (sinh mệnh) + 线 (tuyến – đường) → con đường, tuyến cung ứng sống còn; cũng chỉ đường sinh đạo trên lòng bàn tay.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🛟","examples":[{"type":"basic","zh":"质量是企业的生命线。","pinyin":"Zhìliàng shì qǐyè de shēngmìngxiàn.","vi":"Chất lượng là huyết mạch của doanh nghiệp."},{"type":"simple","zh":"这条公路是灾区的生命线。","pinyin":"Zhè tiáo gōnglù shì zāiqū de shēngmìngxiàn.","vi":"Con đường này là đường sống của vùng thiên tai."},{"type":"compound","zh":"一旦这条运输生命线被切断，前线的补给就会出问题。","pinyin":"Yídàn zhè tiáo yùnshū shēngmìngxiàn bèi qiēduàn, qiánxiàn de bǔjǐ jiù huì chūwèntí.","vi":"Một khi tuyến vận chuyển huyết mạch này bị cắt đứt, tiếp tế cho tiền tuyến sẽ gặp vấn đề."}],"related":[{"hanzi":"生命","pinyin":"shēngmìng","vi":"sinh mệnh"},{"hanzi":"命脉","pinyin":"mìngmài","vi":"mạch sống"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"救命","pinyin":"jiùmìng","vi":"cứu mạng"}],"traditional":"生命線"},{"id":"生怕","hanzi":"生怕","pinyin":"shēngpà","meaning_vi":"chỉ sợ, e rằng, sợ nhất là","explanation":"生 (rất, hết sức) + 怕 (phạ – sợ) → rất sợ điều gì xảy ra, nên làm việc gì đó để tránh.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"他生怕迟到。","pinyin":"Tā shēngpà chídào.","vi":"Anh ấy rất sợ đến muộn."},{"type":"simple","zh":"她轻轻地走进房间，生怕吵醒了孩子。","pinyin":"Tā qīngqīng de zǒujìn fángjiān, shēngpà chǎoxǐngle háizi.","vi":"Cô ấy nhẹ nhàng bước vào phòng, chỉ sợ làm con thức giấc."},{"type":"compound","zh":"因为生怕忘了带护照，所以他出门前检查了好几遍。","pinyin":"Yīnwèi shēngpà wàngle dài hùzhào, suǒyǐ tā chū ménqián jiǎnchále hǎojǐ biàn.","vi":"Vì sợ quên mang hộ chiếu nên trước khi ra khỏi nhà anh ấy kiểm tra mấy lần."}],"related":[{"hanzi":"害怕","pinyin":"hàipà","vi":"sợ hãi"},{"hanzi":"唯恐","pinyin":"wéikǒng","vi":"chỉ sợ"},{"hanzi":"担心","pinyin":"dānxīn","vi":"lo lắng"},{"hanzi":"恐怕","pinyin":"kǒngpà","vi":"e rằng"}]},{"id":"生平","hanzi":"生平","pinyin":"shēngpíng","meaning_vi":"cuộc đời, tiểu sử; trong đời","explanation":"生 (sinh – đời sống) + 平 (bình – suốt, bình sinh) → cả cuộc đời một con người; cũng dùng như “trong đời này”.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"📜","examples":[{"type":"basic","zh":"这是他生平第一次出国。","pinyin":"Zhè shì tā shēngpíng dìyīcì chūguó.","vi":"Đây là lần đầu tiên trong đời ông ấy ra nước ngoài."},{"type":"simple","zh":"博物馆里介绍了这位诗人的生平。","pinyin":"Bówùguǎn lǐ jièshàole zhè wèi shīrén de shēngpíng.","vi":"Trong bảo tàng có giới thiệu tiểu sử của nhà thơ này."},{"type":"compound","zh":"如果你想读懂他的作品，就应该先了解他的生平。","pinyin":"Rúguǒ nǐ xiǎng dúdǒng tā de zuòpǐn, jiù yīnggāi xiān liǎojiě tā de shēngpíng.","vi":"Nếu muốn hiểu tác phẩm của ông ấy thì nên tìm hiểu tiểu sử của ông trước."}],"related":[{"hanzi":"一生","pinyin":"yìshēng","vi":"một đời"},{"hanzi":"平生","pinyin":"píngshēng","vi":"bình sinh"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"},{"hanzi":"传记","pinyin":"zhuànjì","vi":"tiểu sử, truyện ký"}]},{"id":"生前","hanzi":"生前","pinyin":"shēngqián","meaning_vi":"lúc sinh thời, khi còn sống","explanation":"生 (sinh – sống) + 前 (tiền – trước) → thời gian khi người đã khuất còn sống.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🕊️","examples":[{"type":"basic","zh":"这是他生前的照片。","pinyin":"Zhè shì tā shēngqián de zhàopiàn.","vi":"Đây là ảnh lúc sinh thời của ông ấy."},{"type":"simple","zh":"奶奶生前最喜欢在院子里种花。","pinyin":"Nǎinai shēngqián zuì xǐhuan zài yuànzi lǐ zhònghuā.","vi":"Lúc sinh thời bà nội thích nhất là trồng hoa trong sân."},{"type":"compound","zh":"虽然他生前没有得到认可，但是去世后作品却大受欢迎。","pinyin":"Suīrán tā shēngqián méiyǒu dédào rènkě, dànshì qùshì hòu zuòpǐn què dà shòuhuānyíng.","vi":"Tuy lúc sinh thời không được công nhận nhưng sau khi ông mất, tác phẩm lại rất được yêu thích."}],"related":[{"hanzi":"死后","pinyin":"sǐhòu","vi":"sau khi chết"},{"hanzi":"生平","pinyin":"shēngpíng","vi":"cuộc đời"},{"hanzi":"在世","pinyin":"zàishì","vi":"còn sống"},{"hanzi":"去世","pinyin":"qùshì","vi":"qua đời"}]},{"id":"生死","hanzi":"生死","pinyin":"shēngsǐ","meaning_vi":"sống chết, sinh tử","explanation":"生 (sinh – sống) + 死 (tử – chết) → sự sống và cái chết; thường chỉ việc hệ trọng liên quan đến tính mạng.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"☯️","examples":[{"type":"basic","zh":"这是生死问题。","pinyin":"Zhè shì shēngsǐ wèntí.","vi":"Đây là vấn đề sống còn."},{"type":"simple","zh":"他们是一起经历过生死的朋友。","pinyin":"Tāmen shì yìqǐ jīnglìguo shēngsǐ de péngyou.","vi":"Họ là những người bạn từng cùng nhau vào sinh ra tử."},{"type":"compound","zh":"即使面对生死考验，他也没有放弃自己的信念。","pinyin":"Jíshǐ miànduì shēngsǐ kǎoyàn, tā yě méiyǒu fàngqì zìjǐ de xìnniàn.","vi":"Dù đối mặt với thử thách sống còn, anh ấy cũng không từ bỏ niềm tin của mình."}],"related":[{"hanzi":"生命","pinyin":"shēngmìng","vi":"sinh mệnh"},{"hanzi":"死亡","pinyin":"sǐwáng","vi":"cái chết"},{"hanzi":"生死存亡","pinyin":"shēngsǐcúnwáng","vi":"sống còn"},{"hanzi":"死活","pinyin":"sǐhuó","vi":"sống chết"}]},{"id":"生涯","hanzi":"生涯","pinyin":"shēngyá","meaning_vi":"sự nghiệp, cuộc đời, quãng đời","explanation":"生 (sinh – sống) + 涯 (nhai – bờ, giới hạn) → quãng đời gắn với một nghề hay một hoạt động; hay dùng trong 职业生涯, 教师生涯.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🎓","examples":[{"type":"basic","zh":"他的演艺生涯很成功。","pinyin":"Tā de yǎnyì shēngyá hěn chénggōng.","vi":"Sự nghiệp diễn xuất của anh ấy rất thành công."},{"type":"simple","zh":"退休后，他回忆起三十年的教师生涯。","pinyin":"Tuìxiū hòu, tā huíyì qǐ sānshí nián de jiàoshī shēngyá.","vi":"Sau khi nghỉ hưu, ông nhớ lại ba mươi năm làm thầy giáo."},{"type":"compound","zh":"虽然运动员的职业生涯很短，但是他留下了很多纪录。","pinyin":"Suīrán yùndòngyuán de zhíyè shēngyá hěn duǎn, dànshì tā liúxiàle hěn duō jìlù.","vi":"Tuy sự nghiệp vận động viên rất ngắn, nhưng anh ấy đã để lại nhiều kỷ lục."}],"related":[{"hanzi":"职业","pinyin":"zhíyè","vi":"nghề nghiệp"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"cuộc sống"},{"hanzi":"天涯","pinyin":"tiānyá","vi":"chân trời"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"}]},{"id":"生硬","hanzi":"生硬","pinyin":"shēngyìng","meaning_vi":"cứng nhắc, gượng gạo, thô cứng","explanation":"生 (sinh – sống, chưa chín) + 硬 (ngạnh – cứng) → cứng nhắc, thiếu tự nhiên; dùng cho thái độ, lời nói, câu văn.","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"😐","examples":[{"type":"basic","zh":"他的态度很生硬。","pinyin":"Tā de tàidù hěn shēngyìng.","vi":"Thái độ của anh ấy rất cứng nhắc."},{"type":"simple","zh":"这篇译文读起来有点生硬。","pinyin":"Zhè piān yì wéndú qǐlái yǒudiǎn shēngyìng.","vi":"Bản dịch này đọc lên hơi gượng gạo."},{"type":"compound","zh":"如果你说话太生硬，别人就会觉得不舒服。","pinyin":"Rúguǒ nǐ shuōhuà tài shēngyìng, biérén jiù huì juéde bù shūfu.","vi":"Nếu bạn nói chuyện quá cứng nhắc, người khác sẽ thấy khó chịu."}],"related":[{"hanzi":"僵硬","pinyin":"jiāngyìng","vi":"cứng đờ"},{"hanzi":"生涩","pinyin":"shēngsè","vi":"lúng túng, không trôi chảy"},{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"},{"hanzi":"强硬","pinyin":"qiángyìng","vi":"cứng rắn"}]},{"id":"声称","hanzi":"声称","pinyin":"shēngchēng","meaning_vi":"tuyên bố, khẳng định, tự nhận","explanation":"声 (thanh – tiếng nói) + 称 (xưng – nói, gọi) → công khai nói rằng; thường hàm ý điều được nói chưa chắc đã đúng.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📢","examples":[{"type":"basic","zh":"他声称自己无罪。","pinyin":"Tā shēngchēng zìjǐ wúzuì.","vi":"Anh ta khẳng định mình vô tội."},{"type":"simple","zh":"这家公司声称产品完全无害。","pinyin":"Zhè jiā gōngsī shēngchēng chǎnpǐn wánquán wúhài.","vi":"Công ty này tuyên bố sản phẩm hoàn toàn vô hại."},{"type":"compound","zh":"虽然他声称看见了外星人，但是没有人相信他。","pinyin":"Suīrán tā shēngchēng kànjiànle wàixīngrén, dànshì méi yǒurén xiāngxìn tā.","vi":"Tuy anh ta khẳng định đã nhìn thấy người ngoài hành tinh, nhưng không ai tin."}],"related":[{"hanzi":"宣称","pinyin":"xuānchēng","vi":"tuyên bố"},{"hanzi":"声明","pinyin":"shēngmíng","vi":"thông báo, tuyên bố"},{"hanzi":"自称","pinyin":"zìchēng","vi":"tự xưng"},{"hanzi":"号称","pinyin":"hàochēng","vi":"tự xưng là"}],"traditional":"聲稱"},{"id":"声望","hanzi":"声望","pinyin":"shēngwàng","meaning_vi":"danh vọng, uy tín, tiếng tăm","explanation":"声 (thanh – tiếng tăm) + 望 (vọng – trông mong, danh vọng) → tiếng tăm và sự kính trọng mà người khác dành cho mình.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏅","examples":[{"type":"basic","zh":"他在村里很有声望。","pinyin":"Tā zài cūnlǐ hěn yǒu shēngwàng.","vi":"Ông ấy rất có uy tín trong làng."},{"type":"simple","zh":"这位教授在学术界享有很高的声望。","pinyin":"Zhè wèi jiàoshòu zài xuéshùjiè xiǎngyǒu hěn gāo de shēngwàng.","vi":"Vị giáo sư này có danh vọng rất cao trong giới học thuật."},{"type":"compound","zh":"因为他一直帮助穷人，所以他的声望越来越高。","pinyin":"Yīnwèi tā yìzhí bāngzhù qióngrén, suǒyǐ tā de shēngwàng yuèláiyuè gāo.","vi":"Vì ông luôn giúp đỡ người nghèo nên uy tín của ông ngày càng cao."}],"related":[{"hanzi":"名望","pinyin":"míngwàng","vi":"danh vọng"},{"hanzi":"威望","pinyin":"wēiwàng","vi":"uy tín"},{"hanzi":"声誉","pinyin":"shēngyù","vi":"danh tiếng"},{"hanzi":"名声","pinyin":"míngshēng","vi":"tiếng tăm"}],"traditional":"聲望"},{"id":"省事","hanzi":"省事","pinyin":"shěngshì","meaning_vi":"đỡ việc, tiện, đỡ phiền","explanation":"省 (tỉnh – tiết kiệm, bớt) + 事 (sự – việc) → bớt việc, đỡ rắc rối, tiện lợi.","hsk_level":"7-9","tags":["tinh-tu","sinh-hoat"],"image":"👌","examples":[{"type":"basic","zh":"叫外卖最省事。","pinyin":"Jiào wàimài zuì shěngshì.","vi":"Gọi đồ ăn ngoài là tiện nhất."},{"type":"simple","zh":"用洗碗机洗碗省事多了。","pinyin":"Yòng xǐwǎnjī xǐwǎn shěngshì duō le.","vi":"Rửa bát bằng máy rửa bát đỡ việc hơn nhiều."},{"type":"compound","zh":"如果你提前把材料准备好，到时候就省事了。","pinyin":"Rúguǒ nǐ tíqián bǎ cáiliào zhǔnbèihǎo, dàoshíhou jiù shěngshì le.","vi":"Nếu bạn chuẩn bị tài liệu trước thì đến lúc đó sẽ đỡ việc."}],"related":[{"hanzi":"省力","pinyin":"shěnglì","vi":"đỡ tốn sức"},{"hanzi":"省心","pinyin":"shěngxīn","vi":"đỡ lo"},{"hanzi":"麻烦","pinyin":"máfan","vi":"phiền phức"},{"hanzi":"方便","pinyin":"fāngbiàn","vi":"tiện lợi"}]},{"id":"圣贤","hanzi":"圣贤","pinyin":"shèngxián","meaning_vi":"thánh hiền, bậc thánh nhân hiền triết","explanation":"圣 (thánh – bậc thánh) + 贤 (hiền – người hiền tài) → các bậc thánh nhân, hiền triết có đạo đức và trí tuệ cao.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"孔子被称为圣贤。","pinyin":"Kǒngzǐ bèi chēngwéi shèngxián.","vi":"Khổng Tử được tôn là bậc thánh hiền."},{"type":"simple","zh":"古代圣贤留下了很多智慧的话。","pinyin":"Gǔdài shèngxián liúxiàle hěn duō zhìhuì dehuà.","vi":"Các bậc thánh hiền xưa để lại nhiều lời nói sáng suốt."},{"type":"compound","zh":"即使是圣贤，也难免会犯错误。","pinyin":"Jíshǐ shì shèngxián, yě nánmiǎn huì fàn cuòwù.","vi":"Ngay cả thánh hiền cũng khó tránh khỏi mắc sai lầm."}],"related":[{"hanzi":"圣人","pinyin":"shèngrén","vi":"thánh nhân"},{"hanzi":"贤人","pinyin":"xiánrén","vi":"người hiền"},{"hanzi":"圣地","pinyin":"shèngdì","vi":"thánh địa"},{"hanzi":"贤惠","pinyin":"xiánhuì","vi":"hiền thục"}],"traditional":"聖賢"},{"id":"胜出","hanzi":"胜出","pinyin":"shèngchū","meaning_vi":"giành chiến thắng, thắng cuộc","explanation":"胜 (thắng – thắng) + 出 (xuất – ra, nổi lên) → vượt lên giành thắng lợi trong cuộc thi, bầu cử.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"红队最后胜出。","pinyin":"Hóng duì zuìhòu shèngchū.","vi":"Đội đỏ cuối cùng giành chiến thắng."},{"type":"simple","zh":"她在歌唱比赛中胜出了。","pinyin":"Tā zài gēchàng bǐsài zhōng shèngchū le.","vi":"Cô ấy đã thắng trong cuộc thi hát."},{"type":"compound","zh":"虽然对手很强，但是我们最后还是胜出了。","pinyin":"Suīrán duìshǒu hěn qiáng, dànshì wǒmen zuìhòu háishì shèngchū le.","vi":"Tuy đối thủ rất mạnh, nhưng cuối cùng chúng tôi vẫn thắng."}],"related":[{"hanzi":"胜利","pinyin":"shènglì","vi":"thắng lợi"},{"hanzi":"获胜","pinyin":"huòshèng","vi":"giành chiến thắng"},{"hanzi":"战胜","pinyin":"zhànshèng","vi":"đánh bại"},{"hanzi":"落败","pinyin":"luòbài","vi":"thất bại"}],"traditional":"勝出"},{"id":"盛大","hanzi":"盛大","pinyin":"shèngdà","meaning_vi":"long trọng, hoành tráng, to lớn","explanation":"盛 (thịnh – thịnh vượng, rầm rộ) + 大 (đại – lớn) → quy mô lớn, long trọng; thường dùng cho lễ hội, nghi thức.","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🎉","examples":[{"type":"basic","zh":"婚礼办得很盛大。","pinyin":"Hūnlǐ bàn de hěn shèngdà.","vi":"Đám cưới được tổ chức rất hoành tráng."},{"type":"simple","zh":"学校举行了盛大的开学典礼。","pinyin":"Xuéxiào jǔxíngle shèngdà de kāixué diǎnlǐ.","vi":"Trường tổ chức lễ khai giảng long trọng."},{"type":"compound","zh":"因为今年是建校一百周年，所以庆祝活动特别盛大。","pinyin":"Yīnwèi jīnnián shì jiàn xiào yī bǎi zhōunián, suǒyǐ qìngzhù huódòng tèbié shèngdà.","vi":"Vì năm nay là kỷ niệm 100 năm thành lập trường nên lễ kỷ niệm đặc biệt hoành tráng."}],"related":[{"hanzi":"隆重","pinyin":"lóngzhòng","vi":"long trọng"},{"hanzi":"盛会","pinyin":"shènghuì","vi":"hội lớn"},{"hanzi":"盛况","pinyin":"shèngkuàng","vi":"cảnh tượng tưng bừng"},{"hanzi":"宏大","pinyin":"hóngdà","vi":"to lớn"}]},{"id":"盛会","hanzi":"盛会","pinyin":"shènghuì","meaning_vi":"hội lớn, sự kiện trọng đại","explanation":"盛 (thịnh – rầm rộ, lớn) + 会 (hội – cuộc họp, hội) → cuộc hội họp, lễ hội quy mô lớn và long trọng.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎊","examples":[{"type":"basic","zh":"这是一次体育盛会。","pinyin":"Zhè shì yí cì tǐyù shènghuì.","vi":"Đây là một đại hội thể thao lớn."},{"type":"simple","zh":"世界杯是全球球迷的盛会。","pinyin":"Shìjièbēi shì quánqiú qiúmí de shènghuì.","vi":"World Cup là ngày hội lớn của người hâm mộ bóng đá toàn cầu."},{"type":"compound","zh":"虽然这次盛会只有三天，但是吸引了几十万游客。","pinyin":"Suīrán zhè cì shènghuì zhǐyǒu sān tiān, dànshì xīyǐnle jǐ shíwàn yóukè.","vi":"Tuy sự kiện lớn này chỉ kéo dài ba ngày, nhưng đã thu hút mấy trăm nghìn du khách."}],"related":[{"hanzi":"盛大","pinyin":"shèngdà","vi":"long trọng"},{"hanzi":"大会","pinyin":"dàhuì","vi":"đại hội"},{"hanzi":"晚会","pinyin":"wǎnhuì","vi":"dạ hội"},{"hanzi":"聚会","pinyin":"jùhuì","vi":"buổi tụ họp"}],"traditional":"盛會"},{"id":"剩余","hanzi":"剩余","pinyin":"shèngyú","meaning_vi":"còn lại, còn thừa, phần dư","explanation":"剩 (thặng – thừa ra) + 余 (dư – dư lại) → phần còn thừa lại sau khi đã dùng; cũng là danh từ 'phần dư'.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"🍱","examples":[{"type":"basic","zh":"剩余的钱不多了。","pinyin":"Shèngyú de qián bù duō le.","vi":"Số tiền còn lại không nhiều nữa."},{"type":"simple","zh":"把剩余的饭菜放进冰箱吧。","pinyin":"Bǎ shèngyú de fàncài fàngjìn bīngxiāng ba.","vi":"Cất thức ăn còn thừa vào tủ lạnh đi."},{"type":"compound","zh":"如果还有剩余的时间，我们就再复习一遍。","pinyin":"Rúguǒ háiyǒu shèngyú de shíjiān, wǒmen jiù zài fùxí yíbiàn.","vi":"Nếu còn dư thời gian, chúng ta sẽ ôn lại một lượt."}],"related":[{"hanzi":"剩下","pinyin":"shèngxià","vi":"còn lại"},{"hanzi":"多余","pinyin":"duōyú","vi":"thừa"},{"hanzi":"余额","pinyin":"yú'é","vi":"số dư"},{"hanzi":"过剩","pinyin":"guòshèng","vi":"dư thừa"}],"traditional":"剩餘"},{"id":"失利","hanzi":"失利","pinyin":"shīlì","meaning_vi":"thất bại, thua trận","explanation":"失 (thất – mất) + 利 (lợi – lợi thế, thắng lợi) → mất thế thắng, bị thua trong thi đấu hay chiến trận.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"📉","examples":[{"type":"basic","zh":"主队这次失利了。","pinyin":"Zhǔduì zhè cì shīlì le.","vi":"Đội chủ nhà lần này đã thua."},{"type":"simple","zh":"他在决赛中意外失利。","pinyin":"Tā zài juésài zhōng yìwài shīlì.","vi":"Anh ấy bất ngờ thất bại trong trận chung kết."},{"type":"compound","zh":"虽然上一场比赛失利了，但是队员们没有灰心。","pinyin":"Suīrán shàng yì chǎng bǐsài shīlì le, dànshì duìyuánmen méiyǒu huīxīn.","vi":"Tuy trận trước đã thua, nhưng các cầu thủ không nản lòng."}],"related":[{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"},{"hanzi":"胜利","pinyin":"shènglì","vi":"thắng lợi"},{"hanzi":"输","pinyin":"shū","vi":"thua"},{"hanzi":"受挫","pinyin":"shòucuò","vi":"gặp trắc trở"}]},{"id":"失恋","hanzi":"失恋","pinyin":"shīliàn","meaning_vi":"thất tình","explanation":"失 (thất – mất) + 恋 (luyến – tình yêu) → mất người yêu, tình yêu tan vỡ.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"她最近失恋了。","pinyin":"Tā zuìjìn shīliàn le.","vi":"Gần đây cô ấy bị thất tình."},{"type":"simple","zh":"失恋以后，他整天不想说话。","pinyin":"Shīliàn yǐhòu, tā zhěngtiān bù xiǎng shuōhuà.","vi":"Sau khi thất tình, cả ngày anh ấy chẳng muốn nói gì."},{"type":"compound","zh":"即使失恋了，你也要好好照顾自己。","pinyin":"Jíshǐ shīliàn le, nǐ yě yào hǎohǎo zhàogù zìjǐ.","vi":"Dù có thất tình, bạn cũng phải chăm sóc bản thân thật tốt."}],"related":[{"hanzi":"恋爱","pinyin":"liàn'ài","vi":"yêu đương"},{"hanzi":"分手","pinyin":"fēnshǒu","vi":"chia tay"},{"hanzi":"初恋","pinyin":"chūliàn","vi":"mối tình đầu"},{"hanzi":"暗恋","pinyin":"ànliàn","vi":"yêu thầm"}],"traditional":"失戀"},{"id":"失效","hanzi":"失效","pinyin":"shīxiào","meaning_vi":"mất hiệu lực, hết tác dụng","explanation":"失 (thất – mất) + 效 (hiệu – hiệu quả, hiệu lực) → không còn hiệu lực hoặc tác dụng nữa.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛔","examples":[{"type":"basic","zh":"这张优惠券已经失效了。","pinyin":"Zhè zhāng yōuhuìquàn yǐjīng shīxiào le.","vi":"Phiếu giảm giá này đã hết hiệu lực."},{"type":"simple","zh":"药品过期以后就会失效。","pinyin":"Yàopǐn guòqī yǐhòu jiù huì shīxiào.","vi":"Thuốc quá hạn sẽ mất tác dụng."},{"type":"compound","zh":"如果合同到期不续签，它就会自动失效。","pinyin":"Rúguǒ hétong dàoqī bú xùqiān, tā jiù huì zìdòng shīxiào.","vi":"Nếu hợp đồng đến hạn mà không ký tiếp thì nó sẽ tự động mất hiệu lực."}],"related":[{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu lực"},{"hanzi":"无效","pinyin":"wúxiào","vi":"vô hiệu"},{"hanzi":"生效","pinyin":"shēngxiào","vi":"bắt đầu có hiệu lực"},{"hanzi":"过期","pinyin":"guòqī","vi":"hết hạn"}]},{"id":"失业率","hanzi":"失业率","pinyin":"shīyèlǜ","meaning_vi":"tỷ lệ thất nghiệp","explanation":"失业 (thất nghiệp – mất việc) + 率 (suất – tỷ lệ) → tỷ lệ người thất nghiệp trong lực lượng lao động.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📊","examples":[{"type":"basic","zh":"今年的失业率下降了。","pinyin":"Jīnnián de shīyèlǜ xiàjiàng le.","vi":"Tỷ lệ thất nghiệp năm nay đã giảm."},{"type":"simple","zh":"这个城市的失业率比较高。","pinyin":"Zhè ge chéngshì de shīyèlǜ bǐjiào gāo.","vi":"Tỷ lệ thất nghiệp ở thành phố này khá cao."},{"type":"compound","zh":"因为很多工厂倒闭了，所以当地的失业率明显上升。","pinyin":"Yīnwèi hěn duō gōngchǎng dǎobì le, suǒyǐ dāngdì de shīyèlǜ míngxiǎn shàngshēng.","vi":"Vì nhiều nhà máy đóng cửa nên tỷ lệ thất nghiệp ở địa phương tăng rõ rệt."}],"related":[{"hanzi":"失业","pinyin":"shīyè","vi":"thất nghiệp"},{"hanzi":"就业","pinyin":"jiùyè","vi":"có việc làm"},{"hanzi":"就业率","pinyin":"jiùyèlǜ","vi":"tỷ lệ có việc làm"},{"hanzi":"通货膨胀","pinyin":"tōnghuòpéngzhàng","vi":"lạm phát"}],"traditional":"失業率"},{"id":"师长","hanzi":"师长","pinyin":"shīzhǎng","meaning_vi":"thầy cô, bậc thầy; sư đoàn trưởng","explanation":"师 (sư – thầy; sư đoàn) + 长 (trưởng – người đứng đầu, bề trên) → thầy cô và bậc trên; trong quân đội là sư đoàn trưởng.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"👨‍🏫","examples":[{"type":"basic","zh":"我们要尊敬师长。","pinyin":"Wǒmen yào zūnjìng shīzhǎng.","vi":"Chúng ta phải kính trọng thầy cô."},{"type":"simple","zh":"毕业那天，他向师长们一一道谢。","pinyin":"Bìyè nà tiān, tā xiàng shīzhǎngmen yīyī dàoxiè.","vi":"Ngày tốt nghiệp, cậu ấy lần lượt cảm ơn từng thầy cô."},{"type":"compound","zh":"虽然他已经当上了师长，但是仍然和士兵一起吃饭。","pinyin":"Suīrán tā yǐjīng dāngshàngle shīzhǎng, dànshì réngrán hé shìbīng yìqǐ chīfàn.","vi":"Tuy đã làm sư đoàn trưởng, ông vẫn ăn cơm cùng binh lính."}],"related":[{"hanzi":"老师","pinyin":"lǎoshī","vi":"thầy cô"},{"hanzi":"师生","pinyin":"shīshēng","vi":"thầy trò"},{"hanzi":"长辈","pinyin":"zhǎngbèi","vi":"bề trên"},{"hanzi":"军长","pinyin":"jūnzhǎng","vi":"quân đoàn trưởng"}],"traditional":"師長"},{"id":"施加","hanzi":"施加","pinyin":"shījiā","meaning_vi":"gây (áp lực), tạo (ảnh hưởng), tác động","explanation":"施 (thi – thi hành, đưa ra) + 加 (gia – thêm vào) → đưa áp lực, ảnh hưởng tác động lên ai; hay đi với 压力, 影响.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗜️","examples":[{"type":"basic","zh":"不要给孩子施加压力。","pinyin":"Bú yào gěi háizi shījiā yālì.","vi":"Đừng gây áp lực cho trẻ con."},{"type":"simple","zh":"国际社会对该国施加了影响。","pinyin":"Guójì shèhuì duì gāi guó shījiāle yǐngxiǎng.","vi":"Cộng đồng quốc tế đã tác động lên nước đó."},{"type":"compound","zh":"即使别人施加压力，他也坚持自己的决定。","pinyin":"Jíshǐ biérén shījiā yālì, tā yě jiānchí zìjǐ de juédìng.","vi":"Dù người khác gây sức ép, anh ấy vẫn giữ quyết định của mình."}],"related":[{"hanzi":"施压","pinyin":"shīyā","vi":"gây sức ép"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"加以","pinyin":"jiāyǐ","vi":"tiến hành, thêm vào"},{"hanzi":"施展","pinyin":"shīzhǎn","vi":"thi triển"}]},{"id":"施行","hanzi":"施行","pinyin":"shīxíng","meaning_vi":"thi hành, có hiệu lực, thực thi","explanation":"施 (thi – thi hành) + 行 (hành – làm, thực hiện) → đưa (luật lệ, quy định) vào thực hiện, bắt đầu có hiệu lực.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"新法律下月施行。","pinyin":"Xīn fǎlǜ xiàyuè shīxíng.","vi":"Luật mới sẽ có hiệu lực vào tháng sau."},{"type":"simple","zh":"这项规定从明年一月一日起施行。","pinyin":"Zhè xiàng guīdìng cóng míngnián Yīyuè yī rì qǐ shīxíng.","vi":"Quy định này được thi hành từ ngày 1 tháng 1 năm sau."},{"type":"compound","zh":"虽然新政策已经施行，但是很多人还不了解。","pinyin":"Suīrán xīn zhèngcè yǐjīng shīxíng, dànshì hěn duō rén hái bù liǎojiě.","vi":"Tuy chính sách mới đã được thực thi, nhưng nhiều người vẫn chưa hiểu rõ."}],"related":[{"hanzi":"实行","pinyin":"shíxíng","vi":"thực hiện"},{"hanzi":"实施","pinyin":"shíshī","vi":"thực thi"},{"hanzi":"执行","pinyin":"zhíxíng","vi":"thi hành"},{"hanzi":"推行","pinyin":"tuīxíng","vi":"triển khai"}]},{"id":"湿度","hanzi":"湿度","pinyin":"shīdù","meaning_vi":"độ ẩm","explanation":"湿 (thấp – ẩm ướt) + 度 (độ – mức độ) → mức độ ẩm của không khí hay vật chất.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"💧","examples":[{"type":"basic","zh":"今天湿度很大。","pinyin":"Jīntiān shīdù hěn dà.","vi":"Hôm nay độ ẩm rất cao."},{"type":"simple","zh":"南方春天的空气湿度特别高。","pinyin":"Nánfāng chūntiān de kōngqì shīdù tèbié gāo.","vi":"Độ ẩm không khí mùa xuân ở miền Nam đặc biệt cao."},{"type":"compound","zh":"如果房间湿度太低，皮肤就会变得很干。","pinyin":"Rúguǒ fángjiān shīdù tài dī, pífū jiù huì biànde hěn gān.","vi":"Nếu độ ẩm trong phòng quá thấp, da sẽ trở nên rất khô."}],"related":[{"hanzi":"温度","pinyin":"wēndù","vi":"nhiệt độ"},{"hanzi":"潮湿","pinyin":"cháoshī","vi":"ẩm ướt"},{"hanzi":"干燥","pinyin":"gānzào","vi":"khô hanh"},{"hanzi":"湿润","pinyin":"shīrùn","vi":"ẩm, ẩm ướt"}],"traditional":"濕度"},{"id":"十字路口","hanzi":"十字路口","pinyin":"shízìlùkǒu","meaning_vi":"ngã tư; bước ngoặt, ngã rẽ (cuộc đời)","explanation":"十字 (thập tự – hình chữ thập) + 路口 (lộ khẩu – đầu đường) → ngã tư; nghĩa bóng chỉ thời điểm phải đưa ra lựa chọn quan trọng.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚦","examples":[{"type":"basic","zh":"在十字路口左转。","pinyin":"Zài shízìlùkǒu zuǒzhuǎn.","vi":"Rẽ trái ở ngã tư."},{"type":"simple","zh":"前面的十字路口经常堵车。","pinyin":"Qiánmiàn de shízìlùkǒu jīngcháng dǔchē.","vi":"Ngã tư phía trước thường xuyên tắc đường."},{"type":"compound","zh":"如果到了十字路口还看不见商店，你就给我打电话。","pinyin":"Rúguǒ dàole shízìlùkǒu hái kànbújiàn shāngdiàn, nǐ jiù gěi wǒ dǎdiànhuà.","vi":"Nếu đến ngã tư mà vẫn không thấy cửa hàng thì bạn gọi điện cho tôi."}],"related":[{"hanzi":"路口","pinyin":"lùkǒu","vi":"giao lộ"},{"hanzi":"红绿灯","pinyin":"hónglǜdēng","vi":"đèn giao thông"},{"hanzi":"人行道","pinyin":"rénxíngdào","vi":"vỉa hè"},{"hanzi":"拐弯","pinyin":"guǎiwān","vi":"rẽ, quẹo"}]},{"id":"时段","hanzi":"时段","pinyin":"shíduàn","meaning_vi":"khung giờ, khoảng thời gian, ca","explanation":"时 (thời – thời gian) + 段 (đoạn – đoạn, khúc) → một khoảng thời gian nhất định trong ngày; ví dụ 黄金时段 giờ vàng.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🕒","examples":[{"type":"basic","zh":"晚上是黄金时段。","pinyin":"Wǎnshang shì huángjīn shíduàn.","vi":"Buổi tối là khung giờ vàng."},{"type":"simple","zh":"这个时段地铁特别拥挤。","pinyin":"Zhè ge shíduàn dìtiě tèbié yōngjǐ.","vi":"Vào khung giờ này tàu điện ngầm đặc biệt đông."},{"type":"compound","zh":"如果你选择上午的时段，就能避开排队的人群。","pinyin":"Rúguǒ nǐ xuǎnzé shàngwǔ de shíduàn, jiù néng bìkāi páiduì de rénqún.","vi":"Nếu bạn chọn khung giờ buổi sáng thì có thể tránh được đám đông xếp hàng."}],"related":[{"hanzi":"时间","pinyin":"shíjiān","vi":"thời gian"},{"hanzi":"阶段","pinyin":"jiēduàn","vi":"giai đoạn"},{"hanzi":"高峰期","pinyin":"gāofēngqī","vi":"giờ cao điểm"},{"hanzi":"时刻","pinyin":"shíkè","vi":"thời khắc"}],"traditional":"時段"},{"id":"时隔","hanzi":"时隔","pinyin":"shígé","meaning_vi":"cách nhau (một khoảng thời gian), sau","explanation":"时 (thời – thời gian) + 隔 (cách – ngăn cách) → cách nhau một quãng thời gian; thường theo sau là lượng thời gian như 时隔多年.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"时隔多年，我们又见面了。","pinyin":"Shígé duōnián, wǒmen yòu jiànmiàn le.","vi":"Cách nhau bao năm, chúng tôi lại gặp nhau."},{"type":"simple","zh":"时隔十年，他再次回到了故乡。","pinyin":"Shígé shí nián, tā zàicì huídàole gùxiāng.","vi":"Sau mười năm, anh ấy lại trở về quê hương."},{"type":"compound","zh":"虽然时隔已久，但是那件事我仍然记得很清楚。","pinyin":"Suīrán shígé yǐjiǔ, dànshì nà jiàn shì wǒ réngrán jìde hěn qīngchu.","vi":"Tuy đã lâu lắm rồi, nhưng chuyện đó tôi vẫn nhớ rất rõ."}],"related":[{"hanzi":"相隔","pinyin":"xiānggé","vi":"cách nhau"},{"hanzi":"间隔","pinyin":"jiàngé","vi":"khoảng cách"},{"hanzi":"隔开","pinyin":"gékāi","vi":"ngăn cách"},{"hanzi":"时光","pinyin":"shíguāng","vi":"thời gian, năm tháng"}],"traditional":"時隔"},{"id":"时好时坏","hanzi":"时好时坏","pinyin":"shíhǎo-shíhuài","meaning_vi":"lúc tốt lúc xấu, chập chờn","explanation":"时…时… (thời – lúc… lúc…) + 好 (hảo – tốt) + 坏 (hoại – xấu) → lúc thì tốt lúc thì xấu, không ổn định.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌗","examples":[{"type":"basic","zh":"他的病时好时坏。","pinyin":"Tā de bìng shíhǎoshíhuài.","vi":"Bệnh của anh ấy lúc đỡ lúc nặng."},{"type":"simple","zh":"这里的网络信号时好时坏。","pinyin":"Zhèlǐ de wǎngluò xìnhào shíhǎoshíhuài.","vi":"Tín hiệu mạng ở đây lúc tốt lúc kém."},{"type":"compound","zh":"因为最近天气时好时坏，所以出门一定要带伞。","pinyin":"Yīnwèi zuìjìn tiānqì shíhǎoshíhuài, suǒyǐ chūmén yídìngyào dài sǎn.","vi":"Vì gần đây thời tiết thất thường nên ra ngoài nhất định phải mang ô."}],"related":[{"hanzi":"时冷时热","pinyin":"shílěngshírè","vi":"lúc nóng lúc lạnh"},{"hanzi":"忽好忽坏","pinyin":"hūhǎohūhuài","vi":"lúc tốt lúc xấu"},{"hanzi":"不稳定","pinyin":"bùwěndìng","vi":"không ổn định"},{"hanzi":"反复","pinyin":"fǎnfù","vi":"lặp đi lặp lại"}],"traditional":"時好時壞"},{"id":"时间表","hanzi":"时间表","pinyin":"shíjiānbiǎo","meaning_vi":"thời gian biểu, lịch trình","explanation":"时间 (thời gian) + 表 (biểu – bảng) → bảng ghi giờ giấc, lịch trình các hoạt động.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🗓️","examples":[{"type":"basic","zh":"请看一下时间表。","pinyin":"Qǐngkàn yíxià shíjiānbiǎo.","vi":"Hãy xem thời gian biểu một chút."},{"type":"simple","zh":"火车时间表贴在墙上。","pinyin":"Huǒchē shíjiānbiǎo tiē zài qiáng shàng.","vi":"Bảng giờ tàu được dán trên tường."},{"type":"compound","zh":"如果不按时间表复习，你就很难通过考试。","pinyin":"Rúguǒ bú àn shíjiānbiǎo fùxí, nǐ jiù hěn nán tōngguò kǎoshì.","vi":"Nếu không ôn tập theo thời gian biểu, bạn sẽ khó thi đỗ."}],"related":[{"hanzi":"日程","pinyin":"rìchéng","vi":"lịch trình"},{"hanzi":"课程表","pinyin":"kèchéngbiǎo","vi":"thời khóa biểu"},{"hanzi":"计划","pinyin":"jìhuà","vi":"kế hoạch"},{"hanzi":"安排","pinyin":"ānpái","vi":"sắp xếp"}],"traditional":"時間表"},{"id":"时空","hanzi":"时空","pinyin":"shíkōng","meaning_vi":"thời gian và không gian, không-thời gian","explanation":"时 (thời – thời gian) + 空 (không – không gian) → thời gian và không gian; trong vật lý là không-thời gian.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌌","examples":[{"type":"basic","zh":"这部电影讲时空旅行。","pinyin":"Zhè bù diànyǐng jiǎng shíkōng lǚxíng.","vi":"Bộ phim này kể về du hành thời gian."},{"type":"simple","zh":"音乐能跨越时空打动人心。","pinyin":"Yīnyuè néng kuàyuè shíkōng dǎdòng rénxīn.","vi":"Âm nhạc có thể vượt qua không gian và thời gian để chạm tới lòng người."},{"type":"compound","zh":"虽然我们身处不同的时空，但是感情是相通的。","pinyin":"Suīrán wǒmen shēnchǔ bùtóng de shíkōng, dànshì gǎnqíng shì xiāngtōng de.","vi":"Tuy chúng ta ở những thời đại và nơi chốn khác nhau, nhưng tình cảm vẫn thông nhau."}],"related":[{"hanzi":"空间","pinyin":"kōngjiān","vi":"không gian"},{"hanzi":"时间","pinyin":"shíjiān","vi":"thời gian"},{"hanzi":"宇宙","pinyin":"yǔzhòu","vi":"vũ trụ"},{"hanzi":"穿越","pinyin":"chuānyuè","vi":"xuyên không"}],"traditional":"時空"},{"id":"实体","hanzi":"实体","pinyin":"shítǐ","meaning_vi":"thực thể; (cửa hàng) truyền thống, (kinh tế) thực","explanation":"实 (thực – thật) + 体 (thể – thân, vật thể) → vật tồn tại thật, đối lập với ảo/trên mạng; hay gặp 实体店, 实体经济.","hsk_level":"7-9","tags":["danh-tu"],"image":"🏬","examples":[{"type":"basic","zh":"他开了一家实体店。","pinyin":"Tā kāile yìjiā shítǐdiàn.","vi":"Anh ấy mở một cửa hàng thực tế."},{"type":"simple","zh":"疫情对实体经济造成了很大冲击。","pinyin":"Yìqíng duì shítǐjīngjì zào chéngle hěn dà chōngjī.","vi":"Dịch bệnh gây cú sốc lớn cho nền kinh tế thực."},{"type":"compound","zh":"虽然网上价格更便宜，但是很多人还是喜欢去实体店买衣服。","pinyin":"Suīrán wǎngshàng jiàgé gèng piányi, dànshì hěn duō rén háishì xǐhuan qù shítǐdiàn mǎi yīfu.","vi":"Tuy giá trên mạng rẻ hơn, nhưng nhiều người vẫn thích đến cửa hàng truyền thống mua quần áo."}],"related":[{"hanzi":"实物","pinyin":"shíwù","vi":"vật thật"},{"hanzi":"虚拟","pinyin":"xūnǐ","vi":"ảo"},{"hanzi":"物体","pinyin":"wùtǐ","vi":"vật thể"},{"hanzi":"实体店","pinyin":"shítǐdiàn","vi":"cửa hàng truyền thống"}],"traditional":"實體"},{"id":"实物","hanzi":"实物","pinyin":"shíwù","meaning_vi":"vật thật, hiện vật","explanation":"实 (thực – thật) + 物 (vật – đồ vật) → đồ vật có thật, hiện vật (đối lập với hình ảnh, mô hình); 以实物 = bằng hiện vật.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"📦","examples":[{"type":"basic","zh":"这是实物照片。","pinyin":"Zhè shì shíwù zhàopiàn.","vi":"Đây là ảnh chụp sản phẩm thật."},{"type":"simple","zh":"老师拿来实物给我们看。","pinyin":"Lǎoshī nálái shíwù gěi wǒmen kàn.","vi":"Cô giáo mang vật thật đến cho chúng tôi xem."},{"type":"compound","zh":"虽然图片看起来很漂亮，但是实物却差了很多。","pinyin":"Suīrán túpiàn kànqǐlái hěn piàoliang, dànshì shíwù què chàle hěn duō.","vi":"Tuy ảnh trông rất đẹp, nhưng hàng thật lại kém xa."}],"related":[{"hanzi":"实体","pinyin":"shítǐ","vi":"thực thể"},{"hanzi":"物品","pinyin":"wùpǐn","vi":"đồ vật"},{"hanzi":"样品","pinyin":"yàngpǐn","vi":"hàng mẫu"},{"hanzi":"图片","pinyin":"túpiàn","vi":"hình ảnh"}],"traditional":"實物"},{"id":"食用","hanzi":"食用","pinyin":"shíyòng","meaning_vi":"ăn, dùng để ăn, ăn được","explanation":"食 (thực – ăn) + 用 (dụng – dùng) → dùng làm thức ăn; trang trọng, hay gặp trên bao bì (食用方法, 可食用).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"这种蘑菇不能食用。","pinyin":"Zhè zhǒng mógu bù néng shíyòng.","vi":"Loại nấm này không ăn được."},{"type":"simple","zh":"请在保质期内食用这些牛奶。","pinyin":"Qǐng zài bǎozhìqī nèi shíyòng zhèxiē niúnǎi.","vi":"Hãy dùng số sữa này trong hạn sử dụng."},{"type":"compound","zh":"如果食用了过期的食品，就可能会拉肚子。","pinyin":"Rúguǒ shíyòngle guòqī de shípǐn, jiù kěnéng huì lādùzi.","vi":"Nếu ăn thực phẩm quá hạn thì có thể bị tiêu chảy."}],"related":[{"hanzi":"食物","pinyin":"shíwù","vi":"thức ăn"},{"hanzi":"饮用","pinyin":"yǐnyòng","vi":"dùng để uống"},{"hanzi":"食品","pinyin":"shípǐn","vi":"thực phẩm"},{"hanzi":"食用油","pinyin":"shíyòngyóu","vi":"dầu ăn"}]},{"id":"使唤","hanzi":"使唤","pinyin":"shǐhuan","meaning_vi":"sai khiến, sai bảo; điều khiển, sử dụng (đồ vật, gia súc)","explanation":"使 (sử – sai khiến) + 唤 (hoán – gọi) → gọi người khác làm việc cho mình; khẩu ngữ còn chỉ sử dụng, điều khiển dụng cụ.","hsk_level":"7-9","tags":["dong-tu"],"image":"👉","examples":[{"type":"basic","zh":"别总使唤别人。","pinyin":"Bié zǒng shǐhuan biérén.","vi":"Đừng lúc nào cũng sai bảo người khác."},{"type":"simple","zh":"他喜欢使唤弟弟去买东西。","pinyin":"Tā xǐhuan shǐhuan dìdi qù mǎidōngxi.","vi":"Anh ta thích sai em trai đi mua đồ."},{"type":"compound","zh":"虽然他是老板，但是也不能随便使唤员工。","pinyin":"Suīrán tā shì lǎobǎn, dànshì yě bù néng suíbiàn shǐhuan yuángōng.","vi":"Tuy là sếp, nhưng anh ta cũng không thể tùy tiện sai khiến nhân viên."}],"related":[{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"},{"hanzi":"指使","pinyin":"zhǐshǐ","vi":"xúi giục, sai khiến"},{"hanzi":"吩咐","pinyin":"fēnfu","vi":"dặn bảo"},{"hanzi":"差遣","pinyin":"chāiqiǎn","vi":"sai phái"}],"traditional":"使喚"},{"id":"使者","hanzi":"使者","pinyin":"shǐzhě","meaning_vi":"sứ giả, người đưa tin","explanation":"使 (sứ – đi sứ) + 者 (giả – người) → người được phái đi truyền đạt, giao thiệp thay mặt người khác.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"国王派出了使者。","pinyin":"Guówáng pàichūle shǐzhě.","vi":"Nhà vua đã phái sứ giả đi."},{"type":"simple","zh":"人们把鸽子看作和平的使者。","pinyin":"Rénmen bǎ gēzi kànzuò hépíng de shǐzhě.","vi":"Mọi người coi chim bồ câu là sứ giả của hòa bình."},{"type":"compound","zh":"虽然使者带来了礼物，但是对方并没有接受。","pinyin":"Suīrán shǐzhě dàiláile lǐwù, dànshì duìfāng bìng méiyǒu jiēshòu.","vi":"Tuy sứ giả mang lễ vật đến, nhưng phía bên kia không hề nhận."}],"related":[{"hanzi":"大使","pinyin":"dàshǐ","vi":"đại sứ"},{"hanzi":"使馆","pinyin":"shǐguǎn","vi":"sứ quán"},{"hanzi":"使命","pinyin":"shǐmìng","vi":"sứ mệnh"},{"hanzi":"特使","pinyin":"tèshǐ","vi":"đặc sứ"}]},{"id":"世界级","hanzi":"世界级","pinyin":"shìjièjí","meaning_vi":"đẳng cấp thế giới","explanation":"世界 (thế giới) + 级 (cấp – cấp bậc) → đạt tầm cỡ, trình độ thế giới.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌍","examples":[{"type":"basic","zh":"这是世界级的比赛。","pinyin":"Zhè shì shìjièjí de bǐsài.","vi":"Đây là cuộc thi đẳng cấp thế giới."},{"type":"simple","zh":"这座城市有一座世界级的博物馆。","pinyin":"Zhè zuò chéngshì yǒu yí zuò shìjièjí de bówùguǎn.","vi":"Thành phố này có một bảo tàng đẳng cấp thế giới."},{"type":"compound","zh":"只要坚持训练，他就有机会成为世界级的运动员。","pinyin":"Zhǐyào jiānchí xùnliàn, tā jiù yǒujī huì chéngwéi shìjièjí de yùndòngyuán.","vi":"Chỉ cần kiên trì tập luyện, cậu ấy sẽ có cơ hội trở thành vận động viên đẳng cấp thế giới."}],"related":[{"hanzi":"世界","pinyin":"shìjiè","vi":"thế giới"},{"hanzi":"国际","pinyin":"Guójì","vi":"quốc tế"},{"hanzi":"一流","pinyin":"yìliú","vi":"hạng nhất"},{"hanzi":"顶级","pinyin":"dǐngjí","vi":"hàng đầu"}],"traditional":"世界級"},{"id":"世袭","hanzi":"世袭","pinyin":"shìxí","meaning_vi":"thế tập, cha truyền con nối","explanation":"世 (thế – đời) + 袭 (tập – kế tục, tiếp nối) → đời đời kế thừa chức tước, địa vị theo dòng họ.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"爵位是世袭的。","pinyin":"Juéwèi shì shìxí de.","vi":"Tước vị là cha truyền con nối."},{"type":"simple","zh":"古代很多官职都是世袭的。","pinyin":"Gǔdài hěn duō guānzhí dōu shì shìxí de.","vi":"Thời xưa nhiều chức quan đều được thế tập."},{"type":"compound","zh":"虽然王位是世袭的，但是新国王必须得到大臣的支持。","pinyin":"Suīrán wángwèi shì shìxí de, dànshì xīn guówáng bìxū dédào dàchén de zhīchí.","vi":"Tuy ngôi vua là cha truyền con nối, nhưng tân vương vẫn phải được các đại thần ủng hộ."}],"related":[{"hanzi":"继承","pinyin":"jìchéng","vi":"thừa kế"},{"hanzi":"世代","pinyin":"shìdài","vi":"đời đời"},{"hanzi":"沿袭","pinyin":"yánxí","vi":"kế thừa, noi theo"},{"hanzi":"袭击","pinyin":"xíjī","vi":"tập kích"}],"traditional":"世襲"},{"id":"市场经济","hanzi":"市场经济","pinyin":"shìchǎngjīngjì","meaning_vi":"kinh tế thị trường","explanation":"市场 (thị trường) + 经济 (kinh tế) → nền kinh tế do quan hệ cung cầu trên thị trường điều tiết.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"💹","examples":[{"type":"basic","zh":"中国实行市场经济。","pinyin":"Zhōngguó shíxíng shìchǎngjīngjì.","vi":"Trung Quốc thực hiện kinh tế thị trường."},{"type":"simple","zh":"市场经济需要公平的竞争环境。","pinyin":"Shìchǎngjīngjì xūyào gōngpíng de jìngzhēng huánjìng.","vi":"Kinh tế thị trường cần môi trường cạnh tranh công bằng."},{"type":"compound","zh":"虽然市场经济很有活力，但是也需要政府的监管。","pinyin":"Suīrán shìchǎngjīngjì hěn yǒuhuólì, dànshì yě xūyào zhèngfǔ de jiānguǎn.","vi":"Tuy kinh tế thị trường rất năng động, nhưng cũng cần sự giám sát của nhà nước."}],"related":[{"hanzi":"计划经济","pinyin":"jìhuàjīngjì","vi":"kinh tế kế hoạch"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"},{"hanzi":"经济","pinyin":"jīngjì","vi":"kinh tế"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"}],"traditional":"市場經濟"},{"id":"似曾相识","hanzi":"似曾相识","pinyin":"sìcéng-xiāngshí","meaning_vi":"dường như đã từng quen, quen quen","explanation":"似 (tự – dường như) + 曾 (tằng – từng) + 相识 (tương thức – quen biết) → hình như đã từng gặp; chỉ cảm giác quen thuộc với người, cảnh mới gặp. Xuất xứ từ thơ Án Thù đời Tống.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🔁","examples":[{"type":"basic","zh":"这里让我似曾相识。","pinyin":"Zhèlǐ ràng wǒ sìcéngxiāngshí.","vi":"Nơi này khiến tôi thấy quen quen."},{"type":"simple","zh":"这首老歌听起来似曾相识。","pinyin":"Zhè shǒu lǎogē tīngqǐlái sìcéngxiāngshí.","vi":"Bài hát cũ này nghe như đã từng nghe."},{"type":"compound","zh":"虽然我们是第一次见面，但是我对他有一种似曾相识的感觉。","pinyin":"Suīrán wǒmen shì dìyīcì jiànmiàn, dànshì wǒ duì tā yǒu yì zhǒng sìcéngxiāngshí de gǎnjué.","vi":"Tuy là lần đầu gặp mặt, nhưng tôi có cảm giác như đã quen anh ấy từ trước."}],"related":[{"hanzi":"相识","pinyin":"xiāngshí","vi":"quen biết"},{"hanzi":"熟悉","pinyin":"shúxī","vi":"quen thuộc"},{"hanzi":"陌生","pinyin":"mòshēng","vi":"xa lạ"},{"hanzi":"曾经","pinyin":"céngjīng","vi":"từng"}],"traditional":"似曾相識"},{"id":"事务所","hanzi":"事务所","pinyin":"shìwùsuǒ","meaning_vi":"văn phòng (luật, kế toán…), hãng","explanation":"事务 (sự vụ – công việc) + 所 (sở – nơi chốn) → nơi xử lý công việc chuyên môn, như 律师事务所 văn phòng luật.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"他在律师事务所工作。","pinyin":"Tā zài lǜshī shìwùsuǒ gōngzuò.","vi":"Anh ấy làm việc ở văn phòng luật."},{"type":"simple","zh":"这家设计事务所只有五个员工。","pinyin":"Zhè jiā shèjì shìwùsuǒ zhǐyǒu wǔ gè yuángōng.","vi":"Văn phòng thiết kế này chỉ có năm nhân viên."},{"type":"compound","zh":"如果你遇到法律问题，就可以去律师事务所咨询。","pinyin":"Rúguǒ nǐ yùdào fǎlǜ wèntí, jiù kěyǐ qù lǜshī shìwùsuǒ zīxún.","vi":"Nếu gặp vấn đề pháp lý, bạn có thể đến văn phòng luật để tư vấn."}],"related":[{"hanzi":"事务","pinyin":"shìwù","vi":"công việc, sự vụ"},{"hanzi":"律师","pinyin":"lǜshī","vi":"luật sư"},{"hanzi":"办公室","pinyin":"bàngōngshì","vi":"văn phòng"},{"hanzi":"公司","pinyin":"gōngsī","vi":"công ty"}],"traditional":"事務所"},{"id":"侍候","hanzi":"侍候","pinyin":"shìhòu","meaning_vi":"hầu hạ, chăm sóc","explanation":"侍 (thị – hầu) + 候 (hậu – chờ, thăm hỏi) → ở bên phục vụ, chăm lo cho người khác.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🫖","examples":[{"type":"basic","zh":"她侍候生病的婆婆。","pinyin":"Tā shìhòu shēngbìng de pópo.","vi":"Cô ấy chăm sóc mẹ chồng bị ốm."},{"type":"simple","zh":"他从小就侍候爷爷奶奶。","pinyin":"Tā cóngxiǎo jiù shìhòu yéye nǎinai.","vi":"Từ nhỏ cậu ấy đã chăm nom ông bà."},{"type":"compound","zh":"虽然侍候病人很辛苦，但是她从来没有抱怨过。","pinyin":"Suīrán shìhòu bìngrén hěn xīnkǔ, dànshì tā cónglái méiyǒu bàoyuàn guo.","vi":"Tuy chăm người bệnh rất vất vả, nhưng cô ấy chưa từng than phiền."}],"related":[{"hanzi":"伺候","pinyin":"cìhou","vi":"hầu hạ"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"},{"hanzi":"服侍","pinyin":"fúshi","vi":"phục dịch"},{"hanzi":"侍者","pinyin":"shìzhě","vi":"người hầu"}]},{"id":"势不可当","hanzi":"势不可当","pinyin":"shìbù-kědāng","meaning_vi":"thế không thể cản, không gì ngăn nổi","explanation":"势 (thế – khí thế) + 不可 (bất khả – không thể) + 当 (đương – chống đỡ) → khí thế mạnh đến mức không ai chống nổi.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"这支球队势不可当。","pinyin":"Zhè zhī qiúduì shìbùkědāng.","vi":"Đội bóng này mạnh không gì cản nổi."},{"type":"simple","zh":"新能源汽车的发展势不可当。","pinyin":"Xīnnéngyuánqìchē de fāzhǎn shìbùkědāng.","vi":"Sự phát triển của xe năng lượng mới là không thể ngăn cản."},{"type":"compound","zh":"一旦改革的浪潮形成，就势不可当。","pinyin":"Yídàn gǎigé de làngcháo xíngchéng, jiù shìbùkědāng.","vi":"Một khi làn sóng cải cách đã hình thành thì không gì ngăn nổi."}],"related":[{"hanzi":"锐不可当","pinyin":"ruìbùkědāng","vi":"mạnh không cản nổi"},{"hanzi":"势如破竹","pinyin":"shìrúpòzhú","vi":"thế như chẻ tre"},{"hanzi":"气势","pinyin":"qìshì","vi":"khí thế"},{"hanzi":"阻挡","pinyin":"zǔdǎng","vi":"ngăn cản"}],"traditional":"勢不可當"},{"id":"视察","hanzi":"视察","pinyin":"shìchá","meaning_vi":"thị sát, kiểm tra","explanation":"视 (thị – nhìn) + 察 (sát – xem xét) → (cấp trên) đến tận nơi xem xét, kiểm tra tình hình.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔍","examples":[{"type":"basic","zh":"市长来工厂视察。","pinyin":"Shìzhǎng lái gōngchǎng shìchá.","vi":"Thị trưởng đến nhà máy thị sát."},{"type":"simple","zh":"领导明天要视察我们的学校。","pinyin":"Lǐngdǎo míngtiān yào shìchá wǒmen de xuéxiào.","vi":"Ngày mai lãnh đạo sẽ đến kiểm tra trường chúng tôi."},{"type":"compound","zh":"因为上级要来视察，所以大家都在打扫卫生。","pinyin":"Yīnwèi shàngjí yào lái shìchá, suǒyǐ dàjiā dōu zài dǎsǎo wèishēng.","vi":"Vì cấp trên sắp đến thị sát nên mọi người đều đang dọn vệ sinh."}],"related":[{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"},{"hanzi":"考察","pinyin":"kǎochá","vi":"khảo sát"},{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"视野","pinyin":"shìyě","vi":"tầm nhìn"}],"traditional":"視察"},{"id":"柿子","hanzi":"柿子","pinyin":"shìzi","meaning_vi":"quả hồng","explanation":"柿 (thị – cây hồng) + 子 (tử – hậu tố danh từ) → quả hồng, chín vào mùa thu.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍊","examples":[{"type":"basic","zh":"秋天的柿子很甜。","pinyin":"Qiūtiān de shìzi hěn tián.","vi":"Hồng mùa thu rất ngọt."},{"type":"simple","zh":"树上挂满了红红的柿子。","pinyin":"Shù shàng guà mǎnle hóng hóng de shìzi.","vi":"Trên cây treo đầy những quả hồng đỏ."},{"type":"compound","zh":"如果柿子还没熟，吃起来就会很涩。","pinyin":"Rúguǒ shìzi hái méi shú, chī qǐlái jiù huì hěn sè.","vi":"Nếu hồng chưa chín thì ăn sẽ rất chát."}],"related":[{"hanzi":"柿饼","pinyin":"shìbǐng","vi":"hồng khô"},{"hanzi":"西红柿","pinyin":"xīhóngshì","vi":"cà chua"},{"hanzi":"橘子","pinyin":"júzi","vi":"quýt"},{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"trái cây"}]},{"id":"识别","hanzi":"识别","pinyin":"shíbié","meaning_vi":"nhận dạng, phân biệt, nhận biết","explanation":"识 (thức – biết, nhận ra) + 别 (biệt – phân biệt) → nhận ra và phân biệt được; hay dùng trong công nghệ: 人脸识别.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🧐","examples":[{"type":"basic","zh":"手机能识别人脸。","pinyin":"Shǒujī néng shíbié rén liǎn.","vi":"Điện thoại có thể nhận diện khuôn mặt."},{"type":"simple","zh":"这个软件可以识别图片里的文字。","pinyin":"Zhè ge ruǎnjiàn kěyǐ shíbié túpiàn lǐ de wénzì.","vi":"Phần mềm này có thể nhận dạng chữ trong ảnh."},{"type":"compound","zh":"如果你学会识别假币，就不容易上当了。","pinyin":"Rúguǒ nǐ xuéhuì shíbié jiǎbì, jiù bù róngyì shàngdàng le.","vi":"Nếu bạn biết nhận ra tiền giả thì sẽ không dễ bị lừa."}],"related":[{"hanzi":"辨别","pinyin":"biànbié","vi":"phân biệt"},{"hanzi":"区别","pinyin":"qūbié","vi":"khác biệt"},{"hanzi":"认识","pinyin":"rènshi","vi":"nhận biết"},{"hanzi":"识破","pinyin":"shípò","vi":"nhìn thấu"}],"traditional":"識別"},{"id":"收买","hanzi":"收买","pinyin":"shōumǎi","meaning_vi":"mua chuộc; thu mua","explanation":"收 (thu – thu vào) + 买 (mãi – mua) → mua vào; nghĩa thường gặp là dùng tiền, lợi ích để mua chuộc lòng người.","hsk_level":"7-9","tags":["dong-tu"],"image":"💰","examples":[{"type":"basic","zh":"他想收买证人。","pinyin":"Tā xiǎng shōumǎi zhèngrén.","vi":"Hắn muốn mua chuộc nhân chứng."},{"type":"simple","zh":"敌人企图用金钱收买他。","pinyin":"Dírén qǐtú yòng jīnqián shōumǎi tā.","vi":"Kẻ địch định dùng tiền bạc mua chuộc anh ấy."},{"type":"compound","zh":"虽然对方出了很多钱，但是他坚决不被收买。","pinyin":"Suīrán duìfāng chūle hěn duō qián, dànshì tā jiānjué bú bèi shōumǎi.","vi":"Tuy đối phương bỏ ra rất nhiều tiền, nhưng anh ấy kiên quyết không để bị mua chuộc."}],"related":[{"hanzi":"贿赂","pinyin":"huìlù","vi":"hối lộ"},{"hanzi":"收购","pinyin":"shōugòu","vi":"thu mua"},{"hanzi":"购买","pinyin":"gòumǎi","vi":"mua"},{"hanzi":"拉拢","pinyin":"lālǒng","vi":"lôi kéo"}],"traditional":"收買"},{"id":"收支","hanzi":"收支","pinyin":"shōuzhī","meaning_vi":"thu chi, thu nhập và chi tiêu","explanation":"收 (thu – thu vào) + 支 (chi – chi ra) → khoản thu và khoản chi; hay dùng 收支平衡 cân bằng thu chi.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"每月收支要记清楚。","pinyin":"Měiyuè shōuzhī yào jì qīngchu.","vi":"Thu chi mỗi tháng phải ghi rõ ràng."},{"type":"simple","zh":"这家公司今年终于收支平衡了。","pinyin":"Zhè jiā gōngsī jīnnián zhōngyú shōuzhī pínghéng le.","vi":"Năm nay công ty này cuối cùng đã cân bằng thu chi."},{"type":"compound","zh":"如果收支长期不平衡，家里就会出现经济困难。","pinyin":"Rúguǒ shōuzhī chángqī bù pínghéng, jiālǐ jiù huì chūxiàn jīngjì kùnnan.","vi":"Nếu thu chi lâu ngày mất cân đối, gia đình sẽ gặp khó khăn kinh tế."}],"related":[{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"支出","pinyin":"zhīchū","vi":"chi tiêu"},{"hanzi":"开支","pinyin":"kāizhī","vi":"khoản chi"},{"hanzi":"账目","pinyin":"zhàngmù","vi":"sổ sách"}]},{"id":"手臂","hanzi":"手臂","pinyin":"shǒubì","meaning_vi":"cánh tay, (nghĩa bóng) trợ thủ","explanation":"手 (thủ – tay) + 臂 (tý – cánh tay) → cả cánh tay; nghĩa bóng chỉ người trợ giúp đắc lực.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"💪","examples":[{"type":"basic","zh":"他的手臂受伤了。","pinyin":"Tā de shǒubì shòushāng le.","vi":"Cánh tay anh ấy bị thương."},{"type":"simple","zh":"她张开手臂抱住了孩子。","pinyin":"Tā zhāngkāi shǒubì bào zhùle háizi.","vi":"Cô ấy dang tay ôm lấy đứa trẻ."},{"type":"compound","zh":"因为每天举重，所以他的手臂特别有力。","pinyin":"Yīnwèi měitiān jǔzhòng, suǒyǐ tā de shǒubì tèbié yǒulì.","vi":"Vì ngày nào cũng cử tạ nên cánh tay anh ấy rất khỏe."}],"related":[{"hanzi":"胳膊","pinyin":"gēbo","vi":"cánh tay"},{"hanzi":"手腕","pinyin":"shǒuwàn","vi":"cổ tay"},{"hanzi":"肩膀","pinyin":"jiānbǎng","vi":"vai"},{"hanzi":"手掌","pinyin":"shǒuzhǎng","vi":"lòng bàn tay"}]},{"id":"手动","hanzi":"手动","pinyin":"shǒudòng","meaning_vi":"thủ công, bằng tay, số sàn","explanation":"手 (thủ – tay) + 动 (động – vận hành) → vận hành bằng tay, không tự động; 手动挡 xe số sàn.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🕹️","examples":[{"type":"basic","zh":"这辆车是手动挡。","pinyin":"Zhè liàng chē shì shǒudòngdǎng.","vi":"Chiếc xe này là xe số sàn."},{"type":"simple","zh":"系统出了问题，只能手动输入数据。","pinyin":"Xìtǒng chūle wèntí, zhǐnéng shǒudòng shūrù shùjù.","vi":"Hệ thống gặp sự cố, chỉ có thể nhập dữ liệu thủ công."},{"type":"compound","zh":"如果自动更新失败了，你就手动下载安装包。","pinyin":"Rúguǒ zìdòng gēngxīn shībài le, nǐ jiù shǒudòng xiàzài ānzhuāngbāo.","vi":"Nếu cập nhật tự động thất bại, bạn hãy tải gói cài đặt về bằng tay."}],"related":[{"hanzi":"自动","pinyin":"zìdòng","vi":"tự động"},{"hanzi":"手工","pinyin":"shǒugōng","vi":"thủ công"},{"hanzi":"操作","pinyin":"cāozuò","vi":"thao tác"},{"hanzi":"手动挡","pinyin":"shǒudòngdǎng","vi":"số sàn"}],"traditional":"手動"},{"id":"手脚","hanzi":"手脚","pinyin":"shǒujiǎo","meaning_vi":"tay chân; động tác; mánh khóe, trò gian lận","explanation":"手 (thủ – tay) + 脚 (cước – chân) → tay chân, cử động; 做手脚 nghĩa bóng là giở trò gian lận.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🤸","examples":[{"type":"basic","zh":"他手脚很麻利。","pinyin":"Tā shǒujiǎo hěn máli.","vi":"Anh ấy tay chân rất nhanh nhẹn."},{"type":"simple","zh":"天太冷了，我的手脚都冻僵了。","pinyin":"Tiān tài lěng le, wǒ de shǒujiǎo dōu dòngjiāng le.","vi":"Trời lạnh quá, tay chân tôi đều cóng cả."},{"type":"compound","zh":"如果有人在账目上做手脚，审计时就会被发现。","pinyin":"Rúguǒ yǒurén zài zhàngmù shàng zuòshǒujiǎo, shěn jìshí jiù huì bèi fāxiàn.","vi":"Nếu có ai giở trò trong sổ sách thì khi kiểm toán sẽ bị phát hiện."}],"related":[{"hanzi":"做手脚","pinyin":"zuòshǒujiǎo","vi":"giở trò"},{"hanzi":"动作","pinyin":"dòngzuò","vi":"động tác"},{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"luống cuống"},{"hanzi":"四肢","pinyin":"sìzhī","vi":"tứ chi"}],"traditional":"手腳"},{"id":"手帕","hanzi":"手帕","pinyin":"shǒupà","meaning_vi":"khăn tay, khăn mùi soa","explanation":"手 (thủ – tay) + 帕 (phạ – khăn) → chiếc khăn nhỏ cầm tay để lau mặt, lau mồ hôi.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🧣","examples":[{"type":"basic","zh":"她拿出一块手帕。","pinyin":"Tā náchū yíkuài shǒupà.","vi":"Cô ấy lấy ra một chiếc khăn tay."},{"type":"simple","zh":"奶奶总是用手帕擦眼镜。","pinyin":"Nǎinai zǒngshì yòng shǒupà cā yǎnjìng.","vi":"Bà luôn dùng khăn tay lau kính."},{"type":"compound","zh":"虽然现在大家都用纸巾，但是爷爷还是习惯带手帕。","pinyin":"Suīrán xiànzài dàjiā dōu yòng zhǐjīn, dànshì yéye háishì xíguàn dài shǒupà.","vi":"Tuy giờ mọi người đều dùng khăn giấy, nhưng ông vẫn quen mang khăn tay."}],"related":[{"hanzi":"纸巾","pinyin":"zhǐjīn","vi":"khăn giấy"},{"hanzi":"毛巾","pinyin":"máojīn","vi":"khăn mặt"},{"hanzi":"手绢","pinyin":"shǒujuàn","vi":"khăn tay"},{"hanzi":"围巾","pinyin":"wéijīn","vi":"khăn quàng"}]},{"id":"手枪","hanzi":"手枪","pinyin":"shǒuqiāng","meaning_vi":"súng lục, súng ngắn","explanation":"手 (thủ – tay) + 枪 (thương – súng) → súng nhỏ cầm một tay để bắn.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔫","examples":[{"type":"basic","zh":"警察拔出了手枪。","pinyin":"Jǐngchá báchūle shǒuqiāng.","vi":"Cảnh sát rút súng lục ra."},{"type":"simple","zh":"这把手枪是博物馆的展品。","pinyin":"Zhè bǎ shǒuqiāng shì bówùguǎn de zhǎnpǐn.","vi":"Khẩu súng ngắn này là hiện vật trưng bày của bảo tàng."},{"type":"compound","zh":"因为私人不能持有手枪，所以他把枪交给了警方。","pinyin":"Yīnwèi sīrén bù néng chíyǒu shǒuqiāng, suǒyǐ tā bǎ qiāng jiāogěile jǐngfāng.","vi":"Vì cá nhân không được sở hữu súng ngắn nên anh ta đã nộp súng cho cảnh sát."}],"related":[{"hanzi":"步枪","pinyin":"bùqiāng","vi":"súng trường"},{"hanzi":"子弹","pinyin":"zǐdàn","vi":"viên đạn"},{"hanzi":"枪声","pinyin":"qiāngshēng","vi":"tiếng súng"},{"hanzi":"开枪","pinyin":"kāiqiāng","vi":"nổ súng"}],"traditional":"手槍"},{"id":"手腕","hanzi":"手腕","pinyin":"shǒuwàn","meaning_vi":"cổ tay; thủ đoạn, tài xoay xở","explanation":"手 (thủ – tay) + 腕 (oản – cổ tay) → cổ tay; nghĩa bóng chỉ thủ đoạn, bản lĩnh xử lý công việc.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"⌚","examples":[{"type":"basic","zh":"我的手腕扭伤了。","pinyin":"Wǒ de shǒuwàn niǔshāng le.","vi":"Cổ tay tôi bị bong gân."},{"type":"simple","zh":"她手腕上戴着一块旧手表。","pinyin":"Tā shǒuwàn shàng dàizhe yíkuài jiù shǒubiǎo.","vi":"Trên cổ tay cô ấy đeo một chiếc đồng hồ cũ."},{"type":"compound","zh":"虽然他很年轻，但是处理问题很有手腕。","pinyin":"Suīrán tā hěn niánqīng, dànshì chǔlǐ wèntí hěn yǒu shǒuwàn.","vi":"Tuy còn trẻ, nhưng anh ấy xử lý vấn đề rất có bản lĩnh."}],"related":[{"hanzi":"手臂","pinyin":"shǒubì","vi":"cánh tay"},{"hanzi":"手段","pinyin":"shǒuduàn","vi":"thủ đoạn"},{"hanzi":"手表","pinyin":"shǒubiǎo","vi":"đồng hồ đeo tay"},{"hanzi":"手掌","pinyin":"shǒuzhǎng","vi":"lòng bàn tay"}]},{"id":"手掌","hanzi":"手掌","pinyin":"shǒuzhǎng","meaning_vi":"lòng bàn tay, bàn tay","explanation":"手 (thủ – tay) + 掌 (chưởng – bàn tay) → phần bàn tay, nhất là lòng bàn tay.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"✋","examples":[{"type":"basic","zh":"他的手掌很大。","pinyin":"Tā de shǒuzhǎng hěn dà.","vi":"Bàn tay anh ấy rất to."},{"type":"simple","zh":"小鸟停在她的手掌上吃米。","pinyin":"Xiǎoniǎo tíng zài tā de shǒuzhǎng shàng chī mǐ.","vi":"Chú chim nhỏ đậu trên lòng bàn tay cô ấy ăn gạo."},{"type":"compound","zh":"虽然天很冷，但是他的手掌一直出汗。","pinyin":"Suīrán tiān hěn lěng, dànshì tā de shǒuzhǎng yìzhí chūhàn.","vi":"Tuy trời rất lạnh, nhưng lòng bàn tay anh ấy cứ ra mồ hôi."}],"related":[{"hanzi":"手指","pinyin":"shǒuzhǐ","vi":"ngón tay"},{"hanzi":"鼓掌","pinyin":"gǔzhǎng","vi":"vỗ tay"},{"hanzi":"手背","pinyin":"shǒubèi","vi":"mu bàn tay"},{"hanzi":"巴掌","pinyin":"bāzhang","vi":"bàn tay, cái tát"}]},{"id":"守候","hanzi":"守候","pinyin":"shǒuhòu","meaning_vi":"chờ đợi, canh giữ, túc trực","explanation":"守 (thủ – giữ, canh) + 候 (hậu – chờ) → ở yên một chỗ canh chừng, chờ đợi; túc trực bên ai.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏱️","examples":[{"type":"basic","zh":"记者在门口守候。","pinyin":"Jìzhě zài ménkǒu shǒuhòu.","vi":"Phóng viên chờ sẵn ở cửa."},{"type":"simple","zh":"妈妈整夜守候在病床旁边。","pinyin":"Māma zhěngyè shǒuhòu zài bìngchuáng pángbiān.","vi":"Mẹ túc trực cả đêm bên giường bệnh."},{"type":"compound","zh":"即使等到天亮，他也要守候在这里。","pinyin":"Jíshǐ děngdào tiānliàng, tā yě yào shǒuhòu zài zhèlǐ.","vi":"Dù phải đợi đến sáng, anh ấy cũng sẽ canh chờ ở đây."}],"related":[{"hanzi":"等候","pinyin":"děnghòu","vi":"chờ đợi"},{"hanzi":"守护","pinyin":"shǒuhù","vi":"bảo vệ"},{"hanzi":"看守","pinyin":"kānshǒu","vi":"canh giữ"},{"hanzi":"陪伴","pinyin":"péibàn","vi":"ở bên"}]},{"id":"首府","hanzi":"首府","pinyin":"Shǒufǔ","meaning_vi":"thủ phủ (thủ phủ khu tự trị)","explanation":"首 (thủ – đầu, đứng đầu) + 府 (phủ – phủ, nơi đặt cơ quan) → thành phố đứng đầu, nơi đặt chính quyền của khu tự trị hay tỉnh.","hsk_level":"7-9","tags":["danh-tu","dia-danh"],"image":"🏛️","examples":[{"type":"basic","zh":"拉萨是西藏的首府。","pinyin":"Lāsà shì Xīzàng de Shǒufǔ.","vi":"Lhasa là thủ phủ của Tây Tạng."},{"type":"simple","zh":"我们坐火车到了新疆首府乌鲁木齐。","pinyin":"Wǒmen zuò huǒchē dàole Xīnjiāng Shǒufǔ Wūlǔmùqí.","vi":"Chúng tôi đi tàu đến Urumqi, thủ phủ của Tân Cương."},{"type":"compound","zh":"虽然首府不算很大，但是交通非常方便。","pinyin":"Suīrán Shǒufǔ búsuàn hěn dà, dànshì jiāotōng fēicháng fāngbiàn.","vi":"Tuy thủ phủ không lớn lắm, nhưng giao thông rất thuận tiện."}],"related":[{"hanzi":"首都","pinyin":"shǒudū","vi":"thủ đô"},{"hanzi":"省会","pinyin":"shěnghuì","vi":"tỉnh lỵ"},{"hanzi":"自治区","pinyin":"zìzhìqū","vi":"khu tự trị"},{"hanzi":"城市","pinyin":"chéngshì","vi":"thành phố"}]},{"id":"首批","hanzi":"首批","pinyin":"shǒupī","meaning_vi":"đợt đầu tiên, lô đầu tiên","explanation":"首 (thủ – đầu tiên) + 批 (phê – lô, đợt) → nhóm, lô đầu tiên trong nhiều đợt.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"🥇","examples":[{"type":"basic","zh":"首批货物已经到了。","pinyin":"Shǒupī huòwù yǐjīng dào le.","vi":"Lô hàng đầu tiên đã đến."},{"type":"simple","zh":"他是公司首批员工之一。","pinyin":"Tā shì gōngsī shǒupī yuángōng zhīyī.","vi":"Anh ấy là một trong những nhân viên đầu tiên của công ty."},{"type":"compound","zh":"如果首批疫苗效果好，政府就会扩大生产。","pinyin":"Rúguǒ shǒupī yìmiáo xiàoguǒ hǎo, zhèngfǔ jiù huì kuòdà shēngchǎn.","vi":"Nếu lô vắc-xin đầu tiên hiệu quả tốt, chính phủ sẽ mở rộng sản xuất."}],"related":[{"hanzi":"首次","pinyin":"shǒucì","vi":"lần đầu"},{"hanzi":"批次","pinyin":"pīcì","vi":"lô, đợt"},{"hanzi":"第一批","pinyin":"dìyīpī","vi":"đợt thứ nhất"},{"hanzi":"首届","pinyin":"shǒujiè","vi":"khóa đầu tiên"}]},{"id":"受过","hanzi":"受过","pinyin":"shòuguò","meaning_vi":"chịu lỗi (thay người khác), gánh tội","explanation":"受 (thụ – chịu) + 过 (quá – lỗi lầm) → chịu lỗi, gánh trách nhiệm; thường dùng 代人受过 chịu tội thay người khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"他替朋友受过。","pinyin":"Tā tì péngyou shòuguò.","vi":"Anh ấy chịu lỗi thay bạn."},{"type":"simple","zh":"这件事不是我做的，我不愿意代人受过。","pinyin":"Zhè jiàn shì bú shì wǒ zuò de, wǒ bú yuànyì dài rén shòuguò.","vi":"Việc này không phải tôi làm, tôi không muốn gánh tội thay người khác."},{"type":"compound","zh":"虽然错不在他，但是他还是主动替下属受过。","pinyin":"Suīrán cuò bú zài tā, dànshì tā háishì zhǔdòng tì xiàshǔ shòuguò.","vi":"Tuy lỗi không phải ở anh ấy, nhưng anh vẫn chủ động chịu lỗi thay cấp dưới."}],"related":[{"hanzi":"代人受过","pinyin":"dàirénshòuguò","vi":"chịu tội thay"},{"hanzi":"过错","pinyin":"guòcuò","vi":"lỗi lầm"},{"hanzi":"背锅","pinyin":"bēiguō","vi":"gánh tội thay"},{"hanzi":"承担","pinyin":"chéngdān","vi":"gánh vác"}],"traditional":"受過"},{"id":"受害","hanzi":"受害","pinyin":"shòuhài","meaning_vi":"bị hại, bị thiệt hại","explanation":"受 (thụ – chịu) + 害 (hại – tổn hại) → chịu tổn hại, bị thiệt hại về người hoặc của.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🤕","examples":[{"type":"basic","zh":"很多农民受害了。","pinyin":"Hěn duō nóngmín shòuhài le.","vi":"Rất nhiều nông dân bị thiệt hại."},{"type":"simple","zh":"这次洪水中受害最严重的是山区。","pinyin":"Zhè cì hóngshuǐ zhōng shòuhài zuì yánzhòng de shì shānqū.","vi":"Trong trận lũ lần này, vùng núi bị thiệt hại nặng nhất."},{"type":"compound","zh":"如果你在网上受害了，就应该马上报警。","pinyin":"Rúguǒ nǐ zài wǎngshàng shòuhài le, jiù yīnggāi mǎshàng bàojǐng.","vi":"Nếu bạn bị hại trên mạng, nên báo cảnh sát ngay."}],"related":[{"hanzi":"受害人","pinyin":"shòuhàirén","vi":"nạn nhân"},{"hanzi":"伤害","pinyin":"shānghài","vi":"làm tổn thương"},{"hanzi":"损害","pinyin":"sǔnhài","vi":"tổn hại"},{"hanzi":"遭受","pinyin":"zāoshòu","vi":"gặp phải"}]},{"id":"受害人","hanzi":"受害人","pinyin":"shòuhàirén","meaning_vi":"người bị hại, nạn nhân","explanation":"受害 (thụ hại – bị hại) + 人 (nhân – người) → người chịu thiệt hại trong vụ án, tai nạn.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🆘","examples":[{"type":"basic","zh":"受害人已经报警了。","pinyin":"Shòuhàirén yǐjīng bàojǐng le.","vi":"Người bị hại đã báo cảnh sát."},{"type":"simple","zh":"法院判他赔偿受害人的损失。","pinyin":"Fǎyuàn pàn tā péicháng shòuhàirén de sǔnshī.","vi":"Tòa án xử anh ta phải bồi thường thiệt hại cho nạn nhân."},{"type":"compound","zh":"虽然受害人很害怕，但是她还是勇敢地出庭作证了。","pinyin":"Suīrán shòuhàirén hěn hàipà, dànshì tā háishì yǒnggǎn de chūtíng zuòzhèng le.","vi":"Tuy người bị hại rất sợ, nhưng cô ấy vẫn dũng cảm ra tòa làm chứng."}],"related":[{"hanzi":"受害者","pinyin":"shòuhàizhě","vi":"nạn nhân"},{"hanzi":"嫌疑人","pinyin":"xiányírén","vi":"nghi phạm"},{"hanzi":"被告","pinyin":"bèigào","vi":"bị cáo"},{"hanzi":"证人","pinyin":"zhèngrén","vi":"nhân chứng"}]},{"id":"受贿","hanzi":"受贿","pinyin":"shòuhuì","meaning_vi":"nhận hối lộ","explanation":"受 (thụ – nhận) + 贿 (hối – của đút lót) → nhận tiền, quà đút lót để làm lợi cho người đưa.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"💸","examples":[{"type":"basic","zh":"那个官员受贿了。","pinyin":"Nà ge guānyuán shòuhuì le.","vi":"Viên quan chức đó đã nhận hối lộ."},{"type":"simple","zh":"他因为受贿被判了十年。","pinyin":"Tā yīnwèi shòuhuì bèi pànle shí nián.","vi":"Hắn bị kết án mười năm vì nhận hối lộ."},{"type":"compound","zh":"一旦受贿的证据被找到，他就会被撤职。","pinyin":"Yídàn shòuhuì de zhèngjù bèi zhǎodào, tā jiù huì bèi chèzhí.","vi":"Một khi tìm được bằng chứng nhận hối lộ, ông ta sẽ bị cách chức."}],"related":[{"hanzi":"行贿","pinyin":"xínghuì","vi":"đưa hối lộ"},{"hanzi":"贿赂","pinyin":"huìlù","vi":"hối lộ"},{"hanzi":"腐败","pinyin":"fǔbài","vi":"tham nhũng"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"}],"traditional":"受賄"},{"id":"受惊","hanzi":"受惊","pinyin":"shòujīng","meaning_vi":"bị giật mình, hoảng sợ","explanation":"受 (thụ – chịu) + 惊 (kinh – sợ hãi) → bị làm cho giật mình, hoảng sợ.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"马受惊跑了。","pinyin":"Mǎ shòujīng pǎo le.","vi":"Con ngựa hoảng sợ chạy mất."},{"type":"simple","zh":"孩子受惊以后一直哭个不停。","pinyin":"Háizi shòujīng yǐhòu yìzhí kū ge bùtíng.","vi":"Đứa bé bị giật mình xong cứ khóc mãi không thôi."},{"type":"compound","zh":"因为突然打雷，所以小猫受惊躲到了床下。","pinyin":"Yīnwèi tūrán dǎléi, suǒyǐ xiǎomāo shòujīng duǒ dàole chuáng xià.","vi":"Vì bỗng có sấm sét nên con mèo hoảng sợ trốn xuống gầm giường."}],"related":[{"hanzi":"吃惊","pinyin":"chījīng","vi":"kinh ngạc"},{"hanzi":"惊吓","pinyin":"jīngxià","vi":"làm sợ hãi"},{"hanzi":"害怕","pinyin":"hàipà","vi":"sợ"},{"hanzi":"惊慌","pinyin":"jīnghuāng","vi":"hoảng hốt"}],"traditional":"受驚"},{"id":"受苦","hanzi":"受苦","pinyin":"shòukǔ","meaning_vi":"chịu khổ, chịu cực","explanation":"受 (thụ – chịu) + 苦 (khổ – khổ sở) → phải chịu cảnh gian khổ, đau đớn.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"我不想让你受苦。","pinyin":"Wǒ bù xiǎng ràng nǐ shòukǔ.","vi":"Anh không muốn để em chịu khổ."},{"type":"simple","zh":"战争让无数百姓受苦受难。","pinyin":"Zhànzhēng ràng wúshù bǎixìng shòukǔ shòunàn.","vi":"Chiến tranh khiến biết bao người dân chịu khổ chịu nạn."},{"type":"compound","zh":"虽然那几年一家人都在受苦，但是他从不抱怨命运。","pinyin":"Suīrán nà jǐ nián yìjiārén dōu zài shòukǔ, dànshì tā cóng bú bàoyuàn mìngyùn.","vi":"Tuy mấy năm đó cả nhà đều chịu khổ, nhưng anh ấy chưa bao giờ oán trách số phận."}],"related":[{"hanzi":"吃苦","pinyin":"chīkǔ","vi":"chịu khổ"},{"hanzi":"痛苦","pinyin":"tòngkǔ","vi":"đau khổ"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"vất vả"},{"hanzi":"享福","pinyin":"xiǎngfú","vi":"hưởng phúc"}]},{"id":"受理","hanzi":"受理","pinyin":"shòulǐ","meaning_vi":"thụ lý, tiếp nhận xử lý","explanation":"受 (thụ – nhận) + 理 (lý – xử lý) → tiếp nhận và giải quyết (vụ án, hồ sơ, yêu cầu).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"📥","examples":[{"type":"basic","zh":"法院受理了此案。","pinyin":"Fǎyuàn shòulǐle cǐ àn.","vi":"Tòa án đã thụ lý vụ án này."},{"type":"simple","zh":"这个窗口只受理护照申请。","pinyin":"Zhè ge chuāngkǒu zhǐ shòulǐ hùzhào shēnqǐng.","vi":"Quầy này chỉ tiếp nhận hồ sơ xin hộ chiếu."},{"type":"compound","zh":"如果材料不齐全，我们就不能受理你的申请。","pinyin":"Rúguǒ cáiliào bù qíquán, wǒmen jiù bù néng shòulǐ nǐ de shēnqǐng.","vi":"Nếu hồ sơ không đầy đủ, chúng tôi không thể tiếp nhận đơn của bạn."}],"related":[{"hanzi":"处理","pinyin":"chǔlǐ","vi":"xử lý"},{"hanzi":"办理","pinyin":"bànlǐ","vi":"làm thủ tục"},{"hanzi":"审理","pinyin":"shěnlǐ","vi":"xét xử"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"đơn xin"}]},{"id":"受益","hanzi":"受益","pinyin":"shòuyì","meaning_vi":"được lợi, hưởng lợi","explanation":"受 (thụ – nhận) + 益 (ích – lợi ích) → nhận được lợi ích, được hưởng lợi từ điều gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎁","examples":[{"type":"basic","zh":"我受益很多。","pinyin":"Wǒ shòuyì hěn duō.","vi":"Tôi được lợi rất nhiều."},{"type":"simple","zh":"这项政策让很多农民受益。","pinyin":"Zhè xiàng zhèngcè ràng hěn duō nóngmín shòuyì.","vi":"Chính sách này giúp nhiều nông dân hưởng lợi."},{"type":"compound","zh":"虽然这本书很薄，但是我读完后受益匪浅。","pinyin":"Suīrán zhè běn shū hěn báo, dànshì wǒ dú wán hòu shòuyì fěi qiǎn.","vi":"Tuy cuốn sách này mỏng, nhưng đọc xong tôi được lợi không ít."}],"related":[{"hanzi":"受益匪浅","pinyin":"shòuyìfěiqiǎn","vi":"được lợi nhiều"},{"hanzi":"利益","pinyin":"lìyì","vi":"lợi ích"},{"hanzi":"收益","pinyin":"shōuyì","vi":"thu nhập, lợi nhuận"},{"hanzi":"受惠","pinyin":"shòuhuì","vi":"được hưởng ơn"}]},{"id":"售价","hanzi":"售价","pinyin":"shòujià","meaning_vi":"giá bán","explanation":"售 (thụ – bán) + 价 (giá – giá cả) → giá bán ra của hàng hóa.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这款手机售价很高。","pinyin":"Zhè kuǎn shǒujī shòujià hěn gāo.","vi":"Mẫu điện thoại này có giá bán rất cao."},{"type":"simple","zh":"新车的售价比去年降低了不少。","pinyin":"Xīnchē de shòujià bǐ qùnián jiàngdīle bùshǎo.","vi":"Giá bán xe mới đã giảm khá nhiều so với năm ngoái."},{"type":"compound","zh":"如果原材料涨价，产品的售价就会跟着提高。","pinyin":"Rúguǒ yuáncáiliào zhǎngjià, chǎnpǐn de shòujià jiù huì gēnzhe tígāo.","vi":"Nếu nguyên liệu tăng giá thì giá bán sản phẩm cũng sẽ tăng theo."}],"related":[{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"},{"hanzi":"定价","pinyin":"dìngjià","vi":"định giá"},{"hanzi":"成本","pinyin":"chéngběn","vi":"giá thành"},{"hanzi":"出售","pinyin":"chūshòu","vi":"bán ra"}],"traditional":"售價"},{"id":"售票","hanzi":"售票","pinyin":"shòupiào","meaning_vi":"bán vé","explanation":"售 (thụ – bán) + 票 (phiếu – vé) → bán vé; 售票处 là quầy bán vé.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🎫","examples":[{"type":"basic","zh":"售票处在左边。","pinyin":"Shòupiào chùzài zuǒbiān.","vi":"Quầy bán vé ở bên trái."},{"type":"simple","zh":"演唱会明天上午十点开始售票。","pinyin":"Yǎnchànghuì míngtiān shàngwǔ shí diǎn kāishǐ shòupiào.","vi":"Buổi hòa nhạc bắt đầu bán vé lúc 10 giờ sáng mai."},{"type":"compound","zh":"因为网上售票很方便，所以排队买票的人少多了。","pinyin":"Yīnwèi wǎngshàng shòupiào hěn fāngbiàn, suǒyǐ páiduì mǎipiào de rén shǎo duō le.","vi":"Vì bán vé trên mạng rất tiện nên người xếp hàng mua vé ít đi nhiều."}],"related":[{"hanzi":"售票员","pinyin":"shòupiàoyuán","vi":"nhân viên bán vé"},{"hanzi":"买票","pinyin":"mǎipiào","vi":"mua vé"},{"hanzi":"门票","pinyin":"ménpiào","vi":"vé vào cửa"},{"hanzi":"检票","pinyin":"jiǎnpiào","vi":"soát vé"}]},{"id":"授权","hanzi":"授权","pinyin":"shòuquán","meaning_vi":"ủy quyền, cấp phép","explanation":"授 (thụ – trao) + 权 (quyền – quyền lực) → trao quyền cho người khác thay mình làm việc; cấp quyền sử dụng.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔑","examples":[{"type":"basic","zh":"我授权他签字。","pinyin":"Wǒ shòuquán tā qiānzì.","vi":"Tôi ủy quyền cho anh ấy ký tên."},{"type":"simple","zh":"这本书已经获得作者的授权翻译。","pinyin":"Zhè běn shū yǐjīng huòdé zuòzhě de shòuquán fānyì.","vi":"Cuốn sách này đã được tác giả cho phép dịch."},{"type":"compound","zh":"如果没有公司的授权，你就不能使用这个商标。","pinyin":"Rúguǒ méiyǒu gōngsī de shòuquán, nǐ jiù bù néng shǐyòng zhè ge shāngbiāo.","vi":"Nếu không có sự cấp phép của công ty, bạn không được dùng nhãn hiệu này."}],"related":[{"hanzi":"权力","pinyin":"quánlì","vi":"quyền lực"},{"hanzi":"委托","pinyin":"wěituō","vi":"ủy thác"},{"hanzi":"许可","pinyin":"xǔkě","vi":"cho phép"},{"hanzi":"授予","pinyin":"shòuyǔ","vi":"trao tặng"}],"traditional":"授權"},{"id":"书橱","hanzi":"书橱","pinyin":"shūchú","meaning_vi":"tủ sách","explanation":"书 (thư – sách) + 橱 (trù – tủ) → tủ có cánh dùng để đựng sách.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"📚","examples":[{"type":"basic","zh":"书橱里放满了书。","pinyin":"Shūchú lǐ fàng mǎnle shū.","vi":"Trong tủ sách để đầy sách."},{"type":"simple","zh":"爸爸买了一个新书橱放在客厅。","pinyin":"Bàba mǎile yí gè xīn shūchú fàng zài kètīng.","vi":"Bố mua một cái tủ sách mới đặt ở phòng khách."},{"type":"compound","zh":"虽然书橱已经很旧了，但是爷爷舍不得扔掉。","pinyin":"Suīrán shūchú yǐjīng hěn jiù le, dànshì yéye shěbude rēngdiào.","vi":"Tuy tủ sách đã rất cũ, nhưng ông không nỡ vứt đi."}],"related":[{"hanzi":"书架","pinyin":"shūjià","vi":"giá sách"},{"hanzi":"书柜","pinyin":"shūguì","vi":"tủ sách"},{"hanzi":"橱窗","pinyin":"chúchuāng","vi":"tủ kính"},{"hanzi":"衣橱","pinyin":"yīchú","vi":"tủ quần áo"}],"traditional":"書櫥"},{"id":"书写","hanzi":"书写","pinyin":"shūxiě","meaning_vi":"viết, ghi chép","explanation":"书 (thư – viết) + 写 (tả – viết) → viết chữ; mang sắc thái trang trọng, cũng dùng nghĩa bóng 书写历史.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"请用正楷书写。","pinyin":"Qǐng yòng zhèngkǎi shūxiě.","vi":"Xin hãy viết bằng chữ khải ngay ngắn."},{"type":"simple","zh":"他们用汗水书写了新的历史。","pinyin":"Tāmen yòng hànshuǐ shūxiěle xīn de lìshǐ.","vi":"Họ dùng mồ hôi viết nên trang sử mới."},{"type":"compound","zh":"如果书写不清楚，阅卷老师就可能看不懂。","pinyin":"Rúguǒ shūxiě bù qīngchu, yuèjuàn lǎoshī jiù kěnéng kànbùdǒng.","vi":"Nếu viết không rõ ràng, giáo viên chấm bài có thể không đọc được."}],"related":[{"hanzi":"写作","pinyin":"xiězuò","vi":"viết văn"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"抄写","pinyin":"chāoxiě","vi":"chép"},{"hanzi":"笔迹","pinyin":"bǐjì","vi":"nét chữ"}],"traditional":"書寫"},{"id":"梳","hanzi":"梳","pinyin":"shū","meaning_vi":"chải; cái lược","explanation":"梳 (sơ – lược; chải) → dùng lược chải tóc, làm cho tóc gọn gàng.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🪮","examples":[{"type":"basic","zh":"她在梳头发。","pinyin":"Tā zài shū tóufa.","vi":"Cô ấy đang chải tóc."},{"type":"simple","zh":"妈妈每天早上给女儿梳辫子。","pinyin":"Māma měitiān zǎoshang gěi nǚ'ér shū biànzi.","vi":"Mỗi sáng mẹ đều tết tóc cho con gái."},{"type":"compound","zh":"如果头发湿的时候用力梳，就容易掉头发。","pinyin":"Rúguǒ tóufa shī de shíhou yònglì shū, jiù róngyì diào tóufa.","vi":"Nếu chải mạnh khi tóc còn ướt thì dễ rụng tóc."}],"related":[{"hanzi":"梳子","pinyin":"shūzi","vi":"cái lược"},{"hanzi":"梳头","pinyin":"shūtóu","vi":"chải đầu"},{"hanzi":"梳理","pinyin":"shūlǐ","vi":"chải, sắp xếp"},{"hanzi":"辫子","pinyin":"biànzi","vi":"bím tóc"}]},{"id":"梳理","hanzi":"梳理","pinyin":"shūlǐ","meaning_vi":"chải; sắp xếp, hệ thống lại","explanation":"梳 (sơ – chải) + 理 (lý – sắp xếp) → chải cho gọn; nghĩa bóng là sắp xếp, hệ thống hóa suy nghĩ, tài liệu.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🧭","examples":[{"type":"basic","zh":"我们梳理一下思路。","pinyin":"Wǒmen shūlǐ yíxià sīlù.","vi":"Chúng ta sắp xếp lại mạch suy nghĩ một chút."},{"type":"simple","zh":"老师帮我们梳理了这一课的语法。","pinyin":"Lǎoshī bāng wǒmen shūlǐle zhè yí kè de yǔfǎ.","vi":"Thầy giúp chúng tôi hệ thống lại ngữ pháp bài này."},{"type":"compound","zh":"只要把问题梳理清楚，解决办法就出来了。","pinyin":"Zhǐyào bǎ wèntí shūlǐ qīngchu, jiějué bànfǎ jiù chūlái le.","vi":"Chỉ cần sắp xếp vấn đề cho rõ ràng thì cách giải quyết sẽ hiện ra."}],"related":[{"hanzi":"整理","pinyin":"zhěnglǐ","vi":"sắp xếp"},{"hanzi":"梳","pinyin":"shū","vi":"chải"},{"hanzi":"理清","pinyin":"lǐqīng","vi":"làm rõ"},{"hanzi":"归纳","pinyin":"guīnà","vi":"quy nạp, tổng hợp"}]},{"id":"疏散","hanzi":"疏散","pinyin":"shūsàn","meaning_vi":"sơ tán, giải tán","explanation":"疏 (sơ – thưa ra) + 散 (tán – tản ra) → làm cho người, vật tản ra; thường dùng khi sơ tán khẩn cấp.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚨","examples":[{"type":"basic","zh":"大楼里的人被疏散了。","pinyin":"Dàlóu lǐ de rén bèi shūsàn le.","vi":"Người trong tòa nhà đã được sơ tán."},{"type":"simple","zh":"台风来之前，政府疏散了沿海居民。","pinyin":"Táifēng lái zhīqián, zhèngfǔ shūsànle yánhǎi jūmín.","vi":"Trước khi bão đến, chính quyền đã sơ tán cư dân ven biển."},{"type":"compound","zh":"一旦听到火警，大家就要按路线疏散。","pinyin":"Yídàn tīngdào huǒjǐng, dàjiā jiùyào àn lùxiàn shūsàn.","vi":"Một khi nghe báo cháy, mọi người phải sơ tán theo lộ trình."}],"related":[{"hanzi":"撤离","pinyin":"chèlí","vi":"rút lui, sơ tán"},{"hanzi":"分散","pinyin":"fēnsàn","vi":"phân tán"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"},{"hanzi":"转移","pinyin":"zhuǎnyí","vi":"di chuyển"}]},{"id":"输家","hanzi":"输家","pinyin":"shūjiā","meaning_vi":"người thua, kẻ thua cuộc","explanation":"输 (thâu – thua) + 家 (gia – người, bên) → bên thua cuộc; đối lập với 赢家.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"😞","examples":[{"type":"basic","zh":"输家要请客。","pinyin":"Shūjiā yào qǐngkè.","vi":"Người thua phải khao."},{"type":"simple","zh":"这场价格战里没有真正的赢家和输家。","pinyin":"Zhè chǎng jiàgézhàn lǐ méiyǒu zhēnzhèng de yíngjiā hé shūjiā.","vi":"Trong cuộc chiến giá cả này không có kẻ thắng người thua thực sự."},{"type":"compound","zh":"虽然他是这盘棋的输家，但是他学到了很多。","pinyin":"Suīrán tā shì zhè pán qí de shūjiā, dànshì tā xuédàole hěn duō.","vi":"Tuy là người thua ván cờ này, nhưng anh ấy học được rất nhiều."}],"related":[{"hanzi":"赢家","pinyin":"yíngjiā","vi":"người thắng"},{"hanzi":"输","pinyin":"shū","vi":"thua"},{"hanzi":"失败者","pinyin":"shībàizhě","vi":"kẻ thất bại"},{"hanzi":"对手","pinyin":"duìshǒu","vi":"đối thủ"}],"traditional":"輸家"},{"id":"输送","hanzi":"输送","pinyin":"shūsòng","meaning_vi":"vận chuyển, chuyển tải, cung cấp","explanation":"输 (thâu – chuyển) + 送 (tống – đưa) → chuyển đưa (vật chất, năng lượng, nhân tài) từ nơi này đến nơi khác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚚","examples":[{"type":"basic","zh":"管道输送天然气。","pinyin":"Guǎndào shūsòng tiānránqì.","vi":"Đường ống vận chuyển khí thiên nhiên."},{"type":"simple","zh":"心脏把血液输送到全身。","pinyin":"Xīnzàng bǎ xuèyè shūsòng dào quánshēn.","vi":"Tim đưa máu đi khắp cơ thể."},{"type":"compound","zh":"虽然学校规模不大，但是为国家输送了很多人才。","pinyin":"Suīrán xuéxiào guīmó búdà, dànshì wèi guójiā shūsòngle hěn duō réncái.","vi":"Tuy trường không lớn, nhưng đã cung cấp nhiều nhân tài cho đất nước."}],"related":[{"hanzi":"运输","pinyin":"yùnshū","vi":"vận tải"},{"hanzi":"传送","pinyin":"chuánsòng","vi":"truyền tải"},{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"},{"hanzi":"输出","pinyin":"shūchū","vi":"xuất ra"}],"traditional":"輸送"},{"id":"输血","hanzi":"输血","pinyin":"shūxuè","meaning_vi":"truyền máu; (nghĩa bóng) tiếp sức, hỗ trợ","explanation":"输 (thâu – chuyển vào) + 血 (huyết – máu) → truyền máu cho người bệnh; nghĩa bóng là hỗ trợ vốn, sức lực.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩸","examples":[{"type":"basic","zh":"病人需要输血。","pinyin":"Bìngrén xūyào shūxuè.","vi":"Bệnh nhân cần truyền máu."},{"type":"simple","zh":"医生马上给伤员输血。","pinyin":"Yīshēng mǎshàng gěi shāngyuán shūxuè.","vi":"Bác sĩ lập tức truyền máu cho người bị thương."},{"type":"compound","zh":"如果只靠政府输血，企业就永远长不大。","pinyin":"Rúguǒ zhǐ kào zhèngfǔ shūxuè, qǐyè jiù yǒngyuǎn zhǎng búdà.","vi":"Nếu chỉ dựa vào chính phủ tiếp sức, doanh nghiệp sẽ mãi không lớn được."}],"related":[{"hanzi":"献血","pinyin":"xiànxuè","vi":"hiến máu"},{"hanzi":"血型","pinyin":"xuèxíng","vi":"nhóm máu"},{"hanzi":"血液","pinyin":"xuèyè","vi":"máu"},{"hanzi":"输液","pinyin":"shūyè","vi":"truyền dịch"}],"traditional":"輸血"},{"id":"赎","hanzi":"赎","pinyin":"shú","meaning_vi":"chuộc, chuộc lại","explanation":"赎 (thục – chuộc) → dùng tiền, vật để lấy lại người hay đồ đã cầm cố; 赎罪 là chuộc tội.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛓️","examples":[{"type":"basic","zh":"他想赎回手表。","pinyin":"Tā xiǎng shúhuí shǒubiǎo.","vi":"Anh ấy muốn chuộc lại chiếc đồng hồ."},{"type":"simple","zh":"家人凑钱把他从绑匪手里赎了出来。","pinyin":"Jiārén còuqián bǎ tā cóng bǎngfěi shǒulǐ shúle chūlái.","vi":"Gia đình gom tiền chuộc anh ấy ra khỏi tay bọn bắt cóc."},{"type":"compound","zh":"即使做了很多好事，他也觉得赎不了当年的罪。","pinyin":"Jíshǐ zuòle hěn duō hǎoshì, tā yě juéde shú bùliǎo dāngnián de zuì.","vi":"Dù đã làm nhiều việc tốt, ông vẫn thấy không chuộc được tội năm xưa."}],"related":[{"hanzi":"赎罪","pinyin":"shúzuì","vi":"chuộc tội"},{"hanzi":"赎金","pinyin":"shújīn","vi":"tiền chuộc"},{"hanzi":"赎回","pinyin":"shúhuí","vi":"chuộc lại"},{"hanzi":"典当","pinyin":"diǎndàng","vi":"cầm đồ"}],"traditional":"贖"},{"id":"暑期","hanzi":"暑期","pinyin":"shǔqī","meaning_vi":"kỳ nghỉ hè, mùa hè","explanation":"暑 (thử – nắng nóng) + 期 (kỳ – thời kỳ) → thời gian nghỉ hè; hay gặp 暑期班, 暑期工.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"☀️","examples":[{"type":"basic","zh":"暑期我去打工。","pinyin":"Shǔqī wǒqù dǎgōng.","vi":"Kỳ nghỉ hè tôi đi làm thêm."},{"type":"simple","zh":"学校暑期开设了游泳班。","pinyin":"Xuéxiào shǔqī kāishèle yóuyǒng bān.","vi":"Nhà trường mở lớp bơi trong dịp hè."},{"type":"compound","zh":"因为暑期游客太多，所以景区的门票很难买。","pinyin":"Yīnwèi shǔqī yóukè tài duō, suǒyǐ jǐngqū de ménpiào hěn nán mǎi.","vi":"Vì mùa hè khách du lịch quá đông nên rất khó mua vé vào khu du lịch."}],"related":[{"hanzi":"暑假","pinyin":"shǔjià","vi":"nghỉ hè"},{"hanzi":"寒假","pinyin":"hánjià","vi":"nghỉ đông"},{"hanzi":"假期","pinyin":"jiàqī","vi":"kỳ nghỉ"},{"hanzi":"学期","pinyin":"xuéqī","vi":"học kỳ"}]},{"id":"曙光","hanzi":"曙光","pinyin":"shǔguāng","meaning_vi":"ánh bình minh; tia hy vọng","explanation":"曙 (thự – rạng đông) + 光 (quang – ánh sáng) → ánh sáng lúc rạng sáng; nghĩa bóng là tia hy vọng, khởi đầu tốt đẹp.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌅","examples":[{"type":"basic","zh":"东方露出了曙光。","pinyin":"Dōngfāng lùchūle shǔguāng.","vi":"Phía đông đã ló rạng ánh bình minh."},{"type":"simple","zh":"新药的研发让病人看到了曙光。","pinyin":"Xīn yào de yánfā ràng bìngrén kàndàole shǔguāng.","vi":"Việc nghiên cứu thuốc mới cho bệnh nhân thấy tia hy vọng."},{"type":"compound","zh":"虽然困难还很多，但是胜利的曙光已经出现了。","pinyin":"Suīrán kùnnan hái hěn duō, dànshì shènglì de shǔguāng yǐjīng chūxiàn le.","vi":"Tuy còn nhiều khó khăn, nhưng ánh sáng chiến thắng đã xuất hiện."}],"related":[{"hanzi":"黎明","pinyin":"límíng","vi":"bình minh"},{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"},{"hanzi":"晨光","pinyin":"chénguāng","vi":"nắng sớm"},{"hanzi":"阳光","pinyin":"yángguāng","vi":"ánh nắng"}]},{"id":"树木","hanzi":"树木","pinyin":"shùmù","meaning_vi":"cây cối","explanation":"树 (thụ – cây) + 木 (mộc – cây, gỗ) → cây cối nói chung (danh từ tập hợp, không dùng với lượng từ cá thể).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"山上树木很多。","pinyin":"Shān shàng shùmù hěn duō.","vi":"Trên núi có rất nhiều cây cối."},{"type":"simple","zh":"公园里的树木长得非常茂盛。","pinyin":"Gōngyuán lǐ de shùmù zhǎngde fēicháng màoshèng.","vi":"Cây cối trong công viên mọc rất tươi tốt."},{"type":"compound","zh":"如果随便砍伐树木，水土就会流失。","pinyin":"Rúguǒ suíbiàn kǎnfá shùmù, shuǐtǔ jiù huì liúshī.","vi":"Nếu chặt phá cây cối tùy tiện thì đất sẽ bị xói mòn."}],"related":[{"hanzi":"森林","pinyin":"sēnlín","vi":"rừng"},{"hanzi":"植物","pinyin":"zhíwù","vi":"thực vật"},{"hanzi":"木头","pinyin":"mùtou","vi":"gỗ"},{"hanzi":"植树","pinyin":"zhíshù","vi":"trồng cây"}],"traditional":"樹木"},{"id":"树梢","hanzi":"树梢","pinyin":"shùshāo","meaning_vi":"ngọn cây","explanation":"树 (thụ – cây) + 梢 (sao – ngọn, đầu cành) → phần ngọn cao nhất của cây.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"月亮挂在树梢上。","pinyin":"Yuèliang guà zài shùshāo shàng.","vi":"Mặt trăng treo trên ngọn cây."},{"type":"simple","zh":"一只小鸟站在树梢上唱歌。","pinyin":"Yì zhī xiǎoniǎo zhàn zài shùshāo shàng chànggē.","vi":"Một chú chim nhỏ đứng trên ngọn cây hót."},{"type":"compound","zh":"虽然风不大，但是树梢还是轻轻地摇着。","pinyin":"Suīrán fēng búdà, dànshì shùshāo háishì qīngqīng de yáo zhe.","vi":"Tuy gió không lớn, nhưng ngọn cây vẫn khẽ đung đưa."}],"related":[{"hanzi":"树枝","pinyin":"shùzhī","vi":"cành cây"},{"hanzi":"树叶","pinyin":"shùyè","vi":"lá cây"},{"hanzi":"树根","pinyin":"shùgēn","vi":"rễ cây"},{"hanzi":"眉梢","pinyin":"méishāo","vi":"đuôi lông mày"}],"traditional":"樹梢"},{"id":"树荫","hanzi":"树荫","pinyin":"shùyīn","meaning_vi":"bóng cây, bóng râm","explanation":"树 (thụ – cây) + 荫 (âm – bóng râm) → bóng mát dưới tán cây.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"我们在树荫下休息。","pinyin":"Wǒmen zài shùyīn xià xiūxi.","vi":"Chúng tôi nghỉ dưới bóng cây."},{"type":"simple","zh":"老人们喜欢坐在树荫下下棋。","pinyin":"Lǎo rénmen xǐhuan zuò zài shùyīn xià xiàqí.","vi":"Các cụ thích ngồi đánh cờ dưới bóng cây."},{"type":"compound","zh":"因为外面太晒了，所以我们把车停在树荫下。","pinyin":"Yīnwèi wàimiàn tài shài le, suǒyǐ wǒmen bǎ chē tíng zài shùyīn xià.","vi":"Vì bên ngoài nắng quá nên chúng tôi đỗ xe dưới bóng cây."}],"related":[{"hanzi":"阴凉","pinyin":"yīnliáng","vi":"bóng mát"},{"hanzi":"树木","pinyin":"shùmù","vi":"cây cối"},{"hanzi":"遮阳","pinyin":"zhēyáng","vi":"che nắng"},{"hanzi":"绿荫","pinyin":"lǜyīn","vi":"bóng xanh"}],"traditional":"樹蔭"},{"id":"树枝","hanzi":"树枝","pinyin":"shùzhī","meaning_vi":"cành cây","explanation":"树 (thụ – cây) + 枝 (chi – cành) → cành nhánh mọc ra từ thân cây.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"树枝被风吹断了。","pinyin":"Shùzhī bèi fēng chuī duàn le.","vi":"Cành cây bị gió thổi gãy."},{"type":"simple","zh":"孩子们捡树枝来生火。","pinyin":"Háizimen jiǎn shùzhī lái shēnghuǒ.","vi":"Bọn trẻ nhặt cành cây về nhóm lửa."},{"type":"compound","zh":"如果树枝长得太密，就要剪掉一些。","pinyin":"Rúguǒ shùzhī zhǎngde tài mì, jiùyào jiǎndiào yìxiē.","vi":"Nếu cành cây mọc quá dày thì phải tỉa bớt."}],"related":[{"hanzi":"树梢","pinyin":"shùshāo","vi":"ngọn cây"},{"hanzi":"树干","pinyin":"shùgàn","vi":"thân cây"},{"hanzi":"枝叶","pinyin":"zhīyè","vi":"cành lá"},{"hanzi":"树叶","pinyin":"shùyè","vi":"lá cây"}],"traditional":"樹枝"},{"id":"耍赖","hanzi":"耍赖","pinyin":"shuǎlài","meaning_vi":"ăn vạ, chơi xấu, chối bay","explanation":"耍 (sái – giở, bày trò) + 赖 (lại – ăn vạ, chối cãi) → giở thói vô lại: thua không nhận, hứa rồi chối.","hsk_level":"7-9","tags":["dong-tu"],"image":"😜","examples":[{"type":"basic","zh":"你输了别耍赖。","pinyin":"Nǐ shūle bié shuǎlài.","vi":"Thua rồi thì đừng chơi xấu."},{"type":"simple","zh":"孩子一不高兴就躺在地上耍赖。","pinyin":"Háizi yí bù gāoxìng jiù tǎng zài dìshàng shuǎlài.","vi":"Đứa bé hễ không vui là nằm lăn ra đất ăn vạ."},{"type":"compound","zh":"虽然他答应过还钱，但是现在却开始耍赖了。","pinyin":"Suīrán tā dāyingguo huán qián, dànshì xiànzài què kāishǐ shuǎlài le.","vi":"Tuy anh ta từng hứa trả tiền, nhưng giờ lại bắt đầu chối bay."}],"related":[{"hanzi":"赖账","pinyin":"làizhàng","vi":"quỵt nợ"},{"hanzi":"抵赖","pinyin":"dǐlài","vi":"chối cãi"},{"hanzi":"耍花招","pinyin":"shuǎhuāzhāo","vi":"giở trò"},{"hanzi":"无赖","pinyin":"wúlài","vi":"vô lại"}],"traditional":"耍賴"},{"id":"衰减","hanzi":"衰减","pinyin":"shuāijiǎn","meaning_vi":"suy giảm, yếu dần","explanation":"衰 (suy – suy yếu) + 减 (giảm – giảm) → yếu dần và giảm đi; dùng cho tín hiệu, năng lượng, sức lực.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"📉","examples":[{"type":"basic","zh":"信号正在衰减。","pinyin":"Xìnhào zhèngzài shuāijiǎn.","vi":"Tín hiệu đang yếu dần."},{"type":"simple","zh":"随着年龄增长，记忆力会慢慢衰减。","pinyin":"Suízhe niánlíng zēngzhǎng, jìyìlì huì mànmàn shuāijiǎn.","vi":"Tuổi càng cao, trí nhớ sẽ dần suy giảm."},{"type":"compound","zh":"如果距离太远，无线信号就会明显衰减。","pinyin":"Rúguǒ jùlí tài yuǎn, wúxiàn xìnhào jiù huì míngxiǎn shuāijiǎn.","vi":"Nếu khoảng cách quá xa, tín hiệu không dây sẽ suy giảm rõ rệt."}],"related":[{"hanzi":"衰退","pinyin":"shuāituì","vi":"suy thoái"},{"hanzi":"减弱","pinyin":"jiǎnruò","vi":"yếu đi"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"giảm bớt"},{"hanzi":"增强","pinyin":"zēngqiáng","vi":"tăng cường"}],"traditional":"衰減"},{"id":"摔跤","hanzi":"摔跤","pinyin":"shuāijiāo","meaning_vi":"ngã, té; đấu vật","explanation":"摔 (suất – ngã, quật) + 跤 (giao – cú ngã) → bị ngã; cũng chỉ môn đấu vật.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🤼","examples":[{"type":"basic","zh":"他走路摔跤了。","pinyin":"Tā zǒulù shuāijiāo le.","vi":"Anh ấy đi đường bị ngã."},{"type":"simple","zh":"蒙古族的男子很喜欢摔跤比赛。","pinyin":"Ménggǔzú de nánzǐ hěn xǐhuan shuāijiāo bǐsài.","vi":"Đàn ông dân tộc Mông Cổ rất thích thi đấu vật."},{"type":"compound","zh":"因为地上结了冰，所以好几个人都摔跤了。","pinyin":"Yīnwèi dìshàng jiéle bīng, suǒyǐ hǎojǐ gè rén dōu shuāijiāo le.","vi":"Vì mặt đất đóng băng nên khá nhiều người bị ngã."}],"related":[{"hanzi":"摔倒","pinyin":"shuāidǎo","vi":"ngã xuống"},{"hanzi":"跌倒","pinyin":"diēdǎo","vi":"té ngã"},{"hanzi":"角力","pinyin":"juélì","vi":"đọ sức"},{"hanzi":"柔道","pinyin":"róudào","vi":"nhu đạo"}]},{"id":"拴","hanzi":"拴","pinyin":"shuān","meaning_vi":"buộc, cột","explanation":"拴 (xuyên – buộc) → dùng dây buộc, cột người hay vật vào chỗ nào đó.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪢","examples":[{"type":"basic","zh":"把狗拴在门口。","pinyin":"Bǎ gǒu shuān zài ménkǒu.","vi":"Buộc con chó ở cửa."},{"type":"simple","zh":"他把小船拴在岸边的树上。","pinyin":"Tā bǎ xiǎochuán shuān zài ànbiān de shù shàng.","vi":"Anh ấy buộc con thuyền nhỏ vào cái cây bên bờ."},{"type":"compound","zh":"如果不把马拴好，它就会自己跑掉。","pinyin":"Rúguǒ bù bǎ mǎ shuān hǎo, tā jiù huì zìjǐ pǎodiào.","vi":"Nếu không buộc ngựa cẩn thận, nó sẽ tự chạy mất."}],"related":[{"hanzi":"绑","pinyin":"bǎng","vi":"trói"},{"hanzi":"系","pinyin":"jì","vi":"thắt, buộc"},{"hanzi":"捆","pinyin":"kǔn","vi":"bó"},{"hanzi":"绳子","pinyin":"shéngzi","vi":"dây thừng"}]},{"id":"涮","hanzi":"涮","pinyin":"shuàn","meaning_vi":"nhúng (lẩu), tráng rửa; (khẩu ngữ) lừa","explanation":"涮 (xoát – tráng, nhúng) → tráng qua nước; nhúng thịt rau thái mỏng vào nồi nước sôi cho chín (涮羊肉); khẩu ngữ: lừa, cho leo cây.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"冬天爱吃涮羊肉。","pinyin":"Dōngtiān ài chī shuànyángròu.","vi":"Mùa đông thích ăn lẩu nhúng thịt cừu."},{"type":"simple","zh":"用完杯子记得用清水涮一下。","pinyin":"Yòngwán bēizi jìde yòng qīngshuǐ shuàn yíxià.","vi":"Dùng cốc xong nhớ tráng qua nước sạch."},{"type":"compound","zh":"虽然他答应来帮忙，但是最后把我们涮了。","pinyin":"Suīrán tā dāying lái bāngmáng, dànshì zuìhòu bǎ wǒmen shuàn le.","vi":"Tuy anh ta hứa đến giúp, nhưng cuối cùng lại cho chúng tôi leo cây."}],"related":[{"hanzi":"火锅","pinyin":"huǒguō","vi":"lẩu"},{"hanzi":"涮羊肉","pinyin":"shuànyángròu","vi":"lẩu thịt cừu"},{"hanzi":"冲洗","pinyin":"chōngxǐ","vi":"xả rửa"},{"hanzi":"烫","pinyin":"tàng","vi":"chần, nhúng nước sôi"}]},{"id":"双向","hanzi":"双向","pinyin":"shuāngxiàng","meaning_vi":"hai chiều, song phương","explanation":"双 (song – đôi, hai) + 向 (hướng – hướng) → theo cả hai hướng, có tác động qua lại.","hsk_level":"7-9","tags":["tinh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"这是双向车道。","pinyin":"Zhè shì shuāngxiàng chēdào.","vi":"Đây là làn đường hai chiều."},{"type":"simple","zh":"沟通应该是双向的，不能只说不听。","pinyin":"Gōutōng yīnggāi shì shuāngxiàng de, bù néng zhǐ shuō bù tīng.","vi":"Giao tiếp phải là hai chiều, không thể chỉ nói mà không nghe."},{"type":"compound","zh":"只要是双向选择，双方就都能找到合适的人。","pinyin":"Zhǐ yàoshì shuāngxiàng xuǎnzé, shuāngfāng jiù dōu néng zhǎodào héshì de rén.","vi":"Chỉ cần là lựa chọn hai chiều, cả hai bên đều tìm được người phù hợp."}],"related":[{"hanzi":"单向","pinyin":"dānxiàng","vi":"một chiều"},{"hanzi":"双方","pinyin":"shuāngfāng","vi":"hai bên"},{"hanzi":"互动","pinyin":"hùdòng","vi":"tương tác"},{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"}],"traditional":"雙向"},{"id":"双重","hanzi":"双重","pinyin":"shuāngchóng","meaning_vi":"hai lớp, kép, song trùng","explanation":"双 (song – đôi) + 重 (trùng – lớp, lặp lại) → gồm hai tầng, hai mặt; như 双重身份, 双重标准.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔂","examples":[{"type":"basic","zh":"他有双重国籍。","pinyin":"Tā yǒu shuāngchóng guójí.","vi":"Anh ấy có hai quốc tịch."},{"type":"simple","zh":"这种做法是典型的双重标准。","pinyin":"Zhè zhǒng zuòfǎ shì diǎnxíng de shuāngchóng biāozhǔn.","vi":"Cách làm này là tiêu chuẩn kép điển hình."},{"type":"compound","zh":"因为她既是老师又是妈妈，所以承受着双重压力。","pinyin":"Yīnwèi tā jìshì lǎoshī yòu shì māma, suǒyǐ chéngshòuzhe shuāngchóng yālì.","vi":"Vì vừa là giáo viên vừa là mẹ nên cô ấy chịu áp lực kép."}],"related":[{"hanzi":"重复","pinyin":"chóngfù","vi":"lặp lại"},{"hanzi":"双倍","pinyin":"shuāngbèi","vi":"gấp đôi"},{"hanzi":"多重","pinyin":"duōchóng","vi":"nhiều lớp"},{"hanzi":"双方","pinyin":"shuāngfāng","vi":"hai bên"}],"traditional":"雙重"},{"id":"霜","hanzi":"霜","pinyin":"shuāng","meaning_vi":"sương muối; kem (bôi da); lớp bột trắng","explanation":"霜 (sương – sương muối) → hơi nước đông thành tinh thể trắng trên mặt vật khi trời lạnh; cũng chỉ kem dưỡng da (面霜).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"❄️","examples":[{"type":"basic","zh":"今早地上有霜。","pinyin":"Jīnzǎo dìshàng yǒu shuāng.","vi":"Sáng nay trên mặt đất có sương muối."},{"type":"simple","zh":"冬天出门前，她总要擦一点面霜。","pinyin":"Dōngtiān chū ménqián, tā zǒngyào cā yìdiǎn miànshuāng.","vi":"Mùa đông trước khi ra ngoài, cô ấy luôn thoa chút kem dưỡng da."},{"type":"compound","zh":"如果夜里下了霜，第二天菜叶就会冻坏。","pinyin":"Rúguǒ yèlǐ xiàle shuāng, dì'èrtiān cài yè jiù huì dòng huài.","vi":"Nếu đêm xuống sương muối thì hôm sau lá rau sẽ bị hỏng vì lạnh."}],"related":[{"hanzi":"冰霜","pinyin":"bīngshuāng","vi":"băng sương"},{"hanzi":"雪","pinyin":"xuě","vi":"tuyết"},{"hanzi":"面霜","pinyin":"miànshuāng","vi":"kem dưỡng mặt"},{"hanzi":"霜冻","pinyin":"shuāngdòng","vi":"sương giá"}]},{"id":"谁知道","hanzi":"谁知道","pinyin":"shéizhīdào","meaning_vi":"ai mà biết, ai ngờ","explanation":"谁 (thùy – ai) + 知道 (tri đạo – biết) → 'ai mà biết được'; dùng để biểu thị không biết hoặc diễn biến bất ngờ ngoài dự đoán.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🤷","examples":[{"type":"basic","zh":"谁知道他去哪儿了？","pinyin":"Shéizhīdào tā qùnǎr le?","vi":"Ai mà biết anh ta đi đâu rồi?"},{"type":"simple","zh":"我以为他会来，谁知道他根本没出现。","pinyin":"Wǒ yǐwéi tā huì lái, shéizhīdào tā gēnběn méi chūxiàn.","vi":"Tôi tưởng anh ấy sẽ đến, ai ngờ anh ấy chẳng hề xuất hiện."},{"type":"compound","zh":"本来天气很好，谁知道一出门就下起了大雨，所以我们只好回家。","pinyin":"Běnlái tiānqì hěn hǎo, shéizhīdào yì chūmén jiù xià qǐle dàyǔ, suǒyǐ wǒmen zhǐhǎo huíjiā.","vi":"Vốn dĩ trời rất đẹp, ai ngờ vừa ra khỏi nhà đã mưa to, nên chúng tôi đành về nhà."}],"related":[{"hanzi":"没想到","pinyin":"méixiǎngdào","vi":"không ngờ"},{"hanzi":"谁料","pinyin":"shéiliào","vi":"ai ngờ"},{"hanzi":"天知道","pinyin":"tiānzhīdào","vi":"có trời mới biết"},{"hanzi":"不料","pinyin":"búliào","vi":"không ngờ"}],"traditional":"誰知道"},{"id":"水槽","hanzi":"水槽","pinyin":"shuǐcáo","meaning_vi":"bồn rửa, máng nước","explanation":"水 (thủy – nước) + 槽 (tào – máng) → máng/bồn chứa nước, nhất là bồn rửa trong bếp.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🚰","examples":[{"type":"basic","zh":"碗放在水槽里。","pinyin":"Wǎn fàng zài shuǐcáo lǐ.","vi":"Bát để trong bồn rửa."},{"type":"simple","zh":"厨房的水槽又被堵住了。","pinyin":"Chúfáng de shuǐcáo yòu bèi dǔzhù le.","vi":"Bồn rửa trong bếp lại bị tắc rồi."},{"type":"compound","zh":"如果水槽里堆满脏碗，厨房就会有异味。","pinyin":"Rúguǒ shuǐcáo lǐ duīmǎn zāng wǎn, chúfáng jiù huì yǒu yìwèi.","vi":"Nếu bồn rửa chất đầy bát bẩn, nhà bếp sẽ có mùi lạ."}],"related":[{"hanzi":"水池","pinyin":"shuǐchí","vi":"bồn nước"},{"hanzi":"水龙头","pinyin":"shuǐlóngtóu","vi":"vòi nước"},{"hanzi":"下水道","pinyin":"xiàshuǐdào","vi":"cống thoát nước"},{"hanzi":"洗碗","pinyin":"xǐwǎn","vi":"rửa bát"}]},{"id":"水稻","hanzi":"水稻","pinyin":"shuǐdào","meaning_vi":"lúa nước","explanation":"水 (thủy – nước) + 稻 (đạo – lúa) → cây lúa trồng ở ruộng ngập nước.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"这里种水稻。","pinyin":"Zhèlǐ zhòng shuǐdào.","vi":"Ở đây trồng lúa nước."},{"type":"simple","zh":"越南南方一年能种三季水稻。","pinyin":"Yuènán nánfāng yì nián néng zhòng sān jì shuǐdào.","vi":"Miền Nam Việt Nam mỗi năm trồng được ba vụ lúa."},{"type":"compound","zh":"因为今年雨水充足，所以水稻长得特别好。","pinyin":"Yīnwèi jīnnián yǔshuǐ chōngzú, suǒyǐ shuǐdào zhǎngde tèbié hǎo.","vi":"Vì năm nay mưa nhiều nên lúa phát triển rất tốt."}],"related":[{"hanzi":"稻田","pinyin":"dàotián","vi":"ruộng lúa"},{"hanzi":"大米","pinyin":"dàmǐ","vi":"gạo"},{"hanzi":"小麦","pinyin":"xiǎomài","vi":"lúa mì"},{"hanzi":"农作物","pinyin":"nóngzuòwù","vi":"cây trồng"}]},{"id":"水管","hanzi":"水管","pinyin":"shuǐguǎn","meaning_vi":"ống nước","explanation":"水 (thủy – nước) + 管 (quản – ống) → ống dẫn nước.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🚿","examples":[{"type":"basic","zh":"水管漏水了。","pinyin":"Shuǐguǎn lòushuǐ le.","vi":"Ống nước bị rò rồi."},{"type":"simple","zh":"冬天太冷，水管都冻裂了。","pinyin":"Dōngtiān tài lěng, shuǐguǎn dōu dòng liè le.","vi":"Mùa đông lạnh quá, ống nước bị đóng băng nứt cả."},{"type":"compound","zh":"如果水管坏了，你就关掉总阀门再找人修。","pinyin":"Rúguǒ shuǐguǎn huàile, nǐ jiù guāndiào zǒng fámén zài zhǎo rén xiū.","vi":"Nếu ống nước hỏng, bạn khóa van tổng rồi gọi người sửa."}],"related":[{"hanzi":"水龙头","pinyin":"shuǐlóngtóu","vi":"vòi nước"},{"hanzi":"管道","pinyin":"guǎndào","vi":"đường ống"},{"hanzi":"水槽","pinyin":"shuǐcáo","vi":"bồn rửa"},{"hanzi":"水管工","pinyin":"shuǐguǎngōng","vi":"thợ sửa ống nước"}]},{"id":"水壶","hanzi":"水壶","pinyin":"shuǐhú","meaning_vi":"ấm nước, bình nước, bình tưới","explanation":"水 (thủy – nước) + 壶 (hồ – ấm, bình) → ấm đun nước, bình đựng nước mang theo hoặc bình tưới cây.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🫖","examples":[{"type":"basic","zh":"水壶里没水了。","pinyin":"Shuǐhú lǐ méi shuǐ le.","vi":"Trong ấm hết nước rồi."},{"type":"simple","zh":"爬山时别忘了带上水壶。","pinyin":"Páshān shí bié wàngle dàishàng shuǐhú.","vi":"Khi leo núi đừng quên mang theo bình nước."},{"type":"compound","zh":"如果水壶里有水垢，烧出来的水就不好喝。","pinyin":"Rúguǒ shuǐhú lǐ yǒu shuǐgòu, shāo chūlái de shuǐ jiù bù hǎohē.","vi":"Nếu trong ấm có cặn, nước đun ra sẽ không ngon."}],"related":[{"hanzi":"茶壶","pinyin":"cháhú","vi":"ấm trà"},{"hanzi":"保温杯","pinyin":"bǎowēnbēi","vi":"bình giữ nhiệt"},{"hanzi":"烧水","pinyin":"shāoshuǐ","vi":"đun nước"},{"hanzi":"热水瓶","pinyin":"rèshuǐpíng","vi":"phích nước"}],"traditional":"水壺"},{"id":"水货","hanzi":"水货","pinyin":"shuǐhuò","meaning_vi":"hàng xách tay, hàng nhập lậu","explanation":"水 (thủy – đường thủy) + 货 (hóa – hàng) → hàng nhập không qua kênh chính thức (vốn chở lậu theo đường thủy); khẩu ngữ còn chỉ đồ dỏm.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"📦","examples":[{"type":"basic","zh":"这部手机是水货。","pinyin":"Zhè bù shǒujī shì shuǐhuò.","vi":"Chiếc điện thoại này là hàng xách tay."},{"type":"simple","zh":"水货虽然便宜，但没有保修。","pinyin":"Shuǐhuò suīrán piányi, dàn méiyǒu bǎoxiū.","vi":"Hàng xách tay tuy rẻ nhưng không có bảo hành."},{"type":"compound","zh":"如果买到水货，出了问题就很难维修。","pinyin":"Rúguǒ mǎi dào shuǐhuò, chūle wèntí jiù hěn nán wéixiū.","vi":"Nếu mua phải hàng nhập lậu, khi hỏng sẽ rất khó sửa."}],"related":[{"hanzi":"行货","pinyin":"hánghuò","vi":"hàng chính hãng"},{"hanzi":"走私","pinyin":"zǒusī","vi":"buôn lậu"},{"hanzi":"假货","pinyin":"jiǎhuò","vi":"hàng giả"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng thật"}],"traditional":"水貨"},{"id":"水晶","hanzi":"水晶","pinyin":"shuǐjīng","meaning_vi":"pha lê, thạch anh","explanation":"水 (thủy – nước) + 晶 (tinh – trong suốt, tinh thể) → khoáng vật trong như nước, tức thạch anh, pha lê.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"💎","examples":[{"type":"basic","zh":"她戴着水晶项链。","pinyin":"Tā dàizhe shuǐjīng xiàngliàn.","vi":"Cô ấy đeo dây chuyền pha lê."},{"type":"simple","zh":"客厅里挂着一盏漂亮的水晶灯。","pinyin":"Kètīng lǐ guàzhe yì zhǎn piàoliang de shuǐjīng dēng.","vi":"Trong phòng khách treo một chiếc đèn pha lê rất đẹp."},{"type":"compound","zh":"虽然这块水晶不大，但是非常透明。","pinyin":"Suīrán zhè kuài shuǐjīng búdà, dànshì fēicháng tòumíng.","vi":"Tuy viên pha lê này không lớn, nhưng rất trong suốt."}],"related":[{"hanzi":"玻璃","pinyin":"bōli","vi":"thủy tinh"},{"hanzi":"钻石","pinyin":"zuànshí","vi":"kim cương"},{"hanzi":"宝石","pinyin":"bǎoshí","vi":"đá quý"},{"hanzi":"晶莹","pinyin":"jīngyíng","vi":"óng ánh"}]},{"id":"水灵灵","hanzi":"水灵灵","pinyin":"shuǐlínglíng","meaning_vi":"tươi rói, mơn mởn, long lanh","explanation":"水灵 (thủy linh – tươi tắn, mọng nước) + 灵 lặp → rất tươi, mọng nước; tả rau quả tươi hoặc đôi mắt, gương mặt xinh tươi.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥬","examples":[{"type":"basic","zh":"这些青菜水灵灵的。","pinyin":"Zhèxiē qīngcài shuǐlínglíng de.","vi":"Rau xanh này tươi rói."},{"type":"simple","zh":"小姑娘有一双水灵灵的大眼睛。","pinyin":"Xiǎo gūniang yǒu yì shuāng shuǐlínglíng de dà yǎnjing.","vi":"Cô bé có đôi mắt to long lanh."},{"type":"compound","zh":"因为刚从地里摘下来，所以这些黄瓜水灵灵的。","pinyin":"Yīnwèi gāng cóng dì lǐ zhāi xiàlái, suǒyǐ zhèxiē huángguā shuǐlínglíng de.","vi":"Vì vừa hái từ ruộng về nên mấy quả dưa chuột này tươi mơn mởn."}],"related":[{"hanzi":"水灵","pinyin":"shuǐling","vi":"tươi tắn"},{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"tươi"},{"hanzi":"鲜嫩","pinyin":"xiānnèn","vi":"tươi non"},{"hanzi":"亮晶晶","pinyin":"liàngjīngjīng","vi":"lấp lánh"}],"traditional":"水靈靈"},{"id":"水面","hanzi":"水面","pinyin":"shuǐmiàn","meaning_vi":"mặt nước","explanation":"水 (thủy – nước) + 面 (diện – mặt) → bề mặt của nước.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"水面很平静。","pinyin":"Shuǐmiàn hěn píngjìng.","vi":"Mặt nước rất phẳng lặng."},{"type":"simple","zh":"几片树叶漂在水面上。","pinyin":"Jǐ piàn shùyè piāo zài shuǐmiàn shàng.","vi":"Mấy chiếc lá trôi trên mặt nước."},{"type":"compound","zh":"如果水面结了厚冰，孩子们就可以在上面滑冰。","pinyin":"Rúguǒ shuǐmiàn jiéle hòu bīng, háizimen jiù kěyǐ zài shàngmiàn huábīng.","vi":"Nếu mặt nước đóng băng dày, bọn trẻ có thể trượt băng trên đó."}],"related":[{"hanzi":"海面","pinyin":"hǎimiàn","vi":"mặt biển"},{"hanzi":"湖面","pinyin":"húmiàn","vi":"mặt hồ"},{"hanzi":"水平面","pinyin":"shuǐpíngmiàn","vi":"mặt phẳng nằm ngang"},{"hanzi":"倒影","pinyin":"dàoyǐng","vi":"bóng phản chiếu"}]},{"id":"水手","hanzi":"水手","pinyin":"shuǐshǒu","meaning_vi":"thủy thủ","explanation":"水 (thủy – nước) + 手 (thủ – người làm nghề) → người làm việc trên tàu thuyền.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"⚓","examples":[{"type":"basic","zh":"他当过水手。","pinyin":"Tā dāngguo shuǐshǒu.","vi":"Anh ấy từng làm thủy thủ."},{"type":"simple","zh":"水手们在甲板上收帆。","pinyin":"Shuǐshǒumen zài jiǎbǎn shàng shōu fān.","vi":"Các thủy thủ đang thu buồm trên boong tàu."},{"type":"compound","zh":"虽然水手的工作很辛苦，但是能看遍世界的海港。","pinyin":"Suīrán shuǐshǒu de gōngzuò hěn xīnkǔ, dànshì néng kàn biàn shìjiè de hǎigǎng.","vi":"Tuy công việc thủy thủ rất vất vả, nhưng được ngắm khắp các cảng biển thế giới."}],"related":[{"hanzi":"船长","pinyin":"chuánzhǎng","vi":"thuyền trưởng"},{"hanzi":"海员","pinyin":"hǎiyuán","vi":"thuyền viên"},{"hanzi":"船员","pinyin":"chuányuán","vi":"thủy thủ đoàn"},{"hanzi":"航海","pinyin":"hánghǎi","vi":"hàng hải"}]},{"id":"水温","hanzi":"水温","pinyin":"shuǐwēn","meaning_vi":"nhiệt độ nước","explanation":"水 (thủy – nước) + 温 (ôn – nhiệt độ) → độ nóng lạnh của nước.","hsk_level":"7-9","tags":["danh-tu"],"image":"🌡️","examples":[{"type":"basic","zh":"水温刚刚好。","pinyin":"Shuǐwēn gāng gānghǎo.","vi":"Nhiệt độ nước vừa đúng."},{"type":"simple","zh":"泡茶的水温不能太高。","pinyin":"Pàochá de shuǐwēn bù néng tài gāo.","vi":"Nước pha trà không được quá nóng."},{"type":"compound","zh":"如果海水水温太低，我们就不下去游泳了。","pinyin":"Rúguǒ hǎishuǐ shuǐwēn tài dī, wǒmen jiù bú xiàqù yóuyǒng le.","vi":"Nếu nước biển quá lạnh thì chúng tôi sẽ không xuống bơi nữa."}],"related":[{"hanzi":"温度","pinyin":"wēndù","vi":"nhiệt độ"},{"hanzi":"气温","pinyin":"qìwēn","vi":"nhiệt độ không khí"},{"hanzi":"体温","pinyin":"tǐwēn","vi":"thân nhiệt"},{"hanzi":"水温计","pinyin":"shuǐwēnjì","vi":"nhiệt kế nước"}],"traditional":"水溫"},{"id":"水域","hanzi":"水域","pinyin":"Shuǐyù","meaning_vi":"vùng nước, hải phận","explanation":"水 (thủy – nước) + 域 (vực – vùng, khu vực) → khu vực mặt nước nhất định (sông, hồ, biển).","hsk_level":"7-9","tags":["danh-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"这片水域很深。","pinyin":"Zhè piàn Shuǐyù hěn shēn.","vi":"Vùng nước này rất sâu."},{"type":"simple","zh":"渔船不能进入别国的水域。","pinyin":"Yúchuán bù néng jìnrù bié guó de Shuǐyù.","vi":"Tàu cá không được đi vào vùng biển của nước khác."},{"type":"compound","zh":"因为这片水域有暗流，所以禁止游泳。","pinyin":"Yīnwèi zhè piàn Shuǐyù yǒu ànliú, suǒyǐ jìnzhǐ yóuyǒng.","vi":"Vì vùng nước này có dòng chảy ngầm nên cấm bơi."}],"related":[{"hanzi":"海域","pinyin":"Hǎiyù","vi":"vùng biển"},{"hanzi":"领域","pinyin":"lǐngyù","vi":"lĩnh vực"},{"hanzi":"流域","pinyin":"liúyù","vi":"lưu vực"},{"hanzi":"区域","pinyin":"qūyù","vi":"khu vực"}]},{"id":"水源","hanzi":"水源","pinyin":"shuǐyuán","meaning_vi":"nguồn nước","explanation":"水 (thủy – nước) + 源 (nguyên – nguồn) → nơi bắt nguồn nước, nguồn cung cấp nước.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"要保护水源。","pinyin":"Yào bǎohù shuǐyuán.","vi":"Phải bảo vệ nguồn nước."},{"type":"simple","zh":"这条河是全城的主要水源。","pinyin":"Zhè tiáo hé shì quánchéng de zhǔyào shuǐyuán.","vi":"Con sông này là nguồn nước chính của cả thành phố."},{"type":"compound","zh":"一旦水源被污染，附近居民就没有干净的水喝了。","pinyin":"Yídàn shuǐyuán bèi wūrǎn, fùjìn jūmín jiù méiyǒu gānjìng de shuǐ hē le.","vi":"Một khi nguồn nước bị ô nhiễm, cư dân gần đó sẽ không có nước sạch để uống."}],"related":[{"hanzi":"源头","pinyin":"yuántóu","vi":"đầu nguồn"},{"hanzi":"水资源","pinyin":"shuǐzīyuán","vi":"tài nguyên nước"},{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"饮用水","pinyin":"yǐnyòngshuǐ","vi":"nước uống"}]},{"id":"水涨船高","hanzi":"水涨船高","pinyin":"shuǐzhǎng-chuángāo","meaning_vi":"nước lên thuyền lên; tăng theo (khi điều kiện chung tăng)","explanation":"水涨 (thủy trướng – nước dâng) + 船高 (thuyền cao – thuyền nổi cao) → nghĩa đen nước dâng thì thuyền nổi; nghĩa bóng sự vật thay đổi, tăng lên theo hoàn cảnh chung.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⛵","examples":[{"type":"basic","zh":"房价水涨船高。","pinyin":"Fángjià shuǐzhǎngchuángāo.","vi":"Giá nhà cũng tăng theo."},{"type":"simple","zh":"经济发展了，工资也水涨船高。","pinyin":"Jīngjì fāzhǎn le, gōngzī yě shuǐzhǎngchuángāo.","vi":"Kinh tế phát triển, lương cũng tăng theo."},{"type":"compound","zh":"因为这位歌手越来越红，所以演出费也水涨船高。","pinyin":"Yīnwèi zhè wèi gēshǒu yuèláiyuè hóng, suǒyǐ yǎnchū fèi yě shuǐzhǎngchuángāo.","vi":"Vì ca sĩ này ngày càng nổi tiếng nên cát-xê cũng tăng theo."}],"related":[{"hanzi":"随之","pinyin":"suízhī","vi":"theo đó"},{"hanzi":"上涨","pinyin":"shàngzhǎng","vi":"tăng lên"},{"hanzi":"顺势","pinyin":"shùnshì","vi":"thuận theo thế"},{"hanzi":"水落石出","pinyin":"shuǐluòshíchū","vi":"cháy nhà ra mặt chuột"}],"traditional":"水漲船高"},{"id":"睡袋","hanzi":"睡袋","pinyin":"shuìdài","meaning_vi":"túi ngủ","explanation":"睡 (thụy – ngủ) + 袋 (đại – túi) → túi dùng để chui vào ngủ khi cắm trại, leo núi.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🏕️","examples":[{"type":"basic","zh":"我带了一个睡袋。","pinyin":"Wǒ dàile yí gè shuìdài.","vi":"Tôi mang theo một chiếc túi ngủ."},{"type":"simple","zh":"晚上山上很冷，最好带厚睡袋。","pinyin":"Wǎnshang shān shàng hěn lěng, zuìhǎo dài hòu shuìdài.","vi":"Buổi tối trên núi rất lạnh, tốt nhất nên mang túi ngủ dày."},{"type":"compound","zh":"虽然睡袋很暖和，但是我在帐篷里还是睡不着。","pinyin":"Suīrán shuìdài hěn nuǎnhuo, dànshì wǒ zài zhàngpeng lǐ háishì shuìbuzháo.","vi":"Tuy túi ngủ rất ấm, nhưng nằm trong lều tôi vẫn không ngủ được."}],"related":[{"hanzi":"帐篷","pinyin":"zhàngpeng","vi":"lều"},{"hanzi":"露营","pinyin":"lùyíng","vi":"cắm trại"},{"hanzi":"背包","pinyin":"bēibāo","vi":"ba lô"},{"hanzi":"被子","pinyin":"bèizi","vi":"chăn"}]},{"id":"顺路","hanzi":"顺路","pinyin":"shùnlù","meaning_vi":"tiện đường, thuận đường","explanation":"顺 (thuận – thuận theo) + 路 (lộ – đường) → nhân tiện trên đường đi làm luôn việc khác.","hsk_level":"7-9","tags":["pho-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"我顺路送你回家。","pinyin":"Wǒ shùnlù sòng nǐ huíjiā.","vi":"Tôi tiện đường đưa bạn về nhà."},{"type":"simple","zh":"下班时我顺路去超市买了点菜。","pinyin":"Xiàbān shí wǒ shùnlù qù chāoshì mǎile diǎncài.","vi":"Lúc tan làm tôi tiện đường ghé siêu thị mua ít rau."},{"type":"compound","zh":"如果你明天顺路，就帮我把这封信寄了吧。","pinyin":"Rúguǒ nǐ míngtiān shùnlù, jiù bāng wǒ bǎ zhè fēng xìn jìle ba.","vi":"Nếu mai bạn tiện đường thì gửi giúp tôi lá thư này nhé."}],"related":[{"hanzi":"顺便","pinyin":"shùnbiàn","vi":"nhân tiện"},{"hanzi":"顺手","pinyin":"shùnshǒu","vi":"tiện tay"},{"hanzi":"绕路","pinyin":"ràolù","vi":"đi vòng"},{"hanzi":"路过","pinyin":"lùguò","vi":"đi ngang qua"}],"traditional":"順路"},{"id":"顺势","hanzi":"顺势","pinyin":"shùnshì","meaning_vi":"thuận thế, nhân đà, tiện thể","explanation":"顺 (thuận – thuận theo) + 势 (thế – xu thế, đà) → nương theo đà, xu thế mà làm; tranh thủ cơ hội.","hsk_level":"7-9","tags":["pho-tu"],"image":"🏄","examples":[{"type":"basic","zh":"他顺势坐了下来。","pinyin":"Tā shùnshì zuòle xiàlái.","vi":"Anh ấy nhân đà ngồi xuống luôn."},{"type":"simple","zh":"对手一推，他顺势倒在了地上。","pinyin":"Duìshǒu yì tuī, tā shùnshì dǎo zài le dìshàng.","vi":"Đối thủ vừa đẩy, anh ấy liền thuận đà ngã xuống đất."},{"type":"compound","zh":"既然市场需求很大，我们就应该顺势扩大生产。","pinyin":"Jìrán shìchǎng xūqiú hěn dà, wǒmen jiù yīnggāi shùnshì kuòdà shēngchǎn.","vi":"Nếu nhu cầu thị trường đã lớn thì chúng ta nên nhân đà mở rộng sản xuất."}],"related":[{"hanzi":"趁机","pinyin":"chènjī","vi":"nhân cơ hội"},{"hanzi":"顺手","pinyin":"shùnshǒu","vi":"tiện tay"},{"hanzi":"顺应","pinyin":"shùnyìng","vi":"thuận theo"},{"hanzi":"形势","pinyin":"xíngshì","vi":"tình thế"}],"traditional":"順勢"},{"id":"顺手","hanzi":"顺手","pinyin":"shùnshǒu","meaning_vi":"tiện tay; thuận tay, trôi chảy","explanation":"顺 (thuận – thuận) + 手 (thủ – tay) → tiện tay làm luôn; cũng là tính từ: dùng thuận tay, công việc suôn sẻ.","hsk_level":"7-9","tags":["pho-tu"],"image":"🤲","examples":[{"type":"basic","zh":"出门请顺手关灯。","pinyin":"Chūmén qǐng shùnshǒu guān dēng.","vi":"Ra ngoài nhớ tiện tay tắt đèn."},{"type":"simple","zh":"这把新剪刀用起来很顺手。","pinyin":"Zhè bǎ xīn jiǎndāo yòng qǐlái hěn shùnshǒu.","vi":"Cây kéo mới này dùng rất thuận tay."},{"type":"compound","zh":"虽然开始不太顺手，但是练了几天就熟练了。","pinyin":"Suīrán kāishǐ bú tài shùnshǒu, dànshì liànle jǐtiān jiù shúliàn le.","vi":"Tuy lúc đầu chưa thuận tay lắm, nhưng luyện vài ngày là thạo."}],"related":[{"hanzi":"顺便","pinyin":"shùnbiàn","vi":"nhân tiện"},{"hanzi":"随手","pinyin":"suíshǒu","vi":"tiện tay"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"thuận lợi"},{"hanzi":"顺路","pinyin":"shùnlù","vi":"tiện đường"}],"traditional":"順手"},{"id":"顺心","hanzi":"顺心","pinyin":"shùnxīn","meaning_vi":"vừa ý, như ý, thuận lòng","explanation":"顺 (thuận – thuận) + 心 (tâm – lòng) → mọi việc hợp lòng mình, vừa ý.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😊","examples":[{"type":"basic","zh":"祝你事事顺心！","pinyin":"Zhù nǐ shìshì shùnxīn!","vi":"Chúc bạn vạn sự như ý!"},{"type":"simple","zh":"最近工作不太顺心，他心情很差。","pinyin":"Zuìjìn gōngzuò bú tài shùnxīn, tā xīnqíng hěn chà.","vi":"Gần đây công việc không vừa ý nên tâm trạng anh ấy rất tệ."},{"type":"compound","zh":"即使生活不顺心，也不要把气撒在家人身上。","pinyin":"Jíshǐ shēnghuó bú shùnxīn, yě bú yào bǎ qì sǎ zài jiārén shēnshàng.","vi":"Dù cuộc sống không như ý, cũng đừng trút giận lên người nhà."}],"related":[{"hanzi":"如意","pinyin":"rúyì","vi":"như ý"},{"hanzi":"遂心","pinyin":"suìxīn","vi":"vừa lòng"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"thuận lợi"},{"hanzi":"称心","pinyin":"chènxīn","vi":"hài lòng"}],"traditional":"順心"},{"id":"顺着","hanzi":"顺着","pinyin":"shùnzhe","meaning_vi":"theo, dọc theo, chiều theo","explanation":"顺 (thuận – theo) + 着 (trợ từ) → men theo, dọc theo một hướng; cũng có nghĩa chiều theo ý ai.","hsk_level":"7-9","tags":["gioi-tu"],"image":"➡️","examples":[{"type":"basic","zh":"顺着这条路走。","pinyin":"Shùnzhe zhè tiáo lù zǒu.","vi":"Đi theo con đường này."},{"type":"simple","zh":"眼泪顺着她的脸流了下来。","pinyin":"Yǎnlèi shùnzhe tā de liǎn liúle xiàlái.","vi":"Nước mắt lăn dài trên má cô ấy."},{"type":"compound","zh":"如果你总是顺着孩子，他就会越来越任性。","pinyin":"Rúguǒ nǐ zǒngshì shùnzhe háizi, tā jiù huì yuèláiyuè rènxìng.","vi":"Nếu bạn lúc nào cũng chiều theo con, nó sẽ ngày càng bướng bỉnh."}],"related":[{"hanzi":"沿着","pinyin":"yánzhe","vi":"dọc theo"},{"hanzi":"随着","pinyin":"suízhe","vi":"theo"},{"hanzi":"顺从","pinyin":"shùncóng","vi":"vâng theo"},{"hanzi":"朝着","pinyin":"cháozhe","vi":"hướng về"}],"traditional":"順著"},{"id":"说白了","hanzi":"说白了","pinyin":"shuōbáile","meaning_vi":"nói trắng ra, nói thẳng ra","explanation":"说 (thuyết – nói) + 白 (bạch – rõ ràng, trắng) + 了 → nói cho rõ, nói trắng ra; dùng để tóm lại bản chất vấn đề.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"说白了，他就是懒。","pinyin":"Shuōbáile, tā jiùshì lǎn.","vi":"Nói trắng ra, anh ta chỉ là lười."},{"type":"simple","zh":"说白了，这个计划就是为了省钱。","pinyin":"Shuōbáile, zhè ge jìhuà jiùshì wèile shěngqián.","vi":"Nói thẳng ra, kế hoạch này chỉ để tiết kiệm tiền."},{"type":"compound","zh":"虽然他讲了半天，但是说白了就是不想帮忙。","pinyin":"Suīrán tā jiǎngle bàn tiān, dànshì shuōbáile jiùshì bù xiǎng bāngmáng.","vi":"Tuy anh ta nói cả buổi, nhưng nói trắng ra là không muốn giúp."}],"related":[{"hanzi":"说到底","pinyin":"shuōdàodǐ","vi":"suy cho cùng"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thẳng thắn"},{"hanzi":"直说","pinyin":"zhíshuō","vi":"nói thẳng"},{"hanzi":"明白","pinyin":"míngbai","vi":"rõ ràng"}],"traditional":"說白了"},{"id":"说不上","hanzi":"说不上","pinyin":"shuōbushàng","meaning_vi":"không nói được, khó nói; chưa đến mức","explanation":"说 (thuyết – nói) + 不上 (không tới) → không nói rõ được; hoặc chưa đáng để gọi là, chưa đến mức.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤔","examples":[{"type":"basic","zh":"我也说不上为什么。","pinyin":"Wǒ yě shuōbushàng wèishénme.","vi":"Tôi cũng không nói được là tại sao."},{"type":"simple","zh":"这道菜说不上好吃，但也不难吃。","pinyin":"Zhè dào cài shuōbushàng hǎochī, dàn yě bùnán chī.","vi":"Món này chẳng đến mức ngon, nhưng cũng không dở."},{"type":"compound","zh":"虽然我们见过几次，但是还说不上是朋友。","pinyin":"Suīrán wǒmen jiànguo jǐ cì, dànshì hái shuōbushàng shì péngyou.","vi":"Tuy chúng tôi gặp vài lần, nhưng chưa thể gọi là bạn bè."}],"related":[{"hanzi":"谈不上","pinyin":"tánbushàng","vi":"chưa nói đến"},{"hanzi":"说不清","pinyin":"shuōbuqīng","vi":"nói không rõ"},{"hanzi":"说得上","pinyin":"shuōdeshàng","vi":"có thể nói là"},{"hanzi":"算不上","pinyin":"suànbushàng","vi":"chẳng tính là"}],"traditional":"說不上"},{"id":"说到底","hanzi":"说到底","pinyin":"shuōdàodǐ","meaning_vi":"suy cho cùng, rốt cuộc","explanation":"说 (thuyết – nói) + 到底 (đáo để – đến tận cùng) → nói cho đến cùng, xét đến cùng.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🎯","examples":[{"type":"basic","zh":"说到底还是钱的问题。","pinyin":"Shuōdàodǐ háishì qián de wèntí.","vi":"Suy cho cùng vẫn là vấn đề tiền."},{"type":"simple","zh":"说到底，健康比什么都重要。","pinyin":"Shuōdàodǐ, jiànkāng bǐ shénme dōu zhòngyào.","vi":"Rốt cuộc thì sức khỏe quan trọng hơn tất cả."},{"type":"compound","zh":"虽然大家吵了很久，但是说到底谁也没有错。","pinyin":"Suīrán dàjiā chǎole hěn jiǔ, dànshì shuōdàodǐ shéi yě méiyǒu cuò.","vi":"Tuy mọi người cãi nhau rất lâu, nhưng suy cho cùng chẳng ai sai cả."}],"related":[{"hanzi":"归根到底","pinyin":"guīgēndàodǐ","vi":"xét cho cùng"},{"hanzi":"说白了","pinyin":"shuōbáile","vi":"nói trắng ra"},{"hanzi":"毕竟","pinyin":"bìjìng","vi":"rốt cuộc"},{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"}],"traditional":"說到底"},{"id":"说道","hanzi":"说道","pinyin":"shuōdào","meaning_vi":"nói rằng, nói (dẫn lời)","explanation":"说 (thuyết – nói) + 道 (đạo – nói) → nói rằng; dùng trong văn kể chuyện để dẫn lời nói trực tiếp.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"他笑着说道：“好！”","pinyin":"Tā xiàozhe shuōdào: \"hǎo!\"","vi":"Anh ấy cười nói: \"Được!\""},{"type":"simple","zh":"老师看着我们，慢慢地说道：“别怕。”","pinyin":"Lǎoshī kànzhe wǒmen, mànmàn de shuōdào: \"bié pà.\"","vi":"Cô giáo nhìn chúng tôi, chậm rãi nói: \"Đừng sợ.\""},{"type":"compound","zh":"虽然他很生气，但是他还是平静地说道：“我们再谈谈。”","pinyin":"Suīrán tā hěn shēngqì, dànshì tā háishì píngjìng de shuōdào: \"wǒmen zài tántan.\"","vi":"Tuy rất tức giận, anh ấy vẫn bình tĩnh nói: \"Chúng ta nói chuyện lại đi.\""}],"related":[{"hanzi":"说","pinyin":"shuō","vi":"nói"},{"hanzi":"问道","pinyin":"wèndào","vi":"hỏi rằng"},{"hanzi":"答道","pinyin":"dádào","vi":"đáp rằng"},{"hanzi":"喊道","pinyin":"hǎndào","vi":"hét lên"}],"traditional":"說道"},{"id":"说干就干","hanzi":"说干就干","pinyin":"shuōgàn-jiùgàn","meaning_vi":"nói là làm, làm ngay","explanation":"说 (thuyết – nói) + 干 (cán – làm) + 就 (tựu – liền) + 干 → vừa nói xong là bắt tay làm ngay, không chần chừ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"他说干就干。","pinyin":"Tā shuōgànjiùgàn.","vi":"Anh ấy nói là làm ngay."},{"type":"simple","zh":"我们说干就干，当天就把房间收拾好了。","pinyin":"Wǒmen shuōgànjiùgàn, dàngtiān jiù bǎ fángjiān shōushi hǎo le.","vi":"Chúng tôi nói là làm, ngay trong ngày đã dọn xong phòng."},{"type":"compound","zh":"因为她做事说干就干，所以老板很信任她。","pinyin":"Yīnwèi tā zuòshì shuōgànjiùgàn, suǒyǐ lǎobǎn hěn xìnrèn tā.","vi":"Vì cô ấy làm việc nói là làm ngay nên sếp rất tin tưởng."}],"related":[{"hanzi":"雷厉风行","pinyin":"léilìfēngxíng","vi":"nhanh như chớp"},{"hanzi":"说到做到","pinyin":"shuōdàozuòdào","vi":"nói được làm được"},{"hanzi":"立刻","pinyin":"lìkè","vi":"lập tức"},{"hanzi":"拖延","pinyin":"tuōyán","vi":"trì hoãn"}],"traditional":"說幹就幹"},{"id":"说谎","hanzi":"说谎","pinyin":"shuōhuǎng","meaning_vi":"nói dối","explanation":"说 (thuyết – nói) + 谎 (hoảng – lời dối) → nói điều không thật.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤥","examples":[{"type":"basic","zh":"小孩子不能说谎。","pinyin":"Xiǎoháizi bù néng shuōhuǎng.","vi":"Trẻ con không được nói dối."},{"type":"simple","zh":"他一说谎脸就红。","pinyin":"Tā yì shuōhuǎng liǎn jiù hóng.","vi":"Hễ nói dối là mặt anh ấy đỏ lên."},{"type":"compound","zh":"如果你一直说谎，以后就没有人相信你了。","pinyin":"Rúguǒ nǐ yìzhí shuōhuǎng, yǐhòu jiù méi yǒurén xiāngxìn nǐ le.","vi":"Nếu bạn cứ nói dối mãi, sau này sẽ chẳng ai tin bạn nữa."}],"related":[{"hanzi":"撒谎","pinyin":"sāhuǎng","vi":"nói dối"},{"hanzi":"谎言","pinyin":"huǎngyán","vi":"lời nói dối"},{"hanzi":"诚实","pinyin":"chéngshí","vi":"trung thực"},{"hanzi":"骗人","pinyin":"piànrén","vi":"lừa người"}],"traditional":"說謊"},{"id":"说老实话","hanzi":"说老实话","pinyin":"shuōlǎo-shihuà","meaning_vi":"nói thật lòng, thú thật","explanation":"说 (thuyết – nói) + 老实话 (lão thực thoại – lời thật thà) → nói thật, thành thật mà nói; dùng mở đầu câu.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🙋","examples":[{"type":"basic","zh":"说老实话，我很紧张。","pinyin":"Shuōlǎoshihuà, wǒ hěn jǐnzhāng.","vi":"Nói thật, tôi rất hồi hộp."},{"type":"simple","zh":"说老实话，这部电影我没看懂。","pinyin":"Shuōlǎoshihuà, zhè bù diànyǐng wǒ méi kàndǒng.","vi":"Thú thật, bộ phim này tôi xem không hiểu."},{"type":"compound","zh":"说老实话，虽然工资不高，但是我很喜欢这份工作。","pinyin":"Shuōlǎoshihuà, suīrán gōngzī bù gāo, dànshì wǒ hěn xǐhuan zhè fèn gōngzuò.","vi":"Nói thật lòng, tuy lương không cao nhưng tôi rất thích công việc này."}],"related":[{"hanzi":"说真的","pinyin":"shuōzhēnde","vi":"nói thật"},{"hanzi":"老实","pinyin":"lǎoshi","vi":"thật thà"},{"hanzi":"实话","pinyin":"shíhuà","vi":"lời thật"},{"hanzi":"坦白地说","pinyin":"tǎnbáideshuō","vi":"thẳng thắn mà nói"}],"traditional":"說老實話"},{"id":"说起来","hanzi":"说起来","pinyin":"shuōqǐlái","meaning_vi":"nói ra thì, nhắc đến thì","explanation":"说 (thuyết – nói) + 起来 (khởi lai – bắt đầu) → khi nói đến, nhắc đến; dùng để dẫn chủ đề hoặc đánh giá.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"💭","examples":[{"type":"basic","zh":"说起来容易，做起来难。","pinyin":"Shuōqǐlái róngyì, zuò qǐlái nán.","vi":"Nói thì dễ, làm mới khó."},{"type":"simple","zh":"说起来，我们已经十年没见了。","pinyin":"Shuōqǐlái, wǒmen yǐjīng shí nián méi jiàn le.","vi":"Nói ra thì chúng ta đã mười năm không gặp rồi."},{"type":"compound","zh":"这件事说起来很简单，但是真正办起来就麻烦了。","pinyin":"Zhè jiàn shì shuōqǐlái hěn jiǎndān, dànshì zhēnzhèng bàn qǐlái jiù máfan le.","vi":"Việc này nói ra thì đơn giản, nhưng thực sự làm thì phiền lắm."}],"related":[{"hanzi":"提起","pinyin":"tíqǐ","vi":"nhắc đến"},{"hanzi":"说到","pinyin":"shuōdào","vi":"nói đến"},{"hanzi":"看起来","pinyin":"kànqǐlái","vi":"trông có vẻ"},{"hanzi":"谈起","pinyin":"tánqǐ","vi":"bàn đến"}],"traditional":"說起來"},{"id":"说情","hanzi":"说情","pinyin":"shuōqíng","meaning_vi":"xin hộ, nói đỡ, can thiệp xin xỏ","explanation":"说 (thuyết – nói) + 情 (tình – tình cảm, ân tình) → nói giúp cho người khác để xin tha hoặc xin ưu đãi.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"别替他说情了。","pinyin":"Bié tì tā shuōqíng le.","vi":"Đừng xin hộ cho hắn nữa."},{"type":"simple","zh":"妈妈去学校替弟弟说情。","pinyin":"Māma qù xuéxiào tì dìdi shuōqíng.","vi":"Mẹ đến trường nói đỡ cho em trai."},{"type":"compound","zh":"即使有人来说情，规定也不能随便改变。","pinyin":"Jíshǐ yǒurén lái shuōqíng, guīdìng yě bù néng suíbiàn gǎibiàn.","vi":"Dù có người đến xin hộ, quy định cũng không thể tùy tiện thay đổi."}],"related":[{"hanzi":"求情","pinyin":"qiúqíng","vi":"cầu xin"},{"hanzi":"讲情","pinyin":"jiǎngqíng","vi":"nói đỡ"},{"hanzi":"人情","pinyin":"rénqíng","vi":"ân tình"},{"hanzi":"走后门","pinyin":"zǒuhòumén","vi":"đi cửa sau"}],"traditional":"說情"},{"id":"说闲话","hanzi":"说闲话","pinyin":"shuōxiánhuà","meaning_vi":"nói ra nói vào, buôn chuyện, đàm tiếu","explanation":"说 (thuyết – nói) + 闲话 (nhàn thoại – chuyện phiếm) → nói chuyện phiếm; thường mang nghĩa xấu: bàn tán sau lưng.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗨️","examples":[{"type":"basic","zh":"别在背后说闲话。","pinyin":"Bié zài bèihòu shuōxiánhuà.","vi":"Đừng nói xấu sau lưng."},{"type":"simple","zh":"邻居们总爱在楼下说闲话。","pinyin":"Línjūmen zǒng ài zài lóuxià shuōxiánhuà.","vi":"Hàng xóm luôn thích tụ dưới nhà buôn chuyện."},{"type":"compound","zh":"虽然有人说闲话，但是她一点儿也不在乎。","pinyin":"Suīrán yǒurén shuōxiánhuà, dànshì tā yìdiǎnr yě bú zàihu.","vi":"Tuy có người đàm tiếu, nhưng cô ấy chẳng bận tâm chút nào."}],"related":[{"hanzi":"闲话","pinyin":"xiánhuà","vi":"chuyện phiếm"},{"hanzi":"聊天","pinyin":"liáotiān","vi":"tán gẫu"},{"hanzi":"议论","pinyin":"yìlùn","vi":"bàn tán"},{"hanzi":"八卦","pinyin":"bāguà","vi":"chuyện tầm phào"}],"traditional":"說閒話"},{"id":"说真的","hanzi":"说真的","pinyin":"shuōzhēnde","meaning_vi":"nói thật, thật sự mà nói","explanation":"说 (thuyết – nói) + 真的 (chân – thật) → nói nghiêm túc, nói thật; dùng nhấn mạnh sự thành thật.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"😶","examples":[{"type":"basic","zh":"说真的，我很想你。","pinyin":"Shuōzhēnde, wǒ hěn xiǎng nǐ.","vi":"Nói thật, anh rất nhớ em."},{"type":"simple","zh":"说真的，你应该换个工作了。","pinyin":"Shuōzhēnde, nǐ yīnggāi huàn ge gōngzuò le.","vi":"Nói thật, bạn nên đổi việc rồi."},{"type":"compound","zh":"说真的，如果不是你帮忙，我早就放弃了。","pinyin":"Shuōzhēnde, rúguǒ bú shì nǐ bāngmáng, wǒ zǎojiù fàngqì le.","vi":"Nói thật, nếu không có bạn giúp thì tôi đã bỏ cuộc từ lâu."}],"related":[{"hanzi":"说老实话","pinyin":"shuōlǎoshihuà","vi":"nói thật lòng"},{"hanzi":"真的","pinyin":"zhēnde","vi":"thật sự"},{"hanzi":"其实","pinyin":"qíshí","vi":"thực ra"},{"hanzi":"老实说","pinyin":"lǎoshishuō","vi":"thú thật"}],"traditional":"說真的"},{"id":"硕果","hanzi":"硕果","pinyin":"shuòguǒ","meaning_vi":"thành quả lớn, kết quả to lớn","explanation":"硕 (thạc – to lớn) + 果 (quả – trái, kết quả) → trái to; nghĩa bóng là thành tựu lớn; 硕果累累 thành quả dồi dào.","hsk_level":"7-9","tags":["danh-tu"],"image":"🍎","examples":[{"type":"basic","zh":"果园硕果累累。","pinyin":"Guǒyuán shuòguǒlěilěi.","vi":"Vườn quả trĩu trịt trái to."},{"type":"simple","zh":"多年的研究终于结出了硕果。","pinyin":"Duōnián de yánjiū zhōngyú jiéchūle shuòguǒ.","vi":"Nhiều năm nghiên cứu cuối cùng đã cho thành quả lớn."},{"type":"compound","zh":"因为团队一直努力，所以今年取得了硕果。","pinyin":"Yīnwèi tuánduì yìzhí nǔlì, suǒyǐ jīnnián qǔ déle shuòguǒ.","vi":"Vì cả đội luôn nỗ lực nên năm nay đã gặt hái thành quả lớn."}],"related":[{"hanzi":"成果","pinyin":"chéngguǒ","vi":"thành quả"},{"hanzi":"硕士","pinyin":"shuòshì","vi":"thạc sĩ"},{"hanzi":"成就","pinyin":"chéngjiù","vi":"thành tựu"},{"hanzi":"果实","pinyin":"guǒshí","vi":"trái cây, thành quả"}],"traditional":"碩果"},{"id":"丝","hanzi":"丝","pinyin":"sī","meaning_vi":"tơ, sợi; chút xíu; sợi (món ăn thái sợi)","explanation":"丝 (ti – tơ tằm) → sợi tơ, vật mảnh như sợi; lượng từ chỉ mức rất nhỏ (一丝); món ăn thái sợi (土豆丝).","hsk_level":"7-9","tags":["danh-tu"],"image":"🧵","examples":[{"type":"basic","zh":"这是真丝围巾。","pinyin":"Zhè shì zhēn sī wéijīn.","vi":"Đây là khăn quàng lụa thật."},{"type":"simple","zh":"我最爱吃妈妈做的土豆丝。","pinyin":"Wǒ zuì ài chī māma zuò de tǔdòusī.","vi":"Tôi thích nhất món khoai tây thái sợi mẹ làm."},{"type":"compound","zh":"虽然他嘴上说没事，但是脸上露出了一丝紧张。","pinyin":"Suīrán tā zuǐ shàng shuō méishì, dànshì liǎn shàng lùchūle yìsī jǐnzhāng.","vi":"Tuy miệng nói không sao, nhưng mặt anh ấy lộ ra một chút căng thẳng."}],"related":[{"hanzi":"丝绸","pinyin":"sīchóu","vi":"lụa"},{"hanzi":"蚕丝","pinyin":"cánsī","vi":"tơ tằm"},{"hanzi":"一丝不苟","pinyin":"yìsībùgǒu","vi":"tỉ mỉ cẩn thận"},{"hanzi":"粉丝","pinyin":"fěnsī","vi":"miến"}],"traditional":"絲"},{"id":"私房钱","hanzi":"私房钱","pinyin":"sīfángqián","meaning_vi":"tiền riêng, quỹ đen","explanation":"私房 (tư phòng – của riêng) + 钱 (tiền) → khoản tiền riêng giấu không cho người nhà (thường là vợ/chồng) biết.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🐷","examples":[{"type":"basic","zh":"他偷偷存私房钱。","pinyin":"Tā tōutōu cún sīfángqián.","vi":"Anh ấy lén giữ quỹ đen."},{"type":"simple","zh":"妻子在书里发现了丈夫的私房钱。","pinyin":"Qīzi zài shū lǐ fāxiànle zhàngfu de sīfángqián.","vi":"Người vợ phát hiện tiền riêng của chồng giấu trong sách."},{"type":"compound","zh":"虽然钱不多，但是这些私房钱是她给自己留的后路。","pinyin":"Suīrán qián bù duō, dànshì zhèxiē sīfángqián shì tā gěi zìjǐ liú de hòulù.","vi":"Tuy không nhiều, nhưng số tiền riêng này là đường lui cô ấy để dành cho mình."}],"related":[{"hanzi":"存钱","pinyin":"cúnqián","vi":"để dành tiền"},{"hanzi":"零花钱","pinyin":"línghuāqián","vi":"tiền tiêu vặt"},{"hanzi":"私人","pinyin":"sīrén","vi":"cá nhân"},{"hanzi":"积蓄","pinyin":"jīxù","vi":"tiền tiết kiệm"}],"traditional":"私房錢"},{"id":"私立","hanzi":"私立","pinyin":"sīlì","meaning_vi":"tư lập, tư thục","explanation":"私 (tư – riêng) + 立 (lập – lập ra) → do tư nhân thành lập; đối lập với 公立.","hsk_level":"7-9","tags":["tinh-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"这是一所私立学校。","pinyin":"Zhè shì yì suǒ sīlì xuéxiào.","vi":"Đây là một trường tư thục."},{"type":"simple","zh":"私立医院的服务通常比较好。","pinyin":"Sīlì yīyuàn de fúwù tōngcháng bǐjiào hǎo.","vi":"Dịch vụ của bệnh viện tư thường khá tốt."},{"type":"compound","zh":"虽然私立大学学费很贵，但是很多家长还是愿意送孩子去。","pinyin":"Suīrán sīlì dàxué xuéfèi hěn guì, dànshì hěn duō jiāzhǎng háishì yuànyì sòng háizi qù.","vi":"Tuy học phí đại học tư rất đắt, nhưng nhiều phụ huynh vẫn sẵn lòng cho con theo học."}],"related":[{"hanzi":"公立","pinyin":"gōnglì","vi":"công lập"},{"hanzi":"私营","pinyin":"sīyíng","vi":"tư doanh"},{"hanzi":"民办","pinyin":"mínbàn","vi":"dân lập"},{"hanzi":"私有","pinyin":"sīyǒu","vi":"tư hữu"}]},{"id":"私事","hanzi":"私事","pinyin":"sīshì","meaning_vi":"việc riêng, chuyện riêng tư","explanation":"私 (tư – riêng) + 事 (sự – việc) → việc cá nhân, không liên quan đến công việc chung.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"🔒","examples":[{"type":"basic","zh":"这是我的私事。","pinyin":"Zhè shì wǒ de sīshì.","vi":"Đây là chuyện riêng của tôi."},{"type":"simple","zh":"上班时间不要处理私事。","pinyin":"Shàngbān shíjiān bú yào chǔlǐ sīshì.","vi":"Đừng giải quyết việc riêng trong giờ làm."},{"type":"compound","zh":"如果你有私事要办，就提前跟经理请假。","pinyin":"Rúguǒ nǐ yǒu sīshì yào bàn, jiù tíqián gēn jīnglǐ qǐngjià.","vi":"Nếu có việc riêng cần làm, bạn hãy xin nghỉ với quản lý trước."}],"related":[{"hanzi":"公事","pinyin":"gōngshì","vi":"việc công"},{"hanzi":"隐私","pinyin":"yǐnsī","vi":"quyền riêng tư"},{"hanzi":"私人","pinyin":"sīrén","vi":"cá nhân"},{"hanzi":"家事","pinyin":"jiāshì","vi":"việc nhà"}]},{"id":"私有","hanzi":"私有","pinyin":"sīyǒu","meaning_vi":"tư hữu, thuộc sở hữu tư nhân","explanation":"私 (tư – riêng) + 有 (hữu – có, sở hữu) → thuộc quyền sở hữu của cá nhân.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏠","examples":[{"type":"basic","zh":"这片土地是私有的。","pinyin":"Zhè piàn tǔdì shì sīyǒu de.","vi":"Mảnh đất này thuộc sở hữu tư nhân."},{"type":"simple","zh":"法律保护公民的私有财产。","pinyin":"Fǎlǜ bǎohù gōngmín de sīyǒu cáichǎn.","vi":"Pháp luật bảo vệ tài sản tư hữu của công dân."},{"type":"compound","zh":"虽然这家公司以前是国有的，但是现在已经私有化了。","pinyin":"Suīrán zhè jiā gōngsī yǐqián shì guó yǒude, dànshì xiànzài yǐjīng sīyǒuhuà le.","vi":"Tuy công ty này trước kia là quốc doanh, nhưng nay đã tư nhân hóa."}],"related":[{"hanzi":"公有","pinyin":"gōngyǒu","vi":"công hữu"},{"hanzi":"国有","pinyin":"guóyǒu","vi":"quốc hữu"},{"hanzi":"私有化","pinyin":"sīyǒuhuà","vi":"tư nhân hóa"},{"hanzi":"财产","pinyin":"cáichǎn","vi":"tài sản"}]},{"id":"思路","hanzi":"思路","pinyin":"sīlù","meaning_vi":"mạch suy nghĩ, hướng tư duy, ý tưởng","explanation":"思 (tư – suy nghĩ) + 路 (lộ – đường) → con đường của suy nghĩ, cách tư duy để giải quyết vấn đề.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"你的思路很清楚。","pinyin":"Nǐ de sīlù hěn qīngchu.","vi":"Mạch suy nghĩ của bạn rất rõ ràng."},{"type":"simple","zh":"电话一响，我的思路就被打断了。","pinyin":"Diànhuà yì xiǎng, wǒ de sīlù jiù bèi dǎduàn le.","vi":"Điện thoại vừa reo, dòng suy nghĩ của tôi bị cắt ngang."},{"type":"compound","zh":"如果换个思路想问题，你就会发现新的办法。","pinyin":"Rúguǒ huàn ge sīlù xiǎng wèntí, nǐ jiù huì fāxiàn xīn de bànfǎ.","vi":"Nếu thay đổi cách nghĩ về vấn đề, bạn sẽ tìm ra cách mới."}],"related":[{"hanzi":"思考","pinyin":"sīkǎo","vi":"suy nghĩ"},{"hanzi":"思维","pinyin":"sīwéi","vi":"tư duy"},{"hanzi":"想法","pinyin":"xiǎngfǎ","vi":"ý nghĩ"},{"hanzi":"梳理","pinyin":"shūlǐ","vi":"sắp xếp"}]},{"id":"思前想后","hanzi":"思前想后","pinyin":"sīqián-xiǎnghòu","meaning_vi":"nghĩ trước nghĩ sau, cân nhắc kỹ","explanation":"思前 (tư tiền – nghĩ về trước) + 想后 (tưởng hậu – nghĩ về sau) → suy đi tính lại nguyên nhân và hậu quả, cân nhắc nhiều lần.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"🤯","examples":[{"type":"basic","zh":"他思前想后，没睡着。","pinyin":"Tā sīqiánxiǎnghòu, méi shuìzháo.","vi":"Anh ấy nghĩ trước nghĩ sau, không ngủ được."},{"type":"simple","zh":"思前想后，我还是决定辞职。","pinyin":"Sīqiánxiǎnghòu, wǒ háishì juédìng cízhí.","vi":"Cân nhắc mãi, tôi vẫn quyết định nghỉ việc."},{"type":"compound","zh":"虽然她思前想后了好几天，但是还是拿不定主意。","pinyin":"Suīrán tā sīqiánxiǎnghòule hǎo jǐtiān, dànshì háishì ná budìng zhǔyi.","vi":"Tuy đã suy đi tính lại mấy ngày, cô ấy vẫn chưa quyết được."}],"related":[{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"cân nhắc"},{"hanzi":"深思熟虑","pinyin":"shēnsīshúlǜ","vi":"suy nghĩ chín chắn"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"左思右想","pinyin":"zuǒsīyòuxiǎng","vi":"nghĩ tới nghĩ lui"}],"traditional":"思前想後"},{"id":"四季","hanzi":"四季","pinyin":"sìjì","meaning_vi":"bốn mùa","explanation":"四 (tứ – bốn) + 季 (quý – mùa) → bốn mùa xuân, hạ, thu, đông.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"🍂","examples":[{"type":"basic","zh":"这里四季如春。","pinyin":"Zhèlǐ sìjìrúchūn.","vi":"Nơi đây bốn mùa như xuân."},{"type":"simple","zh":"公园一年四季都有花开。","pinyin":"Gōngyuán yì nián sìjì dōu yǒu huā kāi.","vi":"Công viên quanh năm bốn mùa đều có hoa nở."},{"type":"compound","zh":"虽然这个城市四季分明，但是春天和秋天都很短。","pinyin":"Suīrán zhè ge chéngshì sìjì fēnmíng, dànshì chūntiān hé qiūtiān dōu hěn duǎn.","vi":"Tuy thành phố này bốn mùa rõ rệt, nhưng mùa xuân và mùa thu đều rất ngắn."}],"related":[{"hanzi":"季节","pinyin":"jìjié","vi":"mùa"},{"hanzi":"春夏秋冬","pinyin":"chūnxiàqiūdōng","vi":"xuân hạ thu đông"},{"hanzi":"四季如春","pinyin":"sìjìrúchūn","vi":"bốn mùa như xuân"},{"hanzi":"气候","pinyin":"qìhòu","vi":"khí hậu"}]},{"id":"饲料","hanzi":"饲料","pinyin":"sìliào","meaning_vi":"thức ăn chăn nuôi","explanation":"饲 (tự – cho ăn, nuôi) + 料 (liệu – nguyên liệu) → thức ăn dùng để nuôi gia súc, gia cầm, cá.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐄","examples":[{"type":"basic","zh":"该给鸡喂饲料了。","pinyin":"Gāi gěi jī wèi sìliào le.","vi":"Đến giờ cho gà ăn rồi."},{"type":"simple","zh":"饲料价格上涨，养猪的成本也高了。","pinyin":"Sìliào jiàgé shàngzhǎng, yǎng zhū de chéngběn yě gāo le.","vi":"Giá thức ăn chăn nuôi tăng, chi phí nuôi lợn cũng cao lên."},{"type":"compound","zh":"如果饲料里加了违禁药物，肉就不能吃了。","pinyin":"Rúguǒ sìliào lǐjiāle wéijìn yàowù, ròu jiù bù néng chī le.","vi":"Nếu thức ăn chăn nuôi có thuốc cấm thì thịt không ăn được nữa."}],"related":[{"hanzi":"饲养","pinyin":"sìyǎng","vi":"chăn nuôi"},{"hanzi":"喂养","pinyin":"wèiyǎng","vi":"cho ăn, nuôi"},{"hanzi":"养殖","pinyin":"yǎngzhí","vi":"nuôi trồng"},{"hanzi":"牲畜","pinyin":"shēngchù","vi":"gia súc"}],"traditional":"飼料"},{"id":"松绑","hanzi":"松绑","pinyin":"sōngbǎng","meaning_vi":"cởi trói, nới lỏng (quy định)","explanation":"松 (tùng – lỏng ra) + 绑 (bảng – trói) → cởi dây trói; nghĩa bóng là nới lỏng hạn chế, quy định.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔓","examples":[{"type":"basic","zh":"快给他松绑。","pinyin":"Kuài gěi tā sōngbǎng.","vi":"Mau cởi trói cho anh ta."},{"type":"simple","zh":"政府决定为小企业松绑。","pinyin":"Zhèngfǔ jué dìngwèi xiǎoqǐyè sōngbǎng.","vi":"Chính phủ quyết định nới lỏng quy định cho doanh nghiệp nhỏ."},{"type":"compound","zh":"只要给学生的课业松绑，他们就有更多时间发展兴趣。","pinyin":"Zhǐyào gěi xuésheng de kèyè sōngbǎng, tāmen jiù yǒu gèng duō shíjiān fāzhǎn xìngqù.","vi":"Chỉ cần giảm tải bài vở cho học sinh, các em sẽ có thêm thời gian phát triển sở thích."}],"related":[{"hanzi":"捆绑","pinyin":"kǔnbǎng","vi":"trói buộc"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"thả lỏng"},{"hanzi":"解除","pinyin":"jiěchú","vi":"gỡ bỏ"},{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"}],"traditional":"鬆綁"},{"id":"松弛","hanzi":"松弛","pinyin":"sōngchí","meaning_vi":"lỏng lẻo, chùng, thư giãn","explanation":"松 (tùng – lỏng) + 弛 (thỉ – chùng, buông) → không căng, lỏng ra; dùng cho cơ bắp, da, tinh thần, kỷ luật.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🧘","examples":[{"type":"basic","zh":"她的皮肤有些松弛。","pinyin":"Tā de pífū yǒuxiē sōngchí.","vi":"Da cô ấy hơi chùng nhão."},{"type":"simple","zh":"泡个热水澡能让肌肉松弛下来。","pinyin":"Pào ge rèshuǐzǎo néng ràng jīròu sōngchí xiàlái.","vi":"Tắm nước nóng giúp cơ bắp thư giãn."},{"type":"compound","zh":"如果纪律松弛了，工作效率就会下降。","pinyin":"Rúguǒ jìlǜ sōngchí le, gōngzuò xiàolǜ jiù huì xiàjiàng.","vi":"Nếu kỷ luật lỏng lẻo, hiệu quả công việc sẽ giảm."}],"related":[{"hanzi":"放松","pinyin":"fàngsōng","vi":"thả lỏng"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"},{"hanzi":"松懈","pinyin":"sōngxiè","vi":"lơ là"},{"hanzi":"宽松","pinyin":"kuānsōng","vi":"rộng rãi, thoải mái"}],"traditional":"鬆弛"},{"id":"搜查","hanzi":"搜查","pinyin":"sōuchá","meaning_vi":"lục soát, khám xét","explanation":"搜 (sưu – tìm kiếm) + 查 (tra – xem xét) → lục soát kỹ để tìm người hay vật phạm pháp.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🕵️","examples":[{"type":"basic","zh":"警察搜查了房间。","pinyin":"Jǐngchá sōuchále fángjiān.","vi":"Cảnh sát đã khám xét căn phòng."},{"type":"simple","zh":"他们在机场被仔细搜查了一遍。","pinyin":"Tāmen zài jīchǎng bèi zǐxì sōuchále yíbiàn.","vi":"Họ bị lục soát kỹ một lượt ở sân bay."},{"type":"compound","zh":"如果没有搜查证，警察就不能随便进入民宅。","pinyin":"Rúguǒ méiyǒu sōu cházhèng, jǐngchá jiù bù néng suíbiàn jìnrù mínzhái.","vi":"Nếu không có lệnh khám xét, cảnh sát không được tùy tiện vào nhà dân."}],"related":[{"hanzi":"搜索","pinyin":"sōusuǒ","vi":"tìm kiếm"},{"hanzi":"检查","pinyin":"jiǎnchá","vi":"kiểm tra"},{"hanzi":"搜身","pinyin":"sōushēn","vi":"khám người"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"}]},{"id":"搜寻","hanzi":"搜寻","pinyin":"sōuxún","meaning_vi":"tìm kiếm, sục tìm","explanation":"搜 (sưu – tìm) + 寻 (tầm – tìm) → tìm kiếm khắp nơi người hay vật.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔎","examples":[{"type":"basic","zh":"救援队正在搜寻失踪者。","pinyin":"Jiùyuánduì zhèngzài sōuxún shīzōng zhě.","vi":"Đội cứu hộ đang tìm kiếm người mất tích."},{"type":"simple","zh":"他在旧书店里搜寻那本绝版书。","pinyin":"Tā zài jiù shūdiàn lǐ sōuxún nà běn juébǎn shū.","vi":"Anh ấy sục tìm cuốn sách tuyệt bản ở hiệu sách cũ."},{"type":"compound","zh":"虽然搜寻了三天三夜，但是仍然没有找到那条船。","pinyin":"Suīrán sōuxúnle sān tiān sān yè, dànshì réngrán méiyǒu zhǎodào nà tiáo chuán.","vi":"Tuy đã tìm kiếm ba ngày ba đêm, nhưng vẫn chưa thấy con tàu đó."}],"related":[{"hanzi":"寻找","pinyin":"xúnzhǎo","vi":"tìm kiếm"},{"hanzi":"搜索","pinyin":"sōusuǒ","vi":"tìm kiếm (trên mạng)"},{"hanzi":"搜查","pinyin":"sōuchá","vi":"lục soát"},{"hanzi":"寻求","pinyin":"xúnqiú","vi":"tìm cầu"}],"traditional":"搜尋"},{"id":"酥","hanzi":"酥","pinyin":"sū","meaning_vi":"giòn tan, xốp; bánh xốp; bủn rủn","explanation":"酥 (tô – bánh xốp, giòn) → chỉ đồ ăn giòn xốp dễ vỡ (bánh ngàn lớp); cũng tả cảm giác tay chân bủn rủn, mềm nhũn.","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"🥐","examples":[{"type":"basic","zh":"这饼干又香又酥。","pinyin":"Zhè bǐnggān yòu xiāng yòu sū.","vi":"Bánh quy này vừa thơm vừa giòn xốp."},{"type":"simple","zh":"他走了一天路，两条腿都酥了。","pinyin":"Tā zǒule yì tiān lù, liǎng tiáo tuǐ dōu sū le.","vi":"Đi bộ cả ngày, hai chân anh ấy bủn rủn cả."},{"type":"compound","zh":"如果烤的时间不够，饼皮就不会这么酥。","pinyin":"Rúguǒ kǎo de shíjiān búgòu, bǐng pí jiù bú huì zhème sū.","vi":"Nếu nướng chưa đủ thời gian thì vỏ bánh sẽ không giòn xốp thế này."}],"related":[{"hanzi":"脆","pinyin":"cuì","vi":"giòn"},{"hanzi":"酥饼","pinyin":"sūbǐng","vi":"bánh nướng xốp"},{"hanzi":"香脆","pinyin":"xiāngcuì","vi":"thơm giòn"},{"hanzi":"软","pinyin":"ruǎn","vi":"mềm"}]},{"id":"俗","hanzi":"俗","pinyin":"sú","meaning_vi":"tục, phong tục; tầm thường, quê mùa","explanation":"俗 (tục – phong tục, thế tục) → tập quán của dân gian; tính từ chỉ tầm thường, sến, kém thanh nhã.","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🎎","examples":[{"type":"basic","zh":"这件衣服太俗了。","pinyin":"Zhè jiàn yīfu tài sú le.","vi":"Bộ quần áo này sến quá."},{"type":"simple","zh":"入乡随俗，到了这里就按这里的规矩办。","pinyin":"Rùxiāngsuísú, dàole zhèlǐ jiù àn zhèlǐ de guīju bàn.","vi":"Nhập gia tùy tục, đến đây thì làm theo lệ ở đây."},{"type":"compound","zh":"虽然这个故事有点俗，但是观众都很喜欢。","pinyin":"Suīrán zhè ge gùshi yǒudiǎn sú, dànshì guānzhòng dōu hěn xǐhuan.","vi":"Tuy câu chuyện này hơi tầm thường, nhưng khán giả đều rất thích."}],"related":[{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"},{"hanzi":"习俗","pinyin":"xísú","vi":"tập tục"},{"hanzi":"庸俗","pinyin":"yōngsú","vi":"dung tục"},{"hanzi":"通俗","pinyin":"tōngsú","vi":"thông tục, dễ hiểu"}]},{"id":"俗话说","hanzi":"俗话说","pinyin":"súhuàshuō","meaning_vi":"tục ngữ có câu, người ta thường nói","explanation":"俗话 (tục thoại – lời nói dân gian) + 说 (thuyết – nói) → tục ngữ nói rằng; dùng để dẫn một câu tục ngữ.","hsk_level":"7-9","tags":["thanh-ngu","ngon-ngu"],"image":"🗯️","examples":[{"type":"basic","zh":"俗话说，熟能生巧。","pinyin":"Súhuàshuō, shúnéngshēngqiǎo.","vi":"Tục ngữ có câu, quen tay hay việc."},{"type":"simple","zh":"俗话说得好，远亲不如近邻。","pinyin":"Súhuàshuō de hǎo, yuǎnqīn bùrú jìnlín.","vi":"Người ta nói đúng, bà con xa không bằng láng giềng gần."},{"type":"compound","zh":"俗话说，只要功夫深，铁杵就能磨成针。","pinyin":"Súhuàshuō, zhǐyào gōngfu shēn, tiě chǔ jiù néng mó chéng zhēn.","vi":"Tục ngữ có câu, chỉ cần công phu sâu, chày sắt cũng mài thành kim."}],"related":[{"hanzi":"俗语","pinyin":"súyǔ","vi":"tục ngữ"},{"hanzi":"谚语","pinyin":"yànyǔ","vi":"ngạn ngữ"},{"hanzi":"常言道","pinyin":"chángyándào","vi":"thường nói rằng"},{"hanzi":"成语","pinyin":"chéngyǔ","vi":"thành ngữ"}],"traditional":"俗話說"},{"id":"俗语","hanzi":"俗语","pinyin":"súyǔ","meaning_vi":"tục ngữ, câu nói dân gian","explanation":"俗 (tục – dân gian) + 语 (ngữ – lời nói) → câu nói phổ biến trong dân gian, đúc kết kinh nghiệm.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"📖","examples":[{"type":"basic","zh":"这是一句老俗语。","pinyin":"Zhè shì yíjù lǎo súyǔ.","vi":"Đây là một câu tục ngữ cổ."},{"type":"simple","zh":"学习俗语能帮助我们了解中国文化。","pinyin":"Xuéxí súyǔ néng bāngzhù wǒmen liǎojiě Zhōngguó wénhuà.","vi":"Học tục ngữ giúp chúng ta hiểu văn hóa Trung Quốc."},{"type":"compound","zh":"虽然俗语很简单，但是里面包含着深刻的道理。","pinyin":"Suīrán súyǔ hěn jiǎndān, dànshì lǐmiàn bāohánzhe shēnkè de dàolǐ.","vi":"Tuy tục ngữ rất giản dị, nhưng chứa đựng đạo lý sâu sắc."}],"related":[{"hanzi":"俗话","pinyin":"súhuà","vi":"lời tục ngữ"},{"hanzi":"谚语","pinyin":"yànyǔ","vi":"ngạn ngữ"},{"hanzi":"成语","pinyin":"chéngyǔ","vi":"thành ngữ"},{"hanzi":"口语","pinyin":"kǒuyǔ","vi":"khẩu ngữ"}],"traditional":"俗語"},{"id":"素","hanzi":"素","pinyin":"sù","meaning_vi":"chay; trơn, giản dị; vốn dĩ","explanation":"素 (tố – lụa trắng, mộc mạc) → màu trơn, không trang trí; đồ ăn chay (吃素); trong văn viết còn là phó từ 'vốn, xưa nay'.","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"🥦","examples":[{"type":"basic","zh":"我奶奶吃素。","pinyin":"Wǒ nǎinai chīsù.","vi":"Bà tôi ăn chay."},{"type":"simple","zh":"她喜欢穿颜色很素的衣服。","pinyin":"Tā xǐhuan chuān yánsè hěn sù de yīfu.","vi":"Cô ấy thích mặc quần áo màu trơn giản dị."},{"type":"compound","zh":"虽然这家店的菜都是素的，但是味道一点儿也不差。","pinyin":"Suīrán zhè jiā diàn de cài dōu shì sù de, dànshì wèidào yìdiǎnr yě búchà.","vi":"Tuy món ở quán này toàn đồ chay, nhưng hương vị chẳng kém chút nào."}],"related":[{"hanzi":"吃素","pinyin":"chīsù","vi":"ăn chay"},{"hanzi":"素食","pinyin":"sùshí","vi":"đồ chay"},{"hanzi":"朴素","pinyin":"pǔsù","vi":"giản dị"},{"hanzi":"荤","pinyin":"hūn","vi":"món mặn"}]},{"id":"素材","hanzi":"素材","pinyin":"sùcái","meaning_vi":"tư liệu, chất liệu (sáng tác)","explanation":"素 (tố – mộc, thô) + 材 (tài – vật liệu) → chất liệu thô, tư liệu dùng cho sáng tác văn học, nghệ thuật, video.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎞️","examples":[{"type":"basic","zh":"我在收集写作素材。","pinyin":"Wǒ zài shōují xiězuò sùcái.","vi":"Tôi đang thu thập tư liệu viết văn."},{"type":"simple","zh":"这段视频可以作为广告素材。","pinyin":"Zhè duàn shìpín kěyǐ zuòwéi guǎnggào sùcái.","vi":"Đoạn video này có thể dùng làm chất liệu quảng cáo."},{"type":"compound","zh":"因为他经常旅行，所以小说的素材特别丰富。","pinyin":"Yīnwèi tā jīngcháng lǚxíng, suǒyǐ xiǎoshuō de sùcái tèbié fēngfù.","vi":"Vì anh ấy hay đi du lịch nên tư liệu cho tiểu thuyết rất phong phú."}],"related":[{"hanzi":"材料","pinyin":"cáiliào","vi":"tài liệu"},{"hanzi":"题材","pinyin":"tícái","vi":"đề tài"},{"hanzi":"资料","pinyin":"zīliào","vi":"tư liệu"},{"hanzi":"创作","pinyin":"chuàngzuò","vi":"sáng tác"}]},{"id":"诉苦","hanzi":"诉苦","pinyin":"sùkǔ","meaning_vi":"than thở, kể khổ","explanation":"诉 (tố – kể, tố) + 苦 (khổ – nỗi khổ) → kể nỗi khổ, than phiền với người khác.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😩","examples":[{"type":"basic","zh":"她向我诉苦。","pinyin":"Tā xiàng wǒ sùkǔ.","vi":"Cô ấy than thở với tôi."},{"type":"simple","zh":"他一见到朋友就开始诉苦。","pinyin":"Tā yí jiàndào péngyou jiù kāishǐ sùkǔ.","vi":"Hễ gặp bạn bè là anh ấy bắt đầu kể khổ."},{"type":"compound","zh":"虽然工作很累，但是她从不在家人面前诉苦。","pinyin":"Suīrán gōngzuò hěn lèi, dànshì tā cóng bú zài jiārén miànqián sùkǔ.","vi":"Tuy công việc rất mệt, nhưng cô ấy chưa bao giờ than thở trước mặt gia đình."}],"related":[{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"phàn nàn"},{"hanzi":"叫苦","pinyin":"jiàokǔ","vi":"kêu khổ"},{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"},{"hanzi":"诉说","pinyin":"sùshuō","vi":"kể lể"}],"traditional":"訴苦"},{"id":"蒜","hanzi":"蒜","pinyin":"suàn","meaning_vi":"tỏi","explanation":"蒜 (toán – tỏi) → cây tỏi, củ tỏi dùng làm gia vị.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🧄","examples":[{"type":"basic","zh":"炒菜放点蒜。","pinyin":"Chǎocài fàng diǎn suàn.","vi":"Xào rau cho chút tỏi."},{"type":"simple","zh":"他把蒜切碎后放进了酱汁里。","pinyin":"Tā bǎ suàn qiēsuì hòu fàngjìnle jiàng zhī lǐ.","vi":"Anh ấy băm nhỏ tỏi rồi cho vào nước sốt."},{"type":"compound","zh":"如果你吃了生蒜，嘴里就会有很重的味道。","pinyin":"Rúguǒ nǐ chīle shēng suàn, zuǐlǐ jiù huì yǒu hěn zhòng de wèidào.","vi":"Nếu ăn tỏi sống, trong miệng sẽ có mùi rất nặng."}],"related":[{"hanzi":"大蒜","pinyin":"dàsuàn","vi":"tỏi"},{"hanzi":"葱","pinyin":"cōng","vi":"hành"},{"hanzi":"姜","pinyin":"jiāng","vi":"gừng"},{"hanzi":"蒜头","pinyin":"suàntóu","vi":"củ tỏi"}]},{"id":"算账","hanzi":"算账","pinyin":"suànzhàng","meaning_vi":"tính toán sổ sách; tính sổ, trả đũa","explanation":"算 (toán – tính) + 账 (trướng – sổ sách) → tính toán sổ sách; nghĩa bóng là tính sổ, trả thù với ai.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"🧮","examples":[{"type":"basic","zh":"月底要算账。","pinyin":"Yuèdǐ yào suànzhàng.","vi":"Cuối tháng phải tính sổ sách."},{"type":"simple","zh":"老板在柜台后面认真地算账。","pinyin":"Lǎobǎn zài guìtái hòumiàn rènzhēn de suànzhàng.","vi":"Ông chủ đang chăm chú tính toán sổ sách sau quầy."},{"type":"compound","zh":"如果他再欺负你，我就去找他算账。","pinyin":"Rúguǒ tā zài qīfu nǐ, wǒ jiù qù zhǎo tā suànzhàng.","vi":"Nếu hắn còn bắt nạt em, anh sẽ đi tính sổ với hắn."}],"related":[{"hanzi":"结账","pinyin":"jiézhàng","vi":"thanh toán"},{"hanzi":"记账","pinyin":"jìzhàng","vi":"ghi sổ"},{"hanzi":"账单","pinyin":"zhàngdān","vi":"hóa đơn"},{"hanzi":"报复","pinyin":"bàofù","vi":"trả thù"}],"traditional":"算賬"},{"id":"虽说","hanzi":"虽说","pinyin":"suīshuō","meaning_vi":"tuy nói, mặc dù","explanation":"虽 (tuy – tuy) + 说 (thuyết – nói) → tuy nói là, mặc dù; mang sắc thái khẩu ngữ, thường đi với 但是, 可是.","hsk_level":"7-9","tags":["lien-tu"],"image":"🔀","examples":[{"type":"basic","zh":"虽说累，但很开心。","pinyin":"Suīshuō lèi, dàn hěn kāixīn.","vi":"Tuy mệt nhưng rất vui."},{"type":"simple","zh":"虽说是夏天，山上的晚上还挺冷。","pinyin":"Suīshuō shì xiàtiān, shān shàng de wǎnshang hái tǐng lěng.","vi":"Tuy là mùa hè, nhưng buổi tối trên núi vẫn khá lạnh."},{"type":"compound","zh":"虽说他学中文才一年，但是已经能看懂新闻了。","pinyin":"Suīshuō tā xué Zhōngwén cái yì nián, dànshì yǐjīng néng kàndǒng xīnwén le.","vi":"Tuy anh ấy mới học tiếng Trung một năm, nhưng đã đọc hiểu được tin tức."}],"related":[{"hanzi":"虽然","pinyin":"suīrán","vi":"tuy rằng"},{"hanzi":"尽管","pinyin":"jǐnguǎn","vi":"mặc dù"},{"hanzi":"虽则","pinyin":"suīzé","vi":"tuy là"},{"hanzi":"但是","pinyin":"dànshì","vi":"nhưng"}],"traditional":"雖說"},{"id":"随处可见","hanzi":"随处可见","pinyin":"suíchù-kějiàn","meaning_vi":"có thể thấy ở khắp nơi","explanation":"随处 (tùy xứ – bất cứ nơi nào) + 可见 (khả kiến – có thể thấy) → nhìn đâu cũng thấy, rất phổ biến.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"樱花随处可见。","pinyin":"Yīnghuā suíchùkějiàn.","vi":"Hoa anh đào có thể thấy ở khắp nơi."},{"type":"simple","zh":"在这个城市，共享单车随处可见。","pinyin":"Zài zhè ge chéngshì, gòngxiǎng dānchē suíchùkějiàn.","vi":"Ở thành phố này, xe đạp chia sẻ có ở khắp nơi."},{"type":"compound","zh":"虽然塑料袋随处可见，但是它们对环境的危害很大。","pinyin":"Suīrán sùliàodài suíchùkějiàn, dànshì tāmen duì huánjìng de wēihài hěn dà.","vi":"Tuy túi ni-lông có ở khắp nơi, nhưng chúng gây hại rất lớn cho môi trường."}],"related":[{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"},{"hanzi":"随处","pinyin":"suíchù","vi":"bất cứ đâu"},{"hanzi":"比比皆是","pinyin":"bǐbǐjiēshì","vi":"đâu đâu cũng có"},{"hanzi":"常见","pinyin":"chángjiàn","vi":"thường gặp"}],"traditional":"隨處可見"},{"id":"随大溜","hanzi":"随大溜","pinyin":"suídàliù","meaning_vi":"theo số đông, a dua theo đám đông","explanation":"随 (tùy – theo) + 大溜 (đại lưu – dòng chảy lớn) → trôi theo dòng chính; nghĩa bóng là làm theo số đông, không có chủ kiến.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🐑","examples":[{"type":"basic","zh":"他做事总随大溜。","pinyin":"Tā zuòshì zǒng suídàliù.","vi":"Anh ấy làm gì cũng theo số đông."},{"type":"simple","zh":"选专业不能随大溜，要看自己的兴趣。","pinyin":"Xuǎn zhuānyè bù néng suídàliù, yào kàn zìjǐ de xìngqù.","vi":"Chọn ngành không thể chạy theo đám đông, phải dựa vào sở thích của mình."},{"type":"compound","zh":"如果你只会随大溜，就很难有自己的想法。","pinyin":"Rúguǒ nǐ zhǐ huì suídàliù, jiù hěn nán yǒu zìjǐ de xiǎngfǎ.","vi":"Nếu bạn chỉ biết a dua theo số đông thì khó có suy nghĩ riêng."}],"related":[{"hanzi":"随波逐流","pinyin":"suíbōzhúliú","vi":"trôi theo dòng"},{"hanzi":"从众","pinyin":"cóngzhòng","vi":"theo số đông"},{"hanzi":"跟风","pinyin":"gēnfēng","vi":"chạy theo trào lưu"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"}],"traditional":"隨大溜"},{"id":"随时随地","hanzi":"随时随地","pinyin":"suíshí-suídì","meaning_vi":"bất cứ lúc nào, bất cứ nơi đâu","explanation":"随时 (tùy thời – bất cứ lúc nào) + 随地 (tùy địa – bất cứ nơi nào) → mọi lúc mọi nơi.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌐","examples":[{"type":"basic","zh":"手机能随时随地上网。","pinyin":"Shǒu jīnéng suíshísuídì shàngwǎng.","vi":"Điện thoại có thể lên mạng mọi lúc mọi nơi."},{"type":"simple","zh":"有了这个软件，你可以随时随地学中文。","pinyin":"Yǒule zhè ge ruǎnjiàn, nǐ kěyǐ suíshísuídì xué Zhōngwén.","vi":"Có phần mềm này, bạn có thể học tiếng Trung mọi lúc mọi nơi."},{"type":"compound","zh":"即使工作再忙，他也随时随地带着一本书。","pinyin":"Jíshǐ gōngzuò zài máng, tā yě suíshísuídì dàizhe yì běn shū.","vi":"Dù công việc bận đến mấy, anh ấy vẫn luôn mang theo một cuốn sách bên mình."}],"related":[{"hanzi":"随时","pinyin":"suíshí","vi":"bất cứ lúc nào"},{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"},{"hanzi":"随地","pinyin":"suídì","vi":"bất cứ đâu"},{"hanzi":"无时无刻","pinyin":"wúshíwúkè","vi":"mọi lúc"}],"traditional":"隨時隨地"},{"id":"遂心","hanzi":"遂心","pinyin":"suìxīn","meaning_vi":"vừa lòng, như ý","explanation":"遂 (toại – thỏa, toại nguyện) + 心 (tâm – lòng) → hợp ý, thỏa lòng mong muốn.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"这件事办得很遂心。","pinyin":"Zhè jiàn shì bàn de hěn suìxīn.","vi":"Việc này làm rất vừa lòng."},{"type":"simple","zh":"终于买到遂心的房子，她很高兴。","pinyin":"Zhōngyú mǎi dào suìxīn de fángzi, tā hěn gāoxìng.","vi":"Cuối cùng mua được căn nhà ưng ý, cô ấy rất vui."},{"type":"compound","zh":"即使生活不能样样遂心，我们也要乐观面对。","pinyin":"Jíshǐ shēnghuó bù néng yàngyàng suìxīn, wǒmen yě yào lèguān miànduì.","vi":"Dù cuộc sống không thể việc gì cũng như ý, chúng ta vẫn phải lạc quan đối mặt."}],"related":[{"hanzi":"顺心","pinyin":"shùnxīn","vi":"vừa ý"},{"hanzi":"如意","pinyin":"rúyì","vi":"như ý"},{"hanzi":"称心","pinyin":"chènxīn","vi":"hài lòng"},{"hanzi":"遂愿","pinyin":"suìyuàn","vi":"toại nguyện"}]},{"id":"损","hanzi":"损","pinyin":"sǔn","meaning_vi":"tổn hại, hao tổn; (khẩu ngữ) cay độc, châm chọc","explanation":"损 (tổn – giảm, hại) → làm giảm, gây hại (损坏, 损失); khẩu ngữ: nói móc, cay nghiệt.","hsk_level":"7-9","tags":["dong-tu"],"image":"🩹","examples":[{"type":"basic","zh":"你说话太损了。","pinyin":"Nǐ shuōhuà tài sǔn le.","vi":"Bạn nói chuyện cay độc quá."},{"type":"simple","zh":"长时间看手机对眼睛有损。","pinyin":"Cháng shíjiān kàn shǒujī duì yǎnjing yǒusǔn.","vi":"Xem điện thoại lâu có hại cho mắt."},{"type":"compound","zh":"虽然他喜欢损朋友，但是关键时刻总会帮忙。","pinyin":"Suīrán tā xǐhuan sǔn péngyou, dànshì guānjiànshíkè zǒng huì bāngmáng.","vi":"Tuy anh ấy thích châm chọc bạn bè, nhưng lúc quan trọng luôn ra tay giúp."}],"related":[{"hanzi":"损坏","pinyin":"sǔnhuài","vi":"hư hỏng"},{"hanzi":"损失","pinyin":"sǔnshī","vi":"tổn thất"},{"hanzi":"损害","pinyin":"sǔnhài","vi":"tổn hại"},{"hanzi":"受损","pinyin":"shòusǔn","vi":"bị hư hại"}],"traditional":"損"},{"id":"缩","hanzi":"缩","pinyin":"suō","meaning_vi":"co lại, rút lại, thu nhỏ","explanation":"缩 (súc – co lại) → co rút, thu nhỏ lại hoặc rụt về phía sau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🐢","examples":[{"type":"basic","zh":"乌龟把头缩回去了。","pinyin":"Wūguī bǎ tóu suō huíqù le.","vi":"Con rùa rụt đầu vào rồi."},{"type":"simple","zh":"天太冷，他缩着脖子走路。","pinyin":"Tiān tài lěng, tā suōzhe bózi zǒulù.","vi":"Trời lạnh quá, anh ấy rụt cổ bước đi."},{"type":"compound","zh":"如果把图片缩小一点，就能放进这一页了。","pinyin":"Rúguǒ bǎ túpiàn suōxiǎo yìdiǎn, jiù néng fàngjìn zhè yí yè le.","vi":"Nếu thu nhỏ ảnh một chút thì có thể đặt vừa trang này."}],"related":[{"hanzi":"缩小","pinyin":"suōxiǎo","vi":"thu nhỏ"},{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"},{"hanzi":"退缩","pinyin":"tuìsuō","vi":"chùn bước"},{"hanzi":"伸","pinyin":"shēn","vi":"duỗi ra"}],"traditional":"縮"},{"id":"缩水","hanzi":"缩水","pinyin":"suōshuǐ","meaning_vi":"co lại (khi giặt); (nghĩa bóng) bị thu hẹp, giảm","explanation":"缩 (súc – co) + 水 (thủy – nước) → vải co lại khi gặp nước; nghĩa bóng chỉ lợi nhuận, tài sản bị giảm.","hsk_level":"7-9","tags":["dong-tu"],"image":"👕","examples":[{"type":"basic","zh":"这件T恤缩水了。","pinyin":"Zhè jiàn T xù suō shuǐ le.","vi":"Chiếc áo phông này bị co rồi."},{"type":"simple","zh":"股市下跌，他的财产缩水了一半。","pinyin":"Gǔshì xiàdiē, tā de cáichǎn suōshuǐle yíbàn.","vi":"Chứng khoán giảm, tài sản của anh ấy teo mất một nửa."},{"type":"compound","zh":"如果用热水洗毛衣，它就很容易缩水。","pinyin":"Rúguǒ yòng rèshuǐ xǐ máoyī, tā jiù hěn róngyì suōshuǐ.","vi":"Nếu giặt áo len bằng nước nóng thì rất dễ bị co."}],"related":[{"hanzi":"缩小","pinyin":"suōxiǎo","vi":"thu nhỏ"},{"hanzi":"贬值","pinyin":"biǎnzhí","vi":"mất giá"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"giảm bớt"},{"hanzi":"膨胀","pinyin":"péngzhàng","vi":"phình ra"}],"traditional":"縮水"},{"id":"所谓","hanzi":"所谓","pinyin":"suǒwèi","meaning_vi":"cái gọi là, điều được gọi là","explanation":"所 (sở – cái mà) + 谓 (vị – gọi là) → cái được gọi là; dùng để giải thích khái niệm, hoặc tỏ ý không đồng tình (cái gọi là…).","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"❝","examples":[{"type":"basic","zh":"这就是所谓的代沟。","pinyin":"Zhè jiùshì suǒwèi de dàigōu.","vi":"Đây chính là cái gọi là khoảng cách thế hệ."},{"type":"simple","zh":"他所谓的专家其实什么都不懂。","pinyin":"Tā suǒwèi de zhuānjiā qíshí shénme dōu bù dǒng.","vi":"Cái gọi là chuyên gia của anh ta thực ra chẳng hiểu gì."},{"type":"compound","zh":"虽然他说得很好听，但是所谓的优惠根本不存在。","pinyin":"Suīrán tā shuō de hěn hǎotīng, dànshì suǒwèi de yōuhuì gēnběnbù cúnzài.","vi":"Tuy anh ta nói nghe rất hay, nhưng cái gọi là ưu đãi hoàn toàn không có."}],"related":[{"hanzi":"无所谓","pinyin":"wúsuǒwèi","vi":"không sao cả"},{"hanzi":"称为","pinyin":"chēngwéi","vi":"gọi là"},{"hanzi":"叫做","pinyin":"jiàozuò","vi":"gọi là"},{"hanzi":"所以","pinyin":"suǒyǐ","vi":"cho nên"}],"traditional":"所謂"},{"id":"他人","hanzi":"他人","pinyin":"tārén","meaning_vi":"người khác","explanation":"他 (tha – khác) + 人 (nhân – người) → người khác, kẻ khác; trang trọng hơn 别人.","hsk_level":"7-9","tags":["dai-tu","xa-hoi"],"image":"👥","examples":[{"type":"basic","zh":"不要随便打扰他人。","pinyin":"Bú yào suíbiàn dǎrǎo tārén.","vi":"Đừng tùy tiện làm phiền người khác."},{"type":"simple","zh":"我们应该尊重他人的选择。","pinyin":"Wǒmen yīnggāi zūnzhòng tārén de xuǎnzé.","vi":"Chúng ta nên tôn trọng lựa chọn của người khác."},{"type":"compound","zh":"如果你总是依赖他人，就永远学不会独立。","pinyin":"Rúguǒ nǐ zǒngshì yīlài tārén, jiù yǒngyuǎn xué bú huì dúlì.","vi":"Nếu lúc nào cũng dựa dẫm người khác, bạn sẽ mãi không học được tự lập."}],"related":[{"hanzi":"别人","pinyin":"biérén","vi":"người khác"},{"hanzi":"自己","pinyin":"zìjǐ","vi":"bản thân"},{"hanzi":"旁人","pinyin":"pángrén","vi":"người ngoài"},{"hanzi":"他们","pinyin":"tāmen","vi":"họ"}]},{"id":"拓宽","hanzi":"拓宽","pinyin":"tuòkuān","meaning_vi":"mở rộng, nới rộng","explanation":"拓 (thác – khai phá, mở) + 宽 (khoan – rộng) → làm cho rộng ra (đường sá, tầm nhìn, thị trường).","hsk_level":"7-9","tags":["dong-tu"],"image":"↔️","examples":[{"type":"basic","zh":"这条路要拓宽了。","pinyin":"Zhè tiáo lù yào tuòkuān le.","vi":"Con đường này sắp được mở rộng."},{"type":"simple","zh":"读书可以拓宽我们的视野。","pinyin":"Dúshū kěyǐ tuòkuān wǒmen de shìyě.","vi":"Đọc sách có thể mở rộng tầm nhìn của chúng ta."},{"type":"compound","zh":"只要拓宽销售渠道，产品就能卖到更多地方。","pinyin":"Zhǐyào tuòkuān xiāoshòu qúdào, chǎnpǐn jiù néng mài dào gèng duō dìfang.","vi":"Chỉ cần mở rộng kênh bán hàng, sản phẩm sẽ bán được ở nhiều nơi hơn."}],"related":[{"hanzi":"开拓","pinyin":"kāituò","vi":"khai thác"},{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"拓展","pinyin":"tuòzhǎn","vi":"mở mang"},{"hanzi":"宽阔","pinyin":"kuānkuò","vi":"rộng rãi"}],"traditional":"拓寬"},{"id":"踏上","hanzi":"踏上","pinyin":"tàshàng","meaning_vi":"đặt chân lên, bước lên","explanation":"踏 (đạp – giẫm, bước) + 上 (thượng – lên) → bước chân lên; nghĩa bóng là bắt đầu một hành trình (踏上征程).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"👣","examples":[{"type":"basic","zh":"他踏上了归途。","pinyin":"Tā tàshàngle guītú.","vi":"Anh ấy đã lên đường trở về."},{"type":"simple","zh":"这是我第一次踏上中国的土地。","pinyin":"Zhè shì wǒ dìyīcì tàshàng Zhōngguó de tǔdì.","vi":"Đây là lần đầu tôi đặt chân lên đất Trung Quốc."},{"type":"compound","zh":"虽然前路很艰难，但是他还是勇敢地踏上了创业之路。","pinyin":"Suīrán qiánlù hěn jiānnán, dànshì tā háishì yǒnggǎn de tàshàngle chuàngyè zhī lù.","vi":"Tuy con đường phía trước gian nan, anh ấy vẫn dũng cảm bước vào con đường khởi nghiệp."}],"related":[{"hanzi":"踏实","pinyin":"tāshi","vi":"chắc chắn, vững vàng"},{"hanzi":"登上","pinyin":"dēngshàng","vi":"leo lên"},{"hanzi":"走上","pinyin":"zǒushàng","vi":"bước lên"},{"hanzi":"启程","pinyin":"qǐchéng","vi":"khởi hành"}]},{"id":"胎","hanzi":"胎","pinyin":"tāi","meaning_vi":"thai; lứa; lốp xe","explanation":"胎 (thai – bào thai) → bào thai trong bụng mẹ; lượng từ chỉ lứa sinh; cũng chỉ lốp xe (轮胎).","hsk_level":"7-9","tags":["danh-tu"],"image":"🛞","examples":[{"type":"basic","zh":"她怀了第二胎。","pinyin":"Tā huáile dì èrtāi.","vi":"Cô ấy mang thai lần thứ hai."},{"type":"simple","zh":"我的自行车后胎没气了。","pinyin":"Wǒ de zìxíngchē hòu tāi méi qì le.","vi":"Lốp sau xe đạp của tôi xẹp rồi."},{"type":"compound","zh":"因为这只狗一胎生了六只小狗，所以主人忙坏了。","pinyin":"Yīnwèi zhè zhī gǒu yì tāishēngle liù zhī xiǎogǒu, suǒyǐ zhǔrén máng huàile.","vi":"Vì con chó này đẻ một lứa sáu con nên chủ bận tối mắt."}],"related":[{"hanzi":"胎儿","pinyin":"tāi'ér","vi":"thai nhi"},{"hanzi":"轮胎","pinyin":"lúntāi","vi":"lốp xe"},{"hanzi":"怀胎","pinyin":"huáitāi","vi":"mang thai"},{"hanzi":"双胞胎","pinyin":"shuāngbāotāi","vi":"sinh đôi"}]},{"id":"胎儿","hanzi":"胎儿","pinyin":"tāi'ér","meaning_vi":"thai nhi","explanation":"胎 (thai – bào thai) + 儿 (nhi – con) → đứa con còn trong bụng mẹ.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🤰","examples":[{"type":"basic","zh":"胎儿发育正常。","pinyin":"Tāi'ér fāyù zhèngcháng.","vi":"Thai nhi phát triển bình thường."},{"type":"simple","zh":"孕妇抽烟会影响胎儿的健康。","pinyin":"Yùnfù chōuyān huì yǐngxiǎng tāi'ér de jiànkāng.","vi":"Bà bầu hút thuốc sẽ ảnh hưởng sức khỏe thai nhi."},{"type":"compound","zh":"如果孕期营养不够，胎儿就可能长得太小。","pinyin":"Rúguǒ yùnqī yíngyǎng búgòu, tāi'ér jiù kěnéng zhǎngde tài xiǎo.","vi":"Nếu thai kỳ không đủ dinh dưỡng, thai nhi có thể phát triển quá nhỏ."}],"related":[{"hanzi":"孕妇","pinyin":"yùnfù","vi":"bà bầu"},{"hanzi":"怀孕","pinyin":"huáiyùn","vi":"mang thai"},{"hanzi":"婴儿","pinyin":"yīng'ér","vi":"trẻ sơ sinh"},{"hanzi":"胎","pinyin":"tāi","vi":"thai"}],"traditional":"胎兒"},{"id":"台球","hanzi":"台球","pinyin":"táiqiú","meaning_vi":"bi-a","explanation":"台 (đài – bàn) + 球 (cầu – bóng) → môn chơi bóng trên bàn, tức bi-a.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🎱","examples":[{"type":"basic","zh":"我们去打台球吧。","pinyin":"Wǒmen qù dǎ táiqiú ba.","vi":"Chúng ta đi chơi bi-a đi."},{"type":"simple","zh":"他周末常和朋友去台球厅。","pinyin":"Tā zhōumò cháng hé péngyou qù táiqiú tīng.","vi":"Cuối tuần anh ấy thường cùng bạn đến quán bi-a."},{"type":"compound","zh":"虽然他打台球的时间不长，但是技术进步得很快。","pinyin":"Suīrán tā dǎ táiqiú de shíjiān bù cháng, dànshì jìshù jìnbù de hěn kuài.","vi":"Tuy chơi bi-a chưa lâu, nhưng kỹ thuật của anh ấy tiến bộ rất nhanh."}],"related":[{"hanzi":"球杆","pinyin":"qiúgān","vi":"cơ bi-a"},{"hanzi":"斯诺克","pinyin":"sīnuòkè","vi":"snooker"},{"hanzi":"保龄球","pinyin":"bǎolíngqiú","vi":"bowling"},{"hanzi":"乒乓球","pinyin":"pīngpāngqiú","vi":"bóng bàn"}],"traditional":"檯球"},{"id":"太极","hanzi":"太极","pinyin":"Tàijí","meaning_vi":"thái cực; thái cực quyền","explanation":"太 (thái – rất, tột cùng) + 极 (cực – cực điểm) → Thái Cực, nguồn gốc vạn vật trong triết học cổ; thường chỉ 太极拳 (thái cực quyền).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"☯️","examples":[{"type":"basic","zh":"爷爷每天打太极。","pinyin":"Yéye měitiān dǎtàijí.","vi":"Ông ngày nào cũng tập thái cực quyền."},{"type":"simple","zh":"公园里很多老人在练太极拳。","pinyin":"Gōngyuán lǐ hěn duō lǎorén zài liàn tàijíquán.","vi":"Trong công viên nhiều cụ già đang tập thái cực quyền."},{"type":"compound","zh":"虽然太极的动作很慢，但是对身体很有好处。","pinyin":"Suīrán Tàijí de dòngzuò hěn màn, dànshì duì shēntǐ hěn yǒu hǎochù.","vi":"Tuy động tác thái cực rất chậm, nhưng rất có lợi cho sức khỏe."}],"related":[{"hanzi":"太极拳","pinyin":"tàijíquán","vi":"thái cực quyền"},{"hanzi":"阴阳","pinyin":"yīnyáng","vi":"âm dương"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"võ thuật"},{"hanzi":"八卦","pinyin":"bāguà","vi":"bát quái"}],"traditional":"太極"},{"id":"太平","hanzi":"太平","pinyin":"tàipíng","meaning_vi":"thái bình, yên ổn","explanation":"太 (thái – rất, lớn) + 平 (bình – yên ổn) → yên ổn, không có chiến tranh, loạn lạc; cũng dùng làm địa danh.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"天下太平。","pinyin":"Tiānxià tàipíng.","vi":"Thiên hạ thái bình."},{"type":"simple","zh":"老百姓都希望过太平日子。","pinyin":"Lǎobǎixìng dōu xīwàngguò tàipíng rìzi.","vi":"Người dân đều mong sống những ngày thái bình."},{"type":"compound","zh":"虽然现在看起来很太平，但是我们不能放松警惕。","pinyin":"Suīrán xiànzài kànqǐlái hěn tàipíng, dànshì wǒmen bù néng fàngsōng jǐngtì.","vi":"Tuy giờ trông có vẻ yên ổn, nhưng chúng ta không được lơ là cảnh giác."}],"related":[{"hanzi":"和平","pinyin":"hépíng","vi":"hòa bình"},{"hanzi":"平安","pinyin":"píng'ān","vi":"bình an"},{"hanzi":"安宁","pinyin":"ānníng","vi":"yên bình"},{"hanzi":"战乱","pinyin":"zhànluàn","vi":"loạn lạc"}]},{"id":"贪","hanzi":"贪","pinyin":"tān","meaning_vi":"tham, tham lam; ham","explanation":"贪 (tham – tham lam) → ham muốn quá mức (tiền bạc, ăn chơi); cũng chỉ tham nhũng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤑","examples":[{"type":"basic","zh":"做人不能太贪。","pinyin":"Zuòrén bù néng tài tān.","vi":"Làm người không được quá tham."},{"type":"simple","zh":"他贪便宜买了一堆没用的东西。","pinyin":"Tā tānpiányi mǎile yìduī méiyòng de dōngxi.","vi":"Anh ta ham rẻ mua một đống đồ vô dụng."},{"type":"compound","zh":"如果官员贪钱，老百姓就不会信任政府。","pinyin":"Rúguǒ guānyuán tān qián, lǎobǎixìng jiù bú huì xìnrèn zhèngfǔ.","vi":"Nếu quan chức tham tiền, người dân sẽ không tin chính quyền."}],"related":[{"hanzi":"贪心","pinyin":"tānxīn","vi":"lòng tham"},{"hanzi":"贪婪","pinyin":"tānlán","vi":"tham lam"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"贪玩","pinyin":"tānwán","vi":"ham chơi"}],"traditional":"貪"},{"id":"贪玩儿","hanzi":"贪玩儿","pinyin":"tānwánr","meaning_vi":"ham chơi","explanation":"贪 (tham – ham) + 玩儿 (ngoạn – chơi) → mải chơi, ham chơi hơn học hay làm.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🎮","examples":[{"type":"basic","zh":"这孩子太贪玩儿。","pinyin":"Zhè háizi tài tānwánr.","vi":"Đứa trẻ này ham chơi quá."},{"type":"simple","zh":"他小时候很贪玩儿，常常忘了写作业。","pinyin":"Tā xiǎoshíhou hěn tānwánr, chángcháng wàngle xiě zuòyè.","vi":"Hồi nhỏ cậu ấy rất ham chơi, thường quên làm bài tập."},{"type":"compound","zh":"虽然弟弟有点贪玩儿，但是考试成绩一直不错。","pinyin":"Suīrán dìdi yǒudiǎn tānwánr, dànshì kǎoshì chéngjì yìzhí búcuò.","vi":"Tuy em trai hơi ham chơi, nhưng điểm thi luôn khá tốt."}],"related":[{"hanzi":"贪","pinyin":"tān","vi":"ham"},{"hanzi":"玩耍","pinyin":"wánshuǎ","vi":"vui chơi"},{"hanzi":"淘气","pinyin":"táoqì","vi":"nghịch ngợm"},{"hanzi":"用功","pinyin":"yònggōng","vi":"chăm chỉ"}],"traditional":"貪玩兒"},{"id":"瘫","hanzi":"瘫","pinyin":"tān","meaning_vi":"bại liệt; mềm nhũn, rã rời","explanation":"瘫 (than – tê liệt) → liệt, mất khả năng cử động; khẩu ngữ chỉ mệt rã rời, nằm vật ra; 瘫痪 cũng dùng cho hệ thống tê liệt.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🦽","examples":[{"type":"basic","zh":"他累得瘫在沙发上。","pinyin":"Tā lèi de tān zài shāfā shàng.","vi":"Anh ấy mệt đến nằm vật ra sofa."},{"type":"simple","zh":"爷爷中风后半身瘫了。","pinyin":"Yéye zhòngfēng hòubàn shēn tān le.","vi":"Ông bị đột quỵ nên liệt nửa người."},{"type":"compound","zh":"因为暴雪太大，所以全市交通几乎瘫了。","pinyin":"Yīnwèi bàoxuě tài dà, suǒyǐ quánshì jiāotōng jīhū tān le.","vi":"Vì bão tuyết quá lớn nên giao thông toàn thành phố gần như tê liệt."}],"related":[{"hanzi":"瘫痪","pinyin":"tānhuàn","vi":"bại liệt, tê liệt"},{"hanzi":"软","pinyin":"ruǎn","vi":"mềm"},{"hanzi":"中风","pinyin":"zhòngfēng","vi":"đột quỵ"},{"hanzi":"残疾","pinyin":"cánjí","vi":"tàn tật"}],"traditional":"癱"},{"id":"坛","hanzi":"坛","pinyin":"tán","meaning_vi":"đàn, đàn tế; giới (văn đàn); hũ, vò","explanation":"坛 (đàn – nền cao để tế lễ) → đàn tế, diễn đàn; chỉ giới, lĩnh vực (文坛, 体坛); cũng là hũ, vò và lượng từ 'vò'.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏺","examples":[{"type":"basic","zh":"他买了一坛酒。","pinyin":"Tā mǎile yì tán jiǔ.","vi":"Anh ấy mua một vò rượu."},{"type":"simple","zh":"北京的天坛是古代皇帝祭天的地方。","pinyin":"Běijīng de Tiāntán shì gǔdài huángdì jìtiān de dìfang.","vi":"Thiên Đàn ở Bắc Kinh là nơi vua chúa xưa tế trời."},{"type":"compound","zh":"虽然他刚进入文坛不久，但是作品已经很受欢迎。","pinyin":"Suīrán tā gāng jìnrù wéntán bùjiǔ, dànshì zuòpǐn yǐjīng hěn shòuhuānyíng.","vi":"Tuy mới bước vào văn đàn chưa lâu, nhưng tác phẩm của anh ấy đã rất được yêu thích."}],"related":[{"hanzi":"论坛","pinyin":"lùntán","vi":"diễn đàn"},{"hanzi":"文坛","pinyin":"wéntán","vi":"văn đàn"},{"hanzi":"体坛","pinyin":"tǐtán","vi":"giới thể thao"},{"hanzi":"花坛","pinyin":"huātán","vi":"bồn hoa"}],"traditional":"壇"},{"id":"谈不上","hanzi":"谈不上","pinyin":"tánbushàng","meaning_vi":"chưa nói đến, chẳng đến mức","explanation":"谈 (đàm – nói) + 不上 (không tới) → không đến mức có thể nói là, còn xa mới gọi được là.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙅","examples":[{"type":"basic","zh":"这谈不上什么帮助。","pinyin":"Zhè tánbushàng shénme bāngzhù.","vi":"Cái này chẳng đáng gọi là giúp đỡ gì."},{"type":"simple","zh":"我只是会做几个菜，谈不上是厨师。","pinyin":"Wǒ zhǐshì huì zuò jǐ gè cài, tánbushàng shì chúshī.","vi":"Tôi chỉ biết nấu vài món, chưa thể gọi là đầu bếp."},{"type":"compound","zh":"如果连饭都吃不饱，就谈不上什么享受了。","pinyin":"Rúguǒ lián fàn dōu chībubǎo, jiù tánbushàng shénme xiǎngshòu le.","vi":"Nếu đến cơm còn chưa đủ no thì nói gì đến hưởng thụ."}],"related":[{"hanzi":"说不上","pinyin":"shuōbushàng","vi":"khó nói, chưa đến mức"},{"hanzi":"算不上","pinyin":"suànbushàng","vi":"chẳng tính là"},{"hanzi":"谈得上","pinyin":"tándeshàng","vi":"có thể nói là"},{"hanzi":"何况","pinyin":"hékuàng","vi":"huống hồ"}],"traditional":"談不上"},{"id":"谈到","hanzi":"谈到","pinyin":"tándào","meaning_vi":"nói đến, nhắc đến, đề cập","explanation":"谈 (đàm – nói chuyện) + 到 (đáo – đến) → nói đến, đề cập tới một chủ đề.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗨️","examples":[{"type":"basic","zh":"他谈到了他的家乡。","pinyin":"Tā tándàole tā de jiāxiāng.","vi":"Anh ấy nhắc đến quê hương mình."},{"type":"simple","zh":"一谈到足球，他就特别兴奋。","pinyin":"Yì tándào zúqiú, tā jiù tèbié xīngfèn.","vi":"Hễ nói đến bóng đá là anh ấy đặc biệt hào hứng."},{"type":"compound","zh":"虽然会上谈到了很多问题，但是都没有找到解决办法。","pinyin":"Suīrán huì shàng tándàole hěn duō wèntí, dànshì dōu méiyǒu zhǎodào jiějué bànfǎ.","vi":"Tuy cuộc họp đề cập nhiều vấn đề, nhưng chưa tìm được cách giải quyết nào."}],"related":[{"hanzi":"谈起","pinyin":"tánqǐ","vi":"nhắc tới"},{"hanzi":"提到","pinyin":"tídào","vi":"đề cập"},{"hanzi":"说到","pinyin":"shuōdào","vi":"nói đến"},{"hanzi":"谈论","pinyin":"tánlùn","vi":"bàn luận"}],"traditional":"談到"},{"id":"谈论","hanzi":"谈论","pinyin":"tánlùn","meaning_vi":"bàn luận, bàn tán","explanation":"谈 (đàm – nói chuyện) + 论 (luận – bàn) → cùng nhau nói và bàn về một chuyện.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👥","examples":[{"type":"basic","zh":"大家都在谈论这件事。","pinyin":"Dàjiā dōu zài tánlùn zhè jiàn shì.","vi":"Mọi người đều đang bàn tán việc này."},{"type":"simple","zh":"我们在午饭时谈论了新电影。","pinyin":"Wǒmen zài wǔfàn shí tánlùnle xīn diànyǐng.","vi":"Chúng tôi bàn về bộ phim mới trong bữa trưa."},{"type":"compound","zh":"即使你不同意，也不要在背后谈论别人。","pinyin":"Jíshǐ nǐ bù tóngyì, yě bú yào zài bèihòu tánlùn biérén.","vi":"Dù bạn không đồng ý, cũng đừng bàn tán về người khác sau lưng."}],"related":[{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"},{"hanzi":"议论","pinyin":"yìlùn","vi":"bàn tán"},{"hanzi":"谈话","pinyin":"tánhuà","vi":"nói chuyện"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"}],"traditional":"談論"},{"id":"谈起","hanzi":"谈起","pinyin":"tánqǐ","meaning_vi":"nhắc tới, kể về","explanation":"谈 (đàm – nói) + 起 (khởi – bắt đầu) → bắt đầu nói đến, nhắc lại chuyện gì.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他很少谈起过去。","pinyin":"Tā hěn shǎo tánqǐ guòqù.","vi":"Anh ấy ít khi nhắc tới quá khứ."},{"type":"simple","zh":"奶奶常常谈起她年轻时的故事。","pinyin":"Nǎinai chángcháng tánqǐ tā niánqīng shí de gùshi.","vi":"Bà thường kể về chuyện thời trẻ của bà."},{"type":"compound","zh":"每次谈起那场比赛，他都会激动得说不出话。","pinyin":"Měi cì tánqǐ nà chǎng bǐsài, tā dōuhuì jīdòng de shuōbuchū huà.","vi":"Mỗi lần nhắc tới trận đấu đó, anh ấy đều xúc động đến nghẹn lời."}],"related":[{"hanzi":"谈到","pinyin":"tándào","vi":"nói đến"},{"hanzi":"提起","pinyin":"tíqǐ","vi":"nhắc đến"},{"hanzi":"说起","pinyin":"shuōqǐ","vi":"nói về"},{"hanzi":"回忆","pinyin":"huíyì","vi":"hồi tưởng"}],"traditional":"談起"},{"id":"痰","hanzi":"痰","pinyin":"tán","meaning_vi":"đờm","explanation":"痰 (đàm – đờm) → chất nhầy tiết ra từ đường hô hấp; 吐痰 là khạc nhổ.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🤧","examples":[{"type":"basic","zh":"请勿随地吐痰。","pinyin":"Qǐngwù suídì tǔtán.","vi":"Xin đừng khạc nhổ bừa bãi."},{"type":"simple","zh":"他感冒了，嗓子里总是有痰。","pinyin":"Tā gǎnmào le, sǎngzi lǐ zǒngshì yǒu tán.","vi":"Anh ấy bị cảm, trong cổ họng lúc nào cũng có đờm."},{"type":"compound","zh":"如果咳嗽一直有黄痰，就最好去医院检查。","pinyin":"Rúguǒ késou yìzhí yǒu huáng tán, jiù zuìhǎo qù yīyuàn jiǎnchá.","vi":"Nếu ho mãi có đờm vàng thì tốt nhất nên đi viện khám."}],"related":[{"hanzi":"吐痰","pinyin":"tǔtán","vi":"khạc nhổ"},{"hanzi":"咳嗽","pinyin":"késou","vi":"ho"},{"hanzi":"化痰","pinyin":"huàtán","vi":"long đờm"},{"hanzi":"嗓子","pinyin":"sǎngzi","vi":"cổ họng"}]},{"id":"坦克","hanzi":"坦克","pinyin":"tǎnkè","meaning_vi":"xe tăng","explanation":"坦克 (thản khắc) → từ phiên âm tiếng Anh 'tank', chỉ xe tăng quân sự.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🪖","examples":[{"type":"basic","zh":"坦克开进了城里。","pinyin":"Tǎnkè kāi jìnle chénglǐ.","vi":"Xe tăng đã tiến vào thành phố."},{"type":"simple","zh":"博物馆门口停着一辆旧坦克。","pinyin":"Bówùguǎn ménkǒu tíngzhe yí liàng jiù tǎnkè.","vi":"Trước cửa bảo tàng có đặt một chiếc xe tăng cũ."},{"type":"compound","zh":"虽然坦克很坚固，但是在山区里很难行动。","pinyin":"Suīrán tǎnkè hěn jiāngù, dànshì zài shānqū lǐ hěn nán xíngdòng.","vi":"Tuy xe tăng rất kiên cố, nhưng rất khó di chuyển ở vùng núi."}],"related":[{"hanzi":"装甲车","pinyin":"zhuāngjiǎchē","vi":"xe bọc thép"},{"hanzi":"大炮","pinyin":"dàpào","vi":"đại bác"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"},{"hanzi":"武器","pinyin":"wǔqì","vi":"vũ khí"}]},{"id":"坦然","hanzi":"坦然","pinyin":"tǎnrán","meaning_vi":"thản nhiên, bình thản","explanation":"坦 (thản – bằng phẳng, thẳng thắn) + 然 (nhiên – dáng vẻ) → lòng thanh thản, không lo lắng hay áy náy.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"他坦然地笑了。","pinyin":"Tā tǎnrán de xiào le.","vi":"Anh ấy thản nhiên mỉm cười."},{"type":"simple","zh":"面对失败，她表现得很坦然。","pinyin":"Miànduì shībài, tā biǎoxiàn de hěn tǎnrán.","vi":"Đối diện thất bại, cô ấy tỏ ra rất bình thản."},{"type":"compound","zh":"只要问心无愧，你就可以坦然面对别人的批评。","pinyin":"Zhǐyào wènxīnwúkuì, nǐ jiù kěyǐ tǎnrán miànduì biérén de pīpíng.","vi":"Chỉ cần không thẹn với lòng, bạn có thể bình thản đối mặt lời phê bình của người khác."}],"related":[{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thẳng thắn"},{"hanzi":"平静","pinyin":"píngjìng","vi":"bình tĩnh"},{"hanzi":"镇定","pinyin":"zhèndìng","vi":"điềm tĩnh"},{"hanzi":"不安","pinyin":"bù'ān","vi":"bất an"}]},{"id":"毯子","hanzi":"毯子","pinyin":"tǎnzi","meaning_vi":"chăn, mền, thảm","explanation":"毯 (thảm – thảm, chăn len) + 子 (tử – hậu tố) → tấm chăn dày hoặc tấm thảm.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🛏️","examples":[{"type":"basic","zh":"给我一条毯子。","pinyin":"Gěi wǒ yì tiáo tǎnzi.","vi":"Cho tôi một cái chăn."},{"type":"simple","zh":"飞机上有点冷，我盖上了毯子。","pinyin":"Fēijī shàng yǒudiǎn lěng, wǒ gàishàngle tǎnzi.","vi":"Trên máy bay hơi lạnh, tôi đắp chăn lên."},{"type":"compound","zh":"如果晚上降温，你就多盖一条毯子。","pinyin":"Rúguǒ wǎnshang jiàngwēn, nǐ jiù duō gài yì tiáo tǎnzi.","vi":"Nếu buổi tối trời trở lạnh, bạn đắp thêm một cái chăn."}],"related":[{"hanzi":"被子","pinyin":"bèizi","vi":"chăn"},{"hanzi":"地毯","pinyin":"dìtǎn","vi":"thảm trải sàn"},{"hanzi":"枕头","pinyin":"zhěntou","vi":"gối"},{"hanzi":"床单","pinyin":"chuángdān","vi":"ga trải giường"}]},{"id":"炭","hanzi":"炭","pinyin":"tàn","meaning_vi":"than củi","explanation":"炭 (thán – than) → than củi do đốt gỗ tạo thành, dùng làm nhiên liệu; 木炭, 炭火.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔥","examples":[{"type":"basic","zh":"炉子里的炭烧红了。","pinyin":"Lúzi lǐ de tàn shāohóng le.","vi":"Than trong lò đã cháy đỏ."},{"type":"simple","zh":"烤肉要用炭火才香。","pinyin":"Kǎoròu yào yòng tànhuǒ cái xiāng.","vi":"Thịt nướng phải dùng lửa than mới thơm."},{"type":"compound","zh":"如果在屋里烧炭不开窗，就可能会中毒。","pinyin":"Rúguǒ zài wū lǐ shāotàn bù kāi chuāng, jiù kěnéng huì zhòngdú.","vi":"Nếu đốt than trong nhà mà không mở cửa sổ thì có thể bị ngộ độc."}],"related":[{"hanzi":"木炭","pinyin":"mùtàn","vi":"than củi"},{"hanzi":"煤","pinyin":"méi","vi":"than đá"},{"hanzi":"炭火","pinyin":"tànhuǒ","vi":"lửa than"},{"hanzi":"碳","pinyin":"tàn","vi":"các-bon"}]},{"id":"探","hanzi":"探","pinyin":"tàn","meaning_vi":"dò, thăm dò; thăm; thò ra","explanation":"探 (thám – dò xét) → tìm tòi, dò thám; đi thăm (探病); thò đầu, người ra (探头).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔦","examples":[{"type":"basic","zh":"他探出头来看。","pinyin":"Tā tàn chūtóu lái kàn.","vi":"Anh ấy thò đầu ra nhìn."},{"type":"simple","zh":"周末我们去医院探病。","pinyin":"Zhōumò wǒmen qù yīyuàn tànbìng.","vi":"Cuối tuần chúng tôi vào viện thăm bệnh."},{"type":"compound","zh":"如果你不确定他的态度，就先去探探口风。","pinyin":"Rúguǒ nǐ bú quèdìng tā de tàidù, jiù xiān qù tàn tankǒufēng.","vi":"Nếu bạn chưa chắc thái độ của anh ấy thì hãy đi thăm dò ý tứ trước."}],"related":[{"hanzi":"探索","pinyin":"tànsuǒ","vi":"thăm dò, khám phá"},{"hanzi":"探望","pinyin":"tànwàng","vi":"thăm hỏi"},{"hanzi":"侦探","pinyin":"zhēntàn","vi":"thám tử"},{"hanzi":"试探","pinyin":"shìtàn","vi":"dò ý"}]},{"id":"探亲","hanzi":"探亲","pinyin":"tànqīn","meaning_vi":"về thăm người thân","explanation":"探 (thám – thăm) + 亲 (thân – người thân) → đi thăm gia đình, họ hàng (thường ở xa).","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🏡","examples":[{"type":"basic","zh":"他回老家探亲了。","pinyin":"Tā huílǎojiā tànqīn le.","vi":"Anh ấy về quê thăm người thân rồi."},{"type":"simple","zh":"春节期间很多人坐火车回家探亲。","pinyin":"Chūnjié qījiān hěn duō rén zuò huǒchē huíjiā tànqīn.","vi":"Dịp Tết nhiều người đi tàu về nhà thăm gia đình."},{"type":"compound","zh":"因为工作太忙，所以他两年没回家探亲了。","pinyin":"Yīnwèi gōngzuò tài máng, suǒyǐ tā liǎng nián méi huíjiā tànqīn le.","vi":"Vì công việc quá bận nên hai năm rồi anh ấy chưa về thăm nhà."}],"related":[{"hanzi":"探望","pinyin":"tànwàng","vi":"thăm hỏi"},{"hanzi":"亲戚","pinyin":"qīnqi","vi":"họ hàng"},{"hanzi":"回家","pinyin":"huíjiā","vi":"về nhà"},{"hanzi":"看望","pinyin":"kànwàng","vi":"đi thăm"}],"traditional":"探親"},{"id":"碳","hanzi":"碳","pinyin":"tàn","meaning_vi":"các-bon (nguyên tố C)","explanation":"碳 (thán – nguyên tố các-bon) → nguyên tố hóa học C; hay gặp 低碳 ít các-bon, 碳排放 phát thải các-bon.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚛️","examples":[{"type":"basic","zh":"钻石是由碳组成的。","pinyin":"Zuànshí shì yóu tàn zǔchéng de.","vi":"Kim cương được cấu tạo từ các-bon."},{"type":"simple","zh":"我们要减少二氧化碳的排放。","pinyin":"Wǒmen yào jiǎnshǎo èryǎnghuàtàn de páifàng.","vi":"Chúng ta phải giảm phát thải khí CO2."},{"type":"compound","zh":"如果大家都选择低碳出行，空气就会更干净。","pinyin":"Rúguǒ dàjiā dōu xuǎnzé dītàn chūxíng, kōngqì jiù huì gèng gānjìng.","vi":"Nếu mọi người đều chọn đi lại ít phát thải, không khí sẽ sạch hơn."}],"related":[{"hanzi":"二氧化碳","pinyin":"èryǎnghuàtàn","vi":"khí CO2"},{"hanzi":"低碳","pinyin":"dītàn","vi":"ít các-bon"},{"hanzi":"炭","pinyin":"tàn","vi":"than củi"},{"hanzi":"氧","pinyin":"yǎng","vi":"ô-xy"}]},{"id":"汤圆","hanzi":"汤圆","pinyin":"tāngyuán","meaning_vi":"bánh trôi nước, chè trôi","explanation":"汤 (thang – canh, nước) + 圆 (viên – tròn) → viên bột nếp tròn có nhân, luộc trong nước; ăn vào Tết Nguyên Tiêu.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍡","examples":[{"type":"basic","zh":"元宵节吃汤圆。","pinyin":"Yuánxiāojié chī tāngyuán.","vi":"Tết Nguyên Tiêu ăn bánh trôi."},{"type":"simple","zh":"妈妈做的芝麻汤圆特别甜。","pinyin":"Māma zuò de zhīma tāngyuán tèbié tián.","vi":"Bánh trôi nhân vừng mẹ làm đặc biệt ngọt."},{"type":"compound","zh":"虽然汤圆很好吃，但是吃多了不容易消化。","pinyin":"Suīrán tāngyuán hěn hǎochī, dànshì chī duōle bù róngyì xiāohuà.","vi":"Tuy bánh trôi rất ngon, nhưng ăn nhiều sẽ khó tiêu."}],"related":[{"hanzi":"元宵","pinyin":"yuánxiāo","vi":"bánh nguyên tiêu"},{"hanzi":"饺子","pinyin":"jiǎozi","vi":"sủi cảo"},{"hanzi":"元宵节","pinyin":"Yuánxiāojié","vi":"Tết Nguyên Tiêu"},{"hanzi":"糯米","pinyin":"nuòmǐ","vi":"gạo nếp"}],"traditional":"湯圓"},{"id":"堂","hanzi":"堂","pinyin":"táng","meaning_vi":"sảnh, gian nhà lớn; họ (bên nội); tiết (học)","explanation":"堂 (đường – gian nhà chính) → phòng lớn (礼堂, 食堂); chỉ quan hệ anh em họ bên nội (堂哥); lượng từ cho tiết học.","hsk_level":"7-9","tags":["luong-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"今天有两堂课。","pinyin":"Jīntiān yǒu liǎng táng kè.","vi":"Hôm nay có hai tiết học."},{"type":"simple","zh":"他是我的堂哥，比我大三岁。","pinyin":"Tā shì wǒ de tánggē, bǐ wǒ dàsān suì.","vi":"Anh ấy là anh họ bên nội của tôi, hơn tôi ba tuổi."},{"type":"compound","zh":"虽然这堂课只有四十分钟，但是我学到了很多。","pinyin":"Suīrán zhè táng kè zhǐyǒu sìshí fēnzhōng, dànshì wǒ xuédàole hěn duō.","vi":"Tuy tiết học này chỉ có 40 phút, nhưng tôi học được rất nhiều."}],"related":[{"hanzi":"食堂","pinyin":"shítáng","vi":"nhà ăn"},{"hanzi":"礼堂","pinyin":"lǐtáng","vi":"hội trường"},{"hanzi":"课堂","pinyin":"kètáng","vi":"lớp học"},{"hanzi":"堂兄弟","pinyin":"tángxiōngdì","vi":"anh em họ"}]},{"id":"糖果","hanzi":"糖果","pinyin":"tángguǒ","meaning_vi":"kẹo","explanation":"糖 (đường – đường) + 果 (quả – quả) → kẹo, đồ ngọt.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍬","examples":[{"type":"basic","zh":"孩子们喜欢糖果。","pinyin":"Háizimen xǐhuan tángguǒ.","vi":"Trẻ con thích kẹo."},{"type":"simple","zh":"过年时桌上摆满了各种糖果。","pinyin":"Guònián shí zhuō shàng bǎimǎnle gèzhǒng tángguǒ.","vi":"Dịp Tết trên bàn bày đầy đủ loại kẹo."},{"type":"compound","zh":"如果吃太多糖果，牙齿就会长蛀牙。","pinyin":"Rúguǒ chī tài duō tángguǒ, yáchǐ jiù huìzhǎng zhùyá.","vi":"Nếu ăn quá nhiều kẹo, răng sẽ bị sâu."}],"related":[{"hanzi":"巧克力","pinyin":"qiǎokèlì","vi":"sô-cô-la"},{"hanzi":"甜食","pinyin":"tiánshí","vi":"đồ ngọt"},{"hanzi":"零食","pinyin":"língshí","vi":"đồ ăn vặt"},{"hanzi":"棒棒糖","pinyin":"bàngbàngtáng","vi":"kẹo mút"}]},{"id":"淌","hanzi":"淌","pinyin":"tǎng","meaning_vi":"chảy, nhỏ giọt, tuôn","explanation":"淌 (thảng – chảy) → chất lỏng chảy xuống, nhỏ giọt (mồ hôi, nước mắt, nước).","hsk_level":"7-9","tags":["dong-tu"],"image":"💦","examples":[{"type":"basic","zh":"他满头淌汗。","pinyin":"Tā mǎn tóu tǎnghàn.","vi":"Anh ấy mồ hôi chảy đầy đầu."},{"type":"simple","zh":"听到这个消息，她的眼泪淌了下来。","pinyin":"Tīngdào zhè ge xiāoxi, tā de yǎnlèi tǎngle xiàlái.","vi":"Nghe tin này, nước mắt cô ấy tuôn rơi."},{"type":"compound","zh":"因为水龙头没关紧，所以水一直往下淌。","pinyin":"Yīnwèi shuǐlóngtóu méi guānjǐn, suǒyǐ shuǐ yìzhí wǎng xià tǎng.","vi":"Vì vòi nước chưa khóa chặt nên nước cứ nhỏ xuống mãi."}],"related":[{"hanzi":"流","pinyin":"liú","vi":"chảy"},{"hanzi":"滴","pinyin":"dī","vi":"nhỏ giọt"},{"hanzi":"流淌","pinyin":"liútǎng","vi":"chảy trôi"},{"hanzi":"淌汗","pinyin":"tǎnghàn","vi":"chảy mồ hôi"}]},{"id":"逃生","hanzi":"逃生","pinyin":"táoshēng","meaning_vi":"thoát thân, chạy thoát","explanation":"逃 (đào – chạy trốn) + 生 (sinh – sống) → chạy trốn để giữ mạng sống khi gặp nguy hiểm.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏃","examples":[{"type":"basic","zh":"他们成功逃生了。","pinyin":"Tāmen chénggōng táoshēng le.","vi":"Họ đã thoát thân thành công."},{"type":"simple","zh":"请记住大楼的逃生通道在哪里。","pinyin":"Qǐng jìzhù dàlóu de táoshēng tōngdào zài nǎlǐ.","vi":"Hãy nhớ lối thoát hiểm của tòa nhà ở đâu."},{"type":"compound","zh":"一旦发生火灾，就要用湿毛巾捂住口鼻逃生。","pinyin":"Yídàn fāshēng huǒzāi, jiùyào yòng shī máojīn wǔzhù kǒubí táoshēng.","vi":"Một khi xảy ra hỏa hoạn, phải dùng khăn ướt bịt miệng mũi để thoát ra."}],"related":[{"hanzi":"逃跑","pinyin":"táopǎo","vi":"chạy trốn"},{"hanzi":"逃亡","pinyin":"táowáng","vi":"lưu vong"},{"hanzi":"求生","pinyin":"qiúshēng","vi":"cầu sinh"},{"hanzi":"安全出口","pinyin":"ānquánchūkǒu","vi":"lối thoát hiểm"}]},{"id":"逃亡","hanzi":"逃亡","pinyin":"táowáng","meaning_vi":"bỏ trốn, lưu vong, đào tẩu","explanation":"逃 (đào – chạy trốn) + 亡 (vong – mất, bỏ đi) → bỏ trốn khỏi nơi cư trú, sống lẩn trốn.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🏃‍♂️","examples":[{"type":"basic","zh":"罪犯逃亡到了国外。","pinyin":"Zuìfàn táowáng dàole guówài.","vi":"Tội phạm đã đào tẩu ra nước ngoài."},{"type":"simple","zh":"他在外逃亡了五年才被抓住。","pinyin":"Tā zài wài táowángle wǔ nián cái bèi zhuāzhù.","vi":"Hắn lẩn trốn bên ngoài năm năm mới bị bắt."},{"type":"compound","zh":"虽然他逃亡了很多年，但是最后还是回来自首了。","pinyin":"Suīrán tā táowángle hěn duōnián, dànshì zuìhòu háishì huílái zìshǒu le.","vi":"Tuy đã bỏ trốn nhiều năm, nhưng cuối cùng hắn vẫn quay về đầu thú."}],"related":[{"hanzi":"逃跑","pinyin":"táopǎo","vi":"chạy trốn"},{"hanzi":"流亡","pinyin":"liúwáng","vi":"lưu vong"},{"hanzi":"逃犯","pinyin":"táofàn","vi":"kẻ đào tẩu"},{"hanzi":"逃生","pinyin":"táoshēng","vi":"thoát thân"}]},{"id":"淘","hanzi":"淘","pinyin":"táo","meaning_vi":"vo, đãi; lùng mua, săn (đồ); sàng lọc, đào thải","explanation":"淘 (đào – vo, đãi) → cho vào nước để rửa sạch, lọc (淘米); nghĩa mở rộng: tìm mua (淘宝), loại bỏ (淘汰).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧺","examples":[{"type":"basic","zh":"做饭前先淘米。","pinyin":"Zuòfàn qián xiān táomǐ.","vi":"Trước khi nấu cơm phải vo gạo."},{"type":"simple","zh":"她喜欢在旧货市场淘便宜货。","pinyin":"Tā xǐhuan zài jiùhuò shìchǎng táo piányihuò.","vi":"Cô ấy thích săn đồ rẻ ở chợ đồ cũ."},{"type":"compound","zh":"虽然淘金很辛苦，但是当年很多人都去了加州。","pinyin":"Suīrán táojīn hěn xīnkǔ, dànshì dāngnián hěn duō rén dōu qùle Jiāzhōu.","vi":"Tuy đãi vàng rất vất vả, nhưng năm đó nhiều người vẫn kéo đến California."}],"related":[{"hanzi":"淘汰","pinyin":"táotài","vi":"đào thải"},{"hanzi":"淘气","pinyin":"táoqì","vi":"nghịch ngợm"},{"hanzi":"淘米","pinyin":"táomǐ","vi":"vo gạo"},{"hanzi":"淘宝","pinyin":"Táobǎo","vi":"săn đồ"}]},{"id":"讨","hanzi":"讨","pinyin":"tǎo","meaning_vi":"đòi, xin; chuốc lấy; thảo phạt","explanation":"讨 (thảo – đòi, xét, đánh dẹp) → đòi hỏi (讨债), xin (讨饭); chuốc lấy, gây ra (讨人厌); xưa là đem quân đánh dẹp.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙋","examples":[{"type":"basic","zh":"他去讨债了。","pinyin":"Tā qù tǎozhài le.","vi":"Anh ấy đi đòi nợ rồi."},{"type":"simple","zh":"别做这种讨人厌的事。","pinyin":"Bié zuò zhè zhǒng tǎorényàn de shì.","vi":"Đừng làm những việc khiến người ta ghét như thế."},{"type":"compound","zh":"如果你一直迟到，就是自讨苦吃。","pinyin":"Rúguǒ nǐ yìzhí chídào, jiùshì zì tǎo kǔ chī.","vi":"Nếu bạn cứ đi muộn mãi thì là tự chuốc khổ vào thân."}],"related":[{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"},{"hanzi":"讨厌","pinyin":"tǎoyàn","vi":"ghét"},{"hanzi":"讨价还价","pinyin":"tǎojiàhuánjià","vi":"mặc cả"},{"hanzi":"讨好","pinyin":"tǎohǎo","vi":"lấy lòng"}],"traditional":"討"},{"id":"讨人喜欢","hanzi":"讨人喜欢","pinyin":"tǎorén-xǐhuan","meaning_vi":"dễ mến, được người yêu thích","explanation":"讨 (thảo – chuốc lấy) + 人 (nhân – người) + 喜欢 (hỉ hoan – thích) → khiến người ta yêu thích, đáng yêu.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🥰","examples":[{"type":"basic","zh":"这只小狗很讨人喜欢。","pinyin":"Zhè zhī xiǎogǒu hěn tǎorénxǐhuan.","vi":"Chú chó con này rất đáng yêu."},{"type":"simple","zh":"她说话温柔，特别讨人喜欢。","pinyin":"Tā shuōhuà wēnróu, tèbié tǎorénxǐhuan.","vi":"Cô ấy nói năng dịu dàng, đặc biệt dễ mến."},{"type":"compound","zh":"虽然他不太会说话，但是因为很诚实，所以挺讨人喜欢的。","pinyin":"Suīrán tā bú tài huì shuōhuà, dànshì yīnwèi hěn chéngshí, suǒyǐ tǐng tǎorénxǐhuan de.","vi":"Tuy anh ấy không khéo ăn nói, nhưng nhờ thật thà nên khá được mọi người quý."}],"related":[{"hanzi":"讨厌","pinyin":"tǎoyàn","vi":"đáng ghét"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"đáng yêu"},{"hanzi":"讨好","pinyin":"tǎohǎo","vi":"lấy lòng"},{"hanzi":"受欢迎","pinyin":"shòuhuānyíng","vi":"được hoan nghênh"}],"traditional":"討人喜歡"},{"id":"特例","hanzi":"特例","pinyin":"tèlì","meaning_vi":"trường hợp đặc biệt, ngoại lệ","explanation":"特 (đặc – đặc biệt) + 例 (lệ – ví dụ, trường hợp) → trường hợp riêng biệt, không theo quy luật chung.","hsk_level":"7-9","tags":["danh-tu"],"image":"⭐","examples":[{"type":"basic","zh":"这只是一个特例。","pinyin":"Zhè zhǐshì yí gè tèlì.","vi":"Đây chỉ là một trường hợp đặc biệt."},{"type":"simple","zh":"学校不会因为你而开特例。","pinyin":"Xuéxiào bú huì yīnwèi nǐ ér kāi tèlì.","vi":"Trường sẽ không vì bạn mà đặt ra ngoại lệ."},{"type":"compound","zh":"如果每个人都要求特例，规定就没有意义了。","pinyin":"Rúguǒ měigèrén dōu yāoqiú tèlì, guīdìng jiù méiyǒu yìyì le.","vi":"Nếu ai cũng đòi ngoại lệ thì quy định chẳng còn ý nghĩa gì."}],"related":[{"hanzi":"例外","pinyin":"lìwài","vi":"ngoại lệ"},{"hanzi":"特殊","pinyin":"tèshū","vi":"đặc thù"},{"hanzi":"案例","pinyin":"ànlì","vi":"trường hợp"},{"hanzi":"惯例","pinyin":"guànlì","vi":"lệ thường"}]},{"id":"特邀","hanzi":"特邀","pinyin":"tèyāo","meaning_vi":"mời đặc biệt, khách mời đặc biệt","explanation":"特 (đặc – đặc biệt) + 邀 (yêu – mời) → mời riêng, mời đặc biệt; hay gặp 特邀嘉宾 khách mời đặc biệt.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"他是特邀嘉宾。","pinyin":"Tā shì tèyāo jiābīn.","vi":"Anh ấy là khách mời đặc biệt."},{"type":"simple","zh":"主办方特邀了三位专家来做报告。","pinyin":"Zhǔbànfāng tèyāole sān wèi zhuānjiā lái zuò bàogào.","vi":"Ban tổ chức đặc biệt mời ba chuyên gia đến báo cáo."},{"type":"compound","zh":"因为她在这个领域很有名，所以被特邀参加论坛。","pinyin":"Yīnwèi tā zài zhè ge lǐngyù hěn yǒumíng, suǒyǐ bèi tèyāo cānjiā lùntán.","vi":"Vì cô ấy rất nổi tiếng trong lĩnh vực này nên được mời đặc biệt tham dự diễn đàn."}],"related":[{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"mời"},{"hanzi":"嘉宾","pinyin":"jiābīn","vi":"khách quý"},{"hanzi":"应邀","pinyin":"yìngyāo","vi":"nhận lời mời"},{"hanzi":"特约","pinyin":"tèyuē","vi":"mời riêng"}]},{"id":"特制","hanzi":"特制","pinyin":"tèzhì","meaning_vi":"chế tạo đặc biệt, làm riêng","explanation":"特 (đặc – đặc biệt) + 制 (chế – chế tạo) → làm riêng theo yêu cầu đặc biệt, không phải hàng thông thường.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛠️","examples":[{"type":"basic","zh":"这是特制的蛋糕。","pinyin":"Zhè shì tèzhì de dàngāo.","vi":"Đây là chiếc bánh làm riêng."},{"type":"simple","zh":"运动员穿的是特制的比赛服。","pinyin":"Yùndòngyuán chuān de shì tèzhì de bǐsài fú.","vi":"Vận động viên mặc đồ thi đấu được chế tạo đặc biệt."},{"type":"compound","zh":"因为这把椅子是特制的，所以价格比普通的贵很多。","pinyin":"Yīnwèi zhè bǎ yǐzi shì tèzhì de, suǒyǐ jiàgé bǐ pǔtōng de guì hěn duō.","vi":"Vì chiếc ghế này được làm riêng nên giá đắt hơn loại thường nhiều."}],"related":[{"hanzi":"定制","pinyin":"dìngzhì","vi":"đặt làm"},{"hanzi":"制造","pinyin":"zhìzào","vi":"chế tạo"},{"hanzi":"特殊","pinyin":"tèshū","vi":"đặc biệt"},{"hanzi":"专用","pinyin":"zhuānyòng","vi":"chuyên dụng"}],"traditional":"特製"},{"id":"腾","hanzi":"腾","pinyin":"téng","meaning_vi":"phi, bay vút lên; dọn ra, để trống","explanation":"腾 (đằng – phi lên, bay lên) → phi nhanh, vọt lên (奔腾, 升腾); khẩu ngữ: dọn trống, dành ra (腾地方, 腾时间).","hsk_level":"7-9","tags":["dong-tu"],"image":"🐎","examples":[{"type":"basic","zh":"请腾个位子给我。","pinyin":"Qǐng téng ge wèizi gěi wǒ.","vi":"Làm ơn nhường một chỗ cho tôi."},{"type":"simple","zh":"我们把这个房间腾出来给客人住。","pinyin":"Wǒmen bǎ zhè ge fángjiān téng chūlái gěi kèrén zhù.","vi":"Chúng tôi dọn trống căn phòng này cho khách ở."},{"type":"compound","zh":"即使工作再忙，他也会腾出时间陪孩子。","pinyin":"Jíshǐ gōngzuò zài máng, tā yě huì téngchū shíjiān péi háizi.","vi":"Dù công việc bận đến mấy, anh ấy cũng dành thời gian ở bên con."}],"related":[{"hanzi":"奔腾","pinyin":"bēnténg","vi":"phi nước đại"},{"hanzi":"腾飞","pinyin":"téngfēi","vi":"bay vút lên"},{"hanzi":"折腾","pinyin":"zhēteng","vi":"lăn lộn, hành hạ"},{"hanzi":"沸腾","pinyin":"fèiténg","vi":"sôi sục"}],"traditional":"騰"},{"id":"藤椅","hanzi":"藤椅","pinyin":"téngyǐ","meaning_vi":"ghế mây","explanation":"藤 (đằng – cây mây) + 椅 (ỷ – ghế) → ghế đan bằng mây.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🪑","examples":[{"type":"basic","zh":"阳台上有一把藤椅。","pinyin":"Yángtái shàng yǒu yì bǎ téngyǐ.","vi":"Trên ban công có một chiếc ghế mây."},{"type":"simple","zh":"爷爷喜欢坐在藤椅上看报纸。","pinyin":"Yéye xǐhuan zuò zài téngyǐ shàng kàn bàozhǐ.","vi":"Ông thích ngồi trên ghế mây đọc báo."},{"type":"compound","zh":"虽然这把藤椅很旧了，但是坐起来还是很舒服。","pinyin":"Suīrán zhè bǎ téngyǐ hěn jiù le, dànshì zuò qǐlái háishì hěn shūfu.","vi":"Tuy chiếc ghế mây này đã cũ, nhưng ngồi vẫn rất thoải mái."}],"related":[{"hanzi":"椅子","pinyin":"yǐzi","vi":"ghế"},{"hanzi":"沙发","pinyin":"shāfā","vi":"sofa"},{"hanzi":"藤","pinyin":"téng","vi":"mây, dây leo"},{"hanzi":"摇椅","pinyin":"yáoyǐ","vi":"ghế bập bênh"}]},{"id":"梯子","hanzi":"梯子","pinyin":"tīzi","meaning_vi":"cái thang","explanation":"梯 (thê – thang) + 子 (tử – hậu tố) → dụng cụ có nhiều bậc để trèo lên cao.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪜","examples":[{"type":"basic","zh":"把梯子搬过来。","pinyin":"Bǎ tīzi bān guòlái.","vi":"Mang cái thang lại đây."},{"type":"simple","zh":"他爬上梯子去换灯泡。","pinyin":"Tā páshàng tīzi qù huàn dēngpào.","vi":"Anh ấy trèo lên thang thay bóng đèn."},{"type":"compound","zh":"如果梯子放得不稳，就很容易摔下来。","pinyin":"Rúguǒ tīzi fàng de bùwěn, jiù hěn róngyì shuāi xiàlái.","vi":"Nếu đặt thang không vững thì rất dễ ngã xuống."}],"related":[{"hanzi":"楼梯","pinyin":"lóutī","vi":"cầu thang"},{"hanzi":"电梯","pinyin":"diàntī","vi":"thang máy"},{"hanzi":"台阶","pinyin":"táijiē","vi":"bậc thềm"},{"hanzi":"爬","pinyin":"pá","vi":"trèo"}]},{"id":"提防","hanzi":"提防","pinyin":"dīfang","meaning_vi":"đề phòng, cảnh giác","explanation":"提 (đề – nâng, nêu) + 防 (phòng – phòng ngừa) → cảnh giác, đề phòng người xấu hoặc điều bất lợi.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"你要提防骗子。","pinyin":"Nǐ yào dīfang piànzi.","vi":"Bạn phải đề phòng kẻ lừa đảo."},{"type":"simple","zh":"出门在外，一定要提防陌生人的花言巧语。","pinyin":"Chūmén zài wài, yídìngyào dīfang mòshēngrén de huāyánqiǎoyǔ.","vi":"Khi ra ngoài, nhất định phải đề phòng lời đường mật của người lạ."},{"type":"compound","zh":"虽然他表面很热情，但是你还是得提防着点。","pinyin":"Suīrán tā biǎomiàn hěn rèqíng, dànshì nǐ háishi děi dīfangzhe diǎn.","vi":"Tuy bề ngoài anh ta rất nhiệt tình, nhưng bạn vẫn nên đề phòng một chút."}],"related":[{"hanzi":"防备","pinyin":"fángbèi","vi":"phòng bị"},{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"},{"hanzi":"防范","pinyin":"fángfàn","vi":"phòng ngừa"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"cẩn thận"}]},{"id":"提早","hanzi":"提早","pinyin":"tízǎo","meaning_vi":"sớm hơn, trước thời hạn, dời sớm lên","explanation":"提 (đề – nâng, đưa lên) + 早 (tảo – sớm) → đưa thời gian lên sớm hơn dự định.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"我们提早出发吧。","pinyin":"Wǒmen tízǎo chūfā ba.","vi":"Chúng ta xuất phát sớm hơn nhé."},{"type":"simple","zh":"会议提早到下午两点开始。","pinyin":"Huìyì tízǎo dào xiàwǔ liǎng diǎn kāishǐ.","vi":"Cuộc họp được dời sớm lên bắt đầu lúc hai giờ chiều."},{"type":"compound","zh":"因为路上可能堵车，所以我们最好提早半小时出门。","pinyin":"Yīnwèi lùshang kěnéng dǔchē, suǒyǐ wǒmen zuìhǎo tízǎo bànxiǎoshí chūmén.","vi":"Vì trên đường có thể kẹt xe nên tốt nhất chúng ta ra khỏi nhà sớm nửa tiếng."}],"related":[{"hanzi":"提前","pinyin":"tíqián","vi":"trước, sớm hơn"},{"hanzi":"推迟","pinyin":"tuīchí","vi":"hoãn lại"},{"hanzi":"早日","pinyin":"zǎorì","vi":"sớm ngày"},{"hanzi":"延期","pinyin":"yánqī","vi":"gia hạn"}]},{"id":"体温","hanzi":"体温","pinyin":"tǐwēn","meaning_vi":"nhiệt độ cơ thể, thân nhiệt","explanation":"体 (thể – cơ thể) + 温 (ôn – ấm, nhiệt độ) → nhiệt độ của cơ thể.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🌡️","examples":[{"type":"basic","zh":"先量一下体温。","pinyin":"Xiān liáng yíxià tǐwēn.","vi":"Đo thân nhiệt trước đã."},{"type":"simple","zh":"孩子的体温一直在三十八度左右。","pinyin":"Háizi de tǐwēn yìzhí zài sānshí bādù zuǒyòu.","vi":"Thân nhiệt của đứa bé cứ ở khoảng 38 độ."},{"type":"compound","zh":"如果体温超过三十九度，就要马上去医院。","pinyin":"Rúguǒ tǐwēn chāoguò sān shíjiǔ dù, jiùyào mǎshàng qù yīyuàn.","vi":"Nếu thân nhiệt vượt quá 39 độ thì phải đi bệnh viện ngay."}],"related":[{"hanzi":"发烧","pinyin":"fāshāo","vi":"sốt"},{"hanzi":"体温计","pinyin":"tǐwēnjì","vi":"nhiệt kế"},{"hanzi":"温度","pinyin":"wēndù","vi":"nhiệt độ"},{"hanzi":"体重","pinyin":"tǐzhòng","vi":"cân nặng"}],"traditional":"體溫"},{"id":"剃","hanzi":"剃","pinyin":"tì","meaning_vi":"cạo (râu, tóc)","explanation":"剃 (thế – cạo), có bộ 刂 (dao) → dùng dao cạo sạch râu, tóc; thường gặp trong 剃头, 剃胡子.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🪒","examples":[{"type":"basic","zh":"他每天早上剃胡子。","pinyin":"Tā měitiān zǎoshang tì húzi.","vi":"Sáng nào anh ấy cũng cạo râu."},{"type":"simple","zh":"他为了拍电影把头发剃光了。","pinyin":"Tā wèile pāidiànyǐng bǎ tóufa tì guāng le.","vi":"Anh ấy đã cạo trọc đầu để đóng phim."},{"type":"compound","zh":"虽然剃了光头很凉快，但是他觉得不太好看。","pinyin":"Suīrán tìle guāngtóu hěn liángkuai, dànshì tā juéde bú tài hǎokàn.","vi":"Tuy cạo trọc rất mát nhưng anh ấy thấy không đẹp lắm."}],"related":[{"hanzi":"剃刀","pinyin":"tìdāo","vi":"dao cạo"},{"hanzi":"刮","pinyin":"guā","vi":"cạo, gọt"},{"hanzi":"胡子","pinyin":"húzi","vi":"râu"},{"hanzi":"理发","pinyin":"lǐfà","vi":"cắt tóc"}]},{"id":"替换","hanzi":"替换","pinyin":"tìhuàn","meaning_vi":"thay thế, thay, đổi","explanation":"替 (thế – thay) + 换 (hoán – đổi) → đổi cái mới vào chỗ cái cũ, đưa người hoặc vật khác vào thay.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"请替换旧电池。","pinyin":"Qǐng tìhuàn jiù diànchí.","vi":"Hãy thay pin cũ."},{"type":"simple","zh":"教练在下半场替换了两名球员。","pinyin":"Jiàoliàn zài xiàbànchǎng tìhuànle liǎng míng qiúyuán.","vi":"Huấn luyện viên đã thay hai cầu thủ trong hiệp hai."},{"type":"compound","zh":"如果这个零件坏了，就得马上替换。","pinyin":"Rúguǒ zhè ge língjiàn huàile, jiù děi mǎshàng tìhuàn.","vi":"Nếu linh kiện này hỏng thì phải thay ngay."}],"related":[{"hanzi":"替代","pinyin":"tìdài","vi":"thay thế"},{"hanzi":"更换","pinyin":"gēnghuàn","vi":"thay đổi"},{"hanzi":"代替","pinyin":"dàitì","vi":"thay cho"},{"hanzi":"交换","pinyin":"jiāohuàn","vi":"trao đổi"}],"traditional":"替換"},{"id":"替身","hanzi":"替身","pinyin":"tìshēn","meaning_vi":"người đóng thế, người thế thân","explanation":"替 (thế – thay) + 身 (thân – thân mình) → người thay thân mình làm việc; nay hay dùng chỉ diễn viên đóng thế.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"这场戏用了替身。","pinyin":"Zhè chǎng xì yòngle tìshēn.","vi":"Cảnh này đã dùng diễn viên đóng thế."},{"type":"simple","zh":"危险的打斗动作都由替身来完成。","pinyin":"Wēixiǎn de dǎdòu dòngzuò dōu yóu tìshēn lái wánchéng.","vi":"Các động tác đánh nhau nguy hiểm đều do người đóng thế thực hiện."},{"type":"compound","zh":"虽然有替身可以用，但是她坚持自己跳进冰冷的湖里。","pinyin":"Suīrán yǒu tìshēn kěyǐ yòng, dànshì tā jiānchí zìjǐ tiàojìn bīnglěng de Húli.","vi":"Tuy có người đóng thế nhưng cô ấy vẫn kiên quyết tự nhảy xuống hồ lạnh buốt."}],"related":[{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"替代","pinyin":"tìdài","vi":"thay thế"},{"hanzi":"特技","pinyin":"tèjì","vi":"kỹ xảo"},{"hanzi":"替罪羊","pinyin":"tìzuìyáng","vi":"con dê tế thần"}]},{"id":"天地","hanzi":"天地","pinyin":"tiāndì","meaning_vi":"trời đất; thế giới, phạm vi hoạt động","explanation":"天 (thiên – trời) + 地 (địa – đất) → trời đất; nghĩa bóng là một thế giới, khoảng không gian để phát triển.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌏","examples":[{"type":"basic","zh":"这里是孩子们的天地。","pinyin":"Zhèlǐ shì háizimen de tiāndì.","vi":"Đây là thế giới của bọn trẻ."},{"type":"simple","zh":"他在网络行业闯出了一片新天地。","pinyin":"Tā zài wǎngluò hángyè chuǎng chūle yípiàn Xīntiāndì.","vi":"Anh ấy đã mở ra một chân trời mới trong ngành internet."},{"type":"compound","zh":"只要你肯努力，就能在这个领域开拓自己的天地。","pinyin":"Zhǐyào nǐ kěn nǔlì, jiù néng zài zhè ge lǐngyù kāituò zìjǐ de tiāndì.","vi":"Chỉ cần bạn chịu cố gắng thì có thể mở mang thế giới riêng trong lĩnh vực này."}],"related":[{"hanzi":"天下","pinyin":"tiānxià","vi":"thiên hạ"},{"hanzi":"世界","pinyin":"shìjiè","vi":"thế giới"},{"hanzi":"领域","pinyin":"lǐngyù","vi":"lĩnh vực"},{"hanzi":"天空","pinyin":"tiānkōng","vi":"bầu trời"}]},{"id":"天鹅","hanzi":"天鹅","pinyin":"tiān'é","meaning_vi":"thiên nga","explanation":"天 (thiên – trời) + 鹅 (nga – ngỗng) → \"ngỗng trời\", tức chim thiên nga.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦢","examples":[{"type":"basic","zh":"湖上有两只天鹅。","pinyin":"Hú shang yǒu liǎng zhī tiān'é.","vi":"Trên hồ có hai con thiên nga."},{"type":"simple","zh":"白色的天鹅在湖面上优雅地游来游去。","pinyin":"Báisè de tiān'é zài húmiàn shang yōuyǎ de yóu lái yóu qù.","vi":"Những con thiên nga trắng bơi qua bơi lại duyên dáng trên mặt hồ."},{"type":"compound","zh":"因为这里冬天不结冰，所以每年都有天鹅来过冬。","pinyin":"Yīnwèi zhèlǐ dōngtiān bù jiébīng, suǒyǐ měinián dōu yǒu tiān'é lái guòdōng.","vi":"Vì mùa đông ở đây không đóng băng nên năm nào cũng có thiên nga đến tránh rét."}],"related":[{"hanzi":"鹅","pinyin":"é","vi":"con ngỗng"},{"hanzi":"白天鹅","pinyin":"báitiān'é","vi":"thiên nga trắng"},{"hanzi":"丑小鸭","pinyin":"chǒuxiǎoyā","vi":"vịt con xấu xí"},{"hanzi":"鸟类","pinyin":"niǎolèi","vi":"loài chim"}],"traditional":"天鵝"},{"id":"天平","hanzi":"天平","pinyin":"tiānpíng","meaning_vi":"cái cân (cân đĩa), cán cân","explanation":"天 (thiên – trời) + 平 (bình – thăng bằng) → dụng cụ cân hai đĩa giữ thăng bằng; nghĩa bóng là cán cân công lý, thắng thua.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚖️","examples":[{"type":"basic","zh":"用天平称一下。","pinyin":"Yòng tiānpíng chēng yíxià.","vi":"Dùng cân để cân thử xem."},{"type":"simple","zh":"实验室里的天平能精确到零点一克。","pinyin":"Shíyànshì li de tiānpíng néng jīngquè dào língdiǎn yí kè.","vi":"Cái cân trong phòng thí nghiệm chính xác đến 0,1 gam."},{"type":"compound","zh":"如果天平两边不平衡，就说明重量不一样。","pinyin":"Rúguǒ tiānpíng liǎngbiān bù pínghéng, jiù shuōmíng zhòngliàng bù yíyàng.","vi":"Nếu hai bên cân không thăng bằng thì chứng tỏ trọng lượng khác nhau."}],"related":[{"hanzi":"秤","pinyin":"chèng","vi":"cái cân"},{"hanzi":"平衡","pinyin":"pínghéng","vi":"cân bằng"},{"hanzi":"砝码","pinyin":"fǎmǎ","vi":"quả cân"},{"hanzi":"称","pinyin":"chēng","vi":"cân"}]},{"id":"天桥","hanzi":"天桥","pinyin":"tiānqiáo","meaning_vi":"cầu vượt (cho người đi bộ)","explanation":"天 (thiên – trời, trên cao) + 桥 (kiều – cầu) → cây cầu bắc trên cao qua đường; cũng là tên khu Thiên Kiều ở Bắc Kinh.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🌉","examples":[{"type":"basic","zh":"我们走天桥过马路。","pinyin":"Wǒmen zǒu tiānqiáo guòmǎlù.","vi":"Chúng ta đi cầu vượt để qua đường."},{"type":"simple","zh":"学校门口新建了一座人行天桥。","pinyin":"Xuéxiào ménkǒu xīnjiànle yí zuò Rénxíng tiānqiáo.","vi":"Trước cổng trường mới xây một cây cầu vượt cho người đi bộ."},{"type":"compound","zh":"虽然走天桥要多花几分钟，但是比横穿马路安全多了。","pinyin":"Suīrán zǒu tiānqiáo yào duō huā jǐ fēnzhōng, dànshì bǐ héngchuān mǎlù ānquán duō le.","vi":"Tuy đi cầu vượt mất thêm vài phút nhưng an toàn hơn băng qua đường nhiều."}],"related":[{"hanzi":"立交桥","pinyin":"lìjiāoqiáo","vi":"cầu vượt giao lộ"},{"hanzi":"地下通道","pinyin":"dìxiàtōngdào","vi":"hầm đi bộ"},{"hanzi":"人行道","pinyin":"rénxíngdào","vi":"vỉa hè"},{"hanzi":"桥梁","pinyin":"qiáoliáng","vi":"cầu"}],"traditional":"天橋"},{"id":"天使","hanzi":"天使","pinyin":"tiānshǐ","meaning_vi":"thiên thần","explanation":"天 (thiên – trời) + 使 (sứ – sứ giả) → sứ giả nhà trời; cũng dùng ví người hiền lành, tốt bụng.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"👼","examples":[{"type":"basic","zh":"她笑起来像天使。","pinyin":"Tā xiào qǐlái xiàng tiānshǐ.","vi":"Cô ấy cười lên trông như thiên thần."},{"type":"simple","zh":"护士常常被人们称为“白衣天使”。","pinyin":"Hùshi chángcháng bèi rénmen chēngwéi \"bái yī tiānshǐ\".","vi":"Y tá thường được gọi là \"thiên thần áo trắng\"."},{"type":"compound","zh":"虽然他平时很调皮，但是睡着的时候像个小天使。","pinyin":"Suīrán tā píngshí hěn tiáopí, dànshì shuìzháo de shíhou xiàng ge xiǎo tiānshǐ.","vi":"Tuy thường ngày nó rất nghịch nhưng lúc ngủ trông như thiên thần nhỏ."}],"related":[{"hanzi":"魔鬼","pinyin":"móguǐ","vi":"ma quỷ"},{"hanzi":"天堂","pinyin":"tiāntáng","vi":"thiên đường"},{"hanzi":"翅膀","pinyin":"chìbǎng","vi":"đôi cánh"},{"hanzi":"白衣天使","pinyin":"báiyītiānshǐ","vi":"thiên thần áo trắng"}]},{"id":"天线","hanzi":"天线","pinyin":"tiānxiàn","meaning_vi":"ăng-ten","explanation":"天 (thiên – trời, trên không) + 线 (tuyến – dây) → dây đặt trên cao để thu phát sóng, tức ăng-ten.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📡","examples":[{"type":"basic","zh":"屋顶上装了天线。","pinyin":"Wūdǐng shangzhuāngle tiānxiàn.","vi":"Trên mái nhà có lắp ăng-ten."},{"type":"simple","zh":"收音机的天线拉长以后信号好多了。","pinyin":"Shōuyīnjī de tiānxiàn lācháng yǐhòu xìnhào hǎoduō le.","vi":"Kéo dài ăng-ten radio ra thì tín hiệu tốt hơn nhiều."},{"type":"compound","zh":"如果天线被大风吹歪了，电视就没有信号了。","pinyin":"Rúguǒ tiānxiàn bèi dàfēngchuī wāi le, diànshì jiù méiyǒu xìnhào le.","vi":"Nếu ăng-ten bị gió lớn thổi lệch thì tivi sẽ mất tín hiệu."}],"related":[{"hanzi":"信号","pinyin":"xìnhào","vi":"tín hiệu"},{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"接收","pinyin":"jiēshōu","vi":"thu nhận"},{"hanzi":"无线","pinyin":"wúxiàn","vi":"không dây"}],"traditional":"天線"},{"id":"天主教","hanzi":"天主教","pinyin":"Tiānzhǔjiào","meaning_vi":"Công giáo, đạo Thiên Chúa","explanation":"天主 (Thiên Chủ – Chúa Trời) + 教 (giáo – tôn giáo) → đạo thờ Thiên Chúa, tức Công giáo La Mã.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"⛪","examples":[{"type":"basic","zh":"她信天主教。","pinyin":"Tā xìn Tiānzhǔjiào.","vi":"Cô ấy theo đạo Công giáo."},{"type":"simple","zh":"这座天主教堂已经有一百多年的历史了。","pinyin":"Zhè zuò Tiānzhǔ jiàotáng yǐjīng yǒu yī bǎi duōnián de lìshǐ le.","vi":"Nhà thờ Công giáo này đã có hơn trăm năm lịch sử."},{"type":"compound","zh":"虽然他家世代信天主教，但是他本人很少去教堂。","pinyin":"Suīrán tā jiā shìdài xìn Tiānzhǔjiào, dànshì tā běnrén hěn shǎo qù jiàotáng.","vi":"Tuy gia đình anh ấy theo Công giáo qua nhiều đời nhưng bản thân anh ấy ít khi đi nhà thờ."}],"related":[{"hanzi":"基督教","pinyin":"Jīdūjiào","vi":"Cơ Đốc giáo"},{"hanzi":"教堂","pinyin":"jiàotáng","vi":"nhà thờ"},{"hanzi":"佛教","pinyin":"Fójiào","vi":"Phật giáo"},{"hanzi":"宗教","pinyin":"zōngjiào","vi":"tôn giáo"}]},{"id":"添加","hanzi":"添加","pinyin":"tiānjiā","meaning_vi":"thêm vào, bổ sung","explanation":"添 (thiêm – thêm) + 加 (gia – cộng thêm) → thêm vào cho nhiều hơn; hay dùng trong 添加剂 (chất phụ gia), 添加好友.","hsk_level":"7-9","tags":["dong-tu"],"image":"➕","examples":[{"type":"basic","zh":"我添加了你的微信。","pinyin":"Wǒ tiānjiāle nǐ de Wēixìn.","vi":"Tôi đã thêm WeChat của bạn rồi."},{"type":"simple","zh":"这种饼干没有添加任何防腐剂。","pinyin":"Zhè zhǒng bǐnggān méiyǒu tiānjiā rènhé fángfǔjì.","vi":"Loại bánh quy này không thêm bất kỳ chất bảo quản nào."},{"type":"compound","zh":"如果汤太淡了，就再添加一点盐。","pinyin":"Rúguǒ tāng tài dàn le, jiù zài tiānjiā yìdiǎn yán.","vi":"Nếu canh nhạt quá thì thêm chút muối nữa."}],"related":[{"hanzi":"增加","pinyin":"zēngjiā","vi":"tăng thêm"},{"hanzi":"添加剂","pinyin":"tiānjiājì","vi":"chất phụ gia"},{"hanzi":"补充","pinyin":"bǔchōng","vi":"bổ sung"},{"hanzi":"删除","pinyin":"shānchú","vi":"xóa bỏ"}]},{"id":"填补","hanzi":"填补","pinyin":"tiánbǔ","meaning_vi":"lấp đầy, bù đắp (chỗ trống, thiếu hụt)","explanation":"填 (điền – lấp) + 补 (bổ – bù, vá) → lấp vào chỗ trống, bù vào chỗ thiếu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧩","examples":[{"type":"basic","zh":"这项技术填补了空白。","pinyin":"Zhè xiàng jìshù tiánbǔle kòngbái.","vi":"Công nghệ này đã lấp đầy khoảng trống."},{"type":"simple","zh":"公司正在招人填补这个职位的空缺。","pinyin":"Gōngsī zhèngzài zhāorén tiánbǔ zhè ge zhíwèi de kòngquē.","vi":"Công ty đang tuyển người để lấp chỗ trống của vị trí này."},{"type":"compound","zh":"虽然他买了很多东西，但是仍然无法填补内心的空虚。","pinyin":"Suīrán tā mǎile hěn duō dōngxi, dànshì réngrán wúfǎ tiánbǔ nèixīn de kōngxū.","vi":"Tuy mua rất nhiều thứ nhưng anh ấy vẫn không thể lấp đầy sự trống rỗng trong lòng."}],"related":[{"hanzi":"弥补","pinyin":"míbǔ","vi":"bù đắp"},{"hanzi":"空白","pinyin":"kòngbái","vi":"khoảng trống"},{"hanzi":"空缺","pinyin":"kòngquē","vi":"chỗ khuyết"},{"hanzi":"补充","pinyin":"bǔchōng","vi":"bổ sung"}],"traditional":"填補"},{"id":"填充","hanzi":"填充","pinyin":"tiánchōng","meaning_vi":"nhồi, độn, lấp đầy; điền vào chỗ trống","explanation":"填 (điền – lấp) + 充 (sung – đầy) → nhét cho đầy; cũng chỉ dạng bài tập điền vào chỗ trống (填充题).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧸","examples":[{"type":"basic","zh":"枕头里填充了棉花。","pinyin":"Zhěntou li tiánchōngle miánhuā.","vi":"Trong gối có nhồi bông."},{"type":"simple","zh":"工人用泡沫填充墙壁之间的缝隙。","pinyin":"Gōngrén yòng pàomò tiánchōng qiángbì zhījiān de fèngxì.","vi":"Công nhân dùng xốp lấp kín khe hở giữa các bức tường."},{"type":"compound","zh":"因为箱子里还有空间，所以我们用旧报纸填充一下。","pinyin":"Yīnwèi xiāngzi li háiyǒu kōngjiān, suǒyǐ wǒmen yòng jiù bàozhǐ tiánchōng yíxià.","vi":"Vì trong thùng còn chỗ trống nên chúng ta lấy báo cũ chèn vào."}],"related":[{"hanzi":"填满","pinyin":"tiánmǎn","vi":"lấp đầy"},{"hanzi":"充满","pinyin":"chōngmǎn","vi":"tràn đầy"},{"hanzi":"填空","pinyin":"tiánkòng","vi":"điền vào chỗ trống"},{"hanzi":"塞","pinyin":"sāi","vi":"nhét"}]},{"id":"填写","hanzi":"填写","pinyin":"tiánxiě","meaning_vi":"điền (vào đơn, biểu mẫu)","explanation":"填 (điền – điền vào) + 写 (tả – viết) → viết thông tin vào ô trống trong đơn, phiếu.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📝","examples":[{"type":"basic","zh":"请填写这张表格。","pinyin":"Qǐng tiánxiě zhè zhāng biǎogé.","vi":"Vui lòng điền vào tờ đơn này."},{"type":"simple","zh":"办签证时要在网上填写个人信息。","pinyin":"Bàn qiānzhèng shí yào zài wǎngshang tiánxiě gèrén xìnxī.","vi":"Khi làm visa phải điền thông tin cá nhân trên mạng."},{"type":"compound","zh":"如果你填写的地址有误，包裹就可能寄不到。","pinyin":"Rúguǒ nǐ tiánxiě de dìzhǐ yǒu wù, bāoguǒ jiù kěnéng jì búdào.","vi":"Nếu bạn điền sai địa chỉ thì bưu kiện có thể không gửi tới được."}],"related":[{"hanzi":"表格","pinyin":"biǎogé","vi":"biểu mẫu"},{"hanzi":"填表","pinyin":"tiánbiǎo","vi":"điền đơn"},{"hanzi":"签名","pinyin":"qiānmíng","vi":"ký tên"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"xin, đơn xin"}],"traditional":"填寫"},{"id":"挑起","hanzi":"挑起","pinyin":"tiǎoqǐ","meaning_vi":"khơi mào, gây ra, kích động","explanation":"挑 (khiêu – khêu, gây) + 起 (khởi – dấy lên) → khêu cho bùng lên (tranh chấp, mâu thuẫn); đọc tiāo qǐ thì nghĩa là gánh vác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔥","examples":[{"type":"basic","zh":"是他先挑起争吵的。","pinyin":"Shì tā xiān tiǎoqǐ zhēngchǎo de.","vi":"Chính anh ta gây chuyện cãi nhau trước."},{"type":"simple","zh":"有人故意在网上挑起两国网民的矛盾。","pinyin":"Yǒurén gùyì zài wǎngshang tiǎoqǐ liǎngguó wǎngmín de máodùn.","vi":"Có người cố tình khơi mào mâu thuẫn giữa cư dân mạng hai nước."},{"type":"compound","zh":"一旦战争被挑起，就会有无数无辜的人受害。","pinyin":"Yídàn zhànzhēng bèi tiǎoqǐ, jiù huì yǒu wúshù wúgū de rén shòuhài.","vi":"Một khi chiến tranh bị gây ra thì vô số người vô tội sẽ bị hại."}],"related":[{"hanzi":"挑衅","pinyin":"tiǎoxìn","vi":"khiêu khích"},{"hanzi":"挑拨","pinyin":"tiǎobō","vi":"xúi giục, ly gián"},{"hanzi":"引起","pinyin":"yǐnqǐ","vi":"gây ra"},{"hanzi":"煽动","pinyin":"shāndòng","vi":"kích động"}]},{"id":"条款","hanzi":"条款","pinyin":"tiáokuǎn","meaning_vi":"điều khoản","explanation":"条 (điều – điều mục) + 款 (khoản – khoản mục) → từng điều, từng khoản trong hợp đồng, luật lệ.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"请仔细阅读条款。","pinyin":"Qǐng zǐxì yuèdú tiáokuǎn.","vi":"Hãy đọc kỹ các điều khoản."},{"type":"simple","zh":"这份合同里有几条条款对我们很不利。","pinyin":"Zhè fèn hétong li yǒu jǐ tiáo tiáokuǎn duì wǒmen hěn búlì.","vi":"Trong hợp đồng này có vài điều khoản rất bất lợi cho chúng ta."},{"type":"compound","zh":"如果对方违反了合同条款，我们就有权要求赔偿。","pinyin":"Rúguǒ duìfāng wéifǎnle hétong tiáokuǎn, wǒmen jiù yǒuquán yāoqiú péicháng.","vi":"Nếu đối phương vi phạm điều khoản hợp đồng thì chúng ta có quyền đòi bồi thường."}],"related":[{"hanzi":"合同","pinyin":"hétong","vi":"hợp đồng"},{"hanzi":"条例","pinyin":"tiáolì","vi":"điều lệ"},{"hanzi":"协议","pinyin":"xiéyì","vi":"thỏa thuận"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"}],"traditional":"條款"},{"id":"条例","hanzi":"条例","pinyin":"tiáolì","meaning_vi":"điều lệ, quy chế, pháp lệnh","explanation":"条 (điều – điều mục) + 例 (lệ – quy tắc) → văn bản quy định chia thành từng điều do cơ quan nhà nước ban hành.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"📘","examples":[{"type":"basic","zh":"政府颁布了新条例。","pinyin":"Zhèngfǔ bānbùle xīn tiáolì.","vi":"Chính phủ đã ban hành điều lệ mới."},{"type":"simple","zh":"根据交通管理条例，开车不能打电话。","pinyin":"Gēnjù jiāotōng guǎnlǐ tiáolì, kāichē bù néng dǎdiànhuà.","vi":"Theo quy chế quản lý giao thông, lái xe không được gọi điện thoại."},{"type":"compound","zh":"虽然这项条例已经实施了两年，但是很多人还不了解。","pinyin":"Suīrán zhè xiàng tiáolì yǐjīng shíshīle liǎng nián, dànshì hěn duō rén hái bù liǎojiě.","vi":"Tuy điều lệ này đã thực thi hai năm nhưng nhiều người vẫn chưa hiểu rõ."}],"related":[{"hanzi":"法规","pinyin":"fǎguī","vi":"pháp quy"},{"hanzi":"条款","pinyin":"tiáokuǎn","vi":"điều khoản"},{"hanzi":"规章","pinyin":"guīzhāng","vi":"quy chương"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"}],"traditional":"條例"},{"id":"跳动","hanzi":"跳动","pinyin":"tiàodòng","meaning_vi":"đập, nhảy, rung động","explanation":"跳 (khiêu – nhảy) + 动 (động – chuyển động) → chuyển động nhịp nhàng lên xuống, như tim đập, ngọn lửa nhảy múa.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"💓","examples":[{"type":"basic","zh":"我的心跳动得很快。","pinyin":"Wǒ de xīn tiàodòng de hěn kuài.","vi":"Tim tôi đập rất nhanh."},{"type":"simple","zh":"屏幕上的数字不停地跳动着。","pinyin":"Píngmù shang de shùzì bùtíng de tiàodòng zhe.","vi":"Những con số trên màn hình nhảy liên tục."},{"type":"compound","zh":"只要心脏还在跳动，医生就不会放弃抢救。","pinyin":"Zhǐyào xīnzàng hái zài tiàodòng, yīshēng jiù bú huì fàngqì qiǎngjiù.","vi":"Chỉ cần tim vẫn còn đập thì bác sĩ sẽ không bỏ cuộc cấp cứu."}],"related":[{"hanzi":"心跳","pinyin":"xīntiào","vi":"nhịp tim"},{"hanzi":"脉搏","pinyin":"màibó","vi":"mạch đập"},{"hanzi":"跳跃","pinyin":"tiàoyuè","vi":"nhảy vọt"},{"hanzi":"颤动","pinyin":"chàndòng","vi":"rung động"}],"traditional":"跳動"},{"id":"跳伞","hanzi":"跳伞","pinyin":"tiàosǎn","meaning_vi":"nhảy dù","explanation":"跳 (khiêu – nhảy) + 伞 (tản – cái ô, dù) → nhảy từ máy bay xuống bằng dù.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🪂","examples":[{"type":"basic","zh":"我想试试跳伞。","pinyin":"Wǒ xiǎng shìshi tiàosǎn.","vi":"Tôi muốn thử nhảy dù."},{"type":"simple","zh":"飞行员在飞机着火前跳伞逃生了。","pinyin":"Fēixíngyuán zài fēijī zháohuǒ qián tiàosǎn táoshēng le.","vi":"Phi công đã nhảy dù thoát thân trước khi máy bay bốc cháy."},{"type":"compound","zh":"虽然跳伞看起来很危险，但是有教练陪着就不用太担心。","pinyin":"Suīrán tiàosǎn kànqǐlái hěn wēixiǎn, dànshì yǒu jiàoliàn péizhe jiù bú yòng tài dānxīn.","vi":"Tuy nhảy dù trông rất nguy hiểm nhưng có huấn luyện viên đi kèm thì không cần quá lo."}],"related":[{"hanzi":"降落伞","pinyin":"jiàngluòsǎn","vi":"cái dù"},{"hanzi":"跳水","pinyin":"tiàoshuǐ","vi":"nhảy cầu"},{"hanzi":"蹦极","pinyin":"bèngjí","vi":"nhảy bungee"},{"hanzi":"极限运动","pinyin":"jíxiànyùndòng","vi":"thể thao mạo hiểm"}],"traditional":"跳傘"},{"id":"帖子","hanzi":"帖子","pinyin":"tiězi","meaning_vi":"bài đăng (diễn đàn); thiệp mời","explanation":"帖 (thiếp – tờ giấy viết, thiệp) + 子 (tử – hậu tố) → tấm thiếp, giấy mời; nay chủ yếu chỉ bài đăng trên diễn đàn mạng.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💬","examples":[{"type":"basic","zh":"他发了一个帖子。","pinyin":"Tā fāle yí ge tiězi.","vi":"Anh ấy đã đăng một bài."},{"type":"simple","zh":"这个帖子一天之内就有上万人转发。","pinyin":"Zhè ge tiězi yì tiān zhīnèi jiù yǒu shàng wànrén zhuǎnfā.","vi":"Bài đăng này trong một ngày đã có hàng vạn người chia sẻ."},{"type":"compound","zh":"如果帖子内容违反规定，管理员就会把它删掉。","pinyin":"Rúguǒ tiězi nèiróng wéifǎn guīdìng, guǎnlǐyuán jiù huì bǎ tā shāndiào.","vi":"Nếu nội dung bài đăng vi phạm quy định thì quản trị viên sẽ xóa nó."}],"related":[{"hanzi":"发帖","pinyin":"fātiě","vi":"đăng bài"},{"hanzi":"论坛","pinyin":"lùntán","vi":"diễn đàn"},{"hanzi":"跟帖","pinyin":"gēntiě","vi":"bình luận theo"},{"hanzi":"请帖","pinyin":"qǐngtiě","vi":"thiệp mời"}]},{"id":"贴近","hanzi":"贴近","pinyin":"tiējìn","meaning_vi":"áp sát, gần gũi, sát với","explanation":"贴 (thiếp – dán, áp) + 近 (cận – gần) → áp sát vào; nghĩa bóng là gần gũi, sát với thực tế.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"他把耳朵贴近门。","pinyin":"Tā bǎ ěrduo tiējìn mén.","vi":"Anh ấy áp tai sát cửa."},{"type":"simple","zh":"这部电影的故事非常贴近普通人的生活。","pinyin":"Zhè bù diànyǐng de gùshi fēicháng tiējìn pǔtōngrén de shēnghuó.","vi":"Câu chuyện bộ phim này rất gần gũi với cuộc sống người bình thường."},{"type":"compound","zh":"只有贴近群众，才能真正了解他们的需要。","pinyin":"Zhǐyǒu tiējìn qúnzhòng, cáinéng zhēnzhèng liǎojiě tāmen de xūyào.","vi":"Chỉ khi gần gũi quần chúng mới thật sự hiểu được nhu cầu của họ."}],"related":[{"hanzi":"接近","pinyin":"jiējìn","vi":"tiếp cận"},{"hanzi":"靠近","pinyin":"kàojìn","vi":"đến gần"},{"hanzi":"亲近","pinyin":"qīnjìn","vi":"thân cận"},{"hanzi":"贴心","pinyin":"tiēxīn","vi":"chu đáo, thân thiết"}],"traditional":"貼近"},{"id":"听从","hanzi":"听从","pinyin":"tīngcóng","meaning_vi":"nghe theo, tuân theo","explanation":"听 (thính – nghe) + 从 (tùng – theo) → nghe và làm theo lời khuyên, mệnh lệnh.","hsk_level":"7-9","tags":["dong-tu"],"image":"👂","examples":[{"type":"basic","zh":"请听从医生的建议。","pinyin":"Qǐng tīngcóng yīshēng de jiànyì.","vi":"Hãy nghe theo lời khuyên của bác sĩ."},{"type":"simple","zh":"士兵必须听从指挥官的命令。","pinyin":"Shìbīng bìxū tīngcóng zhǐhuīguān de mìnglìng.","vi":"Binh lính phải tuân theo mệnh lệnh của chỉ huy."},{"type":"compound","zh":"要是当初听从了父母的劝告，他就不会吃这么大的亏。","pinyin":"Yàoshi dāngchū tīngcóngle fùmǔ de quàngào, tā jiù bú huì chī zhème dà de kuī.","vi":"Nếu lúc đầu nghe theo lời khuyên của bố mẹ thì anh ấy đã không chịu thiệt lớn như vậy."}],"related":[{"hanzi":"服从","pinyin":"fúcóng","vi":"phục tùng"},{"hanzi":"遵从","pinyin":"zūncóng","vi":"tuân theo"},{"hanzi":"听话","pinyin":"tīnghuà","vi":"nghe lời"},{"hanzi":"违抗","pinyin":"wéikàng","vi":"chống lệnh"}],"traditional":"聽從"},{"id":"听话","hanzi":"听话","pinyin":"tīnghuà","meaning_vi":"nghe lời, ngoan","explanation":"听 (thính – nghe) + 话 (thoại – lời nói) → nghe theo lời người khác, ngoan ngoãn (thường nói về trẻ em, vật nuôi).","hsk_level":"7-9","tags":["tinh-tu","gia-dinh"],"image":"🧒","examples":[{"type":"basic","zh":"这孩子很听话。","pinyin":"Zhè háizi hěn tīnghuà.","vi":"Đứa trẻ này rất ngoan."},{"type":"simple","zh":"我家的小狗特别听话，从来不乱叫。","pinyin":"Wǒ jiā de xiǎogǒu tèbié tīnghuà, cóngláibú luànjiào.","vi":"Chú chó nhà tôi rất nghe lời, chưa bao giờ sủa bậy."},{"type":"compound","zh":"如果你乖乖听话，周末妈妈就带你去动物园。","pinyin":"Rúguǒ nǐ guāiguāi tīnghuà, zhōumò māma jiù dài nǐ qù dòngwùyuán.","vi":"Nếu con ngoan ngoãn nghe lời thì cuối tuần mẹ sẽ đưa con đi sở thú."}],"related":[{"hanzi":"乖","pinyin":"guāi","vi":"ngoan"},{"hanzi":"听从","pinyin":"tīngcóng","vi":"nghe theo"},{"hanzi":"淘气","pinyin":"táoqì","vi":"nghịch ngợm"},{"hanzi":"懂事","pinyin":"dǒngshì","vi":"hiểu chuyện"}],"traditional":"聽話"},{"id":"停车位","hanzi":"停车位","pinyin":"tíngchēwèi","meaning_vi":"chỗ đỗ xe","explanation":"停车 (đình xa – đỗ xe) + 位 (vị – chỗ) → ô, chỗ dành để đỗ xe.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🅿️","examples":[{"type":"basic","zh":"这里没有停车位。","pinyin":"Zhèlǐ méiyǒu tíngchēwèi.","vi":"Ở đây không có chỗ đỗ xe."},{"type":"simple","zh":"周末商场附近很难找到停车位。","pinyin":"Zhōumò shāngchǎng fùjìn hěn nán zhǎodào tíngchēwèi.","vi":"Cuối tuần rất khó tìm chỗ đỗ xe gần trung tâm thương mại."},{"type":"compound","zh":"因为小区停车位太少，所以很多车只能停在路边。","pinyin":"Yīnwèi xiǎoqū tíngchēwèi tài shǎo, suǒyǐ hěn duō chē zhǐnéng tíng zài lùbiān.","vi":"Vì khu dân cư quá ít chỗ đỗ xe nên nhiều xe chỉ đành đỗ bên đường."}],"related":[{"hanzi":"停车场","pinyin":"tíngchēchǎng","vi":"bãi đỗ xe"},{"hanzi":"车位","pinyin":"chēwèi","vi":"chỗ đỗ xe"},{"hanzi":"停车","pinyin":"tíngchē","vi":"đỗ xe"},{"hanzi":"车库","pinyin":"chēkù","vi":"nhà để xe"}],"traditional":"停車位"},{"id":"停电","hanzi":"停电","pinyin":"tíngdiàn","meaning_vi":"mất điện, cúp điện","explanation":"停 (đình – dừng) + 电 (điện – điện) → ngừng cung cấp điện.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🔌","examples":[{"type":"basic","zh":"昨晚突然停电了。","pinyin":"Zuówǎn tūrán tíngdiàn le.","vi":"Tối qua đột nhiên mất điện."},{"type":"simple","zh":"明天上午这一带要停电四个小时。","pinyin":"Míngtiān shàngwǔ zhè yídài yào tíngdiàn sì ge xiǎoshí.","vi":"Sáng mai khu vực này sẽ cúp điện bốn tiếng."},{"type":"compound","zh":"因为停电了，所以我们只好点蜡烛吃晚饭。","pinyin":"Yīnwèi tíngdiàn le, suǒyǐ wǒmen zhǐhǎo diǎn làzhú chī wǎnfàn.","vi":"Vì mất điện nên chúng tôi đành thắp nến ăn tối."}],"related":[{"hanzi":"断电","pinyin":"duàndiàn","vi":"ngắt điện"},{"hanzi":"来电","pinyin":"láidiàn","vi":"có điện lại"},{"hanzi":"停水","pinyin":"tíngshuǐ","vi":"cúp nước"},{"hanzi":"电力","pinyin":"diànlì","vi":"điện lực"}],"traditional":"停電"},{"id":"停放","hanzi":"停放","pinyin":"tíngfàng","meaning_vi":"đỗ, đậu (xe), để tạm","explanation":"停 (đình – dừng) + 放 (phóng – đặt, để) → để xe hoặc đồ vật dừng tại một chỗ.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"车辆请停放整齐。","pinyin":"Chēliàng qǐng tíngfàng zhěngqí.","vi":"Xe vui lòng đỗ ngay ngắn."},{"type":"simple","zh":"共享单车不能随便停放在人行道上。","pinyin":"Gòngxiǎng dānchē bù néng suíbiàn tíngfàng zài rénxíngdào shang.","vi":"Xe đạp công cộng không được tùy tiện đỗ trên vỉa hè."},{"type":"compound","zh":"如果车辆违规停放，就会被交警拖走。","pinyin":"Rúguǒ chēliàng wéiguī tíngfàng, jiù huì bèi jiāojǐng tuōzǒu.","vi":"Nếu xe đỗ sai quy định thì sẽ bị cảnh sát giao thông kéo đi."}],"related":[{"hanzi":"停车","pinyin":"tíngchē","vi":"đỗ xe"},{"hanzi":"放置","pinyin":"fàngzhì","vi":"đặt để"},{"hanzi":"停靠","pinyin":"tíngkào","vi":"đậu, cập bến"},{"hanzi":"存放","pinyin":"cúnfàng","vi":"cất giữ"}]},{"id":"通车","hanzi":"通车","pinyin":"tōngchē","meaning_vi":"thông xe, có tuyến xe chạy","explanation":"通 (thông – thông suốt) + 车 (xa – xe) → đường, cầu mới mở cho xe chạy qua; hoặc có tuyến xe đến một nơi.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚆","examples":[{"type":"basic","zh":"新大桥今天通车了。","pinyin":"Xīn Dàqiáo jīntiān tōngchē le.","vi":"Cây cầu mới hôm nay đã thông xe."},{"type":"simple","zh":"这条高铁预计明年年底正式通车。","pinyin":"Zhè tiáo gāotiě yùjì míngnián niándǐ zhèngshì tōngchē.","vi":"Tuyến đường sắt cao tốc này dự kiến cuối năm sau chính thức thông xe."},{"type":"compound","zh":"因为山区通车了，所以村民进城方便多了。","pinyin":"Yīnwèi shānqū tōngchē le, suǒyǐ cūnmín jìnchéng fāngbiàn duō le.","vi":"Vì vùng núi đã có đường xe chạy nên người dân lên thành phố thuận tiện hơn nhiều."}],"related":[{"hanzi":"通行","pinyin":"tōngxíng","vi":"thông hành"},{"hanzi":"开通","pinyin":"kāitōng","vi":"khai thông"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"giao thông"},{"hanzi":"修路","pinyin":"xiūlù","vi":"làm đường"}],"traditional":"通車"},{"id":"通风","hanzi":"通风","pinyin":"tōngfēng","meaning_vi":"thông gió, thoáng khí","explanation":"通 (thông – thông suốt) + 风 (phong – gió) → cho gió lưu thông, làm thoáng khí; nghĩa bóng là báo tin lén (通风报信).","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🌬️","examples":[{"type":"basic","zh":"房间要经常通风。","pinyin":"Fángjiān yào jīngcháng tōngfēng.","vi":"Phòng cần thường xuyên thông gió."},{"type":"simple","zh":"新装修的房子至少要通风两个月。","pinyin":"Xīn zhuāngxiū de fángzi zhìshǎo yào tōngfēng liǎng geyuè.","vi":"Nhà mới sửa xong phải thông gió ít nhất hai tháng."},{"type":"compound","zh":"如果厨房不通风，油烟就会散不出去。","pinyin":"Rúguǒ chúfáng bù tōngfēng, yóuyān jiù huì sàn bù chūqù.","vi":"Nếu bếp không thông gió thì khói dầu mỡ sẽ không thoát ra được."}],"related":[{"hanzi":"透气","pinyin":"tòuqì","vi":"thoáng khí"},{"hanzi":"空气","pinyin":"kōngqì","vi":"không khí"},{"hanzi":"通气","pinyin":"tōngqì","vi":"thông hơi"},{"hanzi":"闷","pinyin":"mēn","vi":"ngột ngạt"}],"traditional":"通風"},{"id":"通告","hanzi":"通告","pinyin":"tōnggào","meaning_vi":"thông cáo, thông báo","explanation":"通 (thông – khắp) + 告 (cáo – báo) → báo cho mọi người cùng biết; tờ thông báo công khai.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📢","examples":[{"type":"basic","zh":"门口贴了一张通告。","pinyin":"Ménkǒu tiēle yì zhāng tōnggào.","vi":"Ở cửa có dán một tờ thông báo."},{"type":"simple","zh":"学校发出通告，明天停课一天。","pinyin":"Xuéxiào fāchū tōnggào, míngtiān tíngkè yì tiān.","vi":"Trường ra thông báo ngày mai nghỉ học một ngày."},{"type":"compound","zh":"一旦收到台风通告，渔船就必须马上回港。","pinyin":"Yídàn shōudào táifēng tōnggào, yúchuán jiù bìxū mǎshàng huí gǎng.","vi":"Một khi nhận được thông báo bão thì tàu cá phải lập tức về cảng."}],"related":[{"hanzi":"通知","pinyin":"tōngzhī","vi":"thông báo"},{"hanzi":"公告","pinyin":"gōnggào","vi":"công cáo"},{"hanzi":"布告","pinyin":"bùgào","vi":"bố cáo"},{"hanzi":"宣布","pinyin":"xuānbù","vi":"tuyên bố"}]},{"id":"通通","hanzi":"通通","pinyin":"tōngtōng","meaning_vi":"tất cả, toàn bộ, hết thảy","explanation":"通 (thông – khắp, suốt) lặp lại → nhấn mạnh \"hết thảy, toàn bộ\"; là khẩu ngữ, tương đương 全部.","hsk_level":"7-9","tags":["pho-tu","so-luong"],"image":"📦","examples":[{"type":"basic","zh":"把垃圾通通扔掉。","pinyin":"Bǎ lājī tōngtōng rēngdiào.","vi":"Vứt hết rác đi."},{"type":"simple","zh":"他把攒下来的零花钱通通捐给了灾区。","pinyin":"Tā bǎ zǎn xiàlái de línghuāqián tōngtōng juāngěile zāiqū.","vi":"Cậu ấy quyên toàn bộ tiền tiêu vặt dành dụm được cho vùng thiên tai."},{"type":"compound","zh":"只要是过期的食品，就通通不许上架。","pinyin":"Zhǐ yàoshì guòqī de shípǐn, jiù tōngtōng bùxǔ shàngjià.","vi":"Chỉ cần là thực phẩm hết hạn thì tuyệt đối không được lên kệ."}],"related":[{"hanzi":"全部","pinyin":"quánbù","vi":"toàn bộ"},{"hanzi":"统统","pinyin":"tǒngtǒng","vi":"hết thảy"},{"hanzi":"所有","pinyin":"suǒyǒu","vi":"tất cả"},{"hanzi":"一律","pinyin":"yílǜ","vi":"nhất loạt"}]},{"id":"通宵","hanzi":"通宵","pinyin":"tōngxiāo","meaning_vi":"suốt đêm, thâu đêm","explanation":"通 (thông – suốt) + 宵 (tiêu – đêm) → suốt cả đêm.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌙","examples":[{"type":"basic","zh":"他昨晚熬了通宵。","pinyin":"Tā zuówǎn áole tōngxiāo.","vi":"Tối qua anh ấy thức trắng đêm."},{"type":"simple","zh":"年轻人在网吧里通宵玩游戏。","pinyin":"Niánqīngrén zài wǎngbā li tōngxiāo wán yóuxì.","vi":"Thanh niên chơi game thâu đêm trong quán net."},{"type":"compound","zh":"虽然通宵复习很辛苦，但是第二天考试他一点也不困。","pinyin":"Suīrán tōngxiāo fùxí hěn xīnkǔ, dànshì dì'èrtiān kǎoshì tā yìdiǎn yě bú kùn.","vi":"Tuy ôn bài suốt đêm rất vất vả nhưng hôm sau thi cậu ấy chẳng buồn ngủ chút nào."}],"related":[{"hanzi":"熬夜","pinyin":"áoyè","vi":"thức khuya"},{"hanzi":"整夜","pinyin":"zhěngyè","vi":"cả đêm"},{"hanzi":"彻夜","pinyin":"chèyè","vi":"suốt đêm"},{"hanzi":"夜里","pinyin":"yèli","vi":"ban đêm"}]},{"id":"通行证","hanzi":"通行证","pinyin":"tōngxíngzhèng","meaning_vi":"giấy thông hành, thẻ ra vào","explanation":"通行 (thông hành – đi qua) + 证 (chứng – giấy chứng nhận) → giấy cho phép ra vào, qua lại một nơi.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🎫","examples":[{"type":"basic","zh":"请出示通行证。","pinyin":"Qǐng chūshì tōngxíngzhèng.","vi":"Vui lòng xuất trình giấy thông hành."},{"type":"simple","zh":"记者凭通行证进入了比赛现场。","pinyin":"Jìzhě píng tōngxíngzhèng jìnrùle bǐsài xiànchǎng.","vi":"Phóng viên vào hiện trường thi đấu nhờ thẻ thông hành."},{"type":"compound","zh":"如果没有通行证，保安就不会让你进园区。","pinyin":"Rúguǒ méiyǒu tōngxíngzhèng, bǎo'ān jiù bú huì ràng nǐ jìn yuánqū.","vi":"Nếu không có thẻ ra vào thì bảo vệ sẽ không cho bạn vào khu."}],"related":[{"hanzi":"证件","pinyin":"zhèngjiàn","vi":"giấy tờ"},{"hanzi":"护照","pinyin":"hùzhào","vi":"hộ chiếu"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"thị thực"},{"hanzi":"通行","pinyin":"tōngxíng","vi":"đi qua"}],"traditional":"通行證"},{"id":"同伴","hanzi":"同伴","pinyin":"tóngbàn","meaning_vi":"bạn đồng hành, bạn cùng nhóm","explanation":"同 (đồng – cùng) + 伴 (bạn – người đi cùng) → người cùng làm, cùng đi với mình.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👫","examples":[{"type":"basic","zh":"他找不到同伴了。","pinyin":"Tā zhǎobúdào tóngbàn le.","vi":"Cậu ấy không tìm thấy bạn đồng hành nữa."},{"type":"simple","zh":"小猴子跟着同伴在树上跳来跳去。","pinyin":"Xiǎo hóuzi gēnzhe tóngbàn zài shù shang tiào lái tiào qù.","vi":"Chú khỉ con theo bạn bè nhảy qua nhảy lại trên cây."},{"type":"compound","zh":"虽然路途很艰难，但是有同伴互相鼓励，他们终于登上了山顶。","pinyin":"Suīrán lùtú hěn jiānnán, dànshì yǒu tóngbàn hùxiāng gǔlì, tāmen zhōngyú dēngshàngle shāndǐng.","vi":"Tuy đường đi rất gian nan nhưng có bạn đồng hành động viên nhau, cuối cùng họ đã lên tới đỉnh núi."}],"related":[{"hanzi":"伙伴","pinyin":"huǒbàn","vi":"bạn đồng hành"},{"hanzi":"同伙","pinyin":"tónghuǒ","vi":"đồng bọn"},{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"},{"hanzi":"陪伴","pinyin":"péibàn","vi":"bầu bạn"}]},{"id":"同步","hanzi":"同步","pinyin":"tóngbù","meaning_vi":"đồng bộ, đồng thời, song song","explanation":"同 (đồng – cùng) + 步 (bộ – bước) → cùng bước, diễn ra cùng lúc; trong công nghệ là đồng bộ dữ liệu.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔁","examples":[{"type":"basic","zh":"手机和电脑已同步。","pinyin":"Shǒujī hé diànnǎo yǐ tóngbù.","vi":"Điện thoại và máy tính đã đồng bộ."},{"type":"simple","zh":"这部电影将在全球同步上映。","pinyin":"Zhè bù diànyǐng jiāng zài quánqiú tóngbù shàngyìng.","vi":"Bộ phim này sẽ khởi chiếu đồng thời trên toàn cầu."},{"type":"compound","zh":"只要打开云备份，照片就会自动同步到新手机上。","pinyin":"Zhǐyào dǎkāi yún bèifèn, zhàopiàn jiù huì zìdòng tóngbù dào xīnshǒu jī shang.","vi":"Chỉ cần bật sao lưu đám mây thì ảnh sẽ tự đồng bộ sang điện thoại mới."}],"related":[{"hanzi":"同时","pinyin":"tóngshí","vi":"đồng thời"},{"hanzi":"一致","pinyin":"yízhì","vi":"nhất trí"},{"hanzi":"异步","pinyin":"yìbù","vi":"không đồng bộ"},{"hanzi":"同期","pinyin":"tóngqī","vi":"cùng kỳ"}]},{"id":"同感","hanzi":"同感","pinyin":"tónggǎn","meaning_vi":"cùng cảm nhận, đồng cảm","explanation":"同 (đồng – cùng) + 感 (cảm – cảm giác) → có cùng cảm nhận, cùng một ấn tượng với người khác.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"对此我深有同感。","pinyin":"Duì cǐ wǒ shēn yǒu tónggǎn.","vi":"Về điều này tôi cũng cảm thấy y như vậy."},{"type":"simple","zh":"听了她的发言，在场的很多人都有同感。","pinyin":"Tīngle tā de fāyán, zài chǎng de hěn duō rén dōu yǒu tónggǎn.","vi":"Nghe cô ấy phát biểu, nhiều người có mặt đều có cùng cảm nhận."},{"type":"compound","zh":"虽然我们来自不同的国家，但是对这个问题却有同感。","pinyin":"Suīrán wǒmen láizì bùtóng de guójiā, dànshì duì zhè ge wèntí què yǒu tónggǎn.","vi":"Tuy chúng tôi đến từ các nước khác nhau nhưng lại có cùng cảm nhận về vấn đề này."}],"related":[{"hanzi":"共鸣","pinyin":"gòngmíng","vi":"đồng cảm, cộng hưởng"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"thông cảm"},{"hanzi":"感受","pinyin":"gǎnshòu","vi":"cảm nhận"},{"hanzi":"认同","pinyin":"rèntóng","vi":"đồng tình"}]},{"id":"同伙","hanzi":"同伙","pinyin":"tónghuǒ","meaning_vi":"đồng bọn, tòng phạm","explanation":"同 (đồng – cùng) + 伙 (hỏa – bọn, nhóm) → người cùng bọn, thường chỉ kẻ cùng làm việc xấu.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🦹","examples":[{"type":"basic","zh":"警察抓住了他的同伙。","pinyin":"Jǐngchá zhuāzhùle tā de tónghuǒ.","vi":"Cảnh sát đã bắt được đồng bọn của hắn."},{"type":"simple","zh":"小偷在逃跑时被同伙丢下了。","pinyin":"Xiǎotōu zài táopǎo shí bèi tónghuǒ diūxià le.","vi":"Tên trộm bị đồng bọn bỏ lại khi đang chạy trốn."},{"type":"compound","zh":"如果你说出同伙的下落，法院就可能从轻处罚。","pinyin":"Rúguǒ nǐ shuōchū tónghuǒ de xiàluò, fǎyuàn jiù kěnéng cóng qīng chǔfá.","vi":"Nếu anh khai ra tung tích đồng bọn thì tòa có thể xử nhẹ."}],"related":[{"hanzi":"团伙","pinyin":"tuánhuǒ","vi":"băng nhóm"},{"hanzi":"同谋","pinyin":"tóngmóu","vi":"đồng mưu"},{"hanzi":"共犯","pinyin":"gòngfàn","vi":"đồng phạm"},{"hanzi":"伙伴","pinyin":"huǒbàn","vi":"bạn đồng hành"}],"traditional":"同夥"},{"id":"同年","hanzi":"同年","pinyin":"tóngnián","meaning_vi":"cùng năm, năm đó","explanation":"同 (đồng – cùng) + 年 (niên – năm) → cùng một năm; cũng chỉ người cùng tuổi.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"我们是同年出生的。","pinyin":"Wǒmen shì tóngnián chūshēng de.","vi":"Chúng tôi sinh cùng năm."},{"type":"simple","zh":"他大学毕业后同年考上了公务员。","pinyin":"Tā dàxué bìyè hòu tóngnián kǎoshàngle gōngwùyuán.","vi":"Anh ấy tốt nghiệp đại học rồi ngay năm đó thi đỗ công chức."},{"type":"compound","zh":"虽然他们是同年入职的，但是现在职位相差很大。","pinyin":"Suīrán tāmen shì tóngnián rùzhí de, dànshì xiànzài zhíwèi xiāngchà hěn dà.","vi":"Tuy họ vào làm cùng năm nhưng hiện nay chức vụ chênh lệch rất nhiều."}],"related":[{"hanzi":"同龄","pinyin":"tónglíng","vi":"cùng tuổi"},{"hanzi":"当年","pinyin":"dāngnián","vi":"năm đó"},{"hanzi":"同期","pinyin":"tóngqī","vi":"cùng kỳ"},{"hanzi":"同岁","pinyin":"tóngsuì","vi":"cùng tuổi"}]},{"id":"同人","hanzi":"同人","pinyin":"tóngrén","meaning_vi":"người cùng ngành, đồng nghiệp; (văn hóa) đồng nhân, fan sáng tác","explanation":"同 (đồng – cùng) + 人 (nhân – người) → người cùng nghề, cùng giới; nay còn chỉ tác phẩm do fan sáng tác lại từ truyện, phim gốc.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"✍️","examples":[{"type":"basic","zh":"她喜欢写同人小说。","pinyin":"Tā xǐhuan xiě tóngrén xiǎoshuō.","vi":"Cô ấy thích viết truyện đồng nhân (fanfic)."},{"type":"simple","zh":"这本杂志是几位业界同人一起创办的。","pinyin":"Zhè běn zázhì shì jǐ wèi yèjiè tóngrén yìqǐ chuàngbàn de.","vi":"Tạp chí này do mấy người cùng ngành cùng sáng lập."},{"type":"compound","zh":"因为原作太受欢迎了，所以网上出现了大量同人作品。","pinyin":"Yīnwèi yuánzuò tài shòuhuānyíng le, suǒyǐ wǎngshang chūxiànle dàliàng tóngrén zuòpǐn.","vi":"Vì tác phẩm gốc quá được yêu thích nên trên mạng xuất hiện rất nhiều tác phẩm đồng nhân."}],"related":[{"hanzi":"同行","pinyin":"tóngháng","vi":"người cùng ngành"},{"hanzi":"同事","pinyin":"tóngshì","vi":"đồng nghiệp"},{"hanzi":"粉丝","pinyin":"fěnsī","vi":"người hâm mộ"},{"hanzi":"原作","pinyin":"yuánzuò","vi":"nguyên tác"}]},{"id":"同志","hanzi":"同志","pinyin":"tóngzhì","meaning_vi":"đồng chí; (khẩu ngữ) người đồng tính","explanation":"同 (đồng – cùng) + 志 (chí – chí hướng) → người cùng chí hướng, đồng chí; trong khẩu ngữ hiện đại còn chỉ người đồng tính.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"同志们，辛苦了！","pinyin":"Tóngzhìmen, xīnkǔ le!","vi":"Các đồng chí vất vả rồi!"},{"type":"simple","zh":"老王是一位工作认真的好同志。","pinyin":"Lǎo Wáng shì yí wèi gōngzuò rènzhēn de hǎo tóngzhì.","vi":"Ông Vương là một đồng chí tốt, làm việc nghiêm túc."},{"type":"compound","zh":"虽然大家来自不同部门，但是都是并肩奋斗的同志。","pinyin":"Suīrán dàjiā láizì bùtóng bùmén, dànshì dōu shì bìngjiān fèndòu de tóngzhì.","vi":"Tuy mọi người đến từ các bộ phận khác nhau nhưng đều là đồng chí sát cánh phấn đấu."}],"related":[{"hanzi":"同事","pinyin":"tóngshì","vi":"đồng nghiệp"},{"hanzi":"战友","pinyin":"zhànyǒu","vi":"chiến hữu"},{"hanzi":"志同道合","pinyin":"zhìtóngdàohé","vi":"chí đồng đạo hợp"},{"hanzi":"同胞","pinyin":"tóngbāo","vi":"đồng bào"}]},{"id":"铜","hanzi":"铜","pinyin":"tóng","meaning_vi":"đồng (kim loại)","explanation":"铜 (đồng): bộ 金 (kim loại) + 同 (đồng – gợi âm) → kim loại đồng màu đỏ vàng, dẫn điện tốt.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🥉","examples":[{"type":"basic","zh":"这是一枚铜币。","pinyin":"Zhè shì yìméi tóng bì.","vi":"Đây là một đồng xu bằng đồng."},{"type":"simple","zh":"他在比赛中获得了一块铜牌。","pinyin":"Tā zài bǐsài zhōng huòdéle yíkuài tóngpái.","vi":"Anh ấy giành được một tấm huy chương đồng trong cuộc thi."},{"type":"compound","zh":"因为铜的导电性能好，所以电线大多用铜做。","pinyin":"Yīnwèi tóng de dǎodiàn xìngnéng hǎo, suǒyǐ diànxiàn dà duōyòng tóng zuò.","vi":"Vì đồng dẫn điện tốt nên dây điện phần lớn làm bằng đồng."}],"related":[{"hanzi":"铜牌","pinyin":"tóngpái","vi":"huy chương đồng"},{"hanzi":"铁","pinyin":"tiě","vi":"sắt"},{"hanzi":"金属","pinyin":"jīnshǔ","vi":"kim loại"},{"hanzi":"青铜","pinyin":"qīngtóng","vi":"đồng thanh"}],"traditional":"銅"},{"id":"统治","hanzi":"统治","pinyin":"tǒngzhì","meaning_vi":"thống trị, cai trị","explanation":"统 (thống – thống lĩnh) + 治 (trị – cai trị) → nắm quyền cai trị một quốc gia, khu vực.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"国王统治了四十年。","pinyin":"Guówáng tǒngzhìle sìshí nián.","vi":"Nhà vua đã trị vì bốn mươi năm."},{"type":"simple","zh":"这个地区曾被外国殖民者统治了一百多年。","pinyin":"Zhè ge dìqū céng bèi wàiguó zhímínzhě tǒngzhìle yī bǎi duōnián.","vi":"Khu vực này từng bị thực dân nước ngoài thống trị hơn một trăm năm."},{"type":"compound","zh":"虽然他的统治很严酷，但是国家的经济却发展得很快。","pinyin":"Suīrán tā de tǒngzhì hěn yánkù, dànshì guójiā de jīngjì què fāzhǎn de hěn kuài.","vi":"Tuy sự cai trị của ông ta rất hà khắc nhưng kinh tế đất nước lại phát triển nhanh."}],"related":[{"hanzi":"统治者","pinyin":"tǒngzhìzhě","vi":"kẻ thống trị"},{"hanzi":"政权","pinyin":"zhèngquán","vi":"chính quyền"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"quản lý"},{"hanzi":"王朝","pinyin":"wángcháo","vi":"vương triều"}],"traditional":"統治"},{"id":"捅","hanzi":"捅","pinyin":"tǒng","meaning_vi":"chọc, đâm, thọc; huých; làm lộ ra","explanation":"捅 (thống): bộ 扌 (tay) → dùng tay hoặc vật nhọn chọc, đâm; nghĩa bóng 捅出去 là để lộ chuyện ra ngoài.","hsk_level":"7-9","tags":["dong-tu"],"image":"👉","examples":[{"type":"basic","zh":"别用棍子捅鸟窝。","pinyin":"Bié yòng gùnzi tǒng niǎowō.","vi":"Đừng lấy gậy chọc tổ chim."},{"type":"simple","zh":"他悄悄用胳膊肘捅了我一下。","pinyin":"Tā qiāoqiāo yòng gēbozhǒu tǒngle wǒ yíxià.","vi":"Anh ấy lén huých khuỷu tay vào tôi một cái."},{"type":"compound","zh":"如果你把这件事捅出去，公司就会陷入大麻烦。","pinyin":"Rúguǒ nǐ bǎ zhè jiàn shì tǒng chūqù, gōngsī jiù huì xiànrù dà máfan.","vi":"Nếu bạn để lộ chuyện này ra ngoài thì công ty sẽ gặp rắc rối lớn."}],"related":[{"hanzi":"戳","pinyin":"chuō","vi":"chọc"},{"hanzi":"刺","pinyin":"cì","vi":"đâm"},{"hanzi":"捅娄子","pinyin":"tǒnglóuzi","vi":"gây họa"},{"hanzi":"推","pinyin":"tuī","vi":"đẩy"}]},{"id":"桶","hanzi":"桶","pinyin":"tǒng","meaning_vi":"thùng, xô; (lượng từ) thùng","explanation":"桶 (dũng): bộ 木 (gỗ) → đồ đựng hình trụ, xưa làm bằng gỗ; cũng là lượng từ như 一桶水.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🪣","examples":[{"type":"basic","zh":"我提了一桶水。","pinyin":"Wǒ tíle yì tǒng shuǐ.","vi":"Tôi xách một xô nước."},{"type":"simple","zh":"请把垃圾扔进门口的垃圾桶里。","pinyin":"Qǐng bǎ lājī rēng jìn ménkǒu de lājītǒng li.","vi":"Hãy vứt rác vào thùng rác ở cửa."},{"type":"compound","zh":"因为国际油价上涨，所以每桶原油贵了五美元。","pinyin":"Yīnwèi Guójì yóujià shàngzhǎng, suǒyǐ měi tǒng yuányóu guìle wǔ měiyuán.","vi":"Vì giá dầu thế giới tăng nên mỗi thùng dầu thô đắt thêm năm đô la."}],"related":[{"hanzi":"水桶","pinyin":"shuǐtǒng","vi":"xô nước"},{"hanzi":"垃圾桶","pinyin":"lājītǒng","vi":"thùng rác"},{"hanzi":"木桶","pinyin":"mùtǒng","vi":"thùng gỗ"},{"hanzi":"盆","pinyin":"pén","vi":"chậu"}]},{"id":"筒","hanzi":"筒","pinyin":"tǒng","meaning_vi":"ống, ống tròn","explanation":"筒 (đồng): bộ 竹 (tre) → đoạn ống tre; chỉ vật hình ống như 笔筒 (ống bút), 话筒 (micro).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🎋","examples":[{"type":"basic","zh":"桌上有个笔筒。","pinyin":"Zhuō shang yǒu ge bǐtǒng.","vi":"Trên bàn có một ống bút."},{"type":"simple","zh":"他对着话筒唱了一首老歌。","pinyin":"Tā duìzhe huàtǒng chàngle yì shǒu lǎogē.","vi":"Anh ấy hát một bài hát cũ vào micro."},{"type":"compound","zh":"如果邮筒已经满了，就把信交给邮局吧。","pinyin":"Rúguǒ yóutǒng yǐjīng mǎn le, jiù bǎ xìn jiāogěi yóujú ba.","vi":"Nếu hòm thư đã đầy thì hãy đưa thư cho bưu điện."}],"related":[{"hanzi":"笔筒","pinyin":"bǐtǒng","vi":"ống bút"},{"hanzi":"话筒","pinyin":"huàtǒng","vi":"micro"},{"hanzi":"竹筒","pinyin":"zhútǒng","vi":"ống tre"},{"hanzi":"邮筒","pinyin":"yóutǒng","vi":"hòm thư"}]},{"id":"偷看","hanzi":"偷看","pinyin":"tōukàn","meaning_vi":"nhìn trộm, xem lén","explanation":"偷 (thâu – lén, trộm) + 看 (khán – nhìn) → lén lút nhìn khi người khác không biết.","hsk_level":"7-9","tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"不许偷看答案！","pinyin":"Bùxǔ tōukàn dá'àn!","vi":"Không được nhìn trộm đáp án!"},{"type":"simple","zh":"她趁妹妹不在偷看了她的日记。","pinyin":"Tā chèn mèimei bú zài tōukànle tā de rìjì.","vi":"Cô ấy nhân lúc em gái vắng nhà đọc trộm nhật ký của em."},{"type":"compound","zh":"虽然他很想偷看礼物，但是还是忍到了生日那天。","pinyin":"Suīrán tā hěn xiǎng tōukàn lǐwù, dànshì háishi rěn dàole shēngrì nà tiān.","vi":"Tuy rất muốn xem trộm quà nhưng cậu ấy vẫn nhịn đến ngày sinh nhật."}],"related":[{"hanzi":"偷窥","pinyin":"tōukuī","vi":"nhìn trộm"},{"hanzi":"偷听","pinyin":"tōutīng","vi":"nghe lén"},{"hanzi":"偷偷","pinyin":"tōutōu","vi":"lén lút"},{"hanzi":"窥视","pinyin":"kuīshì","vi":"dòm ngó"}]},{"id":"偷窥","hanzi":"偷窥","pinyin":"tōukuī","meaning_vi":"nhìn trộm, rình mò","explanation":"偷 (thâu – lén) + 窥 (khuy – dòm qua khe) → lén dòm ngó đời tư người khác, mang nghĩa xấu.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🕵️","examples":[{"type":"basic","zh":"偷窥他人是违法的。","pinyin":"Tōukuī tārén shì wéifǎ de.","vi":"Nhìn trộm người khác là phạm pháp."},{"type":"simple","zh":"有人在酒店房间里安装摄像头偷窥客人。","pinyin":"Yǒurén zài jiǔdiàn fángjiān li ānzhuāng shèxiàngtóu tōukuī kèrén.","vi":"Có kẻ lắp camera trong phòng khách sạn để nhìn trộm khách."},{"type":"compound","zh":"一旦发现有人偷窥，你就应该立刻报警。","pinyin":"Yídàn fāxiàn yǒurén tōukuī, nǐ jiù yīnggāi lìkè bàojǐng.","vi":"Một khi phát hiện có người nhìn trộm thì bạn nên lập tức báo cảnh sát."}],"related":[{"hanzi":"偷看","pinyin":"tōukàn","vi":"xem lén"},{"hanzi":"窥探","pinyin":"kuītàn","vi":"dò xét"},{"hanzi":"隐私","pinyin":"yǐnsī","vi":"quyền riêng tư"},{"hanzi":"监视","pinyin":"jiānshì","vi":"giám sát"}],"traditional":"偷窺"},{"id":"头部","hanzi":"头部","pinyin":"tóubù","meaning_vi":"phần đầu, vùng đầu","explanation":"头 (đầu – cái đầu) + 部 (bộ – bộ phận) → bộ phận đầu của cơ thể hoặc phần đầu của vật.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🧠","examples":[{"type":"basic","zh":"他头部受了伤。","pinyin":"Tā tóubù shòule shāng.","vi":"Anh ấy bị thương ở đầu."},{"type":"simple","zh":"骑摩托车一定要戴头盔保护头部。","pinyin":"Qí mótuōchē yídìngyào dài tóukuī bǎohù tóubù.","vi":"Đi xe máy nhất định phải đội mũ bảo hiểm để bảo vệ đầu."},{"type":"compound","zh":"如果头部受到重击，就可能导致脑震荡。","pinyin":"Rúguǒ tóubù shòudào zhòngjī, jiù kěnéng dǎozhì nǎozhèndàng.","vi":"Nếu đầu bị đánh mạnh thì có thể dẫn đến chấn động não."}],"related":[{"hanzi":"头","pinyin":"tóu","vi":"đầu"},{"hanzi":"脑袋","pinyin":"nǎodai","vi":"cái đầu"},{"hanzi":"颈部","pinyin":"jǐngbù","vi":"vùng cổ"},{"hanzi":"腹部","pinyin":"fùbù","vi":"vùng bụng"}],"traditional":"頭部"},{"id":"头顶","hanzi":"头顶","pinyin":"tóudǐng","meaning_vi":"đỉnh đầu; phía trên đầu","explanation":"头 (đầu) + 顶 (đỉnh – chóp) → chỗ cao nhất của đầu; cũng chỉ khoảng không ngay phía trên đầu.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🙆","examples":[{"type":"basic","zh":"他头顶有点秃了。","pinyin":"Tā tóudǐng yǒudiǎn tū le.","vi":"Đỉnh đầu anh ấy hơi hói rồi."},{"type":"simple","zh":"一架飞机从我们头顶上飞过。","pinyin":"Yí jià fēijī cóng wǒmen tóudǐng shang fēiguò.","vi":"Một chiếc máy bay bay qua trên đầu chúng tôi."},{"type":"compound","zh":"虽然太阳就在头顶上，但是树林里一点也不热。","pinyin":"Suīrán tàiyáng jiù zài tóudǐng shang, dànshì shùlín li yìdiǎn yě bú rè.","vi":"Tuy mặt trời ngay trên đỉnh đầu nhưng trong rừng chẳng nóng chút nào."}],"related":[{"hanzi":"头发","pinyin":"tóufa","vi":"tóc"},{"hanzi":"头部","pinyin":"tóubù","vi":"phần đầu"},{"hanzi":"顶端","pinyin":"dǐngduān","vi":"đỉnh, chóp"},{"hanzi":"脚底","pinyin":"jiǎodǐ","vi":"lòng bàn chân"}],"traditional":"頭頂"},{"id":"头号","hanzi":"头号","pinyin":"tóuhào","meaning_vi":"số một, hàng đầu","explanation":"头 (đầu – đứng đầu) + 号 (hiệu – số hiệu) → mang số một, hạng nhất; hay dùng như 头号敌人, 头号新闻.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥇","examples":[{"type":"basic","zh":"他是头号嫌疑人。","pinyin":"Tā shì tóuhào xiányírén.","vi":"Hắn là nghi phạm số một."},{"type":"simple","zh":"环境污染已成为这座城市的头号难题。","pinyin":"Huánjìng wūrǎn yǐ chéngwéi zhè zuò chéngshì de tóuhào nántí.","vi":"Ô nhiễm môi trường đã trở thành vấn đề nan giải số một của thành phố này."},{"type":"compound","zh":"虽然他是队里的头号球星，但是从不摆架子。","pinyin":"Suīrán tā shì duì li de tóuhào qiúxīng, dànshì cóng bù bǎijiàzi.","vi":"Tuy là ngôi sao số một của đội nhưng anh ấy chưa bao giờ làm cao."}],"related":[{"hanzi":"第一","pinyin":"dìyī","vi":"thứ nhất"},{"hanzi":"一流","pinyin":"yìliú","vi":"hạng nhất"},{"hanzi":"首要","pinyin":"shǒuyào","vi":"hàng đầu"},{"hanzi":"头等","pinyin":"tóuděng","vi":"hạng nhất"}],"traditional":"頭號"},{"id":"头条","hanzi":"头条","pinyin":"tóutiáo","meaning_vi":"tin hàng đầu, tít trang nhất","explanation":"头 (đầu) + 条 (điều – mục, tin) → mục tin đứng đầu, tin nóng nhất trên báo, mạng; cũng là tên ứng dụng 今日头条.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📰","examples":[{"type":"basic","zh":"这条新闻上了头条。","pinyin":"Zhè tiáo xīnwén shàngle tóutiáo.","vi":"Tin này đã lên trang nhất."},{"type":"simple","zh":"他的离婚消息占据了各大网站的头条。","pinyin":"Tā de líhūn xiāoxi zhànjùle gè dà wǎngzhàn de tóutiáo.","vi":"Tin ly hôn của anh ấy chiếm tít đầu của các trang mạng lớn."},{"type":"compound","zh":"如果这件丑闻被曝光，明天就一定会上头条。","pinyin":"Rúguǒ zhè jiàn chǒuwén bèi bàoguāng, míngtiān jiù yídìng huì shàng tóutiáo.","vi":"Nếu vụ bê bối này bị phanh phui thì ngày mai chắc chắn lên tin hàng đầu."}],"related":[{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"},{"hanzi":"头版","pinyin":"tóubǎn","vi":"trang nhất"},{"hanzi":"热搜","pinyin":"rèsōu","vi":"tìm kiếm nóng"},{"hanzi":"报道","pinyin":"bàodào","vi":"đưa tin"}],"traditional":"頭條"},{"id":"头晕","hanzi":"头晕","pinyin":"tóuyūn","meaning_vi":"chóng mặt, choáng váng","explanation":"头 (đầu) + 晕 (vựng – choáng) → đầu choáng váng, quay cuồng.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😵","examples":[{"type":"basic","zh":"我有点头晕。","pinyin":"Wǒ yǒudiǎn tóuyūn.","vi":"Tôi hơi chóng mặt."},{"type":"simple","zh":"坐了一天的船让她头晕得厉害。","pinyin":"Zuòle yì tiān de chuán ràng tā tóuyūn de lìhai.","vi":"Ngồi tàu cả ngày khiến cô ấy chóng mặt dữ dội."},{"type":"compound","zh":"如果你感到头晕恶心，就先坐下来休息一下。","pinyin":"Rúguǒ nǐ gǎndào tóuyūn ěxin, jiù xiān zuò xiàlái xiūxi yíxià.","vi":"Nếu bạn thấy chóng mặt buồn nôn thì ngồi xuống nghỉ một chút trước đã."}],"related":[{"hanzi":"头疼","pinyin":"tóuténg","vi":"đau đầu"},{"hanzi":"晕车","pinyin":"yùnchē","vi":"say xe"},{"hanzi":"眩晕","pinyin":"xuànyùn","vi":"hoa mắt"},{"hanzi":"恶心","pinyin":"ěxin","vi":"buồn nôn"}],"traditional":"頭暈"},{"id":"投射","hanzi":"投射","pinyin":"tóushè","meaning_vi":"ném, phóng; chiếu (ánh sáng, ánh mắt)","explanation":"投 (đầu – ném) + 射 (xạ – bắn, chiếu) → ném, phóng tới mục tiêu; chiếu ánh sáng hay ánh mắt về một phía.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔦","examples":[{"type":"basic","zh":"阳光投射在墙上。","pinyin":"Yángguāng tóushè zài qiáng shang.","vi":"Ánh nắng chiếu lên tường."},{"type":"simple","zh":"所有人都向他投射出羡慕的目光。","pinyin":"Suǒyǒurén dōu xiàng tā tóushè chū xiànmù de mùguāng.","vi":"Mọi người đều hướng ánh mắt ngưỡng mộ về phía anh ấy."},{"type":"compound","zh":"因为灯光从背后投射过来，所以地上出现了长长的影子。","pinyin":"Yīnwèi dēngguāng cóng bèihòu tóushè guòlái, suǒyǐ dìshang chūxiànle cháng cháng de yǐngzi.","vi":"Vì ánh đèn chiếu từ phía sau nên trên mặt đất hiện ra cái bóng dài."}],"related":[{"hanzi":"照射","pinyin":"zhàoshè","vi":"chiếu sáng"},{"hanzi":"投影","pinyin":"tóuyǐng","vi":"phép chiếu"},{"hanzi":"反射","pinyin":"fǎnshè","vi":"phản xạ"},{"hanzi":"发射","pinyin":"fāshè","vi":"phóng"}]},{"id":"透过","hanzi":"透过","pinyin":"tòuguò","meaning_vi":"xuyên qua; thông qua","explanation":"透 (thấu – xuyên thấu) + 过 (quá – qua) → xuyên qua vật gì đó; nghĩa bóng là thông qua (hiện tượng để thấy bản chất).","hsk_level":"7-9","tags":["dong-tu"],"image":"🪟","examples":[{"type":"basic","zh":"阳光透过窗帘照进来。","pinyin":"Yángguāng tòuguò chuānglián zhào jìnlái.","vi":"Ánh nắng xuyên qua rèm chiếu vào."},{"type":"simple","zh":"我们要透过现象看清问题的本质。","pinyin":"Wǒmen yào tòuguò xiànxiàng kànqīng wèntí de běnzhì.","vi":"Chúng ta phải nhìn qua hiện tượng để thấy rõ bản chất vấn đề."},{"type":"compound","zh":"虽然隔着一层玻璃，但是透过它仍能看清外面的雪景。","pinyin":"Suīrán gézhe yīcéng bōli, dànshì tòuguò tā réng néng kànqīng wàimiàn de xuějǐng.","vi":"Tuy cách một lớp kính nhưng nhìn qua nó vẫn thấy rõ cảnh tuyết bên ngoài."}],"related":[{"hanzi":"通过","pinyin":"tōngguò","vi":"thông qua"},{"hanzi":"穿过","pinyin":"chuānguò","vi":"đi xuyên qua"},{"hanzi":"透明","pinyin":"tòumíng","vi":"trong suốt"},{"hanzi":"渗透","pinyin":"shèntòu","vi":"thẩm thấu"}],"traditional":"透過"},{"id":"透气","hanzi":"透气","pinyin":"tòuqì","meaning_vi":"thoáng khí, thông hơi; hít thở khí trời","explanation":"透 (thấu – thấu qua) + 气 (khí – không khí) → không khí lọt qua được; cũng chỉ ra ngoài hít thở cho thoải mái.","hsk_level":"7-9","tags":["dong-tu"],"image":"👕","examples":[{"type":"basic","zh":"这件衬衫很透气。","pinyin":"Zhè jiàn chènshān hěn tòuqì.","vi":"Chiếc áo sơ mi này rất thoáng."},{"type":"simple","zh":"纯棉的袜子比化纤的更透气。","pinyin":"Chúnmián de wàzi bǐ huàxiān de gèng tòuqì.","vi":"Tất cotton thoáng khí hơn tất sợi tổng hợp."},{"type":"compound","zh":"因为屋里实在太闷了，所以他走到阳台上透透气。","pinyin":"Yīnwèi wū li shízài tài mēn le, suǒyǐ tā zǒu dào yángtái shang tòu touqì.","vi":"Vì trong phòng quá ngột ngạt nên anh ấy ra ban công hít thở chút không khí."}],"related":[{"hanzi":"通风","pinyin":"tōngfēng","vi":"thông gió"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"},{"hanzi":"闷","pinyin":"mēn","vi":"bí bách"},{"hanzi":"透明","pinyin":"tòumíng","vi":"trong suốt"}],"traditional":"透氣"},{"id":"突发","hanzi":"突发","pinyin":"tūfā","meaning_vi":"bất ngờ xảy ra, đột phát","explanation":"突 (đột – đột ngột) + 发 (phát – phát sinh) → xảy ra một cách bất ngờ; hay dùng trong 突发事件, 突发疾病.","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"他突发心脏病。","pinyin":"Tā tūfā xīnzàngbìng.","vi":"Ông ấy đột ngột lên cơn đau tim."},{"type":"simple","zh":"公司要提前做好应对突发事件的准备。","pinyin":"Gōngsī yào tíqián zuò hǎo yìngduì tūfā shìjiàn de zhǔnbèi.","vi":"Công ty cần chuẩn bị trước để ứng phó sự cố bất ngờ."},{"type":"compound","zh":"一旦发生突发情况，乘客就要听从乘务员的指挥。","pinyin":"Yídàn fāshēng tūfā qíngkuàng, chéngkè jiùyào tīngcóng chéngwùyuán de zhǐhuī.","vi":"Một khi xảy ra tình huống bất ngờ thì hành khách phải nghe theo chỉ dẫn của tiếp viên."}],"related":[{"hanzi":"突然","pinyin":"tūrán","vi":"đột nhiên"},{"hanzi":"爆发","pinyin":"bàofā","vi":"bùng nổ"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"突如其来","pinyin":"tūrúqílái","vi":"bất thình lình"}],"traditional":"突發"},{"id":"突击","hanzi":"突击","pinyin":"tūjī","meaning_vi":"đột kích, tấn công bất ngờ; làm gấp, dốc sức hoàn thành","explanation":"突 (đột – xông tới) + 击 (kích – đánh) → bất ngờ xông vào tấn công; nghĩa bóng là dồn sức làm gấp cho xong.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"部队连夜突击敌营。","pinyin":"Bùduì liányè tūjī díyíng.","vi":"Bộ đội đột kích doanh trại địch ngay trong đêm."},{"type":"simple","zh":"考试前一晚他还在突击复习。","pinyin":"Kǎoshì qián yì wǎn tā hái zài tūjī fùxí.","vi":"Đêm trước kỳ thi cậu ấy vẫn còn ôn cấp tốc."},{"type":"compound","zh":"虽然突击检查让大家很紧张，但是结果一切正常。","pinyin":"Suīrán tūjī jiǎnchá ràng dàjiā hěn jǐnzhāng, dànshì jiéguǒ yíqiè zhèngcháng.","vi":"Tuy cuộc kiểm tra đột xuất khiến mọi người căng thẳng nhưng kết quả mọi thứ đều bình thường."}],"related":[{"hanzi":"袭击","pinyin":"xíjī","vi":"tập kích"},{"hanzi":"进攻","pinyin":"jìngōng","vi":"tấn công"},{"hanzi":"突破","pinyin":"tūpò","vi":"đột phá"},{"hanzi":"攻击","pinyin":"gōngjī","vi":"công kích"}],"traditional":"突擊"},{"id":"突如其来","hanzi":"突如其来","pinyin":"tūrú-qílái","meaning_vi":"bất thình lình, ập đến đột ngột","explanation":"突 (đột – bỗng) + 如 (như) + 其 (kỳ – nó) + 来 (lai – đến) → bỗng nhiên ập đến; xuất xứ Kinh Dịch, chỉ sự việc xảy ra quá bất ngờ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"昨天下了一场突如其来的暴雨。","pinyin":"Zuótiān xiàle yì chǎng tūrúqílái de bàoyǔ.","vi":"Hôm qua có một trận mưa lớn bất thình lình."},{"type":"simple","zh":"突如其来的消息让他一下子愣住了。","pinyin":"Tūrúqílái de xiāoxi ràng tā yíxiàzi lèngzhù le.","vi":"Tin tức bất ngờ khiến anh ấy sững sờ."},{"type":"compound","zh":"虽然这场疫情突如其来，但是医院很快就做出了反应。","pinyin":"Suīrán zhè chǎng yìqíng tūrúqílái, dànshì yīyuàn hěn kuài jiù zuòchūle fǎnyìng.","vi":"Tuy dịch bệnh ập đến đột ngột nhưng bệnh viện đã phản ứng rất nhanh."}],"related":[{"hanzi":"突然","pinyin":"tūrán","vi":"đột nhiên"},{"hanzi":"突发","pinyin":"tūfā","vi":"đột phát"},{"hanzi":"意想不到","pinyin":"yìxiǎngbúdào","vi":"không ngờ tới"},{"hanzi":"措手不及","pinyin":"cuòshǒubùjí","vi":"trở tay không kịp"}],"traditional":"突如其來"},{"id":"图表","hanzi":"图表","pinyin":"túbiǎo","meaning_vi":"biểu đồ, đồ thị","explanation":"图 (đồ – hình vẽ) + 表 (biểu – bảng) → hình vẽ và bảng biểu thể hiện số liệu.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📊","examples":[{"type":"basic","zh":"请看这张图表。","pinyin":"Qǐngkàn zhè zhāng túbiǎo.","vi":"Hãy xem biểu đồ này."},{"type":"simple","zh":"他用图表清楚地展示了销量变化。","pinyin":"Tāyòng túbiǎo qīngchu de zhǎnshìle xiāoliàng biànhuà.","vi":"Anh ấy dùng biểu đồ thể hiện rõ biến động doanh số."},{"type":"compound","zh":"如果把数据做成图表，大家就能一目了然。","pinyin":"Rúguǒ bǎ shùjù zuò chéng túbiǎo, dàjiā jiù néng yímùliǎorán.","vi":"Nếu làm dữ liệu thành biểu đồ thì mọi người nhìn là hiểu ngay."}],"related":[{"hanzi":"表格","pinyin":"biǎogé","vi":"bảng biểu"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"曲线","pinyin":"qūxiàn","vi":"đường cong"},{"hanzi":"图形","pinyin":"túxíng","vi":"hình vẽ"}],"traditional":"圖表"},{"id":"图像","hanzi":"图像","pinyin":"túxiàng","meaning_vi":"hình ảnh, ảnh","explanation":"图 (đồ – hình vẽ) + 像 (tượng – hình ảnh) → hình ảnh được vẽ, chụp hoặc hiển thị trên màn hình.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🖼️","examples":[{"type":"basic","zh":"图像有点模糊。","pinyin":"Túxiàng yǒudiǎn móhu.","vi":"Hình ảnh hơi mờ."},{"type":"simple","zh":"这台相机拍出的图像非常清晰。","pinyin":"Zhè tái xiàngjī pāichū de túxiàng fēicháng qīngxī.","vi":"Hình ảnh máy ảnh này chụp ra rất sắc nét."},{"type":"compound","zh":"只要上传一张图像，软件就能自动识别里面的文字。","pinyin":"Zhǐyào shàngchuán yì zhāng túxiàng, ruǎnjiàn jiù néng zìdòng shíbié lǐmiàn de wénzì.","vi":"Chỉ cần tải lên một ảnh là phần mềm có thể tự nhận diện chữ trong đó."}],"related":[{"hanzi":"图片","pinyin":"túpiàn","vi":"hình ảnh"},{"hanzi":"影像","pinyin":"yǐngxiàng","vi":"ảnh chụp"},{"hanzi":"画面","pinyin":"huàmiàn","vi":"khung hình"},{"hanzi":"像素","pinyin":"xiàngsù","vi":"điểm ảnh"}],"traditional":"圖像"},{"id":"图纸","hanzi":"图纸","pinyin":"túzhǐ","meaning_vi":"bản vẽ, bản thiết kế","explanation":"图 (đồ – hình vẽ) + 纸 (chỉ – giấy) → giấy có bản vẽ kỹ thuật, thiết kế công trình.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📐","examples":[{"type":"basic","zh":"工程师在看图纸。","pinyin":"Gōngchéngshī zài kàn túzhǐ.","vi":"Kỹ sư đang xem bản vẽ."},{"type":"simple","zh":"工人们按照图纸一步一步地组装机器。","pinyin":"Gōngrénmen ànzhào túzhǐ yí bù yi bù de zǔzhuāng jīqì.","vi":"Công nhân lắp ráp máy từng bước theo bản vẽ."},{"type":"compound","zh":"如果图纸上的尺寸有错，整座楼就可能出问题。","pinyin":"Rúguǒ túzhǐ shang de chǐcùn yǒu cuò, zhěng zuò lóu jiù kěnéng chūwèntí.","vi":"Nếu kích thước trên bản vẽ sai thì cả tòa nhà có thể gặp vấn đề."}],"related":[{"hanzi":"设计","pinyin":"shèjì","vi":"thiết kế"},{"hanzi":"蓝图","pinyin":"lántú","vi":"bản thiết kế"},{"hanzi":"工程","pinyin":"gōngchéng","vi":"công trình"},{"hanzi":"草图","pinyin":"cǎotú","vi":"bản phác thảo"}],"traditional":"圖紙"},{"id":"屠杀","hanzi":"屠杀","pinyin":"túshā","meaning_vi":"tàn sát, thảm sát","explanation":"屠 (đồ – giết mổ) + 杀 (sát – giết) → giết hại hàng loạt một cách tàn bạo.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🗡️","examples":[{"type":"basic","zh":"那是一场大屠杀。","pinyin":"Nàshì yì chǎng dàtúshā.","vi":"Đó là một cuộc đại thảm sát."},{"type":"simple","zh":"侵略者在这座城市里屠杀了无数平民。","pinyin":"Qīnlüèzhě zài zhè zuò chéng shìli túshāle wúshù píngmín.","vi":"Kẻ xâm lược đã tàn sát vô số dân thường trong thành phố này."},{"type":"compound","zh":"虽然屠杀已经过去了几十年，但是幸存者仍无法忘记。","pinyin":"Suīrán túshā yǐjīng guòqùle jǐ shí nián, dànshì xìngcúnzhě réng wúfǎ wàngjì.","vi":"Tuy cuộc thảm sát đã qua mấy chục năm nhưng người sống sót vẫn không thể quên."}],"related":[{"hanzi":"杀害","pinyin":"shāhài","vi":"sát hại"},{"hanzi":"残杀","pinyin":"cánshā","vi":"tàn sát"},{"hanzi":"屠夫","pinyin":"túfū","vi":"đồ tể"},{"hanzi":"暴行","pinyin":"bàoxíng","vi":"hành vi tàn bạo"}],"traditional":"屠殺"},{"id":"土匪","hanzi":"土匪","pinyin":"tǔfěi","meaning_vi":"thổ phỉ, kẻ cướp","explanation":"土 (thổ – đất, địa phương) + 匪 (phỉ – giặc cướp) → bọn cướp có vũ trang chiếm cứ một vùng.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏴‍☠️","examples":[{"type":"basic","zh":"山里曾经有土匪。","pinyin":"Shān li céngjīng yǒu tǔfěi.","vi":"Trong núi từng có thổ phỉ."},{"type":"simple","zh":"那时候土匪经常下山抢老百姓的粮食。","pinyin":"Nàshíhou tǔfěi jīngcháng xiàshān qiǎng lǎobǎixìng de liángshi.","vi":"Thời đó thổ phỉ thường xuống núi cướp lương thực của dân."},{"type":"compound","zh":"因为土匪横行，所以商人们都不敢走这条路。","pinyin":"Yīnwèi tǔfěi héngxíng, suǒyǐ shāng rénmen dōu bù gǎn zǒu zhè tiáo lù.","vi":"Vì thổ phỉ hoành hành nên thương nhân đều không dám đi con đường này."}],"related":[{"hanzi":"强盗","pinyin":"qiángdào","vi":"kẻ cướp"},{"hanzi":"盗贼","pinyin":"dàozéi","vi":"trộm cướp"},{"hanzi":"匪徒","pinyin":"fěitú","vi":"kẻ phỉ"},{"hanzi":"山贼","pinyin":"shānzéi","vi":"giặc núi"}]},{"id":"涂","hanzi":"涂","pinyin":"tú","meaning_vi":"bôi, quét, thoa; gạch xóa","explanation":"涂 (đồ): bộ 氵 (nước) → bôi chất lỏng hay sơn lên bề mặt; cũng là gạch xóa chữ (涂掉).","hsk_level":"7-9","tags":["dong-tu"],"image":"🖌️","examples":[{"type":"basic","zh":"墙上涂了白漆。","pinyin":"Qiáng shang túle bái qī.","vi":"Tường đã quét sơn trắng."},{"type":"simple","zh":"出门前她在脸上涂了一层防晒霜。","pinyin":"Chū ménqián tā zài liǎn shang túle yīcéng fángshàishuāng.","vi":"Trước khi ra ngoài cô ấy thoa một lớp kem chống nắng lên mặt."},{"type":"compound","zh":"如果写错了字，就用笔涂掉再重新写。","pinyin":"Rúguǒ xiě cuòle zì, jiù yòng bǐ tú diào zài chóngxīn xiě.","vi":"Nếu viết sai chữ thì dùng bút gạch đi rồi viết lại."}],"related":[{"hanzi":"涂抹","pinyin":"túmǒ","vi":"bôi trát"},{"hanzi":"涂鸦","pinyin":"túyā","vi":"vẽ bậy"},{"hanzi":"刷","pinyin":"shuā","vi":"quét"},{"hanzi":"擦","pinyin":"cā","vi":"lau, thoa"}],"traditional":"塗"},{"id":"团伙","hanzi":"团伙","pinyin":"tuánhuǒ","meaning_vi":"băng nhóm (tội phạm), băng đảng","explanation":"团 (đoàn – nhóm) + 伙 (hỏa – bọn) → nhóm người tụ tập, thường chỉ băng nhóm tội phạm.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"👥","examples":[{"type":"basic","zh":"这是一个诈骗团伙。","pinyin":"Zhè shì yí ge zhàpiàn tuánhuǒ.","vi":"Đây là một băng nhóm lừa đảo."},{"type":"simple","zh":"警方一举打掉了一个盗窃团伙。","pinyin":"Jǐngfāng yìjǔ dǎdiàole yí ge dàoqiè tuánhuǒ.","vi":"Cảnh sát đã triệt phá một băng nhóm trộm cắp."},{"type":"compound","zh":"虽然团伙成员分散在各地，但是警察还是把他们一一抓获了。","pinyin":"Suīrán tuánhuǒ chéngyuán fēnsàn zài gèdì, dànshì jǐngchá háishi bǎ tāmen yīyī zhuāhuò le.","vi":"Tuy các thành viên băng nhóm phân tán khắp nơi nhưng cảnh sát vẫn bắt được từng người."}],"related":[{"hanzi":"同伙","pinyin":"tónghuǒ","vi":"đồng bọn"},{"hanzi":"帮派","pinyin":"bāngpài","vi":"bang phái"},{"hanzi":"犯罪","pinyin":"fànzuì","vi":"phạm tội"},{"hanzi":"黑社会","pinyin":"hēishèhuì","vi":"xã hội đen"}],"traditional":"團伙"},{"id":"团员","hanzi":"团员","pinyin":"tuányuán","meaning_vi":"đoàn viên, thành viên đoàn","explanation":"团 (đoàn – đoàn thể) + 员 (viên – thành viên) → thành viên của một đoàn; ở Trung Quốc thường chỉ đoàn viên Đoàn Thanh niên Cộng sản.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🙋","examples":[{"type":"basic","zh":"他是共青团员。","pinyin":"Tā shì Gòngqīngtuán yuán.","vi":"Cậu ấy là đoàn viên Đoàn Thanh niên."},{"type":"simple","zh":"旅行团的团员们在机场集合。","pinyin":"Lǚxíngtuán de tuányuánmen zài jīchǎng jíhé.","vi":"Các thành viên đoàn du lịch tập trung ở sân bay."},{"type":"compound","zh":"因为有一位团员迟到了，所以大巴晚了半小时才出发。","pinyin":"Yīnwèi yǒu yí wèi tuányuán chídào le, suǒyǐ dàbā wǎnle bànxiǎoshí cái chūfā.","vi":"Vì có một thành viên đến muộn nên xe buýt trễ nửa tiếng mới xuất phát."}],"related":[{"hanzi":"成员","pinyin":"chéngyuán","vi":"thành viên"},{"hanzi":"团长","pinyin":"tuánzhǎng","vi":"trưởng đoàn"},{"hanzi":"党员","pinyin":"dǎngyuán","vi":"đảng viên"},{"hanzi":"会员","pinyin":"huìyuán","vi":"hội viên"}],"traditional":"團員"},{"id":"推敲","hanzi":"推敲","pinyin":"tuīqiāo","meaning_vi":"cân nhắc, trau chuốt (câu chữ), suy xét kỹ","explanation":"推 (thôi – đẩy) + 敲 (xao – gõ) → điển tích Giả Đảo phân vân giữa \"đẩy cửa\" hay \"gõ cửa\" trong câu thơ → cân nhắc kỹ từng chữ, suy xét kỹ lưỡng.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"这句话值得推敲。","pinyin":"Zhè jù huà zhíde tuīqiāo.","vi":"Câu này đáng để cân nhắc kỹ."},{"type":"simple","zh":"这篇稿子他推敲了整整一个星期。","pinyin":"Zhè piān gǎozi tā tuīqiāole zhěngzhěng yī ge xīngqī.","vi":"Bài viết này anh ấy đã trau chuốt suốt một tuần."},{"type":"compound","zh":"虽然他的说法听起来有道理，但是经不起推敲。","pinyin":"Suīrán tā de shuōfǎ tīngqǐlái yǒudàolǐ, dànshì jīngbùqǐ tuīqiāo.","vi":"Tuy cách nói của anh ta nghe có lý nhưng không chịu nổi sự xem xét kỹ."}],"related":[{"hanzi":"琢磨","pinyin":"zuómo","vi":"suy ngẫm"},{"hanzi":"斟酌","pinyin":"zhēnzhuó","vi":"cân nhắc"},{"hanzi":"思考","pinyin":"sīkǎo","vi":"suy nghĩ"},{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"xem xét"}]},{"id":"推选","hanzi":"推选","pinyin":"tuīxuǎn","meaning_vi":"bầu chọn, đề cử","explanation":"推 (thôi – đề cử) + 选 (tuyển – chọn) → đề cử và bầu chọn người đảm nhận chức vụ.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🗳️","examples":[{"type":"basic","zh":"大家推选他当班长。","pinyin":"Dàjiā tuīxuǎn tā dāng bānzhǎng.","vi":"Mọi người bầu cậu ấy làm lớp trưởng."},{"type":"simple","zh":"全体员工推选出了三名代表参加会议。","pinyin":"Quántǐ yuángōng tuīxuǎn chūle sān míng dàibiǎo cānjiā huìyì.","vi":"Toàn thể nhân viên đã bầu ra ba đại diện dự họp."},{"type":"compound","zh":"因为她做事公正，所以被推选为委员会主席。","pinyin":"Yīnwèi tā zuòshì gōngzhèng, suǒyǐ bèi tuīxuǎn wéi wěiyuánhuì zhǔxí.","vi":"Vì làm việc công tâm nên bà ấy được bầu làm chủ tịch ủy ban."}],"related":[{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"},{"hanzi":"推举","pinyin":"tuījǔ","vi":"đề cử"},{"hanzi":"选拔","pinyin":"xuǎnbá","vi":"tuyển chọn"},{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"}],"traditional":"推選"},{"id":"退回","hanzi":"退回","pinyin":"tuìhuí","meaning_vi":"trả lại, gửi trả, lùi về","explanation":"退 (thoái – lui) + 回 (hồi – về) → trả lại cho người gửi; hoặc lùi trở về chỗ cũ.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"↩️","examples":[{"type":"basic","zh":"稿件被退回了。","pinyin":"Gǎojiàn bèi tuìhuí le.","vi":"Bản thảo đã bị trả lại."},{"type":"simple","zh":"地址写错的包裹被退回给了寄件人。","pinyin":"Dìzhǐ xiě cuò de bāoguǒ bèi tuìhuí gěile jìjiànrén.","vi":"Bưu kiện ghi sai địa chỉ đã bị trả lại cho người gửi."},{"type":"compound","zh":"如果对商品不满意，七天内就可以无理由退回。","pinyin":"Rúguǒ duì shāngpǐn bù mǎnyì, qī tiān nèi jiù kěyǐ wú lǐyóu tuìhuí.","vi":"Nếu không hài lòng với sản phẩm thì trong bảy ngày có thể trả lại mà không cần lý do."}],"related":[{"hanzi":"退还","pinyin":"tuìhuán","vi":"hoàn trả"},{"hanzi":"退货","pinyin":"tuìhuò","vi":"trả hàng"},{"hanzi":"返回","pinyin":"fǎnhuí","vi":"quay về"},{"hanzi":"寄回","pinyin":"jìhuí","vi":"gửi trả"}]},{"id":"退休金","hanzi":"退休金","pinyin":"tuìxiūjīn","meaning_vi":"lương hưu","explanation":"退休 (thoái hưu – nghỉ hưu) + 金 (kim – tiền) → khoản tiền nhận hằng tháng sau khi nghỉ hưu.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"爷爷每月领退休金。","pinyin":"Yéye měiyuè lǐng tuìxiūjīn.","vi":"Ông nội hằng tháng lĩnh lương hưu."},{"type":"simple","zh":"她用退休金报了一个老年大学的绘画班。","pinyin":"Tā yòng tuìxiūjīn bàole yí ge lǎonián dàxué de huìhuà bān.","vi":"Bà ấy dùng lương hưu đăng ký lớp vẽ ở đại học người cao tuổi."},{"type":"compound","zh":"虽然退休金不算多，但是老两口过得很知足。","pinyin":"Suīrán tuìxiūjīn búsuàn duō, dànshì lǎoliǎngkǒu guòde hěn zhīzú.","vi":"Tuy lương hưu không nhiều nhưng hai ông bà sống rất mãn nguyện."}],"related":[{"hanzi":"退休","pinyin":"tuìxiū","vi":"nghỉ hưu"},{"hanzi":"养老金","pinyin":"yǎnglǎojīn","vi":"tiền dưỡng lão"},{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"社保","pinyin":"shèbǎo","vi":"bảo hiểm xã hội"}]},{"id":"退学","hanzi":"退学","pinyin":"tuìxué","meaning_vi":"bỏ học, thôi học","explanation":"退 (thoái – rút lui) + 学 (học – trường học) → rời khỏi trường, thôi không học nữa (tự nguyện hoặc bị buộc).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎒","examples":[{"type":"basic","zh":"他因病退学了。","pinyin":"Tā yīn bìng tuìxué le.","vi":"Cậu ấy thôi học vì bệnh."},{"type":"simple","zh":"那个学生因为多次作弊被学校勒令退学。","pinyin":"Nà ge xuésheng yīnwèi duōcì zuòbì bèi xuéxiào lèlìng tuìxué.","vi":"Học sinh đó bị nhà trường buộc thôi học vì nhiều lần gian lận."},{"type":"compound","zh":"虽然他大学中途退学了，但是后来创办了一家大公司。","pinyin":"Suīrán tā dàxué zhōngtú tuìxué le, dànshì hòulái chuàngbànle yìjiā dàgōngsī.","vi":"Tuy bỏ ngang đại học nhưng sau này anh ấy đã sáng lập một công ty lớn."}],"related":[{"hanzi":"辍学","pinyin":"chuòxué","vi":"bỏ học"},{"hanzi":"休学","pinyin":"xiūxué","vi":"tạm nghỉ học"},{"hanzi":"入学","pinyin":"rùxué","vi":"nhập học"},{"hanzi":"毕业","pinyin":"bìyè","vi":"tốt nghiệp"}],"traditional":"退學"},{"id":"退役","hanzi":"退役","pinyin":"tuìyì","meaning_vi":"giải ngũ, giải nghệ; (thiết bị) ngừng sử dụng","explanation":"退 (thoái – rút lui) + 役 (dịch – binh dịch, phục vụ) → rời quân ngũ hoặc vận động viên giải nghệ; cũng nói về máy móc cũ ngừng hoạt động.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏅","examples":[{"type":"basic","zh":"她去年退役了。","pinyin":"Tā qùnián tuìyì le.","vi":"Cô ấy đã giải nghệ năm ngoái."},{"type":"simple","zh":"这架老式战斗机已经正式退役了。","pinyin":"Zhè jià lǎoshì zhàndòujī yǐjīng zhèngshì tuìyì le.","vi":"Chiếc máy bay chiến đấu đời cũ này đã chính thức ngừng hoạt động."},{"type":"compound","zh":"虽然他已经退役多年，但是每天还坚持训练。","pinyin":"Suīrán tā yǐjīng tuìyì duōnián, dànshì měitiān hái jiānchí xùnliàn.","vi":"Tuy đã giải nghệ nhiều năm nhưng ngày nào anh ấy vẫn kiên trì tập luyện."}],"related":[{"hanzi":"退伍","pinyin":"tuìwǔ","vi":"xuất ngũ"},{"hanzi":"服役","pinyin":"fúyì","vi":"phục vụ quân dịch"},{"hanzi":"退休","pinyin":"tuìxiū","vi":"nghỉ hưu"},{"hanzi":"现役","pinyin":"xiànyì","vi":"tại ngũ"}]},{"id":"屯","hanzi":"屯","pinyin":"tún","meaning_vi":"đóng quân; tích trữ; làng, thôn","explanation":"屯 (đồn) → nơi quân đóng giữ (đồn điền); nghĩa mở rộng là tích trữ (屯粮) và làng xóm ở vùng Đông Bắc Trung Quốc.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏘️","examples":[{"type":"basic","zh":"他在家里屯了很多米。","pinyin":"Tā zài jiāli túnle hěn duō mǐ.","vi":"Anh ấy tích trữ rất nhiều gạo ở nhà."},{"type":"simple","zh":"古代朝廷派大军屯在边境开荒种地。","pinyin":"Gǔdài cháotíng pài dàjūn tún zài biānjìng kāihuāng zhòngdì.","vi":"Triều đình xưa phái đại quân đóng ở biên giới khai hoang trồng trọt."},{"type":"compound","zh":"因为听说要涨价，所以很多人都去超市屯货。","pinyin":"Yīnwèi tīngshuō yào zhǎngjià, suǒyǐ hěn duō rén dōu qù chāoshì tún huò.","vi":"Vì nghe nói sắp tăng giá nên nhiều người đi siêu thị tích trữ hàng."}],"related":[{"hanzi":"囤积","pinyin":"túnjī","vi":"tích trữ"},{"hanzi":"驻扎","pinyin":"zhùzhā","vi":"đóng quân"},{"hanzi":"屯田","pinyin":"túntián","vi":"đồn điền"},{"hanzi":"村庄","pinyin":"cūnzhuāng","vi":"làng mạc"}]},{"id":"拖累","hanzi":"拖累","pinyin":"tuōlěi","meaning_vi":"làm liên lụy, làm gánh nặng","explanation":"拖 (tha – kéo, lôi) + 累 (lụy – liên lụy) → kéo người khác vào gánh nặng, làm liên lụy.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪨","examples":[{"type":"basic","zh":"我不想拖累大家。","pinyin":"Wǒ bù xiǎng tuōlěi dàjiā.","vi":"Tôi không muốn làm liên lụy mọi người."},{"type":"simple","zh":"他觉得自己的病拖累了整个家庭。","pinyin":"Tā juéde zìjǐ de bìng tuōlěile zhěngge jiātíng.","vi":"Ông ấy cảm thấy bệnh của mình làm khổ cả gia đình."},{"type":"compound","zh":"如果一个人总是拖延，就会拖累整个团队的进度。","pinyin":"Rúguǒ yígerén zǒngshì tuōyán, jiù huì tuōlěi zhěngge tuánduì de jìndù.","vi":"Nếu một người cứ trì hoãn thì sẽ kéo lùi tiến độ của cả nhóm."}],"related":[{"hanzi":"连累","pinyin":"liánlěi","vi":"liên lụy"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"},{"hanzi":"牵连","pinyin":"qiānlián","vi":"dính líu"},{"hanzi":"拖后腿","pinyin":"tuōhòutuǐ","vi":"níu chân"}]},{"id":"拖欠","hanzi":"拖欠","pinyin":"tuōqiàn","meaning_vi":"nợ dây dưa, chây ì, khất nợ","explanation":"拖 (tha – kéo dài) + 欠 (khiếm – thiếu, nợ) → kéo dài không trả khoản nợ hoặc tiền lương.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"公司拖欠工资了。","pinyin":"Gōngsī tuōqiàn gōngzī le.","vi":"Công ty nợ lương rồi."},{"type":"simple","zh":"他已经拖欠了三个月的房租。","pinyin":"Tā yǐjīng tuōqiànle sān geyuè de fángzū.","vi":"Anh ấy đã nợ ba tháng tiền nhà."},{"type":"compound","zh":"如果你继续拖欠贷款，银行就会起诉你。","pinyin":"Rúguǒ nǐ jìxù tuōqiàn dàikuǎn, yínháng jiù huì qǐsù nǐ.","vi":"Nếu anh tiếp tục chây ì khoản vay thì ngân hàng sẽ kiện anh."}],"related":[{"hanzi":"欠款","pinyin":"qiànkuǎn","vi":"khoản nợ"},{"hanzi":"赖账","pinyin":"làizhàng","vi":"quỵt nợ"},{"hanzi":"偿还","pinyin":"chánghuán","vi":"hoàn trả"},{"hanzi":"债务","pinyin":"zhàiwù","vi":"nợ nần"}]},{"id":"脱落","hanzi":"脱落","pinyin":"tuōluò","meaning_vi":"rơi ra, bong ra, rụng","explanation":"脱 (thoát – tách ra) + 落 (lạc – rơi) → tách khỏi chỗ bám và rơi xuống, như tóc rụng, sơn bong.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"墙皮脱落了。","pinyin":"Qiáng pí tuōluò le.","vi":"Lớp vữa tường bong ra rồi."},{"type":"simple","zh":"压力太大会导致头发大量脱落。","pinyin":"Yālì tài dàhuì dǎozhì tóufa dàliàng tuōluò.","vi":"Áp lực quá lớn có thể khiến tóc rụng nhiều."},{"type":"compound","zh":"因为胶水不够牢，所以墙上的瓷砖开始脱落了。","pinyin":"Yīnwèi jiāoshuǐ búgòu láo, suǒyǐ qiáng shang de cízhuān kāishǐ tuōluò le.","vi":"Vì keo không đủ chắc nên gạch men trên tường bắt đầu bong ra."}],"related":[{"hanzi":"掉落","pinyin":"diàoluò","vi":"rơi rụng"},{"hanzi":"脱发","pinyin":"tuōfà","vi":"rụng tóc"},{"hanzi":"剥落","pinyin":"bōluò","vi":"bong tróc"},{"hanzi":"掉","pinyin":"diào","vi":"rơi"}],"traditional":"脫落"},{"id":"驮","hanzi":"驮","pinyin":"tuó","meaning_vi":"thồ, chở trên lưng, cõng","explanation":"驮 (đà): bộ 马 (ngựa) → con vật mang đồ trên lưng; đọc duò thì nghĩa là hàng thồ.","hsk_level":"7-9","tags":["dong-tu","dong-vat"],"image":"🐫","examples":[{"type":"basic","zh":"骆驼驮着货物。","pinyin":"Luòtuo tuózhe huòwù.","vi":"Lạc đà thồ hàng hóa."},{"type":"simple","zh":"小毛驴驮着两袋粮食慢慢地走上山。","pinyin":"Xiǎo máolǘ tuózhe liǎng dài liángshi mànmàn de zǒu shàngshān.","vi":"Chú lừa nhỏ thồ hai bao lương thực chậm rãi đi lên núi."},{"type":"compound","zh":"虽然爸爸已经很累了，但是还是把儿子驮在背上。","pinyin":"Suīrán bàba yǐjīng hěn lèi le, dànshì háishi bǎ érzi tuó zài bèi shang.","vi":"Tuy bố đã rất mệt nhưng vẫn cõng con trai trên lưng."}],"related":[{"hanzi":"背","pinyin":"bēi","vi":"cõng"},{"hanzi":"骆驼","pinyin":"luòtuo","vi":"lạc đà"},{"hanzi":"运","pinyin":"yùn","vi":"chở"},{"hanzi":"扛","pinyin":"káng","vi":"vác"}],"traditional":"馱"},{"id":"妥","hanzi":"妥","pinyin":"tuǒ","meaning_vi":"thỏa đáng, ổn thỏa; xong xuôi","explanation":"妥 (thỏa) → yên ổn, thích đáng; hay dùng trong 妥当, 不妥, hoặc sau động từ chỉ việc đã xong (办妥).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"这样做恐怕不妥。","pinyin":"Zhèyàng zuò kǒngpà bùtuǒ.","vi":"Làm như vậy e là không ổn."},{"type":"simple","zh":"签证手续已经全部办妥了。","pinyin":"Qiānzhèng shǒuxù yǐjīng quánbù bàntuǒ le.","vi":"Thủ tục visa đã làm xong xuôi cả rồi."},{"type":"compound","zh":"一旦事情谈妥，我们就马上签合同。","pinyin":"Yídàn shìqing tántuǒ, wǒmen jiù mǎshàng qiānhétong.","vi":"Một khi bàn xong việc thì chúng ta ký hợp đồng ngay."}],"related":[{"hanzi":"妥当","pinyin":"tuǒdang","vi":"thỏa đáng"},{"hanzi":"妥善","pinyin":"tuǒshàn","vi":"chu đáo"},{"hanzi":"妥协","pinyin":"tuǒxié","vi":"thỏa hiệp"},{"hanzi":"不妥","pinyin":"bùtuǒ","vi":"không ổn"}]},{"id":"唾液","hanzi":"唾液","pinyin":"tuòyè","meaning_vi":"nước bọt","explanation":"唾 (thóa – nước bọt, nhổ) + 液 (dịch – chất lỏng) → chất lỏng tiết ra trong miệng (từ dùng trang trọng, y học).","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"💧","examples":[{"type":"basic","zh":"唾液能帮助消化。","pinyin":"Tuòyè néng bāngzhù xiāohuà.","vi":"Nước bọt có thể giúp tiêu hóa."},{"type":"simple","zh":"医生采集了病人的唾液进行检测。","pinyin":"Yīshēng cǎijíle bìngrén de tuòyè jìnxíng jiǎncè.","vi":"Bác sĩ lấy mẫu nước bọt của bệnh nhân để xét nghiệm."},{"type":"compound","zh":"因为看到了美食，所以他嘴里不停地分泌唾液。","pinyin":"Yīnwèi kàndàole měishí, suǒyǐ tā zuǐli bùtíng de fēnmì tuòyè.","vi":"Vì nhìn thấy món ngon nên miệng anh ấy tiết nước bọt liên tục."}],"related":[{"hanzi":"口水","pinyin":"kǒushuǐ","vi":"nước miếng"},{"hanzi":"吐","pinyin":"tǔ","vi":"nhổ"},{"hanzi":"消化","pinyin":"xiāohuà","vi":"tiêu hóa"},{"hanzi":"体液","pinyin":"tǐyè","vi":"dịch cơ thể"}]},{"id":"瓦","hanzi":"瓦","pinyin":"wǎ","meaning_vi":"ngói; oát (W)","explanation":"瓦 (ngõa – ngói đất nung) → miếng ngói lợp nhà; còn là viết tắt của 瓦特 (oát, đơn vị công suất).","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"屋顶的瓦碎了。","pinyin":"Wūdǐng de wǎ suì le.","vi":"Ngói trên mái vỡ rồi."},{"type":"simple","zh":"这个灯泡的功率是六十瓦。","pinyin":"Zhè ge dēngpào de gōnglǜ shì liù shíwǎ.","vi":"Công suất của bóng đèn này là 60 oát."},{"type":"compound","zh":"因为台风吹掉了好几片瓦，所以屋里开始漏雨。","pinyin":"Yīnwèi táifēng chuī diàole hǎojǐ piàn wǎ, suǒyǐ wū li kāishǐ lòu yǔ.","vi":"Vì bão thổi bay mấy viên ngói nên trong nhà bắt đầu dột."}],"related":[{"hanzi":"瓦片","pinyin":"wǎpiàn","vi":"viên ngói"},{"hanzi":"砖","pinyin":"zhuān","vi":"gạch"},{"hanzi":"屋顶","pinyin":"wūdǐng","vi":"mái nhà"},{"hanzi":"瓦特","pinyin":"wǎtè","vi":"oát"}]},{"id":"外号","hanzi":"外号","pinyin":"wàihào","meaning_vi":"biệt danh, tên lóng","explanation":"外 (ngoại – bên ngoài) + 号 (hiệu – tên gọi) → tên gọi ngoài tên thật, do người khác đặt.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🏷️","examples":[{"type":"basic","zh":"他的外号叫“大头”。","pinyin":"Tā de wàihào jiào \"dàtóu\".","vi":"Biệt danh của cậu ấy là \"Đầu To\"."},{"type":"simple","zh":"同学们给这个跑得快的男孩起了个外号。","pinyin":"Tóngxuémen gěi zhè ge pǎo de kuài de nánhái qǐle ge wàihào.","vi":"Bạn học đặt cho cậu bé chạy nhanh này một biệt danh."},{"type":"compound","zh":"虽然这个外号有点难听，但是他自己并不在意。","pinyin":"Suīrán zhè ge wàihào yǒudiǎn nántīng, dànshì tā zìjǐ bìngbú zàiyì.","vi":"Tuy biệt danh này hơi khó nghe nhưng bản thân cậu ấy không để ý."}],"related":[{"hanzi":"绰号","pinyin":"chuòhào","vi":"biệt hiệu"},{"hanzi":"昵称","pinyin":"nìchēng","vi":"tên thân mật"},{"hanzi":"名字","pinyin":"míngzi","vi":"tên"},{"hanzi":"小名","pinyin":"xiǎomíng","vi":"tên ở nhà"}],"traditional":"外號"},{"id":"外籍","hanzi":"外籍","pinyin":"wàijí","meaning_vi":"quốc tịch nước ngoài, (người) nước ngoài","explanation":"外 (ngoại – nước ngoài) + 籍 (tịch – hộ tịch, quốc tịch) → mang quốc tịch nước ngoài; thường làm định ngữ như 外籍教师.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌐","examples":[{"type":"basic","zh":"她是外籍教师。","pinyin":"Tā shì wàijí jiàoshī.","vi":"Cô ấy là giáo viên nước ngoài."},{"type":"simple","zh":"这家公司雇用了二十多名外籍员工。","pinyin":"Zhè jiā gōngsī gùyòngle èrshíduō míng wàijí yuángōng.","vi":"Công ty này thuê hơn hai mươi nhân viên nước ngoài."},{"type":"compound","zh":"如果外籍人士想在这里工作，就必须先申请工作签证。","pinyin":"Rúguǒ wàijí rénshì xiǎng zài zhèlǐ gōngzuò, jiù bìxū xiān shēnqǐng gōngzuò qiānzhèng.","vi":"Nếu người nước ngoài muốn làm việc ở đây thì phải xin thị thực lao động trước."}],"related":[{"hanzi":"国籍","pinyin":"guójí","vi":"quốc tịch"},{"hanzi":"外国人","pinyin":"wàiguórén","vi":"người nước ngoài"},{"hanzi":"华裔","pinyin":"Huáyì","vi":"người gốc Hoa"},{"hanzi":"本地","pinyin":"běndì","vi":"bản địa"}]},{"id":"外婆","hanzi":"外婆","pinyin":"wàipó","meaning_vi":"bà ngoại","explanation":"外 (ngoại – bên ngoại) + 婆 (bà – bà lão) → bà bên ngoại, mẹ của mẹ.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👵","examples":[{"type":"basic","zh":"我很想念外婆。","pinyin":"Wǒ hěn xiǎngniàn wàipó.","vi":"Tôi rất nhớ bà ngoại."},{"type":"simple","zh":"外婆每年春天都会腌一大坛咸菜。","pinyin":"Wàipó měinián chūntiān dōuhuì yān yí dà tán xiáncài.","vi":"Mùa xuân năm nào bà ngoại cũng muối một vại dưa lớn."},{"type":"compound","zh":"虽然外婆已经八十岁了，但是她的记性还特别好。","pinyin":"Suīrán wàipó yǐjīng bāshí suì le, dànshì tā de jìxing hái tèbié hǎo.","vi":"Tuy bà ngoại đã tám mươi tuổi nhưng trí nhớ vẫn rất tốt."}],"related":[{"hanzi":"外公","pinyin":"wàigōng","vi":"ông ngoại"},{"hanzi":"姥姥","pinyin":"lǎolao","vi":"bà ngoại (phương Bắc)"},{"hanzi":"奶奶","pinyin":"nǎinai","vi":"bà nội"},{"hanzi":"外孙","pinyin":"wàisūn","vi":"cháu ngoại"}]},{"id":"外星人","hanzi":"外星人","pinyin":"wàixīngrén","meaning_vi":"người ngoài hành tinh","explanation":"外 (ngoại – bên ngoài) + 星 (tinh – hành tinh) + 人 (nhân – người) → sinh vật đến từ hành tinh khác.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"👽","examples":[{"type":"basic","zh":"你相信有外星人吗？","pinyin":"Nǐ xiāngxìn yǒu wàixīngrén ma?","vi":"Bạn có tin có người ngoài hành tinh không?"},{"type":"simple","zh":"这部科幻片讲的是外星人入侵地球的故事。","pinyin":"Zhè bù kēhuànpiàn jiǎng de shì wàixīngrén rùqīn dìqiú de gùshi.","vi":"Bộ phim khoa học viễn tưởng này kể chuyện người ngoài hành tinh xâm lược Trái Đất."},{"type":"compound","zh":"即使宇宙中真有外星人，他们也未必会来地球。","pinyin":"Jíshǐ yǔzhòu zhōng zhēn yǒu wàixīngrén, tāmen yě wèibì huì lái dìqiú.","vi":"Dù vũ trụ thật sự có người ngoài hành tinh thì họ cũng chưa chắc đến Trái Đất."}],"related":[{"hanzi":"宇宙","pinyin":"yǔzhòu","vi":"vũ trụ"},{"hanzi":"飞碟","pinyin":"fēidié","vi":"đĩa bay"},{"hanzi":"星球","pinyin":"xīngqiú","vi":"hành tinh"},{"hanzi":"外太空","pinyin":"wàitàikōng","vi":"ngoài vũ trụ"}]},{"id":"外形","hanzi":"外形","pinyin":"wàixíng","meaning_vi":"hình dáng bên ngoài, kiểu dáng","explanation":"外 (ngoại – bên ngoài) + 形 (hình – hình dạng) → hình dáng nhìn thấy từ bên ngoài của vật.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔷","examples":[{"type":"basic","zh":"这辆车外形很酷。","pinyin":"Zhè liàng chē wàixíng hěn kù.","vi":"Chiếc xe này có kiểu dáng rất ngầu."},{"type":"simple","zh":"这座建筑的外形像一朵盛开的莲花。","pinyin":"Zhè zuò jiànzhù de wàixíng xiàng yì duǒ shèngkāi de liánhuā.","vi":"Hình dáng tòa nhà này giống một đóa sen đang nở."},{"type":"compound","zh":"虽然这两款手机外形差不多，但是性能差别很大。","pinyin":"Suīrán zhè liǎng kuǎn shǒujī wàixíng chàbuduō, dànshì xìngnéng chābié hěn dà.","vi":"Tuy hai mẫu điện thoại này kiểu dáng gần giống nhau nhưng hiệu năng khác biệt rất lớn."}],"related":[{"hanzi":"外观","pinyin":"wàiguān","vi":"bề ngoài"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"vẻ ngoài"},{"hanzi":"形状","pinyin":"xíngzhuàng","vi":"hình dạng"},{"hanzi":"造型","pinyin":"zàoxíng","vi":"tạo hình"}]},{"id":"完蛋","hanzi":"完蛋","pinyin":"wándàn","meaning_vi":"tiêu đời, toi, hỏng bét","explanation":"完 (hoàn – hết) + 蛋 (đản – quả trứng) → khẩu ngữ, nghĩa là tiêu rồi, xong đời, thất bại hoàn toàn.","hsk_level":"7-9","tags":["dong-tu"],"image":"😱","examples":[{"type":"basic","zh":"完蛋了，我忘带钥匙了！","pinyin":"Wándàn le, wǒ wàng dài yàoshi le!","vi":"Toi rồi, tôi quên mang chìa khóa!"},{"type":"simple","zh":"那家小店开了不到半年就完蛋了。","pinyin":"Nà jiā xiǎodiàn kāile búdào bàn nián jiù wándàn le.","vi":"Cửa hàng nhỏ đó mở chưa đầy nửa năm đã sập tiệm."},{"type":"compound","zh":"如果明天交不了报告，我这个月的奖金就完蛋了。","pinyin":"Rúguǒ míngtiān jiāo bùliǎo bàogào, wǒ zhè geyuè de jiǎngjīn jiù wándàn le.","vi":"Nếu mai không nộp được báo cáo thì tiền thưởng tháng này của tôi coi như toi."}],"related":[{"hanzi":"完了","pinyin":"wánle","vi":"xong đời"},{"hanzi":"糟糕","pinyin":"zāogāo","vi":"hỏng bét"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"},{"hanzi":"垮台","pinyin":"kuǎtái","vi":"sụp đổ"}]},{"id":"完好","hanzi":"完好","pinyin":"wánhǎo","meaning_vi":"nguyên vẹn, còn tốt","explanation":"完 (hoàn – trọn vẹn) + 好 (hảo – tốt) → còn nguyên, không hư hỏng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"包裹完好无损。","pinyin":"Bāoguǒ wánhǎowúsǔn.","vi":"Bưu kiện còn nguyên vẹn không hư hại."},{"type":"simple","zh":"这座古桥至今仍保存得十分完好。","pinyin":"Zhè zuò gǔ qiáo zhìjīn réng bǎocún de shífēn wánhǎo.","vi":"Cây cầu cổ này đến nay vẫn được bảo tồn rất nguyên vẹn."},{"type":"compound","zh":"虽然地震很强烈，但是这栋楼仍然完好地立在那里。","pinyin":"Suīrán dìzhèn hěn qiángliè, dànshì zhè dòng lóu réngrán wánhǎo de lì zài nàlǐ.","vi":"Tuy động đất rất mạnh nhưng tòa nhà này vẫn đứng nguyên vẹn ở đó."}],"related":[{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"},{"hanzi":"无损","pinyin":"wúsǔn","vi":"không tổn hại"},{"hanzi":"破损","pinyin":"pòsǔn","vi":"hư hỏng"},{"hanzi":"良好","pinyin":"liánghǎo","vi":"tốt đẹp"}]},{"id":"玩耍","hanzi":"玩耍","pinyin":"wánshuǎ","meaning_vi":"vui chơi, nô đùa","explanation":"玩 (ngoạn – chơi) + 耍 (sái – đùa nghịch) → chơi đùa, thường nói về trẻ em.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🤸","examples":[{"type":"basic","zh":"孩子们在院子里玩耍。","pinyin":"Háizimen zài yuànzi li wánshuǎ.","vi":"Bọn trẻ nô đùa trong sân."},{"type":"simple","zh":"几只小猫在草地上快乐地玩耍。","pinyin":"Jǐ zhī xiǎomāo zài cǎo dìshang kuàilè de wánshuǎ.","vi":"Mấy chú mèo con vui vẻ nô đùa trên bãi cỏ."},{"type":"compound","zh":"因为河边很危险，所以妈妈不让孩子去那里玩耍。","pinyin":"Yīnwèi hébiān hěn wēixiǎn, suǒyǐ māma bú ràng háizi qù nàlǐ wánshuǎ.","vi":"Vì bờ sông nguy hiểm nên mẹ không cho con ra đó chơi."}],"related":[{"hanzi":"玩","pinyin":"wán","vi":"chơi"},{"hanzi":"游戏","pinyin":"yóuxì","vi":"trò chơi"},{"hanzi":"嬉戏","pinyin":"xīxì","vi":"nô đùa"},{"hanzi":"打闹","pinyin":"dǎnào","vi":"đùa nghịch"}]},{"id":"挽","hanzi":"挽","pinyin":"wǎn","meaning_vi":"kéo, vãn hồi, cứu vãn; khoác (tay), xắn (tay áo)","explanation":"挽 (vãn – kéo lại): bộ 扌 (tay) → kéo, níu lại; mở rộng thành cứu vãn, khoác tay, xắn tay áo.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"她挽着妈妈的手。","pinyin":"Tā wǎnzhe māma de shǒu.","vi":"Cô ấy khoác tay mẹ."},{"type":"simple","zh":"他挽起袖子开始收拾厨房。","pinyin":"Tā wǎn qǐ xiùzi kāishǐ shōushi chúfáng.","vi":"Anh ấy xắn tay áo lên bắt đầu dọn bếp."},{"type":"compound","zh":"虽然他一再道歉，但是也挽不回她的心了。","pinyin":"Suīrán tā yízài dàoqiàn, dànshì yě wǎn bu huí tā de xīn le.","vi":"Tuy anh ấy xin lỗi mãi nhưng cũng không níu kéo được trái tim cô ấy nữa."}],"related":[{"hanzi":"挽回","pinyin":"wǎnhuí","vi":"cứu vãn"},{"hanzi":"挽救","pinyin":"wǎnjiù","vi":"cứu vãn, cứu giúp"},{"hanzi":"挽留","pinyin":"wǎnliú","vi":"níu giữ"},{"hanzi":"拉","pinyin":"lā","vi":"kéo"}]},{"id":"晚间","hanzi":"晚间","pinyin":"wǎnjiān","meaning_vi":"buổi tối, ban đêm","explanation":"晚 (vãn – muộn, tối) + 间 (gian – khoảng) → khoảng thời gian buổi tối.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌙","examples":[{"type":"basic","zh":"晚间新闻开始了。","pinyin":"Wǎnjiān xīnwén kāishǐ le.","vi":"Bản tin buổi tối bắt đầu rồi."},{"type":"simple","zh":"这家超市晚间七点以后打八折。","pinyin":"Zhè jiā chāoshì wǎnjiān qīdiǎn yǐhòu dǎ bā zhé.","vi":"Siêu thị này giảm 20% sau bảy giờ tối."},{"type":"compound","zh":"因为晚间气温会骤降，所以出门记得多穿件衣服。","pinyin":"Yīnwèi wǎnjiān qìwēn huì zhòujiàng, suǒyǐ chūmén jìde duō chuān jiàn yīfu.","vi":"Vì buổi tối nhiệt độ sẽ giảm đột ngột nên ra ngoài nhớ mặc thêm áo."}],"related":[{"hanzi":"夜间","pinyin":"yèjiān","vi":"ban đêm"},{"hanzi":"晚上","pinyin":"wǎnshang","vi":"buổi tối"},{"hanzi":"傍晚","pinyin":"bàngwǎn","vi":"chạng vạng"},{"hanzi":"白天","pinyin":"báitiān","vi":"ban ngày"}],"traditional":"晚間"},{"id":"晚年","hanzi":"晚年","pinyin":"wǎnnián","meaning_vi":"tuổi già, những năm cuối đời","explanation":"晚 (vãn – muộn) + 年 (niên – năm) → những năm cuối của đời người.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"👴","examples":[{"type":"basic","zh":"他晚年过得很幸福。","pinyin":"Tā wǎnnián guòde hěn xìngfú.","vi":"Tuổi già ông ấy sống rất hạnh phúc."},{"type":"simple","zh":"爷爷晚年最大的爱好是种花。","pinyin":"Yéye wǎnnián zuì dà de àihào shì zhònghuā.","vi":"Sở thích lớn nhất của ông nội lúc về già là trồng hoa."},{"type":"compound","zh":"虽然他年轻时吃了很多苦，但是晚年生活很安稳。","pinyin":"Suīrán tā niánqīng shí chīle hěn duō kǔ, dànshì wǎnnián shēnghuó hěn ānwěn.","vi":"Tuy lúc trẻ ông chịu nhiều khổ cực nhưng cuộc sống tuổi già rất yên ổn."}],"related":[{"hanzi":"老年","pinyin":"lǎonián","vi":"tuổi già"},{"hanzi":"晚景","pinyin":"wǎnjǐng","vi":"cảnh về già"},{"hanzi":"青年","pinyin":"qīngnián","vi":"thanh niên"},{"hanzi":"养老","pinyin":"yǎnglǎo","vi":"dưỡng lão"}]},{"id":"晚期","hanzi":"晚期","pinyin":"wǎnqī","meaning_vi":"thời kỳ cuối, giai đoạn cuối","explanation":"晚 (vãn – muộn) + 期 (kỳ – thời kỳ) → thời kỳ cuối; hay dùng cho bệnh tật (癌症晚期) hoặc giai đoạn lịch sử.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"⏳","examples":[{"type":"basic","zh":"他是肺癌晚期。","pinyin":"Tā shì fèi'ái wǎnqī.","vi":"Ông ấy bị ung thư phổi giai đoạn cuối."},{"type":"simple","zh":"这幅画是画家晚期的代表作品。","pinyin":"Zhè fú huà shì huàjiā wǎnqī de dàibiǎo zuòpǐn.","vi":"Bức tranh này là tác phẩm tiêu biểu thời kỳ cuối của họa sĩ."},{"type":"compound","zh":"如果早点检查，就不会拖到晚期才发现。","pinyin":"Rúguǒ zǎodiǎn jiǎnchá, jiù bú huì tuō dào wǎnqī cái fāxiàn.","vi":"Nếu khám sớm hơn thì đã không để đến giai đoạn cuối mới phát hiện."}],"related":[{"hanzi":"早期","pinyin":"zǎoqī","vi":"thời kỳ đầu"},{"hanzi":"中期","pinyin":"zhōngqī","vi":"thời kỳ giữa"},{"hanzi":"后期","pinyin":"hòuqī","vi":"giai đoạn sau"},{"hanzi":"末期","pinyin":"mòqī","vi":"thời kỳ cuối"}]},{"id":"万万","hanzi":"万万","pinyin":"wànwàn","meaning_vi":"tuyệt đối (không), dù thế nào cũng (không)","explanation":"万 (vạn – mười nghìn) lặp lại → nhấn mạnh tuyệt đối; thường đứng trước 不/没/别: 万万不可.","hsk_level":"7-9","tags":["pho-tu"],"image":"🚫","examples":[{"type":"basic","zh":"这事万万不可。","pinyin":"Zhè shì wànwàn bùkě.","vi":"Việc này tuyệt đối không được."},{"type":"simple","zh":"我万万没想到他会骗我。","pinyin":"Wǒ wànwàn méi xiǎngdào tā huì piàn wǒ.","vi":"Tôi không ngờ được rằng anh ấy lại lừa tôi."},{"type":"compound","zh":"即使再生气，你也万万不能动手打人。","pinyin":"Jíshǐ zài shēngqì, nǐ yě wànwàn bù néng dòngshǒu dǎrén.","vi":"Dù có tức giận đến đâu, bạn cũng tuyệt đối không được ra tay đánh người."}],"related":[{"hanzi":"千万","pinyin":"qiānwàn","vi":"nhất thiết"},{"hanzi":"绝对","pinyin":"juéduì","vi":"tuyệt đối"},{"hanzi":"决不","pinyin":"juébù","vi":"quyết không"},{"hanzi":"务必","pinyin":"wùbì","vi":"nhất định phải"}],"traditional":"萬萬"},{"id":"汪洋","hanzi":"汪洋","pinyin":"wāngyáng","meaning_vi":"biển nước mênh mông, bao la","explanation":"汪 (uông – nước sâu rộng) + 洋 (dương – biển lớn) → vùng nước mênh mông bát ngát.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"眼前是一片汪洋。","pinyin":"Yǎnqián shì yípiàn wāngyáng.","vi":"Trước mắt là một biển nước mênh mông."},{"type":"simple","zh":"洪水过后，整个村庄成了一片汪洋。","pinyin":"Hóngshuǐ guòhòu, zhěnggè cūnzhuāng chéngle yípiàn wāngyáng.","vi":"Sau trận lũ, cả ngôi làng biến thành một biển nước."},{"type":"compound","zh":"虽然小船在汪洋中显得很渺小，但是它一直没有停下。","pinyin":"Suīrán xiǎochuán zài wāngyáng zhōng xiǎnde hěn miǎoxiǎo, dànshì tā yìzhí méiyǒu tíngxià.","vi":"Tuy con thuyền nhỏ trông thật bé nhỏ giữa biển nước mênh mông, nhưng nó vẫn không dừng lại."}],"related":[{"hanzi":"海洋","pinyin":"hǎiyáng","vi":"đại dương"},{"hanzi":"大海","pinyin":"dàhǎi","vi":"biển cả"},{"hanzi":"辽阔","pinyin":"liáokuò","vi":"bao la"},{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"}]},{"id":"王国","hanzi":"王国","pinyin":"wángguó","meaning_vi":"vương quốc","explanation":"王 (vương – vua) + 国 (quốc – nước) → đất nước do vua cai trị; nghĩa bóng: thế giới riêng (动物王国).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"英国是个王国。","pinyin":"Yīng guóshì gè wángguó.","vi":"Anh là một vương quốc."},{"type":"simple","zh":"这个动物园被称为孩子们的动物王国。","pinyin":"Zhè ge dòngwùyuán bèi chēngwéi háizimen de dòngwù wángguó.","vi":"Vườn thú này được gọi là vương quốc động vật của trẻ em."},{"type":"compound","zh":"虽然这个王国面积很小，但是历史非常悠久。","pinyin":"Suīrán zhè ge wángguó miànjī hěn xiǎo, dànshì lìshǐ fēicháng yōujiǔ.","vi":"Tuy vương quốc này diện tích rất nhỏ nhưng lịch sử vô cùng lâu đời."}],"related":[{"hanzi":"国王","pinyin":"guówáng","vi":"quốc vương"},{"hanzi":"王子","pinyin":"wángzǐ","vi":"hoàng tử"},{"hanzi":"帝国","pinyin":"dìguó","vi":"đế quốc"},{"hanzi":"共和国","pinyin":"gònghéguó","vi":"nước cộng hòa"}],"traditional":"王國"},{"id":"王牌","hanzi":"王牌","pinyin":"wángpái","meaning_vi":"con át chủ bài, quân bài tẩy; hàng đầu","explanation":"王 (vương – vua) + 牌 (bài – quân bài) → quân bài mạnh nhất; nghĩa bóng là người/vật chủ lực.","hsk_level":"7-9","tags":["danh-tu"],"image":"🃏","examples":[{"type":"basic","zh":"他是队里的王牌。","pinyin":"Tā shì duì li de wángpái.","vi":"Anh ấy là con át chủ bài của đội."},{"type":"simple","zh":"这款手机是公司今年的王牌产品。","pinyin":"Zhè kuǎn shǒujī shì gōngsī jīnnián de wángpái chǎnpǐn.","vi":"Mẫu điện thoại này là sản phẩm chủ lực năm nay của công ty."},{"type":"compound","zh":"如果对手不出全力，我们就先不打出王牌。","pinyin":"Rúguǒ duìshǒu bù chū quánlì, wǒmen jiù xiān bù dǎ chū wángpái.","vi":"Nếu đối thủ không dốc toàn lực thì ta tạm thời chưa tung con át chủ bài."}],"related":[{"hanzi":"王牌军","pinyin":"wángpáijūn","vi":"đội quân tinh nhuệ"},{"hanzi":"主力","pinyin":"zhǔlì","vi":"chủ lực"},{"hanzi":"底牌","pinyin":"dǐpái","vi":"bài tẩy"},{"hanzi":"招牌","pinyin":"zhāopai","vi":"chiêu bài"}]},{"id":"网点","hanzi":"网点","pinyin":"wǎngdiǎn","meaning_vi":"điểm giao dịch, điểm bán hàng, chi nhánh (trong mạng lưới)","explanation":"网 (võng – mạng lưới) + 点 (điểm) → các điểm nằm trong một mạng lưới kinh doanh, dịch vụ.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"附近有银行网点吗？","pinyin":"Fùjìn yǒu yínháng wǎngdiǎn ma?","vi":"Gần đây có điểm giao dịch ngân hàng không?"},{"type":"simple","zh":"这家快递公司在全国有上万个网点。","pinyin":"Zhè jiā kuàidì gōngsī zài quán guóyǒu shàngwàn gè wǎngdiǎn.","vi":"Công ty chuyển phát này có hơn một vạn điểm giao dịch trên cả nước."},{"type":"compound","zh":"因为网上业务越来越多，所以很多银行关闭了一些网点。","pinyin":"Yīnwèi wǎngshàng yèwù yuèláiyuè duō, suǒyǐ hěn duō yínháng guānbìle yìxiē wǎngdiǎn.","vi":"Vì giao dịch trực tuyến ngày càng nhiều nên nhiều ngân hàng đã đóng bớt một số điểm giao dịch."}],"related":[{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng lưới"},{"hanzi":"分行","pinyin":"fēnháng","vi":"chi nhánh ngân hàng"},{"hanzi":"门店","pinyin":"méndiàn","vi":"cửa hàng"},{"hanzi":"营业厅","pinyin":"yíngyètīng","vi":"quầy giao dịch"}],"traditional":"網點"},{"id":"忘不了","hanzi":"忘不了","pinyin":"wàngbùliǎo","meaning_vi":"không thể quên, quên không được","explanation":"忘 (vong – quên) + 不了 (không thể) → muốn quên cũng không quên được.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"我忘不了那一天。","pinyin":"Wǒ wàngbùliǎo nà yì tiān.","vi":"Tôi không thể quên ngày hôm đó."},{"type":"simple","zh":"她永远忘不了外婆做的红烧肉。","pinyin":"Tā yǒngyuǎn wàngbùliǎo wàipó zuò de hóngshāoròu.","vi":"Cô ấy mãi không quên được món thịt kho của bà ngoại."},{"type":"compound","zh":"虽然已经过去十年了，但是我还是忘不了他的笑容。","pinyin":"Suīrán yǐjīng guòqù shí nián le, dànshì wǒ háishi wàngbùliǎo tā de xiàoróng.","vi":"Tuy đã mười năm trôi qua nhưng tôi vẫn không quên được nụ cười của anh ấy."}],"related":[{"hanzi":"难忘","pinyin":"nánwàng","vi":"khó quên"},{"hanzi":"忘掉","pinyin":"wàngdiào","vi":"quên đi"},{"hanzi":"记住","pinyin":"jìzhù","vi":"ghi nhớ"},{"hanzi":"怀念","pinyin":"huáiniàn","vi":"hoài niệm"}]},{"id":"忘掉","hanzi":"忘掉","pinyin":"wàngdiào","meaning_vi":"quên đi, quên mất","explanation":"忘 (vong – quên) + 掉 (bổ ngữ: mất đi) → quên hẳn, gạt ra khỏi trí nhớ.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"忘掉那些烦恼吧。","pinyin":"Wàngdiào nàxiē fánnǎo ba.","vi":"Hãy quên đi những phiền muộn đó."},{"type":"simple","zh":"我差点把今天的约会忘掉了。","pinyin":"Wǒ chàdiǎn bǎ jīntiān de yuēhuì wàngdiào le.","vi":"Tôi suýt nữa quên mất cuộc hẹn hôm nay."},{"type":"compound","zh":"即使你想忘掉过去，也不能逃避应该承担的责任。","pinyin":"Jíshǐ nǐ xiǎng wàngdiào guòqù, yě bù néng táobì yīnggāi chéngdān de zérèn.","vi":"Cho dù bạn muốn quên đi quá khứ, cũng không thể trốn tránh trách nhiệm phải gánh vác."}],"related":[{"hanzi":"忘记","pinyin":"wàngjì","vi":"quên"},{"hanzi":"遗忘","pinyin":"yíwàng","vi":"lãng quên"},{"hanzi":"忘不了","pinyin":"wàngbùliǎo","vi":"không quên được"},{"hanzi":"记得","pinyin":"jìde","vi":"nhớ"}]},{"id":"旺盛","hanzi":"旺盛","pinyin":"wàngshèng","meaning_vi":"dồi dào, mạnh mẽ, tràn đầy (sức sống)","explanation":"旺 (vượng – thịnh, mạnh) + 盛 (thịnh – dồi dào) → tràn đầy, sung mãn; hay đi với 精力, 生命力, 需求.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"他精力很旺盛。","pinyin":"Tā jīnglì hěn wàngshèng.","vi":"Anh ấy tràn đầy sinh lực."},{"type":"simple","zh":"春天到了，小草长得十分旺盛。","pinyin":"Chūntiān dào le, xiǎo cǎo zhǎngde shífēn wàngshèng.","vi":"Mùa xuân đến, cỏ non mọc rất tươi tốt."},{"type":"compound","zh":"因为市场需求很旺盛，所以工厂决定增加产量。","pinyin":"Yīnwèi shìchǎng xūqiú hěn wàngshèng, suǒyǐ gōngchǎng juédìng zēngjiā chǎnliàng.","vi":"Vì nhu cầu thị trường rất mạnh nên nhà máy quyết định tăng sản lượng."}],"related":[{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"hưng thịnh"},{"hanzi":"充沛","pinyin":"chōngpèi","vi":"dồi dào"},{"hanzi":"茂盛","pinyin":"màoshèng","vi":"tươi tốt"},{"hanzi":"衰弱","pinyin":"shuāiruò","vi":"suy yếu"}]},{"id":"望","hanzi":"望","pinyin":"wàng","meaning_vi":"nhìn xa, trông; mong, hy vọng; thăm hỏi","explanation":"望 (vọng – trông xa, mong mỏi) → nhìn về phía xa; mở rộng thành mong đợi (希望) và thăm hỏi (看望).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔭","examples":[{"type":"basic","zh":"他抬头望着星空。","pinyin":"Tā táitóu wàngzhe xīngkōng.","vi":"Anh ấy ngẩng đầu ngắm bầu trời sao."},{"type":"simple","zh":"站在山顶望去，整个城市尽收眼底。","pinyin":"Zhàn zài shāndǐng wàng qù, zhěnggè chéngshì jìn shōu yǎndǐ.","vi":"Đứng trên đỉnh núi nhìn ra, cả thành phố thu gọn trong tầm mắt."},{"type":"compound","zh":"如果有什么不懂的地方，望大家及时提出来。","pinyin":"Rúguǒ yǒu shénme bù dǒng de dìfang, wàng dàjiā jíshí tí chūlái.","vi":"Nếu có chỗ nào chưa hiểu, mong mọi người kịp thời nêu ra."}],"related":[{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"},{"hanzi":"看望","pinyin":"kànwàng","vi":"thăm hỏi"},{"hanzi":"眺望","pinyin":"tiàowàng","vi":"nhìn ra xa"},{"hanzi":"失望","pinyin":"shīwàng","vi":"thất vọng"}]},{"id":"望远镜","hanzi":"望远镜","pinyin":"wàngyuǎnjìng","meaning_vi":"kính viễn vọng, ống nhòm","explanation":"望 (vọng – nhìn) + 远 (viễn – xa) + 镜 (kính) → kính dùng để nhìn xa.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔭","examples":[{"type":"basic","zh":"我买了个望远镜。","pinyin":"Wǒ mǎile gè wàngyuǎnjìng.","vi":"Tôi đã mua một cái ống nhòm."},{"type":"simple","zh":"他用望远镜观察树上的小鸟。","pinyin":"Tāyòng wàngyuǎnjìng guānchá shù shang de xiǎoniǎo.","vi":"Anh ấy dùng ống nhòm quan sát chim nhỏ trên cây."},{"type":"compound","zh":"如果天气晴朗，用望远镜就能看清月亮表面。","pinyin":"Rúguǒ tiānqì qínglǎng, yòng wàngyuǎnjìng jiù néng kànqīng yuèliang biǎomiàn.","vi":"Nếu trời quang đãng thì dùng kính viễn vọng có thể nhìn rõ bề mặt mặt trăng."}],"related":[{"hanzi":"显微镜","pinyin":"xiǎnwēijìng","vi":"kính hiển vi"},{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"kính mắt"},{"hanzi":"镜头","pinyin":"jìngtóu","vi":"ống kính"},{"hanzi":"天文台","pinyin":"tiānwéntái","vi":"đài thiên văn"}],"traditional":"望遠鏡"},{"id":"危急","hanzi":"危急","pinyin":"wēijí","meaning_vi":"nguy cấp, nguy kịch","explanation":"危 (nguy – nguy hiểm) + 急 (cấp – gấp) → nguy hiểm và cấp bách, cần xử lý ngay.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🚨","examples":[{"type":"basic","zh":"病人情况很危急。","pinyin":"Bìngrén qíngkuàng hěn wēijí.","vi":"Tình trạng bệnh nhân rất nguy kịch."},{"type":"simple","zh":"在危急关头，他挺身而出救了孩子。","pinyin":"Zài wēijí guāntóu, tā tǐng shēn ér chū jiùle háizi.","vi":"Vào thời khắc nguy cấp, anh ấy xông ra cứu đứa trẻ."},{"type":"compound","zh":"一旦遇到危急情况，就立即拨打急救电话。","pinyin":"Yídàn yùdào wēijí qíngkuàng, jiù lìjí bōdǎ jíjiù diànhuà.","vi":"Một khi gặp tình huống nguy cấp thì lập tức gọi điện cấp cứu."}],"related":[{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"紧急","pinyin":"jǐnjí","vi":"khẩn cấp"},{"hanzi":"危机","pinyin":"wēijī","vi":"khủng hoảng"},{"hanzi":"安全","pinyin":"ānquán","vi":"an toàn"}]},{"id":"萎缩","hanzi":"萎缩","pinyin":"wěisuō","meaning_vi":"teo, héo, co lại; suy giảm, sa sút","explanation":"萎 (nuy – héo) + 缩 (súc – co lại) → héo rút, teo đi; nghĩa bóng là (thị trường, kinh tế) thu hẹp, sa sút.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥀","examples":[{"type":"basic","zh":"他的肌肉萎缩了。","pinyin":"Tā de jīròu wěisuō le.","vi":"Cơ bắp của anh ấy bị teo."},{"type":"simple","zh":"受疫情影响，旅游市场明显萎缩。","pinyin":"Shòu yìqíng yǐngxiǎng, lǚyóu shìchǎng míngxiǎn wěisuō.","vi":"Do ảnh hưởng của dịch bệnh, thị trường du lịch thu hẹp rõ rệt."},{"type":"compound","zh":"如果长期不锻炼，肌肉就会慢慢萎缩。","pinyin":"Rúguǒ chángqī bú duànliàn, jīròu jiù huì mànmàn wěisuō.","vi":"Nếu lâu dài không tập luyện thì cơ bắp sẽ dần dần teo đi."}],"related":[{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"},{"hanzi":"枯萎","pinyin":"kūwěi","vi":"khô héo"},{"hanzi":"衰退","pinyin":"shuāituì","vi":"suy thoái"},{"hanzi":"扩张","pinyin":"kuòzhāng","vi":"mở rộng"}],"traditional":"萎縮"},{"id":"微妙","hanzi":"微妙","pinyin":"wēimiào","meaning_vi":"tinh tế, vi diệu, tế nhị","explanation":"微 (vi – nhỏ bé) + 妙 (diệu – tài tình) → tinh tế, khó nắm bắt; thường nói về quan hệ, cảm xúc, sự khác biệt.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🎭","examples":[{"type":"basic","zh":"两人关系很微妙。","pinyin":"Liǎng rén guānxì hěn wēimiào.","vi":"Quan hệ giữa hai người rất tế nhị."},{"type":"simple","zh":"这两种颜色之间有微妙的差别。","pinyin":"Zhè liǎng zhǒng yánsè zhījiān yǒu wēimiào de chābié.","vi":"Giữa hai màu này có sự khác biệt tinh tế."},{"type":"compound","zh":"虽然他没说什么，但是表情发生了微妙的变化。","pinyin":"Suīrán tā méi shuō shénme, dànshì biǎoqíng fāshēngle wēimiào de biànhuà.","vi":"Tuy anh ấy không nói gì, nhưng nét mặt đã có sự thay đổi khó nhận ra."}],"related":[{"hanzi":"奥妙","pinyin":"àomiào","vi":"huyền diệu"},{"hanzi":"细微","pinyin":"xìwēi","vi":"nhỏ nhặt"},{"hanzi":"复杂","pinyin":"fùzá","vi":"phức tạp"},{"hanzi":"敏感","pinyin":"mǐngǎn","vi":"nhạy cảm"}]},{"id":"微弱","hanzi":"微弱","pinyin":"wēiruò","meaning_vi":"yếu ớt, mờ nhạt, le lói","explanation":"微 (vi – nhỏ) + 弱 (nhược – yếu) → rất yếu, rất nhỏ (ánh sáng, âm thanh, hơi thở…).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🕯️","examples":[{"type":"basic","zh":"他的呼吸很微弱。","pinyin":"Tā de hūxī hěn wēiruò.","vi":"Hơi thở của anh ấy rất yếu ớt."},{"type":"simple","zh":"远处透出一点微弱的灯光。","pinyin":"Yuǎnchù tòu chū yìdiǎn wēiruò de dēngguāng.","vi":"Từ xa le lói một chút ánh đèn yếu ớt."},{"type":"compound","zh":"虽然希望很微弱，但是医生们仍然没有放弃。","pinyin":"Suīrán xīwàng hěn wēiruò, dànshì yīshēngmen réngrán méiyǒu fàngqì.","vi":"Tuy hy vọng rất mong manh nhưng các bác sĩ vẫn không bỏ cuộc."}],"related":[{"hanzi":"虚弱","pinyin":"xūruò","vi":"suy nhược"},{"hanzi":"微小","pinyin":"wēixiǎo","vi":"nhỏ bé"},{"hanzi":"强烈","pinyin":"qiángliè","vi":"mạnh mẽ"},{"hanzi":"薄弱","pinyin":"bóruò","vi":"yếu kém"}]},{"id":"围墙","hanzi":"围墙","pinyin":"wéiqiáng","meaning_vi":"tường rào, tường bao","explanation":"围 (vi – vây quanh) + 墙 (tường) → bức tường bao quanh một khu đất, ngôi nhà.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🧱","examples":[{"type":"basic","zh":"学校的围墙很高。","pinyin":"Xuéxiào de wéiqiáng hěn gāo.","vi":"Tường rào của trường rất cao."},{"type":"simple","zh":"小偷翻过围墙进了院子。","pinyin":"Xiǎotōu fānguò wéiqiáng jìnle yuànzi.","vi":"Tên trộm trèo qua tường rào vào sân."},{"type":"compound","zh":"因为围墙年久失修，所以物业决定重新修建。","pinyin":"Yīnwèi wéiqiáng nián jiǔ shīxiū, suǒyǐ wùyè juédìng chóngxīn xiūjiàn.","vi":"Vì tường bao lâu năm không sửa chữa nên ban quản lý quyết định xây lại."}],"related":[{"hanzi":"墙壁","pinyin":"qiángbì","vi":"vách tường"},{"hanzi":"篱笆","pinyin":"líba","vi":"hàng rào"},{"hanzi":"院子","pinyin":"yuànzi","vi":"sân"},{"hanzi":"大门","pinyin":"dàmén","vi":"cổng lớn"}],"traditional":"圍牆"},{"id":"唯","hanzi":"唯","pinyin":"wéi","meaning_vi":"chỉ, duy nhất","explanation":"唯 (duy – chỉ có) → chỉ, duy nhất; dùng trong văn viết và các từ như 唯一, 唯有.","hsk_level":"7-9","tags":["pho-tu"],"image":"☝️","examples":[{"type":"basic","zh":"唯你是问。","pinyin":"Wéi nǐ shì wèn.","vi":"Chỉ hỏi tội mình anh thôi."},{"type":"simple","zh":"大家都同意了，唯他一人反对。","pinyin":"Dàjiā dōu tóngyì le, wéi tā yìrén fǎnduì.","vi":"Mọi người đều đồng ý, chỉ có mình anh ta phản đối."},{"type":"compound","zh":"虽然条件很艰苦，但是唯有坚持才能成功。","pinyin":"Suīrán tiáojiàn hěn jiānkǔ, dànshì wéiyǒu jiānchí cáinéng chénggōng.","vi":"Tuy điều kiện rất gian khổ nhưng chỉ có kiên trì mới thành công."}],"related":[{"hanzi":"唯一","pinyin":"wéiyī","vi":"duy nhất"},{"hanzi":"唯有","pinyin":"wéiyǒu","vi":"chỉ có"},{"hanzi":"只","pinyin":"zhǐ","vi":"chỉ"},{"hanzi":"仅","pinyin":"jǐn","vi":"chỉ, vẻn vẹn"}]},{"id":"尾气","hanzi":"尾气","pinyin":"wěiqì","meaning_vi":"khí thải (xe cộ)","explanation":"尾 (vĩ – đuôi) + 气 (khí) → khí thoát ra từ đuôi xe, tức khí thải của phương tiện.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"💨","examples":[{"type":"basic","zh":"汽车尾气污染空气。","pinyin":"Qìchē wěiqì wūrǎn kōngqì.","vi":"Khí thải ô tô làm ô nhiễm không khí."},{"type":"simple","zh":"新车必须通过尾气排放检测。","pinyin":"Xīnchē bìxū tōngguò wěiqì páifàng jiǎncè.","vi":"Xe mới phải qua kiểm định khí thải."},{"type":"compound","zh":"如果大家多坐地铁，城市里的尾气就会少很多。","pinyin":"Rúguǒ dàjiā duō zuò dìtiě, chéngshì li de wěiqì jiù huì shǎo hěn duō.","vi":"Nếu mọi người đi tàu điện ngầm nhiều hơn thì khí thải trong thành phố sẽ giảm đi nhiều."}],"related":[{"hanzi":"废气","pinyin":"fèiqì","vi":"khí thải"},{"hanzi":"排放","pinyin":"páifàng","vi":"thải ra"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"ô nhiễm"},{"hanzi":"雾霾","pinyin":"wùmái","vi":"sương mù khói bụi"}],"traditional":"尾氣"},{"id":"委员会","hanzi":"委员会","pinyin":"wěiyuánhuì","meaning_vi":"ủy ban, hội đồng","explanation":"委员 (ủy viên – thành viên được ủy nhiệm) + 会 (hội) → tổ chức gồm các ủy viên, tức ủy ban.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"委员会已经成立了。","pinyin":"Wěiyuánhuì yǐjīng chénglì le.","vi":"Ủy ban đã được thành lập."},{"type":"simple","zh":"这个方案需要委员会投票通过。","pinyin":"Zhè ge fāng'àn xūyào wěiyuánhuì tóupiào tōngguò.","vi":"Phương án này cần ủy ban bỏ phiếu thông qua."},{"type":"compound","zh":"虽然委员会讨论了很久，但是还是没有做出决定。","pinyin":"Suīrán wěiyuánhuì tǎolùnle hěn jiǔ, dànshì háishi méiyǒu zuòchū juédìng.","vi":"Tuy ủy ban thảo luận rất lâu nhưng vẫn chưa đưa ra quyết định."}],"related":[{"hanzi":"委员","pinyin":"wěiyuán","vi":"ủy viên"},{"hanzi":"主任","pinyin":"zhǔrèn","vi":"chủ nhiệm"},{"hanzi":"理事会","pinyin":"lǐshìhuì","vi":"hội đồng quản trị"},{"hanzi":"会议","pinyin":"huìyì","vi":"hội nghị"}],"traditional":"委員會"},{"id":"卫视","hanzi":"卫视","pinyin":"wèishì","meaning_vi":"truyền hình vệ tinh, kênh vệ tinh","explanation":"卫 (vệ – trong 卫星: vệ tinh) + 视 (thị – trong 电视: truyền hình) → kênh truyền hình phát qua vệ tinh.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📡","examples":[{"type":"basic","zh":"我爱看湖南卫视。","pinyin":"Wǒ ài kàn Húnán wèishì.","vi":"Tôi thích xem kênh vệ tinh Hồ Nam."},{"type":"simple","zh":"这部电视剧今晚在东方卫视首播。","pinyin":"Zhè bù diànshìjù jīnwǎn zài dōngfāng wèishì shǒubō.","vi":"Bộ phim truyền hình này tối nay ra mắt trên kênh vệ tinh Đông Phương."},{"type":"compound","zh":"因为这档节目收视率很高，所以多家卫视都想购买版权。","pinyin":"Yīnwèi zhè dàng jiémù shōushìlǜ hěn gāo, suǒyǐ duō jiā wèishì dōu xiǎng gòumǎi bǎnquán.","vi":"Vì chương trình này có tỷ suất người xem cao nên nhiều kênh vệ tinh đều muốn mua bản quyền."}],"related":[{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"电视台","pinyin":"diànshìtái","vi":"đài truyền hình"},{"hanzi":"频道","pinyin":"píndào","vi":"kênh"},{"hanzi":"节目","pinyin":"jiémù","vi":"chương trình"}],"traditional":"衛視"},{"id":"为人","hanzi":"为人","pinyin":"wéirén","meaning_vi":"cách đối nhân xử thế, tính cách, con người","explanation":"为 (vi – làm) + 人 (nhân – người) → cách làm người, cách cư xử với người khác.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🙂","examples":[{"type":"basic","zh":"他为人很正直。","pinyin":"Tā wéirén hěn zhèngzhí.","vi":"Anh ấy là người rất chính trực."},{"type":"simple","zh":"老王为人热情，邻居们都喜欢他。","pinyin":"Lǎo Wáng wéirén rèqíng, línjūmen dōu xǐhuan tā.","vi":"Ông Vương tính tình nhiệt tình, hàng xóm đều quý ông."},{"type":"compound","zh":"虽然他能力一般，但是为人很实在，大家都信任他。","pinyin":"Suīrán tā nénglì yìbān, dànshì wéirén hěn shízài, dàjiā dōu xìnrèn tā.","vi":"Tuy năng lực anh ấy bình thường nhưng con người rất thật thà, ai cũng tin tưởng."}],"related":[{"hanzi":"做人","pinyin":"zuòrén","vi":"làm người"},{"hanzi":"人品","pinyin":"rénpǐn","vi":"nhân phẩm"},{"hanzi":"品格","pinyin":"pǐngé","vi":"phẩm cách"},{"hanzi":"处世","pinyin":"chǔshì","vi":"xử thế"}],"traditional":"為人"},{"id":"未","hanzi":"未","pinyin":"wèi","meaning_vi":"chưa, không","explanation":"未 (vị – chưa) → phủ định trong văn viết, tương đương 没有 hoặc 不: 未完成, 尚未.","hsk_level":"7-9","tags":["pho-tu"],"image":"⌛","examples":[{"type":"basic","zh":"此事尚未决定。","pinyin":"Cǐshì shàngwèi juédìng.","vi":"Việc này vẫn chưa quyết định."},{"type":"simple","zh":"这本小说他写了一半，至今未完成。","pinyin":"Zhè běn xiǎoshuō tā xiěle yíbàn, zhìjīn wèi wánchéng.","vi":"Cuốn tiểu thuyết này ông viết được một nửa, đến nay vẫn chưa hoàn thành."},{"type":"compound","zh":"虽然雨已经停了，但是道路还未完全恢复通行。","pinyin":"Suīrán yǔ yǐjīng tíng le, dànshì dàolù hái wèi wánquán huīfù tōngxíng.","vi":"Tuy mưa đã tạnh nhưng đường sá vẫn chưa hoàn toàn thông xe trở lại."}],"related":[{"hanzi":"尚未","pinyin":"shàngwèi","vi":"vẫn chưa"},{"hanzi":"未来","pinyin":"wèilái","vi":"tương lai"},{"hanzi":"没有","pinyin":"méiyǒu","vi":"chưa, không có"},{"hanzi":"已经","pinyin":"yǐjīng","vi":"đã"}]},{"id":"未成年人","hanzi":"未成年人","pinyin":"wèichéngniánrén","meaning_vi":"người chưa thành niên","explanation":"未 (vị – chưa) + 成年 (thành niên – trưởng thành) + 人 (nhân) → người chưa đến tuổi trưởng thành (dưới 18).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🧒","examples":[{"type":"basic","zh":"未成年人禁止入内。","pinyin":"Wèichéngniánrén jìnzhǐ rù nèi.","vi":"Cấm người chưa thành niên vào trong."},{"type":"simple","zh":"商店不能向未成年人出售香烟。","pinyin":"Shāngdiàn bù néng xiàng wèichéngniánrén chūshòu xiāngyān.","vi":"Cửa hàng không được bán thuốc lá cho người chưa thành niên."},{"type":"compound","zh":"因为他还是未成年人，所以签合同需要父母同意。","pinyin":"Yīnwèi tā háishi wèichéngniánrén, suǒyǐ qiānhétong xūyào fùmǔ tóngyì.","vi":"Vì cậu ấy vẫn là người chưa thành niên nên ký hợp đồng cần có sự đồng ý của cha mẹ."}],"related":[{"hanzi":"成年人","pinyin":"chéngniánrén","vi":"người trưởng thành"},{"hanzi":"青少年","pinyin":"qīngshàonián","vi":"thanh thiếu niên"},{"hanzi":"儿童","pinyin":"értóng","vi":"trẻ em"},{"hanzi":"监护人","pinyin":"jiānhùrén","vi":"người giám hộ"}]},{"id":"未经","hanzi":"未经","pinyin":"wèijīng","meaning_vi":"chưa qua, chưa được (cho phép…)","explanation":"未 (vị – chưa) + 经 (kinh – trải qua) → chưa trải qua (thủ tục, sự cho phép…); hay gặp 未经允许, 未经同意.","hsk_level":"7-9","tags":["pho-tu"],"image":"⛔","examples":[{"type":"basic","zh":"未经允许，请勿入内。","pinyin":"Wèijīng yǔnxǔ, qǐngwù rù nèi.","vi":"Chưa được phép, xin đừng vào."},{"type":"simple","zh":"他未经同意就用了我的电脑。","pinyin":"Tā wèijīng tóngyì jiù yòngle wǒ de diànnǎo.","vi":"Anh ta dùng máy tính của tôi mà chưa được đồng ý."},{"type":"compound","zh":"如果未经核实就发布消息，就可能造成严重后果。","pinyin":"Rúguǒ wèijīng héshí jiù fābù xiāoxi, jiù kěnéng zàochéng yánzhòng hòuguǒ.","vi":"Nếu chưa kiểm chứng đã đăng tin thì có thể gây hậu quả nghiêm trọng."}],"related":[{"hanzi":"未","pinyin":"wèi","vi":"chưa"},{"hanzi":"经过","pinyin":"jīngguò","vi":"trải qua"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"cho phép"},{"hanzi":"擅自","pinyin":"shànzì","vi":"tự ý"}],"traditional":"未經"},{"id":"位子","hanzi":"位子","pinyin":"wèizi","meaning_vi":"chỗ ngồi; vị trí, chức vị","explanation":"位 (vị – chỗ, vị trí) + 子 (hậu tố) → chỗ ngồi; nghĩa bóng là chức vụ, địa vị.","hsk_level":"7-9","tags":["danh-tu"],"image":"💺","examples":[{"type":"basic","zh":"这个位子有人吗？","pinyin":"Zhè ge wèizi yǒurén ma?","vi":"Chỗ này có ai ngồi chưa?"},{"type":"simple","zh":"我早点去电影院帮你占个位子。","pinyin":"Wǒ zǎodiǎn qù diànyǐngyuàn bāng nǐ zhàn gè wèizi.","vi":"Tôi đến rạp chiếu phim sớm giữ chỗ cho bạn."},{"type":"compound","zh":"虽然他坐上了经理的位子，但是压力也越来越大。","pinyin":"Suīrán tā zuò shàngle jīnglǐ de wèizi, dànshì yālì yě yuèláiyuè dà.","vi":"Tuy anh ấy đã ngồi lên ghế giám đốc nhưng áp lực cũng ngày càng lớn."}],"related":[{"hanzi":"座位","pinyin":"zuòwèi","vi":"chỗ ngồi"},{"hanzi":"位置","pinyin":"wèizhi","vi":"vị trí"},{"hanzi":"职位","pinyin":"zhíwèi","vi":"chức vị"},{"hanzi":"让座","pinyin":"ràngzuò","vi":"nhường chỗ"}]},{"id":"喂养","hanzi":"喂养","pinyin":"wèiyǎng","meaning_vi":"nuôi, cho ăn, nuôi dưỡng","explanation":"喂 (úy – cho ăn) + 养 (dưỡng – nuôi) → cho ăn và chăm nuôi (trẻ nhỏ, vật nuôi).","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🍼","examples":[{"type":"basic","zh":"她用母乳喂养孩子。","pinyin":"Tā yòng mǔrǔ wèiyǎng háizi.","vi":"Cô ấy nuôi con bằng sữa mẹ."},{"type":"simple","zh":"奶奶在院子里喂养了十几只鸡。","pinyin":"Nǎinai zài yuànzi li wèiyǎngle shíjǐ zhī jī.","vi":"Bà nội nuôi hơn chục con gà trong sân."},{"type":"compound","zh":"如果喂养方法不科学，宠物就容易生病。","pinyin":"Rúguǒ wèiyǎng fāngfǎ bù kēxué, chǒngwù jiù róngyì shēngbìng.","vi":"Nếu cách cho ăn không khoa học thì thú cưng dễ bị bệnh."}],"related":[{"hanzi":"饲养","pinyin":"sìyǎng","vi":"chăn nuôi"},{"hanzi":"喂","pinyin":"wèi","vi":"cho ăn"},{"hanzi":"抚养","pinyin":"fǔyǎng","vi":"nuôi nấng"},{"hanzi":"养育","pinyin":"yǎngyù","vi":"nuôi dạy"}],"traditional":"餵養"},{"id":"慰劳","hanzi":"慰劳","pinyin":"wèiláo","meaning_vi":"úy lạo, thăm hỏi khích lệ, khao thưởng","explanation":"慰 (úy – an ủi) + 劳 (lao – công lao, vất vả) → an ủi, khao thưởng người đã vất vả.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎁","examples":[{"type":"basic","zh":"我们去慰劳工人。","pinyin":"Wǒmen qù wèiláo gōngrén.","vi":"Chúng ta đi thăm hỏi khích lệ công nhân."},{"type":"simple","zh":"老板请大家吃饭，慰劳一下辛苦的员工。","pinyin":"Lǎobǎn qǐng dàjiā chīfàn, wèiláo yíxià xīnkǔ de yuángōng.","vi":"Ông chủ mời mọi người ăn cơm để khao nhân viên đã vất vả."},{"type":"compound","zh":"因为大家连续加班一个月，所以公司准备了礼物慰劳大家。","pinyin":"Yīnwèi dàjiā liánxù jiābān yí gèyuè, suǒyǐ gōngsī zhǔnbèile lǐwù wèiláo dàjiā.","vi":"Vì mọi người tăng ca liên tục một tháng nên công ty chuẩn bị quà để khích lệ mọi người."}],"related":[{"hanzi":"慰问","pinyin":"wèiwèn","vi":"thăm hỏi"},{"hanzi":"犒劳","pinyin":"kàoláo","vi":"khao thưởng"},{"hanzi":"安慰","pinyin":"ānwèi","vi":"an ủi"},{"hanzi":"辛劳","pinyin":"xīnláo","vi":"vất vả"}],"traditional":"慰勞"},{"id":"温度计","hanzi":"温度计","pinyin":"wēndùjì","meaning_vi":"nhiệt kế","explanation":"温度 (ôn độ – nhiệt độ) + 计 (kế – dụng cụ đo) → dụng cụ đo nhiệt độ.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🌡️","examples":[{"type":"basic","zh":"温度计显示三十度。","pinyin":"Wēndùjì xiǎnshì sānshí dù.","vi":"Nhiệt kế chỉ ba mươi độ."},{"type":"simple","zh":"窗外挂着一个小小的温度计。","pinyin":"Chuāng wàiguàzhe yí gè xiǎoxiǎo de wēndùjì.","vi":"Ngoài cửa sổ treo một chiếc nhiệt kế nhỏ."},{"type":"compound","zh":"如果温度计打碎了，就不要用手去碰里面的水银。","pinyin":"Rúguǒ wēndùjì dǎsuì le, jiù bú yào yòng shǒu qù pèng lǐmiàn de shuǐyín.","vi":"Nếu nhiệt kế bị vỡ thì đừng dùng tay chạm vào thủy ngân bên trong."}],"related":[{"hanzi":"体温计","pinyin":"tǐwēnjì","vi":"nhiệt kế đo thân nhiệt"},{"hanzi":"温度","pinyin":"wēndù","vi":"nhiệt độ"},{"hanzi":"气温","pinyin":"qìwēn","vi":"nhiệt độ không khí"},{"hanzi":"湿度","pinyin":"shīdù","vi":"độ ẩm"}],"traditional":"溫度計"},{"id":"温室","hanzi":"温室","pinyin":"wēnshì","meaning_vi":"nhà kính","explanation":"温 (ôn – ấm) + 室 (thất – phòng) → phòng giữ ấm để trồng cây; 温室效应 là hiệu ứng nhà kính.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"温室里种着蔬菜。","pinyin":"Wēnshì li zhòngzhe shūcài.","vi":"Trong nhà kính trồng rau."},{"type":"simple","zh":"冬天，这些花只能放在温室里。","pinyin":"Dōngtiān, zhèxiē huā zhǐnéng fàng zài wēnshì li.","vi":"Mùa đông, những bông hoa này chỉ có thể để trong nhà kính."},{"type":"compound","zh":"因为温室气体排放增加，所以全球气温不断上升。","pinyin":"Yīnwèi wēnshì qìtǐ páifàng zēngjiā, suǒyǐ quánqiú qìwēn búduàn shàngshēng.","vi":"Vì lượng khí nhà kính thải ra tăng lên nên nhiệt độ toàn cầu không ngừng tăng."}],"related":[{"hanzi":"大棚","pinyin":"dàpéng","vi":"nhà lưới, nhà màng"},{"hanzi":"温室效应","pinyin":"wēnshìxiàoyìng","vi":"hiệu ứng nhà kính"},{"hanzi":"花房","pinyin":"huāfáng","vi":"nhà trồng hoa"},{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"}],"traditional":"溫室"},{"id":"温习","hanzi":"温习","pinyin":"wēnxí","meaning_vi":"ôn tập, ôn lại","explanation":"温 (ôn – ôn lại) + 习 (tập – học tập) → ôn lại bài cũ (温故而知新).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"我在温习功课。","pinyin":"Wǒ zài wēnxí gōngkè.","vi":"Tôi đang ôn bài."},{"type":"simple","zh":"考试前一周，他每天晚上都温习笔记。","pinyin":"Kǎoshì qián yìzhōu, tā měitiān wǎnshang dōu wēnxí bǐjì.","vi":"Một tuần trước kỳ thi, tối nào cậu ấy cũng ôn lại ghi chép."},{"type":"compound","zh":"如果学过的内容不经常温习，就很容易忘记。","pinyin":"Rúguǒ xuéguò de nèiróng bù jīngcháng wēnxí, jiù hěn róngyì wàngjì.","vi":"Nếu nội dung đã học không thường xuyên ôn lại thì rất dễ quên."}],"related":[{"hanzi":"复习","pinyin":"fùxí","vi":"ôn tập"},{"hanzi":"预习","pinyin":"yùxí","vi":"chuẩn bị bài"},{"hanzi":"学习","pinyin":"xuéxí","vi":"học tập"},{"hanzi":"功课","pinyin":"gōngkè","vi":"bài vở"}],"traditional":"溫習"},{"id":"温馨","hanzi":"温馨","pinyin":"wēnxīn","meaning_vi":"ấm áp, ấm cúng","explanation":"温 (ôn – ấm) + 馨 (hinh – hương thơm) → ấm áp, dễ chịu; hay dùng cho không khí gia đình, lời nhắc (温馨提示).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🏡","examples":[{"type":"basic","zh":"这个家很温馨。","pinyin":"Zhè ge jiā hěn wēnxīn.","vi":"Ngôi nhà này rất ấm cúng."},{"type":"simple","zh":"温馨提示：请保管好您的随身物品。","pinyin":"Wēnxīn tíshì: qǐng bǎoguǎn hǎo nín de suíshēn wùpǐn.","vi":"Lời nhắc nhỏ: xin quý khách giữ gìn đồ đạc mang theo."},{"type":"compound","zh":"虽然房间不大，但是布置得很温馨。","pinyin":"Suīrán fángjiān búdà, dànshì bùzhì de hěn wēnxīn.","vi":"Tuy căn phòng không lớn nhưng được bày trí rất ấm cúng."}],"related":[{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"},{"hanzi":"舒适","pinyin":"shūshì","vi":"dễ chịu"},{"hanzi":"浪漫","pinyin":"làngmàn","vi":"lãng mạn"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"vắng lạnh"}],"traditional":"溫馨"},{"id":"瘟疫","hanzi":"瘟疫","pinyin":"wēnyì","meaning_vi":"bệnh dịch, ôn dịch","explanation":"瘟 (ôn – bệnh dịch) + 疫 (dịch – bệnh lây lan) → bệnh truyền nhiễm lan rộng.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🦠","examples":[{"type":"basic","zh":"那年发生了瘟疫。","pinyin":"Nà nián fāshēngle wēnyì.","vi":"Năm đó xảy ra bệnh dịch."},{"type":"simple","zh":"中世纪的一场瘟疫夺走了无数人的生命。","pinyin":"Zhōngshìjì de yì chǎng wēnyì duózǒule wúshù rén de shēngmìng.","vi":"Một trận dịch thời Trung cổ đã cướp đi vô số sinh mạng."},{"type":"compound","zh":"一旦瘟疫开始流行，就必须立刻隔离病人。","pinyin":"Yídàn wēnyì kāishǐ liúxíng, jiù bìxū lìkè gélí bìngrén.","vi":"Một khi dịch bệnh bắt đầu lan rộng thì phải lập tức cách ly người bệnh."}],"related":[{"hanzi":"疫情","pinyin":"yìqíng","vi":"tình hình dịch bệnh"},{"hanzi":"传染病","pinyin":"chuánrǎnbìng","vi":"bệnh truyền nhiễm"},{"hanzi":"鼠疫","pinyin":"shǔyì","vi":"bệnh dịch hạch"},{"hanzi":"疫苗","pinyin":"yìmiáo","vi":"vắc-xin"}]},{"id":"文","hanzi":"文","pinyin":"wén","meaning_vi":"chữ viết, văn, văn chương; văn hóa; (họ) Văn","explanation":"文 (văn – hoa văn, chữ viết) → chữ, bài văn, văn chương; đối lập với 武 (võ); cũng là họ Văn.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"📜","examples":[{"type":"basic","zh":"这段古文很难懂。","pinyin":"Zhè duàn gǔwén hěn nándǒng.","vi":"Đoạn văn cổ này rất khó hiểu."},{"type":"simple","zh":"他能文能武，书法和剑术样样精通。","pinyin":"Tā néng wén néng wǔ, shūfǎ hé jiànshù yàngyàng jīngtōng.","vi":"Anh ấy văn võ song toàn, thư pháp lẫn kiếm thuật đều tinh thông."},{"type":"compound","zh":"虽然他是理科生，但是作文写得一点也不差。","pinyin":"Suīrán tā shì lǐkē shēng, dànshì zuòwén xiě de yìdiǎn yě búchà.","vi":"Tuy cậu ấy là học sinh ban tự nhiên nhưng viết văn chẳng kém chút nào."}],"related":[{"hanzi":"文字","pinyin":"wénzì","vi":"chữ viết"},{"hanzi":"文章","pinyin":"wénzhāng","vi":"bài văn"},{"hanzi":"文化","pinyin":"wénhuà","vi":"văn hóa"},{"hanzi":"武","pinyin":"wǔ","vi":"võ"}]},{"id":"文科","hanzi":"文科","pinyin":"wénkē","meaning_vi":"khối xã hội, ngành khoa học xã hội và nhân văn","explanation":"文 (văn – văn chương) + 科 (khoa – ngành) → các ngành văn, sử, triết…; đối lập với 理科 (khối tự nhiên).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"她选了文科。","pinyin":"Tā xuǎnle wénkē.","vi":"Cô ấy chọn khối xã hội."},{"type":"simple","zh":"他是文科生，最喜欢历史和地理。","pinyin":"Tā shì wénkē shēng, zuì xǐhuan lìshǐ hé dìlǐ.","vi":"Cậu ấy là học sinh khối xã hội, thích nhất lịch sử và địa lý."},{"type":"compound","zh":"虽然父母希望他学理科，但是他坚持选择了文科。","pinyin":"Suīrán fùmǔ xīwàng tā xué lǐkē, dànshì tā jiānchí xuǎnzéle wénkē.","vi":"Tuy bố mẹ muốn cậu học khối tự nhiên nhưng cậu vẫn kiên quyết chọn khối xã hội."}],"related":[{"hanzi":"理科","pinyin":"lǐkē","vi":"khối tự nhiên"},{"hanzi":"工科","pinyin":"gōngkē","vi":"khối kỹ thuật"},{"hanzi":"专业","pinyin":"zhuānyè","vi":"chuyên ngành"},{"hanzi":"学科","pinyin":"xuékē","vi":"môn học"}]},{"id":"蚊帐","hanzi":"蚊帐","pinyin":"wénzhàng","meaning_vi":"màn, mùng (chống muỗi)","explanation":"蚊 (văn – muỗi) + 帐 (trướng – màn, rèm) → tấm màn che giường để chống muỗi.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🛏️","examples":[{"type":"basic","zh":"睡觉前挂好蚊帐。","pinyin":"Shuìjiào qián guàhǎo wénzhàng.","vi":"Trước khi ngủ hãy mắc màn cẩn thận."},{"type":"simple","zh":"蚊帐破了个洞，蚊子都飞进来了。","pinyin":"Wénzhàng pòle gè dòng, wénzi dōu fēi jìnlái le.","vi":"Màn bị thủng một lỗ, muỗi bay vào hết rồi."},{"type":"compound","zh":"如果晚上不挂蚊帐，就会被蚊子咬得睡不着。","pinyin":"Rúguǒ wǎnshang bú guà wénzhàng, jiù huì bèi wénzi yǎo de shuìbuzháo.","vi":"Nếu buổi tối không mắc màn thì sẽ bị muỗi đốt không ngủ được."}],"related":[{"hanzi":"蚊子","pinyin":"wénzi","vi":"con muỗi"},{"hanzi":"蚊香","pinyin":"wénxiāng","vi":"hương muỗi"},{"hanzi":"床单","pinyin":"chuángdān","vi":"ga trải giường"},{"hanzi":"窗帘","pinyin":"chuānglián","vi":"rèm cửa"}],"traditional":"蚊帳"},{"id":"蚊子","hanzi":"蚊子","pinyin":"wénzi","meaning_vi":"con muỗi","explanation":"蚊 (văn – muỗi) + 子 (hậu tố) → con muỗi.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦟","examples":[{"type":"basic","zh":"屋里有只蚊子。","pinyin":"Wū li yǒu zhī wénzi.","vi":"Trong phòng có một con muỗi."},{"type":"simple","zh":"夏天的晚上，河边的蚊子特别多。","pinyin":"Xiàtiān de wǎnshang, hébiān de wénzi tèbié duō.","vi":"Buổi tối mùa hè, bên bờ sông muỗi đặc biệt nhiều."},{"type":"compound","zh":"因为蚊子会传播疾病，所以要及时清理家里的积水。","pinyin":"Yīnwèi wénzi huì chuánbō jíbìng, suǒyǐ yào jíshí qīnglǐ jiāli de jīshuǐ.","vi":"Vì muỗi có thể truyền bệnh nên phải kịp thời dọn sạch nước đọng trong nhà."}],"related":[{"hanzi":"苍蝇","pinyin":"cāngying","vi":"con ruồi"},{"hanzi":"蚊帐","pinyin":"wénzhàng","vi":"màn chống muỗi"},{"hanzi":"蚊香","pinyin":"wénxiāng","vi":"hương muỗi"},{"hanzi":"叮","pinyin":"dīng","vi":"đốt, chích"}]},{"id":"吻合","hanzi":"吻合","pinyin":"wěnhé","meaning_vi":"khớp, trùng khớp, ăn khớp","explanation":"吻 (vẫn – môi) + 合 (hợp – khớp lại) → hai môi khép khít; nghĩa bóng là hoàn toàn khớp nhau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧩","examples":[{"type":"basic","zh":"两个指纹完全吻合。","pinyin":"Liǎng gè zhǐwén wánquán wěnhé.","vi":"Hai dấu vân tay hoàn toàn trùng khớp."},{"type":"simple","zh":"他说的情况与事实并不吻合。","pinyin":"Tā shuō de qíngkuàng yǔ shìshí bìngbù wěnhé.","vi":"Tình hình anh ta nói không khớp với sự thật."},{"type":"compound","zh":"如果实验结果和理论吻合，就说明我们的假设是对的。","pinyin":"Rúguǒ shíyàn jiéguǒ hé lǐlùn wěnhé, jiù shuōmíng wǒmen de jiǎshè shì duì de.","vi":"Nếu kết quả thí nghiệm khớp với lý thuyết thì chứng tỏ giả thuyết của chúng ta là đúng."}],"related":[{"hanzi":"符合","pinyin":"fúhé","vi":"phù hợp"},{"hanzi":"一致","pinyin":"yízhì","vi":"nhất trí"},{"hanzi":"相符","pinyin":"xiāngfú","vi":"tương xứng"},{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"}]},{"id":"紊乱","hanzi":"紊乱","pinyin":"wěnluàn","meaning_vi":"rối loạn, hỗn loạn","explanation":"紊 (vấn – rối) + 乱 (loạn) → rối loạn, mất trật tự; hay dùng cho cơ thể (内分泌紊乱) hoặc trật tự.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🌀","examples":[{"type":"basic","zh":"他的作息很紊乱。","pinyin":"Tā de zuòxī hěn wěnluàn.","vi":"Giờ giấc sinh hoạt của anh ấy rất rối loạn."},{"type":"simple","zh":"长期熬夜会导致内分泌紊乱。","pinyin":"Chángqī áoyè huì dǎozhì nèifēnmì wěnluàn.","vi":"Thức khuya lâu ngày sẽ gây rối loạn nội tiết."},{"type":"compound","zh":"因为系统出现故障，所以交通信号一度紊乱。","pinyin":"Yīnwèi xìtǒng chūxiàn gùzhàng, suǒyǐ jiāotōng xìnhào yídù wěnluàn.","vi":"Vì hệ thống gặp sự cố nên đèn tín hiệu giao thông có lúc bị rối loạn."}],"related":[{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"},{"hanzi":"失调","pinyin":"shītiáo","vi":"mất cân bằng"},{"hanzi":"有序","pinyin":"yǒuxù","vi":"có trật tự"},{"hanzi":"杂乱","pinyin":"záluàn","vi":"lộn xộn"}],"traditional":"紊亂"},{"id":"问卷","hanzi":"问卷","pinyin":"wènjuàn","meaning_vi":"bảng câu hỏi, phiếu khảo sát","explanation":"问 (vấn – hỏi) + 卷 (quyển – tờ, phiếu) → tờ phiếu gồm các câu hỏi để điều tra.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"请填一下问卷。","pinyin":"Qǐng tián yíxià wènjuàn.","vi":"Xin hãy điền phiếu khảo sát."},{"type":"simple","zh":"我们一共收回了五百份调查问卷。","pinyin":"Wǒmen yígòng shōuhuíle wǔ bǎi fèn diàochá wènjuàn.","vi":"Chúng tôi thu về tổng cộng năm trăm phiếu khảo sát."},{"type":"compound","zh":"如果问卷的问题太多，就很少有人愿意认真填写。","pinyin":"Rúguǒ wènjuàn de wèntí tài duō, jiù hěn shǎoyǒu rén yuànyì rènzhēn tiánxiě.","vi":"Nếu phiếu có quá nhiều câu hỏi thì ít ai chịu điền nghiêm túc."}],"related":[{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"填写","pinyin":"tiánxiě","vi":"điền"},{"hanzi":"试卷","pinyin":"shìjuàn","vi":"đề thi"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"}],"traditional":"問卷"},{"id":"卧","hanzi":"卧","pinyin":"wò","meaning_vi":"nằm; (chỗ) nằm ngủ","explanation":"卧 (ngọa – nằm) → nằm xuống; cũng dùng cho động vật nằm phục, và trong 卧室 (phòng ngủ), 卧铺 (giường nằm).","hsk_level":"7-9","tags":["dong-tu"],"image":"🛌","examples":[{"type":"basic","zh":"小狗卧在门口。","pinyin":"Xiǎogǒu wò zài ménkǒu.","vi":"Chú chó nhỏ nằm ở cửa."},{"type":"simple","zh":"医生让他卧床休息一个星期。","pinyin":"Yīshēng ràng tā wòchuáng xiūxi yí gè xīngqī.","vi":"Bác sĩ bảo anh ấy nằm nghỉ trên giường một tuần."},{"type":"compound","zh":"虽然他病得很重，卧在床上，但是仍然坚持看文件。","pinyin":"Suīrán tā bìng de hěn zhòng, wò zài chuáng shang, dànshì réngrán jiānchí kàn wénjiàn.","vi":"Tuy ốm nặng phải nằm trên giường, nhưng ông vẫn cố xem tài liệu."}],"related":[{"hanzi":"躺","pinyin":"tǎng","vi":"nằm"},{"hanzi":"卧室","pinyin":"wòshì","vi":"phòng ngủ"},{"hanzi":"卧铺","pinyin":"wòpù","vi":"giường nằm (tàu)"},{"hanzi":"趴","pinyin":"pā","vi":"nằm sấp"}],"traditional":"臥"},{"id":"污秽","hanzi":"污秽","pinyin":"wūhuì","meaning_vi":"bẩn thỉu, ô uế; đồ dơ bẩn","explanation":"污 (ô – bẩn) + 秽 (uế – dơ dáy) → bẩn thỉu, ô uế; cũng chỉ thứ dơ bẩn (về vật chất hay tinh thần).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"地上满是污秽。","pinyin":"Dìshang mǎnshì wūhuì.","vi":"Dưới đất đầy những thứ dơ bẩn."},{"type":"simple","zh":"他用清水冲掉了墙上的污秽。","pinyin":"Tāyòng qīngshuǐ chōngdiàole qiáng shang de wūhuì.","vi":"Anh ấy dùng nước sạch rửa trôi vết bẩn trên tường."},{"type":"compound","zh":"虽然这条河曾经很污秽，但是经过治理已经变清了。","pinyin":"Suīrán zhè tiáo hé céngjīng hěn wūhuì, dànshì jīngguò zhìlǐ yǐjīng biàn qīng le.","vi":"Tuy con sông này từng rất bẩn nhưng sau khi xử lý đã trở nên trong."}],"related":[{"hanzi":"肮脏","pinyin":"āngzāng","vi":"bẩn thỉu"},{"hanzi":"污垢","pinyin":"wūgòu","vi":"cáu bẩn"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"ô nhiễm"},{"hanzi":"干净","pinyin":"gānjìng","vi":"sạch sẽ"}],"traditional":"污穢"},{"id":"呜咽","hanzi":"呜咽","pinyin":"wūyè","meaning_vi":"nức nở, thút thít","explanation":"呜 (ô – tiếng khóc) + 咽 (yết – nghẹn) → khóc nghẹn ngào; cũng tả tiếng gió, nước réo rỉ thê lương.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😢","examples":[{"type":"basic","zh":"她低声呜咽着。","pinyin":"Tā dīshēng wūyè zhe.","vi":"Cô ấy khẽ khóc nức nở."},{"type":"simple","zh":"听到这个消息，老人忍不住呜咽起来。","pinyin":"Tīngdào zhè ge xiāoxi, lǎorén rěnbuzhù wūyè qǐlái.","vi":"Nghe tin này, ông cụ không kìm được mà nức nở."},{"type":"compound","zh":"虽然她努力忍住眼泪，但是还是发出了呜咽声。","pinyin":"Suīrán tā nǔlì rěn zhù yǎnlèi, dànshì háishi fāchūle wūyè shēng.","vi":"Tuy cô cố kìm nước mắt nhưng vẫn bật ra tiếng thút thít."}],"related":[{"hanzi":"哭泣","pinyin":"kūqì","vi":"khóc"},{"hanzi":"抽泣","pinyin":"chōuqì","vi":"thút thít"},{"hanzi":"哽咽","pinyin":"gěngyè","vi":"nghẹn ngào"},{"hanzi":"痛哭","pinyin":"tòngkū","vi":"khóc nức nở"}],"traditional":"嗚咽"},{"id":"巫婆","hanzi":"巫婆","pinyin":"wūpó","meaning_vi":"mụ phù thủy, bà đồng","explanation":"巫 (vu – thầy pháp, phù thủy) + 婆 (bà – bà già) → bà đồng, mụ phù thủy.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧙‍♀️","examples":[{"type":"basic","zh":"童话里有个巫婆。","pinyin":"Tónghuà li yǒu gè wūpó.","vi":"Trong truyện cổ tích có một mụ phù thủy."},{"type":"simple","zh":"那个巫婆把王子变成了一只青蛙。","pinyin":"Nà ge wūpó bǎ wángzǐ biàn chéngle yì zhī qīngwā.","vi":"Mụ phù thủy đó biến hoàng tử thành một con ếch."},{"type":"compound","zh":"虽然故事里的巫婆很可怕，但是孩子们还是爱听。","pinyin":"Suīrán gùshi li de wūpó hěn kěpà, dànshì háizimen háishi ài tīng.","vi":"Tuy mụ phù thủy trong truyện rất đáng sợ nhưng bọn trẻ vẫn thích nghe."}],"related":[{"hanzi":"巫师","pinyin":"wūshī","vi":"thầy phù thủy"},{"hanzi":"魔法","pinyin":"mófǎ","vi":"phép thuật"},{"hanzi":"女巫","pinyin":"nǚwū","vi":"nữ phù thủy"},{"hanzi":"童话","pinyin":"tónghuà","vi":"truyện cổ tích"}]},{"id":"屋顶","hanzi":"屋顶","pinyin":"wūdǐng","meaning_vi":"mái nhà, nóc nhà","explanation":"屋 (ốc – nhà) + 顶 (đỉnh – chóp) → phần trên cùng của ngôi nhà, mái nhà.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"猫跳上了屋顶。","pinyin":"Māo tiào shàngle wūdǐng.","vi":"Con mèo nhảy lên mái nhà."},{"type":"simple","zh":"大雨过后，屋顶开始漏水了。","pinyin":"Dàyǔ guòhòu, wūdǐng kāishǐ lòushuǐ le.","vi":"Sau trận mưa lớn, mái nhà bắt đầu dột."},{"type":"compound","zh":"如果在屋顶装上太阳能板，就能节省不少电费。","pinyin":"Rúguǒ zài wūdǐng zhuāng shàng tàiyángnéng bǎn, jiù néng jiéshěng bùshǎo diànfèi.","vi":"Nếu lắp tấm pin mặt trời trên mái nhà thì có thể tiết kiệm khá nhiều tiền điện."}],"related":[{"hanzi":"房顶","pinyin":"fángdǐng","vi":"nóc nhà"},{"hanzi":"屋檐","pinyin":"wūyán","vi":"mái hiên"},{"hanzi":"天花板","pinyin":"tiānhuābǎn","vi":"trần nhà"},{"hanzi":"瓦","pinyin":"wǎ","vi":"ngói"}],"traditional":"屋頂"},{"id":"无不","hanzi":"无不","pinyin":"wúbù","meaning_vi":"không ai không, không gì không, đều","explanation":"无 (vô – không có) + 不 (bất – không) → phủ định kép = khẳng định mạnh: tất cả đều.","hsk_level":"7-9","tags":["pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"观众无不感动。","pinyin":"Guānzhòng wúbù gǎndòng.","vi":"Khán giả ai nấy đều xúc động."},{"type":"simple","zh":"看过这部电影的人无不称赞。","pinyin":"Kànguò zhè bù diànyǐng de rén wúbù chēngzàn.","vi":"Người đã xem bộ phim này không ai không khen ngợi."},{"type":"compound","zh":"虽然比赛输了，但是大家无不佩服他的勇气。","pinyin":"Suīrán bǐsài shū le, dànshì dàjiā wúbú pèifú tā de yǒngqì.","vi":"Tuy thua trận nhưng ai nấy đều khâm phục lòng dũng cảm của anh ấy."}],"related":[{"hanzi":"都","pinyin":"dōu","vi":"đều"},{"hanzi":"无一不","pinyin":"wúyíbù","vi":"không một ai không"},{"hanzi":"莫不","pinyin":"mòbù","vi":"không ai không"},{"hanzi":"全部","pinyin":"quánbù","vi":"toàn bộ"}],"traditional":"無不"},{"id":"无敌","hanzi":"无敌","pinyin":"wúdí","meaning_vi":"vô địch, không có đối thủ","explanation":"无 (vô – không) + 敌 (địch – đối thủ) → không có đối thủ nào sánh được; khẩu ngữ cũng dùng để khen 'đỉnh nhất' (无敌了).","hsk_level":"7-9","tags":["tinh-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"这支球队真是无敌。","pinyin":"Zhè zhī qiúduì zhēn shì wúdí.","vi":"Đội bóng này đúng là vô địch."},{"type":"simple","zh":"他在围棋界保持了十年无敌的纪录。","pinyin":"Tā zài wéiqí jiè bǎochíle shí nián wúdí de jìlù.","vi":"Ông ấy giữ kỷ lục bất bại mười năm trong làng cờ vây."},{"type":"compound","zh":"虽然这位拳王号称天下无敌，但是最后还是输给了新人。","pinyin":"Suīrán zhè wèi quánwáng hàochēng tiānxià wúdí, dànshì zuìhòu háishi shūgěile xīnrén.","vi":"Tuy võ sĩ quyền Anh này tự xưng thiên hạ vô địch nhưng cuối cùng vẫn thua một người mới."}],"related":[{"hanzi":"天下无敌","pinyin":"tiānxiàwúdí","vi":"thiên hạ vô địch"},{"hanzi":"敌人","pinyin":"dírén","vi":"kẻ địch"},{"hanzi":"冠军","pinyin":"guànjūn","vi":"quán quân"},{"hanzi":"对手","pinyin":"duìshǒu","vi":"đối thủ"}],"traditional":"無敵"},{"id":"无恶不作","hanzi":"无恶不作","pinyin":"wú'è-búzuò","meaning_vi":"không việc ác nào không làm, tội ác tày trời","explanation":"Nghĩa đen: không có điều ác nào mà không làm → chỉ kẻ cực kỳ độc ác, gây đủ mọi tội lỗi.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😈","examples":[{"type":"basic","zh":"这伙人无恶不作。","pinyin":"Zhè huǒ rén wú'èbúzuò.","vi":"Bọn người này không việc ác nào không làm."},{"type":"simple","zh":"那个恶霸在村里无恶不作，大家都怕他。","pinyin":"Nà ge èbà zài cūnli wú'èbúzuò, dàjiā dōu pà tā.","vi":"Tên ác bá đó làm đủ điều ác trong làng, ai cũng sợ hắn."},{"type":"compound","zh":"虽然这个团伙无恶不作，但是最终还是被警方抓获了。","pinyin":"Suīrán zhè ge tuánhuǒ wú'èbúzuò, dànshì zuìzhōng háishi bèi jǐngfāng zhuāhuò le.","vi":"Tuy băng nhóm này làm đủ mọi điều ác nhưng cuối cùng vẫn bị cảnh sát bắt."}],"related":[{"hanzi":"作恶多端","pinyin":"zuò'èduōduān","vi":"gây ác vô số"},{"hanzi":"罪大恶极","pinyin":"zuìdà'èjí","vi":"tội ác tày trời"},{"hanzi":"恶贯满盈","pinyin":"èguànmǎnyíng","vi":"tội ác chồng chất"},{"hanzi":"助人为乐","pinyin":"zhùrénwéilè","vi":"vui khi giúp người"}],"traditional":"無惡不作"},{"id":"无关紧要","hanzi":"无关紧要","pinyin":"wúguān-jǐnyào","meaning_vi":"không quan trọng, chẳng đáng kể","explanation":"无关 (vô quan – không liên quan) + 紧要 (khẩn yếu – hệ trọng) → không liên quan đến điều hệ trọng, không đáng bận tâm.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"这些都无关紧要。","pinyin":"Zhèxiē dōu wúguānjǐnyào.","vi":"Những thứ này đều không quan trọng."},{"type":"simple","zh":"别为了无关紧要的小事跟他吵架。","pinyin":"Bié wèile wúguānjǐnyào de xiǎoshì gēn tā chǎojià.","vi":"Đừng vì chuyện nhỏ không đáng kể mà cãi nhau với anh ấy."},{"type":"compound","zh":"虽然这个错误看起来无关紧要，但是可能影响整个结果。","pinyin":"Suīrán zhè ge cuòwù kànqǐlái wúguānjǐnyào, dànshì kěnéng yǐngxiǎng zhěnggè jiéguǒ.","vi":"Tuy lỗi này trông có vẻ không quan trọng nhưng có thể ảnh hưởng đến toàn bộ kết quả."}],"related":[{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"nhỏ nhặt không đáng kể"},{"hanzi":"无足轻重","pinyin":"wúzúqīngzhòng","vi":"không đáng kể"},{"hanzi":"至关重要","pinyin":"zhìguānzhòngyào","vi":"cực kỳ quan trọng"},{"hanzi":"要紧","pinyin":"yàojǐn","vi":"quan trọng"}],"traditional":"無關緊要"},{"id":"无话可说","hanzi":"无话可说","pinyin":"wúhuà-kěshuō","meaning_vi":"không còn gì để nói","explanation":"Nghĩa đen: không có lời nào để nói → cạn lời, không biết nói gì (vì bất lực, phục, hoặc giận).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤐","examples":[{"type":"basic","zh":"我真是无话可说。","pinyin":"Wǒ zhēn shì wúhuàkěshuō.","vi":"Tôi thật sự hết lời để nói."},{"type":"simple","zh":"面对确凿的证据，他终于无话可说了。","pinyin":"Miànduì quèzáo de zhèngjù, tā zhōngyú wúhuàkěshuō le.","vi":"Trước chứng cứ rõ ràng, cuối cùng hắn không còn gì để nói."},{"type":"compound","zh":"既然你已经决定了，那我也无话可说。","pinyin":"Jìrán nǐ yǐjīng juédìng le, nà wǒ yě wúhuàkěshuō.","vi":"Bạn đã quyết định rồi thì tôi cũng không còn gì để nói."}],"related":[{"hanzi":"哑口无言","pinyin":"yǎkǒuwúyán","vi":"câm như hến"},{"hanzi":"无言以对","pinyin":"wúyányǐduì","vi":"không lời đáp lại"},{"hanzi":"沉默","pinyin":"chénmò","vi":"im lặng"},{"hanzi":"滔滔不绝","pinyin":"tāotāobùjué","vi":"nói thao thao bất tuyệt"}],"traditional":"無話可說"},{"id":"无济于事","hanzi":"无济于事","pinyin":"wújì-yúshì","meaning_vi":"chẳng ích gì, không giải quyết được gì","explanation":"无 (vô – không) + 济 (tế – giúp ích) + 于事 (với việc) → không giúp ích gì cho sự việc.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🚫","examples":[{"type":"basic","zh":"后悔也无济于事。","pinyin":"Hòuhuǐ yě wújìyúshì.","vi":"Hối hận cũng chẳng ích gì."},{"type":"simple","zh":"光着急是无济于事的，得想办法。","pinyin":"Guāng zháojí shì wújìyúshì de, děi xiǎngbànfǎ.","vi":"Chỉ sốt ruột thì chẳng ích gì, phải nghĩ cách."},{"type":"compound","zh":"即使你现在哭得再伤心，也无济于事了。","pinyin":"Jíshǐ nǐ xiànzài kū de zài shāngxīn, yě wújìyúshì le.","vi":"Dù bây giờ bạn có khóc đau lòng đến mấy thì cũng chẳng ích gì nữa."}],"related":[{"hanzi":"徒劳","pinyin":"túláo","vi":"uổng công"},{"hanzi":"白费","pinyin":"báifèi","vi":"phí công"},{"hanzi":"于事无补","pinyin":"yúshìwúbǔ","vi":"chẳng bổ ích gì"},{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu quả"}],"traditional":"無濟於事"},{"id":"无家可归","hanzi":"无家可归","pinyin":"wújiā-kěguī","meaning_vi":"không nhà để về, vô gia cư","explanation":"Nghĩa đen: không có nhà để quay về → mất nhà cửa, lang thang, vô gia cư.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🏚️","examples":[{"type":"basic","zh":"地震让许多人无家可归。","pinyin":"Dìzhèn ràng xǔduō rén wújiākěguī.","vi":"Động đất khiến nhiều người mất nhà cửa."},{"type":"simple","zh":"冬天，志愿者给无家可归的人送去棉被。","pinyin":"Dōngtiān, zhìyuànzhě gěi wújiākěguī de rén sòngqù miánbèi.","vi":"Mùa đông, tình nguyện viên mang chăn bông đến cho người vô gia cư."},{"type":"compound","zh":"因为洪水冲毁了房子，所以上千人无家可归。","pinyin":"Yīnwèi hóngshuǐ chōng huǐle fángzi, suǒyǐ shàng qiān rén wújiākěguī.","vi":"Vì lũ lụt cuốn trôi nhà cửa nên hàng nghìn người không có nhà để về."}],"related":[{"hanzi":"流浪","pinyin":"liúlàng","vi":"lang thang"},{"hanzi":"露宿街头","pinyin":"lùsùjiētóu","vi":"ngủ ngoài đường"},{"hanzi":"颠沛流离","pinyin":"diānpèiliúlí","vi":"trôi dạt khắp nơi"},{"hanzi":"安居乐业","pinyin":"ānjūlèyè","vi":"an cư lạc nghiệp"}],"traditional":"無家可歸"},{"id":"无理","hanzi":"无理","pinyin":"wúlǐ","meaning_vi":"vô lý, ngang ngược","explanation":"无 (vô – không) + 理 (lý – lẽ phải) → không có lý lẽ, ngang ngược; hay gặp 无理要求, 无理取闹.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😤","examples":[{"type":"basic","zh":"这是无理要求。","pinyin":"Zhè shì wúlǐ yāoqiú.","vi":"Đây là yêu cầu vô lý."},{"type":"simple","zh":"顾客的态度十分无理，服务员都很生气。","pinyin":"Gùkè de tàidù shífēn wúlǐ, fúwùyuán dōu hěn shēngqì.","vi":"Thái độ của khách hàng hết sức ngang ngược, nhân viên phục vụ ai cũng tức giận."},{"type":"compound","zh":"虽然对方的要求很无理，但是我们还是要冷静处理。","pinyin":"Suīrán duìfāng de yāoqiú hěn wúlǐ, dànshì wǒmen háishi yào lěngjìng chǔlǐ.","vi":"Tuy yêu cầu của đối phương rất vô lý nhưng chúng ta vẫn phải xử lý bình tĩnh."}],"related":[{"hanzi":"无理取闹","pinyin":"wúlǐqǔnào","vi":"gây sự vô cớ"},{"hanzi":"蛮横","pinyin":"mánhèng","vi":"ngang ngược"},{"hanzi":"合理","pinyin":"hélǐ","vi":"hợp lý"},{"hanzi":"讲理","pinyin":"jiǎnglǐ","vi":"biết lý lẽ"}],"traditional":"無理"},{"id":"无力","hanzi":"无力","pinyin":"wúlì","meaning_vi":"không có sức, bất lực, yếu ớt","explanation":"无 (vô – không) + 力 (lực – sức) → không có sức lực; nghĩa bóng là không có khả năng làm gì (无力偿还).","hsk_level":"7-9","tags":["tinh-tu"],"image":"😩","examples":[{"type":"basic","zh":"我浑身无力。","pinyin":"Wǒ húnshēn wúlì.","vi":"Tôi toàn thân rã rời."},{"type":"simple","zh":"发烧以后，他感到四肢无力。","pinyin":"Fāshāo yǐhòu, tā gǎndào sìzhī wúlì.","vi":"Sau khi sốt, anh ấy thấy tay chân bủn rủn."},{"type":"compound","zh":"因为公司经营失败，所以他已经无力偿还贷款了。","pinyin":"Yīnwèi gōngsī jīngyíng shībài, suǒyǐ tā yǐjīng wúlì chánghuán dàikuǎn le.","vi":"Vì công ty làm ăn thất bại nên anh ấy đã không còn khả năng trả khoản vay."}],"related":[{"hanzi":"乏力","pinyin":"fálì","vi":"mệt mỏi"},{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"},{"hanzi":"有力","pinyin":"yǒulì","vi":"mạnh mẽ"},{"hanzi":"虚弱","pinyin":"xūruò","vi":"suy nhược"}],"traditional":"無力"},{"id":"无论如何","hanzi":"无论如何","pinyin":"wúlùnrúhé","meaning_vi":"dù thế nào đi nữa, bằng mọi giá","explanation":"无论 (vô luận – bất kể) + 如何 (như hà – thế nào) → bất kể thế nào, trong mọi trường hợp.","hsk_level":"7-9","tags":["pho-tu"],"image":"💪","examples":[{"type":"basic","zh":"你无论如何要来。","pinyin":"Nǐ wúlùnrúhé yào lái.","vi":"Dù thế nào bạn cũng phải đến."},{"type":"simple","zh":"这件事无论如何不能告诉妈妈。","pinyin":"Zhè jiàn shì wúlùnrúhé bù néng gàosu māma.","vi":"Chuyện này dù thế nào cũng không được nói với mẹ."},{"type":"compound","zh":"即使困难再多，我们也无论如何要按时完成任务。","pinyin":"Jíshǐ kùnnan zài duō, wǒmen yě wúlùnrúhé yào ànshí wánchéng rènwu.","vi":"Dù khó khăn nhiều đến đâu, chúng ta cũng phải bằng mọi giá hoàn thành nhiệm vụ đúng hạn."}],"related":[{"hanzi":"不管怎样","pinyin":"bùguǎnzěnyàng","vi":"dù sao đi nữa"},{"hanzi":"反正","pinyin":"fǎnzhèng","vi":"dù sao"},{"hanzi":"务必","pinyin":"wùbì","vi":"nhất định phải"},{"hanzi":"无论","pinyin":"wúlùn","vi":"bất kể"}],"traditional":"無論如何"},{"id":"无能","hanzi":"无能","pinyin":"wúnéng","meaning_vi":"bất tài, vô dụng, kém cỏi","explanation":"无 (vô – không) + 能 (năng – năng lực) → không có năng lực, bất tài.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😞","examples":[{"type":"basic","zh":"他觉得自己很无能。","pinyin":"Tā juéde zìjǐ hěn wúnéng.","vi":"Anh ấy cảm thấy mình thật vô dụng."},{"type":"simple","zh":"人们纷纷批评政府的无能。","pinyin":"Rénmen fēnfēn pīpíng zhèngfǔ de wúnéng.","vi":"Mọi người dồn dập chỉ trích sự bất lực của chính quyền."},{"type":"compound","zh":"虽然他看起来很无能，但是关键时刻却帮了大忙。","pinyin":"Suīrán tā kànqǐlái hěn wúnéng, dànshì guānjiànshíkè què bāngle dà máng.","vi":"Tuy trông anh ta có vẻ bất tài nhưng vào lúc then chốt lại giúp được việc lớn."}],"related":[{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"},{"hanzi":"能干","pinyin":"nénggàn","vi":"giỏi giang"},{"hanzi":"无用","pinyin":"wúyòng","vi":"vô dụng"},{"hanzi":"能力","pinyin":"nénglì","vi":"năng lực"}],"traditional":"無能"},{"id":"无情","hanzi":"无情","pinyin":"wúqíng","meaning_vi":"vô tình, nhẫn tâm, tàn nhẫn","explanation":"无 (vô – không) + 情 (tình – tình cảm) → không có tình cảm, lạnh lùng tàn nhẫn; cũng dùng cho thời gian, thiên tai.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🥶","examples":[{"type":"basic","zh":"岁月真是无情。","pinyin":"Suìyuè zhēn shì wúqíng.","vi":"Năm tháng thật vô tình."},{"type":"simple","zh":"一场无情的大火烧毁了整条街。","pinyin":"Yì chǎng wúqíng de dàhuǒ shāohuǐle zhěngtiáo jiē.","vi":"Một trận hỏa hoạn tàn khốc đã thiêu rụi cả con phố."},{"type":"compound","zh":"虽然他说话很无情，但是其实是为了让你清醒。","pinyin":"Suīrán tā shuōhuà hěn wúqíng, dànshì qíshí shì wèile ràng nǐ qīngxǐng.","vi":"Tuy anh ấy nói chuyện rất phũ phàng, nhưng thật ra là để bạn tỉnh ngộ."}],"related":[{"hanzi":"冷酷","pinyin":"lěngkù","vi":"lạnh lùng tàn nhẫn"},{"hanzi":"残酷","pinyin":"cánkù","vi":"tàn khốc"},{"hanzi":"多情","pinyin":"duōqíng","vi":"đa tình"},{"hanzi":"无情无义","pinyin":"wúqíngwúyì","vi":"bạc tình bạc nghĩa"}],"traditional":"無情"},{"id":"无情无义","hanzi":"无情无义","pinyin":"wúqíng-wúyì","meaning_vi":"bạc tình bạc nghĩa, vô tình vô nghĩa","explanation":"无情 (vô tình) + 无义 (vô nghĩa – không có đạo nghĩa) → không có tình cảm cũng chẳng có nghĩa khí, lạnh lùng phụ bạc.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💔","examples":[{"type":"basic","zh":"他真是无情无义。","pinyin":"Tā zhēn shì wúqíngwúyì.","vi":"Hắn đúng là bạc tình bạc nghĩa."},{"type":"simple","zh":"朋友有难他却躲开，真是无情无义。","pinyin":"Péngyou yǒu nàn tā què duǒkāi, zhēn shì wúqíngwúyì.","vi":"Bạn gặp nạn mà hắn lại lánh đi, thật bạc tình bạc nghĩa."},{"type":"compound","zh":"虽然大家都说他无情无义，但是他其实有自己的苦衷。","pinyin":"Suīrán dàjiā dōu shuō tā wúqíngwúyì, dànshì tā qíshí yǒu zìjǐ de kǔzhōng.","vi":"Tuy mọi người đều nói anh ta bạc tình bạc nghĩa nhưng thật ra anh có nỗi khổ riêng."}],"related":[{"hanzi":"忘恩负义","pinyin":"wàng'ēnfùyì","vi":"vong ân bội nghĩa"},{"hanzi":"无情","pinyin":"wúqíng","vi":"vô tình"},{"hanzi":"有情有义","pinyin":"yǒuqíngyǒuyì","vi":"có tình có nghĩa"},{"hanzi":"冷酷无情","pinyin":"lěngkùwúqíng","vi":"lạnh lùng tàn nhẫn"}],"traditional":"無情無義"},{"id":"无私","hanzi":"无私","pinyin":"wúsī","meaning_vi":"vô tư, không vụ lợi, quên mình","explanation":"无 (vô – không) + 私 (tư – riêng tư) → không vì lợi ích riêng, sẵn lòng hy sinh cho người khác.","hsk_level":"7-9","tags":["tinh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"母爱是无私的。","pinyin":"Mǔ'ài shì wúsī de.","vi":"Tình mẹ là vô tư không vụ lợi."},{"type":"simple","zh":"感谢志愿者们的无私奉献。","pinyin":"Gǎnxiè zhìyuànzhěmen de wúsīfèngxiàn.","vi":"Cảm ơn sự cống hiến quên mình của các tình nguyện viên."},{"type":"compound","zh":"虽然他的收入不高，但是一直无私地资助贫困学生。","pinyin":"Suīrán tā de shōurù bù gāo, dànshì yìzhí wúsī de zīzhù pínkùn xuésheng.","vi":"Tuy thu nhập không cao nhưng ông luôn tận tâm tài trợ cho học sinh nghèo."}],"related":[{"hanzi":"自私","pinyin":"zìsī","vi":"ích kỷ"},{"hanzi":"奉献","pinyin":"fèngxiàn","vi":"cống hiến"},{"hanzi":"公正无私","pinyin":"gōngzhèngwúsī","vi":"công bằng vô tư"},{"hanzi":"大公无私","pinyin":"dàgōngwúsī","vi":"chí công vô tư"}],"traditional":"無私"},{"id":"无所作为","hanzi":"无所作为","pinyin":"wúsuǒ-zuòwéi","meaning_vi":"không làm được gì, chẳng có thành tựu gì","explanation":"无所 (không có gì) + 作为 (tác vi – làm nên) → không làm nên trò trống gì, thụ động, không có chí tiến thủ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🛋️","examples":[{"type":"basic","zh":"他一生无所作为。","pinyin":"Tā yìshēng wúsuǒzuòwéi.","vi":"Cả đời ông ta chẳng làm nên trò trống gì."},{"type":"simple","zh":"面对危机，政府不能无所作为。","pinyin":"Miànduì wēijī, zhèngfǔ bù néng wúsuǒzuòwéi.","vi":"Trước khủng hoảng, chính phủ không thể khoanh tay đứng nhìn."},{"type":"compound","zh":"如果年轻时只知道玩，就可能一辈子无所作为。","pinyin":"Rúguǒ niánqīng shí zhǐ zhīdào wán, jiù kěnéng yíbèizi wúsuǒzuòwéi.","vi":"Nếu lúc trẻ chỉ biết chơi thì có thể cả đời chẳng làm được gì."}],"related":[{"hanzi":"碌碌无为","pinyin":"lùlùwúwéi","vi":"tầm thường vô vị"},{"hanzi":"有所作为","pinyin":"yǒusuǒzuòwéi","vi":"làm nên chuyện"},{"hanzi":"一事无成","pinyin":"yíshìwúchéng","vi":"không làm nên việc gì"},{"hanzi":"作为","pinyin":"zuòwéi","vi":"hành động, thành tựu"}],"traditional":"無所作為"},{"id":"无线","hanzi":"无线","pinyin":"wúxiàn","meaning_vi":"không dây","explanation":"无 (vô – không) + 线 (tuyến – dây) → không cần dây dẫn; hay gặp 无线网络, 无线耳机.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"📶","examples":[{"type":"basic","zh":"这里有无线网络吗？","pinyin":"Zhèlǐ yǒu wúxiànwǎngluò ma?","vi":"Ở đây có mạng không dây không?"},{"type":"simple","zh":"我买了一副新的无线耳机。","pinyin":"Wǒ mǎile yí fù xīn de wúxiàn ěrjī.","vi":"Tôi mua một chiếc tai nghe không dây mới."},{"type":"compound","zh":"因为用了无线充电器，所以桌上再也没有乱糟糟的电线了。","pinyin":"Yīnwèi yòngle wúxiàn chōngdiànqì, suǒyǐ zhuō shang zài yě méiyǒu luànzāozāo de diànxiàn le.","vi":"Vì dùng bộ sạc không dây nên trên bàn không còn dây điện lộn xộn nữa."}],"related":[{"hanzi":"有线","pinyin":"yǒuxiàn","vi":"có dây"},{"hanzi":"无线电","pinyin":"wúxiàndiàn","vi":"vô tuyến điện"},{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"},{"hanzi":"蓝牙","pinyin":"Lányá","vi":"bluetooth"}],"traditional":"無線"},{"id":"无形中","hanzi":"无形中","pinyin":"wúxíngzhōng","meaning_vi":"vô hình trung, một cách vô thức, dần dần không hay","explanation":"无形 (vô hình – không thấy hình dạng) + 中 (trung – trong) → trong lúc không nhận ra, một cách tự nhiên.","hsk_level":"7-9","tags":["pho-tu"],"image":"👻","examples":[{"type":"basic","zh":"这无形中增加了压力。","pinyin":"Zhè wúxíngzhōng zēngjiāle yālì.","vi":"Điều này vô hình trung làm tăng áp lực."},{"type":"simple","zh":"父母的习惯无形中影响着孩子。","pinyin":"Fùmǔ de xíguàn wúxíngzhōng yǐngxiǎngzhe háizi.","vi":"Thói quen của cha mẹ vô hình trung ảnh hưởng đến con cái."},{"type":"compound","zh":"虽然他没有批评我，但是无形中给了我很大的压力。","pinyin":"Suīrán tā méiyǒu pīpíng wǒ, dànshì wúxíngzhōng gěile wǒ hěn dà de yālì.","vi":"Tuy anh ấy không phê bình tôi nhưng vô hình trung đã tạo cho tôi áp lực rất lớn."}],"related":[{"hanzi":"不知不觉","pinyin":"bùzhībùjué","vi":"bất tri bất giác"},{"hanzi":"潜移默化","pinyin":"qiányímòhuà","vi":"thấm dần dần"},{"hanzi":"无形","pinyin":"wúxíng","vi":"vô hình"},{"hanzi":"悄悄","pinyin":"qiāoqiāo","vi":"lặng lẽ"}],"traditional":"無形中"},{"id":"无须","hanzi":"无须","pinyin":"wúxū","meaning_vi":"không cần, không phải","explanation":"无 (vô – không) + 须 (tu – cần phải) → không cần phải; dùng trong văn viết, đứng trước động từ.","hsk_level":"7-9","tags":["pho-tu"],"image":"🙅","examples":[{"type":"basic","zh":"你无须担心。","pinyin":"Nǐ wúxū dānxīn.","vi":"Bạn không cần lo lắng."},{"type":"simple","zh":"这次活动免费参加，无须报名。","pinyin":"Zhè cì huódòng miǎnfèi cānjiā, wúxū bàomíng.","vi":"Hoạt động lần này tham gia miễn phí, không cần đăng ký."},{"type":"compound","zh":"既然事情已经解决了，你就无须再道歉了。","pinyin":"Jìrán shìqing yǐjīng jiějué le, nǐ jiù wúxū zài dàoqiàn le.","vi":"Chuyện đã giải quyết xong rồi thì bạn không cần xin lỗi nữa."}],"related":[{"hanzi":"不必","pinyin":"búbì","vi":"không cần"},{"hanzi":"无需","pinyin":"wúxū","vi":"không cần"},{"hanzi":"必须","pinyin":"bìxū","vi":"phải"},{"hanzi":"不用","pinyin":"búyòng","vi":"không cần"}],"traditional":"無須"},{"id":"无缘","hanzi":"无缘","pinyin":"wúyuán","meaning_vi":"không có duyên, không có cơ hội","explanation":"无 (vô – không) + 缘 (duyên – duyên phận) → không có duyên phận hoặc cơ hội; hay gặp 与…无缘 (lỡ mất, không đạt được).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"他与冠军无缘。","pinyin":"Tā yǔ guànjūn wúyuán.","vi":"Anh ấy không có duyên với chức vô địch."},{"type":"simple","zh":"因为受伤，他与这届奥运会无缘了。","pinyin":"Yīnwèi shòushāng, tā yǔ zhè jiè Àoyùnhuì wúyuán le.","vi":"Vì chấn thương, anh ấy lỡ mất kỳ Olympic này."},{"type":"compound","zh":"虽然两人很相爱，但是终究无缘走到一起。","pinyin":"Suīrán liǎng rén hěn xiāng'ài, dànshì zhōngjiū wúyuán zǒu dào yìqǐ.","vi":"Tuy hai người rất yêu nhau nhưng rốt cuộc không có duyên đến được với nhau."}],"related":[{"hanzi":"有缘","pinyin":"yǒuyuán","vi":"có duyên"},{"hanzi":"缘分","pinyin":"yuánfèn","vi":"duyên phận"},{"hanzi":"错过","pinyin":"cuòguò","vi":"bỏ lỡ"},{"hanzi":"无缘无故","pinyin":"wúyuánwúgù","vi":"vô duyên vô cớ"}],"traditional":"無緣"},{"id":"五星级","hanzi":"五星级","pinyin":"wǔxīngjí","meaning_vi":"năm sao, hạng năm sao","explanation":"五 (ngũ – năm) + 星 (tinh – sao) + 级 (cấp – hạng) → hạng năm sao, thường nói về khách sạn cao cấp.","hsk_level":"7-9","tags":["tinh-tu","du-lich"],"image":"⭐","examples":[{"type":"basic","zh":"这是五星级酒店。","pinyin":"Zhè shì wǔxīngjí jiǔdiàn.","vi":"Đây là khách sạn năm sao."},{"type":"simple","zh":"他们在一家五星级饭店举行了婚礼。","pinyin":"Tāmen zài yìjiā wǔxīngjí fàndiàn jǔxíngle hūnlǐ.","vi":"Họ tổ chức lễ cưới ở một khách sạn năm sao."},{"type":"compound","zh":"虽然五星级宾馆价格很贵，但是服务确实一流。","pinyin":"Suīrán wǔxīngjí bīnguǎn jiàgé hěn guì, dànshì fúwù quèshí yìliú.","vi":"Tuy khách sạn năm sao giá rất đắt nhưng dịch vụ quả thật hạng nhất."}],"related":[{"hanzi":"星级","pinyin":"xīngjí","vi":"hạng sao"},{"hanzi":"酒店","pinyin":"jiǔdiàn","vi":"khách sạn"},{"hanzi":"豪华","pinyin":"háohuá","vi":"sang trọng"},{"hanzi":"一流","pinyin":"yìliú","vi":"hạng nhất"}],"traditional":"五星級"},{"id":"武力","hanzi":"武力","pinyin":"wǔlì","meaning_vi":"vũ lực, sức mạnh quân sự","explanation":"武 (vũ/võ – quân sự) + 力 (lực – sức) → sức mạnh quân sự, bạo lực.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"⚔️","examples":[{"type":"basic","zh":"不能用武力解决。","pinyin":"Bù néng yòng wǔlì jiějué.","vi":"Không thể giải quyết bằng vũ lực."},{"type":"simple","zh":"双方都表示不会首先使用武力。","pinyin":"Shuāngfāng dōu biǎoshì bú huì shǒuxiān shǐyòng wǔlì.","vi":"Hai bên đều tuyên bố sẽ không sử dụng vũ lực trước."},{"type":"compound","zh":"即使双方矛盾再大，也应该避免诉诸武力。","pinyin":"Jíshǐ shuāngfāng máodùn zài dà, yě yīnggāi bìmiǎn sùzhū wǔlì.","vi":"Dù mâu thuẫn giữa hai bên lớn đến đâu cũng nên tránh dùng đến vũ lực."}],"related":[{"hanzi":"暴力","pinyin":"bàolì","vi":"bạo lực"},{"hanzi":"军事","pinyin":"jūnshì","vi":"quân sự"},{"hanzi":"武器","pinyin":"wǔqì","vi":"vũ khí"},{"hanzi":"和平","pinyin":"hépíng","vi":"hòa bình"}]},{"id":"舞厅","hanzi":"舞厅","pinyin":"wǔtīng","meaning_vi":"vũ trường, phòng khiêu vũ","explanation":"舞 (vũ – múa, nhảy) + 厅 (sảnh – phòng lớn) → phòng lớn để khiêu vũ.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"💃","examples":[{"type":"basic","zh":"他们去舞厅跳舞。","pinyin":"Tāmen qù wǔtīng tiàowǔ.","vi":"Họ đến vũ trường khiêu vũ."},{"type":"simple","zh":"周末的舞厅里挤满了年轻人。","pinyin":"Zhōumò de wǔtīng li jǐmǎnle niánqīngrén.","vi":"Vũ trường cuối tuần chật kín người trẻ."},{"type":"compound","zh":"虽然舞厅里音乐很吵，但是大家都跳得很开心。","pinyin":"Suīrán wǔtīng li yīnyuè hěn chǎo, dànshì dàjiā dōu tiào de hěn kāixīn.","vi":"Tuy nhạc trong vũ trường rất ồn nhưng mọi người đều nhảy rất vui."}],"related":[{"hanzi":"跳舞","pinyin":"tiàowǔ","vi":"khiêu vũ"},{"hanzi":"舞会","pinyin":"wǔhuì","vi":"buổi dạ vũ"},{"hanzi":"酒吧","pinyin":"jiǔbā","vi":"quán bar"},{"hanzi":"大厅","pinyin":"dàtīng","vi":"sảnh lớn"}],"traditional":"舞廳"},{"id":"物体","hanzi":"物体","pinyin":"wùtǐ","meaning_vi":"vật thể","explanation":"物 (vật) + 体 (thể – khối, hình thể) → vật có hình dạng, chiếm chỗ trong không gian.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🧊","examples":[{"type":"basic","zh":"物体都会下落。","pinyin":"Wùtǐ dōuhuì xiàluò.","vi":"Mọi vật thể đều sẽ rơi xuống."},{"type":"simple","zh":"天空中出现了一个不明发光物体。","pinyin":"Tiānkōng zhōng chūxiànle yí gè bùmíng fāguāng wùtǐ.","vi":"Trên bầu trời xuất hiện một vật thể phát sáng không rõ."},{"type":"compound","zh":"如果物体受到的力不平衡，它的运动状态就会改变。","pinyin":"Rúguǒ wùtǐ shòudào de lì bù pínghéng, tā de yùndòng zhuàngtài jiù huì gǎibiàn.","vi":"Nếu lực tác dụng lên vật thể không cân bằng thì trạng thái chuyển động của nó sẽ thay đổi."}],"related":[{"hanzi":"物质","pinyin":"wùzhì","vi":"vật chất"},{"hanzi":"物品","pinyin":"wùpǐn","vi":"đồ vật"},{"hanzi":"固体","pinyin":"gùtǐ","vi":"chất rắn"},{"hanzi":"液体","pinyin":"yètǐ","vi":"chất lỏng"}],"traditional":"物體"},{"id":"物证","hanzi":"物证","pinyin":"wùzhèng","meaning_vi":"vật chứng","explanation":"物 (vật) + 证 (chứng – bằng chứng) → đồ vật dùng làm chứng cứ trong vụ án.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"警方找到了物证。","pinyin":"Jǐngfāng zhǎodàole wùzhèng.","vi":"Cảnh sát đã tìm thấy vật chứng."},{"type":"simple","zh":"这把刀是本案最重要的物证。","pinyin":"Zhè bǎ dāo shì běn àn zuì zhòngyào de wùzhèng.","vi":"Con dao này là vật chứng quan trọng nhất của vụ án."},{"type":"compound","zh":"虽然有证人作证，但是缺少物证，案子还不能结。","pinyin":"Suīrán yǒu zhèngrén zuòzhèng, dànshì quēshǎo wùzhèng, ànzi hái bù néng jié.","vi":"Tuy có nhân chứng làm chứng nhưng thiếu vật chứng nên vụ án chưa thể kết thúc."}],"related":[{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"},{"hanzi":"人证","pinyin":"rénzhèng","vi":"nhân chứng"},{"hanzi":"证人","pinyin":"zhèngrén","vi":"người làm chứng"},{"hanzi":"罪证","pinyin":"zuìzhèng","vi":"tang chứng"}],"traditional":"物證"},{"id":"吸纳","hanzi":"吸纳","pinyin":"xīnà","meaning_vi":"thu hút, tiếp nhận, hấp thụ","explanation":"吸 (hấp – hút) + 纳 (nạp – nhận vào) → hút vào và tiếp nhận (vốn, nhân tài, ý kiến…).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧲","examples":[{"type":"basic","zh":"公司吸纳了新人。","pinyin":"Gōngsī xīnàle xīnrén.","vi":"Công ty đã tiếp nhận người mới."},{"type":"simple","zh":"这座城市每年吸纳大量外来人口。","pinyin":"Zhè zuò chéngshì měinián xīnà dàliàng wàilái rénkǒu.","vi":"Thành phố này mỗi năm tiếp nhận rất nhiều dân nhập cư."},{"type":"compound","zh":"如果能吸纳更多社会资金，项目就能提前完成。","pinyin":"Rúguǒ néng xīnà gèng duō shèhuì zījīn, xiàngmù jiù néng tíqián wánchéng.","vi":"Nếu có thể thu hút thêm vốn xã hội thì dự án sẽ hoàn thành sớm."}],"related":[{"hanzi":"吸收","pinyin":"xīshōu","vi":"hấp thụ"},{"hanzi":"接纳","pinyin":"jiēnà","vi":"tiếp nhận"},{"hanzi":"吸引","pinyin":"xīyǐn","vi":"thu hút"},{"hanzi":"容纳","pinyin":"róngnà","vi":"chứa đựng"}],"traditional":"吸納"},{"id":"稀","hanzi":"稀","pinyin":"xī","meaning_vi":"thưa, thưa thớt; loãng; hiếm","explanation":"稀 (hy – thưa, hiếm) → thưa thớt (稀少), loãng (稀饭), hiếm có (稀有).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥣","examples":[{"type":"basic","zh":"这粥太稀了。","pinyin":"Zhè zhōu tài xī le.","vi":"Cháo này loãng quá."},{"type":"simple","zh":"山顶上空气稀，走几步就喘。","pinyin":"Shāndǐng shangkōng qì xī, zǒu jǐ bù jiù chuǎn.","vi":"Trên đỉnh núi không khí loãng, đi vài bước là thở dốc."},{"type":"compound","zh":"因为粥煮得太稀，所以孩子吃完很快又饿了。","pinyin":"Yīnwèi zhōu zhǔ de tài xī, suǒyǐ háizi chīwán hěn kuài yòu è le.","vi":"Vì cháo nấu loãng quá nên bọn trẻ ăn xong chẳng mấy chốc lại đói."}],"related":[{"hanzi":"稀饭","pinyin":"xīfàn","vi":"cháo loãng"},{"hanzi":"稀少","pinyin":"xīshǎo","vi":"thưa thớt"},{"hanzi":"稠","pinyin":"chóu","vi":"đặc"},{"hanzi":"稀有","pinyin":"xīyǒu","vi":"hiếm có"}]},{"id":"稀奇","hanzi":"稀奇","pinyin":"xīqí","meaning_vi":"hiếm lạ, kỳ lạ","explanation":"稀 (hy – hiếm) + 奇 (kỳ – lạ) → hiếm gặp và lạ lùng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🦄","examples":[{"type":"basic","zh":"这有什么稀奇的？","pinyin":"Zhè yǒu shénme xīqí de?","vi":"Cái này có gì lạ đâu?"},{"type":"simple","zh":"孩子们围着那只稀奇的鸟看个不停。","pinyin":"Háizimen wéizhe nà zhī xīqí de niǎo kàn gè bùtíng.","vi":"Bọn trẻ vây quanh con chim kỳ lạ đó ngắm mãi không thôi."},{"type":"compound","zh":"虽然现在手机支付很普遍，但是二十年前还很稀奇。","pinyin":"Suīrán xiànzài shǒujī zhīfù hěn pǔbiàn, dànshì èrshí niánqián hái hěn xīqí.","vi":"Tuy bây giờ thanh toán bằng điện thoại rất phổ biến nhưng hai mươi năm trước vẫn còn rất hiếm lạ."}],"related":[{"hanzi":"新奇","pinyin":"xīnqí","vi":"mới lạ"},{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ quái"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"平常","pinyin":"píngcháng","vi":"bình thường"}]},{"id":"稀少","hanzi":"稀少","pinyin":"xīshǎo","meaning_vi":"thưa thớt, ít ỏi, hiếm","explanation":"稀 (hy – thưa) + 少 (thiểu – ít) → ít và thưa thớt.","hsk_level":"7-9","tags":["tinh-tu","so-luong"],"image":"🏜️","examples":[{"type":"basic","zh":"这里人口稀少。","pinyin":"Zhèlǐ rénkǒu xīshǎo.","vi":"Ở đây dân cư thưa thớt."},{"type":"simple","zh":"深夜的街道上行人稀少。","pinyin":"Shēnyè de jiēdào shang xíngrén xīshǎo.","vi":"Đêm khuya trên phố người đi lại thưa thớt."},{"type":"compound","zh":"因为沙漠里雨水稀少，所以植物很难生长。","pinyin":"Yīnwèi shāmò li yǔshuǐ xīshǎo, suǒyǐ zhíwù hěn nán shēngzhǎng.","vi":"Vì trong sa mạc mưa rất ít nên cây cối khó sinh trưởng."}],"related":[{"hanzi":"稀疏","pinyin":"xīshū","vi":"thưa thớt"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"稠密","pinyin":"chóumì","vi":"đông đúc"},{"hanzi":"众多","pinyin":"zhòngduō","vi":"đông đảo"}]},{"id":"锡","hanzi":"锡","pinyin":"xī","meaning_vi":"thiếc","explanation":"锡 (tích – thiếc): bộ 钅 (kim loại) → kim loại thiếc, màu trắng bạc, dễ dát mỏng.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🥫","examples":[{"type":"basic","zh":"这是锡做的罐子。","pinyin":"Zhè shì xī zuò de guànzi.","vi":"Đây là cái hộp làm bằng thiếc."},{"type":"simple","zh":"锡的熔点比较低，常用来焊接。","pinyin":"Xī de róngdiǎn bǐjiào dī, cháng yònglái hànjiē.","vi":"Thiếc có nhiệt độ nóng chảy khá thấp, thường dùng để hàn."},{"type":"compound","zh":"虽然锡箔纸很薄，但是能很好地保持食物的温度。","pinyin":"Suīrán xībózhǐ hěn báo, dànshì néng hěn hǎo de bǎochí shíwù de wēndù.","vi":"Tuy giấy bạc thiếc rất mỏng nhưng giữ nhiệt độ thức ăn rất tốt."}],"related":[{"hanzi":"铜","pinyin":"tóng","vi":"đồng"},{"hanzi":"铁","pinyin":"tiě","vi":"sắt"},{"hanzi":"锡箔","pinyin":"xībó","vi":"giấy thiếc"},{"hanzi":"金属","pinyin":"jīnshǔ","vi":"kim loại"}],"traditional":"錫"},{"id":"熙熙攘攘","hanzi":"熙熙攘攘","pinyin":"xīxī-rǎngrǎng","meaning_vi":"tấp nập, nhộn nhịp, người qua kẻ lại","explanation":"熙熙 (vui vẻ, đông đúc) + 攘攘 (hỗn độn, chen chúc) → người đông qua lại tấp nập; xuất phát từ Sử ký: 天下熙熙，皆为利来.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏙️","examples":[{"type":"basic","zh":"街上熙熙攘攘的。","pinyin":"Jiēshang xīxīrǎngrǎng de.","vi":"Trên phố người qua lại tấp nập."},{"type":"simple","zh":"春节前的商场里熙熙攘攘，十分热闹。","pinyin":"Chūnjié qián de shāngchǎng li xīxīrǎngrǎng, shífēn rènao.","vi":"Trung tâm thương mại trước Tết người qua lại tấp nập, vô cùng náo nhiệt."},{"type":"compound","zh":"虽然车站里熙熙攘攘，但是我一眼就认出了妈妈。","pinyin":"Suīrán chēzhàn li xīxīrǎngrǎng, dànshì wǒ yìyǎn jiù rènchūle māma.","vi":"Tuy nhà ga người qua kẻ lại tấp nập nhưng tôi liếc mắt đã nhận ra mẹ."}],"related":[{"hanzi":"人来人往","pinyin":"rénláirénwǎng","vi":"người qua kẻ lại"},{"hanzi":"川流不息","pinyin":"chuānliúbùxī","vi":"nườm nượp không ngớt"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"},{"hanzi":"冷冷清清","pinyin":"lěnglěngqīngqīng","vi":"vắng vẻ quạnh hiu"}]},{"id":"嬉笑","hanzi":"嬉笑","pinyin":"xīxiào","meaning_vi":"cười đùa, vui đùa","explanation":"嬉 (hy – vui chơi) + 笑 (tiếu – cười) → vừa chơi vừa cười đùa.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😆","examples":[{"type":"basic","zh":"孩子们嬉笑着跑开了。","pinyin":"Háizimen xīxiàozhe pǎo kāi le.","vi":"Bọn trẻ cười đùa chạy đi."},{"type":"simple","zh":"教室里传来学生们的嬉笑声。","pinyin":"Jiàoshì li chuánlái xuéshengmen de xīxiào shēng.","vi":"Từ trong lớp vọng ra tiếng cười đùa của học sinh."},{"type":"compound","zh":"虽然他们在嬉笑打闹，但是听到铃声马上就安静了。","pinyin":"Suīrán tāmen zài xīxiào dǎnào, dànshì tīngdào língshēng mǎshàng jiù ānjìng le.","vi":"Tuy chúng đang cười đùa nghịch ngợm nhưng nghe tiếng chuông là im lặng ngay."}],"related":[{"hanzi":"嬉戏","pinyin":"xīxì","vi":"nô đùa"},{"hanzi":"说笑","pinyin":"shuōxiào","vi":"nói cười"},{"hanzi":"欢笑","pinyin":"huānxiào","vi":"cười vui"},{"hanzi":"打闹","pinyin":"dǎnào","vi":"đùa nghịch"}]},{"id":"席","hanzi":"席","pinyin":"xí","meaning_vi":"chiếu; chỗ ngồi; bữa tiệc; (lượng từ) bàn, buổi","explanation":"席 (tịch – chiếu ngồi) → xưa ngồi trên chiếu, nên mở rộng thành chỗ ngồi (座席), bữa tiệc (酒席); cũng là lượng từ (一席话).","hsk_level":"7-9","tags":["danh-tu"],"image":"🍽️","examples":[{"type":"basic","zh":"请大家入席。","pinyin":"Qǐng dàjiā rùxí.","vi":"Mời mọi người vào chỗ ngồi."},{"type":"simple","zh":"他的一席话让我很受启发。","pinyin":"Tā de yìxíhuà ràng wǒ hěn shòu qǐfā.","vi":"Những lời ông ấy nói khiến tôi được gợi mở rất nhiều."},{"type":"compound","zh":"因为客人太多，所以主人又加了两席酒菜。","pinyin":"Yīnwèi kèrén tài duō, suǒyǐ zhǔrén yòu jiāle liǎng xí jiǔcài.","vi":"Vì khách quá đông nên chủ nhà kê thêm hai mâm cỗ."}],"related":[{"hanzi":"出席","pinyin":"chūxí","vi":"có mặt, tham dự"},{"hanzi":"酒席","pinyin":"jiǔxí","vi":"tiệc rượu"},{"hanzi":"主席","pinyin":"zhǔxí","vi":"chủ tịch"},{"hanzi":"座位","pinyin":"zuòwèi","vi":"chỗ ngồi"}]},{"id":"洗涤剂","hanzi":"洗涤剂","pinyin":"xǐdíjì","meaning_vi":"chất tẩy rửa, nước rửa","explanation":"洗涤 (tẩy địch – rửa sạch) + 剂 (tễ – chế phẩm, thuốc) → chế phẩm dùng để tẩy rửa.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"🧴","examples":[{"type":"basic","zh":"洗涤剂用完了。","pinyin":"Xǐdíjì yòng wánle.","vi":"Nước tẩy rửa hết rồi."},{"type":"simple","zh":"洗碗时加一点洗涤剂就能去油。","pinyin":"Xǐwǎn shí jiā yìdiǎn xǐdíjì jiù néng qù yóu.","vi":"Khi rửa bát cho thêm chút nước rửa là tẩy được dầu mỡ."},{"type":"compound","zh":"如果洗涤剂残留在蔬菜上，就会对身体有害。","pinyin":"Rúguǒ xǐdíjì cánliú zài shūcài shang, jiù huì duì shēntǐ yǒuhài.","vi":"Nếu chất tẩy rửa còn sót lại trên rau thì sẽ có hại cho sức khỏe."}],"related":[{"hanzi":"洗衣粉","pinyin":"xǐyīfěn","vi":"bột giặt"},{"hanzi":"洗洁精","pinyin":"xǐjiéjīng","vi":"nước rửa chén"},{"hanzi":"清洁剂","pinyin":"qīngjiéjì","vi":"chất tẩy rửa"},{"hanzi":"肥皂","pinyin":"féizào","vi":"xà phòng"}],"traditional":"洗滌劑"},{"id":"喜好","hanzi":"喜好","pinyin":"xǐhào","meaning_vi":"yêu thích, ưa chuộng; sở thích","explanation":"喜 (hỷ – vui, thích) + 好 (hiếu – ưa thích) → yêu thích; cũng dùng như danh từ: sở thích.","hsk_level":"7-9","tags":["dong-tu"],"image":"❤️","examples":[{"type":"basic","zh":"他喜好读书。","pinyin":"Tā xǐhào dúshū.","vi":"Anh ấy thích đọc sách."},{"type":"simple","zh":"每个人的口味和喜好都不一样。","pinyin":"Měigèrén de kǒuwèi hé xǐhào dōu bù yíyàng.","vi":"Khẩu vị và sở thích của mỗi người đều khác nhau."},{"type":"compound","zh":"如果能了解顾客的喜好，就能更好地推荐商品。","pinyin":"Rúguǒ néng liǎojiě gùkè de xǐhào, jiù néng gèng hǎo de tuījiàn shāngpǐn.","vi":"Nếu hiểu được sở thích của khách hàng thì có thể giới thiệu sản phẩm tốt hơn."}],"related":[{"hanzi":"爱好","pinyin":"àihào","vi":"sở thích"},{"hanzi":"兴趣","pinyin":"xìngqù","vi":"hứng thú"},{"hanzi":"偏好","pinyin":"piānhào","vi":"thiên hướng ưa thích"},{"hanzi":"讨厌","pinyin":"tǎoyàn","vi":"ghét"}]},{"id":"喜酒","hanzi":"喜酒","pinyin":"xǐjiǔ","meaning_vi":"rượu mừng, tiệc cưới","explanation":"喜 (hỷ – việc vui, đám cưới) + 酒 (tửu – rượu) → rượu mừng uống trong tiệc cưới; 喝喜酒 = đi ăn cưới.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🥂","examples":[{"type":"basic","zh":"什么时候喝你们的喜酒？","pinyin":"Shénme shíhou hē nǐmen de xǐjiǔ?","vi":"Bao giờ được uống rượu mừng của hai bạn?"},{"type":"simple","zh":"这周末我要去老家喝表哥的喜酒。","pinyin":"Zhè zhōumò wǒ yào qù lǎojiā hē biǎogē de xǐjiǔ.","vi":"Cuối tuần này tôi về quê ăn cưới anh họ."},{"type":"compound","zh":"虽然工作很忙，但是好朋友的喜酒我一定要去。","pinyin":"Suīrán gōngzuò hěn máng, dànshì hǎopéngyou de xǐjiǔ wǒ yídìngyào qù.","vi":"Tuy công việc rất bận nhưng tiệc cưới của bạn thân thì tôi nhất định phải đi."}],"related":[{"hanzi":"喜糖","pinyin":"xǐtáng","vi":"kẹo mừng"},{"hanzi":"婚礼","pinyin":"hūnlǐ","vi":"hôn lễ"},{"hanzi":"喜宴","pinyin":"xǐyàn","vi":"tiệc mừng"},{"hanzi":"喜事","pinyin":"xǐshì","vi":"việc vui"}]},{"id":"喜事","hanzi":"喜事","pinyin":"xǐshì","meaning_vi":"việc vui, chuyện mừng; đám cưới","explanation":"喜 (hỷ – vui mừng) + 事 (sự – việc) → việc vui mừng, đặc biệt là đám cưới.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎉","examples":[{"type":"basic","zh":"家里有喜事了。","pinyin":"Jiāli yǒu xǐshì le.","vi":"Nhà có chuyện vui rồi."},{"type":"simple","zh":"他们家最近喜事连连，又买房又生孩子。","pinyin":"Tāmen jiā zuìjìn xǐshì liánlián, yòu mǎifáng yòu shēngháizi.","vi":"Nhà họ dạo này liên tiếp có tin vui, vừa mua nhà vừa sinh con."},{"type":"compound","zh":"虽然办喜事很热闹，但是也花了不少钱。","pinyin":"Suīrán bàn xǐshì hěn rènao, dànshì yě huāle bùshǎo qián.","vi":"Tuy làm đám cưới rất náo nhiệt nhưng cũng tốn không ít tiền."}],"related":[{"hanzi":"喜酒","pinyin":"xǐjiǔ","vi":"rượu mừng"},{"hanzi":"丧事","pinyin":"sāngshì","vi":"việc tang"},{"hanzi":"好事","pinyin":"hǎoshì","vi":"chuyện tốt"},{"hanzi":"喜讯","pinyin":"xǐxùn","vi":"tin vui"}]},{"id":"喜糖","hanzi":"喜糖","pinyin":"xǐtáng","meaning_vi":"kẹo mừng (cưới)","explanation":"喜 (hỷ – việc vui) + 糖 (đường – kẹo) → kẹo chia cho mọi người trong dịp cưới hỏi, vui mừng.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🍬","examples":[{"type":"basic","zh":"来，吃块喜糖！","pinyin":"Lái, chī kuài xǐtáng!","vi":"Nào, ăn viên kẹo mừng đi!"},{"type":"simple","zh":"她给办公室每个人都发了喜糖。","pinyin":"Tā gěi bàngōngshì měigèrén dōu fāle xǐtáng.","vi":"Cô ấy phát kẹo mừng cho mọi người trong văn phòng."},{"type":"compound","zh":"因为同事下个月结婚，所以今天先给大家发喜糖。","pinyin":"Yīnwèi tóngshì xiàgèyuè jiéhūn, suǒyǐ jīntiān xiān gěi dàjiā fā xǐtáng.","vi":"Vì tháng sau đồng nghiệp kết hôn nên hôm nay phát kẹo mừng cho mọi người trước."}],"related":[{"hanzi":"喜酒","pinyin":"xǐjiǔ","vi":"rượu mừng"},{"hanzi":"糖果","pinyin":"tángguǒ","vi":"kẹo"},{"hanzi":"结婚","pinyin":"jiéhūn","vi":"kết hôn"},{"hanzi":"红包","pinyin":"hóngbāo","vi":"bao lì xì"}]},{"id":"喜洋洋","hanzi":"喜洋洋","pinyin":"xǐyángyáng","meaning_vi":"vui phơi phới, hân hoan","explanation":"喜 (hỷ – vui) + 洋洋 (dương dương – tràn đầy) → niềm vui tràn ngập, hớn hở.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😄","examples":[{"type":"basic","zh":"大家都喜洋洋的。","pinyin":"Dàjiā dōu xǐyángyáng de.","vi":"Mọi người đều vui phơi phới."},{"type":"simple","zh":"过年了，村子里到处喜洋洋。","pinyin":"Guònián le, cūnzi li dàochù xǐyángyáng.","vi":"Tết đến rồi, khắp làng tràn ngập niềm vui."},{"type":"compound","zh":"虽然天气很冷，但是婚礼现场喜洋洋的，十分温暖。","pinyin":"Suīrán tiānqì hěn lěng, dànshì hūnlǐ xiànchǎng xǐyángyáng de, shífēn wēnnuǎn.","vi":"Tuy trời rất lạnh nhưng tiệc cưới tràn ngập niềm vui, vô cùng ấm áp."}],"related":[{"hanzi":"喜气洋洋","pinyin":"xǐqìyángyáng","vi":"hân hoan rạng rỡ"},{"hanzi":"欢天喜地","pinyin":"huāntiānxǐdì","vi":"vui mừng hớn hở"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"vui"},{"hanzi":"愁眉苦脸","pinyin":"chóuméikǔliǎn","vi":"mặt mày ủ ê"}]},{"id":"细腻","hanzi":"细腻","pinyin":"xìnì","meaning_vi":"tinh tế, tỉ mỉ; mịn màng","explanation":"细 (tế – nhỏ, kỹ) + 腻 (nị – mịn, trơn) → mịn màng (da, chất liệu); nghĩa bóng là tinh tế, tỉ mỉ (tình cảm, miêu tả).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🎨","examples":[{"type":"basic","zh":"她的皮肤很细腻。","pinyin":"Tā de pífū hěn xìnì.","vi":"Làn da cô ấy rất mịn màng."},{"type":"simple","zh":"这部小说的心理描写非常细腻。","pinyin":"Zhè bù xiǎoshuō de xīnlǐ miáoxiě fēicháng xìnì.","vi":"Miêu tả tâm lý của cuốn tiểu thuyết này rất tinh tế."},{"type":"compound","zh":"虽然他是个男生，但是感情很细腻，很会照顾人。","pinyin":"Suīrán tā shì gè nánshēng, dànshì gǎnqíng hěn xìnì, hěn huì zhàogù rén.","vi":"Tuy là con trai nhưng cậu ấy tình cảm rất tinh tế, rất biết chăm sóc người khác."}],"related":[{"hanzi":"细致","pinyin":"xìzhì","vi":"tỉ mỉ"},{"hanzi":"光滑","pinyin":"guānghuá","vi":"nhẵn mịn"},{"hanzi":"粗糙","pinyin":"cūcāo","vi":"thô ráp"},{"hanzi":"精致","pinyin":"jīngzhì","vi":"tinh xảo"}],"traditional":"細膩"},{"id":"细心","hanzi":"细心","pinyin":"xìxīn","meaning_vi":"cẩn thận, chu đáo, tỉ mỉ","explanation":"细 (tế – nhỏ, kỹ) + 心 (tâm – lòng) → để tâm đến cả những điều nhỏ, cẩn thận chu đáo.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔎","examples":[{"type":"basic","zh":"她做事很细心。","pinyin":"Tā zuòshì hěn xìxīn.","vi":"Cô ấy làm việc rất cẩn thận."},{"type":"simple","zh":"护士细心地给病人换了药。","pinyin":"Hùshi xìxīn de gěi bìngrén huànle yào.","vi":"Y tá cẩn thận thay thuốc cho bệnh nhân."},{"type":"compound","zh":"如果你再细心一点，就不会把数字写错了。","pinyin":"Rúguǒ nǐ zài xìxīn yìdiǎn, jiù bú huì bǎ shùzì xiě cuò le.","vi":"Nếu bạn cẩn thận hơn một chút thì đã không viết sai con số."}],"related":[{"hanzi":"粗心","pinyin":"cūxīn","vi":"cẩu thả"},{"hanzi":"仔细","pinyin":"zǐxì","vi":"kỹ lưỡng"},{"hanzi":"耐心","pinyin":"nàixīn","vi":"kiên nhẫn"},{"hanzi":"用心","pinyin":"yòngxīn","vi":"chú tâm"}],"traditional":"細心"},{"id":"虾","hanzi":"虾","pinyin":"xiā","meaning_vi":"con tôm","explanation":"虾 (hà – tôm): bộ 虫 (côn trùng, loài nhỏ) → con tôm.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦐","examples":[{"type":"basic","zh":"我爱吃虾。","pinyin":"Wǒ ài chī xiā.","vi":"Tôi thích ăn tôm."},{"type":"simple","zh":"妈妈从市场买回来两斤新鲜的虾。","pinyin":"Māma cóng shìchǎng mǎi huílái liǎng jīn xīnxiān de xiā.","vi":"Mẹ mua từ chợ về hai cân tôm tươi."},{"type":"compound","zh":"因为他对虾过敏，所以点菜时要特别注意。","pinyin":"Yīnwèi tā duìxiā guòmǐn, suǒyǐ diǎncài shí yào tèbié zhùyì.","vi":"Vì anh ấy dị ứng tôm nên khi gọi món phải đặc biệt chú ý."}],"related":[{"hanzi":"龙虾","pinyin":"lóngxiā","vi":"tôm hùm"},{"hanzi":"虾仁","pinyin":"xiārén","vi":"tôm bóc nõn"},{"hanzi":"螃蟹","pinyin":"pángxiè","vi":"con cua"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"hải sản"}],"traditional":"蝦"},{"id":"侠义","hanzi":"侠义","pinyin":"xiáyì","meaning_vi":"hiệp nghĩa, nghĩa hiệp","explanation":"侠 (hiệp – hiệp sĩ) + 义 (nghĩa – việc nghĩa) → trọng nghĩa khí, dám ra tay giúp kẻ yếu.","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🗡️","examples":[{"type":"basic","zh":"他很有侠义精神。","pinyin":"Tā hěn yǒu xiáyì jīngshén.","vi":"Anh ấy rất có tinh thần hiệp nghĩa."},{"type":"simple","zh":"武侠小说里充满了侠义情怀。","pinyin":"Wǔxiáxiǎoshuō li chōngmǎnle xiáyì qínghuái.","vi":"Tiểu thuyết võ hiệp tràn đầy tinh thần nghĩa hiệp."},{"type":"compound","zh":"虽然他只是普通人，但是这种侠义行为令人敬佩。","pinyin":"Suīrán tā zhǐshì pǔtōngrén, dànshì zhè zhǒng xiáyì xíngwéi lìngrén jìngpèi.","vi":"Tuy anh ấy chỉ là người bình thường nhưng hành động nghĩa hiệp này khiến người ta kính phục."}],"related":[{"hanzi":"武侠","pinyin":"wǔxiá","vi":"võ hiệp"},{"hanzi":"义气","pinyin":"yìqi","vi":"nghĩa khí"},{"hanzi":"侠客","pinyin":"xiákè","vi":"hiệp khách"},{"hanzi":"见义勇为","pinyin":"jiànyìyǒngwéi","vi":"thấy việc nghĩa thì làm"}],"traditional":"俠義"},{"id":"下场","hanzi":"下场","pinyin":"xiàchǎng","meaning_vi":"kết cục, hậu quả (xấu); rời sân, ra sân","explanation":"下 (hạ – xuống, rời) + 场 (trường – sân, sân khấu) → rời sân khấu/sân đấu; nghĩa bóng là kết cục cuối cùng, thường xấu.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎬","examples":[{"type":"basic","zh":"他落得这个下场。","pinyin":"Tā luòde zhè ge xiàchǎng.","vi":"Hắn rơi vào kết cục này."},{"type":"simple","zh":"受伤的队员被换下场了。","pinyin":"Shòushāng de duìyuán bèi huàn xiàchǎng le.","vi":"Cầu thủ bị thương đã được thay ra khỏi sân."},{"type":"compound","zh":"如果继续这样骗人，你迟早会有可悲的下场。","pinyin":"Rúguǒ jìxù zhèyàng piànrén, nǐ chízǎo huì yǒu kěbēi de xiàchǎng.","vi":"Nếu tiếp tục lừa người như vậy, sớm muộn gì anh cũng có kết cục đáng buồn."}],"related":[{"hanzi":"结局","pinyin":"jiéjú","vi":"kết cục"},{"hanzi":"后果","pinyin":"hòuguǒ","vi":"hậu quả"},{"hanzi":"上场","pinyin":"shàngchǎng","vi":"ra sân"},{"hanzi":"收场","pinyin":"shōuchǎng","vi":"kết thúc"}],"traditional":"下場"},{"id":"下调","hanzi":"下调","pinyin":"xiàtiáo","meaning_vi":"điều chỉnh giảm, hạ (giá, lãi suất…)","explanation":"下 (hạ – xuống) + 调 (điều – điều chỉnh) → điều chỉnh xuống; đọc xià tiáo khi nói giá cả, lãi suất (đọc xià diào là điều chuyển xuống cấp dưới).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"油价下调了。","pinyin":"Yóujià xiàtiáo le.","vi":"Giá xăng dầu đã giảm."},{"type":"simple","zh":"银行宣布下调存款利率。","pinyin":"Yínháng xuānbù xiàtiáo cúnkuǎn lìlǜ.","vi":"Ngân hàng tuyên bố hạ lãi suất tiền gửi."},{"type":"compound","zh":"如果房价继续下调，很多人就会选择观望。","pinyin":"Rúguǒ fángjià jìxù xiàtiáo, hěn duō rén jiù huì xuǎnzé guānwàng.","vi":"Nếu giá nhà tiếp tục giảm thì nhiều người sẽ chọn đứng ngoài quan sát."}],"related":[{"hanzi":"上调","pinyin":"shàngtiáo","vi":"điều chỉnh tăng"},{"hanzi":"调整","pinyin":"tiáozhěng","vi":"điều chỉnh"},{"hanzi":"降低","pinyin":"jiàngdī","vi":"hạ thấp"},{"hanzi":"下降","pinyin":"xiàjiàng","vi":"giảm xuống"}],"traditional":"下調"},{"id":"下跌","hanzi":"下跌","pinyin":"xiàdiē","meaning_vi":"giảm, sụt, rớt (giá)","explanation":"下 (hạ – xuống) + 跌 (điệt – ngã, rơi) → rơi xuống; dùng cho giá cả, chỉ số.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"股价大幅下跌。","pinyin":"Gǔjià dàfú xiàdiē.","vi":"Giá cổ phiếu giảm mạnh."},{"type":"simple","zh":"今年蔬菜价格比去年下跌了不少。","pinyin":"Jīnnián shūcài jiàgé bǐ qùnián xiàdiēle bùshǎo.","vi":"Năm nay giá rau giảm khá nhiều so với năm ngoái."},{"type":"compound","zh":"虽然股票下跌了，但是他并不着急卖出。","pinyin":"Suīrán gǔpiào xiàdiē le, dànshì tā bìngbù zháojí màichū.","vi":"Tuy cổ phiếu đã giảm nhưng anh ấy không vội bán ra."}],"related":[{"hanzi":"上涨","pinyin":"shàngzhǎng","vi":"tăng lên"},{"hanzi":"下降","pinyin":"xiàjiàng","vi":"giảm xuống"},{"hanzi":"暴跌","pinyin":"bàodiē","vi":"giảm mạnh"},{"hanzi":"回落","pinyin":"huíluò","vi":"giảm trở lại"}]},{"id":"下功夫","hanzi":"下功夫","pinyin":"xiàgōngfu","meaning_vi":"bỏ công sức, dày công, nỗ lực","explanation":"下 (hạ – bỏ vào) + 功夫 (công phu – thời gian, công sức) → dồn thời gian, sức lực vào việc gì.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🏋️","examples":[{"type":"basic","zh":"学外语要下功夫。","pinyin":"Xué wàiyǔ yào xiàgōngfu.","vi":"Học ngoại ngữ phải bỏ công sức."},{"type":"simple","zh":"他在发音上很下功夫，所以进步很快。","pinyin":"Tā zài fāyīn shang hěn xiàgōngfu, suǒyǐ jìnbù hěn kuài.","vi":"Cậu ấy dày công luyện phát âm nên tiến bộ rất nhanh."},{"type":"compound","zh":"只要肯下功夫，就没有学不会的东西。","pinyin":"Zhǐyào kěn xiàgōngfu, jiù méiyǒu xué bú huì de dōngxi.","vi":"Chỉ cần chịu bỏ công sức thì không có gì là không học được."}],"related":[{"hanzi":"功夫","pinyin":"gōngfu","vi":"công phu"},{"hanzi":"努力","pinyin":"nǔlì","vi":"nỗ lực"},{"hanzi":"用功","pinyin":"yònggōng","vi":"chăm chỉ"},{"hanzi":"费劲","pinyin":"fèijìn","vi":"tốn sức"}]},{"id":"下海","hanzi":"下海","pinyin":"xiàhǎi","meaning_vi":"ra biển; bỏ việc nhà nước để kinh doanh","explanation":"下 (hạ – xuống) + 海 (hải – biển) → xuống biển; nghĩa bóng (từ thập niên 80) là bỏ công việc ổn định để lao vào kinh doanh.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🌊","examples":[{"type":"basic","zh":"渔民们清早下海。","pinyin":"Yúmínmen qīngzǎo xiàhǎi.","vi":"Ngư dân ra biển từ sáng sớm."},{"type":"simple","zh":"九十年代，很多人辞职下海经商。","pinyin":"Jiǔshí niándài, hěn duō rén cízhí xiàhǎi jīngshāng.","vi":"Những năm 90, nhiều người bỏ việc để ra kinh doanh."},{"type":"compound","zh":"虽然下海经商有风险，但是他还是辞掉了稳定的工作。","pinyin":"Suīrán xiàhǎi jīngshāng yǒu fēngxiǎn, dànshì tā háishi cídiàole wěndìng de gōngzuò.","vi":"Tuy ra làm kinh doanh có rủi ro nhưng anh ấy vẫn bỏ công việc ổn định."}],"related":[{"hanzi":"经商","pinyin":"jīngshāng","vi":"kinh doanh"},{"hanzi":"创业","pinyin":"chuàngyè","vi":"khởi nghiệp"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"出海","pinyin":"chūhǎi","vi":"ra khơi"}]},{"id":"下级","hanzi":"下级","pinyin":"xiàjí","meaning_vi":"cấp dưới","explanation":"下 (hạ – dưới) + 级 (cấp – cấp bậc) → cấp bậc thấp hơn, người hoặc đơn vị cấp dưới.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👇","examples":[{"type":"basic","zh":"他对下级很好。","pinyin":"Tā duì xiàjí hěn hǎo.","vi":"Ông ấy đối xử rất tốt với cấp dưới."},{"type":"simple","zh":"上级的命令已经传达给下级部门了。","pinyin":"Shàngjí de mìnglìng yǐjīng chuándá gěi xiàjí bùmén le.","vi":"Mệnh lệnh của cấp trên đã được truyền đạt xuống các bộ phận cấp dưới."},{"type":"compound","zh":"如果领导不尊重下级，团队就很难团结。","pinyin":"Rúguǒ lǐngdǎo bù zūnzhòng xiàjí, tuánduì jiù hěn nán tuánjié.","vi":"Nếu lãnh đạo không tôn trọng cấp dưới thì tập thể khó đoàn kết."}],"related":[{"hanzi":"上级","pinyin":"shàngjí","vi":"cấp trên"},{"hanzi":"下属","pinyin":"xiàshǔ","vi":"thuộc cấp"},{"hanzi":"部下","pinyin":"bùxià","vi":"thuộc hạ"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"}],"traditional":"下級"},{"id":"下决心","hanzi":"下决心","pinyin":"xiàjuéxīn","meaning_vi":"quyết tâm, hạ quyết tâm","explanation":"下 (hạ – đưa ra) + 决心 (quyết tâm) → đưa ra quyết tâm làm việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"✊","examples":[{"type":"basic","zh":"我下决心戒烟了。","pinyin":"Wǒ xiàjuéxīn jièyān le.","vi":"Tôi đã quyết tâm bỏ thuốc lá."},{"type":"simple","zh":"她下决心今年一定要考上研究生。","pinyin":"Tā xiàjuéxīn jīnnián yídìngyào kǎoshàng yánjiūshēng.","vi":"Cô ấy hạ quyết tâm năm nay nhất định phải đỗ cao học."},{"type":"compound","zh":"既然已经下决心减肥，就不能再吃夜宵了。","pinyin":"Jìrán yǐjīng xiàjuéxīn jiǎnféi, jiù bù néng zài chī yèxiāo le.","vi":"Đã quyết tâm giảm cân thì không được ăn khuya nữa."}],"related":[{"hanzi":"决心","pinyin":"juéxīn","vi":"quyết tâm"},{"hanzi":"决定","pinyin":"juédìng","vi":"quyết định"},{"hanzi":"下定","pinyin":"xiàdìng","vi":"hạ quyết"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"}],"traditional":"下決心"},{"id":"下令","hanzi":"下令","pinyin":"xiàlìng","meaning_vi":"ra lệnh, hạ lệnh","explanation":"下 (hạ – ban xuống) + 令 (lệnh) → ban lệnh, ra mệnh lệnh.","hsk_level":"7-9","tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"将军下令撤退。","pinyin":"Jiāngjūn xiàlìng chètuì.","vi":"Tướng quân ra lệnh rút lui."},{"type":"simple","zh":"市长下令关闭所有的学校。","pinyin":"Shìzhǎng xiàlìng guānbì suǒyǒu de xuéxiào.","vi":"Thị trưởng ra lệnh đóng cửa tất cả các trường học."},{"type":"compound","zh":"因为台风即将登陆，所以政府下令渔船立即回港。","pinyin":"Yīnwèi táifēng jíjiāng dēnglù, suǒyǐ zhèngfǔ xiàlìng yúchuán lìjí huí gǎng.","vi":"Vì bão sắp đổ bộ nên chính quyền ra lệnh tàu cá lập tức về cảng."}],"related":[{"hanzi":"命令","pinyin":"mìnglìng","vi":"mệnh lệnh"},{"hanzi":"指令","pinyin":"zhǐlìng","vi":"chỉ thị"},{"hanzi":"下达","pinyin":"xiàdá","vi":"truyền đạt xuống"},{"hanzi":"服从","pinyin":"fúcóng","vi":"phục tùng"}]},{"id":"下落","hanzi":"下落","pinyin":"xiàluò","meaning_vi":"tung tích, nơi ở; rơi xuống","explanation":"下 (hạ – xuống) + 落 (lạc – rơi) → rơi xuống; nghĩa mở rộng là chỗ cuối cùng người hay vật rơi về, tức tung tích.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"他的下落不明。","pinyin":"Tā de xiàluò bùmíng.","vi":"Tung tích của anh ấy không rõ."},{"type":"simple","zh":"警察终于查到了那辆车的下落。","pinyin":"Jǐngchá zhōngyú chá dàole nà liàng chē de xiàluò.","vi":"Cảnh sát cuối cùng đã tra ra tung tích của chiếc xe đó."},{"type":"compound","zh":"虽然找了三年，但是她的下落还是没人知道。","pinyin":"Suīrán zhǎole sān nián, dànshì tā de xiàluò háishi méi rén zhīdào.","vi":"Tuy đã tìm ba năm nhưng vẫn không ai biết tung tích của cô ấy."}],"related":[{"hanzi":"落下","pinyin":"luòxià","vi":"rơi xuống"},{"hanzi":"去向","pinyin":"qùxiàng","vi":"hướng đi"},{"hanzi":"踪迹","pinyin":"zōngjì","vi":"dấu vết"},{"hanzi":"下降","pinyin":"xiàjiàng","vi":"hạ xuống"}]},{"id":"下期","hanzi":"下期","pinyin":"xiàqī","meaning_vi":"kỳ sau, số sau","explanation":"下 (hạ – sau, tới) + 期 (kỳ – kỳ, số) → kỳ tiếp theo, số tiếp theo của tạp chí hay chương trình.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"我们下期再见！","pinyin":"Wǒmen xiàqī zàijiàn!","vi":"Chúng ta hẹn gặp lại kỳ sau!"},{"type":"simple","zh":"这本杂志下期会介绍云南的美食。","pinyin":"Zhè běn zázhì xiàqī huì jièshào Yúnnán de měishí.","vi":"Số sau tạp chí này sẽ giới thiệu món ngon Vân Nam."},{"type":"compound","zh":"如果这期来不及报名，你就等下期吧。","pinyin":"Rúguǒ zhè qī láibují bàomíng, nǐ jiù děng xiàqī ba.","vi":"Nếu kỳ này không kịp đăng ký thì bạn đợi kỳ sau nhé."}],"related":[{"hanzi":"上期","pinyin":"shàngqī","vi":"kỳ trước"},{"hanzi":"本期","pinyin":"běnqī","vi":"kỳ này"},{"hanzi":"期刊","pinyin":"qīkān","vi":"tạp chí định kỳ"},{"hanzi":"下次","pinyin":"xiàcì","vi":"lần sau"}]},{"id":"下棋","hanzi":"下棋","pinyin":"xiàqí","meaning_vi":"đánh cờ, chơi cờ","explanation":"下 (hạ – đặt xuống) + 棋 (kỳ – cờ) → đặt quân cờ xuống bàn, tức chơi cờ.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"♟️","examples":[{"type":"basic","zh":"爷爷喜欢下棋。","pinyin":"Yéye xǐhuan xiàqí.","vi":"Ông nội thích đánh cờ."},{"type":"simple","zh":"几个老人每天下午在公园里下棋。","pinyin":"Jǐ gè lǎorén měitiān xiàwǔ zài gōngyuán lǐ xiàqí.","vi":"Mấy cụ già chiều nào cũng đánh cờ trong công viên."},{"type":"compound","zh":"他虽然下棋才一年，但是已经能赢他爸爸了。","pinyin":"Tā suīrán xiàqí cái yì nián, dànshì yǐjīng néng yíng tā bàba le.","vi":"Tuy cậu ấy mới chơi cờ một năm nhưng đã thắng được bố."}],"related":[{"hanzi":"象棋","pinyin":"xiàngqí","vi":"cờ tướng"},{"hanzi":"围棋","pinyin":"wéiqí","vi":"cờ vây"},{"hanzi":"棋盘","pinyin":"qípán","vi":"bàn cờ"},{"hanzi":"棋子","pinyin":"qízǐ","vi":"quân cờ"}]},{"id":"下山","hanzi":"下山","pinyin":"xiàshān","meaning_vi":"xuống núi; (mặt trời) lặn","explanation":"下 (hạ – xuống) + 山 (sơn – núi) → đi xuống núi; cũng chỉ mặt trời, mặt trăng lặn sau núi.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"太阳快下山了。","pinyin":"Tàiyáng kuài xiàshān le.","vi":"Mặt trời sắp lặn rồi."},{"type":"simple","zh":"我们必须在天黑以前下山。","pinyin":"Wǒmen bìxū zài tiānhēi yǐqián xiàshān.","vi":"Chúng ta phải xuống núi trước khi trời tối."},{"type":"compound","zh":"因为突然下起大雨，所以我们只好提前下山。","pinyin":"Yīnwèi tūrán xià qǐ dàyǔ, suǒyǐ wǒmen zhǐhǎo tíqián xiàshān.","vi":"Vì trời bỗng đổ mưa to nên chúng tôi đành xuống núi sớm."}],"related":[{"hanzi":"上山","pinyin":"shàngshān","vi":"lên núi"},{"hanzi":"爬山","pinyin":"páshān","vi":"leo núi"},{"hanzi":"山顶","pinyin":"shāndǐng","vi":"đỉnh núi"},{"hanzi":"日落","pinyin":"rìluò","vi":"mặt trời lặn"}]},{"id":"下手","hanzi":"下手","pinyin":"xiàshǒu","meaning_vi":"ra tay; bắt tay vào làm","explanation":"下 (hạ – đặt xuống) + 手 (thủ – tay) → đặt tay vào việc, tức bắt đầu làm hoặc ra tay.","hsk_level":"7-9","tags":["dong-tu"],"image":"✋","examples":[{"type":"basic","zh":"这件事很难下手。","pinyin":"Zhè jiàn shì hěn nán xiàshǒu.","vi":"Việc này rất khó bắt tay vào."},{"type":"simple","zh":"小偷趁主人睡着的时候下手。","pinyin":"Xiǎotōu chèn zhǔrén shuìzháo de shíhou xiàshǒu.","vi":"Tên trộm ra tay lúc chủ nhà đang ngủ."},{"type":"compound","zh":"如果你想解决问题，就先从最简单的地方下手。","pinyin":"Rúguǒ nǐ xiǎng jiějué wèntí, jiù xiān cóng zuì jiǎndān de dìfang xiàshǒu.","vi":"Nếu muốn giải quyết vấn đề thì hãy bắt đầu từ chỗ đơn giản nhất."}],"related":[{"hanzi":"动手","pinyin":"dòngshǒu","vi":"bắt tay làm"},{"hanzi":"着手","pinyin":"zhuóshǒu","vi":"bắt đầu"},{"hanzi":"出手","pinyin":"chūshǒu","vi":"ra tay"},{"hanzi":"入手","pinyin":"rùshǒu","vi":"bắt tay vào"}]},{"id":"下台","hanzi":"下台","pinyin":"xiàtái","meaning_vi":"xuống sân khấu; từ chức, mất chức","explanation":"下 (hạ – xuống) + 台 (đài – sân khấu, bục) → bước xuống sân khấu; nghĩa bóng là rời khỏi chức vụ, mất quyền lực.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🎤","examples":[{"type":"basic","zh":"总理被迫下台。","pinyin":"Zǒnglǐ bèipò xiàtái.","vi":"Thủ tướng bị buộc phải từ chức."},{"type":"simple","zh":"演员表演完以后鞠了一躬就下台了。","pinyin":"Yǎnyuán biǎoyǎn wán yǐhòu jūle yì gōng jiù xiàtái le.","vi":"Diễn viên diễn xong cúi chào một cái rồi xuống sân khấu."},{"type":"compound","zh":"一旦丑闻被公开，这位部长就不得不下台。","pinyin":"Yídàn chǒuwén bèi gōngkāi, zhè wèi bùzhǎng jiù bùdébú xiàtái.","vi":"Một khi vụ bê bối bị công khai, vị bộ trưởng này buộc phải từ chức."}],"related":[{"hanzi":"上台","pinyin":"shàngtái","vi":"lên sân khấu, lên nắm quyền"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"舞台","pinyin":"wǔtái","vi":"sân khấu"},{"hanzi":"下野","pinyin":"xiàyě","vi":"mất chức"}],"traditional":"下臺"},{"id":"下乡","hanzi":"下乡","pinyin":"xiàxiāng","meaning_vi":"về nông thôn, xuống cơ sở","explanation":"下 (hạ – xuống) + 乡 (hương – làng quê) → đi về vùng nông thôn, thường để làm việc hoặc giúp đỡ.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🌾","examples":[{"type":"basic","zh":"医生们下乡看病。","pinyin":"Yīshēngmen xiàxiāng kànbìng.","vi":"Các bác sĩ về nông thôn khám bệnh."},{"type":"simple","zh":"这批大学生暑假要下乡支教。","pinyin":"Zhè pī dàxuéshēng shǔjià yào xiàxiāng zhījiào.","vi":"Nhóm sinh viên này nghỉ hè sẽ về nông thôn dạy học tình nguyện."},{"type":"compound","zh":"虽然下乡的生活很苦，但是他学到了很多东西。","pinyin":"Suīrán xiàxiāng de shēnghuó hěn kǔ, dànshì tā xuédàole hěn duō dōngxi.","vi":"Tuy cuộc sống ở nông thôn rất khổ nhưng anh ấy học được nhiều điều."}],"related":[{"hanzi":"乡下","pinyin":"xiāngxia","vi":"nông thôn"},{"hanzi":"农村","pinyin":"nóngcūn","vi":"nông thôn"},{"hanzi":"回乡","pinyin":"huíxiāng","vi":"về quê"},{"hanzi":"进城","pinyin":"jìnchéng","vi":"lên thành phố"}],"traditional":"下鄉"},{"id":"下一代","hanzi":"下一代","pinyin":"xiàyídài","meaning_vi":"thế hệ sau, thế hệ tiếp theo","explanation":"下 (hạ – sau) + 一 (nhất – một) + 代 (đại – thế hệ) → thế hệ kế tiếp, con cháu đời sau.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👶","examples":[{"type":"basic","zh":"要保护好下一代。","pinyin":"Yào bǎohù hǎo xiàyídài.","vi":"Phải bảo vệ tốt thế hệ sau."},{"type":"simple","zh":"我们应该给下一代留下干净的地球。","pinyin":"Wǒmen yīnggāi gěi xiàyídài liúxià gānjìng de dìqiú.","vi":"Chúng ta nên để lại cho thế hệ sau một trái đất sạch."},{"type":"compound","zh":"如果现在不保护环境，下一代就会付出代价。","pinyin":"Rúguǒ xiànzài bù bǎohù huánjìng, xiàyídài jiù huì fùchū dàijià.","vi":"Nếu bây giờ không bảo vệ môi trường thì thế hệ sau sẽ phải trả giá."}],"related":[{"hanzi":"上一代","pinyin":"shàngyídài","vi":"thế hệ trước"},{"hanzi":"后代","pinyin":"hòudài","vi":"con cháu"},{"hanzi":"年轻一代","pinyin":"niánqīngyídài","vi":"thế hệ trẻ"},{"hanzi":"子孙","pinyin":"zǐsūn","vi":"con cháu"}]},{"id":"下坠","hanzi":"下坠","pinyin":"xiàzhuì","meaning_vi":"rơi xuống, sa xuống, trĩu xuống","explanation":"下 (hạ – xuống) + 坠 (trụy – rơi) → rơi xuống phía dưới, sa xuống.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪂","examples":[{"type":"basic","zh":"石头不断下坠。","pinyin":"Shítou búduàn xiàzhuì.","vi":"Hòn đá liên tục rơi xuống."},{"type":"simple","zh":"那只漏了气的气球慢慢下坠。","pinyin":"Nà zhī lòule qì de qìqiú mànmàn xiàzhuì.","vi":"Quả bóng bay bị xì hơi đó từ từ rơi xuống."},{"type":"compound","zh":"虽然飞机突然下坠，但是飞行员很快控制住了。","pinyin":"Suīrán fēijī tūrán xiàzhuì, dànshì fēixíngyuán hěn kuài kòngzhì zhù le.","vi":"Tuy máy bay đột nhiên rơi xuống nhưng phi công đã nhanh chóng kiểm soát được."}],"related":[{"hanzi":"坠落","pinyin":"zhuìluò","vi":"rơi rụng"},{"hanzi":"下落","pinyin":"xiàluò","vi":"rơi xuống"},{"hanzi":"下沉","pinyin":"xiàchén","vi":"chìm xuống"},{"hanzi":"掉下","pinyin":"diàoxià","vi":"rơi xuống"}],"traditional":"下墜"},{"id":"吓唬","hanzi":"吓唬","pinyin":"xiàhu","meaning_vi":"dọa, hù dọa","explanation":"吓 (hách – làm sợ) + 唬 (hổ – dọa) → dọa cho người khác sợ.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"👻","examples":[{"type":"basic","zh":"别吓唬孩子。","pinyin":"Bié xiàhu háizi.","vi":"Đừng dọa trẻ con."},{"type":"simple","zh":"他故意戴着面具吓唬妹妹。","pinyin":"Tā gùyì dàizhe miànjù xiàhu mèimei.","vi":"Cậu ấy cố ý đeo mặt nạ để dọa em gái."},{"type":"compound","zh":"因为他只是吓唬你，所以你不用害怕。","pinyin":"Yīnwèi tā zhǐshì xiàhu nǐ, suǒyǐ nǐ bú yòng hàipà.","vi":"Vì anh ta chỉ dọa bạn thôi nên bạn không cần sợ."}],"related":[{"hanzi":"吓人","pinyin":"xiàrén","vi":"đáng sợ"},{"hanzi":"恐吓","pinyin":"kǒnghè","vi":"đe dọa"},{"hanzi":"威胁","pinyin":"wēixié","vi":"uy hiếp"},{"hanzi":"害怕","pinyin":"hàipà","vi":"sợ hãi"}],"traditional":"嚇唬"},{"id":"吓人","hanzi":"吓人","pinyin":"xiàrén","meaning_vi":"đáng sợ, dọa người","explanation":"吓 (hách – làm sợ) + 人 (nhân – người) → làm người ta sợ, tức đáng sợ.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"这个面具真吓人。","pinyin":"Zhè ge miànjù zhēn xiàrén.","vi":"Cái mặt nạ này thật đáng sợ."},{"type":"simple","zh":"昨天晚上的雷声大得吓人。","pinyin":"Zuótiān wǎnshang de léishēng dà de xiàrén.","vi":"Tiếng sấm tối qua to đến đáng sợ."},{"type":"compound","zh":"虽然这部电影的画面很吓人，但是故事很感人。","pinyin":"Suīrán zhè bù diànyǐng de huàmiàn hěn xiàrén, dànshì gùshi hěn gǎnrén.","vi":"Tuy hình ảnh bộ phim này rất đáng sợ nhưng câu chuyện lại cảm động."}],"related":[{"hanzi":"吓唬","pinyin":"xiàhu","vi":"dọa"},{"hanzi":"可怕","pinyin":"kěpà","vi":"đáng sợ"},{"hanzi":"恐怖","pinyin":"kǒngbù","vi":"kinh hoàng"},{"hanzi":"惊人","pinyin":"jīngrén","vi":"kinh người"}],"traditional":"嚇人"},{"id":"先天","hanzi":"先天","pinyin":"xiāntiān","meaning_vi":"bẩm sinh, tiên thiên","explanation":"先 (tiên – trước) + 天 (thiên – trời, lúc sinh ra) → có từ trước khi sinh ra, tức bẩm sinh; trái nghĩa với 后天 (hậu thiên).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🧬","examples":[{"type":"basic","zh":"他有先天心脏病。","pinyin":"Tā yǒu xiāntiān xīnzàngbìng.","vi":"Anh ấy bị bệnh tim bẩm sinh."},{"type":"simple","zh":"她的音乐天赋是先天的。","pinyin":"Tā de yīnyuè tiānfù shì xiāntiān de.","vi":"Năng khiếu âm nhạc của cô ấy là bẩm sinh."},{"type":"compound","zh":"虽然他先天条件不好，但是后天非常努力。","pinyin":"Suīrán tā xiāntiān tiáojiàn bù hǎo, dànshì hòutiān fēicháng nǔlì.","vi":"Tuy điều kiện bẩm sinh không tốt nhưng về sau anh ấy rất nỗ lực."}],"related":[{"hanzi":"后天","pinyin":"hòutiān","vi":"hậu thiên"},{"hanzi":"天生","pinyin":"tiānshēng","vi":"trời sinh"},{"hanzi":"天赋","pinyin":"tiānfù","vi":"năng khiếu bẩm sinh"},{"hanzi":"遗传","pinyin":"yíchuán","vi":"di truyền"}]},{"id":"掀","hanzi":"掀","pinyin":"xiān","meaning_vi":"lật, giở, mở (nắp), vén","explanation":"掀 (hiên – nhấc lên): nhấc vật che phủ lên như nắp nồi, rèm, chăn; còn dùng trong 掀起 (dấy lên).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍲","examples":[{"type":"basic","zh":"他掀开了锅盖。","pinyin":"Tā xiānkāile guōgài.","vi":"Anh ấy mở nắp nồi ra."},{"type":"simple","zh":"一阵大风把屋顶的瓦片掀了下来。","pinyin":"Yízhèn dàfēng bǎ wūdǐng de wǎpiàn xiānle xiàlái.","vi":"Một trận gió lớn lật tung ngói trên mái nhà xuống."},{"type":"compound","zh":"冬天早上他一掀开被子，就冷得直发抖。","pinyin":"Dōngtiān zǎoshang tā yì xiānkāi bèizi, jiù lěng dezhí fādǒu.","vi":"Sáng mùa đông, cậu ấy vừa tung chăn ra là lạnh run cầm cập."}],"related":[{"hanzi":"掀开","pinyin":"xiānkāi","vi":"mở ra"},{"hanzi":"掀起","pinyin":"xiānqǐ","vi":"dấy lên"},{"hanzi":"揭开","pinyin":"jiēkāi","vi":"vén mở"},{"hanzi":"翻","pinyin":"fān","vi":"lật"}]},{"id":"鲜美","hanzi":"鲜美","pinyin":"xiānměi","meaning_vi":"tươi ngon, ngon ngọt","explanation":"鲜 (tiên – tươi) + 美 (mỹ – đẹp, ngon) → tươi và ngon.","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"🐟","examples":[{"type":"basic","zh":"这碗鱼汤很鲜美。","pinyin":"Zhè wǎn yú tāng hěn xiānměi.","vi":"Bát canh cá này rất ngon ngọt."},{"type":"simple","zh":"海边小饭馆的海鲜特别鲜美。","pinyin":"Hǎibiān xiǎofànguǎn de hǎixiān tèbié xiānměi.","vi":"Hải sản ở quán nhỏ ven biển đặc biệt tươi ngon."},{"type":"compound","zh":"因为鱼是刚打上来的，所以味道格外鲜美。","pinyin":"Yīnwèi yú shì gāng dǎ shànglái de, suǒyǐ wèidào géwài xiānměi.","vi":"Vì cá vừa mới đánh lên nên vị đặc biệt tươi ngon."}],"related":[{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"tươi"},{"hanzi":"美味","pinyin":"měiwèi","vi":"ngon"},{"hanzi":"可口","pinyin":"kěkǒu","vi":"ngon miệng"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"hải sản"}],"traditional":"鮮美"},{"id":"鲜血","hanzi":"鲜血","pinyin":"xiānxuè","meaning_vi":"máu tươi","explanation":"鲜 (tiên – tươi) + 血 (huyết – máu) → máu tươi, máu đỏ vừa chảy ra.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🩸","examples":[{"type":"basic","zh":"鲜血染红了衣服。","pinyin":"Xiānxuè rǎn hóngle yīfu.","vi":"Máu tươi nhuộm đỏ quần áo."},{"type":"simple","zh":"他的伤口不停地流出鲜血。","pinyin":"Tā de shāngkǒu bùtíng de liúchū xiānxuè.","vi":"Vết thương của anh ấy không ngừng chảy máu tươi."},{"type":"compound","zh":"虽然手上满是鲜血，但是他仍然坚持把伤员送到医院。","pinyin":"Suīrán shǒushang mǎnshì xiānxuè, dànshì tā réngrán jiānchí bǎ shāngyuán sòng dào yīyuàn.","vi":"Tuy tay đầy máu nhưng anh ấy vẫn kiên trì đưa người bị thương đến bệnh viện."}],"related":[{"hanzi":"血液","pinyin":"xuèyè","vi":"máu"},{"hanzi":"流血","pinyin":"liúxuè","vi":"chảy máu"},{"hanzi":"献血","pinyin":"xiànxuè","vi":"hiến máu"},{"hanzi":"血迹","pinyin":"xuèjì","vi":"vết máu"}],"traditional":"鮮血"},{"id":"弦","hanzi":"弦","pinyin":"xián","meaning_vi":"dây đàn, dây cung","explanation":"弦 (huyền – dây cung, dây đàn): sợi dây căng trên cây cung hoặc nhạc cụ; trong toán học là dây cung.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎻","examples":[{"type":"basic","zh":"吉他断了一根弦。","pinyin":"Jítā duànle yìgēn xián.","vi":"Cây đàn ghi-ta bị đứt một dây."},{"type":"simple","zh":"他小心地给小提琴换上新弦。","pinyin":"Tā xiǎo xīnde gěi xiǎotíqín huàn shàngxīn xián.","vi":"Anh ấy cẩn thận thay dây mới cho cây vĩ cầm."},{"type":"compound","zh":"如果琴弦调得太紧，弹的时候就容易断。","pinyin":"Rúguǒ qínxián tiáo de tài jǐn, tán de shíhou jiù róngyì duàn.","vi":"Nếu lên dây quá căng thì khi đánh sẽ dễ đứt."}],"related":[{"hanzi":"琴弦","pinyin":"qínxián","vi":"dây đàn"},{"hanzi":"弓","pinyin":"gōng","vi":"cây cung"},{"hanzi":"弦乐","pinyin":"xiányuè","vi":"nhạc dây"},{"hanzi":"吉他","pinyin":"jítā","vi":"đàn ghi-ta"}]},{"id":"显示器","hanzi":"显示器","pinyin":"xiǎnshìqì","meaning_vi":"màn hình (máy tính)","explanation":"显示 (hiển thị – cho thấy) + 器 (khí – thiết bị) → thiết bị hiển thị hình ảnh, tức màn hình.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🖥️","examples":[{"type":"basic","zh":"我买了新显示器。","pinyin":"Wǒ mǎile xīn xiǎnshìqì.","vi":"Tôi đã mua màn hình mới."},{"type":"simple","zh":"这台显示器的画面非常清楚。","pinyin":"Zhè tái xiǎnshìqì de huàmiàn fēicháng qīngchu.","vi":"Hình ảnh của màn hình này rất rõ nét."},{"type":"compound","zh":"如果显示器离眼睛太近，眼睛就容易累。","pinyin":"Rúguǒ xiǎnshìqì lí yǎnjing tài jìn, yǎnjing jiù róngyì lèi.","vi":"Nếu màn hình quá gần mắt thì mắt sẽ dễ mỏi."}],"related":[{"hanzi":"显示","pinyin":"xiǎnshì","vi":"hiển thị"},{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"},{"hanzi":"电脑","pinyin":"diànnǎo","vi":"máy tính"},{"hanzi":"键盘","pinyin":"jiànpán","vi":"bàn phím"}],"traditional":"顯示器"},{"id":"显现","hanzi":"显现","pinyin":"xiǎnxiàn","meaning_vi":"hiện ra, lộ ra","explanation":"显 (hiển – rõ) + 现 (hiện – xuất hiện) → hiện ra rõ ràng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌅","examples":[{"type":"basic","zh":"问题逐渐显现。","pinyin":"Wèntí zhújiàn xiǎnxiàn.","vi":"Vấn đề dần dần lộ ra."},{"type":"simple","zh":"远处的山峰在晨光中慢慢显现出来。","pinyin":"Yuǎnchù de shānfēng zài chénguāng zhōng mànmàn xiǎnxiàn chūlái.","vi":"Đỉnh núi phía xa từ từ hiện ra trong nắng sớm."},{"type":"compound","zh":"虽然改革才开始一年，但是效果已经显现出来了。","pinyin":"Suīrán gǎigé cái kāishǐ yì nián, dànshì xiàoguǒ yǐjīng xiǎnxiàn chūlái le.","vi":"Tuy cải cách mới bắt đầu một năm nhưng hiệu quả đã lộ rõ."}],"related":[{"hanzi":"出现","pinyin":"chūxiàn","vi":"xuất hiện"},{"hanzi":"显露","pinyin":"xiǎnlù","vi":"lộ ra"},{"hanzi":"呈现","pinyin":"chéngxiàn","vi":"hiện lên"},{"hanzi":"浮现","pinyin":"fúxiàn","vi":"hiện lên"}],"traditional":"顯現"},{"id":"显眼","hanzi":"显眼","pinyin":"xiǎnyǎn","meaning_vi":"nổi bật, dễ thấy, bắt mắt","explanation":"显 (hiển – rõ) + 眼 (nhãn – mắt) → rõ ràng trước mắt, dễ nhìn thấy.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👀","examples":[{"type":"basic","zh":"红色很显眼。","pinyin":"Hóngsè hěn xiǎnyǎn.","vi":"Màu đỏ rất nổi bật."},{"type":"simple","zh":"他把通知贴在了最显眼的地方。","pinyin":"Tā bǎ tōngzhī tiē zài le zuì xiǎnyǎn de dìfang.","vi":"Anh ấy dán thông báo ở chỗ dễ thấy nhất."},{"type":"compound","zh":"因为她穿了一件黄色外套，所以在人群中特别显眼。","pinyin":"Yīnwèi tā chuānle yí jiàn huángsè wàitào, suǒyǐ zài rénqún zhōng tèbié xiǎnyǎn.","vi":"Vì cô ấy mặc áo khoác vàng nên rất nổi bật giữa đám đông."}],"related":[{"hanzi":"醒目","pinyin":"xǐngmù","vi":"bắt mắt"},{"hanzi":"突出","pinyin":"tūchū","vi":"nổi bật"},{"hanzi":"明显","pinyin":"míngxiǎn","vi":"rõ ràng"},{"hanzi":"引人注目","pinyin":"yǐnrénzhùmù","vi":"thu hút sự chú ý"}],"traditional":"顯眼"},{"id":"现任","hanzi":"现任","pinyin":"xiànrèn","meaning_vi":"hiện giữ chức; đương nhiệm","explanation":"现 (hiện – hiện tại) + 任 (nhậm – đảm nhiệm) → đang giữ chức vụ hiện nay.","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他现任公司经理。","pinyin":"Tā xiànrèn gōngsī jīnglǐ.","vi":"Hiện anh ấy giữ chức giám đốc công ty."},{"type":"simple","zh":"现任校长是一位年轻的女博士。","pinyin":"Xiànrèn xiàozhǎng shì yí wèi niánqīng de nǚ bóshì.","vi":"Hiệu trưởng đương nhiệm là một nữ tiến sĩ trẻ."},{"type":"compound","zh":"虽然现任市长才上任一年，但是城市变化很大。","pinyin":"Suīrán xiànrèn shìzhǎng cái shàngrèn yì nián, dànshì chéngshì biànhuà hěn dà.","vi":"Tuy thị trưởng đương nhiệm mới nhậm chức một năm nhưng thành phố đã thay đổi nhiều."}],"related":[{"hanzi":"前任","pinyin":"qiánrèn","vi":"tiền nhiệm"},{"hanzi":"继任","pinyin":"jìrèn","vi":"kế nhiệm"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"现职","pinyin":"xiànzhí","vi":"chức vụ hiện tại"}],"traditional":"現任"},{"id":"现行","hanzi":"现行","pinyin":"xiànxíng","meaning_vi":"hiện hành, đang có hiệu lực","explanation":"现 (hiện – hiện nay) + 行 (hành – thi hành) → đang được thi hành, đang có hiệu lực.","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"这是现行法律。","pinyin":"Zhè shì xiànxíng fǎlǜ.","vi":"Đây là luật hiện hành."},{"type":"simple","zh":"现行的考试制度还有不少问题。","pinyin":"Xiànxíng de kǎoshì zhìdù háiyǒu bùshǎo wèntí.","vi":"Chế độ thi cử hiện hành vẫn còn không ít vấn đề."},{"type":"compound","zh":"如果现行政策不合理，就应该及时修改。","pinyin":"Rúguǒ xiànxíng zhèngcè bù hélǐ, jiù yīnggāi jíshí xiūgǎi.","vi":"Nếu chính sách hiện hành không hợp lý thì nên kịp thời sửa đổi."}],"related":[{"hanzi":"现有","pinyin":"xiànyǒu","vi":"hiện có"},{"hanzi":"实行","pinyin":"shíxíng","vi":"thực hiện"},{"hanzi":"施行","pinyin":"shīxíng","vi":"thi hành"},{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu lực"}],"traditional":"現行"},{"id":"线条","hanzi":"线条","pinyin":"xiàntiáo","meaning_vi":"đường nét, nét vẽ","explanation":"线 (tuyến – sợi, đường) + 条 (điều – dải dài) → các đường nét trong tranh, thư pháp hoặc hình dáng vật thể.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"✏️","examples":[{"type":"basic","zh":"这幅画线条简单。","pinyin":"Zhè fú huà xiàntiáo jiǎndān.","vi":"Bức tranh này nét vẽ đơn giản."},{"type":"simple","zh":"这辆跑车的线条非常流畅。","pinyin":"Zhè liàng pǎochē de xiàntiáo fēicháng liúchàng.","vi":"Đường nét của chiếc xe thể thao này rất mượt mà."},{"type":"compound","zh":"虽然画里只有几根线条，但是人物的表情很生动。","pinyin":"Suīrán huà lǐ zhǐyǒu jǐ gēn xiàntiáo, dànshì rénwù de biǎoqíng hěn shēngdòng.","vi":"Tuy bức tranh chỉ có vài nét nhưng biểu cảm nhân vật rất sinh động."}],"related":[{"hanzi":"线","pinyin":"xiàn","vi":"đường, sợi"},{"hanzi":"轮廓","pinyin":"lúnkuò","vi":"đường viền"},{"hanzi":"曲线","pinyin":"qūxiàn","vi":"đường cong"},{"hanzi":"直线","pinyin":"zhíxiàn","vi":"đường thẳng"}],"traditional":"線條"},{"id":"限","hanzi":"限","pinyin":"xiàn","meaning_vi":"hạn chế, giới hạn","explanation":"限 (hạn – giới hạn): đặt ra mức không được vượt qua về số lượng, thời gian hay phạm vi.","hsk_level":"7-9","tags":["dong-tu"],"image":"⛔","examples":[{"type":"basic","zh":"每人限买两件。","pinyin":"Měirén xiàn mǎi liǎng jiàn.","vi":"Mỗi người chỉ được mua hai món."},{"type":"simple","zh":"老师限我们三天内交作业。","pinyin":"Lǎoshī xiàn wǒmen sān tiān nèi jiāo zuòyè.","vi":"Thầy giáo hạn chúng tôi nộp bài trong ba ngày."},{"type":"compound","zh":"因为座位有限，所以这次活动限五十人参加。","pinyin":"Yīnwèi zuòwèi yǒuxiàn, suǒyǐ zhè cì huódòng xiàn wǔshí rén cānjiā.","vi":"Vì chỗ ngồi có hạn nên hoạt động lần này giới hạn năm mươi người tham gia."}],"related":[{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"},{"hanzi":"期限","pinyin":"qīxiàn","vi":"thời hạn"},{"hanzi":"有限","pinyin":"yǒuxiàn","vi":"có hạn"},{"hanzi":"无限","pinyin":"wúxiàn","vi":"vô hạn"}]},{"id":"限定","hanzi":"限定","pinyin":"xiàndìng","meaning_vi":"hạn định, giới hạn","explanation":"限 (hạn – giới hạn) + 定 (định – định ra) → quy định giới hạn về số lượng, phạm vi hay thời gian.","hsk_level":"7-9","tags":["dong-tu"],"image":"📏","examples":[{"type":"basic","zh":"时间限定为一小时。","pinyin":"Shíjiān xiàn dìngwéi yì xiǎoshí.","vi":"Thời gian được giới hạn là một tiếng."},{"type":"simple","zh":"这次比赛限定参赛者的年龄在十八岁以下。","pinyin":"Zhè cì bǐsài xiàndìng cānsàizhě de niánlíng zài shíbā suì yǐxià.","vi":"Cuộc thi lần này giới hạn tuổi thí sinh dưới mười tám."},{"type":"compound","zh":"虽然题目限定了范围，但是你可以自由发挥。","pinyin":"Suīrán tímù xiàndìngle fànwéi, dànshì nǐ kěyǐ zìyóu fāhuī.","vi":"Tuy đề bài đã giới hạn phạm vi nhưng bạn có thể tự do phát huy."}],"related":[{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"},{"hanzi":"限度","pinyin":"xiàndù","vi":"giới hạn"},{"hanzi":"限量","pinyin":"xiànliàng","vi":"giới hạn số lượng"}]},{"id":"限度","hanzi":"限度","pinyin":"xiàndù","meaning_vi":"giới hạn, mức độ tối đa","explanation":"限 (hạn – giới hạn) + 度 (độ – mức) → mức giới hạn không thể vượt quá.","hsk_level":"7-9","tags":["danh-tu"],"image":"📊","examples":[{"type":"basic","zh":"忍耐是有限度的。","pinyin":"Rěnnài shì yǒu xiàndù de.","vi":"Sự nhẫn nại là có giới hạn."},{"type":"simple","zh":"我们要把损失降到最低限度。","pinyin":"Wǒmen yào bǎ sǔnshī jiàng dào zuì dī xiàndù.","vi":"Chúng ta phải giảm tổn thất xuống mức thấp nhất."},{"type":"compound","zh":"即使你心里再生气，说话也要有个限度。","pinyin":"Jíshǐ nǐ xīnlǐ zài shēngqì, shuōhuà yě yàoyǒu ge xiàndù.","vi":"Dù trong lòng bạn giận đến đâu thì nói năng cũng phải có giới hạn."}],"related":[{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"},{"hanzi":"极限","pinyin":"jíxiàn","vi":"cực hạn"},{"hanzi":"程度","pinyin":"chéngdù","vi":"mức độ"},{"hanzi":"范围","pinyin":"fànwéi","vi":"phạm vi"}]},{"id":"限于","hanzi":"限于","pinyin":"xiànyú","meaning_vi":"giới hạn ở, chỉ trong phạm vi","explanation":"限 (hạn – giới hạn) + 于 (vu – ở) → bị giới hạn trong một phạm vi nhất định.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔒","examples":[{"type":"basic","zh":"名额限于十人。","pinyin":"Míng'é xiànyú shí rén.","vi":"Số suất giới hạn ở mười người."},{"type":"simple","zh":"本次优惠仅限于新会员。","pinyin":"Běn cì yōuhuì jǐn xiànyú xīn huìyuán.","vi":"Ưu đãi lần này chỉ dành cho hội viên mới."},{"type":"compound","zh":"由于篇幅限于三千字，所以我只能写重点。","pinyin":"Yóuyú piānfú xiànyú sān qiān zì, suǒyǐ wǒ zhǐnéng xiě zhòngdiǎn.","vi":"Vì độ dài giới hạn ở ba nghìn chữ nên tôi chỉ có thể viết ý chính."}],"related":[{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"},{"hanzi":"局限","pinyin":"júxiàn","vi":"bó hẹp"},{"hanzi":"仅限","pinyin":"jǐnxiàn","vi":"chỉ giới hạn"},{"hanzi":"限定","pinyin":"xiàndìng","vi":"hạn định"}],"traditional":"限於"},{"id":"陷","hanzi":"陷","pinyin":"xiàn","meaning_vi":"lún, sa vào, rơi vào","explanation":"陷 (hãm – sa xuống, lún): rơi vào chỗ trũng hoặc vào tình thế khó khăn; cũng có nghĩa là cạm bẫy.","hsk_level":"7-9","tags":["dong-tu"],"image":"🕳️","examples":[{"type":"basic","zh":"车轮陷进了泥里。","pinyin":"Chēlún xiàn jìnle ní lǐ.","vi":"Bánh xe bị lún vào bùn."},{"type":"simple","zh":"公司因为资金问题陷入了危机。","pinyin":"Gōngsī yīnwèi zījīn wèntí xiànrùle wēijī.","vi":"Công ty rơi vào khủng hoảng vì vấn đề vốn."},{"type":"compound","zh":"如果你再往前走，脚就会陷进沼泽里。","pinyin":"Rúguǒ nǐ zài wǎng qián zǒu, jiǎo jiù huì xiàn jìn zhǎozé lǐ.","vi":"Nếu bạn đi tiếp về phía trước thì chân sẽ lún vào đầm lầy."}],"related":[{"hanzi":"陷入","pinyin":"xiànrù","vi":"rơi vào"},{"hanzi":"陷阱","pinyin":"xiànjǐng","vi":"cạm bẫy"},{"hanzi":"塌陷","pinyin":"tāxiàn","vi":"sụt lún"},{"hanzi":"缺陷","pinyin":"quēxiàn","vi":"khuyết điểm"}]},{"id":"陷阱","hanzi":"陷阱","pinyin":"xiànjǐng","meaning_vi":"cạm bẫy, bẫy","explanation":"陷 (hãm – sa xuống) + 阱 (tỉnh – hố bẫy) → hố bẫy để bắt thú; nghĩa bóng là mưu kế lừa người.","hsk_level":"7-9","tags":["danh-tu"],"image":"🪤","examples":[{"type":"basic","zh":"这是一个陷阱。","pinyin":"Zhè shì yí gè xiànjǐng.","vi":"Đây là một cái bẫy."},{"type":"simple","zh":"猎人在树林里挖了一个陷阱。","pinyin":"Lièrén zài shùlín lǐ wāle yí gè xiànjǐng.","vi":"Người thợ săn đào một cái bẫy trong rừng."},{"type":"compound","zh":"如果你相信这种广告，就很容易掉进陷阱。","pinyin":"Rúguǒ nǐ xiāngxìn zhè zhǒng guǎnggào, jiù hěn róngyì diào jìn xiànjǐng.","vi":"Nếu bạn tin loại quảng cáo này thì rất dễ sập bẫy."}],"related":[{"hanzi":"圈套","pinyin":"quāntào","vi":"cái bẫy"},{"hanzi":"骗局","pinyin":"piànjú","vi":"trò lừa"},{"hanzi":"陷","pinyin":"xiàn","vi":"sa vào"},{"hanzi":"上当","pinyin":"shàngdàng","vi":"mắc lừa"}]},{"id":"献血","hanzi":"献血","pinyin":"xiànxuè","meaning_vi":"hiến máu","explanation":"献 (hiến – dâng tặng) + 血 (huyết – máu) → hiến máu để cứu người.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩸","examples":[{"type":"basic","zh":"他每年都献血。","pinyin":"Tā měinián dōu xiànxuè.","vi":"Năm nào anh ấy cũng hiến máu."},{"type":"simple","zh":"很多大学生主动到医院献血。","pinyin":"Hěn duōdà xuéshēng zhǔdòng dào yīyuàn xiànxuè.","vi":"Nhiều sinh viên chủ động đến bệnh viện hiến máu."},{"type":"compound","zh":"只要身体健康，就可以定期参加献血。","pinyin":"Zhǐyào shēntǐ jiànkāng, jiù kěyǐ dìngqī cānjiā xiànxuè.","vi":"Chỉ cần sức khỏe tốt là có thể tham gia hiến máu định kỳ."}],"related":[{"hanzi":"鲜血","pinyin":"xiānxuè","vi":"máu tươi"},{"hanzi":"输血","pinyin":"shūxuè","vi":"truyền máu"},{"hanzi":"捐献","pinyin":"juānxiàn","vi":"quyên tặng"},{"hanzi":"献","pinyin":"xiàn","vi":"dâng hiến"}],"traditional":"獻血"},{"id":"腺","hanzi":"腺","pinyin":"xiàn","meaning_vi":"tuyến (trong cơ thể)","explanation":"腺 (tuyến): cơ quan trong cơ thể tiết ra các chất như mồ hôi, nước bọt, hoóc-môn.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🔬","examples":[{"type":"basic","zh":"汗腺能排出汗水。","pinyin":"Hànxiàn néng páichū hànshuǐ.","vi":"Tuyến mồ hôi có thể tiết ra mồ hôi."},{"type":"simple","zh":"医生说她的甲状腺有点儿问题。","pinyin":"Yīshēng shuō tā de jiǎzhuàngxiàn yǒudiǎnr wèntí.","vi":"Bác sĩ nói tuyến giáp của cô ấy có chút vấn đề."},{"type":"compound","zh":"如果淋巴腺肿了，就要及时去医院检查。","pinyin":"Rúguǒ línbāxiàn zhǒng le, jiùyào jíshí qù yīyuàn jiǎnchá.","vi":"Nếu tuyến bạch huyết bị sưng thì phải kịp thời đến bệnh viện kiểm tra."}],"related":[{"hanzi":"汗腺","pinyin":"hànxiàn","vi":"tuyến mồ hôi"},{"hanzi":"甲状腺","pinyin":"jiǎzhuàngxiàn","vi":"tuyến giáp"},{"hanzi":"腺体","pinyin":"xiàntǐ","vi":"tuyến"},{"hanzi":"淋巴腺","pinyin":"línbāxiàn","vi":"tuyến bạch huyết"}]},{"id":"仙鹤","hanzi":"仙鹤","pinyin":"xiānhè","meaning_vi":"hạc đầu đỏ, tiên hạc","explanation":"仙 (tiên – thần tiên) + 鹤 (hạc – chim hạc) → loài hạc đầu đỏ, trong văn hóa Trung Hoa tượng trưng cho sự trường thọ.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦢","examples":[{"type":"basic","zh":"湖边飞来一只仙鹤。","pinyin":"Húbiān fēi lái yì zhī xiānhè.","vi":"Một con hạc bay đến bên hồ."},{"type":"simple","zh":"在中国画里，仙鹤常常代表长寿。","pinyin":"Zài Zhōngguóhuà lǐ, xiānhè chángcháng dàibiǎo chángshòu.","vi":"Trong tranh Trung Quốc, chim hạc thường tượng trưng cho trường thọ."},{"type":"compound","zh":"虽然仙鹤很少见，但是在这片湿地里能看到。","pinyin":"Suīrán xiānhè hěn shǎojiàn, dànshì zài zhè piàn shīdì lǐ néng kàndào.","vi":"Tuy hạc đầu đỏ rất hiếm nhưng ở vùng đất ngập nước này có thể thấy."}],"related":[{"hanzi":"鹤","pinyin":"hè","vi":"chim hạc"},{"hanzi":"丹顶鹤","pinyin":"dāndǐnghè","vi":"hạc đầu đỏ"},{"hanzi":"神仙","pinyin":"shénxiān","vi":"thần tiên"},{"hanzi":"长寿","pinyin":"chángshòu","vi":"trường thọ"}],"traditional":"仙鶴"},{"id":"仙女","hanzi":"仙女","pinyin":"xiānnǚ","meaning_vi":"tiên nữ, nàng tiên","explanation":"仙 (tiên – thần tiên) + 女 (nữ – con gái) → người con gái nơi tiên giới; còn dùng để khen cô gái xinh đẹp.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧚","examples":[{"type":"basic","zh":"她美得像仙女。","pinyin":"Tā měi de xiàng xiānnǚ.","vi":"Cô ấy đẹp như tiên nữ."},{"type":"simple","zh":"奶奶给我讲了一个仙女下凡的故事。","pinyin":"Nǎinai gěi wǒ jiǎngle yí gè xiānnǚ xiàfán de gùshi.","vi":"Bà kể cho tôi nghe câu chuyện tiên nữ giáng trần."},{"type":"compound","zh":"虽然只是一个童话，但是孩子们都相信仙女真的存在。","pinyin":"Suīrán zhǐshì yí gè tónghuà, dànshì háizimen dōu xiāngxìn xiānnǚ zhēn de cúnzài.","vi":"Tuy chỉ là truyện cổ tích nhưng bọn trẻ đều tin nàng tiên có thật."}],"related":[{"hanzi":"神仙","pinyin":"shénxiān","vi":"thần tiên"},{"hanzi":"仙鹤","pinyin":"xiānhè","vi":"tiên hạc"},{"hanzi":"天使","pinyin":"tiānshǐ","vi":"thiên thần"},{"hanzi":"童话","pinyin":"tónghuà","vi":"truyện cổ tích"}]},{"id":"乡亲","hanzi":"乡亲","pinyin":"xiāngqīn","meaning_vi":"bà con đồng hương, bà con làng xóm","explanation":"乡 (hương – quê) + 亲 (thân – người thân) → những người cùng quê, thân thiết như người nhà.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏘️","examples":[{"type":"basic","zh":"乡亲们都来帮忙。","pinyin":"Xiāngqīnmen dōu lái bāngmáng.","vi":"Bà con trong làng đều đến giúp."},{"type":"simple","zh":"他把赚来的钱用来给乡亲们修路。","pinyin":"Tā bǎ zhuàn lái de qián yònglái gěi xiāngqīnmen xiūlù.","vi":"Anh ấy dùng tiền kiếm được để làm đường cho bà con."},{"type":"compound","zh":"虽然他离开家乡很多年了，但是乡亲们还记得他。","pinyin":"Suīrán tā líkāi jiāxiāng hěn duōnián le, dànshì xiāngqīnmen hái jìde tā.","vi":"Tuy anh ấy rời quê nhiều năm nhưng bà con vẫn còn nhớ anh."}],"related":[{"hanzi":"老乡","pinyin":"lǎoxiāng","vi":"đồng hương"},{"hanzi":"家乡","pinyin":"jiāxiāng","vi":"quê nhà"},{"hanzi":"乡下","pinyin":"xiāngxia","vi":"nông thôn"},{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"}],"traditional":"鄉親"},{"id":"乡下","hanzi":"乡下","pinyin":"xiāngxia","meaning_vi":"nông thôn, vùng quê","explanation":"乡 (hương – làng quê) + 下 (hạ – nơi, phía dưới) → vùng quê, nông thôn.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🌾","examples":[{"type":"basic","zh":"我奶奶住在乡下。","pinyin":"Wǒ nǎinai zhùzài xiāngxia.","vi":"Bà tôi sống ở quê."},{"type":"simple","zh":"暑假我们去乡下看外公外婆。","pinyin":"Shǔjià wǒmen qù xiāngxia kàn wàigōng wàipó.","vi":"Kỳ nghỉ hè chúng tôi về quê thăm ông bà ngoại."},{"type":"compound","zh":"虽然乡下没有城里方便，但是空气特别新鲜。","pinyin":"Suīrán xiāngxia méiyǒu chénglǐ fāngbiàn, dànshì kōngqì tèbié xīnxiān.","vi":"Tuy nông thôn không tiện bằng thành phố nhưng không khí rất trong lành."}],"related":[{"hanzi":"农村","pinyin":"nóngcūn","vi":"nông thôn"},{"hanzi":"城里","pinyin":"chénglǐ","vi":"trong thành phố"},{"hanzi":"乡亲","pinyin":"xiāngqīn","vi":"bà con đồng hương"},{"hanzi":"下乡","pinyin":"xiàxiāng","vi":"về nông thôn"}],"traditional":"鄉下"},{"id":"相伴","hanzi":"相伴","pinyin":"xiāngbàn","meaning_vi":"bầu bạn, đồng hành cùng nhau","explanation":"相 (tương – lẫn nhau) + 伴 (bạn – bầu bạn) → ở bên nhau, làm bạn với nhau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"两人一生相伴。","pinyin":"Liǎng rén yìshēng xiāngbàn.","vi":"Hai người bên nhau suốt đời."},{"type":"simple","zh":"这只小狗与老人相伴了十年。","pinyin":"Zhè zhī xiǎogǒu yǔ lǎorén xiāngbànle shí nián.","vi":"Chú chó nhỏ này đã bầu bạn với ông cụ mười năm."},{"type":"compound","zh":"即使生活再艰难，只要有家人相伴，我也不怕。","pinyin":"Jíshǐ shēnghuó zài jiānnán, zhǐyào yǒu jiārén xiāngbàn, wǒ yě bú pà.","vi":"Dù cuộc sống khó khăn đến đâu, chỉ cần có gia đình bên cạnh thì tôi cũng không sợ."}],"related":[{"hanzi":"陪伴","pinyin":"péibàn","vi":"bầu bạn"},{"hanzi":"伙伴","pinyin":"huǒbàn","vi":"bạn đồng hành"},{"hanzi":"作伴","pinyin":"zuòbàn","vi":"làm bạn"},{"hanzi":"相随","pinyin":"xiāngsuí","vi":"đi theo nhau"}]},{"id":"相比之下","hanzi":"相比之下","pinyin":"xiāngbǐzhīxià","meaning_vi":"so ra thì, khi so sánh thì","explanation":"相比 (tương tỉ – so với nhau) + 之下 (chi hạ – trong điều kiện đó) → khi đem ra so sánh thì...; thường đứng đầu câu để chuyển ý.","hsk_level":"7-9","tags":["lien-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"相比之下，这个更好。","pinyin":"Xiāngbǐzhīxià, zhè ge gèng hǎo.","vi":"So ra thì cái này tốt hơn."},{"type":"simple","zh":"相比之下，乡下的生活节奏慢得多。","pinyin":"Xiāngbǐzhīxià, xiāngxia de shēnghuó jiézòu màn de duō.","vi":"So ra thì nhịp sống ở nông thôn chậm hơn nhiều."},{"type":"compound","zh":"虽然这家店贵一点儿，但是相比之下质量好多了。","pinyin":"Suīrán zhè jiā diàn guì yìdiǎnr, dànshì xiāngbǐzhīxià zhìliàng hǎoduō le.","vi":"Tuy cửa hàng này đắt hơn một chút nhưng so ra chất lượng tốt hơn nhiều."}],"related":[{"hanzi":"相比","pinyin":"xiāngbǐ","vi":"so với"},{"hanzi":"比较","pinyin":"bǐjiào","vi":"so sánh"},{"hanzi":"对比","pinyin":"duìbǐ","vi":"đối chiếu"},{"hanzi":"相对而言","pinyin":"xiāngduì'éryán","vi":"nói một cách tương đối"}]},{"id":"相传","hanzi":"相传","pinyin":"xiāngchuán","meaning_vi":"tương truyền, truyền lại","explanation":"相 (tương – nối tiếp nhau) + 传 (truyền – truyền lại) → truyền từ đời này sang đời khác; dùng như \"tương truyền rằng...\".","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"相传这里有龙。","pinyin":"Xiāngchuán zhèlǐ yǒu lóng.","vi":"Tương truyền nơi đây có rồng."},{"type":"simple","zh":"相传这座古桥是一位和尚修建的。","pinyin":"Xiāngchuán zhè zuò gǔ qiáo shì yí wèi héshang xiūjiàn de.","vi":"Tương truyền cây cầu cổ này do một nhà sư xây dựng."},{"type":"compound","zh":"虽然只是相传的故事，但是村里人都相信。","pinyin":"Suīrán zhǐshì xiāngchuán de gùshi, dànshì cūn lǐrén dōu xiāngxìn.","vi":"Tuy chỉ là câu chuyện truyền miệng nhưng người trong làng đều tin."}],"related":[{"hanzi":"传说","pinyin":"chuánshuō","vi":"truyền thuyết"},{"hanzi":"流传","pinyin":"liúchuán","vi":"lưu truyền"},{"hanzi":"世代","pinyin":"shìdài","vi":"đời đời"},{"hanzi":"传统","pinyin":"chuántǒng","vi":"truyền thống"}],"traditional":"相傳"},{"id":"相当于","hanzi":"相当于","pinyin":"xiāngdāngyú","meaning_vi":"tương đương với","explanation":"相当 (tương đương – ngang nhau) + 于 (vu – với) → ngang bằng với, tương đương với.","hsk_level":"7-9","tags":["dong-tu"],"image":"🟰","examples":[{"type":"basic","zh":"一元相当于十角。","pinyin":"Yìyuán xiāngdāngyú shí jiǎo.","vi":"Một tệ tương đương với mười hào."},{"type":"simple","zh":"这块地相当于两个足球场那么大。","pinyin":"Zhè kuài dì xiāngdāngyú liǎng gè zúqiúchǎng nàme dà.","vi":"Mảnh đất này rộng tương đương hai sân bóng đá."},{"type":"compound","zh":"如果你每天省十块钱，一年就相当于省了三千多块。","pinyin":"Rúguǒ nǐ měitiān shěng shí kuài qián, yì nián jiù xiāngdāngyú shěngle sān qiān duō kuài.","vi":"Nếu mỗi ngày bạn tiết kiệm mười tệ thì một năm tương đương tiết kiệm hơn ba nghìn."}],"related":[{"hanzi":"相当","pinyin":"xiāngdāng","vi":"tương đương"},{"hanzi":"等于","pinyin":"děngyú","vi":"bằng"},{"hanzi":"相等","pinyin":"xiāngděng","vi":"ngang nhau"},{"hanzi":"差不多","pinyin":"chàbuduō","vi":"xấp xỉ"}],"traditional":"相當於"},{"id":"相对","hanzi":"相对","pinyin":"xiāngduì","meaning_vi":"tương đối; đối diện nhau","explanation":"相 (tương – lẫn nhau) + 对 (đối – đối diện) → đối diện nhau; nghĩa thường dùng là \"tương đối, so ra thì\".","hsk_level":"7-9","tags":["pho-tu"],"image":"↔️","examples":[{"type":"basic","zh":"这里房价相对便宜。","pinyin":"Zhèlǐ fángjià xiāngduì piányi.","vi":"Giá nhà ở đây tương đối rẻ."},{"type":"simple","zh":"两座大楼隔着马路遥遥相对。","pinyin":"Liǎng zuò dàlóu gézhe mǎlù yáoyáo xiāngduì.","vi":"Hai tòa nhà đối diện nhau qua con đường."},{"type":"compound","zh":"虽然这份工作工资相对低，但是很稳定。","pinyin":"Suīrán zhè fèn gōngzuò gōngzī xiāngduì dī, dànshì hěn wěndìng.","vi":"Tuy công việc này lương tương đối thấp nhưng rất ổn định."}],"related":[{"hanzi":"绝对","pinyin":"juéduì","vi":"tuyệt đối"},{"hanzi":"相对而言","pinyin":"xiāngduì'éryán","vi":"nói tương đối"},{"hanzi":"比较","pinyin":"bǐjiào","vi":"khá, tương đối"},{"hanzi":"对面","pinyin":"duìmiàn","vi":"đối diện"}],"traditional":"相對"},{"id":"相对而言","hanzi":"相对而言","pinyin":"xiāngduì'éryán","meaning_vi":"nói một cách tương đối, so ra mà nói","explanation":"相对 (tương đối) + 而言 (nhi ngôn – mà nói) → xét một cách tương đối, khi so sánh mà nói.","hsk_level":"7-9","tags":["lien-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"相对而言，这样更安全。","pinyin":"Xiāngduì'éryán, zhèyàng gèng ānquán.","vi":"Nói một cách tương đối thì làm vậy an toàn hơn."},{"type":"simple","zh":"相对而言，坐火车比坐飞机便宜。","pinyin":"Xiāngduì'éryán, zuò huǒchē bǐ zuòfēijī piányi.","vi":"So ra mà nói, đi tàu hỏa rẻ hơn đi máy bay."},{"type":"compound","zh":"虽然两种方法都可以，但是相对而言第一种更简单。","pinyin":"Suīrán liǎng zhǒng fāngfǎ dōu kěyǐ, dànshì xiāngduì'éryán dìyī zhǒng gèng jiǎndān.","vi":"Tuy cả hai cách đều được nhưng xét tương đối thì cách thứ nhất đơn giản hơn."}],"related":[{"hanzi":"相对","pinyin":"xiāngduì","vi":"tương đối"},{"hanzi":"相比之下","pinyin":"xiāngbǐzhīxià","vi":"so ra thì"},{"hanzi":"总的来说","pinyin":"zǒngdeláishuō","vi":"nói chung"},{"hanzi":"一般来说","pinyin":"yìbānláishuō","vi":"thông thường mà nói"}],"traditional":"相對而言"},{"id":"相连","hanzi":"相连","pinyin":"xiānglián","meaning_vi":"nối liền, liền nhau","explanation":"相 (tương – lẫn nhau) + 连 (liên – nối) → nối liền với nhau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"两个房间相连。","pinyin":"Liǎng gè fángjiān xiānglián.","vi":"Hai căn phòng liền nhau."},{"type":"simple","zh":"一座大桥把两个城市紧紧相连。","pinyin":"Yí zuò Dàqiáo bǎ liǎng gè chéngshì jǐnjǐn xiānglián.","vi":"Một cây cầu lớn nối chặt hai thành phố với nhau."},{"type":"compound","zh":"因为两国山水相连，所以自古以来交往频繁。","pinyin":"Yīnwèi liǎngguó shānshuǐ xiānglián, suǒyǐ zìgǔ yǐlái jiāowǎng pínfán.","vi":"Vì hai nước núi sông liền nhau nên từ xưa đã qua lại thường xuyên."}],"related":[{"hanzi":"连接","pinyin":"liánjiē","vi":"nối liền"},{"hanzi":"相通","pinyin":"xiāngtōng","vi":"thông nhau"},{"hanzi":"相邻","pinyin":"xiānglín","vi":"liền kề"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"}],"traditional":"相連"},{"id":"相通","hanzi":"相通","pinyin":"xiāngtōng","meaning_vi":"thông nhau, tương thông","explanation":"相 (tương – lẫn nhau) + 通 (thông – thông suốt) → thông với nhau; nghĩa bóng là có điểm chung, hiểu được nhau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚪","examples":[{"type":"basic","zh":"这两条河是相通的。","pinyin":"Zhè liǎng tiáo hé shì xiāngtōng de.","vi":"Hai con sông này thông với nhau."},{"type":"simple","zh":"不同国家的人在情感上是相通的。","pinyin":"Bùtóng guójiā de rén zài qínggǎn shang shì xiāngtōng de.","vi":"Người các nước khác nhau đều có tình cảm chung."},{"type":"compound","zh":"虽然两种语言差别很大，但是很多道理是相通的。","pinyin":"Suīrán liǎng zhǒng yǔyán chābié hěn dà, dànshì hěn duō dàolǐ shì xiāngtōng de.","vi":"Tuy hai ngôn ngữ khác nhau nhiều nhưng nhiều đạo lý là tương thông."}],"related":[{"hanzi":"相连","pinyin":"xiānglián","vi":"nối liền"},{"hanzi":"沟通","pinyin":"gōutōng","vi":"giao tiếp"},{"hanzi":"共通","pinyin":"gòngtōng","vi":"chung, thông nhau"},{"hanzi":"心灵相通","pinyin":"xīnlíngxiāngtōng","vi":"tâm hồn đồng điệu"}]},{"id":"相遇","hanzi":"相遇","pinyin":"xiāngyù","meaning_vi":"gặp nhau, gặp gỡ","explanation":"相 (tương – lẫn nhau) + 遇 (ngộ – gặp) → gặp nhau, thường là tình cờ gặp gỡ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👫","examples":[{"type":"basic","zh":"我们在车站相遇。","pinyin":"Wǒmen zài chēzhàn xiāngyù.","vi":"Chúng tôi gặp nhau ở nhà ga."},{"type":"simple","zh":"他们第一次相遇是在一家书店里。","pinyin":"Tāmen dìyīcì xiāngyù shì zài yìjiā shūdiàn lǐ.","vi":"Lần đầu họ gặp nhau là ở một hiệu sách."},{"type":"compound","zh":"如果那天我没有迟到，我们也许就不会相遇。","pinyin":"Rúguǒ nà tiān wǒ méiyǒu chídào, wǒmen yěxǔ jiù bú huì xiāngyù.","vi":"Nếu hôm đó tôi không đến muộn thì có lẽ chúng ta đã không gặp nhau."}],"related":[{"hanzi":"遇见","pinyin":"yùjiàn","vi":"gặp"},{"hanzi":"相识","pinyin":"xiāngshí","vi":"quen biết"},{"hanzi":"重逢","pinyin":"chóngféng","vi":"gặp lại"},{"hanzi":"偶遇","pinyin":"ǒuyù","vi":"tình cờ gặp"}]},{"id":"相约","hanzi":"相约","pinyin":"xiāngyuē","meaning_vi":"hẹn nhau","explanation":"相 (tương – lẫn nhau) + 约 (ước – hẹn) → hẹn với nhau.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📆","examples":[{"type":"basic","zh":"我们相约明天见。","pinyin":"Wǒmen xiāngyuē míngtiānjiàn.","vi":"Chúng tôi hẹn nhau mai gặp."},{"type":"simple","zh":"老同学们相约周末一起去爬山。","pinyin":"Lǎo tóngxuémen xiāngyuē zhōumò yìqǐ qù páshān.","vi":"Các bạn học cũ hẹn nhau cuối tuần cùng đi leo núi."},{"type":"compound","zh":"虽然我们相约十年后再见，但是谁也没想到会这么快。","pinyin":"Suīrán wǒmen xiāngyuē shí nián hòu zàijiàn, dànshì shéi yě méi xiǎngdào huì zhème kuài.","vi":"Tuy chúng tôi hẹn mười năm sau gặp lại nhưng không ai ngờ lại nhanh thế."}],"related":[{"hanzi":"约会","pinyin":"yuēhuì","vi":"hẹn hò"},{"hanzi":"约定","pinyin":"yuēdìng","vi":"giao hẹn"},{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"mời"},{"hanzi":"相会","pinyin":"xiānghuì","vi":"gặp nhau"}],"traditional":"相約"},{"id":"香料","hanzi":"香料","pinyin":"xiāngliào","meaning_vi":"gia vị, hương liệu","explanation":"香 (hương – thơm) + 料 (liệu – nguyên liệu) → chất tạo mùi thơm cho thức ăn hoặc nước hoa.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🌶️","examples":[{"type":"basic","zh":"这道菜放了很多香料。","pinyin":"Zhè dào cài fàngle hěn duō xiāngliào.","vi":"Món này cho rất nhiều gia vị."},{"type":"simple","zh":"印度菜常常用到各种香料。","pinyin":"Yìndù cài cháng chángyòng dào gèzhǒng xiāngliào.","vi":"Món Ấn Độ thường dùng đủ loại gia vị."},{"type":"compound","zh":"如果香料放得太多，菜的原味就没有了。","pinyin":"Rúguǒ xiāngliào fàng de tài duō, cài de yuánwèi jiù méiyǒu le.","vi":"Nếu cho quá nhiều gia vị thì món ăn sẽ mất vị gốc."}],"related":[{"hanzi":"调料","pinyin":"tiáoliào","vi":"gia vị"},{"hanzi":"香味","pinyin":"xiāngwèi","vi":"mùi thơm"},{"hanzi":"胡椒","pinyin":"hújiāo","vi":"hạt tiêu"},{"hanzi":"香水","pinyin":"xiāngshuǐ","vi":"nước hoa"}]},{"id":"香水","hanzi":"香水","pinyin":"xiāngshuǐ","meaning_vi":"nước hoa","explanation":"香 (hương – thơm) + 水 (thủy – nước) → nước thơm, tức nước hoa.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🧴","examples":[{"type":"basic","zh":"她喜欢用香水。","pinyin":"Tā xǐhuan yòng xiāngshuǐ.","vi":"Cô ấy thích dùng nước hoa."},{"type":"simple","zh":"他给女朋友买了一瓶法国香水。","pinyin":"Tā gěi nǚpéngyou mǎile yì píng Fǎguó xiāngshuǐ.","vi":"Anh ấy mua cho bạn gái một chai nước hoa Pháp."},{"type":"compound","zh":"虽然这瓶香水很贵，但是味道特别好闻。","pinyin":"Suīrán zhè píng xiāngshuǐ hěn guì, dànshì wèidào tèbié hǎo wén.","vi":"Tuy chai nước hoa này rất đắt nhưng mùi rất dễ chịu."}],"related":[{"hanzi":"香味","pinyin":"xiāngwèi","vi":"mùi thơm"},{"hanzi":"香料","pinyin":"xiāngliào","vi":"hương liệu"},{"hanzi":"化妆品","pinyin":"huàzhuāngpǐn","vi":"mỹ phẩm"},{"hanzi":"喷","pinyin":"pēn","vi":"xịt"}]},{"id":"香味","hanzi":"香味","pinyin":"xiāngwèi","meaning_vi":"mùi thơm, hương thơm","explanation":"香 (hương – thơm) + 味 (vị – mùi) → mùi thơm.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"👃","examples":[{"type":"basic","zh":"厨房里飘出香味。","pinyin":"Chúfáng lǐ piāo chū xiāngwèi.","vi":"Mùi thơm bay ra từ trong bếp."},{"type":"simple","zh":"面包店里充满了刚出炉面包的香味。","pinyin":"Miànbāodiàn lǐ chōngmǎnle gāng chūlú miànbāo de xiāngwèi.","vi":"Tiệm bánh tràn ngập mùi thơm của bánh mì vừa ra lò."},{"type":"compound","zh":"我一闻到咖啡的香味，就马上精神了。","pinyin":"Wǒ yì wéndào kāfēi de xiāngwèi, jiù mǎshàng jīngshen le.","vi":"Tôi vừa ngửi thấy mùi cà phê là tỉnh táo ngay."}],"related":[{"hanzi":"香","pinyin":"xiāng","vi":"thơm"},{"hanzi":"气味","pinyin":"qìwèi","vi":"mùi"},{"hanzi":"臭味","pinyin":"chòuwèi","vi":"mùi hôi"},{"hanzi":"香水","pinyin":"xiāngshuǐ","vi":"nước hoa"}]},{"id":"香烟","hanzi":"香烟","pinyin":"xiāngyān","meaning_vi":"thuốc lá (điếu)","explanation":"香 (hương – thơm) + 烟 (yên – khói) → điếu thuốc lá; nghĩa gốc là khói hương.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🚬","examples":[{"type":"basic","zh":"他买了一包香烟。","pinyin":"Tā mǎile yì bāo xiāngyān.","vi":"Anh ấy mua một bao thuốc lá."},{"type":"simple","zh":"医生劝他早点儿把香烟戒掉。","pinyin":"Yīshēng quàn tā zǎodiǎnr bǎ xiāngyān jièdiào.","vi":"Bác sĩ khuyên anh ấy sớm bỏ thuốc lá."},{"type":"compound","zh":"虽然他知道香烟对身体有害，但是总是戒不掉。","pinyin":"Suīrán tā zhīdào xiāngyān duì shēntǐ yǒuhài, dànshì zǒngshì jiè bu diào.","vi":"Tuy biết thuốc lá có hại cho sức khỏe nhưng anh ấy mãi không bỏ được."}],"related":[{"hanzi":"抽烟","pinyin":"chōuyān","vi":"hút thuốc"},{"hanzi":"吸烟","pinyin":"xīyān","vi":"hút thuốc"},{"hanzi":"戒烟","pinyin":"jièyān","vi":"cai thuốc"},{"hanzi":"烟灰缸","pinyin":"yānhuīgāng","vi":"gạt tàn"}],"traditional":"香煙"},{"id":"香油","hanzi":"香油","pinyin":"xiāngyóu","meaning_vi":"dầu mè, dầu vừng","explanation":"香 (hương – thơm) + 油 (du – dầu) → dầu thơm, thường chỉ dầu mè.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🫙","examples":[{"type":"basic","zh":"凉菜里加点香油。","pinyin":"Liángcài lǐ jiādiǎn xiāngyóu.","vi":"Cho chút dầu mè vào món nguội."},{"type":"simple","zh":"妈妈在饺子馅里滴了几滴香油。","pinyin":"Māma zài jiǎozi xiàn lǐ dīle jǐ dī xiāngyóu.","vi":"Mẹ nhỏ vài giọt dầu mè vào nhân sủi cảo."},{"type":"compound","zh":"只要放一点儿香油，这碗面就会香很多。","pinyin":"Zhǐyào fàng yìdiǎnr xiāngyóu, zhè wǎn miàn jiù huì xiāng hěn duō.","vi":"Chỉ cần cho một chút dầu mè là bát mì này sẽ thơm hơn nhiều."}],"related":[{"hanzi":"芝麻","pinyin":"zhīma","vi":"vừng, mè"},{"hanzi":"食用油","pinyin":"shíyòngyóu","vi":"dầu ăn"},{"hanzi":"酱油","pinyin":"jiàngyóu","vi":"xì dầu"},{"hanzi":"香料","pinyin":"xiāngliào","vi":"gia vị"}]},{"id":"镶","hanzi":"镶","pinyin":"xiāng","meaning_vi":"khảm, nạm, viền","explanation":"镶 (tương – khảm): gắn vật này vào vật kia hoặc viền quanh mép, như nạm đá quý vào nhẫn.","hsk_level":"7-9","tags":["dong-tu"],"image":"💍","examples":[{"type":"basic","zh":"戒指上镶着钻石。","pinyin":"Jièzhi shang xiāngzhe zuànshí.","vi":"Trên nhẫn có nạm kim cương."},{"type":"simple","zh":"工人在窗户上镶了一块新玻璃。","pinyin":"Gōngrén zài chuānghu shang xiāngle yíkuài xīn bōli.","vi":"Người thợ lắp một tấm kính mới vào cửa sổ."},{"type":"compound","zh":"虽然这颗牙是镶的，但是看起来和真的一样。","pinyin":"Suīrán zhè kē yá shì xiāng de, dànshì kànqǐlái hé zhēn de yíyàng.","vi":"Tuy chiếc răng này là răng bọc nhưng trông giống hệt răng thật."}],"related":[{"hanzi":"镶嵌","pinyin":"xiāngqiàn","vi":"khảm nạm"},{"hanzi":"镶边","pinyin":"xiāngbiān","vi":"viền mép"},{"hanzi":"钻石","pinyin":"zuànshí","vi":"kim cương"},{"hanzi":"装饰","pinyin":"zhuāngshì","vi":"trang trí"}],"traditional":"鑲"},{"id":"享","hanzi":"享","pinyin":"xiǎng","meaning_vi":"hưởng, tận hưởng","explanation":"享 (hưởng – được hưởng): nhận và tận hưởng lợi ích, niềm vui; thường gặp trong 享受, 分享.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥂","examples":[{"type":"basic","zh":"他们有福同享。","pinyin":"Tāmen yǒufú tóng xiǎng.","vi":"Họ có phúc cùng hưởng."},{"type":"simple","zh":"老人退休后在乡下安享晚年。","pinyin":"Lǎorén tuìxiū hòu zài xiāngxia ān xiǎng wǎnnián.","vi":"Ông cụ nghỉ hưu rồi về quê an hưởng tuổi già."},{"type":"compound","zh":"只要是公司的员工，就可以享有这项福利。","pinyin":"Zhǐ yàoshì gōngsī de yuángōng, jiù kěyǐ xiǎngyǒu zhè xiàng fúlì.","vi":"Chỉ cần là nhân viên công ty là được hưởng phúc lợi này."}],"related":[{"hanzi":"享受","pinyin":"xiǎngshòu","vi":"hưởng thụ"},{"hanzi":"分享","pinyin":"fēnxiǎng","vi":"chia sẻ"},{"hanzi":"享有","pinyin":"xiǎngyǒu","vi":"được hưởng"},{"hanzi":"共享","pinyin":"gòngxiǎng","vi":"dùng chung"}]},{"id":"响起","hanzi":"响起","pinyin":"xiǎngqǐ","meaning_vi":"vang lên, reo lên","explanation":"响 (hưởng – vang, kêu) + 起 (khởi – bắt đầu) → âm thanh bắt đầu vang lên.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔔","examples":[{"type":"basic","zh":"电话铃声响起。","pinyin":"Diànhuà língshēng xiǎngqǐ.","vi":"Chuông điện thoại reo lên."},{"type":"simple","zh":"全场响起了热烈的掌声。","pinyin":"Quánchǎng xiǎngqǐle rèliè de zhǎngshēng.","vi":"Cả hội trường vang lên tràng pháo tay nồng nhiệt."},{"type":"compound","zh":"下课铃一响起，学生们就冲出了教室。","pinyin":"Xiàkè líng yì xiǎngqǐ, xuéshengmen jiù chōngchūle jiàoshì.","vi":"Chuông tan học vừa reo, học sinh đã ùa ra khỏi lớp."}],"related":[{"hanzi":"响","pinyin":"xiǎng","vi":"kêu, vang"},{"hanzi":"铃声","pinyin":"língshēng","vi":"tiếng chuông"},{"hanzi":"回响","pinyin":"huíxiǎng","vi":"tiếng vọng"},{"hanzi":"传来","pinyin":"chuánlái","vi":"vọng tới"}],"traditional":"響起"},{"id":"向着","hanzi":"向着","pinyin":"xiàngzhe","meaning_vi":"hướng về; bênh vực, thiên vị","explanation":"向 (hướng – hướng về) + 着 (trợ từ) → hướng về phía; trong khẩu ngữ còn có nghĩa thiên vị, bênh vực ai.","hsk_level":"7-9","tags":["gioi-tu"],"image":"🧭","examples":[{"type":"basic","zh":"向着目标前进。","pinyin":"Xiàngzhe mùbiāo qiánjìn.","vi":"Tiến về phía mục tiêu."},{"type":"simple","zh":"向日葵总是向着太阳的方向。","pinyin":"Xiàng rì kuí zǒngshì xiàngzhe tàiyáng de fāngxiàng.","vi":"Hoa hướng dương luôn hướng về phía mặt trời."},{"type":"compound","zh":"虽然弟弟做错了，但是妈妈还是向着他。","pinyin":"Suīrán dìdi zuòcuò le, dànshì māma háishi xiàngzhe tā.","vi":"Tuy em trai làm sai nhưng mẹ vẫn bênh nó."}],"related":[{"hanzi":"朝着","pinyin":"cháozhe","vi":"hướng về"},{"hanzi":"向","pinyin":"xiàng","vi":"về phía"},{"hanzi":"偏向","pinyin":"piānxiàng","vi":"thiên vị"},{"hanzi":"面向","pinyin":"miànxiàng","vi":"hướng mặt về"}],"traditional":"向著"},{"id":"项链","hanzi":"项链","pinyin":"xiàngliàn","meaning_vi":"dây chuyền, vòng cổ","explanation":"项 (hạng – cổ, gáy) + 链 (liên – dây xích) → dây xích đeo ở cổ, tức dây chuyền.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"📿","examples":[{"type":"basic","zh":"她戴着珍珠项链。","pinyin":"Tā dàizhe zhēnzhū xiàngliàn.","vi":"Cô ấy đeo dây chuyền ngọc trai."},{"type":"simple","zh":"他送给妈妈一条金项链作为生日礼物。","pinyin":"Tā sònggěi māma yì tiáo jīn xiàngliàn zuòwéi shēngrì lǐwù.","vi":"Anh ấy tặng mẹ một sợi dây chuyền vàng làm quà sinh nhật."},{"type":"compound","zh":"虽然这条项链不贵，但是对她来说意义很大。","pinyin":"Suīrán zhè tiáo xiàngliàn bú guì, dànshì duì tā lái shuō yìyì hěn dà.","vi":"Tuy sợi dây chuyền này không đắt nhưng với cô ấy rất có ý nghĩa."}],"related":[{"hanzi":"戒指","pinyin":"jièzhi","vi":"nhẫn"},{"hanzi":"耳环","pinyin":"ěrhuán","vi":"hoa tai"},{"hanzi":"手链","pinyin":"shǒuliàn","vi":"vòng tay"},{"hanzi":"首饰","pinyin":"shǒushì","vi":"trang sức"}],"traditional":"項鍊"},{"id":"像样","hanzi":"像样","pinyin":"xiàngyàng","meaning_vi":"ra dáng, tươm tất, coi được","explanation":"像 (tượng – giống) + 样 (dạng – khuôn mẫu) → giống với khuôn mẫu, tức ra dáng, đạt chuẩn.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👌","examples":[{"type":"basic","zh":"这字写得很像样。","pinyin":"Zhè zì xiě de hěn xiàngyàng.","vi":"Chữ này viết rất ra dáng."},{"type":"simple","zh":"他连一件像样的衣服都没有。","pinyin":"Tā lián yí jiàn xiàngyàng de yīfu dōu méiyǒu.","vi":"Anh ấy đến một bộ quần áo tươm tất cũng không có."},{"type":"compound","zh":"虽然房子不大，但是收拾得挺像样的。","pinyin":"Suīrán fángzi búdà, dànshì shōushi de tǐng xiàngyàng de.","vi":"Tuy nhà không lớn nhưng được dọn dẹp khá tươm tất."}],"related":[{"hanzi":"体面","pinyin":"tǐmiàn","vi":"tươm tất"},{"hanzi":"样子","pinyin":"yàngzi","vi":"dáng vẻ"},{"hanzi":"不像话","pinyin":"búxiànghuà","vi":"chẳng ra gì"},{"hanzi":"得体","pinyin":"détǐ","vi":"đúng mực"}],"traditional":"像樣"},{"id":"橡胶","hanzi":"橡胶","pinyin":"xiàngjiāo","meaning_vi":"cao su","explanation":"橡 (tượng – cây cao su) + 胶 (giao – keo, nhựa) → nhựa của cây cao su, tức cao su.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🛞","examples":[{"type":"basic","zh":"轮胎是橡胶做的。","pinyin":"Lúntāi shì xiàngjiāo zuò de.","vi":"Lốp xe làm bằng cao su."},{"type":"simple","zh":"这双手套是用天然橡胶做的。","pinyin":"Zhè shuāng shǒutào shì yòng tiānrán xiàngjiāo zuò de.","vi":"Đôi găng tay này làm bằng cao su thiên nhiên."},{"type":"compound","zh":"因为橡胶有弹性，所以常用来做球和鞋底。","pinyin":"Yīnwèi xiàngjiāo yǒutánxìng, suǒyǐ cháng yònglái zuòqiú hé xiédǐ.","vi":"Vì cao su có tính đàn hồi nên thường được dùng làm bóng và đế giày."}],"related":[{"hanzi":"橡皮","pinyin":"xiàngpí","vi":"cục tẩy"},{"hanzi":"塑料","pinyin":"sùliào","vi":"nhựa"},{"hanzi":"轮胎","pinyin":"lúntāi","vi":"lốp xe"},{"hanzi":"弹性","pinyin":"tánxìng","vi":"tính đàn hồi"}],"traditional":"橡膠"},{"id":"消","hanzi":"消","pinyin":"xiāo","meaning_vi":"tan, tiêu tan, mất đi","explanation":"消 (tiêu – tan biến): làm cho mất dần đi như tan, tiêu, giảm; hay gặp trong 消失, 消气.","hsk_level":"7-9","tags":["dong-tu"],"image":"💨","examples":[{"type":"basic","zh":"他的气消了。","pinyin":"Tā de qì xiāo le.","vi":"Anh ấy đã nguôi giận."},{"type":"simple","zh":"脸上的肿过了两天才慢慢消下去。","pinyin":"Liǎn shang de zhǒngguò le liǎng tiāncái mànmàn xiāo xiàqù.","vi":"Chỗ sưng trên mặt hai ngày sau mới từ từ xẹp xuống."},{"type":"compound","zh":"虽然他道了歉，但是我心里的火还没消。","pinyin":"Suīrán tā dàole qiàn, dànshì wǒ xīnlǐ de huǒ hái méi xiāo.","vi":"Tuy anh ta đã xin lỗi nhưng cơn giận trong lòng tôi vẫn chưa nguôi."}],"related":[{"hanzi":"消失","pinyin":"xiāoshī","vi":"biến mất"},{"hanzi":"消除","pinyin":"xiāochú","vi":"loại bỏ"},{"hanzi":"取消","pinyin":"qǔxiāo","vi":"hủy bỏ"},{"hanzi":"消气","pinyin":"xiāoqì","vi":"nguôi giận"}]},{"id":"消沉","hanzi":"消沉","pinyin":"xiāochén","meaning_vi":"sa sút tinh thần, chán nản","explanation":"消 (tiêu – tiêu tan) + 沉 (trầm – chìm) → tinh thần tiêu tan, chìm xuống, tức chán nản, ủ rũ.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"他最近很消沉。","pinyin":"Tā zuìjìn hěn xiāochén.","vi":"Dạo này anh ấy rất chán nản."},{"type":"simple","zh":"失业以后他一直情绪消沉。","pinyin":"Shīyè yǐhòu tā yìzhí qíngxù xiāochén.","vi":"Sau khi thất nghiệp, anh ấy luôn ủ rũ."},{"type":"compound","zh":"虽然比赛输了，但是你不能因此意志消沉。","pinyin":"Suīrán bǐsài shū le, dànshì nǐ bù néng yīncǐ yìzhì xiāochén.","vi":"Tuy thua trận nhưng bạn không được vì thế mà suy sụp ý chí."}],"related":[{"hanzi":"低落","pinyin":"dīluò","vi":"sa sút"},{"hanzi":"沮丧","pinyin":"jǔsàng","vi":"chán nản"},{"hanzi":"振作","pinyin":"zhènzuò","vi":"phấn chấn"},{"hanzi":"颓废","pinyin":"tuífèi","vi":"suy sụp"}]},{"id":"消遣","hanzi":"消遣","pinyin":"xiāoqiǎn","meaning_vi":"giải trí, tiêu khiển","explanation":"消 (tiêu – tiêu hao) + 遣 (khiển – xua đi) → cho thời gian trôi qua, xua nỗi buồn chán, tức tiêu khiển.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎣","examples":[{"type":"basic","zh":"钓鱼是他的消遣。","pinyin":"Diàoyú shì tā de xiāoqiǎn.","vi":"Câu cá là thú tiêu khiển của ông ấy."},{"type":"simple","zh":"周末他常常看小说消遣。","pinyin":"Zhōumò tā chángcháng kàn xiǎoshuō xiāoqiǎn.","vi":"Cuối tuần anh ấy thường đọc tiểu thuyết để giải trí."},{"type":"compound","zh":"虽然只是为了消遣，但是他画的画越来越好。","pinyin":"Suīrán zhǐshì wèile xiāoqiǎn, dànshì tā huà de huà yuèláiyuè hǎo.","vi":"Tuy chỉ vẽ để giải trí nhưng tranh anh ấy vẽ ngày càng đẹp."}],"related":[{"hanzi":"娱乐","pinyin":"yúlè","vi":"giải trí"},{"hanzi":"休闲","pinyin":"xiūxián","vi":"thư giãn"},{"hanzi":"解闷","pinyin":"jiěmèn","vi":"giải buồn"},{"hanzi":"爱好","pinyin":"àihào","vi":"sở thích"}]},{"id":"销","hanzi":"销","pinyin":"xiāo","meaning_vi":"bán, tiêu thụ; hủy bỏ","explanation":"销 (tiêu – nung chảy kim loại): nghĩa phát triển thành tiêu thụ, bán hàng và hủy bỏ, như trong 销售, 注销.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这种茶销往国外。","pinyin":"Zhè zhǒng chá xiāo wǎng guówài.","vi":"Loại trà này được bán ra nước ngoài."},{"type":"simple","zh":"这款手机在年轻人中销得特别好。","pinyin":"Zhè kuǎn shǒujī zài niánqīng rénzhōng xiāo de tèbié hǎo.","vi":"Mẫu điện thoại này bán rất chạy trong giới trẻ."},{"type":"compound","zh":"如果产品质量不好，广告做得再多也很难销出去。","pinyin":"Rúguǒ chǎnpǐn zhìliàng bù hǎo, guǎnggào zuò de zài duō yě hěn nán xiāo chūqù.","vi":"Nếu chất lượng sản phẩm không tốt thì quảng cáo nhiều đến mấy cũng khó bán được."}],"related":[{"hanzi":"销售","pinyin":"xiāoshòu","vi":"bán hàng"},{"hanzi":"销量","pinyin":"xiāoliàng","vi":"lượng bán"},{"hanzi":"推销","pinyin":"tuīxiāo","vi":"chào hàng"},{"hanzi":"注销","pinyin":"zhùxiāo","vi":"hủy bỏ"}],"traditional":"銷"},{"id":"销量","hanzi":"销量","pinyin":"xiāoliàng","meaning_vi":"doanh số, lượng tiêu thụ","explanation":"销 (tiêu – tiêu thụ) + 量 (lượng – số lượng) → số lượng hàng bán ra.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"📈","examples":[{"type":"basic","zh":"今年销量增加了。","pinyin":"Jīnnián xiāoliàng zēngjiā le.","vi":"Năm nay lượng bán đã tăng."},{"type":"simple","zh":"这本小说的销量已经超过一百万册。","pinyin":"Zhè běn xiǎoshuō de xiāoliàng yǐjīng chāoguò yī bǎiwàn cè.","vi":"Lượng bán của cuốn tiểu thuyết này đã vượt quá một triệu bản."},{"type":"compound","zh":"因为广告做得好，所以新产品的销量一直很高。","pinyin":"Yīnwèi guǎnggào zuò de hǎo, suǒyǐ xīnchǎnpǐn de xiāoliàng yìzhí hěn gāo.","vi":"Vì quảng cáo làm tốt nên doanh số sản phẩm mới luôn rất cao."}],"related":[{"hanzi":"销售","pinyin":"xiāoshòu","vi":"bán hàng"},{"hanzi":"产量","pinyin":"chǎnliàng","vi":"sản lượng"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"},{"hanzi":"畅销","pinyin":"chàngxiāo","vi":"bán chạy"}],"traditional":"銷量"},{"id":"小丑","hanzi":"小丑","pinyin":"xiǎochǒu","meaning_vi":"chú hề; kẻ lố bịch","explanation":"小 (tiểu – nhỏ) + 丑 (sửu – vai hề trong kịch) → vai hề, chú hề; nghĩa bóng chỉ kẻ lố bịch.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🤡","examples":[{"type":"basic","zh":"孩子们喜欢小丑。","pinyin":"Háizimen xǐhuan xiǎochǒu.","vi":"Bọn trẻ thích chú hề."},{"type":"simple","zh":"马戏团的小丑逗得观众哈哈大笑。","pinyin":"Mǎxìtuán de xiǎochǒu dòu de guānzhòng hāhā dàxiào.","vi":"Chú hề của đoàn xiếc chọc khán giả cười ha hả."},{"type":"compound","zh":"虽然他在台上扮演小丑，但是台下是个很严肃的人。","pinyin":"Suīrán tā zài tái shang bànyǎn xiǎochǒu, dànshì táixià shì ge hěn yánsù de rén.","vi":"Tuy trên sân khấu anh ấy đóng vai hề nhưng ngoài đời là người rất nghiêm túc."}],"related":[{"hanzi":"马戏团","pinyin":"mǎxìtuán","vi":"đoàn xiếc"},{"hanzi":"滑稽","pinyin":"huájī","vi":"hài hước"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"丑角","pinyin":"chǒujué","vi":"vai hề"}]},{"id":"小贩","hanzi":"小贩","pinyin":"xiǎofàn","meaning_vi":"người bán hàng rong, tiểu thương","explanation":"小 (tiểu – nhỏ) + 贩 (phán – buôn bán) → người buôn bán nhỏ, bán hàng rong.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🛒","examples":[{"type":"basic","zh":"街上有很多小贩。","pinyin":"Jiēshang yǒu hěn duō xiǎofàn.","vi":"Trên phố có rất nhiều người bán hàng rong."},{"type":"simple","zh":"一个小贩在路边卖烤红薯。","pinyin":"Yí gè xiǎofàn zài lùbiān mài kǎohóngshǔ.","vi":"Một người bán hàng rong đang bán khoai lang nướng bên đường."},{"type":"compound","zh":"虽然小贩的东西很便宜，但是质量没有保证。","pinyin":"Suīrán xiǎofàn de dōngxi hěn piányi, dànshì zhìliàng méiyǒu bǎozhèng.","vi":"Tuy đồ của người bán rong rất rẻ nhưng chất lượng không được đảm bảo."}],"related":[{"hanzi":"摊贩","pinyin":"tānfàn","vi":"người bán quầy"},{"hanzi":"商贩","pinyin":"shāngfàn","vi":"tiểu thương"},{"hanzi":"摆摊","pinyin":"bǎitān","vi":"bày sạp"},{"hanzi":"叫卖","pinyin":"jiàomài","vi":"rao bán"}],"traditional":"小販"},{"id":"小看","hanzi":"小看","pinyin":"xiǎokàn","meaning_vi":"coi thường, xem nhẹ","explanation":"小 (tiểu – nhỏ) + 看 (khán – nhìn) → nhìn người hay việc là nhỏ bé, tức coi thường.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙄","examples":[{"type":"basic","zh":"别小看这个孩子。","pinyin":"Bié xiǎokàn zhè ge háizi.","vi":"Đừng coi thường đứa trẻ này."},{"type":"simple","zh":"你千万不要小看这次考试的难度。","pinyin":"Nǐ qiānwàn bú yào xiǎokàn zhè cì kǎoshì de nándù.","vi":"Bạn tuyệt đối đừng xem nhẹ độ khó của kỳ thi này."},{"type":"compound","zh":"虽然他个子不高，但是你不能小看他的力气。","pinyin":"Suīrán tā gèzi bù gāo, dànshì nǐ bù néng xiǎokàn tā de lìqi.","vi":"Tuy anh ấy không cao nhưng bạn không thể coi thường sức lực của anh ấy."}],"related":[{"hanzi":"看不起","pinyin":"kànbuqǐ","vi":"khinh thường"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"xem nhẹ"},{"hanzi":"低估","pinyin":"dīgū","vi":"đánh giá thấp"},{"hanzi":"重视","pinyin":"zhòngshì","vi":"coi trọng"}]},{"id":"小路","hanzi":"小路","pinyin":"xiǎolù","meaning_vi":"đường nhỏ, lối mòn","explanation":"小 (tiểu – nhỏ) + 路 (lộ – đường) → con đường nhỏ, lối mòn.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛤️","examples":[{"type":"basic","zh":"我们走小路吧。","pinyin":"Wǒmen zǒu xiǎolù ba.","vi":"Chúng ta đi đường nhỏ đi."},{"type":"simple","zh":"一条小路通向山上的寺庙。","pinyin":"Yì tiáo xiǎolù tōngxiàng shān shang de sìmiào.","vi":"Một lối mòn dẫn lên ngôi chùa trên núi."},{"type":"compound","zh":"如果走这条小路，我们就能早半个小时到。","pinyin":"Rúguǒ zǒu zhè tiáo xiǎolù, wǒmen jiù néng zǎo bàn gè xiǎoshí dào.","vi":"Nếu đi đường nhỏ này thì chúng ta có thể đến sớm nửa tiếng."}],"related":[{"hanzi":"大路","pinyin":"dàlù","vi":"đường lớn"},{"hanzi":"马路","pinyin":"mǎlù","vi":"đường phố"},{"hanzi":"胡同","pinyin":"hútòng","vi":"ngõ hẻm"},{"hanzi":"小道","pinyin":"xiǎodào","vi":"đường nhỏ"}]},{"id":"小气","hanzi":"小气","pinyin":"xiǎoqì","meaning_vi":"keo kiệt, bủn xỉn; hẹp hòi","explanation":"小 (tiểu – nhỏ) + 气 (khí – khí độ) → khí độ nhỏ, tức keo kiệt, hẹp hòi.","hsk_level":"7-9","tags":["tinh-tu"],"image":"💰","examples":[{"type":"basic","zh":"他这个人很小气。","pinyin":"Tā zhè ge rén hěn xiǎoqì.","vi":"Anh ta là người rất keo kiệt."},{"type":"simple","zh":"老板小气得连一杯咖啡都不请。","pinyin":"Lǎobǎn xiǎoqì de lián yì bēi kāfēi dōu bù qǐng.","vi":"Ông chủ keo đến mức một ly cà phê cũng không mời."},{"type":"compound","zh":"虽然他很有钱，但是对朋友却特别小气。","pinyin":"Suīrán tā hěn yǒuqián, dànshì duì péngyou què tèbié xiǎoqì.","vi":"Tuy anh ta rất có tiền nhưng với bạn bè lại cực kỳ bủn xỉn."}],"related":[{"hanzi":"大方","pinyin":"dàfang","vi":"hào phóng"},{"hanzi":"吝啬","pinyin":"lìnsè","vi":"keo kiệt"},{"hanzi":"抠门","pinyin":"kōumén","vi":"bủn xỉn"},{"hanzi":"小心眼","pinyin":"xiǎoxīnyǎn","vi":"hẹp hòi"}],"traditional":"小氣"},{"id":"小区","hanzi":"小区","pinyin":"xiǎoqū","meaning_vi":"khu dân cư, khu chung cư","explanation":"小 (tiểu – nhỏ) + 区 (khu – khu vực) → khu dân cư nhỏ, thường là khu nhà ở có ban quản lý.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏢","examples":[{"type":"basic","zh":"我们小区很安静。","pinyin":"Wǒmen xiǎoqū hěn ānjìng.","vi":"Khu chung cư của chúng tôi rất yên tĩnh."},{"type":"simple","zh":"小区门口新开了一家超市。","pinyin":"Xiǎoqū ménkǒu xīn kāile yìjiā chāoshì.","vi":"Trước cổng khu dân cư mới mở một siêu thị."},{"type":"compound","zh":"因为小区里有很多树，所以夏天也不太热。","pinyin":"Yīnwèi xiǎoqū lǐ yǒu hěn duō shù, suǒyǐ xiàtiān yě bú tài rè.","vi":"Vì trong khu dân cư có nhiều cây nên mùa hè cũng không quá nóng."}],"related":[{"hanzi":"社区","pinyin":"shèqū","vi":"cộng đồng"},{"hanzi":"住宅","pinyin":"zhùzhái","vi":"nhà ở"},{"hanzi":"物业","pinyin":"wùyè","vi":"ban quản lý"},{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"}],"traditional":"小區"},{"id":"小曲","hanzi":"小曲","pinyin":"xiǎoqǔ","meaning_vi":"khúc hát, bài hát dân gian","explanation":"小 (tiểu – nhỏ) + 曲 (khúc – bài hát) → bài hát ngắn, điệu hát dân gian.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎶","examples":[{"type":"basic","zh":"他哼着小曲回家。","pinyin":"Tā hēngzhe xiǎoqǔ huíjiā.","vi":"Anh ấy vừa ngân nga khúc hát vừa về nhà."},{"type":"simple","zh":"奶奶一边做饭一边唱家乡的小曲。","pinyin":"Nǎinai yìbiān zuòfàn yìbiān chàng jiāxiāng de xiǎoqǔ.","vi":"Bà vừa nấu cơm vừa hát điệu hát quê nhà."},{"type":"compound","zh":"虽然这首小曲很简单，但是大家都很喜欢听。","pinyin":"Suīrán zhè shǒu xiǎoqǔ hěn jiǎndān, dànshì dàjiā dōu hěn xǐhuan tīng.","vi":"Tuy khúc hát này rất đơn giản nhưng ai cũng thích nghe."}],"related":[{"hanzi":"歌曲","pinyin":"gēqǔ","vi":"bài hát"},{"hanzi":"民歌","pinyin":"míngē","vi":"dân ca"},{"hanzi":"曲子","pinyin":"qǔzi","vi":"khúc nhạc"},{"hanzi":"哼","pinyin":"hēng","vi":"ngân nga"}]},{"id":"小人","hanzi":"小人","pinyin":"xiǎorén","meaning_vi":"kẻ tiểu nhân, kẻ xấu","explanation":"小 (tiểu – nhỏ) + 人 (nhân – người) → người có nhân cách thấp kém, tiểu nhân; trái nghĩa với 君子 (quân tử).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🐍","examples":[{"type":"basic","zh":"他是个小人。","pinyin":"Tā shì ge xiǎorén.","vi":"Hắn là kẻ tiểu nhân."},{"type":"simple","zh":"我们要提防背后说坏话的小人。","pinyin":"Wǒmen yào dīfang bèihòu shuō huàihuà de xiǎorén.","vi":"Chúng ta phải đề phòng kẻ tiểu nhân nói xấu sau lưng."},{"type":"compound","zh":"如果你总是和小人来往，就迟早会吃亏。","pinyin":"Rúguǒ nǐ zǒngshì hé xiǎorén láiwǎng, jiù chízǎo huì chīkuī.","vi":"Nếu bạn cứ qua lại với kẻ tiểu nhân thì sớm muộn cũng chịu thiệt."}],"related":[{"hanzi":"君子","pinyin":"jūnzǐ","vi":"quân tử"},{"hanzi":"坏人","pinyin":"huàirén","vi":"người xấu"},{"hanzi":"卑鄙","pinyin":"bēibǐ","vi":"hèn hạ"},{"hanzi":"小气","pinyin":"xiǎoqì","vi":"hẹp hòi"}]},{"id":"小提琴","hanzi":"小提琴","pinyin":"xiǎotíqín","meaning_vi":"đàn vi-ô-lông, vĩ cầm","explanation":"小 (tiểu – nhỏ) + 提 (đề – cầm, nâng) + 琴 (cầm – đàn) → cây đàn nhỏ cầm lên kéo, tức vĩ cầm.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎻","examples":[{"type":"basic","zh":"她会拉小提琴。","pinyin":"Tā huì lā xiǎotíqín.","vi":"Cô ấy biết kéo vĩ cầm."},{"type":"simple","zh":"他从五岁开始学习拉小提琴。","pinyin":"Tā cóng wǔ suì kāishǐ xuéxí lā xiǎotíqín.","vi":"Cậu ấy bắt đầu học kéo vĩ cầm từ năm tuổi."},{"type":"compound","zh":"虽然练小提琴很辛苦，但是她每天坚持两个小时。","pinyin":"Suīrán liàn xiǎotíqín hěn xīnkǔ, dànshì tā měitiān jiānchí liǎng gè xiǎoshí.","vi":"Tuy tập vĩ cầm rất vất vả nhưng ngày nào cô ấy cũng kiên trì hai tiếng."}],"related":[{"hanzi":"钢琴","pinyin":"gāngqín","vi":"đàn piano"},{"hanzi":"大提琴","pinyin":"dàtíqín","vi":"đàn cello"},{"hanzi":"乐器","pinyin":"yuèqì","vi":"nhạc cụ"},{"hanzi":"琴弦","pinyin":"qínxián","vi":"dây đàn"}]},{"id":"小溪","hanzi":"小溪","pinyin":"xiǎoxī","meaning_vi":"suối nhỏ, con lạch","explanation":"小 (tiểu – nhỏ) + 溪 (khê – suối) → dòng suối nhỏ.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"小溪清澈见底。","pinyin":"Xiǎoxī qīngchè jiàndǐ.","vi":"Con suối nhỏ trong vắt thấy tận đáy."},{"type":"simple","zh":"一条小溪从村子前面流过。","pinyin":"Yì tiáo xiǎoxī cóng cūnzi qiánmian liú guò.","vi":"Một con suối nhỏ chảy qua trước làng."},{"type":"compound","zh":"虽然小溪不深，但是下雨后水流很急。","pinyin":"Suīrán xiǎoxī bù shēn, dànshì xiàyǔ hòu shuǐliú hěn jí.","vi":"Tuy suối nhỏ không sâu nhưng sau cơn mưa nước chảy rất xiết."}],"related":[{"hanzi":"河流","pinyin":"héliú","vi":"sông ngòi"},{"hanzi":"溪水","pinyin":"xīshuǐ","vi":"nước suối"},{"hanzi":"泉水","pinyin":"quánshuǐ","vi":"nước suối nguồn"},{"hanzi":"瀑布","pinyin":"pùbù","vi":"thác nước"}]},{"id":"小卒","hanzi":"小卒","pinyin":"xiǎozú","meaning_vi":"lính quèn, kẻ vô danh tiểu tốt, quân tốt","explanation":"小 (tiểu – nhỏ) + 卒 (tốt – lính) → người lính bình thường; nghĩa bóng là nhân vật nhỏ bé, vô danh; trong cờ tướng là quân tốt.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🪖","examples":[{"type":"basic","zh":"我只是个小卒。","pinyin":"Wǒ zhǐshì ge xiǎozú.","vi":"Tôi chỉ là một kẻ tiểu tốt."},{"type":"simple","zh":"他在这家大公司里只是个无名小卒。","pinyin":"Tā zài zhè jiā dàgōngsī lǐ zhǐshì ge wúmíng xiǎozú.","vi":"Ở công ty lớn này anh ấy chỉ là một nhân viên vô danh."},{"type":"compound","zh":"虽然他当年只是个小卒，但是后来成了大将军。","pinyin":"Suīrán tā dāngnián zhǐshì ge xiǎozú, dànshì hòulái chéngle dàjiāngjūn.","vi":"Tuy năm đó anh ta chỉ là lính quèn nhưng sau này trở thành đại tướng."}],"related":[{"hanzi":"士兵","pinyin":"shìbīng","vi":"binh lính"},{"hanzi":"无名小卒","pinyin":"wúmíngxiǎozú","vi":"kẻ vô danh tiểu tốt"},{"hanzi":"将军","pinyin":"jiāngjūn","vi":"tướng quân"},{"hanzi":"小人物","pinyin":"xiǎorénwù","vi":"người nhỏ bé"}]},{"id":"孝顺","hanzi":"孝顺","pinyin":"xiàoshùn","meaning_vi":"hiếu thảo, hiếu thuận","explanation":"孝 (hiếu – hiếu thảo) + 顺 (thuận – vâng theo) → hiếu thảo và vâng lời cha mẹ, ông bà.","hsk_level":"7-9","tags":["tinh-tu","gia-dinh"],"image":"👵","examples":[{"type":"basic","zh":"他是个孝顺的儿子。","pinyin":"Tā shì ge xiàoshùn de érzi.","vi":"Anh ấy là một người con hiếu thảo."},{"type":"simple","zh":"她每个周末都回家孝顺父母。","pinyin":"Tā měi gè zhōumò dōu huíjiā xiàoshùn fùmǔ.","vi":"Cuối tuần nào cô ấy cũng về nhà phụng dưỡng cha mẹ."},{"type":"compound","zh":"虽然工作很忙，但是他从来没忘记孝顺老人。","pinyin":"Suīrán gōngzuò hěn máng, dànshì tā cónglái méi wàngjì xiàoshùn lǎorén.","vi":"Tuy công việc bận rộn nhưng anh ấy chưa bao giờ quên hiếu thảo với ông bà cha mẹ."}],"related":[{"hanzi":"孝心","pinyin":"xiàoxīn","vi":"lòng hiếu thảo"},{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"kính trọng"},{"hanzi":"父母","pinyin":"fùmǔ","vi":"cha mẹ"},{"hanzi":"报答","pinyin":"bàodá","vi":"báo đáp"}],"traditional":"孝順"},{"id":"效应","hanzi":"效应","pinyin":"xiàoyìng","meaning_vi":"hiệu ứng","explanation":"效 (hiệu – hiệu quả) + 应 (ứng – đáp ứng) → hiện tượng, phản ứng do một tác động gây ra, tức hiệu ứng.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌡️","examples":[{"type":"basic","zh":"这就是温室效应。","pinyin":"Zhè jiùshì wēnshìxiàoyìng.","vi":"Đây chính là hiệu ứng nhà kính."},{"type":"simple","zh":"名人代言产生了明显的广告效应。","pinyin":"Míngrén dàiyán chǎnshēngle míngxiǎn de guǎnggào xiàoyìng.","vi":"Người nổi tiếng làm đại diện đã tạo ra hiệu ứng quảng cáo rõ rệt."},{"type":"compound","zh":"一旦一家店降价，就会产生连锁效应。","pinyin":"Yídàn yìjiā diàn jiàngjià, jiù huì chǎnshēng liánsuǒ xiàoyìng.","vi":"Một khi một cửa hàng giảm giá thì sẽ tạo ra hiệu ứng dây chuyền."}],"related":[{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"},{"hanzi":"反应","pinyin":"fǎnyìng","vi":"phản ứng"},{"hanzi":"温室效应","pinyin":"wēnshìxiàoyìng","vi":"hiệu ứng nhà kính"}],"traditional":"效應"},{"id":"协定","hanzi":"协定","pinyin":"xiédìng","meaning_vi":"hiệp định, thỏa thuận","explanation":"协 (hiệp – cùng nhau) + 定 (định – quyết định) → cùng nhau định ra, tức hiệp định.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📝","examples":[{"type":"basic","zh":"两国签订了协定。","pinyin":"Liǎngguó qiāndìngle xiédìng.","vi":"Hai nước đã ký kết hiệp định."},{"type":"simple","zh":"双方达成了一项新的贸易协定。","pinyin":"Shuāngfāng dáchéngle yí xiàng xīn de màoyì xiédìng.","vi":"Hai bên đã đạt được một hiệp định thương mại mới."},{"type":"compound","zh":"如果有一方违反协定，另一方就有权终止合作。","pinyin":"Rúguǒ yǒu yìfāng wéifǎn xiédìng, lìng yìfāng jiù yǒuquán zhōngzhǐ hézuò.","vi":"Nếu một bên vi phạm hiệp định thì bên kia có quyền chấm dứt hợp tác."}],"related":[{"hanzi":"协议","pinyin":"xiéyì","vi":"thỏa thuận"},{"hanzi":"条约","pinyin":"tiáoyuē","vi":"điều ước"},{"hanzi":"合同","pinyin":"hétong","vi":"hợp đồng"},{"hanzi":"签订","pinyin":"qiāndìng","vi":"ký kết"}],"traditional":"協定"},{"id":"协同","hanzi":"协同","pinyin":"xiétóng","meaning_vi":"phối hợp, hiệp đồng","explanation":"协 (hiệp – hợp sức) + 同 (đồng – cùng) → cùng nhau phối hợp hành động.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🧩","examples":[{"type":"basic","zh":"各部门协同工作。","pinyin":"Gè bùmén xiétóng gōngzuò.","vi":"Các bộ phận phối hợp làm việc."},{"type":"simple","zh":"警察协同消防员救出了被困的人。","pinyin":"Jǐngchá xiétóng xiāofángyuán jiùchūle bèi kùn de rén.","vi":"Cảnh sát phối hợp với lính cứu hỏa cứu những người bị mắc kẹt."},{"type":"compound","zh":"只要大家协同作战，就一定能完成任务。","pinyin":"Zhǐyào dàjiā xiétóng zuòzhàn, jiù yídìng néng wánchéng rènwu.","vi":"Chỉ cần mọi người phối hợp tác chiến thì nhất định sẽ hoàn thành nhiệm vụ."}],"related":[{"hanzi":"协作","pinyin":"xiézuò","vi":"hợp tác"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"},{"hanzi":"共同","pinyin":"gòngtóng","vi":"cùng nhau"}],"traditional":"協同"},{"id":"协作","hanzi":"协作","pinyin":"xiézuò","meaning_vi":"hợp tác, cộng tác","explanation":"协 (hiệp – hợp sức) + 作 (tác – làm) → cùng nhau làm việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👥","examples":[{"type":"basic","zh":"我们需要团队协作。","pinyin":"Wǒmen xūyào tuánduì xiézuò.","vi":"Chúng ta cần sự hợp tác của cả nhóm."},{"type":"simple","zh":"这个项目由三所大学共同协作完成。","pinyin":"Zhè ge xiàngmù yóu sān suǒ dàxué gòngtóng xiézuò wánchéng.","vi":"Dự án này do ba trường đại học cùng hợp tác hoàn thành."},{"type":"compound","zh":"如果大家不互相协作，这么大的工程就做不完。","pinyin":"Rúguǒ dàjiā bú hùxiāng xiézuò, zhème dà de gōngchéng jiù zuò bu wán.","vi":"Nếu mọi người không hợp tác với nhau thì công trình lớn thế này sẽ không làm xong."}],"related":[{"hanzi":"协同","pinyin":"xiétóng","vi":"phối hợp"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"},{"hanzi":"团队","pinyin":"tuánduì","vi":"đội nhóm"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"}],"traditional":"協作"},{"id":"邪","hanzi":"邪","pinyin":"xié","meaning_vi":"tà, gian tà; kỳ quái, quái lạ","explanation":"邪 (tà – không chính đáng): trái với chính đạo, xấu xa; trong khẩu ngữ còn chỉ sự kỳ quái, khác thường.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😈","examples":[{"type":"basic","zh":"他从来不信邪。","pinyin":"Tā cóngláibú xìn xié.","vi":"Anh ấy chưa bao giờ tin chuyện ma tà."},{"type":"simple","zh":"他年轻时走过一段邪路。","pinyin":"Tā niánqīng shí zǒuguò yí duàn xiélù.","vi":"Hồi trẻ anh ta từng đi vào con đường sai trái."},{"type":"compound","zh":"虽然他嘴上说不怕，但是心里也觉得这事有点儿邪。","pinyin":"Suīrán tā zuǐ shang shuō bú pà, dànshì xīnlǐ yě juéde zhè shì yǒudiǎnr xié.","vi":"Tuy miệng nói không sợ nhưng trong lòng anh ấy cũng thấy chuyện này hơi quái lạ."}],"related":[{"hanzi":"邪恶","pinyin":"xié'è","vi":"tà ác"},{"hanzi":"正","pinyin":"zhèng","vi":"chính"},{"hanzi":"邪路","pinyin":"xiélù","vi":"đường tà"},{"hanzi":"歪","pinyin":"wāi","vi":"lệch lạc"}]},{"id":"邪恶","hanzi":"邪恶","pinyin":"xié'è","meaning_vi":"tà ác, độc ác, gian tà","explanation":"邪 (tà – gian tà) + 恶 (ác – xấu ác) → gian tà và độc ác.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👹","examples":[{"type":"basic","zh":"他的笑容很邪恶。","pinyin":"Tā de xiàoróng hěn xié'è.","vi":"Nụ cười của hắn rất gian ác."},{"type":"simple","zh":"故事里的巫婆有一颗邪恶的心。","pinyin":"Gùshi lǐ de wūpó yǒu yì kē xié'è de xīn.","vi":"Mụ phù thủy trong truyện có một trái tim độc ác."},{"type":"compound","zh":"虽然坏人很邪恶，但是最后还是被英雄打败了。","pinyin":"Suīrán huàirén hěn xié'è, dànshì zuìhòu háishi bèi yīngxióng dǎbài le.","vi":"Tuy kẻ xấu rất độc ác nhưng cuối cùng vẫn bị người anh hùng đánh bại."}],"related":[{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"邪","pinyin":"xié","vi":"tà"},{"hanzi":"罪恶","pinyin":"zuì'è","vi":"tội ác"},{"hanzi":"正义","pinyin":"zhèngyì","vi":"chính nghĩa"}],"traditional":"邪惡"},{"id":"挟持","hanzi":"挟持","pinyin":"xiéchí","meaning_vi":"bắt giữ, khống chế (con tin)","explanation":"挟 (hiệp – kẹp dưới nách) + 持 (trì – giữ) → kẹp chặt giữ lấy, tức khống chế, bắt giữ người.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⛓️","examples":[{"type":"basic","zh":"歹徒挟持了人质。","pinyin":"Dǎitú xiéchíle rénzhì.","vi":"Tên côn đồ đã bắt giữ con tin."},{"type":"simple","zh":"一名男子在银行里挟持了一位职员。","pinyin":"Yì míng nánzǐ zài yínháng lǐ xiéchíle yí wèi zhíyuán.","vi":"Một người đàn ông khống chế một nhân viên trong ngân hàng."},{"type":"compound","zh":"虽然歹徒挟持了司机，但是警察很快把人救了出来。","pinyin":"Suīrán dǎitú xiéchíle sījī, dànshì jǐngchá hěn kuài bǎ rén jiùle chūlái.","vi":"Tuy tên côn đồ đã bắt giữ tài xế nhưng cảnh sát nhanh chóng giải cứu được."}],"related":[{"hanzi":"劫持","pinyin":"jiéchí","vi":"bắt cóc"},{"hanzi":"绑架","pinyin":"bǎngjià","vi":"bắt cóc"},{"hanzi":"人质","pinyin":"rénzhì","vi":"con tin"},{"hanzi":"歹徒","pinyin":"dǎitú","vi":"kẻ côn đồ"}],"traditional":"挾持"},{"id":"携手","hanzi":"携手","pinyin":"xiéshǒu","meaning_vi":"nắm tay nhau, chung tay","explanation":"携 (huề – dắt, mang) + 手 (thủ – tay) → nắm tay nhau; nghĩa bóng là chung tay hợp tác.","hsk_level":"7-9","tags":["dong-tu"],"image":"🫱","examples":[{"type":"basic","zh":"我们携手前进。","pinyin":"Wǒmen xiéshǒu qiánjìn.","vi":"Chúng ta chung tay tiến lên."},{"type":"simple","zh":"两家公司携手开发新能源汽车。","pinyin":"Liǎng jiā gōngsī xiéshǒu kāifā xīnnéngyuánqìchē.","vi":"Hai công ty bắt tay phát triển xe năng lượng mới."},{"type":"compound","zh":"只要我们携手合作，就没有克服不了的困难。","pinyin":"Zhǐyào wǒmen xiéshǒu hézuò, jiù méiyǒu kèfú bùliǎo de kùnnan.","vi":"Chỉ cần chúng ta chung tay hợp tác thì không có khó khăn nào không vượt qua được."}],"related":[{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"},{"hanzi":"联手","pinyin":"liánshǒu","vi":"bắt tay nhau"},{"hanzi":"手拉手","pinyin":"shǒulāshǒu","vi":"tay nắm tay"},{"hanzi":"携带","pinyin":"xiédài","vi":"mang theo"}],"traditional":"攜手"},{"id":"泄","hanzi":"泄","pinyin":"xiè","meaning_vi":"rò rỉ, thoát ra; tiết lộ; trút (giận)","explanation":"泄 (tiết – thoát ra): chất lỏng, khí thoát ra ngoài; nghĩa bóng là để lộ bí mật hoặc trút cảm xúc.","hsk_level":"7-9","tags":["dong-tu"],"image":"💧","examples":[{"type":"basic","zh":"轮胎泄了气。","pinyin":"Lúntāi xièle qì.","vi":"Lốp xe bị xì hơi."},{"type":"simple","zh":"他不小心把公司的秘密泄了出去。","pinyin":"Tā bù xiǎoxīn bǎ gōngsī de mìmì xièle chūqù.","vi":"Anh ấy vô ý làm lộ bí mật của công ty."},{"type":"compound","zh":"虽然输了比赛，但是队员们没有泄气。","pinyin":"Suīrán shūle bǐsài, dànshì duìyuánmen méiyǒu xièqì.","vi":"Tuy thua trận nhưng các cầu thủ không nản lòng."}],"related":[{"hanzi":"泄漏","pinyin":"xièlòu","vi":"rò rỉ"},{"hanzi":"泄气","pinyin":"xièqì","vi":"nản lòng"},{"hanzi":"发泄","pinyin":"fāxiè","vi":"trút giận"},{"hanzi":"泄密","pinyin":"xièmì","vi":"lộ bí mật"}],"traditional":"洩"},{"id":"泄漏","hanzi":"泄漏","pinyin":"xièlòu","meaning_vi":"rò rỉ; tiết lộ, để lộ","explanation":"泄 (tiết – thoát ra) + 漏 (lậu – rò) → chất lỏng, khí rò rỉ ra ngoài; cũng chỉ việc để lộ thông tin.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"煤气泄漏了！","pinyin":"Méiqì xièlòu le!","vi":"Rò rỉ khí ga rồi!"},{"type":"simple","zh":"工厂的化学品泄漏污染了河水。","pinyin":"Gōngchǎng de huàxuépǐn xièlòu wūrǎnle héshuǐ.","vi":"Hóa chất rò rỉ từ nhà máy đã làm ô nhiễm nước sông."},{"type":"compound","zh":"如果比赛方案提前泄漏，我们的计划就会失败。","pinyin":"Rúguǒ bǐsài fāng'àn tíqián xièlòu, wǒmen de jìhuà jiù huì shībài.","vi":"Nếu phương án thi đấu bị lộ trước thì kế hoạch của chúng ta sẽ thất bại."}],"related":[{"hanzi":"泄露","pinyin":"xièlù","vi":"tiết lộ"},{"hanzi":"漏","pinyin":"lòu","vi":"rò"},{"hanzi":"泄密","pinyin":"xièmì","vi":"lộ bí mật"},{"hanzi":"渗漏","pinyin":"shènlòu","vi":"thấm rỉ"}],"traditional":"洩漏"},{"id":"泻","hanzi":"泻","pinyin":"xiè","meaning_vi":"chảy xiết, đổ ào; tiêu chảy","explanation":"泻 (tả – chảy mạnh xuống): nước chảy ào xuống; trong y học chỉ đi ngoài, tiêu chảy.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🌊","examples":[{"type":"basic","zh":"河水一泻千里。","pinyin":"Héshuǐ yí xiè qiānlǐ.","vi":"Nước sông chảy xiết nghìn dặm."},{"type":"simple","zh":"阳光从窗户泻进了房间。","pinyin":"Yángguāng cóng chuānghu xiè jìnle fángjiān.","vi":"Ánh nắng từ cửa sổ tràn vào phòng."},{"type":"compound","zh":"因为他吃了不干净的东西，所以上吐下泻。","pinyin":"Yīnwèi tā chīle bù gānjìng de dōngxi, suǒyǐ shàng tù xià xiè.","vi":"Vì ăn phải đồ không sạch nên anh ấy vừa nôn vừa tiêu chảy."}],"related":[{"hanzi":"腹泻","pinyin":"fùxiè","vi":"tiêu chảy"},{"hanzi":"倾泻","pinyin":"qīngxiè","vi":"đổ ào"},{"hanzi":"拉肚子","pinyin":"lādùzi","vi":"đau bụng đi ngoài"},{"hanzi":"流","pinyin":"liú","vi":"chảy"}],"traditional":"瀉"},{"id":"卸","hanzi":"卸","pinyin":"xiè","meaning_vi":"dỡ (hàng); tháo, gỡ; trút bỏ (trách nhiệm)","explanation":"卸 (tá – dỡ xuống): dỡ hàng, tháo bỏ đồ trên người hay trên máy; cũng chỉ trút bỏ trách nhiệm.","hsk_level":"7-9","tags":["dong-tu"],"image":"📦","examples":[{"type":"basic","zh":"工人在卸货。","pinyin":"Gōngrén zài xièhuò.","vi":"Công nhân đang dỡ hàng."},{"type":"simple","zh":"她回到家第一件事就是卸妆。","pinyin":"Tā huí dàojiā dìyī jiàn shì jiùshì xièzhuāng.","vi":"Về đến nhà, việc đầu tiên cô ấy làm là tẩy trang."},{"type":"compound","zh":"等这车货一卸完，我们就马上出发去下一站。","pinyin":"Děng zhè chē huò yí xiè wán, wǒmen jiù mǎshàng chūfā qù xiàyízhàn.","vi":"Đợi dỡ xong xe hàng này, chúng ta sẽ lập tức đi trạm tiếp theo."}],"related":[{"hanzi":"装卸","pinyin":"zhuāngxiè","vi":"bốc dỡ"},{"hanzi":"卸货","pinyin":"xièhuò","vi":"dỡ hàng"},{"hanzi":"卸妆","pinyin":"xièzhuāng","vi":"tẩy trang"},{"hanzi":"推卸","pinyin":"tuīxiè","vi":"đùn đẩy"}]},{"id":"心安理得","hanzi":"心安理得","pinyin":"xīn'ān-lǐdé","meaning_vi":"thanh thản, yên lòng không áy náy","explanation":"心安 (tâm an – lòng yên) + 理得 (lý đắc – hợp lẽ) → làm việc hợp lẽ nên lòng thanh thản; nay cũng dùng mỉa người làm sai mà vẫn thản nhiên.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😌","examples":[{"type":"basic","zh":"他心安理得地收下了。","pinyin":"Tā xīn'ānlǐdé de shōuxià le.","vi":"Anh ta thản nhiên nhận lấy."},{"type":"simple","zh":"他心安理得地享受着父母的照顾。","pinyin":"Tā xīn'ānlǐdé de xiǎngshòuzhe fùmǔ de zhàogù.","vi":"Anh ta thản nhiên hưởng sự chăm sóc của bố mẹ."},{"type":"compound","zh":"只要你问心无愧，就可以心安理得地睡觉。","pinyin":"Zhǐyào nǐ wènxīnwúkuì, jiù kěyǐ xīn'ānlǐdé de shuìjiào.","vi":"Chỉ cần bạn không hổ thẹn với lương tâm thì có thể ngủ yên lòng."}],"related":[{"hanzi":"问心无愧","pinyin":"wènxīnwúkuì","vi":"không hổ thẹn với lương tâm"},{"hanzi":"理所当然","pinyin":"lǐsuǒdāngrán","vi":"lẽ đương nhiên"},{"hanzi":"安心","pinyin":"ānxīn","vi":"yên tâm"},{"hanzi":"坦然","pinyin":"tǎnrán","vi":"thản nhiên"}]},{"id":"心病","hanzi":"心病","pinyin":"xīnbìng","meaning_vi":"nỗi lo canh cánh, tâm bệnh","explanation":"心 (tâm – lòng) + 病 (bệnh) → bệnh trong lòng, tức nỗi lo âu, khúc mắc khó nói.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"这是他的一块心病。","pinyin":"Zhè shì tā de yíkuài xīnbìng.","vi":"Đây là nỗi lo canh cánh của anh ấy."},{"type":"simple","zh":"儿子的婚事成了妈妈的心病。","pinyin":"Érzi de hūnshì chéngle māma de xīnbìng.","vi":"Chuyện cưới xin của con trai trở thành nỗi lo của mẹ."},{"type":"compound","zh":"虽然他嘴上不说，但是这件事一直是他的心病。","pinyin":"Suīrán tā zuǐ shang bù shuō, dànshì zhè jiàn shì yìzhí shì tā de xīnbìng.","vi":"Tuy ngoài miệng không nói nhưng việc này luôn là nỗi day dứt của anh ấy."}],"related":[{"hanzi":"心事","pinyin":"xīnshì","vi":"nỗi lòng"},{"hanzi":"担心","pinyin":"dānxīn","vi":"lo lắng"},{"hanzi":"烦恼","pinyin":"fánnǎo","vi":"phiền muộn"},{"hanzi":"心结","pinyin":"xīnjié","vi":"khúc mắc"}]},{"id":"心肠","hanzi":"心肠","pinyin":"xīncháng","meaning_vi":"tấm lòng, lòng dạ","explanation":"心 (tâm – tim) + 肠 (tràng – ruột) → tim ruột, tức lòng dạ, bản tính tốt xấu của con người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"❤️","examples":[{"type":"basic","zh":"她心肠很好。","pinyin":"Tā xīncháng hěn hǎo.","vi":"Cô ấy có tấm lòng rất tốt."},{"type":"simple","zh":"这位热心肠的老人经常帮助邻居。","pinyin":"Zhè wèi rèxīncháng de lǎorén jīngcháng bāngzhù línjū.","vi":"Ông cụ nhiệt tình này thường xuyên giúp đỡ hàng xóm."},{"type":"compound","zh":"虽然他说话很冲，但是心肠其实很软。","pinyin":"Suīrán tā shuōhuà hěn chòng, dànshì xīncháng qíshí hěn ruǎn.","vi":"Tuy anh ấy nói chuyện cộc cằn nhưng lòng dạ thực ra rất mềm."}],"related":[{"hanzi":"心地","pinyin":"xīndì","vi":"tâm địa"},{"hanzi":"热心肠","pinyin":"rèxīncháng","vi":"nhiệt tình"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"铁石心肠","pinyin":"tiěshíxīncháng","vi":"lòng dạ sắt đá"}],"traditional":"心腸"},{"id":"心慌","hanzi":"心慌","pinyin":"xīnhuāng","meaning_vi":"hoảng hốt, cuống, hồi hộp","explanation":"心 (tâm – lòng) + 慌 (hoảng – cuống) → trong lòng hoảng hốt, bối rối; cũng chỉ tim đập nhanh.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"我有点儿心慌。","pinyin":"Wǒ yǒudiǎnr xīnhuāng.","vi":"Tôi hơi hoảng."},{"type":"simple","zh":"他一上台就心慌得说不出话来。","pinyin":"Tā yí shàngtái jiù xīnhuāng de shuōbuchū huà lái.","vi":"Anh ấy vừa lên sân khấu là cuống đến mức không nói nên lời."},{"type":"compound","zh":"因为昨晚没睡好，所以今天总觉得心慌。","pinyin":"Yīnwèi zuówǎn méi shuì hǎo, suǒyǐ jīntiān zǒng juéde xīnhuāng.","vi":"Vì tối qua ngủ không ngon nên hôm nay cứ thấy hồi hộp trong người."}],"related":[{"hanzi":"慌张","pinyin":"huāngzhāng","vi":"hoảng hốt"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"},{"hanzi":"着急","pinyin":"zháojí","vi":"sốt ruột"},{"hanzi":"心跳","pinyin":"xīntiào","vi":"nhịp tim"}]},{"id":"心急如焚","hanzi":"心急如焚","pinyin":"xīnjí-rúfén","meaning_vi":"nóng lòng như lửa đốt, vô cùng sốt ruột","explanation":"心急 (tâm cấp – lòng gấp) + 如焚 (như phần – như lửa đốt) → lòng nóng như lửa đốt, ý chỉ vô cùng sốt ruột, lo lắng.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"妈妈心急如焚。","pinyin":"Māma xīnjírúfén.","vi":"Mẹ sốt ruột như lửa đốt."},{"type":"simple","zh":"找不到孩子的父母心急如焚地四处打听。","pinyin":"Zhǎobudào háizi de fùmǔ xīnjírúfén de sìchù dǎting.","vi":"Bố mẹ không tìm thấy con nóng ruột hỏi han khắp nơi."},{"type":"compound","zh":"因为航班一再延误，所以赶着开会的他心急如焚。","pinyin":"Yīnwèi hángbān yízài yánwù, suǒyǐ gǎnzhe kāihuì de tā xīnjírúfén.","vi":"Vì chuyến bay liên tục bị hoãn nên anh ấy, người đang vội đi họp, sốt ruột như lửa đốt."}],"related":[{"hanzi":"焦急","pinyin":"jiāojí","vi":"nóng ruột"},{"hanzi":"着急","pinyin":"zháojí","vi":"sốt ruột"},{"hanzi":"坐立不安","pinyin":"zuòlìbù'ān","vi":"đứng ngồi không yên"},{"hanzi":"心急","pinyin":"xīnjí","vi":"nóng lòng"}]},{"id":"心里话","hanzi":"心里话","pinyin":"xīnlihuà","meaning_vi":"lời thật lòng, tâm sự","explanation":"心里 (tâm lý – trong lòng) + 话 (thoại – lời) → lời nói từ trong lòng, lời thật lòng.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"说说你的心里话。","pinyin":"Shuōshuo nǐ de xīnlihuà.","vi":"Nói ra lời thật lòng của bạn đi."},{"type":"simple","zh":"她只愿意跟奶奶说心里话。","pinyin":"Tā zhǐ yuànyì gēn nǎinai shuō xīnlihuà.","vi":"Cô bé chỉ muốn tâm sự với bà."},{"type":"compound","zh":"如果你有心里话，就大胆地说出来吧。","pinyin":"Rúguǒ nǐ yǒu xīnlihuà, jiù dàdǎn de shuō chūlái ba.","vi":"Nếu bạn có điều muốn tâm sự thì cứ mạnh dạn nói ra."}],"related":[{"hanzi":"真心话","pinyin":"zhēnxīnhuà","vi":"lời thật lòng"},{"hanzi":"心声","pinyin":"xīnshēng","vi":"tiếng lòng"},{"hanzi":"谈心","pinyin":"tánxīn","vi":"tâm sự"},{"hanzi":"实话","pinyin":"shíhuà","vi":"lời thật"}],"traditional":"心裡話"},{"id":"心灵手巧","hanzi":"心灵手巧","pinyin":"xīnlíng-shǒuqiǎo","meaning_vi":"khéo tay hay làm, thông minh khéo léo","explanation":"心灵 (tâm linh – đầu óc nhanh nhạy) + 手巧 (thủ xảo – tay khéo) → đầu óc thông minh, đôi tay khéo léo.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✂️","examples":[{"type":"basic","zh":"她心灵手巧。","pinyin":"Tā xīnlíngshǒuqiǎo.","vi":"Cô ấy khéo tay hay làm."},{"type":"simple","zh":"心灵手巧的奶奶给我织了一件毛衣。","pinyin":"Xīnlíngshǒuqiǎo de nǎinai gěi wǒ zhīle yí jiàn máoyī.","vi":"Bà khéo tay đã đan cho tôi một chiếc áo len."},{"type":"compound","zh":"因为她心灵手巧，所以什么东西都能做得很漂亮。","pinyin":"Yīnwèi tā xīnlíngshǒuqiǎo, suǒyǐ shénme dōngxi dōu néng zuò de hěn piàoliang.","vi":"Vì cô ấy khéo tay nên làm gì cũng đẹp."}],"related":[{"hanzi":"手巧","pinyin":"shǒuqiǎo","vi":"khéo tay"},{"hanzi":"灵巧","pinyin":"língqiǎo","vi":"khéo léo"},{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"},{"hanzi":"笨手笨脚","pinyin":"bènshǒubènjiǎo","vi":"vụng về"}],"traditional":"心靈手巧"},{"id":"心声","hanzi":"心声","pinyin":"xīnshēng","meaning_vi":"tiếng lòng, tâm tư nguyện vọng","explanation":"心 (tâm – lòng) + 声 (thanh – tiếng) → tiếng nói của trái tim, tâm tư nguyện vọng thật sự.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🗣️","examples":[{"type":"basic","zh":"这首歌唱出了心声。","pinyin":"Zhè shǒu gēchàng chūle xīnshēng.","vi":"Bài hát này đã hát lên tiếng lòng."},{"type":"simple","zh":"政府应该认真听取老百姓的心声。","pinyin":"Zhèngfǔ yīnggāi rènzhēn tīngqǔ lǎobǎixìng de xīnshēng.","vi":"Chính phủ nên lắng nghe nghiêm túc tâm tư của người dân."},{"type":"compound","zh":"虽然她不善于表达，但是这封信写出了她的心声。","pinyin":"Suīrán tā bú shànyú biǎodá, dànshì zhè fēng xìn xiě chūle tā de xīnshēng.","vi":"Tuy cô ấy không giỏi bày tỏ nhưng lá thư này đã nói lên tiếng lòng của cô."}],"related":[{"hanzi":"心里话","pinyin":"xīnlihuà","vi":"lời thật lòng"},{"hanzi":"心愿","pinyin":"xīnyuàn","vi":"tâm nguyện"},{"hanzi":"呼声","pinyin":"hūshēng","vi":"tiếng nói, nguyện vọng"},{"hanzi":"心意","pinyin":"xīnyì","vi":"tấm lòng"}],"traditional":"心聲"},{"id":"心事","hanzi":"心事","pinyin":"xīnshì","meaning_vi":"tâm sự, nỗi lo trong lòng","explanation":"心 (tâm – lòng) + 事 (sự – việc) → việc canh cánh trong lòng, nỗi lo lắng.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"你好像有心事。","pinyin":"Nǐ hǎoxiàng yǒu xīnshì.","vi":"Hình như bạn có tâm sự."},{"type":"simple","zh":"她把心事都写在了日记本里。","pinyin":"Tā bǎ xīnshì dōu xiě zài le rìjìběn lǐ.","vi":"Cô ấy viết hết tâm sự vào cuốn nhật ký."},{"type":"compound","zh":"如果你心里有什么心事，就跟我说说吧。","pinyin":"Rúguǒ nǐ xīnlǐ yǒu shénme xīnshì, jiù gēn wǒ shuōshuo ba.","vi":"Nếu trong lòng bạn có tâm sự gì thì nói với tôi nhé."}],"related":[{"hanzi":"心病","pinyin":"xīnbìng","vi":"nỗi lo canh cánh"},{"hanzi":"心思","pinyin":"xīnsi","vi":"suy nghĩ"},{"hanzi":"烦恼","pinyin":"fánnǎo","vi":"phiền muộn"},{"hanzi":"忧虑","pinyin":"yōulǜ","vi":"lo âu"}]},{"id":"心思","hanzi":"心思","pinyin":"xīnsi","meaning_vi":"suy nghĩ, tâm tư, tâm trí","explanation":"心 (tâm – lòng) + 思 (tư – nghĩ) → điều suy nghĩ trong lòng; cũng chỉ tâm trí, hứng thú để làm việc.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"我猜不透他的心思。","pinyin":"Wǒ cāibutòu tā de xīnsi.","vi":"Tôi không đoán được suy nghĩ của anh ấy."},{"type":"simple","zh":"她把所有心思都放在了孩子身上。","pinyin":"Tā bǎ suǒyǒu xīnsi dōu fàng zài le háizi shēnshang.","vi":"Cô ấy dồn hết tâm trí vào con cái."},{"type":"compound","zh":"因为马上要放假了，所以大家都没心思上课。","pinyin":"Yīnwèi mǎshàng yào fàngjià le, suǒyǐ dàjiā dōu méi xīnsi shàngkè.","vi":"Vì sắp được nghỉ nên mọi người chẳng còn tâm trí học hành."}],"related":[{"hanzi":"心事","pinyin":"xīnshì","vi":"nỗi lòng"},{"hanzi":"想法","pinyin":"xiǎngfǎ","vi":"suy nghĩ"},{"hanzi":"心意","pinyin":"xīnyì","vi":"tấm lòng"},{"hanzi":"用心","pinyin":"yòngxīn","vi":"chú tâm"}]},{"id":"心酸","hanzi":"心酸","pinyin":"xīnsuān","meaning_vi":"chua xót, đau lòng","explanation":"心 (tâm – lòng) + 酸 (toan – chua) → lòng chua xót, đau buồn thương cảm.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😢","examples":[{"type":"basic","zh":"听了让人心酸。","pinyin":"Tīngle ràng rén xīnsuān.","vi":"Nghe mà thấy chua xót."},{"type":"simple","zh":"老人孤单的背影让我一阵心酸。","pinyin":"Lǎorén gūdān de bèiyǐng ràng wǒ yízhèn xīnsuān.","vi":"Bóng lưng cô đơn của ông cụ khiến tôi chạnh lòng."},{"type":"compound","zh":"每当想起小时候吃过的苦，她就忍不住心酸。","pinyin":"Měidāng xiǎngqǐ xiǎoshíhou chīguò de kǔ, tā jiù rěnbuzhù xīnsuān.","vi":"Mỗi khi nhớ lại những khổ cực thời thơ ấu, cô ấy lại không kìm được chua xót."}],"related":[{"hanzi":"难过","pinyin":"nánguò","vi":"buồn"},{"hanzi":"伤心","pinyin":"shāngxīn","vi":"đau lòng"},{"hanzi":"辛酸","pinyin":"xīnsuān","vi":"cay đắng"},{"hanzi":"心疼","pinyin":"xīnténg","vi":"xót xa"}]},{"id":"心想事成","hanzi":"心想事成","pinyin":"xīnxiǎng-shìchéng","meaning_vi":"cầu được ước thấy, muốn gì được nấy","explanation":"心想 (tâm tưởng – trong lòng nghĩ) + 事成 (sự thành – việc thành) → nghĩ gì được nấy; là lời chúc thường dùng dịp Tết, sinh nhật.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌠","examples":[{"type":"basic","zh":"祝你心想事成！","pinyin":"Zhù nǐ xīnxiǎngshìchéng!","vi":"Chúc bạn cầu được ước thấy!"},{"type":"simple","zh":"春节时大家互相祝福心想事成。","pinyin":"Chūnjié shí dàjiā hùxiāng zhùfú xīnxiǎngshìchéng.","vi":"Dịp Tết mọi người chúc nhau muốn gì được nấy."},{"type":"compound","zh":"只要你肯付出努力，就一定能心想事成。","pinyin":"Zhǐyào nǐ kěn fùchū nǔlì, jiù yídìng néng xīnxiǎngshìchéng.","vi":"Chỉ cần bạn chịu bỏ công sức thì nhất định sẽ toại nguyện."}],"related":[{"hanzi":"万事如意","pinyin":"wànshìrúyì","vi":"vạn sự như ý"},{"hanzi":"梦想成真","pinyin":"mèngxiǎngchéngzhēn","vi":"ước mơ thành hiện thực"},{"hanzi":"如愿以偿","pinyin":"rúyuànyǐcháng","vi":"toại nguyện"},{"hanzi":"祝福","pinyin":"zhùfú","vi":"chúc phúc"}]},{"id":"心胸","hanzi":"心胸","pinyin":"xīnxiōng","meaning_vi":"tấm lòng, độ lượng; hoài bão","explanation":"心 (tâm – lòng) + 胸 (hung – ngực) → lồng ngực và trái tim, chỉ độ rộng lượng và hoài bão của con người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🫶","examples":[{"type":"basic","zh":"他心胸很宽广。","pinyin":"Tā xīnxiōng hěn kuānguǎng.","vi":"Anh ấy có tấm lòng rất rộng lượng."},{"type":"simple","zh":"心胸狭窄的人很难与别人相处。","pinyin":"Xīnxiōng xiázhǎi de rén hěn nán yǔ biérén xiāngchǔ.","vi":"Người hẹp hòi rất khó hòa hợp với người khác."},{"type":"compound","zh":"如果你心胸开阔一点儿，就不会为小事生气了。","pinyin":"Rúguǒ nǐ xīnxiōng kāikuò yìdiǎnr, jiù bú huì wèi xiǎoshì shēngqì le.","vi":"Nếu bạn rộng lượng hơn một chút thì sẽ không giận vì chuyện nhỏ nữa."}],"related":[{"hanzi":"胸怀","pinyin":"xiōnghuái","vi":"tấm lòng"},{"hanzi":"气量","pinyin":"qìliàng","vi":"độ lượng"},{"hanzi":"宽容","pinyin":"kuānróng","vi":"khoan dung"},{"hanzi":"小气","pinyin":"xiǎoqì","vi":"hẹp hòi"}]},{"id":"心意","hanzi":"心意","pinyin":"xīnyì","meaning_vi":"tấm lòng, tâm ý","explanation":"心 (tâm – lòng) + 意 (ý – ý định) → tình cảm và ý tốt trong lòng, tấm lòng.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💝","examples":[{"type":"basic","zh":"这是我的一点心意。","pinyin":"Zhè shì wǒ de yìdiǎn xīnyì.","vi":"Đây là chút lòng thành của tôi."},{"type":"simple","zh":"他用一束鲜花表达了自己的心意。","pinyin":"Tāyòng yí shù xiānhuā biǎodále zìjǐ de xīnyì.","vi":"Anh ấy dùng một bó hoa để bày tỏ tấm lòng."},{"type":"compound","zh":"虽然礼物很便宜，但是包含着孩子的一片心意。","pinyin":"Suīrán lǐwù hěn piányi, dànshì bāohánzhe háizi de yípiàn xīnyì.","vi":"Tuy món quà rẻ nhưng chứa đựng cả tấm lòng của đứa trẻ."}],"related":[{"hanzi":"心思","pinyin":"xīnsi","vi":"tâm tư"},{"hanzi":"情意","pinyin":"qíngyì","vi":"tình ý"},{"hanzi":"好意","pinyin":"hǎoyì","vi":"ý tốt"},{"hanzi":"心愿","pinyin":"xīnyuàn","vi":"tâm nguyện"}]},{"id":"欣喜","hanzi":"欣喜","pinyin":"xīnxǐ","meaning_vi":"vui mừng, hân hoan","explanation":"欣 (hân – vui) + 喜 (hỉ – mừng) → vui mừng, hân hoan.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😊","examples":[{"type":"basic","zh":"大家都很欣喜。","pinyin":"Dàjiā dōu hěn xīnxǐ.","vi":"Mọi người đều rất vui mừng."},{"type":"simple","zh":"老师对孩子们的进步感到十分欣喜。","pinyin":"Lǎoshī duì háizimen de jìnbù gǎndào shífēn xīnxǐ.","vi":"Cô giáo rất vui mừng trước sự tiến bộ của các em."},{"type":"compound","zh":"他一收到录取通知书，就欣喜地给妈妈打了电话。","pinyin":"Tā yì shōudào lùqǔ tōngzhīshū, jiù xīnxǐ de gěi māma dǎle diànhuà.","vi":"Vừa nhận được giấy báo trúng tuyển, cậu ấy vui mừng gọi điện cho mẹ."}],"related":[{"hanzi":"欣慰","pinyin":"xīnwèi","vi":"vui mừng yên lòng"},{"hanzi":"喜悦","pinyin":"xǐyuè","vi":"vui sướng"},{"hanzi":"高兴","pinyin":"gāoxìng","vi":"vui"},{"hanzi":"惊喜","pinyin":"jīngxǐ","vi":"bất ngờ vui mừng"}]},{"id":"新潮","hanzi":"新潮","pinyin":"xīncháo","meaning_vi":"hợp thời, thời thượng; trào lưu mới","explanation":"新 (tân – mới) + 潮 (triều – làn sóng, trào lưu) → làn sóng mới, trào lưu mới; dùng để tả cái hợp mốt, thời thượng.","hsk_level":"7-9","tags":["tinh-tu","trang-phuc"],"image":"🕶️","examples":[{"type":"basic","zh":"他的发型很新潮。","pinyin":"Tā de fàxíng hěn xīncháo.","vi":"Kiểu tóc của anh ấy rất thời thượng."},{"type":"simple","zh":"年轻人都喜欢穿新潮的衣服。","pinyin":"Niánqīngrén dōu xǐhuan chuān xīncháo de yīfu.","vi":"Người trẻ đều thích mặc quần áo hợp mốt."},{"type":"compound","zh":"虽然奶奶已经七十岁了，但是她的想法很新潮。","pinyin":"Suīrán nǎinai yǐjīng qīshí suì le, dànshì tā de xiǎngfǎ hěn xīncháo.","vi":"Tuy bà đã bảy mươi tuổi nhưng suy nghĩ rất hiện đại."}],"related":[{"hanzi":"时髦","pinyin":"shímáo","vi":"hợp mốt"},{"hanzi":"潮流","pinyin":"cháoliú","vi":"trào lưu"},{"hanzi":"时尚","pinyin":"shíshàng","vi":"thời trang"},{"hanzi":"老土","pinyin":"lǎotǔ","vi":"quê mùa"}]},{"id":"新房","hanzi":"新房","pinyin":"xīnfáng","meaning_vi":"nhà mới; phòng tân hôn","explanation":"新 (tân – mới) + 房 (phòng – nhà, phòng) → căn nhà mới; cũng chỉ phòng cưới của đôi vợ chồng mới.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"我们搬进了新房。","pinyin":"Wǒmen bān jìnle xīnfáng.","vi":"Chúng tôi đã dọn vào nhà mới."},{"type":"simple","zh":"他们把新房布置得又温馨又漂亮。","pinyin":"Tāmen bǎ xīnfáng bùzhì de yòu wēnxīn yòu piàoliang.","vi":"Họ bày trí phòng tân hôn vừa ấm cúng vừa đẹp."},{"type":"compound","zh":"因为新房刚装修完，所以要通风几个月再住。","pinyin":"Yīnwèi xīnfáng gāng zhuāngxiū wán, suǒyǐ yào tōngfēng jǐ gèyuè zài zhù.","vi":"Vì nhà mới vừa sửa xong nên phải để thông gió vài tháng rồi mới ở."}],"related":[{"hanzi":"房子","pinyin":"fángzi","vi":"nhà"},{"hanzi":"装修","pinyin":"zhuāngxiū","vi":"sửa sang"},{"hanzi":"搬家","pinyin":"bānjiā","vi":"chuyển nhà"},{"hanzi":"婚房","pinyin":"hūnfáng","vi":"phòng cưới"}]},{"id":"新款","hanzi":"新款","pinyin":"xīnkuǎn","meaning_vi":"mẫu mới, kiểu mới","explanation":"新 (tân – mới) + 款 (khoản – kiểu dáng) → kiểu dáng mới, mẫu mã mới.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🆕","examples":[{"type":"basic","zh":"这是今年的新款。","pinyin":"Zhè shì jīnnián de xīnkuǎn.","vi":"Đây là mẫu mới năm nay."},{"type":"simple","zh":"商店里摆满了新款运动鞋。","pinyin":"Shāngdiàn lǐ bǎimǎnle xīnkuǎn yùndòngxié.","vi":"Trong cửa hàng bày đầy giày thể thao mẫu mới."},{"type":"compound","zh":"虽然新款手机很贵，但是很多人还是排队购买。","pinyin":"Suīrán xīnkuǎn shǒujī hěn guì, dànshì hěn duō rén háishi páiduì gòumǎi.","vi":"Tuy điện thoại mẫu mới rất đắt nhưng nhiều người vẫn xếp hàng mua."}],"related":[{"hanzi":"款式","pinyin":"kuǎnshì","vi":"kiểu dáng"},{"hanzi":"旧款","pinyin":"jiùkuǎn","vi":"mẫu cũ"},{"hanzi":"新品","pinyin":"xīnpǐn","vi":"sản phẩm mới"},{"hanzi":"型号","pinyin":"xínghào","vi":"mẫu mã"}]},{"id":"新奇","hanzi":"新奇","pinyin":"xīnqí","meaning_vi":"mới lạ, lạ lẫm","explanation":"新 (tân – mới) + 奇 (kỳ – lạ) → mới mẻ và lạ lùng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"这玩具很新奇。","pinyin":"Zhè wánjù hěn xīnqí.","vi":"Món đồ chơi này rất mới lạ."},{"type":"simple","zh":"孩子们对城市里的一切都感到新奇。","pinyin":"Háizimen duì chéngshì lǐ de yíqiè dōu gǎndào xīnqí.","vi":"Bọn trẻ thấy mọi thứ ở thành phố đều mới lạ."},{"type":"compound","zh":"因为第一次出国，所以他觉得什么都很新奇。","pinyin":"Yīnwèi dìyīcì chūguó, suǒyǐ tā juéde shénme dōu hěn xīnqí.","vi":"Vì lần đầu ra nước ngoài nên anh ấy thấy cái gì cũng mới lạ."}],"related":[{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"mới mẻ"},{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ lạ"},{"hanzi":"好奇","pinyin":"hàoqí","vi":"tò mò"},{"hanzi":"稀奇","pinyin":"xīqí","vi":"hiếm lạ"}]},{"id":"新生","hanzi":"新生","pinyin":"xīnshēng","meaning_vi":"học sinh mới, tân sinh viên; mới ra đời, mới nảy sinh","explanation":"新 (tân – mới) + 生 (sinh – sinh ra, học trò) → mới sinh ra, mới nảy sinh; cũng chỉ học sinh, sinh viên mới nhập học.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🎒","examples":[{"type":"basic","zh":"新生明天报到。","pinyin":"Xīnshēng míngtiān bàodào.","vi":"Ngày mai tân sinh viên đến làm thủ tục nhập học."},{"type":"simple","zh":"学长们热情地帮新生搬行李。","pinyin":"Xuézhǎngmen rèqíng de bāng xīnshēng bān xíngli.","vi":"Các anh khóa trên nhiệt tình giúp tân sinh viên chuyển hành lý."},{"type":"compound","zh":"虽然新生对学校还不熟悉，但是很快就适应了。","pinyin":"Suīrán xīnshēng duì xuéxiào hái bù shúxī, dànshì hěn kuài jiù shìyìng le.","vi":"Tuy học sinh mới chưa quen trường nhưng đã nhanh chóng thích nghi."}],"related":[{"hanzi":"新人","pinyin":"xīnrén","vi":"người mới"},{"hanzi":"学生","pinyin":"xuésheng","vi":"học sinh"},{"hanzi":"入学","pinyin":"rùxué","vi":"nhập học"},{"hanzi":"新生儿","pinyin":"xīnshēng'ér","vi":"trẻ sơ sinh"}]},{"id":"新式","hanzi":"新式","pinyin":"xīnshì","meaning_vi":"kiểu mới, loại mới","explanation":"新 (tân – mới) + 式 (thức – kiểu) → kiểu mới, loại mới.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔧","examples":[{"type":"basic","zh":"这是新式武器。","pinyin":"Zhè shì xīnshì wǔqì.","vi":"Đây là vũ khí kiểu mới."},{"type":"simple","zh":"工厂引进了一批新式机器。","pinyin":"Gōngchǎng yǐnjìnle yìpī xīnshì jīqì.","vi":"Nhà máy nhập về một lô máy móc kiểu mới."},{"type":"compound","zh":"虽然新式教学方法很有趣，但是有些老师还不习惯。","pinyin":"Suīrán xīnshì jiàoxué fāngfǎ hěn yǒuqù, dànshì yǒuxiē lǎoshī hái bù xíguàn.","vi":"Tuy phương pháp dạy học kiểu mới rất thú vị nhưng một số giáo viên vẫn chưa quen."}],"related":[{"hanzi":"老式","pinyin":"lǎoshì","vi":"kiểu cũ"},{"hanzi":"新型","pinyin":"xīnxíng","vi":"loại mới"},{"hanzi":"样式","pinyin":"yàngshì","vi":"kiểu dáng"},{"hanzi":"现代","pinyin":"xiàndài","vi":"hiện đại"}]},{"id":"新手","hanzi":"新手","pinyin":"xīnshǒu","meaning_vi":"người mới, lính mới, tay mơ","explanation":"新 (tân – mới) + 手 (thủ – người làm một việc) → người mới vào nghề, chưa có kinh nghiệm.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔰","examples":[{"type":"basic","zh":"我还是个新手。","pinyin":"Wǒ háishi ge xīnshǒu.","vi":"Tôi vẫn còn là người mới."},{"type":"simple","zh":"新手司机开车一定要特别小心。","pinyin":"Xīnshǒu sījī kāichē yídìngyào tèbié xiǎoxīn.","vi":"Tài xế mới lái xe nhất định phải đặc biệt cẩn thận."},{"type":"compound","zh":"虽然他是个新手，但是学得比谁都快。","pinyin":"Suīrán tā shì ge xīnshǒu, dànshì xué de bǐ shéi dōu kuài.","vi":"Tuy anh ấy là người mới nhưng học nhanh hơn ai hết."}],"related":[{"hanzi":"老手","pinyin":"lǎoshǒu","vi":"tay lão luyện"},{"hanzi":"新人","pinyin":"xīnrén","vi":"người mới"},{"hanzi":"生手","pinyin":"shēngshǒu","vi":"tay mơ"},{"hanzi":"菜鸟","pinyin":"càiniǎo","vi":"lính mới"}]},{"id":"信件","hanzi":"信件","pinyin":"xìnjiàn","meaning_vi":"thư từ, thư tín","explanation":"信 (tín – thư) + 件 (kiện – món, bản) → các lá thư, thư từ gửi qua bưu điện.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"✉️","examples":[{"type":"basic","zh":"桌上有几封信件。","pinyin":"Zhuō shang yǒu jǐ fēng xìnjiàn.","vi":"Trên bàn có mấy lá thư."},{"type":"simple","zh":"邮递员每天上午送来一大堆信件。","pinyin":"Yóudìyuán měitiān shàngwǔ sòng lái yí dà duī xìnjiàn.","vi":"Người đưa thư sáng nào cũng mang đến một chồng thư lớn."},{"type":"compound","zh":"虽然现在有了电子邮件，但是他还是喜欢写纸质信件。","pinyin":"Suīrán xiànzài yǒule diànzǐ yóujiàn, dànshì tā háishi xǐhuan xiě zhǐzhì xìnjiàn.","vi":"Tuy giờ đã có thư điện tử nhưng ông ấy vẫn thích viết thư giấy."}],"related":[{"hanzi":"书信","pinyin":"shūxìn","vi":"thư từ"},{"hanzi":"邮件","pinyin":"yóujiàn","vi":"thư"},{"hanzi":"信封","pinyin":"xìnfēng","vi":"phong bì"},{"hanzi":"寄","pinyin":"jì","vi":"gửi"}]},{"id":"星座","hanzi":"星座","pinyin":"xīngzuò","meaning_vi":"chòm sao; cung hoàng đạo","explanation":"星 (tinh – sao) + 座 (tọa – chỗ, cụm) → cụm sao, chòm sao; còn chỉ cung hoàng đạo.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"♌","examples":[{"type":"basic","zh":"你是什么星座？","pinyin":"Nǐ shì shénme xīngzuò?","vi":"Bạn thuộc cung hoàng đạo nào?"},{"type":"simple","zh":"晴朗的夜里可以看到很多星座。","pinyin":"Qínglǎng de yèlǐ kěyǐ kàndào hěn duō xīngzuò.","vi":"Đêm trời quang có thể thấy rất nhiều chòm sao."},{"type":"compound","zh":"虽然她不太相信星座，但是每天都看星座运势。","pinyin":"Suīrán tā bú tài xiāngxìn xīngzuò, dànshì měitiān dōu kàn xīngzuò yùnshì.","vi":"Tuy không tin lắm vào cung hoàng đạo nhưng ngày nào cô ấy cũng xem tử vi."}],"related":[{"hanzi":"星星","pinyin":"xīngxing","vi":"ngôi sao"},{"hanzi":"星空","pinyin":"xīngkōng","vi":"bầu trời sao"},{"hanzi":"天文","pinyin":"tiānwén","vi":"thiên văn"},{"hanzi":"属相","pinyin":"shǔxiang","vi":"con giáp"}]},{"id":"猩猩","hanzi":"猩猩","pinyin":"xīngxing","meaning_vi":"đười ươi","explanation":"猩猩 (tinh tinh): tên gọi chung các loài vượn lớn, thường chỉ đười ươi.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦧","examples":[{"type":"basic","zh":"猩猩很聪明。","pinyin":"Xīngxing hěn cōngming.","vi":"Đười ươi rất thông minh."},{"type":"simple","zh":"动物园里的猩猩正在吃香蕉。","pinyin":"Dòngwùyuán lǐ de xīngxing zhèngzài chī xiāngjiāo.","vi":"Con đười ươi trong sở thú đang ăn chuối."},{"type":"compound","zh":"因为森林被砍伐，所以野生猩猩越来越少。","pinyin":"Yīnwèi sēnlín bèi kǎnfá, suǒyǐ yěshēng xīngxing yuèláiyuè shǎo.","vi":"Vì rừng bị chặt phá nên đười ươi hoang dã ngày càng ít."}],"related":[{"hanzi":"大猩猩","pinyin":"dàxīngxing","vi":"khỉ đột"},{"hanzi":"猴子","pinyin":"hóuzi","vi":"con khỉ"},{"hanzi":"动物园","pinyin":"dòngwùyuán","vi":"sở thú"},{"hanzi":"黑猩猩","pinyin":"hēixīngxing","vi":"tinh tinh"}]},{"id":"行情","hanzi":"行情","pinyin":"hángqíng","meaning_vi":"giá thị trường, tình hình thị trường","explanation":"行 (hàng – ngành nghề, thị trường) + 情 (tình – tình hình) → tình hình giá cả trên thị trường.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"最近房市行情不好。","pinyin":"Zuìjìn fángshì hángqíng bù hǎo.","vi":"Gần đây thị trường nhà đất không tốt."},{"type":"simple","zh":"他每天早上都要看股票行情。","pinyin":"Tā měitiān zǎo Shangdōu yào kàn gǔpiào hángqíng.","vi":"Sáng nào anh ấy cũng xem tình hình giá cổ phiếu."},{"type":"compound","zh":"如果你不了解市场行情，就很容易买贵了。","pinyin":"Rúguǒ nǐ bù liǎojiě shìchǎng hángqíng, jiù hěn róngyì mǎi guì le.","vi":"Nếu bạn không nắm giá thị trường thì rất dễ mua đắt."}],"related":[{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"},{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"},{"hanzi":"股票","pinyin":"gǔpiào","vi":"cổ phiếu"},{"hanzi":"行业","pinyin":"hángyè","vi":"ngành nghề"}]},{"id":"行使","hanzi":"行使","pinyin":"xíngshǐ","meaning_vi":"thực thi, sử dụng (quyền)","explanation":"行 (hành – làm) + 使 (sử – dùng) → đem ra sử dụng, thực thi một quyền hạn hay chức năng.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"公民有权行使投票权。","pinyin":"Gōngmín yǒuquán xíngshǐ tóupiàoquán.","vi":"Công dân có quyền thực hiện quyền bỏ phiếu."},{"type":"simple","zh":"法院依法独立行使审判权。","pinyin":"Fǎyuàn yīfǎ dúlì xíngshǐ shěnpànquán.","vi":"Tòa án độc lập thực thi quyền xét xử theo pháp luật."},{"type":"compound","zh":"如果你不按时行使权利，就可能失去这个机会。","pinyin":"Rúguǒ nǐ bú ànshí xíngshǐ quánlì, jiù kěnéng shīqù zhè ge jīhuì.","vi":"Nếu bạn không thực hiện quyền đúng hạn thì có thể mất cơ hội này."}],"related":[{"hanzi":"权利","pinyin":"quánlì","vi":"quyền lợi"},{"hanzi":"权力","pinyin":"quánlì","vi":"quyền lực"},{"hanzi":"执行","pinyin":"zhíxíng","vi":"chấp hành"},{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"}]},{"id":"行走","hanzi":"行走","pinyin":"xíngzǒu","meaning_vi":"đi, đi bộ","explanation":"行 (hành – đi) + 走 (tẩu – đi, chạy) → đi lại, bước đi.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚶","examples":[{"type":"basic","zh":"他在雪地里行走。","pinyin":"Tā zài xuědì lǐ xíngzǒu.","vi":"Anh ấy bước đi trên tuyết."},{"type":"simple","zh":"受伤以后他只能扶着墙慢慢行走。","pinyin":"Shòushāng yǐhòu tā zhǐnéng fúzhe qiáng mànmàn xíngzǒu.","vi":"Sau khi bị thương anh ấy chỉ có thể vịn tường đi chậm."},{"type":"compound","zh":"虽然山路很难行走，但是风景非常美。","pinyin":"Suīrán shānlù hěn nán xíngzǒu, dànshì fēngjǐng fēicháng měi.","vi":"Tuy đường núi rất khó đi nhưng phong cảnh vô cùng đẹp."}],"related":[{"hanzi":"走路","pinyin":"zǒulù","vi":"đi bộ"},{"hanzi":"步行","pinyin":"bùxíng","vi":"đi bộ"},{"hanzi":"散步","pinyin":"sànbù","vi":"tản bộ"},{"hanzi":"奔跑","pinyin":"bēnpǎo","vi":"chạy"}]},{"id":"形影不离","hanzi":"形影不离","pinyin":"xíngyǐng-bùlí","meaning_vi":"như hình với bóng, không rời nhau","explanation":"形 (hình – thân hình) + 影 (ảnh – cái bóng) + 不离 (bất ly – không rời) → như thân và bóng không bao giờ rời nhau, chỉ hai người rất thân thiết, lúc nào cũng ở bên nhau.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👯","examples":[{"type":"basic","zh":"她们俩形影不离。","pinyin":"Tāmen liǎ xíngyǐngbùlí.","vi":"Hai cô ấy như hình với bóng."},{"type":"simple","zh":"这对双胞胎从小就形影不离。","pinyin":"Zhè duì shuāngbāotāi cóngxiǎo jiù xíngyǐngbùlí.","vi":"Cặp song sinh này từ nhỏ đã như hình với bóng."},{"type":"compound","zh":"虽然以前他们形影不离，但是上大学后就很少见面了。","pinyin":"Suīrán yǐqián tāmen xíngyǐngbùlí, dànshì shàng dàxué hòu jiù hěn shǎojiàn miàn le.","vi":"Tuy trước kia họ như hình với bóng nhưng lên đại học thì ít gặp nhau."}],"related":[{"hanzi":"如影随形","pinyin":"rúyǐngsuíxíng","vi":"như bóng theo hình"},{"hanzi":"亲密","pinyin":"qīnmì","vi":"thân mật"},{"hanzi":"朝夕相处","pinyin":"zhāoxīxiāngchǔ","vi":"sớm tối bên nhau"},{"hanzi":"好朋友","pinyin":"hǎopéngyou","vi":"bạn thân"}],"traditional":"形影不離"},{"id":"醒来","hanzi":"醒来","pinyin":"xǐnglái","meaning_vi":"tỉnh dậy, thức dậy","explanation":"醒 (tỉnh – tỉnh) + 来 (lai – lại, ra) → tỉnh lại sau giấc ngủ hoặc hôn mê.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"⏰","examples":[{"type":"basic","zh":"他终于醒来了。","pinyin":"Tā zhōngyú xǐnglái le.","vi":"Cuối cùng anh ấy đã tỉnh lại."},{"type":"simple","zh":"我早上醒来发现外面下雪了。","pinyin":"Wǒ zǎoshang xǐnglái fāxiàn wàimiàn xiàxuě le.","vi":"Sáng tôi thức dậy thì thấy bên ngoài có tuyết rơi."},{"type":"compound","zh":"孩子半夜一醒来，就大声哭着要找妈妈。","pinyin":"Háizi bànyè yì xǐnglái, jiù dàshēng kūzhe yào zhǎo māma.","vi":"Đứa bé nửa đêm vừa tỉnh dậy là khóc to đòi mẹ."}],"related":[{"hanzi":"睡醒","pinyin":"shuìxǐng","vi":"ngủ dậy"},{"hanzi":"起床","pinyin":"qǐchuáng","vi":"thức dậy"},{"hanzi":"苏醒","pinyin":"sūxǐng","vi":"hồi tỉnh"},{"hanzi":"睡着","pinyin":"shuìzháo","vi":"ngủ thiếp"}],"traditional":"醒來"},{"id":"兴奋剂","hanzi":"兴奋剂","pinyin":"xīngfènjì","meaning_vi":"chất kích thích, doping","explanation":"兴奋 (hưng phấn) + 剂 (tễ – thuốc) → thuốc gây hưng phấn, chất kích thích; trong thể thao gọi là doping.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"💊","examples":[{"type":"basic","zh":"运动员禁止使用兴奋剂。","pinyin":"Yùndòngyuán jìnzhǐ shǐyòng xīngfènjì.","vi":"Vận động viên bị cấm sử dụng chất kích thích."},{"type":"simple","zh":"那位选手因为服用兴奋剂被取消了成绩。","pinyin":"Nà wèi xuǎnshǒu yīnwèi fúyòng xīngfènjì bèi qǔxiāole chéngjì.","vi":"Vận động viên đó bị hủy thành tích vì dùng doping."},{"type":"compound","zh":"一旦查出使用兴奋剂，运动员就会被禁赛。","pinyin":"Yídàn cháchū shǐyòng xīngfènjì, yùndòngyuán jiù huì bèi jìnsài.","vi":"Một khi bị phát hiện dùng doping, vận động viên sẽ bị cấm thi đấu."}],"related":[{"hanzi":"兴奋","pinyin":"xīngfèn","vi":"hưng phấn"},{"hanzi":"药物","pinyin":"yàowù","vi":"thuốc"},{"hanzi":"禁赛","pinyin":"jìnsài","vi":"cấm thi đấu"},{"hanzi":"检测","pinyin":"jiǎncè","vi":"kiểm tra"}],"traditional":"興奮劑"},{"id":"兴建","hanzi":"兴建","pinyin":"xīngjiàn","meaning_vi":"xây dựng, khởi công xây","explanation":"兴 (hưng – dấy lên, bắt đầu) + 建 (kiến – xây) → bắt đầu xây dựng công trình quy mô lớn.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏗️","examples":[{"type":"basic","zh":"这里正在兴建机场。","pinyin":"Zhèlǐ zhèngzài xīngjiàn jīchǎng.","vi":"Ở đây đang xây dựng sân bay."},{"type":"simple","zh":"政府计划在河上兴建一座大桥。","pinyin":"Zhèngfǔ jìhuà zài hé shang xīngjiàn yí zuò Dàqiáo.","vi":"Chính phủ dự định xây một cây cầu lớn trên sông."},{"type":"compound","zh":"因为人口增加，所以城里兴建了很多新学校。","pinyin":"Yīnwèi rénkǒu zēngjiā, suǒyǐ chénglǐ xīngjiànle hěn duō xīn xuéxiào.","vi":"Vì dân số tăng nên thành phố đã xây nhiều trường học mới."}],"related":[{"hanzi":"建设","pinyin":"jiànshè","vi":"xây dựng"},{"hanzi":"修建","pinyin":"xiūjiàn","vi":"xây dựng"},{"hanzi":"建造","pinyin":"jiànzào","vi":"xây cất"},{"hanzi":"工程","pinyin":"gōngchéng","vi":"công trình"}],"traditional":"興建"},{"id":"兴致","hanzi":"兴致","pinyin":"xìngzhì","meaning_vi":"hứng thú, hứng khởi","explanation":"兴 (hứng – hứng thú) + 致 (trí – ý vị) → hứng thú, cảm giác vui thích muốn làm việc gì.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🎉","examples":[{"type":"basic","zh":"大家兴致很高。","pinyin":"Dàjiā xìngzhì hěn gāo.","vi":"Mọi người rất hào hứng."},{"type":"simple","zh":"爷爷兴致勃勃地给我们讲他年轻时的故事。","pinyin":"Yéye xìngzhìbóbó de gěi wǒmen jiǎng tā niánqīng shí de gùshi.","vi":"Ông nội hào hứng kể cho chúng tôi nghe chuyện thời trẻ."},{"type":"compound","zh":"虽然下着小雨，但是游客们的兴致一点儿也没减。","pinyin":"Suīrán xiàzhe xiǎoyǔ, dànshì yóukèmen de xìngzhì yìdiǎnr yě méi jiǎn.","vi":"Tuy trời mưa nhỏ nhưng sự hào hứng của du khách không hề giảm."}],"related":[{"hanzi":"兴趣","pinyin":"xìngqù","vi":"hứng thú"},{"hanzi":"兴致勃勃","pinyin":"xìngzhìbóbó","vi":"hào hứng"},{"hanzi":"扫兴","pinyin":"sǎoxìng","vi":"mất hứng"},{"hanzi":"心情","pinyin":"xīnqíng","vi":"tâm trạng"}],"traditional":"興致"},{"id":"姓氏","hanzi":"姓氏","pinyin":"xìngshì","meaning_vi":"họ, dòng họ","explanation":"姓 (tính – họ) + 氏 (thị – họ, dòng tộc) → họ của một người, dòng họ.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👪","examples":[{"type":"basic","zh":"中国姓氏很多。","pinyin":"Zhōngguó xìngshì hěn duō.","vi":"Họ của người Trung Quốc rất nhiều."},{"type":"simple","zh":"李是中国人数最多的姓氏之一。","pinyin":"Lǐ shì Zhōngguó rénshù zuì duō de xìngshì zhīyī.","vi":"Lý là một trong những họ đông người nhất Trung Quốc."},{"type":"compound","zh":"虽然两国的姓氏写法不同，但是很多来源是一样的。","pinyin":"Suīrán liǎngguó de xìngshì xiěfǎ bùtóng, dànshì hěn duō láiyuán shì yíyàng de.","vi":"Tuy cách viết họ của hai nước khác nhau nhưng nhiều họ có cùng nguồn gốc."}],"related":[{"hanzi":"姓","pinyin":"xìng","vi":"họ"},{"hanzi":"名字","pinyin":"míngzi","vi":"tên"},{"hanzi":"家族","pinyin":"jiāzú","vi":"gia tộc"},{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"}]},{"id":"幸存","hanzi":"幸存","pinyin":"xìngcún","meaning_vi":"sống sót, may mắn còn lại","explanation":"幸 (hạnh – may mắn) + 存 (tồn – còn) → may mắn còn sống sót sau tai họa.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛟","examples":[{"type":"basic","zh":"他是唯一幸存的人。","pinyin":"Tā shì wéiyī xìngcún de rén.","vi":"Anh ấy là người duy nhất sống sót."},{"type":"simple","zh":"这座古塔在地震中幸存了下来。","pinyin":"Zhè zuò Gǔtǎ zài dìzhèn zhōng xìngcúnle xiàlái.","vi":"Ngôi tháp cổ này may mắn còn lại sau trận động đất."},{"type":"compound","zh":"虽然他在事故中幸存，但是失去了一条腿。","pinyin":"Suīrán tā zài shìgù zhōng xìngcún, dànshì shīqùle yì tiáo tuǐ.","vi":"Tuy sống sót trong tai nạn nhưng anh ấy mất một chân."}],"related":[{"hanzi":"幸存者","pinyin":"xìngcúnzhě","vi":"người sống sót"},{"hanzi":"幸免","pinyin":"xìngmiǎn","vi":"may mắn thoát khỏi"},{"hanzi":"生存","pinyin":"shēngcún","vi":"sinh tồn"},{"hanzi":"遇难","pinyin":"yùnàn","vi":"gặp nạn"}],"traditional":"倖存"},{"id":"幸好","hanzi":"幸好","pinyin":"xìnghǎo","meaning_vi":"may mà, may quá","explanation":"幸 (hạnh – may mắn) + 好 (hảo – tốt) → may mà, nhờ có điều kiện thuận lợi nên tránh được điều xấu.","hsk_level":"7-9","tags":["pho-tu"],"image":"🍀","examples":[{"type":"basic","zh":"幸好你来了。","pinyin":"Xìnghǎo nǐ lái le.","vi":"May mà bạn đến."},{"type":"simple","zh":"幸好我带了伞，没被雨淋湿。","pinyin":"Xìnghǎo wǒ dàile sǎn, méi bèi yǔ línshī.","vi":"May mà tôi mang ô nên không bị ướt mưa."},{"type":"compound","zh":"幸好医生发现得早，不然后果就非常严重了。","pinyin":"Xìnghǎo yīshēng fāxiàn de zǎo, bùrán hòuguǒ jiù fēicháng yánzhòng le.","vi":"May mà bác sĩ phát hiện sớm, nếu không hậu quả đã rất nghiêm trọng."}],"related":[{"hanzi":"幸亏","pinyin":"xìngkuī","vi":"may mà"},{"hanzi":"好在","pinyin":"hǎozài","vi":"may là"},{"hanzi":"幸运","pinyin":"xìngyùn","vi":"may mắn"},{"hanzi":"不然","pinyin":"bùrán","vi":"nếu không"}]},{"id":"幸亏","hanzi":"幸亏","pinyin":"xìngkuī","meaning_vi":"may mà, may nhờ","explanation":"幸 (hạnh – may mắn) + 亏 (khuy – nhờ có) → may nhờ có, may mà; thường đi với 不然, 否则.","hsk_level":"7-9","tags":["pho-tu"],"image":"🙏","examples":[{"type":"basic","zh":"幸亏没有下雨。","pinyin":"Xìngkuī méiyǒu xiàyǔ.","vi":"May mà trời không mưa."},{"type":"simple","zh":"幸亏邻居及时报警，火很快被扑灭了。","pinyin":"Xìngkuī línjū jíshí bàojǐng, huǒ hěn kuài bèi pūmiè le.","vi":"May mà hàng xóm kịp thời báo cảnh sát nên lửa được dập tắt nhanh."},{"type":"compound","zh":"幸亏你提醒了我，否则我就忘了带护照。","pinyin":"Xìngkuī nǐ tíxǐngle wǒ, fǒuzé wǒ jiù wàngle dài hùzhào.","vi":"May mà bạn nhắc tôi, nếu không tôi đã quên mang hộ chiếu."}],"related":[{"hanzi":"幸好","pinyin":"xìnghǎo","vi":"may mà"},{"hanzi":"多亏","pinyin":"duōkuī","vi":"nhờ có"},{"hanzi":"否则","pinyin":"fǒuzé","vi":"nếu không"},{"hanzi":"侥幸","pinyin":"jiǎoxìng","vi":"may mắn hú họa"}],"traditional":"幸虧"},{"id":"幸免","hanzi":"幸免","pinyin":"xìngmiǎn","meaning_vi":"may mắn thoát khỏi","explanation":"幸 (hạnh – may mắn) + 免 (miễn – tránh khỏi) → may mắn tránh được tai họa.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"只有他幸免于难。","pinyin":"Zhǐyǒu tā xìngmiǎn yú nàn.","vi":"Chỉ có anh ấy may mắn thoát nạn."},{"type":"simple","zh":"大火烧了整条街，只有这家店幸免。","pinyin":"Dà huǒshāole zhěngtiáo jiē, zhǐyǒu zhè jiā diàn xìngmiǎn.","vi":"Đám cháy thiêu rụi cả con phố, chỉ có cửa hàng này thoát được."},{"type":"compound","zh":"因为他那天请假在家，所以幸免于这场事故。","pinyin":"Yīnwèi tā nà tiān qǐngjià zài jiā, suǒyǐ xìngmiǎn yú zhè chǎng shìgù.","vi":"Vì hôm đó anh ấy xin nghỉ ở nhà nên may mắn thoát khỏi tai nạn này."}],"related":[{"hanzi":"幸存","pinyin":"xìngcún","vi":"sống sót"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh"},{"hanzi":"逃脱","pinyin":"táotuō","vi":"thoát khỏi"},{"hanzi":"幸运","pinyin":"xìngyùn","vi":"may mắn"}],"traditional":"倖免"},{"id":"凶残","hanzi":"凶残","pinyin":"xiōngcán","meaning_vi":"hung tàn, tàn bạo","explanation":"凶 (hung – hung ác) + 残 (tàn – tàn bạo) → hung ác và tàn bạo.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🐺","examples":[{"type":"basic","zh":"狼是凶残的动物。","pinyin":"Láng shì xiōngcán de dòngwù.","vi":"Sói là loài động vật hung tàn."},{"type":"simple","zh":"警方终于抓住了那个凶残的罪犯。","pinyin":"Jǐngfāng zhōngyú zhuāzhùle nà ge xiōngcán de zuìfàn.","vi":"Cảnh sát cuối cùng đã bắt được tên tội phạm tàn bạo đó."},{"type":"compound","zh":"虽然敌人非常凶残，但是村民们没有屈服。","pinyin":"Suīrán dírén fēicháng xiōngcán, dànshì cūnmínmen méiyǒu qūfú.","vi":"Tuy kẻ thù vô cùng tàn bạo nhưng dân làng không khuất phục."}],"related":[{"hanzi":"残忍","pinyin":"cánrěn","vi":"tàn nhẫn"},{"hanzi":"凶狠","pinyin":"xiōnghěn","vi":"hung dữ"},{"hanzi":"残暴","pinyin":"cánbào","vi":"tàn bạo"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"}],"traditional":"兇殘"},{"id":"凶狠","hanzi":"凶狠","pinyin":"xiōnghěn","meaning_vi":"hung dữ, hung ác","explanation":"凶 (hung – hung ác) + 狠 (ngận – độc ác) → hung dữ, độc ác.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😠","examples":[{"type":"basic","zh":"那只狗很凶狠。","pinyin":"Nà zhī gǒu hěn xiōnghěn.","vi":"Con chó đó rất hung dữ."},{"type":"simple","zh":"他用凶狠的眼神盯着对手。","pinyin":"Tāyòng xiōnghěn de yǎnshén dīngzhe duìshǒu.","vi":"Anh ta nhìn chằm chằm đối thủ bằng ánh mắt hung dữ."},{"type":"compound","zh":"虽然他样子很凶狠，但是其实是个好人。","pinyin":"Suīrán tā yàngzi hěn xiōnghěn, dànshì qíshí shì ge hǎorén.","vi":"Tuy trông anh ta rất dữ tợn nhưng thực ra là người tốt."}],"related":[{"hanzi":"凶残","pinyin":"xiōngcán","vi":"hung tàn"},{"hanzi":"凶恶","pinyin":"xiōng'è","vi":"hung ác"},{"hanzi":"狠毒","pinyin":"hěndú","vi":"độc ác"},{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"}],"traditional":"兇狠"},{"id":"汹涌","hanzi":"汹涌","pinyin":"xiōngyǒng","meaning_vi":"cuồn cuộn, dữ dội (sóng nước)","explanation":"汹 (hung – nước dâng mạnh) + 涌 (dũng – trào lên) → nước dâng trào cuồn cuộn dữ dội.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"海浪十分汹涌。","pinyin":"Hǎilàng shífēn xiōngyǒng.","vi":"Sóng biển vô cùng dữ dội."},{"type":"simple","zh":"汹涌的河水冲垮了村口的小桥。","pinyin":"Xiōngyǒng de héshuǐ chōngkuǎle cūn kǒu de Xiǎoqiáo.","vi":"Nước sông cuồn cuộn cuốn sập cây cầu nhỏ đầu làng."},{"type":"compound","zh":"因为海面波涛汹涌，所以渔船都不敢出海。","pinyin":"Yīnwèi hǎimiàn bōtāo xiōngyǒng, suǒyǐ yúchuán dōu bù gǎn chūhǎi.","vi":"Vì mặt biển sóng to cuồn cuộn nên thuyền đánh cá đều không dám ra khơi."}],"related":[{"hanzi":"波涛","pinyin":"bōtāo","vi":"sóng lớn"},{"hanzi":"澎湃","pinyin":"péngpài","vi":"cuồn cuộn"},{"hanzi":"平静","pinyin":"píngjìng","vi":"yên ả"},{"hanzi":"海浪","pinyin":"hǎilàng","vi":"sóng biển"}],"traditional":"洶湧"},{"id":"胸膛","hanzi":"胸膛","pinyin":"xiōngtáng","meaning_vi":"lồng ngực, ngực","explanation":"胸 (hung – ngực) + 膛 (thang – khoang) → khoang ngực, lồng ngực.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"💪","examples":[{"type":"basic","zh":"他挺起了胸膛。","pinyin":"Tā tǐng qǐle xiōngtáng.","vi":"Anh ấy ưỡn ngực lên."},{"type":"simple","zh":"孩子把头靠在爸爸宽阔的胸膛上。","pinyin":"Háizi bǎ tóu kào zài bàba kuānkuò de xiōngtáng shang.","vi":"Đứa bé tựa đầu vào lồng ngực rộng của bố."},{"type":"compound","zh":"虽然输了比赛，但是队员们依然挺着胸膛走出赛场。","pinyin":"Suīrán shūle bǐsài, dànshì duìyuánmen yīrán tǐngzhe xiōngtáng zǒuchū sàichǎng.","vi":"Tuy thua trận nhưng các cầu thủ vẫn ưỡn ngực bước ra khỏi sân."}],"related":[{"hanzi":"胸口","pinyin":"xiōngkǒu","vi":"ngực"},{"hanzi":"胸部","pinyin":"xiōngbù","vi":"vùng ngực"},{"hanzi":"挺胸","pinyin":"tǐngxiōng","vi":"ưỡn ngực"},{"hanzi":"肩膀","pinyin":"jiānbǎng","vi":"vai"}]},{"id":"休克","hanzi":"休克","pinyin":"xiūkè","meaning_vi":"sốc, choáng (y học)","explanation":"休克: phiên âm từ tiếng Anh \"shock\" → tình trạng sốc, choáng do mất máu, dị ứng, tuần hoàn suy giảm.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🚑","examples":[{"type":"basic","zh":"病人休克了！","pinyin":"Bìngrén xiūkè le!","vi":"Bệnh nhân bị sốc rồi!"},{"type":"simple","zh":"他因为失血过多而休克。","pinyin":"Tā yīnwèi shīxuè guòduō ér xiūkè.","vi":"Anh ấy bị sốc vì mất máu quá nhiều."},{"type":"compound","zh":"如果过敏严重，病人就可能出现休克。","pinyin":"Rúguǒ guòmǐn yánzhòng, bìngrén jiù kěnéng chūxiàn xiūkè.","vi":"Nếu dị ứng nặng thì bệnh nhân có thể bị sốc."}],"related":[{"hanzi":"昏迷","pinyin":"hūnmí","vi":"hôn mê"},{"hanzi":"晕倒","pinyin":"yūndǎo","vi":"ngất xỉu"},{"hanzi":"抢救","pinyin":"qiǎngjiù","vi":"cấp cứu"},{"hanzi":"过敏","pinyin":"guòmǐn","vi":"dị ứng"}]},{"id":"休眠","hanzi":"休眠","pinyin":"xiūmián","meaning_vi":"ngủ đông, ngủ yên (sinh vật, núi lửa); chế độ ngủ (máy tính)","explanation":"休 (hưu – nghỉ) + 眠 (miên – ngủ) → ở trạng thái nghỉ, tạm ngừng hoạt động; dùng cho núi lửa, sinh vật, máy tính.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"💤","examples":[{"type":"basic","zh":"这是一座休眠火山。","pinyin":"Zhè shì yí zuò xiūmián huǒshān.","vi":"Đây là một ngọn núi lửa đang ngủ."},{"type":"simple","zh":"电脑长时间不用会自动进入休眠状态。","pinyin":"Diànnǎo cháng shíjiān bú yòng huì zìdòng jìnrù xiūmián zhuàngtài.","vi":"Máy tính lâu không dùng sẽ tự động vào chế độ ngủ."},{"type":"compound","zh":"虽然种子在冬天休眠，但是春天一到就会发芽。","pinyin":"Suīrán zhǒngzi zài dōngtiān xiūmián, dànshì chūntiān yí dào jiù huì fāyá.","vi":"Tuy hạt giống ngủ yên trong mùa đông nhưng xuân đến là nảy mầm."}],"related":[{"hanzi":"冬眠","pinyin":"dōngmián","vi":"ngủ đông"},{"hanzi":"睡眠","pinyin":"shuìmián","vi":"giấc ngủ"},{"hanzi":"待机","pinyin":"dàijī","vi":"chế độ chờ"},{"hanzi":"火山","pinyin":"huǒshān","vi":"núi lửa"}]},{"id":"休想","hanzi":"休想","pinyin":"xiūxiǎng","meaning_vi":"đừng hòng, đừng mơ","explanation":"休 (hưu – đừng, thôi) + 想 (tưởng – nghĩ) → đừng có nghĩ đến, đừng hòng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"你休想骗我！","pinyin":"Nǐ xiūxiǎng piàn wǒ!","vi":"Anh đừng hòng lừa tôi!"},{"type":"simple","zh":"不交钱的话，你休想拿走这些东西。","pinyin":"Bù jiāoqián dehuà, nǐ xiūxiǎng názǒu zhèxiē dōngxi.","vi":"Không trả tiền thì đừng hòng mang những thứ này đi."},{"type":"compound","zh":"如果你不向我道歉，就休想让我原谅你。","pinyin":"Rúguǒ nǐ bú xiàng wǒ dàoqiàn, jiù xiūxiǎng ràng wǒ yuánliàng nǐ.","vi":"Nếu bạn không xin lỗi tôi thì đừng mơ tôi tha thứ."}],"related":[{"hanzi":"别想","pinyin":"biéxiǎng","vi":"đừng nghĩ"},{"hanzi":"妄想","pinyin":"wàngxiǎng","vi":"vọng tưởng"},{"hanzi":"做梦","pinyin":"zuòmèng","vi":"nằm mơ"},{"hanzi":"不可能","pinyin":"bùkěnéng","vi":"không thể"}]},{"id":"修补","hanzi":"修补","pinyin":"xiūbǔ","meaning_vi":"sửa chữa, vá, tu bổ","explanation":"修 (tu – sửa) + 补 (bổ – vá, bù) → sửa chữa chỗ hỏng, vá lại.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧵","examples":[{"type":"basic","zh":"他在修补渔网。","pinyin":"Tā zài xiūbǔ yúwǎng.","vi":"Ông ấy đang vá lưới đánh cá."},{"type":"simple","zh":"工人们正在修补被雨水冲坏的路面。","pinyin":"Gōngrénmen zhèngzài xiūbǔ bèi yǔshuǐ chōng huài de lùmiàn.","vi":"Công nhân đang sửa mặt đường bị nước mưa làm hỏng."},{"type":"compound","zh":"虽然花瓶已经修补好了，但是还能看出裂痕。","pinyin":"Suīrán huāpíng yǐjīng xiūbǔ hǎo le, dànshì hái néng kànchū lièhén.","vi":"Tuy chiếc bình đã được sửa xong nhưng vẫn nhìn thấy vết nứt."}],"related":[{"hanzi":"修理","pinyin":"xiūlǐ","vi":"sửa chữa"},{"hanzi":"弥补","pinyin":"míbǔ","vi":"bù đắp"},{"hanzi":"补","pinyin":"bǔ","vi":"vá"},{"hanzi":"修复","pinyin":"xiūfù","vi":"phục hồi"}],"traditional":"修補"},{"id":"修订","hanzi":"修订","pinyin":"xiūdìng","meaning_vi":"sửa đổi, hiệu đính","explanation":"修 (tu – sửa) + 订 (đính – đính chính) → sửa chữa, hiệu đính văn bản, sách, luật.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"这本词典修订了。","pinyin":"Zhè běn cídiǎn xiūdìng le.","vi":"Cuốn từ điển này đã được hiệu đính."},{"type":"simple","zh":"专家们正在修订新版的教材。","pinyin":"Zhuānjiāmen zhèngzài xiūdìng xīnbǎn de jiàocái.","vi":"Các chuyên gia đang hiệu đính giáo trình phiên bản mới."},{"type":"compound","zh":"因为法律已经过时，所以议会决定重新修订。","pinyin":"Yīnwèi fǎlǜ yǐjīng guòshí, suǒyǐ yìhuì juédìng chóngxīn xiūdìng.","vi":"Vì luật đã lỗi thời nên quốc hội quyết định sửa đổi lại."}],"related":[{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa đổi"},{"hanzi":"修正","pinyin":"xiūzhèng","vi":"sửa chữa"},{"hanzi":"订正","pinyin":"dìngzhèng","vi":"đính chính"},{"hanzi":"版本","pinyin":"bǎnběn","vi":"phiên bản"}],"traditional":"修訂"},{"id":"修路","hanzi":"修路","pinyin":"xiūlù","meaning_vi":"sửa đường, làm đường","explanation":"修 (tu – sửa, xây) + 路 (lộ – đường) → sửa chữa hoặc xây dựng đường sá.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚧","examples":[{"type":"basic","zh":"前面正在修路。","pinyin":"Qiánmiàn zhèngzài xiūlù.","vi":"Phía trước đang sửa đường."},{"type":"simple","zh":"村里集资修路，家家户户都出了钱。","pinyin":"Cūnlǐ jízī xiūlù, jiājiāhùhù dōu chūle qián.","vi":"Làng góp vốn làm đường, nhà nào cũng góp tiền."},{"type":"compound","zh":"因为这条街在修路，所以公交车要绕道走。","pinyin":"Yīnwèi zhè tiáo jiē zài xiūlù, suǒyǐ gōngjiāochē yào ràodào zǒu.","vi":"Vì con phố này đang sửa đường nên xe buýt phải đi đường vòng."}],"related":[{"hanzi":"修建","pinyin":"xiūjiàn","vi":"xây dựng"},{"hanzi":"道路","pinyin":"dàolù","vi":"đường sá"},{"hanzi":"施工","pinyin":"shīgōng","vi":"thi công"},{"hanzi":"绕道","pinyin":"ràodào","vi":"đi đường vòng"}]},{"id":"修长","hanzi":"修长","pinyin":"xiūcháng","meaning_vi":"thon dài, mảnh dẻ","explanation":"修 (tu – dài) + 长 (trường – dài) → dài và thon, thường tả dáng người, ngón tay, cổ.","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"🦒","examples":[{"type":"basic","zh":"她的手指很修长。","pinyin":"Tā de shǒuzhǐ hěn xiūcháng.","vi":"Ngón tay cô ấy rất thon dài."},{"type":"simple","zh":"那位模特有一双修长的腿。","pinyin":"Nà wèi mótè yǒu yì shuāng xiūcháng de tuǐ.","vi":"Người mẫu đó có đôi chân thon dài."},{"type":"compound","zh":"虽然他的身材很修长，但是力气非常大。","pinyin":"Suīrán tā de shēncái hěn xiūcháng, dànshì lìqi fēicháng dà.","vi":"Tuy dáng người anh ấy mảnh khảnh nhưng sức rất khỏe."}],"related":[{"hanzi":"苗条","pinyin":"miáotiao","vi":"thon thả"},{"hanzi":"细长","pinyin":"xìcháng","vi":"dài mảnh"},{"hanzi":"高挑","pinyin":"gāotiǎo","vi":"cao ráo"},{"hanzi":"身材","pinyin":"shēncái","vi":"vóc dáng"}],"traditional":"修長"},{"id":"修正","hanzi":"修正","pinyin":"xiūzhèng","meaning_vi":"sửa chữa, chỉnh sửa, đính chính","explanation":"修 (tu – sửa) + 正 (chính – đúng) → sửa cho đúng.","hsk_level":"7-9","tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"请修正这个错误。","pinyin":"Qǐng xiūzhèng zhè ge cuòwù.","vi":"Hãy sửa lỗi này."},{"type":"simple","zh":"科学家根据新数据修正了原来的结论。","pinyin":"Kēxuéjiā gēnjù xīn shùjù xiūzhèngle yuánlái de jiélùn.","vi":"Các nhà khoa học đã điều chỉnh kết luận cũ dựa trên dữ liệu mới."},{"type":"compound","zh":"如果发现计划有问题，就要及时修正。","pinyin":"Rúguǒ fāxiàn jìhuà yǒu wèntí, jiùyào jíshí xiūzhèng.","vi":"Nếu phát hiện kế hoạch có vấn đề thì phải kịp thời điều chỉnh."}],"related":[{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa đổi"},{"hanzi":"纠正","pinyin":"jiūzhèng","vi":"uốn nắn"},{"hanzi":"改正","pinyin":"gǎizhèng","vi":"sửa sai"},{"hanzi":"修订","pinyin":"xiūdìng","vi":"hiệu đính"}]},{"id":"羞愧","hanzi":"羞愧","pinyin":"xiūkuì","meaning_vi":"xấu hổ, hổ thẹn","explanation":"羞 (tu – thẹn) + 愧 (quý – hổ thẹn) → xấu hổ, hổ thẹn vì lỗi của mình.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"他羞愧地低下了头。","pinyin":"Tā xiūkuì de dīxiàle tóu.","vi":"Anh ấy xấu hổ cúi đầu."},{"type":"simple","zh":"撒谎被发现后，他感到非常羞愧。","pinyin":"Sāhuǎng bèi fāxiàn hòu, tā gǎndào fēicháng xiūkuì.","vi":"Bị phát hiện nói dối, cậu ấy cảm thấy vô cùng xấu hổ."},{"type":"compound","zh":"虽然他觉得很羞愧，但是还是勇敢地承认了错误。","pinyin":"Suīrán tā juéde hěn xiūkuì, dànshì háishi yǒnggǎn de chéngrènle cuòwù.","vi":"Tuy thấy rất hổ thẹn nhưng anh ấy vẫn dũng cảm nhận lỗi."}],"related":[{"hanzi":"惭愧","pinyin":"cánkuì","vi":"hổ thẹn"},{"hanzi":"害羞","pinyin":"hàixiū","vi":"ngượng ngùng"},{"hanzi":"内疚","pinyin":"nèijiù","vi":"áy náy"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"}]},{"id":"秀丽","hanzi":"秀丽","pinyin":"xiùlì","meaning_vi":"xinh đẹp, tươi đẹp, thanh tú","explanation":"秀 (tú – đẹp, thanh tú) + 丽 (lệ – đẹp) → đẹp đẽ, thanh tú; thường tả phong cảnh hoặc nét chữ, dung mạo.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"这里山水秀丽。","pinyin":"Zhèlǐ shānshuǐ xiùlì.","vi":"Non nước nơi đây tươi đẹp."},{"type":"simple","zh":"桂林以秀丽的山水风光闻名世界。","pinyin":"Guìlín yǐ xiùlì de shānshuǐ fēngguāng wénmíng shìjiè.","vi":"Quế Lâm nổi tiếng thế giới nhờ phong cảnh non nước tươi đẹp."},{"type":"compound","zh":"虽然她的字写得很秀丽，但是速度有点儿慢。","pinyin":"Suīrán tā de zì xiě de hěn xiùlì, dànshì sùdù yǒudiǎnr màn.","vi":"Tuy chữ cô ấy viết rất đẹp nhưng tốc độ hơi chậm."}],"related":[{"hanzi":"美丽","pinyin":"měilì","vi":"xinh đẹp"},{"hanzi":"秀美","pinyin":"xiùměi","vi":"thanh tú"},{"hanzi":"风景","pinyin":"fēngjǐng","vi":"phong cảnh"},{"hanzi":"壮丽","pinyin":"zhuànglì","vi":"hùng vĩ"}],"traditional":"秀麗"},{"id":"秀美","hanzi":"秀美","pinyin":"xiùměi","meaning_vi":"thanh tú, duyên dáng","explanation":"秀 (tú – thanh tú) + 美 (mỹ – đẹp) → đẹp một cách thanh nhã, duyên dáng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌸","examples":[{"type":"basic","zh":"她长得很秀美。","pinyin":"Tā zhǎngde hěn xiùměi.","vi":"Cô ấy trông rất thanh tú."},{"type":"simple","zh":"江南的小镇有一种秀美的气质。","pinyin":"Jiāngnán de xiǎozhèn yǒu yì zhǒng xiùměi de qìzhì.","vi":"Các thị trấn nhỏ Giang Nam mang một vẻ đẹp duyên dáng."},{"type":"compound","zh":"虽然这里没有高山大河，但是风景十分秀美。","pinyin":"Suīrán zhèlǐ méiyǒu gāoshān dàhé, dànshì fēngjǐng shífēn xiùměi.","vi":"Tuy nơi đây không có núi cao sông lớn nhưng phong cảnh rất duyên dáng."}],"related":[{"hanzi":"秀丽","pinyin":"xiùlì","vi":"tươi đẹp"},{"hanzi":"优美","pinyin":"yōuměi","vi":"thanh nhã"},{"hanzi":"清秀","pinyin":"qīngxiù","vi":"thanh tú"},{"hanzi":"美丽","pinyin":"měilì","vi":"xinh đẹp"}]},{"id":"锈","hanzi":"锈","pinyin":"xiù","meaning_vi":"gỉ sét, rỉ","explanation":"锈 (tú – gỉ): lớp gỉ hình thành trên bề mặt kim loại do bị ôxy hóa; cũng dùng như động từ \"bị gỉ\".","hsk_level":"7-9","tags":["danh-tu"],"image":"🔩","examples":[{"type":"basic","zh":"铁门生锈了。","pinyin":"Tiě mén shēngxiù le.","vi":"Cánh cổng sắt bị gỉ rồi."},{"type":"simple","zh":"这把旧刀已经锈得切不动菜了。","pinyin":"Zhè bǎ jiù dāo yǐjīng xiù de qiē budòng cài le.","vi":"Con dao cũ này đã gỉ đến mức không thái nổi rau."},{"type":"compound","zh":"如果自行车经常淋雨，链条就容易生锈。","pinyin":"Rúguǒ zìxíngchē jīngcháng línyǔ, liàntiáo jiù róngyì shēngxiù.","vi":"Nếu xe đạp thường xuyên dầm mưa thì xích xe dễ bị gỉ."}],"related":[{"hanzi":"生锈","pinyin":"shēngxiù","vi":"bị gỉ"},{"hanzi":"铁锈","pinyin":"tiěxiù","vi":"gỉ sắt"},{"hanzi":"不锈钢","pinyin":"búxiùgāng","vi":"thép không gỉ"},{"hanzi":"腐蚀","pinyin":"fǔshí","vi":"ăn mòn"}],"traditional":"鏽"},{"id":"须","hanzi":"须","pinyin":"xū","meaning_vi":"phải, cần phải","explanation":"须 (tu – cần, phải): biểu thị điều bắt buộc phải làm; thường gặp trong văn viết như 必须, 须知.","hsk_level":"7-9","tags":["pho-tu"],"image":"❗","examples":[{"type":"basic","zh":"出门须带证件。","pinyin":"Chūmén xū dài zhèngjiàn.","vi":"Ra ngoài phải mang giấy tờ."},{"type":"simple","zh":"所有乘客上车前须出示车票。","pinyin":"Suǒyǒu chéngkè shàng chēqián xū chūshì chēpiào.","vi":"Tất cả hành khách phải xuất trình vé trước khi lên xe."},{"type":"compound","zh":"如果要参加比赛，就须在月底前报名。","pinyin":"Rúguǒ yào cānjiā bǐsài, jiù xū zài yuèdǐ qián bàomíng.","vi":"Nếu muốn tham gia cuộc thi thì phải đăng ký trước cuối tháng."}],"related":[{"hanzi":"必须","pinyin":"bìxū","vi":"bắt buộc"},{"hanzi":"须知","pinyin":"xūzhī","vi":"điều cần biết"},{"hanzi":"无须","pinyin":"wúxū","vi":"không cần"},{"hanzi":"需要","pinyin":"xūyào","vi":"cần"}],"traditional":"須"},{"id":"虚","hanzi":"虚","pinyin":"xū","meaning_vi":"trống rỗng; giả, hư; yếu (sức khỏe); chột dạ","explanation":"虚 (hư – trống rỗng): không có thực chất, giả dối; cũng chỉ cơ thể suy yếu hoặc trong lòng chột dạ.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🫥","examples":[{"type":"basic","zh":"他身体有点儿虚。","pinyin":"Tā shēntǐ yǒudiǎnr xū.","vi":"Người anh ấy hơi yếu."},{"type":"simple","zh":"他说话的时候心里有点儿虚。","pinyin":"Tā shuōhuà de shíhou xīnlǐ yǒudiǎnr xū.","vi":"Lúc nói chuyện anh ấy hơi chột dạ."},{"type":"compound","zh":"虽然广告说得很好，但是内容大多是虚的。","pinyin":"Suīrán guǎnggào shuō de hěn hǎo, dànshì nèiróng dàduō shì xū de.","vi":"Tuy quảng cáo nói rất hay nhưng phần lớn nội dung là giả."}],"related":[{"hanzi":"空虚","pinyin":"kōngxū","vi":"trống rỗng"},{"hanzi":"虚假","pinyin":"xūjiǎ","vi":"giả dối"},{"hanzi":"虚弱","pinyin":"xūruò","vi":"yếu ớt"},{"hanzi":"实","pinyin":"shí","vi":"thực"}],"traditional":"虛"},{"id":"虚幻","hanzi":"虚幻","pinyin":"xūhuàn","meaning_vi":"hư ảo, ảo tưởng","explanation":"虚 (hư – không thực) + 幻 (huyễn – ảo) → hư ảo, không có thật.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"那只是虚幻的梦。","pinyin":"Nà zhǐshì xūhuàn de mèng.","vi":"Đó chỉ là giấc mơ hư ảo."},{"type":"simple","zh":"电影把观众带进了一个虚幻的世界。","pinyin":"Diànyǐng bǎ guānzhòng dài jìnle yí gè xūhuàn de shìjiè.","vi":"Bộ phim đưa khán giả vào một thế giới ảo."},{"type":"compound","zh":"虽然网络上的生活很精彩，但是很多东西是虚幻的。","pinyin":"Suīrán wǎngluò shang de shēnghuó hěn jīngcǎi, dànshì hěn duō dōngxi shì xūhuàn de.","vi":"Tuy cuộc sống trên mạng rất đặc sắc nhưng nhiều thứ là hư ảo."}],"related":[{"hanzi":"虚拟","pinyin":"xūnǐ","vi":"ảo"},{"hanzi":"幻想","pinyin":"huànxiǎng","vi":"ảo tưởng"},{"hanzi":"现实","pinyin":"xiànshí","vi":"hiện thực"},{"hanzi":"梦幻","pinyin":"mènghuàn","vi":"mộng ảo"}],"traditional":"虛幻"},{"id":"虚弱","hanzi":"虚弱","pinyin":"xūruò","meaning_vi":"yếu ớt, suy nhược","explanation":"虚 (hư – trống, suy) + 弱 (nhược – yếu) → cơ thể suy yếu, sức khỏe kém.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"她病后很虚弱。","pinyin":"Tā bìng hòu hěn xūruò.","vi":"Sau trận ốm cô ấy rất yếu."},{"type":"simple","zh":"刚做完手术的病人身体十分虚弱。","pinyin":"Gāng zuòwán shǒushù de bìngrén shēntǐ shífēn xūruò.","vi":"Bệnh nhân vừa phẫu thuật xong cơ thể rất suy nhược."},{"type":"compound","zh":"因为好几天没吃东西，所以他虚弱得站不起来。","pinyin":"Yīnwèi hǎo jǐtiān méi chī dōngxi, suǒyǐ tā xūruò de zhàn bu qǐlái.","vi":"Vì mấy ngày không ăn gì nên anh ấy yếu đến mức không đứng dậy nổi."}],"related":[{"hanzi":"衰弱","pinyin":"shuāiruò","vi":"suy nhược"},{"hanzi":"强壮","pinyin":"qiángzhuàng","vi":"khỏe mạnh"},{"hanzi":"无力","pinyin":"wúlì","vi":"không còn sức"},{"hanzi":"疲惫","pinyin":"píbèi","vi":"mệt mỏi"}],"traditional":"虛弱"},{"id":"需","hanzi":"需","pinyin":"xū","meaning_vi":"cần, đòi hỏi","explanation":"需 (nhu – cần): cần đến, đòi hỏi; thường dùng trong văn viết, gặp trong 需要, 必需.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧾","examples":[{"type":"basic","zh":"此药需冷藏。","pinyin":"Cǐ yào xū lěngcáng.","vi":"Thuốc này cần bảo quản lạnh."},{"type":"simple","zh":"办理签证需提供两张照片。","pinyin":"Bànlǐ qiānzhèng xū tígōng liǎng zhāng zhàopiàn.","vi":"Làm thị thực cần nộp hai tấm ảnh."},{"type":"compound","zh":"如果要完成这个项目，就需投入大量资金。","pinyin":"Rúguǒ yào wánchéng zhè ge xiàngmù, jiù xū tóurù dàliàng zījīn.","vi":"Nếu muốn hoàn thành dự án này thì cần đầu tư một lượng vốn lớn."}],"related":[{"hanzi":"需要","pinyin":"xūyào","vi":"cần"},{"hanzi":"需求","pinyin":"xūqiú","vi":"nhu cầu"},{"hanzi":"必需","pinyin":"bìxū","vi":"thiết yếu"},{"hanzi":"须","pinyin":"xū","vi":"phải"}]},{"id":"许","hanzi":"许","pinyin":"xǔ","meaning_vi":"cho phép; hứa; có lẽ","explanation":"许 (hứa – cho phép, hứa hẹn): cho phép, hứa hẹn; còn biểu thị phỏng đoán như 也许 (có lẽ); cũng là một họ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤞","examples":[{"type":"basic","zh":"妈妈不许我玩手机。","pinyin":"Māma bùxǔ wǒ wán shǒujī.","vi":"Mẹ không cho tôi chơi điện thoại."},{"type":"simple","zh":"她过生日时闭上眼睛许了一个愿。","pinyin":"Tā guòshēngrì shí bìshàng yǎnjing xǔle yí gè yuàn.","vi":"Lúc sinh nhật cô ấy nhắm mắt ước một điều."},{"type":"compound","zh":"既然你已经许下了承诺，就一定要做到。","pinyin":"Jìrán nǐ yǐjīng xǔxiàle chéngnuò, jiù yídìngyào zuòdào.","vi":"Đã hứa rồi thì nhất định phải làm được."}],"related":[{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"cho phép"},{"hanzi":"也许","pinyin":"yěxǔ","vi":"có lẽ"},{"hanzi":"许愿","pinyin":"xǔyuàn","vi":"ước nguyện"},{"hanzi":"不许","pinyin":"bùxǔ","vi":"không cho phép"}],"traditional":"許"},{"id":"许可证","hanzi":"许可证","pinyin":"xǔkězhèng","meaning_vi":"giấy phép","explanation":"许可 (hứa khả – cho phép) + 证 (chứng – giấy chứng nhận) → giấy chứng nhận được cho phép, tức giấy phép.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🪪","examples":[{"type":"basic","zh":"开餐馆要有许可证。","pinyin":"Kāi cānguǎn yàoyǒu xǔkězhèng.","vi":"Mở nhà hàng phải có giấy phép."},{"type":"simple","zh":"这家工厂的生产许可证已经过期了。","pinyin":"Zhè jiā gōngchǎng de shēngchǎn xǔkězhèng yǐjīng guòqī le.","vi":"Giấy phép sản xuất của nhà máy này đã hết hạn."},{"type":"compound","zh":"如果没有许可证，就不能在这里钓鱼。","pinyin":"Rúguǒ méiyǒu xǔkězhèng, jiù bù néng zài zhèlǐ diàoyú.","vi":"Nếu không có giấy phép thì không được câu cá ở đây."}],"related":[{"hanzi":"执照","pinyin":"zhízhào","vi":"giấy phép"},{"hanzi":"许可","pinyin":"xǔkě","vi":"cho phép"},{"hanzi":"证件","pinyin":"zhèngjiàn","vi":"giấy tờ"},{"hanzi":"批准","pinyin":"pīzhǔn","vi":"phê duyệt"}],"traditional":"許可證"},{"id":"旭日","hanzi":"旭日","pinyin":"xùrì","meaning_vi":"mặt trời mới mọc","explanation":"旭 (húc – ánh mặt trời mới mọc) + 日 (nhật – mặt trời) → mặt trời buổi sớm vừa lên.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌄","examples":[{"type":"basic","zh":"旭日从东方升起。","pinyin":"Xùrì cóng dōngfāng shēngqǐ.","vi":"Mặt trời mới mọc lên từ phương đông."},{"type":"simple","zh":"我们在山顶上看到了美丽的旭日。","pinyin":"Wǒmen zài shāndǐng shang kàndàole měilì de xùrì.","vi":"Chúng tôi ngắm mặt trời mọc tuyệt đẹp trên đỉnh núi."},{"type":"compound","zh":"虽然山顶很冷，但是看到旭日的那一刻大家都很激动。","pinyin":"Suīrán shāndǐng hěn lěng, dànshì kàndào xùrì de nà yíkè dàjiā dōu hěn jīdòng.","vi":"Tuy trên đỉnh núi rất lạnh nhưng khoảnh khắc thấy mặt trời mọc ai cũng xúc động."}],"related":[{"hanzi":"日出","pinyin":"rìchū","vi":"mặt trời mọc"},{"hanzi":"朝阳","pinyin":"zhāoyáng","vi":"mặt trời buổi sáng"},{"hanzi":"夕阳","pinyin":"xīyáng","vi":"mặt trời lặn"},{"hanzi":"黎明","pinyin":"límíng","vi":"bình minh"}]},{"id":"序","hanzi":"序","pinyin":"xù","meaning_vi":"thứ tự, lời tựa","explanation":"序 (tự – thứ tự): thứ tự trước sau; cũng chỉ phần mở đầu, lời tựa của sách.","hsk_level":"7-9","tags":["danh-tu"],"image":"🔢","examples":[{"type":"basic","zh":"请按序排队。","pinyin":"Qǐng àn xù páiduì.","vi":"Xin xếp hàng theo thứ tự."},{"type":"simple","zh":"这本书的序是一位著名作家写的。","pinyin":"Zhè běn shū de xù shì yí wèi zhùmíng zuòjiā xiě de.","vi":"Lời tựa của cuốn sách này do một nhà văn nổi tiếng viết."},{"type":"compound","zh":"如果大家不遵守秩序，现场就会很乱。","pinyin":"Rúguǒ dàjiā bù zūnshǒu zhìxù, xiànchǎng jiù huì hěn luàn.","vi":"Nếu mọi người không giữ trật tự thì hiện trường sẽ rất lộn xộn."}],"related":[{"hanzi":"顺序","pinyin":"shùnxù","vi":"thứ tự"},{"hanzi":"秩序","pinyin":"zhìxù","vi":"trật tự"},{"hanzi":"序言","pinyin":"xùyán","vi":"lời tựa"},{"hanzi":"程序","pinyin":"chéngxù","vi":"trình tự"}]},{"id":"叙述","hanzi":"叙述","pinyin":"xùshù","meaning_vi":"kể lại, thuật lại, tường thuật","explanation":"叙 (tự – kể) + 述 (thuật – thuật lại) → kể lại sự việc theo trình tự.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"📖","examples":[{"type":"basic","zh":"请叙述事情经过。","pinyin":"Qǐng xùshù shìqing jīngguò.","vi":"Hãy thuật lại diễn biến sự việc."},{"type":"simple","zh":"他用简单的语言叙述了自己的经历。","pinyin":"Tāyòng jiǎndān de yǔyán xùshùle zìjǐ de jīnglì.","vi":"Anh ấy dùng ngôn ngữ đơn giản để kể lại trải nghiệm của mình."},{"type":"compound","zh":"虽然他叙述得很详细，但是警察还是有些疑问。","pinyin":"Suīrán tā xùshù de hěn xiángxì, dànshì jǐngchá háishi yǒuxiē yíwèn.","vi":"Tuy anh ấy thuật lại rất chi tiết nhưng cảnh sát vẫn còn vài nghi vấn."}],"related":[{"hanzi":"描述","pinyin":"miáoshù","vi":"miêu tả"},{"hanzi":"讲述","pinyin":"jiǎngshù","vi":"kể"},{"hanzi":"陈述","pinyin":"chénshù","vi":"trình bày"},{"hanzi":"叙事","pinyin":"xùshì","vi":"tự sự"}],"traditional":"敘述"},{"id":"续","hanzi":"续","pinyin":"xù","meaning_vi":"nối tiếp, tiếp tục; thêm vào, châm thêm","explanation":"续 (tục – nối tiếp): nối dài, tiếp tục; cũng chỉ thêm vào cho đầy như châm thêm trà.","hsk_level":"7-9","tags":["dong-tu"],"image":"➕","examples":[{"type":"basic","zh":"给我续点儿茶。","pinyin":"Gěi wǒ xù diǎnr chá.","vi":"Châm thêm cho tôi chút trà."},{"type":"simple","zh":"他决定和公司再续三年合同。","pinyin":"Tā juédìng hé gōngsī zài xù sān nián hétong.","vi":"Anh ấy quyết định gia hạn hợp đồng với công ty thêm ba năm."},{"type":"compound","zh":"如果会员卡已经到期了，就要及时续费。","pinyin":"Rúguǒ huìyuánkǎ yǐjīng dàoqī le, jiùyào jíshí xùfèi.","vi":"Nếu thẻ hội viên đã hết hạn thì phải kịp thời gia hạn phí."}],"related":[{"hanzi":"继续","pinyin":"jìxù","vi":"tiếp tục"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"手续","pinyin":"shǒuxù","vi":"thủ tục"},{"hanzi":"续集","pinyin":"xùjí","vi":"phần tiếp theo"}],"traditional":"續"},{"id":"絮叨","hanzi":"絮叨","pinyin":"xùdao","meaning_vi":"lải nhải, nói dai, lắm lời","explanation":"絮 (nhứ – sợi bông vụn, rườm rà) + 叨 (thao – lải nhải) → nói rườm rà, lặp đi lặp lại không dứt.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗯️","examples":[{"type":"basic","zh":"奶奶又在絮叨了。","pinyin":"Nǎinai yòu zài xùdao le.","vi":"Bà lại đang lải nhải rồi."},{"type":"simple","zh":"他絮叨了半天也没说到重点。","pinyin":"Tā xùdaole bàn tiān yě méi shuōdào zhòngdiǎn.","vi":"Anh ta lải nhải mãi mà vẫn chưa nói vào trọng tâm."},{"type":"compound","zh":"虽然妈妈总是絮叨，但是她说的都是为我好。","pinyin":"Suīrán māma zǒngshì xùdao, dànshì tā shuō de dōu shì wèi wǒ hǎo.","vi":"Tuy mẹ hay nói dai nhưng những gì mẹ nói đều vì tốt cho tôi."}],"related":[{"hanzi":"唠叨","pinyin":"láodao","vi":"cằn nhằn"},{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"dài dòng"},{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"than phiền"},{"hanzi":"多嘴","pinyin":"duōzuǐ","vi":"lắm mồm"}]},{"id":"宣读","hanzi":"宣读","pinyin":"xuāndú","meaning_vi":"đọc (công bố) trước mọi người, tuyên đọc","explanation":"宣 (tuyên – công bố) + 读 (độc – đọc) → đọc to văn bản trước đông người để công bố.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"校长宣读了获奖名单。","pinyin":"Xiàozhǎng xuāndúle huòjiǎng míngdān.","vi":"Hiệu trưởng đọc danh sách đoạt giải."},{"type":"simple","zh":"法官在法庭上宣读了判决书。","pinyin":"Fǎguān zài fǎtíng shang xuāndúle pànjuéshū.","vi":"Thẩm phán tuyên đọc bản án tại tòa."},{"type":"compound","zh":"当主持人宣读结果时，全场一下子安静了。","pinyin":"Dāng zhǔchírén xuāndú jiéguǒ shí, quánchǎng yíxiàzi ānjìng le.","vi":"Khi người dẫn chương trình đọc kết quả, cả hội trường bỗng im phăng phắc."}],"related":[{"hanzi":"宣布","pinyin":"xuānbù","vi":"tuyên bố"},{"hanzi":"朗读","pinyin":"lǎngdú","vi":"đọc to"},{"hanzi":"宣告","pinyin":"xuāngào","vi":"tuyên cáo"},{"hanzi":"发表","pinyin":"fābiǎo","vi":"phát biểu"}],"traditional":"宣讀"},{"id":"宣告","hanzi":"宣告","pinyin":"xuāngào","meaning_vi":"tuyên bố, tuyên cáo","explanation":"宣 (tuyên – công bố) + 告 (cáo – báo cho biết) → tuyên bố công khai cho mọi người biết.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"📣","examples":[{"type":"basic","zh":"会议宣告结束。","pinyin":"Huìyì xuāngào jiéshù.","vi":"Hội nghị tuyên bố kết thúc."},{"type":"simple","zh":"这家公司去年正式宣告破产。","pinyin":"Zhè jiā gōngsī qùnián zhèngshì xuāngào pòchǎn.","vi":"Công ty này năm ngoái chính thức tuyên bố phá sản."},{"type":"compound","zh":"因为双方都不肯让步，所以谈判宣告失败。","pinyin":"Yīnwèi shuāngfāng dōu bùkěn ràngbù, suǒyǐ tánpàn xuāngào shībài.","vi":"Vì hai bên đều không chịu nhượng bộ nên cuộc đàm phán đã đi đến thất bại."}],"related":[{"hanzi":"宣布","pinyin":"xuānbù","vi":"tuyên bố"},{"hanzi":"宣言","pinyin":"xuānyán","vi":"tuyên ngôn"},{"hanzi":"公告","pinyin":"gōnggào","vi":"thông cáo"},{"hanzi":"宣读","pinyin":"xuāndú","vi":"tuyên đọc"}]},{"id":"宣泄","hanzi":"宣泄","pinyin":"xuānxiè","meaning_vi":"trút ra, giải tỏa (cảm xúc)","explanation":"宣 (tuyên – phát ra) + 泄 (tiết – thoát ra) → cho thoát ra ngoài; nghĩa thường dùng là trút bỏ, giải tỏa cảm xúc dồn nén.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😤","examples":[{"type":"basic","zh":"他需要宣泄情绪。","pinyin":"Tā xūyào xuānxiè qíngxù.","vi":"Anh ấy cần giải tỏa cảm xúc."},{"type":"simple","zh":"很多人通过运动来宣泄压力。","pinyin":"Hěn duō rén tōngguò yùndòng lái xuānxiè yālì.","vi":"Nhiều người giải tỏa áp lực bằng cách tập thể thao."},{"type":"compound","zh":"如果心里的不满得不到宣泄，就容易生病。","pinyin":"Rúguǒ xīnlǐ de bùmǎn débudào xuānxiè, jiù róngyì shēngbìng.","vi":"Nếu sự bất mãn trong lòng không được giải tỏa thì dễ sinh bệnh."}],"related":[{"hanzi":"发泄","pinyin":"fāxiè","vi":"trút giận"},{"hanzi":"释放","pinyin":"shìfàng","vi":"giải phóng"},{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"},{"hanzi":"压抑","pinyin":"yāyì","vi":"kìm nén"}],"traditional":"宣洩"},{"id":"宣言","hanzi":"宣言","pinyin":"xuānyán","meaning_vi":"tuyên ngôn","explanation":"宣 (tuyên – công bố) + 言 (ngôn – lời) → lời tuyên bố công khai về quan điểm, mục tiêu.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📜","examples":[{"type":"basic","zh":"他们发表了独立宣言。","pinyin":"Tāmen fābiǎole dúlì xuānyán.","vi":"Họ công bố bản tuyên ngôn độc lập."},{"type":"simple","zh":"这份环保宣言得到了很多国家的支持。","pinyin":"Zhè fèn huánbǎo xuānyán dédàole hěn duō guójiā de zhīchí.","vi":"Bản tuyên ngôn bảo vệ môi trường này được nhiều nước ủng hộ."},{"type":"compound","zh":"虽然宣言写得很好，但是关键在于行动。","pinyin":"Suīrán xuānyán xiě de hěn hǎo, dànshì guānjiàn zàiyú xíngdòng.","vi":"Tuy bản tuyên ngôn viết rất hay nhưng điều then chốt là hành động."}],"related":[{"hanzi":"声明","pinyin":"shēngmíng","vi":"tuyên bố"},{"hanzi":"宣告","pinyin":"xuāngào","vi":"tuyên cáo"},{"hanzi":"宣布","pinyin":"xuānbù","vi":"tuyên bố"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"}]},{"id":"玄","hanzi":"玄","pinyin":"xuán","meaning_vi":"huyền bí, khó hiểu; khó tin, huyền hoặc; màu đen","explanation":"玄 (huyền – đen, sâu xa): nghĩa gốc là màu đen thẫm; nghĩa thường dùng là huyền bí, sâu xa khó hiểu, hoặc khó tin.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌀","examples":[{"type":"basic","zh":"这事说得太玄了。","pinyin":"Zhè shì shuō de tài xuán le.","vi":"Chuyện này nói nghe huyền hoặc quá."},{"type":"simple","zh":"他讲的道理太玄，我一点儿也听不懂。","pinyin":"Tā jiǎng de dàolǐ tài xuán, wǒ yìdiǎnr yě tīngbudǒng.","vi":"Đạo lý anh ấy nói quá cao siêu, tôi chẳng hiểu gì."},{"type":"compound","zh":"虽然故事听起来很玄，但是确实发生过。","pinyin":"Suīrán gùshi tīngqǐlái hěn xuán, dànshì quèshí fāshēng guò.","vi":"Tuy câu chuyện nghe có vẻ khó tin nhưng thực sự đã xảy ra."}],"related":[{"hanzi":"玄妙","pinyin":"xuánmiào","vi":"huyền diệu"},{"hanzi":"神秘","pinyin":"shénmì","vi":"thần bí"},{"hanzi":"玄机","pinyin":"xuánjī","vi":"điều huyền bí"},{"hanzi":"深奥","pinyin":"shēn'ào","vi":"sâu xa"}]},{"id":"旋涡","hanzi":"旋涡","pinyin":"xuánwō","meaning_vi":"xoáy nước, vòng xoáy","explanation":"旋 (toàn – xoay tròn) + 涡 (oa – chỗ nước xoáy) → chỗ nước xoáy tròn; nghĩa bóng là tình thế rắc rối khó thoát ra.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌀","examples":[{"type":"basic","zh":"河中有个旋涡。","pinyin":"Hé zhōng yǒu ge xuánwō.","vi":"Giữa sông có một xoáy nước."},{"type":"simple","zh":"小船被卷进了巨大的旋涡。","pinyin":"Xiǎochuán bèi juǎn jìnle jùdà de xuánwō.","vi":"Chiếc thuyền nhỏ bị cuốn vào xoáy nước khổng lồ."},{"type":"compound","zh":"一旦卷入这场政治旋涡，他就很难脱身了。","pinyin":"Yídàn juǎnrù zhè chǎng zhèngzhì xuánwō, tā jiù hěn nán tuōshēn le.","vi":"Một khi bị cuốn vào vòng xoáy chính trị này, anh ấy sẽ rất khó thoát ra."}],"related":[{"hanzi":"漩涡","pinyin":"xuánwō","vi":"xoáy nước"},{"hanzi":"旋转","pinyin":"xuánzhuǎn","vi":"xoay tròn"},{"hanzi":"卷入","pinyin":"juǎnrù","vi":"bị cuốn vào"},{"hanzi":"水流","pinyin":"shuǐliú","vi":"dòng nước"}],"traditional":"旋渦"},{"id":"选民","hanzi":"选民","pinyin":"xuǎnmín","meaning_vi":"cử tri","explanation":"选 (tuyển – chọn, bầu) + 民 (dân – người dân) → người dân có quyền bầu cử, tức cử tri.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🗳️","examples":[{"type":"basic","zh":"选民们去投票了。","pinyin":"Xuǎnmínmen qù tóupiào le.","vi":"Các cử tri đã đi bỏ phiếu."},{"type":"simple","zh":"候选人在广场上向选民发表演讲。","pinyin":"Hòuxuǎnrén zài guǎngchǎng shang xiàng xuǎnmín fābiǎo yǎnjiǎng.","vi":"Ứng cử viên diễn thuyết trước cử tri tại quảng trường."},{"type":"compound","zh":"如果不能赢得年轻选民的支持，他就很难当选。","pinyin":"Rúguǒ bù néng yíngdé niánqīng xuǎnmín de zhīchí, tā jiù hěn nán dāngxuǎn.","vi":"Nếu không giành được sự ủng hộ của cử tri trẻ thì ông ấy khó trúng cử."}],"related":[{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"},{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"},{"hanzi":"候选人","pinyin":"hòuxuǎnrén","vi":"ứng cử viên"},{"hanzi":"当选","pinyin":"dāngxuǎn","vi":"trúng cử"}],"traditional":"選民"},{"id":"选项","hanzi":"选项","pinyin":"xuǎnxiàng","meaning_vi":"lựa chọn, phương án (để chọn)","explanation":"选 (tuyển – chọn) + 项 (hạng – mục) → các mục để chọn, phương án lựa chọn.","hsk_level":"7-9","tags":["danh-tu"],"image":"☑️","examples":[{"type":"basic","zh":"请选择一个选项。","pinyin":"Qǐng xuǎnzé yí gè xuǎnxiàng.","vi":"Hãy chọn một phương án."},{"type":"simple","zh":"这道题的四个选项看起来都差不多。","pinyin":"Zhè dào tí de sì gè xuǎnxiàng kànqǐlái dōu chàbuduō.","vi":"Bốn phương án của câu hỏi này trông đều na ná nhau."},{"type":"compound","zh":"如果你不确定答案，就先排除明显错误的选项。","pinyin":"Rúguǒ nǐ bú quèdìng dá'àn, jiù xiān páichú míngxiǎn cuòwù de xuǎnxiàng.","vi":"Nếu bạn không chắc đáp án thì hãy loại các phương án sai rõ ràng trước."}],"related":[{"hanzi":"选择","pinyin":"xuǎnzé","vi":"lựa chọn"},{"hanzi":"答案","pinyin":"dá'àn","vi":"đáp án"},{"hanzi":"选择题","pinyin":"xuǎnzétí","vi":"câu trắc nghiệm"},{"hanzi":"项目","pinyin":"xiàngmù","vi":"hạng mục"}],"traditional":"選項"},{"id":"选用","hanzi":"选用","pinyin":"xuǎnyòng","meaning_vi":"chọn dùng, tuyển chọn để dùng","explanation":"选 (tuyển – chọn) + 用 (dụng – dùng) → chọn ra để sử dụng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛠️","examples":[{"type":"basic","zh":"这里选用优质木材。","pinyin":"Zhèlǐ xuǎnyòng yōuzhì mùcái.","vi":"Ở đây chọn dùng gỗ chất lượng cao."},{"type":"simple","zh":"这家餐厅只选用当天的新鲜蔬菜。","pinyin":"Zhè jiā cāntīng zhǐ xuǎnyòng dàngtiān de xīnxiān shūcài.","vi":"Nhà hàng này chỉ chọn dùng rau tươi trong ngày."},{"type":"compound","zh":"因为选用了好材料，所以这座房子特别结实。","pinyin":"Yīnwèi xuǎnyòngle hǎo cáiliào, suǒyǐ zhè zuò fángzi tèbié jiēshi.","vi":"Vì chọn dùng vật liệu tốt nên ngôi nhà này rất chắc chắn."}],"related":[{"hanzi":"选择","pinyin":"xuǎnzé","vi":"lựa chọn"},{"hanzi":"采用","pinyin":"cǎiyòng","vi":"áp dụng"},{"hanzi":"挑选","pinyin":"tiāoxuǎn","vi":"chọn lựa"},{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"}],"traditional":"選用"},{"id":"靴子","hanzi":"靴子","pinyin":"xuēzi","meaning_vi":"ủng, bốt","explanation":"靴 (ngoa – giày cổ cao) + 子 (tử – hậu tố) → giày cổ cao, ủng, bốt.","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"👢","examples":[{"type":"basic","zh":"她穿了一双靴子。","pinyin":"Tā chuānle yì shuāng xuēzi.","vi":"Cô ấy đi một đôi bốt."},{"type":"simple","zh":"冬天下雪的时候我喜欢穿长靴子。","pinyin":"Dōngtiān xiàxuě de shíhou wǒ xǐhuan chuān cháng xuēzi.","vi":"Mùa đông khi tuyết rơi tôi thích đi bốt cao cổ."},{"type":"compound","zh":"虽然这双靴子很好看，但是穿久了脚会疼。","pinyin":"Suīrán zhè shuāng xuēzi hěn hǎokàn, dànshì chuān jiǔle jiǎo huì téng.","vi":"Tuy đôi bốt này rất đẹp nhưng đi lâu sẽ đau chân."}],"related":[{"hanzi":"鞋子","pinyin":"xiézi","vi":"giày"},{"hanzi":"雨靴","pinyin":"yǔxuē","vi":"ủng đi mưa"},{"hanzi":"皮靴","pinyin":"píxuē","vi":"bốt da"},{"hanzi":"袜子","pinyin":"wàzi","vi":"tất"}]},{"id":"学士","hanzi":"学士","pinyin":"xuéshì","meaning_vi":"cử nhân (học vị)","explanation":"学 (học – học) + 士 (sĩ – người có học) → người có học thức; nay chỉ học vị cử nhân.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"他有学士学位。","pinyin":"Tā yǒu xuéshì xuéwèi.","vi":"Anh ấy có bằng cử nhân."},{"type":"simple","zh":"她在北京大学获得了中文学士学位。","pinyin":"Tā zài Běijīngdàxué huòdéle Zhōngwén xuéshì xuéwèi.","vi":"Cô ấy lấy bằng cử nhân tiếng Trung ở Đại học Bắc Kinh."},{"type":"compound","zh":"虽然他只有学士学位，但是工作能力比很多博士还强。","pinyin":"Suīrán tā zhǐyǒu xuéshì xuéwèi, dànshì gōngzuò nénglì bǐ hěn duō bóshì hái qiáng.","vi":"Tuy chỉ có bằng cử nhân nhưng năng lực làm việc của anh ấy còn hơn nhiều tiến sĩ."}],"related":[{"hanzi":"硕士","pinyin":"shuòshì","vi":"thạc sĩ"},{"hanzi":"博士","pinyin":"bóshì","vi":"tiến sĩ"},{"hanzi":"学位","pinyin":"xuéwèi","vi":"học vị"},{"hanzi":"本科","pinyin":"běnkē","vi":"đại học hệ chính quy"}],"traditional":"學士"},{"id":"学堂","hanzi":"学堂","pinyin":"xuétáng","meaning_vi":"trường học (cách nói xưa)","explanation":"学 (học – học) + 堂 (đường – gian nhà lớn) → nhà để học, tức trường học; là cách gọi thời xưa.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"他小时候上过学堂。","pinyin":"Tā xiǎoshíhou shàngguò xuétáng.","vi":"Hồi nhỏ ông ấy từng đi học trường làng."},{"type":"simple","zh":"村里的老学堂已经有一百多年历史了。","pinyin":"Cūnlǐ de lǎo xuétáng yǐjīng yǒu yī bǎi duōnián lìshǐ le.","vi":"Ngôi trường cũ trong làng đã có hơn một trăm năm lịch sử."},{"type":"compound","zh":"虽然学堂很简陋，但是孩子们学习都很认真。","pinyin":"Suīrán xuétáng hěn jiǎnlòu, dànshì háizimen xuéxí dōu hěn rènzhēn.","vi":"Tuy trường học rất sơ sài nhưng bọn trẻ học rất chăm chỉ."}],"related":[{"hanzi":"学校","pinyin":"xuéxiào","vi":"trường học"},{"hanzi":"私塾","pinyin":"sīshú","vi":"trường tư thục xưa"},{"hanzi":"课堂","pinyin":"kètáng","vi":"lớp học"},{"hanzi":"书院","pinyin":"shūyuàn","vi":"thư viện, học viện xưa"}],"traditional":"學堂"},{"id":"学业","hanzi":"学业","pinyin":"xuéyè","meaning_vi":"việc học, học hành","explanation":"学 (học – học) + 业 (nghiệp – sự nghiệp) → sự nghiệp học tập, việc học hành.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他顺利完成了学业。","pinyin":"Tā shùnlì wánchéngle xuéyè.","vi":"Anh ấy đã hoàn thành việc học một cách suôn sẻ."},{"type":"simple","zh":"父母最关心的是孩子的学业。","pinyin":"Fùmǔ zuì guānxīn de shì háizi de xuéyè.","vi":"Điều bố mẹ quan tâm nhất là việc học của con."},{"type":"compound","zh":"因为家里经济困难，所以他不得不中断学业。","pinyin":"Yīnwèi jiālǐ jīngjì kùnnan, suǒyǐ tā bùdébù zhōngduàn xuéyè.","vi":"Vì gia đình khó khăn về kinh tế nên anh ấy buộc phải bỏ dở việc học."}],"related":[{"hanzi":"学习","pinyin":"xuéxí","vi":"học tập"},{"hanzi":"成绩","pinyin":"chéngjì","vi":"thành tích"},{"hanzi":"毕业","pinyin":"bìyè","vi":"tốt nghiệp"},{"hanzi":"课业","pinyin":"kèyè","vi":"bài vở"}],"traditional":"學業"},{"id":"学艺","hanzi":"学艺","pinyin":"xuéyì","meaning_vi":"học nghề, học nghệ thuật","explanation":"学 (học – học) + 艺 (nghệ – kỹ năng, nghệ thuật) → học một nghề, một môn nghệ thuật.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎨","examples":[{"type":"basic","zh":"他从小跟师傅学艺。","pinyin":"Tā cóngxiǎo gēn shīfu xuéyì.","vi":"Từ nhỏ anh ấy đã theo thầy học nghề."},{"type":"simple","zh":"她十岁就去北京学艺，后来成了京剧演员。","pinyin":"Tā shí suì jiù qù Běijīng xuéyì, hòulái chéngle Jīngjù yǎnyuán.","vi":"Mười tuổi cô ấy đã lên Bắc Kinh học nghệ, sau trở thành diễn viên kinh kịch."},{"type":"compound","zh":"虽然学艺很辛苦，但是他从来没想过放弃。","pinyin":"Suīrán xuéyì hěn xīnkǔ, dànshì tā cónglái méi xiǎngguò fàngqì.","vi":"Tuy học nghề rất vất vả nhưng anh ấy chưa bao giờ nghĩ đến bỏ cuộc."}],"related":[{"hanzi":"手艺","pinyin":"shǒuyì","vi":"tay nghề"},{"hanzi":"师傅","pinyin":"shīfu","vi":"thầy dạy nghề"},{"hanzi":"技艺","pinyin":"jìyì","vi":"kỹ nghệ"},{"hanzi":"拜师","pinyin":"bàishī","vi":"bái sư"}],"traditional":"學藝"},{"id":"雪山","hanzi":"雪山","pinyin":"xuěshān","meaning_vi":"núi tuyết","explanation":"雪 (tuyết) + 山 (sơn – núi) → núi phủ tuyết quanh năm.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"远处是一座雪山。","pinyin":"Yuǎnchù shì yí zuò xuěshān.","vi":"Phía xa là một ngọn núi tuyết."},{"type":"simple","zh":"登山队员们终于爬上了雪山的顶峰。","pinyin":"Dēngshān duìyuánmen zhōngyú páshàngle xuěshān de dǐngfēng.","vi":"Các thành viên đội leo núi cuối cùng đã lên tới đỉnh núi tuyết."},{"type":"compound","zh":"虽然雪山很美，但是爬上去非常危险。","pinyin":"Suīrán xuěshān hěn měi, dànshì pá shàngqù fēicháng wēixiǎn.","vi":"Tuy núi tuyết rất đẹp nhưng leo lên vô cùng nguy hiểm."}],"related":[{"hanzi":"冰川","pinyin":"bīngchuān","vi":"sông băng"},{"hanzi":"高山","pinyin":"gāoshān","vi":"núi cao"},{"hanzi":"积雪","pinyin":"jīxuě","vi":"tuyết đọng"},{"hanzi":"山顶","pinyin":"shāndǐng","vi":"đỉnh núi"}]},{"id":"血栓","hanzi":"血栓","pinyin":"xuèshuān","meaning_vi":"cục máu đông, huyết khối","explanation":"血 (huyết – máu) + 栓 (xuyên – cái nút) → cục máu đông lại như cái nút chặn trong mạch máu.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"他得了脑血栓。","pinyin":"Tā déle nǎo xuèshuān.","vi":"Ông ấy bị huyết khối não."},{"type":"simple","zh":"长时间坐着不动容易形成血栓。","pinyin":"Cháng shíjiān zuòzhe búdòng róngyì xíngchéng xuèshuān.","vi":"Ngồi lâu không cử động dễ hình thành cục máu đông."},{"type":"compound","zh":"如果血栓堵住了血管，就会非常危险。","pinyin":"Rúguǒ xuèshuān dǔzhùle xuèguǎn, jiù huì fēicháng wēixiǎn.","vi":"Nếu cục máu đông làm tắc mạch máu thì sẽ rất nguy hiểm."}],"related":[{"hanzi":"血管","pinyin":"xuèguǎn","vi":"mạch máu"},{"hanzi":"血液","pinyin":"xuèyè","vi":"máu"},{"hanzi":"中风","pinyin":"zhòngfēng","vi":"đột quỵ"},{"hanzi":"心脏病","pinyin":"xīnzàngbìng","vi":"bệnh tim"}]},{"id":"勋章","hanzi":"勋章","pinyin":"xūnzhāng","meaning_vi":"huân chương","explanation":"勋 (huân – công lao) + 章 (chương – huy hiệu) → huy hiệu ghi nhận công lao, tức huân chương.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🎖️","examples":[{"type":"basic","zh":"他获得了一枚勋章。","pinyin":"Tā huòdéle yìméi xūnzhāng.","vi":"Ông ấy được trao một tấm huân chương."},{"type":"simple","zh":"爷爷把战争时期的勋章挂在墙上。","pinyin":"Yéye bǎ zhànzhēng shíqī de xūnzhāng guà zài qiáng shang.","vi":"Ông nội treo những tấm huân chương thời chiến lên tường."},{"type":"compound","zh":"因为他在救灾中表现突出，所以被授予了勋章。","pinyin":"Yīnwèi tā zài jiùzāi zhōng biǎoxiàn tūchū, suǒyǐ bèi shòuyǔle xūnzhāng.","vi":"Vì có thành tích nổi bật trong cứu trợ thiên tai nên anh ấy được trao huân chương."}],"related":[{"hanzi":"奖章","pinyin":"jiǎngzhāng","vi":"huy chương"},{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"功劳","pinyin":"gōngláo","vi":"công lao"},{"hanzi":"授予","pinyin":"shòuyǔ","vi":"trao tặng"}],"traditional":"勳章"},{"id":"熏","hanzi":"熏","pinyin":"xūn","meaning_vi":"hun, xông khói, ám (mùi)","explanation":"熏 (huân – hun khói): dùng khói hơ, hun cho chín hoặc cho có mùi; cũng chỉ mùi khói, mùi hôi xộc vào.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥓","examples":[{"type":"basic","zh":"烟把墙熏黑了。","pinyin":"Yān bǎ qiáng xūn hēi le.","vi":"Khói hun đen cả bức tường."},{"type":"simple","zh":"奶奶每年冬天都会做一些熏肉。","pinyin":"Nǎinai měinián dōngtiān dōuhuì zuò yìxiē xūnròu.","vi":"Mùa đông năm nào bà cũng làm ít thịt hun khói."},{"type":"compound","zh":"因为厨房的油烟太大，所以我被熏得直流眼泪。","pinyin":"Yīnwèi chúfáng de yóuyān tài dà, suǒyǐ wǒ bèi xūn de zhíliú yǎnlèi.","vi":"Vì khói dầu trong bếp quá nhiều nên tôi bị xông đến chảy nước mắt."}],"related":[{"hanzi":"熏肉","pinyin":"xūnròu","vi":"thịt hun khói"},{"hanzi":"烟","pinyin":"yān","vi":"khói"},{"hanzi":"烤","pinyin":"kǎo","vi":"nướng"},{"hanzi":"熏陶","pinyin":"xūntáo","vi":"hun đúc"}],"traditional":"燻"},{"id":"寻","hanzi":"寻","pinyin":"xún","meaning_vi":"tìm, tìm kiếm","explanation":"寻 (tầm – tìm): tìm kiếm; thường dùng trong văn viết, gặp trong 寻找, 寻求.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔎","examples":[{"type":"basic","zh":"他四处寻人。","pinyin":"Tā sìchù xún rén.","vi":"Anh ấy đi khắp nơi tìm người."},{"type":"simple","zh":"这对夫妻在报纸上登了寻人启事。","pinyin":"Zhè duì fūqī zài bàozhǐ shang dēngle xún rén qǐshì.","vi":"Đôi vợ chồng này đăng thông báo tìm người trên báo."},{"type":"compound","zh":"虽然他千里寻亲，但是最后还是没找到父母。","pinyin":"Suīrán tā qiānlǐ xúnqīn, dànshì zuìhòu háishi méi zhǎodào fùmǔ.","vi":"Tuy anh ấy vượt nghìn dặm đi tìm người thân nhưng cuối cùng vẫn không tìm được cha mẹ."}],"related":[{"hanzi":"寻找","pinyin":"xúnzhǎo","vi":"tìm kiếm"},{"hanzi":"寻求","pinyin":"xúnqiú","vi":"tìm cầu"},{"hanzi":"搜寻","pinyin":"sōuxún","vi":"lùng tìm"},{"hanzi":"找","pinyin":"zhǎo","vi":"tìm"}],"traditional":"尋"},{"id":"寻常","hanzi":"寻常","pinyin":"xúncháng","meaning_vi":"bình thường, thông thường","explanation":"寻 (tầm) + 常 (thường): xưa 寻 và 常 là đơn vị đo chiều dài ngắn, ý chỉ cái nhỏ bé thường gặp → bình thường, thông thường.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🙂","examples":[{"type":"basic","zh":"这不是寻常的事。","pinyin":"Zhèbú shì xúncháng de shì.","vi":"Đây không phải chuyện bình thường."},{"type":"simple","zh":"他今天的表现有点儿不同寻常。","pinyin":"Tā jīntiān de biǎoxiàn yǒudiǎnr bùtóng xúncháng.","vi":"Hôm nay biểu hiện của anh ấy hơi khác thường."},{"type":"compound","zh":"虽然这只是一顿寻常的晚饭，但是全家人吃得很开心。","pinyin":"Suīrán zhè zhǐshì yí dùn xúncháng de wǎnfàn, dànshì quán jiārén chī de hěn kāixīn.","vi":"Tuy chỉ là một bữa tối bình thường nhưng cả nhà ăn rất vui."}],"related":[{"hanzi":"平常","pinyin":"píngcháng","vi":"bình thường"},{"hanzi":"普通","pinyin":"pǔtōng","vi":"phổ thông"},{"hanzi":"一般","pinyin":"yìbān","vi":"thông thường"},{"hanzi":"不同寻常","pinyin":"bùtóngxúncháng","vi":"khác thường"}],"traditional":"尋常"},{"id":"驯","hanzi":"驯","pinyin":"xùn","meaning_vi":"thuần hóa, huấn luyện (thú vật)","explanation":"驯 (thuần – thuần phục): làm cho thú hoang trở nên thuần, nghe lời; cũng chỉ sự ngoan ngoãn.","hsk_level":"7-9","tags":["dong-tu","dong-vat"],"image":"🐎","examples":[{"type":"basic","zh":"他很会驯马。","pinyin":"Tā hěn huì xùnmǎ.","vi":"Anh ấy rất giỏi thuần ngựa."},{"type":"simple","zh":"马戏团的人花了三年才把这只老虎驯好。","pinyin":"Mǎxìtuán de rén huāle sān nián cái bǎ zhè zhī lǎohǔ xùn hǎo.","vi":"Người của đoàn xiếc mất ba năm mới thuần hóa được con hổ này."},{"type":"compound","zh":"虽然这匹马很难驯，但是他最后还是成功了。","pinyin":"Suīrán zhè pǐ mǎ hěn nán xùn, dànshì tā zuìhòu háishi chénggōng le.","vi":"Tuy con ngựa này rất khó thuần nhưng cuối cùng anh ấy vẫn thành công."}],"related":[{"hanzi":"驯服","pinyin":"xùnfú","vi":"thuần phục"},{"hanzi":"驯养","pinyin":"xùnyǎng","vi":"thuần dưỡng"},{"hanzi":"训练","pinyin":"xùnliàn","vi":"huấn luyện"},{"hanzi":"野生","pinyin":"yěshēng","vi":"hoang dã"}],"traditional":"馴"},{"id":"训","hanzi":"训","pinyin":"xùn","meaning_vi":"dạy bảo, răn dạy, mắng","explanation":"训 (huấn – dạy bảo): dạy dỗ, răn bảo; trong khẩu ngữ còn chỉ việc mắng, khiển trách.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👨‍🏫","examples":[{"type":"basic","zh":"他被老板训了一顿。","pinyin":"Tā bèi lǎobǎn xùnle yí dùn.","vi":"Anh ấy bị ông chủ mắng một trận."},{"type":"simple","zh":"爸爸常常训我做事不认真。","pinyin":"Bàba chángcháng xùn wǒ zuòshì bú rènzhēn.","vi":"Bố thường mắng tôi làm việc không nghiêm túc."},{"type":"compound","zh":"如果你明天再迟到，就又要被老师训了。","pinyin":"Rúguǒ nǐ míngtiān zài chídào, jiù yòu yào bèi lǎoshī xùn le.","vi":"Nếu mai bạn lại đi muộn thì sẽ lại bị thầy mắng."}],"related":[{"hanzi":"教训","pinyin":"jiàoxun","vi":"bài học, dạy dỗ"},{"hanzi":"训练","pinyin":"xùnliàn","vi":"huấn luyện"},{"hanzi":"培训","pinyin":"péixùn","vi":"đào tạo"},{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"}],"traditional":"訓"},{"id":"丫头","hanzi":"丫头","pinyin":"yātou","meaning_vi":"con bé, cô bé; a hoàn, đầy tớ gái","explanation":"丫 (a – chạc, búi tóc hai bên) + 头 (đầu) → con gái nhỏ búi tóc hai bên, tức cô bé; xưa còn chỉ a hoàn, nay thường gọi thân mật.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👧","examples":[{"type":"basic","zh":"这丫头真聪明。","pinyin":"Zhè yātou zhēn cōngming.","vi":"Con bé này thật thông minh."},{"type":"simple","zh":"奶奶总是亲切地叫我“傻丫头”。","pinyin":"Nǎinai zǒngshì qīnqiè de jiào wǒ \"shǎ yātou\".","vi":"Bà luôn trìu mến gọi tôi là \"con bé ngốc\"."},{"type":"compound","zh":"虽然她还是个小丫头，但是已经很会照顾人了。","pinyin":"Suīrán tā háishi ge xiǎo yātou, dànshì yǐjīng hěn huì zhàogù rén le.","vi":"Tuy vẫn còn là cô bé nhưng nó đã rất biết chăm sóc người khác."}],"related":[{"hanzi":"姑娘","pinyin":"gūniang","vi":"cô gái"},{"hanzi":"女孩","pinyin":"nǚhái","vi":"bé gái"},{"hanzi":"小子","pinyin":"xiǎozi","vi":"thằng nhóc"},{"hanzi":"闺女","pinyin":"guīnü","vi":"con gái"}],"traditional":"丫頭"},{"id":"押","hanzi":"押","pinyin":"yā","meaning_vi":"áp giải, giam giữ; cầm cố, đặt cọc","explanation":"押 (áp – giữ lại, đè): giữ lại làm tin như cầm cố, đặt cọc; cũng chỉ giam giữ hoặc áp giải phạm nhân.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔐","examples":[{"type":"basic","zh":"犯人被押走了。","pinyin":"Fànrén bèi yā zǒu le.","vi":"Phạm nhân đã bị áp giải đi."},{"type":"simple","zh":"租房子的时候要先押一个月房租。","pinyin":"Zū fángzi de shíhou yào xiān yā yí gèyuè fángzū.","vi":"Khi thuê nhà phải đặt cọc trước một tháng tiền nhà."},{"type":"compound","zh":"虽然他把车押给了银行，但是钱还是不够。","pinyin":"Suīrán tā bǎ chē yā gěile yínháng, dànshì qián háishi búgòu.","vi":"Tuy anh ấy đã cầm cố xe cho ngân hàng nhưng tiền vẫn không đủ."}],"related":[{"hanzi":"押金","pinyin":"yājīn","vi":"tiền đặt cọc"},{"hanzi":"抵押","pinyin":"dǐyā","vi":"thế chấp"},{"hanzi":"关押","pinyin":"guānyā","vi":"giam giữ"},{"hanzi":"押送","pinyin":"yāsòng","vi":"áp giải"}]},{"id":"牙齿","hanzi":"牙齿","pinyin":"yáchǐ","meaning_vi":"răng","explanation":"牙 (nha – răng) + 齿 (xỉ – răng) → răng nói chung.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🦷","examples":[{"type":"basic","zh":"她的牙齿很白。","pinyin":"Tā de yáchǐ hěn bái.","vi":"Răng cô ấy rất trắng."},{"type":"simple","zh":"饭后最好用牙线清洁牙齿。","pinyin":"Fàn hòu zuìhǎo yòng yáxiàn qīngjié yáchǐ.","vi":"Sau bữa ăn tốt nhất nên dùng chỉ nha khoa làm sạch răng."},{"type":"compound","zh":"如果你每天都吃很多糖，牙齿就很容易坏。","pinyin":"Rúguǒ nǐ měitiān dōu chī hěn duōtáng, yáchǐ jiù hěn róngyì huài.","vi":"Nếu ngày nào bạn cũng ăn nhiều kẹo thì răng rất dễ bị hỏng."}],"related":[{"hanzi":"牙","pinyin":"yá","vi":"răng"},{"hanzi":"牙医","pinyin":"yáyī","vi":"nha sĩ"},{"hanzi":"刷牙","pinyin":"shuāyá","vi":"đánh răng"},{"hanzi":"牙膏","pinyin":"yágāo","vi":"kem đánh răng"}],"traditional":"牙齒"},{"id":"芽","hanzi":"芽","pinyin":"yá","meaning_vi":"mầm, chồi","explanation":"芽 (nha – mầm): mầm non mới nhú ra từ hạt hoặc cành cây.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"柳树发芽了。","pinyin":"Liǔshù fāyá le.","vi":"Cây liễu đã đâm chồi."},{"type":"simple","zh":"春雨过后，地里冒出了很多嫩芽。","pinyin":"Chūnyǔ guòhòu, dì lǐ mào chūle hěn duō nènyá.","vi":"Sau cơn mưa xuân, trên đất nhú lên rất nhiều mầm non."},{"type":"compound","zh":"如果土豆放的时间太久，就会长出芽来。","pinyin":"Rúguǒ tǔdòu fàng de shíjiān tài jiǔ, jiù huì zhǎngchū yá lái.","vi":"Nếu để khoai tây quá lâu thì sẽ mọc mầm."}],"related":[{"hanzi":"发芽","pinyin":"fāyá","vi":"nảy mầm"},{"hanzi":"嫩芽","pinyin":"nènyá","vi":"mầm non"},{"hanzi":"种子","pinyin":"zhǒngzi","vi":"hạt giống"},{"hanzi":"萌芽","pinyin":"méngyá","vi":"manh nha"}]},{"id":"哑","hanzi":"哑","pinyin":"yǎ","meaning_vi":"câm; khàn (giọng)","explanation":"哑 (á – câm): không nói được; cũng chỉ giọng khàn, mất tiếng.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🤐","examples":[{"type":"basic","zh":"他嗓子哑了。","pinyin":"Tā sǎngzi yǎ le.","vi":"Anh ấy bị khàn giọng."},{"type":"simple","zh":"她唱了一晚上的歌，声音都哑了。","pinyin":"Tā chàngle yì wǎnshang de gē, shēngyīn dōu yǎ le.","vi":"Cô ấy hát cả buổi tối, giọng khàn hết cả."},{"type":"compound","zh":"虽然他天生是哑巴，但是会用手语和大家交流。","pinyin":"Suīrán tā tiānshēng shì yǎba, dànshì huì yòng shǒuyǔ hé dàjiā jiāoliú.","vi":"Tuy bị câm bẩm sinh nhưng anh ấy biết dùng ngôn ngữ ký hiệu để giao tiếp với mọi người."}],"related":[{"hanzi":"哑巴","pinyin":"yǎba","vi":"người câm"},{"hanzi":"沙哑","pinyin":"shāyǎ","vi":"khàn đặc"},{"hanzi":"嗓子","pinyin":"sǎngzi","vi":"cổ họng"},{"hanzi":"聋","pinyin":"lóng","vi":"điếc"}],"traditional":"啞"},{"id":"烟囱","hanzi":"烟囱","pinyin":"yāncōng","meaning_vi":"ống khói","explanation":"烟 (yên – khói) + 囱 (song – ống khói) → ống dẫn khói thoát lên cao.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏭","examples":[{"type":"basic","zh":"烟囱在冒烟。","pinyin":"Yāncōng zài màoyān.","vi":"Ống khói đang bốc khói."},{"type":"simple","zh":"工厂的大烟囱每天都冒着黑烟。","pinyin":"Gōngchǎng de dà yāncōng měitiān dōu màozhe hēi yān.","vi":"Ống khói lớn của nhà máy ngày nào cũng xả khói đen."},{"type":"compound","zh":"虽然这个烟囱已经不用了，但是村民们把它保留了下来。","pinyin":"Suīrán zhè ge yāncōng yǐjīng bú yòng le, dànshì cūnmínmen bǎ tā bǎoliúle xiàlái.","vi":"Tuy ống khói này không dùng nữa nhưng dân làng vẫn giữ lại."}],"related":[{"hanzi":"烟","pinyin":"yān","vi":"khói"},{"hanzi":"工厂","pinyin":"gōngchǎng","vi":"nhà máy"},{"hanzi":"冒烟","pinyin":"màoyān","vi":"bốc khói"},{"hanzi":"壁炉","pinyin":"bìlú","vi":"lò sưởi"}],"traditional":"煙囪"},{"id":"烟火","hanzi":"烟火","pinyin":"yānhuǒ","meaning_vi":"pháo hoa; khói lửa","explanation":"烟 (yên – khói) + 火 (hỏa – lửa) → khói và lửa; thường chỉ pháo hoa bắn lên trời.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎆","examples":[{"type":"basic","zh":"天上放起了烟火。","pinyin":"Tiānshang fàng qǐle yānhuǒ.","vi":"Trên trời bắn pháo hoa."},{"type":"simple","zh":"新年晚上，江边的烟火特别漂亮。","pinyin":"Xīnnián wǎnshang, jiāngbiān de yānhuǒ tèbié piàoliang.","vi":"Đêm giao thừa, pháo hoa bên bờ sông đặc biệt đẹp."},{"type":"compound","zh":"虽然烟火只有短短几秒，但是给人留下了美好的回忆。","pinyin":"Suīrán yānhuǒ zhǐyǒu duǎn duǎn jǐ miǎo, dànshì gěi rén liúxiàle měihǎo de huíyì.","vi":"Tuy pháo hoa chỉ có vài giây ngắn ngủi nhưng để lại kỷ niệm đẹp."}],"related":[{"hanzi":"烟花","pinyin":"yānhuā","vi":"pháo hoa"},{"hanzi":"鞭炮","pinyin":"biānpào","vi":"pháo nổ"},{"hanzi":"放烟火","pinyin":"fàngyānhuǒ","vi":"bắn pháo hoa"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"}],"traditional":"煙火"},{"id":"淹","hanzi":"淹","pinyin":"yān","meaning_vi":"ngập, làm ngập; chết đuối","explanation":"淹 (yêm – ngâm, ngập): nước tràn ngập lên; cũng chỉ bị chết đuối.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌧️","examples":[{"type":"basic","zh":"大水淹了农田。","pinyin":"Dàshuǐ yānle nóngtián.","vi":"Nước lớn làm ngập ruộng đồng."},{"type":"simple","zh":"暴雨过后，好几条街都被淹了。","pinyin":"Bàoyǔ guòhòu, hǎojǐ tiáo jiē dōu bèi yān le.","vi":"Sau trận mưa lớn, mấy con phố đều bị ngập."},{"type":"compound","zh":"如果你不会游泳，就别去深水区，以免被淹。","pinyin":"Rúguǒ nǐ bú huì yóuyǒng, jiù bié qù shēn shuǐ qū, yǐmiǎn bèi yān.","vi":"Nếu bạn không biết bơi thì đừng ra chỗ nước sâu kẻo bị đuối nước."}],"related":[{"hanzi":"淹没","pinyin":"yānmò","vi":"nhấn chìm"},{"hanzi":"淹死","pinyin":"yānsǐ","vi":"chết đuối"},{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"},{"hanzi":"泡","pinyin":"pào","vi":"ngâm"}]},{"id":"延","hanzi":"延","pinyin":"yán","meaning_vi":"kéo dài, gia hạn; lùi lại, hoãn","explanation":"延 (diên – kéo dài): kéo dài thời gian hoặc khoảng cách; cũng chỉ lùi lại, hoãn lại.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"会议延到下周。","pinyin":"Huìyì yán dào xiàzhōu.","vi":"Cuộc họp được hoãn sang tuần sau."},{"type":"simple","zh":"因为下雨，比赛时间往后延了一天。","pinyin":"Yīnwèi xiàyǔ, bǐsài shíjiān wǎng hòu yánle yì tiān.","vi":"Vì trời mưa nên giờ thi đấu lùi lại một ngày."},{"type":"compound","zh":"如果签证快到期了，就要尽快去申请延期。","pinyin":"Rúguǒ qiānzhèng kuài dàoqī le, jiùyào jǐnkuài qù shēnqǐng yánqī.","vi":"Nếu thị thực sắp hết hạn thì phải nhanh chóng đi xin gia hạn."}],"related":[{"hanzi":"延长","pinyin":"yáncháng","vi":"kéo dài"},{"hanzi":"延期","pinyin":"yánqī","vi":"gia hạn, hoãn"},{"hanzi":"延续","pinyin":"yánxù","vi":"tiếp diễn"},{"hanzi":"推迟","pinyin":"tuīchí","vi":"trì hoãn"}]},{"id":"延缓","hanzi":"延缓","pinyin":"yánhuǎn","meaning_vi":"trì hoãn, làm chậm lại","explanation":"延 (diên – kéo dài) + 缓 (hoãn – chậm) → kéo dài thời gian, làm chậm lại.","hsk_level":"7-9","tags":["dong-tu"],"image":"🐢","examples":[{"type":"basic","zh":"运动能延缓衰老。","pinyin":"Yùndòng néng yánhuǎn shuāilǎo.","vi":"Tập thể dục có thể làm chậm quá trình lão hóa."},{"type":"simple","zh":"这种新药可以延缓病情的发展。","pinyin":"Zhè zhǒng xīn yào kěyǐ yánhuǎn bìngqíng de fāzhǎn.","vi":"Loại thuốc mới này có thể làm chậm diễn biến của bệnh."},{"type":"compound","zh":"虽然工程延缓了几个月，但是质量没有受到影响。","pinyin":"Suīrán gōngchéng yánhuǎnle jǐ gèyuè, dànshì zhìliàng méiyǒu shòudào yǐngxiǎng.","vi":"Tuy công trình bị chậm lại vài tháng nhưng chất lượng không bị ảnh hưởng."}],"related":[{"hanzi":"推迟","pinyin":"tuīchí","vi":"trì hoãn"},{"hanzi":"减缓","pinyin":"jiǎnhuǎn","vi":"giảm tốc"},{"hanzi":"延迟","pinyin":"yánchí","vi":"chậm trễ"},{"hanzi":"加速","pinyin":"jiāsù","vi":"tăng tốc"}],"traditional":"延緩"},{"id":"延误","hanzi":"延误","pinyin":"yánwù","meaning_vi":"chậm trễ, lỡ (thời cơ), bị hoãn","explanation":"延 (diên – kéo dài) + 误 (ngộ – lỡ, sai) → kéo dài làm lỡ việc, chậm trễ.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🛫","examples":[{"type":"basic","zh":"航班延误了。","pinyin":"Hángbān yánwù le.","vi":"Chuyến bay bị hoãn."},{"type":"simple","zh":"大雾导致很多航班严重延误。","pinyin":"Dàwù dǎozhì hěn duō hángbān yánzhòng yánwù.","vi":"Sương mù dày khiến nhiều chuyến bay bị hoãn nghiêm trọng."},{"type":"compound","zh":"如果病人没有及时送医，就会延误治疗。","pinyin":"Rúguǒ bìngrén méiyǒu jíshí sòngyī, jiù huì yánwù zhìliáo.","vi":"Nếu bệnh nhân không được đưa đi viện kịp thời thì sẽ lỡ thời điểm điều trị."}],"related":[{"hanzi":"耽误","pinyin":"dānwu","vi":"làm lỡ"},{"hanzi":"延迟","pinyin":"yánchí","vi":"chậm trễ"},{"hanzi":"推迟","pinyin":"tuīchí","vi":"hoãn lại"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"đúng giờ"}],"traditional":"延誤"},{"id":"言行","hanzi":"言行","pinyin":"yánxíng","meaning_vi":"lời nói và việc làm","explanation":"言 (ngôn – lời nói) + 行 (hành – việc làm) → lời nói và hành động của một người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🗨️","examples":[{"type":"basic","zh":"他言行一致。","pinyin":"Tā yánxíngyízhì.","vi":"Anh ấy nói và làm đi đôi với nhau."},{"type":"simple","zh":"老师的言行对学生影响很大。","pinyin":"Lǎoshī de yánxíng duì xuésheng yǐngxiǎng hěn dà.","vi":"Lời nói và việc làm của giáo viên ảnh hưởng rất lớn đến học sinh."},{"type":"compound","zh":"虽然他说得很好听，但是言行并不一致。","pinyin":"Suīrán tā shuō de hěn hǎotīng, dànshì yánxíng bìngbù yízhì.","vi":"Tuy anh ta nói rất hay nhưng lời nói và việc làm không hề nhất quán."}],"related":[{"hanzi":"行为","pinyin":"xíngwéi","vi":"hành vi"},{"hanzi":"言论","pinyin":"yánlùn","vi":"ngôn luận"},{"hanzi":"举止","pinyin":"jǔzhǐ","vi":"cử chỉ"},{"hanzi":"言行一致","pinyin":"yánxíngyízhì","vi":"nói đi đôi với làm"}]},{"id":"沿岸","hanzi":"沿岸","pinyin":"yán'àn","meaning_vi":"ven bờ, dọc bờ, vùng duyên hải","explanation":"沿 (duyên – men theo) + 岸 (ngạn – bờ) → khu vực men theo bờ sông, bờ biển.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏖️","examples":[{"type":"basic","zh":"长江沿岸城市很多。","pinyin":"Chángjiāng yán'àn chéngshì hěn duō.","vi":"Dọc bờ sông Trường Giang có rất nhiều thành phố."},{"type":"simple","zh":"沿岸的渔民大多靠打鱼为生。","pinyin":"Yán'àn de yúmín dàduō kào dǎyú wéishēng.","vi":"Ngư dân ven bờ phần lớn sống nhờ đánh cá."},{"type":"compound","zh":"因为台风快来了，所以沿岸居民都被转移到了安全地区。","pinyin":"Yīnwèi táifēng kuài lái le, suǒyǐ yán'àn jūmín dōu bèi zhuǎnyí dàole ānquán dìqū.","vi":"Vì bão sắp đến nên dân cư ven biển đều được sơ tán đến nơi an toàn."}],"related":[{"hanzi":"沿海","pinyin":"yánhǎi","vi":"ven biển"},{"hanzi":"海岸","pinyin":"hǎi'àn","vi":"bờ biển"},{"hanzi":"河岸","pinyin":"hé'àn","vi":"bờ sông"},{"hanzi":"沿线","pinyin":"yánxiàn","vi":"dọc tuyến"}]},{"id":"沿线","hanzi":"沿线","pinyin":"yánxiàn","meaning_vi":"dọc tuyến, ven tuyến (đường sắt, đường bộ)","explanation":"沿 (duyên – men theo) + 线 (tuyến – tuyến đường) → khu vực dọc theo một tuyến đường như đường sắt, đường cao tốc.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚆","examples":[{"type":"basic","zh":"铁路沿线风景很美。","pinyin":"Tiělù yánxiàn fēngjǐng hěn měi.","vi":"Phong cảnh dọc tuyến đường sắt rất đẹp."},{"type":"simple","zh":"地铁沿线的房价涨得特别快。","pinyin":"Dìtiě yánxiàn de fángjià zhǎng de tèbié kuài.","vi":"Giá nhà dọc tuyến tàu điện ngầm tăng rất nhanh."},{"type":"compound","zh":"因为高速公路修通了，所以沿线的小镇发展得很快。","pinyin":"Yīnwèi gāosùgōnglù xiū tōng le, suǒyǐ yánxiàn de xiǎozhèn fāzhǎn de hěn kuài.","vi":"Vì đường cao tốc đã thông xe nên các thị trấn dọc tuyến phát triển rất nhanh."}],"related":[{"hanzi":"沿途","pinyin":"yántú","vi":"dọc đường"},{"hanzi":"沿岸","pinyin":"yán'àn","vi":"ven bờ"},{"hanzi":"路线","pinyin":"lùxiàn","vi":"tuyến đường"},{"hanzi":"铁路","pinyin":"tiělù","vi":"đường sắt"}],"traditional":"沿線"},{"id":"炎症","hanzi":"炎症","pinyin":"yánzhèng","meaning_vi":"viêm, chứng viêm","explanation":"炎 (viêm – nóng, sưng) + 症 (chứng – bệnh chứng) → tình trạng cơ thể sưng, nóng, đau do viêm.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🔥","examples":[{"type":"basic","zh":"伤口有炎症了。","pinyin":"Shāngkǒu yǒu yánzhèng le.","vi":"Vết thương bị viêm rồi."},{"type":"simple","zh":"医生给他开了治疗炎症的药。","pinyin":"Yīshēng gěi tā kāile zhìliáo yánzhèng de yào.","vi":"Bác sĩ kê cho anh ấy thuốc chữa viêm."},{"type":"compound","zh":"如果炎症不及时控制，就可能引起发烧。","pinyin":"Rúguǒ yánzhèng bù jíshí kòngzhì, jiù kěnéng yǐnqǐ fāshāo.","vi":"Nếu không kiểm soát viêm kịp thời thì có thể gây sốt."}],"related":[{"hanzi":"发炎","pinyin":"fāyán","vi":"bị viêm"},{"hanzi":"消炎","pinyin":"xiāoyán","vi":"tiêu viêm"},{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"},{"hanzi":"感染","pinyin":"gǎnrǎn","vi":"nhiễm trùng"}]},{"id":"研讨","hanzi":"研讨","pinyin":"yántǎo","meaning_vi":"nghiên cứu thảo luận, hội thảo","explanation":"研 (nghiên – nghiên cứu) + 讨 (thảo – thảo luận) → cùng nghiên cứu và bàn bạc một vấn đề; thường dùng trong 研讨会 (hội thảo).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🗣️","examples":[{"type":"basic","zh":"专家们正在研讨方案。","pinyin":"Zhuānjiāmen zhèngzài yántǎo fāng'àn.","vi":"Các chuyên gia đang thảo luận phương án."},{"type":"simple","zh":"下周学院要研讨新的课程改革。","pinyin":"Xiàzhōu xuéyuàn yào yántǎo xīn de kèchéng gǎigé.","vi":"Tuần sau học viện sẽ hội thảo về cải cách chương trình mới."},{"type":"compound","zh":"虽然大家研讨了整整一天，但是还没达成一致。","pinyin":"Suīrán dàjiā yántǎole zhěngzhěng yī tiān, dànshì hái méi dáchéng yízhì.","vi":"Tuy mọi người đã thảo luận suốt cả ngày nhưng vẫn chưa thống nhất."}],"related":[{"hanzi":"研讨会","pinyin":"yántǎohuì","vi":"hội thảo"},{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"探讨","pinyin":"tàntǎo","vi":"thảo luận, tìm hiểu"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"}],"traditional":"研討"},{"id":"阎王","hanzi":"阎王","pinyin":"Yánwáng","meaning_vi":"Diêm Vương; kẻ hung ác tàn bạo","explanation":"阎 (Diêm) + 王 (vương – vua) → Diêm Vương, vua cõi âm trong Phật giáo; nghĩa bóng chỉ người hung dữ, độc ác.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"👹","examples":[{"type":"basic","zh":"他凶得像个阎王。","pinyin":"Tā xiōng de xiàng gè Yánwáng.","vi":"Anh ta dữ như Diêm Vương."},{"type":"simple","zh":"传说阎王掌管着人的生死。","pinyin":"Chuánshuō Yánwáng zhǎngguǎnzhe rén de shēngsǐ.","vi":"Truyền thuyết kể Diêm Vương nắm giữ sự sống chết của con người."},{"type":"compound","zh":"因为老板总是板着脸，所以员工私下叫他阎王。","pinyin":"Yīnwèi lǎobǎn zǒngshì bǎnzheliǎn, suǒyǐ yuángōng sīxià jiào tā Yánwáng.","vi":"Vì ông chủ lúc nào cũng mặt lạnh nên nhân viên lén gọi ông là Diêm Vương."}],"related":[{"hanzi":"地狱","pinyin":"dìyù","vi":"địa ngục"},{"hanzi":"魔鬼","pinyin":"móguǐ","vi":"ma quỷ"},{"hanzi":"阎罗","pinyin":"Yánluó","vi":"Diêm La"},{"hanzi":"恶霸","pinyin":"èbà","vi":"kẻ ác bá"}],"traditional":"閻王"},{"id":"衍生","hanzi":"衍生","pinyin":"yǎnshēng","meaning_vi":"phát sinh, sinh ra, phái sinh","explanation":"衍 (diễn – lan rộng, sinh sôi) + 生 (sinh – sinh ra) → từ cái gốc sinh ra cái mới; cũng dùng làm danh từ/định ngữ như 衍生品 (sản phẩm phái sinh).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🌱","examples":[{"type":"basic","zh":"这部电影衍生了很多周边产品。","pinyin":"Zhè bù diànyǐng yǎnshēngle hěn duō zhōubiān chǎnpǐn.","vi":"Bộ phim này sinh ra rất nhiều sản phẩm ăn theo."},{"type":"simple","zh":"网络发展衍生出许多新职业。","pinyin":"Wǎngluò fāzhǎn yǎnshēng chū xǔduō xīn zhíyè.","vi":"Sự phát triển của mạng đã sinh ra nhiều nghề mới."},{"type":"compound","zh":"一旦主要问题解决了，衍生的小问题就会减少。","pinyin":"Yídàn zhǔyào wèntí jiějué le, yǎnshēng de xiǎo wèntí jiù huì jiǎnshǎo.","vi":"Một khi vấn đề chính được giải quyết, các vấn đề nhỏ phát sinh sẽ giảm đi."}],"related":[{"hanzi":"衍生品","pinyin":"yǎnshēngpǐn","vi":"sản phẩm phái sinh"},{"hanzi":"派生","pinyin":"pàishēng","vi":"phái sinh"},{"hanzi":"产生","pinyin":"chǎnshēng","vi":"nảy sinh"},{"hanzi":"繁衍","pinyin":"fányǎn","vi":"sinh sôi"}]},{"id":"眼红","hanzi":"眼红","pinyin":"yǎnhóng","meaning_vi":"ghen tị, thèm muốn; đỏ mắt (tức giận)","explanation":"眼 (nhãn – mắt) + 红 (hồng – đỏ) → mắt đỏ lên vì thèm muốn cái của người khác; chỉ sự ghen tị, đố kỵ.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"别人发财他就眼红。","pinyin":"Biérén fācái tā jiù yǎnhóng.","vi":"Người khác phát tài là anh ta đỏ mắt ghen tị."},{"type":"simple","zh":"看到同事升职，他有点儿眼红。","pinyin":"Kàndào tóngshì shēngzhí, tā yǒudiǎnr yǎnhóng.","vi":"Thấy đồng nghiệp thăng chức, anh ấy hơi ghen tị."},{"type":"compound","zh":"与其眼红别人的成功，不如自己好好努力。","pinyin":"Yǔqí yǎnhóng biérén de chénggōng, bùrú zìjǐ hǎohǎo nǔlì.","vi":"Thay vì ghen tị với thành công của người khác, chi bằng tự mình cố gắng."}],"related":[{"hanzi":"嫉妒","pinyin":"jídù","vi":"đố kỵ"},{"hanzi":"羡慕","pinyin":"xiànmù","vi":"ngưỡng mộ, thèm muốn"},{"hanzi":"妒忌","pinyin":"dùjì","vi":"ghen ghét"},{"hanzi":"红眼病","pinyin":"hóngyǎnbìng","vi":"bệnh đỏ mắt (ghen tị)"}],"traditional":"眼紅"},{"id":"眼下","hanzi":"眼下","pinyin":"yǎnxià","meaning_vi":"hiện nay, trước mắt, lúc này","explanation":"眼 (nhãn – mắt) + 下 (hạ – dưới) → ngay dưới mắt, tức thời điểm hiện tại.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"眼下正是农忙季节。","pinyin":"Yǎnxià zhèngshì nóngmáng jìjié.","vi":"Hiện đang là mùa vụ bận rộn."},{"type":"simple","zh":"眼下最要紧的是找到住的地方。","pinyin":"Yǎnxià zuì yàojǐn de shì zhǎodào zhù de dìfang.","vi":"Việc cần kíp nhất lúc này là tìm chỗ ở."},{"type":"compound","zh":"虽然眼下困难很多，但是前景还是光明的。","pinyin":"Suīrán yǎnxià kùnnan hěn duō, dànshì qiánjǐng háishì guāngmíng de.","vi":"Tuy trước mắt có nhiều khó khăn nhưng tương lai vẫn tươi sáng."}],"related":[{"hanzi":"目前","pinyin":"mùqián","vi":"hiện nay"},{"hanzi":"当前","pinyin":"dāngqián","vi":"trước mắt"},{"hanzi":"现在","pinyin":"xiànzài","vi":"bây giờ"},{"hanzi":"眼前","pinyin":"yǎnqián","vi":"trước mắt"}]},{"id":"演播室","hanzi":"演播室","pinyin":"yǎnbōshì","meaning_vi":"trường quay, phòng thu phát sóng","explanation":"演 (diễn – biểu diễn) + 播 (bá – phát sóng) + 室 (thất – phòng) → phòng để biểu diễn và phát sóng chương trình truyền hình, phát thanh.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎙️","examples":[{"type":"basic","zh":"嘉宾已经进了演播室。","pinyin":"Jiābīn yǐjīng jìnle yǎnbōshì.","vi":"Khách mời đã vào trường quay."},{"type":"simple","zh":"电视台新建了一个大型演播室。","pinyin":"Diànshìtái xīnjiànle yí gè dàxíng yǎnbōshì.","vi":"Đài truyền hình mới xây một trường quay lớn."},{"type":"compound","zh":"因为节目要直播，所以演播室里谁也不能说话。","pinyin":"Yīnwèi jiémù yào zhíbō, suǒyǐ yǎnbōshì lǐ shéi yě bù néng shuōhuà.","vi":"Vì chương trình phát trực tiếp nên trong trường quay không ai được nói chuyện."}],"related":[{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"},{"hanzi":"录音棚","pinyin":"lùyīnpéng","vi":"phòng thu âm"},{"hanzi":"主持人","pinyin":"zhǔchírén","vi":"người dẫn chương trình"},{"hanzi":"电视台","pinyin":"diànshìtái","vi":"đài truyền hình"}]},{"id":"演技","hanzi":"演技","pinyin":"yǎnjì","meaning_vi":"diễn xuất, kỹ năng diễn xuất","explanation":"演 (diễn – biểu diễn) + 技 (kỹ – kỹ năng) → kỹ năng diễn xuất của diễn viên.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"她的演技非常自然。","pinyin":"Tā de yǎnjì fēicháng zìrán.","vi":"Diễn xuất của cô ấy rất tự nhiên."},{"type":"simple","zh":"这位新演员的演技受到了观众好评。","pinyin":"Zhè wèi xīn yǎnyuán de yǎnjì shòudàole guānzhòng hǎopíng.","vi":"Diễn xuất của diễn viên mới này được khán giả khen ngợi."},{"type":"compound","zh":"虽然他长得很帅，但是演技实在一般。","pinyin":"Suīrán tā zhǎngde hěn shuài, dànshì yǎnjì shízài yìbān.","vi":"Tuy anh ta rất đẹp trai nhưng diễn xuất thật sự bình thường."}],"related":[{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"biểu diễn"},{"hanzi":"技巧","pinyin":"jìqiǎo","vi":"kỹ xảo"},{"hanzi":"演戏","pinyin":"yǎnxì","vi":"đóng kịch"}]},{"id":"演练","hanzi":"演练","pinyin":"yǎnliàn","meaning_vi":"diễn tập, tập dượt","explanation":"演 (diễn – diễn tập) + 练 (luyện – luyện tập) → tập dượt theo tình huống giả định, như diễn tập phòng cháy.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚒","examples":[{"type":"basic","zh":"学校今天演练消防疏散。","pinyin":"Xuéxiào jīntiān yǎnliàn xiāofáng shūsàn.","vi":"Hôm nay trường diễn tập sơ tán phòng cháy."},{"type":"simple","zh":"士兵们在山区进行实战演练。","pinyin":"Shìbīngmen zài shānqū jìnxíng shízhàn yǎnliàn.","vi":"Binh lính tiến hành diễn tập thực chiến ở vùng núi."},{"type":"compound","zh":"只要平时多演练，遇到地震就不会慌张。","pinyin":"Zhǐyào píngshí duō yǎnliàn, yùdào dìzhèn jiù bú huì huāngzhāng.","vi":"Chỉ cần ngày thường diễn tập nhiều thì gặp động đất sẽ không hoảng."}],"related":[{"hanzi":"演习","pinyin":"yǎnxí","vi":"diễn tập"},{"hanzi":"训练","pinyin":"xùnliàn","vi":"huấn luyện"},{"hanzi":"练习","pinyin":"liànxí","vi":"luyện tập"},{"hanzi":"排练","pinyin":"páiliàn","vi":"tập dượt (biểu diễn)"}],"traditional":"演練"},{"id":"演示","hanzi":"演示","pinyin":"yǎnshì","meaning_vi":"trình diễn, minh họa, thuyết trình","explanation":"演 (diễn – thể hiện) + 示 (thị – cho thấy) → làm mẫu, trình bày cho người khác xem cách vận hành.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🖥️","examples":[{"type":"basic","zh":"请你演示一下操作步骤。","pinyin":"Qǐng nǐ yǎnshì yíxià cāozuò bùzhòu.","vi":"Mời bạn trình diễn các bước thao tác."},{"type":"simple","zh":"他用电脑给客户演示新软件的功能。","pinyin":"Tāyòng diànnǎo gěi kèhù yǎnshì xīn ruǎnjiàn de gōngnéng.","vi":"Anh ấy dùng máy tính trình diễn chức năng phần mềm mới cho khách hàng."},{"type":"compound","zh":"如果演示时网络断了，就先播放录好的视频。","pinyin":"Rúguǒ yǎnshì shí wǎngluò duàn le, jiù xiān bōfàng lù hǎo de shìpín.","vi":"Nếu lúc trình diễn bị mất mạng thì phát video đã quay sẵn trước."}],"related":[{"hanzi":"演示文稿","pinyin":"yǎnshìwéngǎo","vi":"bản trình chiếu"},{"hanzi":"展示","pinyin":"zhǎnshì","vi":"trưng bày, thể hiện"},{"hanzi":"示范","pinyin":"shìfàn","vi":"làm mẫu"},{"hanzi":"表演","pinyin":"biǎoyǎn","vi":"biểu diễn"}]},{"id":"演说","hanzi":"演说","pinyin":"yǎnshuō","meaning_vi":"diễn thuyết; bài diễn văn","explanation":"演 (diễn – trình bày) + 说 (thuyết – nói) → nói trước công chúng để trình bày quan điểm.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🎤","examples":[{"type":"basic","zh":"他的演说很有感染力。","pinyin":"Tā de yǎnshuō hěn yǒu gǎnrǎnlì.","vi":"Bài diễn thuyết của ông ấy rất có sức lôi cuốn."},{"type":"simple","zh":"总统在广场上发表了重要演说。","pinyin":"Zǒngtǒng zài guǎngchǎng shàng fābiǎole zhòngyào yǎnshuō.","vi":"Tổng thống đã có bài diễn văn quan trọng tại quảng trường."},{"type":"compound","zh":"虽然她第一次上台演说，但是一点儿也不紧张。","pinyin":"Suīrán tā dìyīcì shàngtái yǎnshuō, dànshì yìdiǎnr yě bù jǐnzhāng.","vi":"Tuy lần đầu lên bục diễn thuyết nhưng cô ấy chẳng hề căng thẳng."}],"related":[{"hanzi":"演讲","pinyin":"yǎnjiǎng","vi":"diễn giảng"},{"hanzi":"发言","pinyin":"fāyán","vi":"phát biểu"},{"hanzi":"口才","pinyin":"kǒucái","vi":"tài ăn nói"},{"hanzi":"讲话","pinyin":"jiǎnghuà","vi":"bài nói"}],"traditional":"演說"},{"id":"演戏","hanzi":"演戏","pinyin":"yǎnxì","meaning_vi":"đóng kịch, diễn kịch; giả vờ","explanation":"演 (diễn – biểu diễn) + 戏 (hí – kịch) → biểu diễn kịch, đóng phim; nghĩa bóng là giả vờ, làm bộ.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"她从小就喜欢演戏。","pinyin":"Tā cóngxiǎo jiù xǐhuan yǎnxì.","vi":"Cô ấy thích diễn kịch từ nhỏ."},{"type":"simple","zh":"别在我面前演戏了，我都知道了。","pinyin":"Bié zài wǒ miànqián yǎnxì le, wǒ dōu zhīdàole.","vi":"Đừng diễn kịch trước mặt tôi nữa, tôi biết hết rồi."},{"type":"compound","zh":"即使演戏很辛苦，他也从来不抱怨。","pinyin":"Jíshǐ yǎnxì hěn xīnkǔ, tā yě cóngláibú bàoyuàn.","vi":"Dù đóng phim rất vất vả, anh ấy cũng chưa từng than phiền."}],"related":[{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"演技","pinyin":"yǎnjì","vi":"diễn xuất"},{"hanzi":"拍戏","pinyin":"pāixì","vi":"quay phim"},{"hanzi":"装","pinyin":"zhuāng","vi":"giả vờ"}],"traditional":"演戲"},{"id":"演艺圈","hanzi":"演艺圈","pinyin":"yǎnyìquān","meaning_vi":"giới showbiz, làng giải trí","explanation":"演艺 (diễn nghệ – nghệ thuật biểu diễn) + 圈 (khuyên – giới, vòng) → giới những người làm nghệ thuật biểu diễn, showbiz.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🌟","examples":[{"type":"basic","zh":"他想进入演艺圈。","pinyin":"Tā xiǎng jìnrù yǎnyìquān.","vi":"Anh ấy muốn bước chân vào showbiz."},{"type":"simple","zh":"演艺圈的竞争比想象中激烈得多。","pinyin":"Yǎnyìquān de jìngzhēng bǐ xiǎngxiàng zhōng jīliè de duō.","vi":"Cạnh tranh trong làng giải trí khốc liệt hơn tưởng tượng nhiều."},{"type":"compound","zh":"虽然她退出演艺圈多年，但是粉丝仍然记得她。","pinyin":"Suīrán tā tuìchū yǎnyìquān duōnián, dànshì fěnsī réngrán jìde tā.","vi":"Tuy đã rời showbiz nhiều năm nhưng người hâm mộ vẫn nhớ đến cô."}],"related":[{"hanzi":"娱乐圈","pinyin":"yúlèquān","vi":"làng giải trí"},{"hanzi":"明星","pinyin":"míngxīng","vi":"ngôi sao"},{"hanzi":"艺人","pinyin":"yìrén","vi":"nghệ sĩ"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"}],"traditional":"演藝圈"},{"id":"厌烦","hanzi":"厌烦","pinyin":"yànfán","meaning_vi":"chán ghét, phát chán, ngán","explanation":"厌 (yếm – chán ghét) + 烦 (phiền – phiền muộn) → cảm thấy chán và bực vì điều gì lặp lại hoặc phiền phức.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😩","examples":[{"type":"basic","zh":"我厌烦了天天加班。","pinyin":"Wǒ yànfánle tiāntiān jiābān.","vi":"Tôi phát ngán chuyện ngày nào cũng tăng ca."},{"type":"simple","zh":"孩子对重复的练习感到厌烦。","pinyin":"Háizi duì chóngfù de liànxí gǎndào yànfán.","vi":"Đứa trẻ cảm thấy chán những bài tập lặp đi lặp lại."},{"type":"compound","zh":"如果你总是唠叨，别人就会厌烦。","pinyin":"Rúguǒ nǐ zǒngshì láodao, biérén jiù huì yànfán.","vi":"Nếu bạn cứ cằn nhằn mãi thì người khác sẽ thấy phiền chán."}],"related":[{"hanzi":"讨厌","pinyin":"tǎoyàn","vi":"ghét"},{"hanzi":"厌倦","pinyin":"yànjuàn","vi":"chán nản"},{"hanzi":"不耐烦","pinyin":"búnàifán","vi":"mất kiên nhẫn"},{"hanzi":"烦躁","pinyin":"fánzào","vi":"bực bội"}],"traditional":"厭煩"},{"id":"咽","hanzi":"咽","pinyin":"yān","meaning_vi":"họng, yết hầu (nuốt: yàn)","explanation":"咽 (yết/yến) chỉ cổ họng, hầu (yān); khi đọc yàn là động từ “nuốt”, như 咽下 (nuốt xuống).","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"👅","examples":[{"type":"basic","zh":"我咽部有点儿发炎。","pinyin":"Wǒ yān bù yǒudiǎnr fāyán.","vi":"Vùng họng của tôi hơi bị viêm."},{"type":"simple","zh":"医生仔细检查了病人的咽部。","pinyin":"Yīshēng zǐxì jiǎnchále bìngrén de yān bù.","vi":"Bác sĩ kiểm tra kỹ vùng họng của bệnh nhân."},{"type":"compound","zh":"因为咽部一直疼，所以他连饭都吃不下。","pinyin":"Yīnwèi yān bù yìzhí téng, suǒyǐ tā lián fàn dōu chībúxià.","vi":"Vì họng đau suốt nên anh ấy ăn cơm cũng không nổi."}],"related":[{"hanzi":"咽喉","pinyin":"yānhóu","vi":"yết hầu"},{"hanzi":"喉咙","pinyin":"hóulóng","vi":"cổ họng"},{"hanzi":"吞咽","pinyin":"tūnyàn","vi":"nuốt"},{"hanzi":"咽炎","pinyin":"yānyán","vi":"viêm họng"}]},{"id":"咽喉","hanzi":"咽喉","pinyin":"yānhóu","meaning_vi":"yết hầu, cổ họng; nơi hiểm yếu","explanation":"咽 (yết – họng) + 喉 (hầu – thanh quản) → cổ họng; nghĩa bóng chỉ vị trí then chốt, hiểm yếu.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🗣️","examples":[{"type":"basic","zh":"他的咽喉又红又肿。","pinyin":"Tā de yānhóu yòu hóng yòu zhǒng.","vi":"Cổ họng anh ấy vừa đỏ vừa sưng."},{"type":"simple","zh":"这个海峡是两国贸易的咽喉。","pinyin":"Zhè gè Hǎixiá shì liǎngguó màoyì de yānhóu.","vi":"Eo biển này là yết hầu thương mại của hai nước."},{"type":"compound","zh":"如果咽喉一直疼，就最好去医院看看。","pinyin":"Rúguǒ yānhóu yìzhí téng, jiù zuìhǎo qù yīyuàn kànkan.","vi":"Nếu cổ họng đau mãi thì tốt nhất nên đi bệnh viện khám."}],"related":[{"hanzi":"喉咙","pinyin":"hóulóng","vi":"cổ họng"},{"hanzi":"嗓子","pinyin":"sǎngzi","vi":"giọng, họng"},{"hanzi":"要道","pinyin":"yàodào","vi":"đường hiểm yếu"},{"hanzi":"咽炎","pinyin":"yānyán","vi":"viêm họng"}]},{"id":"验","hanzi":"验","pinyin":"yàn","meaning_vi":"kiểm tra, xét nghiệm, nghiệm","explanation":"验 (nghiệm – kiểm tra, thử) → kiểm tra để xác định thật giả hay tình trạng, như 验血 (xét nghiệm máu).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🧪","examples":[{"type":"basic","zh":"明天早上要验血。","pinyin":"Míngtiān zǎoshang yào yànxuè.","vi":"Sáng mai phải xét nghiệm máu."},{"type":"simple","zh":"海关人员仔细验了我的护照。","pinyin":"Hǎiguān rényuán zǐxì yànle wǒ de hùzhào.","vi":"Nhân viên hải quan kiểm tra kỹ hộ chiếu của tôi."},{"type":"compound","zh":"只要验一下指纹，就知道是不是他干的。","pinyin":"Zhǐyào yàn yíxià zhǐwén, jiù zhīdào shìbushì tā gàn de.","vi":"Chỉ cần kiểm tra dấu vân tay là biết có phải anh ta làm hay không."}],"related":[{"hanzi":"检验","pinyin":"jiǎnyàn","vi":"kiểm nghiệm"},{"hanzi":"验证","pinyin":"yànzhèng","vi":"xác minh"},{"hanzi":"化验","pinyin":"huàyàn","vi":"xét nghiệm"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"kinh nghiệm"}],"traditional":"驗"},{"id":"焰火","hanzi":"焰火","pinyin":"yànhuǒ","meaning_vi":"pháo hoa","explanation":"焰 (diệm – ngọn lửa) + 火 (hỏa – lửa) → pháo bắn lên trời tỏa ánh lửa nhiều màu.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎆","examples":[{"type":"basic","zh":"夜空中焰火绽放。","pinyin":"Yè kōngzhōng yànhuǒ zhànfàng.","vi":"Pháo hoa nở rộ trên bầu trời đêm."},{"type":"simple","zh":"春节晚上，江边放了很多焰火。","pinyin":"Chūnjié wǎnshang, jiāngbiān fàngle hěn duō yànhuǒ.","vi":"Đêm Tết, bên bờ sông bắn rất nhiều pháo hoa."},{"type":"compound","zh":"因为风太大，所以今晚的焰火表演取消了。","pinyin":"Yīnwèi fēng tài dà, suǒyǐ jīnwǎn de yànhuǒ biǎoyǎn qǔxiāo le.","vi":"Vì gió quá lớn nên màn trình diễn pháo hoa tối nay bị hủy."}],"related":[{"hanzi":"烟花","pinyin":"yānhuā","vi":"pháo hoa"},{"hanzi":"鞭炮","pinyin":"biānpào","vi":"pháo nổ"},{"hanzi":"火焰","pinyin":"huǒyàn","vi":"ngọn lửa"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"}]},{"id":"燕子","hanzi":"燕子","pinyin":"yànzi","meaning_vi":"chim én","explanation":"燕 (yến – chim én) + 子 (tử – hậu tố danh từ) → chim én, loài chim báo hiệu mùa xuân.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐦","examples":[{"type":"basic","zh":"燕子飞回来了。","pinyin":"Yànzi fēi huílái le.","vi":"Chim én đã bay về."},{"type":"simple","zh":"屋檐下有一个燕子的窝。","pinyin":"Wūyán xià yǒu yí gè yànzi de wō.","vi":"Dưới mái hiên có một tổ chim én."},{"type":"compound","zh":"每当燕子低飞的时候，往往就要下雨了。","pinyin":"Měidāng yànzi dī fēi de shíhou, wǎngwǎng jiùyào xiàyǔ le.","vi":"Mỗi khi chim én bay thấp thì thường là sắp mưa."}],"related":[{"hanzi":"燕窝","pinyin":"yànwō","vi":"tổ yến"},{"hanzi":"麻雀","pinyin":"máquè","vi":"chim sẻ"},{"hanzi":"候鸟","pinyin":"hòuniǎo","vi":"chim di cư"},{"hanzi":"春天","pinyin":"chūntiān","vi":"mùa xuân"}]},{"id":"秧歌","hanzi":"秧歌","pinyin":"yāngge","meaning_vi":"điệu múa ương ca (múa dân gian miền Bắc TQ)","explanation":"秧 (ương – mạ lúa) + 歌 (ca – bài hát) → vốn là điệu hát múa khi cấy lúa, nay là điệu múa dân gian vui nhộn phổ biến ở miền Bắc Trung Quốc.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💃","examples":[{"type":"basic","zh":"老人们在公园扭秧歌。","pinyin":"Lǎo rénmen zài gōngyuán niǔyāngge.","vi":"Các cụ già múa ương ca trong công viên."},{"type":"simple","zh":"过年时村里总有人扭秧歌、敲锣鼓。","pinyin":"Guònián shí cūnlǐ zǒng yǒurén niǔyāngge, qiāo luógǔ.","vi":"Dịp Tết trong làng luôn có người múa ương ca, đánh chiêng trống."},{"type":"compound","zh":"虽然秧歌动作简单，但是跳起来特别热闹。","pinyin":"Suīrán yāngge dòngzuò jiǎndān, dànshì tiào qǐlái tèbié rènao.","vi":"Tuy động tác ương ca đơn giản nhưng múa lên rất náo nhiệt."}],"related":[{"hanzi":"扭秧歌","pinyin":"niǔyāngge","vi":"múa ương ca"},{"hanzi":"民间舞","pinyin":"mínjiānwǔ","vi":"múa dân gian"},{"hanzi":"锣鼓","pinyin":"luógǔ","vi":"chiêng trống"},{"hanzi":"广场舞","pinyin":"guǎngchǎngwǔ","vi":"nhảy quảng trường"}]},{"id":"扬","hanzi":"扬","pinyin":"yáng","meaning_vi":"giơ lên, tung lên; truyền bá, tuyên dương","explanation":"扬 (dương – nâng lên, tung lên) → nâng cao, tung lên; mở rộng ra là truyền bá, tuyên dương, như 表扬, 发扬.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙌","examples":[{"type":"basic","zh":"她扬起头笑了。","pinyin":"Tā yáng qǐtóu xiào le.","vi":"Cô ấy ngẩng đầu lên cười."},{"type":"simple","zh":"风一吹，地上的尘土扬了起来。","pinyin":"Fēng yì chuī, dìshàng de chéntǔ yángle qǐlái.","vi":"Gió thổi một cái, bụi đất trên mặt đất tung lên."},{"type":"compound","zh":"我们不但要继承传统，而且要把它发扬光大。","pinyin":"Wǒmen búdàn yào jìchéng chuántǒng, érqiě yào bǎ tā fāyángguāngdà.","vi":"Chúng ta không chỉ kế thừa truyền thống mà còn phải phát huy rạng rỡ nó."}],"related":[{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"khen ngợi"},{"hanzi":"发扬","pinyin":"fāyáng","vi":"phát huy"},{"hanzi":"宣扬","pinyin":"xuānyáng","vi":"tuyên truyền"},{"hanzi":"飘扬","pinyin":"piāoyáng","vi":"tung bay"}],"traditional":"揚"},{"id":"阳性","hanzi":"阳性","pinyin":"yángxìng","meaning_vi":"dương tính; giống đực (ngữ pháp)","explanation":"阳 (dương – mặt tích cực, dương) + 性 (tính – tính chất) → kết quả xét nghiệm dương tính; trong ngữ pháp là giống đực.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"➕","examples":[{"type":"basic","zh":"检测结果是阳性。","pinyin":"Jiǎncè jiéguǒ shì yángxìng.","vi":"Kết quả xét nghiệm là dương tính."},{"type":"simple","zh":"他的病毒检测呈阳性，需要隔离。","pinyin":"Tā de bìngdú jiǎncè chéngyángxìng, xūyào gélí.","vi":"Xét nghiệm virus của anh ấy dương tính, cần cách ly."},{"type":"compound","zh":"一旦发现阳性病例，就要马上通知卫生部门。","pinyin":"Yídàn fāxiàn yángxìng bìnglì, jiùyào mǎshàng tōngzhī wèishēng bùmén.","vi":"Một khi phát hiện ca dương tính thì phải báo ngay cho cơ quan y tế."}],"related":[{"hanzi":"阴性","pinyin":"yīnxìng","vi":"âm tính"},{"hanzi":"检测","pinyin":"jiǎncè","vi":"xét nghiệm"},{"hanzi":"病例","pinyin":"bìnglì","vi":"ca bệnh"},{"hanzi":"隔离","pinyin":"gélí","vi":"cách ly"}],"traditional":"陽性"},{"id":"杨树","hanzi":"杨树","pinyin":"yángshù","meaning_vi":"cây dương, cây bạch dương","explanation":"杨 (dương – cây dương) + 树 (thụ – cây) → cây dương, loại cây thân cao thẳng, thường trồng ven đường ở miền Bắc.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"路边种满了杨树。","pinyin":"Lùbiān zhòng mǎnle yángshù.","vi":"Ven đường trồng đầy cây dương."},{"type":"simple","zh":"春天杨树的飞絮让很多人过敏。","pinyin":"Chūntiān yángshù de fēixù ràng hěn duō rén guòmǐn.","vi":"Mùa xuân bông cây dương bay khiến nhiều người dị ứng."},{"type":"compound","zh":"因为杨树长得快，所以北方常用它来防风。","pinyin":"Yīnwèi yángshù zhǎngde kuài, suǒyǐ běifāng chángyòng tā lái fángfēng.","vi":"Vì cây dương lớn nhanh nên miền Bắc hay trồng để chắn gió."}],"related":[{"hanzi":"柳树","pinyin":"liǔshù","vi":"cây liễu"},{"hanzi":"白杨","pinyin":"báiyáng","vi":"bạch dương"},{"hanzi":"树林","pinyin":"shùlín","vi":"rừng cây"},{"hanzi":"松树","pinyin":"sōngshù","vi":"cây thông"}],"traditional":"楊樹"},{"id":"养活","hanzi":"养活","pinyin":"yǎnghuo","meaning_vi":"nuôi sống, nuôi nấng","explanation":"养 (dưỡng – nuôi) + 活 (hoạt – sống) → nuôi cho sống, lo cái ăn cái mặc cho người hoặc vật.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"👨‍👩‍👧","examples":[{"type":"basic","zh":"他一个人养活全家。","pinyin":"Tā yígèrén yǎnghuo quánjiā.","vi":"Một mình anh ấy nuôi cả nhà."},{"type":"simple","zh":"这点工资连自己都养活不了。","pinyin":"Zhè diǎn gōngzī lián zìjǐ dōu yǎnghuo bùliǎo.","vi":"Đồng lương ít ỏi này nuôi bản thân còn không nổi."},{"type":"compound","zh":"虽然收入不高，但是她还是养活了三个孩子。","pinyin":"Suīrán shōurù bù gāo, dànshì tā háishì yǎnghuole sān gè háizi.","vi":"Tuy thu nhập không cao nhưng bà vẫn nuôi sống ba đứa con."}],"related":[{"hanzi":"抚养","pinyin":"fǔyǎng","vi":"nuôi dưỡng"},{"hanzi":"养家","pinyin":"yǎngjiā","vi":"nuôi gia đình"},{"hanzi":"供养","pinyin":"gōngyǎng","vi":"cấp dưỡng"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"cuộc sống"}],"traditional":"養活"},{"id":"养老金","hanzi":"养老金","pinyin":"yǎnglǎojīn","meaning_vi":"lương hưu, tiền dưỡng lão","explanation":"养老 (dưỡng lão – chăm lo tuổi già) + 金 (kim – tiền) → khoản tiền nhận hàng tháng khi về hưu.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"爷爷每月领养老金。","pinyin":"Yéye měiyuè lǐng yǎnglǎojīn.","vi":"Ông nội lĩnh lương hưu mỗi tháng."},{"type":"simple","zh":"今年退休人员的养老金又涨了。","pinyin":"Jīnnián tuìxiū rényuán de yǎnglǎojīn yòu zhǎng le.","vi":"Năm nay lương hưu của người về hưu lại tăng."},{"type":"compound","zh":"如果年轻时不交社保，老了就领不到养老金。","pinyin":"Rúguǒ niánqīng shí bù jiāo shèbǎo, lǎole jiù lǐng búdào yǎnglǎojīn.","vi":"Nếu lúc trẻ không đóng bảo hiểm xã hội thì về già sẽ không lĩnh được lương hưu."}],"related":[{"hanzi":"退休金","pinyin":"tuìxiūjīn","vi":"tiền hưu trí"},{"hanzi":"退休","pinyin":"tuìxiū","vi":"nghỉ hưu"},{"hanzi":"社保","pinyin":"shèbǎo","vi":"bảo hiểm xã hội"},{"hanzi":"养老院","pinyin":"yǎnglǎoyuàn","vi":"viện dưỡng lão"}],"traditional":"養老金"},{"id":"养老院","hanzi":"养老院","pinyin":"yǎnglǎoyuàn","meaning_vi":"viện dưỡng lão","explanation":"养老 (dưỡng lão – chăm lo tuổi già) + 院 (viện – nơi, cơ sở) → nơi chăm sóc người cao tuổi.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏥","examples":[{"type":"basic","zh":"奶奶住进了养老院。","pinyin":"Nǎinai zhù jìnle yǎnglǎoyuàn.","vi":"Bà nội đã vào ở viện dưỡng lão."},{"type":"simple","zh":"周末我们去养老院做义工。","pinyin":"Zhōumò wǒmen qù yǎnglǎoyuàn zuò yìgōng.","vi":"Cuối tuần chúng tôi đến viện dưỡng lão làm tình nguyện."},{"type":"compound","zh":"虽然养老院条件不错，但是老人还是想回家。","pinyin":"Suīrán yǎnglǎoyuàn tiáojiàn búcuò, dànshì lǎorén háishì xiǎng huíjiā.","vi":"Tuy điều kiện viện dưỡng lão khá tốt nhưng ông cụ vẫn muốn về nhà."}],"related":[{"hanzi":"敬老院","pinyin":"jìnglǎoyuàn","vi":"nhà dưỡng lão"},{"hanzi":"养老金","pinyin":"yǎnglǎojīn","vi":"lương hưu"},{"hanzi":"老人","pinyin":"lǎorén","vi":"người già"},{"hanzi":"护工","pinyin":"hùgōng","vi":"hộ lý"}],"traditional":"養老院"},{"id":"养殖","hanzi":"养殖","pinyin":"yǎngzhí","meaning_vi":"nuôi trồng (thủy sản, gia súc)","explanation":"养 (dưỡng – nuôi) + 殖 (thực – sinh sôi) → nuôi cho sinh sôi, thường nói về nuôi cá, tôm, gia súc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🐟","examples":[{"type":"basic","zh":"他在海边养殖海参。","pinyin":"Tā zài hǎibiān yǎngzhí hǎishēn.","vi":"Anh ấy nuôi hải sâm ở ven biển."},{"type":"simple","zh":"这个村靠养殖小龙虾富了起来。","pinyin":"Zhè gè cūn kào yǎngzhí xiǎolóngxiā fùle qǐlái.","vi":"Làng này giàu lên nhờ nuôi tôm hùm đất."},{"type":"compound","zh":"如果养殖技术不过关，就很容易亏本。","pinyin":"Rúguǒ yǎngzhí jìshù bú guòguān, jiù hěn róngyì kuīběn.","vi":"Nếu kỹ thuật nuôi trồng không đạt thì rất dễ lỗ vốn."}],"related":[{"hanzi":"养殖场","pinyin":"yǎngzhíchǎng","vi":"trại nuôi"},{"hanzi":"繁殖","pinyin":"fánzhí","vi":"sinh sản"},{"hanzi":"饲养","pinyin":"sìyǎng","vi":"chăn nuôi"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng trọt"}],"traditional":"養殖"},{"id":"氧","hanzi":"氧","pinyin":"yǎng","meaning_vi":"ôxy","explanation":"氧 (dưỡng) → nguyên tố ôxy, khí cần cho sự sống; thường gặp trong 氧气 (khí ôxy).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🫧","examples":[{"type":"basic","zh":"病人需要吸氧。","pinyin":"Bìngrén xūyào xīyǎng.","vi":"Bệnh nhân cần thở ôxy."},{"type":"simple","zh":"高原上空气稀薄，缺氧很常见。","pinyin":"Gāoyuán shàngkōng qì xībó, quēyǎng hěn chángjiàn.","vi":"Trên cao nguyên không khí loãng, thiếu ôxy rất thường gặp."},{"type":"compound","zh":"如果水里的氧不够，鱼就会浮到水面上来。","pinyin":"Rúguǒ shuǐ lǐ de yǎng búgòu, yú jiù huì fú dào shuǐmiàn shànglái.","vi":"Nếu ôxy trong nước không đủ, cá sẽ nổi lên mặt nước."}],"related":[{"hanzi":"氧气","pinyin":"yǎngqì","vi":"khí ôxy"},{"hanzi":"缺氧","pinyin":"quēyǎng","vi":"thiếu ôxy"},{"hanzi":"二氧化碳","pinyin":"èryǎnghuàtàn","vi":"CO2"},{"hanzi":"氢","pinyin":"qīng","vi":"hiđrô"}]},{"id":"痒","hanzi":"痒","pinyin":"yǎng","meaning_vi":"ngứa, nhột","explanation":"痒 (dạng – ngứa) → cảm giác ngứa trên da; còn dùng nghĩa bóng như 手痒 (ngứa tay, muốn làm).","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"🤧","examples":[{"type":"basic","zh":"蚊子咬得我很痒。","pinyin":"Wénzi yǎo de wǒ hěn yǎng.","vi":"Muỗi đốt làm tôi ngứa quá."},{"type":"simple","zh":"他背上起了疹子，痒得睡不着。","pinyin":"Tā bèi shang qǐle zhěnzi, yǎng de shuìbuzháo.","vi":"Lưng anh ấy nổi mẩn, ngứa đến mức không ngủ được."},{"type":"compound","zh":"即使皮肤很痒，你也不要用手去抓。","pinyin":"Jíshǐ pífū hěn yǎng, nǐ yě bú yào yòng shǒu qù zhuā.","vi":"Dù da có ngứa thế nào, bạn cũng đừng lấy tay gãi."}],"related":[{"hanzi":"瘙痒","pinyin":"sàoyǎng","vi":"ngứa ngáy"},{"hanzi":"挠","pinyin":"náo","vi":"gãi"},{"hanzi":"过敏","pinyin":"guòmǐn","vi":"dị ứng"},{"hanzi":"手痒","pinyin":"shǒuyǎng","vi":"ngứa tay"}],"traditional":"癢"},{"id":"样本","hanzi":"样本","pinyin":"yàngběn","meaning_vi":"mẫu, hàng mẫu, mẫu vật","explanation":"样 (dạng – kiểu, mẫu) + 本 (bản – bản) → vật hoặc bản dùng làm mẫu để xem xét, nghiên cứu.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🧫","examples":[{"type":"basic","zh":"请寄一份样本给我。","pinyin":"Qǐng jì yí fèn yàngběn gěi wǒ.","vi":"Vui lòng gửi cho tôi một bản mẫu."},{"type":"simple","zh":"研究人员采集了一千份血液样本。","pinyin":"Yánjiū rényuán cǎijíle yī qiān fèn xuèyè yàngběn.","vi":"Các nhà nghiên cứu đã thu thập một nghìn mẫu máu."},{"type":"compound","zh":"因为样本数量太少，所以结论不太可靠。","pinyin":"Yīnwèi yàngběn shùliàng tài shǎo, suǒyǐ jiélùn bú tài kěkào.","vi":"Vì số lượng mẫu quá ít nên kết luận không đáng tin lắm."}],"related":[{"hanzi":"样品","pinyin":"yàngpǐn","vi":"hàng mẫu"},{"hanzi":"标本","pinyin":"biāoběn","vi":"tiêu bản"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"抽样","pinyin":"chōuyàng","vi":"lấy mẫu"}],"traditional":"樣本"},{"id":"妖怪","hanzi":"妖怪","pinyin":"yāoguài","meaning_vi":"yêu quái, quái vật","explanation":"妖 (yêu – yêu tinh) + 怪 (quái – quái lạ) → yêu quái trong truyện thần thoại.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"👺","examples":[{"type":"basic","zh":"孙悟空打败了妖怪。","pinyin":"Sūnwùkōng dǎbàile yāoguài.","vi":"Tôn Ngộ Không đánh bại yêu quái."},{"type":"simple","zh":"小时候我很怕故事里的妖怪。","pinyin":"Xiǎoshíhou wǒ hěn pà gùshi lǐ de yāoguài.","vi":"Hồi nhỏ tôi rất sợ yêu quái trong truyện."},{"type":"compound","zh":"虽然妖怪会变成美女，但是孙悟空一眼就认出来了。","pinyin":"Suīrán yāoguài huì biànchéng měinǚ, dànshì Sūnwùkōng yìyǎn jiù rèn chūlái le.","vi":"Tuy yêu quái biến thành mỹ nữ nhưng Tôn Ngộ Không nhìn một cái là nhận ra."}],"related":[{"hanzi":"妖精","pinyin":"yāojing","vi":"yêu tinh"},{"hanzi":"魔鬼","pinyin":"móguǐ","vi":"ma quỷ"},{"hanzi":"怪物","pinyin":"guàiwu","vi":"quái vật"},{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"}]},{"id":"邀","hanzi":"邀","pinyin":"yāo","meaning_vi":"mời, rủ","explanation":"邀 (yêu/yêu cầu – mời) → mời, rủ người khác tham gia; thường gặp trong 邀请, 应邀.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"他邀我去喝茶。","pinyin":"Tā yāo wǒqù hēchá.","vi":"Anh ấy mời tôi đi uống trà."},{"type":"simple","zh":"我们特地邀了几位老同学来聚会。","pinyin":"Wǒmen tèdì yāole jǐ wèi lǎo tóngxué lái jùhuì.","vi":"Chúng tôi đặc biệt mời vài bạn học cũ đến họp mặt."},{"type":"compound","zh":"既然朋友盛情相邀，我就不好推辞了。","pinyin":"Jìrán péngyou shèngqíng xiāng yāo, wǒ jiù bù hǎo tuīcí le.","vi":"Bạn bè đã nhiệt tình mời thì tôi khó lòng từ chối."}],"related":[{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"mời"},{"hanzi":"应邀","pinyin":"yìngyāo","vi":"nhận lời mời"},{"hanzi":"邀约","pinyin":"yāoyuē","vi":"hẹn mời"},{"hanzi":"请","pinyin":"qǐng","vi":"mời"}]},{"id":"窑","hanzi":"窑","pinyin":"yáo","meaning_vi":"lò (nung gạch, gốm); hang ở","explanation":"窑 (diêu – lò nung) → lò nung gạch, ngói, gốm sứ; cũng chỉ hang động để ở như 窑洞.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🏺","examples":[{"type":"basic","zh":"这座窑专门烧瓷器。","pinyin":"Zhè zuò yáo zhuānmén shāo cíqì.","vi":"Lò này chuyên nung đồ sứ."},{"type":"simple","zh":"村子里还保留着一座百年老窑。","pinyin":"Cūnzi lǐ hái bǎoliúzhe yí zuò bǎi niánlǎo yáo.","vi":"Trong làng vẫn còn giữ một lò nung trăm năm tuổi."},{"type":"compound","zh":"如果窑里的温度不够高，瓷器就烧不好。","pinyin":"Rúguǒ yáo lǐ de wēndù búgòu gāo, cíqì jiù shāo bù hǎo.","vi":"Nếu nhiệt độ trong lò không đủ cao thì đồ sứ nung không đạt."}],"related":[{"hanzi":"窑洞","pinyin":"yáodòng","vi":"nhà hang"},{"hanzi":"瓷器","pinyin":"cíqì","vi":"đồ sứ"},{"hanzi":"砖窑","pinyin":"zhuānyáo","vi":"lò gạch"},{"hanzi":"陶瓷","pinyin":"táocí","vi":"gốm sứ"}],"traditional":"窯"},{"id":"摇滚","hanzi":"摇滚","pinyin":"yáogǔn","meaning_vi":"nhạc rock","explanation":"摇 (dao – lắc) + 滚 (cổn – lăn) → dịch ý từ rock 'n' roll, dòng nhạc sôi động.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎸","examples":[{"type":"basic","zh":"他特别爱听摇滚。","pinyin":"Tā tèbié ài tīng yáogǔn.","vi":"Anh ấy đặc biệt thích nghe nhạc rock."},{"type":"simple","zh":"这支摇滚乐队在年轻人中很有名。","pinyin":"Zhè zhī yáogǔn yuèduì zài niánqīng rénzhōng hěn yǒumíng.","vi":"Ban nhạc rock này rất nổi tiếng trong giới trẻ."},{"type":"compound","zh":"虽然父母不喜欢摇滚，但是他坚持组了乐队。","pinyin":"Suīrán fùmǔ bù xǐhuan yáogǔn, dànshì tā jiānchí zǔle yuèduì.","vi":"Tuy bố mẹ không thích nhạc rock nhưng cậu ấy vẫn kiên quyết lập ban nhạc."}],"related":[{"hanzi":"摇滚乐","pinyin":"yáogǔnyuè","vi":"nhạc rock"},{"hanzi":"乐队","pinyin":"yuèduì","vi":"ban nhạc"},{"hanzi":"流行乐","pinyin":"liúxíngyuè","vi":"nhạc pop"},{"hanzi":"吉他","pinyin":"jítā","vi":"đàn ghi-ta"}],"traditional":"搖滾"},{"id":"摇摇欲坠","hanzi":"摇摇欲坠","pinyin":"yáoyáo-yùzhuì","meaning_vi":"lung lay sắp đổ, chực sụp đổ","explanation":"摇摇 (dao dao – lắc lư) + 欲 (dục – sắp) + 坠 (trụy – rơi) → lắc lư sắp rơi; nghĩa bóng chỉ tình thế bấp bênh, sắp sụp đổ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏚️","examples":[{"type":"basic","zh":"那座老房子摇摇欲坠。","pinyin":"Nà zuò lǎo fángzi yáoyáoyùzhuì.","vi":"Ngôi nhà cũ đó lung lay sắp đổ."},{"type":"simple","zh":"这家公司的经营已经摇摇欲坠。","pinyin":"Zhè jiā gōngsī de jīngyíng yǐjīng yáoyáoyùzhuì.","vi":"Việc kinh doanh của công ty này đã chực sụp đổ."},{"type":"compound","zh":"因为那面墙摇摇欲坠，所以工人赶紧把它拆了。","pinyin":"Yīnwèi nà miàn qiáng yáoyáoyùzhuì, suǒyǐ gōngrén gǎnjǐn bǎ tā chāi le.","vi":"Vì bức tường đó lung lay sắp đổ nên công nhân vội dỡ nó đi."}],"related":[{"hanzi":"岌岌可危","pinyin":"jíjíkěwēi","vi":"nguy cơ cận kề"},{"hanzi":"摇晃","pinyin":"yáohuàng","vi":"lắc lư"},{"hanzi":"坚如磐石","pinyin":"jiānrúpánshí","vi":"vững như bàn thạch"},{"hanzi":"倒塌","pinyin":"dǎotā","vi":"sụp đổ"}],"traditional":"搖搖欲墜"},{"id":"遥控","hanzi":"遥控","pinyin":"yáokòng","meaning_vi":"điều khiển từ xa","explanation":"遥 (dao – xa) + 控 (khống – điều khiển) → điều khiển từ xa; cũng chỉ cái điều khiển (遥控器).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🎮","examples":[{"type":"basic","zh":"他用手机遥控空调。","pinyin":"Tāyòng shǒujī yáokòng kōngtiáo.","vi":"Anh ấy dùng điện thoại điều khiển máy lạnh từ xa."},{"type":"simple","zh":"孩子在广场上遥控一架小飞机。","pinyin":"Háizi zài guǎngchǎng shàng yáokòng yí jià xiǎo fēijī.","vi":"Đứa trẻ điều khiển từ xa một chiếc máy bay nhỏ ở quảng trường."},{"type":"compound","zh":"即使人在国外，他也能遥控公司的大小事情。","pinyin":"Jíshǐ rén zài guówài, tā yě néng yáokòng gōngsī de dàxiǎo shìqing.","vi":"Dù đang ở nước ngoài, ông ấy vẫn điều khiển từ xa mọi việc lớn nhỏ của công ty."}],"related":[{"hanzi":"遥控器","pinyin":"yáokòngqì","vi":"cái điều khiển"},{"hanzi":"控制","pinyin":"kòngzhì","vi":"kiểm soát"},{"hanzi":"无人机","pinyin":"wúrénjī","vi":"máy bay không người lái"},{"hanzi":"远程","pinyin":"yuǎnchéng","vi":"từ xa"}],"traditional":"遙控"},{"id":"药方","hanzi":"药方","pinyin":"yàofāng","meaning_vi":"đơn thuốc, phương thuốc","explanation":"药 (dược – thuốc) + 方 (phương – phương thuốc) → đơn kê các vị thuốc để chữa bệnh.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"📜","examples":[{"type":"basic","zh":"医生给我开了药方。","pinyin":"Yīshēng gěi wǒ kāile yàofāng.","vi":"Bác sĩ đã kê đơn thuốc cho tôi."},{"type":"simple","zh":"这是他家祖传的中药药方。","pinyin":"Zhè shì tā jiā zǔchuán de zhōngyào yàofāng.","vi":"Đây là phương thuốc Bắc gia truyền của nhà anh ấy."},{"type":"compound","zh":"没有医生的药方，药店就不能卖这种药。","pinyin":"Méiyǒu yīshēng de yàofāng, yàodiàn jiù bù néng mài zhè zhǒng yào.","vi":"Không có đơn của bác sĩ thì hiệu thuốc không được bán loại thuốc này."}],"related":[{"hanzi":"处方","pinyin":"chǔfāng","vi":"đơn thuốc"},{"hanzi":"偏方","pinyin":"piānfāng","vi":"bài thuốc dân gian"},{"hanzi":"中药","pinyin":"zhōngyào","vi":"thuốc Bắc"},{"hanzi":"配方","pinyin":"pèifāng","vi":"công thức"}],"traditional":"藥方"},{"id":"要不","hanzi":"要不","pinyin":"yàobù","meaning_vi":"nếu không thì, hay là","explanation":"要 (yếu – nếu) + 不 (bất – không) → “nếu không” (biểu thị kết quả ngược lại), hoặc “hay là” để đề nghị.","hsk_level":"7-9","tags":["lien-tu"],"image":"🔀","examples":[{"type":"basic","zh":"快走吧，要不就迟到了。","pinyin":"Kuài zǒu ba, yàobú jiù chídào le.","vi":"Đi nhanh thôi, nếu không sẽ muộn."},{"type":"simple","zh":"要不我们周末去爬山吧？","pinyin":"Yàobù wǒmen zhōumò qù páshān ba?","vi":"Hay là cuối tuần chúng ta đi leo núi nhé?"},{"type":"compound","zh":"你最好带把伞，要不下雨的话就会淋湿。","pinyin":"Nǐ zuìhǎo dài bǎ sǎn, yàobú xiàyǔ dehuà jiù huì línshī.","vi":"Bạn nên mang ô, nếu không trời mưa sẽ bị ướt."}],"related":[{"hanzi":"要不然","pinyin":"yàobùrán","vi":"nếu không thì"},{"hanzi":"否则","pinyin":"fǒuzé","vi":"nếu không"},{"hanzi":"不然","pinyin":"bùrán","vi":"bằng không"},{"hanzi":"要不是","pinyin":"yàobushì","vi":"nếu không phải"}]},{"id":"要不是","hanzi":"要不是","pinyin":"yàobushì","meaning_vi":"nếu không phải (vì), nếu không nhờ","explanation":"要 (nếu) + 不是 (không phải) → giả định ngược lại với sự thật: “nếu không vì…”, vế sau nêu kết quả khác đi.","hsk_level":"7-9","tags":["lien-tu"],"image":"🙏","examples":[{"type":"basic","zh":"要不是你，我就输了。","pinyin":"Yàobushì nǐ, wǒ jiù shū le.","vi":"Nếu không nhờ bạn thì tôi đã thua rồi."},{"type":"simple","zh":"要不是堵车，我早就到了。","pinyin":"Yàobushì dǔchē, wǒ zǎojiù dào le.","vi":"Nếu không tắc đường thì tôi đã đến từ lâu."},{"type":"compound","zh":"要不是医生及时抢救，他就没命了。","pinyin":"Yàobushì yīshēng jíshí qiǎngjiù, tā jiù méimìng le.","vi":"Nếu không nhờ bác sĩ cấp cứu kịp thời thì anh ấy đã mất mạng."}],"related":[{"hanzi":"要不","pinyin":"yàobù","vi":"nếu không thì"},{"hanzi":"如果","pinyin":"rúguǒ","vi":"nếu"},{"hanzi":"幸亏","pinyin":"xìngkuī","vi":"may mà"},{"hanzi":"多亏","pinyin":"duōkuī","vi":"nhờ có"}]},{"id":"要害","hanzi":"要害","pinyin":"yàohài","meaning_vi":"chỗ hiểm, điểm mấu chốt","explanation":"要 (yếu – quan trọng) + 害 (hại – nguy hại) → bộ phận trọng yếu, bị thương là nguy hiểm; nghĩa bóng là chỗ then chốt của vấn đề.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"这一刀没伤到要害。","pinyin":"Zhè yì dāo méi shāng dào yàohài.","vi":"Nhát dao này không trúng chỗ hiểm."},{"type":"simple","zh":"他的话一下子说中了问题的要害。","pinyin":"Tā dehuà yíxiàzi shuōzhòngle wèntí de yàohài.","vi":"Lời anh ấy nói trúng ngay điểm mấu chốt của vấn đề."},{"type":"compound","zh":"如果抓不住要害，就算忙一整天也没用。","pinyin":"Rúguǒ zhuā búzhù yàohài, jiùsuàn máng yìzhěngtiān yě méiyòng.","vi":"Nếu không nắm được mấu chốt thì dù bận cả ngày cũng vô ích."}],"related":[{"hanzi":"关键","pinyin":"guānjiàn","vi":"mấu chốt"},{"hanzi":"要点","pinyin":"yàodiǎn","vi":"điểm chính"},{"hanzi":"致命","pinyin":"zhìmìng","vi":"chí mạng"},{"hanzi":"核心","pinyin":"héxīn","vi":"cốt lõi"}]},{"id":"要紧","hanzi":"要紧","pinyin":"yàojǐn","meaning_vi":"quan trọng, hệ trọng, nghiêm trọng","explanation":"要 (yếu – quan trọng) + 紧 (khẩn – gấp) → quan trọng và cấp bách; 不要紧 nghĩa là “không sao”.","hsk_level":"7-9","tags":["tinh-tu"],"image":"❗","examples":[{"type":"basic","zh":"这件事很要紧。","pinyin":"Zhè jiàn shì hěn yàojǐn.","vi":"Việc này rất quan trọng."},{"type":"simple","zh":"我有要紧的事，得先走一步。","pinyin":"Wǒ yǒu yàojǐn de shì, děi xiān zǒu yí bù.","vi":"Tôi có việc quan trọng, phải đi trước một bước."},{"type":"compound","zh":"虽然伤得不要紧，但是你还是去医院看看吧。","pinyin":"Suīrán shāng de búyàojǐn, dànshì nǐ háishì qù yīyuàn kànkan ba.","vi":"Tuy vết thương không nghiêm trọng nhưng bạn vẫn nên đi viện khám."}],"related":[{"hanzi":"重要","pinyin":"zhòngyào","vi":"quan trọng"},{"hanzi":"紧急","pinyin":"jǐnjí","vi":"khẩn cấp"},{"hanzi":"不要紧","pinyin":"búyàojǐn","vi":"không sao"},{"hanzi":"要命","pinyin":"yàomìng","vi":"nguy hiểm, quá mức"}],"traditional":"要緊"},{"id":"要领","hanzi":"要领","pinyin":"yàolǐng","meaning_vi":"điểm cốt yếu, yếu lĩnh, bí quyết","explanation":"要 (yếu – trọng yếu) + 领 (lĩnh – cổ áo, cái nắm giữ) → phần chủ yếu, then chốt của động tác hay vấn đề.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📌","examples":[{"type":"basic","zh":"他很快掌握了要领。","pinyin":"Tā hěn kuài zhǎngwòle yàolǐng.","vi":"Anh ấy nhanh chóng nắm được yếu lĩnh."},{"type":"simple","zh":"教练一遍遍讲解游泳的动作要领。","pinyin":"Jiàoliàn yíbiàn biàn jiǎngjiě yóuyǒng de dòngzuò yàolǐng.","vi":"Huấn luyện viên giảng đi giảng lại yếu lĩnh động tác bơi."},{"type":"compound","zh":"只要掌握了要领，学开车就不难。","pinyin":"Zhǐyào zhǎngwòle yàolǐng, xué kāichē jiù bùnán.","vi":"Chỉ cần nắm được bí quyết thì học lái xe không khó."}],"related":[{"hanzi":"要点","pinyin":"yàodiǎn","vi":"ý chính"},{"hanzi":"不得要领","pinyin":"bùdéyàolǐng","vi":"không nắm được trọng tâm"},{"hanzi":"诀窍","pinyin":"juéqiào","vi":"bí quyết"},{"hanzi":"技巧","pinyin":"jìqiǎo","vi":"kỹ xảo"}],"traditional":"要領"},{"id":"要强","hanzi":"要强","pinyin":"yàoqiáng","meaning_vi":"hiếu thắng, không chịu thua kém","explanation":"要 (yếu – muốn) + 强 (cường – mạnh, hơn người) → luôn muốn hơn người, không chịu thua kém.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"💪","examples":[{"type":"basic","zh":"她是个要强的女人。","pinyin":"Tā shì gè yàoqiáng de nǚrén.","vi":"Cô ấy là người phụ nữ không chịu thua kém ai."},{"type":"simple","zh":"他从小要强，什么事都想做第一。","pinyin":"Tā cóngxiǎo yàoqiáng, shénmeshì dōu xiǎng zuò dìyī.","vi":"Từ nhỏ cậu ấy đã hiếu thắng, việc gì cũng muốn đứng đầu."},{"type":"compound","zh":"因为她太要强，所以生病了也不肯请假。","pinyin":"Yīnwèi tā tài yàoqiáng, suǒyǐ shēngbìngle yě bùkěn qǐngjià.","vi":"Vì cô ấy quá hiếu thắng nên ốm cũng không chịu xin nghỉ."}],"related":[{"hanzi":"好强","pinyin":"hàoqiáng","vi":"hiếu thắng"},{"hanzi":"争强好胜","pinyin":"zhēngqiánghàoshèng","vi":"tranh hơn thua"},{"hanzi":"倔强","pinyin":"juéjiàng","vi":"bướng bỉnh"},{"hanzi":"上进","pinyin":"shàngjìn","vi":"cầu tiến"}],"traditional":"要強"},{"id":"椰子","hanzi":"椰子","pinyin":"yēzi","meaning_vi":"dừa, cây dừa","explanation":"椰 (da – cây dừa) + 子 (tử – quả) → quả dừa hoặc cây dừa.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🥥","examples":[{"type":"basic","zh":"我想喝椰子汁。","pinyin":"Wǒ xiǎng hē yēzizhī.","vi":"Tôi muốn uống nước dừa."},{"type":"simple","zh":"海南的海边到处都是椰子树。","pinyin":"Hǎinán de hǎibiān dàochù dōu shì yēzishù.","vi":"Bờ biển Hải Nam đâu đâu cũng là cây dừa."},{"type":"compound","zh":"虽然椰子壳很硬，但是用刀一劈就开了。","pinyin":"Suīrán yēzi ké hěn yìng, dànshì yòng dāo yì pī jiù kāi le.","vi":"Tuy vỏ dừa rất cứng nhưng dùng dao bổ một cái là mở ra."}],"related":[{"hanzi":"椰汁","pinyin":"yēzhī","vi":"nước dừa"},{"hanzi":"椰子树","pinyin":"yēzishù","vi":"cây dừa"},{"hanzi":"芒果","pinyin":"mángguǒ","vi":"xoài"},{"hanzi":"热带","pinyin":"rèdài","vi":"nhiệt đới"}]},{"id":"也就是说","hanzi":"也就是说","pinyin":"yějiùshìshuō","meaning_vi":"nói cách khác, tức là","explanation":"也 (dã – cũng) + 就是 (chính là) + 说 (thuyết – nói) → dùng để diễn giải lại ý trước bằng cách khác, “tức là”.","hsk_level":"7-9","tags":["lien-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"也就是说，你不来了？","pinyin":"Yě jiùshì shuō, nǐ bù lái le?","vi":"Tức là bạn không đến nữa à?"},{"type":"simple","zh":"他没回复，也就是说他不同意。","pinyin":"Tā méi huífù, yě jiùshì shuō tā bù tóngyì.","vi":"Anh ấy không trả lời, tức là anh ấy không đồng ý."},{"type":"compound","zh":"票已经卖完了，也就是说我们只能改天再来。","pinyin":"Piào yǐjīng mài wánle, yě jiùshì shuō wǒmen zhǐnéng gǎitiān zài lái.","vi":"Vé đã bán hết rồi, nói cách khác là chúng ta chỉ có thể hôm khác quay lại."}],"related":[{"hanzi":"换句话说","pinyin":"huànjùhuàshuō","vi":"nói cách khác"},{"hanzi":"即","pinyin":"jí","vi":"tức là"},{"hanzi":"就是说","pinyin":"jiùshìshuō","vi":"nghĩa là"},{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"}],"traditional":"也就是說"},{"id":"野餐","hanzi":"野餐","pinyin":"yěcān","meaning_vi":"dã ngoại, picnic","explanation":"野 (dã – đồng nội) + 餐 (xan – bữa ăn) → bữa ăn ngoài trời khi đi chơi.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🧺","examples":[{"type":"basic","zh":"周末去公园野餐吧。","pinyin":"Zhōumò qù gōngyuán yěcān ba.","vi":"Cuối tuần đi công viên picnic nhé."},{"type":"simple","zh":"我们在湖边铺了块布，开始野餐。","pinyin":"Wǒmen zài húbiān pūle kuài bù, kāishǐ yěcān.","vi":"Chúng tôi trải tấm vải bên hồ rồi bắt đầu picnic."},{"type":"compound","zh":"如果明天天气好，我们就带孩子去野餐。","pinyin":"Rúguǒ míngtiān tiānqì hǎo, wǒmen jiù dàiháizi qù yěcān.","vi":"Nếu mai trời đẹp, chúng ta sẽ đưa con đi picnic."}],"related":[{"hanzi":"野炊","pinyin":"yěchuī","vi":"nấu ăn ngoài trời"},{"hanzi":"郊游","pinyin":"jiāoyóu","vi":"đi chơi ngoại ô"},{"hanzi":"露营","pinyin":"lùyíng","vi":"cắm trại"},{"hanzi":"烧烤","pinyin":"shāokǎo","vi":"nướng BBQ"}]},{"id":"野炊","hanzi":"野炊","pinyin":"yěchuī","meaning_vi":"nấu ăn ngoài trời, cắm trại nấu nướng","explanation":"野 (dã – ngoài trời) + 炊 (xuy – nấu nướng) → nhóm lửa nấu ăn ngoài trời khi đi dã ngoại.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🏕️","examples":[{"type":"basic","zh":"同学们去河边野炊。","pinyin":"Tóngxuémen qù hébiān yěchuī.","vi":"Các bạn học đi nấu ăn dã ngoại ven sông."},{"type":"simple","zh":"野炊的时候大家分工捡柴、洗菜。","pinyin":"Yěchuī de shíhou dàjiā fēngōng jiǎn chái, xǐ cài.","vi":"Lúc nấu ăn ngoài trời mọi người chia nhau nhặt củi, rửa rau."},{"type":"compound","zh":"虽然野炊做的饭很简单，但是大家吃得特别香。","pinyin":"Suīrán yěchuī zuò de fàn hěn jiǎndān, dànshì dàjiā chī de tèbié xiāng.","vi":"Tuy món nấu ngoài trời rất đơn giản nhưng mọi người ăn rất ngon miệng."}],"related":[{"hanzi":"野餐","pinyin":"yěcān","vi":"picnic"},{"hanzi":"露营","pinyin":"lùyíng","vi":"cắm trại"},{"hanzi":"篝火","pinyin":"gōuhuǒ","vi":"lửa trại"},{"hanzi":"炊烟","pinyin":"chuīyān","vi":"khói bếp"}]},{"id":"野兽","hanzi":"野兽","pinyin":"yěshòu","meaning_vi":"dã thú, thú hoang","explanation":"野 (dã – hoang dã) + 兽 (thú – thú vật) → thú vật sống hoang trong tự nhiên.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐺","examples":[{"type":"basic","zh":"山里常有野兽出没。","pinyin":"Shān lǐ chángyǒu yěshòu chūmò.","vi":"Trong núi thường có dã thú xuất hiện."},{"type":"simple","zh":"猎人晚上点火防止野兽靠近。","pinyin":"Lièrén wǎnshang diǎnhuǒ fángzhǐ yěshòu kàojìn.","vi":"Thợ săn đốt lửa ban đêm để dã thú không lại gần."},{"type":"compound","zh":"即使遇到野兽，你也不要转身就跑。","pinyin":"Jíshǐ yùdào yěshòu, nǐ yě bú yào zhuǎnshēn jiù pǎo.","vi":"Dù gặp dã thú, bạn cũng đừng quay lưng bỏ chạy."}],"related":[{"hanzi":"猛兽","pinyin":"měngshòu","vi":"thú dữ"},{"hanzi":"动物","pinyin":"dòngwù","vi":"động vật"},{"hanzi":"野生","pinyin":"yěshēng","vi":"hoang dã"},{"hanzi":"禽兽","pinyin":"qínshòu","vi":"cầm thú"}],"traditional":"野獸"},{"id":"野外","hanzi":"野外","pinyin":"yěwài","meaning_vi":"dã ngoại, ngoài trời, vùng hoang","explanation":"野 (dã – đồng nội) + 外 (ngoại – bên ngoài) → nơi hoang dã ngoài thành phố, ngoài trời.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"他喜欢在野外拍鸟。","pinyin":"Tā xǐhuan zài yěwài pāi niǎo.","vi":"Anh ấy thích chụp chim ngoài thiên nhiên."},{"type":"simple","zh":"参加野外训练要带足水和食物。","pinyin":"Cānjiā yěwài xùnliàn yào dài zú shuǐ hé shíwù.","vi":"Tham gia huấn luyện dã ngoại phải mang đủ nước và thức ăn."},{"type":"compound","zh":"如果在野外迷了路，就待在原地等人来救。","pinyin":"Rúguǒ zài yěwài míle lù, jiù dāi zài yuándì děng rén lái jiù.","vi":"Nếu bị lạc ngoài hoang dã thì ở yên tại chỗ chờ người đến cứu."}],"related":[{"hanzi":"户外","pinyin":"hùwài","vi":"ngoài trời"},{"hanzi":"郊外","pinyin":"jiāowài","vi":"ngoại ô"},{"hanzi":"野生","pinyin":"yěshēng","vi":"hoang dã"},{"hanzi":"荒野","pinyin":"huāngyě","vi":"đồng hoang"}]},{"id":"野营","hanzi":"野营","pinyin":"yěyíng","meaning_vi":"cắm trại","explanation":"野 (dã – ngoài trời) + 营 (doanh – doanh trại, trại) → dựng lều ở ngoài trời để nghỉ.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"⛺","examples":[{"type":"basic","zh":"暑假我们去山里野营。","pinyin":"Shǔjià wǒmen qù shān lǐ yěyíng.","vi":"Nghỉ hè chúng tôi vào núi cắm trại."},{"type":"simple","zh":"野营的时候，晚上可以看到满天星星。","pinyin":"Yěyíng de shíhou, wǎnshang kěyǐ kàndào mǎntiān xīngxing.","vi":"Khi cắm trại, buổi tối có thể ngắm cả bầu trời sao."},{"type":"compound","zh":"因为营地不让生火，所以野营只能吃干粮。","pinyin":"Yīnwèi yíngdì bú ràng shēnghuǒ, suǒyǐ yěyíng zhǐnéng chī gānliang.","vi":"Vì khu trại không cho nhóm lửa nên khi cắm trại chỉ ăn lương khô được."}],"related":[{"hanzi":"露营","pinyin":"lùyíng","vi":"cắm trại"},{"hanzi":"帐篷","pinyin":"zhàngpeng","vi":"cái lều"},{"hanzi":"野炊","pinyin":"yěchuī","vi":"nấu ăn ngoài trời"},{"hanzi":"营地","pinyin":"yíngdì","vi":"khu trại"}],"traditional":"野營"},{"id":"业","hanzi":"业","pinyin":"yè","meaning_vi":"nghề nghiệp, ngành nghề, sự nghiệp","explanation":"业 (nghiệp – nghề, việc) → nghề nghiệp, ngành; thường làm thành tố như 行业, 毕业, 业余.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他以修车为业。","pinyin":"Tā yǐ xiūchē wéi yè.","vi":"Anh ấy lấy nghề sửa xe làm kế sinh nhai."},{"type":"simple","zh":"他大学毕业后一直在银行业工作。","pinyin":"Tā dàxué bìyè hòu yìzhí zài yínhángyè gōngzuò.","vi":"Sau khi tốt nghiệp đại học, anh ấy luôn làm trong ngành ngân hàng."},{"type":"compound","zh":"只有安居乐业，人们才会对未来有信心。","pinyin":"Zhǐyǒu ānjūlèyè, rénmen cái huì duì wèilái yǒu xìnxīn.","vi":"Chỉ khi an cư lạc nghiệp, người ta mới có niềm tin vào tương lai."}],"related":[{"hanzi":"职业","pinyin":"zhíyè","vi":"nghề nghiệp"},{"hanzi":"行业","pinyin":"hángyè","vi":"ngành nghề"},{"hanzi":"事业","pinyin":"shìyè","vi":"sự nghiệp"},{"hanzi":"就业","pinyin":"jiùyè","vi":"việc làm"}],"traditional":"業"},{"id":"夜班","hanzi":"夜班","pinyin":"yèbān","meaning_vi":"ca đêm","explanation":"夜 (dạ – đêm) + 班 (ban – ca làm việc) → ca làm việc ban đêm.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🌙","examples":[{"type":"basic","zh":"她这周上夜班。","pinyin":"Tā zhè zhōu shàng yèbān.","vi":"Tuần này cô ấy làm ca đêm."},{"type":"simple","zh":"护士下了夜班就回家睡觉了。","pinyin":"Hùshi xiàle yèbān jiù huíjiā shuìjiào le.","vi":"Y tá tan ca đêm là về nhà ngủ luôn."},{"type":"compound","zh":"虽然夜班工资高一点，但是对身体不太好。","pinyin":"Suīrán yèbān gōngzī gāo yìdiǎn, dànshì duì shēntǐ bú tài hǎo.","vi":"Tuy ca đêm lương cao hơn chút nhưng không tốt cho sức khỏe."}],"related":[{"hanzi":"白班","pinyin":"báibān","vi":"ca ngày"},{"hanzi":"值班","pinyin":"zhíbān","vi":"trực ca"},{"hanzi":"加班","pinyin":"jiābān","vi":"tăng ca"},{"hanzi":"倒班","pinyin":"dǎobān","vi":"đổi ca"}]},{"id":"夜市","hanzi":"夜市","pinyin":"yèshì","meaning_vi":"chợ đêm","explanation":"夜 (dạ – đêm) + 市 (thị – chợ) → chợ họp vào buổi tối.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏮","examples":[{"type":"basic","zh":"我们去夜市吃小吃。","pinyin":"Wǒmen qù yèshì chī xiǎochī.","vi":"Chúng ta đi chợ đêm ăn quà vặt."},{"type":"simple","zh":"这条街的夜市一直开到凌晨两点。","pinyin":"Zhè tiáo jiē de yèshì yìzhí kāi dào língchén liǎng diǎn.","vi":"Chợ đêm phố này mở đến tận hai giờ sáng."},{"type":"compound","zh":"每当天黑以后，夜市就变得特别热闹。","pinyin":"Měidāng tiānhēi yǐhòu, yèshì jiù biànde tèbié rènao.","vi":"Mỗi khi trời tối, chợ đêm lại trở nên vô cùng náo nhiệt."}],"related":[{"hanzi":"小吃","pinyin":"xiǎochī","vi":"món ăn vặt"},{"hanzi":"地摊","pinyin":"dìtān","vi":"sạp hàng vỉa hè"},{"hanzi":"集市","pinyin":"jíshì","vi":"phiên chợ"},{"hanzi":"夜生活","pinyin":"yèshēnghuó","vi":"cuộc sống về đêm"}]},{"id":"夜晚","hanzi":"夜晚","pinyin":"yèwǎn","meaning_vi":"đêm, ban đêm","explanation":"夜 (dạ – đêm) + 晚 (vãn – tối) → khoảng thời gian ban đêm.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌃","examples":[{"type":"basic","zh":"夜晚的城市很美。","pinyin":"Yèwǎn de chéngshì hěn měi.","vi":"Thành phố về đêm rất đẹp."},{"type":"simple","zh":"沙漠的夜晚比白天冷得多。","pinyin":"Shāmò de yèwǎn bǐ bái tiānlěng de duō.","vi":"Đêm ở sa mạc lạnh hơn ban ngày nhiều."},{"type":"compound","zh":"每到夜晚，他就一个人坐在窗前想家。","pinyin":"Měi dào yèwǎn, tā jiù yígèrén zuò zài chuāng qián xiǎngjiā.","vi":"Cứ đến đêm, anh ấy lại ngồi một mình bên cửa sổ nhớ nhà."}],"related":[{"hanzi":"晚上","pinyin":"wǎnshang","vi":"buổi tối"},{"hanzi":"深夜","pinyin":"shēnyè","vi":"đêm khuya"},{"hanzi":"白天","pinyin":"báitiān","vi":"ban ngày"},{"hanzi":"夜里","pinyin":"yèli","vi":"trong đêm"}]},{"id":"夜校","hanzi":"夜校","pinyin":"yèxiào","meaning_vi":"trường học buổi tối, lớp học ban đêm","explanation":"夜 (dạ – đêm) + 校 (hiệu – trường) → trường mở lớp vào buổi tối cho người đi làm.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"他晚上去夜校学英语。","pinyin":"Tā wǎnshang qù yèxiào xué Yīngyǔ.","vi":"Buổi tối anh ấy đi học tiếng Anh ở lớp đêm."},{"type":"simple","zh":"很多工人通过上夜校拿到了文凭。","pinyin":"Hěn duō gōngrén tōngguò shàng yèxiào nádàole wénpíng.","vi":"Nhiều công nhân lấy được bằng nhờ học trường buổi tối."},{"type":"compound","zh":"虽然白天上班很累，但是她坚持每晚去夜校。","pinyin":"Suīrán báitiān shàngbān hěn lèi, dànshì tā jiānchí měi wǎn qù yèxiào.","vi":"Tuy ban ngày đi làm rất mệt nhưng cô ấy vẫn kiên trì tối nào cũng đi học đêm."}],"related":[{"hanzi":"补习班","pinyin":"bǔxíbān","vi":"lớp học thêm"},{"hanzi":"培训","pinyin":"péixùn","vi":"đào tạo"},{"hanzi":"进修","pinyin":"jìnxiū","vi":"học nâng cao"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"trường học"}]},{"id":"夜以继日","hanzi":"夜以继日","pinyin":"yèyǐ-jìrì","meaning_vi":"ngày đêm không nghỉ, làm suốt ngày đêm","explanation":"夜 (dạ – đêm) + 以 (dĩ – lấy) + 继 (kế – nối) + 日 (nhật – ngày) → lấy đêm nối ngày; chỉ làm việc liên tục ngày đêm.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"⏰","examples":[{"type":"basic","zh":"工人们夜以继日地施工。","pinyin":"Gōngrénmen yèyǐjìrì de shīgōng.","vi":"Công nhân thi công ngày đêm không nghỉ."},{"type":"simple","zh":"为了赶论文，他夜以继日地查资料。","pinyin":"Wèile gǎn lùnwén, tā yèyǐjìrì de chá zīliào.","vi":"Để kịp luận văn, anh ấy tra tài liệu ngày đêm."},{"type":"compound","zh":"因为医生们夜以继日地抢救，所以病人终于脱离了危险。","pinyin":"Yīnwèi yīshēngmen yèyǐjìrì de qiǎngjiù, suǒyǐ bìngrén zhōngyú tuōlíle wēixiǎn.","vi":"Vì các bác sĩ cấp cứu ngày đêm nên bệnh nhân cuối cùng đã qua cơn nguy hiểm."}],"related":[{"hanzi":"日以继夜","pinyin":"rìyǐjìyè","vi":"ngày nối đêm"},{"hanzi":"废寝忘食","pinyin":"fèiqǐnwàngshí","vi":"quên ăn quên ngủ"},{"hanzi":"通宵","pinyin":"tōngxiāo","vi":"suốt đêm"},{"hanzi":"连夜","pinyin":"liányè","vi":"ngay trong đêm"}],"traditional":"夜以繼日"},{"id":"夜总会","hanzi":"夜总会","pinyin":"yèzǒnghuì","meaning_vi":"hộp đêm, câu lạc bộ đêm","explanation":"夜 (dạ – đêm) + 总会 (tổng hội – câu lạc bộ) → câu lạc bộ giải trí hoạt động về đêm.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🪩","examples":[{"type":"basic","zh":"这家夜总会很有名。","pinyin":"Zhè jiā yèzǒnghuì hěn yǒumíng.","vi":"Hộp đêm này rất nổi tiếng."},{"type":"simple","zh":"他年轻时在夜总会当过歌手。","pinyin":"Tā niánqīng shí zài yèzǒnghuì dāngguò gēshǒu.","vi":"Hồi trẻ anh ấy từng làm ca sĩ ở hộp đêm."},{"type":"compound","zh":"因为夜总会太吵，所以附近居民常常投诉。","pinyin":"Yīnwèi yèzǒnghuì tài chǎo, suǒyǐ fùjìn jūmín chángcháng tóusù.","vi":"Vì hộp đêm quá ồn nên cư dân gần đó thường xuyên khiếu nại."}],"related":[{"hanzi":"酒吧","pinyin":"jiǔbā","vi":"quán bar"},{"hanzi":"舞厅","pinyin":"wǔtīng","vi":"vũ trường"},{"hanzi":"夜生活","pinyin":"yèshēnghuó","vi":"cuộc sống về đêm"},{"hanzi":"娱乐场所","pinyin":"yúlèchǎngsuǒ","vi":"nơi giải trí"}],"traditional":"夜總會"},{"id":"液晶","hanzi":"液晶","pinyin":"yèjīng","meaning_vi":"tinh thể lỏng (LCD)","explanation":"液 (dịch – chất lỏng) + 晶 (tinh – tinh thể) → tinh thể lỏng, dùng làm màn hình như 液晶电视.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📺","examples":[{"type":"basic","zh":"我买了台液晶电视。","pinyin":"Wǒ mǎile tái yèjīng diànshì.","vi":"Tôi đã mua một chiếc tivi LCD."},{"type":"simple","zh":"这块液晶屏幕摔坏了，得换新的。","pinyin":"Zhè kuài yèjīng píngmù shuāi huàile, děi huànxīn de.","vi":"Màn hình LCD này bị rơi vỡ, phải thay cái mới."},{"type":"compound","zh":"虽然液晶显示器很轻薄，但是屏幕很怕压。","pinyin":"Suīrán yèjīng xiǎnshìqì hěn qīngbáo, dànshì píngmù hěn pà yā.","vi":"Tuy màn hình LCD rất mỏng nhẹ nhưng lại rất sợ bị đè."}],"related":[{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"},{"hanzi":"显示器","pinyin":"xiǎnshìqì","vi":"màn hình máy tính"},{"hanzi":"晶体","pinyin":"jīngtǐ","vi":"tinh thể"},{"hanzi":"液体","pinyin":"yètǐ","vi":"chất lỏng"}]},{"id":"一把手","hanzi":"一把手","pinyin":"yìbǎshǒu","meaning_vi":"người đứng đầu, thủ trưởng; tay giỏi","explanation":"一 (nhất – số một) + 把手 (bả thủ – tay cầm) → người nắm quyền số một trong một đơn vị; cũng chỉ người giỏi việc.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他是厂里的一把手。","pinyin":"Tā shì chǎng lǐ de yìbǎshǒu.","vi":"Ông ấy là người đứng đầu nhà máy."},{"type":"simple","zh":"这件事得由一把手亲自拍板。","pinyin":"Zhè jiàn shì děi yóu yìbǎshǒu qīnzì pāibǎn.","vi":"Việc này phải do thủ trưởng đích thân quyết định."},{"type":"compound","zh":"虽然他刚当上一把手，但是已经做出了不少改革。","pinyin":"Suīrán tā gāng dāngshàng yìbǎshǒu, dànshì yǐjīng zuòchūle bùshǎo gǎigé.","vi":"Tuy mới lên làm người đứng đầu nhưng ông ấy đã thực hiện khá nhiều cải cách."}],"related":[{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"},{"hanzi":"负责人","pinyin":"fùzérén","vi":"người phụ trách"},{"hanzi":"老板","pinyin":"lǎobǎn","vi":"ông chủ"},{"hanzi":"一手","pinyin":"yìshǒu","vi":"tay nghề"}]},{"id":"一不小心","hanzi":"一不小心","pinyin":"yíbùxiǎoxīn","meaning_vi":"lỡ sơ ý, vô tình, không cẩn thận một chút","explanation":"一 (nhất – một chút) + 不小心 (bất tiểu tâm – không cẩn thận) → chỉ hơi lơ là một chút là xảy ra chuyện.","hsk_level":"7-9","tags":["pho-tu"],"image":"😬","examples":[{"type":"basic","zh":"我一不小心摔倒了。","pinyin":"Wǒ yíbùxiǎoxīn shuāidǎo le.","vi":"Tôi lỡ sơ ý bị ngã."},{"type":"simple","zh":"她一不小心把咖啡洒在了键盘上。","pinyin":"Tā yíbùxiǎoxīn bǎ kāfēi sǎ zài le jiànpán shàng.","vi":"Cô ấy lỡ tay làm đổ cà phê lên bàn phím."},{"type":"compound","zh":"这条山路很窄，一不小心就会掉下去。","pinyin":"Zhè tiáo shānlù hěn zhǎi, yíbùxiǎoxīn jiù huì diào xiàqù.","vi":"Đường núi này rất hẹp, sơ ý một chút là rơi xuống ngay."}],"related":[{"hanzi":"不小心","pinyin":"bùxiǎoxīn","vi":"không cẩn thận"},{"hanzi":"粗心","pinyin":"cūxīn","vi":"cẩu thả"},{"hanzi":"一时疏忽","pinyin":"yìshíshūhu","vi":"nhất thời sơ suất"},{"hanzi":"小心","pinyin":"xiǎoxīn","vi":"cẩn thận"}]},{"id":"一成不变","hanzi":"一成不变","pinyin":"yìchéng-búbiàn","meaning_vi":"bất di bất dịch, không hề thay đổi","explanation":"一 (nhất – một khi) + 成 (thành – hình thành) + 不变 (bất biến) → một khi đã thành thì không đổi; chỉ sự cứng nhắc, cố định.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🗿","examples":[{"type":"basic","zh":"规定不是一成不变的。","pinyin":"Guīdìng bú shì yìchéngbúbiàn de.","vi":"Quy định không phải là bất di bất dịch."},{"type":"simple","zh":"他的生活一成不变，每天都一样。","pinyin":"Tā de shēnghuó yìchéngbúbiàn, měitiān dōu yíyàng.","vi":"Cuộc sống của anh ấy chẳng thay đổi gì, ngày nào cũng như nhau."},{"type":"compound","zh":"市场变化很快，如果方法一成不变，就会被淘汰。","pinyin":"Shìchǎng biànhuà hěn kuài, rúguǒ fāngfǎ yìchéngbúbiàn, jiù huì bèi táotài.","vi":"Thị trường thay đổi nhanh, nếu phương pháp cứ giữ nguyên thì sẽ bị đào thải."}],"related":[{"hanzi":"千变万化","pinyin":"qiānbiànwànhuà","vi":"thiên biến vạn hóa"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư lối cũ"},{"hanzi":"固定","pinyin":"gùdìng","vi":"cố định"},{"hanzi":"不变","pinyin":"búbiàn","vi":"không đổi"}],"traditional":"一成不變"},{"id":"一筹莫展","hanzi":"一筹莫展","pinyin":"yìchóu-mòzhǎn","meaning_vi":"bó tay, hết cách, không tìm ra kế gì","explanation":"一 (nhất – một) + 筹 (trù – kế sách) + 莫 (mạc – không) + 展 (triển – thi triển) → không thi triển được một kế nào; chỉ hoàn toàn bế tắc.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"大家都一筹莫展。","pinyin":"Dàjiā dōu yìchóumòzhǎn.","vi":"Mọi người đều bó tay."},{"type":"simple","zh":"面对这个难题，专家们也一筹莫展。","pinyin":"Miànduì zhè gè nántí, zhuānjiāmen yě yìchóumòzhǎn.","vi":"Trước bài toán khó này, các chuyên gia cũng bó tay."},{"type":"compound","zh":"正当我一筹莫展的时候，老朋友突然打来电话帮了我。","pinyin":"Zhèngdāng wǒ yìchóumòzhǎn de shíhou, lǎopéngyou tūrán dǎ lái diànhuà bāngle wǒ.","vi":"Đúng lúc tôi hết cách thì bạn cũ bất ngờ gọi điện giúp tôi."}],"related":[{"hanzi":"束手无策","pinyin":"shùshǒuwúcè","vi":"bó tay hết cách"},{"hanzi":"无计可施","pinyin":"wújìkěshī","vi":"không còn kế gì"},{"hanzi":"想方设法","pinyin":"xiǎngfāngshèfǎ","vi":"tìm mọi cách"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"cách làm"}],"traditional":"一籌莫展"},{"id":"一大早","hanzi":"一大早","pinyin":"yídàzǎo","meaning_vi":"sáng sớm tinh mơ, từ sáng sớm","explanation":"一 (nhất) + 大早 (đại tảo – rất sớm) → ngay từ lúc sáng sớm.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌅","examples":[{"type":"basic","zh":"他一大早就出门了。","pinyin":"Tā yídàzǎo jiù chūmén le.","vi":"Anh ấy ra khỏi nhà từ sáng sớm."},{"type":"simple","zh":"一大早，菜市场就挤满了人。","pinyin":"Yídàzǎo, càishìchǎng jiù jǐmǎnle rén.","vi":"Mới sáng sớm, chợ đã chật kín người."},{"type":"compound","zh":"因为要赶第一班飞机，所以我们一大早就起床了。","pinyin":"Yīnwèi yào gǎn dìyī bān fēijī, suǒyǐ wǒmen yídàzǎo jiù qǐchuáng le.","vi":"Vì phải kịp chuyến bay đầu tiên nên chúng tôi dậy từ sáng sớm."}],"related":[{"hanzi":"一早","pinyin":"yìzǎo","vi":"sáng sớm"},{"hanzi":"清早","pinyin":"qīngzǎo","vi":"sáng tinh mơ"},{"hanzi":"大清早","pinyin":"dàqīngzǎo","vi":"sớm tinh mơ"},{"hanzi":"早晨","pinyin":"zǎochen","vi":"buổi sáng"}]},{"id":"一动不动","hanzi":"一动不动","pinyin":"yídòng-budòng","meaning_vi":"bất động, không nhúc nhích","explanation":"一 (nhất – một chút) + 动 (động) + 不动 (bất động) → không động đậy chút nào.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧍","examples":[{"type":"basic","zh":"猫一动不动地盯着鱼缸。","pinyin":"Māo yídòngbudòng de dīngzhe yúgāng.","vi":"Con mèo nhìn chằm chằm bể cá không nhúc nhích."},{"type":"simple","zh":"士兵在烈日下一动不动地站着。","pinyin":"Shìbīng zài lièrì xià yídòngbudòng de zhàn zhe.","vi":"Người lính đứng bất động dưới nắng gắt."},{"type":"compound","zh":"虽然蚊子在咬他，但是他还是一动不动地趴着。","pinyin":"Suīrán wénzi zài yǎo tā, dànshì tā háishì yídòngbudòng de pā zhe.","vi":"Tuy muỗi đang đốt nhưng anh ấy vẫn nằm sấp bất động."}],"related":[{"hanzi":"纹丝不动","pinyin":"wénsībúdòng","vi":"không suy suyển"},{"hanzi":"静止","pinyin":"jìngzhǐ","vi":"tĩnh lặng"},{"hanzi":"动弹","pinyin":"dòngtan","vi":"cựa quậy"},{"hanzi":"一声不吭","pinyin":"yìshēngbùkēng","vi":"im thin thít"}],"traditional":"一動不動"},{"id":"一度","hanzi":"一度","pinyin":"yídù","meaning_vi":"từng có lúc, có một thời; một lần","explanation":"一 (nhất – một) + 度 (độ – lần) → một lần, một thời gian trong quá khứ.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"🔙","examples":[{"type":"basic","zh":"他一度想放弃。","pinyin":"Tā yídù xiǎng fàngqì.","vi":"Anh ấy từng có lúc muốn bỏ cuộc."},{"type":"simple","zh":"这首歌一度在网上非常流行。","pinyin":"Zhè shǒu gē yídù zài wǎngshàng fēicháng liúxíng.","vi":"Bài hát này từng có thời rất thịnh hành trên mạng."},{"type":"compound","zh":"虽然公司一度面临破产，但是后来又重新站了起来。","pinyin":"Suīrán gōngsī yídù miànlín pòchǎn, dànshì hòulái yòu chóngxīn zhànle qǐlái.","vi":"Tuy công ty từng đứng trước nguy cơ phá sản nhưng sau đó lại vực dậy."}],"related":[{"hanzi":"曾经","pinyin":"céngjīng","vi":"đã từng"},{"hanzi":"一时","pinyin":"yìshí","vi":"nhất thời"},{"hanzi":"年度","pinyin":"niándù","vi":"năm (tài chính)"},{"hanzi":"一阵","pinyin":"yízhèn","vi":"một hồi"}]},{"id":"一概","hanzi":"一概","pinyin":"yígài","meaning_vi":"tất cả, nhất loạt, hoàn toàn (không ngoại lệ)","explanation":"一 (nhất – đồng loạt) + 概 (khái – đại khái, toàn bộ) → toàn bộ không trừ cái nào; thường đi với phủ định: 一概不…","hsk_level":"7-9","tags":["pho-tu"],"image":"🚫","examples":[{"type":"basic","zh":"过期商品一概不退。","pinyin":"Guòqī shāngpǐn yígài bú tuì.","vi":"Hàng hết hạn nhất loạt không đổi trả."},{"type":"simple","zh":"他对外面的传言一概不理。","pinyin":"Tā duì wàimiàn de chuányán yígài bùlǐ.","vi":"Anh ấy hoàn toàn mặc kệ những lời đồn bên ngoài."},{"type":"compound","zh":"只要是与工作无关的电话，他一概不接。","pinyin":"Zhǐ yàoshì yǔ gōngzuò wúguān de diànhuà, tā yígài bù jiē.","vi":"Hễ là cuộc gọi không liên quan đến công việc, anh ấy nhất loạt không nghe."}],"related":[{"hanzi":"一律","pinyin":"yílǜ","vi":"nhất luật"},{"hanzi":"全部","pinyin":"quánbù","vi":"toàn bộ"},{"hanzi":"一概而论","pinyin":"yígài'érlùn","vi":"vơ đũa cả nắm"},{"hanzi":"统统","pinyin":"tǒngtǒng","vi":"tất cả"}]},{"id":"一概而论","hanzi":"一概而论","pinyin":"yígài-érlùn","meaning_vi":"vơ đũa cả nắm, đánh đồng mọi thứ","explanation":"一概 (nhất khái – tất cả như nhau) + 而论 (nhi luận – mà bàn) → bàn mọi việc theo cùng một kiểu; thường dùng ở dạng phủ định 不能一概而论.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"这事不能一概而论。","pinyin":"Zhè shì bù néng yígài'érlùn.","vi":"Chuyện này không thể vơ đũa cả nắm."},{"type":"simple","zh":"每个孩子情况不同，不可一概而论。","pinyin":"Měi gè háizi qíngkuàng bùtóng, bùkě yígài'érlùn.","vi":"Mỗi đứa trẻ một hoàn cảnh, không thể đánh đồng."},{"type":"compound","zh":"虽然有些网店卖假货，但是也不能一概而论。","pinyin":"Suīrán yǒuxiē wǎngdiàn mài jiǎhuò, dànshì yě bù néng yígài'érlùn.","vi":"Tuy có một số cửa hàng online bán hàng giả nhưng cũng không thể vơ đũa cả nắm."}],"related":[{"hanzi":"以偏概全","pinyin":"yǐpiāngàiquán","vi":"lấy bộ phận suy ra toàn thể"},{"hanzi":"具体问题具体分析","pinyin":"jùtǐ wèntí jùtǐ fēnxī","vi":"việc nào xét việc nấy"},{"hanzi":"一概","pinyin":"yígài","vi":"nhất loạt"},{"hanzi":"相提并论","pinyin":"xiāngtíbìnglùn","vi":"đánh đồng"}],"traditional":"一概而論"},{"id":"一干二净","hanzi":"一干二净","pinyin":"yìgān-èrjìng","meaning_vi":"sạch sành sanh, sạch trơn, hoàn toàn","explanation":"一 (nhất) + 干 (can – khô, sạch) + 二 (nhị) + 净 (tịnh – sạch) → sạch trơn không còn gì; thường nói quên sạch, ăn sạch.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧹","examples":[{"type":"basic","zh":"我把这事忘得一干二净。","pinyin":"Wǒ bǎ zhè shì wàng de yìgān'èrjìng.","vi":"Tôi quên sạch sành sanh chuyện này."},{"type":"simple","zh":"孩子们把一桌菜吃得一干二净。","pinyin":"Háizimen bǎ yì zhuō cài chī de yìgān'èrjìng.","vi":"Bọn trẻ ăn sạch trơn cả mâm thức ăn."},{"type":"compound","zh":"虽然他借了我的钱，但是早就忘得一干二净了。","pinyin":"Suīrán tā jièle wǒ de qián, dànshì zǎojiù wàng de yìgān'èrjìng le.","vi":"Tuy anh ta vay tiền tôi nhưng đã quên sạch từ lâu rồi."}],"related":[{"hanzi":"干干净净","pinyin":"gāngānjìngjìng","vi":"sạch sẽ"},{"hanzi":"精光","pinyin":"jīngguāng","vi":"sạch trơn"},{"hanzi":"彻底","pinyin":"chèdǐ","vi":"triệt để"},{"hanzi":"干净","pinyin":"gānjìng","vi":"sạch"}],"traditional":"一乾二淨"},{"id":"一个劲儿","hanzi":"一个劲儿","pinyin":"yígejìnr","meaning_vi":"cứ một mực, liên tục, không ngừng","explanation":"一个 (một) + 劲儿 (kình – sức lực) → dồn một sức không ngừng; chỉ hành động lặp đi lặp lại liên tục.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"他一个劲儿地道歉。","pinyin":"Tā yígejìnr de dàoqiàn.","vi":"Anh ấy cứ xin lỗi mãi."},{"type":"simple","zh":"孩子一个劲儿地哭，谁也哄不好。","pinyin":"Háizi yígejìnr de kū, shéi yě hǒng bù hǎo.","vi":"Đứa bé cứ khóc mãi, không ai dỗ được."},{"type":"compound","zh":"虽然我说不饿，但是奶奶还是一个劲儿地给我夹菜。","pinyin":"Suīrán wǒ shuō bú è, dànshì nǎinai háishì yígejìnr de gěi wǒ jiā cài.","vi":"Tuy tôi nói không đói nhưng bà vẫn cứ gắp thức ăn cho tôi mãi."}],"related":[{"hanzi":"不停","pinyin":"bùtíng","vi":"không ngừng"},{"hanzi":"一直","pinyin":"yìzhí","vi":"luôn luôn"},{"hanzi":"连连","pinyin":"liánlián","vi":"liên tục"},{"hanzi":"一味","pinyin":"yíwèi","vi":"một mực"}],"traditional":"一個勁兒"},{"id":"一鼓作气","hanzi":"一鼓作气","pinyin":"yìgǔ-zuòqì","meaning_vi":"một mạch, dốc sức làm liền một hơi","explanation":"一 (nhất) + 鼓 (cổ – hồi trống) + 作气 (tác khí – lên tinh thần) → hồi trống đầu tiên làm binh sĩ hăng hái nhất (theo 《左传》); chỉ thừa lúc hăng hái làm một mạch đến xong.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🥁","examples":[{"type":"basic","zh":"我们一鼓作气爬到了山顶。","pinyin":"Wǒmen yìgǔzuòqì pá dàole shāndǐng.","vi":"Chúng tôi leo một mạch lên đỉnh núi."},{"type":"simple","zh":"他一鼓作气写完了整篇报告。","pinyin":"Tā yìgǔzuòqì xiě wánle zhěng piān bàogào.","vi":"Anh ấy viết một mạch xong cả bản báo cáo."},{"type":"compound","zh":"既然已经开了头，我们就一鼓作气把它干完吧。","pinyin":"Jìrán yǐjīng kāile tóu, wǒmen jiù yìgǔzuòqì bǎ tā gàn wán ba.","vi":"Đã bắt đầu rồi thì chúng ta làm một mạch cho xong luôn đi."}],"related":[{"hanzi":"一口气","pinyin":"yìkǒuqì","vi":"một hơi"},{"hanzi":"趁热打铁","pinyin":"chènrèdǎtiě","vi":"rèn sắt khi còn nóng"},{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở giữa chừng"},{"hanzi":"士气","pinyin":"shìqì","vi":"sĩ khí"}],"traditional":"一鼓作氣"},{"id":"一锅粥","hanzi":"一锅粥","pinyin":"yìguōzhōu","meaning_vi":"hỗn loạn, rối tinh rối mù","explanation":"一 (nhất) + 锅 (oa – nồi) + 粥 (chúc – cháo) → nghĩa đen là một nồi cháo; nghĩa bóng chỉ tình trạng lộn xộn, rối như canh hẹ.","hsk_level":"7-9","tags":["danh-tu"],"image":"🍲","examples":[{"type":"basic","zh":"会场乱成了一锅粥。","pinyin":"Huìchǎng luàn chéngle yìguōzhōu.","vi":"Hội trường loạn hết cả lên."},{"type":"simple","zh":"经理一走，办公室就乱成一锅粥。","pinyin":"Jīnglǐ yì zǒu, bàngōngshì jiù luàn chéng yìguōzhōu.","vi":"Giám đốc vừa đi, văn phòng đã rối tinh rối mù."},{"type":"compound","zh":"如果没有人统一指挥，现场就会乱成一锅粥。","pinyin":"Rúguǒ méiyǒu rén tǒngyī zhǐhuī, xiànchǎng jiù huì luàn chéng yìguōzhōu.","vi":"Nếu không có người chỉ huy thống nhất, hiện trường sẽ hỗn loạn."}],"related":[{"hanzi":"乱七八糟","pinyin":"luànqībāzāo","vi":"lộn xộn"},{"hanzi":"一团糟","pinyin":"yìtuánzāo","vi":"rối như tơ vò"},{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"},{"hanzi":"一塌糊涂","pinyin":"yìtāhútú","vi":"bết bát"}],"traditional":"一鍋粥"},{"id":"一晃","hanzi":"一晃","pinyin":"yìhuǎng","meaning_vi":"thoáng chốc, chớp mắt (thời gian trôi nhanh)","explanation":"一 (nhất – một cái) + 晃 (hoảng – lướt qua, lóe) → lướt qua trong chớp mắt; thường nói thời gian trôi rất nhanh.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"💨","examples":[{"type":"basic","zh":"一晃十年过去了。","pinyin":"Yìhuǎng shí nián guòqù le.","vi":"Thoáng chốc mười năm đã trôi qua."},{"type":"simple","zh":"一晃孩子都上大学了。","pinyin":"Yìhuǎng háizi dōu shàng dàxué le.","vi":"Chớp mắt con đã vào đại học rồi."},{"type":"compound","zh":"虽然毕业好像是昨天的事，但是一晃已经二十年了。","pinyin":"Suīrán bìyè hǎoxiàng shì zuótiān de shì, dànshì yìhuǎng yǐjīng èrshí nián le.","vi":"Tuy tốt nghiệp tưởng như mới hôm qua nhưng thoáng cái đã hai mươi năm."}],"related":[{"hanzi":"转眼","pinyin":"zhuǎnyǎn","vi":"chớp mắt"},{"hanzi":"一转眼","pinyin":"yìzhuǎnyǎn","vi":"trong nháy mắt"},{"hanzi":"一眨眼","pinyin":"yìzhǎyǎn","vi":"chớp mắt"},{"hanzi":"光阴似箭","pinyin":"guāngyīnsìjiàn","vi":"thời gian thấm thoắt"}]},{"id":"一回事","hanzi":"一回事","pinyin":"yìhuíshì","meaning_vi":"một chuyện, cùng một chuyện","explanation":"一 (nhất – một) + 回 (hồi – lượt) + 事 (sự – việc) → một việc; 两回事 là hai việc khác nhau, 当一回事 là coi trọng.","hsk_level":"7-9","tags":["danh-tu"],"image":"🟰","examples":[{"type":"basic","zh":"这完全是一回事。","pinyin":"Zhè wánquán shì yìhuíshì.","vi":"Đây hoàn toàn là cùng một chuyện."},{"type":"simple","zh":"他根本没把我的话当一回事。","pinyin":"Tā gēnběn méi bǎ wǒ dehuà dàng yìhuíshì.","vi":"Anh ta hoàn toàn không coi lời tôi ra gì."},{"type":"compound","zh":"知道是一回事，做到又是另一回事。","pinyin":"Zhīdào shì yìhuíshì, zuòdào yòu shì lìngyì huíshì.","vi":"Biết là một chuyện, làm được lại là chuyện khác."}],"related":[{"hanzi":"两回事","pinyin":"liǎnghuíshì","vi":"hai chuyện khác nhau"},{"hanzi":"怎么回事","pinyin":"zěnmehuíshì","vi":"chuyện gì vậy"},{"hanzi":"同一","pinyin":"tóngyī","vi":"cùng một"},{"hanzi":"当回事","pinyin":"dànghuíshì","vi":"coi trọng"}]},{"id":"一技之长","hanzi":"一技之长","pinyin":"yíjì-zhīcháng","meaning_vi":"một nghề sở trường, có một tay nghề giỏi","explanation":"一 (nhất – một) + 技 (kỹ – kỹ năng) + 之 (chi – của) + 长 (trường – sở trường) → có một kỹ năng sở trường để sống.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"人总要有一技之长。","pinyin":"Rén zǒng yàoyǒu yíjìzhīcháng.","vi":"Con người luôn cần có một nghề sở trường."},{"type":"simple","zh":"他靠一技之长在城里站稳了脚。","pinyin":"Tā kào yíjìzhīcháng zài chénglǐ zhànwěnle jiǎo.","vi":"Anh ấy nhờ có tay nghề mà đứng vững được ở thành phố."},{"type":"compound","zh":"只要有一技之长，就不怕找不到工作。","pinyin":"Zhǐyào yǒu yíjìzhīcháng, jiù bú pà zhǎobúdào gōngzuò.","vi":"Chỉ cần có một nghề giỏi thì không sợ không tìm được việc."}],"related":[{"hanzi":"特长","pinyin":"tècháng","vi":"sở trường"},{"hanzi":"手艺","pinyin":"shǒuyì","vi":"tay nghề"},{"hanzi":"专长","pinyin":"zhuāncháng","vi":"chuyên môn"},{"hanzi":"技能","pinyin":"jìnéng","vi":"kỹ năng"}],"traditional":"一技之長"},{"id":"一家人","hanzi":"一家人","pinyin":"yìjiārén","meaning_vi":"người một nhà, cả gia đình","explanation":"一 (nhất – một) + 家 (gia – nhà) + 人 (nhân – người) → những người cùng một nhà; cũng dùng chỉ quan hệ thân thiết.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🏠","examples":[{"type":"basic","zh":"我们一家人去旅游。","pinyin":"Wǒmen yìjiārén qù lǚyóu.","vi":"Cả nhà chúng tôi đi du lịch."},{"type":"simple","zh":"别客气，大家都是一家人。","pinyin":"Biékèqi, dàjiā dōu shì yìjiārén.","vi":"Đừng khách sáo, mọi người đều là người một nhà."},{"type":"compound","zh":"虽然一家人住在不同城市，但是每年春节都会团聚。","pinyin":"Suīrán yìjiārén zhùzài bùtóng chéngshì, dànshì měinián Chūnjié dōuhuì tuánjù.","vi":"Tuy cả nhà sống ở các thành phố khác nhau nhưng Tết năm nào cũng đoàn tụ."}],"related":[{"hanzi":"家人","pinyin":"jiārén","vi":"người nhà"},{"hanzi":"全家","pinyin":"quánjiā","vi":"cả nhà"},{"hanzi":"家庭","pinyin":"jiātíng","vi":"gia đình"},{"hanzi":"亲人","pinyin":"qīnrén","vi":"người thân"}]},{"id":"一经","hanzi":"一经","pinyin":"yìjīng","meaning_vi":"một khi đã, hễ đã (qua)","explanation":"一 (nhất – một khi) + 经 (kinh – trải qua) → hễ đã trải qua (hành động nào) là có kết quả ngay; thường đi với 就/便.","hsk_level":"7-9","tags":["pho-tu"],"image":"☝️","examples":[{"type":"basic","zh":"商品一经售出，概不退换。","pinyin":"Shāngpǐn yìjīng shòu chū, gài bú tuìhuàn.","vi":"Hàng đã bán ra, miễn đổi trả."},{"type":"simple","zh":"这个消息一经公布，就引起了轰动。","pinyin":"Zhè gè xiāoxi yìjīng gōngbù, jiù yǐnqǐle hōngdòng.","vi":"Tin này vừa công bố đã gây chấn động."},{"type":"compound","zh":"作弊行为一经发现，就立即取消考试资格。","pinyin":"Zuòbì xíngwéi yìjīng fāxiàn, jiù lìjí qǔxiāo kǎoshì zīgé.","vi":"Hành vi gian lận một khi bị phát hiện sẽ lập tức bị hủy tư cách dự thi."}],"related":[{"hanzi":"一旦","pinyin":"yídàn","vi":"một khi"},{"hanzi":"经过","pinyin":"jīngguò","vi":"trải qua"},{"hanzi":"只要","pinyin":"zhǐyào","vi":"chỉ cần"},{"hanzi":"立即","pinyin":"lìjí","vi":"lập tức"}],"traditional":"一經"},{"id":"一举","hanzi":"一举","pinyin":"yìjǔ","meaning_vi":"một lần, một lượt (mà làm được), một hành động","explanation":"一 (nhất – một) + 举 (cử – hành động) → chỉ bằng một hành động mà đạt được kết quả; thường gặp trong 一举两得.","hsk_level":"7-9","tags":["pho-tu"],"image":"🎯","examples":[{"type":"basic","zh":"他们一举夺得冠军。","pinyin":"Tāmen yìjǔ duódé guànjūn.","vi":"Họ giành chức vô địch chỉ trong một lần."},{"type":"simple","zh":"这部电影让她一举成名。","pinyin":"Zhè bù diànyǐng ràng tā yìjǔchéngmíng.","vi":"Bộ phim này khiến cô ấy nổi tiếng ngay lập tức."},{"type":"compound","zh":"骑车上班既能锻炼身体，又能省钱，真是一举两得。","pinyin":"Qíchē shàngbān jì néng duànliàn shēntǐ, yòu néng shěngqián, zhēn shì yìjǔliǎngdé.","vi":"Đạp xe đi làm vừa rèn luyện sức khỏe vừa tiết kiệm tiền, đúng là một công đôi việc."}],"related":[{"hanzi":"一举两得","pinyin":"yìjǔliǎngdé","vi":"nhất cử lưỡng tiện"},{"hanzi":"一下子","pinyin":"yíxiàzi","vi":"ngay lập tức"},{"hanzi":"举动","pinyin":"jǔdòng","vi":"cử động, hành động"},{"hanzi":"一次","pinyin":"yícì","vi":"một lần"}],"traditional":"一舉"},{"id":"一卡通","hanzi":"一卡通","pinyin":"Yìkǎtōng","meaning_vi":"thẻ đa năng (thẻ giao thông/thẻ thông minh dùng chung)","explanation":"一 (nhất – một) + 卡 (thẻ) + 通 (thông – đi khắp) → một tấm thẻ dùng được nhiều nơi, như thẻ đi tàu xe, thẻ sinh viên.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"💳","examples":[{"type":"basic","zh":"我忘带一卡通了。","pinyin":"Wǒ wàng dài Yìkǎtōng le.","vi":"Tôi quên mang thẻ đa năng rồi."},{"type":"simple","zh":"用一卡通坐地铁和公交都很方便。","pinyin":"Yòng Yìkǎtōng zuò dìtiě hé gōngjiāo dōu hěn fāngbiàn.","vi":"Dùng thẻ đa năng đi tàu điện ngầm và xe buýt đều rất tiện."},{"type":"compound","zh":"如果一卡通里的钱不够，就要先去窗口充值。","pinyin":"Rúguǒ Yìkǎtōng lǐ de qián búgòu, jiùyào xiān qù chuāngkǒu chōngzhí.","vi":"Nếu tiền trong thẻ không đủ thì phải ra quầy nạp tiền trước."}],"related":[{"hanzi":"交通卡","pinyin":"jiāotōngkǎ","vi":"thẻ giao thông"},{"hanzi":"充值","pinyin":"chōngzhí","vi":"nạp tiền"},{"hanzi":"刷卡","pinyin":"shuākǎ","vi":"quẹt thẻ"},{"hanzi":"校园卡","pinyin":"xiàoyuánkǎ","vi":"thẻ sinh viên"}]},{"id":"一揽子","hanzi":"一揽子","pinyin":"yìlǎnzi","meaning_vi":"trọn gói, toàn bộ, bao trùm","explanation":"一 (nhất) + 揽 (lãm – ôm lấy, gom) + 子 → gom tất cả lại một lượt; thường dùng trong 一揽子计划 (gói kế hoạch tổng thể).","hsk_level":"7-9","tags":["tinh-tu"],"image":"📦","examples":[{"type":"basic","zh":"政府推出一揽子政策。","pinyin":"Zhèngfǔ tuīchū yìlǎnzi zhèngcè.","vi":"Chính phủ đưa ra một gói chính sách."},{"type":"simple","zh":"双方签订了一揽子合作协议。","pinyin":"Shuāngfāng qiāndìngle yìlǎnzi hézuò xiéyì.","vi":"Hai bên đã ký một thỏa thuận hợp tác trọn gói."},{"type":"compound","zh":"如果只解决一个问题不够，就需要一揽子方案。","pinyin":"Rúguǒ zhǐ jiějué yí gè wèntí búgòu, jiù xūyào yìlǎnzi fāng'àn.","vi":"Nếu chỉ giải quyết một vấn đề là không đủ thì cần một phương án tổng thể."}],"related":[{"hanzi":"全面","pinyin":"quánmiàn","vi":"toàn diện"},{"hanzi":"整体","pinyin":"zhěngtǐ","vi":"tổng thể"},{"hanzi":"配套","pinyin":"pèitào","vi":"đồng bộ"},{"hanzi":"包揽","pinyin":"bāolǎn","vi":"ôm đồm"}],"traditional":"一攬子"},{"id":"一连","hanzi":"一连","pinyin":"yìlián","meaning_vi":"liền, liên tiếp, liên tục","explanation":"一 (nhất) + 连 (liên – liền nhau) → liên tiếp không gián đoạn; thường đi với số lượng: 一连三天.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔗","examples":[{"type":"basic","zh":"一连下了三天雨。","pinyin":"Yìlián xiàle sān tiān yǔ.","vi":"Mưa liền ba ngày."},{"type":"simple","zh":"他一连打了五个电话都没人接。","pinyin":"Tā yìlián dǎle wǔ gè diànhuà dōu méi rén jiē.","vi":"Anh ấy gọi liền năm cuộc mà không ai nghe."},{"type":"compound","zh":"因为一连加了一周的班，所以他累得生病了。","pinyin":"Yīnwèi yìlián jiāle yìzhōu de bān, suǒyǐ tā lèi de shēngbìng le.","vi":"Vì tăng ca liền một tuần nên anh ấy mệt đến ốm."}],"related":[{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"接连","pinyin":"jiēlián","vi":"liên tiếp"},{"hanzi":"一连串","pinyin":"yìliánchuàn","vi":"hàng loạt"},{"hanzi":"连着","pinyin":"liánzhe","vi":"liền"}],"traditional":"一連"},{"id":"一连串","hanzi":"一连串","pinyin":"yìliánchuàn","meaning_vi":"một loạt, hàng loạt, chuỗi","explanation":"一 (nhất) + 连 (liên – nối) + 串 (xuyến – chuỗi) → một chuỗi nối tiếp nhau.","hsk_level":"7-9","tags":["tinh-tu"],"image":"⛓️","examples":[{"type":"basic","zh":"他问了一连串问题。","pinyin":"Tā wènle yìliánchuàn wèntí.","vi":"Anh ấy hỏi một loạt câu hỏi."},{"type":"simple","zh":"公司最近发生了一连串的怪事。","pinyin":"Gōngsī zuìjìn fāshēngle yìliánchuàn de guàishì.","vi":"Công ty gần đây xảy ra hàng loạt chuyện lạ."},{"type":"compound","zh":"虽然遇到了一连串的挫折，但是她从没想过放弃。","pinyin":"Suīrán yùdàole yìliánchuàn de cuòzhé, dànshì tā cóng méi xiǎngguò fàngqì.","vi":"Tuy gặp hàng loạt thất bại nhưng cô ấy chưa từng nghĩ đến bỏ cuộc."}],"related":[{"hanzi":"一系列","pinyin":"yíxìliè","vi":"một loạt"},{"hanzi":"一连","pinyin":"yìlián","vi":"liên tiếp"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"},{"hanzi":"串","pinyin":"chuàn","vi":"chuỗi"}],"traditional":"一連串"},{"id":"一毛不拔","hanzi":"一毛不拔","pinyin":"yìmáo-bùbá","meaning_vi":"keo kiệt, vắt cổ chày ra nước","explanation":"一 (nhất) + 毛 (mao – sợi lông) + 不拔 (bất bạt – không nhổ) → một sợi lông cũng không chịu nhổ (gốc từ lời Mạnh Tử chê Dương Chu); chỉ người cực kỳ keo kiệt.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🪙","examples":[{"type":"basic","zh":"他是个一毛不拔的人。","pinyin":"Tā shì gè yìmáobùbá de rén.","vi":"Anh ta là người keo kiệt."},{"type":"simple","zh":"朋友有困难，他却一毛不拔。","pinyin":"Péngyou yǒu kùnnan, tā què yìmáobùbá.","vi":"Bạn bè gặp khó khăn, vậy mà anh ta chẳng bỏ ra đồng nào."},{"type":"compound","zh":"虽然他很有钱，但是对别人一毛不拔。","pinyin":"Suīrán tā hěn yǒuqián, dànshì duì biérén yìmáobùbá.","vi":"Tuy rất giàu nhưng ông ta keo kiệt với người khác."}],"related":[{"hanzi":"吝啬","pinyin":"lìnsè","vi":"keo kiệt"},{"hanzi":"小气","pinyin":"xiǎoqi","vi":"bủn xỉn"},{"hanzi":"大方","pinyin":"dàfang","vi":"hào phóng"},{"hanzi":"慷慨","pinyin":"kāngkǎi","vi":"rộng rãi"}]},{"id":"一面","hanzi":"一面","pinyin":"yímiàn","meaning_vi":"một mặt; vừa… vừa…","explanation":"一 (nhất – một) + 面 (diện – mặt) → một mặt, một phương diện; 一面…一面… nghĩa là vừa làm việc này vừa làm việc kia.","hsk_level":"7-9","tags":["pho-tu"],"image":"🪞","examples":[{"type":"basic","zh":"他一面吃饭一面看书。","pinyin":"Tā yímiàn chīfàn yímiàn kànshū.","vi":"Anh ấy vừa ăn cơm vừa đọc sách."},{"type":"simple","zh":"这只是问题的一面，还要看另一面。","pinyin":"Zhè zhǐshì wèntí de yímiàn, hái yào kàn lìngyímiàn.","vi":"Đây chỉ là một mặt của vấn đề, còn phải xem mặt kia."},{"type":"compound","zh":"她一面照顾生病的母亲，一面坚持完成学业。","pinyin":"Tā yímiàn zhàogù shēngbìng de mǔqīn, yímiàn jiānchí wánchéng xuéyè.","vi":"Cô ấy vừa chăm sóc mẹ ốm vừa kiên trì hoàn thành việc học."}],"related":[{"hanzi":"一边","pinyin":"yìbiān","vi":"vừa…vừa"},{"hanzi":"方面","pinyin":"fāngmiàn","vi":"phương diện"},{"hanzi":"另一面","pinyin":"lìngyímiàn","vi":"mặt khác"},{"hanzi":"同时","pinyin":"tóngshí","vi":"đồng thời"}]},{"id":"一年到头","hanzi":"一年到头","pinyin":"yìnián-dàotóu","meaning_vi":"quanh năm, suốt năm","explanation":"一年 (nhất niên – một năm) + 到头 (đáo đầu – đến cuối) → từ đầu năm đến cuối năm, quanh năm suốt tháng.","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"他一年到头都很忙。","pinyin":"Tā yìniándàotóu dōu hěn máng.","vi":"Anh ấy quanh năm đều bận rộn."},{"type":"simple","zh":"这里一年到头都像春天一样。","pinyin":"Zhèlǐ yìniándàotóu dōu xiàng chūntiān yíyàng.","vi":"Nơi đây quanh năm đều như mùa xuân."},{"type":"compound","zh":"虽然农民一年到头辛苦劳动，但是收入还是不高。","pinyin":"Suīrán nóngmín yìniándàotóu xīnkǔ láodòng, dànshì shōurù háishì bù gāo.","vi":"Tuy nông dân vất vả lao động quanh năm nhưng thu nhập vẫn không cao."}],"related":[{"hanzi":"一天到晚","pinyin":"yìtiāndàowǎn","vi":"suốt ngày"},{"hanzi":"常年","pinyin":"chángnián","vi":"quanh năm"},{"hanzi":"全年","pinyin":"quánnián","vi":"cả năm"},{"hanzi":"四季","pinyin":"sìjì","vi":"bốn mùa"}],"traditional":"一年到頭"},{"id":"一旁","hanzi":"一旁","pinyin":"yìpáng","meaning_vi":"một bên, bên cạnh","explanation":"一 (nhất – một) + 旁 (bàng – bên cạnh) → ở một bên, bên cạnh.","hsk_level":"7-9","tags":["danh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"他站在一旁看着。","pinyin":"Tā zhàn zài yìpáng kàn zhe.","vi":"Anh ấy đứng một bên nhìn."},{"type":"simple","zh":"她把手机放在一旁，专心写作业。","pinyin":"Tā bǎshǒu jī fàng zài yìpáng, zhuānxīn xiě zuòyè.","vi":"Cô ấy để điện thoại sang một bên, chuyên tâm làm bài tập."},{"type":"compound","zh":"别人都在忙，你却在一旁看热闹，这样不太好吧。","pinyin":"Biérén dōu zài máng, nǐ què zài yìpáng kànrènao, zhèyàng bú tài hǎo ba.","vi":"Người khác đều đang bận, còn bạn lại đứng một bên xem, như thế không hay lắm đâu."}],"related":[{"hanzi":"旁边","pinyin":"pángbiān","vi":"bên cạnh"},{"hanzi":"身旁","pinyin":"shēnpáng","vi":"bên mình"},{"hanzi":"一边","pinyin":"yìbiān","vi":"một bên"},{"hanzi":"袖手旁观","pinyin":"xiùshǒupángguān","vi":"khoanh tay đứng nhìn"}]},{"id":"一刹那","hanzi":"一刹那","pinyin":"yíchànà","meaning_vi":"trong khoảnh khắc, trong chớp mắt","explanation":"一 (nhất) + 刹那 (sát na – khoảnh khắc cực ngắn, gốc tiếng Phạn kṣaṇa) → khoảnh khắc rất ngắn.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⚡","examples":[{"type":"basic","zh":"一刹那，灯全灭了。","pinyin":"Yíchànà, dēng quán miè le.","vi":"Trong chớp mắt, đèn tắt hết."},{"type":"simple","zh":"看见她的一刹那，我愣住了。","pinyin":"Kànjiàn tā de yíchànà, wǒ lèngzhù le.","vi":"Khoảnh khắc nhìn thấy cô ấy, tôi sững người."},{"type":"compound","zh":"就在汽车冲过来的一刹那，他把孩子拉到了路边。","pinyin":"Jiù zài qìchē chōng guòlái de yíchànà, tā bǎ háizi lā dàole lùbiān.","vi":"Đúng khoảnh khắc ô tô lao tới, anh ấy kéo đứa bé vào lề đường."}],"related":[{"hanzi":"刹那间","pinyin":"chànàjiān","vi":"trong nháy mắt"},{"hanzi":"一瞬间","pinyin":"yíshùnjiān","vi":"trong chớp mắt"},{"hanzi":"顷刻","pinyin":"qǐngkè","vi":"chốc lát"},{"hanzi":"转眼","pinyin":"zhuǎnyǎn","vi":"chớp mắt"}],"traditional":"一剎那"},{"id":"一声不吭","hanzi":"一声不吭","pinyin":"yìshēng-bùkēng","meaning_vi":"im thin thít, không nói một lời","explanation":"一声 (nhất thanh – một tiếng) + 不吭 (bất khanh – không hé răng) → không phát ra một tiếng nào.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤐","examples":[{"type":"basic","zh":"他一声不吭地走了。","pinyin":"Tā yìshēngbùkēng de zǒu le.","vi":"Anh ấy lặng lẽ bỏ đi không nói một lời."},{"type":"simple","zh":"被老师批评后，她一声不吭地坐着。","pinyin":"Bèi lǎoshī pīpíng hòu, tā yìshēngbùkēng de zuò zhe.","vi":"Sau khi bị cô giáo phê bình, cô bé ngồi im thin thít."},{"type":"compound","zh":"虽然伤口很疼，但是他咬着牙一声不吭。","pinyin":"Suīrán shāngkǒu hěn téng, dànshì tā yǎozhe yá yìshēngbùkēng.","vi":"Tuy vết thương rất đau nhưng anh ấy nghiến răng không kêu một tiếng."}],"related":[{"hanzi":"一言不发","pinyin":"yìyánbùfā","vi":"không nói một lời"},{"hanzi":"沉默","pinyin":"chénmò","vi":"im lặng"},{"hanzi":"默不作声","pinyin":"mòbúzuòshēng","vi":"lặng thinh"},{"hanzi":"吭声","pinyin":"kēngshēng","vi":"lên tiếng"}],"traditional":"一聲不吭"},{"id":"一事无成","hanzi":"一事无成","pinyin":"yíshì-wúchéng","meaning_vi":"không làm nên trò trống gì, chẳng nên việc gì","explanation":"一事 (nhất sự – một việc) + 无成 (vô thành – không thành) → không thành được việc gì; chỉ người thất bại, không có thành tựu.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😞","examples":[{"type":"basic","zh":"他忙了半辈子，却一事无成。","pinyin":"Tā mángle bànbèizi, què yíshìwúchéng.","vi":"Ông ấy bận rộn nửa đời người mà chẳng nên việc gì."},{"type":"simple","zh":"整天玩游戏只会让你一事无成。","pinyin":"Zhěngtiān wán yóuxì zhǐ huì ràng nǐ yíshìwúchéng.","vi":"Suốt ngày chơi game chỉ khiến bạn chẳng làm nên trò trống gì."},{"type":"compound","zh":"如果做事总是三分钟热度，就很可能一事无成。","pinyin":"Rúguǒ zuòshì zǒngshì sān fēnzhōng rèdù, jiù hěn kěnéng yíshìwúchéng.","vi":"Nếu làm gì cũng cả thèm chóng chán thì rất có thể chẳng nên việc gì."}],"related":[{"hanzi":"碌碌无为","pinyin":"lùlùwúwéi","vi":"tầm thường vô vị"},{"hanzi":"功成名就","pinyin":"gōngchéngmíngjiù","vi":"công thành danh toại"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"},{"hanzi":"成就","pinyin":"chéngjiù","vi":"thành tựu"}],"traditional":"一事無成"},{"id":"一手","hanzi":"一手","pinyin":"yìshǒu","meaning_vi":"một tay (tự mình); tay nghề, ngón nghề","explanation":"一 (nhất – một) + 手 (thủ – tay) → một tay làm lấy (tự mình gây dựng); cũng chỉ một ngón nghề giỏi, như 露一手.","hsk_level":"7-9","tags":["pho-tu"],"image":"✋","examples":[{"type":"basic","zh":"这家店是他一手创办的。","pinyin":"Zhè jiā diàn shì tā yìshǒu chuàngbàn de.","vi":"Cửa hàng này do một tay anh ấy gây dựng."},{"type":"simple","zh":"他做菜很有一手，今天给大家露一手。","pinyin":"Tā zuòcài hěn yǒuyìshǒu, jīntiān gěi dàjiā lòuyìshǒu.","vi":"Anh ấy nấu ăn rất có nghề, hôm nay trổ tài cho mọi người xem."},{"type":"compound","zh":"虽然孩子是奶奶一手带大的，但是他跟父母也很亲。","pinyin":"Suīrán háizi shì nǎinai yìshǒu dàidà de, dànshì tā gēn fùmǔ yě hěn qīn.","vi":"Tuy đứa bé do một tay bà nội nuôi lớn nhưng nó cũng rất gần gũi bố mẹ."}],"related":[{"hanzi":"亲手","pinyin":"qīnshǒu","vi":"tự tay"},{"hanzi":"露一手","pinyin":"lòuyìshǒu","vi":"trổ tài"},{"hanzi":"手艺","pinyin":"shǒuyì","vi":"tay nghề"},{"hanzi":"一把手","pinyin":"yìbǎshǒu","vi":"người đứng đầu"}]},{"id":"一瞬间","hanzi":"一瞬间","pinyin":"yíshùnjiān","meaning_vi":"trong nháy mắt, trong khoảnh khắc","explanation":"一 (nhất) + 瞬 (thuấn – chớp mắt) + 间 (gian – khoảng) → trong khoảng một cái chớp mắt.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"✨","examples":[{"type":"basic","zh":"烟花一瞬间就消失了。","pinyin":"Yānhuā yíshùnjiān jiù xiāoshī le.","vi":"Pháo hoa biến mất trong nháy mắt."},{"type":"simple","zh":"听到消息的一瞬间，她哭了出来。","pinyin":"Tīngdào xiāoxi de yíshùnjiān, tā kūle chūlái.","vi":"Khoảnh khắc nghe tin, cô ấy bật khóc."},{"type":"compound","zh":"虽然事故只发生在一瞬间，但是后果非常严重。","pinyin":"Suīrán shìgù zhǐ fāshēng zài yíshùnjiān, dànshì hòuguǒ fēicháng yánzhòng.","vi":"Tuy tai nạn chỉ xảy ra trong nháy mắt nhưng hậu quả rất nghiêm trọng."}],"related":[{"hanzi":"瞬间","pinyin":"shùnjiān","vi":"khoảnh khắc"},{"hanzi":"一刹那","pinyin":"yíchànà","vi":"trong chớp mắt"},{"hanzi":"转瞬","pinyin":"zhuǎnshùn","vi":"chớp mắt"},{"hanzi":"片刻","pinyin":"piànkè","vi":"chốc lát"}],"traditional":"一瞬間"},{"id":"一塌糊涂","hanzi":"一塌糊涂","pinyin":"yìtā-hútu","meaning_vi":"bết bát, tệ hại, rối tinh rối mù","explanation":"一塌 (nhất tháp – sụp đổ hẳn) + 糊涂 (hồ đồ – lộn xộn) → sụp đổ, rối loạn hoàn toàn; chỉ tình trạng cực kỳ tệ; cũng dùng sau 得 để nhấn mạnh mức độ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💥","examples":[{"type":"basic","zh":"房间乱得一塌糊涂。","pinyin":"Fángjiān luàn de yìtāhútu.","vi":"Căn phòng bừa bộn kinh khủng."},{"type":"simple","zh":"这次考试他考得一塌糊涂。","pinyin":"Zhè cì kǎoshì tā kǎo de yìtāhútu.","vi":"Lần thi này cậu ấy làm bài bết bát."},{"type":"compound","zh":"因为没有提前准备，所以演出搞得一塌糊涂。","pinyin":"Yīnwèi méiyǒu tíqián zhǔnbèi, suǒyǐ yǎnchū gǎo de yìtāhútu.","vi":"Vì không chuẩn bị trước nên buổi biểu diễn hỏng bét."}],"related":[{"hanzi":"乱七八糟","pinyin":"luànqībāzāo","vi":"lộn xộn"},{"hanzi":"一团糟","pinyin":"yìtuánzāo","vi":"rối tung"},{"hanzi":"糟糕","pinyin":"zāogāo","vi":"tồi tệ"},{"hanzi":"井井有条","pinyin":"jǐngjǐngyǒutiáo","vi":"ngăn nắp"}],"traditional":"一塌糊塗"},{"id":"一体","hanzi":"一体","pinyin":"yìtǐ","meaning_vi":"một khối, một thể thống nhất","explanation":"一 (nhất – một) + 体 (thể – thân, khối) → hợp thành một khối thống nhất.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"这台机器集多种功能于一体。","pinyin":"Zhè tái jīqì jí duōzhǒng gōngnéng yú yìtǐ.","vi":"Chiếc máy này tích hợp nhiều chức năng trong một."},{"type":"simple","zh":"这座城市与周边地区正走向一体化。","pinyin":"Zhè zuò chéngshì yǔ zhōubiān dìqū zhèng zǒuxiàng yìtǐhuà.","vi":"Thành phố này đang tiến tới nhất thể hóa với các vùng xung quanh."},{"type":"compound","zh":"只有全队融为一体，才能赢得比赛。","pinyin":"Zhǐyǒu quán duì róngwéiyìtǐ, cáinéng yíngdé bǐsài.","vi":"Chỉ khi cả đội hòa thành một khối mới thắng được trận đấu."}],"related":[{"hanzi":"整体","pinyin":"zhěngtǐ","vi":"tổng thể"},{"hanzi":"一体化","pinyin":"yìtǐhuà","vi":"nhất thể hóa"},{"hanzi":"统一","pinyin":"tǒngyī","vi":"thống nhất"},{"hanzi":"融为一体","pinyin":"róngwéiyìtǐ","vi":"hòa làm một"}],"traditional":"一體"},{"id":"一天到晚","hanzi":"一天到晚","pinyin":"yìtiān-dàowǎn","meaning_vi":"suốt ngày, từ sáng đến tối","explanation":"一天 (nhất thiên – một ngày) + 到晚 (đáo vãn – đến tối) → từ sáng tới tối; thường hàm ý phàn nàn.","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"🕘","examples":[{"type":"basic","zh":"他一天到晚玩手机。","pinyin":"Tā yìtiāndàowǎn wán shǒujī.","vi":"Nó suốt ngày chơi điện thoại."},{"type":"simple","zh":"妈妈一天到晚忙个不停。","pinyin":"Māma yìtiāndàowǎn máng gè bùtíng.","vi":"Mẹ bận rộn suốt từ sáng đến tối."},{"type":"compound","zh":"你一天到晚待在家里，难怪觉得无聊。","pinyin":"Nǐ yìtiāndàowǎn dāi zài jiālǐ, nánguài juéde wúliáo.","vi":"Bạn suốt ngày ru rú trong nhà, thảo nào thấy chán."}],"related":[{"hanzi":"整天","pinyin":"zhěngtiān","vi":"cả ngày"},{"hanzi":"一年到头","pinyin":"yìniándàotóu","vi":"quanh năm"},{"hanzi":"从早到晚","pinyin":"cóngzǎodàowǎn","vi":"từ sáng đến tối"},{"hanzi":"成天","pinyin":"chéngtiān","vi":"suốt ngày"}]},{"id":"一头","hanzi":"一头","pinyin":"yìtóu","meaning_vi":"một con (gia súc); cắm đầu, lao đầu; một đầu","explanation":"一 (nhất) + 头 (đầu) → “một con” (lượng từ cho gia súc lớn), “một đầu/mái tóc”, hoặc phó từ chỉ lao thẳng, cắm đầu vào.","hsk_level":"7-9","tags":["luong-tu"],"image":"🐂","examples":[{"type":"basic","zh":"院子里拴着一头牛。","pinyin":"Yuànzi lǐ shuānzhe yìtóu niú.","vi":"Trong sân buộc một con bò."},{"type":"simple","zh":"她留着一头长发，非常漂亮。","pinyin":"Tā liúzhe yìtóu chángfà, fēicháng piàoliang.","vi":"Cô ấy để mái tóc dài, rất xinh đẹp."},{"type":"compound","zh":"他一回家就一头倒在床上，因为实在太累了。","pinyin":"Tā yì huíjiā jiù yìtóu dǎo zài chuáng shàng, yīnwèi shízài tài lèi le.","vi":"Anh ấy vừa về nhà là lăn đùng ra giường, vì thật sự quá mệt."}],"related":[{"hanzi":"一端","pinyin":"yìduān","vi":"một đầu"},{"hanzi":"埋头","pinyin":"máitóu","vi":"vùi đầu"},{"hanzi":"头","pinyin":"tóu","vi":"con (lượng từ)"},{"hanzi":"一心","pinyin":"yìxīn","vi":"một lòng"}],"traditional":"一頭"},{"id":"一味","hanzi":"一味","pinyin":"yíwèi","meaning_vi":"một mực, cứ khăng khăng, mù quáng","explanation":"一 (nhất) + 味 (vị – mùi vị) → chỉ một vị; chỉ cứ một mực làm theo một hướng, không xét gì khác (thường hàm ý chê).","hsk_level":"7-9","tags":["pho-tu"],"image":"🙈","examples":[{"type":"basic","zh":"不能一味地批评孩子。","pinyin":"Bù néng yíwèi de pīpíng háizi.","vi":"Không thể một mực phê bình con trẻ."},{"type":"simple","zh":"他一味追求速度，忽略了质量。","pinyin":"Tā yíwèi zhuīqiú sùdù, hūlüèle zhìliàng.","vi":"Anh ấy cứ chạy theo tốc độ mà bỏ qua chất lượng."},{"type":"compound","zh":"如果一味地迁就他，他就会越来越任性。","pinyin":"Rúguǒ yíwèi de qiānjiù tā, tā jiù huì yuèláiyuè rènxìng.","vi":"Nếu cứ một mực chiều theo nó thì nó sẽ ngày càng bướng."}],"related":[{"hanzi":"盲目","pinyin":"mángmù","vi":"mù quáng"},{"hanzi":"一个劲儿","pinyin":"yígejìnr","vi":"cứ mãi"},{"hanzi":"总是","pinyin":"zǒngshì","vi":"luôn luôn"},{"hanzi":"一心","pinyin":"yìxīn","vi":"một lòng"}]},{"id":"一无所有","hanzi":"一无所有","pinyin":"yìwú-suǒyǒu","meaning_vi":"không có gì cả, trắng tay","explanation":"一 (nhất – hoàn toàn) + 无 (vô – không) + 所有 (sở hữu – cái có) → chẳng có gì trong tay.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🫙","examples":[{"type":"basic","zh":"他曾经一无所有。","pinyin":"Tā céngjīng yìwúsuǒyǒu.","vi":"Anh ấy từng trắng tay."},{"type":"simple","zh":"一场大火让他变得一无所有。","pinyin":"Yì chǎng dàhuǒ ràng tā biànde yìwúsuǒyǒu.","vi":"Một trận hỏa hoạn khiến ông ấy trắng tay."},{"type":"compound","zh":"虽然刚来城市时一无所有，但是他靠努力买了房。","pinyin":"Suīrán gāng lái chéngshì shí yìwúsuǒyǒu, dànshì tā kào nǔlì mǎile fáng.","vi":"Tuy mới lên thành phố tay trắng nhưng anh ấy đã nhờ nỗ lực mà mua được nhà."}],"related":[{"hanzi":"两手空空","pinyin":"liǎngshǒukōngkōng","vi":"hai bàn tay trắng"},{"hanzi":"一贫如洗","pinyin":"yìpínrúxǐ","vi":"nghèo rớt mồng tơi"},{"hanzi":"应有尽有","pinyin":"yīngyǒujìnyǒu","vi":"có đủ mọi thứ"},{"hanzi":"一无所知","pinyin":"yìwúsuǒzhī","vi":"không biết gì"}],"traditional":"一無所有"},{"id":"一无所知","hanzi":"一无所知","pinyin":"yìwú-suǒzhī","meaning_vi":"hoàn toàn không biết gì","explanation":"一 (nhất – hoàn toàn) + 无 (vô – không) + 所知 (sở tri – điều biết) → không biết chút gì.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"❓","examples":[{"type":"basic","zh":"我对此一无所知。","pinyin":"Wǒ duì cǐ yìwúsuǒzhī.","vi":"Tôi hoàn toàn không biết gì về chuyện này."},{"type":"simple","zh":"他对电脑一无所知，连开机都不会。","pinyin":"Tā duì diànnǎo yìwúsuǒzhī, lián kāijī dōu bú huì.","vi":"Ông ấy không biết gì về máy tính, đến bật máy cũng không biết."},{"type":"compound","zh":"虽然我对这个行业一无所知，但是我愿意从头学起。","pinyin":"Suīrán wǒ duì zhè gè hángyè yìwúsuǒzhī, dànshì wǒ yuànyì cóngtóu xué qǐ.","vi":"Tuy tôi chẳng biết gì về ngành này nhưng tôi sẵn lòng học từ đầu."}],"related":[{"hanzi":"一窍不通","pinyin":"yíqiàobùtōng","vi":"dốt đặc cán mai"},{"hanzi":"无知","pinyin":"wúzhī","vi":"vô tri"},{"hanzi":"了如指掌","pinyin":"liǎorúzhǐzhǎng","vi":"rõ như lòng bàn tay"},{"hanzi":"一无所有","pinyin":"yìwúsuǒyǒu","vi":"trắng tay"}],"traditional":"一無所知"},{"id":"一系列","hanzi":"一系列","pinyin":"yíxìliè","meaning_vi":"một loạt, hàng loạt","explanation":"一 (nhất) + 系列 (hệ liệt – chuỗi, loạt) → một chuỗi các sự việc liên quan nhau.","hsk_level":"7-9","tags":["tinh-tu"],"image":"📚","examples":[{"type":"basic","zh":"公司采取了一系列措施。","pinyin":"Gōngsī cǎiqǔle yíxìliè cuòshī.","vi":"Công ty đã áp dụng một loạt biện pháp."},{"type":"simple","zh":"新政策带来了一系列积极的变化。","pinyin":"Xīn zhèngcè dàiláile yíxìliè jījí de biànhuà.","vi":"Chính sách mới mang lại hàng loạt thay đổi tích cực."},{"type":"compound","zh":"因为一系列失误，所以球队最后输掉了比赛。","pinyin":"Yīnwèi yíxìliè shīwù, suǒyǐ qiúduì zuìhòu shūdiàole bǐsài.","vi":"Vì một loạt sai lầm nên đội bóng cuối cùng thua trận."}],"related":[{"hanzi":"系列","pinyin":"xìliè","vi":"loạt, dòng"},{"hanzi":"一连串","pinyin":"yìliánchuàn","vi":"chuỗi"},{"hanzi":"一揽子","pinyin":"yìlǎnzi","vi":"trọn gói"},{"hanzi":"多项","pinyin":"duōxiàng","vi":"nhiều hạng mục"}]},{"id":"一线","hanzi":"一线","pinyin":"yíxiàn","meaning_vi":"tuyến đầu, tiền tuyến; hạng nhất","explanation":"一 (nhất – thứ nhất) + 线 (tuyến – tuyến) → tuyến đầu nơi trực tiếp làm việc/chiến đấu; còn chỉ hạng nhất như 一线城市.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🛡️","examples":[{"type":"basic","zh":"他在生产一线工作。","pinyin":"Tā zài shēngchǎn yíxiàn gōngzuò.","vi":"Anh ấy làm việc ở tuyến đầu sản xuất."},{"type":"simple","zh":"疫情期间，医护人员冲在第一线。","pinyin":"Yìqíng qījiān, yīhù rényuán chōng zài dìyīxiàn.","vi":"Trong dịch bệnh, nhân viên y tế xông pha nơi tuyến đầu."},{"type":"compound","zh":"虽然一线城市机会多，但是生活压力也很大。","pinyin":"Suīrán yíxiàn chéngshì jīhuì duō, dànshì shēnghuó yālì yě hěn dà.","vi":"Tuy thành phố hạng nhất nhiều cơ hội nhưng áp lực cuộc sống cũng rất lớn."}],"related":[{"hanzi":"前线","pinyin":"qiánxiàn","vi":"tiền tuyến"},{"hanzi":"基层","pinyin":"jīcéng","vi":"cơ sở"},{"hanzi":"二线","pinyin":"èrxiàn","vi":"tuyến hai"},{"hanzi":"第一线","pinyin":"dìyīxiàn","vi":"tuyến đầu"}],"traditional":"一線"},{"id":"一心","hanzi":"一心","pinyin":"yìxīn","meaning_vi":"một lòng, toàn tâm toàn ý","explanation":"一 (nhất – một) + 心 (tâm – lòng) → dồn hết một lòng vào việc gì.","hsk_level":"7-9","tags":["pho-tu"],"image":"❤️","examples":[{"type":"basic","zh":"他一心想当医生。","pinyin":"Tā yìxīn xiǎng dāng yīshēng.","vi":"Anh ấy một lòng muốn làm bác sĩ."},{"type":"simple","zh":"她一心扑在工作上，很少休息。","pinyin":"Tā yìxīn pū zài gōngzuò shàng, hěn shǎo xiūxi.","vi":"Cô ấy dồn hết tâm sức vào công việc, rất ít nghỉ ngơi."},{"type":"compound","zh":"只要大家一心一意，就没有克服不了的困难。","pinyin":"Zhǐyào dàjiā yìxīnyíyì, jiù méiyǒu kèfú bùliǎo de kùnnan.","vi":"Chỉ cần mọi người một lòng một dạ thì không có khó khăn nào không vượt qua được."}],"related":[{"hanzi":"一心一意","pinyin":"yìxīnyíyì","vi":"một lòng một dạ"},{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"},{"hanzi":"全心全意","pinyin":"quánxīnquányì","vi":"toàn tâm toàn ý"},{"hanzi":"三心二意","pinyin":"sānxīn'èryì","vi":"hai lòng"}]},{"id":"一言不发","hanzi":"一言不发","pinyin":"yìyán-bùfā","meaning_vi":"không nói một lời","explanation":"一言 (nhất ngôn – một lời) + 不发 (bất phát – không nói ra) → không thốt ra một lời nào.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😶","examples":[{"type":"basic","zh":"他坐在那里一言不发。","pinyin":"Tā zuò zài nàlǐ yìyánbùfā.","vi":"Anh ấy ngồi đó không nói một lời."},{"type":"simple","zh":"会议上，经理一言不发地听着。","pinyin":"Huìyì shàng, jīnglǐ yìyánbùfā de tīng zhe.","vi":"Trong cuộc họp, giám đốc im lặng lắng nghe."},{"type":"compound","zh":"虽然大家吵得很厉害，但是他始终一言不发。","pinyin":"Suīrán dàjiā chǎo de hěn lìhai, dànshì tā shǐzhōng yìyánbùfā.","vi":"Tuy mọi người cãi nhau dữ dội nhưng anh ấy trước sau không nói lời nào."}],"related":[{"hanzi":"一声不吭","pinyin":"yìshēngbùkēng","vi":"im thin thít"},{"hanzi":"沉默不语","pinyin":"chénmòbùyǔ","vi":"im lặng không nói"},{"hanzi":"滔滔不绝","pinyin":"tāotāobùjué","vi":"thao thao bất tuyệt"},{"hanzi":"发言","pinyin":"fāyán","vi":"phát biểu"}],"traditional":"一言不發"},{"id":"一言一行","hanzi":"一言一行","pinyin":"yìyán-yìxíng","meaning_vi":"từng lời nói việc làm, nhất cử nhất động","explanation":"一言 (một lời) + 一行 (một việc làm) → mỗi lời nói, mỗi hành động.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"👣","examples":[{"type":"basic","zh":"父母的一言一行影响孩子。","pinyin":"Fùmǔ de yìyányìxíng yǐngxiǎng háizi.","vi":"Từng lời nói việc làm của cha mẹ ảnh hưởng đến con."},{"type":"simple","zh":"老师的一言一行都是学生的榜样。","pinyin":"Lǎoshī de yìyányìxíng dōu shì xuésheng de bǎngyàng.","vi":"Nhất cử nhất động của thầy cô đều là tấm gương cho học sinh."},{"type":"compound","zh":"既然你是公众人物，就要注意自己的一言一行。","pinyin":"Jìrán nǐ shì gōngzhòng rénwù, jiùyào zhùyì zìjǐ de yìyányìxíng.","vi":"Đã là người của công chúng thì bạn phải chú ý từng lời nói việc làm của mình."}],"related":[{"hanzi":"言行","pinyin":"yánxíng","vi":"lời nói và việc làm"},{"hanzi":"举止","pinyin":"jǔzhǐ","vi":"cử chỉ"},{"hanzi":"言行一致","pinyin":"yánxíngyízhì","vi":"nói đi đôi với làm"},{"hanzi":"一举一动","pinyin":"yìjǔyídòng","vi":"nhất cử nhất động"}]},{"id":"一眼","hanzi":"一眼","pinyin":"yìyǎn","meaning_vi":"một cái nhìn, nhìn một cái, thoáng nhìn","explanation":"一 (nhất – một) + 眼 (nhãn – mắt, cái nhìn) → chỉ nhìn một cái (là đủ thấy, nhận ra).","hsk_level":"7-9","tags":["pho-tu"],"image":"👀","examples":[{"type":"basic","zh":"我一眼就认出了他。","pinyin":"Wǒ yìyǎn jiù rènchūle tā.","vi":"Tôi nhận ra anh ấy ngay từ cái nhìn đầu tiên."},{"type":"simple","zh":"她看了一眼手表，急忙出门了。","pinyin":"Tā kànle yìyǎn shǒubiǎo, jímáng chūmén le.","vi":"Cô ấy liếc nhìn đồng hồ rồi vội vàng ra khỏi nhà."},{"type":"compound","zh":"虽然只看了一眼，但是那幅画让我久久不能忘记。","pinyin":"Suīrán zhǐ kànle yìyǎn, dànshì nà fú huà ràng wǒ jiǔjiǔ bù néng wàngjì.","vi":"Tuy chỉ nhìn thoáng qua nhưng bức tranh ấy khiến tôi mãi không quên."}],"related":[{"hanzi":"一眼望去","pinyin":"yìyǎnwàngqù","vi":"phóng tầm mắt"},{"hanzi":"一见钟情","pinyin":"yíjiànzhōngqíng","vi":"yêu từ cái nhìn đầu tiên"},{"hanzi":"瞥","pinyin":"piē","vi":"liếc"},{"hanzi":"眼光","pinyin":"yǎnguāng","vi":"ánh mắt"}]},{"id":"一一","hanzi":"一一","pinyin":"yīyī","meaning_vi":"từng cái một, lần lượt","explanation":"一 (nhất) lặp lại → từng cái một, lần lượt không bỏ sót.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔢","examples":[{"type":"basic","zh":"他一一回答了问题。","pinyin":"Tā yīyī huídále wèntí.","vi":"Anh ấy lần lượt trả lời từng câu hỏi."},{"type":"simple","zh":"主人把客人一一介绍给大家。","pinyin":"Zhǔrén bǎ kèrén yīyī jièshào gěi dàjiā.","vi":"Chủ nhà lần lượt giới thiệu từng vị khách với mọi người."},{"type":"compound","zh":"因为时间有限，所以我不能一一感谢每个人。","pinyin":"Yīnwèi shíjiān yǒuxiàn, suǒyǐ wǒ bù néng yīyī gǎnxiè měigèrén.","vi":"Vì thời gian có hạn nên tôi không thể cảm ơn từng người một."}],"related":[{"hanzi":"逐一","pinyin":"zhúyī","vi":"lần lượt từng cái"},{"hanzi":"依次","pinyin":"yīcì","vi":"theo thứ tự"},{"hanzi":"挨个","pinyin":"āigè","vi":"lần lượt từng người"},{"hanzi":"分别","pinyin":"fēnbié","vi":"riêng từng"}]},{"id":"一应俱全","hanzi":"一应俱全","pinyin":"yìyīng-jùquán","meaning_vi":"đầy đủ mọi thứ, có đủ cả","explanation":"一应 (nhất ứng – mọi thứ cần có) + 俱全 (câu toàn – đều đủ) → mọi thứ cần thiết đều có đầy đủ.","hsk_level":"7-9","tags":["thanh-ngu","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"超市里商品一应俱全。","pinyin":"Chāoshì lǐ shāngpǐn yìyīngjùquán.","vi":"Siêu thị có đủ mọi mặt hàng."},{"type":"simple","zh":"新房子里家具电器一应俱全。","pinyin":"Xīnfáng zi lǐ jiājù diànqì yìyīngjùquán.","vi":"Trong nhà mới đồ đạc, đồ điện đầy đủ cả."},{"type":"compound","zh":"虽然这家酒店不大，但是设施一应俱全。","pinyin":"Suīrán zhè jiā jiǔdiàn búdà, dànshì shèshī yìyīngjùquán.","vi":"Tuy khách sạn này không lớn nhưng tiện nghi có đủ cả."}],"related":[{"hanzi":"应有尽有","pinyin":"yīngyǒujìnyǒu","vi":"có đủ mọi thứ"},{"hanzi":"齐全","pinyin":"qíquán","vi":"đầy đủ"},{"hanzi":"完备","pinyin":"wánbèi","vi":"hoàn bị"},{"hanzi":"一无所有","pinyin":"yìwúsuǒyǒu","vi":"chẳng có gì"}],"traditional":"一應俱全"},{"id":"一早","hanzi":"一早","pinyin":"yìzǎo","meaning_vi":"sáng sớm","explanation":"一 (nhất) + 早 (tảo – sớm) → lúc sáng sớm, ngay đầu buổi sáng.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🐓","examples":[{"type":"basic","zh":"明天一早出发。","pinyin":"Míngtiān yìzǎo chūfā.","vi":"Sáng sớm mai xuất phát."},{"type":"simple","zh":"他今天一早就去机场接人了。","pinyin":"Tā jīntiān yìzǎo jiù qù jīchǎng jiērén le.","vi":"Sáng sớm nay anh ấy đã ra sân bay đón người."},{"type":"compound","zh":"如果明天一早不下雨，我们就去看日出。","pinyin":"Rúguǒ míngtiān yìzǎo bú xiàyǔ, wǒmen jiù qù kàn rìchū.","vi":"Nếu sáng sớm mai không mưa, chúng ta sẽ đi ngắm bình minh."}],"related":[{"hanzi":"一大早","pinyin":"yídàzǎo","vi":"sáng tinh mơ"},{"hanzi":"清早","pinyin":"qīngzǎo","vi":"sáng sớm"},{"hanzi":"早晨","pinyin":"zǎochen","vi":"buổi sáng"},{"hanzi":"凌晨","pinyin":"língchén","vi":"rạng sáng"}]},{"id":"一长一短","hanzi":"一长一短","pinyin":"yìcháng-yìduǎn","meaning_vi":"kể lể dài dòng, nói lải nhải không dứt","explanation":"一长 (nhất trường – một dài) + 一短 (nhất đoản – một ngắn) → chuyện dài chuyện ngắn; chỉ nói năng lải nhải, kể lể đủ điều.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🗨️","examples":[{"type":"basic","zh":"她一长一短地说个不停。","pinyin":"Tā yìchángyìduǎn de shuō gè bùtíng.","vi":"Bà ấy kể lể lải nhải không ngớt."},{"type":"simple","zh":"奶奶一长一短地讲起了过去的事。","pinyin":"Nǎinai yìchángyìduǎn de jiǎng qǐle guòqù de shì.","vi":"Bà nội kể lể dài dòng chuyện ngày xưa."},{"type":"compound","zh":"虽然他一长一短地解释了半天，但是我还是没听明白。","pinyin":"Suīrán tā yìchángyìduǎn de jiěshìle bàn tiān, dànshì wǒ háishì méi tīng míngbai.","vi":"Tuy anh ấy giải thích dài dòng cả buổi nhưng tôi vẫn không hiểu."}],"related":[{"hanzi":"唠叨","pinyin":"láodao","vi":"cằn nhằn"},{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"dài dòng"},{"hanzi":"说长道短","pinyin":"shuōchángdàoduǎn","vi":"nói ra nói vào"},{"hanzi":"絮絮叨叨","pinyin":"xùxùdāodāo","vi":"lải nhải"}],"traditional":"一長一短"},{"id":"一阵","hanzi":"一阵","pinyin":"yízhèn","meaning_vi":"một trận, một hồi, một lúc","explanation":"一 (nhất) + 阵 (trận – đợt) → một đợt, một hồi (gió, mưa, tiếng cười…) hoặc một khoảng thời gian.","hsk_level":"7-9","tags":["luong-tu","thoi-gian"],"image":"🌬️","examples":[{"type":"basic","zh":"外面刮起一阵大风。","pinyin":"Wàimiàn guā qǐ yízhèn dàfēng.","vi":"Bên ngoài nổi lên một trận gió lớn."},{"type":"simple","zh":"教室里突然响起一阵笑声。","pinyin":"Jiàoshì lǐ tūrán xiǎngqǐ yízhèn xiàoshēng.","vi":"Trong lớp bỗng vang lên một tràng cười."},{"type":"compound","zh":"我前一阵比较忙，所以没给你打电话。","pinyin":"Wǒ qián yízhèn bǐjiào máng, suǒyǐ méi gěi nǐ dǎdiànhuà.","vi":"Dạo trước tôi khá bận nên không gọi điện cho bạn."}],"related":[{"hanzi":"一阵子","pinyin":"yízhènzi","vi":"một thời gian"},{"hanzi":"阵雨","pinyin":"zhènyǔ","vi":"mưa rào"},{"hanzi":"一会儿","pinyin":"yíhuìr","vi":"một lát"},{"hanzi":"一下","pinyin":"yíxià","vi":"một chút"}],"traditional":"一陣"},{"id":"伊斯兰教","hanzi":"伊斯兰教","pinyin":"Yīsīlánjiào","meaning_vi":"đạo Hồi, Hồi giáo","explanation":"伊斯兰 (Y-tư-lan – phiên âm Islam) + 教 (giáo – tôn giáo) → đạo Hồi.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"☪️","examples":[{"type":"basic","zh":"他信仰伊斯兰教。","pinyin":"Tā xìnyǎng Yīsīlánjiào.","vi":"Anh ấy theo đạo Hồi."},{"type":"simple","zh":"伊斯兰教是世界三大宗教之一。","pinyin":"Yīsīlánjiào shì shìjiè sān dà zōngjiào zhīyī.","vi":"Hồi giáo là một trong ba tôn giáo lớn của thế giới."},{"type":"compound","zh":"因为他信伊斯兰教，所以不吃猪肉。","pinyin":"Yīnwèi Tāxìn Yīsīlánjiào, suǒyǐ bù chī zhūròu.","vi":"Vì anh ấy theo đạo Hồi nên không ăn thịt lợn."}],"related":[{"hanzi":"穆斯林","pinyin":"Mùsīlín","vi":"người Hồi giáo"},{"hanzi":"清真","pinyin":"qīngzhēn","vi":"Halal"},{"hanzi":"佛教","pinyin":"Fójiào","vi":"Phật giáo"},{"hanzi":"基督教","pinyin":"Jīdūjiào","vi":"Cơ Đốc giáo"}],"traditional":"伊斯蘭教"},{"id":"医务","hanzi":"医务","pinyin":"yīwù","meaning_vi":"y vụ, công tác y tế","explanation":"医 (y – y tế) + 务 (vụ – công việc) → công việc thuộc ngành y; thường làm định ngữ như 医务人员, 医务室.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"⚕️","examples":[{"type":"basic","zh":"学校有个医务室。","pinyin":"Xuéxiào yǒu gè yīwùshì.","vi":"Trường có một phòng y tế."},{"type":"simple","zh":"医务人员日夜守护着病人。","pinyin":"Yīwù rényuán rìyè shǒuhùzhe bìngrén.","vi":"Nhân viên y tế ngày đêm túc trực bên bệnh nhân."},{"type":"compound","zh":"如果运动时受了伤，就马上去医务室处理。","pinyin":"Rúguǒ yùndòng shí shòule shāng, jiù mǎshàng qù yīwùshì chǔlǐ.","vi":"Nếu bị thương khi chơi thể thao thì đến ngay phòng y tế để xử lý."}],"related":[{"hanzi":"医务室","pinyin":"yīwùshì","vi":"phòng y tế"},{"hanzi":"医护","pinyin":"yīhù","vi":"y tá bác sĩ"},{"hanzi":"医疗","pinyin":"yīliáo","vi":"y tế"},{"hanzi":"卫生","pinyin":"wèishēng","vi":"vệ sinh"}],"traditional":"醫務"},{"id":"依","hanzi":"依","pinyin":"yī","meaning_vi":"theo, dựa vào; nghe theo, chiều theo","explanation":"依 (y – nương tựa, theo) → dựa vào; làm giới từ nghĩa là “theo, căn cứ”, như 依我看 (theo tôi thấy).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"依我看，这样不行。","pinyin":"Yīwǒkàn, zhèyàng bù xíng.","vi":"Theo tôi thấy, như vậy không được."},{"type":"simple","zh":"孩子哭着闹着，妈妈只好依了他。","pinyin":"Háizi kūzhe nào zhe, māma zhǐhǎo yīle tā.","vi":"Đứa bé khóc lóc ăn vạ, mẹ đành chiều theo nó."},{"type":"compound","zh":"如果大家都依法办事，社会就会更公平。","pinyin":"Rúguǒ dàjiā dōu yīfǎ bànshì, shèhuì jiù huì gèng gōngpíng.","vi":"Nếu ai cũng làm việc theo pháp luật thì xã hội sẽ công bằng hơn."}],"related":[{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"依照","pinyin":"yīzhào","vi":"theo"},{"hanzi":"依赖","pinyin":"yīlài","vi":"ỷ lại"},{"hanzi":"依法","pinyin":"yīfǎ","vi":"theo pháp luật"}]},{"id":"依依不舍","hanzi":"依依不舍","pinyin":"yīyī-bùshě","meaning_vi":"lưu luyến không nỡ rời xa","explanation":"依依 (y y – quyến luyến) + 不舍 (bất xả – không nỡ bỏ) → bịn rịn, không nỡ chia tay.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"我们依依不舍地告别。","pinyin":"Wǒmen yīyībùshě de gàobié.","vi":"Chúng tôi bịn rịn chia tay."},{"type":"simple","zh":"孩子依依不舍地离开了外婆家。","pinyin":"Háizi yīyībùshě de líkāile wàipó jiā.","vi":"Đứa bé lưu luyến rời nhà bà ngoại."},{"type":"compound","zh":"虽然假期结束了，但是大家都对这里依依不舍。","pinyin":"Suīrán jiàqī jiéshù le, dànshì dàjiā dōu duì zhèlǐ yīyībùshě.","vi":"Tuy kỳ nghỉ đã kết thúc nhưng mọi người đều lưu luyến nơi này."}],"related":[{"hanzi":"恋恋不舍","pinyin":"liànliànbùshě","vi":"quyến luyến"},{"hanzi":"难舍难分","pinyin":"nánshěnánfēn","vi":"khó lòng chia xa"},{"hanzi":"告别","pinyin":"gàobié","vi":"từ biệt"},{"hanzi":"舍不得","pinyin":"shěbude","vi":"không nỡ"}],"traditional":"依依不捨"},{"id":"怡然自得","hanzi":"怡然自得","pinyin":"yírán-zìdé","meaning_vi":"ung dung tự tại, vui vẻ mãn nguyện","explanation":"怡然 (di nhiên – vui vẻ thư thái) + 自得 (tự đắc – tự thấy hài lòng) → thư thái vui vẻ, tự thấy mãn nguyện.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"老人怡然自得地钓鱼。","pinyin":"Lǎorén yíránzìdé de diàoyú.","vi":"Ông cụ ung dung tự tại ngồi câu cá."},{"type":"simple","zh":"他退休后在乡下过着怡然自得的生活。","pinyin":"Tā tuìxiū hòu zài xiāngxiaguò zhe yíránzìdé de shēnghuó.","vi":"Sau khi nghỉ hưu, ông ấy sống cuộc đời thư thái ở quê."},{"type":"compound","zh":"虽然收入不多，但是他们一家过得怡然自得。","pinyin":"Suīrán shōurù bù duō, dànshì tāmen yìjiā guòde yíránzìdé.","vi":"Tuy thu nhập không nhiều nhưng cả nhà họ sống ung dung mãn nguyện."}],"related":[{"hanzi":"悠然自得","pinyin":"yōuránzìdé","vi":"thong dong tự tại"},{"hanzi":"自得其乐","pinyin":"zìdéqílè","vi":"tự tìm niềm vui"},{"hanzi":"逍遥","pinyin":"xiāoyáo","vi":"tiêu dao"},{"hanzi":"惬意","pinyin":"qièyì","vi":"dễ chịu"}]},{"id":"姨","hanzi":"姨","pinyin":"yí","meaning_vi":"dì (chị em gái của mẹ); cô, dì (gọi phụ nữ cùng vai mẹ)","explanation":"姨 (di – dì) → chị em gái của mẹ; cũng dùng gọi thân mật phụ nữ trạc tuổi mẹ (阿姨).","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👩","examples":[{"type":"basic","zh":"小姨明天来我家。","pinyin":"Xiǎoyí míngtiān lái wǒ jiā.","vi":"Dì út mai đến nhà tôi."},{"type":"simple","zh":"我妈妈有两个姐姐，我叫她们大姨和二姨。","pinyin":"Wǒ māma yǒu liǎng gè jiějie, wǒ jiào tāmen dàyí hé èr yí.","vi":"Mẹ tôi có hai chị gái, tôi gọi là dì cả và dì hai."},{"type":"compound","zh":"因为姨就住在学校附近，所以我常去她家吃饭。","pinyin":"Yīnwèi yí jiù zhùzài xuéxiào fùjìn, suǒyǐ wǒ cháng qù tā jiā chīfàn.","vi":"Vì dì sống ngay gần trường nên tôi hay đến nhà dì ăn cơm."}],"related":[{"hanzi":"阿姨","pinyin":"āyí","vi":"cô, dì"},{"hanzi":"姨妈","pinyin":"yímā","vi":"dì (đã có chồng)"},{"hanzi":"姑姑","pinyin":"gūgu","vi":"cô (em/chị của bố)"},{"hanzi":"舅舅","pinyin":"jiùjiu","vi":"cậu"}]},{"id":"移交","hanzi":"移交","pinyin":"yíjiāo","meaning_vi":"chuyển giao, bàn giao","explanation":"移 (di – dời) + 交 (giao – giao cho) → chuyển và giao lại cho người/cơ quan khác phụ trách.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🤲","examples":[{"type":"basic","zh":"案件已移交法院。","pinyin":"Ànjiàn yǐ yíjiāo fǎyuàn.","vi":"Vụ án đã được chuyển giao cho tòa án."},{"type":"simple","zh":"离职前，他把工作移交给了同事。","pinyin":"Lízhí qián, tā bǎ gōngzuò yíjiāo gěile tóngshì.","vi":"Trước khi nghỉ việc, anh ấy bàn giao công việc cho đồng nghiệp."},{"type":"compound","zh":"一旦工程验收合格，就正式移交给使用单位。","pinyin":"Yídàn gōngchéng yànshōu hégé, jiù zhèngshì yíjiāo gěi shǐyòng dānwèi.","vi":"Một khi công trình nghiệm thu đạt, sẽ chính thức bàn giao cho đơn vị sử dụng."}],"related":[{"hanzi":"交接","pinyin":"jiāojiē","vi":"bàn giao"},{"hanzi":"转交","pinyin":"zhuǎnjiāo","vi":"chuyển giao"},{"hanzi":"接管","pinyin":"jiēguǎn","vi":"tiếp quản"},{"hanzi":"移送","pinyin":"yísòng","vi":"chuyển đến"}]},{"id":"移植","hanzi":"移植","pinyin":"yízhí","meaning_vi":"cấy ghép, di thực (cây)","explanation":"移 (di – dời) + 植 (thực – trồng) → dời cây đi trồng chỗ khác; trong y học là cấy ghép mô, cơ quan.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🫀","examples":[{"type":"basic","zh":"他做了肾移植手术。","pinyin":"Tā zuòle shèn yízhí shǒushù.","vi":"Ông ấy đã phẫu thuật ghép thận."},{"type":"simple","zh":"春天是移植树苗的好时候。","pinyin":"Chūntiān shì yízhí shùmiáo de hǎo shíhou.","vi":"Mùa xuân là thời điểm tốt để trồng dời cây con."},{"type":"compound","zh":"如果找不到合适的骨髓，移植就无法进行。","pinyin":"Rúguǒ zhǎobúdào héshì de gǔsuǐ, yízhí jiù wúfǎ jìnxíng.","vi":"Nếu không tìm được tủy xương phù hợp thì không thể tiến hành cấy ghép."}],"related":[{"hanzi":"器官","pinyin":"qìguān","vi":"cơ quan (nội tạng)"},{"hanzi":"捐献","pinyin":"juānxiàn","vi":"hiến tặng"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng"},{"hanzi":"嫁接","pinyin":"jiàjiē","vi":"ghép cây"}]},{"id":"遗弃","hanzi":"遗弃","pinyin":"yíqì","meaning_vi":"vứt bỏ, ruồng bỏ","explanation":"遗 (di – để lại) + 弃 (khí – bỏ) → bỏ rơi người hoặc vật mình có trách nhiệm.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚮","examples":[{"type":"basic","zh":"这只小狗被主人遗弃了。","pinyin":"Zhè zhī xiǎogǒu bèi zhǔrén yíqì le.","vi":"Chú chó con này bị chủ bỏ rơi."},{"type":"simple","zh":"遗弃老人是违法行为。","pinyin":"Yíqì lǎorén shì wéifǎ xíngwéi.","vi":"Bỏ rơi người già là hành vi vi phạm pháp luật."},{"type":"compound","zh":"虽然她小时候被遗弃过，但是养父母给了她很多爱。","pinyin":"Suīrán tā xiǎoshíhou bèi yíqì guò, dànshì yǎngfùmǔ gěile tā hěn duō ài.","vi":"Tuy hồi nhỏ cô ấy từng bị bỏ rơi nhưng bố mẹ nuôi đã cho cô rất nhiều yêu thương."}],"related":[{"hanzi":"抛弃","pinyin":"pāoqì","vi":"vứt bỏ"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"收养","pinyin":"shōuyǎng","vi":"nhận nuôi"},{"hanzi":"流浪","pinyin":"liúlàng","vi":"lang thang"}],"traditional":"遺棄"},{"id":"遗体","hanzi":"遗体","pinyin":"yítǐ","meaning_vi":"di thể, thi hài","explanation":"遗 (di – để lại) + 体 (thể – thân thể) → thân thể người đã khuất để lại; cách nói trang trọng.","hsk_level":"7-9","tags":["danh-tu"],"image":"⚱️","examples":[{"type":"basic","zh":"家属来认领遗体。","pinyin":"Jiāshǔ lái rènlǐng yítǐ.","vi":"Người nhà đến nhận thi hài."},{"type":"simple","zh":"人们排队向遗体告别。","pinyin":"Rénmen páiduì xiàng yítǐ gàobié.","vi":"Mọi người xếp hàng viếng thi hài."},{"type":"compound","zh":"根据他生前的愿望，遗体捐给了医学院。","pinyin":"Gēnjù tā shēngqián de yuànwàng, yítǐ juāngěile yīxuéyuàn.","vi":"Theo nguyện vọng lúc sinh thời, thi hài ông được hiến cho trường y."}],"related":[{"hanzi":"尸体","pinyin":"shītǐ","vi":"xác chết"},{"hanzi":"遗物","pinyin":"yíwù","vi":"di vật"},{"hanzi":"遗愿","pinyin":"yíyuàn","vi":"di nguyện"},{"hanzi":"葬礼","pinyin":"zànglǐ","vi":"tang lễ"}],"traditional":"遺體"},{"id":"遗物","hanzi":"遗物","pinyin":"yíwù","meaning_vi":"di vật, vật để lại","explanation":"遗 (di – để lại) + 物 (vật) → đồ vật người đã khuất hoặc thời xưa để lại.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎞️","examples":[{"type":"basic","zh":"这是爷爷的遗物。","pinyin":"Zhè shì yéye de yíwù.","vi":"Đây là di vật của ông nội."},{"type":"simple","zh":"她整理母亲的遗物时哭了。","pinyin":"Tā zhěnglǐ mǔqīn de yíwù shí kū le.","vi":"Cô ấy bật khóc khi sắp xếp di vật của mẹ."},{"type":"compound","zh":"虽然这块表已经不走了，但是作为父亲的遗物，他一直留着。","pinyin":"Suīrán zhè kuài biǎo yǐjīng bù zǒu le, dànshì zuòwéi fùqīn de yíwù, tā yìzhí liú zhe.","vi":"Tuy chiếc đồng hồ đã không chạy nữa nhưng là di vật của cha nên anh ấy vẫn giữ."}],"related":[{"hanzi":"遗产","pinyin":"yíchǎn","vi":"di sản"},{"hanzi":"遗体","pinyin":"yítǐ","vi":"thi hài"},{"hanzi":"纪念品","pinyin":"jìniànpǐn","vi":"vật kỷ niệm"},{"hanzi":"文物","pinyin":"wénwù","vi":"cổ vật"}],"traditional":"遺物"},{"id":"遗愿","hanzi":"遗愿","pinyin":"yíyuàn","meaning_vi":"di nguyện","explanation":"遗 (di – để lại) + 愿 (nguyện – mong muốn) → mong muốn mà người đã khuất để lại.","hsk_level":"7-9","tags":["danh-tu"],"image":"🕯️","examples":[{"type":"basic","zh":"我们完成了他的遗愿。","pinyin":"Wǒmen wánchéngle tā de yíyuàn.","vi":"Chúng tôi đã hoàn thành di nguyện của ông ấy."},{"type":"simple","zh":"按照奶奶的遗愿，骨灰撒进了大海。","pinyin":"Ànzhào nǎinai de yíyuàn, gǔhuī sǎ jìnle dàhǎi.","vi":"Theo di nguyện của bà, tro cốt được rải xuống biển."},{"type":"compound","zh":"为了实现父亲的遗愿，他放弃了工作回老家办学。","pinyin":"Wèile shíxiàn fùqīn de yíyuàn, tā fàngqìle gōngzuò huílǎojiā bànxué.","vi":"Để thực hiện di nguyện của cha, anh ấy bỏ việc về quê mở trường."}],"related":[{"hanzi":"遗嘱","pinyin":"yízhǔ","vi":"di chúc"},{"hanzi":"心愿","pinyin":"xīnyuàn","vi":"tâm nguyện"},{"hanzi":"遗言","pinyin":"yíyán","vi":"lời trăng trối"},{"hanzi":"愿望","pinyin":"yuànwàng","vi":"nguyện vọng"}],"traditional":"遺願"},{"id":"疑点","hanzi":"疑点","pinyin":"yídiǎn","meaning_vi":"điểm đáng ngờ, điểm nghi vấn","explanation":"疑 (nghi – ngờ) + 点 (điểm) → chỗ còn đáng nghi, chưa rõ ràng.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"这个案子疑点很多。","pinyin":"Zhè gè'àn zi yídiǎn hěn duō.","vi":"Vụ án này có nhiều điểm đáng ngờ."},{"type":"simple","zh":"警察发现他的证词里有几个疑点。","pinyin":"Jǐngchá fāxiàn tā de zhèngcí lǐ yǒu jǐ gè yídiǎn.","vi":"Cảnh sát phát hiện lời khai của hắn có vài điểm đáng ngờ."},{"type":"compound","zh":"只要还有疑点没查清，就不能轻易下结论。","pinyin":"Zhǐyào háiyǒu yídiǎn méi cháqīng, jiù bù néng qīngyì xià jiélùn.","vi":"Chỉ cần còn điểm nghi vấn chưa làm rõ thì không thể dễ dàng kết luận."}],"related":[{"hanzi":"疑问","pinyin":"yíwèn","vi":"nghi vấn"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"nghi ngờ"},{"hanzi":"线索","pinyin":"xiànsuǒ","vi":"manh mối"},{"hanzi":"可疑","pinyin":"kěyí","vi":"khả nghi"}],"traditional":"疑點"},{"id":"疑虑","hanzi":"疑虑","pinyin":"yílǜ","meaning_vi":"nghi ngại, băn khoăn, lo ngại","explanation":"疑 (nghi – ngờ) + 虑 (lự – lo nghĩ) → mối ngờ vực và lo lắng trong lòng.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🤔","examples":[{"type":"basic","zh":"他打消了我的疑虑。","pinyin":"Tā dǎxiāole wǒ de yílǜ.","vi":"Anh ấy xua tan nỗi băn khoăn của tôi."},{"type":"simple","zh":"很多人对这种新药还有疑虑。","pinyin":"Hěn duō rén duì zhè zhǒng xīn yào háiyǒu yílǜ.","vi":"Nhiều người vẫn còn nghi ngại về loại thuốc mới này."},{"type":"compound","zh":"如果你心里有疑虑，就直接问清楚吧。","pinyin":"Rúguǒ nǐ xīnlǐ yǒu yílǜ, jiù zhíjiē wèn qīngchu ba.","vi":"Nếu trong lòng bạn có băn khoăn thì cứ hỏi thẳng cho rõ."}],"related":[{"hanzi":"顾虑","pinyin":"gùlǜ","vi":"e ngại"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"hoài nghi"},{"hanzi":"担忧","pinyin":"dānyōu","vi":"lo lắng"},{"hanzi":"疑惑","pinyin":"yíhuò","vi":"nghi hoặc"}],"traditional":"疑慮"},{"id":"以至于","hanzi":"以至于","pinyin":"yǐzhìyú","meaning_vi":"đến nỗi, đến mức","explanation":"以 (dĩ – lấy, để) + 至于 (chí ư – đến mức) → nối vế sau chỉ kết quả do mức độ của vế trước gây ra.","hsk_level":"7-9","tags":["lien-tu"],"image":"➡️","examples":[{"type":"basic","zh":"他太紧张，以至于忘词了。","pinyin":"Tā tài jǐnzhāng, yǐzhìyú wàngcí le.","vi":"Anh ấy căng thẳng đến mức quên lời."},{"type":"simple","zh":"雨下得太大，以至于航班全部取消。","pinyin":"Yǔ xià de tài dà, yǐzhìyú hángbān quánbù qǔxiāo.","vi":"Mưa to đến mức tất cả chuyến bay đều bị hủy."},{"type":"compound","zh":"她看书看得太投入，以至于连饭都忘了吃。","pinyin":"Tā kànshū kàn de tài tóurù, yǐzhìyú lián fàn dōu wàngle chī.","vi":"Cô ấy đọc sách say mê đến nỗi quên cả ăn cơm."}],"related":[{"hanzi":"以至","pinyin":"yǐzhì","vi":"đến mức"},{"hanzi":"以致","pinyin":"yǐzhì","vi":"dẫn đến"},{"hanzi":"甚至","pinyin":"shènzhì","vi":"thậm chí"},{"hanzi":"所以","pinyin":"suǒyǐ","vi":"cho nên"}],"traditional":"以至於"},{"id":"矣","hanzi":"矣","pinyin":"yǐ","meaning_vi":"rồi, vậy (trợ từ cuối câu trong văn cổ)","explanation":"矣 (hĩ) → trợ từ cuối câu trong văn cổ, tương đương 了 hiện đại, biểu thị sự việc đã xảy ra hoặc khẳng định.","hsk_level":"7-9","tags":["tro-tu","ngon-ngu"],"image":"📜","examples":[{"type":"basic","zh":"悔之晚矣。","pinyin":"Huǐ zhī wǎn yǐ.","vi":"Hối thì đã muộn rồi."},{"type":"simple","zh":"此事已过去多年矣。","pinyin":"Cǐshì yǐ guòqù duōnián yǐ.","vi":"Việc này đã qua nhiều năm rồi."},{"type":"compound","zh":"如果现在还不努力，等到老了就悔之晚矣。","pinyin":"Rúguǒ xiànzài hái bù nǔlì, děngdào lǎole jiù huǐ zhī wǎn yǐ.","vi":"Nếu bây giờ còn không cố gắng thì đến lúc già hối hận cũng đã muộn."}],"related":[{"hanzi":"了","pinyin":"le","vi":"rồi"},{"hanzi":"也","pinyin":"yě","vi":"vậy (trợ từ cổ)"},{"hanzi":"焉","pinyin":"yān","vi":"vậy, ở đó (cổ)"},{"hanzi":"文言文","pinyin":"wényánwén","vi":"văn ngôn"}]},{"id":"倚","hanzi":"倚","pinyin":"yǐ","meaning_vi":"dựa, tựa; ỷ vào","explanation":"倚 (ỷ – dựa) → tựa thân vào vật gì; nghĩa bóng là cậy, ỷ vào (倚老卖老).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"她倚在门口看雨。","pinyin":"Tā yǐ zài ménkǒu kàn yǔ.","vi":"Cô ấy tựa cửa ngắm mưa."},{"type":"simple","zh":"他倚着栏杆，望着远处的大海。","pinyin":"Tā yǐzhe lángān, wàngzhe yuǎnchù de dàhǎi.","vi":"Anh ấy tựa lan can, ngắm biển xa."},{"type":"compound","zh":"虽然他年纪最大，但是从不倚老卖老。","pinyin":"Suīrán tā niánjì zuì dà, dànshì cóng bù yǐ lǎo mài lǎo.","vi":"Tuy lớn tuổi nhất nhưng ông ấy không bao giờ cậy già lên mặt."}],"related":[{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"靠","pinyin":"kào","vi":"tựa"},{"hanzi":"倚靠","pinyin":"yǐkào","vi":"dựa dẫm"},{"hanzi":"倚老卖老","pinyin":"yǐlǎomàilǎo","vi":"cậy già lên mặt"}]},{"id":"义工","hanzi":"义工","pinyin":"yìgōng","meaning_vi":"tình nguyện viên, công việc tình nguyện","explanation":"义 (nghĩa – việc nghĩa) + 工 (công – việc, người làm) → người làm việc không công vì lợi ích chung.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🙋","examples":[{"type":"basic","zh":"她周末去做义工。","pinyin":"Tā zhōumò qù zuò yìgōng.","vi":"Cuối tuần cô ấy đi làm tình nguyện."},{"type":"simple","zh":"很多大学生在博物馆当义工。","pinyin":"Hěn duōdà xuéshēng zài bówùguǎn dāng yìgōng.","vi":"Nhiều sinh viên làm tình nguyện viên ở bảo tàng."},{"type":"compound","zh":"虽然做义工没有报酬，但是他觉得很有意义。","pinyin":"Suīrán zuò yìgōng méiyǒu bàochou, dànshì tā juéde hěn yǒuyìyì.","vi":"Tuy làm tình nguyện không có thù lao nhưng anh ấy thấy rất ý nghĩa."}],"related":[{"hanzi":"志愿者","pinyin":"zhìyuànzhě","vi":"tình nguyện viên"},{"hanzi":"公益","pinyin":"gōngyì","vi":"công ích"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"义务","pinyin":"yìwù","vi":"nghĩa vụ"}],"traditional":"義工"},{"id":"议","hanzi":"议","pinyin":"yì","meaning_vi":"bàn bạc, bàn luận, đề nghị","explanation":"议 (nghị – bàn luận) → bàn bạc, nghị luận; thường làm thành tố như 议论, 会议, 建议.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗳️","examples":[{"type":"basic","zh":"此事容后再议。","pinyin":"Cǐshì róng hòu zài yì.","vi":"Việc này để sau sẽ bàn lại."},{"type":"simple","zh":"大家对这个方案议了一下午。","pinyin":"Dàjiā duì zhè gè fāng'àn yìle yí xiàwǔ.","vi":"Mọi người bàn bạc phương án này cả buổi chiều."},{"type":"compound","zh":"既然意见不统一，那就等经理回来再议吧。","pinyin":"Jìrán yìjiàn bù tǒngyī, nà jiù děng jīnglǐ huílái zài yì ba.","vi":"Đã không thống nhất ý kiến thì đợi giám đốc về rồi bàn tiếp."}],"related":[{"hanzi":"议论","pinyin":"yìlùn","vi":"bàn tán"},{"hanzi":"商议","pinyin":"shāngyì","vi":"thương lượng"},{"hanzi":"建议","pinyin":"jiànyì","vi":"đề nghị"},{"hanzi":"会议","pinyin":"huìyì","vi":"hội nghị"}],"traditional":"議"},{"id":"议会","hanzi":"议会","pinyin":"yìhuì","meaning_vi":"nghị viện, quốc hội","explanation":"议 (nghị – bàn bạc) + 会 (hội – hội đồng) → cơ quan lập pháp, nơi các nghị sĩ bàn bạc và thông qua luật.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"议会通过了新法案。","pinyin":"Yìhuì tōngguòle xīn fǎ'àn.","vi":"Nghị viện đã thông qua dự luật mới."},{"type":"simple","zh":"这个提案在议会引起了激烈争论。","pinyin":"Zhè gè tí'àn zài yìhuì yǐnqǐle jīliè zhēnglùn.","vi":"Đề án này gây tranh cãi gay gắt tại nghị viện."},{"type":"compound","zh":"如果议会不批准预算，政府就无法执行计划。","pinyin":"Rúguǒ yìhuì bù pīzhǔn yùsuàn, zhèngfǔ jiù wúfǎ zhíxíng jìhuà.","vi":"Nếu nghị viện không phê chuẩn ngân sách thì chính phủ không thể thực hiện kế hoạch."}],"related":[{"hanzi":"议员","pinyin":"yìyuán","vi":"nghị sĩ"},{"hanzi":"国会","pinyin":"Guóhuì","vi":"quốc hội"},{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"},{"hanzi":"法案","pinyin":"fǎ'àn","vi":"dự luật"}],"traditional":"議會"},{"id":"议员","hanzi":"议员","pinyin":"yìyuán","meaning_vi":"nghị sĩ, đại biểu nghị viện","explanation":"议 (nghị – bàn bạc) + 员 (viên – thành viên) → thành viên của nghị viện.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"他当选为议员。","pinyin":"Tā dāngxuǎn wéi yìyuán.","vi":"Ông ấy đắc cử nghị sĩ."},{"type":"simple","zh":"几位议员对新政策提出了质疑。","pinyin":"Jǐ wèi yìyuán duì xīn zhèngcè tíchūle zhìyí.","vi":"Vài nghị sĩ đã chất vấn chính sách mới."},{"type":"compound","zh":"虽然这位议员很年轻，但是在选民中威望很高。","pinyin":"Suīrán zhè wèi yìyuán hěn niánqīng, dànshì zài xuǎnmín zhōng wēiwàng hěn gāo.","vi":"Tuy vị nghị sĩ này còn trẻ nhưng rất có uy tín với cử tri."}],"related":[{"hanzi":"议会","pinyin":"yìhuì","vi":"nghị viện"},{"hanzi":"代表","pinyin":"dàibiǎo","vi":"đại biểu"},{"hanzi":"选民","pinyin":"xuǎnmín","vi":"cử tri"},{"hanzi":"政客","pinyin":"zhèngkè","vi":"chính khách"}],"traditional":"議員"},{"id":"屹立","hanzi":"屹立","pinyin":"yìlì","meaning_vi":"sừng sững, đứng vững","explanation":"屹 (ngật – cao vút, vững) + 立 (lập – đứng) → đứng sừng sững, vững chãi không lay chuyển.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗼","examples":[{"type":"basic","zh":"高塔屹立在山顶。","pinyin":"Gāotǎ yìlì zài shāndǐng.","vi":"Ngọn tháp cao sừng sững trên đỉnh núi."},{"type":"simple","zh":"这座古桥屹立了几百年。","pinyin":"Zhè zuò gǔ qiáo yìlìle jǐ bǎinián.","vi":"Cây cầu cổ này đứng vững mấy trăm năm."},{"type":"compound","zh":"尽管经历了多次地震，这座寺庙依然屹立不倒。","pinyin":"Jǐnguǎn jīnglìle duōcì dìzhèn, zhè zuò sìmiào yīrán yìlì bù dǎo.","vi":"Dù trải qua nhiều trận động đất, ngôi chùa này vẫn đứng vững không đổ."}],"related":[{"hanzi":"耸立","pinyin":"sǒnglì","vi":"sừng sững"},{"hanzi":"矗立","pinyin":"chùlì","vi":"đứng thẳng"},{"hanzi":"挺立","pinyin":"tǐnglì","vi":"đứng thẳng"},{"hanzi":"倒塌","pinyin":"dǎotā","vi":"sụp đổ"}]},{"id":"异性","hanzi":"异性","pinyin":"yìxìng","meaning_vi":"người khác giới; khác tính chất","explanation":"异 (dị – khác) + 性 (tính – giới tính, tính chất) → khác giới tính; cũng chỉ tính chất khác nhau.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"⚧️","examples":[{"type":"basic","zh":"他很少和异性说话。","pinyin":"Tā hěn shǎo hé yìxìng shuōhuà.","vi":"Anh ấy rất ít nói chuyện với người khác giới."},{"type":"simple","zh":"青春期的孩子开始对异性感兴趣。","pinyin":"Qīngchūnqī de háizi kāishǐ duì yìxìng gǎnxìngqù.","vi":"Trẻ tuổi dậy thì bắt đầu quan tâm đến người khác giới."},{"type":"compound","zh":"虽然他们是异性朋友，但是关系很纯洁。","pinyin":"Suīrán tāmen shì yìxìng péngyou, dànshì guānxi hěn chúnjié.","vi":"Tuy họ là bạn khác giới nhưng quan hệ rất trong sáng."}],"related":[{"hanzi":"同性","pinyin":"tóngxìng","vi":"đồng giới"},{"hanzi":"性别","pinyin":"xìngbié","vi":"giới tính"},{"hanzi":"异性恋","pinyin":"yìxìngliàn","vi":"dị tính luyến ái"},{"hanzi":"男女","pinyin":"nánnǚ","vi":"nam nữ"}],"traditional":"異性"},{"id":"异议","hanzi":"异议","pinyin":"yìyì","meaning_vi":"dị nghị, ý kiến phản đối","explanation":"异 (dị – khác) + 议 (nghị – ý kiến) → ý kiến khác, phản đối.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"✋","examples":[{"type":"basic","zh":"谁有异议请举手。","pinyin":"Shéi yǒu yìyì qǐng jǔshǒu.","vi":"Ai có ý kiến phản đối xin giơ tay."},{"type":"simple","zh":"对这个决定，大家都没有异议。","pinyin":"Duì zhè gè juédìng, dàjiā dōu méiyǒu yìyì.","vi":"Về quyết định này, mọi người đều không có ý kiến phản đối."},{"type":"compound","zh":"如果对结果有异议，就可以在七天内提出申诉。","pinyin":"Rúguǒ duì jiéguǒ yǒu yìyì, jiù kěyǐ zài qī tiān nèi tíchū shēnsù.","vi":"Nếu có ý kiến phản đối kết quả thì có thể khiếu nại trong vòng bảy ngày."}],"related":[{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"},{"hanzi":"争议","pinyin":"zhēngyì","vi":"tranh cãi"},{"hanzi":"意见","pinyin":"yìjiàn","vi":"ý kiến"},{"hanzi":"同意","pinyin":"tóngyì","vi":"đồng ý"}],"traditional":"異議"},{"id":"抑郁","hanzi":"抑郁","pinyin":"yìyù","meaning_vi":"trầm cảm, u uất, buồn bực","explanation":"抑 (ức – đè nén) + 郁 (uất – uất kết) → tâm trạng bị đè nén, u uất; 抑郁症 là bệnh trầm cảm.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🌧️","examples":[{"type":"basic","zh":"她最近心情很抑郁。","pinyin":"Tā zuìjìn xīnqíng hěn yìyù.","vi":"Gần đây tâm trạng cô ấy rất u uất."},{"type":"simple","zh":"长期压力过大容易导致抑郁。","pinyin":"Chángqī yālìguò dà róngyì dǎozhì yìyù.","vi":"Áp lực quá lớn kéo dài dễ dẫn đến trầm cảm."},{"type":"compound","zh":"如果长时间感到抑郁，就应该及时看心理医生。","pinyin":"Rúguǒ cháng shíjiān gǎndào yìyù, jiù yīnggāi jíshí kàn xīnlǐ yīshēng.","vi":"Nếu cảm thấy u uất trong thời gian dài thì nên đi gặp bác sĩ tâm lý kịp thời."}],"related":[{"hanzi":"抑郁症","pinyin":"yìyùzhèng","vi":"bệnh trầm cảm"},{"hanzi":"忧郁","pinyin":"yōuyù","vi":"u buồn"},{"hanzi":"焦虑","pinyin":"jiāolǜ","vi":"lo âu"},{"hanzi":"开朗","pinyin":"kāilǎng","vi":"vui vẻ cởi mở"}],"traditional":"抑鬱"},{"id":"抑制","hanzi":"抑制","pinyin":"yìzhì","meaning_vi":"kìm hãm, ức chế, kiềm chế","explanation":"抑 (ức – đè xuống) + 制 (chế – khống chế) → đè nén và khống chế, không cho phát triển.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛑","examples":[{"type":"basic","zh":"他抑制不住激动。","pinyin":"Tā yìzhì búzhù jīdòng.","vi":"Anh ấy không kìm được xúc động."},{"type":"simple","zh":"这种药可以抑制细菌生长。","pinyin":"Zhè zhǒng yào kěyǐ yìzhì xìjūn shēngzhǎng.","vi":"Loại thuốc này có thể ức chế vi khuẩn phát triển."},{"type":"compound","zh":"政府提高了利率，以便抑制房价过快上涨。","pinyin":"Zhèngfǔ tígāole lìlǜ, yǐbiàn yìzhì fángjiàguò kuài shàngzhǎng.","vi":"Chính phủ tăng lãi suất để kìm hãm giá nhà tăng quá nhanh."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"kiểm soát"},{"hanzi":"压抑","pinyin":"yāyì","vi":"đè nén"},{"hanzi":"克制","pinyin":"kèzhì","vi":"kiềm chế"},{"hanzi":"促进","pinyin":"cùjìn","vi":"thúc đẩy"}]},{"id":"译","hanzi":"译","pinyin":"yì","meaning_vi":"dịch, phiên dịch","explanation":"译 (dịch) → chuyển từ ngôn ngữ này sang ngôn ngữ khác.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"🌐","examples":[{"type":"basic","zh":"这本书译成了中文。","pinyin":"Zhè běn shū yì chéngle Zhōngwén.","vi":"Cuốn sách này đã được dịch sang tiếng Trung."},{"type":"simple","zh":"这首诗由一位著名作家所译。","pinyin":"Zhè shǒu shī yóu yí wèi zhùmíng zuòjiā suǒ yì.","vi":"Bài thơ này do một nhà văn nổi tiếng dịch."},{"type":"compound","zh":"虽然原文很难懂，但是他译得非常通顺。","pinyin":"Suīrán yuánwén hěn nándǒng, dànshì tā yì de fēicháng tōngshùn.","vi":"Tuy nguyên văn rất khó hiểu nhưng anh ấy dịch rất trôi chảy."}],"related":[{"hanzi":"翻译","pinyin":"fānyì","vi":"phiên dịch"},{"hanzi":"译者","pinyin":"yìzhě","vi":"dịch giả"},{"hanzi":"口译","pinyin":"kǒuyì","vi":"dịch nói"},{"hanzi":"笔译","pinyin":"bǐyì","vi":"dịch viết"}],"traditional":"譯"},{"id":"易拉罐","hanzi":"易拉罐","pinyin":"yìlāguàn","meaning_vi":"lon có nắp giật (lon nước ngọt, bia)","explanation":"易 (dịch – dễ) + 拉 (lạp – kéo) + 罐 (quán – lon, hũ) → lon kéo nắp dễ mở.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🥫","examples":[{"type":"basic","zh":"请把易拉罐扔进回收箱。","pinyin":"Qǐng bǎ yìlāguàn rēng jìn huíshōu xiāng.","vi":"Vui lòng bỏ lon vào thùng tái chế."},{"type":"simple","zh":"他喝完饮料，把易拉罐踩扁了。","pinyin":"Tā hē wán yǐnliào, bǎ yìlāguàn cǎi biǎn le.","vi":"Uống xong nước, anh ấy giẫm bẹp cái lon."},{"type":"compound","zh":"因为易拉罐可以回收，所以奶奶总是把它们攒起来卖。","pinyin":"Yīnwèi yìlāguàn kěyǐ huíshōu, suǒyǐ nǎinai zǒngshì bǎ tāmen zǎn qǐlái mài.","vi":"Vì lon có thể tái chế nên bà luôn gom lại để bán."}],"related":[{"hanzi":"罐头","pinyin":"guàntou","vi":"đồ hộp"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"đồ uống"},{"hanzi":"回收","pinyin":"huíshōu","vi":"tái chế"},{"hanzi":"瓶子","pinyin":"píngzi","vi":"chai"}]},{"id":"疫苗","hanzi":"疫苗","pinyin":"yìmiáo","meaning_vi":"vắc-xin","explanation":"疫 (dịch – bệnh dịch) + 苗 (miêu – mầm) → chế phẩm từ mầm bệnh đã làm yếu để tạo miễn dịch.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💉","examples":[{"type":"basic","zh":"孩子今天打疫苗。","pinyin":"Háizi jīntiān dǎyìmiáo.","vi":"Hôm nay con đi tiêm vắc-xin."},{"type":"simple","zh":"科学家正在研发新的流感疫苗。","pinyin":"Kēxuéjiā zhèngzài yánfā xīn de liúgǎn yìmiáo.","vi":"Các nhà khoa học đang nghiên cứu vắc-xin cúm mới."},{"type":"compound","zh":"只要按时接种疫苗，就能大大降低感染风险。","pinyin":"Zhǐyào ànshí jiēzhòng yìmiáo, jiù néng dàdà jiàngdī gǎnrǎn fēngxiǎn.","vi":"Chỉ cần tiêm vắc-xin đúng hạn là có thể giảm mạnh nguy cơ lây nhiễm."}],"related":[{"hanzi":"接种","pinyin":"jiēzhǒng","vi":"tiêm chủng"},{"hanzi":"打针","pinyin":"dǎzhēn","vi":"tiêm"},{"hanzi":"免疫","pinyin":"miǎnyì","vi":"miễn dịch"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"}]},{"id":"益处","hanzi":"益处","pinyin":"yìchu","meaning_vi":"lợi ích, chỗ tốt","explanation":"益 (ích – lợi ích) + 处 (xứ – chỗ) → chỗ có lợi, điều tốt.","hsk_level":"7-9","tags":["danh-tu"],"image":"👍","examples":[{"type":"basic","zh":"运动对身体有益处。","pinyin":"Yùndòng duì shēntǐ yǒuyìchu.","vi":"Vận động có lợi cho cơ thể."},{"type":"simple","zh":"多读书的益处是显而易见的。","pinyin":"Duō dúshū de yìchu shì xiǎn'éryìjiàn de.","vi":"Lợi ích của việc đọc nhiều sách là điều hiển nhiên."},{"type":"compound","zh":"虽然熬夜工作效率高，但是对健康毫无益处。","pinyin":"Suīrán áoyè gōngzuò xiàolǜ gāo, dànshì duì jiànkāng háowú yìchu.","vi":"Tuy thức khuya làm việc hiệu quả cao nhưng chẳng có lợi gì cho sức khỏe."}],"related":[{"hanzi":"好处","pinyin":"hǎochu","vi":"lợi ích"},{"hanzi":"利益","pinyin":"lìyì","vi":"lợi ích"},{"hanzi":"有益","pinyin":"yǒuyì","vi":"có ích"},{"hanzi":"坏处","pinyin":"huàichu","vi":"tác hại"}],"traditional":"益處"},{"id":"意料之外","hanzi":"意料之外","pinyin":"yìliào-zhīwài","meaning_vi":"ngoài dự đoán, bất ngờ","explanation":"意料 (ý liệu – dự liệu) + 之外 (chi ngoại – ở ngoài) → nằm ngoài điều đã dự liệu.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😮","examples":[{"type":"basic","zh":"结果完全在意料之外。","pinyin":"Jiéguǒ wánquán zài yìliàozhīwài.","vi":"Kết quả hoàn toàn nằm ngoài dự đoán."},{"type":"simple","zh":"他会来参加婚礼，真是意料之外。","pinyin":"Tā huì lái cānjiā hūnlǐ, zhēn shì yìliàozhīwài.","vi":"Anh ấy đến dự đám cưới, thật là bất ngờ."},{"type":"compound","zh":"虽然比赛结果在意料之外，但是大家都心服口服。","pinyin":"Suīrán bǐsài jiéguǒ zài yìliàozhīwài, dànshì dàjiā dōu xīnfú kǒufú.","vi":"Tuy kết quả trận đấu nằm ngoài dự đoán nhưng ai cũng tâm phục khẩu phục."}],"related":[{"hanzi":"意料之中","pinyin":"yìliàozhīzhōng","vi":"trong dự đoán"},{"hanzi":"出乎意料","pinyin":"chūhūyìliào","vi":"ngoài dự kiến"},{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"预料","pinyin":"yùliào","vi":"dự liệu"}]},{"id":"溢","hanzi":"溢","pinyin":"yì","meaning_vi":"tràn, trào ra","explanation":"溢 (dật – tràn) → nước đầy tràn ra ngoài; nghĩa bóng là tràn đầy, quá mức như 洋溢, 溢价.","hsk_level":"7-9","tags":["dong-tu"],"image":"🫗","examples":[{"type":"basic","zh":"水从杯子里溢出来了。","pinyin":"Shuǐ cóng bēizi lǐ yì chūlái le.","vi":"Nước tràn ra khỏi cốc rồi."},{"type":"simple","zh":"锅里的牛奶煮开后溢了一灶台。","pinyin":"Guō lǐ de niúnǎi zhǔkāi hòu yìle yí zàotái.","vi":"Sữa trong nồi sôi lên trào ra khắp bếp."},{"type":"compound","zh":"如果水加得太满，煮开的时候就会溢出来。","pinyin":"Rúguǒ shuǐ jiā de tài mǎn, zhǔkāi de shíhou jiù huì yì chūlái.","vi":"Nếu đổ nước quá đầy thì lúc sôi sẽ trào ra."}],"related":[{"hanzi":"洋溢","pinyin":"yángyì","vi":"tràn đầy"},{"hanzi":"溢出","pinyin":"yìchū","vi":"tràn ra"},{"hanzi":"满","pinyin":"mǎn","vi":"đầy"},{"hanzi":"流","pinyin":"liú","vi":"chảy"}]},{"id":"因人而异","hanzi":"因人而异","pinyin":"yīnrén-éryì","meaning_vi":"tùy người mà khác, mỗi người mỗi khác","explanation":"因 (nhân – dựa vào) + 人 (nhân – người) + 而 (nhi – mà) + 异 (dị – khác) → tùy theo từng người mà khác nhau.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🧑‍🤝‍🧑","examples":[{"type":"basic","zh":"效果因人而异。","pinyin":"Xiàoguǒ yīnrén'éryì.","vi":"Hiệu quả tùy từng người."},{"type":"simple","zh":"饮食口味往往因人而异。","pinyin":"Yǐnshí kǒuwèi wǎngwǎng yīnrén'éryì.","vi":"Khẩu vị ăn uống thường mỗi người mỗi khác."},{"type":"compound","zh":"虽然这种药很有效，但是副作用因人而异。","pinyin":"Suīrán zhè zhǒng yào hěn yǒuxiào, dànshì fùzuòyòng yīnrén'éryì.","vi":"Tuy loại thuốc này rất hiệu quả nhưng tác dụng phụ thì tùy từng người."}],"related":[{"hanzi":"因材施教","pinyin":"yīncáishījiào","vi":"dạy theo năng lực"},{"hanzi":"各不相同","pinyin":"gèbùxiāngtóng","vi":"mỗi cái mỗi khác"},{"hanzi":"差异","pinyin":"chāyì","vi":"sự khác biệt"},{"hanzi":"因地制宜","pinyin":"yīndìzhìyí","vi":"tùy nơi mà làm"}],"traditional":"因人而異"},{"id":"阴暗","hanzi":"阴暗","pinyin":"yīn'àn","meaning_vi":"u ám, tối tăm, đen tối","explanation":"阴 (âm – râm, tối) + 暗 (ám – tối) → tối tăm, thiếu ánh sáng; nghĩa bóng chỉ mặt đen tối, tiêu cực như 阴暗面, 阴暗心理.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌑","examples":[{"type":"basic","zh":"地下室很阴暗。","pinyin":"Dìxiàshì hěn yīn'àn.","vi":"Tầng hầm rất tối tăm."},{"type":"simple","zh":"他住在一间阴暗潮湿的小屋里。","pinyin":"Tā zhùzài yì jiān yīn'àn cháoshī de xiǎowū lǐ.","vi":"Anh ấy sống trong một căn phòng nhỏ tối tăm, ẩm thấp."},{"type":"compound","zh":"即使社会有阴暗的一面，我们也要相信善良。","pinyin":"Jíshǐ shèhuì yǒu yīn'àn de yímiàn, wǒmen yě yào xiāngxìn shànliáng.","vi":"Dù xã hội có mặt tối, chúng ta vẫn phải tin vào lòng tốt."}],"related":[{"hanzi":"阴沉","pinyin":"yīnchén","vi":"u ám"},{"hanzi":"黑暗","pinyin":"hēi'àn","vi":"tối tăm"},{"hanzi":"昏暗","pinyin":"hūn'àn","vi":"lờ mờ"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"sáng sủa"}],"traditional":"陰暗"},{"id":"阴性","hanzi":"阴性","pinyin":"yīnxìng","meaning_vi":"âm tính; giống cái (ngữ pháp)","explanation":"阴 (âm) + 性 (tính – tính chất) → tính âm; dùng cho kết quả xét nghiệm không có mầm bệnh, hoặc giống cái trong ngữ pháp.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🧪","examples":[{"type":"basic","zh":"检查结果是阴性。","pinyin":"Jiǎnchá jiéguǒ shì yīnxìng.","vi":"Kết quả kiểm tra là âm tính."},{"type":"simple","zh":"他的核酸检测结果呈阴性。","pinyin":"Tā de hésuānjiǎncè jiéguǒ chéngyīnxìng.","vi":"Kết quả xét nghiệm axit nucleic của anh ấy âm tính."},{"type":"compound","zh":"只有检测结果为阴性，才能进医院探望病人。","pinyin":"Zhǐyǒu jiǎncè jiéguǒ wéi yīnxìng, cáinéng jìn yīyuàn tànwàng bìngrén.","vi":"Chỉ khi kết quả xét nghiệm âm tính mới được vào bệnh viện thăm bệnh nhân."}],"related":[{"hanzi":"阳性","pinyin":"yángxìng","vi":"dương tính"},{"hanzi":"检测","pinyin":"jiǎncè","vi":"xét nghiệm"},{"hanzi":"化验","pinyin":"huàyàn","vi":"xét nghiệm"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"kết quả"}],"traditional":"陰性"},{"id":"殷勤","hanzi":"殷勤","pinyin":"yīnqín","meaning_vi":"ân cần, niềm nở, chu đáo","explanation":"殷 (ân – sâu đậm) + 勤 (cần – siêng) → tiếp đãi chu đáo, nhiệt tình; 献殷勤 là cố ý chiều chuộng để lấy lòng.","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"🍵","examples":[{"type":"basic","zh":"服务员很殷勤。","pinyin":"Fúwùyuán hěn yīnqín.","vi":"Nhân viên phục vụ rất niềm nở."},{"type":"simple","zh":"主人殷勤地给客人倒茶。","pinyin":"Zhǔrén yīnqín de gěi kèrén dào chá.","vi":"Chủ nhà ân cần rót trà cho khách."},{"type":"compound","zh":"因为他想追求她，所以每天都对她大献殷勤。","pinyin":"Yīnwèi tā xiǎng zhuīqiú tā, suǒyǐ měitiān dōu duì tā dà xiànyīnqín.","vi":"Vì muốn theo đuổi cô ấy nên ngày nào anh ta cũng ra sức chiều chuộng cô."}],"related":[{"hanzi":"献殷勤","pinyin":"xiànyīnqín","vi":"lấy lòng"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"周到","pinyin":"zhōudào","vi":"chu đáo"},{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"}]},{"id":"银幕","hanzi":"银幕","pinyin":"yínmù","meaning_vi":"màn bạc, màn ảnh (điện ảnh)","explanation":"银 (ngân – bạc) + 幕 (mạc – tấm màn) → tấm màn chiếu phim màu bạc; nghĩa rộng chỉ điện ảnh.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"她第一次登上银幕。","pinyin":"Tā dìyīcì dēngshàng yínmù.","vi":"Lần đầu tiên cô ấy lên màn bạc."},{"type":"simple","zh":"这部小说被搬上了银幕。","pinyin":"Zhè bù xiǎoshuō bèi bān shàngle yínmù.","vi":"Cuốn tiểu thuyết này đã được chuyển thể lên màn ảnh."},{"type":"compound","zh":"虽然他在银幕上很凶，但是生活中非常温和。","pinyin":"Suīrán tā zài yínmù shang hěn xiōng, dànshì shēnghuó zhōng fēicháng wēnhé.","vi":"Tuy trên màn ảnh anh ấy rất dữ nhưng ngoài đời lại rất hiền hòa."}],"related":[{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"},{"hanzi":"荧幕","pinyin":"yíngmù","vi":"màn ảnh"},{"hanzi":"电影","pinyin":"diànyǐng","vi":"phim điện ảnh"},{"hanzi":"影星","pinyin":"yǐngxīng","vi":"ngôi sao điện ảnh"}],"traditional":"銀幕"},{"id":"引发","hanzi":"引发","pinyin":"yǐnfā","meaning_vi":"gây ra, dẫn đến, châm ngòi","explanation":"引 (dẫn – kéo, dẫn) + 发 (phát – phát ra) → làm nảy sinh, kích hoạt một sự việc, thường là điều tiêu cực.","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"这件事引发了争论。","pinyin":"Zhè jiàn shì yǐnfāle zhēnglùn.","vi":"Việc này đã gây ra tranh cãi."},{"type":"simple","zh":"一根烟头引发了一场森林大火。","pinyin":"Yìgēn yāntóu yǐnfāle yì chǎng sēnlín dàhuǒ.","vi":"Một mẩu thuốc lá đã gây ra trận cháy rừng lớn."},{"type":"compound","zh":"如果长期睡眠不足，就可能引发各种疾病。","pinyin":"Rúguǒ chángqī shuìmián bùzú, jiù kěnéng yǐnfā gèzhǒng jíbìng.","vi":"Nếu thiếu ngủ lâu ngày thì có thể dẫn đến đủ loại bệnh."}],"related":[{"hanzi":"引起","pinyin":"yǐnqǐ","vi":"gây ra"},{"hanzi":"导致","pinyin":"dǎozhì","vi":"dẫn đến"},{"hanzi":"触发","pinyin":"chùfā","vi":"kích hoạt"},{"hanzi":"造成","pinyin":"zàochéng","vi":"gây nên"}],"traditional":"引發"},{"id":"引经据典","hanzi":"引经据典","pinyin":"yǐnjīng-jùdiǎn","meaning_vi":"trích dẫn kinh điển, dẫn chứng sách xưa","explanation":"引 (dẫn – trích) + 经 (kinh – kinh sách) + 据 (cứ – dựa vào) + 典 (điển – điển tích) → dẫn kinh sách, dựa vào điển tích làm luận cứ khi nói hay viết.","hsk_level":"7-9","tags":["thanh-ngu","ngon-ngu"],"image":"📚","examples":[{"type":"basic","zh":"他说话爱引经据典。","pinyin":"Tā shuōhuà ài yǐnjīngjùdiǎn.","vi":"Anh ấy nói chuyện hay trích dẫn kinh điển."},{"type":"simple","zh":"教授在讲座中不停地引经据典。","pinyin":"Jiàoshòu zài jiǎngzuò zhōng bùtíng de yǐnjīngjùdiǎn.","vi":"Giáo sư liên tục trích dẫn kinh điển trong buổi giảng."},{"type":"compound","zh":"虽然他的文章引经据典，但是读起来一点也不枯燥。","pinyin":"Suīrán tā de wénzhāng yǐnjīngjùdiǎn, dànshì dú qǐlái yìdiǎn yě bù kūzào.","vi":"Tuy bài viết của anh ấy trích dẫn nhiều kinh điển nhưng đọc không hề khô khan."}],"related":[{"hanzi":"旁征博引","pinyin":"pángzhēngbóyǐn","vi":"dẫn chứng rộng rãi"},{"hanzi":"引用","pinyin":"yǐnyòng","vi":"trích dẫn"},{"hanzi":"经典","pinyin":"jīngdiǎn","vi":"kinh điển"},{"hanzi":"典故","pinyin":"diǎngù","vi":"điển cố"}],"traditional":"引經據典"},{"id":"引入","hanzi":"引入","pinyin":"yǐnrù","meaning_vi":"đưa vào, du nhập, áp dụng","explanation":"引 (dẫn – dẫn dắt) + 入 (nhập – vào) → dẫn vào, đưa vào (công nghệ, cơ chế, khái niệm mới…).","hsk_level":"7-9","tags":["dong-tu"],"image":"📥","examples":[{"type":"basic","zh":"公司引入了新技术。","pinyin":"Gōngsī yǐnrùle xīnjìshù.","vi":"Công ty đã đưa vào công nghệ mới."},{"type":"simple","zh":"学校今年引入了一套新的管理系统。","pinyin":"Xuéxiào jīnnián yǐnrùle yítào xīn de guǎnlǐ xìtǒng.","vi":"Năm nay trường đã đưa vào một hệ thống quản lý mới."},{"type":"compound","zh":"一旦引入竞争机制，服务质量就会提高。","pinyin":"Yídàn yǐnrù jìngzhēng jīzhì, fúwù zhìliàng jiù huì tígāo.","vi":"Một khi đưa cơ chế cạnh tranh vào thì chất lượng dịch vụ sẽ được nâng cao."}],"related":[{"hanzi":"引进","pinyin":"yǐnjìn","vi":"du nhập"},{"hanzi":"导入","pinyin":"dǎorù","vi":"đưa vào"},{"hanzi":"输入","pinyin":"shūrù","vi":"nhập vào"},{"hanzi":"引出","pinyin":"yǐnchū","vi":"dẫn ra"}]},{"id":"引用","hanzi":"引用","pinyin":"yǐnyòng","meaning_vi":"trích dẫn, dẫn chứng","explanation":"引 (dẫn – kéo, dẫn) + 用 (dụng – dùng) → lấy lời nói, câu văn của người khác dùng vào bài của mình; nghĩa cũ là tiến cử, bổ nhiệm người.","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"💬","examples":[{"type":"basic","zh":"他引用了一句名言。","pinyin":"Tā yǐnyòngle yíjù míngyán.","vi":"Anh ấy trích dẫn một câu danh ngôn."},{"type":"simple","zh":"论文里引用的资料必须注明出处。","pinyin":"Lùnwén lǐ yǐnyòng de zīliào bìxū zhùmíng chūchù.","vi":"Tài liệu trích dẫn trong luận văn phải ghi rõ nguồn."},{"type":"compound","zh":"如果引用别人的观点不注明来源，就算抄袭。","pinyin":"Rúguǒ yǐnyòng biérén de guāndiǎn bú zhùmíng láiyuán, jiùsuàn chāoxí.","vi":"Nếu trích dẫn quan điểm của người khác mà không ghi nguồn thì bị coi là đạo văn."}],"related":[{"hanzi":"引文","pinyin":"yǐnwén","vi":"câu trích dẫn"},{"hanzi":"引述","pinyin":"yǐnshù","vi":"thuật lại"},{"hanzi":"援引","pinyin":"yuányǐn","vi":"viện dẫn"},{"hanzi":"出处","pinyin":"chūchù","vi":"xuất xứ"}]},{"id":"引诱","hanzi":"引诱","pinyin":"yǐnyòu","meaning_vi":"dụ dỗ, cám dỗ, lôi kéo","explanation":"引 (dẫn – kéo) + 诱 (dụ – dụ dỗ) → dùng lợi ích hay thứ hấp dẫn để lôi kéo người khác, thường là làm điều xấu.","hsk_level":"7-9","tags":["dong-tu"],"image":"🪤","examples":[{"type":"basic","zh":"别被金钱引诱了。","pinyin":"Bié bèi jīnqián yǐnyòu le.","vi":"Đừng để tiền bạc cám dỗ."},{"type":"simple","zh":"骗子用高额回报引诱老人投资。","pinyin":"Piànzi yòng gāo'é huíbào yǐnyòu lǎorén tóuzī.","vi":"Kẻ lừa đảo dùng lợi nhuận cao để dụ người già đầu tư."},{"type":"compound","zh":"即使别人用钱引诱他，他也不会出卖朋友。","pinyin":"Jíshǐ biérén yòngqián yǐnyòu tā, tā yě bú huì chūmài péngyou.","vi":"Dù người khác dùng tiền dụ dỗ, anh ấy cũng không bán đứng bạn bè."}],"related":[{"hanzi":"诱惑","pinyin":"yòuhuò","vi":"cám dỗ"},{"hanzi":"勾引","pinyin":"gōuyǐn","vi":"quyến rũ, dụ dỗ"},{"hanzi":"引导","pinyin":"yǐndǎo","vi":"dẫn dắt"},{"hanzi":"诱饵","pinyin":"yòu'ěr","vi":"mồi nhử"}],"traditional":"引誘"},{"id":"饮水","hanzi":"饮水","pinyin":"yǐnshuǐ","meaning_vi":"nước uống; uống nước","explanation":"饮 (ẩm – uống) + 水 (thủy – nước) → nước để uống, việc uống nước; thành ngữ 饮水思源 là uống nước nhớ nguồn.","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"🚰","examples":[{"type":"basic","zh":"山区饮水很困难。","pinyin":"Shānqū yǐnshuǐ hěn kùnnan.","vi":"Ở vùng núi, có nước uống rất khó khăn."},{"type":"simple","zh":"政府帮助村民解决了饮水问题。","pinyin":"Zhèngfǔ bāngzhù cūnmín jiějuéle yǐnshuǐ wèntí.","vi":"Chính quyền đã giúp dân làng giải quyết vấn đề nước uống."},{"type":"compound","zh":"因为当地饮水不卫生，所以很多孩子经常生病。","pinyin":"Yīnwèi dāngdì yǐnshuǐ bú wèishēng, suǒyǐ hěn duō háizi jīngcháng shēngbìng.","vi":"Vì nước uống ở địa phương không hợp vệ sinh nên nhiều trẻ em hay bị ốm."}],"related":[{"hanzi":"饮水思源","pinyin":"yǐnshuǐsīyuán","vi":"uống nước nhớ nguồn"},{"hanzi":"饮用水","pinyin":"yǐnyòngshuǐ","vi":"nước uống"},{"hanzi":"喝水","pinyin":"hēshuǐ","vi":"uống nước"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"đồ uống"}],"traditional":"飲水"},{"id":"饮用水","hanzi":"饮用水","pinyin":"yǐnyòngshuǐ","meaning_vi":"nước uống, nước ăn uống","explanation":"饮 (ẩm – uống) + 用 (dụng – dùng) + 水 (thủy – nước) → nước dùng để uống, đạt chuẩn an toàn.","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"💧","examples":[{"type":"basic","zh":"这里没有饮用水。","pinyin":"Zhèlǐ méiyǒu yǐnyòngshuǐ.","vi":"Ở đây không có nước uống."},{"type":"simple","zh":"地震后灾区急需大量饮用水。","pinyin":"Dìzhèn hòu zāiqū jíxū dàliàng yǐnyòngshuǐ.","vi":"Sau động đất, vùng bị nạn cần gấp rất nhiều nước uống."},{"type":"compound","zh":"如果饮用水受到污染，就会影响全城居民的健康。","pinyin":"Rúguǒ yǐnyòngshuǐ shòudào wūrǎn, jiù huì yǐngxiǎng quánchéng jūmín de jiànkāng.","vi":"Nếu nguồn nước uống bị ô nhiễm thì sẽ ảnh hưởng đến sức khỏe cư dân cả thành phố."}],"related":[{"hanzi":"饮水","pinyin":"yǐnshuǐ","vi":"nước uống"},{"hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","vi":"nước khoáng"},{"hanzi":"自来水","pinyin":"zìláishuǐ","vi":"nước máy"},{"hanzi":"纯净水","pinyin":"chúnjìngshuǐ","vi":"nước tinh khiết"}],"traditional":"飲用水"},{"id":"隐情","hanzi":"隐情","pinyin":"yǐnqíng","meaning_vi":"uẩn khúc, ẩn tình, chuyện khó nói","explanation":"隐 (ẩn – giấu) + 情 (tình – sự tình, tâm tình) → sự tình bị che giấu, khó nói ra.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🤫","examples":[{"type":"basic","zh":"这里面一定有隐情。","pinyin":"Zhè lǐmiàn yídìng yǒu yǐnqíng.","vi":"Trong chuyện này chắc chắn có uẩn khúc."},{"type":"simple","zh":"她终于说出了离婚背后的隐情。","pinyin":"Tā zhōngyú shuōchūle líhūn bèihòu de yǐnqíng.","vi":"Cuối cùng cô ấy đã nói ra uẩn khúc đằng sau cuộc ly hôn."},{"type":"compound","zh":"虽然他什么都没说，但是大家都看得出他有隐情。","pinyin":"Suīrán tā shénme dōu méi shuō, dànshì dàjiā dōu kàndechū tā yǒu yǐnqíng.","vi":"Tuy anh ấy không nói gì nhưng ai cũng nhận ra anh có điều khó nói."}],"related":[{"hanzi":"隐私","pinyin":"yǐnsī","vi":"đời tư"},{"hanzi":"内情","pinyin":"nèiqíng","vi":"nội tình"},{"hanzi":"苦衷","pinyin":"kǔzhōng","vi":"nỗi khổ tâm"},{"hanzi":"秘密","pinyin":"mìmì","vi":"bí mật"}],"traditional":"隱情"},{"id":"隐身","hanzi":"隐身","pinyin":"yǐnshēn","meaning_vi":"tàng hình, ẩn mình, ẩn trạng thái (trực tuyến)","explanation":"隐 (ẩn – giấu) + 身 (thân – thân mình) → giấu thân mình đi; ngày nay hay dùng cho chế độ ẩn trên mạng.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"👻","examples":[{"type":"basic","zh":"他在网上隐身了。","pinyin":"Tā zài wǎngshàng yǐnshēn le.","vi":"Anh ấy để chế độ ẩn trên mạng rồi."},{"type":"simple","zh":"小说里的主人公会一种隐身的法术。","pinyin":"Xiǎoshuō lǐ de zhǔrén gōnghuì yì zhǒng yǐnshēn de fǎshù.","vi":"Nhân vật chính trong tiểu thuyết biết một phép tàng hình."},{"type":"compound","zh":"因为不想被同事打扰，所以他把聊天软件设成了隐身。","pinyin":"Yīnwèi bù xiǎng bèi tóngshì dǎrǎo, suǒyǐ tā bǎ liáotiān ruǎnjiàn shè chéngle yǐnshēn.","vi":"Vì không muốn bị đồng nghiệp làm phiền nên anh ấy để ứng dụng nhắn tin ở chế độ ẩn."}],"related":[{"hanzi":"隐形","pinyin":"yǐnxíng","vi":"vô hình"},{"hanzi":"隐藏","pinyin":"yǐncáng","vi":"che giấu"},{"hanzi":"躲藏","pinyin":"duǒcáng","vi":"ẩn nấp"},{"hanzi":"在线","pinyin":"zàixiàn","vi":"trực tuyến"}],"traditional":"隱身"},{"id":"隐形","hanzi":"隐形","pinyin":"yǐnxíng","meaning_vi":"vô hình, tàng hình, ẩn","explanation":"隐 (ẩn – giấu) + 形 (hình – hình dạng) → giấu hình dạng, không nhìn thấy được; như 隐形眼镜 (kính áp tròng), 隐形飞机.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🫥","examples":[{"type":"basic","zh":"她戴着隐形眼镜。","pinyin":"Tā dàizhe yǐnxíng yǎnjìng.","vi":"Cô ấy đang đeo kính áp tròng."},{"type":"simple","zh":"这种隐形战机很难被雷达发现。","pinyin":"Zhè zhǒng yǐnxíng zhànjī hěn nán bèi léidá fāxiàn.","vi":"Loại máy bay chiến đấu tàng hình này rất khó bị radar phát hiện."},{"type":"compound","zh":"虽然隐形的压力看不见，但是它会慢慢影响人的健康。","pinyin":"Suīrán yǐnxíng de yālì kànbújiàn, dànshì tā huì mànmàn yǐngxiǎng rén de jiànkāng.","vi":"Tuy áp lực vô hình không nhìn thấy được nhưng nó sẽ dần ảnh hưởng đến sức khỏe con người."}],"related":[{"hanzi":"隐身","pinyin":"yǐnshēn","vi":"tàng hình"},{"hanzi":"隐形眼镜","pinyin":"yǐnxíngyǎnjìng","vi":"kính áp tròng"},{"hanzi":"无形","pinyin":"wúxíng","vi":"vô hình"},{"hanzi":"隐蔽","pinyin":"yǐnbì","vi":"kín đáo"}],"traditional":"隱形"},{"id":"隐性","hanzi":"隐性","pinyin":"yǐnxìng","meaning_vi":"ẩn, tiềm ẩn; lặn (di truyền)","explanation":"隐 (ẩn – giấu) + 性 (tính – tính chất) → có tính chất ẩn, không lộ ra ngoài; trong di truyền là tính lặn, đối lập với 显性 (trội).","hsk_level":"7-9","tags":["tinh-tu","khoa-hoc"],"image":"🧬","examples":[{"type":"basic","zh":"这是隐性基因。","pinyin":"Zhè shì yǐnxìng jīyīn.","vi":"Đây là gen lặn."},{"type":"simple","zh":"很多公司都存在隐性加班的问题。","pinyin":"Hěn duō gōngsī dōu cúnzài yǐnxìng jiābān de wèntí.","vi":"Nhiều công ty tồn tại vấn đề làm thêm giờ trá hình."},{"type":"compound","zh":"即使父母都很健康，孩子也可能遗传隐性疾病。","pinyin":"Jíshǐ fùmǔ dōu hěn jiànkāng, háizi yě kěnéng yíchuán yǐnxìng jíbìng.","vi":"Dù bố mẹ đều khỏe mạnh, con cái vẫn có thể di truyền bệnh lặn."}],"related":[{"hanzi":"显性","pinyin":"xiǎnxìng","vi":"trội, lộ rõ"},{"hanzi":"隐患","pinyin":"yǐnhuàn","vi":"mối họa tiềm ẩn"},{"hanzi":"潜在","pinyin":"qiánzài","vi":"tiềm tàng"},{"hanzi":"基因","pinyin":"jīyīn","vi":"gen"}],"traditional":"隱性"},{"id":"瘾","hanzi":"瘾","pinyin":"yǐn","meaning_vi":"nghiện, cơn nghiện, thú say mê","explanation":"瘾 (ẩn – nghiện) = 疒 (bộ bệnh) + 隐 → thói nghiện khó bỏ như bệnh; cũng chỉ sự ham thích say mê như 上瘾, 过瘾.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🚬","examples":[{"type":"basic","zh":"他的烟瘾很大。","pinyin":"Tā de yānyǐn hěn dà.","vi":"Anh ấy nghiện thuốc lá rất nặng."},{"type":"simple","zh":"孩子玩手机玩上了瘾。","pinyin":"Háizi wán shǒujī wán shàngle yǐn.","vi":"Đứa trẻ chơi điện thoại đến nghiện."},{"type":"compound","zh":"一旦染上了赌瘾，就很难再戒掉。","pinyin":"Yídàn rǎnshàngle dǔ yǐn, jiù hěn nán zài jièdiào.","vi":"Một khi đã dính nghiện cờ bạc thì rất khó cai."}],"related":[{"hanzi":"上瘾","pinyin":"shàngyǐn","vi":"nghiện"},{"hanzi":"过瘾","pinyin":"guòyǐn","vi":"đã, thỏa thích"},{"hanzi":"烟瘾","pinyin":"yānyǐn","vi":"nghiện thuốc lá"},{"hanzi":"戒","pinyin":"jiè","vi":"cai"}],"traditional":"癮"},{"id":"印章","hanzi":"印章","pinyin":"yìnzhāng","meaning_vi":"con dấu, ấn chương","explanation":"印 (ấn – con dấu) + 章 (chương – con dấu) → con dấu khắc tên dùng để đóng lên giấy tờ, thư họa.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🔏","examples":[{"type":"basic","zh":"请在这里盖印章。","pinyin":"Qǐng zài zhèlǐ gài yìnzhāng.","vi":"Xin đóng dấu vào đây."},{"type":"simple","zh":"爷爷收藏了很多古代的印章。","pinyin":"Yéye shōucángle hěn duō gǔdài de yìnzhāng.","vi":"Ông nội sưu tầm rất nhiều con dấu cổ."},{"type":"compound","zh":"如果合同上没有公司的印章，就没有法律效力。","pinyin":"Rúguǒ hétong shang méiyǒu gōngsī de yìnzhāng, jiù méiyǒu fǎlǜ xiàolì.","vi":"Nếu trên hợp đồng không có dấu của công ty thì không có hiệu lực pháp lý."}],"related":[{"hanzi":"公章","pinyin":"gōngzhāng","vi":"con dấu cơ quan"},{"hanzi":"图章","pinyin":"túzhāng","vi":"con dấu"},{"hanzi":"盖章","pinyin":"gàizhāng","vi":"đóng dấu"},{"hanzi":"印泥","pinyin":"yìnní","vi":"mực đóng dấu"}]},{"id":"应付","hanzi":"应付","pinyin":"yìngfu","meaning_vi":"đối phó, ứng phó; làm qua loa","explanation":"应 (ứng – đáp ứng) + 付 (phó – giao) → xử lý, đối phó với tình huống; cũng chỉ làm chiếu lệ, qua loa cho xong.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤹","examples":[{"type":"basic","zh":"我一个人应付不了。","pinyin":"Wǒ yígèrén yìngfu bùliǎo.","vi":"Một mình tôi không đối phó nổi."},{"type":"simple","zh":"她能轻松应付各种突发情况。","pinyin":"Tā néng qīngsōng yìngfu gèzhǒng tūfā qíngkuàng.","vi":"Cô ấy có thể dễ dàng ứng phó mọi tình huống bất ngờ."},{"type":"compound","zh":"因为他只是应付差事，所以工作总是出错。","pinyin":"Yīnwèi tā zhǐshì yìngfu chāishì, suǒyǐ gōngzuò zǒngshì chūcuò.","vi":"Vì anh ta chỉ làm qua loa cho xong nên công việc luôn có sai sót."}],"related":[{"hanzi":"应对","pinyin":"yìngduì","vi":"ứng đối"},{"hanzi":"对付","pinyin":"duìfu","vi":"đối phó"},{"hanzi":"敷衍","pinyin":"fūyǎn","vi":"qua loa"},{"hanzi":"处理","pinyin":"chǔlǐ","vi":"xử lý"}],"traditional":"應付"},{"id":"应邀","hanzi":"应邀","pinyin":"yìngyāo","meaning_vi":"nhận lời mời, theo lời mời","explanation":"应 (ứng – đáp lại) + 邀 (yêu – mời) → nhận lời mời mà đến hoặc làm việc gì; sắc thái trang trọng.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"他应邀出席了会议。","pinyin":"Tā yìngyāo chūxíle huìyì.","vi":"Anh ấy nhận lời mời đến dự hội nghị."},{"type":"simple","zh":"著名作家应邀来我校做讲座。","pinyin":"Zhùmíng zuòjiā yìngyāo lái wǒ xiào zuò jiǎngzuò.","vi":"Nhà văn nổi tiếng nhận lời mời đến trường tôi diễn thuyết."},{"type":"compound","zh":"虽然工作很忙，但是她还是应邀参加了朋友的婚礼。","pinyin":"Suīrán gōngzuò hěn máng, dànshì tā háishì yìngyāo cānjiāle péngyou de hūnlǐ.","vi":"Tuy công việc rất bận nhưng cô ấy vẫn nhận lời đến dự đám cưới của bạn."}],"related":[{"hanzi":"邀请","pinyin":"yāoqǐng","vi":"mời"},{"hanzi":"受邀","pinyin":"shòuyāo","vi":"được mời"},{"hanzi":"应约","pinyin":"yìngyuē","vi":"nhận lời hẹn"},{"hanzi":"出席","pinyin":"chūxí","vi":"có mặt, dự"}],"traditional":"應邀"},{"id":"应有尽有","hanzi":"应有尽有","pinyin":"yīngyǒu-jìnyǒu","meaning_vi":"có đủ mọi thứ, cái gì cũng có","explanation":"应 (ưng – nên) + 有 (hữu – có) + 尽 (tận – hết) + 有 (hữu – có) → thứ gì nên có thì đều có đủ cả.","hsk_level":"7-9","tags":["thanh-ngu","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"超市里应有尽有。","pinyin":"Chāoshì lǐ yīngyǒujìnyǒu.","vi":"Trong siêu thị thứ gì cũng có."},{"type":"simple","zh":"这条街上的小吃应有尽有。","pinyin":"Zhè tiáo jiēshang de xiǎochī yīngyǒujìnyǒu.","vi":"Trên con phố này món ăn vặt nào cũng có."},{"type":"compound","zh":"虽然这家店不大，但是生活用品应有尽有。","pinyin":"Suīrán zhè jiā diàn búdà, dànshì shēnghuó yòngpǐn yīngyǒujìnyǒu.","vi":"Tuy cửa hàng này không lớn nhưng đồ dùng sinh hoạt có đủ cả."}],"related":[{"hanzi":"一应俱全","pinyin":"yìyīngjùquán","vi":"đầy đủ mọi thứ"},{"hanzi":"包罗万象","pinyin":"bāoluówànxiàng","vi":"bao quát mọi thứ"},{"hanzi":"齐全","pinyin":"qíquán","vi":"đầy đủ"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"phong phú"}],"traditional":"應有盡有"},{"id":"英镑","hanzi":"英镑","pinyin":"Yīngbàng","meaning_vi":"bảng Anh","explanation":"英 (Anh – nước Anh) + 镑 (bảng – phiên âm \"pound\") → đơn vị tiền tệ của nước Anh.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💷","examples":[{"type":"basic","zh":"这本书二十英镑。","pinyin":"Zhè běn shū èrshí Yīngbàng.","vi":"Cuốn sách này giá hai mươi bảng Anh."},{"type":"simple","zh":"我在机场把人民币换成了英镑。","pinyin":"Wǒ zài jīchǎng bǎ rénmínbì huànchéngle Yīngbàng.","vi":"Tôi đã đổi nhân dân tệ sang bảng Anh ở sân bay."},{"type":"compound","zh":"因为英镑汇率下跌，所以去英国留学的费用降低了。","pinyin":"Yīnwèi Yīngbàng huìlǜ xiàdiē, suǒyǐ qù Yīngguó liúxué de fèiyòng jiàngdī le.","vi":"Vì tỷ giá bảng Anh giảm nên chi phí du học Anh đã thấp đi."}],"related":[{"hanzi":"美元","pinyin":"měiyuán","vi":"đô la Mỹ"},{"hanzi":"欧元","pinyin":"ōuyuán","vi":"đồng euro"},{"hanzi":"汇率","pinyin":"huìlǜ","vi":"tỷ giá"},{"hanzi":"便士","pinyin":"biànshì","vi":"xu penny"}],"traditional":"英鎊"},{"id":"鹰","hanzi":"鹰","pinyin":"yīng","meaning_vi":"chim ưng, đại bàng, diều hâu","explanation":"鹰 (ưng – chim ưng) → loài chim săn mồi có mỏ quặp, móng sắc và mắt rất tinh.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦅","examples":[{"type":"basic","zh":"天上飞着一只鹰。","pinyin":"Tiānshàng fēizhe yì zhī yīng.","vi":"Trên trời có một con chim ưng đang bay."},{"type":"simple","zh":"那只鹰从高空俯冲下来抓住了兔子。","pinyin":"Nà zhī yīng cóng gāokōng fǔchōng xiàlái zhuāzhùle tùzi.","vi":"Con chim ưng ấy từ trên cao lao xuống bắt được con thỏ."},{"type":"compound","zh":"虽然鹰飞得很高，但是它能看清地上的小老鼠。","pinyin":"Suīrán yīng fēi de hěn gāo, dànshì tā néng kànqīng dìshang de xiǎolǎoshǔ.","vi":"Tuy chim ưng bay rất cao nhưng nó vẫn nhìn rõ con chuột nhỏ dưới đất."}],"related":[{"hanzi":"老鹰","pinyin":"lǎoyīng","vi":"diều hâu"},{"hanzi":"雄鹰","pinyin":"xióngyīng","vi":"chim ưng dũng mãnh"},{"hanzi":"猎鹰","pinyin":"lièyīng","vi":"chim ưng săn"},{"hanzi":"鹰钩鼻","pinyin":"yīnggōubí","vi":"mũi khoằm"}],"traditional":"鷹"},{"id":"迎","hanzi":"迎","pinyin":"yíng","meaning_vi":"đón, nghênh đón; hướng về phía","explanation":"迎 (nghênh – đón) → ra đón người đến; cũng có nghĩa hướng về phía, đối diện như 迎风, 迎面.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👋","examples":[{"type":"basic","zh":"我去车站迎客人。","pinyin":"Wǒqù chēzhàn yíng kèrén.","vi":"Tôi ra ga đón khách."},{"type":"simple","zh":"全村人都出来迎新娘了。","pinyin":"Quán cūn rén dōu chūlái yíng xīnniáng le.","vi":"Cả làng đều ra đón cô dâu."},{"type":"compound","zh":"虽然风很大，但是他还是迎着风向前跑。","pinyin":"Suīrán fēng hěn dà, dànshì tā háishì yíngzhe fēngxiàng qián pǎo.","vi":"Tuy gió rất to nhưng anh ấy vẫn ngược gió chạy về phía trước."}],"related":[{"hanzi":"欢迎","pinyin":"huānyíng","vi":"hoan nghênh"},{"hanzi":"迎接","pinyin":"yíngjiē","vi":"nghênh tiếp"},{"hanzi":"送","pinyin":"sòng","vi":"tiễn"},{"hanzi":"迎面","pinyin":"yíngmiàn","vi":"ngay trước mặt"}]},{"id":"荧光","hanzi":"荧光","pinyin":"yíngguāng","meaning_vi":"huỳnh quang, dạ quang","explanation":"荧 (huỳnh – ánh sáng le lói) + 光 (quang – ánh sáng) → ánh sáng do một chất phát ra khi được chiếu sáng; như 荧光笔 (bút dạ quang).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🖍️","examples":[{"type":"basic","zh":"我买了一支荧光笔。","pinyin":"Wǒ mǎile yì zhī yíngguāngbǐ.","vi":"Tôi đã mua một cây bút dạ quang."},{"type":"simple","zh":"晚上跑步最好穿带荧光条的衣服。","pinyin":"Wǎnshang pǎobù zuìhǎo chuān dài yíngguāng tiáo de yīfu.","vi":"Chạy bộ buổi tối nên mặc quần áo có dải phản quang."},{"type":"compound","zh":"因为手表上有荧光涂层，所以晚上也能看清时间。","pinyin":"Yīnwèi shǒubiǎo shang yǒu yíngguāng túcéng, suǒyǐ wǎnshang yě néng kànqīng shíjiān.","vi":"Vì đồng hồ có lớp phủ dạ quang nên buổi tối vẫn xem rõ giờ."}],"related":[{"hanzi":"荧光灯","pinyin":"yíngguāngdēng","vi":"đèn huỳnh quang"},{"hanzi":"荧光棒","pinyin":"yíngguāngbàng","vi":"que phát sáng"},{"hanzi":"发光","pinyin":"fāguāng","vi":"phát sáng"},{"hanzi":"荧屏","pinyin":"yíngpíng","vi":"màn hình"}],"traditional":"熒光"},{"id":"营造","hanzi":"营造","pinyin":"yíngzào","meaning_vi":"tạo ra, tạo dựng (bầu không khí); xây dựng","explanation":"营 (doanh – sắp đặt, kinh doanh) + 造 (tạo – làm ra) → xây dựng công trình; nay thường dùng với nghĩa tạo ra bầu không khí, môi trường.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏗️","examples":[{"type":"basic","zh":"灯光营造了浪漫气氛。","pinyin":"Dēngguāng yíngzàole làngmàn qìfēn.","vi":"Ánh đèn tạo nên bầu không khí lãng mạn."},{"type":"simple","zh":"学校要为学生营造安全的学习环境。","pinyin":"Xuéxiào yào wèi xuésheng yíngzào ānquán de xuéxí huánjìng.","vi":"Nhà trường phải tạo cho học sinh một môi trường học tập an toàn."},{"type":"compound","zh":"只有营造公平的竞争环境，企业才能健康发展。","pinyin":"Zhǐyǒu yíngzào gōngpíng de jìngzhēng huánjìng, qǐyè cáinéng jiànkāng fāzhǎn.","vi":"Chỉ khi tạo dựng môi trường cạnh tranh công bằng, doanh nghiệp mới phát triển lành mạnh."}],"related":[{"hanzi":"创造","pinyin":"chuàngzào","vi":"sáng tạo"},{"hanzi":"打造","pinyin":"dǎzào","vi":"tạo dựng"},{"hanzi":"建造","pinyin":"jiànzào","vi":"xây dựng"},{"hanzi":"氛围","pinyin":"fēnwéi","vi":"bầu không khí"}],"traditional":"營造"},{"id":"赢家","hanzi":"赢家","pinyin":"yíngjiā","meaning_vi":"người thắng cuộc, bên thắng","explanation":"赢 (doanh – thắng, có lãi) + 家 (gia – người, bên) → bên thắng trong cuộc chơi hay cuộc cạnh tranh.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🏆","examples":[{"type":"basic","zh":"他是最后的赢家。","pinyin":"Tā shì zuìhòu de yíngjiā.","vi":"Anh ấy là người thắng cuối cùng."},{"type":"simple","zh":"这场价格战没有真正的赢家。","pinyin":"Zhè chǎng jiàgézhàn méiyǒu zhēnzhèng de yíngjiā.","vi":"Cuộc chiến giá cả này không có kẻ thắng thật sự."},{"type":"compound","zh":"即使暂时落后，坚持到底的人也可能成为赢家。","pinyin":"Jíshǐ zànshí luòhòu, jiānchí dàodǐ de rén yě kěnéng chéngwéi yíngjiā.","vi":"Dù tạm thời tụt lại phía sau, người kiên trì đến cùng vẫn có thể trở thành người chiến thắng."}],"related":[{"hanzi":"输家","pinyin":"shūjiā","vi":"người thua"},{"hanzi":"胜者","pinyin":"shèngzhě","vi":"người thắng"},{"hanzi":"赢","pinyin":"yíng","vi":"thắng"},{"hanzi":"双赢","pinyin":"shuāngyíng","vi":"đôi bên cùng có lợi"}],"traditional":"贏家"},{"id":"映","hanzi":"映","pinyin":"yìng","meaning_vi":"phản chiếu, chiếu rọi, soi bóng","explanation":"映 (ánh – chiếu sáng) → ánh sáng chiếu rọi khiến hình bóng hiện lên; gặp trong 反映, 放映, 倒映.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌅","examples":[{"type":"basic","zh":"晚霞映红了天空。","pinyin":"Wǎnxiá yìng hóngle tiānkōng.","vi":"Ráng chiều nhuộm đỏ cả bầu trời."},{"type":"simple","zh":"湖面上映着远处的雪山。","pinyin":"Húmiàn shangyìngzhe yuǎnchù de xuěshān.","vi":"Mặt hồ in bóng dãy núi tuyết phía xa."},{"type":"compound","zh":"当月光映在水面上的时候，整个湖都亮了起来。","pinyin":"Dāng yuèguāng yìng zài shuǐmiàn shang de shíhou, zhěnggè hú dōu liàngle qǐlái.","vi":"Khi ánh trăng chiếu xuống mặt nước, cả hồ bừng sáng lên."}],"related":[{"hanzi":"反映","pinyin":"fǎnyìng","vi":"phản ánh"},{"hanzi":"放映","pinyin":"fàngyìng","vi":"chiếu phim"},{"hanzi":"倒映","pinyin":"dàoyìng","vi":"in bóng"},{"hanzi":"照","pinyin":"zhào","vi":"chiếu"}]},{"id":"硬朗","hanzi":"硬朗","pinyin":"yìnglǎng","meaning_vi":"khỏe mạnh, quắc thước, cứng cáp","explanation":"硬 (ngạnh – cứng) + 朗 (lãng – sáng sủa) → cứng cáp, minh mẫn; thường dùng khen người già còn khỏe mạnh.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"💪","examples":[{"type":"basic","zh":"奶奶身体很硬朗。","pinyin":"Nǎinai shēntǐ hěn yìnglǎng.","vi":"Bà nội vẫn rất khỏe mạnh."},{"type":"simple","zh":"八十岁的爷爷身子骨还很硬朗。","pinyin":"Bāshí suì de yéye shēnzigǔ hái hěn yìnglǎng.","vi":"Ông nội tám mươi tuổi mà xương cốt vẫn rất cứng cáp."},{"type":"compound","zh":"虽然外公已经九十岁了，但是身体依然硬朗。","pinyin":"Suīrán wàigōng yǐjīng jiǔshí suì le, dànshì shēntǐ yīrán yìnglǎng.","vi":"Tuy ông ngoại đã chín mươi tuổi nhưng vẫn còn quắc thước."}],"related":[{"hanzi":"健壮","pinyin":"jiànzhuàng","vi":"khỏe mạnh"},{"hanzi":"结实","pinyin":"jiēshi","vi":"chắc khỏe"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"khỏe mạnh"},{"hanzi":"虚弱","pinyin":"xūruò","vi":"yếu ớt"}]},{"id":"硬盘","hanzi":"硬盘","pinyin":"yìngpán","meaning_vi":"ổ cứng","explanation":"硬 (ngạnh – cứng) + 盘 (bàn – đĩa) → đĩa cứng, thiết bị lưu trữ dữ liệu của máy tính.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💽","examples":[{"type":"basic","zh":"我的硬盘满了。","pinyin":"Wǒ de yìngpán mǎn le.","vi":"Ổ cứng của tôi đầy rồi."},{"type":"simple","zh":"他把照片都存进了移动硬盘。","pinyin":"Tā bǎ zhàopiàn dōu cún jìnle yídòng yìngpán.","vi":"Anh ấy lưu hết ảnh vào ổ cứng di động."},{"type":"compound","zh":"如果硬盘突然坏了，没备份的资料就全没了。","pinyin":"Rúguǒ yìngpán tūrán huàile, méi bèifèn de zīliào jiù quán méile.","vi":"Nếu ổ cứng đột nhiên hỏng thì dữ liệu chưa sao lưu sẽ mất sạch."}],"related":[{"hanzi":"硬件","pinyin":"yìngjiàn","vi":"phần cứng"},{"hanzi":"软件","pinyin":"ruǎnjiàn","vi":"phần mềm"},{"hanzi":"内存","pinyin":"nèicún","vi":"bộ nhớ trong"},{"hanzi":"存储","pinyin":"cúnchǔ","vi":"lưu trữ"}],"traditional":"硬盤"},{"id":"拥挤","hanzi":"拥挤","pinyin":"yōngjǐ","meaning_vi":"đông đúc, chen chúc, chật chội","explanation":"拥 (ủng – ôm, vây quanh) + 挤 (tễ – chen) → người hoặc xe cộ chen chúc dồn vào một chỗ.","hsk_level":"7-9","tags":["tinh-tu","giao-thong"],"image":"🚇","examples":[{"type":"basic","zh":"地铁里很拥挤。","pinyin":"Dìtiě lǐ hěn yōngjǐ.","vi":"Trong tàu điện ngầm rất đông đúc."},{"type":"simple","zh":"节假日的景点总是特别拥挤。","pinyin":"Jiéjiàrì de jǐngdiǎn zǒngshì tèbié yōngjǐ.","vi":"Các điểm du lịch vào ngày lễ luôn đặc biệt chen chúc."},{"type":"compound","zh":"因为早高峰太拥挤，所以他每天提前一个小时出门。","pinyin":"Yīnwèi zǎogāofēng tài yōngjǐ, suǒyǐ tā měitiān tíqián yí gè xiǎoshí chūmén.","vi":"Vì giờ cao điểm buổi sáng quá đông nên ngày nào anh ấy cũng ra khỏi nhà sớm một tiếng."}],"related":[{"hanzi":"挤","pinyin":"jǐ","vi":"chen"},{"hanzi":"拥堵","pinyin":"yōngdǔ","vi":"ùn tắc"},{"hanzi":"宽敞","pinyin":"kuānchang","vi":"rộng rãi"},{"hanzi":"人山人海","pinyin":"rénshānrénhǎi","vi":"biển người"}],"traditional":"擁擠"},{"id":"永不","hanzi":"永不","pinyin":"yǒngbù","meaning_vi":"không bao giờ, mãi mãi không","explanation":"永 (vĩnh – mãi mãi) + 不 (bất – không) → mãi mãi không; sắc thái trang trọng, hay dùng khi thề hứa.","hsk_level":"7-9","tags":["pho-tu"],"image":"♾️","examples":[{"type":"basic","zh":"我永不放弃。","pinyin":"Wǒ yǒngbú fàngqì.","vi":"Tôi không bao giờ bỏ cuộc."},{"type":"simple","zh":"他发誓永不再踏进这个家门。","pinyin":"Tā fāshì yǒngbú zài tàjìn zhè gè jiāmén.","vi":"Anh ta thề sẽ không bao giờ bước chân vào nhà này nữa."},{"type":"compound","zh":"即使遇到再大的困难，我们也永不低头。","pinyin":"Jíshǐ yùdào zài dà de kùnnan, wǒmen yě yǒngbù dītóu.","vi":"Dù gặp khó khăn lớn đến đâu, chúng ta cũng không bao giờ cúi đầu."}],"related":[{"hanzi":"永远","pinyin":"yǒngyuǎn","vi":"mãi mãi"},{"hanzi":"从不","pinyin":"cóngbù","vi":"chưa bao giờ"},{"hanzi":"绝不","pinyin":"juébù","vi":"tuyệt đối không"},{"hanzi":"永久","pinyin":"yǒngjiǔ","vi":"vĩnh cửu"}]},{"id":"永久","hanzi":"永久","pinyin":"yǒngjiǔ","meaning_vi":"vĩnh viễn, lâu dài, vĩnh cửu","explanation":"永 (vĩnh – mãi mãi) + 久 (cửu – lâu) → lâu dài mãi mãi, không thay đổi.","hsk_level":"7-9","tags":["tinh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"这是永久的纪念。","pinyin":"Zhè shì yǒngjiǔ de jìniàn.","vi":"Đây là kỷ niệm mãi mãi."},{"type":"simple","zh":"他终于拿到了这个国家的永久居留权。","pinyin":"Tā zhōngyú nádàole zhè gè guójiā de yǒngjiǔ jūliúquán.","vi":"Cuối cùng anh ấy đã có quyền thường trú vĩnh viễn ở nước này."},{"type":"compound","zh":"如果多次违反规定，账号就会被永久封禁。","pinyin":"Rúguǒ duōcì wéifǎn guīdìng, zhànghào jiù huì bèi yǒngjiǔ fēngjìn.","vi":"Nếu vi phạm quy định nhiều lần thì tài khoản sẽ bị khóa vĩnh viễn."}],"related":[{"hanzi":"永远","pinyin":"yǒngyuǎn","vi":"mãi mãi"},{"hanzi":"长久","pinyin":"chángjiǔ","vi":"lâu dài"},{"hanzi":"永恒","pinyin":"yǒnghéng","vi":"vĩnh hằng"},{"hanzi":"暂时","pinyin":"zànshí","vi":"tạm thời"}]},{"id":"勇往直前","hanzi":"勇往直前","pinyin":"yǒngwǎng-zhíqián","meaning_vi":"dũng cảm tiến lên, thẳng tiến không lùi","explanation":"勇 (dũng – dũng cảm) + 往 (vãng – đi) + 直 (trực – thẳng) + 前 (tiền – phía trước) → dũng cảm thẳng tiến về phía trước, không sợ khó khăn.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"我们要勇往直前。","pinyin":"Wǒmen yào yǒngwǎngzhíqián.","vi":"Chúng ta phải dũng cảm tiến lên."},{"type":"simple","zh":"战士们冒着大雨勇往直前。","pinyin":"Zhànshìmen màozhe dàyǔ yǒngwǎngzhíqián.","vi":"Các chiến sĩ đội mưa lớn dũng cảm tiến lên."},{"type":"compound","zh":"虽然前面的路很难走，但是他依然勇往直前。","pinyin":"Suīrán qiánmiàn de lù hěn nánzǒu, dànshì tā yīrán yǒngwǎngzhíqián.","vi":"Tuy con đường phía trước rất khó đi nhưng anh ấy vẫn dũng cảm tiến bước."}],"related":[{"hanzi":"一往无前","pinyin":"yìwǎngwúqián","vi":"tiến lên không lùi"},{"hanzi":"奋勇","pinyin":"fènyǒng","vi":"hăng hái"},{"hanzi":"前进","pinyin":"qiánjìn","vi":"tiến lên"},{"hanzi":"退缩","pinyin":"tuìsuō","vi":"lùi bước"}]},{"id":"勇于","hanzi":"勇于","pinyin":"yǒngyú","meaning_vi":"dám, can đảm (làm việc gì)","explanation":"勇 (dũng – dũng cảm) + 于 (vu – ở, đối với) → dũng cảm trong việc gì, dám làm; luôn có động từ đi sau.","hsk_level":"7-9","tags":["dong-tu"],"image":"🦁","examples":[{"type":"basic","zh":"他勇于承认错误。","pinyin":"Tā yǒngyú chéngrèn cuòwù.","vi":"Anh ấy dám nhận lỗi."},{"type":"simple","zh":"年轻人应该勇于尝试新事物。","pinyin":"Niánqīngrén yīnggāi yǒngyú chángshì xīn shìwù.","vi":"Người trẻ nên dám thử những điều mới."},{"type":"compound","zh":"只有勇于面对失败，才能真正走向成功。","pinyin":"Zhǐyǒu yǒngyú miànduì shībài, cáinéng zhēnzhèng zǒuxiàng chénggōng.","vi":"Chỉ khi dám đối mặt với thất bại mới thật sự đi đến thành công."}],"related":[{"hanzi":"敢于","pinyin":"gǎnyú","vi":"dám"},{"hanzi":"善于","pinyin":"shànyú","vi":"giỏi về"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"dũng cảm"},{"hanzi":"勇气","pinyin":"yǒngqì","vi":"dũng khí"}],"traditional":"勇於"},{"id":"涌","hanzi":"涌","pinyin":"yǒng","meaning_vi":"tuôn ra, trào ra, ùa đến","explanation":"涌 (dũng – nước trào lên) → nước từ dưới tuôn trào lên; nghĩa rộng là người hay cảm xúc ùa đến dồn dập như 涌现, 涌入.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"泪水涌了出来。","pinyin":"Lèishuǐ yǒngle chūlái.","vi":"Nước mắt trào ra."},{"type":"simple","zh":"成千上万的游客涌进了古城。","pinyin":"Chéngqiānshàngwàn de yóukè yǒngjìnle gǔchéng.","vi":"Hàng nghìn hàng vạn du khách ùa vào cổ trấn."},{"type":"compound","zh":"每当想起家乡，一股暖流就涌上他的心头。","pinyin":"Měidāng xiǎngqǐ jiāxiāng, yì gǔ nuǎnliú jiù yǒng shàng tā de xīntóu.","vi":"Mỗi khi nhớ về quê hương, một dòng ấm áp lại dâng lên trong lòng anh."}],"related":[{"hanzi":"涌现","pinyin":"yǒngxiàn","vi":"xuất hiện ồ ạt"},{"hanzi":"汹涌","pinyin":"xiōngyǒng","vi":"cuồn cuộn"},{"hanzi":"涌入","pinyin":"yǒngrù","vi":"tràn vào"},{"hanzi":"喷涌","pinyin":"pēnyǒng","vi":"phun trào"}],"traditional":"湧"},{"id":"用餐","hanzi":"用餐","pinyin":"yòngcān","meaning_vi":"dùng bữa, ăn cơm","explanation":"用 (dụng – dùng) + 餐 (xan – bữa ăn) → dùng bữa; cách nói lịch sự, trang trọng của 吃饭.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"请大家入座用餐。","pinyin":"Qǐng dàjiā rùzuò yòngcān.","vi":"Mời mọi người ngồi vào bàn dùng bữa."},{"type":"simple","zh":"酒店的客人可以在二楼餐厅用餐。","pinyin":"Jiǔdiàn de kèrén kěyǐ zài èr lóu cāntīng yòngcān.","vi":"Khách của khách sạn có thể dùng bữa ở nhà hàng tầng hai."},{"type":"compound","zh":"如果您想在店内用餐，就请先在门口排队。","pinyin":"Rúguǒ nín xiǎng zài diàn nèi yòngcān, jiù qǐng xiān zài ménkǒu páiduì.","vi":"Nếu quý khách muốn dùng bữa tại quán thì xin xếp hàng ở cửa trước."}],"related":[{"hanzi":"就餐","pinyin":"jiùcān","vi":"dùng bữa"},{"hanzi":"进餐","pinyin":"jìncān","vi":"ăn uống"},{"hanzi":"吃饭","pinyin":"chīfàn","vi":"ăn cơm"},{"hanzi":"餐厅","pinyin":"cāntīng","vi":"nhà hàng"}]},{"id":"用力","hanzi":"用力","pinyin":"yònglì","meaning_vi":"dùng sức, ra sức, gắng sức","explanation":"用 (dụng – dùng) + 力 (lực – sức) → dùng sức, gắng sức khi làm việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏋️","examples":[{"type":"basic","zh":"他用力推开了门。","pinyin":"Tā yònglì tuīkāile mén.","vi":"Anh ấy dùng sức đẩy cửa ra."},{"type":"simple","zh":"她用力地握住了我的手。","pinyin":"Tā yònglì de wòzhùle wǒ de shǒu.","vi":"Cô ấy nắm chặt lấy tay tôi."},{"type":"compound","zh":"如果你再用力一点，这个瓶盖就能拧开了。","pinyin":"Rúguǒ nǐ zài yònglì yìdiǎn, zhè gè pínggài jiù néng nǐngkāi le.","vi":"Nếu bạn dùng sức thêm chút nữa thì nắp chai này sẽ vặn ra được."}],"related":[{"hanzi":"使劲","pinyin":"shǐjìn","vi":"ra sức"},{"hanzi":"费力","pinyin":"fèilì","vi":"tốn sức"},{"hanzi":"努力","pinyin":"nǔlì","vi":"cố gắng"},{"hanzi":"力气","pinyin":"lìqi","vi":"sức lực"}]},{"id":"用人","hanzi":"用人","pinyin":"yòngrén","meaning_vi":"dùng người, tuyển người; người giúp việc","explanation":"用 (dụng – dùng) + 人 (nhân – người) → sử dụng, bố trí người làm việc; đọc yòngren thì chỉ người giúp việc trong nhà.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"公司现在急需用人。","pinyin":"Gōngsī xiànzài jíxū yòngrén.","vi":"Công ty hiện đang rất cần người."},{"type":"simple","zh":"这位领导用人一向看重能力。","pinyin":"Zhè wèi lǐngdǎo yòngrén yíxiàng kànzhòng nénglì.","vi":"Vị lãnh đạo này dùng người xưa nay luôn coi trọng năng lực."},{"type":"compound","zh":"如果用人不当，再好的计划也会失败。","pinyin":"Rúguǒ yòngrén búdàng, zài hǎo de jìhuà yě huì shībài.","vi":"Nếu dùng người không đúng thì kế hoạch tốt đến mấy cũng thất bại."}],"related":[{"hanzi":"用人单位","pinyin":"yòngréndānwèi","vi":"đơn vị tuyển dụng"},{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"任用","pinyin":"rènyòng","vi":"bổ nhiệm"}]},{"id":"用意","hanzi":"用意","pinyin":"yòngyì","meaning_vi":"dụng ý, ý định, mục đích","explanation":"用 (dụng – dùng) + 意 (ý – ý nghĩ) → ý định thật sự đằng sau một hành động hay lời nói.","hsk_level":"7-9","tags":["danh-tu"],"image":"🎯","examples":[{"type":"basic","zh":"我明白你的用意。","pinyin":"Wǒ míngbai nǐ de yòngyì.","vi":"Tôi hiểu dụng ý của bạn."},{"type":"simple","zh":"老师这样安排是有深刻用意的。","pinyin":"Lǎoshī zhèyàng ānpái shì yǒu shēnkè yòngyì de.","vi":"Thầy giáo sắp xếp như vậy là có dụng ý sâu xa."},{"type":"compound","zh":"虽然妈妈的话很严厉，但是她的用意是好的。","pinyin":"Suīrán māma dehuà hěn yánlì, dànshì tā de yòngyì shì hǎo de.","vi":"Tuy lời mẹ nói rất nghiêm khắc nhưng ý của mẹ là tốt."}],"related":[{"hanzi":"意图","pinyin":"yìtú","vi":"ý đồ"},{"hanzi":"目的","pinyin":"mùdì","vi":"mục đích"},{"hanzi":"用心","pinyin":"yòngxīn","vi":"dụng tâm"},{"hanzi":"动机","pinyin":"dòngjī","vi":"động cơ"}]},{"id":"优","hanzi":"优","pinyin":"yōu","meaning_vi":"ưu, tốt, xuất sắc","explanation":"优 (ưu – tốt, hơn) → tốt, giỏi hơn mức thường; hay gặp trong 优秀, 优点, 优惠 hoặc khi xếp loại \"ưu\".","hsk_level":"7-9","tags":["tinh-tu"],"image":"🥇","examples":[{"type":"basic","zh":"他的成绩全是优。","pinyin":"Tā de chéngjì quán shì yōu.","vi":"Điểm của anh ấy toàn loại ưu."},{"type":"simple","zh":"我们要选择质优价廉的原材料。","pinyin":"Wǒmen yào xuǎnzé zhì yōu jià lián de yuáncáiliào.","vi":"Chúng ta phải chọn nguyên liệu chất lượng tốt mà giá rẻ."},{"type":"compound","zh":"只要考试成绩达到优，就能拿到奖学金。","pinyin":"Zhǐyào kǎoshì chéngjì dádào yōu, jiù néng nádào jiǎngxuéjīn.","vi":"Chỉ cần điểm thi đạt loại ưu là có thể nhận học bổng."}],"related":[{"hanzi":"优秀","pinyin":"yōuxiù","vi":"xuất sắc"},{"hanzi":"优点","pinyin":"yōudiǎn","vi":"ưu điểm"},{"hanzi":"优势","pinyin":"yōushì","vi":"ưu thế"},{"hanzi":"劣","pinyin":"liè","vi":"kém"}],"traditional":"優"},{"id":"优雅","hanzi":"优雅","pinyin":"yōuyǎ","meaning_vi":"thanh lịch, tao nhã, duyên dáng","explanation":"优 (ưu – tốt đẹp) + 雅 (nhã – thanh nhã) → đẹp đẽ, nhã nhặn, có phong thái lịch sự.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🦢","examples":[{"type":"basic","zh":"她举止很优雅。","pinyin":"Tā jǔzhǐ hěn yōuyǎ.","vi":"Cử chỉ của cô ấy rất thanh lịch."},{"type":"simple","zh":"餐厅里播放着优雅的钢琴曲。","pinyin":"Cāntīng lǐ bōfàngzhe yōuyǎ de gāngqín qǔ.","vi":"Trong nhà hàng đang phát những bản nhạc piano du dương."},{"type":"compound","zh":"虽然她已经六十岁了，但是看起来依然很优雅。","pinyin":"Suīrán tā yǐjīng liùshí suì le, dànshì kànqǐlái yīrán hěn yōuyǎ.","vi":"Tuy đã sáu mươi tuổi nhưng bà ấy trông vẫn rất thanh lịch."}],"related":[{"hanzi":"高雅","pinyin":"gāoyǎ","vi":"cao nhã"},{"hanzi":"文雅","pinyin":"wényǎ","vi":"nho nhã"},{"hanzi":"典雅","pinyin":"diǎnyǎ","vi":"trang nhã"},{"hanzi":"粗俗","pinyin":"cūsú","vi":"thô tục"}],"traditional":"優雅"},{"id":"尤为","hanzi":"尤为","pinyin":"yóuwéi","meaning_vi":"đặc biệt, càng, nhất là","explanation":"尤 (vưu – càng, đặc biệt) + 为 (vi – là) → đặc biệt là, càng thêm; đứng trước tính từ hai âm tiết, dùng trong văn viết.","hsk_level":"7-9","tags":["pho-tu"],"image":"⭐","examples":[{"type":"basic","zh":"这一点尤为重要。","pinyin":"Zhè yìdiǎn yóuwéi zhòngyào.","vi":"Điểm này đặc biệt quan trọng."},{"type":"simple","zh":"今年夏天南方的旱情尤为严重。","pinyin":"Jīnnián xiàtiān nánfāng de hànqíng yóuwéi yánzhòng.","vi":"Mùa hè năm nay hạn hán ở miền Nam đặc biệt nghiêm trọng."},{"type":"compound","zh":"虽然大家都很努力，但是小王的表现尤为突出。","pinyin":"Suīrán dàjiā dōu hěn nǔlì, dànshì xiǎo Wáng de biǎoxiàn yóuwéi tūchū.","vi":"Tuy mọi người đều rất cố gắng nhưng Tiểu Vương thể hiện đặc biệt nổi bật."}],"related":[{"hanzi":"尤其","pinyin":"yóuqí","vi":"nhất là"},{"hanzi":"特别","pinyin":"tèbié","vi":"đặc biệt"},{"hanzi":"格外","pinyin":"géwài","vi":"hết sức"},{"hanzi":"更为","pinyin":"gèngwéi","vi":"càng"}],"traditional":"尤為"},{"id":"由此看来","hanzi":"由此看来","pinyin":"yóucǐkànlái","meaning_vi":"xem ra, từ đó mà xét","explanation":"由 (do – từ) + 此 (thử – này) + 看来 (xem ra) → xét từ điều này thì thấy; dùng để rút ra nhận định.","hsk_level":"7-9","tags":["lien-tu"],"image":"🔎","examples":[{"type":"basic","zh":"由此看来，他说谎了。","pinyin":"Yóucǐkànlái, tā shuōhuǎng le.","vi":"Xem ra anh ta đã nói dối."},{"type":"simple","zh":"由此看来，这次失败并不是偶然的。","pinyin":"Yóucǐkànlái, zhè cì shībài bìngbú shì ǒurán de.","vi":"Từ đó mà xét, lần thất bại này không phải ngẫu nhiên."},{"type":"compound","zh":"由此看来，如果不改变方法，就很难提高成绩。","pinyin":"Yóucǐkànlái, rúguǒ bù gǎibiàn fāngfǎ, jiù hěn nán tígāo chéngjì.","vi":"Xem ra nếu không thay đổi phương pháp thì rất khó nâng cao thành tích."}],"related":[{"hanzi":"由此可见","pinyin":"yóucǐkějiàn","vi":"từ đó có thể thấy"},{"hanzi":"看来","pinyin":"kànlái","vi":"xem ra"},{"hanzi":"可见","pinyin":"kějiàn","vi":"có thể thấy"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"vì vậy"}],"traditional":"由此看來"},{"id":"由此可见","hanzi":"由此可见","pinyin":"yóucǐkějiàn","meaning_vi":"từ đó có thể thấy, qua đó thấy rằng","explanation":"由此 (từ điều này) + 可见 (khả kiến – có thể thấy) → từ đó có thể thấy được; dùng để nêu kết luận sau khi đưa dẫn chứng.","hsk_level":"7-9","tags":["lien-tu"],"image":"👀","examples":[{"type":"basic","zh":"由此可见，他很诚实。","pinyin":"Yóucǐkějiàn, tā hěn chéngshí.","vi":"Từ đó có thể thấy anh ấy rất thật thà."},{"type":"simple","zh":"由此可见，坚持锻炼对健康很重要。","pinyin":"Yóucǐkějiàn, jiānchí duànliàn duì jiànkāng hěn zhòngyào.","vi":"Từ đó có thể thấy kiên trì tập luyện rất quan trọng với sức khỏe."},{"type":"compound","zh":"由此可见，只要方法正确，进步就会很快。","pinyin":"Yóucǐkějiàn, zhǐyào fāngfǎ zhèngquè, jìnbù jiù huì hěn kuài.","vi":"Qua đó thấy rằng chỉ cần phương pháp đúng thì sẽ tiến bộ rất nhanh."}],"related":[{"hanzi":"由此看来","pinyin":"yóucǐkànlái","vi":"xem ra"},{"hanzi":"可见","pinyin":"kějiàn","vi":"có thể thấy"},{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"vì vậy"}],"traditional":"由此可見"},{"id":"由来","hanzi":"由来","pinyin":"yóulái","meaning_vi":"nguồn gốc, lai lịch, khởi nguồn","explanation":"由 (do – từ) + 来 (lai – đến) → từ đâu mà đến, tức nguồn gốc của sự vật hay phong tục; 由来已久 là có từ lâu.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏺","examples":[{"type":"basic","zh":"你知道春节的由来吗？","pinyin":"Nǐ zhīdào Chūnjié de yóulái ma?","vi":"Bạn có biết nguồn gốc của Tết Nguyên đán không?"},{"type":"simple","zh":"老人给我们讲了这个地名的由来。","pinyin":"Lǎorén gěi wǒmen jiǎngle zhè gè dìmíng de yóulái.","vi":"Cụ già kể cho chúng tôi nghe về nguồn gốc của địa danh này."},{"type":"compound","zh":"虽然这个习俗由来已久，但是很多年轻人已经不知道了。","pinyin":"Suīrán zhè gè xísú yóulái yǐjiǔ, dànshì hěn duō niánqīngrén yǐjīng bù zhīdàole.","vi":"Tuy phong tục này có từ lâu đời nhưng nhiều người trẻ đã không còn biết đến."}],"related":[{"hanzi":"来历","pinyin":"láilì","vi":"lai lịch"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"由来已久","pinyin":"yóuláiyǐjiǔ","vi":"có từ lâu"}],"traditional":"由來"},{"id":"由衷","hanzi":"由衷","pinyin":"yóuzhōng","meaning_vi":"từ đáy lòng, chân thành","explanation":"由 (do – từ) + 衷 (trung – lòng, nội tâm) → xuất phát từ tận đáy lòng; thường dùng 由衷地 + cảm ơn, vui mừng, khâm phục.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💖","examples":[{"type":"basic","zh":"我由衷地感谢你。","pinyin":"Wǒ yóuzhōng de gǎnxiè nǐ.","vi":"Tôi chân thành cảm ơn bạn."},{"type":"simple","zh":"观众们对他的表演发出由衷的赞叹。","pinyin":"Guānzhòngmen duì tā de biǎoyǎn fāchū yóuzhōng de zàntàn.","vi":"Khán giả thốt lên lời khen ngợi từ đáy lòng trước màn biểu diễn của anh."},{"type":"compound","zh":"虽然他输了比赛，但是仍由衷地祝贺对手。","pinyin":"Suīrán tā shūle bǐsài, dànshì réng yóuzhōng de zhùhè duìshǒu.","vi":"Tuy thua trận nhưng anh ấy vẫn chân thành chúc mừng đối thủ."}],"related":[{"hanzi":"衷心","pinyin":"zhōngxīn","vi":"chân thành"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"发自内心","pinyin":"fāzìnèixīn","vi":"xuất phát từ đáy lòng"},{"hanzi":"违心","pinyin":"wéixīn","vi":"trái lòng"}]},{"id":"犹豫不决","hanzi":"犹豫不决","pinyin":"yóuyù-bùjué","meaning_vi":"do dự không quyết, lưỡng lự, chần chừ","explanation":"犹豫 (do dự – lưỡng lự) + 不决 (bất quyết – không quyết) → do dự mãi mà không đưa ra được quyết định.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🤔","examples":[{"type":"basic","zh":"他还在犹豫不决。","pinyin":"Tā hái zài yóuyùbùjué.","vi":"Anh ấy vẫn còn đang do dự."},{"type":"simple","zh":"面对两份工作，她一直犹豫不决。","pinyin":"Miànduì liǎng fèn gōngzuò, tā yìzhí yóuyùbùjué.","vi":"Đứng trước hai công việc, cô ấy cứ lưỡng lự mãi."},{"type":"compound","zh":"如果你总是犹豫不决，就会错过最好的机会。","pinyin":"Rúguǒ nǐ zǒngshì yóuyùbùjué, jiù huì cuòguò zuìhǎo de jīhuì.","vi":"Nếu bạn cứ do dự mãi thì sẽ bỏ lỡ cơ hội tốt nhất."}],"related":[{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"果断","pinyin":"guǒduàn","vi":"quả quyết"},{"hanzi":"迟疑","pinyin":"chíyí","vi":"chần chừ"},{"hanzi":"当机立断","pinyin":"dāngjīlìduàn","vi":"quyết đoán ngay"}],"traditional":"猶豫不決"},{"id":"邮编","hanzi":"邮编","pinyin":"yóubiān","meaning_vi":"mã bưu chính, mã bưu điện","explanation":"邮 (bưu – bưu điện) + 编 (biên – mã số) → viết tắt của 邮政编码, mã số bưu chính.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"📮","examples":[{"type":"basic","zh":"请写上邮编。","pinyin":"Qǐng xiě shàng yóubiān.","vi":"Vui lòng ghi mã bưu chính."},{"type":"simple","zh":"这个地址的邮编我记不清了。","pinyin":"Zhè ge dìzhǐ de yóubiān wǒ jì bùqīng le.","vi":"Tôi không nhớ rõ mã bưu chính của địa chỉ này."},{"type":"compound","zh":"如果邮编写错了，包裹就可能寄不到。","pinyin":"Rúguǒ yóu biānxiě cuò le, bāoguǒ jiù kěnéng jì búdào.","vi":"Nếu ghi sai mã bưu chính thì bưu kiện có thể không gửi tới được."}],"related":[{"hanzi":"邮政","pinyin":"yóuzhèng","vi":"bưu chính"},{"hanzi":"地址","pinyin":"dìzhǐ","vi":"địa chỉ"},{"hanzi":"邮局","pinyin":"yóujú","vi":"bưu điện"},{"hanzi":"编码","pinyin":"biānmǎ","vi":"mã số"}],"traditional":"郵編"},{"id":"邮政","hanzi":"邮政","pinyin":"yóuzhèng","meaning_vi":"bưu chính, ngành bưu điện","explanation":"邮 (bưu – thư từ) + 政 (chính – việc công) → ngành nhận và chuyển thư từ, bưu phẩm.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🏤","examples":[{"type":"basic","zh":"邮政服务很方便。","pinyin":"Yóuzhèng fúwù hěn fāngbiàn.","vi":"Dịch vụ bưu chính rất tiện lợi."},{"type":"simple","zh":"我通过邮政寄了一封信给奶奶。","pinyin":"Wǒ tōngguò yóuzhèng jìle yì fēng xìn gěi nǎinai.","vi":"Tôi gửi một lá thư cho bà qua bưu điện."},{"type":"compound","zh":"虽然快递越来越多，但是邮政仍然很重要。","pinyin":"Suīrán kuàidì yuèláiyuè duō, dànshì yóuzhèng réngrán hěn zhòngyào.","vi":"Tuy chuyển phát nhanh ngày càng nhiều nhưng bưu chính vẫn rất quan trọng."}],"related":[{"hanzi":"邮局","pinyin":"yóujú","vi":"bưu điện"},{"hanzi":"邮编","pinyin":"yóubiān","vi":"mã bưu chính"},{"hanzi":"邮票","pinyin":"yóupiào","vi":"tem thư"},{"hanzi":"快递","pinyin":"kuàidì","vi":"chuyển phát nhanh"}],"traditional":"郵政"},{"id":"油画","hanzi":"油画","pinyin":"yóuhuà","meaning_vi":"tranh sơn dầu","explanation":"油 (du – dầu) + 画 (họa – tranh) → tranh vẽ bằng màu sơn dầu.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🖼️","examples":[{"type":"basic","zh":"墙上挂着一幅油画。","pinyin":"Qiáng shang guàzhe yì fú yóuhuà.","vi":"Trên tường treo một bức tranh sơn dầu."},{"type":"simple","zh":"她在美术学院学了四年油画。","pinyin":"Tā zài měishù xuéyuàn xuéle sì nián yóuhuà.","vi":"Cô ấy học vẽ sơn dầu bốn năm ở học viện mỹ thuật."},{"type":"compound","zh":"这幅油画虽然很小，但是价格非常高。","pinyin":"Zhè fú yóuhuà suīrán hěn xiǎo, dànshì jiàgé fēicháng gāo.","vi":"Bức tranh sơn dầu này tuy nhỏ nhưng giá rất cao."}],"related":[{"hanzi":"国画","pinyin":"guóhuà","vi":"tranh quốc họa"},{"hanzi":"水彩画","pinyin":"shuǐcǎihuà","vi":"tranh màu nước"},{"hanzi":"画家","pinyin":"huàjiā","vi":"họa sĩ"},{"hanzi":"画展","pinyin":"huàzhǎn","vi":"triển lãm tranh"}],"traditional":"油畫"},{"id":"游船","hanzi":"游船","pinyin":"yóuchuán","meaning_vi":"du thuyền, thuyền du lịch","explanation":"游 (du – đi chơi) + 船 (thuyền) → thuyền chở khách tham quan, du ngoạn.","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🛳️","examples":[{"type":"basic","zh":"我们坐游船游湖。","pinyin":"Wǒmen zuò yóuchuán yóu hú.","vi":"Chúng tôi đi du thuyền dạo hồ."},{"type":"simple","zh":"晚上的游船上挤满了游客。","pinyin":"Wǎnshang de yóuchuán shang jǐmǎnle yóukè.","vi":"Du thuyền buổi tối chật kín du khách."},{"type":"compound","zh":"因为今天风浪太大，所以游船暂停开放。","pinyin":"Yīnwèi jīntiān fēnglàng tài dà, suǒyǐ yóuchuán zàntíng kāifàng.","vi":"Vì hôm nay sóng gió quá lớn nên du thuyền tạm ngừng hoạt động."}],"related":[{"hanzi":"游轮","pinyin":"yóulún","vi":"tàu du lịch"},{"hanzi":"渔船","pinyin":"yúchuán","vi":"thuyền đánh cá"},{"hanzi":"游览","pinyin":"yóulǎn","vi":"du ngoạn"},{"hanzi":"码头","pinyin":"mǎtóu","vi":"bến tàu"}],"traditional":"遊船"},{"id":"游览","hanzi":"游览","pinyin":"yóulǎn","meaning_vi":"tham quan, du ngoạn, du lãm","explanation":"游 (du – đi chơi) + 览 (lãm – ngắm xem) → đi chơi ngắm cảnh, tham quan danh lam thắng cảnh.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🗺️","examples":[{"type":"basic","zh":"我们去游览长城。","pinyin":"Wǒmen qù yóulǎn Chángchéng.","vi":"Chúng tôi đi tham quan Vạn Lý Trường Thành."},{"type":"simple","zh":"导游带大家游览了整个古镇。","pinyin":"Dǎoyóu dài dàjiā yóulǎnle zhěnggè gǔzhèn.","vi":"Hướng dẫn viên dẫn mọi người tham quan khắp thị trấn cổ."},{"type":"compound","zh":"如果时间够的话，我们就再游览一下西湖。","pinyin":"Rúguǒ shíjiān gòu dehuà, wǒmen jiù zài yóulǎn yíxià Xīhú.","vi":"Nếu đủ thời gian thì chúng ta tham quan thêm Tây Hồ."}],"related":[{"hanzi":"参观","pinyin":"cānguān","vi":"tham quan"},{"hanzi":"旅游","pinyin":"lǚyóu","vi":"du lịch"},{"hanzi":"观光","pinyin":"guānguāng","vi":"ngắm cảnh"},{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm du lịch"}],"traditional":"遊覽"},{"id":"有待","hanzi":"有待","pinyin":"yǒudài","meaning_vi":"còn chờ, còn cần phải, còn đợi","explanation":"有 (hữu – có) + 待 (đãi – chờ đợi) → việc vẫn còn phải chờ làm, chưa xong; thường đi với động từ hai âm tiết.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏳","examples":[{"type":"basic","zh":"这个问题有待解决。","pinyin":"Zhè ge wèntí yǒudài jiějué.","vi":"Vấn đề này còn chờ giải quyết."},{"type":"simple","zh":"新药的效果还有待进一步观察。","pinyin":"Xīn yào de xiàoguǒ hái yǒudài jìnyíbù guānchá.","vi":"Hiệu quả của thuốc mới còn cần theo dõi thêm."},{"type":"compound","zh":"虽然计划已经通过，但是细节还有待讨论。","pinyin":"Suīrán jìhuà yǐjīng tōngguò, dànshì xìjié hái yǒudài tǎolùn.","vi":"Tuy kế hoạch đã được thông qua nhưng chi tiết vẫn còn phải thảo luận."}],"related":[{"hanzi":"等待","pinyin":"děngdài","vi":"chờ đợi"},{"hanzi":"有望","pinyin":"yǒuwàng","vi":"có triển vọng"},{"hanzi":"尚待","pinyin":"shàngdài","vi":"vẫn còn chờ"},{"hanzi":"期待","pinyin":"qīdài","vi":"mong đợi"}]},{"id":"有的放矢","hanzi":"有的放矢","pinyin":"yǒudì-fàngshǐ","meaning_vi":"có mục tiêu rõ ràng, nhắm đúng đích","explanation":"Nghĩa đen: có đích (的 – đích, bia) rồi mới bắn tên (矢 – thỉ, mũi tên) → nói năng, làm việc có mục tiêu cụ thể, nhắm đúng vấn đề.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🎯","examples":[{"type":"basic","zh":"学习要有的放矢。","pinyin":"Xuéxí yào yǒudìfàngshǐ.","vi":"Học tập phải có mục tiêu rõ ràng."},{"type":"simple","zh":"老师针对弱点有的放矢地辅导学生。","pinyin":"Lǎoshī zhēnduì ruòdiǎn yǒudìfàngshǐ de fǔdǎo xuésheng.","vi":"Thầy giáo kèm học sinh nhắm đúng vào điểm yếu."},{"type":"compound","zh":"只有先了解客户需求，才能有的放矢地推销产品。","pinyin":"Zhǐyǒu xiān liǎojiě kèhù xūqiú, cáinéng yǒudìfàngshǐ de tuīxiāo chǎnpǐn.","vi":"Chỉ khi hiểu nhu cầu khách hàng trước thì mới chào bán sản phẩm đúng trọng tâm được."}],"related":[{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"},{"hanzi":"对症下药","pinyin":"duìzhèngxiàyào","vi":"bốc thuốc đúng bệnh"},{"hanzi":"无的放矢","pinyin":"wúdìfàngshǐ","vi":"bắn tên không đích"},{"hanzi":"针对","pinyin":"zhēnduì","vi":"nhằm vào"}]},{"id":"有口无心","hanzi":"有口无心","pinyin":"yǒukǒu-wúxīn","meaning_vi":"nói vậy chứ không có ý xấu, miệng nói mà lòng không ác","explanation":"Nghĩa đen: có miệng (口 – khẩu) mà không có lòng (心 – tâm) → lời nói có thể khó nghe nhưng không hề có ác ý.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他这人有口无心。","pinyin":"Tā zhè rén yǒukǒuwúxīn.","vi":"Anh ta nói vậy thôi chứ không có ý xấu."},{"type":"simple","zh":"我知道他说话向来有口无心。","pinyin":"Wǒ zhīdào tā shuōhuà xiànglái yǒukǒuwúxīn.","vi":"Tôi biết anh ấy xưa nay nói năng chẳng có ác ý gì."},{"type":"compound","zh":"虽然他有口无心，但是那句话还是伤了她的心。","pinyin":"Suīrán tā yǒukǒuwúxīn, dànshì nà jù huà háishi shāngle tā de xīn.","vi":"Tuy anh ấy không có ý xấu nhưng câu nói đó vẫn làm cô ấy tổn thương."}],"related":[{"hanzi":"心直口快","pinyin":"xīnzhíkǒukuài","vi":"thẳng tính, nghĩ gì nói nấy"},{"hanzi":"刀子嘴豆腐心","pinyin":"dāozi zuǐ dòufu xīn","vi":"miệng cứng lòng mềm"},{"hanzi":"口是心非","pinyin":"kǒushìxīnfēi","vi":"khẩu thị tâm phi"},{"hanzi":"无心","pinyin":"wúxīn","vi":"vô tình"}],"traditional":"有口無心"},{"id":"有两下子","hanzi":"有两下子","pinyin":"yǒuliǎng-xiàzi","meaning_vi":"có tài, có nghề, giỏi thật","explanation":"有 (hữu – có) + 两下子 (vài đường, vài chiêu) → khẩu ngữ: có bản lĩnh, có tay nghề thật sự.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"💪","examples":[{"type":"basic","zh":"你真有两下子！","pinyin":"Nǐ zhēn yǒuliǎngxiàzi!","vi":"Bạn giỏi thật đấy!"},{"type":"simple","zh":"没想到这个年轻厨师还真有两下子。","pinyin":"Méi xiǎngdào zhè ge niánqīng chúshī hái zhēn yǒuliǎngxiàzi.","vi":"Không ngờ anh đầu bếp trẻ này giỏi thật."},{"type":"compound","zh":"虽然他刚学修车，但是确实有两下子。","pinyin":"Suīrán tā gāng xué xiūchē, dànshì quèshí yǒuliǎngxiàzi.","vi":"Tuy mới học sửa xe nhưng anh ấy đúng là có nghề."}],"related":[{"hanzi":"本事","pinyin":"běnshi","vi":"bản lĩnh"},{"hanzi":"能耐","pinyin":"néngnai","vi":"tài cán"},{"hanzi":"两下子","pinyin":"liǎngxiàzi","vi":"ngón nghề"},{"hanzi":"了不起","pinyin":"liǎobuqǐ","vi":"giỏi giang"}],"traditional":"有兩下子"},{"id":"有所","hanzi":"有所","pinyin":"yǒusuǒ","meaning_vi":"có phần, ít nhiều, phần nào","explanation":"有 (hữu – có) + 所 (sở – trợ từ chỉ đối tượng) → có ít nhiều, có phần; đặt trước động từ hai âm tiết như 有所提高, 有所改善.","hsk_level":"7-9","tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"情况有所好转。","pinyin":"Qíngkuàng yǒusuǒ hǎozhuǎn.","vi":"Tình hình có phần khá lên."},{"type":"simple","zh":"这个月的销售额比上个月有所增加。","pinyin":"Zhè geyuè de xiāoshòu'é bǐ shànggeyuè yǒusuǒ zēngjiā.","vi":"Doanh số tháng này tăng phần nào so với tháng trước."},{"type":"compound","zh":"只要坚持锻炼，你的体质就会有所改善。","pinyin":"Zhǐyào jiānchí duànliàn, nǐ de tǐzhì jiù huì yǒusuǒ gǎishàn.","vi":"Chỉ cần kiên trì tập luyện thì thể chất của bạn sẽ được cải thiện phần nào."}],"related":[{"hanzi":"有所不同","pinyin":"yǒusuǒbùtóng","vi":"có phần khác"},{"hanzi":"略有","pinyin":"lüèyǒu","vi":"hơi có"},{"hanzi":"多少","pinyin":"duōshǎo","vi":"ít nhiều"},{"hanzi":"一无所有","pinyin":"yìwúsuǒyǒu","vi":"không có gì"}]},{"id":"有所不同","hanzi":"有所不同","pinyin":"yǒusuǒ-bùtóng","meaning_vi":"có phần khác nhau, hơi khác","explanation":"有所 (có phần) + 不同 (bất đồng – không giống) → có chỗ khác nhau, không hoàn toàn giống.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"两地风俗有所不同。","pinyin":"Liǎng dì fēngsú yǒusuǒbùtóng.","vi":"Phong tục hai nơi có phần khác nhau."},{"type":"simple","zh":"每个人对幸福的理解有所不同。","pinyin":"Měigerén duì xìngfú de lǐjiě yǒusuǒbùtóng.","vi":"Cách hiểu về hạnh phúc của mỗi người có phần khác nhau."},{"type":"compound","zh":"虽然这两款手机外观相似，但是功能有所不同。","pinyin":"Suīrán zhè liǎng kuǎn shǒujī wàiguān xiāngsì, dànshì gōngnéng yǒusuǒbùtóng.","vi":"Tuy hai mẫu điện thoại này bề ngoài giống nhau nhưng chức năng hơi khác."}],"related":[{"hanzi":"有所","pinyin":"yǒusuǒ","vi":"có phần"},{"hanzi":"不同","pinyin":"bùtóng","vi":"khác nhau"},{"hanzi":"大同小异","pinyin":"dàtóngxiǎoyì","vi":"na ná nhau"},{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác"}]},{"id":"有望","hanzi":"有望","pinyin":"yǒuwàng","meaning_vi":"có triển vọng, có hy vọng","explanation":"有 (hữu – có) + 望 (vọng – hy vọng) → có khả năng đạt được, có triển vọng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"他有望夺冠。","pinyin":"Tā yǒuwàng duóguàn.","vi":"Anh ấy có triển vọng giành chức vô địch."},{"type":"simple","zh":"这条地铁线有望明年年底通车。","pinyin":"Zhè tiáo dìtiě xiàn yǒuwàng míngnián niándǐ tōngchē.","vi":"Tuyến tàu điện ngầm này có triển vọng thông xe vào cuối năm sau."},{"type":"compound","zh":"如果谈判顺利，两家公司就有望达成合作。","pinyin":"Rúguǒ tánpàn shùnlì, liǎng jiā gōngsī jiù yǒuwàng dáchéng hézuò.","vi":"Nếu đàm phán suôn sẻ thì hai công ty có triển vọng đạt được hợp tác."}],"related":[{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"},{"hanzi":"有待","pinyin":"yǒudài","vi":"còn chờ"},{"hanzi":"无望","pinyin":"wúwàng","vi":"vô vọng"},{"hanzi":"前景","pinyin":"qiánjǐng","vi":"triển vọng"}]},{"id":"有效期","hanzi":"有效期","pinyin":"yǒuxiàoqī","meaning_vi":"thời hạn hiệu lực, hạn sử dụng","explanation":"有效 (hữu hiệu – có hiệu lực) + 期 (kỳ – thời hạn) → khoảng thời gian còn hiệu lực hoặc còn hạn dùng.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"护照的有效期快到了。","pinyin":"Hùzhào de yǒuxiàoqī kuài dào le.","vi":"Hộ chiếu sắp hết hạn hiệu lực."},{"type":"simple","zh":"这张优惠券的有效期只有一个月。","pinyin":"Zhè zhāng yōuhuìquàn de yǒuxiàoqī zhǐyǒu yí geyuè.","vi":"Phiếu giảm giá này chỉ có hiệu lực một tháng."},{"type":"compound","zh":"一旦过了有效期，这瓶药就不能再吃了。","pinyin":"Yídànguò le yǒuxiàoqī, zhè píng yào jiù bù néng zài chī le.","vi":"Một khi quá hạn sử dụng thì lọ thuốc này không được uống nữa."}],"related":[{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu lực"},{"hanzi":"保质期","pinyin":"bǎozhìqī","vi":"hạn bảo quản"},{"hanzi":"过期","pinyin":"guòqī","vi":"quá hạn"},{"hanzi":"期限","pinyin":"qīxiàn","vi":"kỳ hạn"}]},{"id":"有幸","hanzi":"有幸","pinyin":"yǒuxìng","meaning_vi":"có may mắn, hân hạnh được","explanation":"有 (hữu – có) + 幸 (hạnh – may mắn) → có được may mắn, vinh hạnh được làm điều gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍀","examples":[{"type":"basic","zh":"我有幸见过他。","pinyin":"Wǒ yǒuxìng jiànguo tā.","vi":"Tôi may mắn đã từng gặp ông ấy."},{"type":"simple","zh":"我们有幸参加了这次国际会议。","pinyin":"Wǒmen yǒuxìng cānjiāle zhè cì Guójì huìyì.","vi":"Chúng tôi hân hạnh được tham dự hội nghị quốc tế lần này."},{"type":"compound","zh":"因为有幸遇到一位好老师，所以他爱上了数学。","pinyin":"Yīnwèi yǒuxìng yùdào yí wèi hǎo lǎoshī, suǒyǐ tā àishàngle shùxué.","vi":"Vì may mắn gặp được một thầy giáo giỏi nên cậu ấy yêu môn toán."}],"related":[{"hanzi":"幸运","pinyin":"xìngyùn","vi":"may mắn"},{"hanzi":"荣幸","pinyin":"róngxìng","vi":"vinh hạnh"},{"hanzi":"不幸","pinyin":"búxìng","vi":"bất hạnh"},{"hanzi":"庆幸","pinyin":"qìngxìng","vi":"mừng vì may mắn"}]},{"id":"有序","hanzi":"有序","pinyin":"yǒuxù","meaning_vi":"có trật tự, ngăn nắp, tuần tự","explanation":"有 (hữu – có) + 序 (tự – thứ tự) → có thứ tự, có trật tự.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🚶","examples":[{"type":"basic","zh":"乘客有序上车。","pinyin":"Chéngkè yǒuxù shàngchē.","vi":"Hành khách lên xe có trật tự."},{"type":"simple","zh":"工作人员组织观众有序离开体育馆。","pinyin":"Gōngzuò rényuán zǔzhī guānzhòng yǒuxù líkāi tǐyùguǎn.","vi":"Nhân viên tổ chức cho khán giả rời nhà thi đấu có trật tự."},{"type":"compound","zh":"只要大家有序排队上车，就不会发生拥挤。","pinyin":"Zhǐyào dàjiā yǒuxù páiduì shàngchē, jiù bú huì fāshēng yōngjǐ.","vi":"Chỉ cần mọi người xếp hàng lên xe có trật tự thì sẽ không xảy ra chen lấn."}],"related":[{"hanzi":"秩序","pinyin":"zhìxù","vi":"trật tự"},{"hanzi":"顺序","pinyin":"shùnxù","vi":"thứ tự"},{"hanzi":"无序","pinyin":"wúxù","vi":"hỗn loạn"},{"hanzi":"井然有序","pinyin":"jǐngrányǒuxù","vi":"ngăn nắp trật tự"}]},{"id":"有益","hanzi":"有益","pinyin":"yǒuyì","meaning_vi":"có ích, có lợi, bổ ích","explanation":"有 (hữu – có) + 益 (ích – lợi ích) → có lợi, mang lại ích lợi.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👍","examples":[{"type":"basic","zh":"散步对身体有益。","pinyin":"Sànbù duì shēntǐ yǒuyì.","vi":"Đi dạo có lợi cho sức khỏe."},{"type":"simple","zh":"多读书是一种非常有益的习惯。","pinyin":"Duō dúshū shì yì zhǒng fēicháng yǒuyì de xíguàn.","vi":"Đọc nhiều sách là một thói quen rất có ích."},{"type":"compound","zh":"虽然这些建议很尖锐，但是对我非常有益。","pinyin":"Suīrán zhèxiē jiànyì hěn jiānruì, dànshì duì wǒ fēicháng yǒuyì.","vi":"Tuy những góp ý này rất gay gắt nhưng lại rất có ích cho tôi."}],"related":[{"hanzi":"有利","pinyin":"yǒulì","vi":"có lợi"},{"hanzi":"有害","pinyin":"yǒuhài","vi":"có hại"},{"hanzi":"益处","pinyin":"yìchu","vi":"lợi ích"},{"hanzi":"无益","pinyin":"wúyì","vi":"vô ích"}]},{"id":"有意","hanzi":"有意","pinyin":"yǒuyì","meaning_vi":"cố ý, có ý định, có ý muốn","explanation":"有 (hữu – có) + 意 (ý – ý định) → có chủ ý, cố tình; cũng chỉ có ý muốn làm việc gì.","hsk_level":"7-9","tags":["pho-tu"],"image":"😏","examples":[{"type":"basic","zh":"他不是有意的。","pinyin":"Tā bú shì yǒuyì de.","vi":"Anh ấy không cố ý đâu."},{"type":"simple","zh":"这家公司有意在越南开设分厂。","pinyin":"Zhè jiā gōngsī yǒu yìzài Yuènán kāishè fēn chǎng.","vi":"Công ty này có ý định mở nhà máy chi nhánh ở Việt Nam."},{"type":"compound","zh":"如果你有意报名，就请在周五前联系我。","pinyin":"Rúguǒ nǐ yǒuyì bàomíng, jiù qǐng zài Zhōuwǔ qián liánxì wǒ.","vi":"Nếu bạn muốn đăng ký thì hãy liên hệ tôi trước thứ Sáu."}],"related":[{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"},{"hanzi":"无意","pinyin":"wúyì","vi":"vô tình"},{"hanzi":"有心","pinyin":"yǒuxīn","vi":"có lòng"},{"hanzi":"意图","pinyin":"yìtú","vi":"ý đồ"}]},{"id":"有助于","hanzi":"有助于","pinyin":"yǒuzhùyú","meaning_vi":"giúp ích cho, có lợi cho, góp phần","explanation":"有 (hữu – có) + 助 (trợ – giúp) + 于 (vu – cho) → có tác dụng hỗ trợ cho việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"运动有助于睡眠。","pinyin":"Yùndòng yǒuzhùyú shuìmián.","vi":"Vận động giúp ngủ ngon hơn."},{"type":"simple","zh":"多听多说有助于提高口语水平。","pinyin":"Duō tīng duō shuō yǒuzhùyú tígāo kǒuyǔ shuǐpíng.","vi":"Nghe nhiều nói nhiều giúp nâng cao trình độ khẩu ngữ."},{"type":"compound","zh":"因为绿茶有助于消化，所以他饭后常喝一杯。","pinyin":"Yīnwèi lǜchá yǒuzhùyú xiāohuà, suǒyǐ tā fàn hòu cháng hē yì bēi.","vi":"Vì trà xanh giúp tiêu hóa nên anh ấy thường uống một cốc sau bữa ăn."}],"related":[{"hanzi":"有利于","pinyin":"yǒulìyú","vi":"có lợi cho"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"},{"hanzi":"有益","pinyin":"yǒuyì","vi":"có ích"},{"hanzi":"促进","pinyin":"cùjìn","vi":"thúc đẩy"}],"traditional":"有助於"},{"id":"诱饵","hanzi":"诱饵","pinyin":"yòu'ěr","meaning_vi":"mồi nhử, mồi câu","explanation":"诱 (dụ – dụ dỗ) + 饵 (nhị – mồi) → mồi để dụ cá, thú; nghĩa bóng là thứ dùng để dụ người mắc bẫy.","hsk_level":"7-9","tags":["danh-tu"],"image":"🪱","examples":[{"type":"basic","zh":"鱼咬住了诱饵。","pinyin":"Yú yǎo zhùle yòu'ěr.","vi":"Cá đã cắn mồi."},{"type":"simple","zh":"骗子用高额回报作诱饵骗取钱财。","pinyin":"Piànzi yòng gāo'é huíbào zuò yòu'ěr piànqǔ qiáncái.","vi":"Kẻ lừa đảo dùng lợi nhuận cao làm mồi nhử để lừa tiền."},{"type":"compound","zh":"即使诱饵再诱人，聪明的狐狸也不会上当。","pinyin":"Jíshǐ yòu'ěr zài yòurén, cōngmíng de húli yě bú huì shàngdàng.","vi":"Dù mồi nhử hấp dẫn đến đâu, con cáo khôn cũng không mắc lừa."}],"related":[{"hanzi":"鱼饵","pinyin":"yú'ěr","vi":"mồi câu cá"},{"hanzi":"诱惑","pinyin":"yòuhuò","vi":"cám dỗ"},{"hanzi":"陷阱","pinyin":"xiànjǐng","vi":"cạm bẫy"},{"hanzi":"引诱","pinyin":"yǐnyòu","vi":"dụ dỗ"}],"traditional":"誘餌"},{"id":"诱发","hanzi":"诱发","pinyin":"yòufā","meaning_vi":"gây ra, dẫn đến, kích phát","explanation":"诱 (dụ – dẫn dụ) + 发 (phát – phát sinh) → khiến cho phát sinh, thường nói về bệnh tật hay sự cố.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"⚠️","examples":[{"type":"basic","zh":"熬夜会诱发疾病。","pinyin":"Áoyè huì yòufā jíbìng.","vi":"Thức khuya có thể gây ra bệnh tật."},{"type":"simple","zh":"天气突然变冷容易诱发心脏病。","pinyin":"Tiānqì tūrán biàn lěng róngyì yòufā xīnzàngbìng.","vi":"Thời tiết đột ngột trở lạnh dễ gây ra bệnh tim."},{"type":"compound","zh":"如果长期压力过大，就可能诱发胃病。","pinyin":"Rúguǒ chángqī yālìguò dà, jiù kěnéng yòufā wèibìng.","vi":"Nếu áp lực quá lớn trong thời gian dài thì có thể gây ra bệnh dạ dày."}],"related":[{"hanzi":"引发","pinyin":"yǐnfā","vi":"gây ra"},{"hanzi":"导致","pinyin":"dǎozhì","vi":"dẫn đến"},{"hanzi":"诱因","pinyin":"yòuyīn","vi":"nguyên nhân gây ra"},{"hanzi":"激发","pinyin":"jīfā","vi":"kích phát"}],"traditional":"誘發"},{"id":"友情","hanzi":"友情","pinyin":"yǒuqíng","meaning_vi":"tình bạn, tình hữu nghị","explanation":"友 (hữu – bạn) + 情 (tình – tình cảm) → tình cảm giữa bạn bè.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"👫","examples":[{"type":"basic","zh":"我很珍惜这段友情。","pinyin":"Wǒ hěn zhēnxī zhè duàn yǒuqíng.","vi":"Tôi rất trân trọng tình bạn này."},{"type":"simple","zh":"他们的友情经受住了时间的考验。","pinyin":"Tāmen de yǒuqíng jīngshòu zhùle shíjiān de kǎoyàn.","vi":"Tình bạn của họ đã vượt qua thử thách của thời gian."},{"type":"compound","zh":"虽然我们分开多年，但是友情从来没有变过。","pinyin":"Suīrán wǒmen fēnkāi duōnián, dànshì yǒuqíng cónglái méiyǒu biàn guo.","vi":"Tuy chúng tôi xa nhau nhiều năm nhưng tình bạn chưa bao giờ thay đổi."}],"related":[{"hanzi":"友谊","pinyin":"yǒuyì","vi":"tình hữu nghị"},{"hanzi":"爱情","pinyin":"àiqíng","vi":"tình yêu"},{"hanzi":"亲情","pinyin":"qīnqíng","vi":"tình thân"},{"hanzi":"友人","pinyin":"yǒurén","vi":"bạn bè"}]},{"id":"友人","hanzi":"友人","pinyin":"yǒurén","meaning_vi":"bạn, bạn bè, người bạn","explanation":"友 (hữu – bạn) + 人 (nhân – người) → người bạn; sắc thái trang trọng, hay dùng trong văn viết.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧑‍🤝‍🧑","examples":[{"type":"basic","zh":"她请来几位友人。","pinyin":"Tā qǐng lái jǐ wèi yǒurén.","vi":"Cô ấy mời đến mấy người bạn."},{"type":"simple","zh":"这次访问受到了外国友人的欢迎。","pinyin":"Zhè cì fǎngwèn shòudàole wàiguó yǒurén de huānyíng.","vi":"Chuyến thăm lần này được bạn bè quốc tế hoan nghênh."},{"type":"compound","zh":"因为得到友人的帮助，所以他很快在北京安顿下来。","pinyin":"Yīnwèi dédào yǒurén de bāngzhù, suǒyǐ tā hěn kuài zài Běijīng āndùn xiàlái.","vi":"Nhờ được bạn bè giúp đỡ nên anh ấy nhanh chóng ổn định cuộc sống ở Bắc Kinh."}],"related":[{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"},{"hanzi":"友情","pinyin":"yǒuqíng","vi":"tình bạn"},{"hanzi":"好友","pinyin":"hǎoyǒu","vi":"bạn thân"},{"hanzi":"友善","pinyin":"yǒushàn","vi":"thân thiện"}]},{"id":"友善","hanzi":"友善","pinyin":"yǒushàn","meaning_vi":"thân thiện, hữu hảo","explanation":"友 (hữu – bạn bè) + 善 (thiện – tốt lành) → đối xử tử tế, thân thiện như với bạn.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"当地人很友善。","pinyin":"Dāngdìrén hěn yǒushàn.","vi":"Người dân địa phương rất thân thiện."},{"type":"simple","zh":"新同事对我露出了友善的微笑。","pinyin":"Xīn tóngshì duì wǒ lùchūle yǒushàn de wēixiào.","vi":"Đồng nghiệp mới nở nụ cười thân thiện với tôi."},{"type":"compound","zh":"只要你待人友善，别人就愿意帮助你。","pinyin":"Zhǐyào nǐ dàirén yǒushàn, biérén jiù yuànyì bāngzhù nǐ.","vi":"Chỉ cần bạn đối xử thân thiện với mọi người thì họ sẽ sẵn lòng giúp bạn."}],"related":[{"hanzi":"友好","pinyin":"yǒuhǎo","vi":"hữu hảo"},{"hanzi":"和善","pinyin":"héshàn","vi":"hiền hòa"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"敌意","pinyin":"díyì","vi":"thù địch"}]},{"id":"余","hanzi":"余","pinyin":"yú","meaning_vi":"dư, thừa; hơn, trên (số lẻ); ngoài, sau (vd 课余)","explanation":"余 (dư – thừa ra) → phần còn lại, dư ra; đặt sau số tròn để chỉ \"hơn\", như 十余人 (hơn mười người); còn là họ Dư.","hsk_level":"7-9","tags":["so-dem","so-luong"],"image":"➕","examples":[{"type":"basic","zh":"现场来了百余人。","pinyin":"Xiànchǎng láile bǎiyú rén.","vi":"Hiện trường có hơn một trăm người đến."},{"type":"simple","zh":"这座古桥已有八百余年的历史。","pinyin":"Zhè zuò gǔ qiáo yǐ yǒu bā bǎi yúnián de lìshǐ.","vi":"Cây cầu cổ này đã có lịch sử hơn tám trăm năm."},{"type":"compound","zh":"虽然工资不高，但是每月还能余下一点钱。","pinyin":"Suīrán gōngzī bù gāo, dànshì měiyuè hái néng yúxià yìdiǎn qián.","vi":"Tuy lương không cao nhưng mỗi tháng vẫn dư ra được chút tiền."}],"related":[{"hanzi":"剩余","pinyin":"shèngyú","vi":"còn thừa"},{"hanzi":"余额","pinyin":"yú'é","vi":"số dư"},{"hanzi":"多余","pinyin":"duōyú","vi":"dư thừa"},{"hanzi":"业余","pinyin":"yèyú","vi":"nghiệp dư"}],"traditional":"餘"},{"id":"余额","hanzi":"余额","pinyin":"yú'é","meaning_vi":"số dư (tài khoản), phần còn lại","explanation":"余 (dư – còn lại) + 额 (ngạch – mức, số lượng) → số tiền còn lại trong tài khoản, hóa đơn.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"卡里余额不足。","pinyin":"Kǎ li yú'é bùzú.","vi":"Số dư trong thẻ không đủ."},{"type":"simple","zh":"我每天睡前都会查一下银行卡余额。","pinyin":"Wǒ měitiān shuì qián dōuhuì chá yíxià yínhángkǎ yú'é.","vi":"Mỗi tối trước khi ngủ tôi đều kiểm tra số dư thẻ ngân hàng."},{"type":"compound","zh":"如果话费余额不足，手机就会自动停机。","pinyin":"Rúguǒ huàfèi yú'é bùzú, shǒujī jiù huì zìdòng tíngjī.","vi":"Nếu số dư cước điện thoại không đủ thì máy sẽ tự động bị khóa."}],"related":[{"hanzi":"余","pinyin":"yú","vi":"dư"},{"hanzi":"账户","pinyin":"zhànghù","vi":"tài khoản"},{"hanzi":"存款","pinyin":"cúnkuǎn","vi":"tiền gửi"},{"hanzi":"充值","pinyin":"chōngzhí","vi":"nạp tiền"}],"traditional":"餘額"},{"id":"渔船","hanzi":"渔船","pinyin":"yúchuán","meaning_vi":"thuyền đánh cá, tàu cá","explanation":"渔 (ngư – đánh cá) + 船 (thuyền) → thuyền dùng để đánh bắt cá.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"⛵","examples":[{"type":"basic","zh":"渔船回港了。","pinyin":"Yúchuán huí gǎng le.","vi":"Thuyền đánh cá đã về cảng."},{"type":"simple","zh":"清晨的海面上漂着几艘小渔船。","pinyin":"Qīngchén de hǎimiàn shang piāozhe jǐ sōu xiǎo yúchuán.","vi":"Trên mặt biển lúc sáng sớm có mấy chiếc thuyền đánh cá nhỏ."},{"type":"compound","zh":"因为台风快要来了，所以渔船都提前回港避风。","pinyin":"Yīnwèi táifēng kuàiyào lái le, suǒyǐ yúchuán dōu tíqián huí gǎng bìfēng.","vi":"Vì bão sắp đến nên các tàu cá đều về cảng tránh gió sớm."}],"related":[{"hanzi":"渔民","pinyin":"yúmín","vi":"ngư dân"},{"hanzi":"游船","pinyin":"yóuchuán","vi":"du thuyền"},{"hanzi":"渔网","pinyin":"yúwǎng","vi":"lưới đánh cá"},{"hanzi":"捕鱼","pinyin":"bǔyú","vi":"đánh bắt cá"}],"traditional":"漁船"},{"id":"逾期","hanzi":"逾期","pinyin":"yúqī","meaning_vi":"quá hạn, trễ hạn","explanation":"逾 (du – vượt quá) + 期 (kỳ – thời hạn) → vượt quá thời hạn quy định.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"贷款已经逾期了。","pinyin":"Dàikuǎn yǐjīng yúqī le.","vi":"Khoản vay đã quá hạn rồi."},{"type":"simple","zh":"图书馆的书逾期归还要交罚款。","pinyin":"Túshūguǎn de shū yúqī guīhuán yào jiāo fákuǎn.","vi":"Sách thư viện trả quá hạn phải nộp phạt."},{"type":"compound","zh":"如果逾期不交房租，房东就会收回房子。","pinyin":"Rúguǒ yúqī bù jiāo fángzū, fángdōng jiù huì shōuhuí fángzi.","vi":"Nếu quá hạn không nộp tiền thuê thì chủ nhà sẽ lấy lại nhà."}],"related":[{"hanzi":"过期","pinyin":"guòqī","vi":"hết hạn"},{"hanzi":"到期","pinyin":"dàoqī","vi":"đến hạn"},{"hanzi":"期限","pinyin":"qīxiàn","vi":"kỳ hạn"},{"hanzi":"按期","pinyin":"ànqī","vi":"đúng hạn"}]},{"id":"与此同时","hanzi":"与此同时","pinyin":"yǔcǐtóngshí","meaning_vi":"đồng thời, cùng lúc đó","explanation":"与 (dữ – với) + 此 (thử – điều này) + 同时 (đồng thời – cùng lúc) → cùng lúc với việc này; dùng để nối hai sự việc diễn ra song song.","hsk_level":"7-9","tags":["lien-tu","thoi-gian"],"image":"🔀","examples":[{"type":"basic","zh":"与此同时，雨停了。","pinyin":"Yǔcǐtóngshí, yǔ tíng le.","vi":"Cùng lúc đó, mưa tạnh."},{"type":"simple","zh":"与此同时，警方也开始调查此事。","pinyin":"Yǔcǐtóngshí, jǐngfāng yě kāishǐ diàochá cǐshì.","vi":"Đồng thời, cảnh sát cũng bắt đầu điều tra vụ việc."},{"type":"compound","zh":"经济发展很快，与此同时，环境问题也越来越严重。","pinyin":"Jīngjì fāzhǎn hěn kuài, yǔcǐtóngshí, huánjìng wèntí yě yuèláiyuè yánzhòng.","vi":"Kinh tế phát triển nhanh, đồng thời vấn đề môi trường cũng ngày càng nghiêm trọng."}],"related":[{"hanzi":"同时","pinyin":"tóngshí","vi":"đồng thời"},{"hanzi":"此外","pinyin":"cǐwài","vi":"ngoài ra"},{"hanzi":"并且","pinyin":"bìngqiě","vi":"hơn nữa"},{"hanzi":"与此相反","pinyin":"yǔcǐxiāngfǎn","vi":"ngược lại với điều này"}],"traditional":"與此同時"},{"id":"与否","hanzi":"与否","pinyin":"yǔfǒu","meaning_vi":"hay không, có… hay không","explanation":"与 (dữ – và) + 否 (phủ – không) → đặt sau động từ hoặc tính từ để chỉ \"có… hay không\"; dùng trong văn viết.","hsk_level":"7-9","tags":["tro-tu"],"image":"❓","examples":[{"type":"basic","zh":"成功与否不重要。","pinyin":"Chénggōng yǔfǒu bú zhòngyào.","vi":"Thành công hay không không quan trọng."},{"type":"simple","zh":"比赛举行与否要看明天的天气。","pinyin":"Bǐsài jǔxíng yǔfǒu yào kàn míngtiān de tiānqì.","vi":"Trận đấu có diễn ra hay không còn tùy thời tiết ngày mai."},{"type":"compound","zh":"无论你同意与否，我们都要按计划进行。","pinyin":"Wúlùn nǐ tóngyì yǔfǒu, wǒmen dōu yào àn jìhuà jìnxíng.","vi":"Dù bạn đồng ý hay không, chúng tôi vẫn phải tiến hành theo kế hoạch."}],"related":[{"hanzi":"是否","pinyin":"shìfǒu","vi":"có… không"},{"hanzi":"能否","pinyin":"néngfǒu","vi":"có thể không"},{"hanzi":"否则","pinyin":"fǒuzé","vi":"nếu không thì"},{"hanzi":"否定","pinyin":"fǒudìng","vi":"phủ định"}],"traditional":"與否"},{"id":"与其","hanzi":"与其","pinyin":"yǔqí","meaning_vi":"thà… còn hơn, thay vì… chi bằng","explanation":"与 (dữ – so với) + 其 (kỳ – điều đó) → dùng trong cấu trúc 与其 A，不如 B: thay vì A thì chi bằng B.","hsk_level":"7-9","tags":["lien-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"与其等待，不如行动。","pinyin":"Yǔqí děngdài, bùrú xíngdòng.","vi":"Thay vì chờ đợi, chi bằng hành động."},{"type":"simple","zh":"与其在家发呆，不如出去走走。","pinyin":"Yǔqí zài jiā fādāi, bùrú chūqù zǒu zou.","vi":"Thay vì ngồi ở nhà thẫn thờ, chi bằng ra ngoài đi dạo."},{"type":"compound","zh":"与其花钱买新的，不如把旧电脑修一修，因为它还很好用。","pinyin":"Yǔqí huāqián mǎi xīn de, bùrú bǎ jiù diànnǎo xiū yi xiū, yīnwèi tā hái hěn hǎoyòng.","vi":"Thay vì tốn tiền mua cái mới, chi bằng sửa lại máy tính cũ, vì nó vẫn dùng tốt."}],"related":[{"hanzi":"不如","pinyin":"bùrú","vi":"chi bằng"},{"hanzi":"宁可","pinyin":"nìngkě","vi":"thà rằng"},{"hanzi":"宁愿","pinyin":"nìngyuàn","vi":"thà"},{"hanzi":"与其说","pinyin":"yǔqíshuō","vi":"nói là… chi bằng"}],"traditional":"與其"},{"id":"予以","hanzi":"予以","pinyin":"yǔyǐ","meaning_vi":"cho, dành cho, tiến hành (văn viết)","explanation":"予 (dữ – cho) + 以 (dĩ – lấy, bằng) → trao cho, áp dụng; văn viết, đi với động từ hai âm tiết như 予以表扬, 予以处罚.","hsk_level":"7-9","tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"学校予以表扬。","pinyin":"Xuéxiào yǔyǐ biǎoyáng.","vi":"Nhà trường đã biểu dương."},{"type":"simple","zh":"公司对违反规定的员工予以处罚。","pinyin":"Gōngsī duì wéifǎn guīdìng de yuángōng yǔyǐ chǔfá.","vi":"Công ty xử phạt những nhân viên vi phạm quy định."},{"type":"compound","zh":"如果发现假冒产品，有关部门就会予以没收。","pinyin":"Rúguǒ fāxiàn jiǎmào chǎnpǐn, yǒuguān bùmén jiù huì yǔyǐ mòshōu.","vi":"Nếu phát hiện hàng giả thì cơ quan chức năng sẽ tịch thu."}],"related":[{"hanzi":"给予","pinyin":"jǐyǔ","vi":"dành cho"},{"hanzi":"加以","pinyin":"jiāyǐ","vi":"tiến hành"},{"hanzi":"授予","pinyin":"shòuyǔ","vi":"trao tặng"},{"hanzi":"赋予","pinyin":"fùyǔ","vi":"giao phó"}]},{"id":"宇宙","hanzi":"宇宙","pinyin":"yǔzhòu","meaning_vi":"vũ trụ","explanation":"宇 (vũ – không gian) + 宙 (trụ – thời gian) → toàn bộ không gian và thời gian, tức vũ trụ.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌌","examples":[{"type":"basic","zh":"宇宙无边无际。","pinyin":"Yǔzhòu wúbiān wújì.","vi":"Vũ trụ mênh mông vô tận."},{"type":"simple","zh":"科学家一直在探索宇宙的起源。","pinyin":"Kēxuéjiā yìzhí zài tànsuǒ yǔzhòu de qǐyuán.","vi":"Các nhà khoa học luôn tìm hiểu nguồn gốc của vũ trụ."},{"type":"compound","zh":"虽然人类已经登上月球，但是对宇宙的了解还很少。","pinyin":"Suīrán rénlèi yǐjīng dēngshàng yuèqiú, dànshì duì yǔzhòu de liǎojiě hái hěn shǎo.","vi":"Tuy loài người đã đặt chân lên Mặt Trăng nhưng hiểu biết về vũ trụ vẫn còn rất ít."}],"related":[{"hanzi":"太空","pinyin":"tàikōng","vi":"không gian vũ trụ"},{"hanzi":"星系","pinyin":"xīngxì","vi":"thiên hà"},{"hanzi":"宇航员","pinyin":"yǔhángyuán","vi":"phi hành gia"},{"hanzi":"银河","pinyin":"Yínhé","vi":"Ngân Hà"}]},{"id":"语气","hanzi":"语气","pinyin":"yǔqì","meaning_vi":"giọng điệu, ngữ khí","explanation":"语 (ngữ – lời nói) + 气 (khí – hơi, khí sắc) → cách nói, giọng điệu thể hiện thái độ, tình cảm; trong ngữ pháp là ngữ khí.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🗨️","examples":[{"type":"basic","zh":"他的语气很冷淡。","pinyin":"Tā de yǔqì hěn lěngdàn.","vi":"Giọng điệu của anh ấy rất lạnh nhạt."},{"type":"simple","zh":"妈妈用温柔的语气安慰哭泣的孩子。","pinyin":"Māma yòng wēnróu de yǔqì ānwèi kūqì de háizi.","vi":"Mẹ dùng giọng dịu dàng an ủi đứa trẻ đang khóc."},{"type":"compound","zh":"即使你说得有道理，也要注意自己的语气。","pinyin":"Jíshǐ nǐ shuō de yǒudàolǐ, yě yào zhùyì zìjǐ de yǔqì.","vi":"Dù bạn nói có lý thì cũng phải chú ý giọng điệu của mình."}],"related":[{"hanzi":"口气","pinyin":"kǒuqì","vi":"giọng nói"},{"hanzi":"语调","pinyin":"yǔdiào","vi":"ngữ điệu"},{"hanzi":"语气词","pinyin":"yǔqìcí","vi":"từ ngữ khí"},{"hanzi":"态度","pinyin":"tàidu","vi":"thái độ"}],"traditional":"語氣"},{"id":"浴室","hanzi":"浴室","pinyin":"yùshì","meaning_vi":"phòng tắm","explanation":"浴 (dục – tắm) + 室 (thất – phòng) → căn phòng dùng để tắm.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🛁","examples":[{"type":"basic","zh":"浴室里有人。","pinyin":"Yùshì li yǒurén.","vi":"Trong phòng tắm có người."},{"type":"simple","zh":"这间公寓的浴室装了一个大浴缸。","pinyin":"Zhè jiān gōngyù de yùshì zhuāngle yí ge dà yùgāng.","vi":"Phòng tắm của căn hộ này lắp một bồn tắm lớn."},{"type":"compound","zh":"因为浴室地板很滑，所以老人洗澡时要特别小心。","pinyin":"Yīnwèi yùshì dìbǎn hěn huá, suǒyǐ lǎorén xǐzǎo shí yào tèbié xiǎoxīn.","vi":"Vì sàn phòng tắm rất trơn nên người già tắm phải đặc biệt cẩn thận."}],"related":[{"hanzi":"卫生间","pinyin":"wèishēngjiān","vi":"nhà vệ sinh"},{"hanzi":"浴缸","pinyin":"yùgāng","vi":"bồn tắm"},{"hanzi":"淋浴","pinyin":"línyù","vi":"tắm vòi sen"},{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"tắm"}]},{"id":"预定","hanzi":"预定","pinyin":"yùdìng","meaning_vi":"định trước, dự định, lên lịch trước","explanation":"预 (dự – trước) + 定 (định – quyết định) → định sẵn từ trước về thời gian, kế hoạch.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"🗓️","examples":[{"type":"basic","zh":"飞机按预定时间起飞。","pinyin":"Fēijī àn yùdìng shíjiān qǐfēi.","vi":"Máy bay cất cánh đúng giờ đã định."},{"type":"simple","zh":"会议预定在下周三上午召开。","pinyin":"Huìyì yùdìng zài xià Zhōusān shàngwǔ zhàokāi.","vi":"Cuộc họp được dự định tổ chức vào sáng thứ Tư tuần sau."},{"type":"compound","zh":"虽然遇到了不少困难，但是工程还是按预定计划完成了。","pinyin":"Suīrán yùdàole bùshǎo kùnnan, dànshì gōngchéng háishi àn yùdìng jìhuà wánchéng le.","vi":"Tuy gặp không ít khó khăn nhưng công trình vẫn hoàn thành theo kế hoạch định sẵn."}],"related":[{"hanzi":"预订","pinyin":"yùdìng","vi":"đặt trước"},{"hanzi":"预约","pinyin":"yùyuē","vi":"hẹn trước"},{"hanzi":"计划","pinyin":"jìhuà","vi":"kế hoạch"},{"hanzi":"规定","pinyin":"guīdìng","vi":"quy định"}],"traditional":"預定"},{"id":"预告","hanzi":"预告","pinyin":"yùgào","meaning_vi":"báo trước, thông báo trước, giới thiệu trước (phim)","explanation":"预 (dự – trước) + 告 (cáo – báo) → báo cho biết trước; cũng chỉ bản tin hay đoạn phim giới thiệu trước.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"📢","examples":[{"type":"basic","zh":"新电影的预告出来了。","pinyin":"Xīn diànyǐng de yùgào chūlái le.","vi":"Đoạn giới thiệu phim mới đã ra rồi."},{"type":"simple","zh":"电视台提前预告了明晚的节目内容。","pinyin":"Diànshìtái tíqián yùgàole míngwǎn de jiémù nèiróng.","vi":"Đài truyền hình đã báo trước nội dung chương trình tối mai."},{"type":"compound","zh":"如果停电时间有变化，物业就会提前预告。","pinyin":"Rúguǒ tíngdiàn shíjiān yǒu biànhuà, wùyè jiù huì tíqián yùgào.","vi":"Nếu thời gian cắt điện thay đổi thì ban quản lý sẽ thông báo trước."}],"related":[{"hanzi":"预报","pinyin":"yùbào","vi":"dự báo"},{"hanzi":"通知","pinyin":"tōngzhī","vi":"thông báo"},{"hanzi":"预示","pinyin":"yùshì","vi":"báo hiệu"},{"hanzi":"公告","pinyin":"gōnggào","vi":"thông cáo"}],"traditional":"預告"},{"id":"预见","hanzi":"预见","pinyin":"yùjiàn","meaning_vi":"thấy trước, dự kiến, tiên liệu","explanation":"预 (dự – trước) + 见 (kiến – thấy) → nhìn thấy trước điều sẽ xảy ra.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🔮","examples":[{"type":"basic","zh":"未来很难预见。","pinyin":"Wèilái hěn nán yùjiàn.","vi":"Tương lai rất khó đoán trước."},{"type":"simple","zh":"他早就预见到了这场经济危机。","pinyin":"Tā zǎojiù yùjiàn dàole zhè chǎng jīngjì wēijī.","vi":"Ông ấy đã thấy trước cuộc khủng hoảng kinh tế này từ lâu."},{"type":"compound","zh":"因为没有预见到风险，所以公司损失惨重。","pinyin":"Yīnwèi méiyǒu yùjiàn dào fēngxiǎn, suǒyǐ gōngsī sǔnshī cǎnzhòng.","vi":"Vì không lường trước được rủi ro nên công ty thiệt hại nặng nề."}],"related":[{"hanzi":"预料","pinyin":"yùliào","vi":"dự liệu"},{"hanzi":"预测","pinyin":"yùcè","vi":"dự đoán"},{"hanzi":"远见","pinyin":"yuǎnjiàn","vi":"tầm nhìn xa"},{"hanzi":"预言","pinyin":"yùyán","vi":"tiên đoán"}],"traditional":"預見"},{"id":"预料","hanzi":"预料","pinyin":"yùliào","meaning_vi":"dự liệu, dự đoán, lường trước","explanation":"预 (dự – trước) + 料 (liệu – liệu tính) → tính toán, đoán trước sự việc.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"📊","examples":[{"type":"basic","zh":"结果出乎预料。","pinyin":"Jiéguǒ chūhū yùliào.","vi":"Kết quả nằm ngoài dự đoán."},{"type":"simple","zh":"比赛的结果完全在大家的预料之中。","pinyin":"Bǐsài de jiéguǒ wánquán zài dàjiā de yùliào zhīzhōng.","vi":"Kết quả trận đấu hoàn toàn nằm trong dự đoán của mọi người."},{"type":"compound","zh":"虽然我预料到他会生气，但是没想到他会离开。","pinyin":"Suīrán wǒ yù liàodào tā huì shēngqì, dànshì méi xiǎngdào tā huì líkāi.","vi":"Tuy tôi đã đoán trước anh ấy sẽ giận nhưng không ngờ anh ấy lại bỏ đi."}],"related":[{"hanzi":"预见","pinyin":"yùjiàn","vi":"thấy trước"},{"hanzi":"意料","pinyin":"yìliào","vi":"ngờ tới"},{"hanzi":"预测","pinyin":"yùcè","vi":"dự báo"},{"hanzi":"出乎意料","pinyin":"chūhūyìliào","vi":"ngoài dự kiến"}],"traditional":"預料"},{"id":"预赛","hanzi":"预赛","pinyin":"yùsài","meaning_vi":"vòng loại, vòng sơ loại","explanation":"预 (dự – trước) + 赛 (tái – thi đấu) → cuộc thi đấu sơ bộ để chọn người vào vòng sau.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏃","examples":[{"type":"basic","zh":"他通过了预赛。","pinyin":"Tā tōngguòle yùsài.","vi":"Anh ấy đã vượt qua vòng loại."},{"type":"simple","zh":"中国队在预赛中以小组第一出线。","pinyin":"Zhōngguó duì zài yùsài zhōng yǐ xiǎozǔ dìyī chūxiàn.","vi":"Đội Trung Quốc đi tiếp với vị trí nhất bảng ở vòng loại."},{"type":"compound","zh":"如果在预赛里发挥失常，就进不了决赛。","pinyin":"Rúguǒ zài yùsài li fāhuī shīcháng, jiù jìn buliǎo juésài.","vi":"Nếu thi đấu sa sút ở vòng loại thì sẽ không vào được chung kết."}],"related":[{"hanzi":"决赛","pinyin":"juésài","vi":"chung kết"},{"hanzi":"半决赛","pinyin":"bànjuésài","vi":"bán kết"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"复赛","pinyin":"fùsài","vi":"vòng hai"}],"traditional":"預賽"},{"id":"预示","hanzi":"预示","pinyin":"yùshì","meaning_vi":"báo hiệu, báo trước, dự báo","explanation":"预 (dự – trước) + 示 (thị – cho thấy) → cho thấy trước điều sắp xảy ra, là dấu hiệu của điều gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌅","examples":[{"type":"basic","zh":"乌云预示着暴雨。","pinyin":"Wūyún yùshìzhe bàoyǔ.","vi":"Mây đen báo hiệu mưa bão."},{"type":"simple","zh":"这次合作预示着两国关系进入新阶段。","pinyin":"Zhè cì hézuò yùshìzhe liǎngguó guānxì jìnrù xīnjiēduàn.","vi":"Lần hợp tác này báo hiệu quan hệ hai nước bước vào giai đoạn mới."},{"type":"compound","zh":"虽然冬天还没结束，但是柳树发芽预示着春天快来了。","pinyin":"Suīrán dōngtiān hái méi jiéshù, dànshì liǔshù fāyá yùshìzhe chūntiān kuài lái le.","vi":"Tuy mùa đông chưa kết thúc nhưng cây liễu nảy mầm báo hiệu mùa xuân sắp đến."}],"related":[{"hanzi":"预告","pinyin":"yùgào","vi":"báo trước"},{"hanzi":"预兆","pinyin":"yùzhào","vi":"điềm báo"},{"hanzi":"显示","pinyin":"xiǎnshì","vi":"cho thấy"},{"hanzi":"兆头","pinyin":"zhàotou","vi":"điềm"}],"traditional":"預示"},{"id":"预售","hanzi":"预售","pinyin":"yùshòu","meaning_vi":"bán trước, mở bán trước","explanation":"预 (dự – trước) + 售 (thụ – bán) → bán ra trước khi hàng chính thức có hoặc trước ngày diễn ra.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🎫","examples":[{"type":"basic","zh":"门票已经开始预售。","pinyin":"Ménpiào yǐjīng kāishǐ yùshòu.","vi":"Vé vào cửa đã bắt đầu bán trước."},{"type":"simple","zh":"这款新手机下周一在网上预售。","pinyin":"Zhè kuǎn xīnshǒu jī xiàzhōu yí zài wǎngshang yùshòu.","vi":"Mẫu điện thoại mới này mở bán trước trên mạng vào thứ Hai tuần sau."},{"type":"compound","zh":"因为预售期间有优惠，所以很多人提前下了单。","pinyin":"Yīnwèi yùshòu qījiān yǒu yōuhuì, suǒyǐ hěn duō rén tíqián xiàle dān.","vi":"Vì trong thời gian bán trước có ưu đãi nên nhiều người đã đặt hàng sớm."}],"related":[{"hanzi":"预订","pinyin":"yùdìng","vi":"đặt trước"},{"hanzi":"销售","pinyin":"xiāoshòu","vi":"tiêu thụ, bán hàng"},{"hanzi":"出售","pinyin":"chūshòu","vi":"bán ra"},{"hanzi":"售票","pinyin":"shòupiào","vi":"bán vé"}],"traditional":"預售"},{"id":"欲望","hanzi":"欲望","pinyin":"yùwàng","meaning_vi":"dục vọng, ham muốn, khát vọng","explanation":"欲 (dục – muốn) + 望 (vọng – mong) → lòng ham muốn, mong cầu có được điều gì.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"他的购买欲望很强。","pinyin":"Tā de gòumǎi yùwàng hěn qiáng.","vi":"Anh ấy có ham muốn mua sắm rất mạnh."},{"type":"simple","zh":"好的老师能激发学生的求知欲望。","pinyin":"Hǎo de lǎoshī néng jīfā xuésheng de qiúzhī yùwàng.","vi":"Giáo viên giỏi có thể khơi dậy khát vọng tìm hiểu của học sinh."},{"type":"compound","zh":"如果不能控制自己的欲望，就很容易走上歧路。","pinyin":"Rúguǒ bù néng kòngzhì zìjǐ de yùwàng, jiù hěn róngyì zǒushàng qílù.","vi":"Nếu không kiểm soát được ham muốn của mình thì rất dễ đi vào đường sai trái."}],"related":[{"hanzi":"愿望","pinyin":"yuànwàng","vi":"nguyện vọng"},{"hanzi":"贪欲","pinyin":"tānyù","vi":"lòng tham"},{"hanzi":"食欲","pinyin":"shíyù","vi":"cảm giác thèm ăn"},{"hanzi":"渴望","pinyin":"kěwàng","vi":"khao khát"}],"traditional":"慾望"},{"id":"遇难","hanzi":"遇难","pinyin":"yùnàn","meaning_vi":"gặp nạn, tử nạn, thiệt mạng","explanation":"遇 (ngộ – gặp) + 难 (nạn – tai nạn) → gặp tai nạn, thường chỉ thiệt mạng trong thảm họa.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🕯️","examples":[{"type":"basic","zh":"三名船员遇难。","pinyin":"Sān míng chuányuán yùnàn.","vi":"Ba thuyền viên đã tử nạn."},{"type":"simple","zh":"这次地震中遇难的人数还在增加。","pinyin":"Zhè cì dìzhèn zhōng yùnàn de rénshù hái zài zēngjiā.","vi":"Số người thiệt mạng trong trận động đất này vẫn đang tăng."},{"type":"compound","zh":"虽然救援队全力搜救，但是仍有两名登山者遇难。","pinyin":"Suīrán jiùyuánduì quánlì sōujiù, dànshì réng yǒu liǎng míng dēngshān zhě yùnàn.","vi":"Tuy đội cứu hộ đã dốc sức tìm kiếm nhưng vẫn có hai người leo núi tử nạn."}],"related":[{"hanzi":"遇险","pinyin":"yùxiǎn","vi":"gặp nguy hiểm"},{"hanzi":"死亡","pinyin":"sǐwáng","vi":"tử vong"},{"hanzi":"灾难","pinyin":"zāinàn","vi":"thảm họa"},{"hanzi":"幸存","pinyin":"xìngcún","vi":"sống sót"}],"traditional":"遇難"},{"id":"遇上","hanzi":"遇上","pinyin":"yùshàng","meaning_vi":"gặp phải, gặp được, tình cờ gặp","explanation":"遇 (ngộ – gặp) + 上 (thượng – bổ ngữ kết quả) → gặp phải, đụng phải người hoặc việc gì một cách bất ngờ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌧️","examples":[{"type":"basic","zh":"路上遇上大雨了。","pinyin":"Lùshang yùshàng dàyǔ le.","vi":"Trên đường gặp phải mưa to."},{"type":"simple","zh":"我在超市门口遇上了多年不见的老同学。","pinyin":"Wǒ zài chāoshì ménkǒu yùshàngle duōnián bújiàn de lǎo tóngxué.","vi":"Tôi tình cờ gặp người bạn học cũ nhiều năm không gặp ở cửa siêu thị."},{"type":"compound","zh":"如果路上遇上堵车，我们就改坐地铁去吧。","pinyin":"Rúguǒ lùshang yùshàng dǔchē, wǒmen jiù gǎi zuò dìtiě qù ba.","vi":"Nếu trên đường gặp tắc xe thì chúng ta chuyển sang đi tàu điện ngầm nhé."}],"related":[{"hanzi":"遇到","pinyin":"yùdào","vi":"gặp phải"},{"hanzi":"碰上","pinyin":"pèngshàng","vi":"đụng phải"},{"hanzi":"相遇","pinyin":"xiāngyù","vi":"gặp nhau"},{"hanzi":"遇见","pinyin":"yùjiàn","vi":"gặp"}]},{"id":"遇险","hanzi":"遇险","pinyin":"yùxiǎn","meaning_vi":"gặp nguy hiểm, lâm nguy","explanation":"遇 (ngộ – gặp) + 险 (hiểm – nguy hiểm) → rơi vào tình huống nguy hiểm.","hsk_level":"7-9","tags":["dong-tu"],"image":"🆘","examples":[{"type":"basic","zh":"一艘渔船在海上遇险。","pinyin":"Yì sōu yúchuán zài hǎishang yùxiǎn.","vi":"Một chiếc thuyền đánh cá gặp nạn trên biển."},{"type":"simple","zh":"救援人员连夜赶去营救遇险的游客。","pinyin":"Jiùyuán rényuán liányè gǎn qù yíngjiù yùxiǎn de yóukè.","vi":"Nhân viên cứu hộ suốt đêm tới cứu những du khách gặp nguy hiểm."},{"type":"compound","zh":"一旦在山里遇险，就要马上拨打求救电话。","pinyin":"Yídàn zài shān li yùxiǎn, jiùyào mǎshàng bōdǎ qiújiù diànhuà.","vi":"Một khi gặp nguy hiểm trong núi thì phải gọi ngay số cứu hộ."}],"related":[{"hanzi":"遇难","pinyin":"yùnàn","vi":"gặp nạn"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"脱险","pinyin":"tuōxiǎn","vi":"thoát nạn"},{"hanzi":"冒险","pinyin":"màoxiǎn","vi":"mạo hiểm"}],"traditional":"遇險"},{"id":"愈来愈","hanzi":"愈来愈","pinyin":"yùláiyù","meaning_vi":"càng ngày càng, ngày càng","explanation":"愈 (dũ – càng) + 来 (lai – đến) + 愈 (càng) → càng lúc càng; nghĩa như 越来越 nhưng sắc thái văn viết.","hsk_level":"7-9","tags":["pho-tu"],"image":"📈","examples":[{"type":"basic","zh":"天气愈来愈冷。","pinyin":"Tiānqì yùláiyù lěng.","vi":"Thời tiết càng ngày càng lạnh."},{"type":"simple","zh":"这座城市的交通愈来愈拥挤了。","pinyin":"Zhè zuò chéngshì de jiāotōng yùláiyù yōngjǐ le.","vi":"Giao thông ở thành phố này ngày càng đông đúc."},{"type":"compound","zh":"因为坚持练习，所以他的中文说得愈来愈流利。","pinyin":"Yīnwèi jiānchí liànxí, suǒyǐ tā de Zhōngwén shuō de yùláiyù liúlì.","vi":"Vì kiên trì luyện tập nên anh ấy nói tiếng Trung ngày càng lưu loát."}],"related":[{"hanzi":"越来越","pinyin":"yuèláiyuè","vi":"ngày càng"},{"hanzi":"愈加","pinyin":"yùjiā","vi":"càng thêm"},{"hanzi":"日益","pinyin":"rìyì","vi":"ngày một"},{"hanzi":"愈演愈烈","pinyin":"yùyǎnyùliè","vi":"ngày càng gay gắt"}],"traditional":"愈來愈"},{"id":"愈演愈烈","hanzi":"愈演愈烈","pinyin":"yùyǎn-yùliè","meaning_vi":"ngày càng gay gắt, ngày càng nghiêm trọng","explanation":"愈 (dũ – càng) + 演 (diễn – diễn biến) + 愈 + 烈 (liệt – dữ dội) → sự việc càng diễn biến càng dữ dội, căng thẳng.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🌋","examples":[{"type":"basic","zh":"争吵愈演愈烈。","pinyin":"Zhēngchǎo yùyǎnyùliè.","vi":"Cuộc cãi vã ngày càng gay gắt."},{"type":"simple","zh":"两家公司之间的价格战愈演愈烈。","pinyin":"Liǎng jiā gōngsī zhījiān de jiàgézhàn yùyǎnyùliè.","vi":"Cuộc chiến giá giữa hai công ty ngày càng khốc liệt."},{"type":"compound","zh":"如果不及时处理，这场矛盾就会愈演愈烈。","pinyin":"Rúguǒ bù jíshí chǔlǐ, zhè chǎng máodùn jiù huì yùyǎnyùliè.","vi":"Nếu không xử lý kịp thời thì mâu thuẫn này sẽ ngày càng căng thẳng."}],"related":[{"hanzi":"愈来愈","pinyin":"yùláiyù","vi":"ngày càng"},{"hanzi":"激烈","pinyin":"jīliè","vi":"kịch liệt"},{"hanzi":"加剧","pinyin":"jiājù","vi":"tăng thêm"},{"hanzi":"火上浇油","pinyin":"huǒshàngjiāoyóu","vi":"đổ dầu vào lửa"}]},{"id":"冤","hanzi":"冤","pinyin":"yuān","meaning_vi":"oan, oan uổng, uổng phí, thiệt","explanation":"冤 (oan – oan khuất) → bị đối xử bất công, oan ức; khẩu ngữ còn chỉ bị thiệt, tốn công vô ích.","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"😤","examples":[{"type":"basic","zh":"他死得太冤了。","pinyin":"Tā sǐ de tài yuān le.","vi":"Anh ấy chết thật oan uổng."},{"type":"simple","zh":"多花了一百块钱，我觉得真冤。","pinyin":"Duō huāle yī bǎi kuài qián, wǒ juéde zhēn yuān.","vi":"Tốn thêm một trăm tệ, tôi thấy thật uổng."},{"type":"compound","zh":"因为没看清地图，所以我们白白走了很多冤枉路，真冤。","pinyin":"Yīnwèi méi kànqīng dìtú, suǒyǐ wǒmen báibái zǒule hěn duō yuānwanglù, zhēn yuān.","vi":"Vì không xem kỹ bản đồ nên chúng tôi đi uổng bao nhiêu đường, thật phí công."}],"related":[{"hanzi":"冤枉","pinyin":"yuānwang","vi":"oan uổng"},{"hanzi":"冤案","pinyin":"yuān'àn","vi":"án oan"},{"hanzi":"申冤","pinyin":"shēnyuān","vi":"minh oan"},{"hanzi":"委屈","pinyin":"wěiqu","vi":"ấm ức"}]},{"id":"渊源","hanzi":"渊源","pinyin":"yuānyuán","meaning_vi":"nguồn gốc, cội nguồn, mối quan hệ lâu đời","explanation":"渊 (uyên – vực sâu) + 源 (nguyên – nguồn nước) → nguồn gốc sâu xa của sự vật, hoặc quan hệ có từ lâu.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🌊","examples":[{"type":"basic","zh":"两家有很深的渊源。","pinyin":"Liǎng jiā yǒu hěn shēn de yuānyuán.","vi":"Hai nhà có mối quan hệ sâu xa lâu đời."},{"type":"simple","zh":"中越两国的文化有着悠久的历史渊源。","pinyin":"Zhōng yuè liǎngguó de wénhuà yǒuzhe yōujiǔ de lìshǐ yuānyuán.","vi":"Văn hóa Trung Quốc và Việt Nam có nguồn gốc lịch sử lâu đời."},{"type":"compound","zh":"只有了解这个节日的渊源，才能真正理解它的意义。","pinyin":"Zhǐyǒu liǎojiě zhè ge jiérì de yuānyuán, cáinéng zhēnzhèng lǐjiě tā de yìyì.","vi":"Chỉ khi hiểu nguồn gốc của ngày lễ này mới có thể thật sự hiểu ý nghĩa của nó."}],"related":[{"hanzi":"源头","pinyin":"yuántóu","vi":"đầu nguồn"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"根源","pinyin":"gēnyuán","vi":"căn nguyên"}],"traditional":"淵源"},{"id":"元老","hanzi":"元老","pinyin":"yuánlǎo","meaning_vi":"nguyên lão, bậc lão thành, người kỳ cựu","explanation":"元 (nguyên – đầu tiên) + 老 (lão – già, lâu năm) → người có thâm niên và uy tín lâu năm trong một tổ chức.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"他是公司的元老。","pinyin":"Tā shì gōngsī de yuánlǎo.","vi":"Ông ấy là người kỳ cựu của công ty."},{"type":"simple","zh":"这几位元老见证了球队的整个发展历程。","pinyin":"Zhè jǐ wèi yuánlǎo jiànzhèngle qiúduì de zhěnggè fāzhǎn lìchéng.","vi":"Mấy vị lão thành này đã chứng kiến toàn bộ chặng đường phát triển của đội bóng."},{"type":"compound","zh":"虽然他已经退休，但是作为元老，大家仍然很尊重他。","pinyin":"Suīrán tā yǐjīng tuìxiū, dànshì zuòwéi yuánlǎo, dàjiā réngrán hěn zūnzhòng tā.","vi":"Tuy ông đã nghỉ hưu nhưng là bậc lão thành nên mọi người vẫn rất kính trọng."}],"related":[{"hanzi":"前辈","pinyin":"qiánbèi","vi":"tiền bối"},{"hanzi":"元首","pinyin":"yuánshǒu","vi":"nguyên thủ"},{"hanzi":"老将","pinyin":"lǎojiàng","vi":"lão tướng"},{"hanzi":"资深","pinyin":"zīshēn","vi":"thâm niên"}]},{"id":"元首","hanzi":"元首","pinyin":"yuánshǒu","meaning_vi":"nguyên thủ quốc gia","explanation":"元 (nguyên – đứng đầu) + 首 (thủ – đầu) → người đứng đầu một quốc gia.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"两国元首举行会谈。","pinyin":"Liǎngguó yuánshǒu jǔxíng huìtán.","vi":"Nguyên thủ hai nước tiến hành hội đàm."},{"type":"simple","zh":"多国元首出席了这次国际峰会。","pinyin":"Duōguó yuánshǒu chūxíle zhè cì Guójì fēnghuì.","vi":"Nguyên thủ nhiều nước đã dự hội nghị thượng đỉnh quốc tế lần này."},{"type":"compound","zh":"因为元首要来访问，所以机场附近加强了安保。","pinyin":"Yīnwèi yuánshǒu yào láifǎng wèn, suǒyǐ jīchǎng fùjìn jiāqiángle ānbǎo.","vi":"Vì nguyên thủ sắp đến thăm nên khu vực gần sân bay được tăng cường an ninh."}],"related":[{"hanzi":"总统","pinyin":"zǒngtǒng","vi":"tổng thống"},{"hanzi":"首脑","pinyin":"shǒunǎo","vi":"người đứng đầu"},{"hanzi":"国王","pinyin":"guówáng","vi":"quốc vương"},{"hanzi":"领导人","pinyin":"lǐngdǎorén","vi":"nhà lãnh đạo"}]},{"id":"原本","hanzi":"原本","pinyin":"yuánběn","meaning_vi":"vốn dĩ, ban đầu, nguyên bản","explanation":"原 (nguyên – ban đầu) + 本 (bản – gốc) → vốn là, lúc đầu; làm danh từ chỉ bản gốc.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔙","examples":[{"type":"basic","zh":"我原本想去北京。","pinyin":"Wǒ yuánběn xiǎng qù Běijīng.","vi":"Ban đầu tôi định đi Bắc Kinh."},{"type":"simple","zh":"这片空地原本是一个热闹的菜市场。","pinyin":"Zhè piàn kòngdì yuánběn shì yí ge rènao de càishìchǎng.","vi":"Bãi đất trống này vốn là một chợ rau náo nhiệt."},{"type":"compound","zh":"原本计划周末去爬山，可是因为下雨，所以只好待在家里。","pinyin":"Yuánběn jìhuà zhōumò qù páshān, kěshì yīnwèi xiàyǔ, suǒyǐ zhǐhǎo dāi zài jiāli.","vi":"Vốn định cuối tuần đi leo núi, nhưng vì trời mưa nên đành ở nhà."}],"related":[{"hanzi":"原来","pinyin":"yuánlái","vi":"vốn là"},{"hanzi":"本来","pinyin":"běnlái","vi":"vốn dĩ"},{"hanzi":"原先","pinyin":"yuánxiān","vi":"trước kia"},{"hanzi":"原版","pinyin":"yuánbǎn","vi":"bản gốc"}]},{"id":"原创","hanzi":"原创","pinyin":"yuánchuàng","meaning_vi":"sáng tác gốc, nguyên bản, tính độc đáo","explanation":"原 (nguyên – ban đầu) + 创 (sáng – tạo ra) → tự mình sáng tạo ra lần đầu, không sao chép.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"✍️","examples":[{"type":"basic","zh":"这首歌是原创的。","pinyin":"Zhè shǒu gē shì yuánchuàng de.","vi":"Bài hát này là sáng tác gốc."},{"type":"simple","zh":"这个平台鼓励用户发布原创内容。","pinyin":"Zhè ge píngtái gǔlì yònghù fābù yuánchuàng nèiróng.","vi":"Nền tảng này khuyến khích người dùng đăng nội dung tự sáng tác."},{"type":"compound","zh":"虽然原创很辛苦，但是作品被认可时特别有成就感。","pinyin":"Suīrán yuánchuàng hěn xīnkǔ, dànshì zuòpǐn bèi rènkě shí tè biéyǒu chéngjiùgǎn.","vi":"Tuy sáng tác gốc rất vất vả nhưng khi tác phẩm được công nhận thì cảm thấy rất thành tựu."}],"related":[{"hanzi":"创作","pinyin":"chuàngzuò","vi":"sáng tác"},{"hanzi":"抄袭","pinyin":"chāoxí","vi":"đạo văn"},{"hanzi":"版权","pinyin":"bǎnquán","vi":"bản quyền"},{"hanzi":"原型","pinyin":"yuánxíng","vi":"nguyên mẫu"}],"traditional":"原創"},{"id":"原地","hanzi":"原地","pinyin":"yuándì","meaning_vi":"tại chỗ, chỗ cũ, nơi ban đầu","explanation":"原 (nguyên – vốn có) + 地 (địa – nơi) → chỗ ban đầu, nơi đang đứng.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"请在原地等我。","pinyin":"Qǐng zài yuándì děng wǒ.","vi":"Hãy đứng yên tại chỗ đợi tôi."},{"type":"simple","zh":"体育老师让同学们原地跳五十下。","pinyin":"Tǐyù lǎoshī ràng tóngxuémen yuándì tiào wǔshí xià.","vi":"Thầy thể dục bảo các bạn nhảy tại chỗ năm mươi lần."},{"type":"compound","zh":"如果在商场里走散了，就站在原地别动。","pinyin":"Rúguǒ zài shāngchǎng li zǒusàn le, jiù zhàn zài yuándì bié dòng.","vi":"Nếu bị lạc nhau trong trung tâm thương mại thì đứng yên tại chỗ đừng đi."}],"related":[{"hanzi":"原处","pinyin":"yuánchù","vi":"chỗ cũ"},{"hanzi":"当地","pinyin":"dāngdì","vi":"địa phương"},{"hanzi":"原地踏步","pinyin":"yuándìtàbù","vi":"giậm chân tại chỗ"},{"hanzi":"现场","pinyin":"xiànchǎng","vi":"hiện trường"}]},{"id":"原型","hanzi":"原型","pinyin":"yuánxíng","meaning_vi":"nguyên mẫu, hình mẫu, nguyên hình","explanation":"原 (nguyên – ban đầu) + 型 (hình – khuôn mẫu) → mẫu ban đầu; nhân vật hay vật thật làm cơ sở cho tác phẩm, sản phẩm.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧩","examples":[{"type":"basic","zh":"这是产品的原型。","pinyin":"Zhè shì chǎnpǐn de yuánxíng.","vi":"Đây là nguyên mẫu của sản phẩm."},{"type":"simple","zh":"小说主人公的原型是作者的爷爷。","pinyin":"Xiǎoshuō zhǔréngōng de yuánxíng shì zuòzhě de yéye.","vi":"Nguyên mẫu nhân vật chính trong tiểu thuyết là ông nội tác giả."},{"type":"compound","zh":"虽然原型做得很粗糙，但是基本功能都能实现。","pinyin":"Suīrán yuánxíng zuò de hěn cūcāo, dànshì jīběn gōngnéng dōu néng shíxiàn.","vi":"Tuy nguyên mẫu làm khá thô sơ nhưng các chức năng cơ bản đều thực hiện được."}],"related":[{"hanzi":"模型","pinyin":"móxíng","vi":"mô hình"},{"hanzi":"原创","pinyin":"yuánchuàng","vi":"nguyên bản"},{"hanzi":"样品","pinyin":"yàngpǐn","vi":"hàng mẫu"},{"hanzi":"典型","pinyin":"diǎnxíng","vi":"điển hình"}]},{"id":"原汁原味","hanzi":"原汁原味","pinyin":"yuánzhī-yuánwèi","meaning_vi":"nguyên chất, nguyên vị, đúng chất gốc","explanation":"Nghĩa đen: nước cốt (汁 – trấp) và hương vị (味 – vị) như ban đầu → giữ nguyên hương vị gốc; nghĩa rộng là chân thực, đúng bản sắc nguyên bản.","hsk_level":"7-9","tags":["thanh-ngu","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"这碗汤原汁原味。","pinyin":"Zhè wǎn tāng yuánzhīyuánwèi.","vi":"Bát canh này giữ nguyên hương vị."},{"type":"simple","zh":"这家小店做的是原汁原味的四川菜。","pinyin":"Zhè jiā xiǎodiàn zuò de shì yuánzhīyuánwèi de sìchuāncài.","vi":"Quán nhỏ này nấu món Tứ Xuyên đúng vị gốc."},{"type":"compound","zh":"为了保持原汁原味，导演坚持在当地拍摄，所以电影非常真实。","pinyin":"Wèile bǎochí yuánzhīyuánwèi, dǎoyǎn jiānchí zài dāngdì pāishè, suǒyǐ diànyǐng fēicháng zhēnshí.","vi":"Để giữ được nét nguyên bản, đạo diễn kiên trì quay tại địa phương nên bộ phim rất chân thực."}],"related":[{"hanzi":"地道","pinyin":"dìdao","vi":"chính gốc"},{"hanzi":"正宗","pinyin":"zhèngzōng","vi":"chính tông"},{"hanzi":"原汁","pinyin":"yuánzhī","vi":"nước cốt"},{"hanzi":"原装","pinyin":"yuánzhuāng","vi":"nguyên đai nguyên kiện"}]},{"id":"原装","hanzi":"原装","pinyin":"yuánzhuāng","meaning_vi":"nguyên đai nguyên kiện, hàng chính hãng, nhập nguyên chiếc","explanation":"原 (nguyên – vốn có) + 装 (trang – đóng gói, lắp ráp) → được lắp ráp và đóng gói tại nơi sản xuất gốc, hàng chính hãng.","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"📦","examples":[{"type":"basic","zh":"这是原装电池。","pinyin":"Zhè shì yuánzhuāng diànchí.","vi":"Đây là pin chính hãng."},{"type":"simple","zh":"他花高价买了一台原装进口相机。","pinyin":"Tā huā gāojià mǎile yì tái yuánzhuāng jìnkǒu xiàngjī.","vi":"Anh ấy bỏ giá cao mua một chiếc máy ảnh nhập khẩu nguyên chiếc."},{"type":"compound","zh":"虽然原装配件比较贵，但是质量更有保证。","pinyin":"Suīrán yuánzhuāng pèijiàn bǐjiào guì, dànshì zhìliàng gèng yǒu bǎozhèng.","vi":"Tuy linh kiện chính hãng khá đắt nhưng chất lượng đảm bảo hơn."}],"related":[{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"},{"hanzi":"进口","pinyin":"jìnkǒu","vi":"nhập khẩu"},{"hanzi":"组装","pinyin":"zǔzhuāng","vi":"lắp ráp"},{"hanzi":"包装","pinyin":"bāozhuāng","vi":"bao bì"}],"traditional":"原裝"},{"id":"圆形","hanzi":"圆形","pinyin":"yuánxíng","meaning_vi":"hình tròn","explanation":"圆 (viên – tròn) + 形 (hình – hình dạng) → có hình tròn.","hsk_level":"7-9","tags":["danh-tu"],"image":"⭕","examples":[{"type":"basic","zh":"桌子是圆形的。","pinyin":"Zhuōzi shì yuánxíng de.","vi":"Cái bàn có hình tròn."},{"type":"simple","zh":"广场中间有一个圆形的喷水池。","pinyin":"Guǎngchǎng zhōngjiān yǒu yí ge yuánxíng de pēnshuǐchí.","vi":"Giữa quảng trường có một đài phun nước hình tròn."},{"type":"compound","zh":"因为圆形餐桌没有主次之分，所以很适合家庭聚会。","pinyin":"Yīnwèi yuánxíng cānzhuō méiyǒu zhǔ cìzhī fēn, suǒyǐ hěn shìhé jiātíng jùhuì.","vi":"Vì bàn ăn tròn không phân chỗ trên dưới nên rất hợp cho tụ họp gia đình."}],"related":[{"hanzi":"方形","pinyin":"fāngxíng","vi":"hình vuông"},{"hanzi":"三角形","pinyin":"sānjiǎoxíng","vi":"hình tam giác"},{"hanzi":"椭圆","pinyin":"tuǒyuán","vi":"hình bầu dục"},{"hanzi":"圆圈","pinyin":"yuánquān","vi":"vòng tròn"}],"traditional":"圓形"},{"id":"缘分","hanzi":"缘分","pinyin":"yuánfèn","meaning_vi":"duyên phận, duyên số, cơ duyên","explanation":"缘 (duyên – duyên) + 分 (phận – phần số) → mối duyên định sẵn khiến người ta gặp gỡ, gắn bó với nhau.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💞","examples":[{"type":"basic","zh":"我们真有缘分。","pinyin":"Wǒmen zhēn yǒu yuánfèn.","vi":"Chúng ta thật có duyên."},{"type":"simple","zh":"在国外遇到同乡真是一种缘分。","pinyin":"Zài guówài yùdào tóngxiāng zhēn shì yì zhǒng yuánfèn.","vi":"Gặp được người đồng hương ở nước ngoài quả là một cái duyên."},{"type":"compound","zh":"虽然他们只见过一次面，但是缘分让他们走到了一起。","pinyin":"Suīrán tāmen zhǐjiànguo yí cì miàn, dànshì yuánfèn ràng tāmen zǒu dàole yìqǐ.","vi":"Tuy họ chỉ gặp nhau một lần nhưng duyên phận đã đưa họ đến với nhau."}],"related":[{"hanzi":"有缘","pinyin":"yǒuyuán","vi":"có duyên"},{"hanzi":"命运","pinyin":"mìngyùn","vi":"số phận"},{"hanzi":"机缘","pinyin":"jīyuán","vi":"cơ duyên"},{"hanzi":"无缘","pinyin":"wúyuán","vi":"vô duyên, không có duyên"}],"traditional":"緣分"},{"id":"源头","hanzi":"源头","pinyin":"yuántóu","meaning_vi":"đầu nguồn, cội nguồn, nguồn gốc","explanation":"源 (nguyên – nguồn nước) + 头 (đầu) → nơi bắt nguồn của dòng sông; nghĩa rộng là gốc rễ của sự việc.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"💧","examples":[{"type":"basic","zh":"这里是长江的源头。","pinyin":"Zhèlǐ shì Chángjiāng de yuántóu.","vi":"Đây là đầu nguồn sông Trường Giang."},{"type":"simple","zh":"我们必须从源头上解决污染问题。","pinyin":"Wǒmen bìxū cóng yuántóu shang jiějué wūrǎn wèntí.","vi":"Chúng ta phải giải quyết vấn đề ô nhiễm từ gốc."},{"type":"compound","zh":"如果不找到谣言的源头，它就会继续传播。","pinyin":"Rúguǒ bù zhǎodào yáoyán de yuántóu, tā jiù huì jìxù chuánbō.","vi":"Nếu không tìm ra nguồn gốc tin đồn thì nó sẽ tiếp tục lan truyền."}],"related":[{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"根源","pinyin":"gēnyuán","vi":"căn nguyên"},{"hanzi":"渊源","pinyin":"yuānyuán","vi":"cội nguồn"},{"hanzi":"源于","pinyin":"yuányú","vi":"bắt nguồn từ"}],"traditional":"源頭"},{"id":"源于","hanzi":"源于","pinyin":"yuányú","meaning_vi":"bắt nguồn từ, xuất phát từ","explanation":"源 (nguyên – nguồn) + 于 (vu – từ) → có nguồn gốc từ đâu, xuất phát từ cái gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌱","examples":[{"type":"basic","zh":"灵感源于生活。","pinyin":"Línggǎn yuányú shēnghuó.","vi":"Cảm hứng bắt nguồn từ cuộc sống."},{"type":"simple","zh":"这个节日的习俗源于一个古老的传说。","pinyin":"Zhè ge jiérì de xísú yuányú yí ge gǔlǎo de chuánshuō.","vi":"Phong tục của ngày lễ này bắt nguồn từ một truyền thuyết cổ."},{"type":"compound","zh":"因为他的自信源于充分的准备，所以面试时一点也不紧张。","pinyin":"Yīnwèi tā de zìxìn yuányú chōngfèn de zhǔnbèi, suǒyǐ miànshì shí yìdiǎn yě bù jǐnzhāng.","vi":"Vì sự tự tin của anh ấy xuất phát từ việc chuẩn bị kỹ lưỡng nên khi phỏng vấn chẳng hề căng thẳng."}],"related":[{"hanzi":"来自","pinyin":"láizì","vi":"đến từ"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"源头","pinyin":"yuántóu","vi":"đầu nguồn"},{"hanzi":"出自","pinyin":"chūzì","vi":"xuất phát từ"}],"traditional":"源於"},{"id":"远程","hanzi":"远程","pinyin":"yuǎnchéng","meaning_vi":"từ xa, đường dài, tầm xa","explanation":"远 (viễn – xa) + 程 (trình – quãng đường) → khoảng cách xa; thường dùng như 远程教育, 远程办公 (từ xa).","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"我今天远程办公。","pinyin":"Wǒ jīntiān yuǎnchéngbàngōng.","vi":"Hôm nay tôi làm việc từ xa."},{"type":"simple","zh":"技术人员通过远程控制修好了电脑。","pinyin":"Jìshù rényuán tōngguò yuǎnchéng kòngzhì xiūhǎole diànnǎo.","vi":"Kỹ thuật viên đã sửa xong máy tính bằng điều khiển từ xa."},{"type":"compound","zh":"虽然远程上课很方便，但是学生容易分心。","pinyin":"Suīrán yuǎnchéng shàngkè hěn fāngbiàn, dànshì xuésheng róngyì fēnxīn.","vi":"Tuy học từ xa rất tiện nhưng học sinh dễ bị phân tâm."}],"related":[{"hanzi":"在线","pinyin":"zàixiàn","vi":"trực tuyến"},{"hanzi":"遥控","pinyin":"yáokòng","vi":"điều khiển từ xa"},{"hanzi":"远距离","pinyin":"yuǎnjùlí","vi":"cự ly xa"},{"hanzi":"网课","pinyin":"wǎngkè","vi":"lớp học trực tuyến"}],"traditional":"遠程"},{"id":"远近闻名","hanzi":"远近闻名","pinyin":"yuǎnjìn-wénmíng","meaning_vi":"nổi tiếng khắp nơi, gần xa đều biết","explanation":"远近 (viễn cận – xa gần) + 闻名 (văn danh – nghe danh) → cả nơi xa lẫn nơi gần đều nghe tiếng, rất nổi tiếng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"这家店远近闻名。","pinyin":"Zhè jiā diàn yuǎnjìnwénmíng.","vi":"Quán này nổi tiếng khắp vùng."},{"type":"simple","zh":"这个小镇的米粉在当地远近闻名。","pinyin":"Zhè ge xiǎozhèn de mǐfěn zài dāngdì yuǎnjìnwénmíng.","vi":"Bún gạo của thị trấn nhỏ này nổi tiếng khắp vùng."},{"type":"compound","zh":"因为他医术高明，所以在附近几个村子里远近闻名。","pinyin":"Yīnwèi tā yīshù gāomíng, suǒyǐ zài fùjìn jǐ ge cūnzi li yuǎnjìnwénmíng.","vi":"Vì y thuật cao minh nên ông ấy nổi tiếng khắp mấy làng quanh đó."}],"related":[{"hanzi":"闻名","pinyin":"wénmíng","vi":"nổi danh"},{"hanzi":"举世闻名","pinyin":"jǔshìwénmíng","vi":"nổi tiếng thế giới"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"trứ danh"},{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"}],"traditional":"遠近聞名"},{"id":"怨恨","hanzi":"怨恨","pinyin":"yuànhèn","meaning_vi":"oán hận, căm ghét, thù hằn","explanation":"怨 (oán – oán trách) + 恨 (hận – căm ghét) → bất mãn và căm ghét ai đó trong lòng.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😠","examples":[{"type":"basic","zh":"她心里充满怨恨。","pinyin":"Tā xīnli chōngmǎn yuànhèn.","vi":"Trong lòng cô ấy đầy oán hận."},{"type":"simple","zh":"他从来没有怨恨过离开他的父亲。","pinyin":"Tā cónglái méiyǒu yuànhènguo líkāi tā de fùqīn.","vi":"Anh ấy chưa bao giờ oán hận người cha đã bỏ đi."},{"type":"compound","zh":"即使别人伤害过你，也不要一直怨恨下去。","pinyin":"Jíshǐ biérén shānghàiguo nǐ, yě bú yào yìzhí yuànhèn xiàqù.","vi":"Dù người khác từng làm tổn thương bạn thì cũng đừng mãi oán hận."}],"related":[{"hanzi":"怨气","pinyin":"yuànqì","vi":"oán khí"},{"hanzi":"仇恨","pinyin":"chóuhèn","vi":"thù hận"},{"hanzi":"抱怨","pinyin":"bàoyuàn","vi":"phàn nàn"},{"hanzi":"原谅","pinyin":"yuánliàng","vi":"tha thứ"}]},{"id":"怨气","hanzi":"怨气","pinyin":"yuànqì","meaning_vi":"oán khí, bực tức, bất mãn","explanation":"怨 (oán – oán trách) + 气 (khí – hơi, khí) → nỗi bực bội, bất mãn chất chứa trong lòng.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"😾","examples":[{"type":"basic","zh":"他一肚子怨气。","pinyin":"Tā yídùzi yuànqì.","vi":"Anh ta đầy một bụng bực tức."},{"type":"simple","zh":"员工的怨气主要来自不合理的加班制度。","pinyin":"Yuángōng de yuànqì zhǔyào láizì bù hélǐ de jiābān zhìdù.","vi":"Sự bất mãn của nhân viên chủ yếu đến từ chế độ tăng ca bất hợp lý."},{"type":"compound","zh":"如果有怨气就说出来，不要憋在心里。","pinyin":"Rúguǒ yǒu yuànqì jiù shuō chūlái, bú yào biē zài xīnli.","vi":"Nếu có bực tức thì cứ nói ra, đừng dồn nén trong lòng."}],"related":[{"hanzi":"怨恨","pinyin":"yuànhèn","vi":"oán hận"},{"hanzi":"怒气","pinyin":"nùqì","vi":"cơn giận"},{"hanzi":"不满","pinyin":"bùmǎn","vi":"bất mãn"},{"hanzi":"出气","pinyin":"chūqì","vi":"trút giận"}],"traditional":"怨氣"},{"id":"院士","hanzi":"院士","pinyin":"yuànshì","meaning_vi":"viện sĩ","explanation":"院 (viện – viện nghiên cứu) + 士 (sĩ – người có học) → thành viên chính thức của viện hàn lâm khoa học, danh hiệu học thuật cao nhất.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"🎓","examples":[{"type":"basic","zh":"他当选为院士。","pinyin":"Tā dāngxuǎn wéi yuànshì.","vi":"Ông ấy được bầu làm viện sĩ."},{"type":"simple","zh":"这位院士一生致力于水稻研究。","pinyin":"Zhè wèi yuànshì yìshēng zhìlìyú shuǐdào yánjiū.","vi":"Vị viện sĩ này cả đời dốc sức nghiên cứu lúa nước."},{"type":"compound","zh":"虽然他已经是院士，但是每天仍然坚持去实验室。","pinyin":"Suīrán tā yǐjīng shì yuànshì, dànshì měitiān réngrán jiānchí qù shíyànshì.","vi":"Tuy đã là viện sĩ nhưng ông vẫn ngày ngày đến phòng thí nghiệm."}],"related":[{"hanzi":"科学院","pinyin":"kēxuéyuàn","vi":"viện khoa học"},{"hanzi":"教授","pinyin":"jiàoshòu","vi":"giáo sư"},{"hanzi":"学者","pinyin":"xuézhě","vi":"học giả"},{"hanzi":"博士","pinyin":"bóshì","vi":"tiến sĩ"}]},{"id":"曰","hanzi":"曰","pinyin":"yuē","meaning_vi":"nói, rằng (văn cổ)","explanation":"曰 (viết – nói rằng) → động từ cổ văn nghĩa là \"nói\", thường gặp trong 子曰 (Khổng Tử nói).","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"📜","examples":[{"type":"basic","zh":"子曰：“学而时习之。”","pinyin":"Zǐyuē: \"xué ér shí xí zhī.\"","vi":"Khổng Tử nói: \"Học mà thường ôn tập.\""},{"type":"simple","zh":"古文里常用“曰”来表示“说”的意思。","pinyin":"Gǔwén li chángyòng \"yuē\" lái biǎoshì \"shuō\" de yìsi.","vi":"Trong văn cổ thường dùng chữ này để biểu thị nghĩa \"nói\"."},{"type":"compound","zh":"虽然现代人很少说“曰”，但是读古书时经常能见到。","pinyin":"Suīrán xiàndàirén hěn shǎo shuō \"yuē\", dànshì dú gǔshū shí jīngcháng néng jiàndào.","vi":"Tuy người hiện đại ít khi dùng chữ này nhưng khi đọc sách cổ thì thường gặp."}],"related":[{"hanzi":"说","pinyin":"shuō","vi":"nói"},{"hanzi":"道","pinyin":"dào","vi":"nói"},{"hanzi":"云","pinyin":"yún","vi":"rằng (văn cổ)"},{"hanzi":"谓","pinyin":"wèi","vi":"gọi là, nói"}]},{"id":"月初","hanzi":"月初","pinyin":"yuèchū","meaning_vi":"đầu tháng","explanation":"月 (nguyệt – tháng) + 初 (sơ – lúc đầu) → những ngày đầu của tháng.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📆","examples":[{"type":"basic","zh":"工资月初发。","pinyin":"Gōngzī yuèchū fā.","vi":"Lương được phát vào đầu tháng."},{"type":"simple","zh":"我们打算下个月初去云南旅游。","pinyin":"Wǒmen dǎsuàn xiàge yuèchū qù Yúnnán lǚyóu.","vi":"Chúng tôi định đầu tháng sau đi du lịch Vân Nam."},{"type":"compound","zh":"如果月初不交房租，就要多付滞纳金。","pinyin":"Rúguǒ yuèchū bù jiāo fángzū, jiùyào duō fù zhìnàjīn.","vi":"Nếu đầu tháng không nộp tiền thuê nhà thì phải trả thêm tiền phạt chậm nộp."}],"related":[{"hanzi":"月底","pinyin":"yuèdǐ","vi":"cuối tháng"},{"hanzi":"月中","pinyin":"yuèzhōng","vi":"giữa tháng"},{"hanzi":"年初","pinyin":"niánchū","vi":"đầu năm"},{"hanzi":"初旬","pinyin":"chūxún","vi":"thượng tuần"}]},{"id":"月票","hanzi":"月票","pinyin":"yuèpiào","meaning_vi":"vé tháng","explanation":"月 (nguyệt – tháng) + 票 (phiếu – vé) → vé dùng được trong một tháng, thường cho xe buýt, tàu điện.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🎟️","examples":[{"type":"basic","zh":"我买了一张月票。","pinyin":"Wǒ mǎile yì zhāng yuèpiào.","vi":"Tôi đã mua một tấm vé tháng."},{"type":"simple","zh":"学生凭学生证可以办优惠的公交月票。","pinyin":"Xuésheng píng xuéshengzhèng kěyǐ bàn yōuhuì de gōngjiāo yuèpiào.","vi":"Học sinh dùng thẻ học sinh có thể làm vé tháng xe buýt ưu đãi."},{"type":"compound","zh":"因为每天都要坐地铁上班，所以办月票更划算。","pinyin":"Yīnwèi měitiān dōu yào zuò dìtiě shàngbān, suǒyǐ bàn yuèpiào gèng huásuàn.","vi":"Vì ngày nào cũng đi tàu điện ngầm đi làm nên làm vé tháng lợi hơn."}],"related":[{"hanzi":"车票","pinyin":"chēpiào","vi":"vé xe"},{"hanzi":"年票","pinyin":"niánpiào","vi":"vé năm"},{"hanzi":"公交卡","pinyin":"gōngjiāokǎ","vi":"thẻ xe buýt"},{"hanzi":"门票","pinyin":"ménpiào","vi":"vé vào cửa"}]},{"id":"岳父","hanzi":"岳父","pinyin":"yuèfù","meaning_vi":"bố vợ, nhạc phụ","explanation":"岳 (nhạc – núi lớn, chỉ bên nhà vợ) + 父 (phụ – cha) → cha của vợ, nhạc phụ.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👨‍🦳","examples":[{"type":"basic","zh":"他岳父是医生。","pinyin":"Tā yuèfù shì yīshēng.","vi":"Bố vợ anh ấy là bác sĩ."},{"type":"simple","zh":"春节时他带着妻子去看望岳父岳母。","pinyin":"Chūnjié shí tā dàizhe qīzi qù kànwàng yuèfù yuèmǔ.","vi":"Dịp Tết anh ấy đưa vợ đi thăm bố mẹ vợ."},{"type":"compound","zh":"虽然岳父平时话不多，但是对女婿非常关心。","pinyin":"Suīrán yuèfù píngshí huà bù duō, dànshì duì nǚxu fēicháng guānxīn.","vi":"Tuy bố vợ bình thường ít nói nhưng rất quan tâm con rể."}],"related":[{"hanzi":"岳母","pinyin":"yuèmǔ","vi":"mẹ vợ"},{"hanzi":"女婿","pinyin":"nǚxu","vi":"con rể"},{"hanzi":"公公","pinyin":"gōnggong","vi":"bố chồng"},{"hanzi":"丈人","pinyin":"zhàngren","vi":"bố vợ (khẩu ngữ)"}]},{"id":"岳母","hanzi":"岳母","pinyin":"yuèmǔ","meaning_vi":"mẹ vợ, nhạc mẫu","explanation":"岳 (nhạc – chỉ bên nhà vợ) + 母 (mẫu – mẹ) → mẹ của vợ, nhạc mẫu.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👵","examples":[{"type":"basic","zh":"岳母做饭很好吃。","pinyin":"Yuèmǔ zuòfàn hěn hǎochī.","vi":"Mẹ vợ nấu ăn rất ngon."},{"type":"simple","zh":"岳母每个周末都来帮我们带孩子。","pinyin":"Yuèmǔ měi ge zhōumò dōu lái bāng wǒmen dàiháizi.","vi":"Cuối tuần nào mẹ vợ cũng đến giúp chúng tôi trông con."},{"type":"compound","zh":"因为岳母身体不好，所以他们决定把她接来一起住。","pinyin":"Yīnwèi yuèmǔ shēntǐ bù hǎo, suǒyǐ tāmen juédìng bǎ tā jiē lái yìqǐ zhù.","vi":"Vì mẹ vợ sức khỏe yếu nên họ quyết định đón bà về ở cùng."}],"related":[{"hanzi":"岳父","pinyin":"yuèfù","vi":"bố vợ"},{"hanzi":"婆婆","pinyin":"pópo","vi":"mẹ chồng"},{"hanzi":"丈母娘","pinyin":"zhàngmuniáng","vi":"mẹ vợ (khẩu ngữ)"},{"hanzi":"女婿","pinyin":"nǚxu","vi":"con rể"}]},{"id":"悦耳","hanzi":"悦耳","pinyin":"yuè'ěr","meaning_vi":"êm tai, du dương, dễ nghe","explanation":"悦 (duyệt – vui thích) + 耳 (nhĩ – tai) → làm cho tai thích thú, âm thanh êm ái dễ nghe.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🎶","examples":[{"type":"basic","zh":"鸟叫声很悦耳。","pinyin":"Niǎo jiàoshēng hěn yuè'ěr.","vi":"Tiếng chim hót rất êm tai."},{"type":"simple","zh":"她用悦耳的声音给孩子们讲故事。","pinyin":"Tā yòng yuè'ěr de shēngyīn gěi háizimen jiǎng gùshi.","vi":"Cô ấy kể chuyện cho bọn trẻ bằng giọng êm ái."},{"type":"compound","zh":"虽然这首曲子很简单，但是旋律非常悦耳。","pinyin":"Suīrán zhè shǒu qǔzi hěn jiǎndān, dànshì xuánlǜ fēicháng yuè'ěr.","vi":"Tuy bản nhạc này rất đơn giản nhưng giai điệu vô cùng êm tai."}],"related":[{"hanzi":"动听","pinyin":"dòngtīng","vi":"du dương"},{"hanzi":"好听","pinyin":"hǎotīng","vi":"hay, dễ nghe"},{"hanzi":"刺耳","pinyin":"cì'ěr","vi":"chói tai"},{"hanzi":"悦目","pinyin":"yuèmù","vi":"đẹp mắt"}],"traditional":"悅耳"},{"id":"越过","hanzi":"越过","pinyin":"yuèguò","meaning_vi":"vượt qua, băng qua","explanation":"越 (việt – vượt) + 过 (quá – qua) → đi vượt qua một ranh giới, chướng ngại hay khoảng cách.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧗","examples":[{"type":"basic","zh":"马越过了栏杆。","pinyin":"Mǎ yuèguòle lángān.","vi":"Con ngựa đã nhảy qua lan can."},{"type":"simple","zh":"探险队用了三天时间越过这片沙漠。","pinyin":"Tànxiǎn duì yòngle sān tiān shíjiān yuèguò zhè piàn shāmò.","vi":"Đoàn thám hiểm mất ba ngày để vượt qua sa mạc này."},{"type":"compound","zh":"只要越过前面那座山，就能看到村庄了。","pinyin":"Zhǐyào yuèguò qiánmiàn nà zuò shān, jiù néng kàndào cūnzhuāng le.","vi":"Chỉ cần vượt qua ngọn núi phía trước là có thể nhìn thấy làng."}],"related":[{"hanzi":"穿过","pinyin":"chuānguò","vi":"xuyên qua"},{"hanzi":"超过","pinyin":"chāoguò","vi":"vượt quá"},{"hanzi":"跨越","pinyin":"kuàyuè","vi":"vượt qua"},{"hanzi":"翻越","pinyin":"fānyuè","vi":"trèo qua"}],"traditional":"越過"},{"id":"晕倒","hanzi":"晕倒","pinyin":"yūndǎo","meaning_vi":"ngất xỉu, choáng ngã","explanation":"晕 (vựng – choáng váng) + 倒 (đảo – ngã) → choáng váng mất ý thức và ngã xuống.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😵","examples":[{"type":"basic","zh":"他突然晕倒了。","pinyin":"Tā tūrán yūndǎo le.","vi":"Anh ấy đột nhiên ngất xỉu."},{"type":"simple","zh":"一位老人在烈日下排队时晕倒了。","pinyin":"Yí wèi lǎorén zài lièrì xià páiduì shí yūndǎo le.","vi":"Một cụ già ngất xỉu khi xếp hàng dưới nắng gắt."},{"type":"compound","zh":"因为她没吃早饭就去跑步，所以在半路上晕倒了。","pinyin":"Yīnwèi tā méi chī zǎofàn jiù qù pǎobù, suǒyǐ zài bànlù shang yūndǎo le.","vi":"Vì không ăn sáng đã đi chạy bộ nên cô ấy ngất xỉu giữa đường."}],"related":[{"hanzi":"昏倒","pinyin":"hūndǎo","vi":"ngất đi"},{"hanzi":"晕","pinyin":"yūn","vi":"choáng"},{"hanzi":"昏迷","pinyin":"hūnmí","vi":"hôn mê"},{"hanzi":"头晕","pinyin":"tóuyūn","vi":"chóng mặt"}],"traditional":"暈倒"},{"id":"孕妇","hanzi":"孕妇","pinyin":"yùnfù","meaning_vi":"phụ nữ mang thai, bà bầu, thai phụ","explanation":"孕 (dựng – mang thai) + 妇 (phụ – người phụ nữ) → người phụ nữ đang mang thai.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🤰","examples":[{"type":"basic","zh":"请给孕妇让座。","pinyin":"Qǐng gěi yùnfù ràngzuò.","vi":"Hãy nhường chỗ cho bà bầu."},{"type":"simple","zh":"医生建议孕妇每天适当散散步。","pinyin":"Yīshēng jiànyì yùnfù měitiān shìdàng sàn sanbù.","vi":"Bác sĩ khuyên bà bầu mỗi ngày nên đi dạo vừa phải."},{"type":"compound","zh":"因为有些药物对胎儿有害，所以孕妇用药要特别谨慎。","pinyin":"Yīnwèi yǒuxiē yàowù duì tāi'ér yǒuhài, suǒyǐ yùnfù yòng yào yào tèbié jǐnshèn.","vi":"Vì một số thuốc có hại cho thai nhi nên phụ nữ mang thai dùng thuốc phải đặc biệt thận trọng."}],"related":[{"hanzi":"怀孕","pinyin":"huáiyùn","vi":"mang thai"},{"hanzi":"胎儿","pinyin":"tāi'ér","vi":"thai nhi"},{"hanzi":"产妇","pinyin":"chǎnfù","vi":"sản phụ"},{"hanzi":"孕期","pinyin":"yùnqī","vi":"thai kỳ"}],"traditional":"孕婦"},{"id":"运河","hanzi":"运河","pinyin":"yùnhé","meaning_vi":"kênh đào","explanation":"运 (vận – vận chuyển) + 河 (hà – sông) → con sông do người đào để vận chuyển, tưới tiêu.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🛶","examples":[{"type":"basic","zh":"运河上有很多船。","pinyin":"Yùnhé shang yǒu hěn duō chuán.","vi":"Trên kênh đào có rất nhiều thuyền."},{"type":"simple","zh":"京杭大运河是世界上最长的运河。","pinyin":"Jīnghángdàyùnhé shì shìjiè shang zuì cháng de yùnhé.","vi":"Kênh đào lớn Kinh Hàng là kênh đào dài nhất thế giới."},{"type":"compound","zh":"因为有了这条运河，所以南北之间的货物运输方便多了。","pinyin":"Yīnwèi yǒule zhè tiáo yùnhé, suǒyǐ nánběi zhījiān de huòwù yùnshū fāngbiàn duō le.","vi":"Nhờ có con kênh đào này nên việc vận chuyển hàng hóa giữa Nam và Bắc thuận tiện hơn nhiều."}],"related":[{"hanzi":"河流","pinyin":"héliú","vi":"sông ngòi"},{"hanzi":"运输","pinyin":"yùnshū","vi":"vận tải"},{"hanzi":"水道","pinyin":"shuǐdào","vi":"đường thủy"},{"hanzi":"船闸","pinyin":"chuánzhá","vi":"âu thuyền"}],"traditional":"運河"},{"id":"运送","hanzi":"运送","pinyin":"yùnsòng","meaning_vi":"vận chuyển, chuyên chở","explanation":"运 (vận – chuyên chở) + 送 (tống – đưa đi) → chở người hoặc hàng hóa đến nơi khác.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚚","examples":[{"type":"basic","zh":"卡车运送货物。","pinyin":"Kǎchē yùnsòng huòwù.","vi":"Xe tải vận chuyển hàng hóa."},{"type":"simple","zh":"救护车把伤员迅速运送到了医院。","pinyin":"Jiùhù chēbǎ shāngyuán xùnsù yùnsòng dàole yīyuàn.","vi":"Xe cứu thương nhanh chóng chở người bị thương đến bệnh viện."},{"type":"compound","zh":"因为山路被大雪封住了，所以物资只能用直升机运送。","pinyin":"Yīnwèi shānlù bèi Dàxuě fēng zhù le, suǒyǐ wùzī zhǐnéng yòng zhíshēngjī yùnsòng.","vi":"Vì đường núi bị tuyết lớn chặn nên vật tư chỉ có thể vận chuyển bằng trực thăng."}],"related":[{"hanzi":"运输","pinyin":"yùnshū","vi":"vận tải"},{"hanzi":"输送","pinyin":"shūsòng","vi":"chuyển tải"},{"hanzi":"搬运","pinyin":"bānyùn","vi":"bốc vác"},{"hanzi":"快递","pinyin":"kuàidì","vi":"chuyển phát nhanh"}],"traditional":"運送"},{"id":"运转","hanzi":"运转","pinyin":"yùnzhuǎn","meaning_vi":"vận hành, hoạt động, quay vòng","explanation":"运 (vận – chuyển động) + 转 (chuyển – xoay) → chuyển động quay tròn; nghĩa rộng là máy móc, tổ chức hoạt động.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"⚙️","examples":[{"type":"basic","zh":"机器正常运转。","pinyin":"Jīqì zhèngcháng yùnzhuǎn.","vi":"Máy móc vận hành bình thường."},{"type":"simple","zh":"新系统上线后，医院的运转效率提高了。","pinyin":"Xīn xìtǒng shàngxiàn hòu, yīyuàn de yùnzhuǎn xiàolǜ tígāo le.","vi":"Sau khi hệ thống mới đi vào hoạt động, hiệu suất vận hành của bệnh viện đã tăng."},{"type":"compound","zh":"如果资金跟不上，公司就很难维持运转。","pinyin":"Rúguǒ zījīn gēnbushàng, gōngsī jiù hěn nán wéichí yùnzhuǎn.","vi":"Nếu vốn không theo kịp thì công ty rất khó duy trì hoạt động."}],"related":[{"hanzi":"运行","pinyin":"yùnxíng","vi":"vận hành"},{"hanzi":"转动","pinyin":"zhuàndòng","vi":"xoay chuyển"},{"hanzi":"运作","pinyin":"yùnzuò","vi":"vận hành"},{"hanzi":"停转","pinyin":"tíngzhuàn","vi":"ngừng quay"}],"traditional":"運轉"},{"id":"蕴涵","hanzi":"蕴涵","pinyin":"yùnhán","meaning_vi":"hàm chứa, ẩn chứa, bao hàm","explanation":"蕴 (uẩn – chứa đựng) + 涵 (hàm – bao hàm) → chứa đựng bên trong, ẩn chứa ý nghĩa hoặc năng lượng.","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"💎","examples":[{"type":"basic","zh":"这句话蕴涵深意。","pinyin":"Zhè jù huà yùnhán shēn yì.","vi":"Câu nói này hàm chứa ý nghĩa sâu xa."},{"type":"simple","zh":"这幅画里蕴涵着画家对故乡的思念。","pinyin":"Zhè fú huà li yùnhánzhe huàjiā duì gùxiāng de sīniàn.","vi":"Bức tranh này ẩn chứa nỗi nhớ quê hương của họa sĩ."},{"type":"compound","zh":"虽然这些民间故事很简单，但是蕴涵着丰富的智慧。","pinyin":"Suīrán zhèxiē mínjiān gùshi hěn jiǎndān, dànshì yùnhánzhe fēngfù de zhìhuì.","vi":"Tuy những truyện dân gian này rất đơn giản nhưng hàm chứa trí tuệ phong phú."}],"related":[{"hanzi":"蕴含","pinyin":"yùnhán","vi":"hàm chứa"},{"hanzi":"包含","pinyin":"bāohán","vi":"bao gồm"},{"hanzi":"内涵","pinyin":"nèihán","vi":"nội hàm"},{"hanzi":"蕴藏","pinyin":"yùncáng","vi":"tiềm ẩn"}],"traditional":"蘊涵"},{"id":"杂乱无章","hanzi":"杂乱无章","pinyin":"záluàn-wúzhāng","meaning_vi":"lộn xộn, bừa bãi, không có trật tự","explanation":"杂乱 (tạp loạn – lộn xộn) + 无章 (vô chương – không có trật tự, thể thức) → hỗn độn, không hề có hệ thống.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌀","examples":[{"type":"basic","zh":"房间里杂乱无章。","pinyin":"Fángjiān li záluànwúzhāng.","vi":"Trong phòng bừa bộn lộn xộn."},{"type":"simple","zh":"他的文章写得杂乱无章，让人看不懂。","pinyin":"Tā de wénzhāng xiě de záluànwúzhāng, ràng rén kànbudǒng.","vi":"Bài văn của anh ấy viết lộn xộn, khiến người ta đọc không hiểu."},{"type":"compound","zh":"如果资料杂乱无章，找起来就会特别费时间。","pinyin":"Rúguǒ zīliào záluànwúzhāng, zhǎo qǐlái jiù huì tèbié fèi shíjiān.","vi":"Nếu tài liệu lộn xộn thì tìm kiếm sẽ rất tốn thời gian."}],"related":[{"hanzi":"乱七八糟","pinyin":"luànqībāzāo","vi":"lung tung"},{"hanzi":"井井有条","pinyin":"jǐngjǐngyǒutiáo","vi":"ngăn nắp"},{"hanzi":"杂乱","pinyin":"záluàn","vi":"lộn xộn"},{"hanzi":"有条不紊","pinyin":"yǒutiáobùwěn","vi":"đâu ra đấy"}],"traditional":"雜亂無章"},{"id":"栽","hanzi":"栽","pinyin":"zāi","meaning_vi":"trồng, cắm; ngã nhào, vấp ngã","explanation":"栽 (tài – trồng cây) → trồng cây, cắm xuống đất; khẩu ngữ còn chỉ ngã nhào, thất bại.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"院子里栽了几棵树。","pinyin":"Yuànzi li zāile jǐ kē shù.","vi":"Trong sân đã trồng mấy cái cây."},{"type":"simple","zh":"他一不小心栽进了路边的水沟里。","pinyin":"Tā yíbùxiǎoxīn zāi jìnle lùbiān de shuǐgōu li.","vi":"Anh ấy sơ ý ngã nhào xuống rãnh nước ven đường."},{"type":"compound","zh":"因为春天适合栽树，所以学校组织学生去植树。","pinyin":"Yīnwèi chūntiān shìhé zāi shù, suǒyǐ xuéxiào zǔzhī xuésheng qù zhíshù.","vi":"Vì mùa xuân thích hợp trồng cây nên nhà trường tổ chức cho học sinh đi trồng cây."}],"related":[{"hanzi":"种","pinyin":"zhòng","vi":"trồng"},{"hanzi":"栽培","pinyin":"zāipéi","vi":"vun trồng"},{"hanzi":"盆栽","pinyin":"pénzāi","vi":"cây cảnh chậu"},{"hanzi":"栽跟头","pinyin":"zāigēntou","vi":"vấp ngã, thất bại"}]},{"id":"再度","hanzi":"再度","pinyin":"zàidù","meaning_vi":"lại một lần nữa, lần nữa","explanation":"再 (tái – lại) + 度 (độ – lần) → thêm một lần nữa; sắc thái văn viết.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"他再度夺冠。","pinyin":"Tā zàidù duóguàn.","vi":"Anh ấy lại giành chức vô địch."},{"type":"simple","zh":"时隔十年，这位歌手再度登上了舞台。","pinyin":"Shígé shí nián, zhè wèi gēshǒu zàidù dēngshàngle wǔtái.","vi":"Sau mười năm, ca sĩ này lại một lần nữa bước lên sân khấu."},{"type":"compound","zh":"虽然去年失败了，但是他今年再度报名参加比赛。","pinyin":"Suīrán qùnián shībài le, dànshì tā jīnnián zàidù bàomíng cānjiā bǐsài.","vi":"Tuy năm ngoái thất bại nhưng năm nay anh ấy lại đăng ký dự thi."}],"related":[{"hanzi":"再次","pinyin":"zàicì","vi":"lần nữa"},{"hanzi":"重新","pinyin":"chóngxīn","vi":"làm lại"},{"hanzi":"又","pinyin":"yòu","vi":"lại"},{"hanzi":"一度","pinyin":"yídù","vi":"từng có lúc"}]},{"id":"再现","hanzi":"再现","pinyin":"zàixiàn","meaning_vi":"tái hiện, tái xuất hiện","explanation":"再 (tái – lại) + 现 (hiện – xuất hiện) → làm cho cảnh vật, sự việc trong quá khứ hiện ra lần nữa.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🎞️","examples":[{"type":"basic","zh":"电影再现了历史。","pinyin":"Diànyǐng zàixiànle lìshǐ.","vi":"Bộ phim đã tái hiện lịch sử."},{"type":"simple","zh":"这部纪录片真实地再现了当年的战争场面。","pinyin":"Zhè bù jìlùpiàn zhēn shíde zàixiànle dāngnián de zhànzhēng chǎngmiàn.","vi":"Bộ phim tài liệu này tái hiện chân thực cảnh chiến tranh năm xưa."},{"type":"compound","zh":"虽然古城已经被毁，但是专家用技术让它再现在人们眼前。","pinyin":"Suīrán gǔchéng yǐjīng bèi huǐ, dànshì zhuān jiāyòng jìshù ràng tā zài xiànzài rénmen yǎnqián.","vi":"Tuy thành cổ đã bị phá hủy nhưng các chuyên gia dùng công nghệ để nó tái hiện trước mắt mọi người."}],"related":[{"hanzi":"重现","pinyin":"chóngxiàn","vi":"tái hiện"},{"hanzi":"还原","pinyin":"huányuán","vi":"phục dựng"},{"hanzi":"出现","pinyin":"chūxiàn","vi":"xuất hiện"},{"hanzi":"再度","pinyin":"zàidù","vi":"lần nữa"}],"traditional":"再現"},{"id":"在线","hanzi":"在线","pinyin":"zàixiàn","meaning_vi":"trực tuyến, online","explanation":"在 (tại – ở) + 线 (tuyến – đường dây, mạng) → đang ở trên mạng, trực tuyến.","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🌐","examples":[{"type":"basic","zh":"他现在不在线。","pinyin":"Tā xiànzài bu zàixiàn.","vi":"Bây giờ anh ấy không online."},{"type":"simple","zh":"很多年轻人喜欢在线购买生活用品。","pinyin":"Hěn duō niánqīngrén xǐhuan zàixiàn gòumǎi shēnghuó yòngpǐn.","vi":"Nhiều người trẻ thích mua đồ dùng sinh hoạt trực tuyến."},{"type":"compound","zh":"因为可以在线学习，所以她下班后也能上课。","pinyin":"Yīnwèi kěyǐ zàixiàn xuéxí, suǒyǐ tā xiàbān hòu yě néng shàngkè.","vi":"Vì có thể học trực tuyến nên sau giờ làm cô ấy vẫn đi học được."}],"related":[{"hanzi":"离线","pinyin":"líxiàn","vi":"ngoại tuyến"},{"hanzi":"网上","pinyin":"wǎngshang","vi":"trên mạng"},{"hanzi":"远程","pinyin":"yuǎnchéng","vi":"từ xa"},{"hanzi":"上网","pinyin":"shàngwǎng","vi":"lên mạng"}],"traditional":"在線"},{"id":"在职","hanzi":"在职","pinyin":"zàizhí","meaning_vi":"đang tại chức, đang làm việc, vừa làm vừa học","explanation":"在 (tại – đang ở) + 职 (chức – chức vụ, công việc) → đang giữ chức vụ, đang đi làm.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他是在职研究生。","pinyin":"Tā shì zàizhí yánjiūshēng.","vi":"Anh ấy là nghiên cứu sinh vừa làm vừa học."},{"type":"simple","zh":"公司为在职员工提供免费培训。","pinyin":"Gōngsī wèi zàizhí yuángōng tígōng miǎnfèi péixùn.","vi":"Công ty cung cấp đào tạo miễn phí cho nhân viên đang làm việc."},{"type":"compound","zh":"虽然在职读书很辛苦，但是她还是拿到了硕士学位。","pinyin":"Suīrán zàizhí dúshū hěn xīnkǔ, dànshì tā háishi nádàole shuòshì xuéwèi.","vi":"Tuy vừa làm vừa học rất vất vả nhưng cô ấy vẫn lấy được bằng thạc sĩ."}],"related":[{"hanzi":"离职","pinyin":"lízhí","vi":"nghỉ việc"},{"hanzi":"退休","pinyin":"tuìxiū","vi":"nghỉ hưu"},{"hanzi":"任职","pinyin":"rènzhí","vi":"nhậm chức"},{"hanzi":"兼职","pinyin":"jiānzhí","vi":"làm thêm"}],"traditional":"在職"},{"id":"暂","hanzi":"暂","pinyin":"zàn","meaning_vi":"tạm, tạm thời","explanation":"暂 (tạm – trong thời gian ngắn) → tạm thời, nhất thời; hay đứng trước động từ như 暂停, 暂不.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏸️","examples":[{"type":"basic","zh":"此事暂不公开。","pinyin":"Cǐshì zàn bù gōngkāi.","vi":"Việc này tạm thời chưa công bố."},{"type":"simple","zh":"这家餐厅暂不接受网上预订。","pinyin":"Zhè jiā cāntīng zàn bù jiēshòu wǎngshang yùdìng.","vi":"Nhà hàng này tạm thời không nhận đặt chỗ trực tuyến."},{"type":"compound","zh":"如果没有更好的办法，就暂按原计划执行。","pinyin":"Rúguǒ méiyǒu gèng hǎo de bànfǎ, jiù zàn àn yuán jìhuà zhíxíng.","vi":"Nếu không có cách nào tốt hơn thì tạm thời làm theo kế hoạch cũ."}],"related":[{"hanzi":"暂时","pinyin":"zànshí","vi":"tạm thời"},{"hanzi":"暂停","pinyin":"zàntíng","vi":"tạm dừng"},{"hanzi":"短暂","pinyin":"duǎnzàn","vi":"ngắn ngủi"},{"hanzi":"永久","pinyin":"yǒngjiǔ","vi":"vĩnh viễn"}],"traditional":"暫"},{"id":"赞美","hanzi":"赞美","pinyin":"zànměi","meaning_vi":"ca ngợi, khen ngợi, tán dương","explanation":"赞 (tán – khen) + 美 (mỹ – đẹp, tốt) → khen ngợi cái đẹp, cái tốt.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"大家都赞美她。","pinyin":"Dàjiā dōu zànměi tā.","vi":"Mọi người đều khen ngợi cô ấy."},{"type":"simple","zh":"诗人在诗中赞美了家乡的山山水水。","pinyin":"Shīrén zài shī zhōng zànměile jiāxiāng de shān shānshuǐ shuǐ.","vi":"Nhà thơ ca ngợi núi sông quê hương trong bài thơ."},{"type":"compound","zh":"虽然别人的赞美让人开心，但是也不能因此骄傲。","pinyin":"Suīrán biérén de zànměi ràng rén kāixīn, dànshì yě bù néng yīncǐ jiāo'ào.","vi":"Tuy lời khen của người khác khiến ta vui nhưng cũng không được vì thế mà kiêu ngạo."}],"related":[{"hanzi":"赞扬","pinyin":"zànyáng","vi":"tán dương"},{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"赞许","pinyin":"zànxǔ","vi":"khen ngợi"},{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"}],"traditional":"讚美"},{"id":"赞叹不已","hanzi":"赞叹不已","pinyin":"zàntàn-bùyǐ","meaning_vi":"khen ngợi không ngớt, trầm trồ mãi","explanation":"赞叹 (tán thán – trầm trồ khen) + 不已 (bất dĩ – không dứt) → trầm trồ thán phục mãi không thôi.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🤩","examples":[{"type":"basic","zh":"游客们赞叹不已。","pinyin":"Yóukèmen zàntànbùyǐ.","vi":"Du khách trầm trồ khen ngợi không ngớt."},{"type":"simple","zh":"他精彩的表演让观众赞叹不已。","pinyin":"Tā jīngcǎi de biǎoyǎn ràng guānzhòng zàntànbùyǐ.","vi":"Màn biểu diễn tuyệt vời của anh ấy khiến khán giả khen ngợi không ngớt."},{"type":"compound","zh":"虽然只是一幅小小的剪纸，但是精致的做工让人赞叹不已。","pinyin":"Suīrán zhǐshì yì fú xiǎoxiǎo de jiǎnzhǐ, dànshì jīngzhì de zuògōng ràng rén zàntànbùyǐ.","vi":"Tuy chỉ là một bức tranh cắt giấy nhỏ nhưng tay nghề tinh xảo khiến người ta trầm trồ mãi."}],"related":[{"hanzi":"赞叹","pinyin":"zàntàn","vi":"trầm trồ"},{"hanzi":"叹为观止","pinyin":"tànwéiguānzhǐ","vi":"tuyệt vời hết mức"},{"hanzi":"赞不绝口","pinyin":"zànbùjuékǒu","vi":"khen không ngớt lời"},{"hanzi":"惊叹","pinyin":"jīngtàn","vi":"kinh ngạc thán phục"}],"traditional":"讚嘆不已"},{"id":"赞同","hanzi":"赞同","pinyin":"zàntóng","meaning_vi":"tán thành, đồng ý, ủng hộ","explanation":"赞 (tán – ủng hộ) + 同 (đồng – giống, cùng) → cùng ý kiến và ủng hộ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👍","examples":[{"type":"basic","zh":"我赞同你的看法。","pinyin":"Wǒ zàntóng nǐ de kànfǎ.","vi":"Tôi tán thành quan điểm của bạn."},{"type":"simple","zh":"大多数居民赞同在小区里建一个公园。","pinyin":"Dàduōshù jūmín zàntóng zài xiǎoqū li jiàn yí ge gōngyuán.","vi":"Phần lớn cư dân tán thành xây một công viên trong khu dân cư."},{"type":"compound","zh":"即使你不赞同这个方案，也应该说明理由。","pinyin":"Jíshǐ nǐ bú zàntóng zhè ge fāng'àn, yě yīnggāi shuōmíng lǐyóu.","vi":"Dù bạn không tán thành phương án này thì cũng nên nói rõ lý do."}],"related":[{"hanzi":"同意","pinyin":"tóngyì","vi":"đồng ý"},{"hanzi":"赞成","pinyin":"zànchéng","vi":"tán thành"},{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"}],"traditional":"贊同"},{"id":"赞许","hanzi":"赞许","pinyin":"zànxǔ","meaning_vi":"khen ngợi, tán thưởng, ủng hộ","explanation":"赞 (tán – khen) + 许 (hứa – cho phép, chấp thuận) → khen ngợi và chấp nhận, đánh giá tốt.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙂","examples":[{"type":"basic","zh":"老师点头赞许。","pinyin":"Lǎoshī diǎntóu zànxǔ.","vi":"Thầy giáo gật đầu tán thưởng."},{"type":"simple","zh":"他的诚实得到了大家的一致赞许。","pinyin":"Tā de chéngshí dédàole dàjiā de yízhì zànxǔ.","vi":"Sự trung thực của anh ấy được mọi người nhất trí khen ngợi."},{"type":"compound","zh":"因为她主动帮助新同事，所以受到了经理的赞许。","pinyin":"Yīnwèi tā zhǔdòng bāngzhù xīn tóngshì, suǒyǐ shòudàole jīnglǐ de zànxǔ.","vi":"Vì chủ động giúp đỡ đồng nghiệp mới nên cô ấy được quản lý khen ngợi."}],"related":[{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"赞美","pinyin":"zànměi","vi":"ca ngợi"},{"hanzi":"认可","pinyin":"rènkě","vi":"công nhận"},{"hanzi":"责备","pinyin":"zébèi","vi":"trách móc"}],"traditional":"讚許"},{"id":"葬","hanzi":"葬","pinyin":"zàng","meaning_vi":"chôn cất, mai táng","explanation":"葬 (táng – chôn) → chôn cất người chết.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"⚰️","examples":[{"type":"basic","zh":"他死后葬在故乡。","pinyin":"Tā sǐhòu zàng zài gùxiāng.","vi":"Sau khi mất, ông được chôn ở quê nhà."},{"type":"simple","zh":"这位诗人被葬在西湖边的小山上。","pinyin":"Zhè wèi shīrén bèi zàng zài Xīhú biān de xiǎo shān shang.","vi":"Nhà thơ này được an táng trên ngọn đồi nhỏ bên Tây Hồ."},{"type":"compound","zh":"因为老人生前热爱大海，所以家人把他葬在海边。","pinyin":"Yīnwèi lǎorén shēngqián rè'ài dàhǎi, suǒyǐ jiārén bǎ tā zàng zài hǎibiān.","vi":"Vì lúc sinh thời ông cụ yêu biển nên gia đình chôn cất ông bên bờ biển."}],"related":[{"hanzi":"埋葬","pinyin":"máizàng","vi":"chôn cất"},{"hanzi":"葬礼","pinyin":"zànglǐ","vi":"tang lễ"},{"hanzi":"安葬","pinyin":"ānzàng","vi":"an táng"},{"hanzi":"火葬","pinyin":"huǒzàng","vi":"hỏa táng"}]},{"id":"葬礼","hanzi":"葬礼","pinyin":"zànglǐ","meaning_vi":"tang lễ, đám tang","explanation":"葬 (táng – chôn cất) + 礼 (lễ – nghi lễ) → nghi lễ chôn cất, tiễn đưa người đã mất.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🕯️","examples":[{"type":"basic","zh":"葬礼在周日举行。","pinyin":"Zànglǐ zài zhōurì jǔxíng.","vi":"Tang lễ được tổ chức vào Chủ nhật."},{"type":"simple","zh":"很多老同事都来参加了他的葬礼。","pinyin":"Hěn duō lǎo tóngshì dōu lái cānjiāle tā de zànglǐ.","vi":"Nhiều đồng nghiệp cũ đã đến dự đám tang của ông."},{"type":"compound","zh":"虽然葬礼很简单，但是气氛非常庄重。","pinyin":"Suīrán zànglǐ hěn jiǎndān, dànshì qìfēn fēicháng zhuāngzhòng.","vi":"Tuy tang lễ rất giản dị nhưng không khí vô cùng trang nghiêm."}],"related":[{"hanzi":"婚礼","pinyin":"hūnlǐ","vi":"hôn lễ"},{"hanzi":"葬","pinyin":"zàng","vi":"chôn cất"},{"hanzi":"丧事","pinyin":"sāngshì","vi":"việc tang"},{"hanzi":"追悼会","pinyin":"zhuīdàohuì","vi":"lễ truy điệu"}],"traditional":"葬禮"},{"id":"凿","hanzi":"凿","pinyin":"záo","meaning_vi":"đục, khoét; cái đục","explanation":"凿 (tạc – cái đục, đục khoét) → dùng dụng cụ đục, khoét lỗ; danh từ là cái đục.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔨","examples":[{"type":"basic","zh":"工人在墙上凿洞。","pinyin":"Gōngrén zài qiáng shang záo dòng.","vi":"Công nhân đục lỗ trên tường."},{"type":"simple","zh":"古人用简单的工具在岩石上凿出了石窟。","pinyin":"Gǔrén yòng jiǎndān de gōngjù zài yánshí shang záo chūle shíkū.","vi":"Người xưa dùng công cụ thô sơ đục ra những hang đá trên vách núi."},{"type":"compound","zh":"因为井水太少，所以他们决定再往下凿几米。","pinyin":"Yīnwèi jǐngshuǐ tài shǎo, suǒyǐ tāmen juédìng zài wǎng xià záo Jǐmǐ.","vi":"Vì nước giếng quá ít nên họ quyết định đục sâu thêm mấy mét."}],"related":[{"hanzi":"凿子","pinyin":"záozi","vi":"cái đục"},{"hanzi":"开凿","pinyin":"kāizáo","vi":"đào, khai thông"},{"hanzi":"雕刻","pinyin":"diāokè","vi":"điêu khắc"},{"hanzi":"确凿","pinyin":"quèzáo","vi":"xác thực"}],"traditional":"鑿"},{"id":"早年","hanzi":"早年","pinyin":"zǎonián","meaning_vi":"những năm trước, thời trẻ, những năm đầu","explanation":"早 (tảo – sớm) + 年 (niên – năm) → những năm về trước, hoặc thời trẻ của một người.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"他早年当过兵。","pinyin":"Tā zǎonián dāngguo bīng.","vi":"Thời trẻ ông ấy từng đi lính."},{"type":"simple","zh":"这位作家早年在农村生活过很长时间。","pinyin":"Zhè wèi zuòjiā zǎonián zài nóngcūn shēnghuóguo hěn cháng shíjiān.","vi":"Thời trẻ nhà văn này từng sống ở nông thôn rất lâu."},{"type":"compound","zh":"因为早年吃过很多苦，所以他特别珍惜现在的生活。","pinyin":"Yīnwèi zǎonián chīguo hěn duō kǔ, suǒyǐ tā tèbié zhēnxī xiànzài de shēnghuó.","vi":"Vì thời trẻ đã chịu nhiều cực khổ nên ông đặc biệt trân trọng cuộc sống hiện tại."}],"related":[{"hanzi":"晚年","pinyin":"wǎnnián","vi":"tuổi già"},{"hanzi":"当年","pinyin":"dāngnián","vi":"năm đó"},{"hanzi":"青年","pinyin":"qīngnián","vi":"thanh niên"},{"hanzi":"往年","pinyin":"wǎngnián","vi":"những năm trước"}]},{"id":"早日","hanzi":"早日","pinyin":"zǎorì","meaning_vi":"sớm ngày, mau chóng","explanation":"早 (tảo – sớm) + 日 (nhật – ngày) → sớm một ngày nào đó, càng sớm càng tốt; hay dùng trong lời chúc.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"🙏","examples":[{"type":"basic","zh":"祝你早日康复！","pinyin":"Zhù nǐ zǎorì kāngfù!","vi":"Chúc bạn sớm bình phục!"},{"type":"simple","zh":"我们都希望这项工程能早日完工。","pinyin":"Wǒmen dōu xīwàng zhè xiàng gōngchéng néng zǎorì wángōng.","vi":"Chúng tôi đều mong công trình này sớm hoàn thành."},{"type":"compound","zh":"只要大家齐心协力，就能早日实现目标。","pinyin":"Zhǐyào dàjiā qíxīnxiélì, jiù néng zǎorì shíxiàn mùbiāo.","vi":"Chỉ cần mọi người đồng lòng thì sẽ sớm đạt được mục tiêu."}],"related":[{"hanzi":"尽早","pinyin":"jǐnzǎo","vi":"càng sớm càng tốt"},{"hanzi":"提早","pinyin":"tízǎo","vi":"sớm hơn"},{"hanzi":"及早","pinyin":"jízǎo","vi":"kịp sớm"},{"hanzi":"迟早","pinyin":"chízǎo","vi":"sớm muộn"}]},{"id":"枣","hanzi":"枣","pinyin":"zǎo","meaning_vi":"quả táo tàu, táo đỏ","explanation":"枣 (tảo – cây táo tàu) → quả táo tàu (táo đỏ), thường phơi khô dùng nấu cháo, hầm canh.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🫘","examples":[{"type":"basic","zh":"这棵树结满了枣。","pinyin":"Zhè kē shù jié mǎnle zǎo.","vi":"Cây này trĩu quả táo tàu."},{"type":"simple","zh":"奶奶熬粥时喜欢放几颗红枣。","pinyin":"Nǎinai áozhōu shí xǐhuan fàng jǐ kē hóngzǎo.","vi":"Bà nội nấu cháo thích cho vào mấy quả táo đỏ."},{"type":"compound","zh":"虽然这些枣看起来很小，但是吃起来特别甜。","pinyin":"Suīrán zhèxiē zǎo kànqǐlái hěn xiǎo, dànshì chī qǐlái tèbié tián.","vi":"Tuy những quả táo tàu này trông nhỏ nhưng ăn rất ngọt."}],"related":[{"hanzi":"红枣","pinyin":"hóngzǎo","vi":"táo đỏ"},{"hanzi":"枣树","pinyin":"zǎoshù","vi":"cây táo tàu"},{"hanzi":"蜜枣","pinyin":"mìzǎo","vi":"táo tẩm mật"},{"hanzi":"苹果","pinyin":"píngguǒ","vi":"quả táo tây"}],"traditional":"棗"},{"id":"造假","hanzi":"造假","pinyin":"zàojiǎ","meaning_vi":"làm giả, gian lận, làm hàng giả","explanation":"造 (tạo – làm ra) + 假 (giả – không thật) → làm ra đồ giả, ngụy tạo số liệu để lừa dối.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🎭","examples":[{"type":"basic","zh":"他们数据造假。","pinyin":"Tāmen shùjù zàojiǎ.","vi":"Họ làm giả số liệu."},{"type":"simple","zh":"这家工厂因为造假被罚了一大笔钱。","pinyin":"Zhè jiā gōngchǎng yīnwèi zàojiǎ bèi fále yí dàbǐ qián.","vi":"Nhà máy này bị phạt một khoản tiền lớn vì làm hàng giả."},{"type":"compound","zh":"一旦被发现论文造假，他就会失去现在的工作。","pinyin":"Yídàn bèi fāxiàn lùnwén zàojiǎ, tā jiù huì shīqù xiànzài de gōngzuò.","vi":"Một khi bị phát hiện gian lận luận văn, anh ta sẽ mất công việc hiện tại."}],"related":[{"hanzi":"假冒","pinyin":"jiǎmào","vi":"giả mạo"},{"hanzi":"伪造","pinyin":"wěizào","vi":"ngụy tạo"},{"hanzi":"作假","pinyin":"zuòjiǎ","vi":"làm giả"},{"hanzi":"真假","pinyin":"zhēnjiǎ","vi":"thật giả"}]},{"id":"造价","hanzi":"造价","pinyin":"zàojià","meaning_vi":"chi phí xây dựng, giá thành chế tạo","explanation":"造 (tạo – xây, chế tạo) + 价 (giá – giá cả) → chi phí để xây dựng công trình hoặc chế tạo sản phẩm.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🏗️","examples":[{"type":"basic","zh":"这座桥造价很高。","pinyin":"Zhè zuò qiáo zàojià hěn gāo.","vi":"Cây cầu này chi phí xây dựng rất cao."},{"type":"simple","zh":"新体育馆的造价超过了十亿元。","pinyin":"Xīn tǐyùguǎn de zàojià chāoguòle shíyì yuán.","vi":"Chi phí xây dựng nhà thi đấu mới vượt quá một tỷ tệ."},{"type":"compound","zh":"如果改用本地材料，房子的造价就能降低不少。","pinyin":"Rúguǒ gǎiyòng běndì cáiliào, fángzi de zàojià jiù néng jiàngdī bùshǎo.","vi":"Nếu chuyển sang dùng vật liệu địa phương thì chi phí xây nhà có thể giảm đáng kể."}],"related":[{"hanzi":"成本","pinyin":"chéngběn","vi":"giá thành"},{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"},{"hanzi":"造价师","pinyin":"zàojiàshī","vi":"kỹ sư định giá"},{"hanzi":"预算","pinyin":"yùsuàn","vi":"dự toán"}],"traditional":"造價"},{"id":"噪声","hanzi":"噪声","pinyin":"zàoshēng","meaning_vi":"tiếng ồn","explanation":"噪 (táo – ồn ào) + 声 (thanh – âm thanh) → âm thanh ồn ào gây khó chịu.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"🔊","examples":[{"type":"basic","zh":"外面噪声太大了。","pinyin":"Wàimiàn zàoshēng tài dà le.","vi":"Bên ngoài ồn quá."},{"type":"simple","zh":"长期生活在噪声环境中会影响听力。","pinyin":"Chángqī shēnghuó zài zàoshēng huánjìng zhōng huì yǐngxiǎng tīnglì.","vi":"Sống lâu trong môi trường tiếng ồn sẽ ảnh hưởng đến thính lực."},{"type":"compound","zh":"因为工地的噪声太大，所以居民向政府投诉了。","pinyin":"Yīnwèi gōngdì de zàoshēng tài dà, suǒyǐ jūmín xiàng zhèngfǔ tóusù le.","vi":"Vì tiếng ồn ở công trường quá lớn nên cư dân đã khiếu nại lên chính quyền."}],"related":[{"hanzi":"噪音","pinyin":"zàoyīn","vi":"tiếng ồn"},{"hanzi":"声音","pinyin":"shēngyīn","vi":"âm thanh"},{"hanzi":"安静","pinyin":"ānjìng","vi":"yên tĩnh"},{"hanzi":"隔音","pinyin":"géyīn","vi":"cách âm"}],"traditional":"噪聲"},{"id":"则","hanzi":"则","pinyin":"zé","meaning_vi":"thì, lại (văn viết); quy tắc; lượng từ cho mẩu tin, bài","explanation":"则 (tắc – phép tắc; thì) → liên từ văn viết nghĩa \"thì\", biểu thị kết quả hoặc đối lập; còn là lượng từ cho tin tức, truyện ngắn và nghĩa quy tắc như 规则.","hsk_level":"7-9","tags":["lien-tu"],"image":"📏","examples":[{"type":"basic","zh":"欲速则不达。","pinyin":"Yù sù zé bù dá.","vi":"Dục tốc bất đạt."},{"type":"simple","zh":"这则新闻引起了网友的广泛关注。","pinyin":"Zhè zé xīnwén yǐnqǐle wǎngyǒu de guǎngfàn guānzhù.","vi":"Mẩu tin này thu hút sự quan tâm rộng rãi của cư dân mạng."},{"type":"compound","zh":"如果大家同心协力，则任何困难都能克服。","pinyin":"Rúguǒ dàjiā tóngxīnxiélì, zé rènhé kùnnan dōu néng kèfú.","vi":"Nếu mọi người đồng lòng hiệp lực thì khó khăn nào cũng có thể vượt qua."}],"related":[{"hanzi":"规则","pinyin":"guīzé","vi":"quy tắc"},{"hanzi":"原则","pinyin":"yuánzé","vi":"nguyên tắc"},{"hanzi":"否则","pinyin":"fǒuzé","vi":"nếu không thì"},{"hanzi":"就","pinyin":"jiù","vi":"thì"}],"traditional":"則"},{"id":"责备","hanzi":"责备","pinyin":"zébèi","meaning_vi":"trách móc, trách mắng, khiển trách","explanation":"责 (trách – trách nhiệm, trách) + 备 (bị – đầy đủ, cầu toàn) → trách cứ, phê bình lỗi của người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😒","examples":[{"type":"basic","zh":"妈妈没有责备我。","pinyin":"Māma méiyǒu zébèi wǒ.","vi":"Mẹ không trách tôi."},{"type":"simple","zh":"他总是用严厉的口气责备犯错的学生。","pinyin":"Tā zǒngshì yòng yánlì de kǒuqì zébèi fàncuò de xuésheng.","vi":"Ông ấy luôn trách mắng học sinh mắc lỗi bằng giọng nghiêm khắc."},{"type":"compound","zh":"虽然这次是你的错，但是我不想再责备你了。","pinyin":"Suīrán zhè cì shì nǐ de cuò, dànshì wǒ bù xiǎng zài zébèi nǐ le.","vi":"Tuy lần này là lỗi của bạn nhưng tôi không muốn trách bạn nữa."}],"related":[{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"},{"hanzi":"指责","pinyin":"zhǐzé","vi":"chỉ trích"},{"hanzi":"责怪","pinyin":"zéguài","vi":"trách móc"},{"hanzi":"表扬","pinyin":"biǎoyáng","vi":"khen ngợi"}],"traditional":"責備"},{"id":"增收","hanzi":"增收","pinyin":"zēngshōu","meaning_vi":"tăng thu nhập, tăng thu","explanation":"增 (tăng – thêm) + 收 (thu – thu nhập) → làm tăng nguồn thu; cũng có nghĩa thu thêm phí.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"农民今年增收了。","pinyin":"Nóngmín jīnnián zēngshōu le.","vi":"Năm nay nông dân tăng thu nhập."},{"type":"simple","zh":"种植茶叶帮助山区群众实现了增收。","pinyin":"Zhòngzhí cháyè bāngzhù shānqū qúnzhòng shíxiànle zēngshōu.","vi":"Trồng chè đã giúp người dân miền núi tăng thu nhập."},{"type":"compound","zh":"因为发展了乡村旅游，所以村民们普遍增收。","pinyin":"Yīnwèi fāzhǎnle xiāngcūnlǚyóu, suǒyǐ cūnmínmen pǔbiàn zēngshōu.","vi":"Vì phát triển du lịch nông thôn nên người dân trong làng phần lớn đều tăng thu nhập."}],"related":[{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"增产","pinyin":"zēngchǎn","vi":"tăng sản lượng"},{"hanzi":"减收","pinyin":"jiǎnshōu","vi":"giảm thu"},{"hanzi":"增长","pinyin":"zēngzhǎng","vi":"tăng trưởng"}]},{"id":"渣子","hanzi":"渣子","pinyin":"zhāzi","meaning_vi":"cặn, bã, vụn","explanation":"渣 (tra – cặn bã) + 子 (tử – hậu tố danh từ) → phần cặn bã, vụn vặt còn lại sau khi lọc hoặc ăn.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"🍞","examples":[{"type":"basic","zh":"桌上都是面包渣子。","pinyin":"Zhuō Shangdōu shì miànbāo zhāzi.","vi":"Trên bàn toàn vụn bánh mì."},{"type":"simple","zh":"喝完中药后碗底还剩下一些药渣子。","pinyin":"Hē wán zhōngyào hòu wǎn dǐ hái shèngxià yìxiē yào zhāzi.","vi":"Uống xong thuốc bắc, dưới đáy bát vẫn còn ít bã thuốc."},{"type":"compound","zh":"如果不把咖啡渣子倒掉，水池就容易堵住。","pinyin":"Rúguǒ bù bǎ kāfēi zhāzi dào diào, shuǐchí jiù róngyì dǔzhù.","vi":"Nếu không đổ bỏ bã cà phê thì bồn rửa dễ bị tắc."}],"related":[{"hanzi":"渣","pinyin":"zhā","vi":"cặn bã"},{"hanzi":"碎屑","pinyin":"suìxiè","vi":"mảnh vụn"},{"hanzi":"残渣","pinyin":"cánzhā","vi":"cặn thừa"},{"hanzi":"豆渣","pinyin":"dòuzhā","vi":"bã đậu"}]},{"id":"闸","hanzi":"闸","pinyin":"zhá","meaning_vi":"cửa cống, đập nước; phanh (xe)","explanation":"闸 (áp/sạp – cửa cống) → cửa ngăn nước trên sông, kênh; khẩu ngữ chỉ cái phanh xe hoặc cầu dao điện.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚧","examples":[{"type":"basic","zh":"工人打开了水闸。","pinyin":"Gōngrén dǎkāile shuǐzhá.","vi":"Công nhân đã mở cửa cống."},{"type":"simple","zh":"下坡时他赶紧捏住了自行车的车闸。","pinyin":"Xiàpō shí tā gǎnjǐn niē zhùle zìxíngchē de chēzhá.","vi":"Khi xuống dốc anh ấy vội bóp phanh xe đạp."},{"type":"compound","zh":"一旦上游的河水上涨，就要马上关闭闸门。","pinyin":"Yídàn shàngyóu de héshuǐ shàngzhǎng, jiùyào mǎshàng guānbì zhámén.","vi":"Một khi nước sông thượng nguồn dâng lên thì phải đóng cửa cống ngay."}],"related":[{"hanzi":"闸门","pinyin":"zhámén","vi":"cửa cống"},{"hanzi":"水闸","pinyin":"shuǐzhá","vi":"cống nước"},{"hanzi":"刹车","pinyin":"shāchē","vi":"phanh xe"},{"hanzi":"电闸","pinyin":"diànzhá","vi":"cầu dao điện"}],"traditional":"閘"},{"id":"眨眼","hanzi":"眨眼","pinyin":"zhǎyǎn","meaning_vi":"chớp mắt, nháy mắt, trong nháy mắt","explanation":"眨 (trát – chớp) + 眼 (nhãn – mắt) → mắt nhắm mở nhanh; nghĩa bóng là thời gian cực ngắn.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"😉","examples":[{"type":"basic","zh":"她对我眨眼。","pinyin":"Tā duì wǒ zhǎyǎn.","vi":"Cô ấy nháy mắt với tôi."},{"type":"simple","zh":"一眨眼的工夫，孩子就跑得没影了。","pinyin":"Yìzhǎyǎn de gōngfu, háizi jiù pǎo de méiyǐng le.","vi":"Chỉ trong nháy mắt, đứa trẻ đã chạy mất hút."},{"type":"compound","zh":"虽然魔术师就在眼前表演，但是我一眨眼硬币就不见了。","pinyin":"Suīrán móshùshī jiù zài yǎnqián biǎoyǎn, dànshì wǒ yìzhǎyǎn yìngbì jiù bújiàn le.","vi":"Tuy ảo thuật gia biểu diễn ngay trước mắt nhưng tôi vừa chớp mắt thì đồng xu đã biến mất."}],"related":[{"hanzi":"一眨眼","pinyin":"yìzhǎyǎn","vi":"trong chớp mắt"},{"hanzi":"转眼","pinyin":"zhuǎnyǎn","vi":"thoáng chốc"},{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"đôi mắt"},{"hanzi":"瞬间","pinyin":"shùnjiān","vi":"khoảnh khắc"}]},{"id":"榨","hanzi":"榨","pinyin":"zhà","meaning_vi":"ép, vắt; bóc lột","explanation":"榨 (trá – ép) → dùng lực ép để lấy nước, dầu; nghĩa bóng là bóc lột, vắt kiệt.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🧃","examples":[{"type":"basic","zh":"我榨了一杯橙汁。","pinyin":"Wǒ zhàle yì bēi chéngzhī.","vi":"Tôi đã ép một cốc nước cam."},{"type":"simple","zh":"这台机器每天能榨好几吨甘蔗。","pinyin":"Zhè tái jīqì měitiān néng zhà hǎojǐ dūn gānzhè.","vi":"Cái máy này mỗi ngày ép được mấy tấn mía."},{"type":"compound","zh":"如果用新鲜的苹果榨汁，味道就会更甜。","pinyin":"Rúguǒ yòng xīnxiān de píngguǒ zhàzhī, wèidào jiù huì gèng tián.","vi":"Nếu dùng táo tươi ép nước thì vị sẽ ngọt hơn."}],"related":[{"hanzi":"压榨","pinyin":"yāzhà","vi":"ép, bóc lột"},{"hanzi":"榨汁机","pinyin":"zhàzhījī","vi":"máy ép trái cây"},{"hanzi":"果汁","pinyin":"guǒzhī","vi":"nước trái cây"},{"hanzi":"挤","pinyin":"jǐ","vi":"vắt, nặn"}]},{"id":"窄","hanzi":"窄","pinyin":"zhǎi","meaning_vi":"hẹp, chật; hẹp hòi","explanation":"窄 (trách – hẹp) → chiều ngang nhỏ, chật hẹp; nghĩa bóng là hẹp hòi, không rộng lượng.","hsk_level":"7-9","tags":["tinh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"这条路很窄。","pinyin":"Zhè tiáo lù hěn zhǎi.","vi":"Con đường này rất hẹp."},{"type":"simple","zh":"老城区的小巷窄得只能过一辆车。","pinyin":"Lǎochéngqū de xiǎoxiàng zhǎi de zhǐnéngguò yí liàng chē.","vi":"Ngõ nhỏ ở khu phố cổ hẹp đến mức chỉ vừa một chiếc xe."},{"type":"compound","zh":"虽然房间很窄，但是收拾得非常干净。","pinyin":"Suīrán fángjiān hěn zhǎi, dànshì shōushi de fēicháng gānjìng.","vi":"Tuy căn phòng rất chật nhưng được dọn dẹp rất sạch sẽ."}],"related":[{"hanzi":"宽","pinyin":"kuān","vi":"rộng"},{"hanzi":"狭窄","pinyin":"xiázhǎi","vi":"chật hẹp"},{"hanzi":"心胸狭窄","pinyin":"xīnxiōngxiázhǎi","vi":"lòng dạ hẹp hòi"},{"hanzi":"窄小","pinyin":"zhǎixiǎo","vi":"chật chội"}]},{"id":"债务","hanzi":"债务","pinyin":"zhàiwù","meaning_vi":"nợ, khoản nợ, công nợ","explanation":"债 (trái – nợ) + 务 (vụ – việc) → khoản tiền phải trả cho người khác, nghĩa vụ trả nợ.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"他还清了债务。","pinyin":"Tā huán qīngle zhàiwù.","vi":"Anh ấy đã trả hết nợ."},{"type":"simple","zh":"这家公司因为债务问题被迫停业。","pinyin":"Zhè jiā gōngsī yīnwèi zhàiwù wèntí bèipò tíngyè.","vi":"Công ty này buộc phải ngừng kinh doanh vì vấn đề nợ nần."},{"type":"compound","zh":"如果债务越积越多，生活压力就会越来越大。","pinyin":"Rúguǒ zhàiwù yuè jī yuè duō, shēnghuó yālì jiù huì yuèláiyuè dà.","vi":"Nếu nợ nần càng tích càng nhiều thì áp lực cuộc sống sẽ ngày càng lớn."}],"related":[{"hanzi":"欠债","pinyin":"qiànzhài","vi":"mắc nợ"},{"hanzi":"债权","pinyin":"zhàiquán","vi":"quyền đòi nợ"},{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"khoản vay"},{"hanzi":"还债","pinyin":"huánzhài","vi":"trả nợ"}],"traditional":"債務"},{"id":"沾","hanzi":"沾","pinyin":"zhān","meaning_vi":"dính, thấm, vấy; nhờ, hưởng lây","explanation":"沾 (triêm – thấm ướt) → bị dính, thấm vào; nghĩa bóng là được hưởng lây lợi ích nhờ quan hệ (沾光).","hsk_level":"7-9","tags":["dong-tu"],"image":"💦","examples":[{"type":"basic","zh":"鞋上沾了泥。","pinyin":"Xié shang zhānle ní.","vi":"Giày dính bùn."},{"type":"simple","zh":"他的衬衫上沾了一大块油渍。","pinyin":"Tā de chènshān shang zhānle yí dà kuài yóuzì.","vi":"Áo sơ mi của anh ấy dính một vết dầu mỡ to."},{"type":"compound","zh":"因为刚下过雨，所以裤脚沾满了泥水。","pinyin":"Yīnwèi gāng xiàguo yǔ, suǒyǐ kùjiǎo zhānmǎnle níshuǐ.","vi":"Vì trời vừa mưa nên ống quần dính đầy nước bùn."}],"related":[{"hanzi":"沾光","pinyin":"zhānguāng","vi":"hưởng lây"},{"hanzi":"粘","pinyin":"zhān","vi":"dính"},{"hanzi":"沾湿","pinyin":"zhānshī","vi":"làm ướt"},{"hanzi":"污染","pinyin":"wūrǎn","vi":"ô nhiễm"}]},{"id":"粘","hanzi":"粘","pinyin":"zhān","meaning_vi":"dán, dính, bám dính","explanation":"粘 (niêm – dính) → dùng keo, hồ làm cho vật dính vào nhau; đọc nián khi là tính từ \"dính, nhớt\" (cũng viết 黏).","hsk_level":"7-9","tags":["dong-tu"],"image":"🩹","examples":[{"type":"basic","zh":"把邮票粘在信封上。","pinyin":"Bǎ yóupiào zhān zài xìnfēng shang.","vi":"Dán tem lên phong bì."},{"type":"simple","zh":"小女孩用胶水把碎纸片粘了起来。","pinyin":"Xiǎo nǚhái yòng jiāoshuǐ bǎ suì zhǐpiàn zhānle qǐlái.","vi":"Cô bé dùng keo dán các mảnh giấy vụn lại với nhau."},{"type":"compound","zh":"因为糖化了，所以几块饼干粘在了一起。","pinyin":"Yīnwèi táng huà le, suǒyǐ jǐ kuài bǐnggān zhān zài le yìqǐ.","vi":"Vì đường chảy ra nên mấy chiếc bánh quy dính vào nhau."}],"related":[{"hanzi":"胶水","pinyin":"jiāoshuǐ","vi":"keo dán"},{"hanzi":"粘贴","pinyin":"zhāntiē","vi":"dán"},{"hanzi":"黏","pinyin":"nián","vi":"dính, nhớt"},{"hanzi":"沾","pinyin":"zhān","vi":"dính"}]},{"id":"斩","hanzi":"斩","pinyin":"zhǎn","meaning_vi":"chém, chặt; hạ gục (đối thủ)","explanation":"斩 (trảm – chém) → chém, chặt đứt; nghĩa thời nay hay dùng là đánh bại, hạ gục đối thủ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗡️","examples":[{"type":"basic","zh":"他一刀斩断绳子。","pinyin":"Tā yì dāo zhǎnduàn shéngzi.","vi":"Anh ta chém một nhát đứt dây thừng."},{"type":"simple","zh":"这支球队在决赛中力斩对手夺冠。","pinyin":"Zhè zhī qiúduì zài juésài zhōng lì zhǎn duìshǒu duóguàn.","vi":"Đội bóng này đánh bại đối thủ trong trận chung kết và giành chức vô địch."},{"type":"compound","zh":"虽然对手都很强，但是他还是连斩三人进入决赛。","pinyin":"Suīrán duìshǒu dōu hěn qiáng, dànshì tā háishi lián zhǎn sān rén jìnrù juésài.","vi":"Tuy các đối thủ đều mạnh nhưng anh ấy vẫn liên tiếp hạ ba người để vào chung kết."}],"related":[{"hanzi":"砍","pinyin":"kǎn","vi":"chặt"},{"hanzi":"斩首","pinyin":"zhǎnshǒu","vi":"chém đầu"},{"hanzi":"斩草除根","pinyin":"zhǎncǎochúgēn","vi":"nhổ cỏ tận gốc"},{"hanzi":"斩钉截铁","pinyin":"zhǎndīngjiétiě","vi":"dứt khoát"}],"traditional":"斬"},{"id":"斩草除根","hanzi":"斩草除根","pinyin":"zhǎncǎo-chúgēn","meaning_vi":"nhổ cỏ tận gốc, diệt trừ triệt để","explanation":"Nghĩa đen: cắt cỏ (斩草 – trảm thảo) phải bỏ cả rễ (除根 – trừ căn) → diệt trừ tận gốc, không để mầm họa tái phát.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌿","examples":[{"type":"basic","zh":"解决问题要斩草除根。","pinyin":"Jiějué wèntí yào zhǎncǎochúgēn.","vi":"Giải quyết vấn đề phải trừ tận gốc."},{"type":"simple","zh":"警方决心对这个犯罪团伙斩草除根。","pinyin":"Jǐngfāng juéxīn duì zhè ge fànzuì tuánhuǒ zhǎncǎochúgēn.","vi":"Cảnh sát quyết tâm triệt phá tận gốc băng nhóm tội phạm này."},{"type":"compound","zh":"如果不斩草除根，这种病毒就会再次爆发。","pinyin":"Rúguǒ bù zhǎncǎochúgēn, zhè zhǒng bìngdú jiù huì zàicì bàofā.","vi":"Nếu không diệt trừ tận gốc thì loại virus này sẽ lại bùng phát."}],"related":[{"hanzi":"根除","pinyin":"gēnchú","vi":"trừ tận gốc"},{"hanzi":"彻底","pinyin":"chèdǐ","vi":"triệt để"},{"hanzi":"治标不治本","pinyin":"zhìbiāo bú zhìběn","vi":"chữa ngọn không chữa gốc"},{"hanzi":"斩","pinyin":"zhǎn","vi":"chém"}],"traditional":"斬草除根"},{"id":"展出","hanzi":"展出","pinyin":"zhǎnchū","meaning_vi":"trưng bày, triển lãm, đem ra trưng bày","explanation":"展 (triển – bày ra) + 出 (xuất – ra) → đem ra trưng bày cho công chúng xem.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🖼️","examples":[{"type":"basic","zh":"这些文物首次展出。","pinyin":"Zhèxiē wénwù shǒucì zhǎnchū.","vi":"Những cổ vật này được trưng bày lần đầu."},{"type":"simple","zh":"博物馆正在展出一批珍贵的古代瓷器。","pinyin":"Bówùguǎn zhèngzài zhǎnchū yìpī zhēnguì de gǔdài cíqì.","vi":"Bảo tàng đang trưng bày một loạt đồ sứ cổ quý giá."},{"type":"compound","zh":"虽然这些画只展出一周，但是吸引了上万名观众。","pinyin":"Suīrán zhèxiē huà zhǐ zhǎnchū yìzhōu, dànshì xīyǐnle shàng wànmíng guānzhòng.","vi":"Tuy những bức tranh này chỉ trưng bày một tuần nhưng đã thu hút hơn vạn khán giả."}],"related":[{"hanzi":"展览","pinyin":"zhǎnlǎn","vi":"triển lãm"},{"hanzi":"陈列","pinyin":"chénliè","vi":"bày biện"},{"hanzi":"展示","pinyin":"zhǎnshì","vi":"trưng bày"},{"hanzi":"展品","pinyin":"zhǎnpǐn","vi":"hiện vật trưng bày"}]},{"id":"展览会","hanzi":"展览会","pinyin":"zhǎnlǎnhuì","meaning_vi":"cuộc triển lãm, hội chợ triển lãm","explanation":"展览 (triển lãm – trưng bày cho xem) + 会 (hội – cuộc họp, sự kiện) → sự kiện trưng bày sản phẩm, tác phẩm.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"我们去看展览会吧。","pinyin":"Wǒmen qù kàn zhǎnlǎnhuì ba.","vi":"Chúng ta đi xem triển lãm đi."},{"type":"simple","zh":"这次汽车展览会吸引了许多国外厂商。","pinyin":"Zhè cì qìchē zhǎnlǎnhuì xīyǐnle xǔduō guówài chǎngshāng.","vi":"Triển lãm ô tô lần này thu hút nhiều nhà sản xuất nước ngoài."},{"type":"compound","zh":"因为展览会门票是免费的，所以周末来了很多市民。","pinyin":"Yīnwèi zhǎnlǎnhuì ménpiào shì miǎnfèi de, suǒyǐ zhōumò láile hěn duō shìmín.","vi":"Vì vé vào triển lãm miễn phí nên cuối tuần có rất nhiều người dân đến."}],"related":[{"hanzi":"博览会","pinyin":"bólǎnhuì","vi":"hội chợ triển lãm"},{"hanzi":"展出","pinyin":"zhǎnchū","vi":"trưng bày"},{"hanzi":"画展","pinyin":"huàzhǎn","vi":"triển lãm tranh"},{"hanzi":"展厅","pinyin":"zhǎntīng","vi":"phòng triển lãm"}],"traditional":"展覽會"},{"id":"盏","hanzi":"盏","pinyin":"zhǎn","meaning_vi":"chiếc, ngọn (lượng từ cho đèn); chén nhỏ","explanation":"盏 (trản – chén nhỏ) → vốn là chén nhỏ; nay chủ yếu làm lượng từ cho đèn.","hsk_level":"7-9","tags":["luong-tu"],"image":"🪔","examples":[{"type":"basic","zh":"桌上有一盏台灯。","pinyin":"Zhuō shang yǒu yì zhǎn táidēng.","vi":"Trên bàn có một chiếc đèn bàn."},{"type":"simple","zh":"深夜里只有他家还亮着一盏灯。","pinyin":"Shēnyè li zhǐyǒu tā jiā hái liàngzhe yì zhǎn dēng.","vi":"Đêm khuya chỉ có nhà anh ấy còn sáng một ngọn đèn."},{"type":"compound","zh":"因为路边新装了几盏路灯，所以晚上走路安全多了。","pinyin":"Yīnwèi lùbiān xīn zhuāngle jǐ zhǎn lùdēng, suǒyǐ wǎnshang zǒulù ānquán duō le.","vi":"Vì ven đường mới lắp mấy ngọn đèn đường nên đi bộ buổi tối an toàn hơn nhiều."}],"related":[{"hanzi":"灯","pinyin":"dēng","vi":"đèn"},{"hanzi":"台灯","pinyin":"táidēng","vi":"đèn bàn"},{"hanzi":"灯笼","pinyin":"dēnglong","vi":"đèn lồng"},{"hanzi":"茶盏","pinyin":"cházhǎn","vi":"chén trà"}],"traditional":"盞"},{"id":"占卜","hanzi":"占卜","pinyin":"zhānbǔ","meaning_vi":"bói toán, xem bói","explanation":"占 (chiêm – xem điềm) + 卜 (bốc – bói) → dùng các phương pháp như mai rùa, quẻ để đoán việc lành dữ.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🔮","examples":[{"type":"basic","zh":"古人用龟甲占卜。","pinyin":"Gǔrén yòng guījiǎ zhānbǔ.","vi":"Người xưa dùng mai rùa để bói."},{"type":"simple","zh":"她不太相信用塔罗牌占卜未来。","pinyin":"Tā bú tài xiāngxìn yòng tǎluópái zhānbǔ wèilái.","vi":"Cô ấy không mấy tin vào việc dùng bài tarot bói tương lai."},{"type":"compound","zh":"虽然占卜没有科学根据，但是很多人还是觉得有趣。","pinyin":"Suīrán zhānbǔ méiyǒu kēxué gēnjù, dànshì hěn duō rén háishi juéde yǒuqù.","vi":"Tuy bói toán không có cơ sở khoa học nhưng nhiều người vẫn thấy thú vị."}],"related":[{"hanzi":"算命","pinyin":"suànmìng","vi":"xem bói"},{"hanzi":"预言","pinyin":"yùyán","vi":"tiên tri"},{"hanzi":"迷信","pinyin":"míxìn","vi":"mê tín"},{"hanzi":"甲骨文","pinyin":"jiǎgǔwén","vi":"chữ giáp cốt"}]},{"id":"占用","hanzi":"占用","pinyin":"zhànyòng","meaning_vi":"chiếm dụng, chiếm, tốn (thời gian, chỗ)","explanation":"占 (chiếm – giữ lấy) + 用 (dụng – dùng) → chiếm lấy để dùng, làm tốn thời gian, không gian.","hsk_level":"7-9","tags":["dong-tu"],"image":"🅿️","examples":[{"type":"basic","zh":"别占用消防通道。","pinyin":"Bié zhànyòng xiāofáng tōngdào.","vi":"Đừng chiếm dụng lối thoát hiểm."},{"type":"simple","zh":"这款游戏会占用手机很大的内存。","pinyin":"Zhè kuǎn yóuxì huì zhànyòng shǒujī hěn dà de nèicún.","vi":"Trò chơi này chiếm rất nhiều bộ nhớ điện thoại."},{"type":"compound","zh":"如果不会占用您太多时间，我想问几个问题。","pinyin":"Rúguǒ bú huì zhànyòng nín tài duō shíjiān, wǒ xiǎng wèn jǐ ge wèntí.","vi":"Nếu không chiếm quá nhiều thời gian của ngài, tôi muốn hỏi vài câu."}],"related":[{"hanzi":"占据","pinyin":"zhànjù","vi":"chiếm giữ"},{"hanzi":"占领","pinyin":"zhànlǐng","vi":"chiếm lĩnh"},{"hanzi":"使用","pinyin":"shǐyòng","vi":"sử dụng"},{"hanzi":"挪用","pinyin":"nuóyòng","vi":"biển thủ, dùng sai mục đích"}],"traditional":"佔用"},{"id":"站立","hanzi":"站立","pinyin":"zhànlì","meaning_vi":"đứng, đứng thẳng","explanation":"站 (trạm – đứng) + 立 (lập – đứng thẳng) → ở tư thế đứng trên hai chân.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"🧍","examples":[{"type":"basic","zh":"请站立排队。","pinyin":"Qǐng zhànlì páiduì.","vi":"Xin vui lòng đứng xếp hàng."},{"type":"simple","zh":"宝宝已经能扶着沙发站立了。","pinyin":"Bǎobao yǐjīng néng fúzhe shāfā zhànlì le.","vi":"Em bé đã có thể vịn ghế sofa đứng lên rồi."},{"type":"compound","zh":"因为长时间站立工作，所以她的腿经常很酸。","pinyin":"Yīnwèi cháng shíjiān zhànlì gōngzuò, suǒyǐ tā de tuǐ jīngcháng hěn suān.","vi":"Vì phải đứng làm việc trong thời gian dài nên chân cô ấy thường xuyên mỏi nhừ."}],"related":[{"hanzi":"站","pinyin":"zhàn","vi":"đứng"},{"hanzi":"坐下","pinyin":"zuòxià","vi":"ngồi xuống"},{"hanzi":"起立","pinyin":"qǐlì","vi":"đứng dậy"},{"hanzi":"直立","pinyin":"zhílì","vi":"đứng thẳng"}]},{"id":"蘸","hanzi":"蘸","pinyin":"zhàn","meaning_vi":"chấm, nhúng (vào nước chấm, mực…)","explanation":"蘸 (trám – chấm) → nhúng nhẹ vật vào chất lỏng hoặc bột rồi lấy ra.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🥟","examples":[{"type":"basic","zh":"饺子蘸醋吃。","pinyin":"Jiǎozi zhàn cù chī.","vi":"Sủi cảo chấm giấm ăn."},{"type":"simple","zh":"书法老师用毛笔蘸了点墨开始写字。","pinyin":"Shūfǎ lǎoshī yòng máobǐ zhànle diǎn mò kāishǐ xiězì.","vi":"Thầy thư pháp chấm bút lông vào chút mực rồi bắt đầu viết."},{"type":"compound","zh":"如果炸春卷蘸上一点鱼露，味道就会更香。","pinyin":"Rúguǒ zhá chūnjuǎn zhàn shàng yìdiǎn yúlù, wèidào jiù huì gèng xiāng.","vi":"Nếu chấm nem rán với chút nước mắm thì sẽ thơm ngon hơn."}],"related":[{"hanzi":"蘸酱","pinyin":"zhànjiàng","vi":"chấm tương"},{"hanzi":"酱油","pinyin":"jiàngyóu","vi":"xì dầu"},{"hanzi":"沾","pinyin":"zhān","vi":"dính"},{"hanzi":"泡","pinyin":"pào","vi":"ngâm"}]},{"id":"张灯结彩","hanzi":"张灯结彩","pinyin":"zhāngdēng-jiécǎi","meaning_vi":"giăng đèn kết hoa, trang hoàng rực rỡ","explanation":"张灯 (trương đăng – treo đèn) + 结彩 (kết thải – kết lụa màu) → treo đèn lồng, kết dải lụa màu; tả cảnh trang hoàng ngày lễ tết, vui mừng.","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"街上张灯结彩。","pinyin":"Jiēshang zhāngdēngjiécǎi.","vi":"Phố xá giăng đèn kết hoa."},{"type":"simple","zh":"春节前，家家户户都张灯结彩。","pinyin":"Chūnjié qián, jiājiāhùhù dōu zhāngdēngjiécǎi.","vi":"Trước Tết, nhà nhà đều giăng đèn kết hoa."},{"type":"compound","zh":"因为明天是国庆节，所以整个广场都张灯结彩。","pinyin":"Yīnwèi míngtiān shì Guóqìngjié, suǒyǐ zhěnggè guǎngchǎng dōu zhāngdēngjiécǎi.","vi":"Vì mai là Quốc khánh nên cả quảng trường đều giăng đèn kết hoa."}],"related":[{"hanzi":"灯笼","pinyin":"dēnglong","vi":"đèn lồng"},{"hanzi":"喜气洋洋","pinyin":"xǐqìyángyáng","vi":"hân hoan vui mừng"},{"hanzi":"装饰","pinyin":"zhuāngshì","vi":"trang trí"},{"hanzi":"节日","pinyin":"jiérì","vi":"ngày lễ"}],"traditional":"張燈結彩"},{"id":"张贴","hanzi":"张贴","pinyin":"zhāngtiē","meaning_vi":"dán, niêm yết (thông báo, áp phích)","explanation":"张 (trương – mở ra, bày ra) + 贴 (thiếp – dán) → dán thông báo, áp phích lên chỗ công cộng cho mọi người xem.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📌","examples":[{"type":"basic","zh":"这里禁止张贴广告。","pinyin":"Zhèlǐ jìnzhǐ zhāngtiē guǎnggào.","vi":"Ở đây cấm dán quảng cáo."},{"type":"simple","zh":"学校门口张贴了一张考试通知。","pinyin":"Xuéxiào ménkǒu zhāngtiēle yì zhāng kǎoshì tōngzhī.","vi":"Ở cổng trường có dán một tờ thông báo thi."},{"type":"compound","zh":"如果你想找到丢失的小狗，就在小区里张贴寻狗启事。","pinyin":"Rúguǒ nǐ xiǎng zhǎodào diūshī de xiǎogǒu, jiù zài xiǎoqū li zhāngtiē xún gǒu qǐshì.","vi":"Nếu bạn muốn tìm lại chú chó bị lạc thì hãy dán thông báo tìm chó trong khu dân cư."}],"related":[{"hanzi":"贴","pinyin":"tiē","vi":"dán"},{"hanzi":"海报","pinyin":"hǎibào","vi":"áp phích"},{"hanzi":"公告","pinyin":"gōnggào","vi":"thông cáo"},{"hanzi":"布告","pinyin":"bùgào","vi":"bố cáo"}],"traditional":"張貼"},{"id":"张扬","hanzi":"张扬","pinyin":"zhāngyáng","meaning_vi":"phô trương, làm rùm beng, để lộ ra ngoài","explanation":"张 (trương – mở rộng) + 扬 (dương – tung lên, truyền ra) → làm cho nhiều người biết, phô trương; cũng chỉ tính cách thích thể hiện.","hsk_level":"7-9","tags":["dong-tu","con-nguoi"],"image":"📢","examples":[{"type":"basic","zh":"这件事别张扬。","pinyin":"Zhè jiàn shì bié zhāngyáng.","vi":"Chuyện này đừng làm rùm beng."},{"type":"simple","zh":"他中了大奖以后一点也不张扬。","pinyin":"Tā zhòngle dàjiǎng yǐhòu yìdiǎn yě bù zhāngyáng.","vi":"Sau khi trúng giải lớn anh ấy chẳng hề phô trương chút nào."},{"type":"compound","zh":"虽然她家很有钱，但是她从来不张扬。","pinyin":"Suīrán tā jiā hěn yǒuqián, dànshì tā cóngláibù zhāngyáng.","vi":"Tuy nhà cô ấy rất giàu nhưng cô ấy chưa bao giờ phô trương."}],"related":[{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"低调","pinyin":"dīdiào","vi":"khiêm tốn, kín đáo"},{"hanzi":"宣扬","pinyin":"xuānyáng","vi":"tuyên truyền"},{"hanzi":"高调","pinyin":"gāodiào","vi":"phô trương"}],"traditional":"張揚"},{"id":"长达","hanzi":"长达","pinyin":"chángdá","meaning_vi":"dài tới, kéo dài đến","explanation":"长 (trường – dài) + 达 (đạt – tới) → (thời gian, độ dài) lên tới con số nào đó, nhấn mạnh là dài.","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"会议长达三小时。","pinyin":"Huìyì chángdá sān xiǎoshí.","vi":"Cuộc họp kéo dài tới ba tiếng."},{"type":"simple","zh":"这条隧道长达十二公里。","pinyin":"Zhè tiáo suìdào chángdá shí'èr gōnglǐ.","vi":"Đường hầm này dài tới mười hai cây số."},{"type":"compound","zh":"虽然排队时间长达两个小时，但是大家都很耐心。","pinyin":"Suīrán páiduì shíjiān chángdá liǎng gè xiǎoshí, dànshì dàjiā dōu hěn nàixīn.","vi":"Tuy phải xếp hàng tới hai tiếng nhưng mọi người đều rất kiên nhẫn."}],"related":[{"hanzi":"达到","pinyin":"dádào","vi":"đạt tới"},{"hanzi":"长久","pinyin":"chángjiǔ","vi":"lâu dài"},{"hanzi":"持续","pinyin":"chíxù","vi":"kéo dài"},{"hanzi":"长期","pinyin":"chángqī","vi":"dài hạn"}],"traditional":"長達"},{"id":"长期以来","hanzi":"长期以来","pinyin":"chángqīyǐlái","meaning_vi":"từ lâu nay, suốt một thời gian dài","explanation":"长期 (trường kỳ – thời gian dài) + 以来 (dĩ lai – trở lại đây) → suốt một thời gian dài cho đến nay; thường đứng đầu câu.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"🕰️","examples":[{"type":"basic","zh":"长期以来，他很努力。","pinyin":"Chángqīyǐlái, tā hěn nǔlì.","vi":"Từ lâu nay anh ấy luôn rất cố gắng."},{"type":"simple","zh":"长期以来，这个村子一直缺水。","pinyin":"Chángqīyǐlái, zhè ge cūnzi yìzhí quēshuǐ.","vi":"Suốt thời gian dài, ngôi làng này luôn thiếu nước."},{"type":"compound","zh":"长期以来，虽然他工作很忙，但是每周都会给父母打电话。","pinyin":"Chángqīyǐlái, suīrán tā gōngzuò hěn máng, dànshì měizhōu dōuhuì gěi fùmǔ dǎdiànhuà.","vi":"Từ lâu nay, tuy công việc rất bận nhưng tuần nào anh ấy cũng gọi điện cho bố mẹ."}],"related":[{"hanzi":"一直","pinyin":"yìzhí","vi":"luôn luôn"},{"hanzi":"长久","pinyin":"chángjiǔ","vi":"lâu dài"},{"hanzi":"历来","pinyin":"lìlái","vi":"xưa nay"},{"hanzi":"以来","pinyin":"yǐlái","vi":"từ trước đến nay"}],"traditional":"長期以來"},{"id":"长相","hanzi":"长相","pinyin":"zhǎngxiàng","meaning_vi":"diện mạo, tướng mạo, vẻ ngoài","explanation":"长 (trưởng – lớn lên, mọc ra) + 相 (tướng – dáng vẻ) → dáng vẻ, khuôn mặt bên ngoài của một người.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👤","examples":[{"type":"basic","zh":"他长相很普通。","pinyin":"Tā zhǎngxiàng hěn pǔtōng.","vi":"Anh ấy có vẻ ngoài rất bình thường."},{"type":"simple","zh":"这对双胞胎的长相几乎一模一样。","pinyin":"Zhè duì shuāngbāotāi de zhǎngxiàng jīhū yìmúyíyàng.","vi":"Diện mạo của cặp song sinh này gần như giống hệt nhau."},{"type":"compound","zh":"即使长相不出众，她也凭能力赢得了大家的尊重。","pinyin":"Jíshǐ zhǎngxiàng bù chūzhòng, tā yě píng nénglì yíng déle dàjiā de zūnzhòng.","vi":"Dù ngoại hình không nổi bật, cô ấy vẫn nhờ năng lực mà giành được sự tôn trọng của mọi người."}],"related":[{"hanzi":"相貌","pinyin":"xiàngmào","vi":"tướng mạo"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"vẻ bề ngoài"},{"hanzi":"模样","pinyin":"múyàng","vi":"dáng vẻ"},{"hanzi":"长得","pinyin":"zhǎngde","vi":"trông, có vẻ ngoài"}],"traditional":"長相"},{"id":"长效","hanzi":"长效","pinyin":"chángxiào","meaning_vi":"hiệu quả lâu dài, tác dụng kéo dài","explanation":"长 (trường – dài) + 效 (hiệu – hiệu quả) → có tác dụng trong thời gian dài; hay dùng cho thuốc, cơ chế, biện pháp.","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"这是长效药。","pinyin":"Zhè shì chángxiào yào.","vi":"Đây là thuốc có tác dụng kéo dài."},{"type":"simple","zh":"政府要建立保护环境的长效机制。","pinyin":"Zhèngfǔ yào jiànlì bǎohù huánjìng de chángxiào jīzhì.","vi":"Chính phủ cần xây dựng cơ chế lâu dài để bảo vệ môi trường."},{"type":"compound","zh":"因为这种面霜是长效保湿的，所以一天只需要涂一次。","pinyin":"Yīnwèi zhè zhǒng miànshuāng shì chángxiào bǎoshī de, suǒyǐ yì tiān zhǐ xūyào tú yí cì.","vi":"Vì loại kem này dưỡng ẩm lâu dài nên mỗi ngày chỉ cần bôi một lần."}],"related":[{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu quả"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"长期","pinyin":"chángqī","vi":"lâu dài"},{"hanzi":"短效","pinyin":"duǎnxiào","vi":"tác dụng ngắn"}],"traditional":"長效"},{"id":"长足","hanzi":"长足","pinyin":"chángzú","meaning_vi":"vượt bậc, nhanh chóng (tiến bộ, phát triển)","explanation":"长 (trường – dài) + 足 (túc – bước chân) → bước dài, nghĩa bóng là tiến bộ, phát triển vượt bậc; thường đi với 进步, 发展.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🚀","examples":[{"type":"basic","zh":"他取得了长足进步。","pinyin":"Tā qǔ déle chángzú jìnbù.","vi":"Anh ấy đã tiến bộ vượt bậc."},{"type":"simple","zh":"近十年来，这里的交通有了长足的发展。","pinyin":"Jìn shí niánlái, zhèlǐ de jiāotōng yǒule chángzú de fāzhǎn.","vi":"Mười năm gần đây, giao thông ở đây đã phát triển vượt bậc."},{"type":"compound","zh":"虽然他的中文取得了长足的进步，但是写作还需要加强。","pinyin":"Suīrán tā de Zhōngwén qǔ déle chángzú de jìnbù, dànshì xiězuò hái xūyào jiāqiáng.","vi":"Tuy tiếng Trung của anh ấy đã tiến bộ vượt bậc nhưng kỹ năng viết vẫn cần tăng cường."}],"related":[{"hanzi":"进步","pinyin":"jìnbù","vi":"tiến bộ"},{"hanzi":"显著","pinyin":"xiǎnzhù","vi":"rõ rệt"},{"hanzi":"飞跃","pinyin":"fēiyuè","vi":"bước nhảy vọt"},{"hanzi":"突飞猛进","pinyin":"tūfēiměngjìn","vi":"tiến nhanh vượt bậc"}],"traditional":"長足"},{"id":"掌管","hanzi":"掌管","pinyin":"zhǎngguǎn","meaning_vi":"nắm giữ, quản lý, phụ trách","explanation":"掌 (chưởng – bàn tay, nắm giữ) + 管 (quản – quản lý) → nắm quyền quản lý, chịu trách nhiệm một việc.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🗝️","examples":[{"type":"basic","zh":"妈妈掌管家里的钱。","pinyin":"Māma zhǎngguǎn jiāli de qián.","vi":"Mẹ quản lý tiền trong nhà."},{"type":"simple","zh":"公司的财务由王经理一个人掌管。","pinyin":"Gōngsī de cáiwù yóu Wáng jīnglǐ yígèrén zhǎngguǎn.","vi":"Tài chính của công ty do một mình giám đốc Vương nắm giữ."},{"type":"compound","zh":"自从父亲退休以后，饭店就由哥哥掌管了。","pinyin":"Zìcóng fùqīn tuìxiū yǐhòu, fàndiàn jiù yóu gēge zhǎngguǎn le.","vi":"Từ khi bố nghỉ hưu, nhà hàng do anh trai quản lý."}],"related":[{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"quản lý"},{"hanzi":"主管","pinyin":"zhǔguǎn","vi":"phụ trách"},{"hanzi":"掌握","pinyin":"zhǎngwò","vi":"nắm vững"},{"hanzi":"负责","pinyin":"fùzé","vi":"chịu trách nhiệm"}]},{"id":"帐子","hanzi":"帐子","pinyin":"zhàngzi","meaning_vi":"màn, mùng (chống muỗi)","explanation":"帐 (trướng – màn bằng vải) + 子 (tử – hậu tố) → tấm màn treo quanh giường để chống muỗi.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🛏️","examples":[{"type":"basic","zh":"床上挂着帐子。","pinyin":"Chuáng shang guàzhe zhàngzi.","vi":"Trên giường có mắc màn."},{"type":"simple","zh":"夏天睡觉前，奶奶总要放下帐子。","pinyin":"Xiàtiān shuìjiào qián, nǎinai zǒngyào fàngxià zhàngzi.","vi":"Mùa hè trước khi ngủ, bà luôn buông màn xuống."},{"type":"compound","zh":"如果晚上不挂帐子，就会被蚊子咬得睡不着。","pinyin":"Rúguǒ wǎnshang bú guà zhàngzi, jiù huì bèi wénzi yǎo de shuìbùzháo.","vi":"Nếu buổi tối không mắc màn thì sẽ bị muỗi đốt đến mất ngủ."}],"related":[{"hanzi":"蚊帐","pinyin":"wénzhàng","vi":"màn chống muỗi"},{"hanzi":"帐篷","pinyin":"zhàngpeng","vi":"lều"},{"hanzi":"蚊子","pinyin":"wénzi","vi":"con muỗi"},{"hanzi":"床","pinyin":"chuáng","vi":"giường"}],"traditional":"帳子"},{"id":"胀","hanzi":"胀","pinyin":"zhàng","meaning_vi":"trướng, đầy, phình to, căng tức","explanation":"胀 (trướng – phình lên) → vật thể nở to ra; hoặc cơ thể có cảm giác đầy, căng tức.","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"🎈","examples":[{"type":"basic","zh":"我肚子有点胀。","pinyin":"Wǒ dùzi yǒudiǎn zhàng.","vi":"Bụng tôi hơi đầy."},{"type":"simple","zh":"木门被雨水泡得胀起来，关不上了。","pinyin":"Mù mén bèi yǔ shuǐpào de zhàng qǐlai, guān bú shàng le.","vi":"Cửa gỗ ngấm nước mưa nở ra, không đóng được nữa."},{"type":"compound","zh":"因为晚饭吃得太多，所以他觉得胃胀得难受。","pinyin":"Yīnwèi wǎnfàn chī de tài duō, suǒyǐ tā juéde wèi zhàng de nánshòu.","vi":"Vì bữa tối ăn quá nhiều nên anh ấy thấy dạ dày căng tức khó chịu."}],"related":[{"hanzi":"膨胀","pinyin":"péngzhàng","vi":"giãn nở"},{"hanzi":"肿","pinyin":"zhǒng","vi":"sưng"},{"hanzi":"胀痛","pinyin":"zhàngtòng","vi":"căng đau"},{"hanzi":"缩","pinyin":"suō","vi":"co lại"}],"traditional":"脹"},{"id":"账单","hanzi":"账单","pinyin":"zhàngdān","meaning_vi":"hóa đơn, phiếu thanh toán","explanation":"账 (trướng – sổ sách tiền nong) + 单 (đơn – tờ phiếu) → tờ ghi số tiền phải trả.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"服务员，请拿账单。","pinyin":"Fúwùyuán, qǐng ná zhàngdān.","vi":"Phục vụ ơi, cho xin hóa đơn."},{"type":"simple","zh":"这个月的电费账单比上个月高很多。","pinyin":"Zhè geyuè de diànfèi zhàngdān bǐ shànggèyuè gāo hěn duō.","vi":"Hóa đơn tiền điện tháng này cao hơn tháng trước nhiều."},{"type":"compound","zh":"如果信用卡账单不按时还，就要交利息。","pinyin":"Rúguǒ xìnyòngkǎ zhàngdān bú ànshí huán, jiùyào jiāo lìxī.","vi":"Nếu không trả hóa đơn thẻ tín dụng đúng hạn thì phải trả lãi."}],"related":[{"hanzi":"结账","pinyin":"jiézhàng","vi":"thanh toán"},{"hanzi":"买单","pinyin":"mǎidān","vi":"trả tiền"},{"hanzi":"发票","pinyin":"fāpiào","vi":"hóa đơn đỏ"},{"hanzi":"账户","pinyin":"zhànghù","vi":"tài khoản"}],"traditional":"賬單"},{"id":"账号","hanzi":"账号","pinyin":"zhànghào","meaning_vi":"tài khoản (ngân hàng, mạng), tên đăng nhập","explanation":"账 (trướng – sổ sách) + 号 (hiệu – số) → số tài khoản ngân hàng; nay hay dùng cho tài khoản đăng nhập trên mạng.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🔑","examples":[{"type":"basic","zh":"我忘了账号密码。","pinyin":"Wǒ wàngle zhànghào mìmǎ.","vi":"Tôi quên mật khẩu tài khoản."},{"type":"simple","zh":"请把你的银行账号发给我。","pinyin":"Qǐng bǎ nǐ de yínháng zhànghào fāgěi wǒ.","vi":"Hãy gửi số tài khoản ngân hàng của bạn cho tôi."},{"type":"compound","zh":"如果账号在别的手机上登录，系统就会发短信提醒你。","pinyin":"Rúguǒ zhànghào zài biéde shǒujī shang dēnglù, xìtǒng jiù huì fāduǎnxìn tíxǐng nǐ.","vi":"Nếu tài khoản đăng nhập trên điện thoại khác, hệ thống sẽ gửi tin nhắn nhắc bạn."}],"related":[{"hanzi":"账户","pinyin":"zhànghù","vi":"tài khoản"},{"hanzi":"密码","pinyin":"mìmǎ","vi":"mật khẩu"},{"hanzi":"登录","pinyin":"dēnglù","vi":"đăng nhập"},{"hanzi":"注册","pinyin":"zhùcè","vi":"đăng ký"}],"traditional":"賬號"},{"id":"招标","hanzi":"招标","pinyin":"zhāobiāo","meaning_vi":"mời thầu, gọi thầu","explanation":"招 (chiêu – mời gọi) + 标 (tiêu – gói thầu) → công bố điều kiện để mời các đơn vị tham gia đấu thầu.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📑","examples":[{"type":"basic","zh":"这个项目正在招标。","pinyin":"Zhè ge xiàngmù zhèngzài zhāobiāo.","vi":"Dự án này đang mời thầu."},{"type":"simple","zh":"市政府公开招标修建一座新桥。","pinyin":"Shìzhèngfǔ gōngkāi zhāobiāo xiūjiàn yí zuò xīn qiáo.","vi":"Chính quyền thành phố công khai mời thầu xây một cây cầu mới."},{"type":"compound","zh":"因为这次招标很公平，所以小公司也有机会中标。","pinyin":"Yīnwèi zhè cì zhāobiāo hěn gōngpíng, suǒyǐ xiǎo gōngsī yě yǒujī huì zhòngbiāo.","vi":"Vì lần mời thầu này rất công bằng nên công ty nhỏ cũng có cơ hội trúng thầu."}],"related":[{"hanzi":"投标","pinyin":"tóubiāo","vi":"dự thầu"},{"hanzi":"中标","pinyin":"zhòngbiāo","vi":"trúng thầu"},{"hanzi":"竞标","pinyin":"jìngbiāo","vi":"đấu thầu"},{"hanzi":"项目","pinyin":"xiàngmù","vi":"dự án"}],"traditional":"招標"},{"id":"招待","hanzi":"招待","pinyin":"zhāodài","meaning_vi":"tiếp đãi, chiêu đãi, đón tiếp","explanation":"招 (chiêu – mời) + 待 (đãi – đối đãi) → mời và tiếp đón khách chu đáo.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🍵","examples":[{"type":"basic","zh":"谢谢你的热情招待。","pinyin":"Xièxie nǐ de rèqíng zhāodài.","vi":"Cảm ơn sự tiếp đãi nhiệt tình của bạn."},{"type":"simple","zh":"他用家乡的特产招待远方的朋友。","pinyin":"Tāyòng jiāxiāng de tèchǎn zhāodài yuǎnfāng de péngyou.","vi":"Anh ấy dùng đặc sản quê nhà để tiếp đãi bạn từ xa đến."},{"type":"compound","zh":"如果有招待不周的地方，就请大家多多包涵。","pinyin":"Rúguǒ yǒu zhāodài bùzhōu de dìfang, jiù qǐng dàjiā duōduō bāohan.","vi":"Nếu có chỗ nào tiếp đãi chưa chu đáo, mong mọi người bỏ qua cho."}],"related":[{"hanzi":"接待","pinyin":"jiēdài","vi":"tiếp đón"},{"hanzi":"款待","pinyin":"kuǎndài","vi":"khoản đãi"},{"hanzi":"招待会","pinyin":"zhāodàihuì","vi":"tiệc chiêu đãi"},{"hanzi":"客人","pinyin":"kèrén","vi":"khách"}]},{"id":"招待会","hanzi":"招待会","pinyin":"zhāodàihuì","meaning_vi":"tiệc chiêu đãi, buổi tiếp tân, họp báo","explanation":"招待 (chiêu đãi – tiếp đãi) + 会 (hội – buổi gặp) → buổi tiếp khách chính thức, ví dụ 新闻招待会 là họp báo.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🥂","examples":[{"type":"basic","zh":"晚上有个招待会。","pinyin":"Wǎnshang yǒu gè zhāodàihuì.","vi":"Tối nay có một buổi tiệc chiêu đãi."},{"type":"simple","zh":"大使馆为来访的代表团举行了招待会。","pinyin":"Dàshǐguǎn wèi láifǎng de dàibiǎotuán jǔxíngle zhāodàihuì.","vi":"Đại sứ quán tổ chức tiệc chiêu đãi đoàn đại biểu đến thăm."},{"type":"compound","zh":"因为新产品发布了，所以公司明天要召开新闻招待会。","pinyin":"Yīnwèi xīnchǎnpǐn fābù le, suǒyǐ gōngsī míngtiān yào zhàokāi xīnwén zhāodàihuì.","vi":"Vì sản phẩm mới đã ra mắt nên ngày mai công ty sẽ tổ chức họp báo."}],"related":[{"hanzi":"招待","pinyin":"zhāodài","vi":"tiếp đãi"},{"hanzi":"宴会","pinyin":"yànhuì","vi":"yến tiệc"},{"hanzi":"发布会","pinyin":"fābùhuì","vi":"buổi ra mắt"},{"hanzi":"酒会","pinyin":"jiǔhuì","vi":"tiệc rượu"}],"traditional":"招待會"},{"id":"招募","hanzi":"招募","pinyin":"zhāomù","meaning_vi":"chiêu mộ, tuyển mộ, tuyển dụng","explanation":"招 (chiêu – vẫy gọi) + 募 (mộ – tuyển gom) → kêu gọi, tuyển người tham gia.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📣","examples":[{"type":"basic","zh":"我们在招募志愿者。","pinyin":"Wǒmen zài zhāomù zhìyuànzhě.","vi":"Chúng tôi đang tuyển tình nguyện viên."},{"type":"simple","zh":"这家医院正在招募新药试验的参与者。","pinyin":"Zhè jiā yīyuàn zhèngzài zhāomù xīn yào shìyàn de cānyùzhě.","vi":"Bệnh viện này đang tuyển người tham gia thử nghiệm thuốc mới."},{"type":"compound","zh":"虽然招募信息发出去一周了，但是报名的人很少。","pinyin":"Suīrán zhāomù xìnxī fā chūqu yìzhōu le, dànshì bàomíng de rén hěn shǎo.","vi":"Tuy thông báo tuyển mộ đã đăng được một tuần nhưng rất ít người đăng ký."}],"related":[{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"招收","pinyin":"zhāoshōu","vi":"tuyển nhận"},{"hanzi":"募捐","pinyin":"mùjuān","vi":"quyên góp"},{"hanzi":"志愿者","pinyin":"zhìyuànzhě","vi":"tình nguyện viên"}]},{"id":"招数","hanzi":"招数","pinyin":"zhāoshù","meaning_vi":"chiêu thức, chiêu trò, mánh khóe","explanation":"招 (chiêu – đòn, chiêu thức) + 数 (số – các kiểu) → đòn thế trong võ, nước cờ; nghĩa bóng là cách, mánh khóe.","hsk_level":"7-9","tags":["danh-tu"],"image":"🥋","examples":[{"type":"basic","zh":"这招数真厉害。","pinyin":"Zhè zhāoshù zhēn lìhai.","vi":"Chiêu này thật lợi hại."},{"type":"simple","zh":"骗子的招数越来越多，大家要小心。","pinyin":"Piànzi de zhāoshù yuèláiyuè duō, dàjiā yào xiǎoxīn.","vi":"Chiêu trò của kẻ lừa đảo ngày càng nhiều, mọi người phải cẩn thận."},{"type":"compound","zh":"虽然他用尽了各种招数，但是还是没能说服老板。","pinyin":"Suīrán tā yòngjìnle gèzhǒng zhāoshù, dànshì háishi méi néng shuōfú lǎobǎn.","vi":"Tuy anh ấy đã dùng hết mọi chiêu nhưng vẫn không thuyết phục được sếp."}],"related":[{"hanzi":"花样","pinyin":"huāyàng","vi":"trò, kiểu"},{"hanzi":"手段","pinyin":"shǒuduàn","vi":"thủ đoạn"},{"hanzi":"花招","pinyin":"huāzhāo","vi":"mánh lới"},{"hanzi":"办法","pinyin":"bànfǎ","vi":"cách làm"}],"traditional":"招數"},{"id":"爪子","hanzi":"爪子","pinyin":"zhuǎzi","meaning_vi":"móng vuốt, chân (có móng) của động vật","explanation":"爪 (trảo – móng vuốt) + 子 (tử – hậu tố) → bàn chân có móng của chim thú.","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐾","examples":[{"type":"basic","zh":"小猫伸出爪子。","pinyin":"Xiǎomāo shēnchū zhuǎzi.","vi":"Con mèo con giơ móng vuốt ra."},{"type":"simple","zh":"老鹰用锋利的爪子抓住了一条鱼。","pinyin":"Lǎoyīng yòng fēnglì de zhuǎzi zhuāzhùle yì tiáo yú.","vi":"Con đại bàng dùng móng vuốt sắc nhọn quắp lấy một con cá."},{"type":"compound","zh":"因为小狗的爪子上全是泥，所以把地板踩得很脏。","pinyin":"Yīnwèi xiǎogǒu de zhuǎzi shang quán shì ní, suǒyǐ bǎ dìbǎn cǎi de hěn zāng.","vi":"Vì chân chó con dính đầy bùn nên giẫm bẩn hết sàn nhà."}],"related":[{"hanzi":"鸡爪","pinyin":"jīzhǎo","vi":"chân gà"},{"hanzi":"爪牙","pinyin":"zhǎoyá","vi":"nanh vuốt"},{"hanzi":"抓","pinyin":"zhuā","vi":"cào, bắt"},{"hanzi":"指甲","pinyin":"zhǐjia","vi":"móng tay"}]},{"id":"召集","hanzi":"召集","pinyin":"zhàojí","meaning_vi":"triệu tập, tập hợp","explanation":"召 (triệu – gọi đến) + 集 (tập – tụ họp) → gọi mọi người đến tập trung lại một chỗ.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔔","examples":[{"type":"basic","zh":"校长召集全体老师。","pinyin":"Xiàozhǎng zhàojí quántǐ lǎoshī.","vi":"Hiệu trưởng triệu tập toàn thể giáo viên."},{"type":"simple","zh":"班长召集大家下午三点在操场集合。","pinyin":"Bānzhǎng zhàojí dàjiā xiàwǔ sān diǎn zài cāochǎng jíhé.","vi":"Lớp trưởng tập hợp mọi người ba giờ chiều ở sân trường."},{"type":"compound","zh":"一旦出现紧急情况，经理就会马上召集员工开会。","pinyin":"Yídàn chūxiàn jǐnjí qíngkuàng, jīnglǐ jiù huì mǎshàng zhàojí yuángōng kāihuì.","vi":"Hễ có tình huống khẩn cấp, giám đốc sẽ lập tức triệu tập nhân viên họp."}],"related":[{"hanzi":"召开","pinyin":"zhàokāi","vi":"triệu tập (họp)"},{"hanzi":"集合","pinyin":"jíhé","vi":"tập hợp"},{"hanzi":"号召","pinyin":"hàozhào","vi":"kêu gọi"},{"hanzi":"召集人","pinyin":"zhàojírén","vi":"người triệu tập"}]},{"id":"兆头","hanzi":"兆头","pinyin":"zhàotou","meaning_vi":"điềm, điềm báo","explanation":"兆 (triệu – điềm báo) + 头 (đầu – hậu tố) → dấu hiệu báo trước việc lành hay dữ.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🔮","examples":[{"type":"basic","zh":"这是个好兆头。","pinyin":"Zhè shì gè hǎo zhàotou.","vi":"Đây là một điềm tốt."},{"type":"simple","zh":"老人们认为喜鹊叫是吉祥的兆头。","pinyin":"Lǎo rénmen rènwéi xǐquè jiào shì jíxiáng de zhàotou.","vi":"Người già cho rằng chim khách kêu là điềm lành."},{"type":"compound","zh":"虽然开局不顺被看作坏兆头，但是他们最后还是赢了。","pinyin":"Suīrán kāijú búshùn bèi kànzuò huài zhàotou, dànshì tāmen zuìhòu háishi yíng le.","vi":"Tuy khởi đầu không suôn sẻ bị coi là điềm xấu nhưng cuối cùng họ vẫn thắng."}],"related":[{"hanzi":"征兆","pinyin":"zhēngzhào","vi":"điềm báo"},{"hanzi":"预兆","pinyin":"yùzhào","vi":"dấu hiệu báo trước"},{"hanzi":"迹象","pinyin":"jìxiàng","vi":"dấu hiệu"},{"hanzi":"吉利","pinyin":"jílì","vi":"may mắn"}],"traditional":"兆頭"},{"id":"照办","hanzi":"照办","pinyin":"zhàobàn","meaning_vi":"làm theo, cứ thế mà làm","explanation":"照 (chiếu – theo đúng) + 办 (biện – làm) → làm đúng theo yêu cầu, chỉ thị.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"好，我马上照办。","pinyin":"Hǎo, wǒ mǎshàng zhàobàn.","vi":"Được, tôi làm ngay."},{"type":"simple","zh":"医生让他戒烟，他回家就照办了。","pinyin":"Yīshēng ràng tā jièyān, tā huíjiā jiù zhàobàn le.","vi":"Bác sĩ bảo anh ấy bỏ thuốc lá, về nhà anh ấy làm theo ngay."},{"type":"compound","zh":"只要你的要求合理，我们就一定照办。","pinyin":"Zhǐyào nǐ de yāoqiú hélǐ, wǒmen jiù yídìng zhàobàn.","vi":"Chỉ cần yêu cầu của bạn hợp lý, chúng tôi nhất định sẽ làm theo."}],"related":[{"hanzi":"遵照","pinyin":"zūnzhào","vi":"tuân theo"},{"hanzi":"按照","pinyin":"ànzhào","vi":"theo"},{"hanzi":"执行","pinyin":"zhíxíng","vi":"thi hành"},{"hanzi":"服从","pinyin":"fúcóng","vi":"phục tùng"}],"traditional":"照辦"},{"id":"照例","hanzi":"照例","pinyin":"zhàolì","meaning_vi":"theo lệ thường, như thường lệ","explanation":"照 (chiếu – theo) + 例 (lệ – lệ thường) → theo thói quen, quy lệ như mọi khi.","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"他照例早起跑步。","pinyin":"Tā zhàolì zǎoqǐ pǎobù.","vi":"Như thường lệ, anh ấy dậy sớm chạy bộ."},{"type":"simple","zh":"每年中秋节，全家人照例要一起赏月。","pinyin":"Měinián Zhōngqiūjié, quán jiārén zhàolì yào yìqǐ shǎngyuè.","vi":"Mỗi dịp Trung thu, cả nhà theo lệ cùng nhau ngắm trăng."},{"type":"compound","zh":"虽然今天下着大雨，但是爷爷照例去公园打太极拳。","pinyin":"Suīrán jīntiān xiàzhe dàyǔ, dànshì yéye zhàolì qù gōngyuán dǎ tàijíquán.","vi":"Tuy hôm nay mưa to nhưng ông vẫn ra công viên tập thái cực quyền như thường lệ."}],"related":[{"hanzi":"惯例","pinyin":"guànlì","vi":"thông lệ"},{"hanzi":"照常","pinyin":"zhàocháng","vi":"như thường"},{"hanzi":"往常","pinyin":"wǎngcháng","vi":"thường ngày"},{"hanzi":"例外","pinyin":"lìwài","vi":"ngoại lệ"}]},{"id":"照明","hanzi":"照明","pinyin":"zhàomíng","meaning_vi":"chiếu sáng, ánh sáng (đèn)","explanation":"照 (chiếu – rọi) + 明 (minh – sáng) → dùng đèn rọi cho sáng; hệ thống đèn chiếu sáng.","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"💡","examples":[{"type":"basic","zh":"这里的照明很好。","pinyin":"Zhèlǐ de zhàomíng hěn hǎo.","vi":"Ánh sáng ở đây rất tốt."},{"type":"simple","zh":"停电以后，我们只能用蜡烛照明。","pinyin":"Tíngdiàn yǐhòu, wǒmen zhǐnéng yòng làzhú zhàomíng.","vi":"Sau khi mất điện, chúng tôi chỉ có thể thắp nến để chiếu sáng."},{"type":"compound","zh":"因为地下车库照明不足，所以晚上停车很不方便。","pinyin":"Yīnwèi dìxià chēkù zhàomíng bùzú, suǒyǐ wǎnshang tíngchē hěn bù fāngbiàn.","vi":"Vì hầm để xe thiếu ánh sáng nên buổi tối đỗ xe rất bất tiện."}],"related":[{"hanzi":"灯光","pinyin":"dēngguāng","vi":"ánh đèn"},{"hanzi":"光线","pinyin":"guāngxiàn","vi":"ánh sáng"},{"hanzi":"照亮","pinyin":"zhàoliàng","vi":"soi sáng"},{"hanzi":"路灯","pinyin":"lùdēng","vi":"đèn đường"}]},{"id":"罩","hanzi":"罩","pinyin":"zhào","meaning_vi":"trùm, chụp, phủ; cái chụp, cái lồng","explanation":"罩 (tráo – cái chụp, lồng) → dùng vật che phủ lên trên; cũng chỉ đồ dùng để trùm như 口罩 (khẩu trang), 灯罩 (chụp đèn).","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"⛱️","examples":[{"type":"basic","zh":"把菜用盖子罩上。","pinyin":"Bǎ cài yòng gàizi zhào shang.","vi":"Lấy nắp đậy thức ăn lại."},{"type":"simple","zh":"天色阴沉，整座城市被浓雾罩住了。","pinyin":"Tiānsè yīnchén, zhěng zuò chéngshì bèi nóng wùzhào zhù le.","vi":"Trời u ám, cả thành phố bị sương mù dày đặc bao phủ."},{"type":"compound","zh":"如果出门时不罩一件外套，就很容易着凉。","pinyin":"Rúguǒ chūmén shí bú zhào yí jiàn wàitào, jiù hěn róngyì zháoliáng.","vi":"Nếu ra ngoài mà không khoác thêm áo ngoài thì rất dễ bị cảm lạnh."}],"related":[{"hanzi":"口罩","pinyin":"kǒuzhào","vi":"khẩu trang"},{"hanzi":"笼罩","pinyin":"lǒngzhào","vi":"bao trùm"},{"hanzi":"灯罩","pinyin":"dēngzhào","vi":"chụp đèn"},{"hanzi":"遮","pinyin":"zhē","vi":"che"}]},{"id":"肇事","hanzi":"肇事","pinyin":"zhàoshì","meaning_vi":"gây sự, gây ra tai nạn","explanation":"肇 (triệu – khởi đầu, gây ra) + 事 (sự – sự việc) → gây ra sự cố, tai nạn hoặc rối loạn.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚨","examples":[{"type":"basic","zh":"肇事司机逃跑了。","pinyin":"Zhàoshì sījī táopǎo le.","vi":"Tài xế gây tai nạn đã bỏ chạy."},{"type":"simple","zh":"警察很快找到了这起车祸的肇事者。","pinyin":"Jǐngchá hěn kuài zhǎodàole zhè qǐ chēhuò de zhàoshìzhě.","vi":"Cảnh sát nhanh chóng tìm ra người gây ra vụ tai nạn xe này."},{"type":"compound","zh":"如果肇事后逃离现场，就要承担更重的法律责任。","pinyin":"Rúguǒ zhàoshì hòu táolí xiànchǎng, jiùyào chéngdān gèng zhòng de fǎlǜ zérèn.","vi":"Nếu gây tai nạn rồi bỏ trốn khỏi hiện trường thì phải chịu trách nhiệm pháp lý nặng hơn."}],"related":[{"hanzi":"闹事","pinyin":"nàoshì","vi":"gây rối"},{"hanzi":"事故","pinyin":"shìgù","vi":"sự cố"},{"hanzi":"车祸","pinyin":"chēhuò","vi":"tai nạn xe"},{"hanzi":"逃逸","pinyin":"táoyì","vi":"bỏ trốn"}]},{"id":"遮","hanzi":"遮","pinyin":"zhē","meaning_vi":"che, che khuất, che giấu","explanation":"遮 (già – che chắn) → dùng vật chắn lại cho khỏi lộ ra hoặc khỏi bị chiếu vào.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌂","examples":[{"type":"basic","zh":"她用手遮住眼睛。","pinyin":"Tā yòng shǒu zhēzhù yǎnjing.","vi":"Cô ấy lấy tay che mắt."},{"type":"simple","zh":"高楼把我们家的阳光全遮住了。","pinyin":"Gāolóu bǎ wǒmen jiā de yángguāng quán zhēzhù le.","vi":"Tòa nhà cao che hết ánh nắng của nhà chúng tôi."},{"type":"compound","zh":"虽然他想用笑容遮住心里的难过，但是大家都看出来了。","pinyin":"Suīrán tā xiǎng yòng xiàoróng zhēzhù xīnli de nánguò, dànshì dàjiā dōu kàn chūlai le.","vi":"Tuy anh ấy muốn dùng nụ cười che giấu nỗi buồn nhưng mọi người đều nhận ra."}],"related":[{"hanzi":"遮盖","pinyin":"zhēgài","vi":"che đậy"},{"hanzi":"遮挡","pinyin":"zhēdǎng","vi":"che chắn"},{"hanzi":"挡","pinyin":"dǎng","vi":"chắn"},{"hanzi":"遮阳伞","pinyin":"zhēyángsǎn","vi":"ô che nắng"}]},{"id":"遮盖","hanzi":"遮盖","pinyin":"zhēgài","meaning_vi":"che phủ, che đậy, giấu giếm","explanation":"遮 (già – che) + 盖 (cái – đậy) → phủ lên trên cho khuất; nghĩa bóng là che giấu sai lầm, sự thật.","hsk_level":"7-9","tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"大雪遮盖了道路。","pinyin":"Dàxuě zhēgàile dàolù.","vi":"Tuyết lớn phủ kín con đường."},{"type":"simple","zh":"他想遮盖自己的错误，结果越弄越糟。","pinyin":"Tā xiǎng zhēgài zìjǐ de cuòwù, jiéguǒ yuè nòng yuè zāo.","vi":"Anh ta muốn che giấu lỗi của mình, kết quả càng làm càng tệ."},{"type":"compound","zh":"即使你想遮盖事实，真相也迟早会被发现。","pinyin":"Jíshǐ nǐ xiǎng zhēgài shìshí, zhēnxiàng yě chízǎo huì bèi fāxiàn.","vi":"Dù bạn muốn che đậy sự thật thì sớm muộn chân tướng cũng bị phát hiện."}],"related":[{"hanzi":"掩盖","pinyin":"yǎngài","vi":"che giấu"},{"hanzi":"遮掩","pinyin":"zhēyǎn","vi":"che lấp"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"giấu giếm"},{"hanzi":"覆盖","pinyin":"fùgài","vi":"bao phủ"}],"traditional":"遮蓋"},{"id":"折叠","hanzi":"折叠","pinyin":"zhédié","meaning_vi":"gấp, gập; (loại) gấp được","explanation":"折 (chiết – bẻ gập) + 叠 (điệp – chồng lên) → gập vật lại cho chồng lên nhau; đồ có thể gấp gọn.","hsk_level":"7-9","tags":["dong-tu","do-vat"],"image":"🪑","examples":[{"type":"basic","zh":"这是一把折叠椅。","pinyin":"Zhè shì yì bǎ zhédiéyǐ.","vi":"Đây là một chiếc ghế gấp."},{"type":"simple","zh":"她把洗好的衣服折叠整齐放进衣柜。","pinyin":"Tā bǎ xǐ hǎo de yīfu zhédié zhěngqí fàngjìn yīguì.","vi":"Cô ấy gấp quần áo đã giặt gọn gàng rồi cất vào tủ."},{"type":"compound","zh":"因为这辆自行车可以折叠，所以带上地铁很方便。","pinyin":"Yīnwèi zhè liàng zìxíngchē kěyǐ zhédié, suǒyǐ dàishàng dìtiě hěn fāngbiàn.","vi":"Vì chiếc xe đạp này gấp được nên mang lên tàu điện ngầm rất tiện."}],"related":[{"hanzi":"折","pinyin":"zhé","vi":"gấp, bẻ"},{"hanzi":"叠","pinyin":"dié","vi":"xếp chồng"},{"hanzi":"展开","pinyin":"zhǎnkāi","vi":"mở ra"},{"hanzi":"折叠伞","pinyin":"zhédiésǎn","vi":"ô gấp"}],"traditional":"折疊"},{"id":"折合","hanzi":"折合","pinyin":"zhéhé","meaning_vi":"quy đổi, tính ra, tương đương với","explanation":"折 (chiết – quy đổi) + 合 (hợp – khớp vào) → đổi từ đơn vị này sang đơn vị khác cho tương đương.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💱","examples":[{"type":"basic","zh":"一百美元折合多少人民币？","pinyin":"Yī bǎi měiyuán zhéhé duōshao rénmínbì?","vi":"Một trăm đô la đổi ra được bao nhiêu nhân dân tệ?"},{"type":"simple","zh":"这台电脑的价格折合人民币大约五千元。","pinyin":"Zhè tái diànnǎo de jiàgé zhéhé rénmínbì dàyuē wǔ qiān yuán.","vi":"Giá chiếc máy tính này quy ra khoảng năm nghìn nhân dân tệ."},{"type":"compound","zh":"虽然这份工资折合成越南盾看起来很多，但是当地物价也很高。","pinyin":"Suīrán zhè fèn gōngzī zhé héchéng Yuènándùn kànqǐlai hěn duō, dànshì dāngdì wùjià yě hěn gāo.","vi":"Tuy mức lương này quy ra tiền Việt trông rất nhiều nhưng vật giá ở đó cũng rất cao."}],"related":[{"hanzi":"换算","pinyin":"huànsuàn","vi":"quy đổi"},{"hanzi":"相当于","pinyin":"xiāngdāngyú","vi":"tương đương với"},{"hanzi":"汇率","pinyin":"huìlǜ","vi":"tỷ giá"},{"hanzi":"兑换","pinyin":"duìhuàn","vi":"đổi tiền"}]},{"id":"折扣","hanzi":"折扣","pinyin":"zhékòu","meaning_vi":"chiết khấu, sự giảm giá","explanation":"折 (chiết – giảm bớt) + 扣 (khấu – trừ đi) → phần giá được giảm bớt so với giá gốc.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这件衣服有折扣吗？","pinyin":"Zhè jiàn yīfu yǒu zhékòu ma?","vi":"Bộ quần áo này có giảm giá không?"},{"type":"simple","zh":"会员在这家超市购物可以享受折扣。","pinyin":"Huìyuán zài zhè jiā chāoshì gòuwù kěyǐ xiǎngshòu zhékòu.","vi":"Hội viên mua sắm ở siêu thị này được hưởng chiết khấu."},{"type":"compound","zh":"如果一次买三件以上，商店就会给你更大的折扣。","pinyin":"Rúguǒ yí cì mǎi sān jiàn yǐshàng, shāngdiàn jiù huì gěi nǐ gèng dà de zhékòu.","vi":"Nếu mua một lần từ ba món trở lên thì cửa hàng sẽ giảm giá nhiều hơn cho bạn."}],"related":[{"hanzi":"打折","pinyin":"dǎzhé","vi":"giảm giá"},{"hanzi":"优惠","pinyin":"yōuhuì","vi":"ưu đãi"},{"hanzi":"降价","pinyin":"jiàngjià","vi":"hạ giá"},{"hanzi":"原价","pinyin":"yuánjià","vi":"giá gốc"}]},{"id":"这会儿","hanzi":"这会儿","pinyin":"zhèhuìr","meaning_vi":"lúc này, bây giờ, giờ phút này","explanation":"这 (giá – này) + 会儿 (hội – một lúc) → khẩu ngữ, chỉ thời điểm hiện tại hoặc lúc đang nói đến.","hsk_level":"7-9","tags":["dai-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"这会儿他在开会。","pinyin":"Zhèhuìr tā zài kāihuì.","vi":"Lúc này anh ấy đang họp."},{"type":"simple","zh":"都这会儿了，你怎么还没吃饭？","pinyin":"Dōu zhèhuìr le, nǐ zěnme hái méi chīfàn?","vi":"Đã giờ này rồi, sao bạn vẫn chưa ăn cơm?"},{"type":"compound","zh":"刚才还下着大雨，这会儿太阳就出来了。","pinyin":"Gāngcái hái xiàzhe dàyǔ, zhèhuìr tàiyáng jiù chūlai le.","vi":"Vừa nãy còn mưa to, giờ thì mặt trời đã ló ra rồi."}],"related":[{"hanzi":"现在","pinyin":"xiànzài","vi":"bây giờ"},{"hanzi":"此刻","pinyin":"cǐkè","vi":"lúc này"},{"hanzi":"那时","pinyin":"nàshí","vi":"lúc đó"},{"hanzi":"刚才","pinyin":"gāngcái","vi":"vừa nãy"}],"traditional":"這會兒"},{"id":"这样一来","hanzi":"这样一来","pinyin":"zhèyàngyìlái","meaning_vi":"như vậy thì, làm như thế thì","explanation":"这样 (giá dạng – như thế) + 一来 (nhất lai – một khi đến) → nếu (đã) như vậy thì; dùng để nối kết quả của việc vừa nói.","hsk_level":"7-9","tags":["lien-tu"],"image":"➡️","examples":[{"type":"basic","zh":"这样一来，就简单了。","pinyin":"Zhèyàngyìlái, jiù jiǎndān le.","vi":"Như vậy thì đơn giản rồi."},{"type":"simple","zh":"公司搬到了市中心，这样一来上班方便多了。","pinyin":"Gōngsī bān dàole shìzhōngxīn, zhèyàngyìlái shàngbān fāngbiàn duō le.","vi":"Công ty chuyển về trung tâm thành phố, như vậy đi làm tiện hơn nhiều."},{"type":"compound","zh":"他每天坚持早睡早起，这样一来，精神就比以前好多了。","pinyin":"Tā měitiān jiānchí zǎo shuì zǎoqǐ, zhèyàngyìlái, jīngshen jiù bǐ yǐqián hǎoduō le.","vi":"Anh ấy kiên trì ngủ sớm dậy sớm mỗi ngày, như vậy tinh thần tốt hơn trước nhiều."}],"related":[{"hanzi":"这样","pinyin":"zhèyàng","vi":"như thế"},{"hanzi":"因此","pinyin":"yīncǐ","vi":"vì vậy"},{"hanzi":"于是","pinyin":"yúshì","vi":"thế là"},{"hanzi":"如此一来","pinyin":"rúcǐyìlái","vi":"như thế thì"}],"traditional":"這樣一來"},{"id":"着力","hanzi":"着力","pinyin":"zhuólì","meaning_vi":"dồn sức, ra sức, tập trung sức lực","explanation":"着 (trước – đặt vào) + 力 (lực – sức) → đặt sức lực vào một việc, tập trung nỗ lực.","hsk_level":"7-9","tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"我们要着力解决问题。","pinyin":"Wǒmen yào zhuólì jiějué wèntí.","vi":"Chúng ta phải dồn sức giải quyết vấn đề."},{"type":"simple","zh":"政府正在着力改善农村的医疗条件。","pinyin":"Zhèngfǔ zhèngzài zhuólì gǎishàn nóngcūn de yīliáo tiáojiàn.","vi":"Chính phủ đang ra sức cải thiện điều kiện y tế ở nông thôn."},{"type":"compound","zh":"因为学生的口语比较弱，所以老师这学期着力训练听说能力。","pinyin":"Yīnwèi xuésheng de kǒuyǔ bǐjiào ruò, suǒyǐ lǎoshī zhè xuéqī zhuólì xùnliàn tīngshuō nénglì.","vi":"Vì khẩu ngữ của học sinh khá yếu nên học kỳ này thầy giáo tập trung rèn kỹ năng nghe nói."}],"related":[{"hanzi":"努力","pinyin":"nǔlì","vi":"cố gắng"},{"hanzi":"致力","pinyin":"zhìlì","vi":"dốc sức"},{"hanzi":"着重","pinyin":"zhuózhòng","vi":"chú trọng"},{"hanzi":"用力","pinyin":"yònglì","vi":"dùng sức"}],"traditional":"著力"},{"id":"着落","hanzi":"着落","pinyin":"zhuóluò","meaning_vi":"kết quả, tin tức; chỗ dựa, nơi nương tựa; nguồn (tiền)","explanation":"着 (trước – bám vào) + 落 (lạc – rơi xuống, dừng lại) → chỗ có thể dựa vào, nơi rơi về; chỉ việc đã có kết quả, có nguồn chắc chắn.","hsk_level":"7-9","tags":["danh-tu"],"image":"📍","examples":[{"type":"basic","zh":"钱还没有着落。","pinyin":"Qián hái méiyǒu zhuóluò.","vi":"Tiền vẫn chưa có nguồn."},{"type":"simple","zh":"丢失的钱包到现在还没有着落。","pinyin":"Diūshī de qiánbāo dàoxiànzài hái méiyǒu zhuóluò.","vi":"Chiếc ví bị mất đến giờ vẫn chưa có tin tức gì."},{"type":"compound","zh":"一旦工作有了着落，他就打算把父母接到城里。","pinyin":"Yídàn gōngzuò yǒule zhuóluò, tā jiù dǎsuàn bǎ fùmǔ jiēdào chéngli.","vi":"Một khi công việc đã ổn định, anh ấy định đón bố mẹ lên thành phố."}],"related":[{"hanzi":"下落","pinyin":"xiàluò","vi":"tung tích"},{"hanzi":"落实","pinyin":"luòshí","vi":"thực hiện chắc chắn"},{"hanzi":"着陆","pinyin":"zhuólù","vi":"hạ cánh"},{"hanzi":"归宿","pinyin":"guīsù","vi":"nơi chốn trở về"}],"traditional":"著落"},{"id":"着实","hanzi":"着实","pinyin":"zhuóshí","meaning_vi":"quả thực, thật sự, thật là","explanation":"着 (trước – chạm đến) + 实 (thực – thật) → thật sự, đúng là; nhấn mạnh mức độ.","hsk_level":"7-9","tags":["pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"这件事着实不容易。","pinyin":"Zhè jiàn shì zhuóshí bù róngyì.","vi":"Việc này quả thực không dễ."},{"type":"simple","zh":"听到这个消息，大家着实吃了一惊。","pinyin":"Tīngdào zhè ge xiāoxi, dàjiā zhuóshí chīle yì jīng.","vi":"Nghe tin này, mọi người thật sự giật mình."},{"type":"compound","zh":"虽然只是一场小比赛，但是他的表现着实让人佩服。","pinyin":"Suīrán zhǐshì yì chǎng xiǎo bǐsài, dànshì tā de biǎoxiàn zhuóshí ràng rén pèifú.","vi":"Tuy chỉ là trận đấu nhỏ nhưng màn thể hiện của anh ấy thật khiến người ta khâm phục."}],"related":[{"hanzi":"确实","pinyin":"quèshí","vi":"đích thực"},{"hanzi":"实在","pinyin":"shízài","vi":"thật sự"},{"hanzi":"的确","pinyin":"díquè","vi":"quả thật"},{"hanzi":"真是","pinyin":"zhēnshì","vi":"thật là"}],"traditional":"著實"},{"id":"着眼于","hanzi":"着眼于","pinyin":"zhuóyǎnyú","meaning_vi":"nhìn vào, chú trọng vào, xuất phát từ","explanation":"着眼 (trước nhãn – đặt mắt nhìn vào) + 于 (ư – vào) → lấy điều gì làm điểm nhìn, mục tiêu khi suy xét, hành động.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"我们要着眼于未来。","pinyin":"Wǒmen yào zhuóyǎnyú wèilái.","vi":"Chúng ta phải nhìn về tương lai."},{"type":"simple","zh":"这项政策主要着眼于改善居民的生活。","pinyin":"Zhè xiàng zhèngcè zhǔyào zhuóyǎnyú gǎishàn jūmín de shēnghuó.","vi":"Chính sách này chủ yếu chú trọng cải thiện đời sống người dân."},{"type":"compound","zh":"如果只着眼于眼前利益，企业就很难长期发展。","pinyin":"Rúguǒ zhǐ zhuóyǎnyú yǎnqián lìyì, qǐyè jiù hěn nán chángqī fāzhǎn.","vi":"Nếu chỉ chăm chăm vào lợi ích trước mắt thì doanh nghiệp rất khó phát triển lâu dài."}],"related":[{"hanzi":"着眼","pinyin":"zhuóyǎn","vi":"nhìn vào"},{"hanzi":"着重","pinyin":"zhuózhòng","vi":"chú trọng"},{"hanzi":"立足于","pinyin":"lìzúyú","vi":"đứng trên cơ sở"},{"hanzi":"关注","pinyin":"guānzhù","vi":"quan tâm"}],"traditional":"著眼於"},{"id":"针锋相对","hanzi":"针锋相对","pinyin":"zhēnfēng-xiāngduì","meaning_vi":"ăn miếng trả miếng, đối chọi gay gắt","explanation":"针锋 (châm phong – mũi kim) + 相对 (tương đối – chĩa vào nhau) → mũi kim chĩa vào mũi kim; nghĩa bóng là hai bên đối đáp, đấu nhau gay gắt không nhường.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"⚔️","examples":[{"type":"basic","zh":"双方针锋相对。","pinyin":"Shuāngfāng zhēnfēngxiāngduì.","vi":"Hai bên đối chọi gay gắt."},{"type":"simple","zh":"会上两位专家的观点针锋相对，谁也不让谁。","pinyin":"Huì shang liǎng wèi zhuānjiā de guāndiǎn zhēnfēngxiāngduì, shéi yě bú ràng shéi.","vi":"Tại cuộc họp, quan điểm của hai chuyên gia đối chọi gay gắt, không ai nhường ai."},{"type":"compound","zh":"虽然他们在辩论时针锋相对，但是私下里是好朋友。","pinyin":"Suīrán tāmen zài biànlùn shí zhēnfēngxiāngduì, dànshì sīxià li shì hǎopéngyou.","vi":"Tuy khi tranh luận họ ăn miếng trả miếng nhưng ngoài đời lại là bạn thân."}],"related":[{"hanzi":"针尖对麦芒","pinyin":"zhēn jiān duì mài máng","vi":"kẻ tám lạng người nửa cân"},{"hanzi":"以牙还牙","pinyin":"yǐyáhuányá","vi":"ăn miếng trả miếng"},{"hanzi":"争锋","pinyin":"zhēngfēng","vi":"tranh hùng"},{"hanzi":"对立","pinyin":"duìlì","vi":"đối lập"}],"traditional":"針鋒相對"},{"id":"珍重","hanzi":"珍重","pinyin":"zhēnzhòng","meaning_vi":"bảo trọng; quý trọng, trân trọng","explanation":"珍 (trân – quý) + 重 (trọng – coi trọng) → coi trọng, giữ gìn; lời chúc khi chia tay: \"hãy bảo trọng\".","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"请多多珍重！","pinyin":"Qǐng duōduō zhēnzhòng!","vi":"Xin hãy giữ gìn sức khỏe!"},{"type":"simple","zh":"我们要珍重这段来之不易的友谊。","pinyin":"Wǒmen yào zhēnzhòng zhè duàn láizhībúyì de yǒuyì.","vi":"Chúng ta phải trân trọng tình bạn có được không dễ dàng này."},{"type":"compound","zh":"虽然我们以后很难见面了，但是希望你一路珍重。","pinyin":"Suīrán wǒmen yǐhòu hěn nán jiànmiàn le, dànshì xīwàng nǐ yílù zhēnzhòng.","vi":"Tuy sau này chúng ta khó gặp lại, nhưng mong bạn đi đường bảo trọng."}],"related":[{"hanzi":"保重","pinyin":"bǎozhòng","vi":"bảo trọng"},{"hanzi":"珍惜","pinyin":"zhēnxī","vi":"trân trọng"},{"hanzi":"珍贵","pinyin":"zhēnguì","vi":"quý giá"},{"hanzi":"爱惜","pinyin":"àixī","vi":"quý tiếc"}]},{"id":"真假","hanzi":"真假","pinyin":"zhēnjiǎ","meaning_vi":"thật giả, thật hay giả","explanation":"真 (chân – thật) + 假 (giả – giả) → sự thật hay giả dối; thường dùng trong 辨别真假 (phân biệt thật giả).","hsk_level":"7-9","tags":["danh-tu"],"image":"🎭","examples":[{"type":"basic","zh":"我分不清真假。","pinyin":"Wǒ fēn bùqīng zhēnjiǎ.","vi":"Tôi không phân biệt được thật giả."},{"type":"simple","zh":"这个消息的真假还需要进一步核实。","pinyin":"Zhè ge xiāoxi de zhēnjiǎ hái xūyào jìnyíbù héshí.","vi":"Tin này thật hay giả còn cần xác minh thêm."},{"type":"compound","zh":"因为两幅画画得太像了，所以连专家也难辨真假。","pinyin":"Yīnwèi liǎng fú huàhuà de tài xiàng le, suǒyǐ lián zhuānjiā yě nán biàn zhēnjiǎ.","vi":"Vì hai bức tranh vẽ quá giống nhau nên ngay cả chuyên gia cũng khó phân biệt thật giả."}],"related":[{"hanzi":"真伪","pinyin":"zhēnwěi","vi":"thật giả"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thực"},{"hanzi":"假冒","pinyin":"jiǎmào","vi":"giả mạo"},{"hanzi":"辨别","pinyin":"biànbié","vi":"phân biệt"}]},{"id":"真空","hanzi":"真空","pinyin":"zhēnkōng","meaning_vi":"chân không; khoảng trống","explanation":"真 (chân – thật sự) + 空 (không – trống rỗng) → khoảng không hoàn toàn không có không khí; nghĩa bóng là khoảng trống.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🫙","examples":[{"type":"basic","zh":"太空接近真空。","pinyin":"Tàikōng jiējìn zhēnkōng.","vi":"Vũ trụ gần như là chân không."},{"type":"simple","zh":"这些食品都采用了真空包装。","pinyin":"Zhèxiē shípǐn dōu cǎiyòngle zhēnkōng bāozhuāng.","vi":"Những thực phẩm này đều được đóng gói chân không."},{"type":"compound","zh":"因为声音不能在真空中传播，所以宇航员在太空要用无线电说话。","pinyin":"Yīnwèi shēngyīn bù néng zài zhēnkōng zhōng chuánbō, suǒyǐ yǔhángyuán zài tàikōng yào yòng wúxiàndiàn shuōhuà.","vi":"Vì âm thanh không truyền được trong chân không nên phi hành gia trên vũ trụ phải nói chuyện bằng vô tuyến."}],"related":[{"hanzi":"空气","pinyin":"kōngqì","vi":"không khí"},{"hanzi":"真空泵","pinyin":"zhēnkōngbèng","vi":"máy bơm chân không"},{"hanzi":"空白","pinyin":"kòngbái","vi":"chỗ trống"},{"hanzi":"太空","pinyin":"tàikōng","vi":"vũ trụ"}]},{"id":"真情","hanzi":"真情","pinyin":"zhēnqíng","meaning_vi":"tình cảm chân thật; sự thật, tình hình thật","explanation":"真 (chân – thật) + 情 (tình – tình cảm, tình hình) → tình cảm xuất phát từ đáy lòng; cũng chỉ tình hình thực tế.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"这首歌充满真情。","pinyin":"Zhè shǒu gē chōngmǎn zhēnqíng.","vi":"Bài hát này tràn đầy tình cảm chân thành."},{"type":"simple","zh":"喝醉以后，他终于说出了心里的真情。","pinyin":"Hēzuì yǐhòu, tā zhōngyú shuōchūle xīnli de zhēnqíng.","vi":"Sau khi say, cuối cùng anh ấy đã nói ra tình cảm thật trong lòng."},{"type":"compound","zh":"虽然这封信写得很简单，但是字里行间流露着真情。","pinyin":"Suīrán zhè fēng xìn xiě de hěn jiǎndān, dànshì zì lǐ hángjiān liúlùzhe zhēnqíng.","vi":"Tuy lá thư viết rất đơn giản nhưng từng câu chữ đều toát lên tình cảm chân thành."}],"related":[{"hanzi":"真心","pinyin":"zhēnxīn","vi":"thật lòng"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"},{"hanzi":"真相","pinyin":"zhēnxiàng","vi":"chân tướng"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"}]},{"id":"真是的","hanzi":"真是的","pinyin":"zhēnshide","meaning_vi":"thật là! (than phiền, bực bội)","explanation":"真是 (chân thị – thật là) + 的 (đích – trợ từ) → câu cảm thán khẩu ngữ, bày tỏ sự bực mình, không hài lòng.","hsk_level":"7-9","tags":["tro-tu","giao-tiep"],"image":"😤","examples":[{"type":"basic","zh":"你真是的，又迟到！","pinyin":"Nǐ zhēnshide, yòu chídào!","vi":"Bạn thật là, lại đến muộn!"},{"type":"simple","zh":"真是的，出门又忘了带钥匙。","pinyin":"Zhēnshide, chūmén yòu wàngle dài yàoshi.","vi":"Thật là, ra ngoài lại quên mang chìa khóa."},{"type":"compound","zh":"你也真是的，既然身体不舒服，就应该早点告诉我。","pinyin":"Nǐ yě zhēnshide, jìrán shēntǐ bù shūfu, jiù yīnggāi zǎodiǎn gàosu wǒ.","vi":"Bạn cũng thật là, đã thấy trong người không khỏe thì phải nói với tôi sớm chứ."}],"related":[{"hanzi":"真是","pinyin":"zhēnshì","vi":"thật là"},{"hanzi":"讨厌","pinyin":"tǎoyàn","vi":"đáng ghét"},{"hanzi":"怎么搞的","pinyin":"zěnmegǎode","vi":"sao lại thế"},{"hanzi":"烦","pinyin":"fán","vi":"bực mình"}]},{"id":"真心","hanzi":"真心","pinyin":"zhēnxīn","meaning_vi":"thật lòng, chân thành, tấm lòng thật","explanation":"真 (chân – thật) + 心 (tâm – lòng) → tấm lòng thật, xuất phát từ trái tim; cũng làm trạng ngữ \"thật lòng\".","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💗","examples":[{"type":"basic","zh":"我是真心喜欢你。","pinyin":"Wǒ shì zhēnxīn xǐhuan nǐ.","vi":"Anh thật lòng thích em."},{"type":"simple","zh":"她真心感谢那位帮助过她的陌生人。","pinyin":"Tā zhēnxīn gǎnxiè nà wèi bāngzhùguo tā de mòshēngrén.","vi":"Cô ấy thật lòng cảm ơn người lạ từng giúp đỡ mình."},{"type":"compound","zh":"只要你真心对待别人，别人就会真心对待你。","pinyin":"Zhǐyào nǐ zhēnxīn duìdài biérén, biérén jiù huì zhēnxīn duìdài nǐ.","vi":"Chỉ cần bạn đối xử thật lòng với người khác thì người khác cũng sẽ thật lòng với bạn."}],"related":[{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"诚心","pinyin":"chéngxīn","vi":"thành tâm"},{"hanzi":"真情","pinyin":"zhēnqíng","vi":"chân tình"},{"hanzi":"假意","pinyin":"jiǎyì","vi":"giả dối"}]},{"id":"诊所","hanzi":"诊所","pinyin":"zhěnsuǒ","meaning_vi":"phòng khám, phòng mạch","explanation":"诊 (chẩn – khám bệnh) + 所 (sở – nơi chốn) → nơi khám chữa bệnh nhỏ, thường là tư nhân.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"楼下有家诊所。","pinyin":"Lóuxià yǒu jiā zhěnsuǒ.","vi":"Dưới tầng có một phòng khám."},{"type":"simple","zh":"他在小区附近开了一家牙科诊所。","pinyin":"Tā zài xiǎoqū fùjìn kāile yìjiā yákē zhěnsuǒ.","vi":"Anh ấy mở một phòng khám nha khoa gần khu dân cư."},{"type":"compound","zh":"如果只是小感冒，就去附近的诊所看看吧。","pinyin":"Rúguǒ zhǐshì xiǎo gǎnmào, jiù qù fùjìn de zhěnsuǒ kànkan ba.","vi":"Nếu chỉ là cảm nhẹ thì cứ đến phòng khám gần đây khám thử."}],"related":[{"hanzi":"医院","pinyin":"yīyuàn","vi":"bệnh viện"},{"hanzi":"门诊","pinyin":"ménzhěn","vi":"khám ngoại trú"},{"hanzi":"诊断","pinyin":"zhěnduàn","vi":"chẩn đoán"},{"hanzi":"医生","pinyin":"yīshēng","vi":"bác sĩ"}],"traditional":"診所"},{"id":"振作","hanzi":"振作","pinyin":"zhènzuò","meaning_vi":"phấn chấn lên, vực dậy tinh thần","explanation":"振 (chấn – rung lên, vực dậy) + 作 (tác – dấy lên) → làm cho tinh thần hăng hái trở lại.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🌅","examples":[{"type":"basic","zh":"你要振作起来！","pinyin":"Nǐ yào zhènzuò qǐlai!","vi":"Bạn phải vực dậy tinh thần!"},{"type":"simple","zh":"失败以后，他很快就振作了精神。","pinyin":"Shībài yǐhòu, tā hěn kuài jiù zhènzuòle jīngshen.","vi":"Sau thất bại, anh ấy nhanh chóng lấy lại tinh thần."},{"type":"compound","zh":"虽然这次考试没考好，但是你一定要振作起来。","pinyin":"Suīrán zhè cì kǎoshì méi kǎo hǎo, dànshì nǐ yídìngyào zhènzuò qǐlai.","vi":"Tuy lần thi này làm không tốt nhưng bạn nhất định phải phấn chấn lên."}],"related":[{"hanzi":"振奋","pinyin":"zhènfèn","vi":"phấn khởi"},{"hanzi":"打起精神","pinyin":"dǎqǐjīngshen","vi":"lấy lại tinh thần"},{"hanzi":"消沉","pinyin":"xiāochén","vi":"suy sụp"},{"hanzi":"鼓舞","pinyin":"gǔwǔ","vi":"cổ vũ"}]},{"id":"震","hanzi":"震","pinyin":"zhèn","meaning_vi":"rung, chấn động, làm rung chuyển","explanation":"震 (chấn – sấm sét, rung động) → rung mạnh, làm rung chuyển; cũng chỉ động đất.","hsk_level":"7-9","tags":["dong-tu"],"image":"📳","examples":[{"type":"basic","zh":"雷声震得窗户响。","pinyin":"Léishēng zhèn de chuānghu xiǎng.","vi":"Tiếng sấm làm cửa sổ rung lên."},{"type":"simple","zh":"大卡车开过去，桌上的杯子都被震倒了。","pinyin":"Dà kǎchē kāi guòqu, zhuō shang de bēizi dōu bèi zhèn dǎo le.","vi":"Xe tải lớn chạy qua, cốc trên bàn đều bị rung đổ."},{"type":"compound","zh":"因为音乐开得太响，所以楼下的邻居被震得睡不着。","pinyin":"Yīnwèi yīnyuè kāi de tài xiǎng, suǒyǐ lóuxià de línjū bèi zhèn de shuìbùzháo.","vi":"Vì mở nhạc quá to nên hàng xóm tầng dưới bị rung đến mất ngủ."}],"related":[{"hanzi":"地震","pinyin":"dìzhèn","vi":"động đất"},{"hanzi":"震动","pinyin":"zhèndòng","vi":"rung động"},{"hanzi":"震惊","pinyin":"zhènjīng","vi":"kinh ngạc"},{"hanzi":"震耳欲聋","pinyin":"zhèn'ěryùlóng","vi":"đinh tai nhức óc"}]},{"id":"震动","hanzi":"震动","pinyin":"zhèndòng","meaning_vi":"rung động, chấn động, gây chấn động","explanation":"震 (chấn – rung) + 动 (động – chuyển động) → vật rung lên; nghĩa bóng là gây ảnh hưởng mạnh tới lòng người, xã hội.","hsk_level":"7-9","tags":["dong-tu"],"image":"🫨","examples":[{"type":"basic","zh":"手机在桌上震动。","pinyin":"Shǒujī zài zhuō shang zhèndòng.","vi":"Điện thoại rung trên bàn."},{"type":"simple","zh":"这条新闻震动了整个城市。","pinyin":"Zhè tiáo xīnwén zhèndòngle zhěnggè chéngshì.","vi":"Tin tức này làm chấn động cả thành phố."},{"type":"compound","zh":"因为附近在建地铁，所以我们家的墙经常有震动。","pinyin":"Yīnwèi fùjìn zài jiàn dìtiě, suǒyǐ wǒmen jiā de qiáng jīngcháng yǒu zhèndòng.","vi":"Vì gần đây đang xây tàu điện ngầm nên tường nhà chúng tôi thường bị rung."}],"related":[{"hanzi":"振动","pinyin":"zhèndòng","vi":"dao động"},{"hanzi":"震","pinyin":"zhèn","vi":"rung"},{"hanzi":"震撼","pinyin":"zhènhàn","vi":"rung động mạnh"},{"hanzi":"晃动","pinyin":"huàngdòng","vi":"lắc lư"}],"traditional":"震動"},{"id":"争吵","hanzi":"争吵","pinyin":"zhēngchǎo","meaning_vi":"cãi nhau, cãi vã, tranh cãi","explanation":"争 (tranh – giành) + 吵 (sảo – ồn ào, cãi) → lớn tiếng cãi nhau vì bất đồng.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗯️","examples":[{"type":"basic","zh":"他们又争吵起来了。","pinyin":"Tāmen yòu zhēngchǎo qǐlai le.","vi":"Họ lại cãi nhau rồi."},{"type":"simple","zh":"夫妻俩为了孩子上学的事争吵了一晚上。","pinyin":"Fūqī liǎ wèile háizi shàngxué de shì zhēngchǎole yì wǎnshang.","vi":"Hai vợ chồng cãi nhau cả tối vì chuyện con đi học."},{"type":"compound","zh":"如果大家都冷静一点，就不会发生这样的争吵。","pinyin":"Rúguǒ dàjiā dōu lěngjìng yìdiǎn, jiù bú huì fāshēng zhèyàng de zhēngchǎo.","vi":"Nếu mọi người bình tĩnh hơn một chút thì đã không xảy ra cuộc cãi vã như thế."}],"related":[{"hanzi":"吵架","pinyin":"chǎojià","vi":"cãi nhau"},{"hanzi":"争论","pinyin":"zhēnglùn","vi":"tranh luận"},{"hanzi":"争执","pinyin":"zhēngzhí","vi":"tranh chấp"},{"hanzi":"和好","pinyin":"héhǎo","vi":"làm lành"}],"traditional":"爭吵"},{"id":"争分夺秒","hanzi":"争分夺秒","pinyin":"zhēngfēn-duómiǎo","meaning_vi":"tranh thủ từng phút từng giây, chạy đua với thời gian","explanation":"争分 (tranh phân – giành từng phút) + 夺秒 (đoạt miểu – giật từng giây) → tận dụng tối đa thời gian, khẩn trương làm việc.","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"大家都在争分夺秒。","pinyin":"Dàjiā dōu zài zhēngfēnduómiǎo.","vi":"Mọi người đều đang chạy đua với thời gian."},{"type":"simple","zh":"医生们争分夺秒地抢救受伤的乘客。","pinyin":"Yīshēngmen zhēngfēnduómiǎo de qiǎngjiù shòushāng de chéngkè.","vi":"Các bác sĩ tranh thủ từng giây cấp cứu hành khách bị thương."},{"type":"compound","zh":"因为离高考只剩一个月了，所以同学们都在争分夺秒地复习。","pinyin":"Yīnwèi lí gāokǎo zhǐ shèng yí gèyuè le, suǒyǐ tóngxuémen dōu zài zhēngfēnduómiǎo de fùxí.","vi":"Vì chỉ còn một tháng nữa là thi đại học nên các bạn học sinh đều tranh thủ từng phút ôn bài."}],"related":[{"hanzi":"分秒必争","pinyin":"fēnmiǎobìzhēng","vi":"từng giây đều quý"},{"hanzi":"抓紧时间","pinyin":"zhuājǐnshíjiān","vi":"tranh thủ thời gian"},{"hanzi":"争取","pinyin":"zhēngqǔ","vi":"tranh thủ"},{"hanzi":"磨蹭","pinyin":"móceng","vi":"lề mề"}],"traditional":"爭分奪秒"},{"id":"争光","hanzi":"争光","pinyin":"zhēngguāng","meaning_vi":"làm rạng danh, mang vinh quang về","explanation":"争 (tranh – giành) + 光 (quang – vẻ vang) → giành lấy vinh quang, làm vẻ vang cho tập thể, đất nước.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏅","examples":[{"type":"basic","zh":"他为国家争光了。","pinyin":"Tā wèi guójiā zhēngguāng le.","vi":"Anh ấy đã làm rạng danh đất nước."},{"type":"simple","zh":"运动员们决心在奥运会上为祖国争光。","pinyin":"Yùndòngyuánmen juéxīn zài Àoyùnhuì shang wèi zǔguó zhēngguāng.","vi":"Các vận động viên quyết tâm giành vinh quang cho tổ quốc tại Thế vận hội."},{"type":"compound","zh":"虽然他只是个普通学生，但是这次比赛他为学校争光了。","pinyin":"Suīrán tā zhǐshì gè pǔtōng xuésheng, dànshì zhè cì bǐsài tā wèi xuéxiào zhēngguāng le.","vi":"Tuy chỉ là một học sinh bình thường nhưng ở cuộc thi lần này cậu ấy đã làm rạng danh nhà trường."}],"related":[{"hanzi":"争气","pinyin":"zhēngqì","vi":"nỗ lực vươn lên"},{"hanzi":"光荣","pinyin":"guāngróng","vi":"vinh quang"},{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"}],"traditional":"爭光"},{"id":"争执","hanzi":"争执","pinyin":"zhēngzhí","meaning_vi":"tranh chấp, cãi cọ, khăng khăng không nhường","explanation":"争 (tranh – giành) + 执 (chấp – giữ khư khư) → mỗi bên giữ ý kiến của mình, tranh cãi không chịu nhượng bộ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤼","examples":[{"type":"basic","zh":"双方发生了争执。","pinyin":"Shuāngfāng fāshēngle zhēngzhí.","vi":"Hai bên đã xảy ra tranh chấp."},{"type":"simple","zh":"为了停车位，两个邻居争执了半天。","pinyin":"Wèile tíngchēwèi, liǎng gè línjū zhēngzhíle bàn tiān.","vi":"Vì chỗ đỗ xe, hai người hàng xóm tranh cãi mãi."},{"type":"compound","zh":"即使意见不同，大家也不要在会上争执不下。","pinyin":"Jíshǐ yìjiàn bùtóng, dàjiā yě bú yào zài huì shang zhēngzhí búxià.","vi":"Dù ý kiến khác nhau, mọi người cũng đừng tranh cãi không dứt trong cuộc họp."}],"related":[{"hanzi":"争吵","pinyin":"zhēngchǎo","vi":"cãi nhau"},{"hanzi":"争论","pinyin":"zhēnglùn","vi":"tranh luận"},{"hanzi":"纠纷","pinyin":"jiūfēn","vi":"tranh chấp"},{"hanzi":"固执","pinyin":"gùzhí","vi":"cố chấp"}],"traditional":"爭執"},{"id":"征","hanzi":"征","pinyin":"zhēng","meaning_vi":"trưng thu, trưng cầu, tuyển; đi xa, chinh phạt","explanation":"征 (chinh – đi xa, chinh phạt; trưng – thu, gọi) → đi xa đánh dẹp; nay hay dùng nghĩa thu, tuyển, trưng cầu như 征税, 征兵, 征求.","hsk_level":"7-9","tags":["dong-tu"],"image":"📜","examples":[{"type":"basic","zh":"国家依法征税。","pinyin":"Guójiā yīfǎ zhēngshuì.","vi":"Nhà nước thu thuế theo pháp luật."},{"type":"simple","zh":"杂志社正在向读者征稿。","pinyin":"Zázhìshè zhèngzài xiàng dúzhě zhēnggǎo.","vi":"Tòa soạn tạp chí đang nhận bài từ độc giả."},{"type":"compound","zh":"如果到了年龄，男青年就要依法应征入伍。","pinyin":"Rúguǒ dàole niánlíng, nán qīngnián jiùyào yīfǎ yìngzhēng rùwǔ.","vi":"Nếu đến tuổi thì thanh niên nam phải theo luật nhập ngũ."}],"related":[{"hanzi":"征求","pinyin":"zhēngqiú","vi":"trưng cầu"},{"hanzi":"征收","pinyin":"zhēngshōu","vi":"trưng thu"},{"hanzi":"征兵","pinyin":"zhēngbīng","vi":"tuyển quân"},{"hanzi":"远征","pinyin":"yuǎnzhēng","vi":"viễn chinh"}]},{"id":"征集","hanzi":"征集","pinyin":"zhēngjí","meaning_vi":"thu thập, trưng tập, kêu gọi đóng góp","explanation":"征 (trưng – kêu gọi, thu) + 集 (tập – gom lại) → kêu gọi mọi người gửi đến rồi gom lại (ý kiến, tác phẩm, hiện vật…).","hsk_level":"7-9","tags":["dong-tu"],"image":"📥","examples":[{"type":"basic","zh":"我们正在征集意见。","pinyin":"Wǒmen zhèngzài zhēngjí yìjiàn.","vi":"Chúng tôi đang thu thập ý kiến."},{"type":"simple","zh":"博物馆向社会征集抗战时期的老照片。","pinyin":"Bówùguǎn xiàng shèhuì zhēngjí kàngzhàn shíqī de lǎo zhàopiàn.","vi":"Bảo tàng kêu gọi xã hội đóng góp ảnh cũ thời kháng chiến."},{"type":"compound","zh":"虽然征集活动只举办了一个月，但是收到了上千份作品。","pinyin":"Suīrán zhēngjí huódòng zhǐ jǔbànle yí gèyuè, dànshì shōudàole shàng qiān fèn zuòpǐn.","vi":"Tuy hoạt động thu thập chỉ tổ chức trong một tháng nhưng đã nhận được hơn một nghìn tác phẩm."}],"related":[{"hanzi":"收集","pinyin":"shōují","vi":"thu thập"},{"hanzi":"征求","pinyin":"zhēngqiú","vi":"trưng cầu"},{"hanzi":"搜集","pinyin":"sōují","vi":"sưu tầm"},{"hanzi":"募集","pinyin":"mùjí","vi":"quyên góp"}],"traditional":"徵集"},{"id":"睁","hanzi":"睁","pinyin":"zhēng","meaning_vi":"mở (mắt), giương mắt","explanation":"睁 (tranh – mở mắt) → mở to mắt ra; trái nghĩa với 闭 (nhắm).","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"👀","examples":[{"type":"basic","zh":"快睁开眼睛。","pinyin":"Kuài zhēngkāi yǎnjing.","vi":"Mau mở mắt ra."},{"type":"simple","zh":"阳光太刺眼了，我几乎睁不开眼。","pinyin":"Yángguāng tài cìyǎn le, wǒ jīhū zhēng bù kāiyǎn.","vi":"Nắng chói quá, tôi gần như không mở mắt nổi."},{"type":"compound","zh":"因为昨晚熬夜了，所以早上闹钟响了他也睁不开眼睛。","pinyin":"Yīnwèi zuówǎn áoyè le, suǒyǐ zǎoshang nàozhōng xiǎngle tā yě zhēng bù kāi yǎnjing.","vi":"Vì tối qua thức khuya nên sáng nay đồng hồ reo anh ấy cũng không mở nổi mắt."}],"related":[{"hanzi":"闭","pinyin":"bì","vi":"nhắm"},{"hanzi":"眼睛","pinyin":"yǎnjing","vi":"mắt"},{"hanzi":"睁眼","pinyin":"zhēngyǎn","vi":"mở mắt"},{"hanzi":"眨眼","pinyin":"zhǎyǎn","vi":"chớp mắt"}],"traditional":"睜"},{"id":"蒸","hanzi":"蒸","pinyin":"zhēng","meaning_vi":"hấp, đồ (bằng hơi nước); bốc hơi","explanation":"蒸 (chưng – hơi nóng bốc lên) → nấu chín thức ăn bằng hơi nước; nước bốc hơi.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"♨️","examples":[{"type":"basic","zh":"妈妈在蒸包子。","pinyin":"Māma zài zhēng bāozi.","vi":"Mẹ đang hấp bánh bao."},{"type":"simple","zh":"这条鱼蒸十分钟就可以吃了。","pinyin":"Zhè tiáo yú zhēng shí fēnzhōng jiù kěyǐ chī le.","vi":"Con cá này hấp mười phút là ăn được rồi."},{"type":"compound","zh":"如果用蒸的方法做菜，就能更好地保留营养。","pinyin":"Rúguǒ yòng zhēng de fāngfǎ zuòcài, jiù néng gèng hǎo de bǎoliú yíngyǎng.","vi":"Nếu nấu ăn bằng cách hấp thì có thể giữ lại dinh dưỡng tốt hơn."}],"related":[{"hanzi":"蒸发","pinyin":"zhēngfā","vi":"bốc hơi"},{"hanzi":"蒸汽","pinyin":"zhēngqì","vi":"hơi nước"},{"hanzi":"煮","pinyin":"zhǔ","vi":"luộc, nấu"},{"hanzi":"蒸笼","pinyin":"zhēnglóng","vi":"xửng hấp"}]},{"id":"拯救","hanzi":"拯救","pinyin":"zhěngjiù","meaning_vi":"cứu, cứu vớt, giải cứu","explanation":"拯 (chửng – cứu giúp) + 救 (cứu – cứu) → cứu người, vật khỏi nguy nan; thường dùng với đối tượng lớn hoặc tình huống nghiêm trọng.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛟","examples":[{"type":"basic","zh":"医生拯救了他的生命。","pinyin":"Yīshēng zhěngjiùle tā de shēngmìng.","vi":"Bác sĩ đã cứu sống anh ấy."},{"type":"simple","zh":"许多志愿者参加了拯救野生动物的行动。","pinyin":"Xǔduō zhìyuànzhě cānjiāle zhěngjiù yěshēng dòngwù de xíngdòng.","vi":"Nhiều tình nguyện viên tham gia hành động giải cứu động vật hoang dã."},{"type":"compound","zh":"如果不马上采取措施，就无法拯救这家快要倒闭的工厂。","pinyin":"Rúguǒ bù mǎshàng cǎiqǔ cuòshī, jiù wúfǎ zhěngjiù zhè jiā kuàiyào dǎobì de gōngchǎng.","vi":"Nếu không lập tức có biện pháp thì không thể cứu nhà máy sắp phá sản này."}],"related":[{"hanzi":"挽救","pinyin":"wǎnjiù","vi":"cứu vãn"},{"hanzi":"救助","pinyin":"jiùzhù","vi":"cứu trợ"},{"hanzi":"营救","pinyin":"yíngjiù","vi":"giải cứu"},{"hanzi":"抢救","pinyin":"qiǎngjiù","vi":"cấp cứu"}]},{"id":"整洁","hanzi":"整洁","pinyin":"zhěngjié","meaning_vi":"gọn gàng sạch sẽ, ngăn nắp","explanation":"整 (chỉnh – ngay ngắn) + 洁 (khiết – sạch) → ngăn nắp và sạch sẽ.","hsk_level":"7-9","tags":["tinh-tu","sinh-hoat"],"image":"🧹","examples":[{"type":"basic","zh":"房间很整洁。","pinyin":"Fángjiān hěn zhěngjié.","vi":"Căn phòng rất gọn gàng sạch sẽ."},{"type":"simple","zh":"他每天都穿得干干净净，整洁大方。","pinyin":"Tā měitiān dōu chuān de gān ganjìng jìng, zhěngjié dàfang.","vi":"Ngày nào anh ấy cũng ăn mặc sạch sẽ, gọn gàng, đàng hoàng."},{"type":"compound","zh":"因为大家每天轮流打扫，所以教室一直保持得很整洁。","pinyin":"Yīnwèi dàjiā měitiān lúnliú dǎsǎo, suǒyǐ jiàoshì yìzhí bǎochí de hěn zhěngjié.","vi":"Vì mọi người thay phiên quét dọn mỗi ngày nên lớp học luôn gọn gàng sạch sẽ."}],"related":[{"hanzi":"整齐","pinyin":"zhěngqí","vi":"ngay ngắn"},{"hanzi":"干净","pinyin":"gānjìng","vi":"sạch sẽ"},{"hanzi":"清洁","pinyin":"qīngjié","vi":"vệ sinh"},{"hanzi":"凌乱","pinyin":"língluàn","vi":"bừa bộn"}],"traditional":"整潔"},{"id":"整数","hanzi":"整数","pinyin":"zhěngshù","meaning_vi":"số nguyên; số chẵn, số tròn","explanation":"整 (chỉnh – trọn vẹn) + 数 (số – con số) → số nguyên trong toán học; con số tròn, không lẻ.","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"🔢","examples":[{"type":"basic","zh":"五是一个整数。","pinyin":"Wǔ shì yí gè zhěngshù.","vi":"Năm là một số nguyên."},{"type":"simple","zh":"老板说价格凑个整数，算两百块吧。","pinyin":"Lǎobǎn shuō jiàgé còu gè zhěngshù, suàn liǎng bǎi kuài ba.","vi":"Ông chủ nói làm tròn giá cho chẵn, tính hai trăm đồng thôi."},{"type":"compound","zh":"如果除得尽，结果就是整数，否则就是小数。","pinyin":"Rúguǒ chú de jìn, jiéguǒ jiùshì zhěngshù, fǒuzé jiùshì xiǎoshù.","vi":"Nếu chia hết thì kết quả là số nguyên, nếu không thì là số thập phân."}],"related":[{"hanzi":"小数","pinyin":"xiǎoshù","vi":"số thập phân"},{"hanzi":"分数","pinyin":"fēnshù","vi":"phân số"},{"hanzi":"数字","pinyin":"shùzì","vi":"con số"},{"hanzi":"零头","pinyin":"língtóu","vi":"số lẻ"}],"traditional":"整數"},{"id":"正面","hanzi":"正面","pinyin":"zhèngmiàn","meaning_vi":"mặt chính, mặt trước; chính diện, tích cực","explanation":"正 (chính – ngay, chính) + 面 (diện – mặt) → mặt trước, mặt phải của vật; nghĩa bóng là trực diện, tích cực.","hsk_level":"7-9","tags":["danh-tu"],"image":"🪙","examples":[{"type":"basic","zh":"请看照片的正面。","pinyin":"Qǐngkàn zhàopiàn de zhèngmiàn.","vi":"Hãy xem mặt trước của bức ảnh."},{"type":"simple","zh":"这部电影对年轻人产生了正面的影响。","pinyin":"Zhè bù diànyǐng duì niánqīngrén chǎnshēngle zhèngmiàn de yǐngxiǎng.","vi":"Bộ phim này đã tạo ảnh hưởng tích cực đến giới trẻ."},{"type":"compound","zh":"虽然记者问得很尖锐，但是他没有正面回答。","pinyin":"Suīrán jìzhě wèn de hěn jiānruì, dànshì tā méiyǒu zhèngmiàn huídá.","vi":"Tuy phóng viên hỏi rất gay gắt nhưng anh ấy không trả lời trực diện."}],"related":[{"hanzi":"反面","pinyin":"fǎnmiàn","vi":"mặt trái"},{"hanzi":"背面","pinyin":"bèimiàn","vi":"mặt sau"},{"hanzi":"积极","pinyin":"jījí","vi":"tích cực"},{"hanzi":"负面","pinyin":"fùmiàn","vi":"tiêu cực"}]},{"id":"正直","hanzi":"正直","pinyin":"zhèngzhí","meaning_vi":"chính trực, ngay thẳng","explanation":"正 (chính – ngay) + 直 (trực – thẳng) → ngay thẳng, công bằng, không gian dối.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🧍","examples":[{"type":"basic","zh":"他为人很正直。","pinyin":"Tā wéirén hěn zhèngzhí.","vi":"Anh ấy sống rất ngay thẳng."},{"type":"simple","zh":"爷爷是个正直善良的老教师。","pinyin":"Yéye shì gè zhèngzhí shànliáng de lǎo jiàoshī.","vi":"Ông là một thầy giáo già chính trực và hiền lành."},{"type":"compound","zh":"因为他一向正直，所以大家都相信他说的话。","pinyin":"Yīnwèi tā yíxiàng zhèngzhí, suǒyǐ dàjiā dōu xiāngxìn tā shuō dehuà.","vi":"Vì anh ấy luôn ngay thẳng nên mọi người đều tin lời anh ấy nói."}],"related":[{"hanzi":"诚实","pinyin":"chéngshí","vi":"thật thà"},{"hanzi":"公正","pinyin":"gōngzhèng","vi":"công bằng"},{"hanzi":"正派","pinyin":"zhèngpài","vi":"đứng đắn"},{"hanzi":"虚伪","pinyin":"xūwěi","vi":"giả dối"}]},{"id":"证人","hanzi":"证人","pinyin":"zhèngrén","meaning_vi":"nhân chứng, người làm chứng","explanation":"证 (chứng – làm chứng) + 人 (nhân – người) → người đứng ra làm chứng cho một sự việc.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🧑‍⚖️","examples":[{"type":"basic","zh":"他是唯一的证人。","pinyin":"Tā shì wéiyī de zhèngrén.","vi":"Anh ấy là nhân chứng duy nhất."},{"type":"simple","zh":"法官请证人说出当天看到的情况。","pinyin":"Fǎguān qǐng zhèngrén shuōchū dàngtiān kàndào de qíngkuàng.","vi":"Thẩm phán mời nhân chứng kể lại những gì đã thấy hôm đó."},{"type":"compound","zh":"如果没有证人愿意作证，这个案子就很难判。","pinyin":"Rúguǒ méiyǒu zhèngrén yuànyì zuòzhèng, zhè ge'àn zi jiù hěn nán pàn.","vi":"Nếu không có nhân chứng nào chịu làm chứng thì vụ án này rất khó xét xử."}],"related":[{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"},{"hanzi":"作证","pinyin":"zuòzhèng","vi":"làm chứng"},{"hanzi":"目击者","pinyin":"mùjīzhě","vi":"người chứng kiến"},{"hanzi":"证词","pinyin":"zhèngcí","vi":"lời khai"}],"traditional":"證人"},{"id":"症结","hanzi":"症结","pinyin":"zhēngjié","meaning_vi":"mấu chốt, căn nguyên (của vấn đề)","explanation":"症 (trưng – khối u trong bụng theo Đông y) + 结 (kết – nút thắt) → khối cứng trong bụng; nghĩa bóng là chỗ mắc mấu, nguyên nhân chính của vấn đề.","hsk_level":"7-9","tags":["danh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"问题的症结在哪里？","pinyin":"Wèntí de zhēngjié zài nǎlǐ?","vi":"Mấu chốt của vấn đề nằm ở đâu?"},{"type":"simple","zh":"专家终于找到了交通拥堵的症结。","pinyin":"Zhuānjiā zhōngyú zhǎodàole jiāotōng yōngdǔ de zhēngjié.","vi":"Chuyên gia cuối cùng đã tìm ra căn nguyên của tắc đường."},{"type":"compound","zh":"只有找到症结所在，才能真正解决这个问题。","pinyin":"Zhǐyǒu zhǎodào zhēngjié suǒzài, cáinéng zhēnzhèng jiějué zhè ge wèntí.","vi":"Chỉ khi tìm ra mấu chốt thì mới có thể thực sự giải quyết vấn đề này."}],"related":[{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"根源","pinyin":"gēnyuán","vi":"nguồn gốc"},{"hanzi":"原因","pinyin":"yuányīn","vi":"nguyên nhân"},{"hanzi":"要害","pinyin":"yàohài","vi":"chỗ hiểm yếu"}],"traditional":"癥結"},{"id":"之所以","hanzi":"之所以","pinyin":"zhīsuǒyǐ","meaning_vi":"sở dĩ, (cái) lý do mà","explanation":"之 (chi – trợ từ) + 所以 (sở dĩ – lý do) → dùng trong cấu trúc \"A之所以B，是因为C\": A sở dĩ B là vì C.","hsk_level":"7-9","tags":["lien-tu"],"image":"🔍","examples":[{"type":"basic","zh":"我之所以来，是因为你。","pinyin":"Wǒ zhīsuǒyǐ lái, shì yīnwèi nǐ.","vi":"Tôi đến là vì bạn."},{"type":"simple","zh":"他之所以成功，是因为从不放弃。","pinyin":"Tā zhīsuǒyǐ chénggōng, shì yīnwèi cóng bú fàngqì.","vi":"Anh ấy sở dĩ thành công là vì không bao giờ bỏ cuộc."},{"type":"compound","zh":"这家店之所以生意这么好，是因为菜好吃而且价格便宜。","pinyin":"Zhè jiā diàn zhīsuǒyǐ shēngyi zhème hǎo, shì yīnwèi cài hǎochī érqiě jiàgé piányi.","vi":"Quán này sở dĩ đắt khách như vậy là vì đồ ăn ngon mà giá lại rẻ."}],"related":[{"hanzi":"所以","pinyin":"suǒyǐ","vi":"cho nên"},{"hanzi":"因为","pinyin":"yīnwèi","vi":"bởi vì"},{"hanzi":"由于","pinyin":"yóuyú","vi":"do"},{"hanzi":"原因","pinyin":"yuányīn","vi":"nguyên nhân"}]},{"id":"支票","hanzi":"支票","pinyin":"zhīpiào","meaning_vi":"séc, chi phiếu","explanation":"支 (chi – chi trả) + 票 (phiếu – tờ phiếu) → tờ phiếu ra lệnh ngân hàng trả tiền cho người cầm.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"我用支票付款。","pinyin":"Wǒ yòng zhīpiào fùkuǎn.","vi":"Tôi thanh toán bằng séc."},{"type":"simple","zh":"公司给他开了一张五万元的支票。","pinyin":"Gōngsī gěi tā kāile yì zhāng wǔ wàn yuán de zhīpiào.","vi":"Công ty viết cho anh ấy một tấm séc năm vạn tệ."},{"type":"compound","zh":"如果支票上的签名不对，银行就不会给你兑现。","pinyin":"Rúguǒ zhīpiào shang de qiānmíng bú duì, yínháng jiù bú huì gěi nǐ duìxiàn.","vi":"Nếu chữ ký trên séc không đúng thì ngân hàng sẽ không đổi tiền mặt cho bạn."}],"related":[{"hanzi":"现金","pinyin":"xiànjīn","vi":"tiền mặt"},{"hanzi":"兑现","pinyin":"duìxiàn","vi":"đổi thành tiền"},{"hanzi":"汇票","pinyin":"huìpiào","vi":"hối phiếu"},{"hanzi":"银行","pinyin":"yínháng","vi":"ngân hàng"}]},{"id":"汁","hanzi":"汁","pinyin":"zhī","meaning_vi":"nước ép, nước cốt, nhựa","explanation":"汁 (trấp – nước cốt) → chất lỏng chứa trong hoa quả, thức ăn; như 果汁 (nước ép), 肉汁 (nước thịt).","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"🧃","examples":[{"type":"basic","zh":"柠檬汁很酸。","pinyin":"Níngméngzhī hěn suān.","vi":"Nước chanh rất chua."},{"type":"simple","zh":"她每天早上都喝一杯新鲜的橙汁。","pinyin":"Tā měitiān zǎo Shangdōu hē yì bēi xīnxiān de chéngzhī.","vi":"Sáng nào cô ấy cũng uống một cốc nước cam tươi."},{"type":"compound","zh":"如果在鱼上挤一点柠檬汁，腥味就会少很多。","pinyin":"Rúguǒ zài yú shang jǐ yìdiǎn níngméngzhī, xīngwèi jiù huì shǎo hěn duō.","vi":"Nếu vắt một chút nước chanh lên cá thì mùi tanh sẽ giảm đi nhiều."}],"related":[{"hanzi":"果汁","pinyin":"guǒzhī","vi":"nước ép trái cây"},{"hanzi":"原汁原味","pinyin":"yuánzhīyuánwèi","vi":"nguyên chất"},{"hanzi":"汤","pinyin":"tāng","vi":"canh"},{"hanzi":"榨汁","pinyin":"zhàzhī","vi":"ép nước"}]},{"id":"芝麻","hanzi":"芝麻","pinyin":"zhīma","meaning_vi":"vừng, mè","explanation":"芝 (chi) + 麻 (ma – cây gai, vừng) → cây vừng và hạt vừng; nghĩa bóng chỉ việc nhỏ nhặt (芝麻小事).","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🥯","examples":[{"type":"basic","zh":"我喜欢芝麻汤圆。","pinyin":"Wǒ xǐhuan zhīma tāngyuán.","vi":"Tôi thích bánh trôi nhân vừng."},{"type":"simple","zh":"面包上撒了一层香喷喷的芝麻。","pinyin":"Miànbāo shang sǎle yīcéng xiāngpēnpēn de zhīma.","vi":"Trên bánh mì rắc một lớp vừng thơm phức."},{"type":"compound","zh":"虽然只是芝麻大的小事，但是她还是生气了。","pinyin":"Suīrán zhǐshì zhīma dà de xiǎoshì, dànshì tā háishi shēngqì le.","vi":"Tuy chỉ là chuyện nhỏ bằng hạt vừng nhưng cô ấy vẫn giận."}],"related":[{"hanzi":"芝麻油","pinyin":"zhīmayóu","vi":"dầu vừng"},{"hanzi":"黑芝麻","pinyin":"hēizhīma","vi":"vừng đen"},{"hanzi":"花生","pinyin":"huāshēng","vi":"lạc"},{"hanzi":"芝麻开门","pinyin":"zhīmakāimén","vi":"vừng ơi mở ra"}]},{"id":"芝士","hanzi":"芝士","pinyin":"zhīshì","meaning_vi":"phô mai","explanation":"Từ phiên âm của \"cheese\" (qua tiếng Quảng Đông), đồng nghĩa với 奶酪 (phô mai); hay gặp trong tên món ăn như pizza, bánh mì.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🧀","examples":[{"type":"basic","zh":"我很爱吃芝士。","pinyin":"Wǒ hěn ài chī zhīshì.","vi":"Tôi rất thích ăn phô mai."},{"type":"simple","zh":"这块披萨上放了很多芝士。","pinyin":"Zhè kuài pīsà shàng fàngle hěn duō zhīshì.","vi":"Trên miếng pizza này có rất nhiều phô mai."},{"type":"compound","zh":"虽然芝士很好吃，但是热量实在太高了。","pinyin":"Suīrán zhīshì hěn hǎochī, dànshì rèliàng shízài tài gāo le.","vi":"Tuy phô mai rất ngon nhưng lượng calo thật sự quá cao."}],"related":[{"hanzi":"奶酪","pinyin":"nǎilào","vi":"phô mai"},{"hanzi":"黄油","pinyin":"huángyóu","vi":"bơ"},{"hanzi":"牛奶","pinyin":"niúnǎi","vi":"sữa bò"},{"hanzi":"披萨","pinyin":"pīsà","vi":"bánh pizza"}]},{"id":"知己","hanzi":"知己","pinyin":"zhījǐ","meaning_vi":"tri kỷ, bạn tâm giao","explanation":"知 (tri – biết) + 己 (kỷ – mình) → người hiểu rõ mình, bạn tri kỷ.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤝","examples":[{"type":"basic","zh":"他是我的知己。","pinyin":"Tā shì wǒ de zhījǐ.","vi":"Anh ấy là tri kỷ của tôi."},{"type":"simple","zh":"人生得一知己就足够了。","pinyin":"Rénshēng dé yì zhījǐ jiù zúgòu le.","vi":"Đời người có được một tri kỷ là đủ rồi."},{"type":"compound","zh":"虽然我们很少见面，但她一直是我的知己。","pinyin":"Suīrán wǒmen hěn shǎojiàn miàn, dàn tā yìzhí shì wǒ de zhījǐ.","vi":"Tuy chúng tôi ít gặp nhau nhưng cô ấy luôn là tri kỷ của tôi."}],"related":[{"hanzi":"知音","pinyin":"zhīyīn","vi":"tri âm"},{"hanzi":"知心","pinyin":"zhīxīn","vi":"tâm đầu ý hợp"},{"hanzi":"好友","pinyin":"hǎoyǒu","vi":"bạn thân"},{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"}]},{"id":"知识分子","hanzi":"知识分子","pinyin":"zhīshifènzǐ","meaning_vi":"trí thức, người trí thức","explanation":"知识 (tri thức) + 分子 (phần tử) → tầng lớp người có học vấn, làm công việc trí óc.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🎓","examples":[{"type":"basic","zh":"他是个知识分子。","pinyin":"Tā shì ge zhīshifènzǐ.","vi":"Ông ấy là một người trí thức."},{"type":"simple","zh":"这个小镇出了不少知识分子。","pinyin":"Zhè ge xiǎozhèn chūle bùshǎo zhīshifènzǐ.","vi":"Thị trấn nhỏ này sản sinh không ít trí thức."},{"type":"compound","zh":"作为知识分子，他不但教书，而且常常下乡帮助农民。","pinyin":"Zuòwéi zhīshifènzǐ, tā búdàn jiāoshū, érqiě chángcháng xiàxiāng bāngzhù nóngmín.","vi":"Là trí thức, ông không chỉ dạy học mà còn thường về quê giúp nông dân."}],"related":[{"hanzi":"知识","pinyin":"zhīshi","vi":"tri thức"},{"hanzi":"学者","pinyin":"xuézhě","vi":"học giả"},{"hanzi":"文化人","pinyin":"wénhuàrén","vi":"người có học"},{"hanzi":"教授","pinyin":"jiàoshòu","vi":"giáo sư"}],"traditional":"知識分子"},{"id":"知足","hanzi":"知足","pinyin":"zhīzú","meaning_vi":"biết đủ, bằng lòng với những gì mình có","explanation":"知 (tri – biết) + 足 (túc – đủ) → biết thế nào là đủ, bằng lòng với hiện tại; câu quen thuộc 知足常乐 (biết đủ thì luôn vui).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"做人要知足。","pinyin":"Zuòrén yào zhīzú.","vi":"Làm người phải biết đủ."},{"type":"simple","zh":"奶奶是一个很知足的人。","pinyin":"Nǎinai shì yí gè hěn zhīzú de rén.","vi":"Bà nội là người rất biết đủ."},{"type":"compound","zh":"只要家人都平平安安的，我就已经很知足了。","pinyin":"Zhǐyào jiārén dōu píngpíng ān'ān de, wǒ jiù yǐjīng hěn zhīzú le.","vi":"Chỉ cần người nhà đều bình an là tôi đã rất mãn nguyện rồi."}],"related":[{"hanzi":"满足","pinyin":"mǎnzú","vi":"thỏa mãn"},{"hanzi":"知足常乐","pinyin":"zhīzúchánglè","vi":"biết đủ thì vui"},{"hanzi":"贪心","pinyin":"tānxīn","vi":"tham lam"},{"hanzi":"满意","pinyin":"mǎnyì","vi":"hài lòng"}]},{"id":"肢体","hanzi":"肢体","pinyin":"zhītǐ","meaning_vi":"tay chân, chi thể, cơ thể","explanation":"肢 (chi – tay chân) + 体 (thể – thân thể) → tay chân và thân mình; hay gặp trong 肢体语言 (ngôn ngữ cơ thể).","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🤸","examples":[{"type":"basic","zh":"他的肢体很灵活。","pinyin":"Tā de zhītǐ hěn línghuó.","vi":"Tay chân anh ấy rất linh hoạt."},{"type":"simple","zh":"演员用肢体语言表达情感。","pinyin":"Yǎnyuán yòng zhītǐ yǔyán biǎodá qínggǎn.","vi":"Diễn viên dùng ngôn ngữ cơ thể để biểu đạt cảm xúc."},{"type":"compound","zh":"因为长时间不运动，所以他的肢体变得很僵硬。","pinyin":"Yīnwèi cháng shíjiān bú yùndòng, suǒyǐ tā de zhītǐ biànde hěn jiāngyìng.","vi":"Vì lâu ngày không vận động nên tay chân anh ấy trở nên rất cứng."}],"related":[{"hanzi":"四肢","pinyin":"sìzhī","vi":"tứ chi"},{"hanzi":"身体","pinyin":"shēntǐ","vi":"cơ thể"},{"hanzi":"肢体语言","pinyin":"zhītǐyǔyán","vi":"ngôn ngữ cơ thể"},{"hanzi":"躯干","pinyin":"qūgàn","vi":"thân mình"}],"traditional":"肢體"},{"id":"执意","hanzi":"执意","pinyin":"zhíyì","meaning_vi":"khăng khăng, nhất quyết","explanation":"执 (chấp – giữ chặt) + 意 (ý – ý định) → giữ chặt ý mình, nhất quyết làm điều gì dù người khác can ngăn.","hsk_level":"7-9","tags":["pho-tu"],"image":"😤","examples":[{"type":"basic","zh":"他执意要走。","pinyin":"Tā zhíyì yào zǒu.","vi":"Anh ấy nhất quyết đòi đi."},{"type":"simple","zh":"她执意要一个人去旅行。","pinyin":"Tā zhíyì yào yígèrén qù lǚxíng.","vi":"Cô ấy khăng khăng muốn đi du lịch một mình."},{"type":"compound","zh":"尽管大家都劝他休息，他还是执意加班到深夜。","pinyin":"Jǐnguǎn dàjiā dōu quàn tā xiūxi, tā háishì zhíyì jiābān dào shēnyè.","vi":"Dù mọi người đều khuyên nghỉ ngơi, anh ấy vẫn nhất quyết làm thêm đến khuya."}],"related":[{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"},{"hanzi":"固执","pinyin":"gùzhí","vi":"cố chấp"},{"hanzi":"执着","pinyin":"zhízhuó","vi":"kiên định, cố chấp"},{"hanzi":"一意孤行","pinyin":"yíyìgūxíng","vi":"khăng khăng làm theo ý mình"}],"traditional":"執意"},{"id":"执照","hanzi":"执照","pinyin":"zhízhào","meaning_vi":"giấy phép, bằng (hành nghề)","explanation":"执 (chấp – cầm giữ) + 照 (chiếu – giấy chứng nhận) → giấy tờ cơ quan cấp cho phép hành nghề hay hoạt động, như 驾驶执照 (bằng lái xe).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🪪","examples":[{"type":"basic","zh":"他有驾驶执照。","pinyin":"Tā yǒu jiàshǐ zhízhào.","vi":"Anh ấy có bằng lái xe."},{"type":"simple","zh":"开餐厅必须先办营业执照。","pinyin":"Kāi cāntīng bìxū xiān bàn yíngyè zhízhào.","vi":"Mở nhà hàng phải làm giấy phép kinh doanh trước."},{"type":"compound","zh":"如果没有行医执照，就不能给病人看病。","pinyin":"Rúguǒ méiyǒu xíngyī zhízhào, jiù bù néng gěi bìngrén kànbìng.","vi":"Nếu không có giấy phép hành nghề y thì không được khám bệnh cho bệnh nhân."}],"related":[{"hanzi":"驾照","pinyin":"jiàzhào","vi":"bằng lái"},{"hanzi":"证书","pinyin":"zhèngshū","vi":"chứng chỉ"},{"hanzi":"许可证","pinyin":"xǔkězhèng","vi":"giấy phép"},{"hanzi":"营业执照","pinyin":"yíngyèzhízhào","vi":"giấy phép kinh doanh"}],"traditional":"執照"},{"id":"直奔","hanzi":"直奔","pinyin":"zhíbèn","meaning_vi":"đi thẳng đến, lao thẳng tới","explanation":"直 (trực – thẳng) + 奔 (bôn – chạy tới) → đi thẳng một mạch đến nơi nào đó, không ghé chỗ khác.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🏃","examples":[{"type":"basic","zh":"下班后他直奔家里。","pinyin":"Xiàbān hòu tā zhíbèn jiālǐ.","vi":"Tan làm anh ấy về thẳng nhà."},{"type":"simple","zh":"我们下了飞机直奔酒店。","pinyin":"Wǒmen xiàle fēijī zhíbèn jiǔdiàn.","vi":"Chúng tôi xuống máy bay rồi đi thẳng tới khách sạn."},{"type":"compound","zh":"因为肚子太饿了，所以他放学后直奔食堂。","pinyin":"Yīnwèi dùzi tài è le, suǒyǐ tā fàngxué hòu zhíbèn shítáng.","vi":"Vì đói bụng quá nên tan học cậu ấy chạy thẳng tới căng tin."}],"related":[{"hanzi":"奔向","pinyin":"bènxiàng","vi":"chạy về phía"},{"hanzi":"直达","pinyin":"zhídá","vi":"đi thẳng tới"},{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi đến"},{"hanzi":"奔跑","pinyin":"bēnpǎo","vi":"chạy"}]},{"id":"直达","hanzi":"直达","pinyin":"zhídá","meaning_vi":"đi thẳng, chạy thẳng (không dừng, không đổi chuyến)","explanation":"直 (trực – thẳng) + 达 (đạt – đến) → đến thẳng nơi cần đến, không đổi chuyến hay dừng giữa đường; như 直达车 (xe chạy thẳng).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚄","examples":[{"type":"basic","zh":"这趟车直达北京。","pinyin":"Zhè tàng chē zhídá Běijīng.","vi":"Chuyến xe này chạy thẳng đến Bắc Kinh."},{"type":"simple","zh":"从河内有航班直达上海吗？","pinyin":"Cóng Hénèi yǒu hángbān zhídá Shànghǎi ma?","vi":"Từ Hà Nội có chuyến bay thẳng đến Thượng Hải không?"},{"type":"compound","zh":"虽然直达航班贵一点，但是能节省很多时间。","pinyin":"Suīrán zhídá hángbān guì yìdiǎn, dànshì néng jiéshěng hěn duō shíjiān.","vi":"Tuy chuyến bay thẳng đắt hơn một chút nhưng tiết kiệm được nhiều thời gian."}],"related":[{"hanzi":"直飞","pinyin":"zhífēi","vi":"bay thẳng"},{"hanzi":"中转","pinyin":"zhōngzhuǎn","vi":"quá cảnh"},{"hanzi":"到达","pinyin":"dàodá","vi":"đến nơi"},{"hanzi":"直奔","pinyin":"zhíbèn","vi":"đi thẳng tới"}],"traditional":"直達"},{"id":"直觉","hanzi":"直觉","pinyin":"zhíjué","meaning_vi":"trực giác","explanation":"直 (trực – thẳng) + 觉 (giác – cảm nhận) → cảm nhận trực tiếp, không qua suy luận.","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"我相信我的直觉。","pinyin":"Wǒ xiāngxìn wǒ de zhíjué.","vi":"Tôi tin vào trực giác của mình."},{"type":"simple","zh":"很多时候女人的直觉往往很准。","pinyin":"Hěn duō shíhou nǚrén de zhíjué wǎngwǎng hěn zhǔn.","vi":"Nhiều khi trực giác của phụ nữ thường rất chuẩn."},{"type":"compound","zh":"虽然没有证据，但是直觉告诉我他在说谎。","pinyin":"Suīrán méiyǒu zhèngjù, dànshì zhíjué gàosu wǒ tā zài shuōhuǎng.","vi":"Tuy không có bằng chứng nhưng trực giác mách bảo tôi anh ta đang nói dối."}],"related":[{"hanzi":"感觉","pinyin":"gǎnjué","vi":"cảm giác"},{"hanzi":"第六感","pinyin":"dìliùgǎn","vi":"giác quan thứ sáu"},{"hanzi":"预感","pinyin":"yùgǎn","vi":"linh cảm"},{"hanzi":"理性","pinyin":"lǐxìng","vi":"lý trí"}],"traditional":"直覺"},{"id":"直视","hanzi":"直视","pinyin":"zhíshì","meaning_vi":"nhìn thẳng, đối diện thẳng","explanation":"直 (trực – thẳng) + 视 (thị – nhìn) → nhìn thẳng vào ai hay cái gì; nghĩa bóng là thẳng thắn đối diện (直视问题).","hsk_level":"7-9","tags":["dong-tu","co-the"],"image":"👀","examples":[{"type":"basic","zh":"不要直视太阳。","pinyin":"Bú yào zhíshì tàiyáng.","vi":"Đừng nhìn thẳng vào mặt trời."},{"type":"simple","zh":"他不敢直视老师的眼睛。","pinyin":"Tā bù gǎn zhíshì lǎoshī de yǎnjing.","vi":"Cậu ấy không dám nhìn thẳng vào mắt thầy giáo."},{"type":"compound","zh":"因为阳光太强，所以他不敢直视前方。","pinyin":"Yīnwèi yángguāng tài qiáng, suǒyǐ tā bù gǎn zhíshì qiánfāng.","vi":"Vì nắng quá gắt nên anh ấy không dám nhìn thẳng về phía trước."}],"related":[{"hanzi":"正视","pinyin":"zhèngshì","vi":"nhìn thẳng, đối diện"},{"hanzi":"注视","pinyin":"zhùshì","vi":"nhìn chăm chú"},{"hanzi":"凝视","pinyin":"níngshì","vi":"nhìn chằm chằm"},{"hanzi":"回避","pinyin":"huíbì","vi":"né tránh"}],"traditional":"直視"},{"id":"直至","hanzi":"直至","pinyin":"zhízhì","meaning_vi":"cho đến, mãi đến","explanation":"直 (trực – thẳng) + 至 (chí – đến) → kéo dài một mạch cho đến thời điểm hay mức độ nào đó; văn viết, tương đương 直到.","hsk_level":"7-9","tags":["gioi-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"会议直至深夜才结束。","pinyin":"Huìyì zhízhì shēnyè cái jiéshù.","vi":"Cuộc họp mãi đến khuya mới kết thúc."},{"type":"simple","zh":"他在这家工厂工作直至退休。","pinyin":"Tā zài zhè jiā gōngchǎng gōngzuò zhízhì tuìxiū.","vi":"Ông ấy làm việc ở nhà máy này cho đến khi nghỉ hưu."},{"type":"compound","zh":"即使遇到困难，我们也要坚持直至成功。","pinyin":"Jíshǐ yùdào kùnnan, wǒmen yě yào jiānchí zhízhì chénggōng.","vi":"Dù gặp khó khăn, chúng ta cũng phải kiên trì cho đến khi thành công."}],"related":[{"hanzi":"直到","pinyin":"zhídào","vi":"cho đến"},{"hanzi":"至今","pinyin":"zhìjīn","vi":"đến nay"},{"hanzi":"截至","pinyin":"jiézhì","vi":"tính đến"},{"hanzi":"为止","pinyin":"wéizhǐ","vi":"cho đến (khi dừng)"}]},{"id":"值钱","hanzi":"值钱","pinyin":"zhíqián","meaning_vi":"đáng tiền, có giá trị","explanation":"值 (trị – có giá trị) + 钱 (tiền) → đáng giá nhiều tiền, quý giá.","hsk_level":"7-9","tags":["tinh-tu","tien-te"],"image":"💎","examples":[{"type":"basic","zh":"这块表很值钱。","pinyin":"Zhè kuài biǎo hěn zhíqián.","vi":"Chiếc đồng hồ này rất đáng tiền."},{"type":"simple","zh":"小偷把家里值钱的东西都偷走了。","pinyin":"Xiǎotōu bǎ jiālǐ zhíqián de dōngxi dōu tōu zǒu le.","vi":"Kẻ trộm lấy hết đồ có giá trị trong nhà."},{"type":"compound","zh":"这幅画虽然看起来很旧，但是非常值钱。","pinyin":"Zhè fú huà suīrán kànqǐlái hěn jiù, dànshì fēicháng zhíqián.","vi":"Bức tranh này tuy trông rất cũ nhưng cực kỳ đáng giá."}],"related":[{"hanzi":"价值","pinyin":"jiàzhí","vi":"giá trị"},{"hanzi":"昂贵","pinyin":"ángguì","vi":"đắt đỏ"},{"hanzi":"宝贵","pinyin":"bǎoguì","vi":"quý báu"},{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"}],"traditional":"值錢"},{"id":"职权","hanzi":"职权","pinyin":"zhíquán","meaning_vi":"chức quyền, quyền hạn","explanation":"职 (chức – chức vụ) + 权 (quyền – quyền lực) → quyền lực đi kèm chức vụ; hay gặp trong 滥用职权 (lạm dụng chức quyền).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"⚖️","examples":[{"type":"basic","zh":"他滥用了职权。","pinyin":"Tā lànyòngle zhíquán.","vi":"Ông ta đã lạm dụng chức quyền."},{"type":"simple","zh":"经理在职权范围内做出了决定。","pinyin":"Jīnglǐ zài zhíquán fànwéinèi zuòchūle juédìng.","vi":"Giám đốc đã ra quyết định trong phạm vi quyền hạn."},{"type":"compound","zh":"如果有人利用职权谋取私利，就应该受到惩罚。","pinyin":"Rúguǒ yǒurén lìyòng zhíquán móuqǔ sīlì, jiù yīnggāi shòudào chéngfá.","vi":"Nếu có người lợi dụng chức quyền mưu lợi riêng thì phải bị trừng phạt."}],"related":[{"hanzi":"职务","pinyin":"zhíwù","vi":"chức vụ"},{"hanzi":"权力","pinyin":"quánlì","vi":"quyền lực"},{"hanzi":"权限","pinyin":"quánxiàn","vi":"quyền hạn"},{"hanzi":"职责","pinyin":"zhízé","vi":"chức trách"}],"traditional":"職權"},{"id":"职员","hanzi":"职员","pinyin":"zhíyuán","meaning_vi":"nhân viên, viên chức","explanation":"职 (chức – công việc) + 员 (viên – người) → người làm việc trong cơ quan, công ty, nhất là việc văn phòng.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"👔","examples":[{"type":"basic","zh":"她是银行职员。","pinyin":"Tā shì yínháng zhíyuán.","vi":"Cô ấy là nhân viên ngân hàng."},{"type":"simple","zh":"这家公司有两百多名职员。","pinyin":"Zhè jiā gōngsī yǒu liǎng bǎi duō míng zhíyuán.","vi":"Công ty này có hơn hai trăm nhân viên."},{"type":"compound","zh":"虽然他只是个普通职员，但是工作非常认真。","pinyin":"Suīrán tā zhǐshì ge pǔtōng zhíyuán, dànshì gōngzuò fēicháng rènzhēn.","vi":"Tuy anh ấy chỉ là nhân viên bình thường nhưng làm việc rất nghiêm túc."}],"related":[{"hanzi":"员工","pinyin":"yuángōng","vi":"nhân viên"},{"hanzi":"职工","pinyin":"zhígōng","vi":"công nhân viên chức"},{"hanzi":"白领","pinyin":"báilǐng","vi":"dân văn phòng"},{"hanzi":"雇员","pinyin":"gùyuán","vi":"người làm thuê"}],"traditional":"職員"},{"id":"止咳","hanzi":"止咳","pinyin":"zhǐké","meaning_vi":"giảm ho, cắt cơn ho","explanation":"止 (chỉ – dừng) + 咳 (khái – ho) → làm dừng cơn ho; thường gặp trong 止咳药 (thuốc ho).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"这种药能止咳。","pinyin":"Zhè zhǒng yào néng zhǐké.","vi":"Loại thuốc này có thể cắt cơn ho."},{"type":"simple","zh":"喝点蜂蜜水可以润喉止咳。","pinyin":"Hē diǎn fēngmì shuǐ kěyǐ rùn hóu zhǐké.","vi":"Uống chút nước mật ong có thể làm dịu họng, giảm ho."},{"type":"compound","zh":"如果吃了止咳药还不好，就要去医院检查。","pinyin":"Rúguǒ chīle zhǐké yào hái bù hǎo, jiùyào qù yīyuàn jiǎnchá.","vi":"Nếu uống thuốc ho rồi mà vẫn chưa khỏi thì phải đi bệnh viện kiểm tra."}],"related":[{"hanzi":"咳嗽","pinyin":"késou","vi":"ho"},{"hanzi":"止痛","pinyin":"zhǐtòng","vi":"giảm đau"},{"hanzi":"止血","pinyin":"zhǐxuè","vi":"cầm máu"},{"hanzi":"感冒","pinyin":"gǎnmào","vi":"cảm cúm"}]},{"id":"止血","hanzi":"止血","pinyin":"zhǐxuè","meaning_vi":"cầm máu","explanation":"止 (chỉ – dừng) + 血 (huyết – máu) → làm máu ngừng chảy.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"先给伤口止血。","pinyin":"Xiān gěi shāngkǒu zhǐxuè.","vi":"Trước tiên phải cầm máu cho vết thương."},{"type":"simple","zh":"护士用纱布帮他按压止血。","pinyin":"Hùshi yòng shābù bāng tā ànyā zhǐxuè.","vi":"Y tá dùng gạc ấn giúp anh ấy cầm máu."},{"type":"compound","zh":"一旦受伤流血，就应该马上想办法止血。","pinyin":"Yídàn shòushāng liúxuè, jiù yīnggāi mǎshàng xiǎngbànfǎ zhǐxuè.","vi":"Một khi bị thương chảy máu thì phải lập tức tìm cách cầm máu."}],"related":[{"hanzi":"流血","pinyin":"liúxuè","vi":"chảy máu"},{"hanzi":"伤口","pinyin":"shāngkǒu","vi":"vết thương"},{"hanzi":"止痛","pinyin":"zhǐtòng","vi":"giảm đau"},{"hanzi":"包扎","pinyin":"bāozā","vi":"băng bó"}]},{"id":"旨在","hanzi":"旨在","pinyin":"zhǐzài","meaning_vi":"nhằm, nhằm mục đích","explanation":"旨 (chỉ – mục đích, ý chỉ) + 在 (tại – ở) → mục đích nằm ở…; dùng trong văn viết để nêu mục tiêu của một việc.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎯","examples":[{"type":"basic","zh":"此举旨在保护环境。","pinyin":"Cǐ jǔ zhǐzài bǎohù huánjìng.","vi":"Biện pháp này nhằm bảo vệ môi trường."},{"type":"simple","zh":"这项活动旨在帮助贫困儿童。","pinyin":"Zhè xiàng huódòng zhǐzài bāngzhù pínkùn értóng.","vi":"Hoạt động này nhằm giúp đỡ trẻ em nghèo."},{"type":"compound","zh":"虽然新规定旨在减少交通事故，但是很多司机并不理解。","pinyin":"Suīrán xīn guīdìng zhǐzài jiǎnshǎo jiāotōng shìgù, dànshì hěn duō sījī bìngbù lǐjiě.","vi":"Tuy quy định mới nhằm giảm tai nạn giao thông nhưng nhiều tài xế lại không hiểu."}],"related":[{"hanzi":"目的","pinyin":"mùdì","vi":"mục đích"},{"hanzi":"宗旨","pinyin":"zōngzhǐ","vi":"tôn chỉ"},{"hanzi":"意在","pinyin":"yìzài","vi":"có ý nhằm"},{"hanzi":"为了","pinyin":"wèile","vi":"để, vì"}]},{"id":"指教","hanzi":"指教","pinyin":"zhǐjiào","meaning_vi":"chỉ giáo, góp ý","explanation":"指 (chỉ – chỉ ra) + 教 (giáo – dạy) → chỉ bảo, góp ý; câu khách sáo 请多指教 (mong được chỉ giáo nhiều).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙏","examples":[{"type":"basic","zh":"请多多指教！","pinyin":"Qǐng duōduō zhǐjiào!","vi":"Mong được chỉ giáo nhiều!"},{"type":"simple","zh":"欢迎大家对我的作品提出指教。","pinyin":"Huānyíng dàjiā duì wǒ de zuòpǐn tíchū zhǐjiào.","vi":"Hoan nghênh mọi người góp ý cho tác phẩm của tôi."},{"type":"compound","zh":"因为我刚开始学书法，所以希望老师多多指教。","pinyin":"Yīnwèi wǒ gāng kāishǐ xué shūfǎ, suǒyǐ xīwàng lǎoshī duōduō zhǐjiào.","vi":"Vì tôi mới bắt đầu học thư pháp nên mong thầy chỉ giáo nhiều."}],"related":[{"hanzi":"指导","pinyin":"zhǐdǎo","vi":"hướng dẫn"},{"hanzi":"请教","pinyin":"qǐngjiào","vi":"thỉnh giáo"},{"hanzi":"指点","pinyin":"zhǐdiǎn","vi":"chỉ bảo"},{"hanzi":"赐教","pinyin":"cìjiào","vi":"ban lời chỉ giáo"}]},{"id":"指手画脚","hanzi":"指手画脚","pinyin":"zhǐshǒu-huàjiǎo","meaning_vi":"khoa tay múa chân, chỉ trỏ ra lệnh","explanation":"Nghĩa đen: chỉ tay vẽ chân, vừa nói vừa khoa tay múa chân → nghĩa bóng: tùy tiện chỉ trỏ, phê phán hay sai khiến người khác.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"👉","examples":[{"type":"basic","zh":"别在这儿指手画脚。","pinyin":"Bié zài zhèr zhǐshǒuhuàjiǎo.","vi":"Đừng có đứng đây chỉ trỏ."},{"type":"simple","zh":"他总是对别人的工作指手画脚。","pinyin":"Tā zǒngshì duì biérén de gōngzuò zhǐshǒuhuàjiǎo.","vi":"Anh ta lúc nào cũng chỉ trỏ vào công việc của người khác."},{"type":"compound","zh":"你既然不懂技术，就不要在旁边指手画脚了。","pinyin":"Nǐ jìrán bù dǒng jìshù, jiù bú yào zài pángbiān zhǐshǒuhuàjiǎo le.","vi":"Anh đã không hiểu kỹ thuật thì đừng đứng bên cạnh chỉ trỏ nữa."}],"related":[{"hanzi":"指指点点","pinyin":"zhǐzhǐdiǎndiǎn","vi":"chỉ chỉ trỏ trỏ"},{"hanzi":"发号施令","pinyin":"fāhàoshīlìng","vi":"ra lệnh"},{"hanzi":"评头论足","pinyin":"píngtóulùnzú","vi":"bình phẩm soi mói"},{"hanzi":"多管闲事","pinyin":"duōguǎnxiánshì","vi":"lo chuyện bao đồng"}],"traditional":"指手畫腳"},{"id":"指向","hanzi":"指向","pinyin":"zhǐxiàng","meaning_vi":"chỉ về, hướng tới","explanation":"指 (chỉ – trỏ) + 向 (hướng) → chỉ về một hướng; nghĩa bóng là nhắm vào, hướng đến.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧭","examples":[{"type":"basic","zh":"指针指向十二点。","pinyin":"Zhǐzhēn zhǐxiàng shí'èr diǎn.","vi":"Kim đồng hồ chỉ mười hai giờ."},{"type":"simple","zh":"所有证据都指向了那个司机。","pinyin":"Suǒyǒu zhèngjù dōu zhǐxiàngle nà ge sījī.","vi":"Mọi bằng chứng đều chỉ về người tài xế đó."},{"type":"compound","zh":"只要指南针指向北方，我们就不会迷路。","pinyin":"Zhǐyào zhǐnánzhēn zhǐxiàng běifāng, wǒmen jiù bú huì mílù.","vi":"Chỉ cần la bàn chỉ hướng bắc thì chúng ta sẽ không lạc đường."}],"related":[{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"},{"hanzi":"指南针","pinyin":"zhǐnánzhēn","vi":"la bàn"},{"hanzi":"朝向","pinyin":"cháoxiàng","vi":"hướng về"},{"hanzi":"指出","pinyin":"zhǐchū","vi":"chỉ ra"}]},{"id":"至此","hanzi":"至此","pinyin":"zhìcǐ","meaning_vi":"đến đây, đến lúc này","explanation":"至 (chí – đến) + 此 (thử – đây) → đến đây, tới thời điểm hay mức độ này; dùng trong văn viết.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"🏁","examples":[{"type":"basic","zh":"比赛至此结束。","pinyin":"Bǐsài zhìcǐ jiéshù.","vi":"Trận đấu kết thúc tại đây."},{"type":"simple","zh":"故事至此才真正进入高潮。","pinyin":"Gùshi zhìcǐ cái zhēnzhèng jìnrù gāocháo.","vi":"Câu chuyện đến đây mới thực sự lên cao trào."},{"type":"compound","zh":"既然问题已经查清楚了，那么调查至此就可以结束了。","pinyin":"Jìrán wèntí yǐ jīngchá qīngchu le, nàme diàochá zhìcǐ jiù kěyǐ jiéshù le.","vi":"Vấn đề đã điều tra rõ rồi thì cuộc điều tra có thể kết thúc tại đây."}],"related":[{"hanzi":"至今","pinyin":"zhìjīn","vi":"đến nay"},{"hanzi":"为止","pinyin":"wéizhǐ","vi":"cho đến"},{"hanzi":"到此","pinyin":"dàocǐ","vi":"đến đây"},{"hanzi":"从此","pinyin":"cóngcǐ","vi":"từ đó"}]},{"id":"至关重要","hanzi":"至关重要","pinyin":"zhìguānzhòngyào","meaning_vi":"vô cùng quan trọng, then chốt","explanation":"至 (chí – cực kỳ) + 关 (quan – liên quan) + 重要 (trọng yếu) → có liên quan hệ trọng nhất, cực kỳ quan trọng; cụm cố định hay dùng trong văn viết.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔑","examples":[{"type":"basic","zh":"这一步至关重要。","pinyin":"Zhè yí bù zhìguānzhòngyào.","vi":"Bước này vô cùng quan trọng."},{"type":"simple","zh":"睡眠对孩子的成长至关重要。","pinyin":"Shuìmián duì háizi de chéngzhǎng zhìguānzhòngyào.","vi":"Giấc ngủ vô cùng quan trọng đối với sự phát triển của trẻ."},{"type":"compound","zh":"因为第一印象至关重要，所以面试时要穿得整齐。","pinyin":"Yīnwèi dìyīyìnxiàng zhìguānzhòngyào, suǒyǐ miànshì shí yào chuān de zhěngqí.","vi":"Vì ấn tượng đầu tiên vô cùng quan trọng nên khi phỏng vấn phải ăn mặc chỉnh tề."}],"related":[{"hanzi":"重要","pinyin":"zhòngyào","vi":"quan trọng"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"举足轻重","pinyin":"jǔzúqīngzhòng","vi":"có vai trò quyết định"},{"hanzi":"必不可少","pinyin":"bìbùkěshǎo","vi":"không thể thiếu"}],"traditional":"至關重要"},{"id":"志气","hanzi":"志气","pinyin":"zhìqì","meaning_vi":"chí khí, ý chí vươn lên","explanation":"志 (chí – ý chí) + 气 (khí – khí phách) → ý chí và khí phách muốn vươn lên.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"💪","examples":[{"type":"basic","zh":"这孩子很有志气。","pinyin":"Zhè háizi hěn yǒuzhìqì.","vi":"Đứa trẻ này rất có chí khí."},{"type":"simple","zh":"穷人家的孩子也要有志气。","pinyin":"Qióngrén jiā de háizi yě yàoyǒu zhìqì.","vi":"Con nhà nghèo cũng phải có chí khí."},{"type":"compound","zh":"虽然家里很穷，但是他很有志气，从不向人借钱。","pinyin":"Suīrán jiālǐ hěn qióng, dànshì tā hěn yǒuzhìqì, cóng bú xiàng rén jièqián.","vi":"Tuy nhà rất nghèo nhưng anh ấy rất có chí khí, chưa bao giờ vay tiền ai."}],"related":[{"hanzi":"志向","pinyin":"zhìxiàng","vi":"chí hướng"},{"hanzi":"骨气","pinyin":"gǔqì","vi":"khí phách"},{"hanzi":"雄心","pinyin":"xióngxīn","vi":"hùng tâm"},{"hanzi":"意志","pinyin":"yìzhì","vi":"ý chí"}],"traditional":"志氣"},{"id":"制","hanzi":"制","pinyin":"zhì","meaning_vi":"chế độ; chế tạo; khống chế","explanation":"制 (chế) nghĩa gốc là cắt may, làm ra; mở rộng thành định ra, khống chế và chỉ chế độ, như 学分制 (chế độ tín chỉ), 八小时工作制.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚙️","examples":[{"type":"basic","zh":"公司实行八小时工作制。","pinyin":"Gōngsī shíxíng bā xiǎoshí gōngzuò zhì.","vi":"Công ty áp dụng chế độ làm việc tám tiếng."},{"type":"simple","zh":"这场比赛采用三局两胜制。","pinyin":"Zhè chǎng bǐsài cǎiyòng sān jú liǎng shèng zhì.","vi":"Trận đấu này áp dụng thể thức thắng hai trong ba ván."},{"type":"compound","zh":"只要我们先发制人，就能在比赛中掌握主动。","pinyin":"Zhǐyào wǒmen xiānfā zhì rén, jiù néng zài bǐsài zhōng zhǎngwò zhǔdòng.","vi":"Chỉ cần chúng ta ra tay trước là có thể nắm thế chủ động trong trận đấu."}],"related":[{"hanzi":"制度","pinyin":"zhìdù","vi":"chế độ"},{"hanzi":"制造","pinyin":"zhìzào","vi":"chế tạo"},{"hanzi":"控制","pinyin":"kòngzhì","vi":"khống chế"},{"hanzi":"限制","pinyin":"xiànzhì","vi":"hạn chế"}]},{"id":"制品","hanzi":"制品","pinyin":"zhìpǐn","meaning_vi":"sản phẩm, chế phẩm","explanation":"制 (chế – làm ra) + 品 (phẩm – vật phẩm) → đồ được làm từ một nguyên liệu nhất định, như 乳制品 (chế phẩm sữa), 塑料制品 (đồ nhựa).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"📦","examples":[{"type":"basic","zh":"少用塑料制品。","pinyin":"Shǎo yòng sùliào zhìpǐn.","vi":"Hạn chế dùng đồ nhựa."},{"type":"simple","zh":"这家工厂专门生产竹木制品。","pinyin":"Zhè jiā gōngchǎng zhuānmén shēngchǎn zhúmù zhìpǐn.","vi":"Nhà máy này chuyên sản xuất đồ tre gỗ."},{"type":"compound","zh":"因为他对牛奶过敏，所以不能吃任何乳制品。","pinyin":"Yīnwèi tā duì niúnǎi guòmǐn, suǒyǐ bù néng chī rènhé rǔzhìpǐn.","vi":"Vì cậu ấy dị ứng sữa bò nên không thể ăn bất kỳ chế phẩm sữa nào."}],"related":[{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"sản phẩm"},{"hanzi":"商品","pinyin":"shāngpǐn","vi":"hàng hóa"},{"hanzi":"乳制品","pinyin":"rǔzhìpǐn","vi":"chế phẩm sữa"},{"hanzi":"工艺品","pinyin":"gōngyìpǐn","vi":"đồ thủ công mỹ nghệ"}],"traditional":"製品"},{"id":"治学","hanzi":"治学","pinyin":"zhìxué","meaning_vi":"làm học thuật, nghiên cứu học vấn","explanation":"治 (trị – chuyên tâm sửa sang) + 学 (học – học vấn) → chuyên tâm nghiên cứu học thuật; hay đi với 严谨 (治学严谨 – làm học thuật nghiêm cẩn).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他治学很严谨。","pinyin":"Tā zhìxué hěn yánjǐn.","vi":"Ông ấy làm học thuật rất nghiêm cẩn."},{"type":"simple","zh":"老教授一生都在认真治学。","pinyin":"Lǎo jiàoshòu yìshēng dōu zài rènzhēn zhìxué.","vi":"Vị giáo sư già cả đời chuyên tâm nghiên cứu học vấn."},{"type":"compound","zh":"只有坚持严谨的治学态度，才能做出真正的成果。","pinyin":"Zhǐyǒu jiānchí yánjǐn de zhìxué tàidù, cáinéng zuòchū zhēnzhèng de chéngguǒ.","vi":"Chỉ có giữ thái độ học thuật nghiêm cẩn mới làm ra được thành quả thực sự."}],"related":[{"hanzi":"学术","pinyin":"xuéshù","vi":"học thuật"},{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"严谨","pinyin":"yánjǐn","vi":"nghiêm cẩn"},{"hanzi":"学者","pinyin":"xuézhě","vi":"học giả"}],"traditional":"治學"},{"id":"治愈","hanzi":"治愈","pinyin":"zhìyù","meaning_vi":"chữa khỏi; chữa lành (tâm hồn)","explanation":"治 (trị – chữa) + 愈 (dũ – khỏi bệnh) → chữa cho khỏi hẳn; gần đây còn dùng như tính từ chỉ thứ khiến lòng người ấm áp, được chữa lành.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"他的病已经治愈了。","pinyin":"Tā de bìng yǐjīng zhìyù le.","vi":"Bệnh của anh ấy đã chữa khỏi rồi."},{"type":"simple","zh":"这部电影让人感到很治愈。","pinyin":"Zhè bù diànyǐng ràng rén gǎndào hěn zhìyù.","vi":"Bộ phim này khiến người xem thấy được chữa lành."},{"type":"compound","zh":"如果能早发现早治疗，这种病是可以治愈的。","pinyin":"Rúguǒ néng zǎo fāxiàn zǎo zhìliáo, zhè zhǒng bìng shì kěyǐ zhìyù de.","vi":"Nếu phát hiện sớm, điều trị sớm thì bệnh này có thể chữa khỏi."}],"related":[{"hanzi":"治疗","pinyin":"zhìliáo","vi":"điều trị"},{"hanzi":"痊愈","pinyin":"quányù","vi":"khỏi bệnh"},{"hanzi":"康复","pinyin":"kāngfù","vi":"hồi phục"},{"hanzi":"疗愈","pinyin":"liáoyù","vi":"chữa lành"}],"traditional":"治癒"},{"id":"质地","hanzi":"质地","pinyin":"zhìdì","meaning_vi":"chất liệu, kết cấu, chất lượng","explanation":"质 (chất – chất liệu) + 地 (địa – nền) → kết cấu, chất liệu của vật như vải, gỗ, đá; cũng chỉ phẩm chất con người.","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🧵","examples":[{"type":"basic","zh":"这块布质地柔软。","pinyin":"Zhè kuài bù zhìdì róuruǎn.","vi":"Tấm vải này chất liệu mềm mại."},{"type":"simple","zh":"这件大衣的质地非常好。","pinyin":"Zhè jiàn dàyī de zhìdì fēicháng hǎo.","vi":"Chất liệu chiếc áo khoác này rất tốt."},{"type":"compound","zh":"虽然这张桌子价格不高，但是木头的质地很结实。","pinyin":"Suīrán zhè zhāng zhuōzi jiàgé bù gāo, dànshì mùtou de zhìdì hěn jiēshi.","vi":"Tuy cái bàn này giá không cao nhưng chất gỗ rất chắc."}],"related":[{"hanzi":"质量","pinyin":"zhìliàng","vi":"chất lượng"},{"hanzi":"材料","pinyin":"cáiliào","vi":"vật liệu"},{"hanzi":"面料","pinyin":"miànliào","vi":"chất vải"},{"hanzi":"手感","pinyin":"shǒugǎn","vi":"cảm giác khi sờ"}],"traditional":"質地"},{"id":"质问","hanzi":"质问","pinyin":"zhìwèn","meaning_vi":"chất vấn, hỏi vặn","explanation":"质 (chất – đối chất) + 问 (vấn – hỏi) → hỏi dồn, buộc người kia phải giải thích, chịu trách nhiệm.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"❓","examples":[{"type":"basic","zh":"她生气地质问丈夫。","pinyin":"Tā shēngqì de zhìwèn zhàngfu.","vi":"Cô ấy tức giận chất vấn chồng."},{"type":"simple","zh":"记者当场质问了这位官员。","pinyin":"Jìzhě dāngchǎng zhìwènle zhè wèi guānyuán.","vi":"Phóng viên chất vấn vị quan chức này ngay tại chỗ."},{"type":"compound","zh":"面对顾客的质问，经理不但没道歉，反而发了脾气。","pinyin":"Miànduì gùkè de zhìwèn, jīnglǐ búdàn méi dàoqiàn, fǎn'ér fāle píqi.","vi":"Trước sự chất vấn của khách, giám đốc không những không xin lỗi mà còn nổi nóng."}],"related":[{"hanzi":"追问","pinyin":"zhuīwèn","vi":"hỏi dồn"},{"hanzi":"质疑","pinyin":"zhìyí","vi":"nghi vấn"},{"hanzi":"责问","pinyin":"zéwèn","vi":"hỏi tội"},{"hanzi":"询问","pinyin":"xúnwèn","vi":"hỏi han"}],"traditional":"質問"},{"id":"秩序","hanzi":"秩序","pinyin":"zhìxù","meaning_vi":"trật tự","explanation":"秩 (trật – thứ bậc) + 序 (tự – thứ tự) → sự sắp xếp theo thứ tự, quy củ.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚦","examples":[{"type":"basic","zh":"请大家遵守秩序。","pinyin":"Qǐng dàjiā zūnshǒu zhìxù.","vi":"Mời mọi người giữ trật tự."},{"type":"simple","zh":"警察正在维持现场秩序。","pinyin":"Jǐngchá zhèngzài wéichí xiànchǎng zhìxù.","vi":"Cảnh sát đang duy trì trật tự hiện trường."},{"type":"compound","zh":"如果大家都排队，车站的秩序就会好很多。","pinyin":"Rúguǒ dàjiā dōu páiduì, chēzhàn de zhìxù jiù huì hǎo hěn duō.","vi":"Nếu mọi người đều xếp hàng thì trật tự ở nhà ga sẽ tốt hơn nhiều."}],"related":[{"hanzi":"顺序","pinyin":"shùnxù","vi":"thứ tự"},{"hanzi":"混乱","pinyin":"hùnluàn","vi":"hỗn loạn"},{"hanzi":"规则","pinyin":"guīzé","vi":"quy tắc"},{"hanzi":"有条不紊","pinyin":"yǒutiáobùwěn","vi":"ngăn nắp, có trật tự"}]},{"id":"致","hanzi":"致","pinyin":"zhì","meaning_vi":"gửi tới, bày tỏ; dẫn đến","explanation":"致 (trí) nghĩa là gửi đến, bày tỏ (致谢 – cảm ơn, 致信 – gửi thư) hoặc dẫn tới (导致); văn viết, dùng nhiều trong thư từ, phát biểu.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"✉️","examples":[{"type":"basic","zh":"致亲爱的妈妈。","pinyin":"Zhì qīn'ài de māma.","vi":"Gửi mẹ yêu dấu."},{"type":"simple","zh":"我谨代表全体员工向您致谢。","pinyin":"Wǒ jǐn dàibiǎo quántǐ yuángōng xiàng nín zhìxiè.","vi":"Tôi xin thay mặt toàn thể nhân viên gửi lời cảm ơn đến ông."},{"type":"compound","zh":"虽然不能亲自到场，但是我还是要向新人致以美好的祝福。","pinyin":"Suīrán bù néng qīnzì dàochǎng, dànshì wǒ háishì yào xiàng xīnrén zhìyǐ měihǎo de zhùfú.","vi":"Tuy không thể đích thân có mặt nhưng tôi vẫn muốn gửi lời chúc tốt đẹp đến đôi tân lang tân nương."}],"related":[{"hanzi":"致谢","pinyin":"zhìxiè","vi":"cảm ơn"},{"hanzi":"致以","pinyin":"zhìyǐ","vi":"gửi tới"},{"hanzi":"导致","pinyin":"dǎozhì","vi":"dẫn đến"},{"hanzi":"以致","pinyin":"yǐzhì","vi":"đến nỗi"}]},{"id":"致辞","hanzi":"致辞","pinyin":"zhìcí","meaning_vi":"phát biểu, đọc lời chào mừng","explanation":"致 (trí – bày tỏ) + 辞 (từ – lời lẽ) → bày tỏ bằng lời, phát biểu ngắn trong buổi lễ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🎤","examples":[{"type":"basic","zh":"校长上台致辞。","pinyin":"Xiàozhǎng shàngtái zhìcí.","vi":"Hiệu trưởng lên sân khấu phát biểu."},{"type":"simple","zh":"新郎的父亲在婚礼上致辞。","pinyin":"Xīnláng de fùqīn zài hūnlǐ shàng zhìcí.","vi":"Bố chú rể phát biểu trong lễ cưới."},{"type":"compound","zh":"虽然他致辞的时间很短，但是让在场的人都很感动。","pinyin":"Suīrán tā zhìcí de shíjiān hěn duǎn, dànshì ràng zài chǎng de rén dōu hěn gǎndòng.","vi":"Tuy anh ấy phát biểu rất ngắn nhưng khiến mọi người có mặt đều cảm động."}],"related":[{"hanzi":"发言","pinyin":"fāyán","vi":"phát biểu"},{"hanzi":"讲话","pinyin":"jiǎnghuà","vi":"nói chuyện"},{"hanzi":"演讲","pinyin":"yǎnjiǎng","vi":"diễn thuyết"},{"hanzi":"致词","pinyin":"zhìcí","vi":"phát biểu"}],"traditional":"致辭"},{"id":"致敬","hanzi":"致敬","pinyin":"zhìjìng","meaning_vi":"bày tỏ lòng kính trọng, chào kính, tri ân","explanation":"致 (trí – gửi tới) + 敬 (kính – kính trọng) → gửi lòng kính trọng tới ai; thường dùng 向…致敬.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🫡","examples":[{"type":"basic","zh":"向英雄致敬！","pinyin":"Xiàng yīngxióng zhìjìng!","vi":"Xin kính chào các anh hùng!"},{"type":"simple","zh":"全体观众起立向老兵致敬。","pinyin":"Quántǐ guānzhòng qǐlì xiàng lǎobīng zhìjìng.","vi":"Toàn thể khán giả đứng dậy chào kính các cựu binh."},{"type":"compound","zh":"因为医生们日夜奋战，所以我们要向他们致敬。","pinyin":"Yīnwèi yīshēngmen rìyè fènzhàn, suǒyǐ wǒmen yào xiàng tāmen zhìjìng.","vi":"Vì các bác sĩ chiến đấu ngày đêm nên chúng ta cần bày tỏ lòng kính trọng với họ."}],"related":[{"hanzi":"敬礼","pinyin":"jìnglǐ","vi":"chào"},{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"致谢","pinyin":"zhìxiè","vi":"cảm ơn"},{"hanzi":"敬意","pinyin":"jìngyì","vi":"lòng kính trọng"}]},{"id":"致命","hanzi":"致命","pinyin":"zhìmìng","meaning_vi":"chí mạng, gây chết người","explanation":"致 (trí – dẫn đến) + 命 (mệnh – mạng sống) → dẫn đến mất mạng; nghĩa bóng là cực kỳ nghiêm trọng (致命的错误 – sai lầm chí mạng).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"☠️","examples":[{"type":"basic","zh":"这是致命的错误。","pinyin":"Zhè shì zhìmìng de cuòwù.","vi":"Đây là sai lầm chí mạng."},{"type":"simple","zh":"这种毒蛇的毒液是致命的。","pinyin":"Zhè zhǒng dúshé de dúyè shì zhìmìng de.","vi":"Nọc của loài rắn độc này có thể gây chết người."},{"type":"compound","zh":"如果不及时抢救，这么重的伤可能是致命的。","pinyin":"Rúguǒ bù jíshí qiǎngjiù, zhème zhòng de shāng kěnéng shì zhìmìng de.","vi":"Nếu không cấp cứu kịp thời, vết thương nặng như vậy có thể gây tử vong."}],"related":[{"hanzi":"要命","pinyin":"yàomìng","vi":"chết người"},{"hanzi":"致死","pinyin":"zhìsǐ","vi":"gây chết"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"致命伤","pinyin":"zhìmìngshāng","vi":"vết thương chí mạng"}]},{"id":"窒息","hanzi":"窒息","pinyin":"zhìxī","meaning_vi":"ngạt thở, nghẹt thở","explanation":"窒 (trất – tắc nghẽn) + 息 (tức – hơi thở) → hơi thở bị tắc, ngạt; nghĩa bóng là bị bóp nghẹt, ngột ngạt.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😵","examples":[{"type":"basic","zh":"房间闷得让人窒息。","pinyin":"Fángjiān mèn de ràng rén zhìxī.","vi":"Căn phòng ngột ngạt đến nghẹt thở."},{"type":"simple","zh":"小孩差点儿被果冻噎得窒息。","pinyin":"Xiǎohái chàdiǎnr bèi guǒdòng yē de zhìxī.","vi":"Đứa bé suýt bị miếng thạch làm nghẹn đến ngạt thở."},{"type":"compound","zh":"如果把塑料袋套在头上，就可能导致窒息。","pinyin":"Rúguǒ bǎ sùliàodài tào zài tóushàng, jiù kěnéng dǎozhì zhìxī.","vi":"Nếu trùm túi nilon lên đầu thì có thể dẫn đến ngạt thở."}],"related":[{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"},{"hanzi":"憋气","pinyin":"biēqì","vi":"nín thở"},{"hanzi":"压抑","pinyin":"yāyì","vi":"ngột ngạt"},{"hanzi":"缺氧","pinyin":"quēyǎng","vi":"thiếu oxy"}]},{"id":"滞留","hanzi":"滞留","pinyin":"zhìliú","meaning_vi":"bị kẹt lại, lưu lại","explanation":"滞 (trệ – ngưng trệ) + 留 (lưu – ở lại) → bị kẹt lại một nơi không đi được; cũng chỉ chất như nước, khí ô nhiễm đọng lại.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🧳","examples":[{"type":"basic","zh":"大雪让旅客滞留机场。","pinyin":"Dàxuě ràng lǚkè zhìliú jīchǎng.","vi":"Tuyết lớn khiến hành khách bị kẹt ở sân bay."},{"type":"simple","zh":"上千名乘客滞留在火车站。","pinyin":"Shàng qiān míng chéngkè zhìliú zài huǒchēzhàn.","vi":"Hàng nghìn hành khách bị kẹt lại ở ga tàu."},{"type":"compound","zh":"因为台风导致航班取消，所以很多游客滞留在岛上。","pinyin":"Yīnwèi táifēng dǎozhì hángbān qǔxiāo, suǒyǐ hěn duō yóukè zhìliú zài dǎo shàng.","vi":"Vì bão khiến chuyến bay bị hủy nên nhiều du khách bị kẹt lại trên đảo."}],"related":[{"hanzi":"停留","pinyin":"tíngliú","vi":"dừng lại"},{"hanzi":"逗留","pinyin":"dòuliú","vi":"lưu lại"},{"hanzi":"停滞","pinyin":"tíngzhì","vi":"đình trệ"},{"hanzi":"滞销","pinyin":"zhìxiāo","vi":"ế hàng"}],"traditional":"滯留"},{"id":"置","hanzi":"置","pinyin":"zhì","meaning_vi":"đặt, để; sắm, mua","explanation":"置 (trí) nghĩa là đặt để (放置, 置于) hoặc sắm sửa (购置, 置办 – mua sắm); thường dùng trong văn viết.","hsk_level":"7-9","tags":["dong-tu"],"image":"📍","examples":[{"type":"basic","zh":"他在城里置了房子。","pinyin":"Tā zài chénglǐ zhìle fángzi.","vi":"Anh ấy đã sắm nhà trong thành phố."},{"type":"simple","zh":"他对别人的劝告一直置之不理。","pinyin":"Tā duì biérén de quàngào yìzhí zhìzhībùlǐ.","vi":"Anh ta luôn bỏ ngoài tai lời khuyên của người khác."},{"type":"compound","zh":"因为孩子要上学，所以他们打算在学校附近置一套房子。","pinyin":"Yīnwèi háizi yào shàngxué, suǒyǐ tāmen dǎsuàn zài xuéxiào fùjìn zhì yítào fángzi.","vi":"Vì con sắp đi học nên họ định sắm một căn nhà gần trường."}],"related":[{"hanzi":"放置","pinyin":"fàngzhì","vi":"đặt để"},{"hanzi":"位置","pinyin":"wèizhì","vi":"vị trí"},{"hanzi":"购置","pinyin":"gòuzhì","vi":"mua sắm"},{"hanzi":"设置","pinyin":"shèzhì","vi":"thiết lập"}]},{"id":"中国画","hanzi":"中国画","pinyin":"Zhōngguóhuà","meaning_vi":"tranh Trung Quốc, quốc họa","explanation":"中国 (Trung Quốc) + 画 (họa – tranh) → tranh truyền thống Trung Quốc vẽ bằng bút lông và mực trên giấy hoặc lụa, còn gọi là 国画.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🖌️","examples":[{"type":"basic","zh":"我在学中国画。","pinyin":"Wǒ zài xué Zhōngguóhuà.","vi":"Tôi đang học vẽ tranh Trung Quốc."},{"type":"simple","zh":"这幅中国画画的是山水。","pinyin":"Zhè fú Zhōngguó huàhuà de shì shānshuǐ.","vi":"Bức tranh Trung Quốc này vẽ phong cảnh sơn thủy."},{"type":"compound","zh":"虽然中国画看起来简单，但是要画好却非常难。","pinyin":"Suīrán Zhōngguóhuà kànqǐlái jiǎndān, dànshì yào huà hǎo què fēicháng nán.","vi":"Tuy tranh Trung Quốc trông đơn giản nhưng muốn vẽ đẹp lại vô cùng khó."}],"related":[{"hanzi":"国画","pinyin":"guóhuà","vi":"quốc họa"},{"hanzi":"水墨画","pinyin":"shuǐmòhuà","vi":"tranh thủy mặc"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"油画","pinyin":"yóuhuà","vi":"tranh sơn dầu"}],"traditional":"中國畫"},{"id":"中途","hanzi":"中途","pinyin":"zhōngtú","meaning_vi":"giữa đường, nửa chừng","explanation":"中 (trung – giữa) + 途 (đồ – đường) → giữa đường đi; nghĩa bóng là giữa chừng một việc.","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🛣️","examples":[{"type":"basic","zh":"他中途下了车。","pinyin":"Tā zhōngtú xiàle chē.","vi":"Anh ấy xuống xe giữa đường."},{"type":"simple","zh":"比赛进行到中途突然下起了大雨。","pinyin":"Bǐsài jìnxíng dào zhōngtú tūrán xià qǐle dàyǔ.","vi":"Trận đấu đang giữa chừng thì đột nhiên mưa to."},{"type":"compound","zh":"既然这个项目已经开始了，就不要中途放弃。","pinyin":"Jìrán zhè ge xiàngmù yǐjīng kāishǐ le, jiù bú yào zhōngtú fàngqì.","vi":"Dự án này đã bắt đầu rồi thì đừng bỏ cuộc giữa chừng."}],"related":[{"hanzi":"半途而废","pinyin":"bàntú'érfèi","vi":"bỏ dở nửa chừng"},{"hanzi":"途中","pinyin":"túzhōng","vi":"trên đường"},{"hanzi":"半路","pinyin":"bànlù","vi":"nửa đường"},{"hanzi":"沿途","pinyin":"yántú","vi":"dọc đường"}]},{"id":"中型","hanzi":"中型","pinyin":"zhōngxíng","meaning_vi":"cỡ vừa, loại trung","explanation":"中 (trung – vừa) + 型 (hình – loại, cỡ) → cỡ trung bình, giữa loại lớn và loại nhỏ.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🚐","examples":[{"type":"basic","zh":"这是一辆中型客车。","pinyin":"Zhè shì yí liàng zhōngxíng kèchē.","vi":"Đây là một chiếc xe khách cỡ trung."},{"type":"simple","zh":"他在一家中型企业当会计。","pinyin":"Tā zài yìjiā zhōngxíng qǐyè dāng kuàijì.","vi":"Anh ấy làm kế toán ở một doanh nghiệp vừa."},{"type":"compound","zh":"虽然这是一座中型城市，但是交通非常方便。","pinyin":"Suīrán zhè shì yí zuò zhōngxíng chéngshì, dànshì jiāotōng fēicháng fāngbiàn.","vi":"Tuy đây là một thành phố cỡ vừa nhưng giao thông rất thuận tiện."}],"related":[{"hanzi":"大型","pinyin":"dàxíng","vi":"cỡ lớn"},{"hanzi":"小型","pinyin":"xiǎoxíng","vi":"cỡ nhỏ"},{"hanzi":"重型","pinyin":"zhòngxíng","vi":"hạng nặng"},{"hanzi":"型号","pinyin":"xínghào","vi":"kiểu, mẫu mã"}]},{"id":"中性","hanzi":"中性","pinyin":"zhōngxìng","meaning_vi":"trung tính","explanation":"中 (trung – giữa) + 性 (tính – tính chất) → tính chất ở giữa, không nghiêng về bên nào: không axit không kiềm, không nam không nữ, hoặc không khen không chê.","hsk_level":"7-9","tags":["tinh-tu","khoa-hoc"],"image":"⚪","examples":[{"type":"basic","zh":"这是中性洗发水。","pinyin":"Zhè shì zhōngxìng xǐfàshuǐ.","vi":"Đây là dầu gội trung tính."},{"type":"simple","zh":"她喜欢穿比较中性的衣服。","pinyin":"Tā xǐhuan chuān bǐjiào zhōngxìng de yīfu.","vi":"Cô ấy thích mặc quần áo phong cách trung tính."},{"type":"compound","zh":"因为这个词是中性的，所以既能用于褒义，也能用于贬义。","pinyin":"Yīnwèi zhè ge cí shì zhōngxìng de, suǒyǐ jì néng yòngyú bāoyì, yě néng yòngyú biǎnyì.","vi":"Vì từ này mang nghĩa trung tính nên có thể dùng cả với nghĩa khen lẫn nghĩa chê."}],"related":[{"hanzi":"酸性","pinyin":"suānxìng","vi":"tính axit"},{"hanzi":"碱性","pinyin":"jiǎnxìng","vi":"tính kiềm"},{"hanzi":"中立","pinyin":"zhōnglì","vi":"trung lập"},{"hanzi":"中性笔","pinyin":"zhōngxìngbǐ","vi":"bút gel"}]},{"id":"中庸","hanzi":"中庸","pinyin":"zhōngyōng","meaning_vi":"trung dung, đạo trung dung","explanation":"中 (trung – giữa) + 庸 (dung – bình thường, không đổi) → đạo trung dung của Nho gia: không thái quá, không bất cập; cũng là tên sách Trung Dung trong Tứ thư.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"☯️","examples":[{"type":"basic","zh":"他信奉中庸之道。","pinyin":"Tā xìnfèng zhōngyōngzhīdào.","vi":"Ông ấy tin theo đạo trung dung."},{"type":"simple","zh":"中庸是儒家的重要思想之一。","pinyin":"Zhōngyōng shì Rújiā de zhòngyào sīxiǎng zhīyī.","vi":"Trung dung là một trong những tư tưởng quan trọng của Nho gia."},{"type":"compound","zh":"虽然中庸之道讲究适度，但是并不等于没有原则。","pinyin":"Suīrán zhōngyōngzhīdào jiǎngjiu shìdù, dànshì bìngbù děngyú méiyǒu yuánzé.","vi":"Tuy đạo trung dung coi trọng sự vừa phải nhưng không có nghĩa là không có nguyên tắc."}],"related":[{"hanzi":"儒家","pinyin":"Rújiā","vi":"Nho gia"},{"hanzi":"孔子","pinyin":"Kǒngzǐ","vi":"Khổng Tử"},{"hanzi":"适度","pinyin":"shìdù","vi":"vừa phải"},{"hanzi":"四书","pinyin":"Sìshū","vi":"Tứ thư"}]},{"id":"中止","hanzi":"中止","pinyin":"zhōngzhǐ","meaning_vi":"đình chỉ, ngừng giữa chừng","explanation":"中 (trung – giữa chừng) + 止 (chỉ – dừng) → dừng lại giữa chừng, có thể tiếp tục hoặc không.","hsk_level":"7-9","tags":["dong-tu"],"image":"⏸️","examples":[{"type":"basic","zh":"谈判被迫中止。","pinyin":"Tánpàn bèipò zhōngzhǐ.","vi":"Cuộc đàm phán buộc phải ngừng lại."},{"type":"simple","zh":"比赛因为暴雨中止了半个小时。","pinyin":"Bǐsài yīnwèi bàoyǔ zhōngzhǐle bàn ge xiǎoshí.","vi":"Trận đấu bị tạm ngừng nửa tiếng vì mưa bão."},{"type":"compound","zh":"如果对方违反合同，我们就有权中止合作。","pinyin":"Rúguǒ duìfāng wéifǎn hétong, wǒmen jiù yǒuquán zhōngzhǐ hézuò.","vi":"Nếu đối phương vi phạm hợp đồng thì chúng ta có quyền đình chỉ hợp tác."}],"related":[{"hanzi":"停止","pinyin":"tíngzhǐ","vi":"dừng lại"},{"hanzi":"终止","pinyin":"zhōngzhǐ","vi":"chấm dứt"},{"hanzi":"暂停","pinyin":"zàntíng","vi":"tạm dừng"},{"hanzi":"中断","pinyin":"zhōngduàn","vi":"gián đoạn"}]},{"id":"忠于","hanzi":"忠于","pinyin":"zhōngyú","meaning_vi":"trung thành với","explanation":"忠 (trung – trung thành) + 于 (vu – với) → trung thành, một lòng với ai hay điều gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"🫶","examples":[{"type":"basic","zh":"他忠于自己的国家。","pinyin":"Tā zhōngyú zìjǐ de guójiā.","vi":"Ông ấy trung thành với tổ quốc."},{"type":"simple","zh":"这部电影很忠于原著小说。","pinyin":"Zhè bù diànyǐng hěn zhōngyú yuánzhù xiǎoshuō.","vi":"Bộ phim này rất trung thành với tiểu thuyết gốc."},{"type":"compound","zh":"无论遇到什么诱惑，他都始终忠于自己的妻子。","pinyin":"Wúlùn yùdào shénme yòuhuò, tā dōu shǐzhōng zhōngyú zìjǐ de qīzi.","vi":"Dù gặp cám dỗ gì, anh ấy vẫn luôn chung thủy với vợ."}],"related":[{"hanzi":"忠诚","pinyin":"zhōngchéng","vi":"trung thành"},{"hanzi":"忠实","pinyin":"zhōngshí","vi":"trung thực"},{"hanzi":"效忠","pinyin":"xiàozhōng","vi":"tận trung"},{"hanzi":"背叛","pinyin":"bèipàn","vi":"phản bội"}],"traditional":"忠於"},{"id":"忠贞","hanzi":"忠贞","pinyin":"zhōngzhēn","meaning_vi":"trung trinh, son sắt, chung thủy","explanation":"忠 (trung – trung thành) + 贞 (trinh – trong sạch, kiên định) → một lòng trung thành son sắt, không thay đổi.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💍","examples":[{"type":"basic","zh":"他们的爱情很忠贞。","pinyin":"Tāmen de àiqíng hěn zhōngzhēn.","vi":"Tình yêu của họ rất son sắt."},{"type":"simple","zh":"她一生对丈夫忠贞不渝。","pinyin":"Tā yìshēng duì zhàngfu zhōngzhēn bùyú.","vi":"Cả đời bà một lòng son sắt với chồng."},{"type":"compound","zh":"尽管丈夫离家多年，她仍然对他保持忠贞。","pinyin":"Jǐnguǎn zhàngfu lí jiā duōnián, tā réngrán duì tā bǎochí zhōngzhēn.","vi":"Dù chồng xa nhà nhiều năm, bà vẫn giữ lòng chung thủy với ông."}],"related":[{"hanzi":"忠诚","pinyin":"zhōngchéng","vi":"trung thành"},{"hanzi":"坚贞","pinyin":"jiānzhēn","vi":"kiên trinh"},{"hanzi":"忠贞不渝","pinyin":"zhōngzhēnbùyú","vi":"trước sau như một"},{"hanzi":"忠心","pinyin":"zhōngxīn","vi":"lòng trung"}],"traditional":"忠貞"},{"id":"终结","hanzi":"终结","pinyin":"zhōngjié","meaning_vi":"kết thúc, chấm dứt","explanation":"终 (chung – cuối) + 结 (kết – kết thúc) → đi đến điểm cuối cùng, chấm dứt hẳn một giai đoạn hay sự việc.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔚","examples":[{"type":"basic","zh":"战争终于终结了。","pinyin":"Zhànzhēng zhōngyú zhōngjié le.","vi":"Chiến tranh cuối cùng đã kết thúc."},{"type":"simple","zh":"这场胜利终结了球队的连败。","pinyin":"Zhè chǎng shènglì zhōngjiéle qiúduì de liánbài.","vi":"Chiến thắng này đã chấm dứt chuỗi thua liên tiếp của đội bóng."},{"type":"compound","zh":"虽然他们的婚姻终结了，但是两人仍然是朋友。","pinyin":"Suīrán tāmen de hūnyīn zhōngjié le, dànshì liǎng rén réngrán shì péngyou.","vi":"Tuy cuộc hôn nhân của họ đã kết thúc nhưng hai người vẫn là bạn."}],"related":[{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"},{"hanzi":"终止","pinyin":"zhōngzhǐ","vi":"chấm dứt"},{"hanzi":"完结","pinyin":"wánjié","vi":"hoàn tất"},{"hanzi":"开端","pinyin":"kāiduān","vi":"khởi đầu"}],"traditional":"終結"},{"id":"终生","hanzi":"终生","pinyin":"zhōngshēng","meaning_vi":"suốt đời, trọn đời","explanation":"终 (chung – hết) + 生 (sinh – cuộc đời) → trọn cả cuộc đời, thường dùng trong 终生难忘 (suốt đời khó quên).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"♾️","examples":[{"type":"basic","zh":"这件事让我终生难忘。","pinyin":"Zhè jiàn shì ràng wǒ zhōngshēng nánwàng.","vi":"Chuyện này khiến tôi suốt đời khó quên."},{"type":"simple","zh":"他把终生献给了教育事业。","pinyin":"Tā bǎ zhōngshēng xiàn gěile jiàoyù shìyè.","vi":"Ông đã cống hiến cả đời cho sự nghiệp giáo dục."},{"type":"compound","zh":"如果小时候不注意保护眼睛，就可能终生受影响。","pinyin":"Rúguǒ xiǎoshíhou bú zhùyì bǎohù yǎnjing, jiù kěnéng zhōngshēng shòu yǐngxiǎng.","vi":"Nếu lúc nhỏ không chú ý bảo vệ mắt thì có thể bị ảnh hưởng suốt đời."}],"related":[{"hanzi":"终身","pinyin":"zhōngshēn","vi":"trọn đời"},{"hanzi":"一生","pinyin":"yìshēng","vi":"cả đời"},{"hanzi":"一辈子","pinyin":"yíbèizi","vi":"cả một đời"},{"hanzi":"毕生","pinyin":"bìshēng","vi":"suốt đời"}],"traditional":"終生"},{"id":"众人","hanzi":"众人","pinyin":"zhòngrén","meaning_vi":"mọi người, đám đông","explanation":"众 (chúng – nhiều người) + 人 (nhân – người) → nhiều người, tất cả mọi người có mặt.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👥","examples":[{"type":"basic","zh":"众人都笑了起来。","pinyin":"Zhòngrén dōu xiàole qǐlái.","vi":"Mọi người đều bật cười."},{"type":"simple","zh":"他当着众人的面向她求婚。","pinyin":"Tā dāngzhe zhòngrén de miànxiàng tā qiúhūn.","vi":"Anh ấy cầu hôn cô trước mặt mọi người."},{"type":"compound","zh":"虽然众人都反对，但是他仍然坚持自己的看法。","pinyin":"Suīrán zhòngrén dōu fǎnduì, dànshì tā réngrán jiānchí zìjǐ de kànfǎ.","vi":"Tuy mọi người đều phản đối nhưng anh ấy vẫn giữ quan điểm của mình."}],"related":[{"hanzi":"大家","pinyin":"dàjiā","vi":"mọi người"},{"hanzi":"大众","pinyin":"dàzhòng","vi":"đại chúng"},{"hanzi":"群众","pinyin":"qúnzhòng","vi":"quần chúng"},{"hanzi":"众所周知","pinyin":"zhòngsuǒzhōuzhī","vi":"ai cũng biết"}],"traditional":"眾人"},{"id":"重播","hanzi":"重播","pinyin":"chóngbō","meaning_vi":"phát lại, chiếu lại","explanation":"重 (trùng – lặp lại) + 播 (bá – phát sóng) → phát sóng lại chương trình đã phát.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"📺","examples":[{"type":"basic","zh":"这部剧今晚重播。","pinyin":"Zhè bù jù jīnwǎn chóngbō.","vi":"Bộ phim này tối nay chiếu lại."},{"type":"simple","zh":"电视台每年春节都重播这部老电影。","pinyin":"Diànshìtái měinián Chūnjié dōu chóngbō zhè bù lǎo diànyǐng.","vi":"Năm nào Tết đài truyền hình cũng chiếu lại bộ phim cũ này."},{"type":"compound","zh":"如果你错过了直播，可以明天中午看重播。","pinyin":"Rúguǒ nǐ cuòguòle zhíbō, kěyǐ míngtiān zhōngwǔ kàn chóngbō.","vi":"Nếu bạn bỏ lỡ buổi phát trực tiếp thì có thể xem phát lại vào trưa mai."}],"related":[{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"},{"hanzi":"转播","pinyin":"zhuǎnbō","vi":"tiếp sóng"},{"hanzi":"回放","pinyin":"huífàng","vi":"phát lại"},{"hanzi":"首播","pinyin":"shǒubō","vi":"phát sóng lần đầu"}]},{"id":"重创","hanzi":"重创","pinyin":"zhòngchuāng","meaning_vi":"gây tổn thất nặng, đánh trọng thương","explanation":"重 (trọng – nặng) + 创 (sang – vết thương) → làm bị thương nặng, gây thiệt hại nghiêm trọng.","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"台风重创了这个小岛。","pinyin":"Táifēng zhòngchuāngle zhè ge xiǎodǎo.","vi":"Cơn bão đã tàn phá nặng nề hòn đảo nhỏ này."},{"type":"simple","zh":"金融危机重创了当地的旅游业。","pinyin":"Jīnróngwēijī zhòngchuāngle dāngdì de lǚyóuyè.","vi":"Khủng hoảng tài chính gây thiệt hại nặng cho ngành du lịch địa phương."},{"type":"compound","zh":"虽然公司受到了重创，但是员工们没有放弃。","pinyin":"Suīrán gōngsī shòudàole zhòngchuāng, dànshì yuángōngmen méiyǒu fàngqì.","vi":"Tuy công ty bị tổn thất nặng nề nhưng nhân viên không bỏ cuộc."}],"related":[{"hanzi":"打击","pinyin":"dǎjī","vi":"đả kích, đòn giáng"},{"hanzi":"重伤","pinyin":"zhòngshāng","vi":"trọng thương"},{"hanzi":"损失","pinyin":"sǔnshī","vi":"tổn thất"},{"hanzi":"摧毁","pinyin":"cuīhuǐ","vi":"phá hủy"}],"traditional":"重創"},{"id":"重返","hanzi":"重返","pinyin":"chóngfǎn","meaning_vi":"trở lại, quay về","explanation":"重 (trùng – lần nữa) + 返 (phản – quay về) → quay trở lại nơi cũ hoặc vị trí cũ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔙","examples":[{"type":"basic","zh":"他重返了赛场。","pinyin":"Tā chóngfǎnle sàichǎng.","vi":"Anh ấy đã trở lại sân thi đấu."},{"type":"simple","zh":"毕业十年后她重返母校。","pinyin":"Bìyè shí nián hòu tā chóngfǎn mǔxiào.","vi":"Mười năm sau khi tốt nghiệp, cô ấy trở lại trường cũ."},{"type":"compound","zh":"虽然受过严重的伤，但是他还是重返了舞台。","pinyin":"Suīrán shòuguo yánzhòng de shāng, dànshì tā háishì chóngfǎnle wǔtái.","vi":"Tuy từng bị thương nặng nhưng anh ấy vẫn trở lại sân khấu."}],"related":[{"hanzi":"返回","pinyin":"fǎnhuí","vi":"trở về"},{"hanzi":"回归","pinyin":"huíguī","vi":"quay về"},{"hanzi":"重回","pinyin":"chónghuí","vi":"quay lại"},{"hanzi":"复出","pinyin":"fùchū","vi":"tái xuất"}]},{"id":"重合","hanzi":"重合","pinyin":"chónghé","meaning_vi":"trùng khớp, trùng nhau","explanation":"重 (trùng – chồng lên) + 合 (hợp – khớp) → chồng lên nhau khớp hoàn toàn; cũng chỉ hai việc trùng nhau.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔁","examples":[{"type":"basic","zh":"两个三角形完全重合。","pinyin":"Liǎng gè sānjiǎoxíng wánquán chónghé.","vi":"Hai tam giác hoàn toàn trùng nhau."},{"type":"simple","zh":"这两本书的内容有一部分重合。","pinyin":"Zhè liǎng běn shū de nèiróng yǒu yíbùfen chónghé.","vi":"Nội dung hai cuốn sách này có một phần trùng nhau."},{"type":"compound","zh":"因为两场考试的时间重合了，所以我只能选一场。","pinyin":"Yīnwèi liǎng chǎng kǎoshì de shíjiān chónghé le, suǒyǐ wǒ zhǐnéng xuǎn yì chǎng.","vi":"Vì thời gian hai kỳ thi trùng nhau nên tôi chỉ có thể chọn một."}],"related":[{"hanzi":"重叠","pinyin":"chóngdié","vi":"chồng lên nhau"},{"hanzi":"吻合","pinyin":"wěnhé","vi":"ăn khớp"},{"hanzi":"重复","pinyin":"chóngfù","vi":"lặp lại"},{"hanzi":"一致","pinyin":"yízhì","vi":"nhất trí"}]},{"id":"重量级","hanzi":"重量级","pinyin":"zhòngliàngjí","meaning_vi":"hạng nặng; tầm cỡ, có sức nặng","explanation":"重量 (trọng lượng) + 级 (cấp – hạng) → hạng cân nặng trong quyền anh, cử tạ; nghĩa bóng chỉ người hay vật có tầm ảnh hưởng lớn.","hsk_level":"7-9","tags":["tinh-tu","the-thao"],"image":"🥊","examples":[{"type":"basic","zh":"他是重量级拳王。","pinyin":"Tā shì zhòngliàngjí quánwáng.","vi":"Anh ấy là nhà vô địch quyền anh hạng nặng."},{"type":"simple","zh":"今晚的节目请来了几位重量级嘉宾。","pinyin":"Jīnwǎn de jiémù qǐng láile jǐ wèi zhòngliàngjí jiābīn.","vi":"Chương trình tối nay mời được mấy vị khách mời tầm cỡ."},{"type":"compound","zh":"虽然对手是重量级选手，但是他一点也不害怕。","pinyin":"Suīrán duìshǒu shì zhòngliàngjí xuǎnshǒu, dànshì tā yìdiǎn yě bú hàipà.","vi":"Tuy đối thủ là tuyển thủ hạng nặng nhưng anh ấy không hề sợ hãi."}],"related":[{"hanzi":"轻量级","pinyin":"qīngliàngjí","vi":"hạng nhẹ"},{"hanzi":"重量","pinyin":"zhòngliàng","vi":"trọng lượng"},{"hanzi":"级别","pinyin":"jíbié","vi":"cấp bậc"},{"hanzi":"拳击","pinyin":"quánjī","vi":"quyền anh"}],"traditional":"重量級"},{"id":"重伤","hanzi":"重伤","pinyin":"zhòngshāng","meaning_vi":"bị thương nặng, trọng thương","explanation":"重 (trọng – nặng) + 伤 (thương – vết thương) → vết thương nặng, bị thương nghiêm trọng.","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🚑","examples":[{"type":"basic","zh":"他在事故中受了重伤。","pinyin":"Tā zài shìgù zhōng shòule zhòngshāng.","vi":"Anh ấy bị thương nặng trong vụ tai nạn."},{"type":"simple","zh":"两名重伤人员已被送往医院。","pinyin":"Liǎng míng zhòngshāng rényuán yǐ bèi sòng wǎng yīyuàn.","vi":"Hai người bị thương nặng đã được đưa đến bệnh viện."},{"type":"compound","zh":"虽然他受了重伤，但是还坚持把孩子救了出来。","pinyin":"Suīrán tā shòule zhòngshāng, dànshì hái jiānchí bǎ háizi jiùle chūlái.","vi":"Tuy bị thương nặng nhưng anh ấy vẫn cố cứu đứa trẻ ra ngoài."}],"related":[{"hanzi":"轻伤","pinyin":"qīngshāng","vi":"bị thương nhẹ"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"bị thương"},{"hanzi":"伤势","pinyin":"shāngshì","vi":"tình trạng vết thương"},{"hanzi":"重创","pinyin":"zhòngchuāng","vi":"tổn thất nặng"}],"traditional":"重傷"},{"id":"重申","hanzi":"重申","pinyin":"chóngshēn","meaning_vi":"nhắc lại, tái khẳng định","explanation":"重 (trùng – lần nữa) + 申 (thân – trình bày) → nói rõ lại lần nữa một lập trường hay quan điểm.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📢","examples":[{"type":"basic","zh":"老师重申了考试纪律。","pinyin":"Lǎoshī chóngshēnle kǎoshì jìlǜ.","vi":"Thầy giáo nhắc lại kỷ luật phòng thi."},{"type":"simple","zh":"外交部发言人重申了政府的立场。","pinyin":"Wàijiāobù fāyánrén chóngshēnle zhèngfǔ de lìchǎng.","vi":"Người phát ngôn Bộ Ngoại giao tái khẳng định lập trường của chính phủ."},{"type":"compound","zh":"虽然经理已经说过多次，但他还是在会上重申了这条规定。","pinyin":"Suīrán jīnglǐ yǐjīng shuōguo duōcì, dàn tā háishì zài huì shàng chóngshēnle zhè tiáo guīdìng.","vi":"Tuy giám đốc đã nói nhiều lần nhưng ông vẫn nhắc lại quy định này trong cuộc họp."}],"related":[{"hanzi":"强调","pinyin":"qiángdiào","vi":"nhấn mạnh"},{"hanzi":"声明","pinyin":"shēngmíng","vi":"tuyên bố"},{"hanzi":"申明","pinyin":"shēnmíng","vi":"nói rõ"},{"hanzi":"重复","pinyin":"chóngfù","vi":"lặp lại"}]},{"id":"重现","hanzi":"重现","pinyin":"chóngxiàn","meaning_vi":"tái hiện, xuất hiện lại","explanation":"重 (trùng – lần nữa) + 现 (hiện – xuất hiện) → xuất hiện trở lại, hoặc tái hiện cảnh cũ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"往事在眼前重现。","pinyin":"Wǎngshì zài yǎnqián chóngxiàn.","vi":"Chuyện cũ hiện lại trước mắt."},{"type":"simple","zh":"这部电影重现了一百年前的北京。","pinyin":"Zhè bù diànyǐng chóngxiànle yī bǎi niánqián de Běijīng.","vi":"Bộ phim này tái hiện Bắc Kinh của một trăm năm trước."},{"type":"compound","zh":"如果不找出原因，这样的问题还会重现。","pinyin":"Rúguǒ bù zhǎochū yuányīn, zhèyàng de wèntí hái huì chóngxiàn.","vi":"Nếu không tìm ra nguyên nhân thì vấn đề như vậy sẽ còn xuất hiện lại."}],"related":[{"hanzi":"再现","pinyin":"zàixiàn","vi":"tái hiện"},{"hanzi":"出现","pinyin":"chūxiàn","vi":"xuất hiện"},{"hanzi":"重演","pinyin":"chóngyǎn","vi":"tái diễn"},{"hanzi":"复原","pinyin":"fùyuán","vi":"phục hồi nguyên dạng"}],"traditional":"重現"},{"id":"重型","hanzi":"重型","pinyin":"zhòngxíng","meaning_vi":"hạng nặng, cỡ lớn","explanation":"重 (trọng – nặng) + 型 (hình – loại) → loại có trọng lượng, công suất lớn, như 重型卡车 (xe tải hạng nặng).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🚛","examples":[{"type":"basic","zh":"这是一台重型机器。","pinyin":"Zhè shì yì tái zhòngxíng jīqì.","vi":"Đây là một cỗ máy hạng nặng."},{"type":"simple","zh":"重型卡车不能在这条路上行驶。","pinyin":"Zhòngxíng kǎchē bù néng zài zhè tiáo lùshàng xíngshǐ.","vi":"Xe tải hạng nặng không được chạy trên con đường này."},{"type":"compound","zh":"因为桥梁承重有限，所以重型车辆禁止通行。","pinyin":"Yīnwèi qiáoliáng chéngzhòng yǒuxiàn, suǒyǐ zhòngxíng chēliàng jìnzhǐ tōngxíng.","vi":"Vì sức chịu tải của cầu có hạn nên xe hạng nặng bị cấm lưu thông."}],"related":[{"hanzi":"轻型","pinyin":"qīngxíng","vi":"loại nhẹ"},{"hanzi":"中型","pinyin":"zhōngxíng","vi":"cỡ vừa"},{"hanzi":"大型","pinyin":"dàxíng","vi":"cỡ lớn"},{"hanzi":"重量级","pinyin":"zhòngliàngjí","vi":"hạng nặng"}]},{"id":"周到","hanzi":"周到","pinyin":"zhōudào","meaning_vi":"chu đáo","explanation":"周 (chu – trọn vẹn khắp nơi) + 到 (đáo – đến) → để ý đến mọi mặt, không bỏ sót điều gì.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🤗","examples":[{"type":"basic","zh":"服务很周到。","pinyin":"Fúwù hěn zhōudào.","vi":"Phục vụ rất chu đáo."},{"type":"simple","zh":"她考虑问题总是非常周到。","pinyin":"Tā kǎolǜ wèntí zǒngshì fēicháng zhōudào.","vi":"Cô ấy suy nghĩ vấn đề lúc nào cũng rất chu đáo."},{"type":"compound","zh":"虽然这家酒店不大，但是服务特别周到。","pinyin":"Suīrán zhè jiā jiǔdiàn búdà, dànshì fúwù tèbié zhōudào.","vi":"Tuy khách sạn này không lớn nhưng phục vụ đặc biệt chu đáo."}],"related":[{"hanzi":"周全","pinyin":"zhōuquán","vi":"chu toàn"},{"hanzi":"细心","pinyin":"xìxīn","vi":"cẩn thận"},{"hanzi":"体贴","pinyin":"tǐtiē","vi":"ân cần"},{"hanzi":"马虎","pinyin":"mǎhu","vi":"qua loa"}]},{"id":"皱","hanzi":"皱","pinyin":"zhòu","meaning_vi":"nhăn, nếp nhăn; cau (mày)","explanation":"皱 (trứu) chỉ nếp nhăn trên da, vải; làm động từ nghĩa là nhăn lại, cau lại (皱眉 – cau mày).","hsk_level":"7-9","tags":["dong-tu"],"image":"😣","examples":[{"type":"basic","zh":"他皱了皱眉头。","pinyin":"Tā zhòule zhòuméitóu.","vi":"Anh ấy khẽ cau mày."},{"type":"simple","zh":"这件衬衫洗完以后全皱了。","pinyin":"Zhè jiàn chènshān xǐ wán yǐhòu quán zhòu le.","vi":"Chiếc áo sơ mi này giặt xong nhăn hết cả."},{"type":"compound","zh":"如果衣服皱得厉害，就用熨斗烫一下。","pinyin":"Rúguǒ yīfu zhòu de lìhai, jiù yòng yùndǒu tàng yíxià.","vi":"Nếu quần áo nhăn nhiều thì dùng bàn là ủi một chút."}],"related":[{"hanzi":"皱纹","pinyin":"zhòuwén","vi":"nếp nhăn"},{"hanzi":"皱眉","pinyin":"zhòuméi","vi":"cau mày"},{"hanzi":"平整","pinyin":"píngzhěng","vi":"phẳng phiu"},{"hanzi":"褶子","pinyin":"zhězi","vi":"nếp gấp"}],"traditional":"皺"},{"id":"朱红","hanzi":"朱红","pinyin":"zhūhóng","meaning_vi":"đỏ son, đỏ chu sa","explanation":"朱 (chu – màu đỏ son) + 红 (hồng – đỏ) → màu đỏ tươi như son, thường thấy trên cửa, cột cung điện.","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🟥","examples":[{"type":"basic","zh":"宫殿的门是朱红色的。","pinyin":"Gōngdiàn de mén shì zhūhóng sè de.","vi":"Cửa cung điện có màu đỏ son."},{"type":"simple","zh":"故宫的墙都刷成了朱红色。","pinyin":"Gùgōng de qiáng dōu shuā chéngle zhūhóng sè.","vi":"Tường Cố Cung đều được sơn màu đỏ son."},{"type":"compound","zh":"因为朱红象征吉祥，所以过年时很多人家贴朱红的对联。","pinyin":"Yīnwèi zhūhóng xiàngzhēng jíxiáng, suǒyǐ guònián shí hěn duō rénjiā tiē zhūhóng de duìlián.","vi":"Vì màu đỏ son tượng trưng cho may mắn nên Tết nhiều nhà dán câu đối đỏ son."}],"related":[{"hanzi":"红色","pinyin":"hóngsè","vi":"màu đỏ"},{"hanzi":"大红","pinyin":"dàhóng","vi":"đỏ tươi"},{"hanzi":"深红","pinyin":"shēnhóng","vi":"đỏ thẫm"},{"hanzi":"朱砂","pinyin":"zhūshā","vi":"chu sa"}],"traditional":"朱紅"},{"id":"诸如此类","hanzi":"诸如此类","pinyin":"zhūrú-cǐlèi","meaning_vi":"những thứ như thế, vân vân","explanation":"诸 (chư – các) + 如 (như) + 此 (thử – này) + 类 (loại) → các thứ giống như loại này; dùng sau khi liệt kê để chỉ còn nhiều thứ tương tự.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"📋","examples":[{"type":"basic","zh":"诸如此类的事很多。","pinyin":"Zhūrúcǐlèi de shì hěn duō.","vi":"Những chuyện như thế này rất nhiều."},{"type":"simple","zh":"他总说迟到、堵车，诸如此类的借口。","pinyin":"Tā zǒng shuō chídào, dǔchē, zhūrúcǐlèi de jièkǒu.","vi":"Anh ta lúc nào cũng viện cớ đến muộn, tắc đường và những lý do tương tự."},{"type":"compound","zh":"虽然诸如此类的问题都不大，但是积累起来就很麻烦。","pinyin":"Suīrán zhūrúcǐlèi de wèntí dōu búdà, dànshì jīlěi qǐlái jiù hěn máfan.","vi":"Tuy những vấn đề kiểu này đều không lớn nhưng tích tụ lại thì rất phiền phức."}],"related":[{"hanzi":"等等","pinyin":"děngděng","vi":"vân vân"},{"hanzi":"之类","pinyin":"zhīlèi","vi":"loại như"},{"hanzi":"如此","pinyin":"rúcǐ","vi":"như thế"},{"hanzi":"类似","pinyin":"lèisì","vi":"tương tự"}],"traditional":"諸如此類"},{"id":"竹竿","hanzi":"竹竿","pinyin":"zhúgān","meaning_vi":"cây sào tre, cần tre","explanation":"竹 (trúc – tre) + 竿 (can – cây sào) → cây tre dài, thẳng, dùng để phơi đồ, chống thuyền...","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"🎋","examples":[{"type":"basic","zh":"奶奶用竹竿晒衣服。","pinyin":"Nǎinai yòng zhúgān shàiyīfu.","vi":"Bà nội dùng sào tre phơi quần áo."},{"type":"simple","zh":"他拿着一根竹竿去打树上的枣。","pinyin":"Tā názhe yìgēn zhúgān qù dǎ shù shàng de zǎo.","vi":"Anh ấy cầm cây sào tre đi đập táo tàu trên cây."},{"type":"compound","zh":"虽然他长得像根竹竿一样瘦，但是力气很大。","pinyin":"Suīrán tā zhǎngde xiàng gēn zhúgān yíyàng shòu, dànshì lìqi hěn dà.","vi":"Tuy anh ấy gầy như cây sào nhưng sức rất khỏe."}],"related":[{"hanzi":"竹子","pinyin":"zhúzi","vi":"cây tre"},{"hanzi":"竹林","pinyin":"zhúlín","vi":"rừng tre"},{"hanzi":"木棍","pinyin":"mùgùn","vi":"gậy gỗ"},{"hanzi":"钓竿","pinyin":"diàogān","vi":"cần câu"}]},{"id":"主","hanzi":"主","pinyin":"zhǔ","meaning_vi":"chủ, người chủ; chính, chủ yếu","explanation":"主 (chủ) là người làm chủ, chủ nhà, người có quyền quyết định; còn mang nghĩa chính yếu (为主 – lấy … làm chính).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"这事你做主吧。","pinyin":"Zhè shì nǐ zuòzhǔ ba.","vi":"Việc này anh quyết định đi."},{"type":"simple","zh":"这家小饭店以卖海鲜为主。","pinyin":"Zhè jiā xiǎo fàndiàn yǐ mài hǎixiān wéizhǔ.","vi":"Quán ăn nhỏ này chủ yếu bán hải sản."},{"type":"compound","zh":"既然你是这里的主人，那么客人就由你来招待。","pinyin":"Jìrán nǐ shì zhèlǐ de zhǔrén, nàme kèrén jiù yóu nǐ lái zhāodài.","vi":"Bạn đã là chủ nhà ở đây thì khách khứa do bạn tiếp đãi."}],"related":[{"hanzi":"主人","pinyin":"zhǔrén","vi":"chủ nhân"},{"hanzi":"做主","pinyin":"zuòzhǔ","vi":"làm chủ, quyết định"},{"hanzi":"主要","pinyin":"zhǔyào","vi":"chủ yếu"},{"hanzi":"客","pinyin":"kè","vi":"khách"}]},{"id":"主编","hanzi":"主编","pinyin":"zhǔbiān","meaning_vi":"tổng biên tập, chủ biên","explanation":"主 (chủ – chính) + 编 (biên – biên soạn) → người phụ trách chính việc biên tập; làm động từ nghĩa là chủ trì biên soạn.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep"],"image":"📰","examples":[{"type":"basic","zh":"她是杂志主编。","pinyin":"Tā shì zázhì zhǔbiān.","vi":"Cô ấy là tổng biên tập tạp chí."},{"type":"simple","zh":"这本词典是王教授主编的。","pinyin":"Zhè běn cídiǎn shì Wáng jiàoshòu zhǔbiān de.","vi":"Cuốn từ điển này do giáo sư Vương chủ biên."},{"type":"compound","zh":"虽然主编很严格，但是大家都很尊敬他。","pinyin":"Suīrán zhǔbiān hěn yángé, dànshì dàjiā dōu hěn zūnjìng tā.","vi":"Tuy tổng biên tập rất nghiêm khắc nhưng mọi người đều kính trọng ông."}],"related":[{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập viên"},{"hanzi":"总编","pinyin":"zǒngbiān","vi":"tổng biên tập"},{"hanzi":"作者","pinyin":"zuòzhě","vi":"tác giả"},{"hanzi":"出版","pinyin":"chūbǎn","vi":"xuất bản"}],"traditional":"主編"},{"id":"主妇","hanzi":"主妇","pinyin":"zhǔfù","meaning_vi":"bà nội trợ, nữ chủ nhân","explanation":"主 (chủ – làm chủ) + 妇 (phụ – người phụ nữ) → người phụ nữ lo việc nhà; hay gặp trong 家庭主妇 (bà nội trợ).","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🏠","examples":[{"type":"basic","zh":"她是家庭主妇。","pinyin":"Tā shì jiātíng zhǔfù.","vi":"Cô ấy là bà nội trợ."},{"type":"simple","zh":"主妇们每天早上都去菜市场买菜。","pinyin":"Zhǔfùmen měitiān zǎo Shangdōu qù càishìchǎng mǎicài.","vi":"Các bà nội trợ sáng nào cũng đi chợ mua thức ăn."},{"type":"compound","zh":"虽然当主妇看起来轻松，但是家务活其实非常累。","pinyin":"Suīrán dāng zhǔfù kànqǐlái qīngsōng, dànshì jiāwùhuó qíshí fēicháng lèi.","vi":"Tuy làm nội trợ trông có vẻ nhẹ nhàng nhưng việc nhà thật ra rất mệt."}],"related":[{"hanzi":"家庭主妇","pinyin":"jiātíngzhǔfù","vi":"bà nội trợ"},{"hanzi":"家务","pinyin":"jiāwù","vi":"việc nhà"},{"hanzi":"女主人","pinyin":"nǚzhǔrén","vi":"nữ chủ nhân"},{"hanzi":"妻子","pinyin":"qīzi","vi":"vợ"}],"traditional":"主婦"},{"id":"主人公","hanzi":"主人公","pinyin":"zhǔréngōng","meaning_vi":"nhân vật chính","explanation":"主人 (chủ nhân) + 公 (công – người) → nhân vật trung tâm của tiểu thuyết, phim ảnh.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🦸","examples":[{"type":"basic","zh":"小说的主人公是个孤儿。","pinyin":"Xiǎoshuō de zhǔréngōng shì ge gū'ér.","vi":"Nhân vật chính của tiểu thuyết là một đứa trẻ mồ côi."},{"type":"simple","zh":"我很喜欢这部电影的主人公。","pinyin":"Wǒ hěn xǐhuan zhè bù diànyǐng de zhǔréngōng.","vi":"Tôi rất thích nhân vật chính của bộ phim này."},{"type":"compound","zh":"虽然主人公最后死了，但是他的精神感动了很多读者。","pinyin":"Suīrán zhǔréngōng zuìhòu sǐle, dànshì tā de jīngshén gǎndòngle hěn duō dúzhě.","vi":"Tuy cuối cùng nhân vật chính chết nhưng tinh thần của anh ấy đã làm cảm động nhiều độc giả."}],"related":[{"hanzi":"主角","pinyin":"zhǔjué","vi":"vai chính"},{"hanzi":"配角","pinyin":"pèijué","vi":"vai phụ"},{"hanzi":"人物","pinyin":"rénwù","vi":"nhân vật"},{"hanzi":"英雄","pinyin":"yīngxióng","vi":"anh hùng"}]},{"id":"主食","hanzi":"主食","pinyin":"zhǔshí","meaning_vi":"lương thực chính, món chính (cơm, mì...)","explanation":"主 (chủ – chính) + 食 (thực – đồ ăn) → thức ăn chính cung cấp năng lượng như cơm, mì, bánh bao.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍚","examples":[{"type":"basic","zh":"越南人的主食是米饭。","pinyin":"Yuènán rén de zhǔshí shì mǐfàn.","vi":"Lương thực chính của người Việt là cơm."},{"type":"simple","zh":"北方人更喜欢把面食当主食。","pinyin":"Běifāng rén gèng xǐhuan bǎ miànshí dāng zhǔshí.","vi":"Người miền Bắc thích lấy đồ làm từ bột mì làm món chính hơn."},{"type":"compound","zh":"如果想减肥，就要少吃主食，多吃蔬菜。","pinyin":"Rúguǒ xiǎng jiǎnféi, jiùyào shǎo chī zhǔshí, duō chī shūcài.","vi":"Nếu muốn giảm cân thì phải ăn ít tinh bột, ăn nhiều rau."}],"related":[{"hanzi":"米饭","pinyin":"mǐfàn","vi":"cơm"},{"hanzi":"面食","pinyin":"miànshí","vi":"đồ ăn làm từ bột mì"},{"hanzi":"副食","pinyin":"fùshí","vi":"thực phẩm phụ"},{"hanzi":"粮食","pinyin":"liángshi","vi":"lương thực"}]},{"id":"主题歌","hanzi":"主题歌","pinyin":"zhǔtígē","meaning_vi":"bài hát chủ đề, nhạc phim","explanation":"主题 (chủ đề) + 歌 (ca – bài hát) → bài hát thể hiện chủ đề của một bộ phim, chương trình hay sự kiện.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎵","examples":[{"type":"basic","zh":"我会唱这首主题歌。","pinyin":"Wǒ huì chàng zhè shǒu zhǔtígē.","vi":"Tôi biết hát bài hát chủ đề này."},{"type":"simple","zh":"这部电视剧的主题歌非常好听。","pinyin":"Zhè bù diànshìjù de zhǔtígē fēicháng hǎotīng.","vi":"Bài hát chủ đề của bộ phim truyền hình này rất hay."},{"type":"compound","zh":"虽然电影早就下映了，但是它的主题歌还在流行。","pinyin":"Suīrán diànyǐng zǎojiù xiàyìng le, dànshì tā de zhǔtígē hái zài liúxíng.","vi":"Tuy bộ phim đã ngừng chiếu từ lâu nhưng bài hát chủ đề của nó vẫn còn thịnh hành."}],"related":[{"hanzi":"主题","pinyin":"zhǔtí","vi":"chủ đề"},{"hanzi":"歌曲","pinyin":"gēqǔ","vi":"bài hát"},{"hanzi":"插曲","pinyin":"chāqǔ","vi":"bài hát lồng trong phim"},{"hanzi":"片尾曲","pinyin":"piànwěiqǔ","vi":"nhạc cuối phim"}],"traditional":"主題歌"},{"id":"主演","hanzi":"主演","pinyin":"zhǔyǎn","meaning_vi":"đóng vai chính; diễn viên chính","explanation":"主 (chủ – chính) + 演 (diễn – diễn xuất) → đóng vai chính trong phim hay vở kịch; cũng chỉ người đóng vai chính.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"她主演过很多电影。","pinyin":"Tā zhǔyǎnguo hěn duō diànyǐng.","vi":"Cô ấy từng đóng vai chính trong nhiều bộ phim."},{"type":"simple","zh":"这部新片由两位年轻演员主演。","pinyin":"Zhè bù xīn piàn yóu liǎng wèi niánqīng yǎnyuán zhǔyǎn.","vi":"Bộ phim mới này do hai diễn viên trẻ đóng vai chính."},{"type":"compound","zh":"因为是他主演的电影，所以票很快就卖完了。","pinyin":"Yīnwèi shì tā zhǔyǎn de diànyǐng, suǒyǐ piào hěn kuài jiù mài wánle.","vi":"Vì là phim anh ấy đóng chính nên vé bán hết rất nhanh."}],"related":[{"hanzi":"主角","pinyin":"zhǔjué","vi":"vai chính"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"导演","pinyin":"dǎoyǎn","vi":"đạo diễn"},{"hanzi":"配角","pinyin":"pèijué","vi":"vai phụ"}]},{"id":"主页","hanzi":"主页","pinyin":"zhǔyè","meaning_vi":"trang chủ","explanation":"主 (chủ – chính) + 页 (hiệt – trang) → trang chính của một website hoặc trang cá nhân trên mạng xã hội.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🏠","examples":[{"type":"basic","zh":"请打开学校主页。","pinyin":"Qǐng dǎkāi xuéxiào zhǔyè.","vi":"Hãy mở trang chủ của trường."},{"type":"simple","zh":"你可以在我的个人主页上留言。","pinyin":"Nǐ kěyǐ zài wǒ de gèrén zhǔyè shàng liúyán.","vi":"Bạn có thể để lại lời nhắn trên trang cá nhân của tôi."},{"type":"compound","zh":"如果找不到报名表，就回到主页重新搜索。","pinyin":"Rúguǒ zhǎobudào bàomíngbiǎo, jiù huídào zhǔyè chóngxīn sōusuǒ.","vi":"Nếu không tìm thấy mẫu đăng ký thì quay lại trang chủ tìm kiếm lại."}],"related":[{"hanzi":"网页","pinyin":"wǎngyè","vi":"trang web"},{"hanzi":"网站","pinyin":"wǎngzhàn","vi":"website"},{"hanzi":"首页","pinyin":"shǒuyè","vi":"trang đầu"},{"hanzi":"链接","pinyin":"liànjiē","vi":"đường liên kết"}],"traditional":"主頁"},{"id":"主义","hanzi":"主义","pinyin":"zhǔyì","meaning_vi":"chủ nghĩa","explanation":"主 (chủ – chính) + 义 (nghĩa – đạo lý) → hệ tư tưởng, học thuyết hay lập trường chủ đạo; đứng sau từ khác tạo thành 'chủ nghĩa…' (浪漫主义 – chủ nghĩa lãng mạn).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📜","examples":[{"type":"basic","zh":"他是个完美主义者。","pinyin":"Tā shì ge wánměi zhǔyì zhě.","vi":"Anh ấy là người theo chủ nghĩa hoàn hảo."},{"type":"simple","zh":"这位诗人的作品充满浪漫主义色彩。","pinyin":"Zhè wèi shīrén de zuòpǐn chōngmǎn làngmàn zhǔyì sècǎi.","vi":"Tác phẩm của nhà thơ này đầy màu sắc chủ nghĩa lãng mạn."},{"type":"compound","zh":"虽然他嘴上反对个人主义，但是做事总是只考虑自己。","pinyin":"Suīrán tā zuǐ shàng fǎnduì gèrénzhǔyì, dànshì zuòshì zǒngshì zhǐ kǎolǜ zìjǐ.","vi":"Tuy ngoài miệng phản đối chủ nghĩa cá nhân nhưng anh ta làm gì cũng chỉ nghĩ cho mình."}],"related":[{"hanzi":"思想","pinyin":"sīxiǎng","vi":"tư tưởng"},{"hanzi":"理论","pinyin":"lǐlùn","vi":"lý luận"},{"hanzi":"个人主义","pinyin":"gèrénzhǔyì","vi":"chủ nghĩa cá nhân"},{"hanzi":"资本主义","pinyin":"zīběnzhǔyì","vi":"chủ nghĩa tư bản"}],"traditional":"主義"},{"id":"主宰","hanzi":"主宰","pinyin":"zhǔzǎi","meaning_vi":"làm chủ, chi phối, thống trị","explanation":"主 (chủ – làm chủ) + 宰 (tể – cai quản) → nắm quyền quyết định, chi phối mọi thứ; cũng chỉ kẻ làm chủ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🎛️","examples":[{"type":"basic","zh":"命运由自己主宰。","pinyin":"Mìngyùn yóu zìjǐ zhǔzǎi.","vi":"Số phận do chính mình làm chủ."},{"type":"simple","zh":"他想主宰公司的一切决定。","pinyin":"Tā xiǎng zhǔzǎi gōngsī de yíqiè juédìng.","vi":"Anh ta muốn chi phối mọi quyết định của công ty."},{"type":"compound","zh":"只要你努力奋斗，就能主宰自己的人生。","pinyin":"Zhǐyào nǐ nǔlì fèndòu, jiù néng zhǔzǎi zìjǐ de rénshēng.","vi":"Chỉ cần nỗ lực phấn đấu, bạn sẽ làm chủ được cuộc đời mình."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"khống chế"},{"hanzi":"支配","pinyin":"zhīpèi","vi":"chi phối"},{"hanzi":"统治","pinyin":"tǒngzhì","vi":"thống trị"},{"hanzi":"掌握","pinyin":"zhǎngwò","vi":"nắm giữ"}]},{"id":"住处","hanzi":"住处","pinyin":"zhùchù","meaning_vi":"chỗ ở, nơi ở","explanation":"住 (trú – ở) + 处 (xứ – nơi) → nơi mình đang ở, chỗ ở.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏘️","examples":[{"type":"basic","zh":"我的住处离公司很近。","pinyin":"Wǒ de zhùchù lí gōngsī hěn jìn.","vi":"Chỗ ở của tôi rất gần công ty."},{"type":"simple","zh":"他刚到北京，还没找到住处。","pinyin":"Tā gāng dào Běijīng, hái méi zhǎodào zhùchù.","vi":"Anh ấy vừa tới Bắc Kinh, vẫn chưa tìm được chỗ ở."},{"type":"compound","zh":"如果你还没有住处，就先住在我家吧。","pinyin":"Rúguǒ nǐ hái méiyǒu zhùchù, jiù xiān zhùzài wǒ jiā ba.","vi":"Nếu bạn chưa có chỗ ở thì cứ ở tạm nhà tôi đi."}],"related":[{"hanzi":"住所","pinyin":"zhùsuǒ","vi":"nơi cư trú"},{"hanzi":"住址","pinyin":"zhùzhǐ","vi":"địa chỉ"},{"hanzi":"宿舍","pinyin":"sùshè","vi":"ký túc xá"},{"hanzi":"房子","pinyin":"fángzi","vi":"nhà"}],"traditional":"住處"},{"id":"住户","hanzi":"住户","pinyin":"zhùhù","meaning_vi":"hộ dân, hộ gia đình (đang cư trú)","explanation":"住 (trú – ở) + 户 (hộ – nhà, hộ) → hộ gia đình đang sống ở một nơi.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"🏢","examples":[{"type":"basic","zh":"这栋楼有五十户住户。","pinyin":"Zhè dòng lóu yǒu wǔshí hù zhùhù.","vi":"Tòa nhà này có năm mươi hộ dân."},{"type":"simple","zh":"楼里的住户都在讨论停电的事。","pinyin":"Lóu lǐ de zhùhù dōu zài tǎolùn tíngdiàn de shì.","vi":"Các hộ trong tòa nhà đều đang bàn chuyện mất điện."},{"type":"compound","zh":"因为电梯坏了，所以高层住户只能走楼梯。","pinyin":"Yīnwèi diàntī huàile, suǒyǐ gāocéng zhùhù zhǐnéng zǒu lóutī.","vi":"Vì thang máy hỏng nên các hộ ở tầng cao chỉ có thể đi thang bộ."}],"related":[{"hanzi":"居民","pinyin":"jūmín","vi":"cư dân"},{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"},{"hanzi":"业主","pinyin":"yèzhǔ","vi":"chủ nhà"},{"hanzi":"小区","pinyin":"xiǎoqū","vi":"khu dân cư"}],"traditional":"住戶"},{"id":"住宿","hanzi":"住宿","pinyin":"zhùsù","meaning_vi":"ở trọ, lưu trú; chỗ ở","explanation":"住 (trú – ở) + 宿 (túc – ngủ qua đêm) → ở lại qua đêm, lưu trú; cũng chỉ chỗ nghỉ.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🛏️","examples":[{"type":"basic","zh":"学校提供住宿。","pinyin":"Xuéxiào tígōng zhùsù.","vi":"Trường có cung cấp chỗ ở."},{"type":"simple","zh":"我们今晚在山下的小旅馆住宿。","pinyin":"Wǒmen jīnwǎn zài Shānxià de xiǎo lǚguǎn zhùsù.","vi":"Tối nay chúng tôi nghỉ lại ở nhà nghỉ nhỏ dưới chân núi."},{"type":"compound","zh":"虽然这里住宿条件一般，但是价格很便宜。","pinyin":"Suīrán zhèlǐ zhùsù tiáojiàn yìbān, dànshì jiàgé hěn piányi.","vi":"Tuy điều kiện lưu trú ở đây bình thường nhưng giá rất rẻ."}],"related":[{"hanzi":"宿舍","pinyin":"sùshè","vi":"ký túc xá"},{"hanzi":"旅馆","pinyin":"lǚguǎn","vi":"nhà nghỉ"},{"hanzi":"住宿费","pinyin":"zhùsùfèi","vi":"tiền phòng"},{"hanzi":"过夜","pinyin":"guòyè","vi":"qua đêm"}]},{"id":"住址","hanzi":"住址","pinyin":"zhùzhǐ","meaning_vi":"địa chỉ (nơi ở)","explanation":"住 (trú – ở) + 址 (chỉ – địa điểm) → địa điểm nơi mình ở, địa chỉ nhà.","hsk_level":"7-9","tags":["danh-tu","nha-cua"],"image":"📮","examples":[{"type":"basic","zh":"请写下你的住址。","pinyin":"Qǐng xiěxià nǐ de zhùzhǐ.","vi":"Hãy viết địa chỉ của bạn."},{"type":"simple","zh":"他搬家以后把新住址告诉了我。","pinyin":"Tā bānjiā yǐhòu bǎ xīn zhùzhǐ gàosule wǒ.","vi":"Sau khi chuyển nhà anh ấy đã cho tôi biết địa chỉ mới."},{"type":"compound","zh":"如果把住址填错了，快递员就送不到你家。","pinyin":"Rúguǒ bǎ zhùzhǐ tián cuò le, kuàidìyuán jiù sòng budào nǐ jiā.","vi":"Nếu điền sai địa chỉ thì nhân viên giao hàng sẽ không giao tới nhà bạn được."}],"related":[{"hanzi":"地址","pinyin":"dìzhǐ","vi":"địa chỉ"},{"hanzi":"住处","pinyin":"zhùchù","vi":"chỗ ở"},{"hanzi":"门牌","pinyin":"ménpái","vi":"biển số nhà"},{"hanzi":"邮编","pinyin":"yóubiān","vi":"mã bưu chính"}]},{"id":"助威","hanzi":"助威","pinyin":"zhùwēi","meaning_vi":"cổ vũ, trợ uy","explanation":"助 (trợ – giúp) + 威 (uy – khí thế) → giúp tăng khí thế, cổ vũ cho đội hay người thi đấu.","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"📣","examples":[{"type":"basic","zh":"我们去给球队助威。","pinyin":"Wǒmen qù gěi qiúduì zhùwēi.","vi":"Chúng tôi đi cổ vũ cho đội bóng."},{"type":"simple","zh":"观众们大声为运动员呐喊助威。","pinyin":"Guānzhòngmen dàshēng wèi yùndòngyuán nàhǎn zhùwēi.","vi":"Khán giả hò hét lớn cổ vũ cho vận động viên."},{"type":"compound","zh":"虽然比赛在外地，但是很多球迷还是赶去助威。","pinyin":"Suīrán bǐsài zài wàidì, dànshì hěn duō qiúmí háishì gǎn qù zhùwēi.","vi":"Tuy trận đấu ở tỉnh khác nhưng nhiều cổ động viên vẫn đến cổ vũ."}],"related":[{"hanzi":"加油","pinyin":"jiāyóu","vi":"cố lên, cổ vũ"},{"hanzi":"呐喊","pinyin":"nàhǎn","vi":"hò hét"},{"hanzi":"鼓励","pinyin":"gǔlì","vi":"động viên"},{"hanzi":"啦啦队","pinyin":"lālāduì","vi":"đội cổ vũ"}]},{"id":"注","hanzi":"注","pinyin":"zhù","meaning_vi":"rót, đổ vào; tiêm; chú ý; chú thích","explanation":"注 (chú) nghĩa gốc là rót nước vào; mở rộng thành dồn vào (注意 – chú ý), tiêm (注射) và ghi chú thích (注解).","hsk_level":"7-9","tags":["dong-tu"],"image":"💉","examples":[{"type":"basic","zh":"他把热水注入瓶中。","pinyin":"Tā bǎ rèshuǐ zhùrù píng zhōng.","vi":"Anh ấy rót nước nóng vào bình."},{"type":"simple","zh":"老师在生词旁边注了拼音。","pinyin":"Lǎoshī zài shēngcí pángbiān zhùle pīnyīn.","vi":"Thầy giáo chú thích phiên âm bên cạnh từ mới."},{"type":"compound","zh":"因为投资人注入了新资金，所以公司又活了过来。","pinyin":"Yīnwèi tóuzīrén zhùrùle xīn zījīn, suǒyǐ gōngsī yòu huóle guòlái.","vi":"Vì nhà đầu tư rót thêm vốn mới nên công ty lại hồi sinh."}],"related":[{"hanzi":"注意","pinyin":"zhùyì","vi":"chú ý"},{"hanzi":"注射","pinyin":"zhùshè","vi":"tiêm"},{"hanzi":"注释","pinyin":"zhùshì","vi":"chú thích"},{"hanzi":"注入","pinyin":"zhùrù","vi":"rót vào"}]},{"id":"贮藏","hanzi":"贮藏","pinyin":"zhùcáng","meaning_vi":"cất trữ, tích trữ, bảo quản","explanation":"贮 (trữ – cất giữ) + 藏 (tàng – cất giấu) → cất giữ đồ vật, lương thực để dùng lâu dài.","hsk_level":"7-9","tags":["dong-tu"],"image":"🥫","examples":[{"type":"basic","zh":"土豆要贮藏在阴凉处。","pinyin":"Tǔdòu yào zhùcáng zài yīnliángchù.","vi":"Khoai tây cần được bảo quản ở nơi thoáng mát."},{"type":"simple","zh":"农民把粮食贮藏在地窖里过冬。","pinyin":"Nóngmín bǎ liángshi zhùcáng zài dìjiào lǐ guòdōng.","vi":"Nông dân cất trữ lương thực trong hầm để qua mùa đông."},{"type":"compound","zh":"如果贮藏方法不对，水果很快就会坏掉。","pinyin":"Rúguǒ zhùcáng fāngfǎ bú duì, shuǐguǒ hěn kuài jiù huì huàidiào.","vi":"Nếu bảo quản không đúng cách thì hoa quả sẽ nhanh hỏng."}],"related":[{"hanzi":"储藏","pinyin":"chǔcáng","vi":"cất giữ"},{"hanzi":"储存","pinyin":"chǔcún","vi":"lưu trữ"},{"hanzi":"保存","pinyin":"bǎocún","vi":"bảo tồn"},{"hanzi":"仓库","pinyin":"cāngkù","vi":"kho"}],"traditional":"貯藏"},{"id":"筑","hanzi":"筑","pinyin":"zhù","meaning_vi":"xây, đắp, xây dựng","explanation":"筑 (trúc) nghĩa là xây, đắp (筑路 – làm đường, 筑巢 – làm tổ); cũng là tên gọi tắt của thành phố Quý Dương.","hsk_level":"7-9","tags":["dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"鸟儿在树上筑巢。","pinyin":"Niǎor zài shù shàng zhùcháo.","vi":"Chim làm tổ trên cây."},{"type":"simple","zh":"工人们正在山里筑一条新公路。","pinyin":"Gōngrénmen zhèngzài shān lǐ zhù yì tiáo xīn gōnglù.","vi":"Công nhân đang làm một con đường mới trong núi."},{"type":"compound","zh":"为了防止洪水，村民们在河边筑起了高高的大堤。","pinyin":"Wèile fángzhǐ hóngshuǐ, cūnmínmen zài hébiān zhù qǐle gāo gāo de dà dī.","vi":"Để phòng lũ, dân làng đã đắp một con đê cao bên bờ sông."}],"related":[{"hanzi":"建筑","pinyin":"jiànzhù","vi":"kiến trúc, xây dựng"},{"hanzi":"修建","pinyin":"xiūjiàn","vi":"xây dựng"},{"hanzi":"构筑","pinyin":"gòuzhù","vi":"xây dựng, dựng lên"},{"hanzi":"筑巢","pinyin":"zhùcháo","vi":"làm tổ"}],"traditional":"築"},{"id":"专柜","hanzi":"专柜","pinyin":"zhuānguì","meaning_vi":"quầy chuyên doanh, quầy hàng riêng","explanation":"专 (chuyên – riêng) + 柜 (quỹ – quầy, tủ) → quầy hàng riêng chỉ bán một loại hay một thương hiệu trong trung tâm thương mại.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"她在化妆品专柜上班。","pinyin":"Tā zài huàzhuāngpǐn zhuānguì shàngbān.","vi":"Cô ấy làm việc ở quầy mỹ phẩm."},{"type":"simple","zh":"这个牌子在商场一楼有专柜。","pinyin":"Zhè ge páizi zài shāngchǎng yī lóu yǒu zhuānguì.","vi":"Thương hiệu này có quầy riêng ở tầng một trung tâm thương mại."},{"type":"compound","zh":"虽然专柜的价格比网上贵，但是质量更有保障。","pinyin":"Suīrán zhuānguì de jiàgé bǐ wǎngshàng guì, dànshì zhìliàng gèng yǒu bǎozhàng.","vi":"Tuy giá ở quầy chính hãng đắt hơn trên mạng nhưng chất lượng được đảm bảo hơn."}],"related":[{"hanzi":"柜台","pinyin":"guìtái","vi":"quầy"},{"hanzi":"专卖店","pinyin":"zhuānmàidiàn","vi":"cửa hàng chuyên doanh"},{"hanzi":"商场","pinyin":"shāngchǎng","vi":"trung tâm thương mại"},{"hanzi":"品牌","pinyin":"pǐnpái","vi":"thương hiệu"}],"traditional":"專櫃"},{"id":"专卖店","hanzi":"专卖店","pinyin":"zhuānmàidiàn","meaning_vi":"cửa hàng chuyên doanh, cửa hàng chính hãng","explanation":"专 (chuyên – riêng) + 卖 (mại – bán) + 店 (điếm – cửa hàng) → cửa hàng chỉ bán sản phẩm của một thương hiệu hay một loại hàng.","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"🏬","examples":[{"type":"basic","zh":"这是一家手机专卖店。","pinyin":"Zhè shì yìjiā shǒujī zhuānmàidiàn.","vi":"Đây là một cửa hàng chuyên bán điện thoại."},{"type":"simple","zh":"我在运动品牌专卖店买了双跑鞋。","pinyin":"Wǒ zài yùndòng pǐnpái zhuānmàidiàn mǎile shuāng pǎoxié.","vi":"Tôi mua một đôi giày chạy ở cửa hàng chính hãng đồ thể thao."},{"type":"compound","zh":"如果担心买到假货，就去官方专卖店买吧。","pinyin":"Rúguǒ dānxīn mǎi dào jiǎhuò, jiù qù guānfāng zhuānmàidiàn mǎi ba.","vi":"Nếu lo mua phải hàng giả thì hãy đến cửa hàng chính hãng mà mua."}],"related":[{"hanzi":"专柜","pinyin":"zhuānguì","vi":"quầy chuyên doanh"},{"hanzi":"商店","pinyin":"shāngdiàn","vi":"cửa hàng"},{"hanzi":"连锁店","pinyin":"liánsuǒdiàn","vi":"chuỗi cửa hàng"},{"hanzi":"旗舰店","pinyin":"qíjiàndiàn","vi":"cửa hàng flagship"}],"traditional":"專賣店"},{"id":"专人","hanzi":"专人","pinyin":"zhuānrén","meaning_vi":"người chuyên trách","explanation":"专 (chuyên – riêng) + 人 (nhân – người) → người được cử riêng để phụ trách một việc cụ thể.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"这件事由专人负责。","pinyin":"Zhè jiàn shìyóu zhuānrén fùzé.","vi":"Việc này do người chuyên trách phụ trách."},{"type":"simple","zh":"公司派专人到机场接客户。","pinyin":"Gōngsī pài zhuānrén dào jīchǎng jiē kèhù.","vi":"Công ty cử người riêng ra sân bay đón khách hàng."},{"type":"compound","zh":"因为设备很复杂，所以需要专人定期维护。","pinyin":"Yīnwèi shèbèi hěn fùzá, suǒyǐ xūyào zhuānrén dìngqī wéihù.","vi":"Vì thiết bị rất phức tạp nên cần có người chuyên trách bảo trì định kỳ."}],"related":[{"hanzi":"专家","pinyin":"zhuānjiā","vi":"chuyên gia"},{"hanzi":"负责人","pinyin":"fùzérén","vi":"người phụ trách"},{"hanzi":"专职","pinyin":"zhuānzhí","vi":"chuyên trách"},{"hanzi":"专门","pinyin":"zhuānmén","vi":"chuyên môn, riêng"}],"traditional":"專人"},{"id":"专著","hanzi":"专著","pinyin":"zhuānzhù","meaning_vi":"chuyên khảo, sách chuyên khảo","explanation":"专 (chuyên – chuyên sâu) + 著 (trứ – tác phẩm) → tác phẩm nghiên cứu chuyên sâu về một vấn đề.","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"他出版了两部专著。","pinyin":"Tā chūbǎnle liǎng bù zhuānzhù.","vi":"Ông ấy đã xuất bản hai cuốn sách chuyên khảo."},{"type":"simple","zh":"这本专著研究的是古代汉语语法。","pinyin":"Zhè běn zhuānzhù yánjiū de shì gǔdài Hànyǔ yǔfǎ.","vi":"Cuốn chuyên khảo này nghiên cứu ngữ pháp Hán ngữ cổ đại."},{"type":"compound","zh":"虽然这本专著很厚，但是写得深入浅出。","pinyin":"Suīrán zhè běn zhuānzhù hěn hòu, dànshì xiě de shēnrùqiǎnchū.","vi":"Tuy cuốn chuyên khảo này rất dày nhưng viết dễ hiểu mà sâu sắc."}],"related":[{"hanzi":"著作","pinyin":"zhùzuò","vi":"tác phẩm"},{"hanzi":"论文","pinyin":"lùnwén","vi":"luận văn"},{"hanzi":"学术","pinyin":"xuéshù","vi":"học thuật"},{"hanzi":"出版","pinyin":"chūbǎn","vi":"xuất bản"}],"traditional":"專著"},{"id":"专职","hanzi":"专职","pinyin":"zhuānzhí","meaning_vi":"chuyên trách, toàn thời gian","explanation":"专 (chuyên – riêng) + 职 (chức – công việc) → chỉ làm riêng một công việc, làm toàn thời gian, trái với 兼职 (kiêm nhiệm).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🧑‍🔧","examples":[{"type":"basic","zh":"她是专职翻译。","pinyin":"Tā shì zhuānzhí fānyì.","vi":"Cô ấy là phiên dịch viên chuyên trách."},{"type":"simple","zh":"学校请了一位专职心理老师。","pinyin":"Xuéxiào qǐngle yí wèi zhuānzhí xīnlǐ lǎoshī.","vi":"Trường mời một giáo viên tâm lý chuyên trách."},{"type":"compound","zh":"虽然兼职比较自由，但是专职的收入更稳定。","pinyin":"Suīrán jiānzhí bǐjiào zìyóu, dànshì zhuānzhí de shōurù gèng wěndìng.","vi":"Tuy làm bán thời gian khá tự do nhưng làm chuyên trách thu nhập ổn định hơn."}],"related":[{"hanzi":"兼职","pinyin":"jiānzhí","vi":"kiêm nhiệm, bán thời gian"},{"hanzi":"全职","pinyin":"quánzhí","vi":"toàn thời gian"},{"hanzi":"专人","pinyin":"zhuānrén","vi":"người chuyên trách"},{"hanzi":"职务","pinyin":"zhíwù","vi":"chức vụ"}],"traditional":"專職"},{"id":"专制","hanzi":"专制","pinyin":"zhuānzhì","meaning_vi":"chuyên chế, độc đoán","explanation":"专 (chuyên – một mình) + 制 (chế – định đoạt) → một người nắm hết quyền định đoạt; chỉ chế độ chuyên chế hoặc tính độc đoán.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"⛓️","examples":[{"type":"basic","zh":"他非常专制。","pinyin":"Tā fēicháng zhuānzhì.","vi":"Ông ta rất độc đoán."},{"type":"simple","zh":"人民最终推翻了专制统治。","pinyin":"Rénmín zuìzhōng tuīfānle zhuānzhì tǒngzhì.","vi":"Nhân dân cuối cùng đã lật đổ ách thống trị chuyên chế."},{"type":"compound","zh":"如果父母过于专制，孩子就容易产生逆反心理。","pinyin":"Rúguǒ fùmǔ guòyú zhuānzhì, háizi jiù róngyì chǎnshēng nìfǎnxīnlǐ.","vi":"Nếu bố mẹ quá độc đoán thì con cái dễ nảy sinh tâm lý chống đối."}],"related":[{"hanzi":"独裁","pinyin":"dúcái","vi":"độc tài"},{"hanzi":"民主","pinyin":"mínzhǔ","vi":"dân chủ"},{"hanzi":"统治","pinyin":"tǒngzhì","vi":"thống trị"},{"hanzi":"霸道","pinyin":"bàdào","vi":"ngang ngược"}],"traditional":"專制"},{"id":"专注","hanzi":"专注","pinyin":"zhuānzhù","meaning_vi":"tập trung, chuyên chú","explanation":"专 (chuyên – một lòng) + 注 (chú – dồn vào) → dồn hết tâm trí vào một việc.","hsk_level":"7-9","tags":["tinh-tu","hoc-tap"],"image":"🎯","examples":[{"type":"basic","zh":"他工作时很专注。","pinyin":"Tā gōngzuò shí hěn zhuānzhù.","vi":"Khi làm việc anh ấy rất tập trung."},{"type":"simple","zh":"孩子专注地看着窗外的小鸟。","pinyin":"Háizi zhuānzhù de kànzhe chuāng wài de xiǎoniǎo.","vi":"Đứa trẻ chăm chú nhìn chú chim nhỏ ngoài cửa sổ."},{"type":"compound","zh":"只有专注于一件事，才能把它做到最好。","pinyin":"Zhǐyǒu zhuānzhù yú yí jiàn shì, cáinéng bǎ tā zuòdào zuìhǎo.","vi":"Chỉ khi tập trung vào một việc mới có thể làm nó tốt nhất."}],"related":[{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"},{"hanzi":"分心","pinyin":"fēnxīn","vi":"phân tâm"},{"hanzi":"注意力","pinyin":"zhùyìlì","vi":"sự chú ý"}],"traditional":"專注"},{"id":"转播","hanzi":"转播","pinyin":"zhuǎnbō","meaning_vi":"tiếp sóng, truyền hình trực tiếp","explanation":"转 (chuyển – chuyển tiếp) + 播 (bá – phát sóng) → phát lại tín hiệu của đài khác, hoặc truyền hình trực tiếp từ hiện trường.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"📡","examples":[{"type":"basic","zh":"电视台转播了比赛。","pinyin":"Diànshìtái zhuǎnbōle bǐsài.","vi":"Đài truyền hình đã tường thuật trận đấu."},{"type":"simple","zh":"今晚八点将现场转播春节晚会。","pinyin":"Jīnwǎn bā diǎnjiāng xiànchǎng zhuǎnbō Chūnjié wǎnhuì.","vi":"Tám giờ tối nay sẽ truyền hình trực tiếp đêm hội mừng xuân."},{"type":"compound","zh":"因为没有买到门票，所以我只能在家看电视转播。","pinyin":"Yīnwèi méiyǒu mǎi dào ménpiào, suǒyǐ wǒ zhǐnéng zài jiā kàn diànshì zhuǎnbō.","vi":"Vì không mua được vé nên tôi chỉ có thể ở nhà xem truyền hình trực tiếp."}],"related":[{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"},{"hanzi":"重播","pinyin":"chóngbō","vi":"phát lại"},{"hanzi":"广播","pinyin":"guǎngbō","vi":"phát thanh"},{"hanzi":"电视台","pinyin":"diànshìtái","vi":"đài truyền hình"}],"traditional":"轉播"},{"id":"转交","hanzi":"转交","pinyin":"zhuǎnjiāo","meaning_vi":"chuyển giao, chuyển hộ","explanation":"转 (chuyển – chuyển qua) + 交 (giao – đưa) → nhận đồ của người này rồi đưa lại cho người khác.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"📨","examples":[{"type":"basic","zh":"请把信转交给他。","pinyin":"Qǐng bǎ xìn zhuǎnjiāo gěi tā.","vi":"Xin chuyển lá thư này cho anh ấy."},{"type":"simple","zh":"这份礼物是同事托我转交的。","pinyin":"Zhè fèn lǐwù shì tóngshì tuō wǒ zhuǎnjiāo de.","vi":"Món quà này là đồng nghiệp nhờ tôi chuyển hộ."},{"type":"compound","zh":"如果老师不在办公室，你就把作业转交给班长。","pinyin":"Rúguǒ lǎoshī bú zài bàngōngshì, nǐ jiù bǎ zuòyè zhuǎnjiāo gěi bānzhǎng.","vi":"Nếu thầy không có ở văn phòng thì em đưa bài tập cho lớp trưởng chuyển giúp."}],"related":[{"hanzi":"转达","pinyin":"zhuǎndá","vi":"chuyển lời"},{"hanzi":"交给","pinyin":"jiāogěi","vi":"giao cho"},{"hanzi":"转告","pinyin":"zhuǎngào","vi":"nhắn lại"},{"hanzi":"递交","pinyin":"dìjiāo","vi":"đệ trình"}],"traditional":"轉交"},{"id":"转学","hanzi":"转学","pinyin":"zhuǎnxué","meaning_vi":"chuyển trường","explanation":"转 (chuyển) + 学 (học – trường học) → chuyển sang học ở trường khác.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"他下学期要转学。","pinyin":"Tā xià xuéqī yào zhuǎnxué.","vi":"Học kỳ sau cậu ấy sẽ chuyển trường."},{"type":"simple","zh":"她是上个月刚转学过来的。","pinyin":"Tā shì shànggeyuè gāng zhuǎnxué guòlái de.","vi":"Cô bé mới chuyển trường đến tháng trước."},{"type":"compound","zh":"因为父母去南方工作了，所以他只好转学。","pinyin":"Yīnwèi fùmǔ qù nánfāng gōngzuò le, suǒyǐ tā zhǐhǎo zhuǎnxué.","vi":"Vì bố mẹ vào miền Nam làm việc nên cậu ấy đành phải chuyển trường."}],"related":[{"hanzi":"转校","pinyin":"zhuǎnxiào","vi":"chuyển trường"},{"hanzi":"插班","pinyin":"chābān","vi":"học chen vào lớp"},{"hanzi":"退学","pinyin":"tuìxué","vi":"thôi học"},{"hanzi":"入学","pinyin":"rùxué","vi":"nhập học"}],"traditional":"轉學"},{"id":"转眼","hanzi":"转眼","pinyin":"zhuǎnyǎn","meaning_vi":"chớp mắt, thoáng chốc","explanation":"转 (chuyển – xoay) + 眼 (nhãn – mắt) → trong khoảnh khắc đảo mắt, chỉ thời gian trôi rất nhanh; hay dùng 转眼间.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⚡","examples":[{"type":"basic","zh":"转眼又到了春节。","pinyin":"Zhuǎnyǎn yòu dàole Chūnjié.","vi":"Chớp mắt đã lại đến Tết."},{"type":"simple","zh":"孩子们转眼间就长大了。","pinyin":"Háizimen zhuǎnyǎnjiān jiù zhǎngdà le.","vi":"Bọn trẻ thoáng chốc đã lớn cả rồi."},{"type":"compound","zh":"虽然感觉刚刚入学，但是转眼就要毕业了。","pinyin":"Suīrán gǎnjué gānggāng rùxué, dànshì zhuǎnyǎn jiùyào bìyè le.","vi":"Tuy cảm giác như vừa mới nhập học nhưng chớp mắt đã sắp tốt nghiệp."}],"related":[{"hanzi":"眨眼","pinyin":"zhǎyǎn","vi":"chớp mắt"},{"hanzi":"瞬间","pinyin":"shùnjiān","vi":"khoảnh khắc"},{"hanzi":"一转眼","pinyin":"yìzhuǎnyǎn","vi":"chớp mắt một cái"},{"hanzi":"转瞬","pinyin":"zhuǎnshùn","vi":"thoáng chốc"}],"traditional":"轉眼"},{"id":"转悠","hanzi":"转悠","pinyin":"zhuànyou","meaning_vi":"đi lòng vòng, lượn lờ; xoay tròn","explanation":"转 (chuyển – xoay vòng) + 悠 (du – lững thững) → đi dạo lòng vòng không mục đích; khẩu ngữ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚶","examples":[{"type":"basic","zh":"我在街上转悠了一下午。","pinyin":"Wǒ zài jiēshàng zhuànyoule yí xiàwǔ.","vi":"Tôi lượn lờ ngoài phố cả buổi chiều."},{"type":"simple","zh":"他吃完饭喜欢在小区里转悠。","pinyin":"Tā chīwán fàn xǐhuan zài xiǎoqū lǐ zhuànyou.","vi":"Ăn cơm xong anh ấy thích đi lòng vòng trong khu nhà."},{"type":"compound","zh":"因为找不到停车位，所以他开着车转悠了半天。","pinyin":"Yīnwèi zhǎobudào tíngchēwèi, suǒyǐ tā kāizhe chē zhuànyoule bàn tiān.","vi":"Vì không tìm được chỗ đỗ xe nên anh ấy lái xe lòng vòng mãi."}],"related":[{"hanzi":"闲逛","pinyin":"xiánguàng","vi":"đi dạo"},{"hanzi":"溜达","pinyin":"liūda","vi":"đi tản bộ"},{"hanzi":"逛街","pinyin":"guàngjiē","vi":"dạo phố"},{"hanzi":"转圈","pinyin":"zhuànquān","vi":"đi vòng quanh"}],"traditional":"轉悠"},{"id":"转载","hanzi":"转载","pinyin":"zhuǎnzǎi","meaning_vi":"đăng lại, đăng tải lại","explanation":"转 (chuyển – chuyển sang) + 载 (tải – đăng) → đăng lại bài đã đăng ở nơi khác.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔗","examples":[{"type":"basic","zh":"本文禁止转载。","pinyin":"Běnwén jìnzhǐ zhuǎnzǎi.","vi":"Bài viết này cấm đăng lại."},{"type":"simple","zh":"这篇文章被很多网站转载了。","pinyin":"Zhè piān wénzhāng bèi hěn duō wǎngzhàn zhuǎnzǎi le.","vi":"Bài viết này đã được nhiều trang web đăng lại."},{"type":"compound","zh":"如果要转载别人的文章，就必须注明出处。","pinyin":"Rúguǒ yào zhuǎnzǎi biérén de wénzhāng, jiù bìxū zhùmíng chūchù.","vi":"Nếu muốn đăng lại bài của người khác thì phải ghi rõ nguồn."}],"related":[{"hanzi":"转发","pinyin":"zhuǎnfā","vi":"chia sẻ, chuyển tiếp"},{"hanzi":"刊登","pinyin":"kāndēng","vi":"đăng báo"},{"hanzi":"原创","pinyin":"yuánchuàng","vi":"nguyên bản"},{"hanzi":"出处","pinyin":"chūchù","vi":"nguồn"}],"traditional":"轉載"},{"id":"庄稼","hanzi":"庄稼","pinyin":"zhuāngjia","meaning_vi":"hoa màu, cây trồng","explanation":"庄 (trang – thôn trang) + 稼 (giá – gieo trồng) → các loại cây lương thực trồng ngoài đồng.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"今年庄稼长得很好。","pinyin":"Jīnnián zhuāngjia zhǎngde hěn hǎo.","vi":"Năm nay hoa màu mọc rất tốt."},{"type":"simple","zh":"一场冰雹毁了村里的庄稼。","pinyin":"Yì chǎng bīngbáo huǐle cūnlǐ de zhuāngjia.","vi":"Một trận mưa đá đã phá hỏng hoa màu trong làng."},{"type":"compound","zh":"如果再不下雨，地里的庄稼就要旱死了。","pinyin":"Rúguǒ zài bú xiàyǔ, dì lǐ de zhuāngjia jiùyào hàn sǐle.","vi":"Nếu không mưa nữa thì hoa màu ngoài đồng sẽ chết khô mất."}],"related":[{"hanzi":"农作物","pinyin":"nóngzuòwù","vi":"cây nông nghiệp"},{"hanzi":"粮食","pinyin":"liángshi","vi":"lương thực"},{"hanzi":"收成","pinyin":"shōucheng","vi":"thu hoạch"},{"hanzi":"种地","pinyin":"zhòngdì","vi":"làm ruộng"}],"traditional":"莊稼"},{"id":"庄园","hanzi":"庄园","pinyin":"zhuāngyuán","meaning_vi":"trang viên, điền trang","explanation":"庄 (trang – thôn trang) + 园 (viên – vườn) → khu đất rộng có nhà ở và vườn ruộng thuộc về một chủ.","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏰","examples":[{"type":"basic","zh":"这座庄园很美。","pinyin":"Zhè zuò zhuāngyuán hěn měi.","vi":"Trang viên này rất đẹp."},{"type":"simple","zh":"他在法国买了一座葡萄酒庄园。","pinyin":"Tā zài Fǎguó mǎile yí zuò pútaojiǔ zhuāngyuán.","vi":"Ông ấy đã mua một trang trại rượu vang ở Pháp."},{"type":"compound","zh":"虽然庄园已经很旧了，但是依然能看出当年的繁华。","pinyin":"Suīrán zhuāngyuán yǐjīng hěn jiù le, dànshì yīrán néng kànchū dāngnián de fánhuá.","vi":"Tuy trang viên đã rất cũ nhưng vẫn thấy được vẻ phồn hoa năm xưa."}],"related":[{"hanzi":"农场","pinyin":"nóngchǎng","vi":"nông trại"},{"hanzi":"别墅","pinyin":"biéshù","vi":"biệt thự"},{"hanzi":"花园","pinyin":"huāyuán","vi":"vườn hoa"},{"hanzi":"地主","pinyin":"dìzhǔ","vi":"địa chủ"}],"traditional":"莊園"},{"id":"桩","hanzi":"桩","pinyin":"zhuāng","meaning_vi":"cọc; (lượng từ) vụ, việc","explanation":"桩 (thung) là cái cọc đóng xuống đất; dùng làm lượng từ cho sự việc (一桩心事 – một nỗi lo, 一桩买卖 – một vụ làm ăn).","hsk_level":"7-9","tags":["luong-tu"],"image":"🪵","examples":[{"type":"basic","zh":"这是一桩好事。","pinyin":"Zhè shì yì zhuāng hǎoshì.","vi":"Đây là một việc tốt."},{"type":"simple","zh":"工人们正在河边打木桩。","pinyin":"Gōngrénmen zhèngzài hébiān dǎ mùzhuāng.","vi":"Công nhân đang đóng cọc gỗ bên bờ sông."},{"type":"compound","zh":"虽然只是一桩小生意，但是他做得非常认真。","pinyin":"Suīrán zhǐshì yì zhuāng xiǎo shēngyi, dànshì tā zuò de fēicháng rènzhēn.","vi":"Tuy chỉ là một vụ làm ăn nhỏ nhưng anh ấy làm rất nghiêm túc."}],"related":[{"hanzi":"木桩","pinyin":"mùzhuāng","vi":"cọc gỗ"},{"hanzi":"件","pinyin":"jiàn","vi":"việc, cái"},{"hanzi":"打桩","pinyin":"dǎzhuāng","vi":"đóng cọc"},{"hanzi":"桩桩件件","pinyin":"zhuāngzhuāngjiànjiàn","vi":"từng việc một"}],"traditional":"樁"},{"id":"壮","hanzi":"壮","pinyin":"zhuàng","meaning_vi":"khỏe mạnh, cường tráng; làm cho mạnh thêm","explanation":"壮 (tráng) nghĩa là khỏe mạnh, to lớn (强壮); làm động từ là làm mạnh thêm (壮胆); cũng là tên dân tộc Choang.","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"💪","examples":[{"type":"basic","zh":"这头牛真壮！","pinyin":"Zhè tóu niú zhēn zhuàng!","vi":"Con bò này khỏe thật!"},{"type":"simple","zh":"邻居家的儿子长得又高又壮。","pinyin":"Lín jūjiā de érzi zhǎngde yòu gāo yòu zhuàng.","vi":"Con trai nhà hàng xóm vừa cao vừa khỏe."},{"type":"compound","zh":"虽然他看起来很壮，但是身体其实不太好。","pinyin":"Suīrán tā kànqǐlái hěn zhuàng, dànshì shēntǐ qíshí bú tài hǎo.","vi":"Tuy trông anh ấy rất vạm vỡ nhưng sức khỏe thực ra không tốt lắm."}],"related":[{"hanzi":"强壮","pinyin":"qiángzhuàng","vi":"cường tráng"},{"hanzi":"健壮","pinyin":"jiànzhuàng","vi":"khỏe mạnh"},{"hanzi":"壮实","pinyin":"zhuàngshi","vi":"chắc nịch"},{"hanzi":"瘦弱","pinyin":"shòuruò","vi":"gầy yếu"}],"traditional":"壯"},{"id":"壮胆","hanzi":"壮胆","pinyin":"zhuàngdǎn","meaning_vi":"lấy thêm can đảm, làm vững dạ","explanation":"壮 (tráng – làm mạnh) + 胆 (đảm – mật, lá gan) → làm cho gan dạ hơn, thêm can đảm.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🦁","examples":[{"type":"basic","zh":"我陪你去壮壮胆。","pinyin":"Wǒ péi nǐ qù zhuàng zhuangdǎn.","vi":"Tôi đi cùng cho bạn vững dạ."},{"type":"simple","zh":"他喝了两杯酒给自己壮胆。","pinyin":"Tā hēle liǎng bēi jiǔ gěi zìjǐ zhuàngdǎn.","vi":"Anh ấy uống hai ly rượu để lấy thêm can đảm."},{"type":"compound","zh":"因为一个人走夜路害怕，所以她一边走一边唱歌壮胆。","pinyin":"Yīnwèi yígèrén zǒu yè lù hàipà, suǒyǐ tā yìbiān zǒu yìbiān chànggē zhuàngdǎn.","vi":"Vì sợ đi đường đêm một mình nên cô ấy vừa đi vừa hát cho đỡ sợ."}],"related":[{"hanzi":"胆子","pinyin":"dǎnzi","vi":"lá gan"},{"hanzi":"胆量","pinyin":"dǎnliàng","vi":"lòng can đảm"},{"hanzi":"大胆","pinyin":"dàdǎn","vi":"bạo dạn"},{"hanzi":"胆小","pinyin":"dǎnxiǎo","vi":"nhát gan"}],"traditional":"壯膽"},{"id":"壮实","hanzi":"壮实","pinyin":"zhuàngshi","meaning_vi":"chắc nịch, khỏe mạnh","explanation":"壮 (tráng – khỏe) + 实 (thực – chắc) → thân hình khỏe mạnh, rắn chắc; khẩu ngữ.","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"🏋️","examples":[{"type":"basic","zh":"这孩子长得真壮实。","pinyin":"Zhè háizi zhǎngde zhēn zhuàngshi.","vi":"Đứa bé này trông thật chắc nịch."},{"type":"simple","zh":"干了一年农活，他变得壮实多了。","pinyin":"Gànle yì nián nónghuó, tā biànde zhuàngshi duō le.","vi":"Làm việc đồng áng một năm, anh ấy rắn chắc hơn nhiều."},{"type":"compound","zh":"虽然他个子不高，但是身体非常壮实。","pinyin":"Suīrán tā gèzi bù gāo, dànshì shēntǐ fēicháng zhuàngshi.","vi":"Tuy anh ấy không cao nhưng thân hình rất rắn chắc."}],"related":[{"hanzi":"结实","pinyin":"jiēshi","vi":"chắc khỏe"},{"hanzi":"强壮","pinyin":"qiángzhuàng","vi":"cường tráng"},{"hanzi":"健壮","pinyin":"jiànzhuàng","vi":"khỏe mạnh"},{"hanzi":"瘦弱","pinyin":"shòuruò","vi":"gầy yếu"}],"traditional":"壯實"},{"id":"撞击","hanzi":"撞击","pinyin":"zhuàngjī","meaning_vi":"va đập, đâm vào","explanation":"撞 (chàng – đâm) + 击 (kích – đánh) → va mạnh vào nhau, đâm vào.","hsk_level":"7-9","tags":["dong-tu"],"image":"💢","examples":[{"type":"basic","zh":"海浪撞击着岩石。","pinyin":"Hǎilàng zhuàngjīzhe yánshí.","vi":"Sóng biển đập vào đá."},{"type":"simple","zh":"两辆车发生了猛烈的撞击。","pinyin":"Liǎng liàng chē fāshēngle měngliè de zhuàngjī.","vi":"Hai chiếc xe đã va chạm dữ dội."},{"type":"compound","zh":"虽然受到了强烈撞击，但是这部手机居然没坏。","pinyin":"Suīrán shòudàole qiángliè zhuàngjī, dànshì zhè bù shǒujī jūrán méi huài.","vi":"Tuy bị va đập mạnh nhưng chiếc điện thoại này lại không hỏng."}],"related":[{"hanzi":"碰撞","pinyin":"pèngzhuàng","vi":"va chạm"},{"hanzi":"冲击","pinyin":"chōngjī","vi":"tác động mạnh"},{"hanzi":"撞车","pinyin":"zhuàngchē","vi":"đâm xe"},{"hanzi":"敲击","pinyin":"qiāojī","vi":"gõ, đập"}],"traditional":"撞擊"},{"id":"追悼会","hanzi":"追悼会","pinyin":"zhuīdàohuì","meaning_vi":"lễ truy điệu","explanation":"追 (truy – nhớ về) + 悼 (điệu – thương tiếc) + 会 (hội – buổi lễ) → buổi lễ tưởng niệm người đã khuất.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🕯️","examples":[{"type":"basic","zh":"他参加了追悼会。","pinyin":"Tā cānjiāle zhuīdàohuì.","vi":"Anh ấy đã dự lễ truy điệu."},{"type":"simple","zh":"学校为老校长举行了追悼会。","pinyin":"Xuéxiào wèi lǎo xiàozhǎng jǔxíngle zhuīdàohuì.","vi":"Nhà trường tổ chức lễ truy điệu cho thầy hiệu trưởng cũ."},{"type":"compound","zh":"虽然追悼会很简单，但是来了很多他教过的学生。","pinyin":"Suīrán zhuīdàohuì hěn jiǎndān, dànshì láile hěn duō tā jiāoguo de xuésheng.","vi":"Tuy lễ truy điệu rất đơn giản nhưng có rất nhiều học trò ông từng dạy đến dự."}],"related":[{"hanzi":"葬礼","pinyin":"zànglǐ","vi":"tang lễ"},{"hanzi":"悼念","pinyin":"dàoniàn","vi":"tưởng niệm"},{"hanzi":"哀悼","pinyin":"āidào","vi":"thương tiếc"},{"hanzi":"纪念","pinyin":"jìniàn","vi":"kỷ niệm"}],"traditional":"追悼會"},{"id":"追赶","hanzi":"追赶","pinyin":"zhuīgǎn","meaning_vi":"đuổi theo, bắt kịp","explanation":"追 (truy – đuổi) + 赶 (cản – đuổi kịp) → đuổi theo cho kịp; nghĩa bóng là cố gắng bắt kịp người đi trước.","hsk_level":"7-9","tags":["dong-tu"],"image":"🏃‍♂️","examples":[{"type":"basic","zh":"警察在追赶小偷。","pinyin":"Jǐngchá zài zhuīgǎn xiǎotōu.","vi":"Cảnh sát đang đuổi theo tên trộm."},{"type":"simple","zh":"我们要努力追赶世界先进水平。","pinyin":"Wǒmen yào nǔlì zhuīgǎn shìjiè xiānjìn shuǐpíng.","vi":"Chúng ta phải nỗ lực bắt kịp trình độ tiên tiến thế giới."},{"type":"compound","zh":"虽然他落后了很多，但是一直在拼命追赶。","pinyin":"Suīrán tā luòhòule hěn duō, dànshì yìzhí zài pīnmìng zhuīgǎn.","vi":"Tuy anh ấy tụt lại khá xa nhưng vẫn luôn liều mạng đuổi theo."}],"related":[{"hanzi":"追","pinyin":"zhuī","vi":"đuổi"},{"hanzi":"赶上","pinyin":"gǎnshàng","vi":"đuổi kịp"},{"hanzi":"追逐","pinyin":"zhuīzhú","vi":"rượt đuổi"},{"hanzi":"落后","pinyin":"luòhòu","vi":"tụt hậu"}],"traditional":"追趕"},{"id":"追随","hanzi":"追随","pinyin":"zhuīsuí","meaning_vi":"đi theo, theo đuổi, theo gót","explanation":"追 (truy – đuổi theo) + 随 (tùy – đi theo) → đi theo ai, theo đuổi lý tưởng hay người mình ngưỡng mộ.","hsk_level":"7-9","tags":["dong-tu"],"image":"👣","examples":[{"type":"basic","zh":"他一直追随老师。","pinyin":"Tā yìzhí zhuīsuí lǎoshī.","vi":"Anh ấy luôn đi theo thầy."},{"type":"simple","zh":"很多年轻人追随他的脚步去了西部。","pinyin":"Hěn duō niánqīngrén zhuīsuí tā de jiǎobù qùle Xībù.","vi":"Nhiều thanh niên theo bước chân ông lên miền Tây."},{"type":"compound","zh":"虽然生活很艰苦，但是他们始终追随自己的梦想。","pinyin":"Suīrán shēnghuó hěn jiānkǔ, dànshì tāmen shǐzhōng zhuīsuí zìjǐ de mèngxiǎng.","vi":"Tuy cuộc sống rất gian khổ nhưng họ vẫn luôn theo đuổi ước mơ của mình."}],"related":[{"hanzi":"跟随","pinyin":"gēnsuí","vi":"đi theo"},{"hanzi":"追随者","pinyin":"zhuīsuízhě","vi":"người theo đuổi"},{"hanzi":"追求","pinyin":"zhuīqiú","vi":"theo đuổi"},{"hanzi":"效仿","pinyin":"xiàofǎng","vi":"bắt chước"}],"traditional":"追隨"},{"id":"追尾","hanzi":"追尾","pinyin":"zhuīwěi","meaning_vi":"đâm vào đuôi xe, tông đuôi","explanation":"追 (truy – đuổi theo) + 尾 (vĩ – đuôi) → xe phía sau đâm vào đuôi xe phía trước.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚗","examples":[{"type":"basic","zh":"前面两辆车追尾了。","pinyin":"Qiánmiàn liǎng liàng chē zhuīwěi le.","vi":"Phía trước có hai chiếc xe tông đuôi nhau."},{"type":"simple","zh":"下雨天路滑，很容易发生追尾。","pinyin":"Xià yǔtiān lù huá, hěn róngyì fāshēng zhuīwěi.","vi":"Trời mưa đường trơn, rất dễ xảy ra tông đuôi xe."},{"type":"compound","zh":"如果跟车太近，一旦前车刹车，就很容易追尾。","pinyin":"Rúguǒ gēn chē tài jìn, yídàn qián chē shāchē, jiù hěn róngyì zhuīwěi.","vi":"Nếu bám xe quá gần, một khi xe trước phanh thì rất dễ đâm vào đuôi."}],"related":[{"hanzi":"撞车","pinyin":"zhuàngchē","vi":"đâm xe"},{"hanzi":"车祸","pinyin":"chēhuò","vi":"tai nạn xe"},{"hanzi":"刹车","pinyin":"shāchē","vi":"phanh xe"},{"hanzi":"车距","pinyin":"chējù","vi":"khoảng cách xe"}]},{"id":"追问","hanzi":"追问","pinyin":"zhuīwèn","meaning_vi":"hỏi dồn, gặng hỏi","explanation":"追 (truy – đuổi theo) + 问 (vấn – hỏi) → hỏi tiếp, hỏi đến cùng để biết rõ.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🕵️","examples":[{"type":"basic","zh":"妈妈追问他去哪儿了。","pinyin":"Māma zhuīwèn tā qùnǎr le.","vi":"Mẹ gặng hỏi cậu ấy đã đi đâu."},{"type":"simple","zh":"记者不停地追问事故的原因。","pinyin":"Jìzhě bùtíng de zhuīwèn shìgù de yuányīn.","vi":"Phóng viên liên tục gặng hỏi nguyên nhân vụ tai nạn."},{"type":"compound","zh":"虽然大家一再追问，但是他始终不肯说出真相。","pinyin":"Suīrán dàjiā yízài zhuīwèn, dànshì tā shǐzhōng bùkěn shuōchū zhēnxiàng.","vi":"Tuy mọi người hỏi dồn mãi nhưng anh ấy vẫn không chịu nói ra sự thật."}],"related":[{"hanzi":"询问","pinyin":"xúnwèn","vi":"hỏi han"},{"hanzi":"质问","pinyin":"zhìwèn","vi":"chất vấn"},{"hanzi":"盘问","pinyin":"pánwèn","vi":"tra hỏi"},{"hanzi":"追究","pinyin":"zhuījiū","vi":"truy cứu"}],"traditional":"追問"},{"id":"追逐","hanzi":"追逐","pinyin":"zhuīzhú","meaning_vi":"rượt đuổi; theo đuổi","explanation":"追 (truy – đuổi) + 逐 (trục – đuổi theo) → chạy đuổi nhau; nghĩa bóng là ra sức theo đuổi (danh lợi, ước mơ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🐕","examples":[{"type":"basic","zh":"孩子们在草地上追逐。","pinyin":"Háizimen zài cǎo dìshàng zhuīzhú.","vi":"Bọn trẻ rượt đuổi nhau trên bãi cỏ."},{"type":"simple","zh":"年轻人应该勇敢地追逐梦想。","pinyin":"Niánqīngrén yīnggāi yǒnggǎn de zhuīzhú mèngxiǎng.","vi":"Người trẻ nên dũng cảm theo đuổi ước mơ."},{"type":"compound","zh":"如果一味追逐名利，就会失去生活的乐趣。","pinyin":"Rúguǒ yíwèi zhuīzhú mínglì, jiù huì shīqù shēnghuó de lèqù.","vi":"Nếu chỉ mải theo đuổi danh lợi thì sẽ mất đi niềm vui cuộc sống."}],"related":[{"hanzi":"追赶","pinyin":"zhuīgǎn","vi":"đuổi theo"},{"hanzi":"追求","pinyin":"zhuīqiú","vi":"theo đuổi"},{"hanzi":"奔跑","pinyin":"bēnpǎo","vi":"chạy"},{"hanzi":"嬉戏","pinyin":"xīxì","vi":"nô đùa"}]},{"id":"追踪","hanzi":"追踪","pinyin":"zhuīzōng","meaning_vi":"theo dấu, truy vết, theo dõi","explanation":"追 (truy – đuổi theo) + 踪 (tung – dấu vết) → lần theo dấu vết; cũng chỉ theo dõi diễn biến (追踪报道 – tường thuật theo dõi).","hsk_level":"7-9","tags":["dong-tu"],"image":"📍","examples":[{"type":"basic","zh":"警方正在追踪逃犯。","pinyin":"Jǐngfāng zhèngzài zhuīzōng táofàn.","vi":"Cảnh sát đang truy vết kẻ chạy trốn."},{"type":"simple","zh":"你可以在网上追踪快递的位置。","pinyin":"Nǐ kěyǐ zài wǎngshàng zhuīzōng kuàidì de wèizhì.","vi":"Bạn có thể theo dõi vị trí bưu kiện trên mạng."},{"type":"compound","zh":"只要手机开着，就能追踪到他的位置。","pinyin":"Zhǐyào shǒujī kāi zhe, jiù néng zhuīzōng dào tā de wèizhì.","vi":"Chỉ cần điện thoại còn mở là có thể truy ra vị trí của anh ta."}],"related":[{"hanzi":"跟踪","pinyin":"gēnzōng","vi":"bám theo"},{"hanzi":"踪迹","pinyin":"zōngjì","vi":"dấu vết"},{"hanzi":"定位","pinyin":"dìngwèi","vi":"định vị"},{"hanzi":"追查","pinyin":"zhuīchá","vi":"truy tra"}],"traditional":"追蹤"},{"id":"坠","hanzi":"坠","pinyin":"zhuì","meaning_vi":"rơi, rớt; trĩu xuống","explanation":"坠 (trụy) nghĩa là rơi từ trên cao xuống (坠落, 坠机 – rơi máy bay), hoặc vật nặng làm trĩu xuống.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"一颗流星坠落了。","pinyin":"Yì kē liúxīng zhuìluò le.","vi":"Một ngôi sao băng đã rơi xuống."},{"type":"simple","zh":"苹果把树枝坠得弯弯的。","pinyin":"Píngguǒ bǎ shùzhī zhuì de Wānwān de.","vi":"Táo làm cành cây trĩu cong xuống."},{"type":"compound","zh":"因为发动机出了故障，所以那架飞机坠入了大海。","pinyin":"Yīnwèi fādòngjī chūle gùzhàng, suǒyǐ nà jià fēijī zhuìrùle dàhǎi.","vi":"Vì động cơ gặp sự cố nên chiếc máy bay đó đã rơi xuống biển."}],"related":[{"hanzi":"坠落","pinyin":"zhuìluò","vi":"rơi xuống"},{"hanzi":"掉","pinyin":"diào","vi":"rơi"},{"hanzi":"下坠","pinyin":"xiàzhuì","vi":"rơi xuống"},{"hanzi":"坠机","pinyin":"zhuìjī","vi":"rơi máy bay"}],"traditional":"墜"},{"id":"准许","hanzi":"准许","pinyin":"zhǔnxǔ","meaning_vi":"cho phép, chuẩn y","explanation":"准 (chuẩn – đồng ý) + 许 (hứa – cho phép) → đồng ý cho làm việc gì.","hsk_level":"7-9","tags":["dong-tu"],"image":"✅","examples":[{"type":"basic","zh":"这里不准许抽烟。","pinyin":"Zhèlǐ bù zhǔnxǔ chōuyān.","vi":"Ở đây không cho phép hút thuốc."},{"type":"simple","zh":"老师准许他提前半小时交卷。","pinyin":"Lǎoshī zhǔnxǔ tā tíqián bànxiǎoshí jiāojuàn.","vi":"Thầy giáo cho phép cậu ấy nộp bài sớm nửa tiếng."},{"type":"compound","zh":"如果没有经过父母准许，孩子不能单独出门。","pinyin":"Rúguǒ méiyǒu jīngguò fùmǔ zhǔnxǔ, háizi bù néng dāndú chūmén.","vi":"Nếu chưa được bố mẹ cho phép thì trẻ không được ra ngoài một mình."}],"related":[{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"cho phép"},{"hanzi":"批准","pinyin":"pīzhǔn","vi":"phê chuẩn"},{"hanzi":"许可","pinyin":"xǔkě","vi":"cho phép"},{"hanzi":"禁止","pinyin":"jìnzhǐ","vi":"cấm"}],"traditional":"准許"},{"id":"捉迷藏","hanzi":"捉迷藏","pinyin":"zhuōmícáng","meaning_vi":"chơi trốn tìm","explanation":"捉 (tróc – bắt) + 迷 (mê – lạc) + 藏 (tàng – trốn) → trò chơi một người đi tìm bắt những người trốn; nghĩa bóng là vòng vo, không nói thẳng.","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🙈","examples":[{"type":"basic","zh":"我们来玩捉迷藏吧！","pinyin":"Wǒmen lái wán zhuōmícáng ba!","vi":"Chúng mình chơi trốn tìm đi!"},{"type":"simple","zh":"孩子们在院子里捉迷藏。","pinyin":"Háizimen zài yuànzi lǐ zhuōmícáng.","vi":"Bọn trẻ chơi trốn tìm trong sân."},{"type":"compound","zh":"既然你有话要说，就直说吧，别跟我捉迷藏了。","pinyin":"Jìrán nǐ yǒu huà yào shuō, jiù zhíshuō ba, bié gēn wǒ zhuōmícáng le.","vi":"Anh đã có điều muốn nói thì cứ nói thẳng, đừng vòng vo với tôi nữa."}],"related":[{"hanzi":"游戏","pinyin":"yóuxì","vi":"trò chơi"},{"hanzi":"躲藏","pinyin":"duǒcáng","vi":"ẩn nấp"},{"hanzi":"藏","pinyin":"cáng","vi":"trốn"},{"hanzi":"玩耍","pinyin":"wánshuǎ","vi":"chơi đùa"}]},{"id":"灼热","hanzi":"灼热","pinyin":"zhuórè","meaning_vi":"nóng rát, nóng bỏng","explanation":"灼 (chước – đốt, cháy) + 热 (nhiệt – nóng) → nóng như bị lửa đốt.","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🔥","examples":[{"type":"basic","zh":"沙滩灼热得烫脚。","pinyin":"Shātān zhuórè de tàng jiǎo.","vi":"Bãi cát nóng rát đến bỏng chân."},{"type":"simple","zh":"夏天中午的阳光十分灼热。","pinyin":"Xiàtiān zhōngwǔ de yángguāng shífēn zhuórè.","vi":"Nắng trưa mùa hè vô cùng nóng rát."},{"type":"compound","zh":"虽然伤口已经处理了，但是还有一种灼热的感觉。","pinyin":"Suīrán shāngkǒu yǐjīng chǔlǐ le, dànshì háiyǒu yì zhǒng zhuórè de gǎnjué.","vi":"Tuy vết thương đã được xử lý nhưng vẫn còn cảm giác nóng rát."}],"related":[{"hanzi":"炎热","pinyin":"yánrè","vi":"nóng bức"},{"hanzi":"滚烫","pinyin":"gǔntàng","vi":"nóng bỏng"},{"hanzi":"烧灼","pinyin":"shāozhuó","vi":"thiêu đốt"},{"hanzi":"酷热","pinyin":"kùrè","vi":"nóng gắt"}],"traditional":"灼熱"},{"id":"酌情","hanzi":"酌情","pinyin":"zhuóqíng","meaning_vi":"tùy tình hình, cân nhắc tình hình","explanation":"酌 (chước – cân nhắc) + 情 (tình – tình hình) → cân nhắc tình hình thực tế mà xử lý; văn viết.","hsk_level":"7-9","tags":["pho-tu"],"image":"🤔","examples":[{"type":"basic","zh":"请酌情处理。","pinyin":"Qǐng zhuóqíng chǔlǐ.","vi":"Xin tùy tình hình mà xử lý."},{"type":"simple","zh":"法院会酌情减轻他的处罚。","pinyin":"Fǎyuàn huì zhuóqíng jiǎnqīng tā de chǔfá.","vi":"Tòa án sẽ cân nhắc tình hình để giảm nhẹ hình phạt cho anh ta."},{"type":"compound","zh":"如果病人情况好转，医生就会酌情减少药量。","pinyin":"Rúguǒ bìngrén qíngkuàng hǎozhuǎn, yīshēng jiù huì zhuóqíng jiǎnshǎo yào liàng.","vi":"Nếu bệnh nhân chuyển biến tốt, bác sĩ sẽ tùy tình hình giảm liều thuốc."}],"related":[{"hanzi":"斟酌","pinyin":"zhēnzhuó","vi":"cân nhắc"},{"hanzi":"酌量","pinyin":"zhuóliàng","vi":"liệu chừng"},{"hanzi":"视情况","pinyin":"shìqíngkuàng","vi":"tùy tình hình"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"}]},{"id":"兹","hanzi":"兹","pinyin":"zī","meaning_vi":"nay, này, đây (văn viết)","explanation":"兹 (tư) là từ văn ngôn nghĩa là 'này, nay'; nay chủ yếu gặp trong văn bản hành chính như 兹定于 (nay quyết định vào…), 兹证明 (nay chứng nhận).","hsk_level":"7-9","tags":["dai-tu"],"image":"📜","examples":[{"type":"basic","zh":"兹证明此人是我校学生。","pinyin":"Zī zhèngmíng cǐ rén shì wǒ xiào xuésheng.","vi":"Nay chứng nhận người này là học sinh trường tôi."},{"type":"simple","zh":"兹定于本周五召开全体大会。","pinyin":"Zī dìngyú běn Zhōuwǔ zhàokāi quántǐ dàhuì.","vi":"Nay quyết định triệu tập đại hội toàn thể vào thứ sáu tuần này."},{"type":"compound","zh":"由于原经理已调往总部，兹任命张先生为新经理。","pinyin":"Yóuyú yuán jīnglǐ yǐ diào wǎng zǒngbù, zī rènmìng Zhāng xiānsheng wéi xīn jīnglǐ.","vi":"Do giám đốc cũ đã được điều về trụ sở chính, nay bổ nhiệm ông Trương làm giám đốc mới."}],"related":[{"hanzi":"此","pinyin":"cǐ","vi":"này"},{"hanzi":"念兹在兹","pinyin":"niànzīzàizī","vi":"luôn canh cánh trong lòng"},{"hanzi":"今","pinyin":"jīn","vi":"nay"},{"hanzi":"特此","pinyin":"tècǐ","vi":"nay đặc biệt"}],"traditional":"茲"},{"id":"姿势","hanzi":"姿势","pinyin":"zīshì","meaning_vi":"tư thế, dáng điệu","explanation":"姿 (tư – dáng vẻ) + 势 (thế – thế đứng) → dáng vẻ, cách đặt thân người khi đứng, ngồi, vận động.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🧘","examples":[{"type":"basic","zh":"这个姿势很舒服。","pinyin":"Zhè ge zīshì hěn shūfu.","vi":"Tư thế này rất thoải mái."},{"type":"simple","zh":"摄影师让她换了好几个姿势。","pinyin":"Shèyǐngshī ràng tā huànle hǎojǐ ge zīshì.","vi":"Nhiếp ảnh gia bảo cô ấy đổi mấy tư thế liền."},{"type":"compound","zh":"如果睡觉的姿势不正确，第二天就容易脖子疼。","pinyin":"Rúguǒ shuìjiào de zīshì bú zhèngquè, dì'èrtiān jiù róngyì bózi téng.","vi":"Nếu tư thế ngủ không đúng thì hôm sau dễ bị đau cổ."}],"related":[{"hanzi":"姿态","pinyin":"zītài","vi":"tư thế, thái độ"},{"hanzi":"动作","pinyin":"dòngzuò","vi":"động tác"},{"hanzi":"坐姿","pinyin":"zuòzī","vi":"tư thế ngồi"},{"hanzi":"手势","pinyin":"shǒushì","vi":"cử chỉ tay"}],"traditional":"姿勢"},{"id":"资本主义","hanzi":"资本主义","pinyin":"zīběnzhǔyì","meaning_vi":"chủ nghĩa tư bản","explanation":"资本 (tư bản – vốn) + 主义 (chủ nghĩa) → chế độ kinh tế xã hội lấy sở hữu tư nhân về tư liệu sản xuất và thị trường làm nền tảng.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏦","examples":[{"type":"basic","zh":"他研究资本主义经济。","pinyin":"Tā yánjiū zīběnzhǔyì jīngjì.","vi":"Ông ấy nghiên cứu kinh tế tư bản chủ nghĩa."},{"type":"simple","zh":"资本主义最早出现在欧洲。","pinyin":"Zīběnzhǔyì zuì zǎo chū xiànzài Ōuzhōu.","vi":"Chủ nghĩa tư bản xuất hiện sớm nhất ở châu Âu."},{"type":"compound","zh":"虽然资本主义推动了生产力发展，但是也带来了贫富差距。","pinyin":"Suīrán zīběnzhǔyì tuīdòngle shēngchǎnlì fāzhǎn, dànshì yě dàiláile pínfùchājù.","vi":"Tuy chủ nghĩa tư bản thúc đẩy lực lượng sản xuất phát triển nhưng cũng gây ra chênh lệch giàu nghèo."}],"related":[{"hanzi":"社会主义","pinyin":"shèhuìzhǔyì","vi":"chủ nghĩa xã hội"},{"hanzi":"资本","pinyin":"zīběn","vi":"tư bản, vốn"},{"hanzi":"市场经济","pinyin":"shìchǎngjīngjì","vi":"kinh tế thị trường"},{"hanzi":"主义","pinyin":"zhǔyì","vi":"chủ nghĩa"}],"traditional":"資本主義"},{"id":"资历","hanzi":"资历","pinyin":"zīlì","meaning_vi":"lý lịch, kinh nghiệm, thâm niên","explanation":"资 (tư – tư cách) + 历 (lịch – trải qua) → tư cách và quá trình công tác đã trải qua, thâm niên.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📄","examples":[{"type":"basic","zh":"他的资历很深。","pinyin":"Tā de zīlì hěn shēn.","vi":"Thâm niên của ông ấy rất cao."},{"type":"simple","zh":"她凭借丰富的资历当上了主管。","pinyin":"Tā píngjiè fēngfù de zīlì dāngshàngle zhǔguǎn.","vi":"Cô ấy dựa vào kinh nghiệm dày dặn để trở thành trưởng bộ phận."},{"type":"compound","zh":"虽然他资历比较浅，但是能力非常强。","pinyin":"Suīrán tā zīlì bǐjiào qiǎn, dànshì nénglì fēicháng qiáng.","vi":"Tuy anh ấy thâm niên còn ít nhưng năng lực rất mạnh."}],"related":[{"hanzi":"经历","pinyin":"jīnglì","vi":"kinh nghiệm, trải qua"},{"hanzi":"资格","pinyin":"zīgé","vi":"tư cách"},{"hanzi":"经验","pinyin":"jīngyàn","vi":"kinh nghiệm"},{"hanzi":"履历","pinyin":"lǚlì","vi":"lý lịch"}],"traditional":"資歷"},{"id":"资讯","hanzi":"资讯","pinyin":"zīxùn","meaning_vi":"thông tin, tin tức","explanation":"资 (tư – tư liệu) + 讯 (tấn – tin tức) → thông tin, tin tức nói chung, nhất là tin trên mạng.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📲","examples":[{"type":"basic","zh":"我每天看财经资讯。","pinyin":"Wǒ měitiān kàn cáijīng zīxùn.","vi":"Ngày nào tôi cũng xem tin tức tài chính."},{"type":"simple","zh":"手机让我们随时获取最新资讯。","pinyin":"Shǒujī ràng wǒmen suíshí huòqǔ zuì xīn zīxùn.","vi":"Điện thoại giúp chúng ta nắm bắt thông tin mới nhất mọi lúc."},{"type":"compound","zh":"虽然网上资讯很多，但是真假需要自己判断。","pinyin":"Suīrán wǎngshàng zīxùn hěn duō, dànshì zhēnjiǎ xūyào zìjǐ pànduàn.","vi":"Tuy thông tin trên mạng rất nhiều nhưng thật giả phải tự mình phán đoán."}],"related":[{"hanzi":"信息","pinyin":"xìnxī","vi":"thông tin"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"},{"hanzi":"消息","pinyin":"xiāoxi","vi":"tin"},{"hanzi":"情报","pinyin":"qíngbào","vi":"tình báo"}],"traditional":"資訊"},{"id":"字迹","hanzi":"字迹","pinyin":"zìjì","meaning_vi":"nét chữ, chữ viết","explanation":"字 (tự – chữ) + 迹 (tích – dấu vết) → dấu vết chữ viết, nét chữ của một người.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"✍️","examples":[{"type":"basic","zh":"他的字迹很工整。","pinyin":"Tā de zìjì hěn gōngzhěng.","vi":"Nét chữ của anh ấy rất ngay ngắn."},{"type":"simple","zh":"这封信上的字迹已经模糊了。","pinyin":"Zhè fēng xìn shàng de zìjì yǐjīng móhu le.","vi":"Chữ viết trên lá thư này đã mờ rồi."},{"type":"compound","zh":"虽然没有署名，但是我一看字迹就知道是她写的。","pinyin":"Suīrán méiyǒu shǔmíng, dànshì wǒ yí kàn zìjì jiù zhīdào shì tā xiě de.","vi":"Tuy không ký tên nhưng tôi nhìn nét chữ là biết cô ấy viết."}],"related":[{"hanzi":"笔迹","pinyin":"bǐjì","vi":"bút tích"},{"hanzi":"书写","pinyin":"shūxiě","vi":"viết"},{"hanzi":"字体","pinyin":"zìtǐ","vi":"kiểu chữ"},{"hanzi":"潦草","pinyin":"liáocǎo","vi":"nguệch ngoạc"}],"traditional":"字跡"},{"id":"字幕","hanzi":"字幕","pinyin":"zìmù","meaning_vi":"phụ đề","explanation":"字 (tự – chữ) + 幕 (mạc – màn) → chữ hiện trên màn ảnh, phụ đề.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎞️","examples":[{"type":"basic","zh":"这部电影有中文字幕。","pinyin":"Zhè bù diànyǐng yǒu Zhōngwén zìmù.","vi":"Bộ phim này có phụ đề tiếng Trung."},{"type":"simple","zh":"我看美剧的时候习惯开着字幕。","pinyin":"Wǒ kàn Měijù de shíhou xíguàn kāizhe zìmù.","vi":"Khi xem phim Mỹ tôi quen bật phụ đề."},{"type":"compound","zh":"如果不看字幕，我就听不懂他们在说什么。","pinyin":"Rúguǒ bú kàn zìmù, wǒ jiù tīngbudǒng tāmen zài shuō shénme.","vi":"Nếu không xem phụ đề thì tôi không hiểu họ đang nói gì."}],"related":[{"hanzi":"字体","pinyin":"zìtǐ","vi":"phông chữ"},{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"},{"hanzi":"配音","pinyin":"pèiyīn","vi":"lồng tiếng"},{"hanzi":"翻译","pinyin":"fānyì","vi":"dịch"}]},{"id":"字体","hanzi":"字体","pinyin":"zìtǐ","meaning_vi":"kiểu chữ, phông chữ","explanation":"字 (tự – chữ) + 体 (thể – hình thể) → hình dạng, phong cách của chữ viết hoặc chữ in.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🔤","examples":[{"type":"basic","zh":"换一种字体吧。","pinyin":"Huàn yì zhǒng zìtǐ ba.","vi":"Đổi một kiểu chữ khác đi."},{"type":"simple","zh":"标题的字体应该大一点。","pinyin":"Biāotí de zìtǐ yīnggāi dà yìdiǎn.","vi":"Phông chữ của tiêu đề nên to hơn một chút."},{"type":"compound","zh":"虽然这种字体很漂亮，但是不适合用在正式文件里。","pinyin":"Suīrán zhè zhǒng zìtǐ hěn piàoliang, dànshì búshì héyòng zài zhèngshì wénjiàn lǐ.","vi":"Tuy kiểu chữ này rất đẹp nhưng không hợp dùng trong văn bản chính thức."}],"related":[{"hanzi":"字号","pinyin":"zìhào","vi":"cỡ chữ"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"字迹","pinyin":"zìjì","vi":"nét chữ"},{"hanzi":"楷书","pinyin":"kǎishū","vi":"chữ khải"}],"traditional":"字體"},{"id":"字眼","hanzi":"字眼","pinyin":"zìyǎn","meaning_vi":"từ ngữ, câu chữ","explanation":"字 (tự – chữ) + 眼 (nhãn – mắt, chỗ then chốt) → từ ngữ dùng trong câu, nhất là chữ then chốt.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🔍","examples":[{"type":"basic","zh":"他说话很注意字眼。","pinyin":"Tā shuōhuà hěn zhùyì zìyǎn.","vi":"Anh ấy nói năng rất chú ý từ ngữ."},{"type":"simple","zh":"合同里有几个字眼写得很模糊。","pinyin":"Hétong lǐ yǒu jǐ ge zìyǎn xiě de hěn móhu.","vi":"Trong hợp đồng có mấy chữ viết rất mơ hồ."},{"type":"compound","zh":"因为他总爱抠字眼，所以跟他讨论问题很累。","pinyin":"Yīnwèi tā zǒng ài kōuzìyǎn, suǒyǐ gēn tā tǎolùn wèntí hěn lèi.","vi":"Vì anh ta hay bắt bẻ câu chữ nên bàn bạc vấn đề với anh ta rất mệt."}],"related":[{"hanzi":"词语","pinyin":"cíyǔ","vi":"từ ngữ"},{"hanzi":"措辞","pinyin":"cuòcí","vi":"cách dùng từ"},{"hanzi":"抠字眼","pinyin":"kōuzìyǎn","vi":"bắt bẻ câu chữ"},{"hanzi":"用词","pinyin":"yòngcí","vi":"dùng từ"}]},{"id":"自称","hanzi":"自称","pinyin":"zìchēng","meaning_vi":"tự xưng, tự nhận là","explanation":"自 (tự – mình) + 称 (xưng – gọi) → tự gọi mình là…, tự nhận mình là… (thường hàm ý chưa chắc đúng).","hsk_level":"7-9","tags":["dong-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"他自称是医生。","pinyin":"Tā zìchēng shì yīshēng.","vi":"Anh ta tự xưng là bác sĩ."},{"type":"simple","zh":"一个自称记者的人来采访我们。","pinyin":"Yí gè zìchēng jìzhě de rén lái cǎifǎng wǒmen.","vi":"Một người tự xưng là phóng viên đến phỏng vấn chúng tôi."},{"type":"compound","zh":"虽然他自称是专家，但是连基本问题都回答不了。","pinyin":"Suīrán tā zìchēng shì zhuānjiā, dànshì lián jīběn wèntí dōu huídá buliǎo.","vi":"Tuy anh ta tự nhận là chuyên gia nhưng đến câu hỏi cơ bản cũng không trả lời được."}],"related":[{"hanzi":"声称","pinyin":"shēngchēng","vi":"tuyên bố"},{"hanzi":"号称","pinyin":"hàochēng","vi":"được gọi là, tự xưng"},{"hanzi":"称呼","pinyin":"chēnghu","vi":"xưng hô"},{"hanzi":"冒充","pinyin":"màochōng","vi":"giả mạo"}],"traditional":"自稱"},{"id":"自费","hanzi":"自费","pinyin":"zìfèi","meaning_vi":"tự túc, tự bỏ tiền","explanation":"自 (tự – mình) + 费 (phí – chi phí) → tự mình chi trả chi phí, không được cơ quan hay nhà nước chi.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"他是自费留学的。","pinyin":"Tā shì zìfèi liúxué de.","vi":"Anh ấy đi du học tự túc."},{"type":"simple","zh":"这次旅行的费用需要自费。","pinyin":"Zhè cì lǚxíng de fèiyòng xūyào zìfèi.","vi":"Chi phí chuyến du lịch này phải tự túc."},{"type":"compound","zh":"虽然公司不报销，但是他还是自费参加了培训。","pinyin":"Suīrán gōngsī bú bàoxiāo, dànshì tā háishì zìfèi cānjiāle péixùn.","vi":"Tuy công ty không thanh toán nhưng anh ấy vẫn tự bỏ tiền đi học bồi dưỡng."}],"related":[{"hanzi":"公费","pinyin":"gōngfèi","vi":"chi phí công"},{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"},{"hanzi":"报销","pinyin":"bàoxiāo","vi":"thanh toán chi phí"},{"hanzi":"费用","pinyin":"fèiyòng","vi":"chi phí"}],"traditional":"自費"},{"id":"自理","hanzi":"自理","pinyin":"zìlǐ","meaning_vi":"tự lo liệu, tự chăm sóc bản thân","explanation":"自 (tự – mình) + 理 (lý – lo liệu) → tự mình lo liệu việc của mình; hay gặp trong 生活自理 (tự lo sinh hoạt) và 费用自理 (tự chịu chi phí).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🧺","examples":[{"type":"basic","zh":"爷爷生活不能自理。","pinyin":"Yéye shēnghuó bù néng zìlǐ.","vi":"Ông nội không thể tự lo sinh hoạt."},{"type":"simple","zh":"这次活动交通费用自理。","pinyin":"Zhè cì huódòng jiāotōng fèiyòng zìlǐ.","vi":"Chi phí đi lại trong hoạt động lần này tự túc."},{"type":"compound","zh":"孩子上小学以后，就应该学会生活自理。","pinyin":"Háizi shàng xiǎoxué yǐhòu, jiù yīnggāi xuéhuì shēnghuó zìlǐ.","vi":"Trẻ vào tiểu học rồi thì nên học cách tự lo sinh hoạt."}],"related":[{"hanzi":"自立","pinyin":"zìlì","vi":"tự lập"},{"hanzi":"照顾","pinyin":"zhàogu","vi":"chăm sóc"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"},{"hanzi":"依赖","pinyin":"yīlài","vi":"ỷ lại"}]},{"id":"自立","hanzi":"自立","pinyin":"zìlì","meaning_vi":"tự lập, tự đứng trên đôi chân mình","explanation":"自 (tự – mình) + 立 (lập – đứng) → tự mình đứng vững, không dựa vào người khác.","hsk_level":"7-9","tags":["dong-tu","con-nguoi"],"image":"🧍","examples":[{"type":"basic","zh":"他十八岁就自立了。","pinyin":"Tā shíbā suì jiù zìlì le.","vi":"Mười tám tuổi anh ấy đã tự lập."},{"type":"simple","zh":"父母应该培养孩子自立的能力。","pinyin":"Fùmǔ yīnggāi péiyǎng háizi zìlì de nénglì.","vi":"Bố mẹ nên rèn cho con khả năng tự lập."},{"type":"compound","zh":"虽然刚工作时很辛苦，但是我终于能自立了。","pinyin":"Suīrán gāng gōngzuò shí hěn xīnkǔ, dànshì wǒ zhōngyú néng zìlì le.","vi":"Tuy lúc mới đi làm rất vất vả nhưng cuối cùng tôi đã có thể tự lập."}],"related":[{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"},{"hanzi":"自强","pinyin":"zìqiáng","vi":"tự cường"},{"hanzi":"自理","pinyin":"zìlǐ","vi":"tự lo liệu"},{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa dẫm"}]},{"id":"自然而然","hanzi":"自然而然","pinyin":"zìrán-érrán","meaning_vi":"tự nhiên mà thế, một cách tự nhiên","explanation":"自然 (tự nhiên) lặp lại với 而 (nhi – mà) → không cần cố ý mà tự nhiên diễn ra như vậy.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"我们自然而然成了朋友。","pinyin":"Wǒmen zìrán'érrán chéngle péngyou.","vi":"Chúng tôi tự nhiên mà thành bạn bè."},{"type":"simple","zh":"多听多说，口语自然而然就提高了。","pinyin":"Duō tīng duō shuō, kǒuyǔ zìrán'érrán jiù tígāo le.","vi":"Nghe nhiều nói nhiều thì khẩu ngữ tự nhiên sẽ tiến bộ."},{"type":"compound","zh":"只要每天坚持锻炼，身体自然而然就会变好。","pinyin":"Zhǐyào měitiān jiānchí duànliàn, shēntǐ zìrán'érrán jiù huì biàn hǎo.","vi":"Chỉ cần ngày nào cũng kiên trì tập luyện thì sức khỏe tự nhiên sẽ tốt lên."}],"related":[{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"},{"hanzi":"顺其自然","pinyin":"shùnqízìrán","vi":"thuận theo tự nhiên"},{"hanzi":"理所当然","pinyin":"lǐsuǒdāngrán","vi":"lẽ đương nhiên"},{"hanzi":"不知不觉","pinyin":"bùzhībùjué","vi":"bất giác"}]},{"id":"自然界","hanzi":"自然界","pinyin":"zìránjiè","meaning_vi":"giới tự nhiên, thế giới tự nhiên","explanation":"自然 (tự nhiên) + 界 (giới – phạm vi) → toàn bộ thế giới tự nhiên gồm sinh vật, núi sông, khí hậu.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌍","examples":[{"type":"basic","zh":"自然界充满奥秘。","pinyin":"Zìránjiè chōngmǎn àomì.","vi":"Thế giới tự nhiên đầy bí ẩn."},{"type":"simple","zh":"水在自然界中不断循环。","pinyin":"Shuǐ zài zìránjiè zhōng búduàn xúnhuán.","vi":"Nước tuần hoàn không ngừng trong tự nhiên."},{"type":"compound","zh":"如果人类继续破坏环境，自然界就会失去平衡。","pinyin":"Rúguǒ rénlèi jìxù pòhuài huánjìng, zìránjiè jiù huì shīqù pínghéng.","vi":"Nếu loài người tiếp tục phá hoại môi trường thì giới tự nhiên sẽ mất cân bằng."}],"related":[{"hanzi":"大自然","pinyin":"dàzìrán","vi":"thiên nhiên"},{"hanzi":"生物","pinyin":"shēngwù","vi":"sinh vật"},{"hanzi":"生态","pinyin":"shēngtài","vi":"sinh thái"},{"hanzi":"环境","pinyin":"huánjìng","vi":"môi trường"}]},{"id":"自如","hanzi":"自如","pinyin":"zìrú","meaning_vi":"tự nhiên, thoải mái, thành thạo","explanation":"自 (tự – tự mình) + 如 (như – theo ý) → hoạt động tùy ý, thoải mái, không bị gò bó; hay gặp trong 运用自如 (vận dụng thành thạo).","hsk_level":"7-9","tags":["tinh-tu"],"image":"😎","examples":[{"type":"basic","zh":"他能运用自如。","pinyin":"Tā néng yùnyòng zìrú.","vi":"Anh ấy có thể vận dụng thành thạo."},{"type":"simple","zh":"她在台上表演得非常自如。","pinyin":"Tā zài tái shàng biǎoyǎn de fēicháng zìrú.","vi":"Cô ấy biểu diễn trên sân khấu rất tự nhiên."},{"type":"compound","zh":"虽然他学中文才两年，但是已经能自如地交流了。","pinyin":"Suīrán tā xué Zhōngwén cái liǎng nián, dànshì yǐjīng néng zìrú de jiāoliú le.","vi":"Tuy anh ấy mới học tiếng Trung hai năm nhưng đã có thể giao tiếp thoải mái."}],"related":[{"hanzi":"自在","pinyin":"zìzai","vi":"thoải mái"},{"hanzi":"熟练","pinyin":"shúliàn","vi":"thành thạo"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"拘束","pinyin":"jūshù","vi":"gò bó"}]},{"id":"自始至终","hanzi":"自始至终","pinyin":"zìshǐ-zhìzhōng","meaning_vi":"từ đầu đến cuối","explanation":"自 (tự – từ) + 始 (thủy – đầu) + 至 (chí – đến) + 终 (chung – cuối) → từ lúc bắt đầu đến khi kết thúc, suốt cả quá trình.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔁","examples":[{"type":"basic","zh":"他自始至终没说话。","pinyin":"Tā zìshǐzhìzhōng méi shuōhuà.","vi":"Từ đầu đến cuối anh ấy không nói câu nào."},{"type":"simple","zh":"她自始至终都支持我的决定。","pinyin":"Tā zìshǐzhìzhōng dōu zhīchí wǒ de juédìng.","vi":"Cô ấy từ đầu đến cuối đều ủng hộ quyết định của tôi."},{"type":"compound","zh":"虽然比赛很艰难，但是队员们自始至终没有放弃。","pinyin":"Suīrán bǐsài hěn jiānnán, dànshì duìyuánmen zìshǐzhìzhōng méiyǒu fàngqì.","vi":"Tuy trận đấu rất gian nan nhưng các cầu thủ từ đầu đến cuối không bỏ cuộc."}],"related":[{"hanzi":"始终","pinyin":"shǐzhōng","vi":"trước sau"},{"hanzi":"从头到尾","pinyin":"cóngtóudàowěi","vi":"từ đầu đến cuối"},{"hanzi":"一贯","pinyin":"yíguàn","vi":"nhất quán"},{"hanzi":"有始有终","pinyin":"yǒushǐyǒuzhōng","vi":"có đầu có cuối"}],"traditional":"自始至終"},{"id":"自私","hanzi":"自私","pinyin":"zìsī","meaning_vi":"ích kỷ","explanation":"自 (tự – mình) + 私 (tư – riêng) → chỉ nghĩ đến lợi ích riêng của mình.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🙅","examples":[{"type":"basic","zh":"他太自私了。","pinyin":"Tā tài zìsī le.","vi":"Anh ta ích kỷ quá."},{"type":"simple","zh":"自私的人很难交到真心朋友。","pinyin":"Zìsī de rén hěn nán jiāo dào zhēnxīn péngyou.","vi":"Người ích kỷ rất khó kết được bạn thật lòng."},{"type":"compound","zh":"如果你总是这么自私，就没有人愿意帮你。","pinyin":"Rúguǒ nǐ zǒngshì zhème zìsī, jiù méiyǒu rén yuànyì bāng nǐ.","vi":"Nếu cậu cứ ích kỷ như vậy thì sẽ chẳng ai muốn giúp cậu."}],"related":[{"hanzi":"自私自利","pinyin":"zìsīzìlì","vi":"ích kỷ vụ lợi"},{"hanzi":"无私","pinyin":"wúsī","vi":"vô tư, chí công"},{"hanzi":"自我","pinyin":"zìwǒ","vi":"bản thân"},{"hanzi":"大方","pinyin":"dàfang","vi":"rộng rãi"}]},{"id":"自私自利","hanzi":"自私自利","pinyin":"zìsī-zìlì","meaning_vi":"ích kỷ vụ lợi, chỉ biết lợi mình","explanation":"自私 (tự tư – vì riêng mình) + 自利 (tự lợi – lợi cho mình) → việc gì cũng chỉ nghĩ cho bản thân, không đoái hoài đến người khác.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🤑","examples":[{"type":"basic","zh":"他是个自私自利的人。","pinyin":"Tā shì ge zìsīzìlì de rén.","vi":"Anh ta là người ích kỷ vụ lợi."},{"type":"simple","zh":"自私自利的行为会伤害集体利益。","pinyin":"Zìsīzìlì de xíngwéi huì shānghài jítǐ lìyì.","vi":"Hành vi ích kỷ vụ lợi sẽ làm tổn hại lợi ích tập thể."},{"type":"compound","zh":"虽然他很有能力，但是因为自私自利，大家都不愿和他合作。","pinyin":"Suīrán tā hěn yǒunénglì, dànshì yīnwèi zìsīzìlì, dàjiā dōu búyuàn hé tā hézuò.","vi":"Tuy anh ta rất có năng lực nhưng vì ích kỷ vụ lợi nên mọi người đều không muốn hợp tác với anh ta."}],"related":[{"hanzi":"自私","pinyin":"zìsī","vi":"ích kỷ"},{"hanzi":"损人利己","pinyin":"sǔnrénlìjǐ","vi":"hại người lợi mình"},{"hanzi":"大公无私","pinyin":"dàgōngwúsī","vi":"chí công vô tư"},{"hanzi":"唯利是图","pinyin":"wéilìshìtú","vi":"chỉ biết chạy theo lợi"}]},{"id":"自卫","hanzi":"自卫","pinyin":"zìwèi","meaning_vi":"tự vệ","explanation":"自 (tự – mình) + 卫 (vệ – bảo vệ) → tự bảo vệ mình khi bị tấn công.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🛡️","examples":[{"type":"basic","zh":"他是出于自卫。","pinyin":"Tā shì chūyú zìwèi.","vi":"Anh ấy hành động vì tự vệ."},{"type":"simple","zh":"女孩子应该学一些自卫的方法。","pinyin":"Nǚháizi yīnggāi xué yìxiē zìwèi de fāngfǎ.","vi":"Con gái nên học một số cách tự vệ."},{"type":"compound","zh":"如果遭到坏人袭击，你有权进行正当自卫。","pinyin":"Rúguǒ zāodào huàirén xíjī, nǐ yǒuquán jìnxíng zhèngdàng zìwèi.","vi":"Nếu bị kẻ xấu tấn công, bạn có quyền phòng vệ chính đáng."}],"related":[{"hanzi":"防卫","pinyin":"fángwèi","vi":"phòng vệ"},{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"},{"hanzi":"反击","pinyin":"fǎnjī","vi":"phản công"},{"hanzi":"正当防卫","pinyin":"zhèngdàngfángwèi","vi":"phòng vệ chính đáng"}],"traditional":"自衛"},{"id":"自信心","hanzi":"自信心","pinyin":"zìxìnxīn","meaning_vi":"lòng tự tin","explanation":"自信 (tự tin) + 心 (tâm – lòng) → niềm tin vào khả năng của chính mình.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🌟","examples":[{"type":"basic","zh":"她缺乏自信心。","pinyin":"Tā quēfá zìxìnxīn.","vi":"Cô ấy thiếu tự tin."},{"type":"simple","zh":"老师的表扬增强了他的自信心。","pinyin":"Lǎoshī de biǎoyáng zēngqiángle tā de zìxìnxīn.","vi":"Lời khen của thầy giáo đã tăng thêm lòng tự tin cho cậu ấy."},{"type":"compound","zh":"只要多给孩子鼓励，他们的自信心就会慢慢建立起来。","pinyin":"Zhǐyào duō gěi háizi gǔlì, tāmen de zìxìnxīn jiù huì mànmàn jiànlì qǐlái.","vi":"Chỉ cần động viên trẻ nhiều hơn thì lòng tự tin của chúng sẽ dần được xây dựng."}],"related":[{"hanzi":"自信","pinyin":"zìxìn","vi":"tự tin"},{"hanzi":"自卑","pinyin":"zìbēi","vi":"tự ti"},{"hanzi":"信心","pinyin":"xìnxīn","vi":"niềm tin"},{"hanzi":"自尊心","pinyin":"zìzūnxīn","vi":"lòng tự trọng"}]},{"id":"自行","hanzi":"自行","pinyin":"zìxíng","meaning_vi":"tự mình, tự làm (lấy)","explanation":"自 (tự – mình) + 行 (hành – làm) → tự mình làm lấy, không cần người khác; dùng trong văn viết, thông báo.","hsk_level":"7-9","tags":["pho-tu"],"image":"🙋","examples":[{"type":"basic","zh":"请自行解决。","pinyin":"Qǐng zìxíng jiějué.","vi":"Xin tự giải quyết."},{"type":"simple","zh":"伤口很小，过几天会自行愈合。","pinyin":"Shāngkǒu hěn xiǎo, guò jǐtiān huì zìxíng yùhé.","vi":"Vết thương rất nhỏ, mấy hôm nữa sẽ tự lành."},{"type":"compound","zh":"如果对结果有疑问，可以自行上网查询。","pinyin":"Rúguǒ duì jiéguǒ yǒu yíwèn, kěyǐ zìxíng shàngwǎng cháxún.","vi":"Nếu có thắc mắc về kết quả, có thể tự lên mạng tra cứu."}],"related":[{"hanzi":"自己","pinyin":"zìjǐ","vi":"tự mình"},{"hanzi":"亲自","pinyin":"qīnzì","vi":"đích thân"},{"hanzi":"自动","pinyin":"zìdòng","vi":"tự động"},{"hanzi":"擅自","pinyin":"shànzì","vi":"tự ý"}]},{"id":"自以为是","hanzi":"自以为是","pinyin":"zìyǐ-wéishì","meaning_vi":"tự cho mình là đúng, cố chấp","explanation":"自 (tự – mình) + 以为 (dĩ vi – cho rằng) + 是 (thị – đúng) → luôn cho mình là đúng, không chịu nghe ý kiến người khác.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🙄","examples":[{"type":"basic","zh":"他总是自以为是。","pinyin":"Tā zǒngshì zìyǐwéishì.","vi":"Anh ta lúc nào cũng tự cho mình là đúng."},{"type":"simple","zh":"自以为是的人很难进步。","pinyin":"Zìyǐwéishì de rén hěn nán jìnbù.","vi":"Người tự cho mình là đúng rất khó tiến bộ."},{"type":"compound","zh":"如果你继续自以为是，早晚会吃大亏的。","pinyin":"Rúguǒ nǐ jìxù zìyǐwéishì, zǎo wǎnhuì chīdàkuī de.","vi":"Nếu cậu cứ tự cho mình là đúng thì sớm muộn cũng sẽ chịu thiệt lớn."}],"related":[{"hanzi":"固执","pinyin":"gùzhí","vi":"cố chấp"},{"hanzi":"骄傲","pinyin":"jiāo'ào","vi":"kiêu ngạo"},{"hanzi":"虚心","pinyin":"xūxīn","vi":"khiêm tốn"},{"hanzi":"目中无人","pinyin":"mùzhōngwúrén","vi":"coi trời bằng vung"}],"traditional":"自以為是"},{"id":"自由自在","hanzi":"自由自在","pinyin":"zìyóu-zìzài","meaning_vi":"tự do tự tại, thong dong","explanation":"自由 (tự do) + 自在 (tự tại – thoải mái) → thong thả, không bị ràng buộc gì.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🕊️","examples":[{"type":"basic","zh":"鸟儿自由自在地飞。","pinyin":"Niǎor zìyóuzìzài de fēi.","vi":"Chim bay lượn tự do tự tại."},{"type":"simple","zh":"退休后他过着自由自在的生活。","pinyin":"Tuìxiū hòu tāguò zhe zìyóuzìzài de shēnghuó.","vi":"Sau khi nghỉ hưu ông sống cuộc sống tự do thong dong."},{"type":"compound","zh":"虽然一个人住有点儿孤单，但是可以自由自在。","pinyin":"Suīrán yígèrén zhù yǒudiǎnr gūdān, dànshì kěyǐ zìyóuzìzài.","vi":"Tuy sống một mình hơi cô đơn nhưng được tự do thoải mái."}],"related":[{"hanzi":"自由","pinyin":"zìyóu","vi":"tự do"},{"hanzi":"自在","pinyin":"zìzai","vi":"thoải mái"},{"hanzi":"无拘无束","pinyin":"wújūwúshù","vi":"không gò bó"},{"hanzi":"逍遥","pinyin":"xiāoyáo","vi":"tiêu dao"}]},{"id":"自责","hanzi":"自责","pinyin":"zìzé","meaning_vi":"tự trách","explanation":"自 (tự – mình) + 责 (trách – trách móc) → tự trách bản thân về lỗi lầm.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"你不必太自责。","pinyin":"Nǐ búbì tài zìzé.","vi":"Bạn không cần tự trách quá."},{"type":"simple","zh":"他为这次失误深深自责。","pinyin":"Tā wèi zhè cì shīwù shēnshēn zìzé.","vi":"Anh ấy tự trách sâu sắc vì sai sót lần này."},{"type":"compound","zh":"虽然事故不是她的错，但是她一直很自责。","pinyin":"Suīrán shìgù bú shì tā de cuò, dànshì tā yìzhí hěn zìzé.","vi":"Tuy tai nạn không phải lỗi của cô ấy nhưng cô ấy vẫn luôn tự trách."}],"related":[{"hanzi":"内疚","pinyin":"nèijiù","vi":"áy náy"},{"hanzi":"后悔","pinyin":"hòuhuǐ","vi":"hối hận"},{"hanzi":"反省","pinyin":"fǎnxǐng","vi":"tự kiểm điểm"},{"hanzi":"责怪","pinyin":"zéguài","vi":"trách móc"}],"traditional":"自責"},{"id":"自助","hanzi":"自助","pinyin":"zìzhù","meaning_vi":"tự phục vụ, tự giúp mình","explanation":"自 (tự – mình) + 助 (trợ – giúp) → tự mình phục vụ mình; hay gặp trong 自助餐 (buffet), 自助游 (du lịch tự túc).","hsk_level":"7-9","tags":["tinh-tu","sinh-hoat"],"image":"🍽️","examples":[{"type":"basic","zh":"我们去吃自助餐吧。","pinyin":"Wǒmen qù chī zìzhùcān ba.","vi":"Chúng ta đi ăn buffet đi."},{"type":"simple","zh":"银行门口有一台自助取款机。","pinyin":"Yínháng ménkǒu yǒu yì tái zìzhù qǔkuǎnjī.","vi":"Trước cửa ngân hàng có một máy rút tiền tự động."},{"type":"compound","zh":"因为不想跟旅行团，所以我们选择了自助游。","pinyin":"Yīnwèi bù xiǎng gēn lǚxíngtuán, suǒyǐ wǒmen xuǎnzéle zìzhùyóu.","vi":"Vì không muốn đi theo đoàn nên chúng tôi chọn du lịch tự túc."}],"related":[{"hanzi":"自助餐","pinyin":"zìzhùcān","vi":"buffet"},{"hanzi":"自理","pinyin":"zìlǐ","vi":"tự lo liệu"},{"hanzi":"服务","pinyin":"fúwù","vi":"phục vụ"},{"hanzi":"互助","pinyin":"hùzhù","vi":"giúp đỡ lẫn nhau"}]},{"id":"子孙","hanzi":"子孙","pinyin":"zǐsūn","meaning_vi":"con cháu, hậu thế","explanation":"子 (tử – con) + 孙 (tôn – cháu) → con cháu, các thế hệ đời sau.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"他子孙满堂。","pinyin":"Tā zǐsūn mǎntáng.","vi":"Ông ấy con cháu đầy nhà."},{"type":"simple","zh":"我们要为子孙后代保护好环境。","pinyin":"Wǒmen yào wèi zǐsūn hòudài bǎohù hǎo huánjìng.","vi":"Chúng ta phải bảo vệ tốt môi trường vì con cháu đời sau."},{"type":"compound","zh":"如果现在浪费资源，子孙后代就会受苦。","pinyin":"Rúguǒ xiànzài làngfèi zīyuán, zǐsūn hòudài jiù huì shòukǔ.","vi":"Nếu bây giờ lãng phí tài nguyên thì con cháu đời sau sẽ chịu khổ."}],"related":[{"hanzi":"后代","pinyin":"hòudài","vi":"đời sau"},{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"},{"hanzi":"孙子","pinyin":"sūnzi","vi":"cháu nội"},{"hanzi":"后裔","pinyin":"hòuyì","vi":"hậu duệ"}],"traditional":"子孫"},{"id":"宗","hanzi":"宗","pinyin":"zōng","meaning_vi":"vụ, lô (lượng từ); tông, dòng họ","explanation":"宗 (tông) nghĩa gốc là tổ tiên, dòng họ (祖宗, 宗族); làm lượng từ cho vụ việc, khoản hàng lớn (一宗案件 – một vụ án).","hsk_level":"7-9","tags":["luong-tu"],"image":"📁","examples":[{"type":"basic","zh":"这是一宗大买卖。","pinyin":"Zhè shì yì zōng dà mǎimai.","vi":"Đây là một vụ làm ăn lớn."},{"type":"simple","zh":"警方破获了一宗诈骗案。","pinyin":"Jǐngfāng pòhuòle yì zōng zhàpiàn àn.","vi":"Cảnh sát đã phá một vụ án lừa đảo."},{"type":"compound","zh":"虽然这宗交易金额很大，但是双方很快就谈妥了。","pinyin":"Suīrán zhè zōng jiāoyì jīn'é hěn dà, dànshì shuāngfāng hěn kuài jiù tántuǒ le.","vi":"Tuy giao dịch này giá trị rất lớn nhưng hai bên đã nhanh chóng thỏa thuận xong."}],"related":[{"hanzi":"件","pinyin":"jiàn","vi":"việc, cái"},{"hanzi":"起","pinyin":"qǐ","vi":"vụ (lượng từ)"},{"hanzi":"宗族","pinyin":"zōngzú","vi":"dòng tộc"},{"hanzi":"祖宗","pinyin":"zǔzong","vi":"tổ tiên"}]},{"id":"综上所述","hanzi":"综上所述","pinyin":"zōngshàngsuǒshù","meaning_vi":"tóm lại, tổng hợp những điều trên","explanation":"综 (tổng – tổng hợp) + 上 (thượng – ở trên) + 所述 (sở thuật – điều đã nói) → tổng hợp những điều đã trình bày ở trên; dùng mở đầu phần kết luận.","hsk_level":"7-9","tags":["lien-tu"],"image":"🧾","examples":[{"type":"basic","zh":"综上所述，方案可行。","pinyin":"Zōngshàngsuǒshù, fāng'àn kěxíng.","vi":"Tóm lại, phương án này khả thi."},{"type":"simple","zh":"综上所述，我们需要更多的资金。","pinyin":"Zōngshàngsuǒshù, wǒmen xūyào gèng duō de zījīn.","vi":"Tổng hợp những điều trên, chúng ta cần thêm nguồn vốn."},{"type":"compound","zh":"综上所述，如果不改变学习方法，成绩就很难提高。","pinyin":"Zōngshàngsuǒshù, rúguǒ bù gǎibiàn xuéxí fāngfǎ, chéngjì jiù hěn nán tígāo.","vi":"Tóm lại, nếu không thay đổi phương pháp học thì thành tích sẽ khó nâng cao."}],"related":[{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"},{"hanzi":"总而言之","pinyin":"zǒng'éryánzhī","vi":"nói tóm lại"},{"hanzi":"总的来说","pinyin":"zǒngdeláishuō","vi":"nhìn chung"},{"hanzi":"总结","pinyin":"zǒngjié","vi":"tổng kết"}],"traditional":"綜上所述"},{"id":"总的来说","hanzi":"总的来说","pinyin":"zǒngdeláishuō","meaning_vi":"nhìn chung, nói chung","explanation":"总的 (tổng thể) + 来说 (mà nói) → xét một cách tổng thể; dùng để nêu nhận định chung.","hsk_level":"7-9","tags":["lien-tu"],"image":"🗒️","examples":[{"type":"basic","zh":"总的来说，还不错。","pinyin":"Zǒngdeláishuō, hái búcuò.","vi":"Nhìn chung là cũng không tệ."},{"type":"simple","zh":"总的来说，这次旅行很愉快。","pinyin":"Zǒngdeláishuō, zhè cì lǚxíng hěn yúkuài.","vi":"Nhìn chung chuyến du lịch lần này rất vui."},{"type":"compound","zh":"总的来说，虽然遇到了一些困难，但是项目进展顺利。","pinyin":"Zǒngdeláishuō, suīrán yùdàole yìxiē kùnnan, dànshì xiàngmù jìnzhǎn shùnlì.","vi":"Nhìn chung, tuy gặp một số khó khăn nhưng dự án tiến triển thuận lợi."}],"related":[{"hanzi":"总之","pinyin":"zǒngzhī","vi":"tóm lại"},{"hanzi":"一般来说","pinyin":"yìbānláishuō","vi":"nói chung"},{"hanzi":"综上所述","pinyin":"zōngshàngsuǒshù","vi":"tóm lại"},{"hanzi":"总体","pinyin":"zǒngtǐ","vi":"tổng thể"}],"traditional":"總的來說"},{"id":"总额","hanzi":"总额","pinyin":"zǒng'é","meaning_vi":"tổng số tiền, tổng ngạch","explanation":"总 (tổng – gộp lại) + 额 (ngạch – mức, số lượng) → tổng số lượng hay tổng giá trị.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🧮","examples":[{"type":"basic","zh":"贷款总额是十万元。","pinyin":"Dàikuǎn zǒng'é shì shíwàn yuán.","vi":"Tổng số tiền vay là một trăm nghìn tệ."},{"type":"simple","zh":"今年的销售总额超过了一个亿。","pinyin":"Jīnnián de xiāoshòu zǒng'é chāoguòle yí gè yì.","vi":"Tổng doanh số năm nay vượt quá một trăm triệu."},{"type":"compound","zh":"虽然每笔捐款不多，但是捐款总额相当可观。","pinyin":"Suīrán měi bǐ juānkuǎn bù duō, dànshì juānkuǎn zǒng'é xiāngdāng kěguān.","vi":"Tuy mỗi khoản quyên góp không nhiều nhưng tổng số tiền khá đáng kể."}],"related":[{"hanzi":"总数","pinyin":"zǒngshù","vi":"tổng số"},{"hanzi":"金额","pinyin":"jīn'é","vi":"số tiền"},{"hanzi":"总计","pinyin":"zǒngjì","vi":"tổng cộng"},{"hanzi":"余额","pinyin":"yú'é","vi":"số dư"}],"traditional":"總額"},{"id":"总计","hanzi":"总计","pinyin":"zǒngjì","meaning_vi":"tổng cộng","explanation":"总 (tổng – gộp) + 计 (kế – tính) → cộng tất cả lại, tổng cộng.","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"➕","examples":[{"type":"basic","zh":"总计五百元。","pinyin":"Zǒngjì wǔ bǎi yuán.","vi":"Tổng cộng năm trăm tệ."},{"type":"simple","zh":"这次活动总计有三千人参加。","pinyin":"Zhè cì huódòng zǒngjì yǒu sān qiān rén cānjiā.","vi":"Hoạt động lần này tổng cộng có ba nghìn người tham gia."},{"type":"compound","zh":"虽然每天只花一点，但是一个月总计下来也不少。","pinyin":"Suīrán měitiān zhǐ huā yìdiǎn, dànshì yí gèyuè zǒngjì xiàlái yě bùshǎo.","vi":"Tuy mỗi ngày chỉ tiêu một ít nhưng cộng cả tháng lại cũng không ít."}],"related":[{"hanzi":"合计","pinyin":"héjì","vi":"cộng lại"},{"hanzi":"共计","pinyin":"gòngjì","vi":"tổng cộng"},{"hanzi":"总额","pinyin":"zǒng'é","vi":"tổng số tiền"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"}],"traditional":"總計"},{"id":"纵横交错","hanzi":"纵横交错","pinyin":"zònghéng-jiāocuò","meaning_vi":"ngang dọc đan xen, chằng chịt","explanation":"纵 (tung – dọc) + 横 (hoành – ngang) + 交错 (giao thác – đan xen) → đường ngang dọc đan chéo nhau chằng chịt; nghĩa bóng chỉ tình hình phức tạp.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🕸️","examples":[{"type":"basic","zh":"城里道路纵横交错。","pinyin":"Chénglǐ dàolù zònghéngjiāocuò.","vi":"Đường sá trong thành phố ngang dọc chằng chịt."},{"type":"simple","zh":"田野里的小河纵横交错。","pinyin":"Tiányě lǐ de xiǎohé zònghéngjiāocuò.","vi":"Những con sông nhỏ trên đồng ruộng đan xen ngang dọc."},{"type":"compound","zh":"因为这里街道纵横交错，所以外地人很容易迷路。","pinyin":"Yīnwèi zhèlǐ jiēdào zònghéngjiāocuò, suǒyǐ wàidìrén hěn róngyì mílù.","vi":"Vì đường phố ở đây ngang dọc chằng chịt nên người nơi khác rất dễ lạc."}],"related":[{"hanzi":"交错","pinyin":"jiāocuò","vi":"đan xen"},{"hanzi":"错综复杂","pinyin":"cuòzōngfùzá","vi":"phức tạp rối ren"},{"hanzi":"四通八达","pinyin":"sìtōngbādá","vi":"thông suốt bốn phương"},{"hanzi":"纵横","pinyin":"zònghéng","vi":"ngang dọc"}],"traditional":"縱橫交錯"},{"id":"纵然","hanzi":"纵然","pinyin":"zòngrán","meaning_vi":"cho dù, dẫu cho","explanation":"纵 (túng – buông thả, dù cho) + 然 (nhiên) → dù cho, cho dù; liên từ nhượng bộ trong văn viết, thường đi với 也.","hsk_level":"7-9","tags":["lien-tu"],"image":"🌧️","examples":[{"type":"basic","zh":"纵然失败也不后悔。","pinyin":"Zòngrán shībài yě bú hòuhuǐ.","vi":"Dù thất bại cũng không hối hận."},{"type":"simple","zh":"纵然下雨他也坚持跑步。","pinyin":"Zòngrán xiàyǔ tā yě jiānchí pǎobù.","vi":"Dù trời mưa anh ấy vẫn kiên trì chạy bộ."},{"type":"compound","zh":"纵然前面有再多困难，我们也要坚持走下去。","pinyin":"Zòngrán qiánmiàn yǒu zài duō kùnnan, wǒmen yě yào jiānchí zǒu xiàqù.","vi":"Dù phía trước có bao nhiêu khó khăn, chúng ta cũng phải kiên trì đi tiếp."}],"related":[{"hanzi":"即使","pinyin":"jíshǐ","vi":"cho dù"},{"hanzi":"尽管","pinyin":"jǐnguǎn","vi":"mặc dù"},{"hanzi":"哪怕","pinyin":"nǎpà","vi":"dù cho"},{"hanzi":"纵使","pinyin":"zòngshǐ","vi":"cho dù"}],"traditional":"縱然"},{"id":"粽子","hanzi":"粽子","pinyin":"zòngzi","meaning_vi":"bánh ú, bánh tro (bánh gạo nếp gói lá)","explanation":"粽 (tống – bánh gạo nếp gói lá) + 子 (tử – hậu tố) → bánh gạo nếp gói lá tre, ăn vào Tết Đoan Ngọ.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍙","examples":[{"type":"basic","zh":"端午节要吃粽子。","pinyin":"Duānwǔjié yào chī zòngzi.","vi":"Tết Đoan Ngọ phải ăn bánh ú."},{"type":"simple","zh":"奶奶每年都亲手包很多粽子。","pinyin":"Nǎinai měinián dōu qīnshǒu bāo hěn duō zòngzi.","vi":"Năm nào bà nội cũng tự tay gói rất nhiều bánh ú."},{"type":"compound","zh":"虽然粽子很好吃，但是糯米不好消化，不能多吃。","pinyin":"Suīrán zòngzi hěn hǎochī, dànshì nuòmǐ bù hǎo xiāohuà, bù néng duō chī.","vi":"Tuy bánh ú rất ngon nhưng gạo nếp khó tiêu, không nên ăn nhiều."}],"related":[{"hanzi":"端午节","pinyin":"Duānwǔjié","vi":"Tết Đoan Ngọ"},{"hanzi":"糯米","pinyin":"nuòmǐ","vi":"gạo nếp"},{"hanzi":"月饼","pinyin":"yuèbing","vi":"bánh trung thu"},{"hanzi":"包粽子","pinyin":"bāozòngzi","vi":"gói bánh ú"}]},{"id":"走过场","hanzi":"走过场","pinyin":"zǒuguòchǎng","meaning_vi":"làm cho có, làm qua loa lấy lệ","explanation":"Nghĩa đen: diễn viên đi lướt qua sân khấu rồi vào → nghĩa bóng: làm việc chỉ cho có hình thức, không thực chất.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🎭","examples":[{"type":"basic","zh":"检查不能走过场。","pinyin":"Jiǎnchá bù néng zǒuguòchǎng.","vi":"Kiểm tra không được làm cho có."},{"type":"simple","zh":"这次培训完全是在走过场。","pinyin":"Zhè cì péixùn wánquán shì zài zǒuguòchǎng.","vi":"Đợt tập huấn này hoàn toàn chỉ là làm cho có."},{"type":"compound","zh":"如果评估只是走过场，就发现不了真正的问题。","pinyin":"Rúguǒ pínggū zhǐshì zǒuguòchǎng, jiù fāxiàn bùliǎo zhēnzhèng de wèntí.","vi":"Nếu đánh giá chỉ làm lấy lệ thì không phát hiện được vấn đề thực sự."}],"related":[{"hanzi":"形式主义","pinyin":"xíngshìzhǔyì","vi":"chủ nghĩa hình thức"},{"hanzi":"敷衍","pinyin":"fūyǎn","vi":"qua loa, đối phó"},{"hanzi":"应付","pinyin":"yìngfu","vi":"đối phó"},{"hanzi":"走形式","pinyin":"zǒuxíngshì","vi":"làm cho có hình thức"}],"traditional":"走過場"},{"id":"走后门","hanzi":"走后门","pinyin":"zǒuhòumén","meaning_vi":"đi cửa sau","explanation":"Nghĩa đen: đi vào bằng cửa sau → nghĩa bóng: dùng quan hệ, nhờ vả để đạt được điều gì không qua con đường chính thức.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚪","examples":[{"type":"basic","zh":"他是走后门进来的。","pinyin":"Tā shì zǒuhòumén jìnlái de.","vi":"Anh ta vào được là nhờ đi cửa sau."},{"type":"simple","zh":"有些人想靠走后门找到好工作。","pinyin":"Yǒuxiērén xiǎng kào zǒuhòumén zhǎodào hǎo gōngzuò.","vi":"Một số người muốn đi cửa sau để tìm được việc tốt."},{"type":"compound","zh":"虽然走后门可以省事，但是这样做对别人很不公平。","pinyin":"Suīrán zǒuhòumén kěyǐ shěngshì, dànshì zhèyàng zuò duì biérén hěn bù gōngpíng.","vi":"Tuy đi cửa sau có thể đỡ mất công nhưng làm vậy rất bất công với người khác."}],"related":[{"hanzi":"关系","pinyin":"guānxi","vi":"quan hệ"},{"hanzi":"托关系","pinyin":"tuōguānxi","vi":"nhờ vả quan hệ"},{"hanzi":"开后门","pinyin":"kāihòumén","vi":"mở cửa sau"},{"hanzi":"不正之风","pinyin":"búzhèngzhīfēng","vi":"tác phong bất chính"}],"traditional":"走後門"},{"id":"走近","hanzi":"走近","pinyin":"zǒujìn","meaning_vi":"đến gần, lại gần","explanation":"走 (tẩu – đi) + 近 (cận – gần) → đi lại gần; nghĩa bóng là tìm hiểu gần gũi hơn.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚶‍♀️","examples":[{"type":"basic","zh":"他慢慢走近小狗。","pinyin":"Tā mànmàn zǒujìn xiǎogǒu.","vi":"Anh ấy chậm rãi đến gần chú chó con."},{"type":"simple","zh":"一位外国老人走近我问路。","pinyin":"Yí wèi wàiguó lǎorén zǒujìn wǒ wènlù.","vi":"Một cụ già người nước ngoài đến gần hỏi đường tôi."},{"type":"compound","zh":"当我走近一看，才发现那不是我的朋友。","pinyin":"Dāng wǒ zǒujìn yí kàn, cái fāxiàn nà bú shì wǒ de péngyou.","vi":"Khi tôi lại gần nhìn kỹ mới phát hiện đó không phải bạn mình."}],"related":[{"hanzi":"靠近","pinyin":"kàojìn","vi":"tới gần"},{"hanzi":"接近","pinyin":"jiējìn","vi":"tiếp cận"},{"hanzi":"走远","pinyin":"zǒuyuǎn","vi":"đi xa"},{"hanzi":"临近","pinyin":"línjìn","vi":"sắp tới"}]},{"id":"走投无路","hanzi":"走投无路","pinyin":"zǒutóu-wúlù","meaning_vi":"cùng đường, không lối thoát","explanation":"走 (tẩu – đi) + 投 (đầu – nương nhờ) + 无路 (vô lộ – không đường) → không còn đường đi, không nơi nương tựa; chỉ bước đường cùng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧱","examples":[{"type":"basic","zh":"他已经走投无路了。","pinyin":"Tā yǐjīng zǒutóuwúlù le.","vi":"Anh ấy đã cùng đường rồi."},{"type":"simple","zh":"走投无路的时候，是朋友帮了我。","pinyin":"Zǒutóuwúlù de shíhou, shì péngyou bāngle wǒ.","vi":"Lúc tôi cùng đường, chính bạn bè đã giúp tôi."},{"type":"compound","zh":"如果不是走投无路，他也不会去借高利贷。","pinyin":"Rúguǒ bú shì zǒutóuwúlù, tā yě bú huì qù jiè gāolìdài.","vi":"Nếu không phải cùng đường thì anh ấy cũng sẽ không đi vay nặng lãi."}],"related":[{"hanzi":"山穷水尽","pinyin":"shānqióngshuǐjìn","vi":"sơn cùng thủy tận"},{"hanzi":"绝境","pinyin":"juéjìng","vi":"bước đường cùng"},{"hanzi":"无路可走","pinyin":"wúlùkězǒu","vi":"không còn đường đi"},{"hanzi":"穷途末路","pinyin":"qióngtúmòlù","vi":"đường cùng"}],"traditional":"走投無路"},{"id":"走弯路","hanzi":"走弯路","pinyin":"zǒuwānlù","meaning_vi":"đi đường vòng, đi sai hướng","explanation":"Nghĩa đen: đi đường cong, đường vòng → nghĩa bóng: làm sai cách nên tốn thời gian công sức.","hsk_level":"7-9","tags":["dong-tu"],"image":"↪️","examples":[{"type":"basic","zh":"听我的，别走弯路。","pinyin":"Tīng wǒ de, bié zǒuwānlù.","vi":"Nghe tôi, đừng đi đường vòng."},{"type":"simple","zh":"听听前辈的经验可以避免走弯路。","pinyin":"Tīng ting qiánbèi de jīngyàn kěyǐ bìmiǎn zǒuwānlù.","vi":"Nghe kinh nghiệm của người đi trước có thể tránh đi đường vòng."},{"type":"compound","zh":"因为一开始方法不对，所以他在学习上走弯路走了很久。","pinyin":"Yīnwèi yì kāishǐ fāngfǎ bú duì, suǒyǐ tā zài xuéxí shàng zǒuwānlù zǒule hěn jiǔ.","vi":"Vì lúc đầu phương pháp không đúng nên anh ấy đi đường vòng trong việc học rất lâu."}],"related":[{"hanzi":"弯路","pinyin":"wānlù","vi":"đường vòng"},{"hanzi":"捷径","pinyin":"jiéjìng","vi":"đường tắt"},{"hanzi":"绕远","pinyin":"ràoyuǎn","vi":"đi vòng xa"},{"hanzi":"走捷径","pinyin":"zǒujiéjìng","vi":"đi đường tắt"}],"traditional":"走彎路"},{"id":"奏效","hanzi":"奏效","pinyin":"zòuxiào","meaning_vi":"có hiệu quả, công hiệu","explanation":"奏 (tấu – dâng lên, đạt được) + 效 (hiệu – hiệu quả) → đạt được hiệu quả mong muốn.","hsk_level":"7-9","tags":["dong-tu"],"image":"✔️","examples":[{"type":"basic","zh":"这个办法很奏效。","pinyin":"Zhè ge bànfǎ hěn zòuxiào.","vi":"Cách này rất hiệu quả."},{"type":"simple","zh":"新的治疗方案终于奏效了。","pinyin":"Xīn de zhìliáo fāng'àn zhōngyú zòuxiào le.","vi":"Phác đồ điều trị mới cuối cùng đã có hiệu quả."},{"type":"compound","zh":"虽然我们试了很多方法，但是都没有奏效。","pinyin":"Suīrán wǒmen shìle hěn duō fāngfǎ, dànshì dōu méiyǒu zòuxiào.","vi":"Tuy chúng tôi đã thử nhiều cách nhưng đều không hiệu quả."}],"related":[{"hanzi":"有效","pinyin":"yǒuxiào","vi":"có hiệu quả"},{"hanzi":"见效","pinyin":"jiànxiào","vi":"thấy hiệu quả"},{"hanzi":"生效","pinyin":"shēngxiào","vi":"có hiệu lực"},{"hanzi":"无效","pinyin":"wúxiào","vi":"vô hiệu"}]},{"id":"足智多谋","hanzi":"足智多谋","pinyin":"zúzhì-duōmóu","meaning_vi":"túc trí đa mưu, mưu trí hơn người","explanation":"足 (túc – đủ đầy) + 智 (trí – trí tuệ) + 多 (đa – nhiều) + 谋 (mưu – mưu kế) → trí tuệ dồi dào, lắm mưu kế; như Gia Cát Lượng trong Tam Quốc.","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🦊","examples":[{"type":"basic","zh":"诸葛亮足智多谋。","pinyin":"Zhūgěliàng zúzhìduōmóu.","vi":"Gia Cát Lượng túc trí đa mưu."},{"type":"simple","zh":"他是一位足智多谋的将军。","pinyin":"Tā shì yí wèi zúzhìduōmóu de jiāngjūn.","vi":"Ông ấy là một vị tướng mưu trí hơn người."},{"type":"compound","zh":"虽然敌人很多，但是因为他足智多谋，最后还是打了胜仗。","pinyin":"Suīrán dírén hěn duō, dànshì yīnwèi tā zúzhìduōmóu, zuìhòu háishì dǎle shèngzhàng.","vi":"Tuy quân địch rất đông nhưng nhờ mưu trí hơn người, cuối cùng ông vẫn thắng trận."}],"related":[{"hanzi":"聪明","pinyin":"cōngming","vi":"thông minh"},{"hanzi":"机智","pinyin":"jīzhì","vi":"nhanh trí"},{"hanzi":"神机妙算","pinyin":"shénjīmiàosuàn","vi":"tính toán như thần"},{"hanzi":"有勇无谋","pinyin":"yǒuyǒngwúmóu","vi":"có dũng không mưu"}],"traditional":"足智多謀"},{"id":"阻挡","hanzi":"阻挡","pinyin":"zǔdǎng","meaning_vi":"ngăn cản, chặn lại","explanation":"阻 (trở – ngăn trở) + 挡 (đáng – chắn) → chặn lại, không cho tiến lên.","hsk_level":"7-9","tags":["dong-tu"],"image":"🚧","examples":[{"type":"basic","zh":"谁也阻挡不了他。","pinyin":"Shéi yě zǔdǎng buliǎo tā.","vi":"Không ai ngăn được anh ấy."},{"type":"simple","zh":"一棵大树阻挡了我们的视线。","pinyin":"Yì kē dà shù zǔdǎngle wǒmen de shìxiàn.","vi":"Một cái cây lớn che khuất tầm nhìn của chúng tôi."},{"type":"compound","zh":"即使遇到再大的困难，也阻挡不了我们前进的脚步。","pinyin":"Jíshǐ yùdào zài dà de kùnnan, yě zǔdǎng bùliǎo wǒmen qiánjìn de jiǎobù.","vi":"Dù gặp khó khăn lớn đến đâu cũng không cản được bước tiến của chúng ta."}],"related":[{"hanzi":"阻止","pinyin":"zǔzhǐ","vi":"ngăn chặn"},{"hanzi":"阻碍","pinyin":"zǔ'ài","vi":"cản trở"},{"hanzi":"抵挡","pinyin":"dǐdǎng","vi":"chống đỡ"},{"hanzi":"拦住","pinyin":"lánzhù","vi":"chặn lại"}],"traditional":"阻擋"},{"id":"阻力","hanzi":"阻力","pinyin":"zǔlì","meaning_vi":"lực cản, trở lực","explanation":"阻 (trở – ngăn trở) + 力 (lực – sức) → lực cản chuyển động; nghĩa bóng là sự cản trở, phản đối.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌬️","examples":[{"type":"basic","zh":"改革遇到了阻力。","pinyin":"Gǎigé yùdàole zǔlì.","vi":"Cải cách đã gặp phải trở lực."},{"type":"simple","zh":"这种车的设计可以减少空气阻力。","pinyin":"Zhè zhǒng chē de shèjì kěyǐ jiǎnshǎo kōngqì zǔlì.","vi":"Thiết kế của loại xe này có thể giảm lực cản không khí."},{"type":"compound","zh":"虽然计划受到了很大阻力，但是他们最终还是完成了。","pinyin":"Suīrán jìhuà shòudàole hěn dà zǔlì, dànshì tāmen zuìzhōng háishì wánchéng le.","vi":"Tuy kế hoạch gặp nhiều trở lực nhưng cuối cùng họ vẫn hoàn thành."}],"related":[{"hanzi":"动力","pinyin":"dònglì","vi":"động lực"},{"hanzi":"阻碍","pinyin":"zǔ'ài","vi":"cản trở"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"摩擦力","pinyin":"mócālì","vi":"lực ma sát"}]},{"id":"组装","hanzi":"组装","pinyin":"zǔzhuāng","meaning_vi":"lắp ráp","explanation":"组 (tổ – tổ hợp) + 装 (trang – lắp) → ghép các bộ phận lại thành một vật hoàn chỉnh.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔧","examples":[{"type":"basic","zh":"我自己组装了电脑。","pinyin":"Wǒ zìjǐ zǔzhuāngle diànnǎo.","vi":"Tôi tự lắp ráp máy tính."},{"type":"simple","zh":"这个书架组装起来非常简单。","pinyin":"Zhè ge shūjià zǔzhuāng qǐlái fēicháng jiǎndān.","vi":"Cái giá sách này lắp ráp rất đơn giản."},{"type":"compound","zh":"只要按照说明书一步步做，你就能组装好这张桌子。","pinyin":"Zhǐyào ànzhào shuōmíngshū yí bùbù zuò, nǐ jiù néng zǔzhuāng hǎo zhè zhāng zhuōzi.","vi":"Chỉ cần làm từng bước theo sách hướng dẫn là bạn có thể lắp xong cái bàn này."}],"related":[{"hanzi":"安装","pinyin":"ānzhuāng","vi":"lắp đặt"},{"hanzi":"拆卸","pinyin":"chāixiè","vi":"tháo dỡ"},{"hanzi":"零件","pinyin":"língjiàn","vi":"linh kiện"},{"hanzi":"装配","pinyin":"zhuāngpèi","vi":"lắp ráp"}],"traditional":"組裝"},{"id":"祖传","hanzi":"祖传","pinyin":"zǔchuán","meaning_vi":"tổ truyền, gia truyền","explanation":"祖 (tổ – tổ tiên) + 传 (truyền – truyền lại) → do tổ tiên truyền lại qua nhiều đời.","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🏺","examples":[{"type":"basic","zh":"这是祖传秘方。","pinyin":"Zhè shì zǔchuán mìfāng.","vi":"Đây là bí phương gia truyền."},{"type":"simple","zh":"他家开了一家祖传的面馆。","pinyin":"Tā jiā kāile yìjiā zǔchuán de miànguǎn.","vi":"Nhà anh ấy mở một quán mì gia truyền."},{"type":"compound","zh":"虽然这块玉不值钱，但是因为是祖传的，所以他非常珍惜。","pinyin":"Suīrán zhè kuài yù bù zhíqián, dànshì yīnwèi shì zǔchuán de, suǒyǐ tā fēicháng zhēnxī.","vi":"Tuy miếng ngọc này không đáng giá nhưng vì là đồ tổ truyền nên anh ấy rất trân trọng."}],"related":[{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"},{"hanzi":"传家宝","pinyin":"chuánjiābǎo","vi":"báu vật gia truyền"},{"hanzi":"世代","pinyin":"shìdài","vi":"nhiều đời"},{"hanzi":"家传","pinyin":"jiāchuán","vi":"gia truyền"}],"traditional":"祖傳"},{"id":"祖籍","hanzi":"祖籍","pinyin":"Zǔjí","meaning_vi":"quê gốc, nguyên quán","explanation":"祖 (tổ – tổ tiên) + 籍 (tịch – sổ hộ tịch, quê quán) → quê quán gốc của tổ tiên.","hsk_level":"7-9","tags":["danh-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"我的祖籍是广东。","pinyin":"Wǒ de Zǔjí shì Guǎngdōng.","vi":"Quê gốc của tôi ở Quảng Đông."},{"type":"simple","zh":"他出生在越南，祖籍在福建。","pinyin":"Tā chūshēng zài Yuènán, Zǔjí zài Fújiàn.","vi":"Anh ấy sinh ra ở Việt Nam, nguyên quán ở Phúc Kiến."},{"type":"compound","zh":"虽然他从没去过祖籍，但是一直想回去看看。","pinyin":"Suīrán tā cóng méi qùguo Zǔjí, dànshì yìzhí xiǎng huíqù kànkan.","vi":"Tuy chưa từng về quê gốc nhưng anh ấy luôn muốn về thăm."}],"related":[{"hanzi":"籍贯","pinyin":"jíguàn","vi":"quê quán"},{"hanzi":"故乡","pinyin":"gùxiāng","vi":"cố hương"},{"hanzi":"老家","pinyin":"lǎojiā","vi":"quê nhà"},{"hanzi":"出生地","pinyin":"chūshēngdì","vi":"nơi sinh"}]},{"id":"祖宗","hanzi":"祖宗","pinyin":"zǔzong","meaning_vi":"tổ tông, tổ tiên","explanation":"祖 (tổ – ông bà, tổ tiên) + 宗 (tông – dòng họ) → các bậc tổ tiên của dòng họ.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🧓","examples":[{"type":"basic","zh":"不能忘了祖宗。","pinyin":"Bù néng wàngle zǔzong.","vi":"Không được quên tổ tông."},{"type":"simple","zh":"过年时大家要先祭拜祖宗。","pinyin":"Guònián shí dàjiā yào xiān jìbài zǔzong.","vi":"Tết đến mọi người phải cúng bái tổ tiên trước."},{"type":"compound","zh":"既然这是祖宗留下来的规矩，我们就应该遵守。","pinyin":"Jìrán zhè shì zǔzong liú xiàlái de guīju, wǒmen jiù yīnggāi zūnshǒu.","vi":"Đã là quy củ tổ tiên để lại thì chúng ta nên tuân theo."}],"related":[{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"},{"hanzi":"祖辈","pinyin":"zǔbèi","vi":"thế hệ ông bà"},{"hanzi":"子孙","pinyin":"zǐsūn","vi":"con cháu"},{"hanzi":"宗族","pinyin":"zōngzú","vi":"dòng tộc"}]},{"id":"钻空子","hanzi":"钻空子","pinyin":"zuānkòngzi","meaning_vi":"lợi dụng kẽ hở, lách luật","explanation":"钻 (toản – chui, khoan) + 空子 (khe hở) → chui qua khe hở; nghĩa bóng là lợi dụng sơ hở của luật lệ hay người khác để trục lợi.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🕳️","examples":[{"type":"basic","zh":"有人想钻空子。","pinyin":"Yǒurén xiǎng zuānkòngzi.","vi":"Có người muốn lợi dụng kẽ hở."},{"type":"simple","zh":"新规定不给投机者钻空子的机会。","pinyin":"Xīn guīdìng bù gěi tóujīzhě zuānkòngzi de jīhuì.","vi":"Quy định mới không cho kẻ đầu cơ cơ hội lách luật."},{"type":"compound","zh":"如果公司的制度不完善，就总会有人钻空子。","pinyin":"Rúguǒ gōngsī de zhìdù bù wánshàn, jiù zǒng huì yǒurén zuānkòngzi.","vi":"Nếu chế độ của công ty không hoàn thiện thì luôn có người lợi dụng kẽ hở."}],"related":[{"hanzi":"漏洞","pinyin":"lòudòng","vi":"lỗ hổng"},{"hanzi":"空子","pinyin":"kòngzi","vi":"kẽ hở"},{"hanzi":"投机取巧","pinyin":"tóujīqǔqiǎo","vi":"cơ hội, khôn lỏi"},{"hanzi":"利用","pinyin":"lìyòng","vi":"lợi dụng"}],"traditional":"鑽空子"},{"id":"罪魁祸首","hanzi":"罪魁祸首","pinyin":"zuìkuí-huòshǒu","meaning_vi":"kẻ cầm đầu, thủ phạm chính","explanation":"罪魁 (tội khôi – kẻ đầu sỏ tội ác) + 祸首 (họa thủ – kẻ gây họa) → kẻ cầm đầu gây ra tội ác; nghĩa bóng là nguyên nhân chính gây ra tai họa.","hsk_level":"7-9","tags":["thanh-ngu","phap-luat"],"image":"🦹","examples":[{"type":"basic","zh":"他才是罪魁祸首。","pinyin":"Tā cái shì zuìkuíhuòshǒu.","vi":"Hắn mới là kẻ chủ mưu."},{"type":"simple","zh":"吸烟是导致肺癌的罪魁祸首。","pinyin":"Xīyān shì dǎozhì fèi'ái de zuìkuíhuòshǒu.","vi":"Hút thuốc là thủ phạm chính gây ung thư phổi."},{"type":"compound","zh":"虽然大家都怪天气，但是真正的罪魁祸首是司机酒后驾车。","pinyin":"Suīrán dàjiā dōu guài tiānqì, dànshì zhēnzhèng de zuìkuíhuòshǒu shì sījī jiǔhòu jiàchē.","vi":"Tuy mọi người đều đổ cho thời tiết nhưng thủ phạm thực sự là tài xế lái xe sau khi uống rượu."}],"related":[{"hanzi":"元凶","pinyin":"yuánxiōng","vi":"hung thủ chính"},{"hanzi":"主谋","pinyin":"zhǔmóu","vi":"kẻ chủ mưu"},{"hanzi":"祸根","pinyin":"huògēn","vi":"mầm họa"},{"hanzi":"帮凶","pinyin":"bāngxiōng","vi":"đồng phạm"}],"traditional":"罪魁禍首"},{"id":"遵照","hanzi":"遵照","pinyin":"zūnzhào","meaning_vi":"tuân theo, làm theo","explanation":"遵 (tuân – tuân theo) + 照 (chiếu – theo đúng) → làm đúng theo chỉ thị, quy định hay lời dặn.","hsk_level":"7-9","tags":["dong-tu"],"image":"📏","examples":[{"type":"basic","zh":"请遵照医嘱服药。","pinyin":"Qǐng zūnzhào yīzhǔ fúyào.","vi":"Xin uống thuốc theo chỉ định của bác sĩ."},{"type":"simple","zh":"我们遵照领导的指示完成了任务。","pinyin":"Wǒmen zūnzhào lǐngdǎo de zhǐshì wánchéngle rènwu.","vi":"Chúng tôi hoàn thành nhiệm vụ theo chỉ thị của lãnh đạo."},{"type":"compound","zh":"只要遵照说明书操作，机器就不会出问题。","pinyin":"Zhǐyào zūnzhào shuōmíngshū cāozuò, jīqì jiù bú huì chūwèntí.","vi":"Chỉ cần thao tác theo sách hướng dẫn thì máy sẽ không gặp sự cố."}],"related":[{"hanzi":"遵守","pinyin":"zūnshǒu","vi":"tuân thủ"},{"hanzi":"按照","pinyin":"ànzhào","vi":"theo"},{"hanzi":"依照","pinyin":"yīzhào","vi":"căn cứ theo"},{"hanzi":"违反","pinyin":"wéifǎn","vi":"vi phạm"}]},{"id":"左顾右盼","hanzi":"左顾右盼","pinyin":"zuǒgù-yòupàn","meaning_vi":"nhìn ngang nhìn dọc, ngó nghiêng","explanation":"左 (tả – trái) + 顾 (cố – ngoảnh nhìn) + 右 (hữu – phải) + 盼 (phán – trông) → ngoảnh trái trông phải; tả dáng nhìn quanh quất, đắn đo hoặc lơ đãng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"他在门口左顾右盼。","pinyin":"Tā zài ménkǒu zuǒgùyòupàn.","vi":"Anh ấy ngó nghiêng ở cửa."},{"type":"simple","zh":"上课时别左顾右盼，要认真听讲。","pinyin":"Shàngkè shí bié zuǒgùyòupàn, yào rènzhēn tīngjiǎng.","vi":"Trong giờ học đừng ngó nghiêng, phải chăm chú nghe giảng."},{"type":"compound","zh":"因为第一次来大城市，所以他一路上左顾右盼，什么都觉得新鲜。","pinyin":"Yīnwèi dìyīcì lái dàchéngshì, suǒyǐ tā yílùshang zuǒgùyòupàn, shénme dōu juéde xīnxiān.","vi":"Vì lần đầu lên thành phố lớn nên dọc đường anh ấy ngó nghiêng, thấy cái gì cũng mới lạ."}],"related":[{"hanzi":"东张西望","pinyin":"dōngzhāngxīwàng","vi":"nhìn đông ngó tây"},{"hanzi":"环顾","pinyin":"huángù","vi":"nhìn quanh"},{"hanzi":"张望","pinyin":"zhāngwàng","vi":"nhìn ngó"},{"hanzi":"目不斜视","pinyin":"mùbùxiéshì","vi":"mắt nhìn thẳng"}],"traditional":"左顧右盼"},{"id":"佐料","hanzi":"佐料","pinyin":"zuǒliào","meaning_vi":"gia vị","explanation":"佐 (tá – phụ trợ) + 料 (liệu – nguyên liệu) → nguyên liệu phụ thêm vào món ăn cho đậm vị.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🧂","examples":[{"type":"basic","zh":"汤里少放点佐料。","pinyin":"Tāng lǐ shǎofàng diǎn zuǒliào.","vi":"Cho ít gia vị vào canh thôi."},{"type":"simple","zh":"妈妈准备了葱、姜、蒜等佐料。","pinyin":"Māma zhǔnbèile cōng, jiāng, suàn děng zuǒliào.","vi":"Mẹ đã chuẩn bị hành, gừng, tỏi và các gia vị khác."},{"type":"compound","zh":"如果佐料放得太多，就会盖住食物本来的味道。","pinyin":"Rúguǒ zuǒliào fàng de tài duō, jiù huì gài zhù shíwù běnlái de wèidao.","vi":"Nếu cho quá nhiều gia vị thì sẽ át mất vị vốn có của món ăn."}],"related":[{"hanzi":"调料","pinyin":"tiáoliào","vi":"gia vị"},{"hanzi":"作料","pinyin":"zuóliao","vi":"gia vị"},{"hanzi":"酱油","pinyin":"jiàngyóu","vi":"xì dầu"},{"hanzi":"调味","pinyin":"tiáowèi","vi":"nêm nếm"}]},{"id":"作对","hanzi":"作对","pinyin":"zuòduì","meaning_vi":"đối đầu, chống đối","explanation":"作 (tác – làm) + 对 (đối – đối địch) → làm đối thủ của ai, cố tình chống lại.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"⚔️","examples":[{"type":"basic","zh":"你为什么总跟我作对？","pinyin":"Nǐ wèishénme zǒng gēn wǒ zuòduì?","vi":"Sao anh cứ đối đầu với tôi thế?"},{"type":"simple","zh":"天气好像故意跟我们作对。","pinyin":"Tiānqì hǎoxiàng gùyì gēn wǒmen zuòduì.","vi":"Thời tiết dường như cố tình chống lại chúng tôi."},{"type":"compound","zh":"虽然他们以前经常作对，但是现在成了好朋友。","pinyin":"Suīrán tāmen yǐqián jīngcháng zuòduì, dànshì xiànzài chéngle hǎopéngyou.","vi":"Tuy trước đây họ thường xuyên đối đầu nhưng giờ đã thành bạn tốt."}],"related":[{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"},{"hanzi":"反对","pinyin":"fǎnduì","vi":"phản đối"},{"hanzi":"为难","pinyin":"wéinán","vi":"làm khó"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"}],"traditional":"作對"},{"id":"作客","hanzi":"作客","pinyin":"zuòkè","meaning_vi":"làm khách, đến chơi nhà","explanation":"作 (tác – làm) + 客 (khách) → đến nhà người khác làm khách.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🏡","examples":[{"type":"basic","zh":"欢迎来我家作客！","pinyin":"Huānyíng lái wǒ jiā zuòkè!","vi":"Hoan nghênh đến nhà tôi chơi!"},{"type":"simple","zh":"周末我们去老师家作客。","pinyin":"Zhōumò wǒmen qù lǎoshī jiā zuòkè.","vi":"Cuối tuần chúng tôi đến nhà thầy giáo làm khách."},{"type":"compound","zh":"如果去中国朋友家作客，最好带一点小礼物。","pinyin":"Rúguǒ qù Zhōngguó péngyou jiā zuòkè, zuìhǎo dài yìdiǎn xiǎo lǐwù.","vi":"Nếu đến nhà bạn Trung Quốc làm khách thì tốt nhất nên mang chút quà nhỏ."}],"related":[{"hanzi":"做客","pinyin":"zuòkè","vi":"làm khách"},{"hanzi":"客人","pinyin":"kèrén","vi":"khách"},{"hanzi":"拜访","pinyin":"bàifǎng","vi":"thăm viếng"},{"hanzi":"招待","pinyin":"zhāodài","vi":"tiếp đãi"}]},{"id":"作物","hanzi":"作物","pinyin":"zuòwù","meaning_vi":"cây trồng, hoa màu","explanation":"作 (tác – làm, trồng trọt) + 物 (vật) → cây trồng nông nghiệp như lúa, ngô, khoai.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌽","examples":[{"type":"basic","zh":"水稻是主要作物。","pinyin":"Shuǐdào shì zhǔyào zuòwù.","vi":"Lúa nước là cây trồng chính."},{"type":"simple","zh":"这里的土地适合种植经济作物。","pinyin":"Zhèlǐ de tǔdì shìhé zhòngzhí jīngjì zuòwù.","vi":"Đất ở đây thích hợp trồng cây công nghiệp."},{"type":"compound","zh":"因为今年雨水充足，所以各种作物都获得了丰收。","pinyin":"Yīnwèi jīnnián yǔshuǐ chōngzú, suǒyǐ gèzhǒng zuòwù dōu huòdéle fēngshōu.","vi":"Vì năm nay mưa nhiều nên các loại cây trồng đều được mùa."}],"related":[{"hanzi":"农作物","pinyin":"nóngzuòwù","vi":"cây nông nghiệp"},{"hanzi":"庄稼","pinyin":"zhuāngjia","vi":"hoa màu"},{"hanzi":"粮食","pinyin":"liángshi","vi":"lương thực"},{"hanzi":"种植","pinyin":"zhòngzhí","vi":"trồng trọt"}]},{"id":"坐落","hanzi":"坐落","pinyin":"zuòluò","meaning_vi":"tọa lạc, nằm ở","explanation":"坐 (tọa – ngồi) + 落 (lạc – đặt xuống) → (công trình) tọa lạc, nằm ở một vị trí.","hsk_level":"7-9","tags":["dong-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"学校坐落在山脚下。","pinyin":"Xuéxiào zuòluò zài shān jiǎoxià.","vi":"Trường học nằm dưới chân núi."},{"type":"simple","zh":"这座古寺坐落在西湖边上。","pinyin":"Zhè zuò gǔ sì zuòluò zài Xīhú biānshang.","vi":"Ngôi chùa cổ này tọa lạc bên bờ Tây Hồ."},{"type":"compound","zh":"因为酒店坐落在市中心，所以去哪里都很方便。","pinyin":"Yīnwèi jiǔdiàn zuòluò zài shìzhōngxīn, suǒyǐ qù nǎlǐ dōu hěn fāngbiàn.","vi":"Vì khách sạn nằm ở trung tâm thành phố nên đi đâu cũng rất tiện."}],"related":[{"hanzi":"位于","pinyin":"wèiyú","vi":"nằm ở"},{"hanzi":"地处","pinyin":"dìchǔ","vi":"nằm ở (vị trí)"},{"hanzi":"位置","pinyin":"wèizhì","vi":"vị trí"},{"hanzi":"座落","pinyin":"zuòluò","vi":"tọa lạc"}]},{"id":"座谈","hanzi":"座谈","pinyin":"zuòtán","meaning_vi":"tọa đàm, trao đổi thân mật","explanation":"座 (tọa – chỗ ngồi) + 谈 (đàm – trò chuyện) → ngồi lại cùng nhau trao đổi thân mật; hay gặp trong 座谈会 (buổi tọa đàm).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗨️","examples":[{"type":"basic","zh":"大家一起座谈一下。","pinyin":"Dàjiā yìqǐ zuòtán yíxià.","vi":"Mọi người cùng tọa đàm một chút."},{"type":"simple","zh":"校长和新生代表进行了座谈。","pinyin":"Xiàozhǎng hé xīnshēng dàibiǎo jìnxíngle zuòtán.","vi":"Hiệu trưởng đã tọa đàm với đại diện tân sinh viên."},{"type":"compound","zh":"虽然座谈只有一个小时，但是大家提出了很多好建议。","pinyin":"Suīrán zuòtán zhǐyǒu yí gè xiǎoshí, dànshì dàjiā tíchūle hěn duō hǎo jiànyì.","vi":"Tuy buổi tọa đàm chỉ có một tiếng nhưng mọi người đã đưa ra nhiều đề xuất hay."}],"related":[{"hanzi":"座谈会","pinyin":"zuòtánhuì","vi":"buổi tọa đàm"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"},{"hanzi":"会谈","pinyin":"huìtán","vi":"hội đàm"}],"traditional":"座談"},{"id":"做生意","hanzi":"做生意","pinyin":"zuòshēngyi","meaning_vi":"làm ăn, kinh doanh, buôn bán","explanation":"做 (tố – làm) + 生意 (sinh ý – việc buôn bán) → làm ăn buôn bán, kinh doanh.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他在上海做生意。","pinyin":"Tā zài Shànghǎi zuòshēngyi.","vi":"Anh ấy làm ăn ở Thượng Hải."},{"type":"simple","zh":"做生意最重要的是讲诚信。","pinyin":"Zuòshēngyi zuì zhòngyào de shì jiǎng chéngxìn.","vi":"Làm ăn quan trọng nhất là giữ chữ tín."},{"type":"compound","zh":"虽然做生意有风险，但是他还是辞职开了一家店。","pinyin":"Suīrán zuòshēngyi yǒu fēngxiǎn, dànshì tā háishì cízhí kāile yìjiā diàn.","vi":"Tuy kinh doanh có rủi ro nhưng anh ấy vẫn nghỉ việc mở một cửa hàng."}],"related":[{"hanzi":"生意","pinyin":"shēngyi","vi":"việc làm ăn"},{"hanzi":"经商","pinyin":"jīngshāng","vi":"kinh doanh"},{"hanzi":"买卖","pinyin":"mǎimai","vi":"buôn bán"},{"hanzi":"商人","pinyin":"shāngrén","vi":"thương nhân"}]},{"id":"做证","hanzi":"做证","pinyin":"zuòzhèng","meaning_vi":"làm chứng","explanation":"做 (tố – làm) + 证 (chứng – bằng chứng) → đứng ra làm nhân chứng, xác nhận sự thật; cũng viết là 作证.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🧑‍⚖️","examples":[{"type":"basic","zh":"我可以为你做证。","pinyin":"Wǒ kě yǐwèi nǐ zuòzhèng.","vi":"Tôi có thể làm chứng cho bạn."},{"type":"simple","zh":"那位目击者同意出庭做证。","pinyin":"Nà wèi mùjīzhě tóngyì chūtíng zuòzhèng.","vi":"Người chứng kiến đó đã đồng ý ra tòa làm chứng."},{"type":"compound","zh":"如果你说的是实话，就不怕当面做证。","pinyin":"Rúguǒ nǐ shuō de shì shíhuà, jiù bú pà dāngmiàn zuòzhèng.","vi":"Nếu anh nói thật thì không sợ đối chất làm chứng trực tiếp."}],"related":[{"hanzi":"作证","pinyin":"zuòzhèng","vi":"làm chứng"},{"hanzi":"证人","pinyin":"zhèngrén","vi":"nhân chứng"},{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"},{"hanzi":"证明","pinyin":"zhèngmíng","vi":"chứng minh"}],"traditional":"做證"}];
